:root{
  --bg:#0f1220;
  --card:#171a2b;
  --card2:#14172a;
  --text:#eef0ff;
  --muted:#b9bdd8;
  --line:#2a2f4a;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --good:#34d399;
  --warn:#fbbf24;
  --bad:#fb7185;
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, #1a1f3a 0%, var(--bg) 55%);color:var(--text);font-family:var(--sans)}
.wrap{max-width:980px;margin:0 auto;padding:22px 16px 40px}
.hdr{display:flex;gap:14px;align-items:flex-start;justify-content:space-between;margin-bottom:14px}
h1{font-size:20px;line-height:1.2;margin:0 0 6px}
.sub{margin:0;color:var(--muted);font-size:13px}
.card{background:linear-gradient(180deg, var(--card) 0%, var(--card2) 100%);border:1px solid var(--line);border-radius:14px;padding:14px 14px 12px;margin:12px 0;box-shadow:0 10px 30px rgba(0,0,0,.25)}
.card h2{margin:0 0 8px;font-size:16px}
.inst{margin:0 0 10px;color:var(--muted);font-size:13px}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.txt{flex:1;min-width:260px;background:#0c0f1d;border:1px solid var(--line);color:var(--text);border-radius:10px;padding:10px 12px;font-size:16px;outline:none}
.txt:focus{border-color:rgba(125,211,252,.7);box-shadow:0 0 0 3px rgba(125,211,252,.12)}
.btn{background:linear-gradient(180deg, rgba(125,211,252,.22), rgba(125,211,252,.08));border:1px solid rgba(125,211,252,.35);color:var(--text);padding:10px 12px;border-radius:10px;font-weight:650;cursor:pointer}
.btn:hover{border-color:rgba(125,211,252,.6)}
.btn:active{transform:translateY(1px)}
.btn.ghost{background:transparent;border:1px solid var(--line);color:var(--muted)}
.btn.ghost:hover{color:var(--text);border-color:rgba(167,139,250,.55)}
.chips{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0 0}
.chip{background:transparent;border:1px dashed rgba(167,139,250,.55);color:var(--text);padding:6px 10px;border-radius:999px;cursor:pointer;font-size:13px}
.chip:hover{border-style:solid}
.out{margin-top:12px;border-top:1px solid var(--line);padding-top:12px}
.block{background:#0c0f1d;border:1px solid var(--line);border-radius:12px;padding:10px 12px;margin:10px 0}
.k{color:var(--muted);font-size:12px;margin-bottom:6px}
.phrase{font-family:var(--mono);font-size:16px;line-height:1.5}
.hl{padding:1px 4px;border-radius:6px;border:1px solid rgba(125,211,252,.35);background:rgba(125,211,252,.10)}
.tag{display:inline-block;font-size:12px;padding:2px 8px;border-radius:999px;border:1px solid var(--line);color:var(--muted);margin-right:6px}
.tag.good{border-color:rgba(52,211,153,.45);color:#bff7df;background:rgba(52,211,153,.08)}
.tag.warn{border-color:rgba(251,191,36,.45);color:#ffe7a6;background:rgba(251,191,36,.08)}
.tag.bad{border-color:rgba(251,113,133,.45);color:#ffc0cb;background:rgba(251,113,133,.08)}
.grid{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:10px;align-items:end}
@media (max-width:860px){.grid{grid-template-columns:1fr}}
.lab{display:flex;flex-direction:column;gap:6px;color:var(--muted);font-size:13px}
.sel{background:#0c0f1d;border:1px solid var(--line);color:var(--text);border-radius:10px;padding:10px 12px;font-size:15px;outline:none}
.sel:focus{border-color:rgba(167,139,250,.7);box-shadow:0 0 0 3px rgba(167,139,250,.12)}
.mini{margin-top:8px;color:var(--muted);font-size:13px}
.note{margin-top:10px;border:1px solid var(--line);border-radius:12px;padding:10px 12px;background:rgba(255,255,255,.02)}
.note summary{cursor:pointer;color:var(--text);font-weight:650}
.noteBody{color:var(--muted);font-size:13px;line-height:1.45;margin-top:8px}
.ftr{margin-top:10px;color:var(--muted)}
.small{font-size:12px}
hr.sep{border:0;border-top:1px solid var(--line);margin:10px 0}
.err{color:#ffd1d9}

passages.gadget_js:
const $ = (sel) => document.querySelector(sel);

const samples = [
  "Ζεὺς δ᾽ ἐπεὶ οὖν Τρῶας",
  "Ζεὺς τε καταχθόνιος",
  "καὶ οἱ ἐπευχόμενος",
  "οἷ αὐτῷ θάνατον",
  "μάχῃ ἔνι κυδιανείρῃ",
  "Ζεύς δέ μοι ἔδωκεν",
  "Ζεύς τε καὶ Ἥρη",
];

function normalizeGreek(s){
  if(!s) return "";
  // Normalize apostrophes and spacing; keep polytonic as-is.
  return s
    .replace(/[’ʼʹ´`]/g, "᾽")
    .replace(/\s+/g, " ")
    .trim();
}

function stripPunct(token){
  return token
    .replace(/[··.,;:!?()\[\]{}«»“”"']/g, "")
    .replace(/᾽/g, "")
    .trim();
}

function tokenize(phrase){
  const norm = normalizeGreek(phrase);
  if(!norm) return [];
  return norm.split(" ").filter(Boolean);
}

function findRule(tokens){
  // Returns {i, kind, msg, tags[]} or null
  // Very small, passage-inspired heuristics.
  for(let i=0;i<tokens.length;i++){
    const t = stripPunct(tokens[i]);
    const next = (i+1<tokens.length) ? stripPunct(tokens[i+1]) : "";
    const prev = (i-1>=0) ? stripPunct(tokens[i-1]) : "";

    // Zeus + de/te
    if(/^Ζε(ύ|ὺ|υ)ς$/u.test(t) || t === "Ζεύς" || t === "Ζεὺς"){
      if(next === "δέ" || next === "δε"){
        return {
          i,
          kind:"zeus-de",
          tags:[{cls:"warn", txt:"enclitic-ish"},{cls:"tag", txt:"trigger: δέ"}],
          msg:"Herodian’s example: Ζεύς before δέ is read as if the acute is not ‘strengthened’ (a weakening/enclitic effect in continuous reading)."
        };
      }
      if(next === "τε"){
        return {
          i,
          kind:"zeus-te",
          tags:[{cls:"good", txt:"strengthened"},{cls:"tag", txt:"trigger: τε"}],
          msg:"Herodian’s example: Ζεύς before τε is read with the accent ‘strengthened’ (clearer prominence)."
        };
      }
    }

    // kai + oi
    if((t === "οἱ" || t === "οἷ") && (prev === "καί" || prev === "και")){
      return {
        i,
        kind:"oi-after-kai",
        tags:[{cls:"warn", txt:"accent shifts"},{cls:"tag", txt:"trigger: καί"}],
        msg:"Herodian notes οἱ can fail to ‘keep’ a circumflex in some contexts; after καί, the reading may treat it differently depending on syntax/meaning."
      };
    }

    // en(i) as a common enclitic-ish particle in Homeric phrase
    if(t === "ἔνι" || t === "ἐνί" || t === "ενι"){
      return {
        i,
        kind:"eni",
        tags:[{cls:"tag", txt:"particle"},{cls:"warn", txt:"light word"}],
        msg:"ἔνι is a light ‘particle-like’ form in epic diction; in reading it often clings closely to its neighbors (toy note)."
      };
    }
  }
  return null;
}

function renderPhrase(tokens, highlightIndex){
  return tokens.map((tok, idx) => {
    const safe = escapeHtml(tok);
    if(idx === highlightIndex) return `<span class="hl">${safe}</span>`;
    return safe;
  }).join(" ");
}

function escapeHtml(s){
  return s
    .replace(/&/g,"&amp;")
    .replace(/</g,"&lt;")
    .replace(/>/g,"&gt;")
    .replace(/"/g,"&quot;")
    .replace(/'/g,"&#39;");
}

function analyzePhrase(){
  const phrase = normalizeGreek($("#phrase").value);
  const out = $("#out");
  const tokens = tokenize(phrase);

  if(tokens.length === 0){
    out.innerHTML = `<div class="block"><div class="k err">Nothing to read yet.</div><div class="phrase">Type a short phrase above.</div></div>`;
    return;
  }

  const rule = findRule(tokens);
  const shown = renderPhrase(tokens, rule ? rule.i : -1);

  let tagsHtml = ``;
  if(rule){
    tagsHtml = rule.tags.map(t => {
      const cls = t.cls === "tag" ? "tag" : `tag ${t.cls}`;
      return `<span class="${cls}">${escapeHtml(t.txt)}</span>`;
    }).join("");
  } else {
    tagsHtml = `<span class="tag">no special trigger found</span>`;
  }

  out.innerHTML = `
    <div class="block">
      <div class="k">Your phrase (highlight = the word the toy is reacting to)</div>
      <div class="phrase">${shown}</div>
    </div>
    <div class="block">
      <div class="k">Reading note</div>
      <div>${tagsHtml}</div>
      <hr class="sep" />
      <div class="phrase" style="font-family: var(--sans); font-size: 14px; color: var(--muted); line-height: 1.45;">
        ${rule ? escapeHtml(rule.msg) : "Try adding δέ or τε after Ζεύς, or put οἱ after καί."}
      </div>
    </div>
  `;
}

function followerValue(){
  const v = $("#follower").value;
  if(v === "(other)") return normalizeGreek($("#other").value);
  return v;
}

function applyMicroLab(){
  const w = normalizeGreek($("#word").value);
  const f = followerValue();
  const mini = $("#mini");

  if(!w){
    mini.innerHTML = `<span class="err">Type a word.</span>`;
    return;
  }

  const tokens = f ? [w, f] : [w];
  const rule = findRule(tokens);

  const phrase = tokens.join(" ");
  const shown = renderPhrase(tokens, rule ? rule.i : -1);

  let verdict = "";
  if(rule){
    verdict = `<span class="tag ${rule.tags[0]?.cls || ""}">${escapeHtml(rule.tags[0]?.txt || "note")}</span>`;
  } else {
    verdict = `<span class="tag">no rule fired</span>`;
  }

  mini.innerHTML = `
    <div class="k">Preview</div>
    <div class="phrase">${shown}</div>
    <div style="margin-top:8px">${verdict}</div>
    <div style="margin-top:8px; color: var(--muted); line-height: 1.45;">
      ${rule ? escapeHtml(rule.msg) : "This toy only knows a few passage-inspired triggers (Ζεύς + δέ/τε; οἱ after καί; ἔνι)."}
    </div>
  `;
}

function setSample(s){
  $("#phrase").value = s;
  analyzePhrase();
}

// Wire up UI
$("#analyze").addEventListener("click", analyzePhrase);
$("#phrase").addEventListener("keydown", (e)=>{ if(e.key==="Enter") analyzePhrase(); });
$("#random").addEventListener("click", ()=> setSample(samples[Math.floor(Math.random()*samples.length)]));
$("#clear").addEventListener("click", ()=>{ $("#phrase").value=""; analyzePhrase(); });

document.querySelectorAll(".chip").forEach(btn=>{
  btn.addEventListener("click", ()=> setSample(btn.getAttribute("data-s")));
});

$("#follower").addEventListener("change", ()=>{
  const isOther = $("#follower").value === "(other)";
  $("#other").disabled = !isOther;
  if(isOther) $("#other").focus();
});
$("#apply").addEventListener("click", applyMicroLab);
$("#other").addEventListener("keydown", (e)=>{ if(e.key==="Enter") applyMicroLab(); });
$("#word").addEventListener("keydown", (e)=>{ if(e.key==="Enter") applyMicroLab(); });

// Initial render
analyzePhrase();
applyMicroLab();

passages.gadget_css:
:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --card:#1d2140;
  --text:#eef0ff;
  --muted:#b9bce6;
  --accent:#8be9fd;
  --accent2:#ffd866;
  --bad:#ff6b6b;
  --ok:#7CFFB2;
  --border:rgba(255,255,255,.12);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
}

*{box-sizing:border-box}

.wrap{
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, "Noto Sans", "Noto Sans Greek", sans-serif;
  color:var(--text);
  background: radial-gradient(1200px 600px at 20% 0%, rgba(139,233,253,.18), transparent 60%),
              radial-gradient(900px 500px at 90% 20%, rgba(255,216,102,.14), transparent 55%),
              var(--bg);
  padding: 18px;
  min-height: 100vh;
}

.hdr{
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap:16px;
  margin: 6px auto 14px;
  max-width: 1100px;
}

h1{font-size: 20px; margin:0 0 6px; letter-spacing:.2px}
.sub{margin:0; color:var(--muted); max-width: 900px; line-height:1.35}

.panel{
  max-width: 1100px;
  margin: 0 auto;
  background: linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 14px;
  box-shadow: var(--shadow);
}

.row{display:flex; gap:10px; align-items:center; flex-wrap:wrap}
.row.small{margin-top:10px}

.lbl{color:var(--muted); font-size: 13px; min-width: 90px}

.in{
  flex: 1 1 320px;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: rgba(0,0,0,.25);
  color: var(--text);
  font-size: 18px;
  outline: none;
}
.in:focus{border-color: rgba(139,233,253,.55); box-shadow: 0 0 0 3px rgba(139,233,253,.12)}

.btn{
  padding: 9px 11px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: rgba(255,255,255,.06);
  color: var(--text);
  cursor:pointer;
  font-size: 13px;
}
.btn:hover{background: rgba(255,255,255,.10)}
.btn:active{transform: translateY(1px)}

.hint{
  color: var(--muted);
  font-size: 13px;
  line-height: 1.35;
  padding: 10px 12px;
  border: 1px dashed rgba(255,255,255,.18);
  border-radius: 12px;
  background: rgba(0,0,0,.18);
  width: 100%;
}

.grid{
  display:grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 12px;
  margin-top: 12px;
}

.card{
  grid-column: span 12;
  background: rgba(0,0,0,.18);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 12px;
}

@media (min-width: 900px){
  .card:nth-child(1){grid-column: span 6}
  .card:nth-child(2){grid-column: span 6}
  .card:nth-child(3){grid-column: span 12}
}

h2{margin:0 0 8px; font-size: 15px; color: var(--accent)}
.p{margin: 0 0 10px; color: var(--muted); line-height:1.35; font-size: 13px}

.syllables{
  display:flex;
  flex-wrap:wrap;
  gap: 8px;
  padding: 8px;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,.10);
  background: rgba(0,0,0,.22);
  min-height: 52px;
}

.syl{
  padding: 8px 10px;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,.12);
  background: rgba(255,255,255,.06);
  cursor:pointer;
  user-select:none;
  font-size: 18px;
}
.syl:hover{border-color: rgba(139,233,253,.45)}
.syl.active{background: rgba(139,233,253,.16); border-color: rgba(139,233,253,.55)}
.syl .tag{display:block; font-size: 11px; color: var(--muted); margin-top: 2px}

.controls{display:flex; gap:10px; flex-wrap:wrap; margin-top: 10px}

.out{display:flex; gap:10px; align-items:baseline; margin-top: 10px; padding: 10px 12px; border-radius: 12px; border: 1px solid rgba(255,255,255,.10); background: rgba(0,0,0,.18)}
.k{min-width: 170px; color: var(--muted); font-size: 12px}
.v{font-size: 14px; line-height:1.25}
.mono{font-family: var(--mono); font-size: 16px}

.details{margin-top: 10px; color: var(--muted)}
.details summary{cursor:pointer}
.details ul{margin: 8px 0 0 18px; padding:0}
.details li{margin: 6px 0; line-height:1.35}

.ftr{margin-top: 12px; padding-top: 10px; border-top: 1px solid rgba(255,255,255,.10)}
.mini{color: var(--muted); font-size: 12px; line-height:1.35}

dialog{border: 1px solid var(--border); border-radius: 14px; background: #12152a; color: var(--text); box-shadow: var(--shadow); padding: 0; max-width: 720px; width: calc(100% - 24px)}
.dlg{padding: 14px}
.dlgRow{display:flex; justify-content:flex-end; margin-top: 12px}
.chips{display:flex; flex-wrap:wrap; gap:8px; margin-top: 10px}
.chip{padding: 8px 10px; border-radius: 999px; border: 1px solid rgba(255,255,255,.14); background: rgba(255,255,255,.06); cursor:pointer; font-size: 14px}
.chip:hover{border-color: rgba(255,216,102,.55)}

.bad{color: var(--bad)}
.ok{color: var(--ok)}

