(() => {
  const $ = (sel) => document.querySelector(sel);
  const inEl = $('#in');
  const outEl = $('#out');
  const detEl = $('#det');
  const marksEl = $('#marks');
  const sylBox = $('#syllables');
  const weightsEl = $('#weights');
  const windowEl = $('#window');
  const suggestEl = $('#suggest');

  const dlg = $('#dlg');
  const chips = $('#chips');

  const examples = [
    'προσῳδία',
    'ἄνθρωπος',
    'ἀγαθός',
    'λόγος',
    'ποταμός',
    'Ἀθηναῖος',
    'Μουσεῖον',
    'κατὰ συνήθειαν',
    'καθολικῆς προσῳδίας'
  ];

  // --- Polytonic helpers ---
  const COMBINING = {
    acute: '\u0301',
    grave: '\u0300',
    circumflex: '\u0342', // perispomeni
    diaeresis: '\u0308',
    smooth: '\u0313',
    rough: '\u0314',
    iotaSub: '\u0345',
    macron: '\u0304',
    breve: '\u0306'
  };

  const ACCENT_SET = new Set([COMBINING.acute, COMBINING.grave, COMBINING.circumflex]);

  const isGreekLetter = (ch) => {
    const cp = ch.codePointAt(0);
    return (cp >= 0x0370 && cp <= 0x03FF) || (cp >= 0x1F00 && cp <= 0x1FFF);
  };

  const isCombining = (ch) => {
    const cp = ch.codePointAt(0);
    return cp >= 0x0300 && cp <= 0x036F;
  };

  const stripAccentsOnly = (s) => {
    // Keep breathings/diaeresis/iota-sub etc; remove only accent marks.
    const n = s.normalize('NFD');
    let out = '';
    for (const ch of n) {
      if (ACCENT_SET.has(ch)) continue;
      out += ch;
    }
    return out.normalize('NFC');
  };

  const listAccentMarks = (s) => {
    const n = s.normalize('NFD');
    let a = 0, g = 0, c = 0;
    for (const ch of n) {
      if (ch === COMBINING.acute) a++;
      else if (ch === COMBINING.grave) g++;
      else if (ch === COMBINING.circumflex) c++;
    }
    return { acute: a, grave: g, circumflex: c, total: a + g + c };
  };

  const VOWELS = new Set([
    'α','ε','η','ι','ο','υ','ω',
    'Α','Ε','Η','Ι','Ο','Υ','Ω'
  ]);

  const isVowelBase = (ch) => VOWELS.has(ch);

  const isVowelOrDiphthongStart = (base) => isVowelBase(base);

  function graphemesNFD(s) {
    // Return array of "clusters" in NFD: base + combining marks.
    const n = s.normalize('NFD');
    const clusters = [];
    let cur = '';
    for (const ch of n) {
      if (!cur) {
        cur = ch;
      } else if (isCombining(ch)) {
        cur += ch;
      } else {
        clusters.push(cur);
        cur = ch;
      }
    }
    if (cur) clusters.push(cur);
    return clusters;
  }

  function clusterHasAccent(cluster) {
    for (const ch of cluster) if (ACCENT_SET.has(ch)) return true;
    return false;
  }

  function clusterBase(cluster) {
    // first codepoint is base in NFD cluster
    return [...cluster][0];
  }

  function clusterWithAcute(cluster) {
    // Add acute to cluster (keeping other diacritics), but avoid duplicates.
    let has = false;
    let out = '';
    for (const ch of cluster) {
      if (ch === COMBINING.acute) has = true;
      out += ch;
    }
    if (!has) out += COMBINING.acute;
    return out;
  }

  function stripAccentsFromCluster(cluster) {
    let out = '';
    for (const ch of cluster) {
      if (ACCENT_SET.has(ch)) continue;
      out += ch;
    }
    return out;
  }

  function syllabifyToy(s) {
    // Very rough syllabification for Greek-like strings.
    // Strategy: work on NFD clusters; build syllables around vowel nuclei.
    const clusters = graphemesNFD(s);
    const syllables = [];
    let cur = [];

    const bases = clusters.map(clusterBase);

    const isSpaceLike = (b) => /\s/.test(b);
    const isPunct = (b) => /[··.,;:!?—\-()\[\]«»"'’]/.test(b);

    function flush() {
      if (cur.length) {
        syllables.push(cur);
        cur = [];
      }
    }

    // Helper: detect diphthong nucleus (toy): αι, ει, οι, υι, αυ, ευ, ηυ, ου
    const diph = new Set(['αι','ει','οι','υι','αυ','ευ','ηυ','ου','ΑΙ','ΕΙ','ΟΙ','ΥΙ','ΑΥ','ΕΥ','ΗΥ','ΟΥ']);

    let i = 0;
    while (i < clusters.length) {
      const b = bases[i];

      if (isSpaceLike(b) || isPunct(b)) {
        flush();
        syllables.push([clusters[i]]); // keep as its own token
        i++;
        continue;
      }

      cur.push(clusters[i]);

      // If this cluster is a vowel, it may be nucleus.
      if (isVowelOrDiphthongStart(b)) {
        // Check diphthong with next base vowel.
        const nb = bases[i + 1];
        if (nb && isVowelOrDiphthongStart(nb)) {
          const pair = (b + nb);
          if (diph.has(pair)) {
            // include next cluster in same syllable nucleus
            cur.push(clusters[i + 1]);
            i += 2;
          } else {
            i += 1;
          }
        } else {
          i += 1;
        }

        // After nucleus, decide where to cut: if next are consonants, keep at most one consonant for onset of next syllable.
        // We'll peek ahead until next vowel/space/punct.
        let j = i;
        const consonantRun = [];
        while (j < clusters.length) {
          const bb = bases[j];
          if (isSpaceLike(bb) || isPunct(bb)) break;
          if (isVowelOrDiphthongStart(bb)) break;
          consonantRun.push(clusters[j]);
          j++;
        }

        if (consonantRun.length === 0) {
          flush();
        } else if (consonantRun.length === 1) {
          // single consonant goes with next syllable onset
          flush();
        } else {
          // split before last consonant (toy)
          const keep = consonantRun.slice(0, consonantRun.length - 1);
          cur.push(...keep);
          flush();
        }

        // advance i to start of next syllable (leave last consonant for onset)
        if (consonantRun.length <= 1) {
          // i already at first consonant (or vowel/space)
        } else {
          i = i + (consonantRun.length - 1);
        }
        continue;
      }

      i++;
    }
    flush();

    // Merge consecutive non-letter tokens into neighbors? Keep simple.
    return syllables;
  }

  function syllableText(sylClusters) {
    return sylClusters.join('').normalize('NFC');
  }

  function findAccentedSyllable(syllables) {
    for (let idx = 0; idx < syllables.length; idx++) {
      const syl = syllables[idx];
      // ignore pure punctuation/space syllables
      let hasGreek = false;
      for (const cl of syl) {
        const b = clusterBase(cl);
        if (isGreekLetter(b)) hasGreek = true;
        if (clusterHasAccent(cl)) return idx;
      }
      if (!hasGreek) continue;
    }
    return -1;
  }

  function syllableWeightToy(sylClusters) {
    // Heavy if: nucleus has long vowel (η ω) or diphthong, or ends with consonant.
    const textNFD = sylClusters.join('');
    const bases = [...textNFD].filter(ch => !isCombining(ch));

    // find vowel bases in syllable
    const vowelBases = bases.filter(isVowelBase);
    let nucleus = vowelBases.join('');

    const diph = new Set(['αι','ει','οι','υι','αυ','ευ','ηυ','ου','ΑΙ','ΕΙ','ΟΙ','ΥΙ','ΑΥ','ΕΥ','ΗΥ','ΟΥ']);
    let longByQuality = false;
    if (vowelBases.some(v => v === 'η' || v === 'ω' || v === 'Η' || v === 'Ω')) longByQuality = true;
    let diphthong = false;
    if (vowelBases.length >= 2) {
      // take first two vowel bases as a guess
      const pair = vowelBases[0] + vowelBases[1];
      if (diph.has(pair)) diphthong = true;
    }

    // ends with consonant base?
    const lastBase = bases[bases.length - 1] || '';
    const endsWithConsonant = lastBase && isGreekLetter(lastBase) && !isVowelBase(lastBase);

    const heavy = longByQuality || diphthong || endsWithConsonant;
    return { heavy, reason: heavy ? (longByQuality ? 'long vowel (η/ω)' : diphthong ? 'diphthong' : 'closed syllable') : 'open + short' };
  }

  function allowedAccentWindowToy(syllables) {
    // Consider only syllables that contain Greek letters.
    const greekSylIdx = syllables
      .map((syl, i) => ({ syl, i }))
      .filter(o => o.syl.some(cl => isGreekLetter(clusterBase(cl))));

    if (greekSylIdx.length === 0) return { allowed: [], note: 'No Greek syllables detected.' };

    const last = greekSylIdx[greekSylIdx.length - 1];
    const lastW = syllableWeightToy(last.syl);

    // Allowed: always ultima and penult; antepenult only if ultima is light.
    const allowed = [];
    const positions = [];

    const addFromEnd = (nFromEnd, label) => {
      const idx = greekSylIdx.length - nFromEnd;
      if (idx >= 0) {
        allowed.push(greekSylIdx[idx].i);
        positions.push(label);
      }
    };

    addFromEnd(1, 'ultima');
    addFromEnd(2, 'penult');
    if (!lastW.heavy) addFromEnd(3, 'antepenult');

    return {
      allowed,
      note: lastW.heavy ? 'Ultima is heavy → (toy) no antepenult accent.' : 'Ultima is light → (toy) antepenult is possible.',
      lastWeight: lastW
    };
  }

  function placeAcuteOnSyllable(syllables, targetIdx) {
    // Strip all accents, then add acute to first vowel cluster in target syllable.
    const stripped = syllables.map(syl => syl.map(stripAccentsFromCluster));

    const syl = stripped[targetIdx];
    if (!syl) return stripped.map(syllableText).join('');

    // Find first vowel base cluster in this syllable.
    for (let j = 0; j < syl.length; j++) {
      const b = clusterBase(syl[j]);
      if (isVowelBase(b)) {
        syl[j] = clusterWithAcute(syl[j]);
        break;
      }
    }

    return stripped.map(syllableText).join('');
  }

  function render() {
    const raw = inEl.value;
    const syllables = syllabifyToy(raw);

    // Render syllable chips
    sylBox.innerHTML = '';
    const accIdx = findAccentedSyllable(syllables);

    syllables.forEach((syl, idx) => {
      const t = syllableText(syl);
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'syl' + (idx === accIdx ? ' active' : '');
      btn.setAttribute('data-idx', String(idx));
      btn.textContent = t;

      // tag: weight if Greek syllable
      const hasGreek = syl.some(cl => isGreekLetter(clusterBase(cl)));
      if (hasGreek && syl.some(cl => isVowelBase(clusterBase(cl)))) {
        const w = syllableWeightToy(syl);
        const tag = document.createElement('span');
        tag.className = 'tag';
        tag.textContent = w.heavy ? 'heavy' : 'light';
        btn.appendChild(tag);
      }

      btn.addEventListener('click', () => {
        const out = placeAcuteOnSyllable(syllables, idx);
        inEl.value = out;
        render();
      });
      sylBox.appendChild(btn);
    });

    // Detected accent info
    const marks = listAccentMarks(raw);
    marksEl.textContent = `acute: ${marks.acute}, grave: ${marks.grave}, circumflex: ${marks.circumflex} (total: ${marks.total})`;

    if (accIdx === -1) {
      detEl.innerHTML = `<span class="bad">No accent mark detected</span> (click a syllable to add an acute).`;
    } else {
      const t = syllableText(syllables[accIdx]);
      detEl.innerHTML = `<span class="ok">Syllable ${accIdx + 1}</span>: <span class="mono">${escapeHtml(t)}</span>`;
    }

    // Weights + window
    const greekSyls = syllables
      .map((syl, i) => ({ syl, i }))
      .filter(o => o.syl.some(cl => isGreekLetter(clusterBase(cl))));

    if (greekSyls.length === 0) {
      weightsEl.textContent = '—';
      windowEl.textContent = '—';
      suggestEl.textContent = '—';
    } else {
      const wStr = greekSyls.map((o, k) => {
        const hasV = o.syl.some(cl => isVowelBase(clusterBase(cl)));
        if (!hasV) return `${k + 1}: ?`;
        const w = syllableWeightToy(o.syl);
        return `${k + 1}: ${w.heavy ? 'H' : 'L'} (${w.reason})`;
      }).join(' · ');
      weightsEl.textContent = wStr;

      const win = allowedAccentWindowToy(syllables);
      windowEl.textContent = `${win.note} Allowed: ${win.allowed.length ? win.allowed.map(i => i + 1).join(', ') : '—'}`;

      if (win.allowed.length) {
        suggestEl.innerHTML = win.allowed.map(i => {
          const t = syllableText(syllables[i]);
          return `<span class="mono">${escapeHtml(t)}</span>`;
        }).join(' / ');
      } else {
        suggestEl.textContent = '—';
      }
    }

    // Output: if exactly one accent mark, show normalized; else show stripped+reapplied? We'll just echo current.
    outEl.textContent = raw;
  }

  function escapeHtml(s) {
    return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  function moveAccent(dir) {
    const raw = inEl.value;
    const syllables = syllabifyToy(raw);
    const greekIdxs = syllables
      .map((syl, i) => ({ syl, i }))
      .filter(o => o.syl.some(cl => isGreekLetter(clusterBase(cl))) && o.syl.some(cl => isVowelBase(clusterBase(cl))));

    if (greekIdxs.length === 0) return;

    const accIdx = findAccentedSyllable(syllables);

    // Determine current position among greek syllables; if none, start at penult.
    let pos = greekIdxs.findIndex(o => o.i === accIdx);
    if (pos === -1) pos = Math.max(0, greekIdxs.length - 2);

    pos = Math.min(greekIdxs.length - 1, Math.max(0, pos + dir));
    const target = greekIdxs[pos].i;

    const out = placeAcuteOnSyllable(syllables, target);
    inEl.value = out;
    render();
  }

  // Events
  inEl.addEventListener('input', render);
  $('#prev').addEventListener('click', () => moveAccent(-1));
  $('#next').addEventListener('click', () => moveAccent(1));
  $('#strip').addEventListener('click', () => {
    inEl.value = stripAccentsOnly(inEl.value);
    render();
  });
  $('#btnClear').addEventListener('click', () => {
    inEl.value = '';
    inEl.focus();
    render();
  });

  // Examples dialog
  function openExamples() {
    chips.innerHTML = '';
    examples.forEach(ex => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'chip';
      b.textContent = ex;
      b.addEventListener('click', () => {
        inEl.value = ex;
        dlg.close();
        render();
        inEl.focus();
      });
      chips.appendChild(b);
    });
    dlg.showModal();
  }
  $('#btnDemo').addEventListener('click', openExamples);

  // Init
  render();
})();

passages.gadget_css:
:root{
  --bg:#0f1220;
  --card:#171a2b;
  --ink:#e9ecff;
  --muted:#b8bfdc;
  --line:#2a2f4a;
  --accent:#7dd3fc;
  --accent2:#a7f3d0;
  --warn:#fbbf24;
}
*{box-sizing:border-box}
body{
  margin:0;
  font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Arial, "Noto Sans", "Liberation Sans", sans-serif;
  background: radial-gradient(1200px 700px at 20% 0%, #1b1f3a 0%, var(--bg) 55%);
  color:var(--ink);
}
.wrap{max-width:980px;margin:0 auto;padding:18px 14px 28px}
.top{display:flex;gap:14px;align-items:flex-end;justify-content:space-between;margin-bottom:12px}
h1{font-size:22px;margin:0 0 4px 0;letter-spacing:.2px}
.sub{margin:0;color:var(--muted);font-size:13px;line-height:1.35}
.card{
  background: linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));
  border:1px solid var(--line);
  border-radius:14px;
  padding:14px 14px 12px;
  margin:12px 0;
  box-shadow: 0 10px 30px rgba(0,0,0,.25);
}
.card h2{margin:0 0 8px 0;font-size:16px}
.inst{margin:0 0 10px 0;color:var(--muted);font-size:13px;line-height:1.35}
.row{display:flex;flex-wrap:wrap;gap:10px;align-items:flex-end}
.lab{display:flex;flex-direction:column;gap:6px;font-size:12px;color:var(--muted)}
input, select{
  background:#0c0f1d;
  color:var(--ink);
  border:1px solid var(--line);
  border-radius:10px;
  padding:10px 10px;
  min-width: 190px;
  outline:none;
}
input:focus, select:focus{border-color:rgba(125,211,252,.7); box-shadow:0 0 0 3px rgba(125,211,252,.15)}
.btn{
  background: linear-gradient(180deg, rgba(125,211,252,.25), rgba(125,211,252,.12));
  border:1px solid rgba(125,211,252,.45);
  color:var(--ink);
  padding:10px 12px;
  border-radius:12px;
  cursor:pointer;
  font-weight:600;
}
.btn:hover{filter:brightness(1.08)}
.btn:active{transform:translateY(1px)}
.btn.ghost{
  background:transparent;
  border:1px solid var(--line);
  color:var(--muted);
}
.out{margin-top:12px}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
@media (max-width:860px){.grid{grid-template-columns:1fr}}
.box{border:1px solid var(--line);border-radius:12px;padding:10px;background:rgba(0,0,0,.18)}
.box h3{margin:0 0 6px 0;font-size:13px;color:var(--accent)}
.mono{font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace; font-size:13px; line-height:1.35}
.hint{margin-top:8px;color:var(--muted);font-size:12px;line-height:1.35}
.mini{margin-top:10px}
.mini summary{cursor:pointer;color:var(--accent2);font-weight:600}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
.chip{border:1px solid var(--line);background:rgba(0,0,0,.18);color:var(--ink);padding:7px 10px;border-radius:999px;cursor:pointer;font-size:13px}
.chip:hover{border-color:rgba(167,243,208,.55)}
.game{display:grid;grid-template-columns:1.4fr .6fr;gap:10px;align-items:stretch}
@media (max-width:860px){.game{grid-template-columns:1fr}}
.q{border:1px solid var(--line);border-radius:12px;padding:10px;background:rgba(0,0,0,.18)}
.prompt{font-size:14px;margin-bottom:10px}
.choices{display:flex;gap:8px;flex-wrap:wrap}
.result{margin-top:10px;min-height:20px;color:var(--muted);font-size:13px}
.score{border:1px solid var(--line);border-radius:12px;padding:10px;background:rgba(0,0,0,.18)}
.small{color:var(--muted);font-size:12px;line-height:1.35}
.foot{margin-top:10px;color:var(--muted)}
mark{
  background: rgba(251,191,36,.22);
  color: var(--ink);
  padding: 0 .18em;
  border-radius: .25em;
  border: 1px solid rgba(251,191,36,.35);
}

