(() => {
  // --- Utilities: Greek normalization & accent handling ---
  const combiningMarks = /[\u0300-\u036f]/g;
  const tonosToOxia = {
    "ά":"ά","έ":"έ","ή":"ή","ί":"ί","ό":"ό","ύ":"ύ","ώ":"ώ",
    "Ά":"Ά","Έ":"Έ","Ή":"Ή","Ί":"Ί","Ό":"Ό","Ύ":"Ύ","Ώ":"Ώ"
  };

  function nfd(s){ return (s||"").normalize('NFD'); }
  function stripCombining(s){ return nfd(s).replace(combiningMarks, "").normalize('NFC'); }

  function hasAccentChar(nfdCharSeq){
    // any of: acute/oxia/tonos, grave, circumflex/perispomeni
    return /[\u0301\u0300\u0342]/.test(nfdCharSeq);
  }

  function accentTypeAtIndex(word, baseIndex){
    // baseIndex counts base letters (no combining). Return 'acute'|'grave'|'circ'|null
    const w = nfd(word);
    let baseCount = -1;
    for(let i=0;i<w.length;i++){
      const ch = w[i];
      const isComb = /[\u0300-\u036f]/.test(ch);
      if(!isComb) baseCount++;
      if(baseCount===baseIndex){
        // scan forward combining marks
        let j=i+1;
        let t=null;
        while(j<w.length && /[\u0300-\u036f]/.test(w[j])){
          if(w[j]==='\u0301') t='acute';
          else if(w[j]==='\u0300') t='grave';
          else if(w[j]==='\u0342') t='circ';
          j++;
        }
        return t;
      }
    }
    return null;
  }

  function findAccentedVowelIndex(word){
    // Return base-letter index of the vowel that carries an accent mark, else -1
    const w = nfd(word);
    let baseIndex = -1;
    for(let i=0;i<w.length;i++){
      const ch = w[i];
      const isComb = /[\u0300-\u036f]/.test(ch);
      if(!isComb) baseIndex++;
      // if this base char is vowel, check its combining marks
      if(!isComb && isVowelBase(ch)){
        let j=i+1;
        let marks="";
        while(j<w.length && /[\u0300-\u036f]/.test(w[j])){ marks+=w[j]; j++; }
        if(hasAccentChar(marks)) return baseIndex;
      }
    }
    return -1;
  }

  function isVowelBase(ch){
    const c = stripCombining(ch).toLowerCase();
    return "αεηιουω".includes(c);
  }

  function isDiphthong(a,b){
    const x = stripCombining(a).toLowerCase();
    const y = stripCombining(b).toLowerCase();
    const pair = x+y;
    return ["αι","ει","οι","υι","αυ","ευ","ου","ηυ"].includes(pair);
  }

  function roughSyllabify(word){
    // Very rough: split after each vowel nucleus (diphthong counts as one)
    const w = nfd(word);
    // Build array of base letters with their original (NFC) grapheme-ish chunks
    const chunks=[];
    let cur="";
    for(let i=0;i<w.length;i++){
      const ch=w[i];
      if(/\p{Mark}/u.test(ch)) cur+=ch;
      else {
        if(cur) chunks.push(cur.normalize('NFC'));
        cur=ch;
      }
    }
    if(cur) chunks.push(cur.normalize('NFC'));

    const syll=[];
    let buf="";
    for(let i=0;i<chunks.length;i++){
      const ch=chunks[i];
      buf+=ch;
      if(isVowelBase(ch)){
        // diphthong with next?
        if(i+1<chunks.length && isVowelBase(chunks[i+1]) && isDiphthong(ch, chunks[i+1])){
          buf+=chunks[i+1];
          i++;
        }
        syll.push(buf);
        buf="";
      }
    }
    if(buf) syll[syll.length-1] = (syll[syll.length-1]||"") + buf;
    return syll.filter(s=>s.length);
  }

  function syllableWeight(syl, focusVowel, qty){
    // heavy if contains long vowel (η ω) or diphthong, or focus vowel treated long
    const base = stripCombining(syl).toLowerCase();
    // diphthongs
    for(let i=0;i<base.length-1;i++){
      if(isDiphthong(base[i], base[i+1])) return 'heavy';
    }
    if(base.includes('η') || base.includes('ω')) return 'heavy';
    if(qty==='long'){
      if(focusVowel==='i' && base.includes('ι')) return 'heavy';
      if(focusVowel==='y' && base.includes('υ')) return 'heavy';
    }
    return 'light';
  }

  function placeDemoAccent(word, focusVowel, qty){
    // Put an ACUTE on antepenult if allowed else on penult (toy).
    const plain = stripCombining(word);
    const syl = roughSyllabify(plain);
    if(syl.length===0) return {word: plain, syl, where:"—"};

    const lastW = syllableWeight(syl[syl.length-1], focusVowel, qty);
    let target = (syl.length>=3 && lastW==='light') ? syl.length-3 : (syl.length>=2 ? syl.length-2 : syl.length-1);

    // Add acute to first vowel of target syllable
    const accentedSyl = syl.map((s,i)=> i===target ? addAcuteToFirstVowel(s) : s);
    return {word: accentedSyl.join(''), syl: accentedSyl, where: target===syl.length-3?"antepenult":(target===syl.length-2?"penult":"ultima"), lastWeight:lastW};
  }

  function addAcuteToFirstVowel(s){
    const w = nfd(s);
    let out="";
    let done=false;
    for(let i=0;i<w.length;i++){
      const ch=w[i];
      if(!done && !/\p{Mark}/u.test(ch) && isVowelBase(ch)){
        out += ch + "\u0301"; // combining acute
        done=true;
      } else {
        out += ch;
      }
    }
    return out.normalize('NFC');
  }

  function markAccentPosition(word){
    const idx = findAccentedVowelIndex(word);
    if(idx<0) return {idx:-1, type:null, marked: word};
    // mark the base letter at idx
    const w = nfd(word);
    let base=-1;
    let out="";
    for(let i=0;i<w.length;i++){
      const ch=w[i];
      const isComb=/\p{Mark}/u.test(ch);
      if(!isComb) base++;
      if(!isComb && base===idx){
        out += "<mark>" + (ch) ;
        // include following combining marks
        let j=i+1;
        while(j<w.length && /\p{Mark}/u.test(w[j])){ out += w[j]; j++; }
        out += "</mark>";
        i = j-1;
      } else {
        out += ch;
      }
    }
    const type = accentTypeAtIndex(word, idx);
    return {idx, type, marked: out.normalize('NFC')};
  }

  // --- UI wiring ---
  const $ = (sel) => document.querySelector(sel);
  const wordEl = $('#word');
  const focusEl = $('#focus');
  const qtyEl = $('#qty');
  const goBtn = $('#go');
  const accentInfo = $('#accentInfo');
  const syllablesOut = $('#syllables');
  const demoOut = $('#demo');
  const chips = $('#chips');

  const samples = [
    {w:"Ἶρος", focus:"i"},
    {w:"μῖμος", focus:"i"},
    {w:"κτίλος", focus:"i"},
    {w:"Χίος", focus:"i"},
    {w:"ἵζε", focus:"i"},
    {w:"ἷζε", focus:"i"},
    {w:"σωλῆνος", focus:"i"},
    {w:"ποιμένος", focus:"i"},
  ];

  function renderChips(){
    chips.innerHTML = "";
    for(const s of samples){
      const b=document.createElement('button');
      b.className='chip';
      b.type='button';
      b.textContent=s.w;
      b.addEventListener('click', ()=>{
        wordEl.value=s.w;
        focusEl.value=s.focus;
        qtyEl.value='short';
        analyze();
      });
      chips.appendChild(b);
    }
  }

  function analyze(){
    const w = wordEl.value.trim();
    if(!w){
      accentInfo.textContent='—';
      syllablesOut.textContent='—';
      demoOut.textContent='—';
      return;
    }

    const marked = markAccentPosition(w);
    const typeLabel = marked.type ? ({acute:'acute (ὀξεῖα)', grave:'grave (βαρεῖα)', circ:'circumflex (περισπωμένη)'}[marked.type]) : 'none detected';
    accentInfo.innerHTML = `accent: <b>${typeLabel}</b><br>accented vowel: ${marked.idx>=0?marked.marked:'(none)'}`;

    const syl = roughSyllabify(w);
    syllablesOut.innerHTML = syl.length ? syl.map(s=>`[${escapeHtml(s)}]`).join(' ') : '—';

    const focus = focusEl.value;
    const qty = qtyEl.value;
    const demo = placeDemoAccent(w, focus, qty);
    const other = placeDemoAccent(w, focus, qty==='long'?'short':'long');

    demoOut.innerHTML = `with focus vowel <b>${focus==='i'?'ι':'υ'}</b> as <b>${qty}</b>: <b>${escapeHtml(demo.word)}</b>`
      + `<br><span class="small">(last syllable: ${demo.lastWeight}; demo target: ${demo.where})</span>`
      + `<br>flip quantity → <b>${escapeHtml(other.word)}</b>`;
  }

  function escapeHtml(s){
    return (s||"").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  goBtn.addEventListener('click', analyze);
  wordEl.addEventListener('keydown', (e)=>{ if(e.key==='Enter') analyze(); });
  focusEl.addEventListener('change', analyze);
  qtyEl.addEventListener('change', analyze);

  // --- Game ---
  const gamePrompt = $('#gamePrompt');
  const gameResult = $('#gameResult');
  const scoreEl = $('#score');
  const pickShort = $('#pickShort');
  const pickLong = $('#pickLong');
  const nextBtn = $('#next');

  const gameItems = [
    {word:"Ἶρος", wants:"long", note:"Herodian: Ἶρος proparoxytone/circumflex on antepenult because ι is long."},
    {word:"μῖμος", wants:"long", note:"μῖμος behaves like long ι in the toy."},
    {word:"κτίλος", wants:"short", note:"κτίλος: ι short → penult accent in the toy."},
    {word:"Χίος", wants:"short", note:"Χίος (island): ι short → penult accent."},
    {word:"ἵζε", wants:"short", note:"imperative ἵζε: short ι."},
    {word:"ἷζε", wants:"long", note:"past ἷζε: long ι."}
  ];
  let gi = 0;
  let correct = 0;
  let total = 0;

  function showGame(){
    const item = gameItems[gi % gameItems.length];
    const demoShort = placeDemoAccent(item.word, 'i', 'short').word;
    const demoLong  = placeDemoAccent(item.word, 'i', 'long').word;
    gamePrompt.innerHTML = `Word: <b>${escapeHtml(item.word)}</b><br>`
      + `<span class="small">Toy outputs: short → <b>${escapeHtml(demoShort)}</b>, long → <b>${escapeHtml(demoLong)}</b></span><br>`
      + `<span class="small">Which quantity matches Herodian’s story for this word?</span>`;
    gameResult.textContent = "";
  }

  function answer(choice){
    const item = gameItems[gi % gameItems.length];
    total++;
    const ok = (choice === item.wants);
    if(ok) correct++;
    scoreEl.textContent = `${correct} / ${total}`;
    gameResult.innerHTML = ok
      ? `✓ Correct. <span class="small">${item.note}</span>`
      : `✗ Not this time. <span class="small">${item.note}</span>`;
  }

  pickShort.addEventListener('click', ()=>answer('short'));
  pickLong.addEventListener('click', ()=>answer('long'));
  nextBtn.addEventListener('click', ()=>{ gi++; showGame(); });

  // init
  renderChips();
  analyze();
  showGame();
})();

