(function(){
  const $ = (sel, root=document) => root.querySelector(sel);
  const $$ = (sel, root=document) => Array.from(root.querySelectorAll(sel));

  const inText = $('#inText');
  const punct = $('#punct');
  const outText = $('#outText');
  const note = $('#note');
  const applyBtn = $('#apply');
  const resetBtn = $('#reset');

  const epiIn = $('#epiIn');
  const epiOut = $('#epiOut');
  const toggleEpi = $('#toggleEpi');
  const normalizeEpi = $('#normalizeEpi');

  // Map acute -> grave for precomposed polytonic vowels (common set)
  const acuteToGrave = new Map([
    ['ά','ὰ'],['έ','ὲ'],['ή','ὴ'],['ί','ὶ'],['ό','ὸ'],['ύ','ὺ'],['ώ','ὼ'],
    ['Ά','Ὰ'],['Έ','Ὲ'],['Ή','Ὴ'],['Ί','Ὶ'],['Ό','Ὸ'],['Ύ','Ὺ'],['Ώ','Ὼ'],

    // alpha
    ['ἄ','ἂ'],['ἅ','ἃ'],['ἄ','ἂ'],['ἅ','ἃ'],['Ἄ','Ἂ'],['Ἅ','Ἃ'],['Ἄ','Ἂ'],['Ἅ','Ἃ'],
    ['ᾄ','ᾂ'],['ᾅ','ᾃ'],['ᾌ','ᾊ'],['ᾍ','ᾋ'],['ᾴ','ᾲ'],['ᾌ','ᾊ'],

    // epsilon
    ['ἔ','ἒ'],['ἕ','ἓ'],['Ἔ','Ἒ'],['Ἕ','Ἓ'],

    // eta
    ['ἤ','ἢ'],['ἥ','ἣ'],['Ἤ','Ἢ'],['Ἥ','Ἣ'],
    ['ᾔ','ᾒ'],['ᾕ','ᾓ'],['ᾜ','ᾚ'],['ᾝ','ᾛ'],['ῄ','ῂ'],

    // iota
    ['ἴ','ἲ'],['ἵ','ἳ'],['Ἴ','Ἲ'],['Ἵ','Ἳ'],
    ['ΐ','ῒ'],

    // omicron
    ['ὄ','ὂ'],['ὅ','ὃ'],['Ὄ','Ὂ'],['Ὅ','Ὃ'],

    // upsilon
    ['ὔ','ὒ'],['ὕ','ὓ'],['ΰ','ῢ'],

    // omega
    ['ὤ','ὢ'],['ὥ','ὣ'],['Ὤ','Ὢ'],['Ὥ','Ὣ'],
    ['ᾤ','ᾢ'],['ᾥ','ᾣ'],['ᾬ','ᾪ'],['ᾭ','ᾫ'],['ῴ','ῲ']
  ]);

  const punctuationSet = new Set([',','.',':',';','·','—','!','?','·','…']);

  function chosenPunct(){
    const v = punct.value;
    if(v==='none') return '';
    if(v==='comma') return ',';
    if(v==='period') return '.';
    if(v==='colon') return ':';
    if(v==='semicolon') return ';';
    if(v==='middot') return '·';
    if(v==='dash') return '—';
    return '';
  }

  function splitLastWord(s){
    // Keep trailing spaces; find last token of letters (Greek/Latin) possibly with diacritics.
    const m = s.match(/^(.*?)([\p{L}\p{M}]+)(\s*)$/u);
    if(!m) return null;
    return {head:m[1], word:m[2], tailSpace:m[3]};
  }

  function graveLastAcute(word){
    // Replace the last acute-bearing character (precomposed) with its grave equivalent.
    // We scan from end to start.
    for(let i=word.length-1;i>=0;i--){
      const ch = word[i];
      if(acuteToGrave.has(ch)){
        return {changed:true, out: word.slice(0,i) + acuteToGrave.get(ch) + word.slice(i+1), at:i, from:ch, to:acuteToGrave.get(ch)};
      }
    }
    return {changed:false, out:word};
  }

  function applyRule(){
    const s = inText.value || '';
    const p = chosenPunct();

    const parts = splitLastWord(s);
    if(!parts){
      outText.textContent = s + p;
      note.textContent = 'No clear “last word” found.';
      return;
    }

    const {head, word, tailSpace} = parts;
    const hasPunct = p && punctuationSet.has(p);

    if(hasPunct){
      outText.textContent = head + word + tailSpace + p;
      note.innerHTML = 'Punctuation follows, so the toy <strong>does not</strong> grave the final acute.';
      return;
    }

    const g = graveLastAcute(word);
    outText.textContent = head + g.out + tailSpace;

    if(g.changed){
      note.innerHTML = 'No punctuation follows: final acute → grave (toy rule). Changed <span class="mono">'+escapeHtml(g.from)+'</span> → <span class="mono">'+escapeHtml(g.to)+'</span>.';
    } else {
      note.innerHTML = 'No punctuation follows, but the toy found <strong>no final acute</strong> to grave (maybe circumflex, no accent, or different encoding).';
    }
  }

  function escapeHtml(str){
    return String(str).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  function renderEpi(){
    epiOut.textContent = epiIn.value;
  }

  function toggleEpiForms(){
    let s = epiIn.value || '';
    // Toggle all occurrences of ἐπί and ἔπι (very naive)
    // Use placeholders to avoid double swapping.
    s = s.replaceAll('ἐπί','__EPI1__').replaceAll('ἔπι','__EPI2__');
    s = s.replaceAll('__EPI1__','ἔπι').replaceAll('__EPI2__','ἐπί');
    epiIn.value = s;
    renderEpi();
  }

  function normalizeToEpi(){
    let s = epiIn.value || '';
    s = s.replaceAll('ἔπι','ἐπί');
    epiIn.value = s;
    renderEpi();
  }

  // Wire up
  applyBtn.addEventListener('click', applyRule);
  resetBtn.addEventListener('click', () => {
    inText.value = 'καὶ Ἀχιλλεύς';
    punct.value = 'none';
    applyRule();
  });

  inText.addEventListener('keydown', (e)=>{ if(e.key==='Enter') applyRule(); });
  punct.addEventListener('change', applyRule);

  $$('.chip').forEach(btn => {
    btn.addEventListener('click', () => {
      inText.value = btn.getAttribute('data-eg') || '';
      punct.value = btn.getAttribute('data-p') || 'none';
      applyRule();
    });
  });

  toggleEpi.addEventListener('click', toggleEpiForms);
  normalizeEpi.addEventListener('click', normalizeToEpi);
  epiIn.addEventListener('input', renderEpi);

  // Initial render
  applyRule();
  renderEpi();
})();

