const $ = (sel) => document.querySelector(sel);
const inp = $('#inp');
const btnAnalyze = $('#btnAnalyze');
const btnExamples = $('#btnExamples');
const pickAcute = $('#pickAcute');
const pickCirc = $('#pickCirc');
const syllablesEl = $('#syllables');
const quantEl = $('#quant');
const resultEl = $('#result');
const verdictEl = $('#verdict');
const syllableButtons = $('#syllableButtons');
const gameHint = $('#gameHint');

let accentType = 'acute'; // 'acute' | 'circ'
let fromEnd = 2; // 1..4
let lastAnalysis = null;

const examples = [
  'Ὅμηρος',
  'Μενέλαος',
  'Ἑρμῆς',
  'Ἡρακλῆς',
  'κῆπος',
  'μῶλος',
  'φίλος',
  'Ἕκτωρ',
  'ἔρως',
  'Μήδεια',
  'Μήδεϊα',
  'πόλεως',
  'μάντεως',
  'ναός',
  'νεώς'
];

// --- Greek helpers ---
const combiningMarks = /[\u0300-\u036f\u1ab0-\u1aff\u1dc0-\u1dff\u20d0-\u20ff\ufe20-\ufe2f]/g;

function stripDiacritics(s){
  // Keep Greek letters, remove combining marks after NFD.
  return s.normalize('NFD').replace(combiningMarks,'').normalize('NFC');
}

function isGreekLetter(ch){
  return /[\u0370-\u03ff\u1f00-\u1fff]/.test(ch);
}

function tokenizeWords(s){
  // Split on spaces, keep only tokens that contain Greek letters.
  return s.split(/\s+/).filter(t => /[\u0370-\u03ff\u1f00-\u1fff]/.test(t));
}

const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

function isVowel(ch){
  return vowels.has(ch);
}

function lowerGreek(s){
  return s.toLocaleLowerCase('el');
}

const diphthongs = [
  'αι','ει','οι','υι','αυ','ευ','ηυ','ου','ωυ','ηι','ωι','ᾳ','ῃ','ῳ'
];

function isNaturallyLongVowelOrDiph(s){
  // s is a vowel nucleus (already stripped of diacritics, lowercased)
  if(!s) return false;
  if(s === 'η' || s === 'ω') return true;
  // treat long iota-subscript vowels as long by nature
  if(s === 'ᾳ' || s === 'ῃ' || s === 'ῳ') return true;
  return diphthongs.includes(s);
}

function roughSyllabify(word){
  // Very rough: build syllables by vowel nuclei; attach preceding consonants;
  // split consonant clusters by a simple rule: keep last consonant for next onset.
  const original = word;
  const clean = stripDiacritics(word);
  const chars = Array.from(clean);

  // Identify vowel nuclei positions and whether they form diphthongs.
  let nuclei = []; // {start,end,text}
  for(let i=0;i<chars.length;i++){
    const ch = chars[i];
    if(!isGreekLetter(ch)) continue;
    if(isVowel(ch)){
      let nuc = ch;
      let start = i;
      let end = i;
      const next = chars[i+1];
      if(next && isVowel(next)){
        const pair = lowerGreek(ch+next);
        if(diphthongs.includes(pair)){
          nuc = ch+next;
          end = i+1;
          i++;
        }
      }
      nuclei.push({start,end,text:nuc});
    }
  }
  if(nuclei.length===0) return [{text: original, nucleus:'', longByNature:false}];

  // Build syllable spans between nuclei.
  let sylls = [];
  for(let n=0;n<nuclei.length;n++){
    const cur = nuclei[n];
    const next = nuclei[n+1];
    const sylStart = (n===0) ? 0 : nuclei[n-1].end+1;
    const sylEnd = next ? next.start-1 : chars.length-1;

    // Now refine: split consonants between cur nucleus and next nucleus.
    // We want: ... V C* V ... => assign last consonant to next syllable onset.
    let end = sylEnd;
    if(next){
      // consonant cluster between cur.end+1 and next.start-1
      const cStart = cur.end+1;
      const cEnd = next.start-1;
      if(cEnd >= cStart){
        const cluster = chars.slice(cStart, cEnd+1);
        // count Greek letters in cluster
        const greekCluster = cluster.filter(isGreekLetter);
        if(greekCluster.length>=2){
          // move last consonant to next onset
          end = cEnd-1;
        } else {
          end = cEnd; // single consonant stays as coda
        }
      } else {
        end = cur.end; // adjacent vowels (hiatus or diphthong already handled)
      }
    }

    const slice = chars.slice(sylStart, end+1).join('');
    // nucleus text from clean chars
    const nucleus = chars.slice(cur.start, cur.end+1).join('');
    const longByNature = isNaturallyLongVowelOrDiph(lowerGreek(nucleus));
    sylls.push({text:slice, nucleus, longByNature});
  }

  // If we left a consonant for next onset, ensure syllable texts cover all chars.
  // Reconstruct by distributing leftover chars to following syllable.
  // Simple fix: rebuild by concatenating syll texts and compare.
  const built = sylls.map(s=>s.text).join('');
  if(built.length !== chars.length){
    // fallback: naive split at nuclei boundaries
    sylls = [];
    for(let n=0;n<nuclei.length;n++){
      const start = (n===0)?0:nuclei[n].start;
      const end = (n===nuclei.length-1)?chars.length-1:nuclei[n+1].start-1;
      const nucleus = chars.slice(nuclei[n].start, nuclei[n].end+1).join('');
      sylls.push({
        text: chars.slice(start,end+1).join(''),
        nucleus,
        longByNature: isNaturallyLongVowelOrDiph(lowerGreek(nucleus))
      });
    }
  }

  // Map syllable slices back onto original word with diacritics:
  // We approximate by applying the same slicing indices on NFD arrays.
  // For simplicity in display, we show syllables from the stripped form.
  return sylls;
}

function applyAccentToSyllable(word, sylls, targetIndexFromEnd, type){
  // Return a display form: stripped word with accent mark on nucleus vowel.
  // We do not attempt correct polytonic placement; we add combining acute/circumflex
  // to the first vowel of the target syllable nucleus.
  const clean = stripDiacritics(word).normalize('NFD');
  const chars = Array.from(clean);

  // Find vowel nuclei positions again in this NFD string.
  let vowelPositions = [];
  for(let i=0;i<chars.length;i++){
    const ch = chars[i];
    if(isVowel(ch)) vowelPositions.push(i);
  }
  if(vowelPositions.length===0) return stripDiacritics(word);

  // Determine which syllable index (0..n-1)
  const n = sylls.length;
  const sylIndex = n - targetIndexFromEnd;
  if(sylIndex < 0 || sylIndex >= n) return stripDiacritics(word);

  // Find first vowel position within that syllable span by searching in syll text.
  // We approximate by locating syllable text in the clean string.
  const cleanNFC = stripDiacritics(word);
  const sylText = sylls[sylIndex].text;
  const start = cleanNFC.indexOf(sylText);
  let pos = -1;
  if(start >= 0){
    const end = start + sylText.length;
    // find first vowel in that range
    for(let i=start;i<end;i++){
      const ch = cleanNFC[i];
      if(isVowel(ch)) { pos = i; break; }
    }
  }
  if(pos < 0){
    // fallback: choose vowel position by nucleus order
    pos = vowelPositions[Math.min(sylIndex, vowelPositions.length-1)];
  }

  // Convert pos in NFC to pos in NFD array: approximate by scanning.
  // We'll rebuild mapping by iterating NFC chars and consuming NFD.
  const nfcChars = Array.from(cleanNFC);
  let nfdIndex = 0;
  let targetNfd = -1;
  for(let i=0;i<nfcChars.length;i++){
    const nfdChunk = Array.from(nfcChars[i].normalize('NFD'));
    if(i === pos){
      targetNfd = nfdIndex; // first codepoint of this char
      break;
    }
    nfdIndex += nfdChunk.length;
  }
  if(targetNfd < 0) targetNfd = vowelPositions[0];

  const mark = (type==='acute') ? '\u0301' : '\u0342'; // combining acute / perispomeni
  // Remove any existing accent marks on that vowel char (combining acute/grave/circumflex)
  // by skipping marks immediately after the vowel.
  let out = [];
  for(let i=0;i<chars.length;i++){
    out.push(chars[i]);
    if(i===targetNfd){
      // insert mark after vowel base
      out.push(mark);
    }
  }
  return out.join('').normalize('NFC');
}

function ruleCheck(sylls, targetFromEnd, type){
  const n = sylls.length;
  const idx = n - targetFromEnd;
  if(idx < 0 || idx >= n){
    return {ok:false, level:'bad', msg:`No such syllable: you asked for ${targetFromEnd} from the end, but the word has ${n}.`};
  }
  if(type==='acute'){
    if(targetFromEnd>=1 && targetFromEnd<=3){
      return {ok:true, level:'good', msg:'Acute is allowed on ultima/penult/antepenult (not further back).'};
    }
    return {ok:false, level:'bad', msg:'Herodian: acute cannot go further back than the antepenult (3rd from end).'};
  } else {
    // circumflex
    if(targetFromEnd>2){
      return {ok:false, level:'bad', msg:'Herodian: circumflex can be only on ultima or penult (not on antepenult).'};
    }
    if(!sylls[idx].longByNature){
      return {ok:false, level:'warn', msg:'Circumflex needs a syllable “long by nature” (η/ω or a diphthong). This syllable doesn’t look naturally long (toy’s guess).'};
    }
    return {ok:true, level:'good', msg:'Circumflex placement looks legal here (ultima/penult + naturally long, by this toy’s guess).'};
  }
}

function render(){
  const text = inp.value.trim();
  const words = tokenizeWords(text);
  const word = words[0] || text;
  const sylls = roughSyllabify(word);
  lastAnalysis = {word, sylls};

  syllablesEl.textContent = sylls.map((s,i)=>`[${i+1}] ${s.text}`).join(' · ');
  quantEl.textContent = sylls.map((s,i)=>`${s.longByNature?'—':'⏑'}(${s.nucleus||'?'})`).join(' ');

  const accented = applyAccentToSyllable(word, sylls, fromEnd, accentType);
  resultEl.textContent = accented;

  const verdict = ruleCheck(sylls, fromEnd, accentType);
  verdictEl.className = 'verdict ' + verdict.level;
  verdictEl.textContent = verdict.msg;

  // game buttons
  syllableButtons.innerHTML = '';
  sylls.forEach((s, i) => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'sbtn';
    const fromEndHere = sylls.length - i;
    btn.dataset.fromend = String(fromEndHere);
    btn.innerHTML = `${s.text}<small>${fromEndHere} from end · ${s.longByNature?'long?':'short?'}</small>`;
    btn.addEventListener('click', () => {
      fromEnd = fromEndHere;
      syncFromEndButtons();
      render();
    });
    syllableButtons.appendChild(btn);
  });

  gameHint.textContent = `Tip: Herodian says acute can be 1–3 from the end; circumflex only 1–2, and only on “naturally long”. Current: ${accentType}, target ${fromEnd} from end.`;
}

function setAccentType(t){
  accentType = t;
  pickAcute.classList.toggle('on', t==='acute');
  pickCirc.classList.toggle('on', t==='circ');
  render();
}

function syncFromEndButtons(){
  document.querySelectorAll('[data-fromend]').forEach(b=>{
    b.classList.toggle('on', Number(b.dataset.fromend)===fromEnd);
  });
}

pickAcute.addEventListener('click', ()=>setAccentType('acute'));
pickCirc.addEventListener('click', ()=>setAccentType('circ'));

document.querySelectorAll('[data-fromend]').forEach(b=>{
  b.addEventListener('click', ()=>{
    fromEnd = Number(b.dataset.fromend);
    syncFromEndButtons();
    render();
  });
});

btnAnalyze.addEventListener('click', render);
inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') render(); });

btnExamples.addEventListener('click', ()=>{
  const cur = inp.value.trim();
  const i = Math.max(0, examples.indexOf(cur));
  const next = examples[(i+1) % examples.length];
  inp.value = next;
  render();
});

// initial
syncFromEndButtons();
render();

