(() => {
  const $ = (sel, root=document) => root.querySelector(sel);
  const $$ = (sel, root=document) => Array.from(root.querySelectorAll(sel));

  const elWord = $('#word');
  const elNext = $('#next');
  const elOut = $('#out');
  const btnExamples = $('#btnExamples');
  const btnClear = $('#btnClear');

  // --- Utilities: Greek normalization and accent placement (toy-level) ---
  const COMBINING = {
    acute: '\u0301',
    circumflex: '\u0342',
    grave: '\u0300',
    diaeresis: '\u0308',
    smooth: '\u0313',
    rough: '\u0314',
    iotaSub: '\u0345'
  };

  const stripCombining = (s) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').normalize('NFC');

  const isGreekLetter = (ch) => /[\u0370-\u03FF\u1F00-\u1FFF]/.test(ch);

  const firstGreekLetter = (s) => {
    const n = s.normalize('NFC');
    for (const ch of n) if (isGreekLetter(ch)) return ch;
    return '';
  };

  const isVowel = (ch) => {
    const c = stripCombining(ch).toLowerCase();
    return 'αεηιουω'.includes(c);
  };

  const startsWithConsonant = (s) => {
    const ch = firstGreekLetter(s);
    if (!ch) return false;
    return isGreekLetter(ch) && !isVowel(ch);
  };

  // Syllabify very roughly: split into vowel nuclei (including common diphthongs).
  function syllableNuclei(word) {
    const w = stripCombining(word).toLowerCase();
    const nuclei = [];
    const chars = Array.from(w);
    const diph = new Set(['αι','ει','οι','υι','αυ','ευ','ηυ','ου']);

    for (let i=0;i<chars.length;i++) {
      const a = chars[i];
      const b = chars[i+1] || '';
      if (isVowel(a)) {
        if (b && isVowel(b) && diph.has(a+b)) {
          nuclei.push({start:i, len:2, text:a+b});
          i++;
        } else {
          nuclei.push({start:i, len:1, text:a});
        }
      }
    }
    return nuclei;
  }

  // Place combining accent on the vowel nucleus of a target syllable counted from end.
  function addAccent(word, fromEndIndex, accentType) {
    const raw = stripCombining(word);
    const nfd = raw.normalize('NFD');
    const base = Array.from(nfd);

    // Map indices in stripped NFC-ish string to indices in NFD array is messy.
    // We'll instead work on NFC codepoints and rebuild with NFD accents by locating vowel nucleus in NFC.
    const w = stripCombining(raw); // NFC
    const nuclei = syllableNuclei(w);
    if (nuclei.length === 0) return raw;

    const target = nuclei[nuclei.length - 1 - fromEndIndex];
    if (!target) return raw;

    // Find the first vowel char position in the target nucleus in the NFC string.
    const chars = Array.from(w);
    const pos = target.start; // position in chars

    // Rebuild with NFD and insert combining mark after that vowel letter.
    // Convert to NFD per character to preserve Greek precomposed letters.
    const out = [];
    for (let i=0;i<chars.length;i++) {
      const ch = chars[i];
      const chNFD = ch.normalize('NFD');
      out.push(chNFD);
      if (i === pos) {
        out.push(accentType === 'circumflex' ? COMBINING.circumflex : COMBINING.acute);
      }
    }
    return out.join('').normalize('NFC');
  }

  function endsWithAiOi(word) {
    const w = stripCombining(word).toLowerCase().trim();
    return w.endsWith('αι') || w.endsWith('οι');
  }

  function lastTwo(word) {
    const w = stripCombining(word).toLowerCase().trim();
    return w.slice(-2);
  }

  // Core toy logic inspired by Herodian 1.9
  function accentSuggestion(word, next, mode) {
    const clean = stripCombining(word).trim();
    if (!clean) return { ok:false, msg:'Type a Greek word.' };
    if (!endsWithAiOi(clean)) {
      return { ok:false, msg:'This toy only handles words ending in -αι or -οι (unaccented input is fine).' };
    }

    const nuclei = syllableNuclei(clean);
    const syllCount = nuclei.length;

    const consonantFollows = startsWithConsonant(next || '');

    // Determine whether final -αι/-οι counts as long.
    // General: short unless consonant follows.
    // Opt/adv: long even without consonant.
    let finalLong = false;
    if (mode === 'optadv') finalLong = true;
    if (consonantFollows) finalLong = true;

    // Special oikoi mode: choose between noun (proparoxytone with circumflex) and adverb (paroxytone acute)
    const base = stripCombining(clean).toLowerCase();
    if (mode === 'oikoi' && (base === 'οικοι' || base === 'οἰκοι' || base === 'οἶκοι')) {
      // If next word starts with consonant, show the "lowered" behavior too.
      const noun = addAccent(clean, 2, 'circumflex'); // antepenult circumflex (toy)
      const adv = addAccent(clean, 1, 'acute'); // penult acute
      let lowered = null;
      if (consonantFollows) {
        // When long, accent cannot stay on antepenult; lower to penult acute (toy)
        lowered = addAccent(clean, 1, 'acute');
      }
      return {
        ok:true,
        kind:'special',
        consonantFollows,
        finalLong,
        forms: { noun, adv, lowered },
        tags: [
          'special case from passage: οἴκοι (adv.) vs οἶκοι (noun)',
          consonantFollows ? 'following consonant ⇒ treat final -οι as long ⇒ “lowering”' : 'no following consonant'
        ]
      };
    }

    // Decide accent position and type.
    // If final is short: allow antepenult accent.
    // If final is long: accent must be on penult (acute).
    // Accent type: if penult is long and final short, circumflex on penult (Herodian mentions προπερισπᾶται like μοῦσαι/κοῦροι).
    // We'll approximate penult-long by checking if penult nucleus is η/ω or diphthong.

    if (syllCount < 2) {
      return { ok:false, msg:'Need at least two syllables for this toy.' };
    }

    const penult = nuclei[syllCount - 2];
    const penText = penult ? penult.text : '';
    const penLong = (() => {
      if (!penText) return false;
      if (penText.length === 2) return true; // diphthong
      return ['η','ω'].includes(penText);
    })();

    let accentFromEnd = 0; // 0=ultima,1=penult,2=antepenult
    let accentType = 'acute';
    let rule = '';

    if (finalLong) {
      accentFromEnd = 1;
      accentType = 'acute';
      rule = consonantFollows
        ? 'Following consonant ⇒ final -αι/-οι treated as long ⇒ accent “lowered” to penult (acute).'
        : 'Optative/adverb mode ⇒ final -αι/-οι treated as long ⇒ accent on penult (acute).';
    } else {
      // final short
      if (syllCount >= 3) {
        accentFromEnd = 2;
        accentType = 'acute';
        rule = 'No following consonant ⇒ final -αι/-οι treated as short ⇒ accent can stand on antepenult (acute).';
      } else {
        accentFromEnd = 1;
        accentType = penLong ? 'circumflex' : 'acute';
        rule = 'Only two syllables ⇒ accent on penult; circumflex if penult seems long and final short (toy).';
      }

      // If user typed something like mou-sai / kou-roi, we want antepenult circumflex? Herodian: προπερισπᾶται.
      // We'll add a playful option: if syllCount>=3 and penLong and final short, show an alternate with circumflex on antepenult? (not standard).
    }

    const accented = addAccent(clean, accentFromEnd, accentType);

    // Provide a "Herodian-style" extra: if final short and penLong and syllCount>=3, show proparoxytone circumflex on antepenult? Actually pro-perispomenon is circumflex on penult.
    // For μοῦσαι, accent is on penult with circumflex (moû-sai): that's fromEnd=1 circumflex.
    // But Herodian says μοῦσαι προπερισπᾶται, i.e., circumflex on penult with final short.
    // Our general rule above would put antepenult for 3+ syllables; that fits Μήδειαι/ἄνθρωποι, but not μοῦσαι/κοῦροι.
    // So: if word is exactly of shape Xουσαι / Xουροι etc? We'll implement a simple override: if syllCount==2 and final is -αι/-οι and penLong => circumflex on penult.
    // For μοῦσαι/κοῦροι, syllCount is 2 indeed.

    const tags = [];
    tags.push(finalLong ? 'final -αι/-οι = long (in this context)' : 'final -αι/-οι = short (in this context)');
    tags.push(consonantFollows ? 'next word starts with consonant' : 'no following consonant detected');

    return {
      ok:true,
      kind:'normal',
      consonantFollows,
      finalLong,
      accented,
      rule,
      tags
    };
  }

  function render() {
    const mode = ($$('input[name=mode]')).find(r => r.checked)?.value || 'general';
    const word = elWord.value;
    const next = elNext.value;

    const res = accentSuggestion(word, next, mode);

    if (!res.ok) {
      elOut.innerHTML = `
        <div class="big"><span class="warn">${escapeHtml(res.msg)}</span></div>
        <div class="meta">Try: <span class="ex">Μηδειαι</span>, <span class="ex">ανθρωποι</span>, <span class="ex">μουσαι</span>, <span class="ex">κουροι</span>, <span class="ex">οικοι</span>.</div>
      `;
      return;
    }

    if (res.kind === 'special') {
      const { noun, adv, lowered } = res.forms;
      elOut.innerHTML = `
        <div class="big">
          <div><span class="ok">noun</span>: <span class="ex">${escapeHtml(noun)}</span></div>
          <div><span class="ok">adverb</span>: <span class="ex">${escapeHtml(adv)}</span></div>
          ${lowered ? `<div><span class="ok">with following consonant</span>: <span class="ex">${escapeHtml(lowered)}</span></div>` : ''}
        </div>
        <div class="meta">${res.tags.map(t=>`<span class="tag">${escapeHtml(t)}</span>`).join('')}</div>
      `;
      return;
    }

    elOut.innerHTML = `
      <div class="big"><span class="ex">${escapeHtml(res.accented)}</span></div>
      <div class="meta">${escapeHtml(res.rule)}<div style="margin-top:6px">${res.tags.map(t=>`<span class="tag">${escapeHtml(t)}</span>`).join('')}</div></div>
    `;
  }

  function escapeHtml(s) {
    return String(s)
      .replaceAll('&','&amp;')
      .replaceAll('<','&lt;')
      .replaceAll('>','&gt;')
      .replaceAll('"','&quot;')
      .replaceAll("'",'&#39;');
  }

  // Events
  ['input','change'].forEach(ev => {
    elWord.addEventListener(ev, render);
    elNext.addEventListener(ev, render);
  });
  $$('input[name=mode]').forEach(r => r.addEventListener('change', render));

  btnExamples.addEventListener('click', () => {
    const examples = [
      {w:'Μηδειαι', n:'', m:'general'},
      {w:'Μηδειαι', n:'γε', m:'general'},
      {w:'ανθρωποι', n:'', m:'general'},
      {w:'ανθρωποι', n:'τε', m:'general'},
      {w:'μουσαι', n:'', m:'general'},
      {w:'μουσαι', n:'γε', m:'general'},
      {w:'κουροι', n:'', m:'general'},
      {w:'κουροι', n:'βροτοι', m:'general'},
      {w:'οικοι', n:'', m:'oikoi'},
      {w:'οικοι', n:'γε', m:'oikoi'},
      {w:'οιμοι', n:'', m:'general'},
      {w:'οιμοι', n:'γε', m:'general'},
      {w:'Μηδειαι', n:'', m:'optadv'},
      {w:'ανθρωποι', n:'', m:'optadv'}
    ];
    const pick = examples[Math.floor(Math.random()*examples.length)];
    elWord.value = pick.w;
    elNext.value = pick.n;
    $$('input[name=mode]').forEach(r => r.checked = (r.value === pick.m));
    render();
  });

  btnClear.addEventListener('click', () => {
    elWord.value = '';
    elNext.value = '';
    $$('input[name=mode]').forEach(r => r.checked = (r.value === 'general'));
    render();
  });

  // Initial render
  render();
})();

