// Herodian Accent Toy (offline, vanilla JS)

const $ = (sel, el=document) => el.querySelector(sel);
const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

// --- Utilities for Greek accent swapping (precomposed) ---
const acuteToGrave = {
  'ά':'ὰ','έ':'ὲ','ή':'ὴ','ί':'ὶ','ό':'ὸ','ύ':'ὺ','ώ':'ὼ',
  'Ά':'Ὰ','Έ':'Ὲ','Ή':'Ὴ','Ί':'Ὶ','Ό':'Ὸ','Ύ':'Ὺ','Ώ':'Ὼ'
};
const graveToAcute = Object.fromEntries(Object.entries(acuteToGrave).map(([a,g])=>[g,a]));

const vowelsBase = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

function isPunct(ch){
  return /[\s\u00A0]/.test(ch) ? false : /[\.,;:!?··—–\)\]\}»”’]/.test(ch);
}

function lowerFinalAcuteInPhrase(text){
  // For each word token, if it ends with an acute vowel and next non-space char is NOT punctuation, lower it.
  // We keep punctuation attached to the word as separate tokens.
  const chars = Array.from(text);

  // Find word spans: sequences of letters/diacritics/apostrophes.
  // We'll treat spaces as separators.
  let i=0;
  const changes = new Map(); // index -> newChar

  while(i < chars.length){
    // skip spaces
    if(/[\s\u00A0]/.test(chars[i])){ i++; continue; }

    // start token
    const start = i;
    while(i < chars.length && !/[\s\u00A0]/.test(chars[i])) i++;
    const end = i; // exclusive

    // token is chars[start:end]
    // Determine last letter char in token (ignore trailing punctuation like comma/period)
    let j = end-1;
    while(j >= start && isPunct(chars[j])) j--;
    if(j < start) continue;

    const last = chars[j];
    if(!(last in acuteToGrave)) continue;

    // Find next non-space char after token
    let k = end;
    while(k < chars.length && /[\s\u00A0]/.test(chars[k])) k++;
    const next = k < chars.length ? chars[k] : null;

    // If punctuation immediately follows (next char is punctuation), do NOT lower.
    if(next && isPunct(next)) continue;

    // Otherwise lower
    changes.set(j, acuteToGrave[last]);
  }

  const out = chars.map((ch, idx) => changes.has(idx) ? changes.get(idx) : ch).join('');
  return { out, changes };
}

function renderWithDiff(original, transformed, changes){
  if(!changes || changes.size===0) return escapeHtml(transformed);
  const o = Array.from(original);
  const t = Array.from(transformed);
  let html = '';
  for(let i=0;i<t.length;i++){
    const ch = t[i];
    if(changes.has(i)) html += `<span class="changed">${escapeHtml(ch)}</span>`;
    else html += escapeHtml(ch);
  }
  return html;
}

function escapeHtml(s){
  return String(s)
    .replaceAll('&','&amp;')
    .replaceAll('<','&lt;')
    .replaceAll('>','&gt;')
    .replaceAll('"','&quot;')
    .replaceAll("'",'&#39;');
}

// --- Contraction sandbox ---
// Very small mapping of adjacent vowel pairs -> contracted vowel.
// Not comprehensive; just enough to feel the idea.
const contractMap = {
  'αο':'ω', 'άο':'ώ', 'ὰο':'ὼ',
  'εο':'ου', 'έο':'ού', 'ὲο':'οὺ',
  'οο':'ου', 'όο':'ού', 'ὸο':'οὺ',
  'ωο':'ω', 'ώο':'ώ', 'ὼο':'ὼ',
  'οϊ':'οι', 'όϊ':'οί', 'ὸϊ':'οὶ',
  'οΐ':'οί', 'οῒ':'οὶ',
  'αϊ':'αι', 'άϊ':'αί', 'ὰϊ':'αὶ',
  'εϊ':'ει', 'έϊ':'εί', 'ὲϊ':'εὶ'
};

function firstVowelPairIndex(str){
  const a = Array.from(str);
  for(let i=0;i<a.length-1;i++){
    const c1=a[i], c2=a[i+1];
    // treat precomposed accented vowels as vowels too
    const b1 = baseVowel(c1);
    const b2 = baseVowel(c2);
    if(b1 && b2) return i;
  }
  return -1;
}

function baseVowel(ch){
  // Return base vowel letter if ch is a (possibly accented) Greek vowel; else null.
  const map = {
    'α':'α','ά':'α','ὰ':'α','ᾶ':'α','ἀ':'α','ἁ':'α','ἄ':'α','ἂ':'α','ἆ':'α','ἅ':'α','ἃ':'α','ἇ':'α','ᾄ':'α','ᾂ':'α','ᾆ':'α','ᾅ':'α','ᾃ':'α','ᾇ':'α','ᾴ':'α','ᾲ':'α','ᾷ':'α',
    'ε':'ε','έ':'ε','ὲ':'ε','ἐ':'ε','ἑ':'ε','ἔ':'ε','ἒ':'ε','ἕ':'ε','ἓ':'ε',
    'η':'η','ή':'η','ὴ':'η','ῆ':'η','ἠ':'η','ἡ':'η','ἤ':'η','ἢ':'η','ἦ':'η','ἥ':'η','ἣ':'η','ἧ':'η','ῄ':'η','ῂ':'η','ῇ':'η',
    'ι':'ι','ί':'ι','ὶ':'ι','ῖ':'ι','ϊ':'ι','ΐ':'ι','ῒ':'ι','ῗ':'ι','ἰ':'ι','ἱ':'ι','ἴ':'ι','ἲ':'ι','ἶ':'ι','ἵ':'ι','ἳ':'ι','ἷ':'ι',
    'ο':'ο','ό':'ο','ὸ':'ο','ὀ':'ο','ὁ':'ο','ὄ':'ο','ὂ':'ο','ὅ':'ο','ὃ':'ο',
    'υ':'υ','ύ':'υ','ὺ':'υ','ῦ':'υ','ϋ':'υ','ΰ':'υ','ῢ':'υ','ῧ':'υ','ὐ':'υ','ὑ':'υ','ὔ':'υ','ὒ':'υ','ὖ':'υ','ὕ':'υ','ὓ':'υ','ὗ':'υ',
    'ω':'ω','ώ':'ω','ὼ':'ω','ῶ':'ω','ὠ':'ω','ὡ':'ω','ὤ':'ω','ὢ':'ω','ὦ':'ω','ὥ':'ω','ὣ':'ω','ὧ':'ω','ῴ':'ω','ῲ':'ω','ῷ':'ω',
    'Α':'Α','Ά':'Α','Ὰ':'Α','ᾶ':'Α',
    'Ε':'Ε','Έ':'Ε','Ὲ':'Ε',
    'Η':'Η','Ή':'Η','Ὴ':'Η',
    'Ι':'Ι','Ί':'Ι','Ὶ':'Ι',
    'Ο':'Ο','Ό':'Ο','Ὸ':'Ο',
    'Υ':'Υ','Ύ':'Υ','Ὺ':'Υ',
    'Ω':'Ω','Ώ':'Ω','Ὼ':'Ω'
  };
  return map[ch] || null;
}

function applyContraction(input, mode){
  const arr = Array.from(input);
  const idx = firstVowelPairIndex(input);
  if(idx === -1) return { out: input, note: 'No adjacent vowel pair found to contract.' };

  const pair = arr[idx] + arr[idx+1];

  // Determine accent interaction based on mode.
  // We approximate by looking for acute/grave on the first/second vowel.
  const v1 = arr[idx], v2 = arr[idx+1];
  const v1HasAcute = v1 in acuteToGrave;
  const v1HasGrave = v1 in graveToAcute;
  const v2HasAcute = v2 in acuteToGrave;
  const v2HasGrave = v2 in graveToAcute;

  let contracted = contractMap[pair];
  if(!contracted){
    // fallback: just remove the second vowel (toy-ish)
    contracted = arr[idx];
  }

  // Now impose accent outcome in a toy way.
  // If mode acute+grave->circumflex: if v1 acute and v2 grave (or unaccented), try to circumflex the contracted vowel.
  // If mode grave+acute->acute: if v1 grave and v2 acute (or unaccented), try to acute the contracted vowel.

  let note = `Contracted the first vowel pair: “${pair}”.`;

  if(mode === 'acuteGraveToCirc'){
    const condition = v1HasAcute && (v2HasGrave || !v2HasAcute);
    if(condition){
      contracted = circumflexify(contracted);
      note += ' Applied toy rule: acute + grave → circumflex.';
    } else {
      note += ' (Condition not clearly met; contraction applied without accent change.)';
    }
  } else {
    const condition = v1HasGrave && (v2HasAcute || !v2HasGrave);
    if(condition){
      contracted = acutify(contracted);
      note += ' Applied toy rule: grave + acute → acute.';
    } else {
      note += ' (Condition not clearly met; contraction applied without accent change.)';
    }
  }

  // Replace pair with contracted string
  const outArr = [...arr.slice(0, idx), ...Array.from(contracted), ...arr.slice(idx+2)];
  return { out: outArr.join(''), note };
}

function acutify(s){
  // If s is a single vowel, add acute; if diphthong, acute the second vowel (toy convention).
  const a = Array.from(s);
  if(a.length===1){
    return addAcute(a[0]);
  }
  // diphthong like ου, οι, ει, αι
  const last = a[a.length-1];
  a[a.length-1] = addAcute(last);
  return a.join('');
}

function circumflexify(s){
  // If single vowel, add circumflex where we have a precomposed form; for diphthongs, circumflex the second.
  const a = Array.from(s);
  if(a.length===1){
    return addCircumflex(a[0]);
  }
  const last = a[a.length-1];
  a[a.length-1] = addCircumflex(last);
  return a.join('');
}

function addAcute(ch){
  // If already grave, swap to acute; if plain vowel, use tonos where available.
  if(ch in graveToAcute) return graveToAcute[ch];
  const map = { 'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ', 'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ', 'ι':'ί','υ':'ύ' };
  return map[ch] || ch;
}

function addCircumflex(ch){
  const map = {
    'α':'ᾶ','ά':'ᾶ','ὰ':'ᾶ',
    'η':'ῆ','ή':'ῆ','ὴ':'ῆ',
    'ι':'ῖ','ί':'ῖ','ὶ':'ῖ',
    'υ':'ῦ','ύ':'ῦ','ὺ':'ῦ',
    'ω':'ῶ','ώ':'ῶ','ὼ':'ῶ',
    // for ο/ε there is no circumflex in Attic orthography; keep acute if present
    'ο':'ό','ὸ':'ό','ό':'ό',
    'ε':'έ','ὲ':'έ','έ':'έ'
  };
  return map[ch] || ch;
}

// --- Wiring UI ---
const phraseEl = $('#phrase');
const applyGraveEl = $('#applyGrave');
const showDiffEl = $('#showDiff');
const phraseOutEl = $('#phraseOut');

const defaultPhrase = phraseEl.value;

function updatePhrase(){
  const txt = phraseEl.value;
  if(!applyGraveEl.checked){
    phraseOutEl.textContent = txt;
    return;
  }
  const { out, changes } = lowerFinalAcuteInPhrase(txt);
  if(showDiffEl.checked){
    phraseOutEl.innerHTML = renderWithDiff(txt, out, changes);
  } else {
    phraseOutEl.textContent = out;
  }
}

phraseEl.addEventListener('input', updatePhrase);
applyGraveEl.addEventListener('change', updatePhrase);
showDiffEl.addEventListener('change', updatePhrase);

$('#resetPhrase').addEventListener('click', ()=>{ phraseEl.value = defaultPhrase; updatePhrase(); });
$('#copyPhrase').addEventListener('click', async ()=>{
  const txt = applyGraveEl.checked ? lowerFinalAcuteInPhrase(phraseEl.value).out : phraseEl.value;
  try{ await navigator.clipboard.writeText(txt); }
  catch{ /* ignore */ }
});

// Contraction UI
const contractInEl = $('#contractIn');
const modeEl = $('#mode');
const contractOutEl = $('#contractOut');
const contractNoteEl = $('#contractNote');

function doContract(){
  const { out, note } = applyContraction(contractInEl.value, modeEl.value);
  contractOutEl.textContent = out;
  contractNoteEl.textContent = note;
}

$('#doContract').addEventListener('click', doContract);
$('#copyContract').addEventListener('click', async ()=>{
  try{ await navigator.clipboard.writeText(contractOutEl.textContent || ''); }
  catch{ /* ignore */ }
});
$('#clearContract').addEventListener('click', ()=>{
  contractInEl.value='';
  contractOutEl.textContent='';
  contractNoteEl.textContent='';
});

$$('.pill').forEach(p=>p.addEventListener('click', ()=>{
  contractInEl.value = p.getAttribute('data-sample');
  doContract();
}));

// init
updatePhrase();
doContract();

