  --muted:#b8bde6;
  --line:#2a2f52;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --good:#34d399;
  --warn:#fbbf24;
  --bad:#fb7185;
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 600px at 20% 0%, #1b1f3a 0%, var(--bg) 55%); color:var(--ink); font:16px/1.45 system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;}
.wrap{max-width:980px;margin:0 auto;padding:22px 16px 40px;}
.hdr h1{margin:0 0 6px;font-size:22px;letter-spacing:.2px}
