.inp:focus{border-color:rgba(125,211,252,.8); box-shadow:0 0 0 3px rgba(125,211,252,.15)}
.btn{padding:10px 12px;border-radius:10px;border:1px solid var(--line);background:#10142a;color:var(--ink);cursor:pointer}
