.btn.primary{background:linear-gradient(180deg, rgba(125,211,252,.25), rgba(167,139,250,.18)); border-color:rgba(125,211,252,.35)}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}
@media (max-width:860px){.grid{grid-template-columns:1fr}}
.pane{padding:12px;border:1px solid var(--line);border-radius:12px;background:rgba(0,0,0,.18)}
.pane h3{margin:0 0 8px;font-size:14px;color:var(--muted)}
.out{padding:10px 12px;border-radius:10px;border:1px dashed rgba(125,211,252,.35);background:rgba(12,15,29,.7);font-family:var(--mono);min-height:42px;display:flex;align-items:center}
.hint{margin:8px 0 0;color:var(--muted);font-size:13px}
.gk{font-family:var(--mono);color:var(--accent)}
.mini{margin-top:10px;display:flex;gap:14px;flex-wrap:wrap}
.chk{color:var(--muted);font-size:13px;display:flex;gap:8px;align-items:center}
.explain{margin-top:10px;color:var(--muted);font-size:13px;border-left:3px solid rgba(125,211,252,.35);padding-left:10px}
.sel{padding:10px 12px;border-radius:10px;border:1px solid var(--line);background:#0c0f1d;color:var(--ink)}
.syll{margin-top:10px;display:flex;flex-wrap:wrap;gap:8px}
.chip{padding:8px 10px;border-radius:999px;border:1px solid var(--line);background:#0c0f1d;color:var(--ink);cursor:pointer;font-family:var(--mono)}
.chip:hover{border-color:rgba(125,211,252,.7)}
.chip small{color:var(--muted);font-family:system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;margin-left:6px}
