const $ = (sel) => document.querySelector(sel);

const demoInputs = [
  "Δημοσθένὲὸς",
  "Δημοσθένὲὸς",
  "χρύσὲὸς",
  "ἀργύρὲὸς",
  "χρυσεος",
  "αργυρεος"
];
let demoIdx = 0;

function normalizeGreek(s){
  // Keep it simple: normalize to NFC so combining marks behave.
  return (s || "").normalize("NFC");
}

function contractEosToOus(s){
  // Toy contraction rules:
  // - accept sequences: "έὸς" (epsilon+acute + omicron+smooth?) as in the passage’s spelling
  // - accept "έος" and plain "εος"
  // - also accept with diaeresis/odd punctuation by stripping a few separators.
  let t = normalizeGreek(s);

  // Remove a few common separators that appear in the quoted examples (like ὲὸ with odd marks)
  // but do NOT remove accents globally.
  t = t.replace(/[··•]/g, "");

  // Specific passage-like sequence: epsilon with acute + omicron with grave? (έὸς)
  // We just match the literal substring if present.
  t = t.replace(/έὸς/g, "ους");
  t = t.replace(/έος/g, "ους");
  t = t.replace(/εος/g, "ους");

  // Also handle capital epsilon
  t = t.replace(/Έος/g, "Ους");
  t = t.replace(/Εος/g, "Ους");

  return t;
}

function applyCircumflexOnFinalOus(word){
  // If word ends in -ους (or -Ους), put circumflex on the upsilon: οῦς / Οῦς.
  // This is a toy: real accentuation depends on quantity and morphology.
  let w = normalizeGreek(word);

  // If already has a circumflex on upsilon in final -οῦς, keep it.
  if (/οῦς$/u.test(w) || /Οῦς$/u.test(w)) return w;

  // If ends with -ους, replace last occurrence.
  w = w.replace(/ους$/u, "οῦς");
  w = w.replace(/Ους$/u, "Οῦς");
  return w;
}

function hasFinalOus(word){
  const w = normalizeGreek(word);
  return /ους$/u.test(w) || /οῦς$/u.test(w) || /Ους$/u.test(w) || /Οῦς$/u.test(w);
}

function render(){
  const raw = normalizeGreek($("#inp").value);
  const contracted = contractEosToOus(raw);
  $("#outContract").textContent = contracted || "(type something above)";

  const doCirc = $("#chkCirc").checked;
  let accented = contracted;
  if (doCirc) accented = applyCircumflexOnFinalOus(accented);
  $("#outAccent").textContent = accented || "";

  const showExplain = $("#chkExplain").checked;
  const ex = $("#explain");
  if (!showExplain){
    ex.textContent = "";
    return;
  }

  const notes = [];
  if (raw !== contracted){
    notes.push(`Contraction applied: “-εος / -έὸς” → “-ους”.`);
  } else {
    notes.push("No contraction pattern found (this toy only knows a few). Try χρύσὲὸς or Δημοσθένὲὸς.");
  }

  if (hasFinalOus(contracted)){
    if (doCirc){
      notes.push("Accent toy rule: final -ους → οῦς (circumflex on ου). This imitates the passage’s claim about simple -ους forms.");
    } else {
      notes.push("Final -ους detected, but circumflex step is turned off.");
    }
  } else {
    notes.push("No final -ους detected after contraction, so the circumflex rule has nothing to target.");
  }

  ex.textContent = notes.join(" ");
}

$("#btnGo").addEventListener("click", render);
$("#inp").addEventListener("input", render);
$("#chkCirc").addEventListener("change", render);
$("#chkExplain").addEventListener("change", render);

$("#btnDemo").addEventListener("click", () => {
  demoIdx = (demoIdx + 1) % demoInputs.length;
  $("#inp").value = demoInputs[demoIdx];
  render();
});

// --- Accent sandbox ---

function stripGreekAccents(s){
  // Remove Greek tonos/oxia, varia, perispomeni and their precomposed variants by NFD filtering.
  const nfd = normalizeGreek(s).normalize("NFD");
  // Combining marks to remove: tonos/oxia (U+0301), varia (U+0300), perispomeni (U+0342), dialytika (U+0308)
  // We keep breathing marks? For simplicity, remove most combining marks in Greek range.
  const cleaned = nfd.replace(/[\u0300-\u036f]/g, "");
  return cleaned.normalize("NFC");
}

function isGreekVowel(ch){
  return /[αεηιουωΑΕΗΙΟΥΩ]/u.test(ch);
}

function splitByVowelNuclei(word){
  // Very simple: find indices of vowels (including diphthongs ου, ει, αι, αυ, ευ, ηυ, οι, υι).
  const w = normalizeGreek(word);
  const nuclei = [];
  const pairs = new Set(["αι","ει","οι","υι","αυ","ευ","ηυ","ου","Αι","Ει","Οι","Υι","Αυ","Ευ","Ηυ","Ου"]);

  let i = 0;
  while (i < w.length){
    const a = w[i];
    const b = w[i+1];
    if (b && pairs.has(a+b)){
      nuclei.push({start:i, len:2, text:a+b});
      i += 2;
      continue;
    }
    if (isGreekVowel(a)){
      nuclei.push({start:i, len:1, text:a});
    }
    i += 1;
  }
  return nuclei;
}

function addAccentToNucleus(word, nucleusIndex, type){
  // Add accent to the first vowel of the nucleus (or upsilon in ου for circumflex preference).
  let w = stripGreekAccents(word);
  const nuclei = splitByVowelNuclei(w);
  if (!nuclei[nucleusIndex]) return w;

  const n = nuclei[nucleusIndex];
  let pos = n.start;

  // If nucleus is ου and type is circ, accent upsilon looks nicer: οῦ.
  if (n.len === 2 && w.slice(n.start, n.start+2) === "ου" && type === "circ"){
    pos = n.start + 1;
  }

  const ch = w[pos];
  const map = {
    acute: {
      "α":"ά","ε":"έ","η":"ή","ι":"ί","ο":"ό","υ":"ύ","ω":"ώ",
      "Α":"Ά","Ε":"Έ","Η":"Ή","Ι":"Ί","Ο":"Ό","Υ":"Ύ","Ω":"Ώ"
    },
    grave: {
      "α":"ὰ","ε":"ὲ","η":"ὴ","ι":"ὶ","ο":"ὸ","υ":"ὺ","ω":"ὼ",
      "Α":"Ὰ","Ε":"Ὲ","Η":"Ὴ","Ι":"Ὶ","Ο":"Ὸ","Υ":"Ὺ","Ω":"Ὼ"
    },
    circ: {
      "α":"ᾶ","ε":"έ","η":"ῆ","ι":"ῖ","ο":"ό","υ":"ῦ","ω":"ῶ",
      "Α":"ᾶ","Ε":"Έ","Η":"ῆ","Ι":"ῖ","Ο":"Ό","Υ":"ῦ","Ω":"ῶ"
    }
  };

  const repl = (map[type] && map[type][ch]) ? map[type][ch] : ch;
  w = w.slice(0,pos) + repl + w.slice(pos+1);
  return w;
}

function renderSandbox(){
  const w = normalizeGreek($("#inp2").value);
  const nuclei = splitByVowelNuclei(stripGreekAccents(w));
  const box = $("#syll");
  box.innerHTML = "";

  if (!w){
    $("#out2").textContent = "";
    return;
  }

  if (nuclei.length === 0){
    $("#out2").textContent = stripGreekAccents(w);
    const span = document.createElement("div");
    span.className = "explain";
    span.textContent = "No vowel nuclei detected (are you using Greek letters?).";
    box.appendChild(span);
    return;
  }

  nuclei.forEach((n, idx) => {
    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = "chip";
    chip.textContent = n.text;
    const sm = document.createElement("small");
    sm.textContent = `#${idx+1}`;
    chip.appendChild(sm);
    chip.addEventListener("click", () => {
      const type = $("#accentType").value;
      const newW = addAccentToNucleus($("#inp2").value, idx, type);
      $("#inp2").value = newW;
      $("#out2").textContent = newW;
      renderSandbox();
    });
    box.appendChild(chip);
  });

  $("#out2").textContent = w;
}

$("#btnSplit").addEventListener("click", renderSandbox);
$("#inp2").addEventListener("input", () => {
  $("#out2").textContent = $("#inp2").value;
});
$("#btnClear").addEventListener("click", () => {
  $("#inp2").value = stripGreekAccents($("#inp2").value);
  renderSandbox();
});

// initial
render();
renderSandbox();

