(() => {
  const $ = (sel) => document.querySelector(sel);
  const inp = $('#inp');
  const outCluster = $('#outCluster');
  const outStem = $('#outStem');
  const outAccent = $('#outAccent');
  const outDerive = $('#outDerive');
  const base = $('#base');
  const recipe = $('#recipe');
  const chkOx = $('#chkOx');
  const chkBar = $('#chkBar');

  const examples = [
    'Παιάν','Ἰάν','Λυκάν','Ἀζάν','ἰδμάν','μεγιστάν','Πορθάν','Πελλάν','Ἀλκμάν',
    'εὐπαίαν','Αἰγίπαν','Ἑρμόπαν','Ἀντίπαν','Εὐήπαν','Τιτανόπαν','Αἰνοτίταν','καρβάν',
    'Αἰνιάν','Ἀκαρνάν','Ἀρκτάν','Ἀτιντάν','Βραχμάν','Γινδάν','Δυμάν','Εὐρυτάν','Φαράν','Ἀρετάν'
  ];

  function stripDiacritics(s){
    // Remove combining marks (accents/breathings/diacritics) but keep base Greek letters.
    return (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  }

  function normalizeRough(s){
    // Lowercase, strip diacritics, normalize final sigma.
    let t = stripDiacritics((s||'').trim());
    t = t.replace(/ς/g,'σ');
    return t.toLowerCase();
  }

  function endsWithAn(word){
    const t = normalizeRough(word);
    return t.endsWith('αν');
  }

  function isGreekLetter(ch){
    return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(ch);
  }

  function isVowel(ch){
    const c = normalizeRough(ch);
    return ['α','ε','η','ι','ο','υ','ω'].includes(c);
  }

  function consonantCountBeforeAlpha(word){
    // Count consecutive consonant letters immediately before the alpha of final -αν.
    const raw = (word||'').trim();
    const t = stripDiacritics(raw).replace(/ς/g,'σ');
    // Find last occurrence of "αν" at end (in stripped form)
    const tLower = t.toLowerCase();
    if(!tLower.endsWith('αν')) return null;
    const idxAlpha = tLower.length - 2; // position of alpha in final -αν
    let i = idxAlpha - 1;
    let count = 0;
    while(i >= 0){
      const ch = tLower[i];
      if(!isGreekLetter(ch)) break;
      if(isVowel(ch)) break;
      // treat ρ, λ, μ, ν, etc. as consonants (fine)
      count++;
      i--;
    }
    return {count, cluster: tLower.slice(i+1, idxAlpha)};
  }

  function analyze(){
    const w = inp.value.trim();
    if(!w){
      outCluster.textContent = 'Type a word first.';
      outStem.textContent = '';
      outAccent.textContent = '';
      return;
    }

    const t = normalizeRough(w);
    const hasAn = t.endsWith('αν');

    if(!hasAn){
      outCluster.innerHTML = `Not ending in <span class="gr">-αν</span> (after rough normalization).\nTry e.g. <span class="gr">Λυκάν</span>, <span class="gr">Παιάν</span>, <span class="gr">Ἀλκμάν</span>.`;
      return;
    }

    const info = consonantCountBeforeAlpha(w);
    const c = info ? info.count : null;
    const cluster = info ? info.cluster : '';

    let verdict = '';
    if(c === 0) verdict = `<span class="good">0 consonants</span> before α ("pure" type): like <span class="gr">Παιάν</span>, <span class="gr">Ἰάν</span>.`;
    else if(c === 1) verdict = `<span class="good">1 consonant</span> before α: like <span class="gr">Λυκάν</span>, <span class="gr">Ἀζάν</span>.`;
    else if(c === 2) verdict = `<span class="good">2 consonants</span> before α: like <span class="gr">ἰδμάν</span>, <span class="gr">μεγιστάν</span>, <span class="gr">Πορθάν</span>, <span class="gr">Πελλάν</span>.`;
    else if(c === 3) verdict = `<span class="bad">3 consonants</span> before α — Herodian says this is exceptional; he notes <span class="gr">Ἀλκμάν</span>.`;
    else verdict = `<span class="bad">${c} consonants</span> before α — beyond the usual pattern in the passage.`;

    outCluster.innerHTML = `Input: <span class="gr">${escapeHtml(w)}</span>\nRough: <span class="gr">${escapeHtml(t)}</span>\nBefore the final <span class="gr">-αν</span>, consonant cluster = <span class="gr">${escapeHtml(cluster || '∅')}</span> (count: ${c}).\n${verdict}`;
  }

  function escapeHtml(s){
    return (s+'').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  function removeFinalAn(word){
    const raw = (word||'').trim();
    const stripped = stripDiacritics(raw).replace(/ς/g,'σ');
    if(!stripped.toLowerCase().endsWith('αν')) return null;
    // remove last 2 chars from original string in a naive way:
    // better: remove from stripped mapping is hard; so do it on stripped and show as "stem-ish".
    const stem = stripped.slice(0, -2);
    return stem;
  }

  function showStem(){
    const w = inp.value.trim();
    if(!w){ outStem.textContent = ''; return; }
    const stem = removeFinalAn(w);
    if(stem == null){
      outStem.textContent = 'No final -αν detected (after stripping diacritics).';
      return;
    }
    const info = consonantCountBeforeAlpha(w);
    const cluster = info ? info.cluster : '';
    outStem.textContent = `Stem-ish (diacritics stripped): ${stem}\nCluster before α was: ${cluster || '∅'}`;
  }

  function clearAccents(s){
    return stripDiacritics(s||'');
  }

  function addAcuteToLastVowel(s){
    // Add combining acute to the last vowel letter.
    const base = clearAccents(s).normalize('NFD');
    const chars = Array.from(base);
    for(let i=chars.length-1;i>=0;i--){
      const ch = chars[i];
      if(isVowel(ch)){
        chars[i] = ch + '\u0301';
        return chars.join('').normalize('NFC');
      }
    }
    return s;
  }

  function addAcuteToPenultVowel(s){
    // Add acute to the penultimate vowel (counting from end).
    const base = clearAccents(s).normalize('NFD');
    const chars = Array.from(base);
    let seen = 0;
    for(let i=chars.length-1;i>=0;i--){
      const ch = chars[i];
      if(isVowel(ch)){
        seen++;
        if(seen === 2){
          chars[i] = ch + '\u0301';
          return chars.join('').normalize('NFC');
        }
      }
    }
    // fallback: last vowel
    return addAcuteToLastVowel(s);
  }

  function suggestAccent(){
    const w0 = inp.value.trim();
    if(!w0){ outAccent.textContent = 'Type a word first.'; return; }
    const w = clearAccents(w0);

    const forceOx = chkOx.checked;
    const preferBar = chkBar.checked;

    let suggestion = w;
    if(forceOx){
      suggestion = addAcuteToLastVowel(w);
    } else if(preferBar){
      suggestion = addAcuteToPenultVowel(w);
    } else {
      suggestion = addAcuteToLastVowel(w);
    }

    const note = forceOx
      ? 'Oxytone mode: accent on the last vowel (toy).'
      : (preferBar ? 'Barytone mode: avoid the last vowel if possible (toy).' : 'Default: last vowel (toy).');

    outAccent.textContent = `Input (accents cleared): ${w}\nSuggestion: ${suggestion}\n${note}`;
  }

  function clearAccentOutput(){
    const w0 = inp.value.trim();
    if(!w0){ outAccent.textContent = ''; return; }
    outAccent.textContent = `Accents cleared: ${clearAccents(w0)}`;
  }

  function derive(){
    const b0 = base.value.trim();
    if(!b0){ outDerive.textContent = 'Type a base first.'; return; }
    const b = clearAccents(b0);
    const r = recipe.value;

    let steps = [];
    let result = '';

    if(r === 'superlative'){
      // toy: replace ιστος/ιστον with ισταν
      const t = normalizeRough(b);
      if(t.endsWith('ιστος') || t.endsWith('ιστον')){
        result = b.replace(/ιστ(ος|ον)$/i,'ιστάν');
        steps.push(`${b} → ${result}`);
      } else {
        result = b + 'τάν';
        steps.push(`(toy) ${b} + τάν → ${result}`);
      }
    }

    if(r === 'neos'){
      // toy: if ends with εος/ος, make εαν/αν
      const t = normalizeRough(b);
      if(t === 'νεος' || t === 'νέος'){
        result = 'νεάν';
        steps.push('νέος → νεάν');
      } else if(t.endsWith('ος')){
        result = b.slice(0,-1) + 'άν';
        steps.push(`(toy) ${b} → ${result}`);
      } else {
        result = b + 'άν';
        steps.push(`(toy) ${b} + άν → ${result}`);
      }
    }

    if(r === 'alkimos'){
      // toy: -ιμος → -ιμάν, then syncope: drop ι (and maybe a vowel) to get -μάν
      const t = normalizeRough(b);
      if(t.endsWith('ιμος')){
        const step1 = b.replace(/ιμος$/i,'ιμάν');
        // syncope: remove the iota before μάν if present
        const step2 = step1.replace(/ιμάν$/i,'μάν');
        result = step2;
        steps.push(`${b} → ${step1} → ${step2}`);
      } else {
        const step1 = b + 'ιμάν';
        const step2 = step1.replace(/ιμάν$/i,'μάν');
        result = step2;
        steps.push(`(toy) ${b} → ${step1} → ${step2}`);
      }
    }

    if(r === 'ethnic'){
      // toy: place-name → -ιος, then -ιάν
      // If ends with -ια, make -ιος; else just append.
      const t = normalizeRough(b);
      let step1 = '';
      if(t.endsWith('ια')){
        step1 = b.slice(0,-1) + 'ος'; // -ια → -ιος (very rough)
        steps.push(`${b} → ${step1} (toy: -ια → -ιος)`);
      } else {
        step1 = b + 'ιος';
        steps.push(`${b} → ${step1} (toy: +ιος)`);
      }
      const step2 = step1.replace(/ιος$/i,'ιάν');
      result = step2;
      steps.push(`${step1} → ${step2} (toy: distinction → -ιάν)`);
    }

    // Analyze result for fun
    const info = consonantCountBeforeAlpha(result);
    let extra = '';
    if(info){
      extra = `\n\nCheck: ${result} has ${info.count} consonant(s) before α in -αν (cluster: ${info.cluster || '∅'}).`;
    }

    outDerive.textContent = steps.join('\n') + `\nResult: ${result}` + extra;
  }

  function randomExample(){
    const w = examples[Math.floor(Math.random()*examples.length)];
    inp.value = w;
    analyze();
  }

  function buildChips(){
    const box = $('#chips');
    box.innerHTML = '';
    examples.forEach(w => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'chip';
      b.textContent = w;
      b.addEventListener('click', () => { inp.value = w; analyze(); });
      box.appendChild(b);
    });
  }

  // Wire up
  $('#btnAnalyze').addEventListener('click', analyze);
  inp.addEventListener('keydown', (e) => { if(e.key === 'Enter') analyze(); });
  $('#btnRandom').addEventListener('click', randomExample);
  $('#btnStrip').addEventListener('click', showStem);
  $('#btnNormalize').addEventListener('click', () => {
    const w = inp.value.trim();
    if(!w) return;
    inp.value = normalizeRough(w);
    analyze();
  });
  $('#btnAccent').addEventListener('click', suggestAccent);
  $('#btnClearAccent').addEventListener('click', clearAccentOutput);
  $('#btnDerive').addEventListener('click', derive);
  $('#btnSwap').addEventListener('click', () => { base.value = inp.value.trim(); });

  // Mutually exclusive-ish checkboxes
  chkOx.addEventListener('change', () => { if(chkOx.checked) chkBar.checked = false; });
  chkBar.addEventListener('change', () => { if(chkBar.checked) chkOx.checked = false; });

  buildChips();
  inp.value = 'Ἀλκμάν';
  analyze();
})();

