.modes label{margin:0;font-size:13px;color:var(--text)}
.hint{margin:8px 0 0;color:var(--muted);font-size:12px}
.btns{display:flex;flex-wrap:wrap;gap:8px}
button{border:1px solid var(--line);background:#0c0f1f;color:var(--text);padding:9px 12px;border-radius:12px;cursor:pointer}
button:hover{border-color:rgba(167,139,250,.7)}
button:active{transform:translateY(1px)}
button.go{background:linear-gradient(90deg, rgba(125,211,252,.18), rgba(167,139,250,.18));border-color:rgba(125,211,252,.35)}
button.ghost{background:transparent}
button.ex{padding:7px 10px;font-size:13px}
.tog{margin-top:10px}
.chk{display:flex;gap:8px;align-items:center;color:var(--muted);font-size:13px;margin:0}
.out h2{margin:0 0 10px;font-size:14px}
.outbox{border:1px dashed rgba(125,211,252,.35);border-radius:12px;padding:12px;min-height:92px;background:rgba(0,0,0,.18)}
.kv{display:grid;grid-template-columns:160px 1fr;gap:8px 12px;align-items:start}
@media (max-width:560px){.kv{grid-template-columns:1fr}}
.key{color:var(--muted);font-size:12px}
.val{font-size:16px}
.badge{display:inline-block;padding:2px 8px;border-radius:999px;border:1px solid var(--line);font-size:12px;margin-left:8px;color:var(--muted)}
.badge.good{border-color:rgba(52,211,153,.5);color:var(--good)}
.badge.warn{border-color:rgba(251,191,36,.55);color:var(--warn)}
.badge.bad{border-color:rgba(251,113,133,.55);color:var(--bad)}
.mono{font-family:var(--mono)}
.notes{margin-top:10px;color:var(--muted)}
.notes summary{cursor:pointer}
