const $ = (s, el=document) => el.querySelector(s);
const $$ = (s, el=document) => Array.from(el.querySelectorAll(s));

const inp = $('#inp');
const out = $('#out');
const strip = $('#strip');

const combiningMarks = /[\u0300-\u036f\u1ab0-\u1aff\u1dc0-\u1dff\u20d0-\u20ff\ufe20-\ufe2f]/g;

function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripDiacritics(s){
  // Remove combining marks; keep base Greek letters.
  return nfc(nfd(s).replace(combiningMarks,''));
}

function normalizeGreek(s){
  let t = (s||'').trim();
  t = t.replace(/\s+/g,' ');
  return t;
}

function endsWithAny(w, arr){
  return arr.some(x => w.endsWith(x));
}

function countVowels(word){
  const w = stripDiacritics(word).toLowerCase();
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω']);
  let c=0;
  for(const ch of w){ if(vowels.has(ch)) c++; }
  return c;
}

function lastVowelIndex(word){
  const w = nfd(word);
  const base = stripDiacritics(word);
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
  // Find last vowel position in NFC string (approx):
  for(let i=base.length-1;i>=0;i--){
    if(vowels.has(base[i])) return i;
  }
  return -1;
}

function addAcuteOnLastVowel(word){
  // Add combining acute (\u0301) after the last vowel base letter.
  const acute = '\u0301';
  const decomposed = nfd(word);
  // Work on stripped base to locate last vowel in base string, then map to decomposed indices.
  const base = stripDiacritics(word);
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
  let baseIdx=-1;
  for(let i=base.length-1;i>=0;i--){ if(vowels.has(base[i])) { baseIdx=i; break; } }
  if(baseIdx<0) return word;

  // Build mapping from base index to decomposed index by scanning decomposed and counting base letters.
  let bCount=-1;
  let insertAt = decomposed.length;
  for(let i=0;i<decomposed.length;i++){
    const ch = decomposed[i];
    // base letters are those that are not combining marks
    if(!combiningMarks.test(ch)){
      bCount++;
      if(bCount===baseIdx){
        // insert after this base letter and any existing combining marks following it
        insertAt = i+1;
        while(insertAt<decomposed.length && combiningMarks.test(decomposed[insertAt])) insertAt++;
        break;
      }
    }
  }
  const withAcute = decomposed.slice(0, insertAt) + acute + decomposed.slice(insertAt);
  return nfc(withAcute);
}

function badge(text, cls){
  return `<span class="badge ${cls}">${escapeHtml(text)}</span>`;
}

function escapeHtml(s){
  return (s+'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function getMode(){
  return ($('input[name=mode]:checked')||{}).value || 'accent';
}

function renderKV(rows){
  return `<div class="kv">${rows.map(r=>`<div class="key">${escapeHtml(r.k)}</div><div class="val">${r.v}</div>`).join('')}</div>`;
}

function accentGuesser(wordRaw){
  const original = wordRaw;
  const w0 = normalizeGreek(original);
  if(!w0) return {html:`<div class="small">Type a Greek word above.</div>`};

  const w = strip.checked ? stripDiacritics(w0) : w0;
  const wStripped = stripDiacritics(w0);

  let notes = [];
  let status = 'warn';

  // Rule: -αν words not with penult ει (toy check: contains "ει" before final αν)
  if(wStripped.endsWith('αν') || wStripped.endsWith('άν') || wStripped.endsWith('Αν') || wStripped.endsWith('άν')){
    const base = wStripped;
    const hasEian = base.includes('ειαν') || base.includes('ειάν') || base.includes('Ειαν') || base.includes('ειαν');
    if(hasEian){
      if(base.includes('Αργειαν') || base.includes('Ἀργειαν') || base.includes('Αργειάν') || base.includes('Ἀργειάν')){
        notes.push(`${badge('exception', 'good')} Looks like <span class="mono">Ἀργειάν</span>-type: diphthong from <span class="mono">Ἀργεῖος</span> (allowed).`);
        status='good';
      } else {
        notes.push(`${badge('warning', 'warn')} Ends in <span class="mono">-αν</span> but contains <span class="mono">ειαν</span>. Herodian says <span class="mono">-αν</span> words normally don’t have penult <span class="mono">ει</span>.`);
      }
    } else {
      notes.push(`${badge('ok', 'good')} Ends in <span class="mono">-αν</span>. Toy expects no penult <span class="mono">ει</span> (e.g. <span class="mono">Ἀλκμάν</span>, <span class="mono">Παιάν</span>).`);
      status='good';
    }
  }

  // Rule: -ην acute tendency (toy: suggest acute on last vowel)
  if(endsWithAny(wStripped, ['ην','ήν','Ην','Ήν'])){
    const vcount = countVowels(wStripped);
    const disyll = (vcount===2);
    const hasAlphaBeforeLast = /α[αεηιουω]?ην$/i.test(wStripped);

    let suggestion = addAcuteOnLastVowel(w);
    let msg = `${badge('rule', 'good')} Ends in <span class="mono">-ην</span>. Toy suggests <b>acute on the last syllable</b>: <span class="mono">${escapeHtml(suggestion)}</span>.`;
    if(disyll) msg += ` (Looks disyllabic.)`;
    if(hasAlphaBeforeLast) msg += ` Pre-final syllable has <span class="mono">α</span>, matching the passage’s later note.`;
    notes.push(msg);
    status='good';
  }

  if(notes.length===0){
    notes.push(`${badge('info','warn')} No specific rule triggered. Try something ending in <span class="mono">-αν</span>, <span class="mono">-ην</span>, or <span class="mono">-εύς</span>.`);
  }

  const rows = [
    {k:'Input', v:`<span class="mono">${escapeHtml(w0)}</span>`},
    {k:'Working form', v:`<span class="mono">${escapeHtml(w)}</span> ${badge(strip.checked?'stripped':'as-is', strip.checked?'warn':'good')}`},
    {k:'Notes', v:`<div>${notes.join('<br>')}</div>`}
  ];

  return {html: renderKV(rows)};
}

function doricConverter(wordRaw){
  const w0 = normalizeGreek(wordRaw);
  if(!w0) return {html:`<div class="small">Type a Greek word above.</div>`};
  const w = strip.checked ? stripDiacritics(w0) : w0;
  const base = stripDiacritics(w);

  let conv = null;
  let voc = null;
  let note = '';

  if(endsWithAny(base, ['ευς','Ευς','εύς','Εύς'])){
    // Replace final ευς with ης
    conv = w.replace(/ευς$/,'ης').replace(/Ευς$/,'ΗΣ').replace(/εύς$/,'ῆς').replace(/Εύς$/,'ῆς');
    // crude vocative: -ης -> -η
    voc = stripDiacritics(conv).replace(/ης$/,'η').replace(/ΗΣ$/,'Η');
    note = `${badge('Doric-ish','good')} Passage mentions <span class="mono">-εύς</span> sometimes becoming long <span class="mono">-ης</span> (e.g. Ἀχιλλεύς → Ἀχιλλῆς).`;
  } else if(endsWithAny(base, ['ης','ῆς','ΗΣ'])){
    conv = w;
    voc = stripDiacritics(w).replace(/ης$/,'η').replace(/ΗΣ$/,'Η');
    note = `${badge('info','warn')} Already looks like <span class="mono">-ης</span>. Toy can still show a vocative-like <span class="mono">-η</span> (cf. Τύδη).`;
  } else {
    note = `${badge('hint','warn')} Try a word ending in <span class="mono">-εύς</span> (e.g. Ὀρφεύς, Ἀχιλλεύς, Τυδεύς).`;
  }

  const rows = [
    {k:'Input', v:`<span class="mono">${escapeHtml(w0)}</span>`},
    {k:'-εύς → -ης', v: conv ? `<span class="mono">${escapeHtml(conv)}</span>` : `<span class="small">(no conversion)</span>`},
    {k:'Vocative-ish (-η)', v: voc ? `<span class="mono">${escapeHtml(voc)}</span>` : `<span class="small">(n/a)</span>`},
    {k:'Note', v: note}
  ];
  return {html: renderKV(rows)};
}

function pleonasmToy(wordRaw){
  const w0 = normalizeGreek(wordRaw);
  if(!w0) return {html:`<div class="small">Type a Greek name (or anything) above, then pick a base below.</div>`};
  const w = strip.checked ? stripDiacritics(w0) : w0;

  const baseChoices = [
    {id:'akme', label:'from ἀκμή (add λ)', add:'λ', expl:"If from ἀκμή, Herodian says the name shows added ‘λ’."},
    {id:'alke', label:'from ἀλκή (add μ)', add:'μ', expl:"If from ἀλκή, added ‘μ’."},
    {id:'alkimos', label:'from ἄλκιμος (syncope demo)', add:null, expl:"If from ἄλκιμος, it arose by syncope (toy removes a middle vowel)."}
  ];

  // Determine choice from a tiny inline selector rendered each time.
  const chosen = $('input[name=pleo]:checked');
  const choice = baseChoices.find(x=>x.id === (chosen?chosen.value:'akme')) || baseChoices[0];

  let result = '';
  if(choice.add){
    // Add consonant after initial alpha if present, else prefix.
    const s = stripDiacritics(w);
    if(s.length>0){
      const first = s[0];
      if(first==='α' || first==='Α' || first==='Ἀ' || first==='ἀ'){
        result = first + choice.add + s.slice(1);
      } else {
        result = choice.add + s;
      }
    } else result = choice.add;
  } else {
    // Syncope demo: remove the first internal vowel after the first character.
    const s = stripDiacritics(w);
    const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
    let removed=false;
    let outS='';
    for(let i=0;i<s.length;i++){
      const ch=s[i];
      if(i>0 && !removed && vowels.has(ch)) { removed=true; continue; }
      outS+=ch;
    }
    result = outS;
  }

  const selector = `
    <div class="small" style="margin-bottom:8px">Choose an etymology-path (toy):</div>
    <div class="modes" role="group" aria-label="Pleonasm choice">
      ${baseChoices.map(x=>`<label><input type="radio" name="pleo" value="${x.id}" ${x.id===choice.id?'checked':''}> ${escapeHtml(x.label)}</label>`).join('')}
    </div>
    <div class="small" style="margin-top:8px">${escapeHtml(choice.expl)}</div>
    <hr>
  `;

  const rows = [
    {k:'Input', v:`<span class="mono">${escapeHtml(w0)}</span>`},
    {k:'Toy output', v:`<span class="mono">${escapeHtml(result)}</span> ${badge(choice.add?'pleonasm':'syncope','warn')}`},
    {k:'Why', v:`<div>${selector}</div>`}
  ];

  return {html: renderKV(rows)};
}

function run(){
  const mode = getMode();
  const w = inp.value;
  let res;
  if(mode==='accent') res = accentGuesser(w);
  else if(mode==='doric') res = doricConverter(w);
  else res = pleonasmToy(w);
  out.innerHTML = res.html;
}

$('#go').addEventListener('click', run);
$('#clear').addEventListener('click', () => { inp.value=''; out.innerHTML=''; inp.focus(); });

inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') run(); });
$$('button.ex').forEach(b=>b.addEventListener('click', ()=>{ inp.value=b.dataset.v; run(); }));
$$('input[name=mode]').forEach(r=>r.addEventListener('change', run));
strip.addEventListener('change', run);

// Initial render
out.innerHTML = `<div class="small">Instructions: type a Greek word, pick a mode, and click <b>Run</b>. Try the example buttons.</div>`;

