const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => Array.from(document.querySelectorAll(sel));

const inp = $('#inp');
const endingEl = $('#ending');
const ruleEl = $('#rule');
const reasonsEl = $('#reasons');
const asTypedEl = $('#asTyped');
const strippedEl = $('#stripped');
const oxytoneEl = $('#oxytone');
const debugEl = $('#debug');

// --- Greek helpers (toy-grade) ---
function stripDiacritics(s){
  // NFD splits base letters + combining marks; remove combining marks.
  return (s || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'')
    .normalize('NFC');
}

function normalizeGreek(s){
  return stripDiacritics(s).toLowerCase().replace(/\s+/g,'').trim();
}

function endsWithAny(s, arr){
  return arr.find(x => s.endsWith(x)) || null;
}

const consonants = new Set('βγδζθκλμνξπρστφχψ'.split(''));
function isConsonant(ch){ return consonants.has(ch); }

function lastIndexOfEtaBeforeFinalN(word){
  // For ...ην or ...λην, eta is penultimate char.
  const i = word.lastIndexOf('η');
  return i;
}

function makeFinalOxytone(original){
  // Replace final η (in ...ην / ...λην) with ή, preserving final ν.
  // If already has ή, keep.
  const s = original;
  const n = normalizeGreek(s);
  if(!(n.endsWith('ην') || n.endsWith('λην'))) return s;

  // Work on NFC string but locate last eta in the original by scanning from end.
  // Simpler: strip diacritics to map positions, then rebuild by replacing the last eta-like char.
  // We'll do a pragmatic approach: replace the last occurrence of 'η' or 'ή' (or eta with other diacritics) before final nu.

  // Find position of final nu in original (last char).
  const chars = Array.from(s);
  if(chars.length < 2) return s;

  // Find last nu (ν/Ν) at end ignoring trailing spaces.
  let end = chars.length - 1;
  while(end >= 0 && /\s/.test(chars[end])) end--;
  if(end < 1) return s;
  const last = chars[end];
  if(stripDiacritics(last).toLowerCase() !== 'ν') return s;

  // Find eta immediately before that (skipping combining marks attached to it).
  // We'll search backward for a base letter whose stripped form is η.
  for(let i=end-1;i>=0;i--){
    const base = chars[i];
    const stripped = stripDiacritics(base);
    if(stripped.toLowerCase() === 'η'){
      // Replace this single codepoint with ή (lower) or Ή (upper) depending on case.
      const isUpper = stripped === 'Η';
      chars[i] = isUpper ? 'Ή' : 'ή';
      return chars.join('');
    }
    // stop if we hit another letter (not combining mark) too far? We'll just continue.
  }
  return s;
}

function stripAccentsOnly(original){
  // Remove combining marks but keep spacing.
  return (original || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function analyze(){
  const raw = inp.value || '';
  const rawTrim = raw.trim();

  asTypedEl.textContent = rawTrim || '—';
  const stripped = stripAccentsOnly(rawTrim);
  strippedEl.textContent = stripped || '—';

  reasonsEl.innerHTML = '';
  debugEl.textContent = '—';

  if(!rawTrim){
    endingEl.textContent = '—';
    ruleEl.textContent = '—';
    oxytoneEl.textContent = '—';
    return;
  }

  const n = normalizeGreek(rawTrim);
  const ending = endsWithAny(n, ['λην','ην']);
  endingEl.textContent = ending ? `Ends in -${ending}` : 'Does not look like -ην / -λην';

  const exceptions = new Set(['ελλην','ἑλλην','ἕλλην']); // normalized will be ελλην
  const isHellen = (n === 'ελλην');

  let wantsAcute = false;
  const reasons = [];

  if(!ending){
    ruleEl.innerHTML = `<span class="warn">No rule applied</span> <span class="badge">try -ην / -λην</span>`;
    oxytoneEl.textContent = makeFinalOxytone(rawTrim); // harmless
    debugEl.textContent = JSON.stringify({normalized:n, ending:null}, null, 2);
    return;
  }

  // Special: -λην: Herodian says oxytone (toy: always wants acute)
  if(ending === 'λην'){
    wantsAcute = true;
    reasons.push('Ending -λην → oxytone (toy follows Herodian’s list: βαλλήν, Τελλήν, …).');
  }

  // For -ην: inspect pre-eta environment
  if(ending === 'ην'){
    const etaIndex = lastIndexOfEtaBeforeFinalN(n);
    const pre = etaIndex > 0 ? n[etaIndex-1] : '';
    const pre2 = etaIndex > 1 ? n[etaIndex-2] : '';

    // Condition A: sigma immediately before eta
    if(pre === 'σ'){
      wantsAcute = true;
      reasons.push('Has σ immediately before η (…σην) → oxytone tendency.');
    }

    // Condition B: doubled consonant right before eta (e.g. σσ, λλ, ρρ)
    if(pre && pre2 && pre === pre2 && isConsonant(pre)){
      wantsAcute = true;
      reasons.push(`Has doubled consonant before η (…${pre2}${pre}ην) → oxytone tendency.`);
    }

    // Condition C: two-consonant cluster before eta (…C C ην)
    if(pre && pre2 && isConsonant(pre) && isConsonant(pre2)){
      wantsAcute = true;
      reasons.push(`Has a two-consonant cluster before η (…${pre2}${pre}ην) → oxytone tendency.`);
    }

    // Condition D: Herodian’s “not preceded by ου diphthong” (toy check)
    // If immediately before the consonant(s) there is ου, we *weaken* the trigger.
    // This is very approximate.
    const pre3 = etaIndex > 2 ? n.slice(etaIndex-3, etaIndex-1) : '';
    const hasOuBefore = (pre3 === 'ου');
    if(hasOuBefore && wantsAcute){
      reasons.push('But toy notices ου right before the pre-η consonant(s); Herodian says this can block the acute. (Toy: marks as uncertain.)');
    }

    if(!wantsAcute){
      reasons.push('No σ / doubled consonant / 2-consonant cluster detected right before η (toy cannot justify oxytone from this rule).');
    }
  }

  // Exception: Ἕλλην
  if(isHellen){
    wantsAcute = false;
    reasons.push('Exception: Ἕλλην is noted as not oxytone (toy treats it as an override).');
  }

  // Render
  if(wantsAcute){
    ruleEl.innerHTML = `<span class="good">Likely oxytone</span> <span class="badge">accent on final</span>`;
  } else {
    ruleEl.innerHTML = `<span class="warn">Not predicted oxytone</span> <span class="badge">toy rule</span>`;
  }

  for(const r of reasons){
    const li = document.createElement('li');
    li.textContent = r;
    reasonsEl.appendChild(li);
  }

  const ox = wantsAcute ? makeFinalOxytone(rawTrim) : rawTrim;
  oxytoneEl.textContent = ox;

  // Debug transparency
  const n = normalizeGreek(rawTrim);
  const etaIndex = lastIndexOfEtaBeforeFinalN(n);
  const dbg = {
    input: rawTrim,
    normalized: n,
    ending,
    etaIndex,
    preEta: etaIndex>0 ? n[etaIndex-1] : null,
    pre2Eta: etaIndex>1 ? n[etaIndex-2] : null,
    pre3slice: etaIndex>2 ? n.slice(etaIndex-3, etaIndex-1) : null,
    exceptionHellen: isHellen,
    wantsAcute
  };
  debugEl.textContent = JSON.stringify(dbg, null, 2);
}

$('#btnAnalyze').addEventListener('click', analyze);
$('#btnClear').addEventListener('click', () => { inp.value=''; inp.focus(); analyze(); });
$('#btnMakeOx').addEventListener('click', () => {
  const v = inp.value.trim();
  if(!v) return;
  inp.value = makeFinalOxytone(v);
  analyze();
});
$('#btnStrip').addEventListener('click', () => {
  const v = inp.value;
  inp.value = stripAccentsOnly(v);
  analyze();
});

inp.addEventListener('keydown', (e) => {
  if(e.key === 'Enter') analyze();
});

$$('.chip').forEach(btn => {
  btn.addEventListener('click', () => {
    inp.value = btn.getAttribute('data-ex');
    analyze();
    inp.focus();
  });
});

// initial
analyze();

