const $ = (sel) => document.querySelector(sel);

// --- Utilities: basic Greek normalization/diacritics handling ---
// Strip combining marks (works for polytonic in NFC/NFD).
function stripDiacritics(s){
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function isGreekLetter(ch){
  return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(ch);
}

function cleanInput(s){
  return (s||'')
    .replace(/\s+/g,' ')
    .trim();
}

// --- Syllabification (rough, for play) ---
const vowels = new Set([
  'α','ε','η','ι','ο','υ','ω',
  'Α','Ε','Η','Ι','Ο','Υ','Ω'
]);

const diphthongs = [
  'αι','ει','οι','υι','αυ','ευ','ου','ηυ',
  'ΑΙ','ΕΙ','ΟΙ','ΥΙ','ΑΥ','ΕΥ','ΟΥ','ΗΥ',
  'Αι','Ει','Οι','Υι','Αυ','Ευ','Ου','Ηυ',
  'αι'.toUpperCase() // harmless
];

function isVowel(ch){ return vowels.has(ch); }

function nextVowelUnit(word, i){
  // returns {unit, len} for vowel nucleus starting at i, else null
  const a = word[i] || '';
  const b = word[i+1] || '';
  const pair = a + b;
  if (diphthongs.includes(pair)) return {unit: pair, len: 2};
  if (isVowel(a)) return {unit: a, len: 1};
  return null;
}

function syllabifyRough(word){
  // Very approximate: split after each vowel nucleus, but pull a single following consonant to next syllable if possible.
  // Good enough for a toy that only needs syllable count and penult/ultima.
  const w = word;
  let i = 0;
  const syll = [];
  let current = '';

  while (i < w.length){
    const ch = w[i];
    current += ch;

    const vunit = nextVowelUnit(w, i);
    if (vunit){
      // ensure we include full diphthong
      if (vunit.len === 2){
        current = current.slice(0, -1) + vunit.unit;
        i += 1; // extra advance below
      }

      // lookahead consonant cluster
      let j = i + 1;
      let cluster = '';
      while (j < w.length){
        const vu = nextVowelUnit(w, j);
        if (vu) break;
        cluster += w[j];
        j++;
      }

      if (j >= w.length){
        // no more vowels: everything stays in last syllable
        syll.push(current + cluster);
        return syll.filter(x=>x.length);
      }

      // There is another vowel later.
      // If cluster length <=1, break syllable here (consonant goes with next syllable).
      // If cluster length >=2, keep first consonant with current syllable.
      if (cluster.length === 0){
        syll.push(current);
        current = '';
      } else if (cluster.length === 1){
        syll.push(current);
        current = '';
      } else {
        syll.push(current + cluster[0]);
        current = cluster.slice(1);
      }

      i = j - 1; // because loop will i++
    }

    i++;
  }

  if (current) syll.push(current);
  return syll.filter(x=>x.length);
}

// --- Accent placement (toy heuristic) ---
const acuteMap = {
  'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
  'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
};
const graveMap = {
  'α':'ὰ','ε':'ὲ','η':'ὴ','ι':'ὶ','ο':'ὸ','υ':'ὺ','ω':'ὼ',
  'Α':'Ὰ','Ε':'Ὲ','Η':'Ὴ','Ι':'Ὶ','Ο':'Ὸ','Υ':'Ὺ','Ω':'Ὼ'
};

function addAccentToSyllable(syllable, preferGrave=false){
  // Put accent on the last vowel of the syllable nucleus.
  const chars = [...syllable];
  for (let i = chars.length - 1; i >= 0; i--){
    const ch = chars[i];
    if (acuteMap[ch]){
      chars[i] = preferGrave ? (graveMap[ch] || acuteMap[ch]) : acuteMap[ch];
      return chars.join('');
    }
  }
  return syllable;
}

function looksCompound(raw){
  const s = raw.toLowerCase();
  if (s.includes('-')) return true;
  // crude prefix triggers inspired by examples in the passage
  const prefixes = ['πολυ', 'αρχι', 'ερι', 'φιλο', 'παν', 'μελλ', 'πανα'];
  return prefixes.some(p => s.startsWith(p));
}

function endsWithEn(word){
  const w = word;
  return w.endsWith('ην') || w.endsWith('ΗΝ') || w.endsWith('ην'.toUpperCase());
}

function accentToy(word, opts){
  const original = word;
  let w = cleanInput(word);
  if (!w) return {ok:false, msg:'Type a Greek word.'};

  // Keep only Greek letters + hyphen/apostrophe for the toy.
  w = [...w].filter(ch => isGreekLetter(ch) || ch==='-' || ch==='ʼ' || ch==="'").join('');
  if (!w) return {ok:false, msg:'No Greek letters found.'};

  const stripped = opts.strip ? stripDiacritics(w) : w;
  const syll = syllabifyRough(stripped.replace(/[-ʼ']/g,''));
  const syllCount = syll.length;

  const ending = endsWithEn(stripped) ? '-ην' : '—';

  let decision = '';
  let target = null; // 'ultima' | 'penult'

  if (!endsWithEn(stripped)){
    decision = 'Not an -ην word (toy still can accent last syllable).';
    target = 'ultima';
  } else {
    if (looksCompound(stripped)){
      decision = 'Looks compound/prefixed → accent penult (toy heuristic).';
      target = 'penult';
    } else if (syllCount > 2){
      decision = 'More than 2 syllables → final acute (…ήν).';
      target = 'ultima';
    } else {
      decision = '2 syllables → final acute (…ήν).';
      target = 'ultima';
    }
  }

  // Build accented output
  let outSyll = syll.slice();
  if (outSyll.length === 0) outSyll = [stripped];

  let idx = outSyll.length - 1;
  if (target === 'penult' && outSyll.length >= 2) idx = outSyll.length - 2;

  const preferGrave = opts.finalGrave && idx === outSyll.length - 1;
  outSyll[idx] = addAccentToSyllable(outSyll[idx], preferGrave);
  const out = outSyll.join('');

  return {
    ok:true,
    original,
    stripped,
    ending,
    syllables: outSyll,
    syllablesPlain: syll,
    decision,
    target,
    out
  };
}

// --- UI wiring ---
const examples = [
  'ωγην', 'αδην', 'ταγην', 'ατταγην', 'τριβην',
  'κορδυλην', 'μαριθην', 'δοθιην', 'ηλακατην',
  'αραδην', 'αραφην', 'κεφαλλην',
  'εἰρην', 'μελλειρην', 'ποιμην', 'αρχιποιμην', 'αυχην', 'εριαυχην', 'ρην', 'πολυρρην'
];

function render(res){
  if (!res.ok){
    $('#ending').textContent = '—';
    $('#syll').textContent = '—';
    $('#rule').textContent = res.msg;
    $('#outword').textContent = '—';
    return;
  }
  $('#ending').textContent = res.ending;
  $('#syll').textContent = res.syllablesPlain.join(' · ') + `  (${res.syllablesPlain.length})`;
  $('#rule').textContent = res.decision;
  $('#outword').textContent = res.out;
}

function run(){
  const opts = {
    strip: $('#strip').checked,
    finalGrave: $('#finalGrave').checked
  };
  const res = accentToy($('#in').value, opts);
  render(res);
}

$('#go').addEventListener('click', run);
$('#in').addEventListener('keydown', (e)=>{ if(e.key==='Enter') run(); });
$('#rand').addEventListener('click', ()=>{
  const w = examples[Math.floor(Math.random()*examples.length)];
  $('#in').value = w;
  run();
});

// --- Quiz ---
let currentQuiz = null;

function newQuiz(){
  const base = examples[Math.floor(Math.random()*examples.length)];
  // For quiz, show unaccented form to guess.
  const shown = stripDiacritics(base);
  currentQuiz = { base: shown };
  $('#qword').textContent = shown;
  $('#qresult').innerHTML = 'Make a guess, then <b>Reveal</b>.';
}

function revealQuiz(userGuess=null){
  const opts = { strip:true, finalGrave:false };
  const res = accentToy(currentQuiz.base, opts);
  const correct = res.target;
  let verdict = '';
  if (userGuess){
    verdict = (userGuess === correct)
      ? `<span class="good">Correct.</span>`
      : `<span class="bad">Not this time.</span>`;
  } else {
    verdict = `<span class="warn">Revealed.</span>`;
  }
  const where = correct === 'ultima' ? 'last syllable (…ήν)' : 'penult';
  $('#qresult').innerHTML = `${verdict} Toy predicts: <b>${where}</b> → <b>${res.out}</b><br><span class="small">Rule: ${res.decision}</span>`;
}

document.querySelectorAll('button[data-guess]').forEach(btn=>{
  btn.addEventListener('click', ()=>{
    const g = btn.getAttribute('data-guess');
    revealQuiz(g);
  });
});
$('#reveal').addEventListener('click', ()=>revealQuiz(null));
$('#next').addEventListener('click', newQuiz);

// initial state
$('#in').value = 'αυχην';
run();
newQuiz();

