(function(){
  const $ = (sel, root=document) => root.querySelector(sel);
  const $$ = (sel, root=document) => Array.from(root.querySelectorAll(sel));

  const inp = $('#inp');
  const proposed = $('#proposed');
  const rule = $('#rule');
  const syll = $('#syll');

  // --- Greek helpers ---
  const combiningMarks = /[\u0300-\u036f\u1ab0-\u1aff\u1dc0-\u1dff\u20d0-\u20ff\uFE20-\uFE2F]/g;
  const greekDiacritics = /[\u0342\u0301\u0300\u0313\u0314\u0308\u0345]/g; // circumflex/acute/grave/smooth/rough/diaeresis/iota-sub

  function stripCombining(s){
    return s.normalize('NFD').replace(combiningMarks,'').normalize('NFC');
  }
  function stripAccentOnly(s){
    // remove accent/breathing/diaeresis/iota-sub but keep base letters
    return s.normalize('NFD').replace(greekDiacritics,'').replace(combiningMarks,'').normalize('NFC');
  }

  function isVowel(ch){
    const c = stripCombining(ch).toLowerCase();
    return 'αεηιουω'.includes(c);
  }

  function roughSyllables(word){
    // Very rough: count vowel groups in the de-accented word.
    const w = stripAccentOnly(word);
    let groups = [];
    let cur = '';
    for (let i=0;i<w.length;i++){
      const ch = w[i];
      if (isVowel(ch)){
        cur += ch;
      } else {
        if (cur) { groups.push(cur); cur=''; }
      }
    }
    if (cur) groups.push(cur);
    return groups;
  }

  function endsWithAny(w, arr){
    const wl = stripAccentOnly(w).toLowerCase();
    return arr.some(suf => wl.endsWith(suf));
  }

  function applyAcuteOnLastVowel(word){
    // Add combining acute to the last vowel letter in the word.
    const nfd = stripAccentOnly(word).normalize('NFD');
    // Find last vowel base char index in NFD stream.
    let idx = -1;
    for (let i=0;i<nfd.length;i++){
      const ch = nfd[i];
      if (isVowel(ch)) idx = i;
    }
    if (idx === -1) return word;
    const acute = '\u0301';
    const out = nfd.slice(0, idx+1) + acute + nfd.slice(idx+1);
    return out.normalize('NFC');
  }

  function applyAcuteOnPenultVowel(word){
    const base = stripAccentOnly(word);
    const syls = roughSyllables(base);
    if (syls.length < 2) return applyAcuteOnLastVowel(base);

    // Find the start index of the penult vowel group in the base string.
    const w = base;
    // Walk through characters, tracking vowel groups.
    let groupIndex = -1;
    let inV = false;
    let starts = [];
    for (let i=0;i<w.length;i++){
      const v = isVowel(w[i]);
      if (v && !inV){
        inV = true;
        starts.push(i);
      }
      if (!v && inV) inV = false;
    }
    const penultStart = starts[starts.length-2];
    if (penultStart == null) return applyAcuteOnLastVowel(base);

    // Put acute on first vowel letter of that group.
    const nfd = w.normalize('NFD');
    // Map NFC index to NFD index approximately by rebuilding.
    // Simpler: operate on NFC string by inserting combining acute after the vowel char.
    const acute = '\u0301';
    const out = w.slice(0, penultStart+1) + acute + w.slice(penultStart+1);
    return out.normalize('NFC');
  }

  function guessRule(word){
    const w0 = word.trim();
    if (!w0) return null;
    const w = stripAccentOnly(w0);
    const wl = w.toLowerCase();

    // Identify endings.
    if (wl.endsWith('μην')){
      return {
        ending: '-μην',
        accent: 'ultima',
        reason: "Words in -μην are usually oxytone (accent on the last syllable).",
        propose: applyAcuteOnLastVowel(w)
      };
    }

    if (wl.endsWith('ρην')){
      // If penult has epsilon: ...ερην
      if (wl.endsWith('ερην')){
        return {
          ending: '-ρην',
          accent: 'penult',
          reason: "In -ρην, if the penult contains ε (…ερην), Herodian says it is paroxytone (accent on penult).",
          propose: applyAcuteOnPenultVowel(w)
        };
      }
      // Exception mentioned: ἄῤῥην (toy can special-case)
      if (wl === 'αρρην' || wl === 'ἄρρην' || wl === 'ἀρρην'){
        return {
          ending: '-ρην',
          accent: 'exception',
          reason: "Herodian notes an exception: ἄῤῥην.",
          propose: 'ἄῤῥην'
        };
      }
      return {
        ending: '-ρην',
        accent: 'ultima',
        reason: "In -ρην, if the penult is not a ‘pure’ ε-syllable (toy: not …ερην), it is usually oxytone.",
        propose: applyAcuteOnLastVowel(w)
      };
    }

    if (wl.endsWith('ιν')){
      return {
        ending: '-ιν',
        accent: 'ultima',
        reason: "Simple words in -ιν (the two-ending type) are oxytone (e.g. δελφίν, Τελχίν).",
        propose: applyAcuteOnLastVowel(w)
      };
    }

    return {
      ending: '—',
      accent: '—',
      reason: "This toy only targets endings -μην, -ρην, -ιν from the passage.",
      propose: w
    };
  }

  function render(){
    const val = inp.value;
    const g = guessRule(val);
    if (!g){
      proposed.textContent = '—';
      rule.textContent = '—';
      syll.textContent = '—';
      return;
    }
    proposed.textContent = g.propose || '—';
    rule.textContent = `${g.ending}: ${g.reason}`;

    const syls = roughSyllables(stripAccentOnly(val));
    syll.textContent = syls.length ? syls.join(' · ') + `  (≈${syls.length})` : 'no vowels found';
  }

  $('#btnGuess').addEventListener('click', render);
  $('#btnClear').addEventListener('click', () => { inp.value=''; render(); inp.focus(); });
  inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') render(); });

  $$('.chip').forEach(b=>b.addEventListener('click', ()=>{ inp.value = b.dataset.ex; render(); inp.focus(); }));

  // initial
  render();
})();

