(() => {
  const $ = (sel) => document.querySelector(sel);

  const inp = $('#inp');
  const cmp = $('#cmp');

  const endsWithEl = $('#endsWith');
  const syllEl = $('#syll');
  const marksEl = $('#marks');
  const ruleEl = $('#rule');

  const accentOut = $('#accentOut');
  const swapOut = $('#swapOut');
  const cmpOut = $('#cmpOut');

  const samples = [
    'Πλάτων', 'Ξενοφῶν', 'αἰών', 'Φόρκυν', 'Γόρτυν', 'Κρονίων',
    'Ἀβοριγῖνος', 'Ἀβοριγῖναι', 'Ἀβοριγινέων', 'ναῦται', 'ναυτέων',
    'εὐάκτιν', 'χρυσάκτιν', 'τριγλώχιν', 'Ποσειδέων', 'Ποσειδεών'
  ];

  // --- Greek helpers (toy-level) ---
  const combining = {
    acute: '\u0301',
    grave: '\u0300',
    circumflex: '\u0342',
    diaeresis: '\u0308',
    smooth: '\u0313',
    rough: '\u0314',
    iotaSub: '\u0345',
    macron: '\u0304',
    breve: '\u0306'
  };

  const ACCENTS = new Set([combining.acute, combining.grave, combining.circumflex]);

  function nfd(s){ return (s || '').normalize('NFD'); }
  function nfc(s){ return (s || '').normalize('NFC'); }

  function stripAccents(s){
    const d = nfd(s);
    let out = '';
    for (const ch of d){
      if (!ACCENTS.has(ch)) out += ch;
    }
    return nfc(out);
  }

  function listAccentMarks(s){
    const d = nfd(s);
    const found = { acute:0, grave:0, circumflex:0 };
    for (const ch of d){
      if (ch === combining.acute) found.acute++;
      else if (ch === combining.grave) found.grave++;
      else if (ch === combining.circumflex) found.circumflex++;
    }
    const parts = [];
    if (found.acute) parts.push(`acute×${found.acute}`);
    if (found.grave) parts.push(`grave×${found.grave}`);
    if (found.circumflex) parts.push(`circumflex×${found.circumflex}`);
    return parts.length ? parts.join(', ') : 'none';
  }

  const VOWELS = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

  function lastVowelIndexNFD(d){
    // Return index in NFD string of the last vowel base letter.
    for (let i = d.length - 1; i >= 0; i--){
      const ch = d[i];
      if (VOWELS.has(ch)) return i;
    }
    return -1;
  }

  function removeAccentFromVowelCluster(d, vowelIdx){
    // Remove accent marks immediately after vowelIdx (within its combining cluster)
    let out = '';
    for (let i = 0; i < d.length; i++){
      const ch = d[i];
      if (i > vowelIdx && i < d.length){
        // if we are in combining marks following the vowel, skip accent marks
        // We detect being in the cluster by checking previous base is the vowel at vowelIdx
      }
      out += ch;
    }
    // second pass: specifically strip accents globally then re-add later
    return stripAccents(nfc(d)).normalize('NFD');
  }

  function addAccentToUltima(word, accentType){
    // Toy: put the chosen accent on the last vowel of the word.
    const base = stripAccents(word);
    const d = nfd(base);
    const idx = lastVowelIndexNFD(d);
    if (idx === -1) return word;

    const mark = accentType === 'acute' ? combining.acute :
                 accentType === 'grave' ? combining.grave :
                 combining.circumflex;

    // Insert mark after the vowel base letter, but before any following combining marks.
    let out = '';
    for (let i = 0; i < d.length; i++){
      out += d[i];
      if (i === idx) out += mark;
    }
    return nfc(out);
  }

  function roughSyllableCount(word){
    // Count vowel groups in stripped word (very rough)
    const s = stripAccents(word);
    const d = nfd(s);
    let count = 0;
    let inV = false;
    for (const ch of d){
      if (VOWELS.has(ch)){
        if (!inV) count++;
        inV = true;
      } else {
        // combining marks ignored; consonants break groups
        if (ch >= '\u0300' && ch <= '\u036F') {
          // combining
        } else {
          inV = false;
        }
      }
    }
    return count || 0;
  }

  function ending(word){
    const s = stripAccents(word).trim();
    const lower = s; // Greek case not crucial here
    const endings = ['ινέων','ῖναι','ιων','ῖνος','ῖσι','ων','υν'];
    for (const e of endings){
      if (lower.endsWith(e)) return e;
    }
    // fallback: last 2 chars
    return lower.length >= 2 ? lower.slice(-2) : lower;
  }

  function toyRule(word){
    const e = ending(word);
    const syl = roughSyllableCount(word);

    if (e === 'ων'){
      return `-ων: Herodian says three tones are possible (acute/grave/circumflex). Try them!`;
    }
    if (e === 'υν'){
      return `-υν: “exceptionally barytone among Aeolians” (toy hint: avoid accenting the ultima).`;
    }
    if (e === 'ιων'){
      return `-ιων: patronymic/ethnic/diminutive often barytone (toy hint: avoid ultima).`;
    }
    if (e === 'ῖνος' || e === 'ῖναι' || e === 'ινέων' || e === 'ῖσι'){
      return `Aborigines-style declension/ethnic endings: play with swapping -ῖνος / -ῖναι / -ινέων / -ῖσι.`;
    }
    if (syl >= 3 && /[\u0301\u0300\u0342]/.test(nfd(word))){
      return `General accent play: try moving the tone to the last vowel (toy).`;
    }
    return `No specific trigger; still, try the three tones or swap endings.`;
  }

  function analyze(){
    const w = inp.value.trim();
    if (!w){
      endsWithEl.textContent = '—';
      syllEl.textContent = '—';
      marksEl.textContent = '—';
      ruleEl.textContent = '—';
      accentOut.textContent = '—';
      swapOut.textContent = '—';
      return;
    }
    endsWithEl.textContent = ending(w);
    syllEl.textContent = String(roughSyllableCount(w));
    marksEl.textContent = listAccentMarks(w);
    ruleEl.textContent = toyRule(w);

    // default accent output: show stripped + three options
    accentOut.textContent = addAccentToUltima(w, 'acute');
    swapOut.textContent = w;
  }

  function swapEnding(word, newEnding){
    const w = stripAccents(word).trim();
    if (!w) return '';

    // Remove a known ending if present; else remove last 2 letters as a crude "stem".
    const known = ['ινέων','ῖναι','ιων','ῖνος','ῖσι','ων','υν'];
    let stem = w;
    for (const e of known){
      if (w.endsWith(e)){
        stem = w.slice(0, -e.length);
        break;
      }
    }
    if (stem === w && w.length > 2) stem = w.slice(0, -2);

    let out = stem + newEnding.replace(/^→\s*/,'').replace(/^-/,'');
    // If user clicked "-ων" etc, ensure it begins with Greek letters not hyphen.
    out = out.replace(/-/, '');
    return out;
  }

  function accentIsOnUltima(word){
    const d = nfd(word);
    // Find last vowel base index
    const idx = lastVowelIndexNFD(d);
    if (idx === -1) return false;
    // Check if any accent mark occurs after idx before next base letter
    for (let i = idx + 1; i < d.length; i++){
      const ch = d[i];
      if (ACCENTS.has(ch)) return true;
      if (VOWELS.has(ch)) break;
      if (!(ch >= '\u0300' && ch <= '\u036F')) break;
    }
    return false;
  }

  // --- wire up ---
  $('#btnAnalyze').addEventListener('click', analyze);
  inp.addEventListener('keydown', (e) => { if (e.key === 'Enter') analyze(); });
  inp.addEventListener('input', () => { /* live-ish */ analyze(); });

  $('#btnRandom').addEventListener('click', () => {
    const w = samples[Math.floor(Math.random() * samples.length)];
    inp.value = w;
    analyze();
  });

  $('#btnClear').addEventListener('click', () => {
    inp.value = '';
    cmp.value = '';
    analyze();
    cmpOut.textContent = '—';
  });

  $('#btnAcute').addEventListener('click', () => {
    const w = inp.value.trim();
    accentOut.textContent = w ? addAccentToUltima(w, 'acute') : '—';
  });
  $('#btnGrave').addEventListener('click', () => {
    const w = inp.value.trim();
    accentOut.textContent = w ? addAccentToUltima(w, 'grave') : '—';
  });
  $('#btnCirc').addEventListener('click', () => {
    const w = inp.value.trim();
    accentOut.textContent = w ? addAccentToUltima(w, 'circumflex') : '—';
  });
  $('#btnStrip').addEventListener('click', () => {
    const w = inp.value.trim();
    accentOut.textContent = w ? stripAccents(w) : '—';
  });

  document.querySelectorAll('.chip').forEach(btn => {
    btn.addEventListener('click', () => {
      const w = inp.value.trim();
      if (!w){ swapOut.textContent = '—'; return; }
      const target = btn.getAttribute('data-swap');
      const newEnd = target.startsWith('-') ? target.slice(1) : target;
      const swapped = swapEnding(w, newEnd);
      // Give it a default toy accent: if -ων, show three-tone suggestion by acute on ultima; else keep stripped.
      swapOut.textContent = (newEnd === 'ων') ? addAccentToUltima(swapped, 'acute') : swapped;
    });
  });

  $('#btnCmp').addEventListener('click', () => {
    const t = cmp.value.trim();
    if (!t){ cmpOut.textContent = '—'; return; }
    const suggested = t.replace(/\s+/g,'');
    const word = suggested.replace('|','');
    const hasAccent = /[\u0301\u0300\u0342]/.test(nfd(word));
    const onUlt = accentIsOnUltima(word);

    let msg = '';
    if (!hasAccent){
      msg = `No accent marks detected. Try adding one (e.g. ${addAccentToUltima(word,'acute')}) and re-check.`;
    } else {
      msg = onUlt
        ? `Accent seems to be on the last vowel → not “barytone” (in the toy sense).`
        : `Accent seems earlier than the last vowel → “barytone-ish” (matches the compound hint).`;
    }

    // If a boundary was provided, show the two parts too.
    if (suggested.includes('|')){
      const [a,b] = suggested.split('|');
      msg += `  Parts: [${a}] + [${b}]`;
    }
    cmpOut.textContent = msg;
  });

  // init
  analyze();
})();

