(() => {
  // --- Utilities for (very) light polytonic handling ---
  const combining = /[\u0300-\u036f]/g;
  const stripCombining = (s) => s.normalize('NFD').replace(combining, '').normalize('NFC');

  const lastIndexOfAny = (s, chars) => {
    for (let i = s.length - 1; i >= 0; i--) if (chars.includes(s[i])) return i;
    return -1;
  };

  const vowels = 'αεηιουωάέήίόύώϊΐϋΰΑΕΗΙΟΥΩΆΈΉΊÓΎΏΪΫ';
  const isVowel = (ch) => vowels.includes(ch);

  function roughSyllables(word){
    // naive: split before each vowel group after the first
    const w = word;
    const nfd = w.normalize('NFD');
    // keep combining with base letter
    const chars = [];
    for (let i=0;i<nfd.length;i++){
      const c = nfd[i];
      if (c.match(combining) && chars.length){
        chars[chars.length-1] += c;
      } else {
        chars.push(c);
      }
    }
    const groups = [];
    let cur = '';
    let seenVowel = false;
    for (let i=0;i<chars.length;i++){
      const base = stripCombining(chars[i]);
      const v = base && isVowel(base);
      if (v && seenVowel){
        groups.push(cur.normalize('NFC'));
        cur = '';
      }
      if (v) seenVowel = true;
      cur += chars[i];
    }
    if (cur) groups.push(cur.normalize('NFC'));
    return groups;
  }

  function endsWithIWN(raw){
    const s = stripCombining(raw).toLowerCase();
    return s.endsWith('ιων');
  }

  function highlightEnding(raw){
    // highlight last 3 base letters (ιων) if present
    const nfd = raw.normalize('NFD');
    // map base letters positions in NFC-ish chunks
    const chunks = [];
    for (let i=0;i<nfd.length;i++){
      const c = nfd[i];
      if (c.match(combining) && chunks.length){
        chunks[chunks.length-1] += c;
      } else {
        chunks.push(c);
      }
    }
    // find last three base letters ignoring combining
    const bases = chunks.map(ch => stripCombining(ch));
    const low = bases.join('').toLowerCase();
    if (!low.endsWith('ιων')) return raw;

    // find indices of last 3 base letters in chunks
    let need = ['ι','ω','ν'];
    const idx = [];
    for (let i=chunks.length-1;i>=0 && need.length;i--){
      const b = bases[i].toLowerCase();
      if (b === need[need.length-1]){
        idx.push(i);
        need.pop();
      }
    }
    if (idx.length !== 3) return raw;
    idx.sort((a,b)=>a-b);
    const start = idx[0];
    const end = idx[2];
    const before = chunks.slice(0,start).join('').normalize('NFC');
    const mid = chunks.slice(start,end+1).join('').normalize('NFC');
    const after = chunks.slice(end+1).join('').normalize('NFC');
    return `${before}<span class="endhi">${mid}</span>${after}`;
  }

  function suggestAccent(raw, gender, ilen){
    // Toy rule:
    // - feminine -ιων => oxytone: ...ών (acute on omega)
    // - otherwise barytone: ...ίων (acute on iota)
    // We implement by rewriting the ending to either ίων or ών.
    const base = stripCombining(raw);
    const low = base.toLowerCase();
    if (!low.endsWith('ιων')) return { ok:false, msg:"Doesn’t look like it ends in -ιων." };

    const stem = raw.slice(0, raw.length - 3); // crude: assumes 3 visible chars; ok for typical input

    const fem = (gender === 'f');
    const rule = fem ? 'oxytone' : 'barytone';

    // Build suggested ending in polytonic-ish NFC.
    const ending = fem ? 'ών' : 'ίων';
    const suggested = stem + ending;

    // Explanation tags
    const tags = [];
    if (gender === 'auto') tags.push('gender:auto');
    else tags.push(`gender:${gender}`);
    if (ilen !== 'auto') tags.push(`ι:${ilen}`);

    return {
      ok:true,
      rule,
      suggested,
      tags
    };
  }

  function autoGender(raw){
    // Heuristic: if word is exactly χιών or ἠϊών (or without diacritics), mark feminine.
    const s = stripCombining(raw).toLowerCase();
    if (s === 'χιων' || s === 'ηιων' || s === 'αιων') return 'f';
    return 'm';
  }

  const examples = [
    {w:'Ὠρίων', g:'m', note:'proper name; Herodian discusses contraction/lengthening'},
    {w:'Δολίων', g:'m', note:'ethnic/tribal name nearby'},
    {w:'Ἠμαθίων', g:'m', note:'barytone -ιων example'},
    {w:'Ἀστερίων', g:'m', note:'barytone -ιων example'},
    {w:'Δευκαλίων', g:'m', note:'barytone -ιων example'},
    {w:'Ἐχίων', g:'m', note:'barytone -ιων example'},
    {w:'Πανδίων', g:'m', note:'barytone -ιων example'},
    {w:'χιών', g:'f', note:'feminine -ιων; oxytone in passage'},
    {w:'ἠϊών', g:'f', note:'feminine -ιων; oxytone in passage'},
    {w:'Ἑρμιών', g:'f', note:'place-name; treated as feminine in passage context'}
  ];

  // --- DOM ---
  const $ = (id) => document.getElementById(id);
  const word = $('word');
  const gender = $('gender');
  const ilen = $('ilen');
  const out = $('out');

  function renderAnalysis(){
    const raw = (word.value || '').trim();
    if (!raw){
      out.innerHTML = `<div class="tiny">Type a Greek word ending in <span class="pill">-ιων</span> to see a toy accent suggestion.</div>`;
      return;
    }

    const g = (gender.value === 'auto') ? autoGender(raw) : gender.value;
    const res = suggestAccent(raw, g, ilen.value);

    const syll = roughSyllables(raw);
    const syllHtml = syll.map(s => `<span class="pill">${s}</span>`).join(' ');

    const endOk = endsWithIWN(raw);

    let msg = '';
    if (!endOk){
      msg = `<div class="warn">This toy is tuned for words ending in <strong>-ιων</strong>. Your input may not match that ending.</div>`;
    }

    if (!res.ok){
      out.innerHTML = `${msg}
        <div class="kv">
          <div class="k">Input</div><div class="v">${raw}</div>
          <div class="k">Syllables (rough)</div><div class="v">${syllHtml}</div>
          <div class="k">Ending check</div><div class="v">${endOk ? '<span class="good">looks like -ιων</span>' : '<span class="bad">not -ιων</span>'}</div>
        </div>
        <div class="tiny">${res.msg}</div>`;
      return;
    }

    const ruleLine = res.rule === 'oxytone'
      ? `<span class="good">Feminine -ιων → oxytone</span> (accent on the last syllable: …<strong>ών</strong>).`
      : `<span class="good">Non-feminine -ιων → barytone</span> (accent not on the last; toy form …<strong>ίων</strong>).`;

    out.innerHTML = `${msg}
      <div class="kv">
        <div class="k">Input</div><div class="v">${highlightEnding(raw)}</div>
        <div class="k">Syllables (rough)</div><div class="v">${syllHtml}</div>
        <div class="k">Toy rule applied</div><div class="v">${ruleLine}</div>
        <div class="k">Suggested form</div><div class="v"><strong>${res.suggested}</strong></div>
        <div class="k">Notes</div><div class="v tiny">Tags: ${res.tags.map(t=>`<span class="pill">${t}</span>`).join(' ')}</div>
      </div>
      <div class="tiny">Reminder: real Greek accentuation depends on quantity, morphology, and tradition; this gadget only illustrates the passage’s contrast.</div>`;
  }

  $('analyze').addEventListener('click', renderAnalysis);
  word.addEventListener('input', () => { if (word.value.trim().length === 0) renderAnalysis(); });
  gender.addEventListener('change', renderAnalysis);
  ilen.addEventListener('change', renderAnalysis);

  $('shuffle').addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    word.value = ex.w;
    gender.value = 'auto';
    ilen.value = 'auto';
    renderAnalysis();
  });

  $('clear').addEventListener('click', () => {
    word.value = '';
    gender.value = 'auto';
    ilen.value = 'auto';
    renderAnalysis();
  });

  // --- Quiz ---
  let q = null;
  let score = 0;
  let total = 0;

  function newQuestion(){
    q = examples[Math.floor(Math.random()*examples.length)];
    $('qword').textContent = q.w;
    $('qhint').textContent = 'Hint: choose oxytone mainly for feminine -ιων (e.g. χιών, ἠϊών).';
  }

  function correctAnswerFor(ex){
    return (ex.g === 'f') ? 'O' : 'B';
  }

  function answer(pick){
    if (!q) newQuestion();
    const correct = correctAnswerFor(q);
    total++;
    if (pick === correct) score++;

    $('score').textContent = String(score);
    $('total').textContent = String(total);

    const verdict = (pick === correct)
      ? `Correct. ${q.note}`
      : `Not by this toy rule. It treats this as ${q.g==='f'?'feminine → oxytone':'non-feminine → barytone'}. ${q.note}`;

    const sug = suggestAccent(q.w, q.g, 'auto');
    $('qhint').innerHTML = `${verdict} Suggested: <strong>${sug.ok ? sug.suggested : q.w}</strong>.`;
  }

  $('pickB').addEventListener('click', () => answer('B'));
  $('pickO').addEventListener('click', () => answer('O'));
  $('nextQ').addEventListener('click', () => newQuestion());

  // init
  renderAnalysis();
  newQuestion();
})();

