const $ = (sel) => document.querySelector(sel);

const examples = [
  {g:"Ἀτρείων", note:"-είων patronymic/ethnic → barytone"},
  {g:"Πηλείων", note:"-είων → barytone"},
  {g:"Ἀργείων", note:"-είων → barytone"},
  {g:"Καδμείων", note:"-είων → barytone"},
  {g:"Βακχείων", note:"-είων → barytone"},
  {g:"Ἡρακλείων", note:"-είων → barytone"},
  {g:"Χαρικλείων", note:"-είων → barytone"},
  {g:"Μαίων", note:"disyllabic -αιων → barytone"},
  {g:"Μήων", note:"αι→η change shown"},
  {g:"αἰών", note:"time-word → oxytone"},
  {g:"Εὐφραίων", note:"polysyllabic -αιων → barytone"},
  {g:"Αἰγαίων", note:"polysyllabic -αιων → barytone"},
  {g:"Ἀκταίων", note:"polysyllabic -αιων → barytone"},
  {g:"Ἑρμιών", note:"place-name; story includes ο→ε"}
];

const combining = /[\u0300-\u036f]/g;

function nfd(s){return s.normalize('NFD');}
function nfc(s){return s.normalize('NFC');}

function stripDiacritics(s){
  // remove combining marks; keep base letters
  return nfc(nfd(s).replace(combining, ''));
}

function hasAcuteOnLastVowel(word){
  // crude: find last vowel (including diphthongs as two letters) and see if any acute combining mark occurs after it
  const w = nfd(word);
  const acute = "\u0301";
  // find last Greek vowel base index
  const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);
  let lastVowelIndex = -1;
  for(let i=0;i<w.length;i++){
    const ch = w[i];
    if(vowels.has(ch)) lastVowelIndex = i;
  }
  if(lastVowelIndex < 0) return false;
  // check combining marks immediately after last vowel base
  for(let j=lastVowelIndex+1;j<w.length;j++){
    const ch = w[j];
    if(ch >= "\u0370" && ch <= "\u03FF") break; // next Greek base letter
    if(ch === acute) return true;
  }
  return false;
}

function endsWithAny(s, arr){
  return arr.some(e => s.endsWith(e));
}

function classify(word){
  const raw = word.trim();
  if(!raw) return {status:"empty"};

  const plain = stripDiacritics(raw);
  const lower = plain.toLowerCase();

  // Key patterns from passage
  const isAionTime = lower === "αιων"; // αἰών

  // -είων (penult ει) patronymic/ethnic barytone
  const isEion = endsWithAny(lower, ["ειων"]);

  // -αιων barytone generally (disyllables explicitly; polysyllables too with exceptions)
  const isAionEnding = endsWithAny(lower, ["αιων"]);

  // Some place-names in -ιών (not the main rule, but present)
  const isIon = endsWithAny(lower, ["ιων"]);

  let expected = null; // "barytone" | "oxytone" | null
  let rule = "";
  let confidence = "warn";

  if(isAionTime){
    expected = "oxytone";
    rule = "Exception in the passage: <mark>αἰών</mark> (time-word) is said to be oxytone (accent on the last).";
    confidence = "good";
  } else if(isEion){
    expected = "barytone";
    rule = "Herodian: patronymics/ethnics in <mark>-ων</mark> with penult <mark>ει</mark> (i.e. <mark>-είων</mark>) are barytone.";
    confidence = "good";
  } else if(isAionEnding){
    expected = "barytone";
    rule = "Herodian: words in <mark>-αιων</mark> are barytone (disyllables explicitly; polysyllables too, with listed exceptions).";
    confidence = "good";
  } else if(isIon){
    expected = "(unknown)";
    rule = "This ends in <mark>-ιων</mark>. The passage lists several place-names in -ιών, but the accent rule stated is mainly about -είων and -αιων.";
    confidence = "warn";
  } else {
    expected = "(unknown)";
    rule = "No matching ending (-είων / -αιων) detected. Try an example from the chips below.";
    confidence = "bad";
  }

  // Observed (from input) — only checks if acute on last vowel; rough proxy for oxytone.
  const observedOxytone = hasAcuteOnLastVowel(raw);
  const observed = observedOxytone ? "oxytone-ish" : "not-last-accent-ish";

  let verdict = "";
  if(expected === "barytone"){
    verdict = observedOxytone ? "Input looks oxytone, but the passage-rule expects barytone." : "Input looks barytone (not last-accent), matching the passage-rule.";
  } else if(expected === "oxytone"){
    verdict = observedOxytone ? "Input looks oxytone, matching the passage-rule." : "Input does not look oxytone, but the passage-rule expects oxytone.";
  } else {
    verdict = "No strong rule applied; showing transformations and a rough accent check.";
  }

  return {raw, plain, expected, observed, verdict, rule, confidence};
}

function applyToyTransforms(s){
  let out = s;
  if($('#stripAcc').checked) out = stripDiacritics(out);
  // apply after stripping accents if chosen
  if($('#swapOe').checked){
    // toy: replace omicron with epsilon (both cases)
    out = out.replace(/ο/g,'ε').replace(/Ο/g,'Ε');
  }
  if($('#swapAi').checked){
    // toy: replace αι with η (and Αι/ΑΙ)
    out = out.replace(/αι/g,'η').replace(/ΑΙ/g,'Η').replace(/Αι/g,'Η');
  }
  return out;
}

function render(){
  const inp = $('#inp').value;
  const info = classify(inp);
  const x = applyToyTransforms(inp.trim());
  $('#xform').textContent = x || "—";

  const res = $('#result');
  const rule = $('#rule');

  if(info.status === 'empty'){
    res.innerHTML = '<span class="badge warn">type something</span> <span class="muted">—</span>';
    rule.textContent = '';
    return;
  }

  const badgeClass = info.confidence;
  const exp = info.expected;
  const obs = info.observed;

  res.innerHTML = `
    <span class="badge ${badgeClass}">expected: ${escapeHtml(exp)}</span>
    <span class="badge">observed: ${escapeHtml(obs)}</span>
    <span>${escapeHtml(info.verdict)}</span>
  `;
  rule.innerHTML = info.rule;
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function mountChips(){
  const box = $('#chips');
  box.innerHTML = '';
  examples.forEach((ex) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip';
    b.textContent = ex.g;
    b.title = ex.note;
    b.addEventListener('click', () => {
      $('#inp').value = ex.g;
      render();
    });
    box.appendChild(b);
  });
}

$('#analyze').addEventListener('click', render);
$('#random').addEventListener('click', () => {
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#inp').value = ex.g;
  render();
});
$('#clear').addEventListener('click', () => {
  $('#inp').value = '';
  render();
  $('#inp').focus();
});
$('#inp').addEventListener('input', render);
['swapOe','swapAi','stripAcc'].forEach(id => $('#'+id).addEventListener('change', render));

mountChips();
render();

