passages.gadget_js:
const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const pretty = $('#pretty');
const meta = $('#meta');
const alt = $('#alt');
const stripBox = $('#strip');
const autoBox = $('#auto');
const btnAnalyze = $('#analyze');
const btnClear = $('#clear');
const btnBary = $('#makeBary');
const btnOxy = $('#makeOxy');

// --- Minimal polytonic helpers (toy-level) ---
// We strip combining marks and also a small set of precomposed accented vowels.
const precomposedMap = new Map([
  ['ά','α'],['ὰ','α'],['ᾶ','α'],['ἀ','α'],['ἁ','α'],['ἄ','α'],['ἂ','α'],['ἆ','α'],['ἅ','α'],['ἃ','α'],['ἇ','α'],['ᾴ','αι'],['ᾲ','αι'],['ᾷ','αι'],
  ['έ','ε'],['ὲ','ε'],['ἐ','ε'],['ἑ','ε'],['ἔ','ε'],['ἒ','ε'],['ἕ','ε'],['ἓ','ε'],
  ['ή','η'],['ὴ','η'],['ῆ','η'],['ἠ','η'],['ἡ','η'],['ἤ','η'],['ἢ','η'],['ἦ','η'],['ἥ','η'],['ἣ','η'],['ἧ','η'],
  ['ί','ι'],['ὶ','ι'],['ῖ','ι'],['ἰ','ι'],['ἱ','ι'],['ἴ','ι'],['ἲ','ι'],['ἶ','ι'],['ἵ','ι'],['ἳ','ι'],['ἷ','ι'],
  ['ό','ο'],['ὸ','ο'],['ὀ','ο'],['ὁ','ο'],['ὄ','ο'],['ὂ','ο'],['ὅ','ο'],['ὃ','ο'],
  ['ύ','υ'],['ὺ','υ'],['ῦ','υ'],['ὐ','υ'],['ὑ','υ'],['ὔ','υ'],['ὒ','υ'],['ὖ','υ'],['ὕ','υ'],['ὓ','υ'],['ὗ','υ'],
  ['ώ','ω'],['ὼ','ω'],['ῶ','ω'],['ὠ','ω'],['ὡ','ω'],['ὤ','ω'],['ὢ','ω'],['ὦ','ω'],['ὥ','ω'],['ὣ','ω'],['ὧ','ω'],
  ['Ά','Α'],['Έ','Ε'],['Ή','Η'],['Ί','Ι'],['Ό','Ο'],['Ύ','Υ'],['Ώ','Ω'],
  ['ϊ','ι'],['ΐ','ι'],['ϋ','υ'],['ΰ','υ'],
]);

function stripDiacritics(s){
  // Normalize to NFD to remove combining marks; also map some precomposed.
  let out = '';
  for (const ch of s){
    if (precomposedMap.has(ch)) out += precomposedMap.get(ch);
    else out += ch;
  }
  // Remove combining marks
  out = out.normalize('NFD').replace(/[\u0300-\u036f\u1dc0-\u1dff]/g,'').normalize('NFC');
  return out;
}

function lastIndexOfAny(s, chars){
  for (let i=s.length-1;i>=0;i--) if (chars.includes(s[i])) return i;
  return -1;
}

const vowels = 'αεηιουωΑΕΗΙΟΥΩ';

function countVowelGroups(s){
  // crude syllable proxy: count runs of vowels (treat diphthongs as one group)
  const t = s;
  let n=0;
  let i=0;
  while(i<t.length){
    const c=t[i];
    if (vowels.includes(c)){
      n++;
      // swallow following vowel if diphthong-ish
      const next=t[i+1]||'';
      if (vowels.includes(next)) i+=2; else i+=1;
      continue;
    }
    i++;
  }
  return n;
}

function applyAcuteOnLastVowel(s){
  // place tonos/acute on last vowel letter (modern tonos for simplicity)
  const idx = lastIndexOfAny(s, vowels);
  if (idx<0) return s;
  const ch = s[idx];
  const map = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };
  const rep = map[ch] || ch;
  return s.slice(0,idx)+rep+s.slice(idx+1);
}

function applyAcuteOnPenultVowel(s){
  // accent the penultimate vowel group (toy): find last two vowel positions, accent the earlier one
  const positions=[];
  for (let i=0;i<s.length;i++) if (vowels.includes(s[i])) positions.push(i);
  if (positions.length===0) return s;
  const idx = positions.length>=2 ? positions[positions.length-2] : positions[0];
  const ch = s[idx];
  const map = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };
  const rep = map[ch] || ch;
  return s.slice(0,idx)+rep+s.slice(idx+1);
}

// --- Passage-inspired micro-lexica (demo only) ---
const oxytoneCities = new Set(['Σικυων','Σικυών','Κρεμμυων','Κρεμμυών','Κρομμυων','Κρομμυών']);
const genitiveOmegaToOmicron = new Set(['αλεκτρυων','Γηρυων','Κερκυων','Αμφικτυων','κελενδρυων','κολοκτρυων','ἀλεκτρυών','Γηρυών','Κερκυών','Ἀμφικτυών','κελενδρυών','κολοκτρυών']);
const bodyPartBwn = new Set(['στίλβων','στιλβων','Στίβων','Στιβων','τρίβων','τριβων','Στράβων','Στραβων','ἄμβων','αμβων']);

function endsWithAny(s, arr){
  return arr.some(e => s.endsWith(e));
}

function analyzeWord(raw){
  const original = raw.trim();
  const base = stripBox.checked ? stripDiacritics(original) : original;
  const baseNoSpace = base.replace(/\s+/g,' ');
  const token = baseNoSpace.split(' ')[0] || '';
  const tokenLower = stripDiacritics(token).toLowerCase();

  const syll = countVowelGroups(stripDiacritics(token));

  let ruleTag = {cls:'warn', text:'heuristic'};
  let suggestion = null; // 'bary' | 'oxy' | null
  let reason = '';

  // -αυων barytone
  if (tokenLower.endsWith('αυων')){
    suggestion = 'bary';
    ruleTag = {cls:'good', text:'-αυων → barytone'};
    reason = "Herodian: τὰ εἰς -αυων βαρύνεται.";
  }
  // -υων
  else if (tokenLower.endsWith('υων')){
    if (syll <= 2){
      suggestion = 'bary';
      ruleTag = {cls:'good', text:'-υων (2 syll.) → barytone'};
      reason = "Herodian: τὰ εἰς -υων δισύλλαβα βαρύνεται.";
    } else {
      // city-name exceptions and omega->omicron list
      if (oxytoneCities.has(token) || oxytoneCities.has(stripDiacritics(token))){
        suggestion = 'oxy';
        ruleTag = {cls:'good', text:'city-name → oxytone'};
        reason = "Herodian: Σικυών (and similar) ὀξύνεται.";
      } else if (genitiveOmegaToOmicron.has(tokenLower) || genitiveOmegaToOmicron.has(token)){
        suggestion = 'oxy';
        ruleTag = {cls:'good', text:'ω→ο in gen. → oxytone'};
        reason = "Herodian: those with genitive ω→ο are ὀξύνεται (demo list).";
      } else {
        suggestion = 'bary';
        ruleTag = {cls:'warn', text:'-υων (>2) varies'};
        reason = "Herodian: >2 syllables in -υων can be barytone or oxytone; toy defaults to barytone unless in a small oxytone list.";
      }
    }
  }
  // -βων
  else if (tokenLower.endsWith('βων')){
    if (syll <= 2){
      if (bodyPartBwn.has(token) || bodyPartBwn.has(tokenLower)){
        suggestion = 'oxy';
        ruleTag = {cls:'warn', text:'body-part exception'};
        reason = "Herodian: -βων disyllables barytone unless body-part; toy marks exception as oxytone-ish for play.";
      } else {
        suggestion = 'bary';
        ruleTag = {cls:'good', text:'-βων (2 syll.) → barytone'};
        reason = "Herodian: τὰ εἰς -βων δισύλλαβα… βαρύνεται.";
      }
    } else {
      suggestion = null;
      ruleTag = {cls:'warn', text:'-βων (not 2 syll.)'};
      reason = "Rule in passage targets disyllables; toy won’t guess confidently.";
    }
  }
  else {
    suggestion = null;
    ruleTag = {cls:'bad', text:'no match'};
    reason = "No matching ending (-αυων / -υων / -βων) detected.";
  }

  return {original, base, token, syll, suggestion, ruleTag, reason};
}

function render(res){
  const tag = `<span class="tag ${res.ruleTag.cls}">${escapeHtml(res.ruleTag.text)}</span>`;
  const syll = `<span class="tag">~${res.syll} syll.</span>`;

  let shown = res.base;
  let applied = '';

  if (autoBox.checked && res.suggestion){
    // apply to first token only, keep rest of phrase
    const parts = res.base.split(/\s+/);
    const first = parts.shift() || '';
    const rest = parts.join(' ');
    const firstStripped = stripBox.checked ? stripDiacritics(first) : first;

    const accented = (res.suggestion==='oxy')
      ? applyAcuteOnLastVowel(firstStripped)
      : applyAcuteOnPenultVowel(firstStripped);

    shown = accented + (rest ? ' ' + rest : '');
    applied = res.suggestion==='oxy' ? 'Applied: oxytone (acute on last vowel letter).' : 'Applied: barytone (acute on penult vowel letter).';
  }

  pretty.textContent = shown || '—';
  meta.innerHTML = `${tag} ${syll}<div style="margin-top:6px">${escapeHtml(res.reason)}${applied?`<div style="margin-top:6px" class="kbd">${escapeHtml(applied)}</div>`:''}</div>`;

  const canPlay = !!res.suggestion || /(?:αυων|υων|βων)$/i.test(stripDiacritics(res.token).toLowerCase());
  btnBary.disabled = !canPlay;
  btnOxy.disabled = !canPlay;

  if (!canPlay){
    alt.textContent = '—';
  } else {
    const baseFirst = stripBox.checked ? stripDiacritics(res.token) : res.token;
    const bary = applyAcuteOnPenultVowel(baseFirst);
    const oxy = applyAcuteOnLastVowel(baseFirst);
    alt.innerHTML = `Try: <span class="kbd">${escapeHtml(bary)}</span> (barytone-ish)  |  <span class="kbd">${escapeHtml(oxy)}</span> (oxytone-ish)`;
  }
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function doAnalyze(){
  const v = inp.value;
  if (!v.trim()){
    pretty.textContent = '—';
    meta.textContent = 'Enter a word and click Analyze.';
    alt.textContent = '—';
    btnBary.disabled = true;
    btnOxy.disabled = true;
    return;
  }
  const res = analyzeWord(v);
  render(res);
}

btnAnalyze.addEventListener('click', doAnalyze);
inp.addEventListener('keydown', (e)=>{
  if (e.key === 'Enter') doAnalyze();
});
btnClear.addEventListener('click', ()=>{
  inp.value='';
  doAnalyze();
  inp.focus();
});

btnBary.addEventListener('click', ()=>{
  const v = inp.value.trim();
  if (!v) return;
  const base = stripBox.checked ? stripDiacritics(v) : v;
  const parts = base.split(/\s+/);
  const first = parts.shift() || '';
  const rest = parts.join(' ');
  const out = applyAcuteOnPenultVowel(first) + (rest ? ' ' + rest : '');
  pretty.textContent = out;
});

btnOxy.addEventListener('click', ()=>{
  const v = inp.value.trim();
  if (!v) return;
  const base = stripBox.checked ? stripDiacritics(v) : v;
  const parts = base.split(/\s+/);
  const first = parts.shift() || '';
  const rest = parts.join(' ');
  const out = applyAcuteOnLastVowel(first) + (rest ? ' ' + rest : '');
  pretty.textContent = out;
});

// Seed with an example
inp.value = 'Χαυων';
doAnalyze();

