const $ = (sel) => document.querySelector(sel);

const examples = [
  {w:"Αλαβων", hint:"Herodian: -βων (more than 2 syllables) → acute"},
  {w:"ἀρραβων", hint:"Herodian: ἀῤῥαβών (acute)"},
  {w:"Χαρναβων", hint:"Herodian: Χαρναβῶν (circumflex)"},
  {w:"πωγων", hint:"Herodian: πώγων (disyllabic -γων, non-inclusive) → grave/‘barytone’"},
  {w:"αγων", hint:"Herodian: ἀγών (inclusive) → acute"},
  {w:"φηγων", hint:"Herodian: φηγών (inclusive) → acute"},
  {w:"Οργων", hint:"Herodian: Ὀργών (toponym) → acute"},
  {w:"πυγων", hint:"Herodian: πυγών ‘declines with ο’"}
];

// --- Greek helpers (very lightweight) ---
const combining = {
  acute: "\u0301",
  grave: "\u0300",
  circumflex: "\u0342",
  diaeresis: "\u0308",
  smooth: "\u0313",
  rough: "\u0314",
  iotaSub: "\u0345"
};

function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripDiacritics(s){
  // Keep Greek letters, remove combining marks.
  return nfc(nfd(s).replace(/[\u0300-\u036f]/g, ""));
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code >= 0x0370 && code <= 0x03FF) || (code >= 0x1F00 && code <= 0x1FFF);
}

function greekVowelBase(ch){
  // expects base (no combining)
  return "αεηιουωΑΕΗΙΟΥΩ".includes(ch);
}

function lastVowelIndex(base){
  for(let i=base.length-1;i>=0;i--){
    if(greekVowelBase(base[i])) return i;
  }
  return -1;
}

function penultVowelIndex(base){
  let seen = 0;
  for(let i=base.length-1;i>=0;i--){
    if(greekVowelBase(base[i])){
      seen++;
      if(seen===2) return i;
    }
  }
  return -1;
}

function countVowels(base){
  let c=0;
  for(const ch of base) if(greekVowelBase(ch)) c++;
  return c;
}

function applyAccentToVowel(word, vowelIndex, accentType){
  if(vowelIndex < 0) return word;
  const base = stripDiacritics(word);
  const chars = [...base];
  const v = chars[vowelIndex];
  // Add combining mark after the vowel.
  let mark = combining.acute;
  if(accentType === 'grave') mark = combining.grave;
  if(accentType === 'circumflex') mark = combining.circumflex;
  chars[vowelIndex] = v + mark;
  return nfc(chars.join(""));
}

function endsWithAny(base, arr){
  const b = base.toLowerCase();
  return arr.some(s => b.endsWith(s));
}

function analyze(wordRaw, opts){
  const cleaned = wordRaw.trim();
  if(!cleaned) return {ok:false, msg:"Enter a Greek word."};

  const base = stripDiacritics(cleaned);
  const lower = base.toLowerCase();
  const vowels = countVowels(base);

  const isBon = lower.endsWith("βων");
  const isGon = lower.endsWith("γων");

  if(!isBon && !isGon){
    return {
      ok:true,
      base,
      accented: cleaned,
      rule:"This toy only targets words ending in -βων or -γων.",
      badge:"warn",
      details:`I see ${vowels} vowel(s). Try e.g. Αλαβων, Χαρναβων, πωγων, αγων.`
    };
  }

  // Default accent placement: on the last vowel (oxytone) unless rule says otherwise.
  let accentType = 'acute';
  let accentVowelIndex = lastVowelIndex(base);
  let rule = "";
  let badge = "good";

  if(isBon){
    // Herodian: -βων hyperdisyllables oxytone; but Χαρναβῶν circumflex.
    if(lower === "χαρναβων"){
      accentType = 'circumflex';
      accentVowelIndex = lastVowelIndex(base); // ω
      rule = "Special case from the passage: Χαρναβῶν takes circumflex.";
    } else if(vowels > 2){
      accentType = 'acute';
      accentVowelIndex = lastVowelIndex(base);
      rule = "Rule of thumb (Herodian): -βων with >2 syllables tends to be oxytone (acute on ultima).";
    } else {
      accentType = 'acute';
      accentVowelIndex = lastVowelIndex(base);
      badge = "warn";
      rule = "Herodian’s cited rule is for >2 syllables; for disyllables this toy just makes it oxytone.";
    }
  }

  if(isGon){
    if(vowels === 2){
      // Herodian: disyllabic masculines in -γων barytone unless inclusive or declined with o; inclusive -> acute.
      if(opts.place){
        accentType = 'acute';
        accentVowelIndex = lastVowelIndex(base);
        rule = "Toponym toggle: like Ὀργών, treat as oxytone (acute on ultima).";
      } else if(opts.inclusive){
        accentType = 'acute';
        accentVowelIndex = lastVowelIndex(base);
        rule = "Inclusive-force toggle: like ἀγών / φηγών → oxytone (acute on ultima).";
      } else if(opts.declO){
        // Not in the ‘grave’ bucket; we’ll default to oxytone for play.
        accentType = 'acute';
        accentVowelIndex = lastVowelIndex(base);
        badge = "warn";
        rule = "‘Declines with ο’ toggle: Herodian separates these from the barytone set; toy defaults to oxytone.";
      } else {
        // barytone: accent on penult; we show it as GRAVE on penult to visualize “βαρύνεται”.
        accentType = 'grave';
        accentVowelIndex = penultVowelIndex(base);
        rule = "Herodian: disyllabic -γων masculines (non-inclusive, not ‘with ο’) are ‘barytone’ → accent on penult.";
      }
    } else {
      // >2 syllables: Herodian says both acute and grave occur; toy offers a choice based on genitive sandbox.
      accentType = 'acute';
      accentVowelIndex = lastVowelIndex(base);
      badge = "warn";
      rule = "Herodian: -γων with >2 syllables can be acute or grave; toy defaults to oxytone.";
    }
  }

  const accented = applyAccentToVowel(base, accentVowelIndex, accentType);
  const details = `Detected ending: ${isBon?"-βων":"-γων"}. Vowels≈syllables: ${vowels}. Accent: ${accentType} on ${accentVowelIndex===lastVowelIndex(base)?"ultima":"penult"}.`;

  return {ok:true, base, accented, rule, details, badge, isBon, isGon, vowels, accentType, accentVowelIndex};
}

function makeForms(analysis, genChoice){
  if(!analysis || !analysis.ok) return [];
  const base = analysis.base;
  const lower = base.toLowerCase();

  // crude stem: remove final ν
  let stem = base;
  if(lower.endsWith("ν")) stem = base.slice(0, -1);

  const nom = analysis.accented;
  let gen = "";
  let note = "";

  if(genChoice === 'os'){
    gen = stem + "ος";
    note = "simple -ος genitive (toy)";
  } else if(genChoice === 'ou'){
    gen = stem + "ου";
    note = "simple -ου genitive (toy)";
  } else {
    // -οντος: attach to stem without changing; purely playful
    gen = stem + "οντος";
    note = "-ντ- genitive vibe (Herodian mentions -ντ- declension)";
  }

  // Accent the generated genitive using same heuristic as for nominative, but re-run analysis on genitive base.
  // For fun, treat genitive as separate word.
  const opts = {
    inclusive: $('#inclusive').checked,
    declO: $('#declO').checked,
    place: $('#place').checked
  };
  const genA = analyze(gen, opts);

  return [
    {tag:"Nominative", val: nom},
    {tag:"Genitive", val: genA.ok ? genA.accented : gen, sub: note}
  ];
}

function setBadge(el, kind){
  el.classList.remove('good','warn','bad');
  el.classList.add(kind);
}

function render(){
  const w = $('#w').value;
  const opts = {
    inclusive: $('#inclusive').checked,
    declO: $('#declO').checked,
    place: $('#place').checked
  };
  const a = analyze(w, opts);

  $('#accented').textContent = a.ok ? a.accented : '—';

  const diag = $('#diagnostic');
  if(!a.ok){
    diag.textContent = a.msg;
    return;
  }

  diag.innerHTML = `${escapeHtml(a.rule)} <span class="badge ${a.badge}">${a.badge==='good'?'rule-fit':a.badge}</span><br><span class="mut">${escapeHtml(a.details)}</span>`;

  // update forms if already present
  if($('#forms').dataset.hasForms === '1'){
    const forms = makeForms(a, $('#gen').value);
    renderForms(forms);
  }

  // store last analysis
  window.__lastAnalysis = a;
}

function renderForms(forms){
  const box = $('#forms');
  box.innerHTML = '';
  for(const f of forms){
    const line = document.createElement('div');
    line.className = 'formline';
    const left = document.createElement('div');
    left.className = 'tag';
    left.textContent = f.tag + (f.sub ? ` — ${f.sub}` : '');
    const right = document.createElement('div');
    right.className = 'val';
    right.textContent = f.val;
    line.appendChild(left);
    line.appendChild(right);
    box.appendChild(line);
  }
  box.dataset.hasForms = '1';
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

$('#go').addEventListener('click', render);
$('#w').addEventListener('keydown', (e)=>{ if(e.key==='Enter') render(); });
$('#inclusive').addEventListener('change', render);
$('#declO').addEventListener('change', render);
$('#place').addEventListener('change', render);

$('#rand').addEventListener('click', ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#w').value = ex.w;
  // set toggles to match some examples
  const lw = stripDiacritics(ex.w).toLowerCase();
  $('#inclusive').checked = (lw === 'αγων' || lw === 'φηγων');
  $('#place').checked = (lw === 'οργων');
  $('#declO').checked = (lw === 'πυγων');
  render();
  // show hint in forms area if empty
  const diag = $('#diagnostic');
  diag.innerHTML = `${escapeHtml(ex.hint)} <span class="badge warn">example</span><br><span class="mut">(You can now tweak the checkboxes.)</span>`;
});

$('#makeForms').addEventListener('click', ()=>{
  const a = window.__lastAnalysis || analyze($('#w').value, {
    inclusive: $('#inclusive').checked,
    declO: $('#declO').checked,
    place: $('#place').checked
  });
  const forms = makeForms(a, $('#gen').value);
  renderForms(forms);
});

// initial
window.__lastAnalysis = null;
render();

