// Herodian Accent Toy (offline, heuristic)
const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const accentOut = $('#accentOut');
const accentWhy = $('#accentWhy');
const genOut = $('#genOut');
const chkFromOs = $('#chkFromOs');
const toggleOut = $('#toggleOut');

// --- Utilities: basic polytonic handling ---
const combining = /[\u0300-\u036f]/g;
function nfd(s){ return (s||'').normalize('NFD'); }
function stripCombining(s){ return nfd(s).replace(combining,'').normalize('NFC'); }
function stripPunctSpaces(s){ return (s||'').replace(/[··.,;:!?“”"'()\[\]{}<>]/g,' ').replace(/\s+/g,' ').trim(); }

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code>=0x0370 && code<=0x03FF) || (code>=0x1F00 && code<=0x1FFF);
}

function greekOnly(s){
  return Array.from(s).filter(c=>isGreekLetter(c) || c===' ' || c==='-').join('');
}

const vowelsBase = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
function isVowelBase(ch){ return vowelsBase.has(ch); }

function lastVowelIndex(word){
  const w = stripCombining(word);
  for(let i=w.length-1;i>=0;i--){
    if(isVowelBase(w[i])) return i;
  }
  return -1;
}

function penultVowelIndex(word){
  const w = stripCombining(word);
  let found = 0;
  for(let i=w.length-1;i>=0;i--){
    if(isVowelBase(w[i])){
      found++;
      if(found===2) return i;
    }
  }
  return -1;
}

function addAcuteOnVowel(word, which){
  // which: 'ultima' or 'penult'
  const wNFD = nfd(word);
  // Map indices in stripped base string to indices in NFD string
  const base = stripCombining(word);
  const targetBaseIndex = which==='penult' ? penultVowelIndex(base) : lastVowelIndex(base);
  if(targetBaseIndex<0) return word;

  // Walk through NFD, counting base letters (non-combining)
  let basePos = -1;
  let out = '';
  for(let i=0;i<wNFD.length;i++){
    const ch = wNFD[i];
    const isComb = combining.test(ch);
    combining.lastIndex = 0;
    if(!isComb){
      basePos++;
      out += ch;
      if(basePos===targetBaseIndex){
        // If next chars already include an acute, keep; else add acute.
        // We won't try to reorder perfectly; just append combining acute.
        // Avoid double acute.
        let j=i+1;
        let hasAcute=false;
        while(j<wNFD.length){
          const cj=wNFD[j];
          const isComb2 = combining.test(cj);
          combining.lastIndex = 0;
          if(!isComb2) break;
          if(cj==='\u0301') hasAcute=true;
          j++;
        }
        if(!hasAcute) out += '\u0301';
      }
    } else {
      out += ch;
    }
  }
  return out.normalize('NFC');
}

function endsWithAny(word, arr){
  const w = stripCombining(word).toLowerCase();
  return arr.some(suf => w.endsWith(suf));
}

function guessCategory(word){
  const w = stripCombining(word);
  const wl = w.toLowerCase();
  if(wl.endsWith('γων')) return 'gwn';
  if(wl.endsWith('δων')) return 'dwn';
  return 'other';
}

function toyGenitive(word){
  const w = stripCombining(word);
  const wl = w.toLowerCase();
  if(wl.endsWith('γων')){
    // -γων -> -γονος
    return w.slice(0, -3) + 'γονος';
  }
  if(wl.endsWith('δων')){
    // -δων -> -δωνος
    return w + 'ος';
  }
  // fallback: add -ος
  return w + 'ος';
}

function analyzeWord(raw){
  const cleaned = greekOnly(stripPunctSpaces(raw));
  if(!cleaned) return null;
  // analyze first token for simplicity
  const token = cleaned.split(' ')[0];
  const cat = guessCategory(token);

  let rule = '';
  let accent = null;

  if(cat==='gwn'){
    if(chkFromOs.checked){
      accent = 'penult';
      rule = 'Heuristic: treat as derivative from a compound in -ος → prefer penult accent (barytone), per Herodian’s exception.';
    } else {
      accent = 'ultima';
      rule = 'Heuristic: -γων “declined through ο” → prefer ultima accent (oxytone), per Herodian’s main statement.';
    }
  } else if(cat==='dwn'){
    // For -δων disyllables: could be either; we offer a toggle-like guess.
    // Toy: if word length is short (≈2 syllables) and contains ω before δων, guess penult; else ultima.
    const base = stripCombining(token).toLowerCase();
    const hasOmega = base.includes('ω');
    // crude syllable count: count vowels
    const vcount = Array.from(base).filter(isVowelBase).length;
    if(vcount<=2 && hasOmega){
      accent = 'penult';
      rule = 'Heuristic: disyllabic -δων with ω present → allow barytone (penult), echoing Herodian’s “keep ω in genitive” group.';
    } else {
      accent = 'ultima';
      rule = 'Heuristic: -δων can vary; defaulting to oxytone unless it looks like the special ω-group.';
    }
  } else {
    accent = 'ultima';
    rule = 'Not a target ending (-γων / -δων). Toy just adds an acute on the last vowel.';
  }

  const accented = addAcuteOnVowel(token, accent);
  const gen = toyGenitive(token);
  const genAcc = addAcuteOnVowel(gen, 'penult'); // mimic ἀρηγόνος style

  // also show the alternate accent if toggled
  const alt = addAcuteOnVowel(token, accent==='ultima' ? 'penult' : 'ultima');

  return { token, cat, accent, rule, accented, gen, genAcc, alt };
}

function render(){
  const res = analyzeWord(inp.value);
  if(!res){
    accentOut.textContent = '—';
    accentWhy.textContent = '—';
    genOut.textContent = '—';
    toggleOut.textContent = '—';
    return;
  }
  accentOut.textContent = res.accented;
  accentWhy.textContent = res.rule;
  genOut.innerHTML = `<span class="mono">${res.genAcc}</span> <span class="why">(toy genitive from ${res.token})</span>`;

  if(res.cat==='gwn'){
    toggleOut.innerHTML = `Alternate accent: <span class="mono">${res.alt}</span>`;
  } else if(res.cat==='dwn'){
    toggleOut.innerHTML = `Try another spelling (with/without ω) to see the toy flip: <span class="mono">${res.alt}</span>`;
  } else {
    toggleOut.innerHTML = `Try a word ending in <span class="mono">-γων</span> or <span class="mono">-δων</span> (e.g. <span class="mono">Παφλαγων</span>, <span class="mono">κωδων</span>).`;
  }
}

$('#btnAnalyze').addEventListener('click', render);
$('#btnClear').addEventListener('click', () => { inp.value=''; render(); inp.focus(); });
inp.addEventListener('input', () => { render(); });
chkFromOs.addEventListener('change', render);

// --- Random examples + quiz ---
const examples = [
  {w:'Παφλαγων', fromOs:false},
  {w:'Λαιστρυγων', fromOs:false},
  {w:'Πηλαγων', fromOs:false},
  {w:'ἀρηγων', fromOs:false},
  {w:'καταπυγων', fromOs:false},
  {w:'κωδων', fromOs:true},
  {w:'Φειδων', fromOs:true},
  {w:'Λαδων', fromOs:true},
  {w:'Νεδων', fromOs:true},
  {w:'Κυδων', fromOs:true},
  {w:'Μυνδων', fromOs:true},
  {w:'Σανδων', fromOs:true},
  {w:'Δωδων', fromOs:true}
];

function pickRandom(){
  const ex = examples[Math.floor(Math.random()*examples.length)];
  inp.value = ex.w;
  // only meaningful for -γων; keep checkbox as user-controlled, but nudge
  if(guessCategory(ex.w)==='gwn') chkFromOs.checked = ex.fromOs;
  render();
  inp.focus();
}
$('#btnRandom').addEventListener('click', pickRandom);

// Quiz
const quizWordEl = $('#quizWord');
const quizFeedback = $('#quizFeedback');
let quiz = null;
let picked = null;

function newQuiz(){
  const ex = examples[Math.floor(Math.random()*examples.length)];
  const cat = guessCategory(ex.w);
  // For quiz, force -γων or -δων
  if(cat==='other') return newQuiz();
  quiz = { w: ex.w, cat };
  picked = null;
  quizWordEl.textContent = stripCombining(ex.w);
  quizFeedback.textContent = 'Pick an accent, then Reveal.';
}

function expectedAccentForQuiz(w){
  const cat = guessCategory(w);
  if(cat==='gwn'){
    // quiz uses checkbox state as the scenario
    return chkFromOs.checked ? 'penult' : 'ultima';
  }
  if(cat==='dwn'){
    const base = stripCombining(w).toLowerCase();
    const hasOmega = base.includes('ω');
    const vcount = Array.from(base).filter(isVowelBase).length;
    if(vcount<=2 && hasOmega) return 'penult';
    return 'ultima';
  }
  return 'ultima';
}

function revealQuiz(){
  if(!quiz) return;
  const exp = expectedAccentForQuiz(quiz.w);
  const shown = addAcuteOnVowel(stripCombining(quiz.w), exp);
  const ok = picked && picked===exp;
  const badge = ok ? '<mark class="good">match</mark>' : '<mark class="bad">miss</mark>';
  const pickTxt = picked ? picked : '—';
  quizFeedback.innerHTML = `Expected: <span class="mono">${shown}</span> (${exp}). You picked <span class="mono">${pickTxt}</span>. ${badge}`;
}

$('#pickUlt').addEventListener('click', ()=>{ picked='ultima'; quizFeedback.textContent='Picked: ultima. Now Reveal.'; });
$('#pickPen').addEventListener('click', ()=>{ picked='penult'; quizFeedback.textContent='Picked: penult. Now Reveal.'; });
$('#reveal').addEventListener('click', revealQuiz);
$('#next').addEventListener('click', newQuiz);

// init
newQuiz();
render();

