const $ = (sel) => document.querySelector(sel);

// --- Utilities for Greek-ish processing (toy-level) ---
const COMBINING = /[\u0300-\u036f]/g;

function stripDiacritics(s){
  // NFD splits tonos etc. into combining marks; remove them.
  return (s || "").normalize('NFD').replace(COMBINING,'').normalize('NFC');
}

function lowerGreek(s){
  return stripDiacritics(s).toLowerCase();
}

const VOWELS = new Set(['α','ε','η','ι','ο','υ','ω']);

function vowelGroups(word){
  // Return array of {start,end,text} for contiguous vowel sequences.
  const w = lowerGreek(word);
  const groups = [];
  let i=0;
  while(i<w.length){
    const ch = w[i];
    if(VOWELS.has(ch)){
      let j=i+1;
      while(j<w.length && VOWELS.has(w[j])) j++;
      groups.push({start:i,end:j,text:w.slice(i,j)});
      i=j;
    } else i++;
  }
  return groups;
}

function endsWithDwn(word){
  const w = lowerGreek(word).replace(/\s+/g,'');
  return w.endsWith('δων');
}

function penultVowel(word){
  const groups = vowelGroups(word);
  if(groups.length < 2) return null;
  // penult syllable nucleus approximated as penultimate vowel-group
  const g = groups[groups.length-2].text;
  // choose last vowel of the group as a crude representative
  return g[g.length-1] || null;
}

function syllableCount(word){
  return vowelGroups(word).length;
}

function applyAcuteToVowelChar(ch){
  const map = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };
  return map[ch] || ch;
}

function accentWord(word, where){
  // where: 'ultima' or 'penult'
  // Accent the last vowel (ultima) or penultimate vowel-group's last vowel.
  const raw = (word || '').trim();
  if(!raw) return '';

  // Work on a diacritic-stripped version but preserve original casing roughly.
  // We'll accent in the stripped string, then return it.
  let w = stripDiacritics(raw);

  const groups = vowelGroups(w);
  if(groups.length === 0) return w;

  let targetGroupIndex = (where === 'penult' && groups.length >= 2) ? groups.length-2 : groups.length-1;
  const g = groups[targetGroupIndex];

  // Find last vowel char position within that group in the current string.
  let pos = g.end - 1;
  // Apply acute to that character.
  const before = w.slice(0,pos);
  const ch = w[pos];
  const after = w.slice(pos+1);
  w = before + applyAcuteToVowelChar(ch) + after;
  return w;
}

function predictAccent(word, opts){
  const o = opts || {proper:false, fem:false};
  const cleaned = (word||'').trim();
  if(!cleaned) return {ok:false, msg:"Type a Greek word ending in -δων."};
  if(!endsWithDwn(cleaned)){
    return {ok:false, msg:"This toy only handles words ending in -δων."};
  }

  const syl = syllableCount(cleaned);
  const pv = penultVowel(cleaned);

  // Defaults
  let where = 'ultima';
  let why = [];

  if(o.fem){
    where = 'ultima';
    why.push("Marked feminine → oxytone (accent on ultima). ");
  }
  if(o.proper){
    where = 'ultima';
    why.push("Marked place/ethnic → oxytone (accent on ultima). ");
  }

  if(!o.fem && !o.proper){
    if(syl <= 2){
      // Passage focuses on over-2-syllable; for 2-syllable -δων many are oxytone in examples.
      where = 'ultima';
      why.push(`≈${syl} syllable(s): toy defaults to oxytone for short -δων (matches many examples like Μυγδών, Σαρδών).`);
    } else {
      if(pv === 'ι'){
        where = 'ultima';
        why.push("Penult vowel ≈ ι → oxytone (per passage)." );
      } else if(pv === 'ο' || pv === 'α' || pv === 'υ'){
        where = 'penult';
        why.push(`Penult vowel ≈ ${pv} → paroxytone (per passage).`);
      } else {
        // η/ε/ω etc not covered in the cited rule; choose ultima but warn.
        where = 'ultima';
        why.push(`Penult vowel ≈ ${pv || '—'} not covered here → default oxytone.`);
      }
    }
  }

  return {
    ok:true,
    where,
    syllables:syl,
    penult:pv,
    explanation: why.join(' ')
  };
}

// --- UI wiring ---
const examples = [
  {w:"Μυγδων", proper:false, fem:false},
  {w:"Σαρδων", proper:false, fem:false},
  {w:"σινδων", proper:false, fem:false},
  {w:"Μαρδων", proper:false, fem:false},
  {w:"Κιναδων", proper:false, fem:false},
  {w:"Κελαδων", proper:false, fem:false},
  {w:"Παμπαδων", proper:false, fem:false},
  {w:"Κορυδων", proper:false, fem:false},
  {w:"Αμυδων", proper:true, fem:false},
  {w:"Καλυδων", proper:true, fem:false},
  {w:"Αβυδων", proper:true, fem:false},
  {w:"Απιδων", proper:true, fem:false},
  {w:"χελιδων", proper:false, fem:false},
  {w:"αηδων", proper:false, fem:true},
  {w:"τηκεδων", proper:false, fem:true},
  {w:"σηπεδων", proper:false, fem:true},
  {w:"τυφεδων", proper:false, fem:true}
];

function renderTokens(){
  const box = $('#tokens');
  box.innerHTML = '';
  examples.forEach((ex, idx) => {
    const div = document.createElement('div');
    div.className = 'token';
    div.tabIndex = 0;
    div.setAttribute('role','button');
    div.dataset.idx = idx;

    const w = document.createElement('span');
    w.className = 'w';
    w.textContent = ex.w;

    const pill = document.createElement('span');
    pill.className = 'pill';
    pill.textContent = 'click';

    div.appendChild(w);
    div.appendChild(pill);

    const act = () => {
      const pred = predictAccent(ex.w, {proper:ex.proper, fem:ex.fem});
      const pv = pred.penult || '—';
      const label = pred.ok ? `${pv} → ${pred.where}` : '—';
      pill.textContent = label;
      pill.classList.remove('good','warn','bad');
      if(!pred.ok) pill.classList.add('bad');
      else if(pred.where === 'penult') pill.classList.add('good');
      else pill.classList.add('warn');

      // Also load into main input for convenience
      $('#inp').value = ex.w;
      $('#isProper').checked = !!ex.proper;
      $('#isFem').checked = !!ex.fem;
      run();
    };

    div.addEventListener('click', act);
    div.addEventListener('keydown', (e)=>{ if(e.key==='Enter' || e.key===' ') { e.preventDefault(); act(); } });

    box.appendChild(div);
  });
}

function run(){
  const word = $('#inp').value;
  const opts = {proper: $('#isProper').checked, fem: $('#isFem').checked};
  $('#rawOut').textContent = word.trim() ? word.trim() : '—';

  const pred = predictAccent(word, opts);
  if(!pred.ok){
    $('#accentOut').textContent = '—';
    $('#ruleOut').textContent = pred.msg;
    return;
  }

  const accented = accentWord(word, pred.where);
  $('#accentOut').textContent = accented;

  const bits = [];
  bits.push(`Ends in -δων: yes.`);
  bits.push(`≈${pred.syllables} syllable(s).`);
  bits.push(`Penult vowel ≈ ${pred.penult || '—'}.`);
  bits.push(`Prediction: ${pred.where === 'ultima' ? 'oxytone (ultima)' : 'paroxytone (penult)'}.`);
  bits.push(pred.explanation);
  $('#ruleOut').textContent = bits.join(' ');
}

$('#btn').addEventListener('click', run);
$('#inp').addEventListener('keydown', (e)=>{ if(e.key==='Enter') run(); });
$('#isProper').addEventListener('change', run);
$('#isFem').addEventListener('change', run);

$('#btnRandom').addEventListener('click', ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#inp').value = ex.w;
  $('#isProper').checked = !!ex.proper;
  $('#isFem').checked = !!ex.fem;
  run();
});

renderTokens();
run();

