const $ = (sel) => document.querySelector(sel);

const examples = [
  {w:"Μακεδών", note:"simple -εδών → oxytone (acute on last)"},
  {w:"σηπεδών", note:"simple -εδών → oxytone"},
  {w:"τηκεδών", note:"simple -εδών → oxytone"},
  {w:"Λαομέδων", note:"compound -μέδων → barytone (grave on last in running text)"},
  {w:"Αὐτομέδων", note:"compound -μέδων → barytone"},
  {w:"Εὐρυμέδων", note:"compound -μέδων → barytone"},
  {w:"Καρχηδών", note:"-ηδών → oxytone"},
  {w:"Χαλκηδών", note:"-ηδών → oxytone"},
  {w:"Ἀνθηδών", note:"-ηδών → oxytone"},
  {w:"Ἀσπληδών", note:"-ηδών → oxytone"},
  {w:"Ἰσσηδών", note:"-εδών (ethnic) → oxytone"},
  {w:"Ἐσσηδών", note:"variant with ε (Alcman)"}
];

// --- Greek helpers (toy-level) ---
const COMBINING = {
  acute: "\u0301",
  grave: "\u0300",
  circumflex: "\u0342",
  diaeresis: "\u0308",
  smooth: "\u0313",
  rough: "\u0314",
  iotaSub: "\u0345"
};

function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripAccentsKeepBreathings(s){
  // remove accent marks but keep breathings/diaeresis/iota-subscript
  const d = nfd(s);
  const out = [];
  for (const ch of d){
    if (ch === COMBINING.acute || ch === COMBINING.grave || ch === COMBINING.circumflex) continue;
    out.push(ch);
  }
  return nfc(out.join(''));
}

function stripAllDiacritics(s){
  const d = nfd(s);
  const out = [];
  for (const ch of d){
    // keep only base letters and spaces/punct
    if (ch >= "\u0300" && ch <= "\u036F") continue;
    out.push(ch);
  }
  return out.join('');
}

function isGreekLetter(base){
  return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(base);
}

function lastGreekVowelIndexNFD(d){
  // Find index in NFD string of the last vowel base letter (αεηιουω + capitals)
  const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);
  // scan by code units; safe enough for Greek
  for (let i = d.length - 1; i >= 0; i--){
    const ch = d[i];
    if (vowels.has(ch)) return i;
  }
  return -1;
}

function removeAccentMarksNFD(d){
  return d.replace(/[\u0300\u0301\u0342]/g, "");
}

function applyAccent(word, kind){
  // kind: 'acute' | 'grave'
  // Place accent on the last vowel of the word (toy). Preserve other diacritics.
  let d = nfd(word);
  d = removeAccentMarksNFD(d);
  const idx = lastGreekVowelIndexNFD(d);
  if (idx === -1) return word;
  const mark = kind === 'grave' ? COMBINING.grave : COMBINING.acute;
  // insert mark after the vowel base letter, but after any existing combining marks already attached to it
  // Find insertion point: after vowel and any following combining marks
  let j = idx + 1;
  while (j < d.length && d.charCodeAt(j) >= 0x0300 && d.charCodeAt(j) <= 0x036F) j++;
  d = d.slice(0, j) + mark + d.slice(j);
  return nfc(d);
}

function endsWithAny(base, arr){
  return arr.some(suf => base.endsWith(suf));
}

function guessType(word){
  const base = stripAllDiacritics(word).replace(/[^\p{L}]+/gu, "");
  const lower = base.toLowerCase();

  const endings = {
    edon: ["εδων"],
    edonOmega: ["εδων", "εδων"],
    hdon: ["ηδων"],
    medon: ["μεδων"]
  };

  const hasMedon = lower.includes("μεδων");
  const endsEdon = endsWithAny(lower, endings.edon);
  const endsHdon = endsWithAny(lower, endings.hdon);
  const endsMedon = endsWithAny(lower, endings.medon);

  // crude compound heuristic: something before μεδων and not starting with μεδων
  const compoundMedon = hasMedon && !lower.startsWith("μεδων") && lower.indexOf("μεδων") > 0;

  return { lower, endsEdon, endsHdon, endsMedon, compoundMedon };
}

function guessGenitive(nom){
  // toy: if ends in -δών/-δων (with omega), make -δόνος
  // We'll operate on accent-stripped but keep breathings.
  const clean = stripAccentsKeepBreathings(nom);
  const base = stripAllDiacritics(clean);
  const lower = base.toLowerCase();

  // Find last occurrence of "δων" (don) and replace with "δονος".
  // Keep original letters as much as possible by slicing original string by length.
  // We'll do a simple approach on diacritic-stripped string and rebuild from that.
  if (lower.endsWith("δων")){
    const stem = clean.slice(0, clean.length - 3);
    // add δονος with acute on ο (δόνος)
    return stem + applyAccent("δονος", 'acute');
  }
  return "(no guess)";
}

function buildSuggestions(word){
  const s = [];
  s.push({label:"acute on last (oxytone)", form: applyAccent(word, 'acute')});
  s.push({label:"grave on last (barytone-ish)", form: applyAccent(word, 'grave')});
  s.push({label:"no accents (strip)", form: stripAccentsKeepBreathings(word)});
  return s;
}

function analyze(){
  const input = $('#in').value.trim();
  if (!input){
    renderEmpty();
    return;
  }

  const g = guessType(input);

  let rule = "";
  let proposed = input;
  let badge = {text:"heuristic", cls:""};

  if ((g.endsEdon || g.endsHdon) && !g.compoundMedon){
    rule = "Looks like a simple word in <mark>-εδών</mark> or <mark>-ηδών</mark> → propose <b>oxytone</b> (acute on last).";
    proposed = applyAccent(input, 'acute');
    badge = {text:"simple → oxytone", cls:"ok"};
  } else if (g.compoundMedon || g.endsMedon){
    rule = "Looks like a compound in <mark>-μέδων</mark> → propose <b>barytone</b> (grave on last in running text).";
    proposed = applyAccent(input, 'grave');
    badge = {text:"compound → barytone", cls:"warn"};
  } else {
    rule = "No clear -εδών/-ηδών/-μέδων signal found. Try one of the examples.";
    proposed = applyAccent(input, 'acute');
    badge = {text:"unclear", cls:""};
  }

  $('#pretty').innerHTML = `${escapeHTML(proposed)} <span class="badge ${badge.cls}">${escapeHTML(badge.text)}</span>`;
  $('#meta').innerHTML = rule + `<br><span class="small">Toy check: ending flags — -εδων: <b>${g.endsEdon}</b>, -ηδων: <b>${g.endsHdon}</b>, contains -μεδων: <b>${g.lower.includes('μεδων')}</b>.</span>`;

  // chips
  const sugg = buildSuggestions(input);
  const chips = $('#chips');
  chips.innerHTML = "";
  for (const item of sugg){
    const div = document.createElement('div');
    div.className = 'chip';
    div.title = item.label;
    div.textContent = item.form;
    div.addEventListener('click', () => {
      $('#in').value = item.form;
      analyze();
    });
    chips.appendChild(div);
  }

  // genitive
  $('#nom').textContent = proposed;
  $('#gen').textContent = guessGenitive(proposed);

  // omega toggle note
  $('#omegaNote').textContent = omegaTogglePreview(proposed);
}

function omegaTogglePreview(word){
  // If ends with δών/δων, show swapped ω/ο in the last syllable (toy)
  const d = stripAccentsKeepBreathings(word);
  const base = stripAllDiacritics(d).toLowerCase();
  if (!base.endsWith("δων")) return "(Tip: try a word ending in -δών.)";

  // Find last omega/omicron in the last 3 letters of the diacritic-stripped form
  // We'll do a simple character replacement on NFC string: replace last ω with ο or last ο with ω.
  let swapped = d;
  // Prefer swapping ω if present
  const idxOmega = swapped.lastIndexOf("ω");
  const idxOmicron = swapped.lastIndexOf("ο");
  if (idxOmega !== -1 && idxOmega > swapped.length - 6){
    swapped = swapped.slice(0, idxOmega) + "ο" + swapped.slice(idxOmega + 1);
  } else if (idxOmicron !== -1 && idxOmicron > swapped.length - 6){
    swapped = swapped.slice(0, idxOmicron) + "ω" + swapped.slice(idxOmicron + 1);
  } else {
    return "(Couldn’t find ω/ο near the end to toggle.)";
  }
  // keep same accent idea: re-apply acute on last vowel
  const reaccent = applyAccent(swapped, 'acute');
  return `Toggle preview: ${word} → ${reaccent}`;
}

function toggleOmega(){
  const input = $('#in').value.trim();
  if (!input) return;
  let s = input;
  // swap last ω/ο in the final -δων region
  const tailWindow = 8;
  const start = Math.max(0, s.length - tailWindow);
  const head = s.slice(0, start);
  let tail = s.slice(start);

  const iOmega = tail.lastIndexOf("ω");
  const iOmicron = tail.lastIndexOf("ο");
  if (iOmega !== -1){
    tail = tail.slice(0, iOmega) + "ο" + tail.slice(iOmega + 1);
  } else if (iOmicron !== -1){
    tail = tail.slice(0, iOmicron) + "ω" + tail.slice(iOmicron + 1);
  } else {
    // nothing to toggle
    return;
  }
  $('#in').value = head + tail;
  analyze();
}

function renderEmpty(){
  $('#pretty').textContent = '—';
  $('#meta').innerHTML = 'Type a word and click <b>Analyze</b>.';
  $('#chips').innerHTML = '';
  $('#nom').textContent = '—';
  $('#gen').textContent = '—';
  $('#omegaNote').textContent = '—';
}

function escapeHTML(s){
  return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function randomExample(){
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#in').value = ex.w;
  analyze();
  // add a little extra hint
  const meta = $('#meta');
  meta.innerHTML += `<br><span class="small">Example note: ${escapeHTML(ex.note)}.</span>`;
}

$('#analyze').addEventListener('click', analyze);
$('#random').addEventListener('click', randomExample);
$('#clear').addEventListener('click', () => { $('#in').value=''; renderEmpty(); $('#in').focus(); });
$('#toggleOmega').addEventListener('click', toggleOmega);
$('#in').addEventListener('keydown', (e) => { if (e.key === 'Enter') analyze(); });

// seed
$('#in').value = 'Καρχηδών';
analyze();

