const $ = (s)=>document.querySelector(s);

const examples = [
  "Σαρπηδών",
  "Ἀκήδων",
  "Θερμώδων",
  "Χαλκώδων",
  "κρατερώδων",
  "Ἁλίζων",
  "Ῥίζων",
  "Ὄζων",
  "Ἄζων",
  "Ὑψίζων",
  "Ἴσσηδοι",
  "Ἰσσηδών"
];

function stripDiacritics(str){
  // Remove combining marks; keep base Greek letters.
  return str.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function hasAccent(str){
  const n = str.normalize('NFD');
  return /[\u0301\u0342\u0300]/.test(n); // acute, circumflex, grave
}

function lastVowelIndex(word){
  const w = stripDiacritics(word);
  const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);
  for(let i=w.length-1;i>=0;i--){
    if(vowels.has(w[i])) return i;
  }
  return -1;
}

function nthVowelFromEndIndex(word, n){
  const w = stripDiacritics(word);
  const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);
  let count=0;
  for(let i=w.length-1;i>=0;i--){
    if(vowels.has(w[i])){
      count++;
      if(count===n) return i;
    }
  }
  return -1;
}

function addAcuteOnVowel(word, vowelIndex){
  if(vowelIndex<0) return word;
  // Insert combining acute after the vowel character.
  const chars = Array.from(word);
  // Map index in stripped string to index in original by scanning base letters.
  const stripped = Array.from(stripDiacritics(word));
  let basePos=-1;
  let origPos=-1;
  for(let i=0;i<chars.length;i++){
    const base = stripDiacritics(chars[i]);
    if(base.length===1 && base === stripped[basePos+1]){
      basePos++;
      if(basePos===vowelIndex){ origPos=i; break; }
    }
  }
  if(origPos<0) return word;
  // If the character already has combining marks (rare in precomposed), normalize to NFD and add.
  const before = word.slice(0, origPos+1);
  const after = word.slice(origPos+1);
  return (before.normalize('NFD') + "\u0301" + after.normalize('NFD')).normalize('NFC');
}

function classify(word){
  const w = stripDiacritics(word.trim());
  const lower = w.toLowerCase();

  const res = {type:"other", note:"", ending:""};

  if(lower.endsWith("ηδων") || lower.endsWith("εδων")){
    res.type = "-ηδων/-εδων";
    res.ending = w.slice(-4);
    res.note = "Herodian mentions Σαρπήδων/Ἀκήδων: gen. -οντος, barytone.";
    return res;
  }
  if(lower.endsWith("ωδων")){
    res.type = "-ωδων";
    res.ending = w.slice(-4);
    res.note = "Herodian: names in -ωδων are barytone (e.g. Θερμώδων).";
    return res;
  }
  if(lower.endsWith("ζων")){
    res.type = "-ζων";
    res.ending = w.slice(-3);
    res.note = "Herodian: many masc. in -ζων are barytone under certain conditions.";
    return res;
  }
  if(lower.endsWith("δοι")){
    res.type = "plural ethnicon?";
    res.ending = w.slice(-3);
    res.note = "Herodian notes Ἴσσηδοι as trisyllabic (ethnic plural).";
    return res;
  }
  return res;
}

function makeGenitiveOntos(word){
  // Very rough: replace final -δων with -δοντος (keeping preceding consonants).
  const raw = word.trim();
  const w = stripDiacritics(raw);
  const lower = w.toLowerCase();
  if(!(lower.endsWith("ηδων") || lower.endsWith("εδων"))) return null;

  // Find the last 4 base letters in the original and replace them.
  const base = stripDiacritics(raw);
  const stemBase = base.slice(0, -4);
  // Rebuild using original prefix (best-effort): take same length prefix from raw stripped mapping.
  // Simpler: operate on stripped and then return stripped; then re-accent barytone-ish.
  let gen = stemBase + "δοντος";

  // Add a plausible accent on the penult of the genitive (e.g. Σαρπήδοντος).
  const penultV = nthVowelFromEndIndex(gen, 2);
  gen = addAcuteOnVowel(gen, penultV);
  return gen;
}

function accentGuess(word, pref){
  const raw = word.trim();
  if(!raw) return "";
  if(hasAccent(raw) && pref===2) return raw;

  // If already accented, keep it (toy is about classification more than correction).
  if(hasAccent(raw)) return raw;

  // Add an acute either on penult (pref=0) or antepenult (pref=1) when possible.
  let targetVowel = -1;
  if(pref===0) targetVowel = nthVowelFromEndIndex(raw, 2);
  else if(pref===1) targetVowel = nthVowelFromEndIndex(raw, 3);
  else targetVowel = nthVowelFromEndIndex(raw, 2);

  if(targetVowel<0) targetVowel = lastVowelIndex(raw);
  return addAcuteOnVowel(raw, targetVowel);
}

function render(){
  const inp = $("#inp").value;
  const mode = document.querySelector('input[name="mode"]:checked').value;
  const pref = parseInt($("#pref").value,10);

  const out = $("#out");
  if(!inp.trim()){
    out.innerHTML = `<div class="tiny">Type a Greek word above, or click an example chip.</div>`;
    return;
  }

  const info = classify(inp);
  const guessed = accentGuess(inp, pref);
  const gen = makeGenitiveOntos(guessed);

  const tags = [];
  if(info.type !== "other") tags.push(`<span class="tag good">pattern: ${escapeHtml(info.type)}</span>`);
  else tags.push(`<span class="tag warn">pattern: (not recognized)</span>`);

  tags.push(`<span class="tag">ending: <span class="mono">${escapeHtml(info.ending || "—")}</span></span>`);
  tags.push(`<span class="tag">accent in input: <span class="mono">${hasAccent(inp)?"yes":"no"}</span></span>`);

  let main = "";
  if(mode==="guess" || mode==="both"){
    main += `<div class="big">${escapeHtml(guessed)}</div>`;
  }

  let extra = "";
  if(mode==="decl" || mode==="both"){
    if(gen){
      extra += `<div><span class="mono">gen. sg.</span> (toy): <b>${escapeHtml(gen)}</b></div>`;
    } else {
      extra += `<div class="tiny">Declension hint appears for -ηδων/-εδων → gen. -οντος.</div>`;
    }
  }

  const note = info.note ? `<div class="tiny" style="margin-top:8px">${escapeHtml(info.note)}</div>` : "";

  out.innerHTML = `${main}<div>${tags.join(" ")}</div>${extra}${note}`;
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function initChips(){
  const box = $("#chips");
  box.innerHTML = "";
  for(const ex of examples){
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip';
    b.textContent = ex;
    b.addEventListener('click', ()=>{ $("#inp").value = ex; render(); $("#inp").focus(); });
    box.appendChild(b);
  }
}

$("#inp").addEventListener('input', render);
for(const r of document.querySelectorAll('input[name="mode"]')) r.addEventListener('change', render);
$("#pref").addEventListener('input', render);

initChips();
render();

