const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => Array.from(document.querySelectorAll(sel));

const inp = $('#inp');

// --- Greek helpers (toy-level) ---
// We strip combining marks and also precomposed tonos/oxia variants by NFD.
function stripDiacritics(s){
  return (s || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'')
    .normalize('NFC');
}

function findAccentTypes(s){
  const n = (s||'').normalize('NFD');
  const hasAcute = /\u0301/.test(n); // oxia/tonos
  const hasGrave = /\u0300/.test(n);
  const hasCirc = /\u0342/.test(n);
  const hasDia = /\u0308/.test(n);
  const parts = [];
  if(hasAcute) parts.push('acute (´)');
  if(hasGrave) parts.push('grave (`)');
  if(hasCirc) parts.push('circumflex (ˆ)');
  if(hasDia) parts.push('diaeresis (¨)');
  return parts.length ? parts.join(', ') : 'none detected';
}

const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

function lastVowelIndex(s){
  // Work in NFD so we can insert combining acute after the vowel base.
  const n = (s||'').normalize('NFD');
  // Build mapping from NFD indices to NFC-ish "base letters" positions.
  // We'll just scan NFD and treat Greek vowel base chars as targets.
  for(let i=n.length-1;i>=0;i--){
    const ch = n[i];
    if(vowels.has(ch)) return i;
  }
  return -1;
}

function makeOxytone(s){
  if(!s) return '';
  let n = stripDiacritics(s).normalize('NFD');
  const i = lastVowelIndex(n);
  if(i<0) return stripDiacritics(s);
  // Insert combining acute after the vowel.
  n = n.slice(0,i+1) + '\u0301' + n.slice(i+1);
  return n.normalize('NFC');
}

function penultVowelIndex(s){
  const n = stripDiacritics(s).normalize('NFD');
  let seen = 0;
  for(let i=n.length-1;i>=0;i--){
    const ch = n[i];
    if(vowels.has(ch)){
      seen++;
      if(seen===2) return i;
    }
  }
  return -1;
}

function makePenultAcute(s){
  if(!s) return '';
  let n = stripDiacritics(s).normalize('NFD');
  const i = penultVowelIndex(n);
  if(i<0) return makeOxytone(s);
  n = n.slice(0,i+1) + '\u0301' + n.slice(i+1);
  return n.normalize('NFC');
}

function endingOf(s){
  const b = stripDiacritics((s||'').trim());
  const low = b.toLowerCase();
  if(low.endsWith('ζων')) return '-ζων';
  if(low.endsWith('θων')) return '-θων';
  return (b.length>=3 ? b.slice(-3) : b) || '—';
}

function looksLikeThwn(s){
  const b = stripDiacritics((s||'').trim()).toLowerCase();
  return b.endsWith('θων');
}

function update(){
  const s = (inp.value||'').trim();
  $('#typed').textContent = s || '—';
  $('#bare').textContent = s ? stripDiacritics(s) : '—';
  $('#accents').textContent = s ? findAccentTypes(s) : '—';
  $('#ending').textContent = s ? endingOf(s) : '—';

  const stripped = s ? stripDiacritics(s) : '';
  $('#stripped').textContent = s ? stripped : '—';
  $('#oxy').textContent = s ? makeOxytone(s) : '—';

  const th = s ? looksLikeThwn(s) : false;
  $('#thwn').innerHTML = s ? (th ? '<span class="good">yes</span>' : 'no') : '—';
  if(!s){
    $('#thwnSug').textContent = '—';
  } else if(th){
    const sug = makePenultAcute(s);
    $('#thwnSug').textContent = `${sug}  (toy “βαρύνεται” guess)`;
  } else {
    $('#thwnSug').textContent = '—';
  }
}

$('#analyze').addEventListener('click', update);
$('#clear').addEventListener('click', () => { inp.value=''; update(); inp.focus(); });

$('#strip').addEventListener('click', () => {
  inp.value = stripDiacritics(inp.value.trim());
  update();
});

$('#oxytone').addEventListener('click', () => {
  inp.value = makeOxytone(inp.value.trim());
  update();
});

$('#compare').addEventListener('click', () => {
  const base = stripDiacritics(inp.value.trim() || 'ὀλιζων');
  const low = base.toLowerCase();
  const out = $('#quizout');
  if(low !== 'ολιζων'){
    out.innerHTML = `Try the letters <span class="mono">ὀλιζων</span> (no accents). Your current stripped form is <span class="mono">${base || '—'}</span>.`;
    return;
  }
  out.innerHTML = `Same letters, two readings:<br>
  • <span class="mono">ὀλίζων</span> = “fewer” (as in <span class="mono">λαοὶ δ’ ὑπ’ ὀλίζονες ἦσαν</span>)<br>
  • <span class="mono">Ὀλιζών</span> = place-name (Thessaly), oxytone by contrast.`;
});

$$('.ex').forEach(el => {
  el.addEventListener('click', () => {
    inp.value = el.getAttribute('data-fill');
    update();
    inp.focus();
  });
});

$$('.q').forEach(btn => {
  btn.addEventListener('click', () => {
    const out = $('#quizout');
    const base = btn.textContent.trim();
    if(base.toLowerCase() === 'ολιζων'){
      out.innerHTML = `You clicked <span class="mono">${base}</span> (unaccented). Herodian’s contrast is:<br>
      • <span class="mono">ὀλίζων</span> (common word “fewer”)<br>
      • <span class="mono">Ὀλιζών</span> (city-name, oxytone).<br>
      Now try pressing “Make oxytone” on <span class="mono">ὀλιζων</span>.`;
    } else {
      out.textContent = 'Pick one of the unaccented buttons.';
    }
  });
});

// Live update on typing (but keep button too)
inp.addEventListener('input', update);

update();

