const $ = (id)=>document.getElementById(id);

// --- Greek utilities (toy-level) ---
const tonosMap = {
  "ά":"α","έ":"ε","ή":"η","ί":"ι","ό":"ο","ύ":"υ","ώ":"ω",
  "Ά":"Α","Έ":"Ε","Ή":"Η","Ί":"Ι","Ό":"Ο","Ύ":"Υ","Ώ":"Ω",
  "ὰ":"α","ά":"α","ὲ":"ε","έ":"ε","ὴ":"η","ή":"η","ὶ":"ι","ί":"ι","ὸ":"ο","ό":"ο","ὺ":"υ","ύ":"υ","ὼ":"ω","ώ":"ω",
  "ᾶ":"α","ῆ":"η","ῖ":"ι","ῦ":"υ","ῶ":"ω",
  "Ὰ":"Α","Ά":"Α","Ὲ":"Ε","Έ":"Ε","Ὴ":"Η","Ή":"Η","Ὶ":"Ι","Ί":"Ι","Ὸ":"Ο","Ό":"Ο","Ὺ":"Υ","Ύ":"Υ","Ὼ":"Ω","Ώ":"Ω",
  "ϊ":"ι","ΐ":"ι","ϋ":"υ","ΰ":"υ","ῒ":"ι","ΐ":"ι","ῢ":"υ","ΰ":"υ","ῗ":"ι","ῧ":"υ",
  "ᾳ":"α","ᾴ":"α","ᾲ":"α","ᾷ":"α","ᾀ":"α","ᾁ":"α","ᾂ":"α","ᾃ":"α","ᾄ":"α","ᾅ":"α","ᾆ":"α","ᾇ":"α",
  "ῃ":"η","ῄ":"η","ῂ":"η","ῇ":"η",
  "ῳ":"ω","ῴ":"ω","ῲ":"ω","ῷ":"ω"
};

function stripAccents(s){
  return Array.from(s).map(ch => tonosMap[ch] ?? ch).join("");
}

const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);

function roughSyllables(s){
  // Very rough: count vowel groups after stripping accents.
  const t = stripAccents(s);
  let count = 0;
  let prevV = false;
  for (const ch of Array.from(t)){
    const isV = vowels.has(ch);
    if (isV && !prevV) count++;
    prevV = isV;
  }
  return Math.max(1, count);
}

function lastVowelIndex(s){
  const arr = Array.from(s);
  for (let i=arr.length-1;i>=0;i--){
    const base = stripAccents(arr[i]);
    if (vowels.has(base)) return i;
  }
  return -1;
}

function addAcuteOnLastVowel(s){
  const arr = Array.from(stripAccents(s));
  const i = lastVowelIndex(arr.join(""));
  if (i<0) return s;
  const ch = arr[i];
  const acute = {
    "α":"ά","ε":"έ","η":"ή","ι":"ί","ο":"ό","υ":"ύ","ω":"ώ",
    "Α":"Ά","Ε":"Έ","Η":"Ή","Ι":"Ί","Ο":"Ό","Υ":"Ύ","Ω":"Ώ"
  };
  arr[i] = acute[ch] ?? ch;
  return arr.join("");
}

function addCircumflexOnOmega(s){
  // Only tries to circumflex the last omega/Ω; otherwise falls back to acute.
  const arr = Array.from(stripAccents(s));
  for (let i=arr.length-1;i>=0;i--){
    if (arr[i]==="ω") { arr[i] = "ῶ"; return arr.join(""); }
    if (arr[i]==="Ω") { arr[i] = "ῶ"; return arr.join(""); } // crude
  }
  return addAcuteOnLastVowel(s);
}

function detectEnding(s){
  const t = stripAccents(s).trim();
  const low = t.toLowerCase();
  if (low.endsWith("θων")) return "-θων";
  if (low.endsWith("κων")) return "-κων";
  return "(other)";
}

function toyGenitive(s, ending, ntDecl){
  const base = stripAccents(s).trim();
  if (!ntDecl) return "—";
  // crude: replace final ν with ντος if ends with -ων
  const low = base.toLowerCase();
  if (low.endsWith("ων")){
    return base.slice(0, -1) + "ντος";
  }
  return base + " (gen?)";
}

function guessAccent(word, hints){
  const clean = stripAccents(word.trim());
  const ending = detectEnding(clean);
  const syl = roughSyllables(clean);

  let trace = [];
  let suggested = clean;
  let label = "—";

  if (ending === "-θων"){
    if (syl <= 2){
      label = "acute (oxytone)";
      suggested = addAcuteOnLastVowel(clean);
      trace.push("-θων disyllables: Herodian lists Πυθών, Σιθών, πιθών, κιθών as oxytone (acute). (Toy: acute on last vowel.)");
    } else {
      // Herodian: >2 syllables tend to be barytone unless place/mountain OR -ντ- and keeps ω.
      if (hints.ntDecl && hints.keepOmega){
        label = "circumflex (special -ντ- + ω)";
        suggested = addCircumflexOnOmega(clean);
        trace.push("-θων >2 syllables: exception when it declines with -ντ- and preserves nominative ω; cf. Ἱπποθῶν. (Toy: circumflex on ω.)");
      } else if (hints.isPlace){
        label = "acute (place/mountain exception)";
        suggested = addAcuteOnLastVowel(clean);
        trace.push("-θων >2 syllables: place/mountain names can behave differently (e.g. Μαραθών, Ἀργανθών). (Toy: make it oxytone.)");
      } else {
        label = "grave/barytone (toy: leave unaccented)";
        suggested = clean;
        trace.push("-θων >2 syllables: ‘βαρύνεται’ unless it’s a place/mountain or -ντ- + keeps ω. (Toy: we don’t compute a full barytone accent, so we leave it plain.)");
        trace.push("Try ticking ‘place/mountain’ or ‘-ντ- declension’ + ‘keeps ω’ to see other outcomes.");
      }
    }
  } else if (ending === "-κων"){
    if (syl <= 2){
      if (hints.isCollective || hints.isBody){
        label = "acute (collective/body-part)";
        suggested = addAcuteOnLastVowel(clean);
        trace.push("-κων disyllabic: usually barytone, but collectives (κροκών, πευκών, χαλκών) and body-parts (ἀγκών) are oxytone. (Toy: acute.)");
      } else {
        label = "grave/barytone (toy: leave unaccented)";
        suggested = clean;
        trace.push("-κων disyllabic masculine: ‘βαρύνεται’ when not collective and not body-part. (Toy: we leave it plain rather than placing a specific barytone accent.)");
        trace.push("Tick ‘collective’ or ‘body-part’ to flip it to oxytone.");
      }
    } else {
      // Herodian: >2 syllables can be acute/grave/circumflex.
      if (hints.ntDecl && hints.keepOmega){
        label = "circumflex (toy guess)";
        suggested = addCircumflexOnOmega(clean);
        trace.push("-κων >2 syllables: Herodian allows acute/grave/circumflex. With -ντ- + ω preserved, the toy guesses circumflex.");
      } else if (hints.isCollective || hints.isBody || hints.isPlace){
        label = "acute (toy guess)";
        suggested = addAcuteOnLastVowel(clean);
        trace.push("-κων >2 syllables: multiple accents occur; with your hint (collective/body/place), the toy guesses oxytone.");
      } else {
        label = "varies (toy default: acute)";
        suggested = addAcuteOnLastVowel(clean);
        trace.push("-κων >2 syllables: Herodian says acute, grave, and circumflex all occur. With no hint, the toy defaults to acute so you see a visible change.");
      }
    }
  } else {
    label = "(no rule)";
    suggested = addAcuteOnLastVowel(clean);
    trace.push("This toy focuses on -θων and -κων. For other words it just adds an acute on the last vowel so you still get a transformation.");
  }

  return {ending, syl, label, suggested, trace};
}

const examples = [
  {w:"Πυθων", h:{}},
  {w:"Σιθων", h:{}},
  {w:"Ιπποθων", h:{ntDecl:true, keepOmega:true}},
  {w:"Μαραθων", h:{isPlace:true}},
  {w:"Αργανθων", h:{isPlace:true}},
  {w:"δρακων", h:{}},
  {w:"κροκων", h:{isCollective:true}},
  {w:"αγκων", h:{isBody:true}},
  {w:"Περιφλεγεθων", h:{}},
  {w:"Φαεθων", h:{ntDecl:true}} // just to show genitive toggle
];

function readHints(){
  return {
    isPlace: $("isPlace").checked,
    isCollective: $("isCollective").checked,
    isBody: $("isBody").checked,
    ntDecl: $("ntDecl").checked,
    keepOmega: $("keepOmega").checked
  };
}

function applyHints(h){
  $("isPlace").checked = !!h.isPlace;
  $("isCollective").checked = !!h.isCollective;
  $("isBody").checked = !!h.isBody;
  $("ntDecl").checked = !!h.ntDecl;
  $("keepOmega").checked = !!h.keepOmega;
}

function run(){
  const word = $("w").value;
  const hints = readHints();
  const res = guessAccent(word, hints);
  $("ending").textContent = res.ending;
  $("syll").textContent = String(res.syl);
  $("accent").textContent = res.suggested + "  —  " + res.label;
  $("gen").textContent = toyGenitive(word, res.ending, hints.ntDecl);
  $("trace").innerHTML = "<ol>" + res.trace.map(t=>"<li>"+escapeHtml(t)+"</li>").join("") + "</ol>";
}

function escapeHtml(s){
  return s.replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;");
}

$("go").addEventListener("click", run);
$("w").addEventListener("keydown", (e)=>{ if(e.key==="Enter") run(); });

$("rand").addEventListener("click", ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $("w").value = ex.w;
  applyHints(ex.h);
  run();
});

// Auto-run once with a default
$("w").value = "Ιπποθων";
applyHints({ntDecl:true, keepOmega:true});
run();

