const $ = (s)=>document.querySelector(s);
const inEl = $('#in');
const outWord = $('#outWord');
const outMeta = $('#outMeta');
const det = $('#det');
const chips = $('#chips');
const modeEl = $('#mode');
const dialEl = $('#dial');

// A few examples from the passage, tagged as local/nonlocal for the toy.
const lex = new Map([
  ['αὐλων','local'], ['αὐλών','local'], ['Αὐλών','local'],
  ['πυλων','local'], ['πυλών','local'],
  ['μυλων','local'], ['μυλών','local'],
  ['Ἀσκάλων','local'], ['Ασκαλων','local'], ['ασκαλων','local'],
  ['Μίλων','nonlocal'], ['Μιλων','nonlocal'], ['μιλων','nonlocal'],
  ['Σόλων','nonlocal'], ['Σολων','nonlocal'], ['σολων','nonlocal'],
  ['Χίλων','nonlocal'], ['Χιλων','nonlocal'], ['χιλων','nonlocal'],
  ['Ἱπποκῶν','nonlocal'], ['Λαοκῶν','nonlocal'], ['Καλλικῶν','nonlocal'], ['Δηϊκῶν','nonlocal'],
  ['γυναικών','local'], ['Ἑλικών','local'],
  ['Τριάκων','nonlocal'], ['σαλάκων','nonlocal'], ['Αἰολοσίκων','nonlocal']
]);

const punctRE = /[··.,;:!?()\[\]{}«»“”"'’—–…]/g;

function stripPunct(s){return s.replace(punctRE,' ').replace(/\s+/g,' ').trim();}

function lastTargetToken(input){
  const clean = stripPunct(input);
  if(!clean) return null;
  const toks = clean.split(' ');
  // find last token that ends with κων/λων (with or without accents)
  for(let i=toks.length-1;i>=0;i--){
    const t = toks[i];
    const bare = removeDiacritics(t);
    if(bare.endsWith('κων') || bare.endsWith('λων')) return t;
  }
  return null;
}

// Remove Greek combining marks + precomposed tonos/varia/perispomeni by NFD stripping.
function removeDiacritics(s){
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function isGreekVowel(ch){
  const b = removeDiacritics(ch);
  return 'αεηιουωΑΕΗΙΟΥΩ'.includes(b);
}

function findLastVowelIndex(word){
  // iterate codepoints
  const arr = Array.from(word);
  for(let i=arr.length-1;i>=0;i--){
    if(isGreekVowel(arr[i])) return i;
  }
  return -1;
}

function applyAccentToVowel(vowelChar, accent, style){
  // accent: 'acute' | 'grave' | 'circ'
  // style: 'poly' | 'mono'
  const base = removeDiacritics(vowelChar);
  const isUpper = base === base.toUpperCase() && base !== base.toLowerCase();

  // combining marks
  const COMB = {
    acute: '\u0301',
    grave: '\u0300',
    circ:  '\u0342'
  };

  let mark = COMB[accent];
  if(style === 'mono'){
    // monotonic: only tonos (acute). For "grave" and "circ" we still show acute.
    mark = COMB.acute;
  }

  // Preserve existing diaeresis if present (ϊ/ϋ/ΐ/ΰ etc.) by decomposing and reassembling.
  const nfd = vowelChar.normalize('NFD');
  const hasDia = nfd.includes('\u0308');
  const dia = hasDia ? '\u0308' : '';

  // Build: base + diaeresis (if any) + accent mark
  const out = (base + dia + mark).normalize('NFC');
  // Keep original case
  return isUpper ? out.toUpperCase() : out;
}

function accentWord(word, localness, style){
  const arr = Array.from(word);
  const vi = findLastVowelIndex(word);
  if(vi < 0) return {word, changed:false, why:'No vowel found.'};

  const accent = (localness === 'local') ? 'acute' : 'grave';
  arr[vi] = applyAccentToVowel(arr[vi], accent, style);
  return {word: arr.join(''), changed:true, accent};
}

function guessLocalness(input, token){
  const mode = modeEl.value;
  if(mode === 'local') return {localness:'local', reason:'Forced LOCAL by you.'};
  if(mode === 'nonlocal') return {localness:'nonlocal', reason:'Forced NOT local by you.'};

  // auto
  if(lex.has(token)){
    const v = lex.get(token);
    return {localness:v, reason:`Found in toy list as ${v.toUpperCase()}.`};
  }
  const bareTok = removeDiacritics(token);
  if(lex.has(bareTok)){
    const v = lex.get(bareTok);
    return {localness:v, reason:`Matched toy list (ignoring accents) as ${v.toUpperCase()}.`};
  }

  const clean = stripPunct(input);
  if(/\b(πόλις|πολις|τόπος|τοπος)\b/.test(clean)){
    return {localness:'local', reason:'Phrase contains πόλις/τόπος → guessed LOCAL.'};
  }

  // weak heuristic: if token ends -λων and looks like a place-name in -ων with omega in last syllable in input, guess local
  if(/[ώώῶ]/.test(token) && removeDiacritics(token).endsWith('λων')){
    return {localness:'local', reason:'Has ω-accented ending and -λων → guessed LOCAL (toy heuristic).'};
  }

  return {localness:'nonlocal', reason:'Default guess: NOT local.'};
}

function renderChips(token, localness, style){
  chips.innerHTML = '';
  const vi = findLastVowelIndex(token);
  const arr = Array.from(token);
  const v = vi>=0 ? arr[vi] : '';
  const base = v ? removeDiacritics(v) : '';

  const acute = v ? applyAccentToVowel(v,'acute',style) : '';
  const grave = v ? applyAccentToVowel(v,'grave',style) : '';
  const circ  = v ? applyAccentToVowel(v,'circ',style) : '';

  const mk = (label, val, on)=>{
    const d = document.createElement('div');
    d.className = 'chip';
    d.innerHTML = `${label}: <b>${val || '—'}</b>` + (on? ' ✓':'' );
    chips.appendChild(d);
  };
  mk('base', base, false);
  mk('acute', acute, localness==='local');
  mk('grave', grave, localness!=='local' && style==='poly');
  mk('circ', circ, false);
}

function update(){
  const input = inEl.value;
  const token = lastTargetToken(input);
  const style = dialEl.value;

  if(!token){
    outWord.textContent = '—';
    outMeta.textContent = 'Type something ending in -κων or -λων (or a phrase containing one).';
    det.textContent = 'No target token found.';
    chips.innerHTML = '';
    return;
  }

  const bare = removeDiacritics(token);
  const ending = bare.endsWith('κων') ? '-κων' : (bare.endsWith('λων') ? '-λων' : '—');

  const {localness, reason} = guessLocalness(input, token);
  const acc = accentWord(token, localness, style);

  outWord.textContent = acc.word;
  outMeta.textContent = `${localness === 'local' ? 'LOCAL → acute on last vowel' : 'NOT local → grave (toy barytone) on last vowel'} · ${reason}`;

  det.textContent = [
    `token: ${token}`,
    `token (no diacritics): ${bare}`,
    `ending: ${ending}`,
    `rule applied: ${localness}`
  ].join('\n');

  renderChips(token, localness, style);
}

$('#apply').addEventListener('click', update);
$('#clear').addEventListener('click', ()=>{inEl.value=''; update(); inEl.focus();});

const examples = [
  'Μίλων',
  'αυλων',
  'Αὐλών πόλις',
  'πυλων',
  'Ἱπποκῶν',
  'Ἀσκάλων',
  'Τριάκων',
  'γυναικών'
];
$('#random').addEventListener('click', ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  inEl.value = ex;
  update();
});

document.querySelectorAll('.pill').forEach(b=>{
  b.addEventListener('click', ()=>{
    inEl.value = b.dataset.snip;
    update();
    inEl.focus();
  });
});

inEl.addEventListener('keydown', (e)=>{ if(e.key==='Enter') update(); });
modeEl.addEventListener('change', update);
dialEl.addEventListener('change', update);

update();

