const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const outMain = $('#outMain');
const outRule = $('#outRule');

const examples = [
  {g:'ἀμπελών', raw:'αμπελων', note:'collective (-ών) → acute'},
  {g:'καμηλών', raw:'καμηλων', note:'collective (-ών) → acute'},
  {g:'Βαβυλών', raw:'Βαβυλων', note:'proper name/city; often written with acute'},
  {g:'Ἀπόλλων', raw:'Απολλων', note:'-ων name (example in passage)'},
  {g:'Κεφάλων', raw:'Κεφαλων', note:'-ων name (example in passage)'},
  {g:'Ἀτιτάλλων', raw:'Ατιταλλων', note:'-ων name (example in passage)'},
  {g:'Τίμων', raw:'Τιμων', note:'-μων → “low” (toy: grave)'},
  {g:'Σίμων', raw:'Σιμων', note:'-μων → “low” (toy: grave)'},
  {g:'Ἄμμων', raw:'Αμμων', note:'-μων → “low” (toy: grave)'},
  {g:'Ἕρμων', raw:'Ερμων', note:'-μων → “low” (toy: grave)'},
  {g:'Σάλμων', raw:'Σαλμων', note:'place-name in passage; toy treats Capitalized as place-name-ish'}
];

function isGreekUpper(ch){
  // Basic Greek uppercase ranges + tonos variants
  return /[Α-ΩΆΈΉΊΌΎΏ]/.test(ch);
}

function stripDiacritics(s){
  // Remove combining marks after NFD
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function lastVowelIndex(s){
  const vowels = 'αεηιουωΑΕΗΙΟΥΩ';
  for(let i=s.length-1;i>=0;i--){
    if(vowels.includes(s[i])) return i;
  }
  return -1;
}

function addAccentOnChar(ch, accent){
  // accent: 'acute' (U+0301) or 'grave' (U+0300)
  const comb = accent==='grave' ? '\u0300' : '\u0301';
  return (ch.normalize('NFD') + comb).normalize('NFC');
}

function forceAccentLastVowel(word, accent){
  const base = stripDiacritics(word);
  const idx = lastVowelIndex(base);
  if(idx<0) return base;
  return base.slice(0, idx) + addAccentOnChar(base[idx], accent) + base.slice(idx+1);
}

function getLastWord(s){
  const parts = s.trim().split(/\s+/).filter(Boolean);
  return parts.length ? parts[parts.length-1] : '';
}

function analyze(){
  const raw = inp.value;
  const last = getLastWord(raw);
  if(!last){
    outMain.textContent = '—';
    outRule.textContent = 'Type a Greek word above.';
    return;
  }

  const base = stripDiacritics(last);
  const lower = base.toLowerCase();

  // Heuristics inspired by the passage
  const endsOn = (suf) => lower.endsWith(suf);

  // tiny whitelist for collectives mentioned
  const collectiveSet = new Set(['αμπελων','καμηλων']);

  let suggestion = base;
  let rule = 'No rule triggered; leaving unaccented (use buttons to force an accent).';

  if(endsOn('μων')){
    const looksPlace = isGreekUpper(base[0]);
    const hasYBefore = lower.endsWith('υμων');

    if(!looksPlace && !hasYBefore){
      suggestion = forceAccentLastVowel(base, 'grave');
      rule = 'Ends in -μων and does not look like a place-name; toy applies “low” accent → grave on last vowel.';
    } else {
      suggestion = base;
      rule = 'Ends in -μων but looks like a place-name (Capitalized) or has -υμων; toy does not apply the “low” rule.';
    }
  } else if(endsOn('ων')){
    if(collectiveSet.has(lower)){
      suggestion = forceAccentLastVowel(base, 'acute');
      rule = 'Collective in -ών (ἀμπελών/καμηλών) → acute on last vowel.';
    } else if(lower === 'βαβυλων' || lower === 'βαβυλωνος'){
      suggestion = forceAccentLastVowel(base, 'acute');
      rule = 'Special-cased: Βαβυλών in the passage → acute on last vowel.';
    } else {
      suggestion = base;
      rule = 'Ends in -ων, but not in the toy’s small “collective” list; leaving unaccented.';
    }
  }

  // If user typed a phrase, replace only last word
  const parts = raw.trim().split(/\s+/).filter(Boolean);
  if(parts.length>1){
    parts[parts.length-1] = suggestion;
    outMain.textContent = parts.join(' ');
  } else {
    outMain.textContent = suggestion;
  }
  outRule.textContent = rule;
}

function fillChips(){
  const box = $('#chips');
  box.innerHTML = '';
  for(const ex of examples){
    const d = document.createElement('div');
    d.className = 'chip';
    d.textContent = ex.g;
    d.title = ex.note + ' (click to load)';
    d.addEventListener('click', () => { inp.value = ex.raw; analyze(); inp.focus(); });
    box.appendChild(d);
  }
}

$('#btnAnalyze').addEventListener('click', analyze);
$('#btnRandom').addEventListener('click', () => {
  const ex = examples[Math.floor(Math.random()*examples.length)];
  inp.value = ex.raw;
  analyze();
  inp.focus();
});
$('#btnClear').addEventListener('click', () => { inp.value=''; analyze(); inp.focus(); });

$('#btnAcute').addEventListener('click', () => {
  const raw = inp.value;
  const last = getLastWord(raw);
  if(!last) return;
  const base = stripDiacritics(last);
  const forced = forceAccentLastVowel(base, 'acute');
  const parts = raw.trim().split(/\s+/).filter(Boolean);
  parts[parts.length-1] = forced;
  inp.value = parts.join(' ');
  outMain.textContent = inp.value;
  outRule.textContent = 'Forced acute on the last vowel (mechanical).';
});

$('#btnGrave').addEventListener('click', () => {
  const raw = inp.value;
  const last = getLastWord(raw);
  if(!last) return;
  const base = stripDiacritics(last);
  const forced = forceAccentLastVowel(base, 'grave');
  const parts = raw.trim().split(/\s+/).filter(Boolean);
  parts[parts.length-1] = forced;
  inp.value = parts.join(' ');
  outMain.textContent = inp.value;
  outRule.textContent = 'Forced grave on the last vowel (mechanical).';
});

$('#btnStrip').addEventListener('click', () => {
  inp.value = stripDiacritics(inp.value);
  outMain.textContent = inp.value || '—';
  outRule.textContent = 'Stripped accents/diacritics (NFD combining marks).';
});

inp.addEventListener('keydown', (e) => {
  if(e.key === 'Enter') analyze();
});

fillChips();
analyze();

