const $ = (sel) => document.querySelector(sel);

const examples = [
  "χειμων",
  "λειμων",
  "δρυμων",
  "Στρυμων",
  "κρεμων",
  "ἀμυμων",
  "ἐγκυμων",
  "οἰκτιρμων",
  "Ἡγημων",
  "Φιλημων",
  "νοημων",
  "ἀσχημων",
  "εὐσχημων",
  "χαιρεημων",
  "ἐλεημων",
  "Τελαμων",
  "καλαμων",
  "πλαταμων",
  "κεραμων",
  "Ποταμων",
  "τερᾰμων" // playful: short alpha hint
];

const exceptionAccent = new Map([
  // oxytone locals/seasons etc. from passage
  ["χειμων","χειμών"],
  ["λειμων","λειμών"],
  ["κευθμων","κευθμών"],
  ["θημων","θημών"],
  ["στρυμων","Στρυμών"],
  ["δρυμων","δρυμών"],
  ["κρεμων","κρεμών"],
  // explicitly oxytone proper/appellative in passage
  ["τελαμων","Τελαμών"],
  ["καλαμων","καλαμών"],
  ["πλαταμων","πλαταμών"],
  ["κεραμων","κεραμών"],
  // explicitly barytone example
  ["τερᾰμων","τεράμων"],
  ["τεραμων","τεράμων"],
]);

function normalizeGreek(s){
  return (s||"")
    .trim()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'') // strip combining diacritics
    .replace(/[’'᾽]/g,'')
    .replace(/\s+/g,' ');
}

function endsWithMon(s){
  const n = normalizeGreek(s).toLowerCase();
  return n.endsWith("μων") || n.endsWith("μον");
}

function countSyllables(word){
  // crude syllable count: count vowel groups
  const w = normalizeGreek(word).toLowerCase();
  const vowels = "αεηιουω";
  let count = 0;
  let inV = false;
  for (let ch of w){
    const isV = vowels.includes(ch);
    if (isV && !inV) count++;
    inV = isV;
  }
  return Math.max(1,count);
}

function lastIndexOfVowelGroup(w){
  const vowels = "αεηιουω";
  w = normalizeGreek(w).toLowerCase();
  for (let i=w.length-1;i>=0;i--){
    if (vowels.includes(w[i])) return i;
  }
  return -1;
}

function guessPenultLong(word){
  // heuristic: look at penult vowel group (second-to-last vowel group)
  const w = normalizeGreek(word).toLowerCase();
  const vowels = "αεηιουω";
  // collect vowel-group start indices
  let groups = [];
  let inV=false;
  for (let i=0;i<w.length;i++){
    const isV = vowels.includes(w[i]);
    if (isV && !inV) groups.push(i);
    inV=isV;
  }
  if (groups.length < 2) return null;
  const penStart = groups[groups.length-2];
  // take up to 2 chars for diphthong check
  const seg = w.slice(penStart, penStart+2);
  const longSingles = new Set(["η","ω"]);
  const longDiph = ["ει","ου","αι","αυ","ευ","ηυ","υι"];
  if (longSingles.has(w[penStart])) return true;
  if (longDiph.includes(seg)) return true;
  return false;
}

function addAcuteOnOmega(word){
  // if ends with μων, turn into μών (precomposed omega+tonos)
  // preserve original casing of earlier letters.
  if (!word) return word;
  const nfd = word.normalize('NFD');
  // remove any existing tonos on final omega
  let base = nfd.replace(/ω[\u0301\u0300\u0342]?/g, 'ω');
  base = base.normalize('NFC');
  // replace last occurrence of "μων" with "μών"
  const idx = base.lastIndexOf("μων");
  const idx2 = base.lastIndexOf("Μων");
  const idx3 = base.lastIndexOf("ΜΩΝ");
  let i = Math.max(idx, idx2, idx3);
  if (i === -1) return base;
  const before = base.slice(0,i);
  const tail = base.slice(i);
  // handle different casings for omega
  if (tail.startsWith("μων")) return before + "μών" + tail.slice(3);
  if (tail.startsWith("Μων")) return before + "Μών" + tail.slice(3);
  if (tail.startsWith("ΜΩΝ")) return before + "ΜΏΝ" + tail.slice(3);
  return base;
}

function analyze(input){
  const raw = (input||"").trim();
  const norm = normalizeGreek(raw);
  const normLower = norm.toLowerCase();

  if (!raw){
    return {error:"Type a Greek word (ideally ending in -μων)."};
  }

  // If phrase, analyze last token
  const tokens = norm.split(' ');
  const last = tokens[tokens.length-1];

  const syll = countSyllables(last);
  const hasMon = endsWithMon(last);

  let decision = {accent:"?", confidence:"warn", reason:[]};

  if (!hasMon){
    decision.accent = "(not -μων)";
    decision.confidence = "bad";
    decision.reason.push("The last word doesn’t look like it ends in -μων/-μον, so the toy won’t apply Herodian’s -μων rules.");
    return {raw, norm, last, syll, hasMon, decision, suggested: raw};
  }

  // exceptions
  if (exceptionAccent.has(normLower)){
    const sug = exceptionAccent.get(normLower);
    decision.accent = sug.endsWith("μών") ? "oxytone" : "barytone";
    decision.confidence = "good";
    decision.reason.push("Matched an example/exception explicitly mentioned in the passage.");
    return {raw, norm, last, syll, hasMon, decision, suggested: replaceLastToken(raw, sug)};
  }

  if (syll <= 2){
    decision.accent = "oxytone";
    decision.confidence = "warn";
    decision.reason.push("Two-syllable -μων words in the passage are often oxytone (esp. local/season terms).");
    return {raw, norm, last, syll, hasMon, decision, suggested: replaceLastToken(raw, addAcuteOnOmega(last))};
  }

  const penLong = guessPenultLong(last);
  if (penLong === true){
    decision.accent = "barytone";
    decision.confidence = "warn";
    decision.reason.push("Heuristic: penult looks long (η/ω or a diphthong), so the toy guesses barytone (Herodian: >2 syllables + long penult → barytone).");
    return {raw, norm, last, syll, hasMon, decision, suggested: raw};
  }

  decision.accent = "oxytone";
  decision.confidence = "warn";
  decision.reason.push("Default guess: oxytone -μών (toy fallback when penult doesn’t look long).");
  return {raw, norm, last, syll, hasMon, decision, suggested: replaceLastToken(raw, addAcuteOnOmega(last))};
}

function replaceLastToken(original, replacement){
  const parts = (original||"").trim().split(/\s+/);
  if (parts.length===0) return replacement;
  parts[parts.length-1] = replacement;
  return parts.join(' ');
}

function badgeClass(conf){
  if (conf==="good") return "good";
  if (conf==="bad") return "bad";
  return "warn";
}

function render(res){
  const out = $("#out");
  if (res.error){
    out.innerHTML = `<div class="card"><div class="v">${escapeHtml(res.error)}</div><div class="explain muted">Try: <span class="g">χειμων</span>, <span class="g">Στρυμων</span>, <span class="g">Φιλημων</span>, <span class="g">Τελαμων</span>.</div></div>`;
    return;
  }

  const badge = `<span class="badge ${badgeClass(res.decision.confidence)}">${escapeHtml(res.decision.confidence)}</span>`;

  out.innerHTML = `
    <div class="grid">
      <div class="card">
        <div class="k">Last word analyzed</div>
        <div class="v">${escapeHtml(res.last)}</div>
        <div class="explain">Syllables (rough): <span class="g">${res.syll}</span> · Ends in -μων? <span class="g">${res.hasMon ? "yes" : "no"}</span></div>
      </div>
      <div class="card">
        <div class="k">Toy prediction</div>
        <div class="v">${escapeHtml(res.decision.accent)} ${badge}</div>
        <div class="explain">Suggested form: <span class="g">${escapeHtml(res.suggested)}</span></div>
      </div>
    </div>
    <div class="card" style="margin-top:10px">
      <div class="k">Why?</div>
      <div class="explain">${res.decision.reason.map(r=>`• ${escapeHtml(r)}`).join("<br>")}</div>
      <hr>
      <div class="explain muted"><span class="smallcaps">Play</span>: try changing the penult vowel (e.g. <span class="g">Φιλημων</span> → <span class="g">Φιλαμων</span>) and see the guess flip.</div>
    </div>
  `;
}

function escapeHtml(s){
  return String(s)
    .replace(/&/g,"&amp;")
    .replace(/</g,"&lt;")
    .replace(/>/g,"&gt;")
    .replace(/\"/g,"&quot;")
    .replace(/'/g,"&#039;");
}

function setupQuickChips(){
  const quick = $("#quick");
  const picks = ["χειμων","Στρυμων","κρεμων","ἀμυμων","Φιλημων","Τελαμων","κεραμων","τεραμων"];
  quick.innerHTML = picks.map(w=>`<button class="chip" type="button" data-w="${escapeHtml(w)}">${escapeHtml(w)}</button>`).join("");
  quick.addEventListener('click', (e)=>{
    const b = e.target.closest('button[data-w]');
    if (!b) return;
    $("#inp").value = b.getAttribute('data-w');
    render(analyze($("#inp").value));
    $("#inp").focus();
  });
}

function randomExample(){
  const w = examples[Math.floor(Math.random()*examples.length)];
  $("#inp").value = w;
  render(analyze(w));
  $("#inp").focus();
}

function init(){
  setupQuickChips();
  $("#btn").addEventListener('click', ()=>render(analyze($("#inp").value)));
  $("#btnRandom").addEventListener('click', randomExample);
  $("#inp").addEventListener('keydown', (e)=>{
    if (e.key === 'Enter') render(analyze($("#inp").value));
  });
  render(analyze(""));
}

init();

