.badge.warn{border-color:rgba(251,191,36,.35); color:rgba(255,232,170,.95); background:rgba(251,191,36,.10)}
.badge.bad{border-color:rgba(251,113,133,.35); color:rgba(255,200,210,.95); background:rgba(251,113,133,.10)}
.rules{margin:8px 0 0 18px; color:var(--muted); line-height:1.45; font-size:13.5px}
