.chipbtn{font-family:var(--mono); font-size:13px; padding:4px 8px; margin:2px 4px; border-radius:999px; border:1px solid rgba(167,139,250,.35); background:rgba(167,139,250,.12); color:var(--text); cursor:pointer}
.chipbtn:hover{background:rgba(167,139,250,.18)}
