@media (max-width:560px){
  .kv{grid-template-columns: 1fr}
  .lbl{min-width:auto}
}

passages.gadget_js:
const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const out = $('#out');
const chkNormalize = $('#chkNormalize');
const chkPhrase = $('#chkPhrase');
const chkCity = $('#chkCity');
const chkShowMarks = $('#chkShowMarks');

const examples = [
  'Αρτεμων','Πολεμων','Διδυμων','δαιμων','Λακεδαιμων','κακοδαιμων','ευδαιμων','Παλαίμων','Μεμνων','Δαφνων','Αγνων','Σεννων','Κραννων','δαφνων','αμεινων',
  'ἡγεμών','ἐθνυμών','δαιτυμών'
];

function stripDiacritics(s){
  // NFD splits base + combining marks; remove combining marks.
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function normalizeGreek(s){
  // Keep Greek letters; also keep spaces and apostrophes/hyphens for phrases.
  let t = s.trim();
  t = t.replace(/[··]/g, '');
  if (chkNormalize.checked) t = stripDiacritics(t);
  // normalize final sigma
  t = t.replace(/σ\b/g, 'ς');
  return t;
}

function isGreekLetter(ch){
  return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(ch);
}

function splitWords(s){
  // Split on whitespace and punctuation, keep Greek tokens.
  const raw = s.split(/[^\u0370-\u03FF\u1F00-\u1FFF]+/).filter(Boolean);
  return raw;
}

function lastIndexOfAny(s, chars){
  let idx = -1;
  for (const c of chars){
    const i = s.lastIndexOf(c);
    if (i > idx) idx = i;
  }
  return idx;
}

function applyAccent(word, pos, mark){
  // Apply combining mark to the vowel at index pos (in NFC output).
  // mark: 'acute' or 'circ'
  const acute = '\u0301';
  const circumflex = '\u0342';
  const m = mark === 'acute' ? acute : circumflex;

  // Work in NFD to insert combining mark after base vowel.
  const nfd = word.normalize('NFD');

  // Map NFC index to NFD index by walking.
  let nfcToNfd = [];
  let nfc = word.normalize('NFC');
  let j = 0;
  for (let i = 0; i < nfc.length; i++){
    const ch = nfc[i];
    const seg = ch.normalize('NFD');
    nfcToNfd[i] = j;
    j += seg.length;
  }
  const nfdPos = nfcToNfd[pos];
  if (nfdPos == null) return word;

  // Insert mark after the base character at nfdPos, but before any existing combining marks.
  let k = nfdPos + 1;
  while (k < nfd.length && /[\u0300-\u036f]/.test(nfd[k])) k++;
  const outNfd = nfd.slice(0, k) + m + nfd.slice(k);
  return outNfd.normalize('NFC');
}

function findVowelIndexBeforeSuffix(w, suffix){
  // Return index (NFC) of the vowel in the syllable immediately before suffix.
  // For -μων: vowel is the character right before 'μ' of 'μων'.
  const idx = w.toLowerCase().lastIndexOf(suffix);
  if (idx < 1) return -1;
  // look left from idx for first Greek vowel
  const vowels = 'αεηιουωάέήίόύώϊΐϋΰ';
  for (let i = idx - 1; i >= 0; i--){
    if (vowels.includes(w[i])) return i;
    if (isGreekLetter(w[i]) === false) break;
  }
  return -1;
}

function analyzeWord(raw){
  const original = raw;
  const w = normalizeGreek(raw);
  const lower = w.toLowerCase();

  const result = {
    original,
    normalized: w,
    rule: null,
    confidence: 'warn',
    why: '',
    suggested: w,
    accentType: null,
    accentOn: null
  };

  const showMarks = chkShowMarks.checked;

  // Rule buckets
  if (lower.endsWith('αιμων')){
    result.rule = '-αιμων → barytone (toy shows circumflex)';
    result.confidence = 'good';
    result.accentType = 'circ';
    result.why = "Herodian: forms in -αιμων are ‘βαρύνεται’.";
    // accent the alpha of αι
    const idx = lower.lastIndexOf('αιμων');
    const pos = idx; // 'α'
    result.accentOn = 'αι';
    if (showMarks) result.suggested = applyAccent(w, pos, 'circ');
    return result;
  }

  if (lower.endsWith('μων')){
    const vpos = findVowelIndexBeforeSuffix(w, 'μων');
    if (vpos >= 0){
      const v = stripDiacritics(w[vpos]).toLowerCase();
      if (v === 'ο'){
        result.rule = '-μων with ο before τέλος → oxytone (acute)';
        result.confidence = 'good';
        result.accentType = 'acute';
        result.accentOn = 'ο';
        result.why = "Herodian: if the pre-final syllable has ο, it is ‘ὀξύνεται’.";
        if (showMarks) result.suggested = applyAccent(w, vpos, 'acute');
      } else if (v === 'ω'){
        result.rule = '-μων with ω before τέλος → barytone (toy shows circumflex)';
        result.confidence = 'good';
        result.accentType = 'circ';
        result.accentOn = 'ω';
        result.why = "Herodian: if with ω, it is ‘βαρύνεται’.";
        if (showMarks) result.suggested = applyAccent(w, vpos, 'circ');
      } else {
        result.rule = '-μων detected, but vowel before suffix not ο/ω';
        result.confidence = 'warn';
        result.why = 'Toy rule only distinguishes ο vs ω before -μων.';
      }
    } else {
      result.rule = '-μων detected';
      result.confidence = 'warn';
      result.why = 'Could not locate the vowel before -μων.';
    }
    return result;
  }

  if (lower.endsWith('ονος')){
    result.rule = '-ονος → barytone (toy shows circumflex)';
    result.confidence = 'warn';
    result.accentType = 'circ';
    result.why = "Herodian: ‘likewise those in -ονος, as ἀμείνων’ (toy simplification).";
    // accent the omicron of -ονος
    const idx = lower.lastIndexOf('ονος');
    const pos = idx;
    result.accentOn = 'ο';
    if (showMarks) result.suggested = applyAccent(w, pos, 'circ');
    return result;
  }

  if (lower.endsWith('νων')){
    // Find consonant cluster before -νων: look at two letters before νων
    const idx = lower.lastIndexOf('νων');
    const pre = lower.slice(Math.max(0, idx-3), idx); // up to 3 letters before
    const hasCluster = /[βγδζθκλμνξπρστφχψ][βγδζθκλμνξπρστφχψ]/.test(pre);

    if (chkCity.checked){
      result.rule = '-νων as city/local → oxytone (acute)';
      result.confidence = 'warn';
      result.accentType = 'acute';
      result.why = "Herodian: Κραννών (city) is ‘ὀξύνεται’. Toggle simulates ‘city name’ exception.";
      // accent the omega in -νων (last syllable)
      const pos = idx + 1; // ω
      result.accentOn = 'ω';
      if (showMarks) result.suggested = applyAccent(w, pos, 'acute');
      return result;
    }

    if (hasCluster){
      result.rule = '-νων with consonant cluster → barytone (toy shows circumflex)';
      result.confidence = 'good';
      result.accentType = 'circ';
      result.why = "Herodian: -νων with consonant ‘in combination or at a distance’ tends to be ‘βαρύνεται’ (unless city/collective).";
      // accent the omega in -νων as a visible barytone marker
      const pos = idx + 1; // ω
      result.accentOn = 'ω';
      if (showMarks) result.suggested = applyAccent(w, pos, 'circ');
    } else {
      result.rule = '-νων detected (no obvious cluster)';
      result.confidence = 'warn';
      result.why = 'Toy cannot decide; Herodian has more conditions (collectives, locals, vowel endings, etc.).';
    }
    return result;
  }

  result.rule = 'No matching ending from this passage';
  result.confidence = 'bad';
  result.why = 'Try a word ending in -μων, -αιμων, -νων, or -ονος.';
  return result;
}

function badge(conf){
  if (conf === 'good') return '<span class="badge good">likely</span>';
  if (conf === 'warn') return '<span class="badge warn">maybe</span>';
  return '<span class="badge bad">no rule</span>';
}

function render(results){
  if (!results.length){
    out.innerHTML = '<div class="hint">Type a word above and click <b>Analyze</b>.</div>';
    return;
  }
  const blocks = results.map(r => {
    const sug = (r.suggested && r.suggested !== r.normalized) ? r.suggested : r.normalized;
    const changed = (sug !== r.normalized);
    return `
      <div class="card">
        <h3>Word: <span class="v">${escapeHtml(r.original)}</span> ${badge(r.confidence)}</h3>
        <div class="kv">
          <div class="k">Normalized</div><div class="v">${escapeHtml(r.normalized)}</div>
          <div class="k">Rule guess</div><div class="v" style="font-size:13.5px; font-family:var(--sans); color:var(--text)">${escapeHtml(r.rule || '')}</div>
          <div class="k">Suggested form</div><div class="v">${escapeHtml(sug)}${changed ? '' : ''}</div>
          <div class="k">Why</div><div class="v" style="font-size:13.5px; font-family:var(--sans); color:var(--muted)">${escapeHtml(r.why || '')}</div>
        </div>
      </div>
    `;
  }).join('');

  out.innerHTML = blocks;
}

function escapeHtml(s){
  return String(s)
    .replaceAll('&','&amp;')
    .replaceAll('<','&lt;')
    .replaceAll('>','&gt;')
    .replaceAll('"','&quot;')
    .replaceAll("'",'&#39;');
}

function analyze(){
  const text = inp.value;
  const norm = normalizeGreek(text);
  if (!norm){
    render([]);
    return;
  }
  let words = [norm];
  if (chkPhrase.checked){
    words = splitWords(norm);
  }
  const results = words.map(analyzeWord);
  render(results);
}

$('#btnAnalyze').addEventListener('click', analyze);
inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') analyze(); });

$('#btnRandom').addEventListener('click', ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  inp.value = ex;
  analyze();
});

$('#btnClear').addEventListener('click', ()=>{
  inp.value = '';
  render([]);
  inp.focus();
});

for (const b of document.querySelectorAll('.chipbtn')){
  b.addEventListener('click', ()=>{
    inp.value = b.getAttribute('data-ex');
    analyze();
  });
}

// initial
render([]);

