const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => Array.from(document.querySelectorAll(sel));

// --- Polytonic helpers (very small, heuristic) ---
const combining = {
  acute: "\u0301",
  grave: "\u0300",
  circumflex: "\u0342",
  smooth: "\u0313",
  rough: "\u0314",
  diaeresis: "\u0308",
  iotaSub: "\u0345"
};

function nfc(s){ return s.normalize('NFC'); }
function nfd(s){ return s.normalize('NFD'); }

function stripDiacritics(s){
  // remove combining marks; keep base letters
  return nfd(s).replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code>=0x0370 && code<=0x03FF) || (code>=0x1F00 && code<=0x1FFF);
}

const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);

function splitGraphemes(s){
  // crude grapheme split: base char + following combining marks
  const a = Array.from(nfd(s));
  const out=[];
  for(const ch of a){
    if(/[\u0300-\u036f]/.test(ch) && out.length){
      out[out.length-1]+=ch;
    } else {
      out.push(ch);
    }
  }
  return out;
}

function syllableNucleiIndices(word){
  // Return indices (in grapheme array) of vowel nuclei (very rough: each vowel letter counts)
  const g = splitGraphemes(word);
  const idx=[];
  for(let i=0;i<g.length;i++){
    const base = stripDiacritics(g[i]);
    if(vowels.has(base)) idx.push(i);
  }
  return {g, idx};
}

function addAccentToVowel(word, vowelIndexFromEnd, accentType){
  // accentType: 'acute'|'grave'|'circumflex'
  const {g, idx} = syllableNucleiIndices(word);
  if(idx.length===0) return word;
  const target = idx[Math.max(0, idx.length - vowelIndexFromEnd)];
  // remove existing accent marks on that grapheme
  let gr = g[target];
  gr = nfd(gr).replace(/[\u0300\u0301\u0342]/g,'');
  gr += combining[accentType];
  g[target]=gr;
  return nfc(g.join(''));
}

function hasAnyAccent(word){
  return /[\u0300\u0301\u0342]/.test(nfd(word));
}

function endsWithBase(word, ending){
  return stripDiacritics(word).toLowerCase().endsWith(ending);
}

function guessRule(word, kind, declHint){
  const base = stripDiacritics(word).toLowerCase();
  const info = {rule:"", accent:"", accentType:"", syllFromEnd:2, decl:"onos", notes:[]};

  // declension guess
  if(declHint !== 'auto') info.decl = declHint;
  else info.decl = (base.endsWith('ινων') || base.endsWith('ανων') || base.endsWith('υπων') || base.endsWith('ρυπων')) ? 'ontos' : 'onos';

  // special-cased examples from passage
  if(base === 'κανων'){
    info.rule = "Special: κανών is oxytone (acute on ultima).";
    info.accentType = 'acute';
    info.syllFromEnd = 1;
    info.accent = 'oxytone';
    info.decl = info.decl === 'auto' ? 'onos' : info.decl;
    return info;
  }
  if(base === 'ευρυπων' || base === 'εὐρυπων'){
    info.rule = "Special: Εὐρυπῶν is circumflexed (as -οντος declension).";
    info.accentType = 'circumflex';
    info.syllFromEnd = 1;
    info.accent = 'perispomenon';
    info.decl = 'ontos';
    return info;
  }

  // kind override
  const k = kind;

  // -ξων rule
  if(base.endsWith('ξων')){
    if(k === 'adj'){
      info.rule = "-ξων adjectival: tends to be oxytone (acute on ultima), like δραξών.";
      info.accentType = 'acute';
      info.syllFromEnd = 1;
      info.accent = 'oxytone';
    } else {
      info.rule = "-ξων (non-adjectival, can be feminine): tends to be recessive (here: proparoxytone if possible).";
      info.accentType = 'acute';
      info.syllFromEnd = 3; // proparoxytone attempt
      info.accent = 'recessive';
    }
    return info;
  }

  // -πων rule
  if(base.endsWith('πων')){
    if(k === 'collective'){
      info.rule = "-πων collective: not covered fully here; toy keeps it less recessive (paroxytone).";
      info.accentType = 'acute';
      info.syllFromEnd = 2;
      info.accent = 'paroxytone';
    } else {
      info.rule = "-πων (not collective): tends to be recessive (here: proparoxytone if possible).";
      info.accentType = 'acute';
      info.syllFromEnd = 3;
      info.accent = 'recessive';
    }
    return info;
  }

  // -ρων with consonant cluster (very rough: any consonant before ρων)
  if(base.endsWith('ρων')){
    const pre = base.slice(0,-3);
    const last = pre.slice(-1);
    const isVowel = ['α','ε','η','ι','ο','υ','ω'].includes(last);
    const clusterish = !isVowel; // crude

    if(clusterish && k !== 'collective' && k !== 'city' && info.decl !== 'ontos'){
      info.rule = "-ρων with consonant cluster (non-collective/non-city/non--ντ-): tends to be recessive.";
      info.accentType = 'acute';
      info.syllFromEnd = 3;
      info.accent = 'recessive';
    } else {
      info.rule = "-ρων: toy defaults to paroxytone (many exceptions exist).";
      info.accentType = 'acute';
      info.syllFromEnd = 2;
      info.accent = 'paroxytone';
    }
    return info;
  }

  // generic -ων
  if(base.endsWith('ων')){
    if(k === 'proper'){
      info.rule = "Proper name in -ων: toy defaults to paroxytone (like many -ωνος names).";
      info.accentType = 'acute';
      info.syllFromEnd = 2;
      info.accent = 'paroxytone';
    } else {
      info.rule = "Generic -ων: toy defaults to paroxytone.";
      info.accentType = 'acute';
      info.syllFromEnd = 2;
      info.accent = 'paroxytone';
    }
    return info;
  }

  info.rule = "Doesn’t look like a -ων word; toy will just echo it.";
  info.accentType = '';
  info.syllFromEnd = 0;
  info.accent = 'none';
  return info;
}

function applyAccent(word, rule){
  if(!rule.accentType) return nfc(word);
  // If user already accented, keep it (but normalize)
  if(hasAnyAccent(word)) return nfc(word);
  // Try to accent requested syllable; if not enough syllables, fall back toward the end.
  const {idx} = syllableNucleiIndices(word);
  let fromEnd = rule.syllFromEnd;
  if(idx.length < fromEnd) fromEnd = Math.min(2, idx.length) || 1;
  return addAccentToVowel(word, fromEnd, rule.accentType);
}

function toyDeclensionForms(nom, decl){
  // Very simplified: nominative -ων; gen -ωνος or -οντος; dat -ωνι or -οντι; acc -ωνα or -οντα; voc = nom
  const base = stripDiacritics(nom);
  const lower = base.toLowerCase();
  if(!lower.endsWith('ων')){
    return null;
  }
  const stem = nom.slice(0, nom.length-2); // keep accents in stem as typed
  if(decl === 'ontos'){
    return {
      "Nom.": nom,
      "Gen.": stem + "οντος",
      "Dat.": stem + "οντι",
      "Acc.": stem + "οντα",
      "Voc.": nom
    };
  }
  return {
    "Nom.": nom,
    "Gen.": stem + "ωνος",
    "Dat.": stem + "ωνι",
    "Acc.": stem + "ωνα",
    "Voc.": nom
  };
}

function render(){
  const raw = $('#inp').value.trim();
  const kind = ($$('input[name="kind"]').find(r=>r.checked)?.value) || 'auto';
  const declHint = ($$('input[name="decl"]').find(r=>r.checked)?.value) || 'auto';

  if(!raw){
    $('#out').innerHTML = `<div class="meta">Type a word ending in <span class="ex">-ων</span> to begin.</div>`;
    $('#decl').innerHTML = '';
    return;
  }

  const rule = guessRule(raw, kind, declHint);
  const accented = applyAccent(raw, rule);

  const tags = [];
  if(rule.accent && rule.accent !== 'none') tags.push(`<span class="tag good">${rule.accent}</span>`);
  if(rule.decl) tags.push(`<span class="tag">decl: ${rule.decl === 'ontos' ? '-οντος' : '-ωνος'}</span>`);
  if(kind !== 'auto') tags.push(`<span class="tag">as: ${kind}</span>`);

  const baseEnds = endsWithBase(raw, 'ων') ? '' : ' <span class="tag bad">not -ων</span>';

  $('#out').innerHTML = `
    <div class="big">${accented}</div>
    <div class="meta">${tags.join('')}${baseEnds}</div>
    <div class="meta">Rule: ${rule.rule}</div>
    <div class="meta">Tip: If you want the toy to add accents, type without accents.</div>
  `;

  const forms = toyDeclensionForms(accented, rule.decl);
  if(!forms){
    $('#decl').innerHTML = `<div class="out"><div class="meta">No declension shown (input doesn’t end in -ων).</div></div>`;
    return;
  }

  const rows = Object.entries(forms).map(([k,v])=>`<tr><td class="k">${k}</td><td class="v">${v}</td></tr>`).join('');

  const otherDecl = (rule.decl === 'ontos') ? 'onos' : 'ontos';
  const otherForms = toyDeclensionForms(accented, otherDecl);
  const rows2 = Object.entries(otherForms).map(([k,v])=>`<tr><td class="k">${k}</td><td class="v">${v}</td></tr>`).join('');

  $('#decl').innerHTML = `
    <table class="tbl" aria-label="Toy declension table">
      <thead><tr><th colspan="2">As ${rule.decl === 'ontos' ? '(-οντος)' : '(-ωνος)'}</th></tr></thead>
      <tbody>${rows}</tbody>
    </table>
    <table class="tbl" aria-label="Alternative toy declension table">
      <thead><tr><th colspan="2">Compare: ${otherDecl === 'ontos' ? '(-οντος)' : '(-ωνος)'}</th></tr></thead>
      <tbody>${rows2}</tbody>
    </table>
  `;
}

const examples = [
  "Κονων","Σινων","Ζηνων","Φαινων","Μονων",
  "κανων","πλατανων","ξενων","παρθενων",
  "Σαξων","Αιξων","Δεξων","Πραξων","αξων",
  "δραξων","Ευρυπων",
  "Λαμπων","θεραπων","Ιππων","πεπων",
  "σωφρων","Λυκοφρων","μεγαλοφρων","αφρων"
];

$('#btn').addEventListener('click', render);
$('#inp').addEventListener('keydown', (e)=>{ if(e.key==='Enter') render(); });
$('#rand').addEventListener('click', ()=>{
  const w = examples[Math.floor(Math.random()*examples.length)];
  $('#inp').value = w;
  // reset to auto for fun
  $$('input[name="kind"]').forEach(r=>r.checked = (r.value==='auto'));
  $$('input[name="decl"]').forEach(r=>r.checked = (r.value==='auto'));
  render();
});

// initial
render();

