:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --card:#1e2238;
  --text:#eef0ff;
  --muted:#b9bfdc;
  --line:#2b3152;
  --accent:#8be9fd;
  --accent2:#ffd479;
  --bad:#ff6b6b;
  --good:#7CFFB2;
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Noto Sans", "Liberation Sans", sans-serif;
}

*{box-sizing:border-box}

.wrap{
  font-family:var(--sans);
  color:var(--text);
  background:linear-gradient(180deg, #0f1220 0%, #0b0d18 100%);
  border:1px solid var(--line);
  border-radius:16px;
  padding:16px;
  max-width:980px;
  margin:0 auto;
}

.hdr{display:flex; gap:12px; align-items:flex-start; justify-content:space-between; margin-bottom:12px;}
.hdr h2{margin:0; font-size:20px; letter-spacing:.2px;}
.sub{margin:6px 0 0 0; color:var(--muted); line-height:1.35; font-size:13px;}

.panel{background:rgba(255,255,255,0.02); border:1px solid var(--line); border-radius:14px; padding:14px;}

.row{display:flex; flex-direction:column; gap:8px; margin-bottom:12px;}
label{font-size:13px; color:var(--muted)}
input[type=text]{
  width:100%;
  padding:12px 12px;
  border-radius:12px;
  border:1px solid var(--line);
  background:var(--card);
  color:var(--text);
  font-size:18px;
  letter-spacing:.2px;
}
input[type=text]:focus{outline:2px solid rgba(139,233,253,.25); border-color:rgba(139,233,253,.55)}

.grid{display:grid; grid-template-columns:repeat(3, 1fr); gap:12px;}
@media (max-width: 900px){.grid{grid-template-columns:1fr}}

.card{background:var(--card); border:1px solid var(--line); border-radius:14px; padding:12px; min-height:120px;}
.card h3{margin:0 0 6px 0; font-size:14px; color:#dfe4ff; letter-spacing:.2px;}
.mini{font-size:12px; color:var(--muted); line-height:1.35;}
.out{margin-top:10px; padding:10px; border-radius:12px; background:rgba(0,0,0,.18); border:1px dashed rgba(255,255,255,.12); font-family:var(--mono); font-size:14px; white-space:pre-wrap; word-break:break-word;}
.out.big{font-size:18px;}

.controls{display:flex; flex-wrap:wrap; gap:10px; align-items:center; margin-top:12px;}
.tog{display:flex; gap:8px; align-items:center; padding:8px 10px; border:1px solid var(--line); border-radius:999px; background:rgba(255,255,255,.02)}
.tog label{margin:0; font-size:12px; color:var(--muted)}
button{cursor:pointer; border:1px solid var(--line); background:linear-gradient(180deg, rgba(139,233,253,.18), rgba(139,233,253,.08)); color:var(--text); padding:9px 12px; border-radius:12px; font-size:13px;}
button:hover{border-color:rgba(139,233,253,.55)}
button:active{transform:translateY(1px)}

.chips{display:flex; flex-wrap:wrap; gap:6px; margin-top:10px;}
.chip{font-size:12px; padding:6px 8px; border-radius:999px; border:1px solid var(--line); background:rgba(255,255,255,.03); color:var(--muted)}
.chip.good{border-color:rgba(124,255,178,.35); color:rgba(124,255,178,.95)}
.chip.warn{border-color:rgba(255,212,121,.35); color:rgba(255,212,121,.95)}
.chip.bad{border-color:rgba(255,107,107,.35); color:rgba(255,107,107,.95)}

.help{margin-top:12px; border:1px solid var(--line); border-radius:14px; background:rgba(255,255,255,.02); padding:10px 12px;}
.help summary{cursor:pointer; color:#dfe4ff; font-size:13px;}
.helpBody{color:var(--muted); font-size:13px; line-height:1.45; margin-top:8px;}

.ft{margin-top:10px; display:flex; justify-content:space-between; align-items:center;}
.ft .mini{color:rgba(185,191,220,.85)}

