(() => {
  const $ = (sel, root=document) => root.querySelector(sel);
  const inp = $('#inp');
  const normOut = $('#normOut');
  const classOut = $('#classOut');
  const reasons = $('#reasons');
  const accentOut = $('#accentOut');
  const noteOut = $('#noteOut');
  const assumePlace = $('#assumePlace');
  const preferPoly = $('#preferPoly');
  const randBtn = $('#rand');
  const clearBtn = $('#clear');

  const examples = [
    'Θήρων','Νέρων','γέρων','Χάρων','Χείρων','Ἀχέρων','Μύρων','Πύρων',
    'Ἀντρών','Πλευρών','Βραυρών','Κιθαιρών','Τιταρών','προθυρών','ἀχυρών',
    'Δεξικρῶν','Ἑρμοκρῶν'
  ];

  // --- Greek helpers ---
  const combiningMarksRE = /[\u0300-\u036f\u1ab0-\u1aff\u1dc0-\u1dff\u20d0-\u20ff\ufe20-\ufe2f]/g;

  function stripDiacritics(s){
    return (s || '').normalize('NFD').replace(combiningMarksRE,'').normalize('NFC');
  }

  function hasAnyAccent(s){
    const n = (s||'').normalize('NFD');
    // acute, grave, circumflex (perispomeni), tonos
    return /[\u0300\u0301\u0342\u0341]/.test(n);
  }

  function lastIndexOfVowel(s){
    const vowels = 'αεηιουωΑΕΗΙΟΥΩ';
    for(let i=s.length-1;i>=0;i--){
      if(vowels.includes(s[i])) return i;
    }
    return -1;
  }

  function penultVowelIndex(s){
    const vowels = 'αεηιουωΑΕΗΙΟΥΩ';
    let count = 0;
    for(let i=s.length-1;i>=0;i--){
      if(vowels.includes(s[i])){
        count++;
        if(count===2) return i;
      }
    }
    return -1;
  }

  function applyCombiningAcuteToVowelAt(s, idx){
    if(idx<0 || idx>=s.length) return s;
    const ch = s[idx];
    const accented = (ch.normalize('NFD') + '\u0301').normalize('NFC');
    return s.slice(0, idx) + accented + s.slice(idx+1);
  }

  // crude: detect if penult contains diphthong oi/ai (in stripped form)
  function penultHasOiAi(stripped){
    const s = stripped;
    // find last two vowel positions to approximate penult syllable start
    const pv = penultVowelIndex(s);
    if(pv<0) return false;
    // check pv..pv+1 for diphthong
    const pair = s.slice(pv, pv+2);
    return pair === 'οι' || pair === 'αι' || pair === 'ΟΙ' || pair === 'ΑΙ' || pair === 'οι'.toUpperCase() || pair === 'αι'.toUpperCase();
  }

  function endsWithRon(stripped){
    return /ρων$/i.test(stripped);
  }

  function endsWithKron(stripped){
    return /κρων$/i.test(stripped);
  }

  function guessClass(raw){
    const stripped = stripDiacritics(raw).trim();
    const rs = [];

    if(!stripped){
      return {klass:'—', score:0, reasons:[]};
    }

    if(!endsWithRon(stripped)){
      rs.push({t:"Doesn't look like -ρων", kind:'bad'});
      return {klass:'Not -ρων (toy rule won\'t apply)', score:0, reasons:rs};
    }

    rs.push({t:'Ends in -ρων', kind:'good'});

    let scoreOx = 0;
    let scoreBar = 0;

    // Herodian-ish: if penult not oi/ai => baritone (unless place-name)
    const hasDiph = penultHasOiAi(stripped);
    if(hasDiph){
      scoreOx += 1;
      rs.push({t:'Penult seems to have οι/αι (toy check)', kind:'warn'});
    } else {
      scoreBar += 2;
      rs.push({t:'Penult not οι/αι → baritone tendency', kind:'good'});
    }

    // -κρων with -ντ- inflection mentioned; we just flag it
    if(endsWithKron(stripped)){
      rs.push({t:'Looks like -κρων (Herodian mentions -ντ- inflection cases)', kind:'warn'});
    }

    if(assumePlace.checked){
      scoreOx += 2;
      rs.push({t:'Treating as place-name/city-homonym → oxytone push', kind:'warn'});
    } else {
      rs.push({t:'Not marked as place-name', kind:'chip'});
    }

    const klass = (scoreOx > scoreBar) ? 'Likely OXYTONE (acute on last)' : 'Likely BARITONE (accent not on last)';
    return {klass, score: scoreOx-scoreBar, reasons: rs};
  }

  function makeToyAccents(raw){
    const trimmed = (raw||'').trim();
    const stripped = stripDiacritics(trimmed);
    if(!stripped) return {ox:'—', bar:'—', existing:''};

    const existing = hasAnyAccent(trimmed) ? trimmed : '';

    // Build from stripped so we don't stack accents.
    const base = stripped;

    const lastV = lastIndexOfVowel(base);
    const penV = penultVowelIndex(base);

    let ox = base;
    let bar = base;

    if(lastV>=0) ox = applyCombiningAcuteToVowelAt(base, lastV);
    if(penV>=0) bar = applyCombiningAcuteToVowelAt(base, penV);

    // If user wants polytonic, we keep combining acute; if not, we still keep it (tonos/oxia differences are font-level).
    // But we can optionally convert to monotonic tonos for lowercase alpha/epsilon/etc.
    if(!preferPoly.checked){
      // leave as-is; most fonts render combining acute as tonos anyway.
    }

    return {ox, bar, existing};
  }

  function render(){
    const raw = inp.value;
    const stripped = stripDiacritics(raw).trim();

    normOut.textContent = stripped ? stripped : '—';

    const g = guessClass(raw);
    classOut.textContent = g.klass;

    reasons.innerHTML = '';
    (g.reasons||[]).forEach(r => {
      const d = document.createElement('div');
      d.className = 'chip ' + (r.kind || '');
      d.textContent = r.t;
      reasons.appendChild(d);
    });

    const a = makeToyAccents(raw);
    if(a.ox === '—'){
      accentOut.textContent = '—';
      noteOut.textContent = '';
      return;
    }

    const lines = [];
    if(a.existing){
      lines.push('Your input (already accented): ' + a.existing);
    }
    lines.push('Toy OXYTONE:  ' + a.ox);
    lines.push('Toy BARITONE: ' + a.bar);
    accentOut.textContent = lines.join('\n');

    const noteBits = [];
    if(!endsWithRon(stripped)) noteBits.push('Toy rule mainly targets -ρων.');
    if(penultHasOiAi(stripped)) noteBits.push('Penult οι/αι detected (crudely).');
    noteBits.push('Tip: toggle “place-name” to see the guess flip.');
    noteOut.textContent = noteBits.join(' ');
  }

  inp.addEventListener('input', render);
  assumePlace.addEventListener('change', render);
  preferPoly.addEventListener('change', render);

  randBtn.addEventListener('click', () => {
    const w = examples[Math.floor(Math.random()*examples.length)];
    inp.value = w;
    render();
    inp.focus();
  });

  clearBtn.addEventListener('click', () => {
    inp.value = '';
    assumePlace.checked = false;
    render();
    inp.focus();
  });

  // seed
  inp.value = 'Χειρων';
  render();
})();

