(() => {
  const $ = (sel, root=document) => root.querySelector(sel);
  const $$ = (sel, root=document) => Array.from(root.querySelectorAll(sel));

  // --- Minimal polytonic helpers (heuristic) ---
  const combining = /[\u0300-\u036f]/g;
  const tonosMap = {
    'ά':'ά','έ':'έ','ή':'ή','ί':'ί','ό':'ό','ύ':'ύ','ώ':'ώ',
    'Ά':'Ά','Έ':'Έ','Ή':'Ή','Ί':'Ί','Ό':'Ό','Ύ':'Ύ','Ώ':'Ώ'
  };
  const monotonicMap = {
    'ά':'ά','έ':'έ','ή':'ή','ί':'ί','ό':'ό','ύ':'ύ','ώ':'ώ',
    'Ά':'Ά','Έ':'Έ','Ή':'Ή','Ί':'Ί','Ό':'Ό','Ύ':'Ύ','Ώ':'Ώ',
    'ά':'ά','έ':'έ','ή':'ή','ί':'ί','ό':'ό','ύ':'ύ','ώ':'ώ'
  };

  function nfd(s){ return s.normalize('NFD'); }
  function nfc(s){ return s.normalize('NFC'); }
  function stripDiacritics(s){ return nfc(nfd(s).replace(combining,'')); }

  function toPolytonicTonos(s){
    // If user types monotonic tonos, keep it but map to polytonic tonos codepoints.
    return s.replace(/[άέήίόύώΆΈΉΊΌΎΏ]/g, ch => tonosMap[ch] || ch);
  }
  function toMonotonic(s){
    return s.replace(/[άέήίόύώΆΈΉΊΌΎΏ]/g, ch => monotonicMap[ch] || ch);
  }

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

  function lastVowelIndex(word){
    const w = nfd(word);
    // Walk codepoints; treat base letters only.
    for(let i=w.length-1;i>=0;i--){
      const ch = w[i];
      if(vowels.has(ch)) return i;
    }
    return -1;
  }

  function addAcuteOnLastSyllable(word){
    // Heuristic: add acute to the last vowel letter (base) if no accent already.
    const w = toPolytonicTonos(word);
    if(/[\u0301\u0342\u0300]/.test(nfd(w))) return w; // already has some accent mark
    const idx = lastVowelIndex(w);
    if(idx < 0) return w;
    const arr = Array.from(nfd(w));
    // Insert combining acute after the vowel base at idx in NFD array terms.
    // Need to find the corresponding position in arr (since idx is in string index, but NFD string index aligns with code units here).
    // We'll do a safer approach: rebuild scanning NFD string.
    const n = nfd(w);
    let out = '';
    for(let i=0;i<n.length;i++){
      out += n[i];
      if(i===idx) out += '\u0301';
    }
    return nfc(out);
  }

  function removeAccents(word){
    // remove acute/grave/circumflex combining marks and precomposed tonos
    const poly = toPolytonicTonos(word);
    const n = nfd(poly)
      .replace(/[\u0301\u0300\u0342]/g,'');
    return nfc(n);
  }

  // --- Data from the passage (small, playful) ---
  // Each entry: lemma (as displayed), category hint, predicted accent type.
  const examples = [
    {w:'Παύσων', cat:'collective', pred:'barytone', note:'listed among “collectives” (περιεκτικά) → barytone.'},
    {w:'Θράσων', cat:'collective', pred:'barytone', note:'collective list → barytone.'},
    {w:'Γράσων', cat:'collective', pred:'barytone', note:'collective list → barytone.'},
    {w:'Μάσσων', cat:'collective', pred:'barytone', note:'collective list; also a river-name mentioned.'},
    {w:'Ἰάσων', cat:'person', pred:'barytone', note:'in the collective list here (toy simplification).'},
    {w:'Αὐσών', cat:'ethnic', pred:'oxytone', note:'explicit: as an ethnic (ἐθνικόν) it is oxytone.'},
    {w:'Αὔσων', cat:'person', pred:'barytone', note:'mythic figure; contrasted with ethnic Αὐσών.'},
    {w:'Αἴσων', cat:'person', pred:'barytone', note:'Aeson, father of Jason.'},
    {w:'Αἰσών', cat:'place', pred:'oxytone', note:'explicit: city-name treated as oxytone (as with cities).'},
    {w:'Ὀλοοσσών', cat:'place', pred:'oxytone', note:'explicit: city-name oxytone.'},
    {w:'Συλοσῶν', cat:'person', pred:'circumflex', note:'explicit: “inflected through -ντ-” → circumflex (toy: mark as special).'},

    {w:'Πλούτων', cat:'person', pred:'oxytone', note:'named as oxytone by differentiation (διαστολή) from barytone pattern.'},
    {w:'Πλάτων', cat:'person', pred:'oxytone', note:'listed among oxytone -των by differentiation.'},
    {w:'Κράτων', cat:'person', pred:'oxytone', note:'listed among oxytone -των by differentiation.'},
    {w:'Κρίτων', cat:'person', pred:'oxytone', note:'listed among oxytone -των by differentiation.'},
    {w:'Τρίτων', cat:'place', pred:'oxytone', note:'river-name listed among oxytone -των.'},
    {w:'Μέντων', cat:'person', pred:'oxytone', note:'listed among oxytone -των.'},
    {w:'γείτων', cat:'common', pred:'oxytone', note:'listed among oxytone -των.'},
    {w:'τέκτων', cat:'common', pred:'oxytone', note:'listed among oxytone -των.'},

    {w:'Κρότων', cat:'place', pred:'barytone', note:'explicit: as founder/city/mountain it is barytone.'},
    {w:'Κροτών', cat:'common', pred:'oxytone', note:'explicit: in the “dog-destroyer” sense it is oxytone (toy uses spelling to distinguish).'},
    {w:'χιτών', cat:'common', pred:'oxytone', note:'explicit: garment is oxytone (differentiation).'},

    {w:'Ἀρίστων', cat:'person', pred:'barytone', note:'explicit: barytone.'},
    {w:'Ἑκάτων', cat:'person', pred:'barytone', note:'explicit: barytone.'},
    {w:'Χαρίτων', cat:'person', pred:'barytone', note:'explicit: barytone.'},
    {w:'Μελίτων', cat:'person', pred:'barytone', note:'explicit: barytone.'},
    {w:'ἀρχιτέκτων', cat:'common', pred:'barytone', note:'explicit: barytone.'},
    {w:'κοιτών', cat:'collective', pred:'barytone', note:'explicit: collective → barytone.'},
    {w:'ἱστών', cat:'collective', pred:'barytone', note:'explicit: collective → barytone.'},
    {w:'προβατών', cat:'collective', pred:'barytone', note:'explicit: collective → barytone.'}
  ];

  const byBare = new Map();
  for(const ex of examples){
    byBare.set(stripDiacritics(ex.w), ex);
  }

  function endsWithOn(word){
    const bare = stripDiacritics(word);
    return bare.endsWith('ων') || bare.endsWith('ΩΝ') || bare.endsWith('ΟΝ') || bare.endsWith('ον') || bare.endsWith('των') || bare.endsWith('ΤΩΝ');
  }

  function pickCategory(userCat, word){
    if(userCat !== 'auto') return userCat;
    const ex = byBare.get(stripDiacritics(word));
    if(ex) return ex.cat;
    // crude heuristics
    const bare = stripDiacritics(word);
    if(/^(Αυ|Αὐ|Αὔ|Αι|Αἰ|Ολοοσ|Ὀλοοσ)/.test(word)) return 'place';
    if(bare.endsWith('των')) return 'person';
    if(bare.endsWith('ων')) return 'person';
    return 'common';
  }

  function predict(word, cat){
    const ex = byBare.get(stripDiacritics(word));
    if(ex) return {pred: ex.pred, why: ex.note, source:'example'};

    const bare = stripDiacritics(word);
    if(bare.endsWith('των')){
      // Passage: -των not collective/ethnic and inflected through o tends barytone; but many famous exceptions oxytone.
      if(cat === 'collective' || cat === 'ethnic') return {pred:'barytone', why:'Toy rule: collective/ethnic tends barytone unless marked otherwise.', source:'heuristic'};
      return {pred:'barytone', why:'Toy rule: -των defaults to barytone (Herodian’s “not collective/ethnic … barytone”), unless a known “differentiated” oxytone.', source:'heuristic'};
    }
    if(bare.endsWith('ων')){
      if(cat === 'ethnic') return {pred:'oxytone', why:'Toy rule: ethnic in -ων often oxytone (cf. Αὐσών).', source:'heuristic'};
      if(cat === 'place') return {pred:'oxytone', why:'Toy rule: some city-names in -ων are treated as oxytone (cf. Αἰσών, Ὀλοοσσών).', source:'heuristic'};
      if(cat === 'collective') return {pred:'barytone', why:'Toy rule: “collectives” (περιεκτικά) are barytone in the passage’s list.', source:'heuristic'};
      return {pred:'barytone', why:'Toy rule: default barytone for -ων unless ethnic/place triggers oxytone.', source:'heuristic'};
    }
    return {pred:'unknown', why:'Toy rule only targets words ending in -ων / -των.', source:'heuristic'};
  }

  function applyPredictedAccent(word, pred){
    const base = removeAccents(word);
    if(pred === 'oxytone') return addAcuteOnLastSyllable(base);
    if(pred === 'barytone') return base; // we do not attempt correct barytone placement
    if(pred === 'circumflex'){
      // playful: add circumflex on last vowel
      const w = toPolytonicTonos(base);
      if(/[\u0301\u0342\u0300]/.test(nfd(w))) return w;
      const idx = lastVowelIndex(w);
      if(idx < 0) return w;
      const n = nfd(w);
      let out='';
      for(let i=0;i<n.length;i++){
        out += n[i];
        if(i===idx) out += '\u0342';
      }
      return nfc(out);
    }
    return word;
  }

  function renderAnalysis(word){
    const out = $('#out');
    const raw = word.trim();
    if(!raw){
      out.innerHTML = '<div class="muted">Type a word above.</div>';
      return;
    }

    const userCat = ($$('input[name=cat]').find(r => r.checked) || {value:'auto'}).value;
    const cat = pickCategory(userCat, raw);
    const p = predict(raw, cat);

    const predictedForm = applyPredictedAccent(raw, p.pred);
    const showMono = $('#chkMonotonic').checked;

    const displayIn = showMono ? toMonotonic(toPolytonicTonos(raw)) : toPolytonicTonos(raw);
    const displayPred = showMono ? toMonotonic(predictedForm) : predictedForm;

    const ending = stripDiacritics(raw).toLowerCase().endsWith('των') ? '-των' : (stripDiacritics(raw).toLowerCase().endsWith('ων') ? '-ων' : '—');

    let badge = '';
    if(p.pred === 'oxytone') badge = '<span class="pill">oxytone</span>';
    else if(p.pred === 'barytone') badge = '<span class="pill">barytone</span>';
    else if(p.pred === 'circumflex') badge = '<span class="pill">circumflex</span>';
    else badge = '<span class="pill">out of scope</span>';

    const warn = (p.pred === 'barytone')
      ? '<div class="small warn">Note: for barytone we do <b>not</b> compute the correct non-final accent position; we simply remove accents to show “not-final”.</div>'
      : '';

    out.innerHTML = `
      <div>${badge} <span class="small">(category: <b>${cat}</b>; ${p.source})</span></div>
      <div class="kv">
        <div class="k">Input</div><div class="v">${escapeHtml(displayIn)}</div>
        <div class="k">Ending</div><div class="v">${ending}</div>
        <div class="k">Toy output</div><div class="v"><b>${escapeHtml(displayPred)}</b></div>
        <div class="k">Reason</div><div class="v">${escapeHtml(p.why)}</div>
      </div>
      ${warn}
      <hr>
      <div class="small">Try changing the category radio buttons to see how the toy-rule flips (especially for <code>-ων</code>).</div>
    `;
  }

  function escapeHtml(s){
    return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  // --- Quiz ---
  let current = null;
  let score = {right:0, total:0};

  function deal(){
    current = examples[Math.floor(Math.random()*examples.length)];
    $('#qWord').textContent = $('#chkMonotonic').checked ? toMonotonic(current.w) : current.w;
    $('#qMsg').innerHTML = `<span class="small">Guess the toy prediction for this example.</span>`;
    $('#btnHint').disabled = false;
    $('#btnReveal').disabled = false;
    $('#btnGuessB').disabled = false;
    $('#btnGuessO').disabled = false;
  }

  function hint(){
    if(!current) return;
    const cat = current.cat;
    const h = {
      collective:'Herodian: “collective/περιεκτικόν” → barytone.',
      ethnic:'Herodian: ethnic (ἐθνικόν) can be oxytone (cf. Αὐσών).',
      place:'Herodian: some city/river names are treated as oxytone “as with cities”.',
      person:'Proper-name bucket; passage lists both barytone and “differentiated” oxytone.',
      common:'Common noun bucket; passage notes χιτών oxytone, but many -των default barytone.'
    }[cat] || 'Use the passage’s contrast: default barytone vs marked oxytone.';
    $('#qMsg').innerHTML = `<span class="pill">hint</span> <span class="small">${escapeHtml(h)}</span>`;
  }

  function reveal(){
    if(!current) return;
    const label = current.pred;
    const cls = (label==='oxytone') ? 'good' : (label==='barytone' ? 'warn' : 'warn');
    $('#qMsg').innerHTML = `<span class="pill">reveal</span> <span class="${cls}"><b>${escapeHtml(label)}</b></span> <span class="small">— ${escapeHtml(current.note)}</span>`;
  }

  function guess(which){
    if(!current) return;
    score.total++;
    const ok = (which === current.pred);
    if(ok) score.right++;
    const cls = ok ? 'good' : 'bad';
    const predForm = applyPredictedAccent(current.w, current.pred);
    const showMono = $('#chkMonotonic').checked;
    const disp = showMono ? toMonotonic(predForm) : predForm;
    $('#qMsg').innerHTML = `
      <span class="pill">${ok ? 'correct' : 'nope'}</span>
      <span class="${cls}"><b>${ok ? '✓' : '✗'}</b></span>
      <span class="small">Toy says: <b>${escapeHtml(current.pred)}</b> → ${escapeHtml(disp)}. Score: ${score.right}/${score.total}.</span>
    `;
  }

  // --- Wire up ---
  $('#btnAnalyze').addEventListener('click', () => renderAnalysis($('#inp').value));
  $('#inp').addEventListener('keydown', (e) => { if(e.key==='Enter') renderAnalysis($('#inp').value); });
  $('#btnRandom').addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    $('#inp').value = $('#chkMonotonic').checked ? toMonotonic(ex.w) : ex.w;
    renderAnalysis($('#inp').value);
  });

  $$('input[name=cat]').forEach(r => r.addEventListener('change', () => renderAnalysis($('#inp').value)));
  $('#chkMonotonic').addEventListener('change', () => {
    // refresh displays
    if(current) $('#qWord').textContent = $('#chkMonotonic').checked ? toMonotonic(current.w) : current.w;
    renderAnalysis($('#inp').value);
  });

  $('#btnDeal').addEventListener('click', deal);
  $('#btnHint').addEventListener('click', hint);
  $('#btnReveal').addEventListener('click', reveal);
  $('#btnGuessB').addEventListener('click', () => guess('barytone'));
  $('#btnGuessO').addEventListener('click', () => guess('oxytone'));

  // initial
  $('#inp').value = 'Αὐσών';
  renderAnalysis($('#inp').value);
})();

