const $ = (sel) => document.querySelector(sel);

const examples = [
  {w:"Ἀγλαοφῶν", nt:true, note:"-φων compound + -ντ- → circumflex"},
  {w:"Ξενοφῶν", nt:true, note:"-φων compound + -ντ- → circumflex"},
  {w:"Δημοφῶν", nt:true, note:"-φων compound + -ντ- → circumflex"},
  {w:"Τρύφων", nt:false, note:"-φων not -ντ- → grave"},
  {w:"Σόφων", nt:false, note:"-φων not -ντ- → grave"},
  {w:"Κολοφών", fem:true, note:"noted as acute (as feminine)"},
  {w:"Τολοφών", fem:true, note:"noted as acute (as feminine)"},
  {w:"κατηφών", fem:true, note:"noted as acute (as feminine)"},
  {w:"Τυφῶν", nt:false, note:"circumflex; also Τυφώς"},
  {w:"Βρύχων", nt:false, note:"disyllabic -χων masc → grave"},
  {w:"Τύχων", nt:false, note:"disyllabic -χων masc → grave"},
  {w:"Σπέρχων", nt:false, note:"disyllabic -χων masc → grave"},
  {w:"Τάρχων", nt:false, note:"disyllabic -χων masc → grave"},
  {w:"παχών", month:true, note:"month-name exception → acute"},
  {w:"Πολυσπερχῶν", nt:true, note:"-χων + -ντ- → circumflex (named)"},
  {w:"Βιστών", nt:false, note:"ethnic declined with ο → acute"},
  {w:"Πλατανιστών", nt:false, note:"acute (named)"}
];

// --- Polytonic helpers (best-effort) ---
const combining = {
  acute: "\u0301",
  grave: "\u0300",
  circumflex: "\u0342",
  diaeresis: "\u0308",
  macron: "\u0304",
  breve: "\u0306",
  smooth: "\u0313",
  rough: "\u0314",
  iotaSub: "\u0345"
};

const greekVowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);

function stripAccents(s){
  // Remove combining diacritics; keep base letters.
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function lastVowelIndexNFD(nfd){
  // Find index in NFD string of the last vowel base char.
  for(let i=nfd.length-1;i>=0;i--){
    const ch = nfd[i];
    if(greekVowels.has(ch)) return i;
  }
  return -1;
}

function applyAccentToLastVowel(word, accent){
  const nfd = word.normalize('NFD');
  const i = lastVowelIndexNFD(nfd);
  if(i<0) return word;

  // Remove existing accent marks from that vowel cluster (acute/grave/circumflex)
  // by deleting combining marks immediately after the vowel.
  let out = "";
  for(let k=0;k<nfd.length;k++){
    const ch = nfd[k];
    if(k===i){
      out += ch;
      // skip following combining marks, but keep non-accent diacritics except we will re-add them.
      // We'll collect them and re-add all except accent marks.
      let j=k+1;
      let kept = "";
      while(j<nfd.length && /[\u0300-\u036f]/.test(nfd[j])){
        const m = nfd[j];
        if(m!==combining.acute && m!==combining.grave && m!==combining.circumflex){
          kept += m;
        }
        j++;
      }
      out += kept + combining[accent];
      k = j-1;
    } else {
      out += ch;
    }
  }
  return out.normalize('NFC');
}

function endsWithAny(s, arr){
  return arr.some(x => s.endsWith(x));
}

function guessRule(wordRaw, flags){
  const word = wordRaw.trim();
  const base = stripAccents(word);
  const lower = base.toLowerCase();

  // Identify ending class (very rough)
  const isPhon = endsWithAny(lower, ["φων"]);
  const isChon = endsWithAny(lower, ["χων"]);
  const isOn = !isPhon && !isChon && endsWithAny(lower, ["ων"]);
  const isBiston = lower === "βιστων";
  const isPlataniston = lower === "πλατανιστων";
  const isTyphon = lower === "τυφων";
  const isGlechon = lower === "γληχων";

  // Determine accent expectation on final syllable per passage.
  // We'll output: {accent: 'acute'|'grave'|'circumflex'|null, label, why, confidence}
  let accent = null;
  let why = "";
  let conf = "medium";

  if(isPlataniston){
    accent = "acute";
    why = "Named in the passage as acute: Πλατανιστών.";
    conf = "high";
  } else if(isBiston){
    accent = "acute";
    why = "Herodian: Βιστών (ethnic declined with ο) is acute.";
    conf = "high";
  } else if(isTyphon){
    accent = "circumflex";
    why = "Herodian: Τυφῶν is circumflex (and also said Τυφώς).";
    conf = "high";
  } else if(isPhon){
    if(flags.feminine){
      accent = "acute";
      why = "Herodian notes some -φών forms (e.g. Κολοφών, Τολοφών, κατηφών) are acute ‘as feminines’.";
      conf = "medium";
    } else if(flags.nt){
      accent = "circumflex";
      why = "Rule: masculine compounds in -φων declined with -ντ- take circumflex (e.g. Δημοφῶν).";
      conf = "medium";
    } else {
      accent = "grave";
      why = "Rule: masculine -φων not declined with -ντ- are ‘βαρύνεται’ (shown here as grave on the last syllable).";
      conf = "medium";
    }
  } else if(isChon){
    if(flags.nt){
      accent = "circumflex";
      why = "Named: Πολυσπερχῶν, declined with -ντ-, takes circumflex.";
      conf = "low";
    } else if(flags.month){
      accent = "acute";
      why = "Exception: παχών (month-name) is acute.";
      conf = "medium";
    } else if(flags.feminine && lower.includes("β")){
      accent = "acute";
      why = "Herodian: γλήχων ought to be grave; but if feminine and with β, it is acute (toy toggle).";
      conf = "low";
    } else {
      accent = "grave";
      why = "Rule: disyllabic masculine -χων are ‘βαρύνονται’ unless month-names.";
      conf = "medium";
    }
  } else if(isOn){
    if(flags.nt){
      accent = "circumflex";
      why = "The passage continues: some -ων masculines with final accent and -ντ- declension… (toy extrapolation).";
      conf = "low";
    } else {
      accent = "acute";
      why = "Not enough info here; defaulting to acute on -ών as a toy guess.";
      conf = "low";
    }
  } else {
    accent = null;
    why = "This toy only recognizes endings -φων, -χων, -ων (and a couple named items).";
    conf = "low";
  }

  return {accent, why, conf, base};
}

function confBadge(conf){
  if(conf==="high") return `<span class="badge bOk">high</span>`;
  if(conf==="medium") return `<span class="badge bWarn">medium</span>`;
  return `<span class="badge bBad">low</span>`;
}

function syllabifyRough(word){
  // Very rough: split into chunks ending with a vowel (plus following combining marks).
  const nfd = word.normalize('NFD');
  const chunks = [];
  let cur = "";
  for(let i=0;i<nfd.length;i++){
    const ch = nfd[i];
    cur += ch;
    if(greekVowels.has(ch)){
      // include any following combining marks
      let j=i+1;
      while(j<nfd.length && /[\u0300-\u036f]/.test(nfd[j])){ cur += nfd[j]; j++; }
      i = j-1;
      chunks.push(cur);
      cur = "";
    }
  }
  if(cur) chunks.push(cur);
  return chunks.map(c=>c.normalize('NFC')).filter(x=>x.length);
}

function makeDeclinePlay(word, flags){
  const base = stripAccents(word);
  const lower = base.toLowerCase();
  // playful: show genitive-like with -ντος if -ντ- toggled, else -νος
  if(endsWithAny(lower,["ων"])){
    const stem = base.slice(0, -2); // remove ων
    if(flags.nt) return `${base} → (toy) ${stem}οντος`;
    return `${base} → (toy) ${stem}ωνος`;
  }
  return `${base} → (toy) —`;
}

function renderTargets(word){
  const t = $('#targets');
  t.innerHTML = "";
  const syl = syllabifyRough(word);
  if(!syl.length){
    t.innerHTML = `<div class="mini">(no syllables detected)</div>`;
    return;
  }
  // Offer last 3 syllables as targets: antepenult/penult/ult
  const last = syl.slice(-3);
  const labels = ["antepenult","penult","ult"].slice(3-last.length);
  last.forEach((chunk, idx)=>{
    const lab = labels[idx];
    const btn = document.createElement('button');
    btn.className = 'tgt';
    btn.type = 'button';
    btn.dataset.which = lab;
    btn.textContent = chunk;
    const tag = document.createElement('span');
    tag.className = 'tag';
    tag.textContent = lab;
    btn.appendChild(tag);
    btn.addEventListener('click', ()=>{
      document.querySelectorAll('.tgt').forEach(x=>x.classList.remove('sel'));
      btn.classList.add('sel');
      // Apply accent to last vowel of the chosen chunk by reconstructing word.
      const full = syl.join('');
      const accent = $('#ruleLine').dataset.accent || 'acute';
      // naive: accent last vowel of the whole word if ult; else accent last vowel of penult/antepenult chunk.
      let rebuilt = "";
      const startIndex = syl.length - last.length;
      const targetIndex = startIndex + idx;
      for(let i=0;i<syl.length;i++){
        if(i===targetIndex){
          rebuilt += applyAccentToLastVowel(syl[i], accent);
        } else {
          rebuilt += stripAccents(syl[i]);
        }
      }
      $('#toyForm').textContent = rebuilt;
    });
    t.appendChild(btn);
  });
}

function analyze(){
  const word = $('#inp').value.trim();
  const flags = {
    nt: $('#tglNt').checked,
    feminine: $('#tglFeminine').checked,
    month: $('#tglMonth').checked
  };

  if(!word){
    $('#ruleLine').textContent = '—';
    $('#ruleLine').dataset.accent = '';
    $('#ruleWhy').textContent = 'Type a word to begin.';
    $('#toyForm').textContent = '—';
    $('#decline').textContent = '—';
    $('#targets').innerHTML = '';
    return;
  }

  const g = guessRule(word, flags);
  let shown = stripAccents(word);
  if(g.accent){
    shown = applyAccentToLastVowel(shown, g.accent);
  }

  const accentLabel = g.accent ? g.accent : 'n/a';
  $('#ruleLine').innerHTML = `${shown} <span class="badge">${accentLabel}</span> ${confBadge(g.conf)}`;
  $('#ruleLine').dataset.accent = g.accent || '';
  $('#ruleWhy').textContent = g.why;

  renderTargets(word);
  $('#toyForm').textContent = shown;
  $('#decline').textContent = makeDeclinePlay(word, flags);
}

function loadExample(ex){
  $('#inp').value = ex.w;
  $('#tglNt').checked = !!ex.nt;
  $('#tglFeminine').checked = !!ex.fem;
  $('#tglMonth').checked = !!ex.month;
  analyze();
}

function initChips(){
  const c = $('#chips');
  c.innerHTML = '';
  examples.forEach(ex=>{
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip';
    b.textContent = ex.w;
    b.title = ex.note;
    b.addEventListener('click', ()=>loadExample(ex));
    c.appendChild(b);
  });
}

$('#btnAnalyze').addEventListener('click', analyze);
$('#btnClear').addEventListener('click', ()=>{ $('#inp').value=''; analyze(); });
$('#btnRandom').addEventListener('click', ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  loadExample(ex);
});
$('#inp').addEventListener('keydown', (e)=>{ if(e.key==='Enter') analyze(); });
['#tglNt','#tglFeminine','#tglMonth'].forEach(id=>$(id).addEventListener('change', analyze));

initChips();
analyze();

