:root{
  --bg:#0f1220;
  --card:#171a2b;
  --muted:#aab0d6;
  --text:#eef0ff;
  --accent:#7dd3fc;
  --accent2:#c4b5fd;
  --bad:#fb7185;
  --good:#34d399;
  --line:rgba(255,255,255,.10);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
}
*{box-sizing:border-box}
.wrap{max-width:980px;margin:24px auto;padding:0 16px;color:var(--text);font:16px/1.35 system-ui,-apple-system,Segoe UI,Roboto,Arial,"Noto Sans",sans-serif}
.hdr{background:linear-gradient(135deg, rgba(125,211,252,.12), rgba(196,181,253,.10));border:1px solid var(--line);border-radius:16px;padding:16px 16px 14px;box-shadow:var(--shadow)}
.hdr h1{margin:0 0 6px;font-size:20px;letter-spacing:.2px}
.sub{margin:0;color:var(--muted)}
.panel{margin-top:14px;background:var(--card);border:1px solid var(--line);border-radius:16px;padding:14px;box-shadow:var(--shadow)}
.row{display:flex;gap:10px;align-items:end;margin:10px 0}
.row.two>div{flex:1}
label{display:block;font-size:12px;color:var(--muted);margin:0 0 6px}
input,select,button{border-radius:12px;border:1px solid var(--line);background:#0c0f1c;color:var(--text);padding:10px 12px}
input{width:100%;font-size:18px;letter-spacing:.2px}
select{width:100%}
button{cursor:pointer;font-weight:650}
button#go{background:linear-gradient(135deg, rgba(125,211,252,.22), rgba(196,181,253,.18));border-color:rgba(125,211,252,.35)}
button.ghost{background:transparent}
button:active{transform:translateY(1px)}
.out{margin-top:10px;border-top:1px dashed var(--line);padding-top:12px}
.outHead{display:flex;align-items:baseline;justify-content:space-between;gap:10px}
.out h2{margin:0;font-size:14px;color:var(--muted);font-weight:700;text-transform:uppercase;letter-spacing:.12em}
.mini{color:var(--muted);font-size:12px}
.results{display:grid;gap:10px;margin-top:10px}
.card{border:1px solid var(--line);border-radius:14px;padding:10px 12px;background:rgba(255,255,255,.03)}
.card .top{display:flex;justify-content:space-between;gap:10px;align-items:center}
.form{font-family:var(--mono);font-size:20px;letter-spacing:.2px}
.badge{font-size:12px;color:var(--muted);border:1px solid var(--line);padding:3px 8px;border-radius:999px;white-space:nowrap}
.expl{margin-top:6px;color:var(--muted);font-size:13px}
.kbd{font-family:var(--mono);font-size:12px;border:1px solid var(--line);padding:1px 6px;border-radius:8px;color:var(--text);background:rgba(0,0,0,.25)}
.help{margin-top:12px;color:var(--muted)}
.help summary{cursor:pointer;color:var(--text)}
.note{margin:8px 0 0;font-size:12px;color:var(--muted)}
.ftr{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:10px;color:var(--muted)}
.tag{font-size:12px}
.toast{min-height:18px;font-size:12px;color:var(--good)}
.hl{color:var(--accent)}
.warn{color:var(--bad)}
body{background:radial-gradient(1200px 700px at 20% 0%, rgba(125,211,252,.10), transparent 55%),radial-gradient(900px 600px at 90% 10%, rgba(196,181,253,.10), transparent 55%),var(--bg)}
@media (max-width:720px){
  .row{flex-direction:column;align-items:stretch}
  .outHead{flex-direction:column;align-items:flex-start}
}

