const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const mode = $('#mode');
const dial = $('#dial');
const results = $('#results');
const toast = $('#toast');

const examples = [
  'Ποσειδέων',
  'Ποσειδῶν',
  'ταῶν',
  'Τυφέων',
  'Τυφῶν',
  'Ξενοφῶν',
  'Κτησιφῶν',
  'Χελιδών',
  'γοργών',
  'λαγών'
];

function showToast(msg, ok=true){
  toast.textContent = msg;
  toast.style.color = ok ? 'var(--good)' : 'var(--bad)';
  clearTimeout(showToast._t);
  showToast._t = setTimeout(()=> toast.textContent = '', 1400);
}

function stripPunct(s){
  return (s||'').replace(/[··.,;:!?\[\]{}()«»“”"'’]/g,'').trim();
}

// --- Greek accent utilities (minimal) ---
const ACCENTS = {
  acute: /[\u0301άέήίόύώΆΈΉΊΌΎΏ]/,
  grave: /[\u0300ὰὲὴὶὸὺὼ]/,
  circumflex: /[\u0342ᾶῆῖῦῶ]/
};

function hasAccentChar(ch){
  return ACCENTS.acute.test(ch) || ACCENTS.grave.test(ch) || ACCENTS.circumflex.test(ch);
}

function normalizeNFC(s){
  try { return s.normalize('NFC'); } catch { return s; }
}

function isVowel(ch){
  return /[αεηιουωΑΕΗΙΟΥΩάέήίόύώὰὲὴὶὸὺὼᾶῆῖῦῶϊϋΐΰ]/.test(ch);
}

function lastVowelIndex(s){
  for(let i=s.length-1;i>=0;i--) if(isVowel(s[i])) return i;
  return -1;
}

function addCircumflexToOmega(word){
  // Replace last ω/ώ/ὸ? with ῶ if possible (toy)
  // Prefer plain ω.
  const w = word;
  for(let i=w.length-1;i>=0;i--){
    const ch = w[i];
    if(ch==='ω') return w.slice(0,i)+'ῶ'+w.slice(i+1);
    if(ch==='ώ') return w.slice(0,i)+'ῶ'+w.slice(i+1);
  }
  return word;
}

function addCircumflexToAlpha(word){
  for(let i=word.length-1;i>=0;i--){
    const ch = word[i];
    if(ch==='α') return word.slice(0,i)+'ᾶ'+word.slice(i+1);
    if(ch==='ά') return word.slice(0,i)+'ᾶ'+word.slice(i+1);
  }
  return word;
}

function syllabifyRough(s){
  // Very rough: split before each vowel group.
  const t = normalizeNFC(stripPunct(s));
  const parts=[];
  let cur='';
  for(let i=0;i<t.length;i++){
    const ch=t[i];
    cur+=ch;
    const next=t[i+1];
    if(isVowel(ch) && (!next || !isVowel(next))){
      parts.push(cur);
      cur='';
    }
  }
  if(cur) parts.push(cur);
  return parts.filter(p=>p.length);
}

function accentType(word){
  const w = normalizeNFC(word);
  for(const ch of w){
    if(ACCENTS.circumflex.test(ch)) return 'circumflex';
    if(ACCENTS.acute.test(ch)) return 'acute';
    if(ACCENTS.grave.test(ch)) return 'grave';
  }
  return 'none';
}

// --- contraction / decontraction toy rules ---
function contractToy(input, dialect){
  let s = normalizeNFC(stripPunct(input));
  const notes=[];

  // Common sequences discussed: εω / αω (Poseidéōn / Poseidáōn) -> ω
  // Also allow οο -> ου (toy), εο -> ου (toy-ish), but keep minimal.

  const before = s;

  // Prefer contracting εω/έω/εώ etc.
  const rules = [
    {re:/εω/g, out:'ω', note:'Contract εω → ω'},
    {re:/έω/g, out:'ώ', note:'Contract έω → ώ (toy)'},
    {re:/εώ/g, out:'ώ', note:'Contract εώ → ώ (toy)'},
    {re:/αω/g, out:'ω', note:'Contract αω → ω'},
    {re:/άω/g, out:'ώ', note:'Contract άω → ώ (toy)'},
    {re:/αώ/g, out:'ώ', note:'Contract αώ → ώ (toy)'},
    {re:/οω/g, out:'ω', note:'Contract οω → ω (toy)'},
    {re:/οο/g, out:'ου', note:'Contract οο → ου (toy)'},
    {re:/εο/g, out:'ου', note:'Contract εο → ου (toy)'},
  ];

  for(const r of rules){
    if(r.re.test(s)){
      s = s.replace(r.re, r.out);
      notes.push(r.note);
    }
  }

  // If we contracted to ω/ώ, optionally circumflex it to mimic Herodian’s “acute+grave → circumflex”.
  // We do this only if the result ends in -ων/-ώn-ish.
  if(/ων$/.test(s) || /ώn$/.test(s)){
    // no-op
  }
  if(/ων$/.test(s)){
    // Put circumflex on the ω of -ων if there is no other accent mark.
    if(accentType(s)==='none'){
      s = addCircumflexToOmega(s);
      notes.push('Add circumflex on contracted ω (toy)');
    }
  }

  // Dialect flavor: Aeolic-ish ω→α in longer words (>2 syllables), echoing Ποσίδαν.
  if(dialect==='aeol'){
    const syl = syllabifyRough(s);
    if(syl.length>2 && s.includes('ω')){
      s = s.replace(/ω/g,'α');
      s = s.replace(/ῶ/g,'ᾶ');
      notes.push('Aeolic-ish: ω → α in longer words (toy)');
    }
  }

  // Attic-ish: if ends with -ων and has no accent, circumflex it.
  if(dialect==='att'){
    if(/ων$/.test(s) && accentType(s)==='none'){
      s = addCircumflexToOmega(s);
      notes.push('Attic-ish: mark -ων with circumflex (toy)');
    }
  }

  if(before===s && notes.length===0) notes.push('No contraction rule fired. Try something with εω/αω (e.g. Ποσειδέων).');

  return {out:s, notes};
}

function decontractToy(input){
  const s = normalizeNFC(stripPunct(input));
  const outs=[];
  const notes=[];

  // If contains ω/ῶ before ν, suggest -έων and -άων.
  // Very targeted to the passage.
  if(/ῶν$/.test(s) || /ων$/.test(s)){
    const base = s.replace(/ῶν$/,'ων').replace(/ων$/,'ων');
    // Find the ω in the last syllable and expand.
    const i = base.lastIndexOf('ω');
    if(i!==-1){
      const pre = base.slice(0,i);
      const post = base.slice(i+1); // should be ν
      outs.push(pre+'έω'+post);
      outs.push(pre+'άω'+post);
      notes.push('Suggest diaeresis-style expansions: -έων / -άων (as in Ποσειδέων, Ποσειδάων).');
    }
  }

  // If contains ου, suggest οο.
  if(s.includes('ου')){
    outs.push(s.replace(/ου/g,'οο'));
    notes.push('Toy expansion: ου → οο');
  }

  if(outs.length===0){
    outs.push(s);
    notes.push('Nothing obvious to decontract. Try Ποσειδῶν or another -ων form.');
  }

  // Deduplicate
  const uniq=[...new Set(outs)];
  return {outs:uniq, notes};
}

function accentHelper(input){
  const s = normalizeNFC(stripPunct(input));
  const syl = syllabifyRough(s);
  const last3 = syl.slice(-3);
  const joined = last3.join('');
  const t = accentType(joined);

  let msg = '';
  if(syl.length===0) msg = 'No syllables detected.';
  else {
    msg = `Last syllables (rough): ${last3.map(x=>`<span class="hl">${escapeHtml(x)}</span>`).join(' · ')}.`;
    if(t==='none') msg += ' Accent mark: <span class="warn">none detected</span>.';
    else msg += ` Accent mark detected: <span class="hl">${t}</span>.`;
  }

  // Also show a crude “rule hint” for -ων.
  let hint='';
  if(/ῶν$/.test(s)) hint = 'Ends in <span class="hl">-ῶν</span> (circumflexed ω). Herodian discusses when this is expected vs exceptional (Ποσειδῶν).';
  else if(/ων$/.test(s)) hint = 'Ends in <span class="hl">-ων</span>. Many names in -φῶν are circumflexed (Ξενοφῶν etc.).';
  else if(/δων$/.test(s) || /δῶν$/.test(s)) hint = 'Ends in <span class="hl">-δων</span>. Herodian notes: “nothing circumflexed ends in -δων” (with exceptions debated).';

  return {html: msg + (hint?`<div class="expl" style="margin-top:6px">${hint}</div>`:'')};
}

function escapeHtml(str){
  return (str+'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function addResultCard(form, badge, expl){
  const div = document.createElement('div');
  div.className='card';
  div.innerHTML = `
    <div class="top">
      <div class="form" title="Click to copy">${escapeHtml(form)}</div>
      <div class="badge">${escapeHtml(badge)}</div>
    </div>
    <div class="expl">${expl}</div>
  `;
  div.querySelector('.form').addEventListener('click', async ()=>{
    try{
      await navigator.clipboard.writeText(form);
      showToast('Copied: '+form);
    }catch{
      // Fallback
      const ta=document.createElement('textarea');
      ta.value=form; document.body.appendChild(ta);
      ta.select();
      try{ document.execCommand('copy'); showToast('Copied: '+form); }
      catch{ showToast('Copy failed (browser blocked).', false); }
      ta.remove();
    }
  });
  results.appendChild(div);
}

function run(){
  results.innerHTML='';
  const text = inp.value;
  const m = mode.value;
  const d = dial.value;

  if(!stripPunct(text)){
    addResultCard('', 'Input needed', 'Type a Greek word (e.g. <span class="kbd">Ποσειδέων</span>).');
    return;
  }

  if(m==='contract'){
    const r = contractToy(text, d);
    addResultCard(r.out, 'contract', r.notes.map(n=>`• ${escapeHtml(n)}`).join('<br>'));

    // Show a “compare” card for Poseidōn specifically.
    if(stripPunct(text).includes('Ποσειδ')){
      const base = stripPunct(text);
      addResultCard('Ποσειδέων → Ποσειδῶν', 'Herodian hook', 'Ionian <span class="kbd">Ποσειδέων</span> can be viewed as contracting to <span class="kbd">Ποσειδῶν</span>, motivating a circumflex by contraction (toy reflection of the passage).');
    }
  }

  if(m==='decontract'){
    const r = decontractToy(text);
    r.outs.forEach((o, idx)=>{
      addResultCard(o, idx===0?'decontract':'alt', idx===0 ? r.notes.map(n=>`• ${escapeHtml(n)}`).join('<br>') : 'Alternative expansion.');
    });
  }

  if(m==='accent'){
    const r = accentHelper(text);
    addResultCard(stripPunct(text), 'analyze', r.html);
  }
}

$('#go').addEventListener('click', run);
$('#rand').addEventListener('click', ()=>{
  inp.value = examples[Math.floor(Math.random()*examples.length)];
  run();
});
$('#clear').addEventListener('click', ()=>{
  inp.value='';
  inp.focus();
  results.innerHTML='';
});

inp.addEventListener('keydown', (e)=>{
  if(e.key==='Enter') run();
});

// initial
run();

