(() => {
  const $ = (s) => document.querySelector(s);
  const inp = $('#inp');
  const outWord = $('#outWord');
  const outMeta = $('#outMeta');
  const outExplain = $('#outExplain');
  const chkPoly = $('#chkPoly');
  const chkExplain = $('#chkExplain');

  let mode = 'auto';

  const examples = [
    {w:'Σιδων', hint:'-ων, city → oxytone'},
    {w:'Πλευρων', hint:'-ων, city → oxytone'},
    {w:'Γυρτων', hint:'-ων, city but listed as barytone/marked'},
    {w:'Ασκαλων', hint:'-αλων exception → barytone'},
    {w:'Βαβυλων', hint:'polysyllabic -ων place → oxytone'},
    {w:'Πλουτων', hint:'-των non-place → barytone'},
    {w:'γειτων', hint:'-των non-place → barytone'},
    {w:'κοιτων', hint:'exception mentioned'},
    {w:'Ιτων', hint:'place-name special; locals Ἰτών'},
    {w:'Πορφυρεων', hint:'polysyllabic -ων place → oxytone'}
  ];

  const chips = $('#chips');
  examples.forEach(ex => {
    const b = document.createElement('button');
    b.className = 'chip';
    b.type = 'button';
    b.textContent = ex.w;
    b.title = ex.hint;
    b.addEventListener('click', () => { inp.value = ex.w; render(); inp.focus(); });
    chips.appendChild(b);
  });

  document.querySelectorAll('.segBtn').forEach(btn => {
    btn.addEventListener('click', () => {
      mode = btn.dataset.mode;
      document.querySelectorAll('.segBtn').forEach(b => b.setAttribute('aria-pressed', String(b === btn)));
      render();
    });
  });

  chkPoly.addEventListener('change', render);
  chkExplain.addEventListener('change', render);
  inp.addEventListener('input', render);

  // --- Utilities ---
  const tonosToPoly = {
    'ά':'ά', 'έ':'έ', 'ή':'ή', 'ί':'ί', 'ό':'ό', 'ύ':'ύ', 'ώ':'ώ',
    'Ά':'Ά', 'Έ':'Έ', 'Ή':'Ή', 'Ί':'Ί', 'Ό':'Ό', 'Ύ':'Ύ', 'Ώ':'Ώ'
  };

  const baseToAcute = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };

  const stripDiacritics = (s) => s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');

  const greekify = (s) => {
    // Very small transliteration: enough for toy inputs like PLOUTON, GEITON.
    const map = {
      'TH':'Θ','CH':'Χ','PH':'Φ','PS':'Ψ','KS':'Ξ',
      'A':'Α','B':'Β','G':'Γ','D':'Δ','E':'Ε','Z':'Ζ','H':'Η','I':'Ι','K':'Κ','L':'Λ','M':'Μ','N':'Ν','O':'Ο','P':'Π','R':'Ρ','S':'Σ','T':'Τ','U':'Υ','Y':'Υ','W':'Ω','X':'Χ','Q':'Κ'
    };
    let t = s.trim();
    if (!t) return '';
    // If it already contains Greek letters, keep it.
    if (/[\u0370-\u03FF\u1F00-\u1FFF]/.test(t)) return t;
    t = t.toUpperCase();
    // digraphs
    t = t.replace(/TH|CH|PH|PS|KS/g, m => map[m] || m);
    // single letters
    t = t.replace(/[A-Z]/g, c => map[c] || c);
    // crude: final sigma
    t = t.replace(/Σ\b/g,'ς');
    return t;
  };

  const lastIndexOfAny = (s, chars) => {
    for (let i = s.length - 1; i >= 0; i--) if (chars.includes(s[i])) return i;
    return -1;
  };

  const addAcuteToLastVowel = (word) => {
    const w = word;
    const vowels = 'αεηιουωΑΕΗΙΟΥΩ';
    const idx = lastIndexOfAny(w, vowels);
    if (idx === -1) return w;
    const ch = w[idx];
    const accented = baseToAcute[ch] || ch;
    return w.slice(0, idx) + accented + w.slice(idx + 1);
  };

  const endsWith = (w, suf) => w.slice(-suf.length) === suf;

  // Exceptions / “noted” items from passage (toy list)
  const exceptions = new Map([
    ['ΓΥΡΤΩΝ', {accent:'bary', note:'Listed among marked/barytone city-names.'}],
    ['ΙΤΩΝ', {accent:'bary', note:'Herodian: Ἴτων (barytone) as special; locals may say Ἰτών.'}],
    ['ΑΣΚΑΛΩΝ', {accent:'bary', note:'Noted barytone because -αλων.'}],
    ['ΚΑΣΤΑΛΩΝ', {accent:'bary', note:'Noted barytone because -αλων.'}],
    ['ΣΟΥΛΜΩΝ', {accent:'bary', note:'Noted form in the passage.'}],
    ['ΚΡΟΤΩΝ', {accent:'bary', note:'Has diastole (meaning-distinction) in the passage.'}],
    ['ΚΟΙΤΩΝ', {accent:'bary', note:'Mentioned as the reason for the “not place-name” proviso.'}]
  ]);

  function syllableCountRough(word) {
    // Rough: count vowel groups in stripped Greek.
    const w = stripDiacritics(word);
    const vowels = 'αεηιουωΑΕΗΙΟΥΩ';
    let count = 0;
    let prevV = false;
    for (const ch of w) {
      const isV = vowels.includes(ch);
      if (isV && !prevV) count++;
      prevV = isV;
    }
    return count;
  }

  function decideAccent(word, interpretMode) {
    const raw = word;
    const g = greekify(raw);
    const gStripped = stripDiacritics(g);
    const key = gStripped.toUpperCase();

    if (!gStripped) return {status:'empty'};

    // Only handle single word for rules; if phrase, take last token.
    const tokens = gStripped.split(/\s+/).filter(Boolean);
    const target = tokens[tokens.length - 1];
    const targetKey = target.toUpperCase();

    const syl = syllableCountRough(target);

    // Exception check
    if (exceptions.has(targetKey)) {
      const ex = exceptions.get(targetKey);
      return {
        status:'ok',
        input:gStripped,
        target,
        accent: ex.accent,
        rule: 'exception',
        note: ex.note,
        syl
      };
    }

    const isOn = endsWith(target, 'ων') || endsWith(target, 'ών') || endsWith(target, 'ΟΝ') || endsWith(target, 'ΩΝ');
    const isTon = endsWith(target, 'των') || endsWith(target, 'ΤΩΝ') || endsWith(target, 'τών');

    if (!(isOn || isTon)) {
      return {
        status:'warn',
        input:gStripped,
        target,
        accent:null,
        rule:'none',
        note:'This toy only guesses for endings -ων / -των.' ,
        syl
      };
    }

    // Determine place vs non-place
    let place = null;
    if (interpretMode === 'place') place = true;
    else if (interpretMode === 'nonplace') place = false;
    else {
      // auto: guess place if capitalized initial or contains typical toponymic vibe (very naive)
      place = /^[Α-Ω]/.test(target) || /^[A-Z]/.test(raw.trim());
    }

    // Rules of thumb from passage
    // 1) Disyllabic -ων place-names -> oxytone
    if (isOn && syl === 2 && place) {
      return {status:'ok', input:gStripped, target, accent:'oxy', rule:'disyllabic -ων place', note:'Disyllables in -ων, when city-names, tend to be oxytone (…ών).', syl, place};
    }

    // 2) Polysyllabic -ων place-names -> oxytone unless -αλων/-λων with alpha before last
    if (isOn && syl > 2 && place) {
      const t = stripDiacritics(target);
      const tKey = t.toUpperCase();
      const endsAlon = /αλων$/i.test(t);
      const endsLonWithA = /αλων$/i.test(t) || /[Αα]λων$/.test(t); // keep simple
      if (endsAlon || endsLonWithA) {
        return {status:'ok', input:gStripped, target, accent:'bary', rule:'-αλων exception', note:'Exception: -αλων (or -λων with α before the end) tends to be barytone (e.g. Ἀσκάλων).', syl, place};
      }
      return {status:'ok', input:gStripped, target, accent:'oxy', rule:'polysyllabic -ων place', note:'Polysyllabic -ων place-names tend to be oxytone (…ών), with some exceptions.', syl, place};
    }

    // 3) Disyllabic -των non-place -> barytone (penult naturally long; toy assumes it)
    if (isTon && syl === 2 && !place) {
      return {status:'ok', input:gStripped, target, accent:'bary', rule:'disyllabic -των non-place', note:'Disyllables in -των (with long penult) tend to be barytone when not place-names (Πλούτων, γείτων…).', syl, place};
    }

    // Fallbacks
    if (isTon && place) {
      return {status:'ok', input:gStripped, target, accent:'bary', rule:'-των default', note:'Toy default: -των often barytone; place-names may vary (cf. Ἴτων vs locals Ἰτών).', syl, place};
    }

    if (isOn && !place) {
      return {status:'ok', input:gStripped, target, accent:'bary', rule:'-ων non-place default', note:'Toy default: if not a place-name, treat -ων as barytone unless known otherwise.', syl, place};
    }

    return {status:'ok', input:gStripped, target, accent:'oxy', rule:'fallback', note:'Fallback guess: oxytone.', syl, place};
  }

  function applyAccent(target, accent) {
    // We only add an acute on the last vowel for oxytone.
    // For barytone we leave unaccented (or keep existing).
    const hasAnyAccent = /[άέήίόύώΆΈΉΊΌΎΏ]/.test(target) || /[\u0301\u0342\u0300]/.test(target.normalize('NFD'));
    if (hasAnyAccent) return target; // respect user accents
    if (accent === 'oxy') return addAcuteToLastVowel(target);
    return target;
  }

  function render() {
    const res = decideAccent(inp.value, mode);

    if (res.status === 'empty') {
      outWord.textContent = '—';
      outMeta.textContent = '';
      outExplain.textContent = '';
      return;
    }

    const showExplain = chkExplain.checked;

    if (res.status === 'warn') {
      outWord.textContent = res.target;
      outMeta.innerHTML = `<span class="badge warn">limited</span> syllables≈${res.syl}`;
      outExplain.textContent = showExplain ? res.note : '';
      return;
    }

    const accented = chkPoly.checked ? applyAccent(res.target, res.accent) : res.target;

    // Rebuild phrase if needed
    const g = greekify(inp.value);
    const gStripped = stripDiacritics(g);
    const tokens = gStripped.split(/\s+/).filter(Boolean);
    tokens[tokens.length - 1] = accented;
    const rebuilt = tokens.join(' ');

    outWord.textContent = rebuilt;

    const badgeClass = res.rule === 'exception' ? 'warn' : 'ok';
    const accentLabel = res.accent === 'oxy' ? 'oxytone (…ών)' : 'barytone (…ων)';
    const placeLabel = (res.place === true) ? 'place-name' : (res.place === false ? 'not place-name' : '');

    outMeta.innerHTML = [
      `<span class="badge ${badgeClass}">${accentLabel}</span>`,
      placeLabel ? `<span class="badge">${placeLabel}</span>` : '',
      `<span class="badge">syllables≈${res.syl}</span>`,
      `<span class="badge">rule: ${res.rule}</span>`
    ].filter(Boolean).join(' ');

    outExplain.textContent = showExplain ? (res.note || '') : '';
  }

  // seed
  inp.value = 'Σιδων';
  render();
})();

