// Herodian -ων accent toy (approximate)
(function(){
  const $ = (sel) => document.querySelector(sel);
  const inp = $('#inp');
  const mode = $('#mode');
  const normEl = $('#norm');
  const resEl = $('#res');
  const syllEl = $('#syll');
  const noteEl = $('#note');

  const examples = [
    'μειζων','ολιζων','κρεισσων','ησσων','θασσων','ελαττων','αμεινων','χειρων','πλειων','μειων','αρειων','βελτιων','ηδιων','γλυκιων','κακιων','βραχιων',
    'περικτιων','αμφικτιων','ιθυκτιων'
  ];

  // --- Greek helpers ---
  const combining = /[\u0300-\u036f]/g; // includes tonos/oxia etc.

  function stripDiacritics(s){
    return (s || '').normalize('NFD').replace(combining,'').normalize('NFC');
  }

  function normalizeGreek(s){
    s = (s||'').trim();
    // normalize final sigma
    s = s.replace(/\s+/g,' ');
    s = s.normalize('NFC');
    return s;
  }

  function toLowerGreek(s){
    return s.toLowerCase();
  }

  function isVowel(ch){
    return 'αεηιουω'.includes(ch);
  }

  function roughSyllabify(word){
    // Very rough: split before each vowel group (diphthongs treated as one group).
    // Works decently for showing penult/ultima targets.
    const w = stripDiacritics(toLowerGreek(word));
    if(!w) return [];

    const diph = new Set(['αι','ει','οι','υι','αυ','ευ','ηυ','ου','ωυ']);
    let parts = [];
    let i = 0;
    while(i < w.length){
      // find next vowel
      let start = i;
      while(i < w.length && !isVowel(w[i])) i++;
      if(i >= w.length){
        // trailing consonants
        if(parts.length) parts[parts.length-1] += w.slice(start);
        else parts.push(w);
        break;
      }
      // include onset consonants with this syllable
      let onset = w.slice(start, i);
      // vowel nucleus
      let nuc = w[i];
      if(i+1 < w.length && isVowel(w[i+1])){
        const pair = w.slice(i, i+2);
        if(diph.has(pair)){
          nuc = pair;
          i += 2;
        } else {
          // hiatus: keep single vowel
          i += 1;
        }
      } else {
        i += 1;
      }
      parts.push(onset + nuc);
    }
    // Now reattach remaining consonants between syllables to the following syllable already handled.
    // But consonants after a vowel before next vowel are currently in onset of next syllable; ok.
    return parts.filter(Boolean);
  }

  function accentuate(word, target){
    // target: 'ultima' or 'penult'
    // Place an acute (U+0301) on the first vowel of the target syllable.
    const original = normalizeGreek(word);
    const base = stripDiacritics(original);
    const low = toLowerGreek(base);

    const sylls = roughSyllabify(low);
    if(sylls.length === 0) return {out: original, sylls: []};

    let idx = sylls.length - 1;
    if(target === 'penult' && sylls.length >= 2) idx = sylls.length - 2;

    // Find start index of that syllable in the string
    let start = 0;
    for(let k=0;k<idx;k++) start += sylls[k].length;
    let end = start + sylls[idx].length;

    // Find first vowel position within [start,end)
    const s = low;
    let vpos = -1;
    for(let p=start;p<end;p++){
      if(isVowel(s[p])){ vpos = p; break; }
    }
    if(vpos === -1) return {out: original, sylls};

    // Build accented output in NFC
    const acute = '\u0301';
    const nfd = s.normalize('NFD');
    // Map vpos in NFC-ish string to NFD index: since we stripped diacritics, 1:1 for Greek letters.
    const before = nfd.slice(0, vpos+1);
    const after = nfd.slice(vpos+1);
    const out = (before + acute + after).normalize('NFC');

    // Restore final sigma if word ends with ς in original or should be final
    const restored = out.replace(/σ\b/g,'ς');
    return {out: restored, sylls};
  }

  function endsWithOn(word){
    const w = stripDiacritics(toLowerGreek(normalizeGreek(word)));
    return /ων$/.test(w);
  }

  function render(){
    const raw = normalizeGreek(inp.value);
    if(!raw){
      normEl.textContent = '—';
      resEl.textContent = '—';
      syllEl.textContent = '—';
      noteEl.textContent = '—';
      return;
    }

    const n = stripDiacritics(toLowerGreek(raw)).replace(/σ\b/g,'ς');
    normEl.textContent = n;

    const on = endsWithOn(raw);
    const m = mode.value;

    let outText = '';
    let note = '';
    let sylls = roughSyllabify(n);

    if(!on){
      // still accent something for fun: default penult
      const a = accentuate(raw, 'penult');
      outText = a.out;
      sylls = a.sylls;
      note = 'Does not look like -ων. I still put an acute on the penult (toy behavior).';
    } else {
      if(m === 'bary'){
        const a = accentuate(raw, 'penult');
        outText = a.out;
        sylls = a.sylls;
        note = 'Herodian: comparatives in -ων are barytone → accent on the penult (approx.).';
      } else if(m === 'oxy'){
        const a = accentuate(raw, 'ultima');
        outText = a.out;
        sylls = a.sylls;
        note = 'Oxytone (accent on ultima): like the “common usage” βραχιών that Herodian rejects.';
      } else {
        const b = accentuate(raw, 'penult');
        const o = accentuate(raw, 'ultima');
        outText = b.out + '   |   ' + o.out;
        sylls = b.sylls;
        note = 'Auto: showing barytone (left) vs oxytone (right).';
      }
    }

    resEl.textContent = outText;
    syllEl.textContent = sylls.length ? sylls.join(' · ') : '—';
    noteEl.textContent = note;
  }

  $('#go').addEventListener('click', render);
  $('#clear').addEventListener('click', () => { inp.value=''; render(); inp.focus(); });
  $('#rand').addEventListener('click', () => {
    const w = examples[Math.floor(Math.random()*examples.length)];
    inp.value = w;
    render();
    inp.focus();
  });
  inp.addEventListener('keydown', (e) => { if(e.key === 'Enter') render(); });
  inp.addEventListener('input', () => { /* live preview, but light */ render(); });
  mode.addEventListener('change', render);

  // Quiz
  const quizData = [
    {plain:'μειζων', label:'comparative', correct:'bary'},
    {plain:'πλειων', label:'comparative', correct:'bary'},
    {plain:'βελτιων', label:'comparative', correct:'bary'},
    {plain:'βραχιων', label:'comparative / body-part', correct:'bary', note:'Herodian explicitly prefers βαρυτονία here.'},
    {plain:'αμφικτιων', label:'compound (not comparative)', correct:'bary', note:'Herodian: keeps accent “in common with the gender”; penult is short.'}
  ];

  function buildQuiz(){
    const host = $('#quiz');
    host.innerHTML = '';
    quizData.forEach((q, i) => {
      const card = document.createElement('div');
      card.className = 'qcard';

      const top = document.createElement('div');
      top.className = 'qtop';

      const w = document.createElement('div');
      w.className = 'qword';
      w.textContent = q.plain;

      const btn = document.createElement('button');
      btn.className = 'qbtn';
      btn.type = 'button';
      btn.textContent = 'Reveal';

      top.appendChild(w);
      top.appendChild(btn);

      const ans = document.createElement('div');
      ans.className = 'qans';

      const lab = document.createElement('div');
      lab.className = 'lab';
      lab.textContent = 'Herodian-style barytone vs oxytone';

      const val = document.createElement('div');
      val.className = 'val';
      const bary = accentuate(q.plain, 'penult').out;
      const oxy = accentuate(q.plain, 'ultima').out;
      val.innerHTML = '<span class="good">' + bary + '</span>  vs  <span class="bad">' + oxy + '</span>';

      const meta = document.createElement('div');
      meta.className = 'small';
      meta.style.marginTop = '6px';
      meta.textContent = (q.note ? (q.label + ' — ' + q.note) : q.label);

      ans.appendChild(lab);
      ans.appendChild(val);
      ans.appendChild(meta);

      btn.addEventListener('click', () => {
        const open = ans.style.display === 'block';
        ans.style.display = open ? 'none' : 'block';
        btn.textContent = open ? 'Reveal' : 'Hide';
      });

      card.appendChild(top);
      card.appendChild(ans);
      host.appendChild(card);
    });
  }

  buildQuiz();
  // initial
  inp.value = 'βραχιων';
  render();
})();

