const $ = (sel) => document.querySelector(sel);

// --- Greek helpers (toy-level) ---
const COMBINING = /[\u0300-\u036f]/g;

function stripCombining(s){
  return s.normalize('NFD').replace(COMBINING,'').normalize('NFC');
}

function normalizeGreek(s){
  // Keep Greek letters, spaces, hyphen; remove punctuation.
  s = (s || '').trim();
  s = s.replace(/[··.,;:!?()\[\]{}"'“”‘’]/g,'');
  // Normalize to NFC for display.
  return s.normalize('NFC');
}

function endsWithAx(s){
  const bare = stripCombining(s).toLowerCase();
  return bare.endsWith('αξ');
}

function greekVowelish(ch){
  // treat αι, ει, οι, υι, αυ, ευ, ου, ηυ as diphthongs later; here just vowel set
  return 'αεηιουω'.includes(ch);
}

function roughSyllables(word){
  // Very rough syllable count: count vowel nuclei, merging common diphthongs.
  const w = stripCombining(word).toLowerCase();
  let i=0, n=0;
  const diph = new Set(['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ωυ']);
  while(i < w.length){
    const ch = w[i];
    if(greekVowelish(ch)){
      const pair = w.slice(i,i+2);
      if(diph.has(pair)) i += 2;
      else i += 1;
      n += 1;
      continue;
    }
    i += 1;
  }
  return Math.max(n, 0);
}

function looksCompound(word){
  // playful heuristic: common first members seen in Herodian list
  const w = stripCombining(word).toLowerCase();
  const prefixes = [
    'πολυ','φιλο','χαρτο','λινο','ἐρι','ερι','ἀχαρνο','αχαρνο','σαμοθρ','ἱππ','ιππ','ἀρχ','αρχ','θυμελ','ὀρθι','ορθι'
  ];
  return prefixes.some(p => w.startsWith(p));
}

function guessAccentType(word){
  const syl = roughSyllables(word);
  if(!endsWithAx(word)) return {type:'unknown', reason:'Does not end in -αξ (after stripping diacritics).', syl};
  if(syl <= 1) return {type:'unknown', reason:'Monosyllables are outside the stated rule.', syl};
  if(looksCompound(word)) return {type:'oxytone', reason:'Looks like a compound (toy heuristic) → oxytone.', syl};
  return {type:'barytone', reason:'Multi-syllable -αξ noun → barytone (default).', syl};
}

function accentuateToy(word, type){
  // Place an acute on the vowel of the chosen syllable nucleus.
  // barytone: accent penult; oxytone: accent ultima.
  // If we can’t find enough syllables, return original.
  const original = normalizeGreek(word);
  const wNFD = original.normalize('NFD');

  // Build list of vowel nuclei positions in NFD string (base vowel indices).
  const bases = [];
  for(let i=0;i<wNFD.length;i++){
    const ch = wNFD[i];
    // base Greek vowels in NFD are still single codepoints
    if('αεηιουωΑΕΗΙΟΥΩ'.includes(ch)){
      // skip if this vowel is part of a diphthong nucleus: we will treat diphthongs by marking first vowel only
      bases.push(i);
    }
  }
  if(bases.length === 0) return original;

  // Determine syllable nuclei with diphthong merging on the stripped string,
  // but map approximately to NFD indices by scanning again.
  const stripped = stripCombining(original);
  const low = stripped.toLowerCase();
  const diph = new Set(['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ωυ']);

  // Map nuclei to indices in stripped string
  const nucleiStrIdx = [];
  for(let i=0;i<low.length;i++){
    if(greekVowelish(low[i])){
      nucleiStrIdx.push(i);
      const pair = low.slice(i,i+2);
      if(diph.has(pair)) i += 1;
    }
  }
  if(nucleiStrIdx.length === 0) return original;

  let targetNucleus = nucleiStrIdx.length - 1; // ultima
  if(type === 'barytone') targetNucleus = Math.max(0, nucleiStrIdx.length - 2); // penult

  // Find corresponding vowel in NFD by walking through stripped string and NFD together.
  // We’ll locate the NFD index of the base vowel at that stripped index.
  let si = 0;
  let targetStrIndex = nucleiStrIdx[targetNucleus];
  let targetNFDIndex = null;

  for(let i=0;i<wNFD.length;i++){
    const ch = wNFD[i];
    if(ch.match(COMBINING)) continue;
    // ch is a base character
    if(si === targetStrIndex){
      targetNFDIndex = i;
      break;
    }
    si += 1;
  }
  if(targetNFDIndex == null) return original;

  // Remove existing accent marks (acute/grave/circumflex) from the whole word, then add acute to target vowel.
  const removeAccents = /[\u0300\u0301\u0342]/g; // grave, acute, perispomeni
  let chars = Array.from(wNFD.replace(removeAccents,''));

  // After removing accents, indices may shift; recompute target index similarly.
  const wNFD2 = chars.join('');
  si = 0; targetNFDIndex = null;
  for(let i=0;i<wNFD2.length;i++){
    const ch = wNFD2[i];
    if(ch.match(COMBINING)) continue;
    if(si === targetStrIndex){ targetNFDIndex = i; break; }
    si += 1;
  }
  if(targetNFDIndex == null) return original;

  // Insert combining acute after the base vowel.
  chars.splice(targetNFDIndex+1, 0, '\u0301');
  return chars.join('').normalize('NFC');
}

// --- UI wiring ---
const examples = [
  'κόλαξ','φύλαξ','ἄναξ','βόαξ','φέναξ','κόρδαξ','ἅρπαξ','χάραξ','θώραξ','οἴαξ','κλῖμαξ','λεῖμαξ','μεῖραξ','ἱέραξ',
  'Σαμόθρᾳξ','Ἱππῶναξ','Ἀρχεάναξ','χαρτοφύλαξ','πολυπῖδαξ','ἐριβῶλαξ','θυμέλαξ','ὀρθίαξ','ἀσπάλαξ','αὖλαξ'
];

function renderAnalysis(word){
  const w = normalizeGreek(word);
  $('#norm').textContent = w || '—';

  const info = guessAccentType(w);
  $('#syll').textContent = w ? String(info.syl) : '—';

  let g = '—';
  if(w){
    if(info.type === 'barytone') g = 'Barytone (toy guess)';
    else if(info.type === 'oxytone') g = 'Oxytone (toy guess)';
    else g = 'Unknown / not applicable';
  }
  $('#guess').textContent = g;

  const accented = (w && (info.type==='barytone' || info.type==='oxytone')) ? accentuateToy(w, info.type) : (w || '—');
  $('#accented').textContent = accented;
  $('#accented').title = info.reason;
}

$('#btnAnalyze').addEventListener('click', () => renderAnalysis($('#inp').value));
$('#inp').addEventListener('keydown', (e) => { if(e.key === 'Enter') renderAnalysis($('#inp').value); });
$('#btnShuffle').addEventListener('click', () => {
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#inp').value = ex;
  renderAnalysis(ex);
});

// --- Card game ---
let dealt = [];
let picks = 0;

function makeCard(word){
  const div = document.createElement('div');
  div.className = 'cardlet';
  div.tabIndex = 0;
  div.setAttribute('role','button');
  div.setAttribute('aria-label', `Card: ${word}`);

  const w = document.createElement('div');
  w.className = 'w';
  w.textContent = word;

  const meta = document.createElement('div');
  meta.className = 'meta';
  meta.textContent = 'Click to reveal';

  const badge = document.createElement('div');
  badge.className = 'badge unk';
  badge.textContent = '???';

  const reveal = document.createElement('div');
  reveal.className = 'reveal';
  reveal.textContent = '';

  div.appendChild(w);
  div.appendChild(meta);
  div.appendChild(badge);
  div.appendChild(reveal);

  function doReveal(){
    if(div.dataset.revealed === '1') return;
    div.dataset.revealed = '1';
    const info = guessAccentType(word);
    const acc = (info.type==='barytone' || info.type==='oxytone') ? accentuateToy(word, info.type) : word;
    if(info.type==='barytone'){
      badge.className = 'badge bary';
      badge.textContent = 'Barytone';
    } else if(info.type==='oxytone'){
      badge.className = 'badge oxy';
      badge.textContent = 'Oxytone';
    } else {
      badge.className = 'badge unk';
      badge.textContent = 'Unknown';
    }
    reveal.textContent = `toy accent: ${acc}`;
    meta.textContent = info.reason;
    picks += 1;
    $('#score').textContent = `Revealed ${picks} / ${dealt.length}.`;
  }

  div.addEventListener('click', doReveal);
  div.addEventListener('keydown', (e)=>{ if(e.key==='Enter' || e.key===' ') { e.preventDefault(); doReveal(); } });
  return div;
}

function deal(){
  picks = 0;
  const pool = [...examples];
  // add a few unaccented variants for fun
  pool.push('κοραξ','φυλαξ','χαραξ','θωραξ','κλιμαξ','λειμαξ','ιεραξ','σαμοθραξ','ιππωναξ','χαρτοφυλαξ','πολυπιδαξ');

  dealt = [];
  while(dealt.length < 6 && pool.length){
    const idx = Math.floor(Math.random()*pool.length);
    dealt.push(pool.splice(idx,1)[0]);
  }

  const box = $('#cards');
  box.innerHTML = '';
  dealt.forEach(w => box.appendChild(makeCard(w)));
  $('#score').textContent = 'Pick a card…';
}

$('#btnDeal').addEventListener('click', deal);
$('#btnReveal').addEventListener('click', ()=>{
  document.querySelectorAll('.cardlet').forEach(c=>c.click());
});

// initial state
renderAnalysis('κόλαξ');
deal();

