const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const mode = $('#mode');
const endingEl = $('#ending');
const accentedEl = $('#accented');
const explainEl = $('#explain');
const sandboxEl = $('#sandbox');

const examples = [
  'Ασφαξ','Ατραξ','Λελεξ','Βερεξ','επιτεξ','αγχιτεξ','πινυταλεξ',
  'Αλλοβροξ','ισοξ','αλοξ','αυλαξ','Καππαδοξ','φοινιξ','βεμβιξ','Τεμμιξ','πεμφιξ','τεττιξ','σκανδιξ','περδιξ','χοινιξ','Κιλιξ','Αιθιξ','Ερνιξ'
];

// --- Greek helpers (toy-level) ---
const combining = /[\u0300-\u036f]/g;

function stripDiacritics(s){
  // Remove combining marks after NFD; also remove Greek tonos/dialytika if precomposed.
  return s.normalize('NFD').replace(combining,'').normalize('NFC');
}

function isUpperGreek(ch){
  return ch === ch.toUpperCase() && ch !== ch.toLowerCase();
}

function toggleCaseGreek(s){
  // naive: if first cased letter is upper, lower all; else upper first letter.
  const letters = [...s];
  const first = letters.find(c => c.toLowerCase() !== c.toUpperCase());
  if(!first) return s;
  if(isUpperGreek(first)) return s.toLowerCase();
  // Title-case-ish
  return s.charAt(0).toUpperCase() + s.slice(1);
}

const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

function vowelGroups(s){
  // crude syllable proxy: count transitions into vowel sequences
  const chars = [...s];
  let groups = [];
  let cur = '';
  let inV = false;
  for(const c of chars){
    const v = vowels.has(c);
    if(v){
      if(!inV){
        if(cur) groups.push({type:'C', text:cur});
        cur = c;
        inV = true;
      } else {
        cur += c;
      }
    } else {
      if(inV){
        groups.push({type:'V', text:cur});
        cur = c;
        inV = false;
      } else {
        cur += c;
      }
    }
  }
  if(cur) groups.push({type: inV ? 'V':'C', text:cur});
  return groups.filter(g => g.type==='V').map(g=>g.text);
}

function detectEnding(base){
  const s = base;
  const low = s.toLowerCase();
  const endings = ['αξ','εξ','οξ','ιξ','ηξ','υξ','ωξ','ξ'];
  for(const e of endings){
    if(low.endsWith(e)) return e;
  }
  return '—';
}

function accentuateToy(word, target){
  // target: 'ultima' or 'penult'
  // We place an acute on the first vowel of the target syllable (proxy via vowel groups).
  const plain = stripDiacritics(word);
  const groups = vowelGroups(plain);
  const n = groups.length;
  if(n === 0) return {out: plain, note: 'No vowels detected.'};

  let idx = 0;
  if(target === 'ultima') idx = n-1;
  else if(target === 'penult') idx = Math.max(0, n-2);
  else idx = n-1;

  // Find position of the vowel group idx in the string
  const chars = [...plain];
  let vg = -1;
  let inV = false;
  let start = -1;
  for(let i=0;i<chars.length;i++){
    const v = vowels.has(chars[i]);
    if(v && !inV){
      vg++;
      inV = true;
      if(vg === idx){ start = i; break; }
    }
    if(!v) inV = false;
  }
  if(start < 0) return {out: plain, note: 'Could not locate syllable.'};

  // Add tonos to that vowel (acute). Use precomposed where possible.
  const map = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };
  const c = chars[start];
  chars[start] = map[c] || c;
  return {out: chars.join(''), note: `Accent placed on ${target === 'ultima' ? 'ultima' : 'penult'} (toy).`};
}

function sandboxForms(plain){
  const low = plain.toLowerCase();
  const end = detectEnding(plain);
  let lines = [];

  // A playful set of alternations inspired by the passage.
  if(end === 'οξ'){
    // Καππάδοξ ~ Καππάδοκος ~ Καππαδόκης
    const stem = plain.slice(0, -2);
    const a = accentuateToy(stem + 'οξ', 'penult').out;
    const b = accentuateToy(stem + 'οκος', 'penult').out;
    const c = accentuateToy(stem + 'οκης', 'penult').out;
    lines.push(`${a}  →  ${b}  /  ${c}`);
    lines.push('Try reading these as: ethnic (in -οξ) vs. “genitive-like” (-οκος) vs. -οκης variant.' );
  } else if(['αξ','εξ','ιξ'].includes(end)){
    const stem = plain.slice(0, -2);
    const bary = accentuateToy(plain, 'penult').out;
    const oxy = accentuateToy(plain, 'ultima').out;
    lines.push(`${bary} (barytone feel)  vs.  ${oxy} (oxytone feel)`);
    lines.push(`Toy stem: ${stem}- … (imagine ethnic/name labels like Herodian’s Ἄσφαξ, Ἄτραξ, φοῖνιξ).`);
  } else if(end === 'ξ'){
    const bary = accentuateToy(plain, 'penult').out;
    const oxy = accentuateToy(plain, 'ultima').out;
    lines.push(`${bary}  vs.  ${oxy}`);
  } else {
    lines.push('No -ξ ending detected; still you can accent barytone/oxytone with the rule menu.');
  }

  return lines.map(l => `• ${l}`).join('\n');
}

function transform(){
  const raw = inp.value.trim();
  if(!raw){
    endingEl.textContent = '—';
    accentedEl.textContent = '—';
    explainEl.textContent = 'Type a Greek word.';
    sandboxEl.textContent = '—';
    return;
  }

  const plain = stripDiacritics(raw);
  const end = detectEnding(plain);
  endingEl.textContent = end;

  let res;
  if(mode.value === 'none'){
    res = {out: plain, note: 'Accents stripped.'};
  } else if(mode.value === 'oxytone'){
    res = accentuateToy(plain, 'ultima');
  } else {
    // barytone
    res = accentuateToy(plain, 'penult');
  }

  accentedEl.textContent = res.out;

  // Explain with a nod to Herodian
  const herod = (['εξ','οξ','ιξ'].includes(end) || end==='αξ')
    ? 'Herodian notes many -εξ/-οξ/-ιξ (and examples in -αξ) are “βαρύνεται” (barytone).'
    : 'Herodian’s passage focuses on several -ξ endings; this toy still lets you try barytone/oxytone.';

  const sylls = vowelGroups(plain).length;
  explainEl.textContent = `${res.note} Vowel-groups (toy syllables): ${sylls}. ${herod}`;

  sandboxEl.textContent = sandboxForms(plain);
}

$('#go').addEventListener('click', transform);
$('#rand').addEventListener('click', () => {
  inp.value = examples[Math.floor(Math.random()*examples.length)];
  transform();
});
$('#swap').addEventListener('click', () => {
  inp.value = toggleCaseGreek(inp.value);
  transform();
});

inp.addEventListener('keydown', (e) => {
  if(e.key === 'Enter') transform();
});
mode.addEventListener('change', transform);

for(const chip of document.querySelectorAll('.chip')){
  chip.addEventListener('click', () => {
    inp.value = chip.getAttribute('data-fill');
    transform();
  });
}

transform();

