passages.gadget_js:
const $ = (sel, el=document) => el.querySelector(sel);
const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

const examples = [
  "φάρυξ",
  "λάρυγξ",
  "ἴυγξ",
  "ὄρτυξ",
  "κόκκυξ",
  "σπινθάρυξ",
  "πομφόλυξ",
  "Ἰᾶπυξ",
  "μύρμηξ",
  "σκώληξ",
  "νάρθηξ",
  "ἀλώπηξ",
  "πτερύξ"
];

// --- Greek helpers (toy-level) ---
const COMBINING = /[\u0300-\u036f]/g;

function stripCombining(s){ return s.normalize('NFD').replace(COMBINING,'').normalize('NFC'); }

function countGamma(s){
  const plain = stripCombining(s);
  let n=0;
  for(const ch of plain){ if(ch === 'γ' || ch === 'Γ') n++; }
  return n;
}

function endsWithAny(s, arr){
  const plain = stripCombining(s);
  return arr.some(e => plain.endsWith(e));
}

function replaceEnding(word, from, to){
  const plain = stripCombining(word);
  if(!plain.endsWith(from)) return null;
  // Replace on plain, then try to map back by slicing original length.
  // We keep original prefix (with accents) by slicing by codepoints length of from.
  const wArr = Array.from(word);
  const fromArr = Array.from(from);
  const prefix = wArr.slice(0, wArr.length - fromArr.length).join('');
  return prefix + to;
}

function guessPattern(word){
  const plain = stripCombining(word);
  if(plain.length === 0) return {kind:"empty"};

  // Order matters: -υγξ before -υξ
  if(plain.endsWith("υγξ")) return {kind:"-υγξ", gen: replaceEnding(word, "υγξ", "υγγος"), alt: replaceEnding(word, "υγξ", "υγος")};
  if(plain.endsWith("υξ")) return {kind:"-υξ", gen: replaceEnding(word, "υξ", "υγος"), alt: replaceEnding(word, "υξ", "υγγος")};
  if(plain.endsWith("ηξ")) return {kind:"-ηξ", gen: replaceEnding(word, "ηξ", "ηκος"), alt: null};
  if(plain.endsWith("ιξ")) return {kind:"-ιξ", gen: replaceEnding(word, "ιξ", "ικος"), alt: null};
  return {kind:"other", gen:null, alt:null};
}

function accentHint(word, school){
  const plain = stripCombining(word);
  // Special-casing the passage’s famous dispute.
  if(plain === stripCombining("πτερύξ")){
    if(school === 'aristarchus'){
      return {form:"πτερύξ (ὀξύτονον)", note:"Aristarchus marks πτερύξ as oxytone (accent on the last syllable), ‘because it is inclusive in sense’."};
    }
    if(school === 'others'){
      return {form:"πτέρυγος (προπαροξύτονον)", note:"Herodian reports that others accent the genitive πτέρυγος proparoxytone, like ὄρτυγος."};
    }
    return {form:"πτερύξ / πτέρυγος (disputed)", note:"Try switching the radio buttons to see the two traditions mentioned by Herodian."};
  }

  // Heuristic: -υξ often treated as oxytone in the passage’s list.
  if(endsWithAny(word,["υξ"])){
    return {form:"(hint) likely ὀξύτονον", note:"Herodian lists many -υξ words and says they ‘signify anything ending in -υξ with an acute’ (toy hint: accent tends to be sharp/oxytone)."};
  }

  // Heuristic: -ηξ non-compound adjectives barytone.
  if(endsWithAny(word,["ηξ"])){
    return {form:"(hint) likely βαρύτονον", note:"Herodian: words in -ηξ that are not compound adjectives are barytone (toy hint: not oxytone)."};
  }

  return {form:"(no hint)", note:"Try an ending in -υξ / -υγξ / -ηξ to trigger a passage-based hint."};
}

function analyze(){
  const inp = $('#inp');
  const w = (inp.value || '').trim();
  const school = ($$('input[name="school"]').find(r=>r.checked)?.value) || 'default';

  $('#nom').textContent = w || '—';

  const pat = guessPattern(w);
  let patternText = '—';
  let noteText = '—';

  if(pat.kind === 'empty'){
    patternText = 'Type a word to begin.';
    noteText = 'Examples: φάρυξ, λάρυγξ, μύρμηξ, πτερύξ.';
  } else if(pat.kind === 'other'){
    patternText = `Ending not recognized (toy looks for -υξ / -υγξ / -ηξ).`;
    noteText = 'Still, you can try adding a typical ending: e.g. -υξ or -ηξ.';
  } else {
    patternText = `Detected ending: ${pat.kind}`;
    if(pat.kind === '-υξ'){
      noteText = "Herodian’s note: nominative often written without γ, but genitive shows one γ (…-υγος), not -υγγος.";
    } else if(pat.kind === '-υγξ'){
      noteText = "Toy note: -υγξ often yields genitive -υγγος (cluster simplifies/assimilates in spelling traditions).";
    } else if(pat.kind === '-ηξ'){
      noteText = "Herodian: many -ηξ (non-compound adjectives) are barytone; genitive often -ηκος.";
    } else {
      noteText = "Toy rule: guess a -κος genitive for this consonant-stem ending.";
    }
  }

  $('#pattern').textContent = patternText;
  $('#note').textContent = noteText;

  const gen = pat.gen || '—';
  const alt = pat.alt || '—';
  $('#gen').textContent = gen;
  $('#alt').textContent = alt;

  const ah = accentHint(w, school);
  $('#accent').textContent = ah.form;
  $('#accentNote').textContent = ah.note;

  // Gamma meter
  const gIn = countGamma(w);
  const gG = countGamma(gen);
  $('#gIn').textContent = String(gIn);
  $('#gGen').textContent = String(gG);

  let warn = '—';
  let cls = 'pill ok';
  if(pat.kind === '-υξ'){
    if(gG === 1) { warn = 'looks Herodian-friendly (one γ)'; cls = 'pill ok'; }
    else if(gG === 0) { warn = 'odd: genitive has no γ'; cls = 'pill bad'; }
    else { warn = 'too many γ (toy expects one)'; cls = 'pill bad'; }
  } else if(pat.kind === '-υγξ'){
    warn = 'note: -υγξ often shows γγ in genitive';
    cls = 'pill ok';
  } else {
    warn = 'gamma rule not relevant';
    cls = 'pill ok';
  }
  const gw = $('#gWarn');
  gw.textContent = warn;
  gw.className = cls;
}

function setRandom(){
  const w = examples[Math.floor(Math.random()*examples.length)];
  $('#inp').value = w;
  analyze();
}

function clearAll(){
  $('#inp').value = '';
  analyze();
}

$('#analyze').addEventListener('click', analyze);
$('#random').addEventListener('click', setRandom);
$('#clear').addEventListener('click', clearAll);
$('#inp').addEventListener('keydown', (e)=>{ if(e.key === 'Enter'){ analyze(); }});
$$('input[name="school"]').forEach(r => r.addEventListener('change', analyze));

// Initialize
analyze();

