passages.gadget_js:
const $ = (sel) => document.querySelector(sel);

const examples = [
  "μάρτυς",
  "μάρτυρ",
  "οὗτος",
  "ἵππος",
  "ψίθυρ",
  "πατήρ",
  "σωτήρ",
  "στατήρ",
  "φράτηρ",
  "Ζωστήρ",
  "Ἴλλυρες",
  "Κέρκυρες",
  "Ἄσσυρες"
];

// --- Greek-ish helpers (toy-level) ---
const combiningMarks = /[\u0300-\u036f]/g;

function nfd(s){ return (s||"").normalize("NFD"); }
function nfc(s){ return (s||"").normalize("NFC"); }

function stripDiacritics(s){
  // Remove combining marks; keep base Greek letters.
  return nfc(nfd(s).replace(combiningMarks, ""));
}

function normalizeSigmaFinal(s){
  // Convert final ς to σ for internal checks, but keep original for display elsewhere.
  return s.replace(/ς/g, "σ");
}

function endsWithAny(s, arr){
  return arr.some(e => s.endsWith(e));
}

function aeolicFinalSigmaToRho(s){
  // Only final sigma (either ς or σ at end) -> ρ
  if (!s) return s;
  if (s.endsWith("ς")) return s.slice(0,-1) + "ρ";
  if (s.endsWith("σ")) return s.slice(0,-1) + "ρ";
  return s;
}

const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);

function lastVowelIndex(s){
  for (let i=s.length-1;i>=0;i--) if (vowels.has(s[i])) return i;
  return -1;
}

function prevVowelIndex(s, from){
  for (let i=from-1;i>=0;i--) if (vowels.has(s[i])) return i;
  return -1;
}

function addAcuteOnVowel(s, idx){
  // Add combining acute to the vowel at idx (toy: no breathing/other marks).
  if (idx < 0 || idx >= s.length) return s;
  const ch = s[idx];
  if (!vowels.has(ch)) return s;
  const acute = "\u0301";
  // If already has combining marks after it, just append acute after base.
  // We'll rebuild in NFD to place acute right after the base char.
  const before = s.slice(0, idx);
  const after = s.slice(idx+1);
  return nfc(nfd(before + ch) + acute + nfd(after));
}

function classifyEnding(raw){
  const s = normalizeSigmaFinal(raw);
  const sBare = s.toLowerCase();

  // Check common endings in the passage.
  if (sBare.endsWith("υρ")) return {ending:"-υρ", note:"Herodian: -υρ barytone (e.g. μάρτυρ)."};
  if (sBare.endsWith("ηρ")) return {ending:"-ηρ", note:"Herodian: -ηρ can be oxytone or barytone; simple masc often oxytone."};
  if (sBare.endsWith("υρες") || sBare.endsWith("υρεσ")) return {ending:"-υρες", note:"Plural like Ἴλλυρες, Κέρκυρες, Ἄσσυρες (often remodeled ethnics)."};
  if (sBare.endsWith("υροι") || sBare.endsWith("υροι")) return {ending:"-υροι", note:"Plural like μάρτυροι (from nominative μάρτυρος in the passage)."};
  if (sBare.endsWith("υς")) return {ending:"-υς", note:"Try Aeolic -ς→-ρ to get a -υρ form (e.g. μάρτυς→μάρτυρ)."};
  if (sBare.endsWith("ος")) return {ending:"-ος", note:"Try Aeolic -ς→-ρ (e.g. οὗτος→οὗτορ, ἵππος→ἵππορ)."};
  return {ending:"(other)", note:"Not one of the toy’s target endings; still can try Aeolic final -ς→-ρ."};
}

function accentGuess(raw, endingInfo){
  // Heuristic:
  // -υρ => barytone: put acute on previous vowel (if possible)
  // -ηρ => if looks like agent noun in -τήρ (tau before eta) => oxytone (acute on last vowel)
  // else ambiguous: show both options.

  const s0 = raw;
  const s = normalizeSigmaFinal(s0);
  const low = s.toLowerCase();

  const lastV = lastVowelIndex(s);
  const prevV = prevVowelIndex(s, lastV);

  if (endingInfo.ending === "-υρ"){
    const idx = prevV >= 0 ? prevV : lastV;
    const out = addAcuteOnVowel(stripDiacritics(s0), idx);
    return {
      label:"Barytone guess for -υρ",
      form: out,
      expl:"Toy rule: -υρ → barytone → accent not on the last syllable (so we mark the previous vowel)."
    };
  }

  if (endingInfo.ending === "-ηρ"){
    const bare = stripDiacritics(s0);
    const bareLow = normalizeSigmaFinal(bare).toLowerCase();
    const looksLikeTeter = /τηρ$/.test(bareLow); // -τήρ class mentioned (τ before η)

    if (looksLikeTeter){
      const out = addAcuteOnVowel(bare, lastV);
      return {
        label:"Oxytone guess for -τηρ",
        form: out,
        expl:"Toy rule: -τηρ (τ before η) often oxytone in Herodian’s discussion (e.g. σωτήρ, στατήρ)."
      };
    }

    // Ambiguous: show two candidates
    const oxy = addAcuteOnVowel(bare, lastV);
    const bary = addAcuteOnVowel(bare, prevV >= 0 ? prevV : lastV);
    return {
      label:"Two guesses for -ηρ",
      form: `${oxy}  |  ${bary}`,
      expl:"Herodian allows both oxytone and barytone for -ηρ; this toy shows both (left oxytone, right barytone)."
    };
  }

  // Default: no guess
  return {
    label:"No specific guess",
    form:"(toggle targets: -υρ / -ηρ)",
    expl:"The toy only makes accent guesses for -υρ and -ηρ endings."
  };
}

function analyze(){
  const inp = $("#inp").value.trim();
  const strip = $("#chkStrip").checked;
  const doAeolic = $("#chkAeolic").checked;
  const doAccent = $("#chkAccent").checked;

  if (!inp){
    $("#ending").textContent = "—";
    $("#norm").textContent = "—";
    $("#aeolic").textContent = "—";
    $("#accent").textContent = "—";
    return;
  }

  const base = strip ? stripDiacritics(inp) : inp;
  const norm = nfc(base);

  const endingInfo = classifyEnding(stripDiacritics(norm));
  $("#ending").innerHTML = `<span class="badge">${endingInfo.ending}</span> <span class="small">${endingInfo.note}</span>`;

  $("#norm").textContent = norm;
  $("#aeolic").textContent = doAeolic ? aeolicFinalSigmaToRho(norm) : "(off)";

  if (doAccent){
    const g = accentGuess(norm, endingInfo);
    $("#accent").innerHTML = `<div class="badge">${g.label}</div>\n<div style="margin-top:8px" class="mono">${escapeHtml(g.form)}</div>\n<div class="small" style="margin-top:8px">${escapeHtml(g.expl)}</div>`;
  } else {
    $("#accent").textContent = "(off)";
  }
}

function escapeHtml(s){
  return String(s)
    .replaceAll("&","&amp;")
    .replaceAll("<","&lt;")
    .replaceAll(">","&gt;")
    .replaceAll('"',"&quot;")
    .replaceAll("'","&#39;");
}

function loadExample(){
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $("#inp").value = ex;
  analyze();
}

$("#btnGo").addEventListener("click", analyze);
$("#btnRand").addEventListener("click", loadExample);
$("#btnClear").addEventListener("click", () => { $("#inp").value = ""; analyze(); $("#inp").focus(); });
$("#inp").addEventListener("input", () => {
  // lightweight live update
  analyze();
});

// init
$("#inp").value = "μάρτυς";
analyze();

