const $ = (sel, el=document) => el.querySelector(sel);
const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

// --- Greek helpers (toy-level) ---
const COMBINING = /[\u0300-\u036f]/g;
const greekNormalize = (s) => (s || "")
  .trim()
  .normalize('NFD')
  .replace(COMBINING, '')
  .normalize('NFC');

const stripPunct = (s) => (s||"")
  .replace(/[··.,;:!?\-—()\[\]{}"'«»]/g, ' ')
  .replace(/\s+/g,' ')
  .trim();

const endsWithEr = (s) => /ηρ$/i.test(greekNormalize(s));

// Very small knowledge base drawn from the passage (plus a couple of obvious kin terms)
const LEX = {
  femBary: new Set(["μητηρ","θυγατηρ","δημητηρ","εινατηρ","πατηρ"]),
  // Herodian calls γαστήρ exceptional (oxytone)
  exceptionsOxy: new Set(["γαστηρ","ελευθηρ"]),
  // Non-ethnic, non-compound -ηρ usually oxytone (examples)
  commonOxy: new Set(["ανηρ","δαηρ","αηρ","αιθηρ","σπινθηρ","αστηρ"]),
  // Ethnics/proper names in -ηρ barytone (examples)
  ethnicBary: new Set(["ιβηρ","ιλλιβηρ","δοβηρ","πιηρ","βυζηρ"]),
  // Compounds mentioned
  compoundsKeep: new Set(["αμαλλοδετηρ","οβελοστατηρ"]),
  compoundsBary: new Set(["λιπανηρ","πολυδαηρ","αινοπατηρ","εριηρ","πανθηρ","σατυροφηρ"])
};

function classify(wordRaw, mode){
  const raw = stripPunct(wordRaw);
  const norm = greekNormalize(raw).toLowerCase();

  const info = {
    input: wordRaw,
    cleaned: raw,
    norm,
    endsEr: endsWithEr(norm),
    mode,
    guess: null,
    confidence: "low",
    why: [],
    toyAccent: null
  };

  if(!raw){
    info.guess = "—";
    info.why.push("Type a word first.");
    return info;
  }

  // If phrase, take last token as head for -ηρ check
  const tokens = raw.split(' ');
  const head = tokens[tokens.length-1];
  const headNorm = greekNormalize(head).toLowerCase();
  info.head = head;
  info.headNorm = headNorm;
  info.endsEr = endsWithEr(headNorm);

  if(!info.endsEr){
    info.guess = "not -ηρ";
    info.why.push("This toy is for words ending in -ηρ. (I looked at the last word of your input.)");
    return info;
  }

  // Mode overrides (user hint)
  const hinted = mode !== 'auto';

  // 1) Hard exceptions
  if(LEX.exceptionsOxy.has(headNorm)){
    info.guess = "oxytone";
    info.confidence = "high";
    info.why.push("Listed as an exception/example in the passage.");
    info.why.push("Herodian notes γαστήρ as ‘σημειώδης’ (exceptional) because it is oxytone.");
    info.toyAccent = addToyAcute(head);
    return info;
  }

  // 2) Feminine kin terms (toy list)
  if(mode === 'fem' || (mode==='auto' && LEX.femBary.has(headNorm))){
    info.guess = "barytone";
    info.confidence = (LEX.femBary.has(headNorm) ? "high" : "medium");
    info.why.push("Feminines in -ηρ are usually barytone (μήτηρ, θυγάτηρ, Δημήτηρ, εἰνάτηρ). (Toy rule)");
    info.toyAccent = addToyGrave(head);
    return info;
  }

  // 3) Ethnics/proper names
  if(mode === 'ethnic' || (mode==='auto' && LEX.ethnicBary.has(headNorm))){
    info.guess = "barytone";
    info.confidence = (LEX.ethnicBary.has(headNorm) ? "high" : "medium");
    info.why.push("Ethnics/proper names in -ηρ are usually barytone (e.g. Ἴβηρ). (Toy rule)");
    info.toyAccent = addToyGrave(head);
    return info;
  }

  // 4) Compounds
  const looksCompound = tokens.length>1 || /[α-ω]+[α-ω]+/i.test(headNorm) && headNorm.length>=7; // very rough
  if(LEX.compoundsKeep.has(headNorm)){
    info.guess = "oxytone";
    info.confidence = "high";
    info.why.push("Recognized compound example where the base keeps η and keeps the accent (δετήρ→ἀμαλλοδετήρ; στατήρ→ὀβελοστατήρ). (Toy list)");
    info.toyAccent = addToyAcute(head);
    return info;
  }
  if(LEX.compoundsBary.has(headNorm)){
    info.guess = "barytone";
    info.confidence = "high";
    info.why.push("Recognized compound example that is barytone in the passage (e.g. λιπάνηρ, πολυδάηρ, αἰνοπάτηρ, ἐρίηρ). (Toy list)");
    info.toyAccent = addToyGrave(head);
    return info;
  }
  if(mode==='app' && looksCompound){
    info.guess = "barytone";
    info.confidence = "low";
    info.why.push("You hinted ‘common noun’; for compounds the accent can shift. This toy defaults to barytone unless it recognizes the pattern.");
    info.toyAccent = addToyGrave(head);
    return info;
  }

  // 5) Common nouns in -ηρ (not ethnic, not compound): oxytone
  if(mode === 'app' || mode==='auto'){
    if(LEX.commonOxy.has(headNorm)){
      info.guess = "oxytone";
      info.confidence = "high";
      info.why.push("Listed among the common -ηρ oxytone examples (ἀνήρ, δαήρ, ἀήρ, αἰθήρ, σπινθήρ). (Toy list)");
      info.toyAccent = addToyAcute(head);
      return info;
    }

    info.guess = "oxytone";
    info.confidence = hinted ? "low" : "medium";
    info.why.push("Default Herodian-style guess: non-ethnic, non-compound -ηρ tends to be oxytone.");
    info.toyAccent = addToyAcute(head);
    return info;
  }

  info.guess = "oxytone";
  info.confidence = "low";
  info.why.push("Fallback guess.");
  info.toyAccent = addToyAcute(head);
  return info;
}

// --- Toy accent rendering ---
// We do NOT compute real accent placement; we just mark the final vowel with acute/grave.
function addToyAcute(word){
  return markLastVowel(word, 'acute');
}
function addToyGrave(word){
  return markLastVowel(word, 'grave');
}

function markLastVowel(word, kind){
  const nfd = (word||"").normalize('NFD');
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
  const acute = '\u0301';
  const grave = '\u0300';
  const mark = kind==='grave' ? grave : acute;

  // Find last vowel base char index in NFD string
  let idx = -1;
  for(let i=0;i<nfd.length;i++){
    const ch = nfd[i];
    if(vowels.has(ch)) idx = i;
  }
  if(idx<0) return word;

  // Insert mark after that vowel, but before any existing combining marks that follow it
  let j = idx+1;
  while(j<nfd.length && /[\u0300-\u036f]/.test(nfd[j])) j++;
  const out = nfd.slice(0,j) + mark + nfd.slice(j);
  return out.normalize('NFC');
}

function render(info){
  const out = $('#out');
  if(info.guess === '—'){
    out.innerHTML = `<div class="kv"><div class="k">Status</div><div class="v">Type a Greek word ending in -ηρ.</div></div>`;
    return;
  }
  if(info.guess === 'not -ηρ'){
    out.innerHTML = `
      <div class="kv"><div class="k">Head word</div><div class="v">${escapeHtml(info.head || info.cleaned)}</div></div>
      <div class="kv"><div class="k">Result</div><div class="v">Not an <span class="gr">-ηρ</span> ending (toy scope).</div></div>
      <div class="kv"><div class="k">Note</div><div class="v">${escapeHtml(info.why.join(' '))}</div></div>
    `;
    return;
  }

  const badgeClass = info.guess === 'oxytone' ? 'oxy' : 'bar';
  const badgeText = info.guess === 'oxytone' ? 'oxytone' : 'barytone';
  const conf = info.confidence;
  const confBadge = conf==='high' ? 'exc' : '';

  out.innerHTML = `
    <div class="kv"><div class="k">Head word</div><div class="v">${escapeHtml(info.head)} <span class="badge ${badgeClass}">${badgeText}</span> <span class="badge ${confBadge}">confidence: ${conf}</span></div></div>
    <div class="kv"><div class="k">Toy-marked form</div><div class="v">${escapeHtml(info.toyAccent || info.head)}</div></div>
    <div class="kv"><div class="k">Why (toy)</div><div class="v">• ${escapeHtml(info.why.join('\n• '))}</div></div>
    <div class="kv"><div class="k">Try next</div><div class="v">Type an ethnic like <span class="gr">Ἴβηρ</span>, a common noun like <span class="gr">ἀήρ</span>, and the exception <span class="gr">γαστήρ</span>.</div></div>
  `;
}

function escapeHtml(s){
  return String(s||"")
    .replaceAll('&','&amp;')
    .replaceAll('<','&lt;')
    .replaceAll('>','&gt;')
    .replaceAll('"','&quot;')
    .replaceAll("'",'&#39;');
}

function currentMode(){
  const r = $('input[name="mode"]:checked');
  return r ? r.value : 'auto';
}

// --- Cards game ---
const EXAMPLES = [
  {w:"μήτηρ", cls:"barytone", note:"feminine kin-term"},
  {w:"θυγάτηρ", cls:"barytone", note:"feminine kin-term"},
  {w:"Ἴβηρ", cls:"barytone", note:"ethnic/proper"},
  {w:"Βύζηρ", cls:"barytone", note:"ethnic/proper"},
  {w:"ἀήρ", cls:"oxytone", note:"common noun"},
  {w:"αἰθήρ", cls:"oxytone", note:"common noun"},
  {w:"σπινθήρ", cls:"oxytone", note:"common noun"},
  {w:"γαστήρ", cls:"oxytone", note:"exception"},
  {w:"Ἐλευθήρ", cls:"oxytone", note:"proper-name exception"},
  {w:"ὀβελοστατήρ", cls:"oxytone", note:"compound keeps accent (toy)"},
  {w:"λιπάνηρ", cls:"barytone", note:"compound shifts (toy)"},
  {w:"ἐρίηρ", cls:"barytone", note:"compound (toy)"}
];

function shuffle(arr){
  const a = arr.slice();
  for(let i=a.length-1;i>0;i--){
    const j = Math.floor(Math.random()*(i+1));
    [a[i],a[j]]=[a[j],a[i]];
  }
  return a;
}

function newRound(){
  const pick = shuffle(EXAMPLES).slice(0,8);
  const cards = $('#cards');
  cards.innerHTML = '';
  pick.forEach(ex => {
    const el = document.createElement('button');
    el.type = 'button';
    el.className = 'card';
    el.setAttribute('aria-label', `Card ${ex.w}`);
    el.dataset.word = ex.w;
    el.dataset.cls = ex.cls;
    el.dataset.note = ex.note;
    el.dataset.revealed = '0';
    el.innerHTML = `
      <div class="word">${escapeHtml(ex.w)}</div>
      <div class="reveal">click to reveal</div>
    `;
    el.addEventListener('click', () => {
      const rev = el.dataset.revealed === '1';
      if(!rev){
        const badge = ex.cls==='oxytone' ? '<span class="badge oxy">oxytone</span>' : '<span class="badge bar">barytone</span>';
        el.innerHTML = `
          <div class="word">${escapeHtml(ex.w)} ${badge}</div>
          <div class="reveal">${escapeHtml(ex.note)}</div>
        `;
        el.dataset.revealed = '1';
      } else {
        el.innerHTML = `
          <div class="word">${escapeHtml(ex.w)}</div>
          <div class="reveal">click to reveal</div>
        `;
        el.dataset.revealed = '0';
      }
    });
    cards.appendChild(el);
  });
}

// --- Wiring ---
function analyzeNow(){
  const w = $('#w').value;
  const info = classify(w, currentMode());
  render(info);
}

$('#analyze').addEventListener('click', analyzeNow);
$('#w').addEventListener('keydown', (e)=>{ if(e.key==='Enter') analyzeNow(); });
$$('input[name="mode"]').forEach(r => r.addEventListener('change', analyzeNow));

$('#clear').addEventListener('click', ()=>{ $('#w').value=''; render(classify('', currentMode())); $('#w').focus(); });

$('#random').addEventListener('click', ()=>{
  const ex = EXAMPLES[Math.floor(Math.random()*EXAMPLES.length)];
  $('#w').value = ex.w;
  analyzeNow();
  $('#w').focus();
});

$('#reshuffle').addEventListener('click', newRound);

// init
newRound();
render(classify('', currentMode()));

