const $ = (sel) => document.querySelector(sel);

const examples = [
  "ῥήτωρ",
  "κλήτωρ",
  "ἵστωρ",
  "Ἕκτωρ",
  "Νέστωρ",
  "Κάστωρ",
  "Μέντωρ",
  "φράτωρ",
  "ἰχώρ",
  "Σάπειρ",
  "Λίγειρ",
  "Ἐλάτειρ"
];

// --- Greek helpers (very lightweight) ---
const combining = /[\u0300-\u036f]/g; // includes acute/grave/circumflex, breathings, iota subscript, etc.

function nfd(s){ return (s||"").normalize("NFD"); }
function nfc(s){ return (s||"").normalize("NFC"); }

function stripDiacritics(s){
  return nfc(nfd(s).replace(combining, ""));
}

function stripToLetters(s){
  // keep Greek letters only (plus final sigma)
  return (s||"").replace(/[^\p{Script=Greek}]/gu, "");
}

function hasAcute(s){
  return nfd(s).includes("\u0301");
}

function endsWithUnaccented(s, ending){
  const a = stripDiacritics(stripToLetters(s)).toLowerCase();
  return a.endsWith(ending);
}

function lastVowelIndexNFD(nfdStr){
  // find index in NFD string of last Greek vowel base char
  const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);
  for(let i=nfdStr.length-1;i>=0;i--){
    const ch = nfdStr[i];
    if(vowels.has(ch)) return i;
  }
  return -1;
}

function syllableNucleiIndicesNFD(nfdStr){
  // crude: each vowel base char counts as a nucleus
  const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);
  const idx=[];
  for(let i=0;i<nfdStr.length;i++) if(vowels.has(nfdStr[i])) idx.push(i);
  return idx;
}

function placeAcuteOnSyllable(word, fromEnd /*1=ultima,2=penult,3=antepenult*/){
  let w = stripToLetters(word);
  if(!w) return "";
  // remove existing accents (keep breathings etc? for simplicity remove all combining marks)
  let baseNFD = nfd(w).replace(combining, "");
  const nuclei = syllableNucleiIndicesNFD(baseNFD);
  if(nuclei.length===0) return nfc(baseNFD);
  const target = nuclei[nuclei.length - fromEnd] ?? nuclei[0];
  // insert combining acute after the vowel base char
  const acute = "\u0301";
  const out = baseNFD.slice(0, target+1) + acute + baseNFD.slice(target+1);
  return nfc(out);
}

function guessGenitive(word){
  // Extremely rough, just to echo the passage: many masc. -ωρ -> -ορος (Νέστορος)
  // Special-case ἰχώρ often given as ἰχῶρος.
  const clean = stripDiacritics(stripToLetters(word));
  const lower = clean.toLowerCase();
  if(!lower) return "";

  if(lower === "ιχωρ") return "ἰχῶρος";

  if(lower.endsWith("ωρ")){
    const stem = clean.slice(0, -2);
    // return with polytonic-ish accent on omega in ending: -ορος (no attempt at correct accent)
    return stem + "ορος";
  }
  if(lower.endsWith("ειρ")){
    const stem = clean.slice(0, -3);
    return stem + "ειρος";
  }
  return "(no guess)";
}

function herodianAccentSuggestion(word){
  const clean = stripDiacritics(stripToLetters(word));
  const lower = clean.toLowerCase();
  if(!lower) return null;

  if(lower === "ιχωρ"){
    return {rule:"exception", label:"ἰχώρ (oxytone exception)", accented: placeAcuteOnSyllable(clean, 1)};
  }

  if(lower.endsWith("ωρ")){
    return {rule:"-or", label:"-ωρ → barytone (toy: penult acute)", accented: placeAcuteOnSyllable(clean, 2)};
  }

  if(lower.endsWith("ειρ")){
    // Herodian: found forms barytone; toy: penult acute
    return {rule:"-eir", label:"-ειρ (≥2 syll.) → barytone (toy: penult acute)", accented: placeAcuteOnSyllable(clean, 2)};
  }

  return {rule:"other", label:"(not -ωρ / -ειρ) — no Herodian rule applied", accented: clean};
}

function syllableCount(word){
  const base = nfd(stripDiacritics(stripToLetters(word)));
  return syllableNucleiIndicesNFD(base).length;
}

function renderAnalysis(){
  const raw = $("#w").value.trim();
  const w = stripToLetters(raw);
  const clean = stripDiacritics(w);
  const lower = clean.toLowerCase();

  if(!w){
    $("#out").innerHTML = "<div class='box'><div class='k'>Nothing to analyze</div><div class='v'>Type a Greek word above.</div></div>";
    return;
  }

  const endsOr = endsWithUnaccented(w, "ωρ");
  const endsEir = endsWithUnaccented(w, "ειρ");
  const sc = syllableCount(w);
  const alreadyAcc = hasAcute(w);

  const sug = herodianAccentSuggestion(w);
  const gen = guessGenitive(w);

  let tag = "<span class='tag'>other</span>";
  if(lower === "ιχωρ") tag = "<span class='tag warn'>exception</span>";
  else if(endsOr) tag = "<span class='tag good'>-ωρ</span>";
  else if(endsEir) tag = "<span class='tag good'>-ειρ</span>";

  const noteBits = [];
  if(endsOr) noteBits.push("Ends in -ωρ");
  if(endsEir) noteBits.push("Ends in -ειρ");
  if(!endsOr && !endsEir) noteBits.push("Doesn’t match the passage’s endings");
  noteBits.push(`${sc} vowel-nuclei (toy syllables)`);
  if(alreadyAcc) noteBits.push("input already has an acute somewhere");

  const note = noteBits.join(" · ");

  const sugBox = `
    <div class="box">
      <div class="k">Herodian-style suggestion ${tag}</div>
      <div class="v"><span class="g">${escapeHTML(sug.accented)}</span></div>
      <div class="k">Rule</div>
      <div class="v" style="font-size:13px;color:var(--muted)">${escapeHTML(sug.label)}</div>
    </div>`;

  const genBox = `
    <div class="box">
      <div class="k">Genitive singular (very rough)</div>
      <div class="v"><span class="g">${escapeHTML(gen)}</span></div>
      <div class="k">Why this is here</div>
      <div class="v" style="font-size:13px;color:var(--muted)">Herodian links <span class="g">ἰχώρ</span>’s unusual accent to its different declension; this box lets you compare “regular” -ωρ → -ορος vs the special-case <span class="g">ἰχῶρος</span>.</div>
    </div>`;

  const diagBox = `
    <div class="box">
      <div class="k">Diagnostics</div>
      <div class="v" style="font-size:13px;color:var(--muted)">${escapeHTML(note)}</div>
      <div class="k">Your input (letters only)</div>
      <div class="v"><span class="g">${escapeHTML(w)}</span></div>
      <div class="k">Stripped of diacritics</div>
      <div class="v"><span class="g">${escapeHTML(clean)}</span></div>
    </div>`;

  const compareBox = `
    <div class="box">
      <div class="k">Compare barytone vs oxytone (toy)</div>
      <div class="v" style="display:flex;gap:10px;flex-wrap:wrap">
        <span class="g">penult: <b>${escapeHTML(placeAcuteOnSyllable(clean, 2))}</b></span>
        <span class="g">ultima: <b>${escapeHTML(placeAcuteOnSyllable(clean, 1))}</b></span>
      </div>
      <div class="k">Hint</div>
      <div class="v" style="font-size:13px;color:var(--muted)">If it’s a typical -ωρ word, Herodian expects barytone (often like the penult form). If it’s <span class="g">ἰχώρ</span>, he expects the ultima form.</div>
    </div>`;

  $("#out").innerHTML = `<div class="grid">${sugBox}${genBox}${compareBox}${diagBox}</div>`;

  // sync slider toy with this word
  $("#base").value = clean;
  updateSlider();
}

function updateSlider(){
  const base = $("#base").value.trim();
  const pos = parseInt($("#pos").value, 10);
  const label = pos===1 ? "ultima" : pos===2 ? "penult" : "antepenult";
  $("#posLabel").textContent = label;
  const res = placeAcuteOnSyllable(base, pos);
  $("#accented").textContent = res || "—";
}

function escapeHTML(s){
  return (s??"").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
}

$("#go").addEventListener("click", renderAnalysis);
$("#w").addEventListener("keydown", (e)=>{ if(e.key==="Enter") renderAnalysis(); });
$("#rand").addEventListener("click", ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $("#w").value = ex;
  renderAnalysis();
});

$("#pos").addEventListener("input", updateSlider);
$("#base").addEventListener("input", updateSlider);

// initial
$("#w").value = "ῥήτωρ";
renderAnalysis();
updateSlider();

