const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const boe = $('#boeotian');
const keepAcc = $('#keepAcc');
const onlyEta = $('#onlyEta');
const asReport = $('#asReport');
const guessBtn = $('#guessBtn');
const clearBtn = $('#clearBtn');
const chips = $('#chips');

const examples = [
  'πένης',
  'πατήρ',
  'μήτηρ',
  'Αἴας',
  'Θόας',
  'Ποίας',
  'Δοίας',
  'Βίας',
  'Πρίας',
  'ἀτταγᾶς',
  'πελεκᾶς',
  'Μαρικᾶς',
  'Γλισᾶς'
];

function lastWord(s){
  const t = (s || '').trim();
  if(!t) return '';
  const parts = t.split(/\s+/);
  return parts[parts.length-1];
}

// --- Greek helpers (toy-level) ---
const COMBINING = {
  acute: '\u0301',
  grave: '\u0300',
  circumflex: '\u0342',
  diaeresis: '\u0308',
  smooth: '\u0313',
  rough: '\u0314',
  iotaSub: '\u0345'
};

function nfd(s){ return (s||'').normalize('NFD'); }
function nfc(s){ return (s||'').normalize('NFC'); }

function stripDiacritics(s){
  // remove combining marks
  return nfd(s).replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function stripAccentOnly(s){
  return nfd(s)
    .replace(new RegExp('['+COMBINING.acute+COMBINING.grave+COMBINING.circumflex+']','g'),'')
    .normalize('NFC');
}

function hasCombining(s, comb){
  return nfd(s).includes(comb);
}

function countSyllablesRough(word){
  // Count vowel nuclei in a very rough way; treat ει/αι/οι/υι/αυ/ευ/ου/ηυ as one.
  const w = stripDiacritics(word).toLowerCase();
  if(!w) return 0;
  const diph = ['ει','αι','οι','υι','αυ','ευ','ου','ηυ'];
  let i=0, count=0;
  while(i<w.length){
    let two = w.slice(i,i+2);
    if(diph.includes(two)) { count++; i+=2; continue; }
    if('αεηιουω'.includes(w[i])) { count++; i++; continue; }
    i++;
  }
  return count;
}

function boeotianEtaToEi(text){
  const t = text || '';
  if(!t.trim()) return '';

  // Work in NFD so we can move accents.
  const src = nfd(t);
  let out = '';

  // Map eta forms (base letter in NFD is η/Η) with possible combining marks.
  for(let i=0;i<src.length;i++){
    const ch = src[i];

    if(ch === 'η' || ch === 'Η'){
      // collect following combining marks
      let j=i+1;
      let marks='';
      while(j<src.length && /[\u0300-\u036f]/.test(src[j])){ marks += src[j]; j++; }

      const isPlain = marks.length===0;
      if(onlyEta.checked && !isPlain){
        out += ch + marks;
        i = j-1;
        continue;
      }

      const upper = (ch === 'Η');
      const e = upper ? 'Ε' : 'ε';
      const ii = upper ? 'Ι' : 'ι';

      if(!keepAcc.checked){
        out += e + ii; // drop marks
      } else {
        // Move accent marks (acute/grave/circumflex) onto iota; keep breathings on epsilon.
        const accentMarks = marks.replace(new RegExp('['+COMBINING.smooth+COMBINING.rough+COMBINING.diaeresis+COMBINING.iotaSub+']','g'),'');
        const otherMarks = marks.replace(new RegExp('['+COMBINING.acute+COMBINING.grave+COMBINING.circumflex+']','g'),'');
        // Put breathings etc. on epsilon, accent on iota.
        out += e + otherMarks + ii + accentMarks;
      }

      i = j-1;
      continue;
    }

    out += ch;
  }

  return nfc(out);
}

function endsWithAs(word){
  const w = stripDiacritics(word).toLowerCase();
  return w.endsWith('ας');
}

function finalAlphaAccentType(word){
  // Look for accent on the final alpha (NFD). Return 'circumflex'|'acute'|'grave'|null
  const w = nfd(word);
  // Find last alpha (α/Α) before final sigma maybe.
  // We'll scan from end for α/Α.
  for(let i=w.length-1;i>=0;i--){
    const ch = w[i];
    if(ch==='α' || ch==='Α'){
      // gather combining marks after it
      let j=i+1;
      let marks='';
      while(j<w.length && /[\u0300-\u036f]/.test(w[j])){ marks += w[j]; j++; }
      if(marks.includes(COMBINING.circumflex)) return 'circumflex';
      if(marks.includes(COMBINING.grave)) return 'grave';
      if(marks.includes(COMBINING.acute)) return 'acute';
      return null;
    }
  }
  return null;
}

function guessAsAccent(word){
  const w = (word||'').trim();
  if(!w) return {ok:false, msg:'Type something above.'};

  const lw = lastWord(w);
  const syl = countSyllablesRough(lw);
  const ends = endsWithAs(lw);

  if(!ends){
    return {ok:false, msg:`Last word: <span class="mono">${escapeHtml(lw)}</span>. It does not look like it ends in <span class="mono">-ας</span> (after stripping accents).`};
  }
  if(syl <= 1){
    return {ok:false, msg:`Last word: <span class="mono">${escapeHtml(lw)}</span>. It ends in <span class="mono">-ας</span>, but I estimate only <b>${syl}</b> syllable — Herodian’s note is about <b>more than one</b>.`};
  }

  const acc = finalAlphaAccentType(lw);
  if(acc){
    const tag = acc==='circumflex' ? tagHtml('circumflex','good') : tagHtml(acc,'warn');
    return {
      ok:true,
      msg:`Last word: <span class="mono">${escapeHtml(lw)}</span> (≈ <b>${syl}</b> syllables). I see a <b>${acc}</b> on the final <span class="mono">α</span>. ${tag}`
    };
  }

  // No explicit accent on final alpha: playful heuristic
  const bare = stripDiacritics(lw).toLowerCase();
  let guess = 'grave';
  let why = 'defaulting to the “grave” group of examples (Αἴας, Θόας, …).';
  if(/(ικας|εκας)$/.test(bare)){
    guess = 'circumflex';
    why = 'names in -ικᾶς/-εκᾶς often show circumflex in the examples (e.g. Μαρικᾶς, πελεκᾶς).';
  }
  const tag = guess==='circumflex' ? tagHtml('circumflex?','good') : tagHtml('grave?','warn');
  return {
    ok:true,
    msg:`Last word: <span class="mono">${escapeHtml(lw)}</span> (≈ <b>${syl}</b> syllables). No clear accent mark on the final <span class="mono">α</span>, so I <b>guess</b> <b>${guess}</b> — ${why} ${tag}`
  };
}

function tagHtml(text, cls){
  return `<span class="tag ${cls}">${escapeHtml(text)}</span>`;
}

function escapeHtml(s){
  return (s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function render(){
  const t = inp.value;
  boe.textContent = boeotianEtaToEi(t);
}

inp.addEventListener('input', render);
keepAcc.addEventListener('change', render);
onlyEta.addEventListener('change', render);

guessBtn.addEventListener('click', () => {
  const r = guessAsAccent(inp.value);
  asReport.innerHTML = r.msg;
});

clearBtn.addEventListener('click', () => {
  inp.value = '';
  boe.textContent = '';
  asReport.textContent = '';
  inp.focus();
});

function addChips(){
  chips.innerHTML = '';
  for(const ex of examples){
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip';
    b.textContent = ex;
    b.addEventListener('click', () => {
      inp.value = ex;
      render();
      asReport.textContent = '';
      inp.focus();
    });
    chips.appendChild(b);
  }
}

addChips();
render();

