(() => {
  const $ = (sel, el=document) => el.querySelector(sel);
  const inp = $('#inp');
  const outMain = $('#outMain');
  const outMini = $('#outMini');

  const examples = [
    {w:'Ἑρμᾶς', note:'proper name; perispōmenon in passage'},
    {w:'Μηνᾶς', note:'proper name; perispōmenon'},
    {w:'Ζηνᾶς', note:'proper name; perispōmenon'},
    {w:'Μητρᾶς', note:'proper name; perispōmenon'},
    {w:'Κομητᾶς', note:'proper name; perispōmenon'},
    {w:'λαχανᾶς', note:'common noun example; perispōmenon list'},
    {w:'ὀστρακᾶς', note:'common noun example; perispōmenon list'},
    {w:'χαλκοκράς', note:'exception: acute in -κράς compounds'},
    {w:'γαλακτοκράς', note:'exception: acute in -κράς compounds'},
    {w:'νεοκράς', note:'exception: acute in -κράς compounds'},
    {w:'ἱμάς', note:'mentioned as anomalously acute'},
    {w:'ἀνδριάς', note:'mentioned as anomalously acute'},
    {w:'ἀλλᾶς', note:'discussed via ἀλλάεις → ἀλλᾶντος'}
  ];

  function stripDiacritics(s){
    // Remove combining marks; keep base Greek letters.
    return (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  }

  function hasCircumflex(s){
    const nfd = (s||'').normalize('NFD');
    return nfd.includes('\u0342'); // perispomeni
  }

  function hasAcute(s){
    const nfd = (s||'').normalize('NFD');
    return nfd.includes('\u0301');
  }

  function endsWithAsBare(s){
    const b = stripDiacritics(s).replace(/\s+/g,'');
    return /ας$/i.test(b);
  }

  function guessAccentClass(word){
    const w = (word||'').trim();
    const bare = stripDiacritics(w);

    if(!endsWithAsBare(w)){
      return {cls:'other', label:'Not an -ας word (toy focuses on -ας / -ᾶς).'};
    }

    // Strong exception pattern from passage: -κράς compounds (acute)
    if(/κρας$/i.test(bare)){
      return {cls:'acute', label:'Likely oxytone (acute) by the -κράς compound exception.'};
    }

    // If user already typed a circumflex, respect it.
    if(hasCircumflex(w)){
      return {cls:'circ', label:'You typed a circumflex: treat as perispōmenon (-ᾶς).'};
    }

    // If user typed an acute on final alpha (or anywhere), flag.
    if(hasAcute(w)){
      return {cls:'acute?', label:'You typed an acute; Herodian says acute is rare here (except -κράς etc.).'};
    }

    // Heuristic: many proper-name-like -ᾶς are circumflexed.
    // If ends with plain -ας without accent marks, suggest circumflex as a “try it”.
    return {cls:'suggest', label:'Try circumflexing the long α: many proper names/diminutives are -ᾶς.'};
  }

  function applyCircumflexOnFinalAlpha(word){
    // Convert final "ας" to "ᾶς" (alpha with circumflex + sigma).
    // Works best when the word is already in polytonic or plain Greek.
    let w = (word||'').trim();
    if(!endsWithAsBare(w)) return w;

    // Remove any combining marks on the final alpha, then add circumflex.
    // Find last alpha before final sigma.
    const nfd = w.normalize('NFD');
    // Replace the last occurrence of alpha + marks + sigma at end.
    const replaced = nfd.replace(/α([\u0300-\u036f]*)ς$/i, (m, marks) => {
      // keep breathing if present? (roughly keep smooth/rough if it was on alpha)
      const keep = (marks||'').replace(/[\u0301\u0300\u0342]/g,'');
      return 'α' + keep + '\u0342' + 'ς';
    });
    return replaced.normalize('NFC');
  }

  function guessGenitive(word){
    const w = (word||'').trim();
    const bare = stripDiacritics(w);
    if(!endsWithAsBare(w)) return null;

    // Very rough, passage-inspired options:
    // -ᾶς often shown with -ᾶντος (like participle-ish / contracted discussion)
    // Ionic anomalous: -άδος (mentioned as "through d")
    // -κράς exception: -άτος ("through t")

    if(/κρας$/i.test(bare)){
      return {form: bare.replace(/ας$/i,'ατος'), note:'Toy guess: -κράς → -κράτος ("through t").'};
    }

    // If looks like one of the Ionic proper names in passage, suggest -άδος.
    const ionicSet = new Set(['Βοιβᾶς','Βιττᾶς','Κυρᾶς']);
    if(ionicSet.has(w)){
      return {form: stripDiacritics(w).replace(/ας$/,'αδος'), note:'Toy guess: Ionic anomalous declension “through d” → -άδος.'};
    }

    // Default: -αντος
    return {form: bare.replace(/ας$/i,'αντος'), note:'Toy guess: participle-like / contracted pattern → -αντος.'};
  }

  function analyze(){
    const w = inp.value.trim();
    if(!w){
      outMain.textContent = '—';
      outMini.textContent = '';
      return;
    }

    const accent = guessAccentClass(w);
    const gen = guessGenitive(w);

    let tag = '';
    if(accent.cls==='circ') tag = '<span class="tag good">perispōmenon</span>';
    else if(accent.cls==='acute') tag = '<span class="tag warn">oxytone exception</span>';
    else if(accent.cls==='acute?') tag = '<span class="tag bad">acute? (rare)</span>';
    else if(accent.cls==='suggest') tag = '<span class="tag">try -ᾶς</span>';
    else tag = '<span class="tag">other</span>';

    const suggested = (accent.cls==='suggest') ? applyCircumflexOnFinalAlpha(w) : null;

    const lines = [];
    lines.push(`Input: ${w}`);
    lines.push(`Accent guess: ${accent.label}`);
    if(suggested && suggested !== w){
      lines.push(`Suggested spelling: ${suggested}`);
    }
    if(gen){
      lines.push(`Genitive (toy): ${gen.form}`);
    }

    outMain.textContent = lines.join('\n');

    const mini = [];
    mini.push(`Bare (no diacritics): ${stripDiacritics(w)}`);
    mini.push(`Ends in -ας: ${endsWithAsBare(w) ? 'yes' : 'no'}`);
    if(gen) mini.push(gen.note);
    outMini.textContent = mini.join('\n');

    // Add tag into the card title area by injecting into outMain? Keep simple: append to mini.
    // Instead, show tag by setting data attribute and using CSS? We'll just show in mini.
    outMini.insertAdjacentHTML('beforeend', `\n\nClass: ${tag}`);
  }

  function buildChips(){
    const box = $('#chips');
    box.innerHTML = '';
    examples.forEach(ex => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'chip';
      b.textContent = ex.w;
      b.title = ex.note;
      b.addEventListener('click', () => {
        inp.value = ex.w;
        analyze();
        inp.focus();
      });
      box.appendChild(b);
    });
  }

  $('#analyze').addEventListener('click', analyze);
  $('#clear').addEventListener('click', () => { inp.value=''; analyze(); inp.focus(); });
  $('#random').addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inp.value = ex.w;
    analyze();
    inp.focus();
  });
  inp.addEventListener('keydown', (e) => {
    if(e.key === 'Enter') analyze();
  });
  inp.addEventListener('input', () => {
    // live update, but lightweight
    analyze();
  });

  buildChips();
  analyze();
})();

