(() => {
  const $ = (sel, root=document) => root.querySelector(sel);

  const inp = $('#inp');
  const btnGo = $('#btnGo');
  const btnRand = $('#btnRand');
  const diag = $('#diag');
  const fNom = $('#fNom');
  const fGen = $('#fGen');
  const fDat = $('#fDat');
  const fAcc = $('#fAcc');
  const fVoc = $('#fVoc');
  const ionSlider = $('#ionSlider');
  const ionLabel = $('#ionLabel');
  const ionOut = $('#ionOut');
  const pleo = $('#pleo');
  const pleoOut = $('#pleoOut');

  const examples = [
    'Νικίας','Λυσίας','Ἀρχίας','Λοξίας','Γοργίας','Ἐρυξίας','Ὠπίας','Προυσίας','Πρακίας','Ἀγρίας','Ἀδρίας','Καλατίας','Ἀσίας','Ἱππίας','Γλαυκίας','Πευκετίας','Πικίας','Παρίας','Βορέας','Ἀνδρέας','Αὐγέας','Πυθέας','Αἰνείας','Αὐγείας','Ἑρμείας','Μαρσύας','Ἰχθύας','Ὀθρύας','Μινύας','Μιλύας'
  ];

  // --- tiny Greek helpers (toy-level) ---
  const stripDiacritics = (s) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').normalize('NFC');
  const lastChar = (s) => (s ? Array.from(s).slice(-1)[0] : '');

  function endsWithAs(s){
    const bare = stripDiacritics(s).replace(/\s+/g,'');
    return bare.endsWith('ας') || bare.endsWith('ας'.toUpperCase());
  }

  function baseFromAs(nom){
    // remove final -ας (ignoring diacritics by mapping indices approximately)
    // We'll do it by stripping diacritics for detection, but cut original by 2 codepoints.
    const t = nom.trim();
    const chars = Array.from(t);
    if (chars.length < 2) return t;
    // assume last two letters are alpha+sigma
    return chars.slice(0, -2).join('');
  }

  function makeForms(nom){
    const t = nom.trim();
    if (!t) return null;

    // Special-cased Ἀσίας for the passage’s point.
    const bare = stripDiacritics(t);
    const isAsias = bare === 'Ασιας' || bare === 'Ἀσιας' || bare === 'ΑΣΙΑΣ';

    if (!endsWithAs(t)){
      return {
        nom: t,
        gen: '—',
        dat: '—',
        acc: '—',
        voc: '—',
        note: 'Not ending in -ας (toy generator focuses on -ας).'
      };
    }

    const stem = baseFromAs(t);
    // Toy Attic-ish set for “pure -ας” (as in Herodian’s list)
    const gen = stem + 'ου';
    const dat = stem + 'ᾳ';
    const acc = stem + 'αν';
    const voc = stem + 'α';

    let note = 'Looks like a “pure -ας” type (toy): gen -ου, dat -ᾳ, acc -αν.';
    if (isAsias) note = 'Special: Ἀσίας in the passage has Homeric/Ionic genitives (Ἀσίω, Ἀσίεω) besides the regular-looking Ἀσίου.';

    return { nom: t, gen, dat, acc, voc, isAsias, note };
  }

  function ionicGenitives(nom, mode){
    // mode: 0 off, 1 Homeric Ἀσίω, 2 Ionic Ἀσίεω
    const bare = stripDiacritics(nom.trim());
    const isAsias = bare === 'Ασιας' || bare === 'Ἀσιας' || bare === 'ΑΣΙΑΣ';
    if (!nom.trim()) return '—';
    if (!isAsias) return 'Ionic genitive toy is only demonstrated for Ἀσίας (per the passage).';

    if (mode === 0) return 'off (use the slider)';
    if (mode === 1) return 'Homeric gen.: Ἀσίω  (≈ “of Asios/Asia” in Homer’s phrase)';
    return 'Ionic gen.: Ἀσίεω  (also attested alongside Ἀσίω)';
  }

  function pleonasticIota(nom, on){
    const t = nom.trim();
    if (!t) return '—';

    // Toy: if ends with -εας, suggest -ειας; if ends with -ειας, suggest -εας.
    const bare = stripDiacritics(t);
    const chars = Array.from(t);

    const endsEas = bare.endsWith('εας');
    const endsEias = bare.endsWith('ειας');

    if (!endsEas && !endsEias){
      return 'Toggle affects -εας / -ειας spellings (e.g. Αἰνείας, Αὐγείας, Ἑρμείας).';
    }

    if (!on){
      return 'off → keep: ' + t;
    }

    if (endsEas){
      // replace final εας with ειας
      const out = chars.slice(0, -3).join('') + 'ειας';
      return 'on → add “pleonastic ι”: ' + out;
    }

    // endsEias: remove iota
    const out = chars.slice(0, -4).join('') + 'εας';
    return 'on → remove the extra ι (reverse): ' + out;
  }

  function update(){
    const t = inp.value.trim();
    const forms = makeForms(t);

    if (!forms){
      diag.textContent = '—';
      fNom.textContent = fGen.textContent = fDat.textContent = fAcc.textContent = fVoc.textContent = '—';
      ionOut.textContent = '—';
      pleoOut.textContent = '—';
      return;
    }

    diag.textContent = forms.note;
    fNom.textContent = forms.nom;
    fGen.textContent = forms.gen;
    fDat.textContent = forms.dat;
    fAcc.textContent = forms.acc;
    fVoc.textContent = forms.voc;

    const mode = Number(ionSlider.value);
    ionLabel.textContent = (mode===0?'off':(mode===1?'Ἀσίω':'Ἀσίεω'));
    ionOut.textContent = ionicGenitives(t, mode);

    pleoOut.textContent = pleonasticIota(t, pleo.checked);
  }

  btnGo.addEventListener('click', update);
  inp.addEventListener('keydown', (e) => { if (e.key === 'Enter') update(); });
  inp.addEventListener('input', () => {
    // live update, but keep it calm
    update();
  });

  btnRand.addEventListener('click', () => {
    const pick = examples[Math.floor(Math.random()*examples.length)];
    inp.value = pick;
    update();
    inp.focus();
    inp.setSelectionRange(inp.value.length, inp.value.length);
  });

  ionSlider.addEventListener('input', update);
  pleo.addEventListener('change', update);

  // init
  inp.value = 'Ἀσίας';
  update();
})();

