const inp = document.getElementById('inp');
const out = document.getElementById('out');
const strip = document.getElementById('strip');

const EXCEPTION_CIRCUMFLEX = new Set([
  // Herodian: Βοιβᾶς περισπᾶται
  'βοιβας',
]);

function normalizeGreek(s){
  // Lowercase, remove spaces/punct, optionally strip diacritics.
  let t = (s || '').trim().toLowerCase();
  t = t.replace(/[··.,;:!?"'“”‘’()\[\]{}<>]/g,'');
  t = t.replace(/\s+/g,'');
  if(strip.checked){
    // NFD splits base + combining marks; remove combining marks.
    t = t.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  }
  return t;
}

function endsWithAny(s, arr){
  return arr.find(x => s.endsWith(x)) || null;
}

function toyAccentOnFinalAlpha(word, kind){
  // kind: 'acute' or 'circ'
  // Replace final alpha (α/ά/ᾶ etc.) with accented version.
  // We do this on a diacritic-stripped base to keep it simple.
  const base = word.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  if(!base) return base;
  // Find last alpha character (α or ᾳ etc. ignored; keep simple).
  const i = base.lastIndexOf('α');
  if(i === -1) return base;
  const repl = (kind === 'circ') ? 'ᾶ' : 'ά';
  return base.slice(0,i) + repl + base.slice(i+1);
}

function classify(raw){
  const n = normalizeGreek(raw);
  if(!n) return {ok:false, msg:'Type a Greek word first.'};

  const ending = endsWithAny(n, ['βας','γας']);
  const isBoibas = EXCEPTION_CIRCUMFLEX.has(n);

  let rule = null;
  let verdict = null;
  let badge = null;
  let suggestion = null;
  let why = '';

  if(isBoibas){
    rule = 'Exception noted by Herodian';
    verdict = 'περισπώμενον (circumflex on the last syllable)';
    badge = {cls:'warn', text:'Exception: last-syllable circumflex'};
    suggestion = toyAccentOnFinalAlpha(raw, 'circ');
    why = 'Herodian explicitly says <mark>Βοιβᾶς περισπᾶται</mark>.';
  } else if(ending === 'βας'){
    rule = 'Τὰ εἰς -βας βαρύνονται';
    verdict = 'βαρύτονον (not accented on the last syllable)';
    badge = {cls:'good', text:'Rule: barytone'};
    // For the toy, we show what it would look like if it were (wrongly) oxytone.
    suggestion = toyAccentOnFinalAlpha(raw, 'acute');
    why = 'Herodian lists many -βας names and says they are <mark>βαρύνονται</mark>.';
  } else if(ending === 'γας'){
    rule = 'Τὰ εἰς -γας πάντα βαρύνεται (unless joking)';
    verdict = 'βαρύτονον (not accented on the last syllable)';
    badge = {cls:'good', text:'Rule: barytone'};
    suggestion = toyAccentOnFinalAlpha(raw, 'acute');
    why = 'He says -γας forms are barytone, except in jest (e.g. <mark>φαγᾶς</mark>).' ;
  } else {
    rule = 'No match';
    verdict = '—';
    badge = {cls:'bad', text:'Not -βας / -γας'};
    suggestion = null;
    why = 'Try a word ending in <span class="code">-βας</span> or <span class="code">-γας</span>.';
  }

  // Extra: detect if user typed an oxytone/circumflex on last alpha (toy check)
  const rawNFD = (raw||'').normalize('NFD');
  const hasAcuteOnAlpha = /α\u0301/.test(rawNFD) || /ά/.test(raw);
  const hasCircOnAlpha = /α\u0342/.test(rawNFD) || /ᾶ/.test(raw);

  let accentNote = '';
  if(ending && !isBoibas){
    if(hasAcuteOnAlpha || hasCircOnAlpha){
      accentNote = 'You typed an accent on the final α. Under Herodian’s rule this ending is expected to be barytone (i.e. not final-accented).';
    } else {
      accentNote = 'Tip: try adding a final accent (e.g. -άς / -ᾶς) and see how the toy reacts.';
    }
  }
  if(isBoibas){
    if(!hasCircOnAlpha){
      accentNote = 'Try writing it as <span class="code">Βοιβᾶς</span> with a circumflex on the last α.';
    }
  }

  return {ok:true, n, ending, isBoibas, rule, verdict, badge, suggestion, why, accentNote};
}

function render(res, raw){
  if(!res.ok){
    out.innerHTML = `<div class="placeholder">${escapeHtml(res.msg)}</div>`;
    return;
  }

  const rawShown = (raw||'').trim() || '—';
  const normShown = res.n || '—';

  let sugBlock = '';
  if(res.suggestion){
    const label = res.isBoibas ? 'Toy “write it with circumflex on last α”' : 'Toy “what if it were final-accented?”';
    sugBlock = `
      <div class="card">
        <h3>${label}</h3>
        <div class="big">${escapeHtml(res.suggestion)}</div>
        <div class="note">This is just a visual nudge: real Greek accentuation depends on syllable quantity and lexical tradition.</div>
      </div>`;
  }

  out.innerHTML = `
    <div class="grid">
      <div class="card">
        <h3>Classification</h3>
        <div class="kv">
          <div class="k">Input</div><div class="v"><span class="code">${escapeHtml(rawShown)}</span></div>
          <div class="k">Normalized</div><div class="v"><span class="code">${escapeHtml(normShown)}</span></div>
          <div class="k">Ending</div><div class="v">${res.ending ? `<span class="code">-${res.ending}</span>` : '—'}</div>
          <div class="k">Herodian rule</div><div class="v">${res.rule}</div>
          <div class="k">Prosodic label</div><div class="v">${res.verdict}</div>
        </div>
        <div style="margin-top:10px">
          <span class="badge ${res.badge.cls}">${escapeHtml(res.badge.text)}</span>
        </div>
        <div class="note" style="margin-top:10px">${res.why}</div>
        ${res.accentNote ? `<div class="note">${res.accentNote}</div>` : ''}
      </div>
      ${sugBlock || `<div class="card"><h3>Try this</h3><div class="note">Pick an example chip above, or type your own river/ethnic name ending in <span class="code">-βας</span> or <span class="code">-γας</span>.</div></div>`}
    </div>
  `;
}

function escapeHtml(s){
  return String(s)
    .replaceAll('&','&amp;')
    .replaceAll('<','&lt;')
    .replaceAll('>','&gt;')
    .replaceAll('"','&quot;')
    .replaceAll("'",'&#39;');
}

function run(){
  const raw = inp.value;
  const res = classify(raw);
  render(res, raw);
}

document.getElementById('analyze').addEventListener('click', run);
document.getElementById('clear').addEventListener('click', () => {
  inp.value = '';
  inp.focus();
  out.innerHTML = `<div class="placeholder">Enter a word ending in <b>-βας</b> or <b>-γας</b> (or try the chips). The toy will classify it and show a suggested “toy accent”.</div>`;
});

inp.addEventListener('keydown', (e) => {
  if(e.key === 'Enter') run();
});

strip.addEventListener('change', run);

document.querySelectorAll('.chip').forEach(btn => {
  btn.addEventListener('click', () => {
    inp.value = btn.dataset.w;
    run();
    inp.focus();
  });
});

// Seed with a relevant example
inp.value = 'Ἄβας';
run();

