const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const outWord = $('#outWord');
const outRule = $('#outRule');

const optContract = $('#optContract');
const optShortA = $('#optShortA');
const optThroughDos = $('#optThroughDos');
const optDimin = $('#optDimin');

const samples = [
  {w:'Λεωνίδας', note:'-δας (barytone tendency)'} ,
  {w:'Θευδᾶς', note:'noted circumflex'} ,
  {w:'Κερκιδᾶς', note:'from contraction'} ,
  {w:'Ἀρκάς', note:'short α → acute'} ,
  {w:'Περδίκκας', note:'-κας barytone'} ,
  {w:'Στρούθας', note:'-θας barytone'} ,
  {w:'Βύζας', note:'-ζας barytone (toy treats as -ας)'} ,
  {w:'φυγάς', note:'acute (Herodian note)'}
];

function stripDiacritics(s){
  // Remove combining marks; keep base Greek letters.
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function lastIndexOfAny(s, chars){
  for(let i=s.length-1;i>=0;i--){
    if(chars.includes(s[i])) return i;
  }
  return -1;
}

function addAccentToLastAlpha(word, accent){
  // accent: 'acute' | 'circ'
  // We place on the last alpha/eta/omega if present; otherwise last vowel.
  const base = stripDiacritics(word);
  const vowels = 'αεηιουωΑΕΗΙΟΥΩ';
  const targets = 'αΑ';
  let idx = lastIndexOfAny(base, targets);
  if(idx === -1) idx = lastIndexOfAny(base, vowels);
  if(idx === -1) return word; // nothing to do

  const ch = base[idx];
  const mark = accent === 'circ' ? '\u0342' : '\u0301'; // perispomeni / oxia
  // Recompose: insert combining mark after the vowel.
  const withMark = base.slice(0, idx+1) + mark + base.slice(idx+1);
  return withMark.normalize('NFC');
}

function endsWithAny(s, arr){
  return arr.some(e => s.endsWith(e));
}

function guessRule(word){
  const raw = (word || '').trim();
  if(!raw) return {out:'—', rule:'Enter a word to see a rule-of-thumb.'};

  const base = stripDiacritics(raw);
  const lower = base.toLowerCase();

  // Special-cased examples from the passage (toy-level)
  const specialCirc = ['θευδας','μητρας','ζηνας','πυθας','ατταγας','αιγας','αργας','υψας','εξας','κερκιδας'];
  const specialAcute = ['φυγας','αρκας'];

  let accent = null; // 'acute' | 'circ' | 'bary'
  let why = '';

  // User toggles first (they override)
  if(optContract.checked){
    accent = 'circ';
    why = 'Contracted (συναλοιφή) toggle → circumflex as a playful default.';
  }
  if(optShortA.checked){
    accent = 'acute';
    why = 'Short α (συστελλόμενον) toggle → acute (cf. Ἀρκάς).';
  }

  if(!accent){
    if(specialCirc.includes(lower)){
      accent = 'circ';
      why = 'Listed/remarked as circumflex in the passage (toy special-case).';
    } else if(specialAcute.includes(lower)){
      accent = 'acute';
      why = 'Remarked as acute in the passage (toy special-case).';
    }
  }

  // Ending-based heuristics
  if(!accent){
    if(endsWithAny(lower, ['δας'])){
      if(optThroughDos.checked || optDimin.checked){
        accent = 'acute';
        why = 'Ending -δας, but exception toggled (διὰ τοῦ -δος / diminutive) → allow oxytone.';
      } else {
        accent = 'bary';
        why = 'Ending -δας tends to be barytone (accent not on ultima), unless exceptions apply.';
      }
    } else if(endsWithAny(lower, ['θας','κας'])){
      accent = 'bary';
      why = `Ending -${lower.endsWith('θας')?'θας':'κας'} tends to be barytone in Herodian’s list.`;
    } else if(endsWithAny(lower, ['ας'])){
      // Generic -ας: default barytone, but allow acute if user says short alpha.
      accent = 'bary';
      why = 'Generic -ας: toy defaults to barytone (many name-like forms in the passage behave so).';
    } else {
      accent = 'acute';
      why = 'Unknown ending: toy falls back to a simple acute on the last vowel.';
    }
  }

  let out = raw;
  if(accent === 'circ'){
    out = addAccentToLastAlpha(raw, 'circ');
  } else if(accent === 'acute'){
    out = addAccentToLastAlpha(raw, 'acute');
  } else if(accent === 'bary'){
    // For barytone, we *avoid* accenting the last syllable: place acute on the penult-ish by targeting the second-to-last vowel.
    out = addBarytoneToy(raw);
  }

  return {out, rule: why};
}

function addBarytoneToy(word){
  const base = stripDiacritics(word);
  const vowels = 'αεηιουωΑΕΗΙΟΥΩ';
  const vowelIdx = [];
  for(let i=0;i<base.length;i++) if(vowels.includes(base[i])) vowelIdx.push(i);
  if(vowelIdx.length === 0) return word;

  // Choose penult vowel if possible, else last.
  const idx = vowelIdx.length >= 2 ? vowelIdx[vowelIdx.length-2] : vowelIdx[vowelIdx.length-1];
  const withMark = base.slice(0, idx+1) + '\u0301' + base.slice(idx+1);
  return withMark.normalize('NFC');
}

function run(){
  const {out, rule} = guessRule(inp.value);
  outWord.textContent = out;
  outRule.textContent = rule;
}

$('#btnGo').addEventListener('click', run);
$('#btnClear').addEventListener('click', () => {
  inp.value = '';
  outWord.textContent = '—';
  outRule.textContent = 'Enter a word to see a rule-of-thumb.';
  optContract.checked = false;
  optShortA.checked = false;
  optThroughDos.checked = false;
  optDimin.checked = false;
  inp.focus();
});

[inp, optContract, optShortA, optThroughDos, optDimin].forEach(el => {
  el.addEventListener('input', run);
  el.addEventListener('change', run);
});

// Chips
const chips = $('#chips');
samples.forEach(s => {
  const d = document.createElement('div');
  d.className = 'chip';
  d.textContent = s.w;
  d.title = s.note;
  d.addEventListener('click', () => {
    inp.value = s.w;
    // reset toggles for a clean demo
    optContract.checked = false;
    optShortA.checked = false;
    optThroughDos.checked = false;
    optDimin.checked = false;
    run();
    inp.focus();
  });
  chips.appendChild(d);
});

// Initial state
run();

