(() => {
  const $ = (sel, el=document) => el.querySelector(sel);
  const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

  const inp = $('#inp');
  const out = $('#out');

  const examples = [
    'Μύλλας','Πάλλας','Βάλλας','Κύλλας','Κίλλας','Ἴλλας','Σίλλας','Φέλλας','Σέλλας','Ἰόλλας','Ἀβόλλας','Ἀμύλλας','Λευκόλλας',
    'πελλᾶς','ἀλλᾶς','βιλλᾶς',
    'Τόλμας','ἀδάμας','Σίλμας','Τέλμας','Θαύμας','Δύμας','Βρίμας','Μάμας','Δάμας','Πολυδάμας','Ἀθάμας','Σαλάμας','Σπιτάμας',
    'Ἑρμᾶς','Ἀρτεμᾶς',
    'Ἄτλας','Βουκεφάλας','Ἀμύκλας','Ἀργόλας'
  ];

  // --- Greek-ish helpers (heuristic, not a full accent engine) ---
  const combining = /[\u0300-\u036f]/g;

  function nfd(s){ return (s||'').normalize('NFD'); }
  function stripCombining(s){ return nfd(s).replace(combining,'').normalize('NFC'); }

  function stripPunctSpace(s){
    return (s||'')
      .replace(/[\s··.,;:!?"'“”‘’()\[\]{}<>«»—–-]/g,'')
      .trim();
  }

  function lowerGreek(s){
    // Lowercase after stripping combining to avoid oddities; then keep original for display.
    return stripCombining(s).toLowerCase();
  }

  function hasEnding(word, ending){
    return lowerGreek(word).endsWith(ending);
  }

  function isGreekVowel(ch){
    return 'αεηιουωάέήίόύώϊΐϋΰ'.includes(ch);
  }

  function syllabifyRough(word){
    // Very rough: split before each vowel group.
    const w = lowerGreek(stripPunctSpace(word));
    if(!w) return [];
    const chars = Array.from(w);
    let syl = [];
    let cur = '';
    for(let i=0;i<chars.length;i++){
      const c = chars[i];
      const prev = chars[i-1];
      const isV = isGreekVowel(c);
      const prevV = prev ? isGreekVowel(prev) : false;
      if(isV && cur && !prevV){
        // start new syllable at vowel
        syl.push(cur);
        cur = c;
      } else {
        cur += c;
      }
    }
    if(cur) syl.push(cur);
    // Merge leading consonant-only chunk into next syllable
    if(syl.length>=2 && !Array.from(syl[0]).some(isGreekVowel)){
      syl[1] = syl[0] + syl[1];
      syl.shift();
    }
    return syl;
  }

  function accentOnPenultSuggestion(word){
    // Suggest an acute on the penult vowel (heuristic). Works best for -ας endings.
    const clean = stripPunctSpace(word);
    const base = stripCombining(clean); // remove existing accents
    const syl = syllabifyRough(base);
    if(syl.length < 2) return base;
    const penultIndex = syl.length - 2;

    // Find last vowel in penult syllable and add tonos (acute) to it.
    const pen = syl[penultIndex];
    const chars = Array.from(pen);
    let vPos = -1;
    for(let i=chars.length-1;i>=0;i--){
      if(isGreekVowel(chars[i])) { vPos = i; break; }
    }
    if(vPos === -1) return base;

    const map = {
      'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
      'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ',
      'ϊ':'ΐ','ϋ':'ΰ','Ϊ':'Ϊ','Ϋ':'Ϋ'
    };

    // Rebuild with accent
    chars[vPos] = map[chars[vPos]] || chars[vPos];
    syl[penultIndex] = chars.join('');
    return syl.join('');
  }

  function analyzeWord(raw){
    const original = raw;
    const w = stripPunctSpace(raw);
    if(!w) return { error: 'Type a Greek word first.' };

    const plain = stripCombining(w);
    const low = plain.toLowerCase();

    const endsLas = low.endsWith('λας');
    const endsLlas = low.endsWith('λλας');
    const endsMas = low.endsWith('μας');

    // Special “joking” circumflex examples explicitly mentioned
    const jokingSet = new Set(['πελλας','αλλας','βιλλας']);
    const isJoking = jokingSet.has(low);

    // Doric-ish -ᾶς examples mentioned
    const doricSet = new Set(['ερμας','αρτεμας']);
    const isDoric = doricSet.has(low);

    let rule = 'No matching rule detected.';
    let verdict = 'unknown';
    let badge = { cls:'warn', text:'heuristic' };

    if(endsLlas){
      rule = 'Ends in -λλας: Herodian says these are typically <b>barytone</b> when the α is “lengthened”.';
      verdict = 'barytone-likely';
      badge = { cls:'good', text:'barytone-likely' };
      if(isJoking){
        rule += ' But this exact word is one of his playful exceptions with a <b>circumflex</b> on the last syllable.';
        verdict = 'circumflex-exception';
        badge = { cls:'warn', text:'joking exception' };
      }
    } else if(endsMas){
      rule = 'Ends in -μας: Herodian says these are <b>barytone</b>.';
      verdict = 'barytone-likely';
      badge = { cls:'good', text:'barytone-likely' };
      if(isDoric){
        rule += ' He notes Doric-type forms like <b>Ἑρμᾶς</b>, <b>Ἀρτεμᾶς</b> (not barytone).';
        verdict = 'doric-note';
        badge = { cls:'warn', text:'Doric note' };
      }
    } else if(endsLas){
      rule = 'Ends in -λας (single λ): the passage lists many such names; accent varies by word, so we only give a gentle suggestion.';
      verdict = 'varies';
      badge = { cls:'warn', text:'varies' };
    }

    const suggested = (endsLas || endsLlas || endsMas) ? accentOnPenultSuggestion(w) : stripCombining(w);

    // Highlight ending
    let ending = '';
    if(endsLlas) ending = 'λλας';
    else if(endsLas) ending = 'λας';
    else if(endsMas) ending = 'μας';

    return {
      original,
      normalized: plain,
      ending,
      rule,
      verdict,
      badge,
      suggested
    };
  }

  function render(res){
    if(res.error){
      out.innerHTML = `<div class="err">${res.error}</div>`;
      return;
    }

    const endingPretty = res.ending ? `<mark>${res.ending}</mark>` : '<span class="muted">(none)</span>';

    out.innerHTML = `
      <div class="grid">
        <div class="card">
          <div class="k">You typed</div>
          <div class="v">${escapeHtml(res.original)}</div>
        </div>
        <div class="card">
          <div class="k">Detected ending</div>
          <div class="v">${endingPretty}
            <span class="badge ${res.badge.cls}">${escapeHtml(res.badge.text)}</span>
          </div>
        </div>
      </div>
      <hr />
      <div class="card">
        <div class="k">Rule-of-thumb (from the passage)</div>
        <div class="v">${res.rule}</div>
      </div>
      <div class="grid" style="margin-top:10px">
        <div class="card">
          <div class="k">Normalized (accents stripped)</div>
          <div class="v">${escapeHtml(res.normalized)}</div>
        </div>
        <div class="card">
          <div class="k">Toy “barytone” suggestion (acute on penult)</div>
          <div class="v">${escapeHtml(res.suggested)}</div>
        </div>
      </div>
      <div class="note" style="margin-top:10px">
        This suggestion is mechanical: it does <span class="smallcaps">not</span> know vowel quantity or real accent rules; it just helps you notice Herodian’s endings.
      </div>
    `;
  }

  function escapeHtml(s){
    return String(s)
      .replaceAll('&','&amp;')
      .replaceAll('<','&lt;')
      .replaceAll('>','&gt;')
      .replaceAll('"','&quot;')
      .replaceAll("'",'&#39;');
  }

  function run(){
    render(analyzeWord(inp.value));
  }

  $('#analyze').addEventListener('click', run);
  inp.addEventListener('keydown', (e) => {
    if(e.key === 'Enter') run();
  });

  $('#clear').addEventListener('click', () => {
    inp.value = '';
    out.innerHTML = '<div class="placeholder">Output will appear here.</div>';
    inp.focus();
  });

  $('#random').addEventListener('click', () => {
    const w = examples[Math.floor(Math.random()*examples.length)];
    inp.value = w;
    run();
    inp.focus();
  });

  $$('.chip').forEach(b => b.addEventListener('click', () => {
    inp.value = b.dataset.w;
    run();
    inp.focus();
  }));

  // Seed with a relevant example
  inp.value = 'Μύλλας';
  run();
})();

