:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --panel2:#1d2136;
  --text:#eef0ff;
  --muted:#b8bce6;
  --accent:#7dd3fc;
  --good:#86efac;
  --bad:#fca5a5;
  --warn:#fde68a;
  --border:rgba(255,255,255,.12);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
}
*{box-sizing:border-box}
body{margin:0; background:radial-gradient(1200px 700px at 20% 0%, #1b2150 0%, var(--bg) 55%); color:var(--text); font: 15px/1.45 system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;}
.wrap{max-width:980px; margin:0 auto; padding:22px 16px 40px;}
header{margin-bottom:14px}
h1{font-size:20px; margin:0 0 6px; letter-spacing:.2px}
.sub{margin:0; color:var(--muted)}
.panel{background:linear-gradient(180deg, var(--panel) 0%, var(--panel2) 100%); border:1px solid var(--border); border-radius:14px; padding:14px; box-shadow:var(--shadow); margin-top:14px}
.row{display:flex; flex-direction:column; gap:6px; margin-bottom:12px}
label{color:var(--muted); font-size:12px; letter-spacing:.2px}
input, select{width:100%; padding:10px 11px; border-radius:10px; border:1px solid var(--border); background:rgba(0,0,0,.18); color:var(--text); outline:none}
input:focus, select:focus{border-color:rgba(125,211,252,.55); box-shadow:0 0 0 3px rgba(125,211,252,.12)}
.grid{display:grid; grid-template-columns:repeat(3, minmax(0,1fr)); gap:10px}
@media (max-width:820px){.grid{grid-template-columns:1fr}}
.btns{display:flex; gap:10px; flex-wrap:wrap; margin:10px 0 6px}
button{border:1px solid rgba(125,211,252,.35); background:rgba(125,211,252,.14); color:var(--text); padding:9px 12px; border-radius:10px; cursor:pointer}
button:hover{background:rgba(125,211,252,.2)}
button:active{transform:translateY(1px)}
button.ghost{border-color:var(--border); background:rgba(255,255,255,.06)}
.out{margin-top:10px; border:1px dashed rgba(255,255,255,.18); border-radius:12px; padding:12px; background:rgba(0,0,0,.16)}
.kv{display:grid; grid-template-columns:160px 1fr; gap:8px 12px; align-items:start}
@media (max-width:560px){.kv{grid-template-columns:1fr}}
.k{color:var(--muted); font-size:12px}
.v{font-family:var(--mono); font-size:15px}
.badge{display:inline-block; padding:2px 8px; border-radius:999px; border:1px solid var(--border); background:rgba(255,255,255,.06); color:var(--muted); font-size:12px; margin-left:6px}
.badge.good{border-color:rgba(134,239,172,.35); color:var(--good); background:rgba(134,239,172,.08)}
.badge.warn{border-color:rgba(253,230,138,.35); color:var(--warn); background:rgba(253,230,138,.08)}
.badge.bad{border-color:rgba(252,165,165,.35); color:var(--bad); background:rgba(252,165,165,.08)}
.notes{margin-top:10px}
.notes summary{cursor:pointer; color:var(--accent)}
.noteBody{color:var(--muted)}
.quizRow{display:grid; grid-template-columns: 1.3fr .7fr; gap:12px}
@media (max-width:820px){.quizRow{grid-template-columns:1fr}}
.card{border:1px solid var(--border); border-radius:14px; padding:12px; background:rgba(0,0,0,.14)}
.label{color:var(--muted); font-size:12px; margin-bottom:6px}
.qWord{font-family:var(--mono); font-size:22px; padding:10px 12px; border-radius:12px; background:rgba(255,255,255,.06); border:1px solid var(--border)}
.choices{display:flex; gap:10px; flex-wrap:wrap; margin-top:10px}
.feedback{margin-top:10px; color:var(--muted)}
.score{font-family:var(--mono); font-size:22px}
.small{color:var(--muted); font-size:12px; margin-top:8px}
.foot{margin-top:14px; text-align:center}
hr{border:none; border-top:1px solid var(--border); margin:10px 0}

passages.gadget_js:
const $ = (sel) => document.querySelector(sel);

// --- Greek helpers (very lightweight; heuristic) ---
const combining = /[\u0300-\u036f]/g;

function stripCombining(s){
  return (s || "").normalize('NFD').replace(combining,'').normalize('NFC');
}

function normalizeGreek(s){
  return stripCombining(s)
    .replace(/[᾽'’]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function lastGreekVowelIndex(nfd){
  // nfd is NFD, no combining stripped (so we can insert combining after base)
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
  for(let i=nfd.length-1;i>=0;i--){
    const ch = nfd[i];
    if(vowels.has(ch)) return i;
  }
  return -1;
}

function applyCombiningAccent(word, mark){
  // mark: '\u0301' acute, '\u0300' grave, '\u0342' circumflex
  if(!word) return word;
  const nfd = word.normalize('NFD');
  const i = lastGreekVowelIndex(nfd);
  if(i<0) return word;

  // remove any existing accent marks (acute/grave/circumflex) anywhere
  const cleaned = nfd.replace(/[\u0300\u0301\u0342]/g, '');
  // recompute index after cleaning? easiest: find last vowel again
  const j = lastGreekVowelIndex(cleaned);
  if(j<0) return word;

  const out = cleaned.slice(0, j+1) + mark + cleaned.slice(j+1);
  return out.normalize('NFC');
}

function tonosize(word){
  // Convert polytonic combining accents to modern tonos where possible.
  // We do this by mapping precomposed polytonic/tonos forms after NFC.
  // For simplicity: just return NFC; most environments show combining acute as tonos-like.
  return word.normalize('NFC');
}

function polyize(word){
  // Keep combining marks; NFC will often precompose to polytonic.
  return word.normalize('NFC');
}

function detectEnding(base){
  const w = base.toLowerCase();
  const endings = ['νας','πας','ρας','σας'];
  for(const e of endings){
    if(w.endsWith(e)) return e;
  }
  return null;
}

function isSpecial(wordBase){
  const w = wordBase.toLowerCase();
  // Special cases mentioned in passage
  if(w === 'δακνας' || w === 'δακνᾶς') return {type:'mockery', note:'Herodian: δακνᾶς is circumflexed as “mockery”.'};
  if(w === 'μηνας' || w === 'ζηνας') return {type:'diminutive', note:'Herodian: Μηνᾶς / Ζηνᾶς are diminutives (exceptions to the default -νας rule).'};
  if(w === 'μητρας' || w === 'ηρας' || w === 'τετρας' || w === 'βορρας') return {type:'circumflex', note:'Herodian: Μητρᾶς, Ἡρᾶς, τετρᾶς, βορρᾶς are circumflexed.'};
  return null;
}

function renderResult(input){
  const dial = $('#dial').value;
  const mock = $('#mock').value;

  const norm = normalizeGreek(input);
  if(!norm){
    return `<div class="kv"><div class="k">Status</div><div class="v">Type a Greek word above.</div></div>`;
  }

  const base = stripCombining(norm); // remove accents for analysis
  const ending = detectEnding(base);
  const special = isSpecial(base);

  let classification = '';
  let badge = '';
  if(ending){
    classification = `Detected ending: -${ending}`;
    badge = `<span class="badge good">in Herodian’s set</span>`;
  } else {
    classification = `No target ending detected (try -νας, -πας, -ρας, -σας).`;
    badge = `<span class="badge warn">outside toy rules</span>`;
  }

  // Decide suggested accent type
  let suggestedType = 'grave';
  let reason = ending ? `Default for -${ending}: “βαρύνεται” (shown as grave in running text).` : 'No rule applied.';

  // Mockery toggle can force circumflex
  const mockForce = (mock === 'yes');
  const mockBlock = (mock === 'no');

  if(special){
    if(special.type === 'mockery'){
      suggestedType = 'circumflex';
      reason = special.note;
    } else if(special.type === 'circumflex'){
      suggestedType = 'circumflex';
      reason = special.note;
    } else if(special.type === 'diminutive'){
      // For diminutives, Herodian says they are exceptions to the default grave rule.
      // We won't try to compute their “correct” accent; we just flag them.
      suggestedType = 'flag';
      reason = special.note + ' (Toy: flagged, not re-accented.)';
    }
  }

  if(mockForce && suggestedType !== 'flag'){
    suggestedType = 'circumflex';
    reason = 'Forced “mockery” mode: try circumflex on the last vowel.';
  }
  if(mockBlock && special && special.type === 'mockery'){
    suggestedType = 'grave';
    reason = 'Mockery disabled: using default grave-style suggestion.';
  }

  // Build forms
  const acute = applyCombiningAccent(base, '\u0301');
  const grave = applyCombiningAccent(base, '\u0300');
  const circumflex = applyCombiningAccent(base, '\u0342');

  let suggestedForm = grave;
  let suggestedLabel = 'Suggested running-text form (grave)';
  let badge2 = `<span class="badge">heuristic</span>`;

  if(suggestedType === 'circumflex'){
    suggestedForm = circumflex;
    suggestedLabel = 'Suggested exception form (circumflex)';
    badge2 = `<span class="badge bad">exception</span>`;
  } else if(suggestedType === 'flag'){
    suggestedForm = base;
    suggestedLabel = 'Flagged as exception (diminutive)';
    badge2 = `<span class="badge warn">needs lexicon</span>`;
  }

  const show = (s) => dial === 'tonos' ? tonosize(s) : polyize(s);

  const hint = ending ? `Try putting it before another word: <span class="v">${show(grave)} λόγος</span> (grave in continuous text).` : '';

  return `
  <div class="kv">
    <div class="k">Normalized</div><div class="v">${show(base)}</div>
    <div class="k">Classification</div><div class="v">${classification} ${badge}</div>
    <div class="k">Citation-style (acute)</div><div class="v">${show(acute)} <span class="badge">toy</span></div>
    <div class="k">Running-text (grave)</div><div class="v">${show(grave)} <span class="badge">acute→grave</span></div>
    <div class="k">Circumflex try</div><div class="v">${show(circumflex)} <span class="badge">toy</span></div>
    <div class="k">Suggestion</div><div class="v">${show(suggestedForm)} ${badge2}</div>
    <div class="k">Why</div><div class="v">${reason}</div>
  </div>
  ${hint ? `<hr/><div class="small">${hint}</div>` : ''}
  `;
}

// --- Quiz ---
const examples = [
  {w:'Αρτυνας', ans:'grave', note:'Herodian lists Ἀρτύνας among -νας that are “βαρύνεται”.'},
  {w:'Ξενας', ans:'grave', note:'Herodian lists Ξένας.'},
  {w:'Πρατινας', ans:'grave', note:'Herodian lists Πρατίνας.'},
  {w:'Πινας', ans:'grave', note:'Herodian lists Πίνας.'},
  {w:'Καναs'.replace('s','ς'), ans:'grave', note:'Herodian lists Κάνας.'},
  {w:'Μηνας', ans:'circ', note:'Herodian: Μηνᾶς is diminutive (exception).'},
  {w:'Ζηνας', ans:'circ', note:'Herodian: Ζηνᾶς is diminutive (exception).'},
  {w:'δακνας', ans:'circ', note:'Herodian: δακνᾶς is circumflexed (mockery).'},
  {w:'Ευρωπας', ans:'grave', note:'Herodian lists Εὐρώπας among -πας.'},
  {w:'Θηρας', ans:'grave', note:'Herodian: Θήρας among -ρας “βαρύνεται”.'},
  {w:'Μητρας', ans:'circ', note:'Herodian: Μητρᾶς circumflex.'},
  {w:'Ηρας', ans:'circ', note:'Herodian: Ἡρᾶς circumflex.'},
  {w:'Χρυσας', ans:'grave', note:'Herodian: -σας “βαρύνεται” (with caveats).'}
];
let current = null;
let score = 0;
let total = 0;

function pickExample(){
  current = examples[Math.floor(Math.random()*examples.length)];
  $('#qFeedback').textContent = '';
  $('#qWord').textContent = current.w;
}

function judge(choice){
  if(!current) pickExample();
  total++;
  const ok = (choice === current.ans);
  if(ok) score++;
  $('#score').textContent = String(score);
  $('#total').textContent = String(total);
  const msg = ok ? `Correct. ${current.note}` : `Not quite. ${current.note}`;
  $('#qFeedback').innerHTML = `<span class="badge ${ok?'good':'bad'}">${ok?'✓':'✗'}</span> ${msg}`;
  pickExample();
}

function reveal(){
  if(!current) pickExample();
  const base = stripCombining(current.w);
  const grave = applyCombiningAccent(base, '\u0300');
  const circumflex = applyCombiningAccent(base, '\u0342');
  const dial = $('#dial').value;
  const show = (s) => dial === 'tonos' ? tonosize(s) : polyize(s);
  const correctForm = current.ans === 'grave' ? show(grave) : show(circumflex);
  $('#qFeedback').innerHTML = `<span class="badge">Answer</span> ${correctForm} — ${current.note}`;
}

// --- Wiring ---
function run(){
  const mode = $('#mode').value;
  if(mode === 'suggest'){
    $('#out').innerHTML = renderResult($('#inp').value);
  } else {
    // In quiz mode, still show analysis below for the typed word (optional)
    $('#out').innerHTML = renderResult($('#inp').value) + `<hr/><div class="small">Quiz mode is on: use the quiz panel below.</div>`;
  }
}

$('#go').addEventListener('click', run);
$('#clear').addEventListener('click', () => { $('#inp').value=''; $('#out').innerHTML = renderResult(''); });
$('#rand').addEventListener('click', () => {
  const ex = examples[Math.floor(Math.random()*examples.length)].w;
  $('#inp').value = ex;
  run();
});
$('#inp').addEventListener('keydown', (e)=>{ if(e.key==='Enter') run(); });
$('#mode').addEventListener('change', run);
$('#dial').addEventListener('change', ()=>{ run(); reveal(); });
$('#mock').addEventListener('change', run);

$('#guessGrave').addEventListener('click', ()=>judge('grave'));
$('#guessCirc').addEventListener('click', ()=>judge('circ'));
$('#reveal').addEventListener('click', reveal);

// init
$('#out').innerHTML = renderResult('');
pickExample();
$('#score').textContent = '0';
$('#total').textContent = '0';

