(() => {
  const $ = (sel) => document.querySelector(sel);
  const inp = $('#inp');
  const out = $('#out');
  const btnTry = $('#btnTry');
  const btnRand = $('#btnRand');
  const chips = $('#chips');

  const examples = [
    'Σώτας','Μέτας','Τύντας','Κώστας','Ἀρχύτας','Εὐρώτας','Τελεύτας','Ὀφέλτας','Ἀκέλτας','Ἀμύντας',
    'Δέλφας','Ἄλφας','Ἄφας','Κύφας','Κορύφας','Ὑπέρφας','Περίφας','Ὀνόφας',
    'Λέχας','Καλλίχας','Λίχας','Κάλχας','Τρύχας',
    'παιδοπίπας','εὐφαρέτρας','παρθενοπίπας','θυννοθήρας','Εὐρυβίας','Πυθαγόρας','Παυσανίας',
    'φυγάς','Ἀρκάς',
    'Γονατᾶς','Φιλητᾶς','Κομητᾶς'
  ];

  // --- Polytonic helpers (very lightweight) ---
  const COMBINING = /[\u0300-\u036f]/g;
  function nfd(s){ return (s||'').normalize('NFD'); }
  function stripCombining(s){ return nfd(s).replace(COMBINING,'').normalize('NFC'); }

  // Detect if a string contains an acute/circumflex/grave (precomposed or combining)
  function hasAccentMark(s){
    const d = nfd(s);
    // combining tonos/oxia, varia, perispomeni
    return /[\u0301\u0300\u0342]/.test(d) || /[άέήίόύώΆΈΉΊΌΎΏᾶῆῖῦῶὰὲὴὶὸὺὼ]/.test(s);
  }

  function lastGreekLetterBase(s){
    const base = stripCombining(s).trim();
    // remove punctuation
    const cleaned = base.replace(/[··.,;:!?\-—\s\u00B7\u037E\u0387\(\)\[\]\{\}"'“”‘’]/g,'');
    return cleaned;
  }

  function endsWithAny(word, arr){
    return arr.some(e => word.endsWith(e));
  }

  function guessCompound(wordBase){
    // very rough: if it contains a hyphen or looks like it has a common first member
    const w = wordBase;
    if (w.includes('-')) return true;
    const prefixes = ['παιδο','παρθενο','πατραλο','εὐ','φιλο','φιλα','χαλκο','θυνο','θυννο','βου','ευ','phil','eury'];
    return prefixes.some(p => w.toLowerCase().startsWith(p));
  }

  const anomalies = new Map([
    ['Γονατας','Anomaly noted by Herodian: accent behaves oddly for -τας names.'],
    ['Φιλητας','Anomaly noted by Herodian: accent behaves oddly for -τας names.'],
    ['Κομητας','Anomaly noted by Herodian: accent behaves oddly for -τας names.']
  ]);

  const oxytoneWhitelist = new Set([
    'φυγας','Αρκας','Ἀρκας','φυγάς','Ἀρκάς','Αρκάς'
  ]);

  function suggestAccent(wordRaw, target){
    // target: 'barytone' or 'oxytone'
    // We do NOT compute real accent placement; we just add an acute on the last alpha for oxytone,
    // or remove final acute for barytone.
    const w = wordRaw.trim();
    if (!w) return '';

    if (target === 'oxytone') {
      // If already has an accent somewhere, keep it.
      if (hasAccentMark(w)) return w;
      // Add acute to last α/Α if present, else last vowel.
      const map = { 'α':'ά','Α':'Ά','ε':'έ','Ε':'Έ','η':'ή','Η':'Ή','ι':'ί','Ι':'Ί','ο':'ό','Ο':'Ό','υ':'ύ','Υ':'Ύ','ω':'ώ','Ω':'Ώ' };
      for (let i=w.length-1;i>=0;i--){
        const ch = w[i];
        if (map[ch]) return w.slice(0,i)+map[ch]+w.slice(i+1);
      }
      return w;
    }

    if (target === 'barytone') {
      // If it ends with accented alpha (ά/ὰ/ᾶ etc.), try to de-accent that last vowel.
      // We'll strip combining marks and return base form.
      // But keep other accents if present? For simplicity, strip all accents.
      return stripCombining(w);
    }
    return w;
  }

  function analyze(input){
    const raw = (input||'').trim();
    if (!raw) {
      out.innerHTML = '<div class="note">Type a Greek word above, then click <b>Analyze</b>.</div>';
      return;
    }

    const base = lastGreekLetterBase(raw);
    const baseNoMarks = stripCombining(base);
    const baseKey = baseNoMarks.replace(/ς/g,'σ');

    const wLower = baseNoMarks.toLowerCase();

    const endingRules = [
      { endings: ['τας'], label: '-τας', defaultAccent: 'barytone' },
      { endings: ['φας'], label: '-φας', defaultAccent: 'barytone' },
      { endings: ['χας'], label: '-χας', defaultAccent: 'barytone' },
      { endings: ['ας'],  label: '-ας',  defaultAccent: 'barytone' }
    ];

    let matched = null;
    for (const r of endingRules){
      if (endsWithAny(wLower, r.endings)) { matched = r; break; }
    }

    let verdict = 'unknown';
    let why = [];
    let badgeClass = 'warn';

    // Exceptions
    const anomalyMsg = anomalies.get(baseKey);
    if (anomalyMsg) {
      verdict = 'anomalous';
      badgeClass = 'bad';
      why.push(anomalyMsg);
    }

    // Oxytone contracted -άς (toy)
    const looksOxytone = oxytoneWhitelist.has(baseNoMarks) || /άς$/i.test(raw) || /\u0301\s*ς$/i.test(nfd(raw));

    if (verdict !== 'anomalous') {
      if (!matched) {
        verdict = 'unknown';
        badgeClass = 'warn';
        why.push('No matching ending among -τας / -φας / -χας / -ας.');
      } else {
        if (matched.label === '-ας') {
          if (looksOxytone) {
            verdict = 'oxytone';
            badgeClass = 'good';
            why.push('Toy rule: contracted -άς types (e.g. φυγάς, Ἀρκάς) are oxytone and decline in -δος.');
          } else if (guessCompound(baseNoMarks)) {
            verdict = 'barytone';
            badgeClass = 'good';
            why.push('Toy rule: compounds in -ας tend to be barytone (accent not on the last).');
          } else {
            verdict = 'barytone';
            badgeClass = 'good';
            why.push('Default from this passage: many -ας name-types are treated as barytone (especially compounds).');
          }
        } else {
          verdict = 'barytone';
          badgeClass = 'good';
          why.push(`Rule from the passage: words ending in ${matched.label} are barytone.`);
        }
      }
    }

    const suggested = (verdict === 'oxytone')
      ? suggestAccent(raw, 'oxytone')
      : (verdict === 'barytone')
        ? suggestAccent(raw, 'barytone')
        : raw;

    const ending = matched ? matched.label : '—';

    const badgeText = verdict === 'barytone' ? 'BARYTONE (not final)' :
                      verdict === 'oxytone' ? 'OXYTONE (final)' :
                      verdict === 'anomalous' ? 'ANOMALOUS' : 'UNKNOWN';

    const extra = [];
    if (matched && matched.label !== '—') {
      extra.push(`Detected ending: <b>${ending}</b>`);
    }
    if (matched && matched.label === '-ας') {
      extra.push(`Compound-guess: <b>${guessCompound(baseNoMarks) ? 'yes' : 'no'}</b>`);
      extra.push(`Has accent mark already: <b>${hasAccentMark(raw) ? 'yes' : 'no'}</b>`);
    }

    out.innerHTML = `
      <div class="grid">
        <div class="card">
          <div class="k">Input (as typed)</div>
          <div class="v mono">${escapeHtml(raw)}</div>
          <hr class="sep" />
          <div class="k">Normalized (no diacritics)</div>
          <div class="v mono">${escapeHtml(stripCombining(raw))}</div>
        </div>
        <div class="card">
          <div class="k">Herodian-style guess</div>
          <div class="v">
            <span class="badge ${badgeClass}">${badgeText}</span>
          </div>
          <div class="fine">${why.map(x => '• ' + escapeHtml(x)).join('<br>')}</div>
          <hr class="sep" />
          <div class="k">Suggested form (toy)</div>
          <div class="v mono">${escapeHtml(suggested)}</div>
          <div class="fine">${extra.join(' · ')}</div>
        </div>
      </div>
    `;
  }

  function escapeHtml(s){
    return String(s)
      .replaceAll('&','&amp;')
      .replaceAll('<','&lt;')
      .replaceAll('>','&gt;')
      .replaceAll('"','&quot;')
      .replaceAll("'",'&#39;');
  }

  function loadRandom(){
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inp.value = ex;
    analyze(ex);
  }

  function addChips(){
    const picks = ['Σώτας','Δέλφας','Κάλχας','παιδοπίπας','Πυθαγόρας','φυγάς','Ἀρκάς','Γονατᾶς'];
    chips.innerHTML = '';
    for (const w of picks){
      const d = document.createElement('div');
      d.className = 'chip';
      d.textContent = w;
      d.title = 'Click to analyze';
      d.addEventListener('click', () => { inp.value = w; analyze(w); inp.focus(); });
      chips.appendChild(d);
    }
  }

  btnTry.addEventListener('click', () => analyze(inp.value));
  btnRand.addEventListener('click', loadRandom);
  inp.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') analyze(inp.value);
  });

  addChips();
  analyze('Σώτας');
})();

