const $ = (sel, el=document) => el.querySelector(sel);
const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

// --- Greek helpers (very lightweight) ---
// Strip combining marks and common precomposed tonos/oxia variants by NFD.
function stripDiacritics(s){
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function endsWithNormalized(word, ending, ignoreAccents){
  const w = ignoreAccents ? stripDiacritics(word) : word;
  const e = ignoreAccents ? stripDiacritics(ending) : ending;
  return w.endsWith(e);
}

function replaceEnding(word, fromEnding, toEnding, ignoreAccents){
  // Replace based on normalized match, but keep original prefix.
  const wNorm = ignoreAccents ? stripDiacritics(word) : word;
  const fNorm = ignoreAccents ? stripDiacritics(fromEnding) : fromEnding;
  if(!wNorm.endsWith(fNorm)) return null;
  // Find cut length in original string by using ending length in code units.
  // This is approximate but fine for Greek here.
  const cut = fromEnding.length;
  return word.slice(0, word.length - cut) + toEnding;
}

function guessType(word, ignoreAccents){
  // Order matters: -ιάς is a subset of -άς.
  if(endsWithNormalized(word,'ιάς',ignoreAccents)) return 'ias';
  if(endsWithNormalized(word,'άς',ignoreAccents) || endsWithNormalized(word,'ας',ignoreAccents)) return 'as';
  return 'other';
}

function buildTransforms(word, ignoreAccents){
  const type = guessType(word, ignoreAccents);
  const res = {type, word};

  if(type==='ias'){
    // Δημητριάς → Δημητριάδος, Δημητριάδες, Δημητριακός (toy)
    res.gen = replaceEnding(word,'ιάς','ιάδος',ignoreAccents) ?? (word + ' (—)');
    res.pl = replaceEnding(word,'ιάς','ιάδες',ignoreAccents) ?? (word + ' (—)');
    // Ethnic adjective: -ιακός is common-ish for toponyms; keep it playful.
    res.ethAdj = replaceEnding(word,'ιάς','ιακός',ignoreAccents) ?? (word + ' (—)');
    res.note = 'Toy rule: many toponyms in -ιάς form a genitive in -ιάδος (cf. Δημητριάς → Δημητριάδος).';
  } else if(type==='as'){
    // Ἑλλάς → Ἑλλάδος, Ἑλλάδες; also a playful -αῖος ethnic.
    // Note: some -άς are 3rd declension; we mimic that.
    // If input is plain -ας without accent, still do -αδος.
    if(endsWithNormalized(word,'άς',ignoreAccents)){
      res.gen = replaceEnding(word,'άς','άδος',ignoreAccents);
      res.pl = replaceEnding(word,'άς','άδες',ignoreAccents);
      res.ethAdj = replaceEnding(word,'άς','αῖος',ignoreAccents);
    } else {
      res.gen = replaceEnding(word,'ας','αδος',ignoreAccents);
      res.pl = replaceEnding(word,'ας','αδες',ignoreAccents);
      res.ethAdj = replaceEnding(word,'ας','αιος',ignoreAccents);
    }
    res.note = 'Toy rule: many names in -άς behave like 3rd declension: gen. -άδος, pl. -άδες (e.g. Ἑλλάς → Ἑλλάδος).';
  } else {
    res.gen = '—';
    res.pl = '—';
    res.ethAdj = '—';
    res.note = 'Try a word ending in -άς or -ιάς (accents optional if “ignore accents” is on).';
  }

  // Accent/prosody-ish hint: show last 3 letters and a crude “accent present?”
  const last = word.slice(Math.max(0, word.length-4));
  res.tail = last;
  res.hasAccent = /[άέήίόύώΐΰ]/.test(word) || /\u0301/.test(word.normalize('NFD'));
  return res;
}

function renderOutput(t, showRules){
  const typeLabel = t.type==='ias' ? 'ends in -ιάς' : (t.type==='as' ? 'ends in -άς' : 'ending not recognized');
  const badge = t.type==='ias' ? '<span class="badge">-ιάς</span>' : (t.type==='as' ? '<span class="badge">-άς</span>' : '<span class="badge">?</span>');

  $('#out').innerHTML = `
    <div class="grid">
      <div class="box">
        <h3>Transformations</h3>
        <div class="kv">
          <div class="k">Input</div><div class="v">${escapeHtml(t.word)} ${badge}</div>
          <div class="k">Genitive (toy)</div><div class="v">${escapeHtml(t.gen ?? '—')}</div>
          <div class="k">Plural (toy)</div><div class="v">${escapeHtml(t.pl ?? '—')}</div>
          <div class="k">Ethnic adj. (toy)</div><div class="v">${escapeHtml(t.ethAdj ?? '—')}</div>
        </div>
        ${showRules ? `<div class="note">${escapeHtml(t.note)}<br><span class="badge">Herodian-ish idea</span> catalogues lots of proper names by their endings.</div>` : ''}
      </div>
      <div class="box">
        <h3>Ending & accent peek</h3>
        <div class="kv">
          <div class="k">Detected</div><div class="v">${escapeHtml(typeLabel)}</div>
          <div class="k">Tail</div><div class="v">${escapeHtml(t.tail)}</div>
          <div class="k">Accent seen?</div><div class="v">${t.hasAccent ? '<span class="good">yes</span>' : '<span class="bad">no/unknown</span>'}</div>
        </div>
        <div class="note">Prosody note (toy): the written accent often sits near the end in these forms (e.g. -άς, -ιάς). This box just checks whether an accent mark is present.</div>
      </div>
    </div>
  `;
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

// --- UI wiring ---
const inp = $('#inp');
const go = $('#go');
const strip = $('#strip');
const showRules = $('#showRules');

function run(){
  const w = inp.value.trim();
  const t = buildTransforms(w, strip.checked);
  renderOutput(t, showRules.checked);
}

go.addEventListener('click', run);
inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') run(); });
$$('.chip').forEach(b=>b.addEventListener('click', ()=>{ inp.value = b.dataset.fill; run(); inp.focus(); }));

// --- Quiz game ---
const quizWords = [
  // -ιάς (toponyms in passage)
  {w:'Δημητριάς', a:'ias'},
  {w:'Τιβεριάς', a:'ias'},
  {w:'Προυσιάς', a:'ias'},
  {w:'Ἀφροδισιάς', a:'ias'},
  {w:'Διοσκουριάς', a:'ias'},
  {w:'Ἀπολλωνιάς', a:'ias'},
  {w:'Θυνιάς', a:'ias'},
  {w:'Ξυνιάς', a:'ias'},
  {w:'Μενουθιάς', a:'ias'},
  {w:'Ἰδριάς', a:'ias'},
  // -άς (not -ιάς)
  {w:'Ἑλλάς', a:'as'},
  {w:'Τρῳάς', a:'as'},
  {w:'Στροφάς', a:'as'},
  {w:'Στοιχάς', a:'as'},
  {w:'Νουβάς', a:'as'},
  {w:'Ὀλκάς', a:'as'},
  {w:'Παλλάς', a:'as'},
  {w:'λαμπάς', a:'as'},
  {w:'δυάς', a:'as'},
  {w:'τριάς', a:'as'}
];

let right=0, wrong=0, current=null;

function pick(){
  current = quizWords[Math.floor(Math.random()*quizWords.length)];
  $('#quizWord').textContent = current.w;
  $('#quizFeedback').textContent = 'Guess the ending.';
}

function answer(guess){
  if(!current) return;
  const ok = (guess===current.a);
  if(ok){
    right++; $('#right').textContent = right;
    $('#quizFeedback').innerHTML = `<span class="good">Right.</span> ${escapeHtml(current.w)} ${current.a==='ias'?'ends in -ιάς':'ends in -άς (but not -ιάς)'}.`;
  } else {
    wrong++; $('#wrong').textContent = wrong;
    $('#quizFeedback').innerHTML = `<span class="bad">Nope.</span> ${escapeHtml(current.w)} ${current.a==='ias'?'ends in -ιάς':'ends in -άς (but not -ιάς)'}.`;
  }
}

$$('.btn').forEach(b=>b.addEventListener('click', ()=>answer(b.dataset.guess)));
$('#next').addEventListener('click', pick);
$('#reset').addEventListener('click', ()=>{ right=0; wrong=0; $('#right').textContent='0'; $('#wrong').textContent='0'; pick(); });

// init
inp.value = 'Ἑλλάς';
run();
pick();

