:root{
  --bg:#0f1220;
  --card:#171a2b;
  --card2:#1d2140;
  --text:#e9ecff;
  --muted:#b9c0ff;
  --faint:#8e96d6;
  --accent:#7bdcff;
  --accent2:#b7ff7b;
  --danger:#ff7b9c;
  --line:rgba(255,255,255,.12);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Noto Sans", "Liberation Sans", sans-serif;
}

*{box-sizing:border-box}

body{
  margin:0;
  font-family:var(--sans);
  background: radial-gradient(1200px 700px at 20% 10%, rgba(123,220,255,.18), transparent 55%),
              radial-gradient(900px 600px at 80% 20%, rgba(183,255,123,.12), transparent 55%),
              radial-gradient(900px 700px at 50% 90%, rgba(255,123,156,.10), transparent 60%),
              var(--bg);
  color:var(--text);
}

.wrap{max-width:1050px;margin:0 auto;padding:22px 16px 40px}

.hdr{display:flex;gap:16px;align-items:flex-end;justify-content:space-between;margin-bottom:14px}

h1{font-size:22px;margin:0 0 6px;letter-spacing:.2px}
.sub{margin:0;color:var(--muted);line-height:1.35;font-size:13.5px}

.card{
  background: linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));
  border:1px solid var(--line);
  border-radius:14px;
  padding:14px 14px 16px;
  box-shadow:var(--shadow);
  margin:14px 0;
}

h2{font-size:15px;margin:0 0 10px;color:var(--text)}

.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.lbl{font-size:12px;color:var(--faint);min-width:44px}

.inp{
  flex:1;
  min-width:240px;
  padding:10px 12px;
  border-radius:10px;
  border:1px solid var(--line);
  background:rgba(0,0,0,.25);
  color:var(--text);
  outline:none;
  font-size:16px;
}
.inp:focus{border-color:rgba(123,220,255,.55); box-shadow:0 0 0 3px rgba(123,220,255,.12)}

.btn{
  padding:10px 12px;
  border-radius:10px;
  border:1px solid rgba(123,220,255,.35);
  background:rgba(123,220,255,.12);
  color:var(--text);
  cursor:pointer;
  font-weight:650;
  letter-spacing:.2px;
}
.btn:hover{background:rgba(123,220,255,.18)}
.btn:active{transform:translateY(1px)}

.btn.ghost{
  border-color:var(--line);
  background:rgba(255,255,255,.04);
  color:var(--muted);
  font-weight:600;
}
.btn.ghost:hover{background:rgba(255,255,255,.07)}

.grid{display:grid;grid-template-columns:1.1fr 1fr 1fr;gap:12px;margin-top:12px}
@media (max-width: 900px){.grid{grid-template-columns:1fr}}

.panel{
  border:1px solid var(--line);
  border-radius:12px;
  padding:12px;
  background:rgba(0,0,0,.18);
}
.panel h3{margin:0 0 8px;font-size:13px;color:var(--muted);letter-spacing:.2px}

.verdict{
  font-size:14px;
  line-height:1.35;
  padding:10px 10px;
  border-radius:10px;
  border:1px dashed rgba(255,255,255,.18);
  background:rgba(0,0,0,.18);
}

.out{display:flex;flex-direction:column;gap:8px}
.outRow{display:flex;gap:10px;align-items:baseline}
.tag{
  font-size:11px;
  color:var(--faint);
  min-width:110px;
}
.mono{font-family:var(--mono);font-size:16px}

.morph{font-family:var(--mono);font-size:13px;line-height:1.45;color:var(--text)}

.mini{margin-top:8px;color:var(--faint);font-size:12px;line-height:1.35}

.quiz{margin-top:10px;border:1px solid var(--line);border-radius:12px;padding:12px;background:rgba(0,0,0,.18)}
.qWord{font-family:var(--mono);font-size:22px;letter-spacing:.2px;margin-bottom:6px}
.qInfo{color:var(--muted);font-size:12.5px;line-height:1.35}
.qResult{margin-top:10px;font-size:13px;line-height:1.35}

.good{color:var(--accent2)}
.bad{color:var(--danger)}

.ft details{color:var(--muted)}
.ft summary{cursor:pointer}
.ft ul{margin:10px 0 0 18px}
.ft li{margin:6px 0;color:var(--muted);font-size:12.5px;line-height:1.35}

