// Herodian Accent Toy (offline, vanilla JS)
(() => {
  const $ = (sel) => document.querySelector(sel);

  const inp = $('#inp');
  const outTyped = $('#outTyped');
  const outGrave = $('#outGrave');
  const outAcute = $('#outAcute');
  const outCirc = $('#outCirc');
  const verdict = $('#verdict');
  const morph = $('#morph');

  const btnAnalyze = $('#btnAnalyze');
  const btnRandom = $('#btnRandom');
  const btnClear = $('#btnClear');

  const btnDeal = $('#btnDeal');
  const btnGuessRule = $('#btnGuessRule');
  const btnGuessEx = $('#btnGuessEx');
  const btnReveal = $('#btnReveal');
  const qWord = $('#qWord');
  const qInfo = $('#qInfo');
  const qResult = $('#qResult');

  // --- Utilities for Greek accents (toy-level) ---
  const combining = {
    acute: '\u0301',
    grave: '\u0300',
    circumflex: '\u0342',
    diaeresis: '\u0308',
    smooth: '\u0313',
    rough: '\u0314',
    iotaSub: '\u0345'
  };

  const baseVowels = new Set([
    'α','ε','η','ι','ο','υ','ω',
    'Α','Ε','Η','Ι','Ο','Υ','Ω'
  ]);

  function nfd(s){ return (s||'').normalize('NFD'); }
  function nfc(s){ return (s||'').normalize('NFC'); }

  function stripCombining(s){
    return nfd(s).replace(/[\u0300-\u036f]/g,'');
  }

  function stripAccentOnly(s){
    // remove acute/grave/circumflex but keep breathings/diaeresis/iota-sub
    return nfd(s).replace(/[\u0300\u0301\u0342]/g,'');
  }

  function lastVowelIndexNFD(sNFD){
    // Find index of last base vowel char in NFD string.
    for(let i=sNFD.length-1;i>=0;i--){
      if(baseVowels.has(sNFD[i])) return i;
    }
    return -1;
  }

  function applyAccentToLastVowel(word, accentComb){
    if(!word) return '';
    const s = nfd(word);
    const i = lastVowelIndexNFD(s);
    if(i<0) return word;

    // Remove existing accent marks from the whole word, then add to last vowel.
    let clean = stripAccentOnly(s);

    // After stripping, indices may shift only by removed combining marks; base vowel positions remain.
    // Recompute last vowel index.
    const j = lastVowelIndexNFD(clean);
    if(j<0) return nfc(clean);

    // Insert accent combining mark right after the vowel and after any existing combining marks that belong to it.
    // In NFD, combining marks follow the base. We'll place accent after existing combining marks (breathing/diaeresis).
    let k = j+1;
    while(k < clean.length && /[\u0300-\u036f]/.test(clean[k])) k++;
    const out = clean.slice(0,k) + accentComb + clean.slice(k);
    return nfc(out);
  }

  function countSyllablesToy(word){
    // Very rough: count vowel groups in stripped string.
    const s = stripCombining(word).toLowerCase();
    const vowels = 'αεηιουω';
    let count = 0;
    let prevV = false;
    for(const ch of s){
      const isV = vowels.includes(ch);
      if(isV && !prevV) count++;
      prevV = isV;
    }
    return count;
  }

  function endsWithIgnoreDiacritics(word, ending){
    const w = stripCombining(word);
    return w.endsWith(ending);
  }

  function hasOnlyUPreFinalToy(word){
    // For -ης words: check the vowel immediately before the final vowel group is upsilon.
    // Example: Ὑῆς (υ + ης), Θυῆς, Κυῆς.
    const s = stripCombining(word).toLowerCase();
    // Find last vowel position
    const vowels = new Set(['α','ε','η','ι','ο','υ','ω']);
    let lastV = -1;
    for(let i=s.length-1;i>=0;i--){ if(vowels.has(s[i])) { lastV=i; break; } }
    if(lastV<0) return false;
    // Find previous vowel before lastV
    for(let i=lastV-1;i>=0;i--){
      if(vowels.has(s[i])) return s[i]==='υ';
    }
    return false;
  }

  // A few curated examples from the passage with "expected" category.
  const lexicon = [
    {w:'Ναίης', cat:'rule', note:'Listed as a simple -ης name; toy treats as barytone.'},
    {w:'Δάης', cat:'rule', note:'Listed; toy treats as barytone.'},
    {w:'Κλεύης', cat:'rule', note:'Listed; toy treats as barytone.'},
    {w:'γλοίης', cat:'rule', note:'Listed; toy treats as barytone.'},
    {w:'Βρύης', cat:'rule', note:'Listed; toy treats as barytone.'},
    {w:'Ὑῆς', cat:'circ', note:'Herodian: circumflex (υ before final, isosyllabic).'},
    {w:'Θυῆς', cat:'circ', note:'Herodian: circumflex (υ before final, isosyllabic).'},
    {w:'Κυῆς', cat:'circ', note:'Herodian: circumflex (υ before final, isosyllabic).'},
    {w:'Γύης', cat:'rule', note:'Herodian: barytone when declined with extra syllable (Γύητος).'},
    {w:'Μύης', cat:'rule', note:'Herodian: barytone when declined with extra syllable.'},
    {w:'ζαής', cat:'acute', note:'Herodian: as compound, acute.'},
    {w:'Τελμισσιάς', cat:'ias', note:'Toponym in -ιάς (not the -ης rule).'},
    {w:'Βολογεσσιάς', cat:'ias', note:'Toponym in -ιάς (not the -ης rule).'},
    {w:'Ἡφαιστιάς', cat:'ias', note:'Toponym in -ιάς (not the -ης rule).'},
    {w:'Κεραστιάς', cat:'ias', note:'Toponym in -ιάς (not the -ης rule).'},
    {w:'Κεραστίς', cat:'other', note:'Variant name; not -ης.'},
    {w:'μέγας', cat:'other', note:'Discussed as irregular; not -ης.'},
    {w:'λᾶας', cat:'other', note:'Discussed; not -ης.'}
  ];

  function analyzeWord(word){
    const trimmed = (word||'').trim();
    if(!trimmed) return null;

    const syll = countSyllablesToy(trimmed);
    const isEtaS = endsWithIgnoreDiacritics(trimmed,'ης') || endsWithIgnoreDiacritics(trimmed,'ΗΣ');
    const isIas = endsWithIgnoreDiacritics(trimmed,'ιάς') || endsWithIgnoreDiacritics(trimmed,'ιας') || endsWithIgnoreDiacritics(trimmed,'ΙΑΣ') || endsWithIgnoreDiacritics(trimmed,'ΙΑΣ');

    // If in lexicon, trust it.
    const hit = lexicon.find(x => stripCombining(x.w) === stripCombining(trimmed));

    let cat = 'unknown';
    let reason = '';

    if(hit){
      cat = hit.cat;
      reason = hit.note;
    } else if(isEtaS && syll===2){
      // toy Herodian rule
      if(hasOnlyUPreFinalToy(trimmed)){
        cat = 'circ';
        reason = 'Toy heuristic: disyllabic -ης with υ before the final syllable → treat like Ὑῆς/Θυῆς/Κυῆς (circumflex).';
      } else {
        cat = 'rule';
        reason = 'Toy heuristic: simple disyllabic -ης → barytone (show grave on the last syllable).';
      }
    } else if(isIas){
      cat = 'ias';
      reason = 'Looks like a toponym in -ιάς (common in the passage). Accent rules vary; toy just offers a playful derivation.';
    } else if(isEtaS){
      cat = 'maybe';
      reason = 'Ends in -ης, but toy is unsure (not clearly disyllabic).';
    } else {
      cat = 'other';
      reason = 'Not an -ης noun (or not recognized).';
    }

    // Suggested accent output
    let suggested = null;
    if(cat==='rule') suggested = applyAccentToLastVowel(trimmed, combining.grave);
    if(cat==='acute') suggested = applyAccentToLastVowel(trimmed, combining.acute);
    if(cat==='circ') suggested = applyAccentToLastVowel(trimmed, combining.circumflex);

    return {trimmed, syll, isEtaS, isIas, cat, reason, suggested};
  }

  function render(word){
    const a = analyzeWord(word);
    if(!a){
      outTyped.textContent = '—';
      outGrave.textContent = '—';
      outAcute.textContent = '—';
      outCirc.textContent = '—';
      verdict.textContent = '—';
      morph.textContent = '—';
      return;
    }

    outTyped.textContent = a.trimmed;
    outGrave.textContent = applyAccentToLastVowel(a.trimmed, combining.grave);
    outAcute.textContent = applyAccentToLastVowel(a.trimmed, combining.acute);
    outCirc.textContent = applyAccentToLastVowel(a.trimmed, combining.circumflex);

    const catLabel = {
      rule: 'Rule-case: βαρυτονο (grave on last in citation)',
      circ: 'Exception: circumflex (περισπᾶται) on last',
      acute: 'Exception: acute (ὀξύνεται) on last',
      ias: 'Toponym in -ιάς (place-name style)',
      maybe: 'Uncertain -ης case',
      other: 'Other / not -ης'
    }[a.cat] || 'Unknown';

    const sug = a.suggested ? `\nSuggested: ${a.suggested}` : '';
    verdict.textContent = `${catLabel}\nSyllables (toy): ${a.syll}\n${a.reason}${sug}`;

    morph.innerHTML = buildMorphBlock(a.trimmed, a);
  }

  function buildMorphBlock(word, a){
    const bare = stripCombining(word);
    const lines = [];

    if(a.isIas){
      // playful derivation: -ιάς often feels like a feminine toponym/adjectival formation.
      const stem = bare.replace(/ιάς$/,'').replace(/ιας$/,'');
      const guessEthnic = stem ? stem + 'ιανός' : '(stem)+ιανός';
      const guessAdj = stem ? stem + 'ιακός' : '(stem)+ιακός';
      lines.push(`<div><span class="k">Ending:</span> -ιάς (toponym-ish)</div>`);
      lines.push(`<div><span class="k">Toy stem:</span> <span class="mono">${escapeHTML(stem||'—')}</span></div>`);
      lines.push(`<div><span class="k">Make an ethnic (toy):</span> <span class="mono">${escapeHTML(guessEthnic)}</span></div>`);
      lines.push(`<div><span class="k">Make an adjective (toy):</span> <span class="mono">${escapeHTML(guessAdj)}</span></div>`);
      lines.push(`<div class="hint">Try swapping stems: <span class="mono">Τελμισσι-</span>, <span class="mono">Βολογεσσι-</span>, <span class="mono">Ἡφαιστι-</span>.</div>`);
    } else if(a.isEtaS){
      const stem = bare.replace(/ης$/,'').replace(/ΗΣ$/,'');
      lines.push(`<div><span class="k">Ending:</span> -ης</div>`);
      lines.push(`<div><span class="k">Toy stem:</span> <span class="mono">${escapeHTML(stem||'—')}</span></div>`);
      lines.push(`<div><span class="k">Toy genitive guess:</span> <span class="mono">${escapeHTML(stem + 'ου')}</span> <span class="dim">(not reliable!)</span></div>`);
      lines.push(`<div><span class="k">Toy plural guess:</span> <span class="mono">${escapeHTML(stem + 'αι')}</span> <span class="dim">(often wrong for -ης)</span></div>`);
      lines.push(`<div class="hint">This panel is intentionally playful: Herodian is about accent/prosody, not a full declension engine.</div>`);
    } else {
      lines.push(`<div><span class="k">No special ending detected.</span></div>`);
      lines.push(`<div class="hint">Try a disyllabic -ης name (e.g. <span class="mono">Δάης</span>) or a -ιάς toponym (e.g. <span class="mono">Τελμισσιάς</span>).</div>`);
    }

    return `<div class="morphBlock">${lines.join('')}</div>`;
  }

  function escapeHTML(s){
    return (s+'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  // --- Quiz ---
  const quizPool = lexicon.filter(x => ['rule','circ','acute'].includes(x.cat));
  let current = null;
  let guess = null;

  function deal(){
    current = quizPool[Math.floor(Math.random()*quizPool.length)];
    guess = null;
    qWord.textContent = current.w;
    qInfo.textContent = 'Guess first, then Reveal.';
    qResult.textContent = '';
    qResult.className = 'qResult';
  }

  function setGuess(g){
    if(!current){ qInfo.textContent = 'Click Deal first.'; return; }
    guess = g;
    qInfo.textContent = `Your guess: ${g==='rule' ? 'Rule (grave)' : 'Exception'}. Now click Reveal.`;
  }

  function reveal(){
    if(!current){ qInfo.textContent = 'Click Deal first.'; return; }
    const isRule = current.cat==='rule';
    const expectedLabel = isRule ? 'Rule (grave)' : (current.cat==='circ' ? 'Exception (circumflex)' : 'Exception (acute)');
    const shown = current.cat==='rule'
      ? applyAccentToLastVowel(current.w, combining.grave)
      : current.cat==='circ'
        ? applyAccentToLastVowel(current.w, combining.circumflex)
        : applyAccentToLastVowel(current.w, combining.acute);

    const ok = (guess===null) ? null : (guess==='rule' ? isRule : !isRule);

    let msg = `Expected: ${expectedLabel}.\nToy accent: ${shown}.\nNote: ${current.note}`;
    qResult.textContent = msg;
    if(ok===true){ qResult.classList.add('good'); }
    else if(ok===false){ qResult.classList.add('bad'); }
  }

  // --- Wire up ---
  btnAnalyze.addEventListener('click', () => render(inp.value));
  inp.addEventListener('keydown', (e) => {
    if(e.key==='Enter') render(inp.value);
  });

  btnRandom.addEventListener('click', () => {
    const ex = lexicon[Math.floor(Math.random()*lexicon.length)].w;
    inp.value = ex;
    render(ex);
  });

  btnClear.addEventListener('click', () => {
    inp.value = '';
    render('');
    inp.focus();
  });

  btnDeal.addEventListener('click', deal);
  btnGuessRule.addEventListener('click', () => setGuess('rule'));
  btnGuessEx.addEventListener('click', () => setGuess('ex'));
  btnReveal.addEventListener('click', reveal);

  // initial
  inp.value = 'Ναίης';
  render(inp.value);
  deal();
})();

