const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const outMain = $('#outMain');
const outAlt = $('#outAlt');
const outWhy = $('#outWhy');
const ethOut = $('#ethOut');

const examples = [
  'Λαβης','λεβης','Κεβης','Καβης','Χαβης','Σιβης','Νουβης','Βυβης','κιβης','Μεγης'
];

// --- Greek helpers (very lightweight) ---
const combining = {
  acute: '\u0301',
  grave: '\u0300',
  circumflex: '\u0342',
  diaeresis: '\u0308',
  smooth: '\u0313',
  rough: '\u0314',
  iotaSub: '\u0345'
};

function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripDiacritics(s){
  // Remove Greek combining marks broadly.
  return nfc(nfd(s).replace(/[\u0300-\u036f]/g,''));
}

function hasGreek(s){ return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(s); }

function lastIndexOfGreekVowel(base){
  // base should be stripped of diacritics.
  const vowels = 'αεηιουωΑΕΗΙΟΥΩ';
  for(let i=base.length-1;i>=0;i--){
    if(vowels.includes(base[i])) return i;
  }
  return -1;
}

function vowelPositions(base){
  const vowels = 'αεηιουωΑΕΗΙΟΥΩ';
  const pos=[];
  for(let i=0;i<base.length;i++) if(vowels.includes(base[i])) pos.push(i);
  return pos;
}

function isDisyllabicApprox(base){
  // Approx: count vowel letters (treat ει/αι/οι/υι/αυ/ευ/ου as 1 by collapsing common digraphs).
  let s = base;
  s = s.replace(/(αι|ει|οι|υι|αυ|ευ|ου|ηυ|Αι|Ει|Οι|Υι|Αυ|Ευ|Ου|Ηυ)/g,'#');
  const count = (s.match(/[αεηιουωΑΕΗΙΟΥΩ#]/g) || []).length;
  return count === 2;
}

function endsWithBetaEtaSigma(base){
  return /βης$/i.test(base);
}
function endsWithGammaEtaSigma(base){
  return /γης$/i.test(base);
}

function penultVowelIndex(base){
  const vpos = vowelPositions(base);
  if(vpos.length < 2) return -1;
  return vpos[vpos.length-2];
}

function applyAccentOnVowel(word, vowelIndex, accentType){
  // Apply combining mark after the vowel letter at vowelIndex.
  // Remove any existing accent marks first.
  let s = nfd(word);
  // Build mapping from base indices to NFD indices.
  const base = stripDiacritics(word);
  // Find NFD index corresponding to the vowelIndex-th base character.
  let baseCount = -1;
  let insertAt = -1;
  for(let i=0;i<s.length;i++){
    const ch = s[i];
    // skip combining marks
    if(/[\u0300-\u036f]/.test(ch)) continue;
    baseCount++;
    if(baseCount === vowelIndex){
      insertAt = i+1; // after the base letter
      break;
    }
  }
  // Strip existing accent marks (acute/grave/circumflex) but keep breathings/diaeresis/iota-sub.
  s = s.replace(/[\u0300\u0301\u0342]/g,'');
  if(insertAt === -1) return nfc(s);
  const mark = combining[accentType] || '';
  s = s.slice(0, insertAt) + mark + s.slice(insertAt);
  return nfc(s);
}

function makeBarytone(word){
  const base = stripDiacritics(word);
  const pv = penultVowelIndex(base);
  if(pv === -1) return word;
  return applyAccentOnVowel(base, pv, 'acute');
}

function makeCircumflex(word){
  const base = stripDiacritics(word);
  const pv = penultVowelIndex(base);
  if(pv === -1) return word;
  return applyAccentOnVowel(base, pv, 'circumflex');
}

function analyze(){
  const raw = inp.value.trim();
  if(!raw){
    renderEmpty();
    return;
  }
  if(!hasGreek(raw)){
    renderWhy(['No Greek letters detected. Try Greek input (e.g. Λαβης, Μεγης).']);
    outMain.textContent = '—';
    outAlt.textContent = '';
    ethOut.value = '';
    return;
  }

  const base = stripDiacritics(raw);
  const disyll = isDisyllabicApprox(base);
  const isBhs = endsWithBetaEtaSigma(base);
  const isGhs = endsWithGammaEtaSigma(base);

  let guess = null; // 'bary' | 'circ'
  const why = [];

  if(!(isBhs || isGhs)){
    why.push('Ending not recognized: this toy only targets disyllables in -βης or -γης (as in the passage).');
  } else {
    why.push(`Ending detected: ${isBhs ? '-βης' : '-γης'}.`);
  }

  if(disyll) why.push('Looks disyllabic (approx. vowel-count heuristic).');
  else why.push('May not be disyllabic (heuristic). The rule in the passage is for disyllables; results may be off.');

  // Special-cased example from the passage
  if(base.toLowerCase() === 'κιβης'){
    guess = 'circ';
    why.push('Special case: κιβῆς is said to be circumflexed (explained as from κιβέας / contraction).');
  }

  if(!guess){
    if(isBhs){
      guess = 'bary';
      why.push('Rule-of-thumb: -βης disyllables with a vowel in the penult are barytone (penult accent).');
    } else if(isGhs){
      guess = 'bary';
      why.push('Rule-of-thumb: -γης disyllables are barytone unless compound/denominative/contraction suggests circumflex.');
      why.push('Toy limitation: it cannot reliably detect compounds/denominatives, so it defaults to barytone.');
    }
  }

  const bary = makeBarytone(base);
  const circ = makeCircumflex(base);

  if(guess === 'bary'){
    outMain.textContent = bary;
    outAlt.textContent = `Alternative (circumflex): ${circ}`;
  } else {
    outMain.textContent = circ;
    outAlt.textContent = `Alternative (barytone): ${bary}`;
  }

  renderWhy(why);
  ethOut.value = proposeEthnicPlural(base);
}

function proposeEthnicPlural(base){
  // playful: Xβης -> Xβαι
  if(!endsWithBetaEtaSigma(base)) return '';
  const stem = base.slice(0, -3); // remove βης
  let eth = stem + 'βαι';

  // Try to copy accent to first vowel (like Βύβης -> Βύβαι).
  const vpos = vowelPositions(eth);
  if(vpos.length){
    eth = applyAccentOnVowel(eth, vpos[0], 'acute');
  }
  return eth;
}

function renderWhy(items){
  outWhy.innerHTML = '';
  for(const it of items){
    const li = document.createElement('li');
    li.textContent = it;
    outWhy.appendChild(li);
  }
}

function renderEmpty(){
  outMain.textContent = '—';
  outAlt.textContent = '—';
  renderWhy(['Type a word above and click Analyze.']);
  ethOut.value = '';
}

function copyText(t){
  if(!t) return;
  // Offline-friendly clipboard attempt
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(t).catch(()=>fallbackCopy(t));
  } else fallbackCopy(t);
}

function fallbackCopy(t){
  const ta = document.createElement('textarea');
  ta.value = t;
  ta.style.position='fixed';
  ta.style.left='-9999px';
  document.body.appendChild(ta);
  ta.select();
  try{ document.execCommand('copy'); } catch(e){}
  document.body.removeChild(ta);
}

$('#btnAnalyze').addEventListener('click', analyze);
$('#btnRandom').addEventListener('click', ()=>{
  inp.value = examples[Math.floor(Math.random()*examples.length)];
  analyze();
});

$('#btnBary').addEventListener('click', ()=>{
  const base = stripDiacritics(inp.value.trim());
  if(!base) return;
  outMain.textContent = makeBarytone(base);
  outAlt.textContent = `Alternative (circumflex): ${makeCircumflex(base)}`;
});

$('#btnCirc').addEventListener('click', ()=>{
  const base = stripDiacritics(inp.value.trim());
  if(!base) return;
  outMain.textContent = makeCircumflex(base);
  outAlt.textContent = `Alternative (barytone): ${makeBarytone(base)}`;
});

$('#btnStrip').addEventListener('click', ()=>{
  const base = stripDiacritics(inp.value.trim());
  if(!base) return;
  outMain.textContent = base;
  outAlt.textContent = 'Accents stripped.';
});

$('#btnCopy').addEventListener('click', ()=>copyText(outMain.textContent.replace(/^—$/,'')));
$('#btnCopyEth').addEventListener('click', ()=>copyText(ethOut.value));

inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') analyze(); });

renderEmpty();

