(() => {
  const $ = (sel) => document.querySelector(sel);
  const wordEl = $('#word');
  const nomOut = $('#nomOut');
  const genOut = $('#genOut');
  const accOut = $('#accOut');
  const nomMeta = $('#nomMeta');
  const genMeta = $('#genMeta');
  const accMeta = $('#accMeta');
  const note = $('#note');
  const keepAccentEl = $('#keepAccent');
  const markSyllEl = $('#markSyll');

  const samples = [
    'μύκης','Μέγης','Γύγης','Δράγγης','Μόργης','Βρίγης','Βρύγης','Μίσγης','Λίργης','Ἄργης','Μογῆς','Δρογῆς','Πύδης'
  ];

  const combining = /[\u0300-\u036f]/g;
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

  function nfd(s){return s.normalize('NFD');}
  function nfc(s){return s.normalize('NFC');}

  function stripCombining(s){return nfd(s).replace(combining,'');}

  function hasAccentOnChar(nfdChar){
    // acute U+0301, grave U+0300, circumflex U+0342
    return /[\u0300\u0301\u0342]/.test(nfdChar);
  }

  function findAccentVowelIndex(word){
    const w = nfd(word);
    // scan grapheme-ish: base letter + combining marks
    let units = [];
    for (let i=0;i<w.length;i++){
      const ch = w[i];
      if (combining.test(ch)) {
        units[units.length-1] += ch;
      } else {
        units.push(ch);
      }
    }
    for (let i=0;i<units.length;i++){
      const base = units[i].replace(combining,'');
      if (vowels.has(base) && hasAccentOnChar(units[i])) return i;
    }
    return -1;
  }

  function addAcuteToVowelUnit(unit){
    // add acute combining mark after existing combining marks (order not perfect, fine for toy)
    if (/[\u0301]/.test(unit)) return unit;
    return unit + '\u0301';
  }

  function ensureSomeAccent(word){
    if (findAccentVowelIndex(word) !== -1) return word;
    // naive: accent the penult vowel unit if possible, else first vowel
    const w = nfd(word);
    let units = [];
    for (let i=0;i<w.length;i++){
      const ch = w[i];
      if (combining.test(ch)) units[units.length-1] += ch;
      else units.push(ch);
    }
    const vowelIdx = [];
    for (let i=0;i<units.length;i++){
      const base = units[i].replace(combining,'');
      if (vowels.has(base)) vowelIdx.push(i);
    }
    if (!vowelIdx.length) return word;
    const target = vowelIdx.length >= 2 ? vowelIdx[vowelIdx.length-2] : vowelIdx[0];
    units[target] = addAcuteToVowelUnit(units[target]);
    return nfc(units.join(''));
  }

  function moveAccentToIndex(word, targetUnitIndex){
    const w = nfd(word);
    let units = [];
    for (let i=0;i<w.length;i++){
      const ch = w[i];
      if (combining.test(ch)) units[units.length-1] += ch;
      else units.push(ch);
    }
    // remove accent marks from all units
    units = units.map(u => u.replace(/[\u0300\u0301\u0342]/g,''));
    if (targetUnitIndex >= 0 && targetUnitIndex < units.length) {
      const base = units[targetUnitIndex].replace(combining,'');
      if (vowels.has(base)) units[targetUnitIndex] = addAcuteToVowelUnit(units[targetUnitIndex]);
    }
    return nfc(units.join(''));
  }

  function roughSyllableCount(word){
    // very rough: count vowel letters in stripped string
    const s = stripCombining(word);
    let c = 0;
    for (const ch of s) if (vowels.has(ch)) c++;
    return c;
  }

  function replaceEnding(base, fromEndings, toEnding){
    for (const e of fromEndings){
      if (base.endsWith(e)) return base.slice(0, base.length - e.length) + toEnding;
    }
    return base + toEnding;
  }

  function decline(nom, pattern){
    // Work on de-accented base for morphology, then reapply accent.
    const nomAcc = ensureSomeAccent(nom.trim());
    const accentIdx = findAccentVowelIndex(nomAcc);

    const nomBare = stripCombining(nomAcc);

    // crude stem guess for -ης / -γης / -δης etc.
    // We'll treat anything ending in -ης as our playground.
    let genBare, accBare;
    if (pattern === 'iso') {
      // μύκης -> μύκεως, μύκην
      genBare = replaceEnding(nomBare, ['ης'], 'εως');
      accBare = replaceEnding(nomBare, ['ης'], 'ην');
    } else {
      // μύκης -> μύκητος, μύκητα
      genBare = replaceEnding(nomBare, ['ης'], 'ητος');
      accBare = replaceEnding(nomBare, ['ης'], 'ητα');
    }

    // Reapply accent: keep same unit index if requested.
    let nomOutW = nomAcc;
    let genOutW = genBare;
    let accOutW = accBare;

    if (keepAccentEl.checked) {
      // Map accent index from nominative units to new word units by counting vowel-units from start.
      // We'll approximate by placing accent on the same vowel-number (not exact syllable).
      const nomStripped = stripCombining(nomAcc);
      const targetVowelNumber = (() => {
        // count vowels up to and including the accented unit in the original NFD units
        const w = nfd(nomAcc);
        let units = [];
        for (let i=0;i<w.length;i++){
          const ch = w[i];
          if (combining.test(ch)) units[units.length-1] += ch;
          else units.push(ch);
        }
        let vNum = -1;
        for (let i=0;i<units.length;i++){
          const base = units[i].replace(combining,'');
          if (vowels.has(base)) vNum++;
          if (i === accentIdx) return vNum;
        }
        return 0;
      })();

      function accentByVowelNumber(bare){
        const w = nfd(bare);
        let units = [];
        for (let i=0;i<w.length;i++){
          const ch = w[i];
          if (combining.test(ch)) units[units.length-1] += ch;
          else units.push(ch);
        }
        let vNum = -1;
        let targetUnit = -1;
        for (let i=0;i<units.length;i++){
          const base = units[i].replace(combining,'');
          if (vowels.has(base)) {
            vNum++;
            if (vNum === targetVowelNumber) { targetUnit = i; break; }
          }
        }
        if (targetUnit === -1) {
          // fallback: penult vowel
          return ensureSomeAccent(bare);
        }
        return moveAccentToIndex(bare, targetUnit);
      }

      genOutW = accentByVowelNumber(genBare);
      accOutW = accentByVowelNumber(accBare);
    } else {
      genOutW = ensureSomeAccent(genBare);
      accOutW = ensureSomeAccent(accBare);
    }

    return { nom: nomOutW, gen: genOutW, acc: accOutW };
  }

  function setMeta(el, word){
    if (!markSyllEl.checked) { el.textContent = ''; return; }
    const syl = roughSyllableCount(word);
    el.innerHTML = `~${syl} vowel(s) <span class="pill">rough</span>`;
  }

  function render(){
    const nom = wordEl.value;
    const pat = document.querySelector('input[name="pat"]:checked').value;

    const forms = decline(nom, pat);
    nomOut.textContent = forms.nom || '—';
    genOut.textContent = forms.gen || '—';
    accOut.textContent = forms.acc || '—';

    setMeta(nomMeta, forms.nom);
    setMeta(genMeta, forms.gen);
    setMeta(accMeta, forms.acc);

    const other = pat === 'iso' ? 'peri' : 'iso';
    const otherForms = decline(nom, other);

    const sameAccent = (findAccentVowelIndex(forms.gen) === findAccentVowelIndex(otherForms.gen)) &&
                       (findAccentVowelIndex(forms.acc) === findAccentVowelIndex(otherForms.acc));

    const patLabel = pat === 'iso' ? 'ἰσοσυλλάβως' : 'περιττοσυλλάβως';
    const otherLabel = other === 'iso' ? 'ἰσοσυλλάβως' : 'περιττοσυλλάβως';

    note.innerHTML = `
      <b>Now:</b> <span class="greek">${patLabel}</span>. 
      <b>Compare:</b> switch to <span class="greek">${otherLabel}</span> → Gen <span class="greek">${otherForms.gen}</span>, Acc <span class="greek">${otherForms.acc}</span>.
      <br>
      Accent comparison (toy): ${sameAccent ? '<span class="good"><b>same place</b></span>' : '<span class="bad"><b>different</b></span>'}.
    `;
  }

  function setPattern(p){
    const r = document.querySelector(`input[name="pat"][value="${p}"]`);
    if (r) r.checked = true;
  }

  $('#go').addEventListener('click', render);
  $('#swap').addEventListener('click', () => {
    const pat = document.querySelector('input[name="pat"]:checked').value;
    setPattern(pat === 'iso' ? 'peri' : 'iso');
    render();
  });
  $('#random').addEventListener('click', () => {
    const w = samples[Math.floor(Math.random()*samples.length)];
    wordEl.value = w;
    render();
  });
  $('#reset').addEventListener('click', () => {
    wordEl.value = 'μύκης';
    setPattern('iso');
    keepAccentEl.checked = true;
    markSyllEl.checked = true;
    render();
  });

  document.querySelectorAll('input[name="pat"]').forEach(r => r.addEventListener('change', render));
  keepAccentEl.addEventListener('change', render);
  markSyllEl.addEventListener('change', render);
  wordEl.addEventListener('keydown', (e) => { if (e.key === 'Enter') render(); });

  render();
})();

