const $ = (sel) => document.querySelector(sel);

const examples = [
  "Ποδης",
  "Ροδης",
  "Ανθης",
  "Σκυθης",
  "Σεϋθης",
  "ψευδης",
  "φραδης",
  "Κελτης",
  "Κωφης",
  "Βυζης",
  "Μενδης",
  "Υδης"
];

// --- Greek helpers (toy-level, not exhaustive) ---
const combining = /[\u0300\u0301\u0302\u0342\u0345\u0313\u0314\u0308\u0344\u0343\u0340]/g; // accents/breathing/diaeresis/iota-sub etc.

function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripDiacritics(s){
  // Keep Greek letters, remove combining marks.
  return nfc(nfd(s).replace(combining, ''));
}

function lastWord(text){
  const t = text.trim();
  if(!t) return "";
  // Split on whitespace; keep last token; strip trailing punctuation.
  const parts = t.split(/\s+/);
  let w = parts[parts.length-1];
  w = w.replace(/[\]\[(){}<>«»“”"'·.,;:!?—–…]+$/g, '');
  return w;
}

function endsWithEtaSigma(word){
  const bare = stripDiacritics(word);
  return /ης$/i.test(bare);
}

function roughPenultVowel(word){
  // Very rough: find last two vowels in the word (after stripping diacritics).
  const bare = stripDiacritics(word);
  const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);
  let found = [];
  for(let i=bare.length-1;i>=0;i--){
    const ch = bare[i];
    if(vowels.has(ch)) found.push(ch);
    if(found.length>=2) break;
  }
  // found[0] = ultima vowel, found[1] = penult vowel
  return found.length>=2 ? found[1] : (found.length===1 ? "(only one vowel)" : "(no vowel?)");
}

function applyUltimaAccentToEtaSigma(word, kind){
  // kind: 'acute' | 'grave' | 'circ'
  // We rewrite the ending -ης as -ής / -ὴς / -ῆς.
  // This is a simplification: ignores breathing on eta, enclitics, etc.
  const bare = stripDiacritics(word);
  const m = bare.match(/^(.*?)(ης)$/i);
  if(!m) return word;
  const stem = m[1];
  const eta = (m[2][0] === 'Η') ? 'Η' : 'η';
  const sigma = (m[2][1] === 'Σ') ? 'Σ' : 'ς';

  let accentedEta = eta;
  if(eta === 'η'){
    if(kind==='acute') accentedEta = 'ή';
    if(kind==='grave') accentedEta = 'ὴ';
    if(kind==='circ')  accentedEta = 'ῆ';
  } else {
    // Capital eta with tonos is Ή; grave/circ not standard in Unicode for capitals; use Ή for acute, else Η.
    if(kind==='acute') accentedEta = 'Ή';
    else accentedEta = 'Η';
  }
  return stem + accentedEta + sigma;
}

function herodianGuess(word){
  // Passage hook: Podēs/Rhodēs circumflex because 'ο' in penult.
  // Toy heuristic: if penult vowel is ο/ω (or Ο/Ω), suggest circumflex; else suggest grave.
  if(!endsWithEtaSigma(word)){
    return {result: word, note: "This toy’s Herodian-ish rule only triggers for words ending in -ης."};
  }
  const pv = roughPenultVowel(word);
  const pvBare = typeof pv === 'string' ? pv : '';
  const isO = /[οωΟΩ]/.test(pvBare);
  const kind = isO ? 'circ' : 'grave';
  const res = applyUltimaAccentToEtaSigma(word, kind);
  const note = isO
    ? "Heuristic: penult looks like ο/ω → suggest circumflex on -ης (cf. Ποδῆς, Ῥοδῆς in the passage)."
    : "Heuristic: penult not ο/ω → suggest grave on -ης (cf. ‘βαρύνονται’ examples like Ἄνθης).";
  return {result: res, note};
}

function detectEnding(word){
  const bare = stripDiacritics(word);
  if(/ης$/i.test(bare)) return "-ης";
  if(/ος$/i.test(bare)) return "-ος";
  if(/ον$/i.test(bare)) return "-ον";
  if(/αι$/i.test(bare)) return "-αι";
  if(/οι$/i.test(bare)) return "-οι";
  return "(other)";
}

function transform(){
  const input = $('#in').value;
  const w = lastWord(input);
  $('#last').textContent = w || '—';
  $('#ending').textContent = w ? detectEnding(w) : '—';
  $('#penult').textContent = w ? roughPenultVowel(w) : '—';

  if(!w){
    $('#res').textContent = '—';
    $('#note').textContent = 'Type something above.';
    return;
  }

  const mode = $('#mode').value;
  let out = w;
  let note = '';

  if(mode === 'strip'){
    out = stripDiacritics(w);
    note = 'Removed combining diacritics (toy “unaccenting”).';
  } else if(mode === 'herodian'){
    const g = herodianGuess(w);
    out = g.result;
    note = g.note;
  } else if(mode === 'acute'){
    out = applyUltimaAccentToEtaSigma(w, 'acute');
    note = endsWithEtaSigma(w) ? 'Forced acute on the ultima of -ης.' : 'Not an -ης word; no change.';
  } else if(mode === 'grave'){
    out = applyUltimaAccentToEtaSigma(w, 'grave');
    note = endsWithEtaSigma(w) ? 'Forced grave on the ultima of -ης.' : 'Not an -ης word; no change.';
  } else if(mode === 'circ'){
    out = applyUltimaAccentToEtaSigma(w, 'circ');
    note = endsWithEtaSigma(w) ? 'Forced circumflex on the ultima of -ης.' : 'Not an -ης word; no change.';
  }

  // Rebuild full input with last word replaced (nice UX)
  const trimmed = input.trim();
  let fullOut = out;
  if(trimmed){
    const parts = trimmed.split(/\s+/);
    parts[parts.length-1] = out;
    fullOut = parts.join(' ');
  }

  $('#res').textContent = fullOut;
  $('#note').textContent = note;
}

function buildChips(){
  const box = $('#chips');
  box.innerHTML = '';
  examples.forEach(ex => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip';
    b.textContent = ex;
    b.addEventListener('click', () => {
      $('#in').value = ex;
      transform();
    });
    box.appendChild(b);
  });
}

$('#go').addEventListener('click', transform);
$('#in').addEventListener('keydown', (e) => {
  if(e.key === 'Enter') transform();
});
$('#mode').addEventListener('change', transform);

buildChips();
transform();

