const $ = (sel, el=document) => el.querySelector(sel);
const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

// --- Greek helpers (very lightweight) ---
const COMBINING = /[\u0300-\u036f]/g;

function nfd(s){ return (s||"").normalize('NFD'); }
function nfc(s){ return (s||"").normalize('NFC'); }

function stripDiacritics(s){
  return nfc(nfd(s).replace(COMBINING, ''));
}

function toMonotonic(s){
  // crude: remove breathings/circumflex/grave/diaeresis, keep acute if present.
  // We keep tonos (U+0301) only.
  const keep = new Set(['\u0301']);
  const out = nfd(s).split('').filter(ch => {
    const code = ch.codePointAt(0);
    if(code >= 0x0300 && code <= 0x036F) return keep.has(ch);
    return true;
  }).join('');
  return nfc(out);
}

function hasAccent(s){
  const d = nfd(s);
  return d.includes('\u0301') || d.includes('\u0342') || d.includes('\u0300');
}

function lastLetterBase(s){
  const t = stripDiacritics(s).trim();
  if(!t) return '';
  return t[t.length-1];
}

function endsWithBase(s, ending){
  return stripDiacritics(s).trim().toLowerCase().endsWith(ending);
}

function letterBeforeEtaInEnding(s){
  // For words ending in -ης, return the base letter immediately before η.
  const t = stripDiacritics(s).trim();
  const low = t.toLowerCase();
  if(!low.endsWith('ης')) return '';
  if(low.length < 3) return '';
  return low[low.length-3];
}

function approxSyllables(s){
  // very rough: count vowel groups in base letters
  const t = stripDiacritics(s).toLowerCase();
  const vowels = 'αεηιουω';
  let count = 0;
  let prevV = false;
  for(const ch of t){
    const isV = vowels.includes(ch);
    if(isV && !prevV) count++;
    prevV = isV;
  }
  return count;
}

function displayForm(s, mode){
  if(mode==='strip') return stripDiacritics(s);
  if(mode==='monotonic') return toMonotonic(s);
  return s;
}

// --- Main analyzer ---
function analyze(){
  const raw = $('#w').value.trim();
  const mode = $('#mode').value;
  const out = $('#out');
  if(!raw){
    out.innerHTML = `<span class="k">Type a Greek word above.</span>`;
    return;
  }

  const shown = displayForm(raw, mode);
  const base = stripDiacritics(raw);
  const syll = approxSyllables(raw);
  const isHs = endsWithBase(raw, 'ης');
  const pre = letterBeforeEtaInEnding(raw);
  const preHit = (pre === 'σ' || pre === 'ξ');
  const accented = hasAccent(raw);

  let verdict = '';
  let why = [];

  if(!isHs){
    verdict = `<span class="warn">Not an -ης ending (in base letters).</span>`;
    why.push(`Base form: <span class="mono">${escapeHtml(base)}</span>`);
  } else {
    why.push(`Looks like <b>-ης</b> (base: <span class="mono">${escapeHtml(base)}</span>).`);
    if(syll) why.push(`Rough syllable count: <b>${syll}</b> (toy).`);

    if(preHit){
      verdict = `<span class="good">Heuristic: likely <b>barytone</b></span>`;
      why.push(`Letter before η is <b>${pre}</b> → matches Herodian’s σ/ξ cue (Ξέρξης, Χρύσης).`);
    } else {
      verdict = `<span class="warn">Heuristic: unclear</span>`;
      why.push(`Letter before η is <b>${pre || '—'}</b> → not the σ/ξ cue.`);
    }

    if(accented){
      why.push(`You typed an accent mark; the toy won’t override it.`);
    } else {
      why.push(`No accent detected in your input; try adding one (e.g. Ξέρξης vs Ξερξης).`);
    }
  }

  // playful “accent suggestion” (not real accentuation)
  let suggest = '';
  if(isHs && !accented){
    if(preHit){
      suggest = `Toy suggestion: write it as <b>${escapeHtml(addToyBarytoneAccent(raw))}</b> (accent earlier).`;
    } else {
      suggest = `Toy suggestion: try both <b>${escapeHtml(addToyOxytoneAccent(raw))}</b> and a barytone spelling; check a lexicon.`;
    }
  }

  out.innerHTML = `
    <div><b>Input:</b> <span class="mono">${escapeHtml(shown)}</span></div>
    <div style="margin-top:6px"><b>Result:</b> ${verdict}</div>
    <hr/>
    <div class="k">${why.join('<br/>')}</div>
    ${suggest ? `<hr/><div>${suggest}</div>` : ''}
  `;
}

// --- Toy accent placement ---
function addToyOxytoneAccent(s){
  // Put an acute on the eta of final -ης if possible.
  const t = stripDiacritics(s);
  const low = t.toLowerCase();
  if(!low.endsWith('ης')) return s;
  // Replace last 'η' with 'ή' (monotonic acute) as a simple visual.
  const idx = t.length - 2;
  const ch = t[idx];
  const repl = (ch === 'η') ? 'ή' : ch;
  return t.slice(0, idx) + repl + t.slice(idx+1);
}

function addToyBarytoneAccent(s){
  // Put an acute on the penult vowel group (very rough).
  const t = stripDiacritics(s);
  const vowels = 'αεηιουω';
  // find vowel-group starts
  let starts = [];
  let prevV = false;
  for(let i=0;i<t.length;i++){
    const isV = vowels.includes(t[i].toLowerCase());
    if(isV && !prevV) starts.push(i);
    prevV = isV;
  }
  if(starts.length < 2) return t;
  const target = starts[starts.length-2];
  const map = { 'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
                'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ' };
  const ch = t[target];
  const repl = map[ch] || ch;
  return t.slice(0,target) + repl + t.slice(target+1);
}

// --- Contraction toy ---
function contractToy(base, level){
  let s = stripDiacritics(base);
  if(level === 0) return s;
  // level 1: show diaeresis on ι after η (ηϊ) if pattern ηι occurs
  if(level === 1){
    // replace ηι with ηϊ (NFC)
    return nfc(s.replace(/ηι/gi, m => m[0] + 'ϊ'));
  }
  // level 2: contract ηι -> ῃ (or just η if you prefer). We'll use ῃ for fun.
  // Use lowercase ῃ and uppercase ῌ? We'll keep simple: ηι -> ῃ, ΗΙ -> ῌ (rare). 
  s = s.replace(/ηι/g, 'ῃ').replace(/ΗΙ/g, 'ῌ').replace(/Ηι/g, 'ῌ').replace(/ηΙ/g, 'ῃ');
  // also common spelling: ληϊστής -> λῃστής (drop iota)
  return s;
}

function updateContraction(){
  const base = $('#cIn').value;
  const level = Number($('#cSlide').value);
  const label = ['0: no contraction','1: show hiatus (ηϊ)','2: contract (ηι→ῃ)'][level] || String(level);
  $('#cLabel').textContent = label;
  const out = contractToy(base, level);
  $('#cOut').innerHTML = `<div><b>Output:</b> <span class="mono">${escapeHtml(out)}</span></div>`;
}

// --- Genitive toy ---
function suggestGenitives(){
  const raw = $('#w').value.trim();
  const out = $('#genOut');
  if(!raw){
    out.innerHTML = `<span class="k">Type a word in the main box first.</span>`;
    return;
  }
  const base = stripDiacritics(raw);
  const low = base.toLowerCase();
  if(!low.endsWith('ης')){
    out.innerHTML = `<span class="warn">This toy only suggests genitives for base -ης.</span>`;
    return;
  }
  const stem = base.slice(0, -2);
  // toy options: -ου (common), -ους (Herodian mentions), -τος (Herodian mentions)
  const opts = [
    stem + 'ου',
    stem + 'ους',
    stem + 'τος'
  ];
  out.innerHTML = `
    <div><b>Base:</b> <span class="mono">${escapeHtml(base)}</span></div>
    <div style="margin-top:6px"><b>Toy genitives:</b></div>
    <ul class="k" style="margin:6px 0 0 18px">
      ${opts.map(x=>`<li><span class="mono">${escapeHtml(x)}</span></li>`).join('')}
    </ul>
    <div class="note">Real genitives depend on declension class and tradition (e.g. Κουρής → Κουρῆτος in the passage).</div>
  `;
}

function loadExampleChips(){
  const examples = ['Ξέρξης','Χρύσης','Μάσης','Πέρσης','Βούσης','Μάρσης','πένης','πλάνης','Φάνης','Δάρης','Χάρης','Κάρης','Κουρής'];
  const box = $('#chips');
  box.innerHTML = examples.map(w => `<button class="chip" data-w="${escapeHtmlAttr(w)}">${escapeHtml(w)}</button>`).join('');
}

// --- Utilities ---
function escapeHtml(s){
  return (s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
function escapeHtmlAttr(s){
  return escapeHtml(s).replace(/`/g,'&#96;');
}

// --- Wire up ---
$('#go').addEventListener('click', analyze);
$('#w').addEventListener('keydown', (e)=>{ if(e.key==='Enter') analyze(); });
$('#mode').addEventListener('change', analyze);

$('#cSlide').addEventListener('input', updateContraction);
$('#cIn').addEventListener('input', updateContraction);

$('#genBtn').addEventListener('click', suggestGenitives);
$('#fillExamples').addEventListener('click', ()=>{ loadExampleChips(); });

$$('.chip').forEach(btn => {
  btn.addEventListener('click', ()=>{
    $('#w').value = btn.dataset.w;
    analyze();
  });
});

document.addEventListener('click', (e)=>{
  const t = e.target;
  if(t && t.classList && t.classList.contains('chip') && t.dataset.w){
    // chips in dynamic area too
    $('#w').value = t.dataset.w;
    analyze();
