passages.gadget_js:
const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => Array.from(document.querySelectorAll(sel));

// --- Greek helpers (toy-level) ---
const combining = /[\u0300-\u036f]/g; // includes tonos/oxia etc.

function nfd(s){ return (s||"").normalize('NFD'); }
function stripDiacritics(s){ return nfd(s).replace(combining, '').normalize('NFC'); }

const VOWELS = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

function lastWord(phrase){
  const t = (phrase||"").trim();
  if(!t) return "";
  // split on spaces and common punctuation
  const parts = t.split(/[\s·,;:.!?«»“”"'()\[\]{}]+/).filter(Boolean);
  return parts.length ? parts[parts.length-1] : t;
}

function endsWithEtaSigma(word){
  const w = stripDiacritics(word);
  return /ης$/i.test(w);
}

function roughSyllables(word){
  // Count vowel groups in stripped form.
  const w = stripDiacritics(word);
  let count = 0;
  let inV = false;
  for(const ch of w){
    const isV = VOWELS.has(ch);
    if(isV && !inV){ count++; inV = true; }
    if(!isV) inV = false;
  }
  return Math.max(1, count);
}

function hasClusterBeforeEta(word){
  // Look at stripped last word; find final ης and inspect preceding letters.
  const w = stripDiacritics(word);
  const m = w.match(/(.*)ης$/i);
  if(!m) return false;
  const stem = m[1];
  if(stem.length < 2) return false;
  const a = stem[stem.length-1];
  const b = stem[stem.length-2];
  const isCon = (c) => c && !VOWELS.has(c) && /[\p{L}]/u.test(c);
  // cluster if last two before η are consonants (e.g. γν, ρν, σθ, μβ)
  return isCon(a) && isCon(b);
}

function looksAdjectivalOxy(word){
  // Very rough: common adjectival patterns mentioned (γυμνής, χερνής, ἀβλής, προβλής, ἀδμής, ἀκμής)
  const w = stripDiacritics(lastWord(word)).toLowerCase();
  return /(ν|ρν|βλ|δμ|κμ)ης$/.test(w) || /(βλης|δμης|κμης|νης)$/.test(w);
}

function guessAccentType(word){
  const lw = lastWord(word);
  if(!endsWithEtaSigma(lw)) return {type:'n/a', why:'Not ending in -ης (toy focuses on -ης).'};

  const syl = roughSyllables(lw);
  const cluster = hasClusterBeforeEta(lw);
  const adj = looksAdjectivalOxy(lw);

  // Heuristic inspired by passage:
  // - disyllabic -ης with cluster before η => barytone
  // - adjectival -ής list => oxytone
  if(adj) return {type:'oxytone', why:'Looks like an adjectival -ής pattern (toy list).'};
  if(syl === 2 && cluster) return {type:'barytone', why:'Disyllabic -ης with consonant cluster before η (Herodian-style list).'};
  if(syl === 2) return {type:'barytone', why:'Disyllabic -ης often barytone in this toy.'};
  return {type:'barytone', why:'Defaulting to barytone for -ης in this toy.'};
}

function applyToyAccent(word, target /* 'penult'|'ultima' */, mark /* 'acute'|'circ' */){
  // Place combining acute/circumflex on the vowel of the target syllable.
  // This is NOT full Greek accentuation; it just marks a vowel in the chosen syllable.
  const lw = lastWord(word);
  const prefix = word.slice(0, word.lastIndexOf(lw));

  const base = stripDiacritics(lw);
  const decomposed = nfd(base);

  // Find syllable nuclei positions (indices in decomposed string) as first vowel of each vowel group.
  const nuclei = [];
  let inV = false;
  for(let i=0;i<decomposed.length;i++){
    const ch = decomposed[i];
    const isV = VOWELS.has(ch);
    if(isV && !inV){ nuclei.push(i); inV = true; }
    if(!isV) inV = false;
  }
  if(!nuclei.length) return word;

  let idx;
  if(target === 'ultima') idx = nuclei[nuclei.length-1];
  else idx = nuclei[Math.max(0, nuclei.length-2)];

  const accent = (mark === 'circ') ? '\u0342' : '\u0301'; // perispomeni / oxia

  // Insert accent after the vowel at idx, but avoid double-accenting if already present.
  let out = decomposed;
  // Remove any existing combining marks first (already stripped), so safe.
  out = out.slice(0, idx+1) + accent + out.slice(idx+1);

  return (prefix + out.normalize('NFC')).trim();
}

function analyzeAndRender(){
  const input = $('#in').value;
  const lw = lastWord(input);

  const ending = endsWithEtaSigma(lw) ? '-ης' : '—';
  $('#ending').textContent = ending;

  const syl = lw ? roughSyllables(lw) : 0;
  $('#syll').textContent = lw ? String(syl) : '—';

  const cluster = lw && endsWithEtaSigma(lw) ? (hasClusterBeforeEta(lw) ? 'yes' : 'no') : '—';
  $('#cluster').textContent = cluster;

  const mode = $('#mode').value;
  const mark = $('#accent').value;

  if(!input.trim()){
    $('#guess').textContent = '—';
    $('#toy').textContent = '—';
    return;
  }

  if(mode === 'strip'){
    $('#guess').textContent = 'strip accents';
    $('#toy').textContent = stripDiacritics(input);
    return;
  }

  let type, why;
  if(mode === 'forceBary') { type='barytone'; why='Forced barytone.'; }
  else if(mode === 'forceOxy') { type='oxytone'; why='Forced oxytone.'; }
  else {
    const g = guessAccentType(input);
    type = g.type;
    why = g.why;
  }

  $('#guess').textContent = `${type} — ${why}`;

  if(type === 'n/a'){
    $('#toy').textContent = stripDiacritics(input);
    return;
  }

  const target = (type === 'oxytone') ? 'ultima' : 'penult';
  $('#toy').textContent = applyToyAccent(input, target, mark);
}

// --- Mini-game ---
const GAME_WORDS = [
  'Μέσθλη̄ς','μάσθλη̄ς','Μάγνης','Πίγρης','Ὅπλης','Πέτρης','Μέμβλης','Βάμβλης','λάγνης','Πάσνης','Μάσνης','Τρίσπλης','Πάρνης','Ἴγνης','Φάγρης','Βάβρης','Ἔγκρης','Σάτρης','Γόνδρης','Νίγρης','Γύμνης',
  'γυμνής','χερνής','ἀβλής','προβλής','ἀδμής','ἀκμής'
];

let current = null;
let score = 0;
let locked = false;

function newRound(){
  current = GAME_WORDS[Math.floor(Math.random()*GAME_WORDS.length)];
  locked = false;
  $('#gWord').textContent = stripDiacritics(current);
  $('#gResult').textContent = 'Make a guess, then Reveal.';
  $('#gHint').textContent = 'Hint: look for -ης and clusters before η (or adjectival patterns).';
}

function reveal(){
  if(!current) return;
  const g = guessAccentType(current);
  const mark = $('#accent').value;
  let shown = stripDiacritics(current);
  if(g.type === 'barytone') shown = applyToyAccent(shown, 'penult', mark);
  if(g.type === 'oxytone') shown = applyToyAccent(shown, 'ultima', mark);
  $('#gResult').innerHTML = `Heuristic says: <strong>${g.type}</strong>. Toy-accented: <span class="mono">${escapeHtml(shown)}</span><br><span class="muted">${escapeHtml(g.why)}</span>`;
  locked = true;
}

function guess(type){
  if(!current || locked) return;
  const g = guessAccentType(current);
  const ok = (g.type === type);
  if(ok){ score++; $('#score').textContent = String(score); }
  $('#gResult').innerHTML = ok
    ? `<span class="good">Correct (by the toy heuristic).</span> Now hit Reveal.`
    : `<span class="bad">Not according to the toy heuristic.</span> Try Reveal.`;
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

// --- Wire up ---
$$('.chip').forEach(b=>b.addEventListener('click', ()=>{ $('#in').value = b.dataset.sample; analyzeAndRender(); }));
$('#in').addEventListener('input', analyzeAndRender);
$('#mode').addEventListener('change', analyzeAndRender);
$('#accent').addEventListener('change', ()=>{ analyzeAndRender(); if(current) reveal(); });

$('#new').addEventListener('click', newRound);
$('#reveal').addEventListener('click', reveal);
$('#bary').addEventListener('click', ()=>guess('barytone'));
$('#oxy').addEventListener('click', ()=>guess('oxytone'));

// init
newRound();
analyzeAndRender();

// small cosmetic: monospace class in game reveal
const styleMono = document.createElement('style');
styleMono.textContent = '.mono{font-family: var(--mono);}';
document.head.appendChild(styleMono);

