(() => {
  const $ = (sel, root=document) => root.querySelector(sel);
  const $$ = (sel, root=document) => Array.from(root.querySelectorAll(sel));

  const inp = $('#inp');
  const patternEl = $('#pattern');
  const notesEl = $('#notes');
  const accentOut = $('#accentOut');
  const accentExplain = $('#accentExplain');
  const moveOut = $('#moveOut');
  const moveExplain = $('#moveExplain');

  const examples = [
    'Ποδάργης',
    'Τεκτοσάγης',
    'Τεκτόσαγος',
    'Σαννίγης',
    'Πηλεΐδης',
    'Ἀτρεΐδης',
    'Θουκυδίδης',
    'Ἰλιάδης',
    'Βουτάδαι',
    'Οἰνειάδαι',
    'Πασαργάδαι',
    'ὑψιπέτης',
    'ὑψιπέτας'
  ];

  function stripPunct(s){
    return (s||'').trim().replace(/[··.,;:!?"“”«»()\[\]{}]/g,'');
  }

  // Rough vowel set (polytonic included)
  const VOWELS = new Set([
    'α','ά','ὰ','ᾶ','ἀ','ἁ','ἄ','ἂ','ἆ','ἅ','ἃ','ἇ','ᾳ','ᾴ','ᾲ','ᾷ','ᾀ','ᾁ','ᾄ','ᾂ','ᾆ','ᾅ','ᾃ','ᾇ',
    'ε','έ','ὲ','ἐ','ἑ','ἔ','ἒ','ἕ','ἓ',
    'η','ή','ὴ','ῆ','ἠ','ἡ','ἤ','ἢ','ἦ','ἥ','ἣ','ἧ','ῃ','ῄ','ῂ','ῇ','ᾐ','ᾑ','ᾔ','ᾒ','ᾖ','ᾕ','ᾓ','ᾗ',
    'ι','ί','ὶ','ῖ','ἰ','ἱ','ἴ','ἲ','ἶ','ἵ','ἳ','ἷ','ϊ','ΐ','ῒ','ῗ',
    'ο','ό','ὸ','ὀ','ὁ','ὄ','ὂ','ὅ','ὃ',
    'υ','ύ','ὺ','ῦ','ὐ','ὑ','ὔ','ὒ','ὖ','ὕ','ὓ','ὗ','ϋ','ΰ','ῢ','ῧ',
    'ω','ώ','ὼ','ῶ','ὠ','ὡ','ὤ','ὢ','ὦ','ὥ','ὣ','ὧ','ῳ','ῴ','ῲ','ῷ','ᾠ','ᾡ','ᾤ','ᾢ','ᾦ','ᾥ','ᾣ','ᾧ'
  ]);

  function isVowel(ch){ return VOWELS.has(ch.toLowerCase()); }

  function syllabifyRough(word){
    // Very rough: split before each vowel group.
    const w = word;
    const parts = [];
    let cur = '';
    let inV = false;
    for (let i=0;i<w.length;i++){
      const ch = w[i];
      const v = isVowel(ch);
      if (!cur){ cur = ch; inV = v; continue; }
      if (v && !inV){
        // start new syllable at vowel
        parts.push(cur);
        cur = ch;
        inV = true;
      } else {
        cur += ch;
        inV = inV || v;
      }
    }
    if (cur) parts.push(cur);
    return parts;
  }

  function removeDiacritics(s){
    return s.normalize('NFD').replace(/\p{M}+/gu,'').normalize('NFC');
  }

  function lastNLettersBase(word, n){
    const base = removeDiacritics(word);
    return base.slice(-n);
  }

  function detect(word){
    const w = stripPunct(word);
    const base = removeDiacritics(w);
    const lower = base.toLowerCase();

    const ends = (suf) => lower.endsWith(suf);

    if (ends('γης')) return {type:'-γης', rule:'Multisyllables in -γης are “βαρύνεται” (toy: accent the penult).'};
    if (ends('δης')) return {type:'-δης', rule:'Patronymics in -δης are “βαρύνεται” (toy: accent the penult). Often α/ι before δ.'};
    if (ends('αδαι') || ends('άδαι') || ends('αδαι'.normalize('NFC'))){
      return {type:'-άδαι', rule:'Plural demotics/ethnics in -άδαι (toy: keep acute on -ά-).'};
    }
    return {type:'(none)', rule:'No target ending detected. Try -γης, -δης, or plural -άδαι.'};
  }

  // Accent helpers: we will add an acute to the first vowel of the target syllable.
  const ACUTE_MAP = new Map([
    ['α','ά'],['ε','έ'],['η','ή'],['ι','ί'],['ο','ό'],['υ','ύ'],['ω','ώ'],
    ['Α','Ά'],['Ε','Έ'],['Η','Ή'],['Ι','Ί'],['Ο','Ό'],['Υ','Ύ'],['Ω','Ώ']
  ]);
  const GRAVE_MAP = new Map([
    ['ά','ὰ'],['έ','ὲ'],['ή','ὴ'],['ί','ὶ'],['ό','ὸ'],['ύ','ὺ'],['ώ','ὼ'],
    ['Ά','Ὰ'],['Έ','Ὲ'],['Ή','Ὴ'],['Ί','Ὶ'],['Ό','Ὸ'],['Ύ','Ὺ'],['Ώ','Ὼ']
  ]);
  const ACUTE_FROM_GRAVE = new Map([
    ['ὰ','ά'],['ὲ','έ'],['ὴ','ή'],['ὶ','ί'],['ὸ','ό'],['ὺ','ύ'],['ὼ','ώ'],
    ['Ὰ','Ά'],['Ὲ','Έ'],['Ὴ','Ή'],['Ὶ','Ί'],['Ὸ','Ό'],['Ὺ','Ύ'],['Ὼ','Ώ']
  ]);

  function addAcuteToFirstVowel(syl){
    for (let i=0;i<syl.length;i++){
      const ch = syl[i];
      const base = removeDiacritics(ch);
      if (ACUTE_MAP.has(base)){
        return syl.slice(0,i) + ACUTE_MAP.get(base) + syl.slice(i+1);
      }
    }
    return syl;
  }

  function suggestAccent(word, det){
    const w = stripPunct(word);
    if (!w) return {out:'—', explain:'—'};

    const syls = syllabifyRough(w);
    const n = syls.length;

    // Default: keep as-is.
    let targetIndex = null;
    let explain = '';

    if (det.type === '-γης' || det.type === '-δης'){
      if (n >= 2) targetIndex = n-2; // penult
      else targetIndex = 0;
      explain = `Toy rule: for ${det.type}, accent the penult ("βαρύνεται").`;
    } else if (det.type === '-άδαι'){
      // accent the syllable containing αδαι: usually penult in plural -άδαι, but we just accent the first syllable of the ending.
      targetIndex = Math.max(0, n-2);
      explain = 'Toy rule: for plural -άδαι, keep an acute on -ά- (often the penult).';
    } else {
      // If no pattern, accent penult as a generic practice.
      targetIndex = Math.max(0, n-2);
      explain = 'No specific rule detected; generic practice: accent the penult.';
    }

    // Remove existing combining marks to avoid double accents; keep breathing etc? We'll simplify: strip all marks then re-accent.
    const plainSyls = syls.map(s => removeDiacritics(s));
    plainSyls[targetIndex] = addAcuteToFirstVowel(plainSyls[targetIndex]);
    const out = plainSyls.join('');

    return {out, explain};
  }

  function toggleFinalAcuteGrave(word){
    // If last vowel has acute, turn to grave; if grave, to acute. Only checks precomposed acute/grave.
    const chars = Array.from(word);
    for (let i=chars.length-1;i>=0;i--){
      const ch = chars[i];
      if (GRAVE_MAP.has(ch)){
        chars[i] = GRAVE_MAP.get(ch); // acute->grave
        return chars.join('');
      }
      if (ACUTE_FROM_GRAVE.has(ch)){
        chars[i] = ACUTE_FROM_GRAVE.get(ch); // grave->acute
        return chars.join('');
      }
    }
    return word;
  }

  function move(word, kind){
    const w = stripPunct(word);
    if (!w) return {out:'—', explain:'Type something first.'};

    const base = removeDiacritics(w);
    const lower = base.toLowerCase();

    const replaceEnding = (from, to) => {
      if (!lower.endsWith(from)) return null;
      return base.slice(0, base.length-from.length) + to;
    };

    if (kind === 'etaToAlpha'){
      // Replace eta with alpha (first occurrence of η/ή/ῆ etc simplified)
      const out = w.replace(/[ηήὴῆ]/g, (m) => ({'η':'α','ή':'ά','ὴ':'ὰ','ῆ':'ᾶ'}[m]||'α'));
      return {out, explain:"Playful dialect move: η → α (as in ὑψιπέτης ~ ὑψιπέτας)."};
    }

    if (kind === 'toGHS'){
      // Like -ος -> -ης (very rough)
      let out = replaceEnding('ος','ης') || replaceEnding('ον','ης') || replaceEnding('ας','ης');
      if (!out) out = base + 'γης';
      return {out, explain:"Toy derivation: try making a -γης form (cf. Καππάδοκος → Καππαδόκης; Τεκτόσαγος → Τεκτοσάγης)."};
    }

    if (kind === 'toDHS'){
      // Make -δης; if ends -δαι -> -δης; if ends -ος -> -δης
      let out = replaceEnding('δαι','δης') || replaceEnding('ος','δης') || replaceEnding('ης','δης');
      if (!out) out = base + 'δης';
      // Ensure α or ι before δ if possible: if ...δης and previous letter not a/i, insert ι.
      const outBase = removeDiacritics(out);
      const idx = outBase.toLowerCase().lastIndexOf('δης');
      if (idx > 0){
        const prev = outBase[idx-1].toLowerCase();
        if (prev !== 'α' && prev !== 'ι'){
          out = out.slice(0, idx) + 'ι' + out.slice(idx);
        }
      }
      return {out, explain:"Toy patronymic: make a -δης form; passage notes α or ι often stands before δ."};
    }

    if (kind === 'toADAI'){
      // Make plural -άδαι; if ends -δης -> -δαι; else append
      let out = replaceEnding('δης','δαι') || replaceEnding('δας','δαι') || replaceEnding('ος','αδαι');
      if (!out) out = base + 'αδαι';
      // Add acute on the alpha of -αδαι if present
      out = out.replace(/αδαι$/i, 'άδαι');
      return {out, explain:"Toy demotic/ethnic plural: make -άδαι (e.g. Βουτάδαι, Οἰνειάδαι, Πασαργάδαι)."};
    }

    return {out:w, explain:'Unknown move.'};
  }

  function render(){
    const raw = inp.value;
    const w = stripPunct(raw);

    const det = detect(w);
    patternEl.textContent = det.type;
    notesEl.textContent = det.rule;

    const sug = suggestAccent(w, det);
    accentOut.textContent = sug.out;
    accentExplain.textContent = sug.explain;

    // Default move output: show a relevant move based on detection
    let defaultMove = 'toDHS';
    if (det.type === '-γης') defaultMove = 'toGHS';
    if (det.type === '-άδαι') defaultMove = 'toDHS';
    if (det.type === '-δης') defaultMove = 'toADAI';

    const mv = move(w, defaultMove);
    moveOut.textContent = mv.out;
    moveExplain.textContent = mv.explain;
  }

  $('#analyze').addEventListener('click', render);
  inp.addEventListener('keydown', (e) => { if (e.key === 'Enter') render(); });
  inp.addEventListener('input', () => {
    // live update, but only if there's something
    if (inp.value.trim().length) render();
  });

  $('#clear').addEventListener('click', () => {
    inp.value='';
    patternEl.textContent='—';
    notesEl.textContent='Enter a word to see what it resembles.';
    accentOut.textContent='—';
    accentExplain.textContent='—';
    moveOut.textContent='—';
    moveExplain.textContent='—';
    inp.focus();
  });

  $('#toggleGrave').addEventListener('click', () => {
    const cur = accentOut.textContent;
    if (!cur || cur==='—') return;
    accentOut.textContent = toggleFinalAcuteGrave(cur);
    accentExplain.textContent = 'Toggled the last accent mark acute↔grave (toy reminder: final acute often becomes grave in running text).';
  });

  $('#copy').addEventListener('click', async () => {
    const text = accentOut.textContent;
    if (!text || text==='—') return;
    try{
      await navigator.clipboard.writeText(text);
      accentExplain.textContent = 'Copied to clipboard.';
    } catch(e){
      accentExplain.textContent = 'Clipboard not available here; select and copy manually.';
    }
  });

  $$('.moves button').forEach(btn => {
    btn.addEventListener('click', () => {
      const kind = btn.getAttribute('data-move');
      const mv = move(inp.value, kind);
      moveOut.textContent = mv.out;
      moveExplain.textContent = mv.explain;
    });
  });

  const chips = $('#chips');
  examples.forEach(ex => {
    const b = document.createElement('button');
    b.className = 'chip';
    b.type = 'button';
    b.textContent = ex;
    b.addEventListener('click', () => {
      inp.value = ex;
      render();
      inp.focus();
    });
    chips.appendChild(b);
  });

  // initial
  inp.value = 'Τεκτόσαγος';
  render();
})();

