h1{font-size:22px;margin:0 0 4px;letter-spacing:.2px}
.sub{margin:0;color:var(--muted)}
.card{background:linear-gradient(180deg,var(--card) 0%, var(--card2) 100%);border:1px solid var(--line);border-radius:14px;padding:16px 16px 14px;box-shadow:var(--shadow);margin:14px 0}
.card h2{font-size:16px;margin:0 0 8px}
.inst{margin:0 0 12px;color:var(--muted)}
.grid{display:grid;grid-template-columns: 1.4fr 1fr auto;gap:12px;align-items:end}
.grid2{display:grid;grid-template-columns: 1.6fr auto;gap:12px;align-items:end}
.lbl span{display:block;font-size:12px;color:var(--muted);margin:0 0 6px}
.txt,.sel{width:100%;padding:10px 10px;border-radius:10px;border:1px solid var(--line);background:#0e1020;color:var(--text);outline:none}
.txt:focus,.sel:focus{border-color:rgba(122,162,255,.8);box-shadow:0 0 0 3px rgba(122,162,255,.18)}
.btnRow{display:flex;gap:10px;justify-content:flex-end;flex-wrap:wrap}
.btn{padding:10px 12px;border-radius:10px;border:1px solid rgba(122,162,255,.55);background:rgba(122,162,255,.18);color:var(--text);cursor:pointer}
.btn:hover{background:rgba(122,162,255,.26)}
.btn:active{transform:translateY(1px)}
.btn.ghost{border-color:var(--line);background:transparent;color:var(--muted)}
.btn.ghost:hover{background:rgba(255,255,255,.04);color:var(--text)}
.out{margin-top:12px;border-top:1px dashed var(--line);padding-top:12px}
.pillRow{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}
.pill{font-size:12px;padding:6px 10px;border-radius:999px;border:1px solid var(--line);background:rgba(255,255,255,.03);color:var(--muted)}
.pill b{color:var(--text)}
.mini{display:grid;grid-template-columns: 1.2fr .8fr;gap:12px}
.miniCol h3{font-size:13px;margin:0 0 6px;color:var(--muted)}
.pre{margin:0;white-space:pre-wrap;background:#0e1020;border:1px solid var(--line);border-radius:12px;padding:10px;min-height:72px}
.ul{margin:0;padding-left:18px;color:var(--muted)}
.ul li{margin:4px 0}
.inspectBox{margin-top:10px;border-top:1px dashed var(--line);padding-top:12px}
.inspectResult{background:#0e1020;border:1px solid var(--line);border-radius:12px;padding:12px;min-height:54px}
.legend{display:flex;gap:10px;align-items:center;margin-top:8px;color:var(--muted);font-size:12px}
.sw{display:inline-block;padding:2px 8px;border-radius:999px;border:1px solid var(--line)}
.sw-i{background:rgba(125,255,178,.12);color:var(--i);border-color:rgba(125,255,178,.35)}
.sw-ei{background:rgba(122,162,255,.12);color:var(--ei);border-color:rgba(122,162,255,.35)}
.sw-other{background:rgba(255,210,122,.12);color:var(--other);border-color:rgba(255,210,122,.35)}
.mark{padding:1px 2px;border-radius:6px}
.mark.i{background:rgba(125,255,178,.16);outline:1px solid rgba(125,255,178,.35)}
.mark.ei{background:rgba(122,162,255,.16);outline:1px solid rgba(122,162,255,.35)}
.mark.other{background:rgba(255,210,122,.16);outline:1px solid rgba(255,210,122,.35)}
.ftr{color:var(--muted);font-size:13px}
summary{cursor:pointer}
.notes{margin-top:8px}
@media (max-width:860px){
  .grid{grid-template-columns:1fr;}
  .mini{grid-template-columns:1fr;}
  .btnRow{justify-content:flex-start}
}

