const $ = (sel) => document.querySelector(sel);

const baseInput = $('#baseInput');
const patternSel = $('#pattern');
const output = $('#output');
const analysis = $('#analysis');
const pills = $('#pills');

const inspectInput = $('#inspectInput');
const inspectResult = $('#inspectResult');

const examples = [
  {base:'Πηλεύς', pattern:'eus', inspect:'Πηλείδης'},
  {base:'Ἀτρεύς', pattern:'eus', inspect:'Ἀτρείδης'},
  {base:'Αἰγεύς', pattern:'eus', inspect:'Αἰγείδης'},
  {base:'Νείλεως', pattern:'attic-ows', inspect:'Νειλείδης'},
  {base:'Εὔνεως', pattern:'attic-ows', inspect:'Εὐνείδης'},
  {base:'Πρίαμος', pattern:'os', inspect:'Πριαμίδης'},
  {base:'Τάνταλος', pattern:'os', inspect:'Τανταλίδης'},
  {base:'Ἕκτωρ', pattern:'os', inspect:'Ἑκτορίδης'},
  {base:'Ἡρακλῆς', pattern:'es', inspect:'Ἡρακλείδης'},
  {base:'Ἰδηΐς', pattern:'is-fem', inspect:'Ἰδηΐδαι'},
  {base:'Μίνως', pattern:'attic-ows', inspect:'Μινωΐδης'},
];
let exIdx = 0;

function stripDiacritics(s){
  // Remove combining marks; keep base Greek letters.
  return (s || '').normalize('NFD').replace(/[\u0300-\u036f\u1ab0-\u1aff\u1dc0-\u1dff\u20d0-\u20ff\ufe20-\ufe2f]/g,'').normalize('NFC');
}

function lastGreekLetter(s){
  const t = stripDiacritics(s).trim();
  for(let i=t.length-1;i>=0;i--){
    const ch = t[i];
    if(/[\u0370-\u03ff\u1f00-\u1fff]/.test(ch)) return ch;
  }
  return '';
}

function guessPattern(base){
  const t = stripDiacritics(base).trim();
  if(/ευς$/i.test(t)) return 'eus';
  if(/(εως|λεως|νεως|ως)$/i.test(t)) return 'attic-ows';
  if(/ις$/i.test(t)) return 'is-fem';
  if(/ης$/i.test(t)) return 'es';
  if(/ος$/i.test(t) || /ρ$/i.test(t)) return 'os';
  return 'os';
}

function buildStem(base, pattern){
  const raw = base.trim();
  const t = stripDiacritics(raw);

  if(pattern==='eus'){
    // Πηλεύς -> Πηλε-
    return raw.replace(/εύς$/,'ε').replace(/ευς$/,'ε');
  }
  if(pattern==='attic-ows'){
    // Νείλεως -> Νειλε-
    return raw.replace(/εως$/,'ε').replace(/ως$/,'');
  }
  if(pattern==='os'){
    // Πρίαμος -> Πρίαμ-
    if(/ος$/i.test(t)) return raw.replace(/ος$/,'');
    // Ἕκτωρ -> Ἑκτορ-
    if(/ρ$/i.test(t)) return raw;
    return raw;
  }
  if(pattern==='es'){
    // Ἡρακλῆς -> Ἡρακλε-
    return raw.replace(/ῆς$/,'ε').replace(/ης$/,'ε');
  }
  if(pattern==='is-fem'){
    // Ἰδηΐς -> Ἰδηΐ-
    return raw.replace(/ις$/,'ι').replace(/ῖς$/,'ι').replace(/ΐς$/,'ΐ');
  }
  return raw;
}

function generateForms(base, pattern){
  const stem = buildStem(base, pattern);
  const forms = [];
  const notes = [];

  if(pattern==='eus'){
    forms.push(stem + 'ίδης');
    forms.push(stem + 'ίδαι');
    notes.push('Rule-of-thumb: -ευς patronymics are written with ει (…ειδης).');
  } else if(pattern==='attic-ows'){
    // toy: often ει in the patronymic
    forms.push(stem + 'είδης');
    forms.push(stem + 'είδαι');
    notes.push('Toy rule: Attic -εως/-ως often yields …ειδης (cf. Νειλείδης, Εὐνείδης).');
  } else if(pattern==='is-fem'){
    forms.push(stem + 'δαι');
    forms.push(stem + 'δης');
    notes.push('Toy rule: feminine -ις can yield a plural ethnic in -ιδαι (cf. Ἰδηΐδαι).');
  } else if(pattern==='es'){
    // offer both, since Herodian distinguishes by quantity; we can’t compute reliably.
    forms.push(stem + 'ίδης');
    forms.push(stem + 'είδης');
    forms.push(stem + 'ίδαι');
    notes.push('Herodian: -ης (gen. -ους) may take ι or ει depending on penult quantity; toy offers both.');
  } else {
    // os
    // common-looking: -ιδης
    forms.push(stem + 'ίδης');
    forms.push(stem + 'ίδαι');
    notes.push('Fallback: many -ος/-ης (gen -ου) patronymics show ι in the penult (…ιδης).');
  }

  // Add a playful “contraction” suggestion for -ωϊδης -> -ῴδης if present
  const contracted = forms
    .map(f => ({from:f, to: contractOiDiaeresis(f)}))
    .filter(x => x.to !== x.from);

  return {stem, forms: unique(forms), notes, contracted};
}

function unique(arr){
  return [...new Set(arr)];
}

function contractOiDiaeresis(word){
  // Very toy: ωϊδης -> ῴδης ; ωΐδης -> ῴδης
  return word
    .replace(/ωϊδης/g,'ῴδης')
    .replace(/ωΐδης/g,'ῴδης')
    .replace(/ωϊδαι/g,'ῴδαι')
    .replace(/ωΐδαι/g,'ῴδαι');
}

function renderPills(base, pattern, stem){
  const end = lastGreekLetter(base);
  const p = [
    {k:'Base ends with', v: end || '—'},
    {k:'Pattern', v: pattern},
    {k:'Stem (toy)', v: stem || '—'},
  ];
  pills.innerHTML = p.map(x => `<span class="pill"><b>${escapeHtml(x.k)}:</b> ${escapeHtml(x.v)}</span>`).join('');
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function renderAnalysis(lines){
  analysis.innerHTML = lines.map(l => `<li>${escapeHtml(l)}</li>`).join('');
}

function doGenerate(){
  const base = baseInput.value.trim();
  if(!base){
    output.textContent = 'Type a base name first.';
    renderAnalysis(['No input.']);
    pills.innerHTML = '';
    return;
  }
  let pattern = patternSel.value;
  if(pattern==='auto') pattern = guessPattern(base);

  const {stem, forms, notes, contracted} = generateForms(base, pattern);

  renderPills(base, pattern, stem);

  let text = '';
  text += `Base: ${base}\n`;
  text += `Suggested: ${forms.join(' · ')}\n`;
  if(contracted.length){
    text += `\nContraction toy (ωϊ/ωΐ → ῴ):\n`;
    for(const c of contracted){
      text += `  ${c.from} → ${c.to}\n`;
    }
  }
  output.textContent = text.trimEnd();

  const extra = [];
  extra.push(...notes);
  extra.push('Reminder: this gadget does not compute vowel quantity; it imitates the passage’s spelling tendencies.');
  renderAnalysis(extra);

  // also update inspector with first form
  inspectInput.value = forms[0] || base;
  doInspect();
}

function findPenultMarker(word){
  // Look for ... (ι|ει) δης/δαι near the end.
  const w = word.trim();
  const plain = stripDiacritics(w);

  // Prefer matching ει before δης/δαι
  let m = plain.match(/(ει)(δαι|δης)$/i);
  if(m){
    const idx = plain.lastIndexOf(m[1]);
    return {kind:'ei', start: idx, len: 2, suffix: m[2]};
  }
  m = plain.match(/(ι)(δαι|δης)$/i);
  if(m){
    const idx = plain.lastIndexOf(m[1]);
    return {kind:'i', start: idx, len: 1, suffix: m[2]};
  }
  // If ends with δης/δαι but not preceded by i/ei, mark the char before δ
  m = plain.match(/(δαι|δης)$/i);
  if(m){
    const suf = m[1];
    const start = plain.length - suf.length - 1;
    if(start >= 0) return {kind:'other', start, len: 1, suffix: suf};
  }
  return null;
}

function highlightByPlainIndex(original, startPlain, lenPlain){
  // Map indices from plain (diacritics stripped) to original string indices.
  const orig = original;
  const map = []; // plainIndex -> origIndex
  let plainIndex = 0;
  for(let i=0;i<orig.length;i++){
    const ch = orig[i];
    const decomp = ch.normalize('NFD');
    const base = decomp.replace(/[\u0300-\u036f\u1ab0-\u1aff\u1dc0-\u1dff\u20d0-\u20ff\ufe20-\ufe2f]/g,'');
    if(base.length){
      // base may be multiple chars, but for Greek letters it’s usually 1
      for(let k=0;k<base.length;k++){
        map[plainIndex++] = i;
      }
    }
  }
  const startOrig = map[startPlain] ?? 0;
  const endPlain = startPlain + lenPlain - 1;
  const endOrig = (map[endPlain] ?? startOrig);

  const before = escapeHtml(orig.slice(0, startOrig));
  const mid = escapeHtml(orig.slice(startOrig, endOrig+1));
  const after = escapeHtml(orig.slice(endOrig+1));
  return {before, mid, after};
}

function doInspect(){
  const w = inspectInput.value.trim();
  if(!w){
    inspectResult.textContent = 'Type a word to inspect.';
    return;
  }
  const marker = findPenultMarker(w);
  if(!marker){
    inspectResult.innerHTML = `<div>Couldn’t find a -δης / -δαι ending to inspect.</div>`;
    return;
  }

  const parts = highlightByPlainIndex(w, marker.start, marker.len);
  const cls = marker.kind;
  const label = marker.kind==='i' ? 'penult looks like ι' : marker.kind==='ei' ? 'penult looks like ει' : 'penult is something else';

  inspectResult.innerHTML = `
    <div><b>Result:</b> ${escapeHtml(label)} (before -${escapeHtml(marker.suffix)})</div>
    <div style="margin-top:8px;font-size:18px;letter-spacing:.2px;">
      ${parts.before}<span class="mark ${cls}">${parts.mid}</span>${parts.after}
    </div>
  `;
}

$('#genBtn').addEventListener('click', doGenerate);
$('#inspectBtn').addEventListener('click', doInspect);

$('#clearBtn').addEventListener('click', () => {
  baseInput.value = '';
  output.textContent = '';
  analysis.innerHTML = '';
  pills.innerHTML = '';
});

$('#shuffleBtn').addEventListener('click', () => {
  const ex = examples[exIdx % examples.length];
  exIdx++;
  baseInput.value = ex.base;
  patternSel.value = ex.pattern;
  inspectInput.value = ex.inspect;
  doGenerate();
});

// Enter-to-run
baseInput.addEventListener('keydown', (e)=>{ if(e.key==='Enter') doGenerate(); });
inspectInput.addEventListener('keydown', (e)=>{ if(e.key==='Enter') doInspect(); });

// initial
doGenerate();

