(function(){
  const $ = (sel, root=document) => root.querySelector(sel);

  const baseEl = $('#base');
  const modeEl = $('#mode');
  const diaEl = $('#dialysis');
  const derivedEl = $('#derived');
  const noteEl = $('#note');
  const syllEl = $('#syll');
  const prosEl = $('#pros');

  const quizEl = $('#quiz');
  const quizOut = $('#quizOut');

  const combiningDiaeresis = '\u0308';

  function nfc(s){
    try { return (s||'').normalize('NFC'); } catch(e){ return s||''; }
  }

  function stripPunct(s){
    return nfc(s).replace(/[··.,;:!?()\[\]{}"'«»<>]/g,'').trim();
  }

  function stripAccentsKeepDiaeresis(s){
    // Remove Greek tonos/oxia/varia/perispomeni etc, but keep diaeresis.
    // Works by NFD and filtering combining marks.
    const keep = new Set([combiningDiaeresis]);
    const out = [];
    const n = (s||'');
    let d;
    try { d = n.normalize('NFD'); } catch(e){ d = n; }
    for(const ch of d){
      const code = ch.codePointAt(0);
      const isComb = (code >= 0x300 && code <= 0x36F) || (code >= 0x1AB0 && code <= 0x1AFF) || (code >= 0x1DC0 && code <= 0x1DFF) || (code >= 0x20D0 && code <= 0x20FF) || (code >= 0xFE20 && code <= 0xFE2F);
      if(isComb){
        if(keep.has(ch)) out.push(ch);
      } else {
        out.push(ch);
      }
    }
    try { return out.join('').normalize('NFC'); } catch(e){ return out.join(''); }
  }

  function endsWithAny(s, arr){
    return arr.some(x => s.endsWith(x));
  }

  function removeEnding(s){
    // Very rough stemmer for common nominative endings.
    const w = stripPunct(s);
    const endings = ['ος','ον','ης','ας','αιος','ειος','ιος','α','η','ω','ους','ευς'];
    // Try longer first
    const sorted = endings.slice().sort((a,b)=>b.length-a.length);
    for(const e of sorted){
      if(w.endsWith(e) && w.length > e.length+1) return w.slice(0, -e.length);
    }
    return w;
  }

  function applyDiaeresisToy(word){
    // Insert diaeresis on ι or υ when preceded by a vowel and not already diaeresis.
    // This is a toy proxy for Herodian's "ι separated from another vowel".
    const vowels = 'αεηιουωΑΕΗΙΟΥΩ';
    const target = new Set(['ι','Ι','υ','Υ']);
    let out = '';
    const s = nfc(word);
    for(let i=0;i<s.length;i++){
      const ch = s[i];
      const prev = i>0 ? s[i-1] : '';
      const next = i+1 < s.length ? s[i+1] : '';
      // If current is iota/upsilon and previous is vowel, add diaeresis unless already has it (either precomposed or combining).
      if(target.has(ch) && vowels.includes(prev)){
        // If next is combining diaeresis already, do nothing.
        if(next === combiningDiaeresis){
          out += ch;
        } else {
          out += ch + combiningDiaeresis;
        }
      } else {
        out += ch;
      }
    }
    return nfc(out);
  }

  function countSyllables(word, {mergeDiphthongs=true}={}){
    // Heuristic syllable counter.
    // 1) strip accents (keep diaeresis)
    // 2) count vowel nuclei; optionally merge common diphthongs unless diaeresis present on second vowel.
    const w0 = stripAccentsKeepDiaeresis(stripPunct(word));
    if(!w0) return 0;

    // Work in NFD so we can see diaeresis as combining mark.
    let w;
    try { w = w0.normalize('NFD'); } catch(e){ w = w0; }

    const isVowel = (ch) => 'αεηιουωΑΕΗΙΟΥΩ'.includes(ch);
    const hasDiaeresisOnPrev = (arr, idx) => {
      // if arr[idx] is a vowel, check following combining marks for diaeresis
      for(let j=idx+1;j<arr.length;j++){
        const c = arr[j];
        const code = c.codePointAt(0);
        const isComb = (code >= 0x300 && code <= 0x36F);
        if(!isComb) break;
        if(c === combiningDiaeresis) return true;
      }
      return false;
    };

    const arr = Array.from(w);
    let nuclei = 0;
    for(let i=0;i<arr.length;i++){
      const ch = arr[i];
      if(!isVowel(ch)) continue;

      // If this vowel is immediately preceded by another vowel, decide whether to merge.
      // We merge if mergeDiphthongs and there is no diaeresis on THIS vowel.
      // (Diaeresis on the second vowel forces separation.)
      let prevVowelIndex = i-1;
      // skip combining marks between prev base letters
      while(prevVowelIndex>=0){
        const c = arr[prevVowelIndex];
        const code = c.codePointAt(0);
        const isComb = (code >= 0x300 && code <= 0x36F);
        if(isComb){ prevVowelIndex--; continue; }
        break;
      }
      const prevIsVowel = prevVowelIndex>=0 && isVowel(arr[prevVowelIndex]);

      if(prevIsVowel && mergeDiphthongs){
        const thisHasDia = hasDiaeresisOnPrev(arr, i);
        if(thisHasDia){
          nuclei += 1;
        } else {
          // merge: do not increment nuclei (counts as same nucleus as previous)
        }
      } else {
        nuclei += 1;
      }
    }
    return nuclei;
  }

  function derive(base, mode, forceDia){
    const clean = stripPunct(base);
    const stem = removeEnding(clean);

    let derived = '';
    let note = '';
    let pros = '';

    if(mode === 'patronymic'){
      // -ίδης; if stem ends in vowel, keep it (toy), else just add.
      derived = stem + 'ίδης';
      note = 'Toy patronymic/metronymic: stem + -ίδης. (Herodian discusses -ίδης and the “split iota” in Πειραΐδης.)';
      pros = 'No accent engine here; try diaeresis to see 3 vs 4 syllables when vowels meet.';
    } else if(mode === 'demePlural'){
      derived = stem + 'ίδαι';
      note = 'Toy deme-name plural: stem + -ίδαι (cf. Δαιδαλ-ίδαι, Ἰων-ίδαι, Σκαμβων-ίδαι).';
      pros = 'Plural in -ίδαι often behaves like a collective/deme-name; accent not computed.';
    } else if(mode === 'odes'){
      derived = stem + 'ώδης';
      note = 'Toy adjective: stem + -ώδης (Herodian: forms in -ώδης are βαρυτονά).';
      pros = 'Hint: -ώδης is said to be barytone (not accented on the last syllable).';
    } else if(mode === 'kes'){
      derived = stem + 'κης';
      note = 'Toy proper name: stem + -κης (Herodian: proper names in -κης are βαρυτονά).';
      pros = 'Hint: -κης proper names are said to be barytone.';
    }

    if(forceDia){
      derived = applyDiaeresisToy(derived);
    }

    return {derived:nfc(derived), note, pros};
  }

  function render(){
    const base = baseEl.value;
    const mode = modeEl.value;
    const forceDia = diaEl.checked;

    const {derived, note, pros} = derive(base, mode, forceDia);
    derivedEl.textContent = derived || '—';
    noteEl.textContent = note || '—';
    prosEl.textContent = pros || '—';

    const sMerge = countSyllables(derived, {mergeDiphthongs:true});
    const sSplit = countSyllables(derived, {mergeDiphthongs:false});

    let msg = '';
    if(sMerge === sSplit){
      msg = `${sMerge} (no difference between συνίζησις/διάλυσις by this toy)`;
    } else {
      msg = `συνίζησις≈${sMerge} vs διάλυσις≈${sSplit}`;
    }
    syllEl.textContent = msg;
  }

  function renderQuiz(){
    const w = quizEl.value;
    const wDia = applyDiaeresisToy(w);
    const sMerge = countSyllables(w, {mergeDiphthongs:true});
    const sSplit = countSyllables(w, {mergeDiphthongs:false});
    const sForced = countSyllables(wDia, {mergeDiphthongs:true});

    let verdict = '';
    if(sMerge !== sSplit){
      verdict = `This word can be heard as ${sMerge} (with synizesis) or ${sSplit} (with dialysis).`;
    } else {
      verdict = `Toy count gives ${sMerge} syllables either way.`;
    }

    quizOut.innerHTML = `
      <div><b>Input:</b> <code>${escapeHtml(w||'')}</code></div>
      <div><b>Auto-diaeresis suggestion:</b> <code>${escapeHtml(wDia||'')}</code></div>
      <div><b>Counts:</b> synizesis≈<span class="good">${sMerge}</span>, dialysis≈<span class="warn">${sSplit}</span>, with auto-diaeresis≈<span class="good">${sForced}</span></div>
      <div class="mini">Try: <code>Πειραιδης</code> vs <code>Πειραΐδης</code> vs <code>Πειραϊδης</code> (diaeresis forces separation in this toy).</div>
      <div style="margin-top:6px">${escapeHtml(verdict)}</div>
    `;
  }

  function escapeHtml(s){
    return (s+'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  // Wire up
  $('#go').addEventListener('click', render);
  baseEl.addEventListener('keydown', (e)=>{ if(e.key==='Enter') render(); });
  modeEl.addEventListener('change', render);
  diaEl.addEventListener('change', render);

  $('#swap').addEventListener('click', ()=>{
    const cur = derivedEl.textContent;
    if(cur && cur !== '—'){
      baseEl.value = cur;
      render();
    }
  });

  $('#clear').addEventListener('click', ()=>{
    baseEl.value='';
    derivedEl.textContent='—';
    noteEl.textContent='—';
    syllEl.textContent='—';
    prosEl.textContent='—';
  });

  $('#check').addEventListener('click', renderQuiz);
  quizEl.addEventListener('keydown', (e)=>{ if(e.key==='Enter') renderQuiz(); });

  document.addEventListener('click', (e)=>{
    const b = e.target.closest('button.ex');
    if(!b) return;
    baseEl.value = b.getAttribute('data-fill') || '';
    render();
  });

  // Initial
  render();
  renderQuiz();
})();

