const $ = (sel) => document.querySelector(sel);

// --- Greek helpers (very lightweight) ---
function stripDiacritics(s){
  // Remove combining marks after NFD; works for polytonic Greek too.
  return (s||"").normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}
function normalizeGreek(s){
  return stripDiacritics(s).replace(/\s+/g,' ').trim();
}
function endsWithAny(s, arr){
  return arr.find(e => s.endsWith(e)) || null;
}

// Heuristic classifier inspired by the passage
function analyzeWord(raw){
  const w = (raw||"").trim();
  const wN = normalizeGreek(w);
  if(!wN) return {ok:false, msg:"Type a Greek word (nominative singular works best)."};

  // detect endings on normalized form
  const end = endsWithAny(wN, ["νικης","νικης", "νικης", "νικης"]); // placeholder; we will use regex below

  // -νίκης / -νικής
  const isNikes = /νικης$/i.test(wN);
  const isNikesAdj = /νικης$/i.test(wN) && /ης$/i.test(wN); // same; we decide by accent presence in raw

  // -λης class
  const isLes = /λης$/i.test(wN);

  // Guess declension pathway for -λης: if user provides a genitive in input (with comma) or we can propose -ητος/-ου.
  // We'll propose both as "possible".

  // Accent-type guess
  let guess = {type:"unknown", why:[]};

  // If the raw word contains an acute on the last syllable (rough proxy): last vowel has tonos/oxia.
  // We'll just check if the last 2 chars include any accented vowel.
  const hasAcuteLast = /[άέήίόύώὰὲὴὶὸὺὼᾶῆῖῦῶἀἁἂἃἄἅἆἇἑἓἕἕἒἔἠἡἢἣἤἥἦἧἰἱἲἳἴἵἶἷὀὁὂὃὄὅὑὓὕὗὖὦὧ]/.test(w.slice(-2));
  // Not reliable; we won't use it for correctness, only for display.

  if(isNikes){
    // If user typed -νίκης with iota accented earlier, likely noun; if -νικής (accent on eta), adjective.
    // We'll infer from presence of accented eta (ή) near end: νεικής etc.
    const rawNFD = w.normalize('NFD');
    const hasEtaAcuteNearEnd = /η\u0301ς$/.test(rawNFD) || /ή\s*$/.test(w); // crude
    if(hasEtaAcuteNearEnd){
      guess.type = "oxytone";
      guess.why.push("Looks like an adjective in -νικής (Herodian: adjectives are oxytone: πολυνεικής, πολυδευκής)." );
    } else {
      guess.type = "barytone";
      guess.why.push("Treating it as a noun in -νίκης (Herodian: ἱερονίκης, Ὀλυμπιονίκης are barytone)." );
    }
  }

  if(isLes){
    guess.why.push("Ends in -λης. Herodian: -λης words are barytone if they decline via -ητος or -ου.");
    if(guess.type === "unknown") guess.type = "barytone";
  }

  // Build playful "decline" suggestions
  const suggestions = [];
  if(isLes){
    const stem = wN.slice(0, -2); // remove -ης
    // nominative ends -λης; genitive could be -λου; alt via -λητος
    // We keep the lambda: ...λης -> ...λου / ...λητος
    const base = wN.slice(0, -2); // remove ης
    suggestions.push({label:"Possible genitive (through -ου)", form: base + "ου"});
    suggestions.push({label:"Possible -ητος form", form: base + "τος"});
  }
  if(isNikes){
    const base = wN.slice(0, -2);
    suggestions.push({label:"Genitive (toy)", form: base + "ου"});
    suggestions.push({label:"Feminine (toy)", form: wN.replace(/ης$/,'η')});
  }

  // If nothing matched, still provide normalization and a tiny ending guess
  const ending = endsWithAny(wN, ["κης","λης","δοκης","δικης","ρακης","βυκης"]);

  return {
    ok:true,
    raw:w,
    norm:wN,
    flags:{isLes,isNikes},
    guess,
    suggestions,
    ending
  };
}

function renderAnalysis(a){
  if(!a.ok){
    $('#out').innerHTML = `<div class="bad">${escapeHtml(a.msg)}</div>`;
    return;
  }
  const chips = [];
  if(a.flags.isLes) chips.push('<span class="tag">-λης class</span>');
  if(a.flags.isNikes) chips.push('<span class="tag">-νίκης / -νικής</span>');
  if(!chips.length && a.ending) chips.push(`<span class="tag">ends: -${escapeHtml(a.ending)}</span>`);
  if(!chips.length) chips.push('<span class="tag">no special rule matched</span>');

  const typeLabel = a.guess.type === 'barytone' ? `<span class="good">Barytone</span>`
                   : a.guess.type === 'oxytone' ? `<span class="good">Oxytone</span>`
                   : `<span class="tag">Unknown</span>`;

  const why = a.guess.why.length ? `<ul class="bul">${a.guess.why.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul>`
                                 : `<div class="note">No passage-based heuristic triggered; try a word in -λης or -νίκης.</div>`;

  const sug = a.suggestions.length ? `
    <hr>
    <div class="k">Toy transformations</div>
    <ul class="bul">${a.suggestions.map(s=>`<li><span class="k">${escapeHtml(s.label)}:</span> <span class="mono">${escapeHtml(s.form)}</span></li>`).join('')}</ul>
  ` : '';

  $('#out').innerHTML = `
    <div class="kv"><span class="k">Input</span><span class="v mono">${escapeHtml(a.raw)}</span></div>
    <div class="kv"><span class="k">Normalized</span><span class="v mono">${escapeHtml(a.norm)}</span></div>
    <div class="kv"><span class="k">Accent type (toy)</span><span class="v">${typeLabel}</span></div>
    ${why}
    ${sug}
  `;
}

function escapeHtml(s){
  return (s||"").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

// --- Sandbox ---
function updateSandbox(){
  const raw = $('#inSandbox').value;
  const n = normalizeGreek(raw);
  $('#norm').textContent = n || '—';
  const end = endsWithAny(n, ['λης','νικης','κης','δοκος','δοξ','δοκης','ρακης']) || '—';
  $('#ends').textContent = end;
}

// --- Quiz ---
const quizItems = [
  {w:'ἱερονίκης', hint:'appellative from a verb (Herodian: barytone)', ans:'barytone'},
  {w:'Ὀλυμπιονίκης', hint:'appellative from a verb (Herodian: barytone)', ans:'barytone'},
  {w:'πολυνεικής', hint:'adjective (Herodian: oxytone)', ans:'oxytone'},
  {w:'πολυδευκής', hint:'adjective (Herodian: oxytone)', ans:'oxytone'},
  {w:'αὐτάρκης', hint:'exception from ἀρκῶ (Herodian: not oxytone here)', ans:'barytone'},
  {w:'ποδάρκης', hint:'exception from ἀρκῶ (Herodian: not oxytone here)', ans:'barytone'},
  {w:'Ἐπιάλης', hint:'-λης declining via -ητος (Herodian: barytone)', ans:'barytone'},
  {w:'Τρεμίλης', hint:'-λης with -ου / -ητος forms (Herodian: barytone)', ans:'barytone'}
];
let qi = 0;
let revealed = false;

function loadQuiz(i){
  qi = (i + quizItems.length) % quizItems.length;
  const it = quizItems[qi];
  $('#quizWord').textContent = it.w;
  $('#quizHint').textContent = it.hint;
  $('#quizOut').innerHTML = 'Make a guess.';
  revealed = false;
}

function revealQuiz(){
  const it = quizItems[qi];
  const label = it.ans === 'barytone' ? 'Barytone' : 'Oxytone';
  $('#quizOut').innerHTML = `Toy answer: <span class="good">${label}</span>.`;
  revealed = true;
}

function guessQuiz(ans){
  const it = quizItems[qi];
  const ok = ans === it.ans;
  if(!revealed) revealQuiz();
  $('#quizOut').innerHTML += `<br>${ok ? '<span class="good">Correct</span>' : '<span class="bad">Not this time</span>'}.`;
}

// --- Examples ---
const examples = [
  'Ἐπιάλης',
  'Κεφάλλης',
  'Ἀκέλης',
  'Τρεμίλης',
  'ἱερονίκης',
  'Ὀλυμπιονίκης',
  'πολυνεικής',
  'πολυδευκής',
  'Καππαδόκης'
];
let exi = 0;
function loadExample(){
  $('#inWord').value = examples[exi % examples.length];
  exi++;
  run();
}

function run(){
  const a = analyzeWord($('#inWord').value);
  renderAnalysis(a);
}

// --- Wire up ---
$('#btnGo').addEventListener('click', run);
$('#inWord').addEventListener('keydown', (e)=>{ if(e.key==='Enter') run(); });
$('#btnClear').addEventListener('click', ()=>{ $('#inWord').value=''; $('#out').innerHTML=''; });
$('#btnShuffle').addEventListener('click', loadExample);

$('#btnNorm').addEventListener('click', updateSandbox);
$('#inSandbox').addEventListener('input', updateSandbox);

$('#btnReveal').addEventListener('click', revealQuiz);
$('#btnNext').addEventListener('click', ()=>loadQuiz(qi+1));
$('#btnBary').addEventListener('click', ()=>guessQuiz('barytone'));
$('#btnOxy').addEventListener('click', ()=>guessQuiz('oxytone'));

// init
$('#out').innerHTML = '<div class="note">Try an example, or type a word ending in <span class="code">-λης</span> or <span class="code">-νίκης</span>.</div>';
loadQuiz(0);
updateSandbox();

