(() => {
  const $ = (sel, root=document) => root.querySelector(sel);
  const $$ = (sel, root=document) => Array.from(root.querySelectorAll(sel));

  // --- Accent helpers (very lightweight) ---
  const COMBINING = {
    acute: "\u0301",
    grave: "\u0300",
    circumflex: "\u0342",
    diaeresis: "\u0308",
    smooth: "\u0313",
    rough: "\u0314",
    iotaSub: "\u0345",
  };

  function stripDiacritics(s){
    // Remove combining marks and precomposed tonos/oxia variants by NFD.
    return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  }

  function isGreekLetter(ch){
    const code = ch.codePointAt(0);
    return (code >= 0x0370 && code <= 0x03FF) || (code >= 0x1F00 && code <= 0x1FFF);
  }

  function lastVowelIndex(word){
    const w = word.normalize('NFD');
    const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
    // treat diphthongs crudely: still accent first vowel we hit from right
    for(let i=w.length-1;i>=0;i--){
      const ch = w[i];
      if(vowels.has(ch)) return i;
    }
    return -1;
  }

  function penultVowelIndex(word){
    const w = word.normalize('NFD');
    const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
    let foundLast = false;
    for(let i=w.length-1;i>=0;i--){
      const ch = w[i];
      if(vowels.has(ch)){
        if(!foundLast){ foundLast = true; }
        else { return i; }
      }
    }
    return -1;
  }

  function addAccentAt(word, idx, mark){
    if(idx < 0) return word;
    const nfd = word.normalize('NFD');
    // Insert combining mark right after the vowel at idx.
    const before = nfd.slice(0, idx+1);
    const after = nfd.slice(idx+1);
    return (before + mark + after).normalize('NFC');
  }

  function suggestAccent(word, target){
    // target: 'oxy' (last vowel) or 'bary' (penult vowel)
    const base = word;
    const usePoly = $('#poly').checked;
    const mark = usePoly ? COMBINING.acute : COMBINING.acute; // tonos/oxia both fine as combining acute
    const idx = target === 'oxy' ? lastVowelIndex(base) : penultVowelIndex(base);
    return addAccentAt(base, idx, mark);
  }

  // --- Classification rules inspired by the passage ---
  function classify(raw){
    const strip = $('#strip').checked;
    const w0 = raw.trim();
    if(!w0) return { ok:false, msg:"Type a Greek word first." };

    const w = strip ? stripDiacritics(w0) : w0;
    const lower = w.toLowerCase();

    // Suffix checks (unaccented)
    const ends = (suf) => lower.endsWith(suf);

    // Special-cased adjective θεοφανής (oxytone) vs proper name Θεοφάνης (barytone)
    // If user types θεοφανης, we can't know; offer both.
    let rule = null;
    let target = null;
    let ambiguity = null;

    if(ends('ηνης')){ rule = "-ηνης forms"; target = 'oxy'; }
    else if(ends('ενης')){ rule = "-ενης proper names"; target = 'bary'; }
    else if(ends('μης')){ rule = "-μης proper names"; target = 'bary'; }
    else if(ends('ανης')){
      rule = "-ανης proper names";
      target = 'bary';
      if(lower === 'θεοφανης'){
        ambiguity = "Herodian notes: the adjective θεοφανής is oxytone, but the proper name Θεοφάνης is barytone.";
      }
    }

    // Bonus: adjectives in -ής with genitive -ους (toy)
    let genitive = null;
    if(ends('ης')){
      // mock genitive: -ης -> -ους (as in ἀμελής etc.)
      genitive = w.replace(/ης$/i, 'ους');
    }

    if(!rule){
      return {
        ok:true,
        input:w0,
        normalized:w,
        classification:"No suffix rule matched",
        badge:"warn",
        rule:"Try something ending in -μης, -ανης, -ενης, -ηνης (e.g. Δημοσθενης, Γιλγαμης, σαφηνης).",
        suggestion: suggestAccent(w, 'oxy'),
        suggestionLabel:"Just for fun (last-vowel acute)",
        genitive
      };
    }

    let classification = target === 'oxy' ? "Oxytone (accent on the last syllable)" : "Barytone (not final-accented)";
    let badge = target === 'oxy' ? "bad" : "good"; // purely visual

    let suggestion = suggestAccent(w, target);
    let suggestionLabel = target === 'oxy' ? "Suggested oxytone accent" : "Suggested barytone accent (penult)";

    // If ambiguous θεοφανης, show both suggestions.
    let alt = null;
    if(ambiguity){
      alt = {
        oxy: suggestAccent(w, 'oxy'),
        bary: suggestAccent(w, 'bary')
      };
      badge = "warn";
      classification = "Ambiguous here (name vs adjective)";
    }

    return {
      ok:true,
      input:w0,
      normalized:w,
      classification,
      badge,
      rule,
      suggestion,
      suggestionLabel,
      genitive,
      ambiguity,
      alt
    };
  }

  function render(res){
    const out = $('#out');
    if(!res.ok){
      out.innerHTML = `<div class="badge bad">Error</div> ${escapeHtml(res.msg)}`;
      return;
    }

    const badgeText = res.badge === 'good' ? 'Barytone-ish' : res.badge === 'bad' ? 'Oxytone-ish' : 'Heuristic';

    let html = `
      <div class="row" style="justify-content:space-between;gap:12px">
        <div>
          <span class="badge ${res.badge}">${badgeText}</span>
          <span class="badge">${escapeHtml(res.rule)}</span>
        </div>
      </div>
      <dl class="kv">
        <dt class="k">You typed</dt><dd class="v">${escapeHtml(res.input)}</dd>
        <dt class="k">Normalized</dt><dd class="v">${escapeHtml(res.normalized)}</dd>
        <dt class="k">Toy verdict</dt><dd class="v">${escapeHtml(res.classification)}</dd>
        <dt class="k">Accent suggestion</dt><dd class="v"><span class="mono">${escapeHtml(res.suggestion)}</span> <span class="badge">${escapeHtml(res.suggestionLabel)}</span></dd>
    `;

    if(res.alt){
      html += `
        <dt class="k">Alt. suggestions</dt>
        <dd class="v">
          <div class="mono">Oxytone: ${escapeHtml(res.alt.oxy)}</div>
          <div class="mono">Barytone: ${escapeHtml(res.alt.bary)}</div>
        </dd>
      `;
    }

    if(res.genitive){
      html += `
        <dt class="k">Mock genitive</dt><dd class="v"><span class="mono">${escapeHtml(res.genitive)}</span> <span class="badge">-ης → -ους (toy)</span></dd>
      `;
    }

    if(res.ambiguity){
      html += `
        <dt class="k">Note</dt><dd class="v">${escapeHtml(res.ambiguity)}</dd>
      `;
    }

    html += `</dl>`;
    out.innerHTML = html;
  }

  function escapeHtml(s){
    return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  // --- Examples / game ---
  const EXAMPLES = [
    "Γιλγάμης",
    "Ἰάμης",
    "Τιγράνης",
    "Ἰορδάνης",
    "Ἀριστοφάνης",
    "Θεοφάνης",
    "θεοφανής",
    "Δημοσθένης",
    "Διογένης",
    "Ἀντιγένης",
    "Ἀριστομένης",
    "Βορυσθένης",
    "σαφηνής",
    "παιδηνής",
    "γαληνής",
    "ἀμελής",
    "ἀφελής"
  ];

  function pickRandom(){
    return EXAMPLES[Math.floor(Math.random()*EXAMPLES.length)];
  }

  // Drag & drop chips
  let dragId = null;

  function makeChip(text){
    const el = document.createElement('div');
    el.className = 'chip';
    el.draggable = true;
    el.textContent = text;
    el.dataset.word = text;
    el.id = 'chip_' + Math.random().toString(16).slice(2);

    el.addEventListener('dragstart', (e) => {
      dragId = el.id;
      e.dataTransfer.setData('text/plain', el.id);
      e.dataTransfer.effectAllowed = 'move';
    });
    return el;
  }

  function setupBins(){
    const bins = $$('.bin');
    bins.forEach(bin => {
      bin.addEventListener('dragover', (e) => {
        e.preventDefault();
        bin.classList.add('dragover');
      });
      bin.addEventListener('dragleave', () => bin.classList.remove('dragover'));
      bin.addEventListener('drop', (e) => {
        e.preventDefault();
        bin.classList.remove('dragover');
        const id = e.dataTransfer.getData('text/plain') || dragId;
        const chip = document.getElementById(id);
        if(!chip) return;
        bin.querySelector('.binBody').appendChild(chip);
      });
    });
  }

  function resetGame(){
    const bank = $('#bank');
    const binBary = $('#binBary');
    const binOxy = $('#binOxy');
    bank.innerHTML = '';
    binBary.innerHTML = '';
    binOxy.innerHTML = '';
    $('#score').textContent = '';

    // Choose 10 chips
    const pool = [...EXAMPLES];
    const chosen = [];
    while(chosen.length < 10 && pool.length){
      chosen.push(pool.splice(Math.floor(Math.random()*pool.length),1)[0]);
    }
    chosen.forEach(w => bank.appendChild(makeChip(w)));
  }

  function expectedBin(word){
    // Use same classifier but force stripping accents for consistency.
    const saved = $('#strip').checked;
    $('#strip').checked = true;
    const res = classify(word);
    $('#strip').checked = saved;

    if(!res.ok) return null;
    if(res.alt) return 'amb';
    if(res.badge === 'good') return 'bary';
    if(res.badge === 'bad') return 'oxy';
    return null;
  }

  function checkGame(){
    const binBary = $('#binBary');
    const binOxy = $('#binOxy');
    const chips = $$('.chip', $('#app'));

    let totalPlaced = 0;
    let correct = 0;
    let ambiguous = 0;

    function inBin(chip, binEl){
      return binEl.contains(chip);
    }

    chips.forEach(chip => {
      const exp = expectedBin(chip.dataset.word);
      const placed = inBin(chip, binBary) ? 'bary' : inBin(chip, binOxy) ? 'oxy' : 'bank';
      chip.style.borderColor = 'rgba(125,211,252,.25)';

      if(placed !== 'bank') totalPlaced++;

      if(exp === 'amb'){
        if(placed !== 'bank'){
          ambiguous++;
          chip.style.borderColor = 'rgba(251,191,36,.55)';
        }
        return;
      }
      if(exp && placed !== 'bank'){
        if(exp === placed){
          correct++;
          chip.style.borderColor = 'rgba(134,239,172,.55)';
        } else {
          chip.style.borderColor = 'rgba(251,113,133,.55)';
        }
      }
    });

    const msg = `Placed: ${totalPlaced}/10 · Correct: ${correct}` + (ambiguous ? ` · Ambiguous: ${ambiguous}` : '');
    $('#score').textContent = msg;
  }

  // --- Wire up ---
  function analyze(){
    const res = classify($('#inp').value);
    render(res);
  }

  $('#btnAnalyze').addEventListener('click', analyze);
  $('#inp').addEventListener('keydown', (e) => {
    if(e.key === 'Enter') analyze();
  });

  $('#btnRandom').addEventListener('click', () => {
    $('#inp').value = pickRandom();
    analyze();
  });

  $('#btnClear').addEventListener('click', () => {
    $('#inp').value = '';
    $('#out').innerHTML = '';
    $('#inp').focus();
  });

  $('#btnReset').addEventListener('click', resetGame);
  $('#btnCheck').addEventListener('click', checkGame);

  setupBins();
  resetGame();

  // Initial demo
  $('#inp').value = 'Δημοσθένης';
  analyze();
})();

