  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
}
*{box-sizing:border-box}
.wrap{max-width:980px;margin:24px auto;padding:0 16px;color:var(--text);font:16px/1.45 system-ui,-apple-system,Segoe UI,Roboto,Arial,"Noto Sans",sans-serif}
.hdr{display:flex;gap:16px;align-items:flex-start;margin-bottom:14px}
