h2{font-size:18px;margin:0 0 8px 0}
.inst{margin:0 0 12px 0;color:var(--muted)}
.ex{font-family:var(--mono);color:var(--accent)}
.row{display:grid;grid-template-columns:140px 1fr auto auto auto;gap:10px;align-items:center;margin:10px 0 12px 0}
.lbl{color:var(--muted);font-weight:600}
