.btn:hover{border-color:rgba(125,211,252,.55)}
.btn:active{transform:translateY(1px)}
.btn.ghost{background:rgba(255,255,255,.06)}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.panel{border:1px solid var(--line);border-radius:12px;padding:12px;background:rgba(0,0,0,.18)}
.panel h3{margin:0 0 8px 0;font-size:14px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}
.big{font-size:22px;font-weight:800;margin:2px 0 4px 0}
.muted{color:var(--muted)}
