.kv:first-of-type{border-top:none}
.k{color:var(--muted)}
.v{font-weight:700}
.mono{font-family:var(--mono)}
.notes{margin-top:10px;color:var(--muted)}
.notes summary{cursor:pointer;color:var(--accent);font-weight:700}
.notes ul{margin:8px 0 0 18px}
.quiz{display:flex;flex-direction:column;gap:10px}
.qrow{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.qword{font-family:var(--mono);font-size:22px;font-weight:900;padding:8px 10px;border-radius:12px;border:1px solid var(--line);background:rgba(0,0,0,.2)}
.feedback{padding:10px 12px;border-radius:12px;border:1px solid var(--line);background:rgba(0,0,0,.18);color:var(--muted)}
.feedback.good{border-color:rgba(134,239,172,.45);color:var(--good)}
.feedback.bad{border-color:rgba(252,165,165,.45);color:var(--bad)}
.feedback.warn{border-color:rgba(253,230,138,.45);color:var(--warn)}
.score{display:flex;gap:10px;flex-wrap:wrap}
.pill{border:1px solid var(--line);background:rgba(255,255,255,.06);padding:6px 10px;border-radius:999px;color:var(--muted)}
.ftr{margin:10px 0 24px 0;color:var(--faint)}
.small{font-size:12.5px}
@media (max-width:820px){
  .row{grid-template-columns:1fr;}
  .grid{grid-template-columns:1fr}
}

