(() => {
  const $ = (sel) => document.querySelector(sel);
  const input = $('#in');
  const mode = $('#mode');
  const accentSel = $('#accent');
  const result = $('#result');
  const explain = $('#explain');
  const chips = $('#chips');

  const examples = [
    'νεώρης','αὐτώρης','κατώρης','ὑληώρης','μεσσώρης','Διώρης','Λυκώρης',
    'Ἀγχίσης','Ἀντίσης','Ἀμφίσης','Ἐρίσης','Κυρίσης','Τιπανίσης','Βασανίσης','Ὀδρύσης',
    'ἐργάτης','ἐλάτης','Ἰξιβάτης','Ἰαζαβάτης','Σαρμάτης','Σαυρομάτης','Γαλάτης','Ἀβρινάτης','Δαλμάτης','Χαριμάτης'
  ];

  // --- Greek helpers ---
  const COMBINING = /[\u0300-\u036f]/g;

  function nfd(s){ return s.normalize('NFD'); }
  function nfc(s){ return s.normalize('NFC'); }

  function stripDiacritics(s){
    // remove combining marks (accents, breathings, iota subscript, diaeresis, etc.)
    return nfc(nfd(s).replace(COMBINING,''));
  }

  function hasGreek(s){
    return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(s);
  }

  function detectEnding(base){
    // base should be stripped of diacritics, but keep Greek letters.
    const b = base;
    if (b.endsWith('ωρης') || b.endsWith('Ωρης') || b.endsWith('ωΡης') || b.endsWith('ΩΡης')) return 'ores';
    if (b.endsWith('σης') || b.endsWith('Σης') || b.endsWith('σης'.toUpperCase())) return 'ses';
    if (b.endsWith('της') || b.endsWith('Της') || b.endsWith('της'.toUpperCase())) return 'tes';
    return null;
  }

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

  function vowelGroups(stripped){
    // crude syllable-ish segmentation: groups of vowels (incl. diphthongs as one group)
    const s = stripped;
    const groups = [];
    let i = 0;
    while (i < s.length){
      const ch = s[i];
      if (!vowels.has(ch)) { i++; continue; }
      let j = i+1;
      while (j < s.length && vowels.has(s[j])) j++;
      groups.push({start:i, end:j});
      i = j;
    }
    return groups;
  }

  function accentCombining(type){
    // acute or circumflex
    return type === 'circumflex' ? '\u0342' : '\u0301';
  }

  function accentPenult(original, forcedType){
    const raw = original.trim();
    if (!raw) return {ok:false, msg:'Type a word first.'};
    if (!hasGreek(raw)) return {ok:false, msg:'Please use Greek letters (polytonic or monotonic is fine).'};

    const stripped = stripDiacritics(raw);
    const ending = forcedType === 'auto' ? detectEnding(stripped) : forcedType;

    const endingLabel = ending === 'ores' ? '-ωρης' : ending === 'ses' ? '-σης' : ending === 'tes' ? '-της' : null;

    // Find penult vowel group
    const groups = vowelGroups(stripped);
    if (groups.length < 2){
      return {ok:false, msg:`I can’t find a penult (need at least 2 vowel groups).`, ending: endingLabel, stripped, groups};
    }
    const penult = groups[groups.length - 2];

    // Place accent on the last vowel of the penult group (toy choice)
    const acc = accentCombining(accentSel.value);
    const idx = penult.end - 1;

    // Build accented string in NFD, then NFC
    const nfdStripped = nfd(stripped);
    // Map idx in NFC string to idx in NFD string: since stripped has no combining marks, NFC and NFD indices align.
    const before = nfdStripped.slice(0, idx + 1);
    const after = nfdStripped.slice(idx + 1);
    const accented = nfc(before + acc + after);

    // Provide a simple split visualization
    const split = splitByGroups(stripped, groups);

    // Herodian-ish message
    let herMsg;
    if (!endingLabel){
      herMsg = `Ending not recognized as -ωρης / -σης / -της. I’ll still accent the penult (toy mode).`;
    } else {
      herMsg = `Detected ${endingLabel}. Herodian notes these are typically accented on the penult (βαρύνονται).`;
    }

    return {
      ok:true,
      accented,
      ending: endingLabel,
      stripped,
      groups,
      split,
      msg: herMsg
    };
  }

  function splitByGroups(stripped, groups){
    // Insert middle dots between vowel groups boundaries (very rough)
    const cuts = new Set();
    for (let k = 0; k < groups.length - 1; k++){
      cuts.add(groups[k].end);
    }
    let out = '';
    for (let i = 0; i < stripped.length; i++){
      out += stripped[i];
      if (cuts.has(i+1)) out += '·';
    }
    return out;
  }

  function render(res){
    if (!res.ok){
      result.textContent = '—';
      explain.innerHTML = `<span class="badge bad">Nope</span> ${escapeHtml(res.msg)}`;
      return;
    }

    result.textContent = res.accented;

    const badge = `<span class="badge good">Penult</span>`;
    const ending = res.ending ? ` <span class="badge">${escapeHtml(res.ending)}</span>` : '';

    explain.innerHTML = `${badge}${ending} ${escapeHtml(res.msg)}
      <div class="kv">
        <div class="k">Stripped</div><div class="v mono">${escapeHtml(res.stripped)}</div>
        <div class="k">Vowel-groups</div><div class="v mono">${escapeHtml(res.split)}</div>
      </div>`;
  }

  function escapeHtml(s){
    return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  function fillChips(){
    chips.innerHTML = '';
    examples.forEach(w => {
      const d = document.createElement('div');
      d.className = 'chip';
      d.textContent = w;
      d.addEventListener('click', () => {
        input.value = w;
        run();
      });
      chips.appendChild(d);
    });
  }

  function run(){
    const forced = mode.value;
    const res = accentPenult(input.value, forced);
    render(res);
  }

  $('#go').addEventListener('click', run);
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') run();
  });

  $('#strip').addEventListener('click', () => {
    input.value = stripDiacritics(input.value);
    run();
  });

  $('#rand').addEventListener('click', () => {
    const w = examples[Math.floor(Math.random()*examples.length)];
    input.value = stripDiacritics(w); // make it a bit game-like
    run();
  });

  mode.addEventListener('change', run);
  accentSel.addEventListener('change', run);

  fillChips();
  // seed
  input.value = 'νεωρης';
  run();
})();

