const $ = (sel, el=document) => el.querySelector(sel);
const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));
const plain=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const FORMS={
μαθητης:['μαθητής','Oxytone: acute on the final syllable; verbal -της example.'],
ποιητης:['ποιητής','Oxytone: acute on the final syllable; verbal -της example.'],
αθλητης:['ἀθλητής','Oxytone: acute on the final syllable; verbal -της example.'],
πειρατης:['πειρατής','Oxytone: acute on the final syllable; verbal -της example.'],
κομητης:['κομήτης','Barytone non-verbal example: acute on the penult, not a written grave.'],
κυβερνητης:['κυβερνήτης','Explicit counterexample to the verbal rule: acute on the penult.'],
ευρετης:['εὑρετής','Separately noted by Herodian; acute on the final syllable.'],
δεσποτης:['δεσπότης','Listed passage form: acute on the penult.'],
τοξοτης:['τοξότης','Listed passage form: acute on the penult.'],
μασσαγετης:['Μασσαγέτης','Ethnic: a Scythian people; acute on the penult.'],
θυσσαγετης:['Θυσσαγέτης','Ethnic around the Maeotic lake; acute on the penult.'],
τορετης:['Τορέτης','Ethnic: a Pontic people; acute on the penult.'],
μυργετης:['Μυργέτης','Ethnic: a Scythian people; acute on the penult.'],
μακετης:['Μακέτης','Ethnic: the Macedonian; acute on the penult.']};
function suggest(word){const key=plain(word);if(!key)return {ok:false,msg:'Type a Greek word first.'};const entry=FORMS[key];return entry?{ok:true,form:entry[0],expl:entry[1]}:{ok:false,msg:'Outside the passage example set; no accent prediction. Try μαθητής or κομήτης.'};}
function renderSuggestion(res){const out=$('#out');out.replaceChildren();const form=document.createElement('div');form.className='big';form.textContent=res.ok?res.form:'No result';const note=document.createElement('p');note.textContent=res.ok?res.expl:res.msg;out.append(form,note);}
function getRadio(){return 'auto';}
// --- Mini sorting game ---
const WORDS = [
  {w:"Μασσαγέτης", bin:"ethnic"},
  {w:"Θυσσαγέτης", bin:"ethnic"},
  {w:"Τορέτης", bin:"ethnic"},
  {w:"Μυργέτης", bin:"ethnic"},
  {w:"Μακέτης", bin:"ethnic"},
  {w:"μαθητής", bin:"agent"},
  {w:"ποιητής", bin:"agent"},
  {w:"πειρατής", bin:"agent"},
  {w:"τοξότης", bin:"agent"},
  {w:"δεσπότης", bin:"other"},
  {w:"κομήτης", bin:"other"},
  {w:"εὑρετής", bin:"agent"}
];

function makeToken(text){
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'token';
  b.textContent = text;
  b.dataset.home = 'bank';
  b.addEventListener('click', () => cycleToken(b));
  return b;
}

function cycleToken(tok){
  const order = ['bank','binEth','binAg','binOt'];
  const cur = tok.parentElement?.id || 'bank';
  const idx = order.indexOf(cur);
  const next = order[(idx+1) % order.length];
  $("#"+next).appendChild(tok);
}

function resetGame(){
  const bank = $("#bank");
  bank.innerHTML = "";
  $("#binEth").innerHTML = "";
  $("#binAg").innerHTML = "";
  $("#binOt").innerHTML = "";
  const shuffled = WORDS.slice().sort(()=>Math.random()-0.5);
  for (const it of shuffled){
    const t = makeToken(it.w);
    t.dataset.answer = it.bin;
    bank.appendChild(t);
  }
  $("#score").textContent = "Click a token to move it: bank → ethnic → agent → other → bank.";
}

function checkGame(){
  let total = 0, correct = 0;
  for (const tok of $$('.token')){
    total++;
    const parentId = tok.parentElement?.id;
    const placed = parentId === 'binEth' ? 'ethnic' : parentId === 'binAg' ? 'agent' : parentId === 'binOt' ? 'other' : 'bank';
    if (placed !== 'bank' && placed === tok.dataset.answer) correct++;
  }
  const placedCount = total - $$('#bank .token').length;
  const msg = `Placed: ${placedCount}/${total}. Correct (among placed): ${correct}/${placedCount}.`;
  $("#score").textContent = msg;
}

// --- Wire up UI ---
function runSuggest(){
  const word = $("#w").value;
  const kind = getRadio('kind');
  const pen = getRadio('pen');
  const res = suggest(word, kind, pen);
  renderSuggestion(res);
}

$("#go").addEventListener('click', runSuggest);
$("#w").addEventListener('keydown', (e)=>{ if(e.key==='Enter') runSuggest(); });

$("#rand").addEventListener('click', ()=>{
  const samples = [
    "μαθητης",
    "ποιητης",
    "κομητης",
    "Μασσαγετης",
    "Θυσσαγετης",
    "κυβερνητης",
    "αθλητης",
    "δεσποτης"
  ];
  $("#w").value = samples[Math.floor(Math.random()*samples.length)];
  runSuggest();
});

$("#reset").addEventListener('click', resetGame);
$("#check").addEventListener('click', checkGame);

// initial
resetGame();
renderSuggestion({ok:false, msg:"Type a -της word above, then click “Show passage form”."});

