const $ = (sel) => document.querySelector(sel);

const baseEl = $('#base');
const modeEl = $('#mode');
const suffixEl = $('#suffix');
const autoAccentEl = $('#autoAccent');
const showSyllEl = $('#showSyll');
const resultEl = $('#result');
const explainEl = $('#explain');
const chipsEl = $('#chips');

const passageExamples = [
  {w:'πεδήτης', base:'πεδ-', suffix:'-ήτης', mode:'simple', note:'simple -ήτης'},
  {w:'πλανήτης', base:'πλαν-', suffix:'-ήτης', mode:'simple', note:'simple -ήτης'},
  {w:'λιμνήτης', base:'λιμν-', suffix:'-ήτης', mode:'simple', note:'simple -ήτης'},
  {w:'Δασσαρήτης', base:'Δασσαρ-', suffix:'-ήτης', mode:'simple', note:'ethnic'},
  {w:'Δεκιήτης', base:'Δεκι-', suffix:'-ήτης', mode:'pleonasm', note:'-ιτης → -ιήτης (toy)'},
  {w:'Ἰουλιήτης', base:'Ἰουλιτ-', suffix:'-ήτης', mode:'pleonasm', note:'from Ἰουλίτης'},
  {w:'Αἰγινήτης', base:'Αἰγινάτ-', suffix:'-ήτης', mode:'trophe', note:'-άτης → -ήτης'},
  {w:'στρατιώτης', base:'στρατιω-', suffix:'-ώτης', mode:'simple', note:'-ώτης'},
  {w:'νησιώτης', base:'νησιω-', suffix:'-ώτης', mode:'simple', note:'-ώτης'},
  {w:'Ἠπειρώτης', base:'Ἠπειρω-', suffix:'-ώτης', mode:'simple', note:'ethnic -ώτης'},
  {w:'ἀγγελιώτης', base:'ἀγγελιω-', suffix:'-ώτης', mode:'simple', note:'-ώτης'},
  {w:'ἀγρώτης', base:'ἀγρω-', suffix:'-ώτης', mode:'simple', note:'-ώτης'},
  {w:'ἀγρώστης', base:'ἀγρω-', suffix:'-στης', mode:'simple', note:'adds σ: -ώτης → -ώστης (toy)'}
];

function stripHyphen(s){
  return (s || '').replace(/[-‐‑‒–—]\s*$/,'').trim();
}

function normalizeGreek(s){
  // Keep as-is; just normalize whitespace.
  return (s || '').replace(/\s+/g,' ').trim();
}

function countSyllablesRough(gr){
  // Very rough: count vowel groups (incl. diphthongs-ish). Not academically strict.
  const s = gr
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,''); // strip combining marks
  const vowels = 'αεηιουωΑΕΗΙΟΥΩ';
  let count = 0;
  let inV = false;
  for (const ch of s){
    const isV = vowels.includes(ch);
    if (isV && !inV) count++;
    inV = isV;
  }
  return Math.max(1, count);
}

function applyToyAccent(word, suffix){
  // If user wants auto accent, ensure suffix vowel is accented.
  // For -ήτης and -ώτης we just replace η/ω in the suffix with ή/ώ.
  if (suffix === '-ήτης'){
    return word.replace(/ητης$/,'ήτης').replace(/Ητης$/,'Ήτης');
  }
  if (suffix === '-ώτης'){
    return word.replace(/ωτης$/,'ώτης').replace(/Ωτης$/,'Ώτης');
  }
  if (suffix === '-ώστης'){
    return word.replace(/ωστης$/,'ώστης').replace(/Ωστης$/,'Ώστης');
  }
  if (suffix === '-στης') return word; // leave
  return word;
}

function buildWord(){
  let base = normalizeGreek(baseEl.value);
  if (!base){
    resultEl.textContent = '—';
    explainEl.textContent = 'Enter a base (Greek letters) and click Build.';
    return;
  }
  base = stripHyphen(base);

  const mode = modeEl.value;
  let suffix = suffixEl.value;

  // Special: allow -ώτης family to optionally show the passage’s -ώστης idea via base ending.
  // If user types something ending in "ω" and chooses -ώτης, fine.

  let transformedBase = base;
  let steps = [];

  if (mode === 'pleonasm'){
    // Toy rule: if base ends with ιτ or ι (as in Ἰουλίτ-), insert η after ι before -της.
    // We'll aim to produce ...ιήτης.
    // If base ends with "ιτ" drop the τ (since -της supplies it), else keep base.
    if (/ιτ$/i.test(transformedBase)){
      transformedBase = transformedBase.replace(/ιτ$/i,'ι');
      steps.push('Removed trailing τ from base (so -της can supply it).');
    }
    // Ensure ends with iota
    if (!/ι$/i.test(transformedBase)){
      steps.push('Pleonasm toy expects base ending in ι (or ιτ). Proceeding anyway.');
    }
    // We will build with -ήτης regardless of suffix selector, because this mode is about -ιήτης.
    suffix = '-ήτης';
    let out = transformedBase + 'ήτης';
    if (autoAccentEl.checked) out = applyToyAccent(out, '-ήτης');
    render(out, steps, {modeLabel:'πλεονασμός (add η)', suffixLabel:'-ιήτης pattern'});
    return;
  }

  if (mode === 'trophe'){
    // Toy rule: if base ends with άτ or ατ, change α → η before -της.
    // Example: Αἰγινάτ- → Αἰγινήτης.
    suffix = '-ήτης';
    if (/[άα]τ$/i.test(transformedBase)){
      transformedBase = transformedBase.replace(/[άα]τ$/i,'η');
      steps.push('Changed -άτ- / -ατ- to -η- (τροπή).');
    } else if (/[άα]$/i.test(transformedBase)){
      transformedBase = transformedBase.replace(/[άα]$/i,'η');
      steps.push('Changed final -ά / -α to -η (τροπή toy).');
    } else {
      steps.push('Trophe toy expects base ending in -α(τ). Proceeding anyway.');
    }
    let out = transformedBase + 'της';
    if (autoAccentEl.checked) out = applyToyAccent(out, '-ήτης');
    render(out, steps, {modeLabel:'τροπή (change)', suffixLabel:'-ήτης'});
    return;
  }

  // simple
  if (suffix === '-ήτης'){
    // If base ends with τ, drop it (avoid ...ττης)
    if (/τ$/i.test(transformedBase)){
      transformedBase = transformedBase.replace(/τ$/i,'');
      steps.push('Dropped trailing τ before -της.');
    }
    let out = transformedBase + 'ητης';
    if (autoAccentEl.checked) out = applyToyAccent(out, '-ήτης');
    render(out, steps, {modeLabel:'simple', suffixLabel:'-ήτης'});
    return;
  }

  if (suffix === '-ώτης'){
    if (/τ$/i.test(transformedBase)){
      transformedBase = transformedBase.replace(/τ$/i,'');
      steps.push('Dropped trailing τ before -της.');
    }
    let out = transformedBase + 'ωτης';
    if (autoAccentEl.checked) out = applyToyAccent(out, '-ώτης');
    render(out, steps, {modeLabel:'simple', suffixLabel:'-ώτης'});
    return;
  }

  // fallback
  let out = transformedBase + suffix.replace(/^-/,'');
  render(out, steps, {modeLabel:'simple', suffixLabel:suffix});
}

function render(word, steps, meta){
  const syll = countSyllablesRough(word);
  const badges = [];
  badges.push(`<span class="badge ok">mode: ${escapeHtml(meta.modeLabel)}</span>`);
  badges.push(`<span class="badge">suffix: ${escapeHtml(meta.suffixLabel)}</span>`);
  if (showSyllEl.checked) badges.push(`<span class="badge">~syllables: ${syll}</span>`);

  resultEl.innerHTML = `<span>${escapeHtml(word)}</span> ${badges.join(' ')}`;

  const stepText = steps.length ? ('Steps: ' + steps.join(' ')) : 'Steps: (none)';
  explainEl.textContent = `${stepText}  (Accent + syllables are approximate.)`;
}

function escapeHtml(s){
  return String(s)
    .replaceAll('&','&amp;')
    .replaceAll('<','&lt;')
    .replaceAll('>','&gt;')
    .replaceAll('"','&quot;')
    .replaceAll("'",'&#39;');
}

function fillChips(){
  chipsEl.innerHTML = '';
  for (const ex of passageExamples){
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip';
    b.textContent = ex.w;
    b.title = ex.note;
    b.addEventListener('click', () => {
      baseEl.value = ex.base;
      modeEl.value = ex.mode;
      if (ex.suffix === '-ώστης' || ex.suffix === '-στης'){
        // map to closest UI option
        suffixEl.value = '-ώτης';
      } else {
        suffixEl.value = ex.suffix;
      }
      buildWord();
    });
    chipsEl.appendChild(b);
  }
}

function randomExample(){
  const ex = passageExamples[Math.floor(Math.random()*passageExamples.length)];
  baseEl.value = ex.base;
  modeEl.value = ex.mode;
  suffixEl.value = (ex.suffix === '-ώτης' || ex.suffix === '-ήτης') ? ex.suffix : '-ώτης';
  buildWord();
}

$('#build').addEventListener('click', buildWord);
$('#clear').addEventListener('click', () => {
  baseEl.value = '';
  resultEl.textContent = '—';
  explainEl.textContent = 'Enter a base and click Build.';
  baseEl.focus();
});
$('#random').addEventListener('click', randomExample);

// clickable inline examples
for (const el of document.querySelectorAll('.ex')){
  el.addEventListener('click', () => {
    baseEl.value = el.dataset.fill || '';
    baseEl.focus();
  });
}

// live-ish updates
baseEl.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') buildWord();
});
modeEl.addEventListener('change', buildWord);
suffixEl.addEventListener('change', buildWord);
autoAccentEl.addEventListener('change', buildWord);
showSyllEl.addEventListener('change', buildWord);

fillChips();
randomExample();

