const $ = (sel, el=document) => el.querySelector(sel);
const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

// --- Greek helpers (toy-level) ---
const COMBINING = /[\u0300-\u036f]/g;
const TONOS_OXIA = /[άέήίόύώΆΈΉΊΌΎΏ]/;

function nfd(s){ return (s||"").normalize('NFD'); }
function nfc(s){ return (s||"").normalize('NFC'); }

function stripDiacritics(s){
  // Remove combining marks; keep base Greek letters.
  return nfc(nfd(s).replace(COMBINING, ''));
}

function hasAccent(s){
  // crude: check for precomposed tonos/oxia letters OR combining acute/grave/circumflex
  const d = nfd(s);
  return /[\u0300\u0301\u0342]/.test(d) || TONOS_OXIA.test(s);
}

function lastIndexOfVowelCluster(s){
  // Return index of last vowel (base) in string.
  const vowels = new Set('αεηιουωΑΕΗΙΟΥΩ'.split(''));
  for(let i=s.length-1;i>=0;i--){
    if(vowels.has(s[i])) return i;
  }
  return -1;
}

function syllabifyToy(word){
  // Very rough: split before each vowel group (CV...)
  // Works decently for showing "barytone vs oxytone" positions.
  const w = stripDiacritics(word);
  const vowels = 'αεηιουωΑΕΗΙΟΥΩ';
  let parts = [];
  let cur = '';
  let i=0;
  while(i<w.length){
    cur += w[i];
    const isV = vowels.includes(w[i]);
    const next = w[i+1];
    const nextIsV = next && vowels.includes(next);
    if(isV && !nextIsV){
      // end vowel group; try to keep following consonant(s) with next syllable, not this one
      parts.push(cur);
      cur='';
    }
    i++;
  }
  if(cur) parts[parts.length-1] = (parts[parts.length-1]||'') + cur;
  // cleanup empties
  parts = parts.filter(p=>p.length);
  if(parts.length===0) parts=[w];
  return parts;
}

function addAcuteOnSyllable(word, syllIndexFromEnd){
  // syllIndexFromEnd: 1=ultima, 2=penult, 3=antepenult
  const base = stripDiacritics(word);
  const syl = syllabifyToy(base);
  const target = syl.length - syllIndexFromEnd;
  if(target < 0) return word;

  // Put acute on the last vowel of the target syllable.
  const vowels = new Set('αεηιουωΑΕΗΙΟΥΩ'.split(''));
  const acuteMap = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };

  let t = syl[target];
  let idx = -1;
  for(let i=t.length-1;i>=0;i--){ if(vowels.has(t[i])) { idx=i; break; } }
  if(idx===-1) return word;
  const ch = t[idx];
  t = t.slice(0,idx) + (acuteMap[ch]||ch) + t.slice(idx+1);
  syl[target]=t;
  return syl.join('');
}

function guessEndingType(input){
  const w = stripDiacritics(input.trim());
  const lower = w.toLowerCase();
  if(lower.endsWith('ιωτης') || lower.endsWith('ιώτης')) return 'iotes';
  if(lower.endsWith('ειτης') || lower.endsWith('είτης')) return 'eites';
  if(lower.endsWith('ιτης') || lower.endsWith('ίτης')) return 'ites';
  if(lower.endsWith('ατης') || lower.endsWith('άτης')) return 'ates';
  if(lower.endsWith('ητης') || lower.endsWith('ητής')) return 'etes';
  return 'auto';
}

function deriveForm(base, endingType){
  // Toy derivations: not historically rigorous.
  let b = base.trim();
  if(!b) return {form:'', note:'Type something.'};

  const b0 = b;
  b = stripDiacritics(b);

  // If user already typed a full adjective, keep it as stem for analysis.
  const lower = b.toLowerCase();

  function dropFinalVowel(s){
    return s.replace(/[αεηιουω]$/i,'');
  }

  let stem = b;
  let suffix = '';
  let note = '';

  if(endingType==='auto'){
    // Heuristic: -εια/-αία/-ια -> -ιώτης; -ιτης already -> keep; else default -άτης.
    if(/[εη]ια$/i.test(lower) || /εια$/i.test(lower) || /ια$/i.test(lower)) endingType='iotes';
    else if(/ιτης$/i.test(lower)) endingType='ites';
    else if(/ειτης$/i.test(lower)) endingType='eites';
    else if(/ητης$/i.test(lower)) endingType='etes';
    else endingType='ates';
  }

  if(endingType==='iotes'){
    // Μάρεια -> Μαρειώτης (drop final -α, keep -ει-)
    stem = dropFinalVowel(b);
    suffix = 'ιώτης';
    note = 'Toy rule: base (often in -εια/-ια) + -ιώτης.';
  } else if(endingType==='ates'){
    // base + -άτης
    stem = dropFinalVowel(b);
    suffix = 'άτης';
    note = 'Toy rule: base + -άτης.';
  } else if(endingType==='ites'){
    stem = dropFinalVowel(b);
    suffix = 'ίτης';
    note = 'Toy rule: base + -ίτης.';
  } else if(endingType==='eites'){
    stem = dropFinalVowel(b);
    suffix = 'είτης';
    note = 'Toy rule: base + -είτης.';
  } else if(endingType==='etes'){
    stem = dropFinalVowel(b);
    suffix = 'ητής';
    note = 'Toy rule: verbal-ish agent noun + -ητής.';
  }

  const form = stem + suffix;
  return {form, note, baseRaw:b0};
}

function accentSuggestion(word, endingType){
  // Return {accented, ruleText, tag}
  const base = stripDiacritics(word);
  const lower = base.toLowerCase();

  // Herodian-inspired toy rules:
  // -ητής verbal => oxytone (ultima)
  // -άτης non-verbal => barytone (penult) [toy]
  // -ίτης (long i) and -είτης => barytone (penult) [toy]
  // -ιώτης: often barytone (penult) [toy]

  let targetFromEnd = 2; // penult default barytone
  let rule = 'Toy default: barytone (accent not on the last syllable).';
  let tag = 'barytone';

  if(endingType==='auto') endingType = guessEndingType(base);

  if(endingType==='etes' || /ητης$/i.test(lower)){
    targetFromEnd = 1;
    rule = 'Herodian: verbal -ητής (e.g. θεατής, πειρατής) is oxytone → accent on ultima.';
    tag = 'oxytone';
  } else if(endingType==='ates' || /ατης$/i.test(lower)){
    targetFromEnd = 2;
    rule = 'Herodian: non-verbal -ᾱτης is barytone (e.g. Εὐφράτης, Νιφάτης) → accent on penult (toy).';
    tag = 'barytone';
  } else if(endingType==='ites' || /ιτης$/i.test(lower)){
    targetFromEnd = 2;
    rule = 'Herodian: -ίτης (with long ι) is barytone (e.g. πολίτης, τεμενίτης) → accent on penult (toy).';
    tag = 'barytone';
  } else if(endingType==='eites' || /ειτης$/i.test(lower)){
    targetFromEnd = 2;
    rule = 'Herodian: -είτης is barytone → accent on penult (toy).';
    tag = 'barytone';
  } else if(endingType==='iotes' || /ιωτης$/i.test(lower)){
    targetFromEnd = 2;
    rule = 'Toy: -ιώτης ethnics often behave barytonically → accent on penult (toy).';
    tag = 'barytone';
  }

  const accented = addAcuteOnSyllable(base, targetFromEnd);
  return {accented, ruleText: rule, tag};
}

// --- UI wiring ---
const inp = $('#inp');
const endingSel = $('#ending');
const go = $('#go');
const strip = $('#strip');
const showSyll = $('#showSyll');
const mainOut = $('#mainOut');
const ruleOut = $('#ruleOut');
const accentPlay = $('#accentPlay');
const accentMeta = $('#accentMeta');
const left = $('#left');
const right = $('#right');

let playWord = '';
let playSyl = [];
let playPosFromEnd = 2;

function setPlay(word, suggestedFromEnd=2){
  playWord = stripDiacritics(word);
  playSyl = syllabifyToy(playWord);
  playPosFromEnd = Math.min(Math.max(1, suggestedFromEnd), Math.max(1, playSyl.length));
  renderPlay();
}

function renderPlay(){
  if(!playWord){
    accentPlay.textContent = '—';
    accentMeta.textContent = '—';
    return;
  }
  const accented = addAcuteOnSyllable(playWord, playPosFromEnd);
  accentPlay.textContent = accented;
  const posName = (playPosFromEnd===1?'ultima': playPosFromEnd===2?'penult':'antepenult');
  accentMeta.textContent = `Toy syllables: ${playSyl.join('·')}  | accent on ${posName}`;
}

function currentMode(){
  return ($('input[name=mode]:checked')||{}).value || 'derive';
}

function run(){
  let w = inp.value.trim();
  if(!w){
    mainOut.textContent = '—';
    ruleOut.textContent = 'Type a Greek word above.';
    setPlay('');
    return;
  }

  const mode = currentMode();
  const chosen = endingSel.value;

  const rawHadAccent = hasAccent(w);
  if(strip.checked) w = stripDiacritics(w);

  if(mode==='derive'){
    const d = deriveForm(w, chosen);
    const endType = (chosen==='auto') ? guessEndingType(d.form) : chosen;
    const acc = accentSuggestion(d.form, endType);

    const syllInfo = showSyll.checked ? `  [${syllabifyToy(acc.accented).join('·')}]` : '';
    const tagClass = acc.tag==='oxytone' ? 'bad' : 'good';
    const tagLabel = acc.tag==='oxytone' ? 'oxytone' : 'barytone';

    mainOut.innerHTML = `${escapeHtml(acc.accented)}${syllInfo} <span class="tag ${tagClass}">${tagLabel}</span>`;
    ruleOut.textContent = `${d.note} ${acc.ruleText}` + (rawHadAccent && strip.checked ? ' (Input accents were ignored.)' : '');

    setPlay(acc.accented, acc.tag==='oxytone' ? 1 : 2);
  } else {
    const endType = (chosen==='auto') ? guessEndingType(w) : chosen;
    const acc = accentSuggestion(w, endType);
    const syllInfo = showSyll.checked ? `  [${syllabifyToy(acc.accented).join('·')}]` : '';
    const tagClass = acc.tag==='oxytone' ? 'bad' : 'good';
    const tagLabel = acc.tag==='oxytone' ? 'oxytone' : 'barytone';

    mainOut.innerHTML = `${escapeHtml(acc.accented)}${syllInfo} <span class="tag ${tagClass}">${tagLabel}</span>`;
    ruleOut.textContent = acc.ruleText + (rawHadAccent && strip.checked ? ' (Input accents were ignored.)' : '');

    setPlay(acc.accented, acc.tag==='oxytone' ? 1 : 2);
  }
}

function escapeHtml(s){
  return (s+'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

// events
['input','change'].forEach(ev=>{
  inp.addEventListener(ev, ()=>{ if(ev==='input') run(); });
  endingSel.addEventListener(ev, run);
  strip.addEventListener(ev, run);
  showSyll.addEventListener(ev, run);
  $$('.radio input').forEach(r=>r.addEventListener(ev, run));
});

go.addEventListener('click', run);

$$('.chip').forEach(b=>{
  b.addEventListener('click', ()=>{
    inp.value = b.dataset.sample;
    run();
    inp.focus();
  });
});

left.addEventListener('click', ()=>{
  if(!playWord) return;
  playPosFromEnd = Math.min(playSyl.length, playPosFromEnd+1);
  renderPlay();
});
right.addEventListener('click', ()=>{
  if(!playWord) return;
  playPosFromEnd = Math.max(1, playPosFromEnd-1);
  renderPlay();
});

// init
inp.value = 'Μάρεια';
run();

