  --muted:#b9c0ff;
  --faint:#8b93d6;
  --accent:#7cf0c6;
  --accent2:#9bb2ff;
  --danger:#ff7a9a;
  --line:rgba(255,255,255,.10);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
