}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, #1b2150 0%, var(--bg) 55%);color:var(--text);font:15px/1.45 system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,"Noto Sans",sans-serif}
.wrap{max-width:980px;margin:0 auto;padding:22px 16px 40px}
.head{padding:10px 12px 18px}
h1{margin:0 0 6px;font-size:22px;letter-spacing:.2px}
h2{margin:0 0 10px;font-size:16px}
.sub{margin:0;color:var(--muted)}
.greek{font-family: "Noto Serif", "Times New Roman", Georgia, serif; font-size:1.05em}
.panel{background:linear-gradient(180deg,var(--panel),var(--panel2));border:1px solid var(--line);border-radius:14px;padding:14px 14px 16px;box-shadow:var(--shadow);margin:12px 0}
.controls{padding:4px 2px 10px}
.lbl{display:block;margin:0 0 8px;color:var(--muted)}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.in{flex:1;min-width:240px;padding:10px 12px;border-radius:12px;border:1px solid var(--line);background:rgba(255,255,255,.06);color:var(--text);outline:none}
.in:focus{border-color:rgba(124,240,198,.55);box-shadow:0 0 0 3px rgba(124,240,198,.12)}
.btn{padding:10px 12px;border-radius:12px;border:1px solid rgba(124,240,198,.35);background:rgba(124,240,198,.12);color:var(--text);cursor:pointer}
.btn:hover{background:rgba(124,240,198,.18)}
.btn:active{transform:translateY(1px)}
.btn.ghost{border-color:var(--line);background:rgba(255,255,255,.06)}
.btn.ghost:hover{background:rgba(255,255,255,.09)}
.opts{display:grid;grid-template-columns:1fr;gap:6px;margin:10px 0 0}
.opt{display:flex;gap:8px;align-items:flex-start;color:var(--muted)}
.opt input{margin-top:2px}
.hint{margin:10px 0 0;color:var(--faint)}
.out{border-top:1px solid var(--line);margin-top:10px;padding-top:12px}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}
.card{border:1px solid var(--line);border-radius:14px;padding:10px 10px 10px;background:rgba(255,255,255,.04)}
.card .form{font-size:18px;margin:0 0 6px}
.card .form .suf{color:var(--accent);font-weight:650}
.card .meta{margin:0;color:var(--muted);font-family:var(--mono);font-size:12px}
.card .note{margin:8px 0 0;color:var(--faint);font-size:13px}
.pill{display:inline-block;padding:2px 8px;border-radius:999px;border:1px solid var(--line);background:rgba(255,255,255,.04);color:var(--muted);font-size:12px}
.mini{margin-top:10px;border:1px solid var(--line);border-radius:12px;padding:8px 10px;background:rgba(255,255,255,.03)}
.mini summary{cursor:pointer;color:var(--muted)}
.miniBody{color:var(--muted)}
.bank{display:flex;flex-wrap:wrap;gap:8px}
.w{border:1px solid var(--line);background:rgba(255,255,255,.04);color:var(--text);padding:6px 10px;border-radius:999px;cursor:pointer;user-select:none}
.w:hover{background:rgba(255,255,255,.07)}
.w.good{border-color:rgba(124,240,198,.45)}
.w.bad{border-color:rgba(255,122,154,.45)}
.quizOut{margin-top:10px;border-top:1px solid var(--line);padding-top:10px;color:var(--muted)}
.quizOut .big{font-size:18px;color:var(--text)}
.quizOut .split{font-family:var(--mono);font-size:12px;color:var(--faint)}
.foot{padding:6px 12px;color:var(--faint)}
.tag{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:2px 8px;margin-right:8px;background:rgba(255,255,255,.03);color:var(--muted)}
@media (prefers-reduced-motion: reduce){
  .btn:active{transform:none}
}

passages.gadget_js:
(() => {
  const $ = (sel) => document.querySelector(sel);
  const cards = $('#cards');
  const inWord = $('#inWord');
  const optStrip = $('#optStrip');
  const optDoubleM = $('#optDoubleM');
  const btnMake = $('#btnMake');
  const btnRandom = $('#btnRandom');

  // A small bank of -ίτης words from the passage (plus a couple of near-misses for the quiz).
  const bank = [
    'ζευγίτης','στυλίτης','ἑρκίτης','Θερσίτης','μεσίτης','στεφανίτης','πυρίτης','ὁδίτης','ἐπαλξίτης','μαγνίτης','φεγγίτης','λυχνίτης','αἰθερίτης','ἀγρίτης','τοπίτης','χωρίτης','ἑδρίτης','Ὠρίτης','Ὑθμίτης','Αὐσχίτης','Ἀμαλεκίτης','Αὐαλίτης','Ἀμμανίτης','Ἀμανίτης','Αὐσονίτης','Βοιίτης','Γεβεωνίτης','Γολομίτης','Διοχίτης','Ἁρματίτης','Ἐπαρίτης','Εὐωνυμίτης','Ἰβηρίτης','Νεφθαλίτης','Ὁμηρίτης','Ὀρβίτης','Σαυνίτης','Τρωΐτης','ἀστίτης','προαστίτης','ἀσπιδίτης','παραιγιαλίτης',
    // distractors (not in -ίτης)
    'Βυζάντιος','Δουλιχιεύς','προάστιον'
  ];

  const samplesForInput = [
    'χώρα','ἄστυ','Ἴβηρ','Ὠρί','Αὐσον','Ἀμμάν','Ἀμάν','αἰθήρ','ἀγρός','τοπός','ὁδός','κώμη'
  ];

  // --- Greek normalization helpers (toy-level) ---
  // Remove combining diacritics (works for polytonic in NFC/NFD mixtures).
  function stripDiacritics(s){
    return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  }

  function tidy(s){
    return (s || '').trim().replace(/\s+/g,' ');
  }

  function endsWithAny(s, arr){
    return arr.some(x => s.endsWith(x));
  }

  // Very rough “base -> -ίτης” builder.
  // Strategy: create a stem guess, then add "ίτης".
  function buildItesForms(raw){
    const original = tidy(raw);
    if(!original) return [];

    const base0 = optStrip.checked ? stripDiacritics(original) : original;
    // remove trailing punctuation
    let base = base0.replace(/[··.,;:!?\)\(\[\]«»"']/g,'');

    // If user types a phrase, take last token as base.
    const parts = base.split(' ');
    base = parts[parts.length - 1];

    // Common endings to drop before adding -ίτης
    // (toy rules inspired by examples like χώρα→χωρ-ίτης, ἄστυ→ἀστ-ίτης)
    let stem = base;
    let rule = 'default: stem + ίτης';

    // If they already gave something ending in -ιτης/-ίτης, just echo.
    const baseStripped = stripDiacritics(base).toLowerCase();
    if(baseStripped.endsWith('ιτης')){
      return [{
        form: base,
        stem: base.slice(0, Math.max(0, base.length - 3)),
        rule: 'already looks like -ίτης',
        note: 'Try entering the base without the suffix.'
      }];
    }

    // Drop common nominative endings
    const lower = stripDiacritics(base).toLowerCase();

    if(endsWithAny(lower, ['α','η'])){
      stem = base.slice(0, -1);
      rule = 'drop -α/-η → +ίτης';
    } else if(endsWithAny(lower, ['ος','ον'])){
      stem = base.slice(0, -2);
      rule = 'drop -ος/-ον → +ίτης';
    } else if(endsWithAny(lower, ['υ'])){
      stem = base.slice(0, -1);
      rule = 'drop -υ → +ίτης (toy)';
    } else if(endsWithAny(lower, ['ι'])){
      stem = base.slice(0, -1);
      rule = 'drop -ι → +ίτης';
    }

    // If stem ends with ρ, often looks nice as -ριτης (Iber → Iberites).
    // We just add -ίτης; the ρ stays.

    // Special: -μαν- base with optional -μμ- (Ἀμμανίτης)
    const forms = [];
    const stemPlain = stem;

    // Accent game: we always show suffix with acute on iota: ίτης.
    const suf = 'ίτης';

    // Basic form
    forms.push({
      form: stemPlain + suf,
      stem: stemPlain,
      rule,
      note: 'Accent toy: acute on the suffix iota (…-ίτης).'
    });

    // Alternative: if stem ends in a vowel, offer a "bridge" -ι-
    const last = stripDiacritics(stemPlain).slice(-1).toLowerCase();
    if(['α','ε','η','ι','ο','υ','ω'].includes(last)){
      forms.push({
        form: stemPlain + 'ι' + suf,
        stem: stemPlain + 'ι',
        rule: 'add a linking -ι- → +ίτης',
        note: 'Some formations feel smoother with an extra -ι-.'
      });
    }

    // Double-m option
    if(optDoubleM.checked){
      const lowStem = stripDiacritics(stemPlain).toLowerCase();
      if(lowStem.endsWith('μαν') || lowStem.endsWith('αμαν') || lowStem.endsWith('αμμαν')){
        // crude: replace final ν with nothing and insert μμ before ίτης
        const baseNoN = stemPlain.replace(/ν$/,'');
        forms.push({
          form: baseNoN + 'μμ' + suf,
          stem: baseNoN + 'μμ',
          rule: 'offer -μμ- before -ίτης (cf. Ἀμμανίτης)',
          note: 'Herodian notes spelling with double μ in Ἀμμανίτης.'
        });
      }
    }

    // De-duplicate
    const seen = new Set();
    return forms.filter(f => {
      const key = f.form;
      if(seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  }

  function renderCards(forms){
    cards.innerHTML = '';
    if(!forms.length){
      cards.innerHTML = '<div class="card"><p class="form">(nothing yet)</p><p class="meta">Type a base and click “Make -ίτης”.</p></div>';
      return;
    }
    for(const f of forms){
      const div = document.createElement('div');
      div.className = 'card';
      const stem = f.stem || '';
      const suf = 'ίτης';
      let shown = f.form;
      // Highlight suffix if present
      if(shown.endsWith(suf)){
        const pre = shown.slice(0, -suf.length);
        shown = `${escapeHtml(pre)}<span class="suf">${escapeHtml(suf)}</span>`;
      } else {
        shown = escapeHtml(shown);
      }
      div.innerHTML = `
        <p class="form greek">${shown}</p>
        <p class="meta">stem: <span class="pill greek">${escapeHtml(stem)}</span> + <span class="pill greek">${escapeHtml(suf)}</span></p>
        <p class="note">${escapeHtml(f.rule)}${f.note ? ' — ' + escapeHtml(f.note) : ''}</p>
      `;
      cards.appendChild(div);
    }
  }

  function escapeHtml(s){
    return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  function make(){
    const forms = buildItesForms(inWord.value);
    renderCards(forms);
  }

  btnMake.addEventListener('click', make);
  inWord.addEventListener('keydown', (e) => {
    if(e.key === 'Enter') make();
  });

  btnRandom.addEventListener('click', () => {
    const s = samplesForInput[Math.floor(Math.random()*samplesForInput.length)];
    inWord.value = s;
    make();
  });

  // --- Quiz bank ---
  const bankEl = $('#wordBank');
  const quizOut = $('#quizOut');

  function isItes(w){
    return stripDiacritics(w).toLowerCase().endsWith('ιτης');
  }

  function splitItes(w){
    // naive split at last "ιτης" (stripped)
    const stripped = stripDiacritics(w);
    const idx = stripped.toLowerCase().lastIndexOf('ιτης');
    if(idx < 0) return null;
    // Map index back to original string length approximately by using same length (works if only diacritics differ)
    const pre = w.slice(0, idx);
    const suf = w.slice(idx);
    return {pre, suf};
  }

  function renderBank(){
    bankEl.innerHTML = '';
    for(const w of bank){
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'w greek';
      b.textContent = w;
      b.addEventListener('click', () => {
        const ok = isItes(w);
        b.classList.remove('good','bad');
        b.classList.add(ok ? 'good' : 'bad');

        if(ok){
          const sp = splitItes(w);
          const pre = sp ? sp.pre : w;
          quizOut.innerHTML = `
            <div class="big greek">${escapeHtml(w)} ✓ ends in -ίτης</div>
            <div class="split">split (toy): ${escapeHtml(pre)} + ίτης</div>
          `;
        } else {
          quizOut.innerHTML = `
            <div class="big greek">${escapeHtml(w)} ✗ not -ίτης</div>
            <div class="split">Hint: many in the passage end with <span class="greek">-ίτης</span> (ethnic/inhabitant adjectives).</div>
          `;
        }
      });
      bankEl.appendChild(b);
    }
  }

  // init
  renderCards([]);
  renderBank();
  inWord.value = 'χώρα';
  make();
})();

