:root{
  --bg:#0f1220;
  --card:#171a2b;
  --card2:#1d2136;
  --text:#e9ecff;
  --muted:#b7bddb;
  --line:#2a2f4a;
  --accent:#7dd3fc;
  --good:#86efac;
  --bad:#fca5a5;
  --warn:#fde68a;
}
*{box-sizing:border-box}
body{
  margin:0;
  font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Arial, "Noto Sans", "Liberation Sans", sans-serif;
  background: radial-gradient(1200px 800px at 20% 0%, #1a1f3a 0%, var(--bg) 55%);
  color:var(--text);
}
.wrap{max-width:980px;margin:0 auto;padding:22px}
.hdr{display:flex;gap:18px;align-items:flex-start;margin-bottom:14px}
h1{font-size:22px;margin:0 0 6px 0;letter-spacing:.2px}
.sub{margin:0;color:var(--muted);line-height:1.35}
.card{
  background: linear-gradient(180deg, var(--card) 0%, var(--card2) 100%);
