  border-radius:14px;
  padding:16px;
  margin:14px 0;
  box-shadow: 0 10px 30px rgba(0,0,0,.25);
}
.card h2{margin:0 0 10px 0;font-size:16px}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:10px 0}
.lbl{min-width:220px;color:var(--muted);font-size:13px}
.txt{
  flex:1;
  min-width:260px;
  padding:10px 12px;
  border-radius:10px;
  border:1px solid var(--line);
  background:#0c0f1c;
  color:var(--text);
  font-size:16px;
}
.sel{
  padding:10px 12px;
  border-radius:10px;
  border:1px solid var(--line);
  background:#0c0f1c;
  color:var(--text);
  font-size:14px;
}
.btn{
  padding:10px 12px;
  border-radius:10px;
  border:1px solid #3a4270;
  background: #24306a;
  color:var(--text);
  cursor:pointer;
  font-weight:600;
}
.btn:hover{filter:brightness(1.08)}
.btn:active{transform:translateY(1px)}
.btn.ghost{background:transparent;border-color:var(--line);color:var(--muted)}
.out{
  margin-top:10px;
  border-top:1px solid var(--line);
  padding-top:10px;
}
.outRow{display:grid;grid-template-columns:160px 1fr;gap:10px;padding:6px 0}
.k{color:var(--muted);font-size:13px}
.v{color:var(--text)}
.big{font-size:22px;letter-spacing:.2px}
.greek{font-family: "Noto Serif", "Times New Roman", Times, serif}
.mono{font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace}
.help{margin-top:10px;color:var(--muted)}
.help summary{cursor:pointer}
.help li{margin:6px 0}
.small{color:var(--muted);font-size:13px;line-height:1.35}
.game{display:grid;grid-template-columns: 1fr 1.2fr;gap:14px;align-items:start}
.pool, .bucketBody{
  min-height:120px;
  padding:10px;
  border-radius:12px;
  border:1px dashed #3a4270;
  background:#0c0f1c;
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  align-content:flex-start;
}
.buckets{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.bucket{border:1px solid var(--line);border-radius:12px;overflow:hidden;background:#0c0f1c}
.bucketTitle{padding:10px 10px 8px 10px;border-bottom:1px solid var(--line);color:var(--muted);font-size:13px}
.bucketBody{border:none;border-radius:0;min-height:160px}
.chip{
  user-select:none;
  padding:7px 10px;
  border-radius:999px;
  border:1px solid #3a4270;
  background:#121735;
  cursor:pointer;
  font-size:14px;
}
.chip:hover{border-color:var(--accent)}
.chip[data-state="placed"]{background:#0f1a2a}
.gameBtns{display:flex;gap:10px;margin-top:10px}
.score{margin-top:10px;padding:10px;border-radius:12px;border:1px solid var(--line);background:#0c0f1c;color:var(--muted)}
.score strong{color:var(--text)}
.good{color:var(--good)}
.bad{color:var(--bad)}
.warn{color:var(--warn)}
.ftr{margin-top:10px;text-align:center}
@media (max-width: 860px){
  .game{grid-template-columns:1fr}
  .outRow{grid-template-columns:1fr}
  .lbl{min-width:160px}
}

passages.gadget_js:
(() => {
  const $ = (sel) => document.querySelector(sel);

  // --- Polytonic helpers (toy-level) ---
  const combining = {
    acute: "\u0301",
    grave: "\u0300",
    circumflex: "\u0342",
    diaeresis: "\u0308",
    smooth: "\u0313",
    rough: "\u0314",
    iotaSub: "\u0345",
    macron: "\u0304",
    breve: "\u0306"
  };

  const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);

  function nfd(s){ return (s||"").normalize('NFD'); }
  function nfc(s){ return (s||"").normalize('NFC'); }

  function stripAccentMarks(s){
    // remove acute/grave/circumflex only
    const d = nfd(s);
    const out = [];
    for (const ch of d) {
      if (ch === combining.acute || ch === combining.grave || ch === combining.circumflex) continue;
      out.push(ch);
    }
    return nfc(out.join(""));
  }

  function lastVowelIndexNFD(d){
    // returns index in NFD string of last vowel base letter
    for (let i = d.length - 1; i >= 0; i--) {
      const ch = d[i];
      if (vowels.has(ch)) return i;
    }
    return -1;
  }

  function hasFinalAcute(word){
    const d = nfd(word);
    const i = lastVowelIndexNFD(d);
    if (i < 0) return false;
    // scan forward through combining marks after the vowel
    for (let j = i+1; j < d.length; j++) {
      const ch = d[j];
      if (vowels.has(ch)) break;
      if (ch === combining.acute) return true;
    }
    return false;
  }

  function addFinalAcute(word){
    // add acute to last vowel, preserving other diacritics
    const d = nfd(word);
    const i = lastVowelIndexNFD(d);
    if (i < 0) return word;

    // If already has acute on that vowel, do nothing
    let j = i+1;
    while (j < d.length && !vowels.has(d[j])) {
      if (d[j] === combining.acute) return nfc(d);
      j++;
    }

    // Insert acute after existing combining marks (but before next base letter)
    const before = d.slice(0, j);
    const after = d.slice(j);
    return nfc(before + combining.acute + after);
  }

  function removeFinalAcute(word){
    const d = nfd(word);
    const i = lastVowelIndexNFD(d);
    if (i < 0) return word;
    let out = "";
    for (let k = 0; k < d.length; k++) {
      const ch = d[k];
      if (k > i && ch === combining.acute) {
        // remove only if it belongs to the last vowel (i.e., before any later vowel)
        // check if there is any vowel between i and k (there isn't by construction)
        // but ensure no later vowel has started
        // We'll remove the first acute after i until next vowel.
        // To keep it simple: remove acute marks after i if no vowel has occurred since i.
        // We'll track.
      }
    }
    // Implement with state
    let seenLastVowel = false;
    let passedLastVowel = false;
    const lastIdx = i;
    for (let k = 0; k < d.length; k++) {
      const ch = d[k];
      if (k === lastIdx) { seenLastVowel = true; passedLastVowel = true; out += ch; continue; }
      if (passedLastVowel) {
        if (vowels.has(ch)) {
          // shouldn't happen, but stop removing
          passedLastVowel = false;
          out += ch;
          continue;
        }
        if (ch === combining.acute) continue;
      }
      out += ch;
    }
    return nfc(out);
  }

  function syllableSketch(word){
    // crude: count vowel groups in stripped word
    const s = stripAccentMarks(word);
    const d = nfd(s);
    let groups = 0;
    let inV = false;
    for (const ch of d) {
      if (vowels.has(ch)) {
        if (!inV) groups++;
        inV = true;
      } else {
        // combining marks ignored
        if (ch >= "\u0300" && ch <= "\u036F") continue;
        inV = false;
      }
    }
    const ending = (s.endsWith("στης") || s.endsWith("στής") || s.endsWith("ΣΤΗΣ") || s.endsWith("ΣΤΉΣ")) ? "-στης" :
                   (s.endsWith("εστης") || s.endsWith("έστης") || s.endsWith("ΕΣΤΗΣ") || s.endsWith("ΈΣΤΗΣ")) ? "-εστης" :
                   (s.endsWith("της") || s.endsWith("τής") || s.endsWith("ΤΗΣ") || s.endsWith("ΤΉΣ")) ? "-της" : "(other)";
    return `${groups} vowel-group(s); ending: ${ending}`;
  }

  function autoMode(word){
    const s = stripAccentMarks(word);
    const lower = s.toLowerCase();
    if (lower.endsWith("εστης")) return "estes_nonadj";
    if (lower.endsWith("στης")) return "stes_verbal";
    if (lower.endsWith("της")) return "tes_attic";
    return "auto";
  }

  function applyRule(word, mode){
    const clean = word.trim();
    if (!clean) return {out:"", explain:""};

    let chosen = mode;
    if (mode === "auto") {
      chosen = autoMode(clean);
    }

    if (chosen === "stes_verbal") {
      const out = addFinalAcute(removeFinalAcute(clean));
      return {
        out,
        explain: "Treated as verbal/polysyllabic -στης → make it oxytone by adding a final acute (…στής)."
      };
    }
    if (chosen === "tes_attic") {
      const out = addFinalAcute(removeFinalAcute(clean));
      return {
        out,
        explain: "Treated as -τής (Attic-type examples) → oxytone by adding a final acute (…τής)."
      };
    }
    if (chosen === "estes_nonadj") {
      const out = removeFinalAcute(clean);
      return {
        out,
        explain: "Treated as non-adjectival -εστης name → barytone: remove any final acute (toy simplification)."
      };
    }

    // fallback
    return {
      out: clean,
      explain: "Auto could not recognize the ending; no change made. Try choosing a type manually."
    };
  }

  // --- UI wiring ---
  const inWord = $("#inWord");
  const mode = $("#mode");
  const outWord = $("#outWord");
  const outExplain = $("#outExplain");
  const outSyl = $("#outSyl");

  function render(){
    const w = inWord.value;
    const m = mode.value;
    const {out, explain} = applyRule(w, m);
    outWord.textContent = out || "—";
    outExplain.textContent = explain || "Type a word and click Apply accent.";
    outSyl.textContent = w.trim() ? syllableSketch(w) : "—";
  }

  $("#btnApply").addEventListener('click', render);
  inWord.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') render();
  });

  $("#btnClear").addEventListener('click', () => {
    inWord.value = "";
    mode.value = "auto";
    outWord.textContent = "—";
    outExplain.textContent = "Type a word and click Apply accent.";
    outSyl.textContent = "—";
    inWord.focus();
  });

  const examples = [
    {w:"λυριστης", mode:"stes_verbal"},
    {w:"λεπιστης", mode:"stes_verbal"},
    {w:"ὑβριστης", mode:"stes_verbal"},
    {w:"ἐρανιστης", mode:"stes_verbal"},
    {w:"δικαστης", mode:"stes_verbal"},
    {w:"ἡλιαστης", mode:"stes_verbal"},
    {w:"δανειστης", mode:"stes_verbal"},
    {w:"παλαιστης", mode:"stes_verbal"},
    {w:"χηρωστης", mode:"stes_verbal"},
    {w:"καθαρτης", mode:"tes_attic"},
    {w:"ἀμυντης", mode:"tes_attic"},
    {w:"φαιδρυντης", mode:"tes_attic"},
    {w:"ποικιλτης", mode:"tes_attic"},
    {w:"καλλυντης", mode:"tes_attic"},
    {w:"πραϋντης", mode:"tes_attic"},
    {w:"Ὀρεστης", mode:"estes_nonadj"},
    {w:"Ὀφελεστης", mode:"estes_nonadj"},
    {w:"Θυεστης", mode:"estes_nonadj"},
    {w:"Ἀκεστης", mode:"estes_nonadj"},
    {w:"Πενεστης", mode:"estes_nonadj"},
    {w:"Κυρρεστης", mode:"estes_nonadj"},
    {w:"Πιαστης", mode:"estes_nonadj"},
    {w:"Προναστης", mode:"estes_nonadj"},
    {w:"Ἀσβυστης", mode:"estes_nonadj"}
  ];

  $("#btnRandom").addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inWord.value = ex.w;
    mode.value = "auto";
    render();
  });

  // --- Mini-game ---
  const pool = $("#pool");
  const bOx = $("#bOx");
  const bBa = $("#bBa");
  const score = $("#score");

  const chipsData = [
    {t:"λυριστής", cls:"oxytone"},
    {t:"λεπιστής", cls:"oxytone"},
    {t:"ὑβριστής", cls:"oxytone"},
    {t:"ἐρανιστής", cls:"oxytone"},
    {t:"δικαστής", cls:"oxytone"},
    {t:"ἡλιαστής", cls:"oxytone"},
    {t:"δανειστής", cls:"oxytone"},
    {t:"παλαιστής", cls:"oxytone"},
    {t:"χηρωστής", cls:"oxytone"},
    {t:"καθαρτής", cls:"oxytone"},
    {t:"ἀμυντής", cls:"oxytone"},
    {t:"πραϋντής", cls:"oxytone"},
    {t:"Ὀρέστης", cls:"barytone"},
    {t:"Θυέστης", cls:"barytone"},
    {t:"Πενέστης", cls:"barytone"},
    {t:"Κυρρέστης", cls:"barytone"},
    {t:"Προνάστης", cls:"barytone"},
    {t:"Ἀσβύστης", cls:"barytone"}
  ];

  function shuffle(a){
    const arr = a.slice();
    for (let i = arr.length-1; i>0; i--) {
      const j = Math.floor(Math.random()*(i+1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  function makeChip(text, cls){
    const el = document.createElement('button');
    el.type = 'button';
    el.className = 'chip greek';
    el.textContent = text;
    el.dataset.answer = cls;
    el.dataset.state = 'pool';
    el.addEventListener('click', () => {
      // cycle: pool -> ox -> ba -> pool
      if (el.dataset.state === 'pool') {
        bOx.appendChild(el);
        el.dataset.state = 'ox';
        el.dataset.stateLabel = 'oxytone';
        el.dataset.state = 'placed';
        el.dataset.bucket = 'oxytone';
      } else if (el.dataset.bucket === 'oxytone') {
        bBa.appendChild(el);
        el.dataset.bucket = 'barytone';
      } else if (el.dataset.bucket === 'barytone') {
        pool.appendChild(el);
        el.dataset.state = 'pool';
        delete el.dataset.bucket;
      }
      score.textContent = '—';
    });
    return el;
  }

  function resetGame(){
    pool.innerHTML = '';
    bOx.innerHTML = '';
    bBa.innerHTML = '';
    score.textContent = '—';
    const items = shuffle(chipsData);
    for (const it of items) pool.appendChild(makeChip(it.t, it.cls));
  }

  $("#btnResetGame").addEventListener('click', resetGame);

  $("#btnCheck").addEventListener('click', () => {
    const all = [...pool.querySelectorAll('.chip'), ...bOx.querySelectorAll('.chip'), ...bBa.querySelectorAll('.chip')];
    let placed = 0;
    let correct = 0;
    for (const el of all) {
      const bucket = el.dataset.bucket;
      if (!bucket) continue;
      placed++;
      if (bucket === el.dataset.answer) correct++;
    }
    const total = chipsData.length;
    const unplaced = total - placed;
    let msg = `<strong>${correct}</strong> correct out of <strong>${placed}</strong> placed.`;
    if (unplaced) msg += ` <span class="warn">(${unplaced} still in the pool.)</span>`;
    msg += `\nTip: the passage’s rule is about classes; exceptions exist—this game follows the passage’s examples.`;
    score.innerHTML = msg;
  });

  // init
  resetGame();
})();

