:root{
  --bg:#0f1220;
  --panel:#151a2e;
  --card:#1b2140;
  --text:#e9ecff;
  --muted:#b7bce6;
  --faint:#7f86c7;
  --accent:#7cf0c5;
  --warn:#ffcf6e;
  --bad:#ff7a90;
  --line:rgba(255,255,255,.10);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
}
*{box-sizing:border-box}
body{margin:0; font-family:var(--sans); background:radial-gradient(1200px 600px at 20% 0%, #1a2050 0%, var(--bg) 55%); color:var(--text)}
.wrap{max-width:1050px; margin:0 auto; padding:22px 16px 28px}
.head{display:flex; gap:16px; align-items:flex-start; justify-content:space-between; margin-bottom:14px}
h1{font-size:20px; margin:0 0 6px; letter-spacing:.2px}
.sub{margin:0; color:var(--muted); line-height:1.35; font-size:13.5px}
.panel{background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02)); border:1px solid var(--line); border-radius:14px; padding:14px; box-shadow:var(--shadow)}
.grid{display:grid; grid-template-columns: 1.05fr .95fr; gap:14px}
@media (max-width: 900px){.grid{grid-template-columns:1fr}}
.card{background:var(--card); border:1px solid var(--line); border-radius:12px; padding:14px}
.card h2{margin:0 0 10px; font-size:15px; color:var(--text)}
.lbl{display:block; font-size:12px; color:var(--muted); margin-bottom:6px}
.inp{width:100%; padding:10px 12px; border-radius:10px; border:1px solid rgba(255,255,255,.14); background:#0f1430; color:var(--text); font-size:16px; outline:none}
.inp:focus{border-color:rgba(124,240,197,.55); box-shadow:0 0 0 3px rgba(124,240,197,.12)}
.row{display:flex; gap:10px; margin-top:10px}
.btn{border:1px solid rgba(255,255,255,.16); background:rgba(124,240,197,.14); color:var(--text); padding:9px 12px; border-radius:10px; cursor:pointer; font-weight:650}
.btn:hover{filter:brightness(1.05)}
.btn:active{transform:translateY(1px)}
.btn.ghost{background:transparent; color:var(--muted)}
.opts{margin-top:10px; padding-top:10px; border-top:1px dashed rgba(255,255,255,.14)}
.opt{display:flex; gap:8px; align-items:flex-start; margin:8px 0; color:var(--muted); font-size:13px}
.opt input{margin-top:2px}
.help{margin-top:10px; border-top:1px dashed rgba(255,255,255,.14); padding-top:10px}
.help summary{cursor:pointer; color:var(--accent); font-weight:650; font-size:13px}
.helpBody{color:var(--muted); font-size:13px; line-height:1.35}
.helpBody ul{margin:8px 0 0 18px}
.out{background:#0f1430; border:1px solid rgba(255,255,255,.14); border-radius:12px; padding:12px; min-height:160px}
.muted{color:var(--muted)}
.kv{display:grid; grid-template-columns: 160px 1fr; gap:8px 10px; align-items:start; font-size:13.5px}
.k{color:var(--faint)}
.v{color:var(--text)}
.badge{display:inline-block; padding:2px 8px; border-radius:999px; font-size:12px; border:1px solid rgba(255,255,255,.16); margin-right:6px}
.badge.ok{background:rgba(124,240,197,.12); color:var(--accent)}
.badge.warn{background:rgba(255,207,110,.12); color:var(--warn)}
.badge.bad{background:rgba(255,122,144,.12); color:var(--bad)}
.big{font-family:var(--mono); font-size:20px; letter-spacing:.2px}
.mini{margin-top:12px}
.mini h3{margin:0 0 8px; font-size:13px; color:var(--muted)}
.chips{display:flex; flex-wrap:wrap; gap:8px}
.chip{border:1px solid rgba(255,255,255,.16); background:rgba(255,255,255,.04); color:var(--text); padding:6px 10px; border-radius:999px; cursor:pointer; font-size:13px}
.chip:hover{border-color:rgba(124,240,197,.45)}
.foot{margin-top:12px}
.note{color:var(--muted); font-size:12.5px; line-height:1.35}

