const $ = (sel) => document.querySelector(sel);

const vowels = new Set([
  'α','ε','η','ι','ο','υ','ω',
  'ά','έ','ή','ί','ό','ύ','ώ',
  'ἀ','ἁ','ἂ','ἃ','ἄ','ἅ','ἆ','ἇ',
  'ἐ','ἑ','ἒ','ἓ','ἔ','ἕ',
  'ἠ','ἡ','ἢ','ἣ','ἤ','ἥ','ἦ','ἧ',
  'ἰ','ἱ','ἲ','ἳ','ἴ','ἵ','ἶ','ἷ',
  'ὀ','ὁ','ὂ','ὃ','ὄ','ὅ',
  'ὐ','ὑ','ὒ','ὓ','ὔ','ὕ','ὖ','ὗ',
  'ὠ','ὡ','ὢ','ὣ','ὤ','ὥ','ὦ','ὧ',
  'ϊ','ΐ','ϋ','ΰ',
  'ᾳ','ᾴ','ᾲ','ᾷ','ᾀ','ᾁ','ᾂ','ᾃ','ᾄ','ᾅ','ᾆ','ᾇ',
  'ῃ','ῄ','ῂ','ῇ','ᾐ','ᾑ','ᾒ','ᾓ','ᾔ','ᾕ','ᾖ','ᾗ',
  'ῳ','ῴ','ῲ','ῷ','ᾠ','ᾡ','ᾢ','ᾣ','ᾤ','ᾥ','ᾦ','ᾧ'
]);

function stripPunct(s){
  return (s||"")
    .replace(/[\u2019'’]/g, "")
    .replace(/[··.,;:!?()\[\]{}<>«»“”"\\/]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function lastWord(s){
  const t = stripPunct(s);
  if(!t) return "";
  const parts = t.split(" ");
  return parts[parts.length-1];
}

function countSyllables(word){
  // toy syllable count: count vowel groups
  let w = word;
  let n = 0;
  let inV = false;
  for(const ch of w){
    const isV = vowels.has(ch) || "αεηιουωάέήίόύώ".includes(ch);
    if(isV && !inV) n++;
    inV = isV;
  }
  return n;
}

function endsWithAny(w, arr){
  return arr.some(suf => w.endsWith(suf));
}

function hasSigmaBeforeTau(w){
  // look for στ before final ης/ης/στης etc.
  return /στ/.test(w);
}

function penultHasEta(w){
  // very rough: check if the second-to-last vowel is eta-ish
  const chars = Array.from(w);
  const vowelIdx = [];
  for(let i=0;i<chars.length;i++){
    const ch = chars[i];
    const isV = vowels.has(ch) || "αεηιουωάέήίόύώ".includes(ch);
    if(isV) vowelIdx.push(i);
  }
  if(vowelIdx.length < 2) return false;
  const penultV = chars[vowelIdx[vowelIdx.length-2]];
  return /[ηήἠἡἢἣἤἥἦἧῃῄῂῇᾐᾑᾒᾓᾔᾕᾖᾗ]/.test(penultV);
}

function addFinalAccent(word, kind){
  // kind: 'acute' or 'grave'
  // We place a combining mark on the last vowel letter.
  const AC = "\u0301"; // combining acute
  const GR = "\u0300"; // combining grave
  const mark = kind === 'grave' ? GR : AC;

  const chars = Array.from(word);
  for(let i=chars.length-1;i>=0;i--){
    const ch = chars[i];
    const isV = vowels.has(ch) || "αεηιουωάέήίόύώ".includes(ch);
    if(isV){
      chars[i] = ch + mark;
      return chars.join("");
    }
  }
  return word;
}

function classify(word, mode){
  const w = word;
  const syl = countSyllables(w);
  const isCapitalized = /^\p{Lu}/u.test(w);

  // Rule A: -στης with η in penult, στ present, >2 syllables => oxytone
  const isStes = endsWithAny(w, ["στης","στής","στῆς","στησ","στης"]) || /στης$/i.test(w);
  const condA = isStes && syl > 2 && hasSigmaBeforeTau(w) && penultHasEta(w);

  // Rule B: polysyllabic -ης paronym from -ος => barytone (toy: ends in -ης and >2 syllables)
  const isEs = endsWithAny(w, ["ης","ής","ῆς"]) && !isStes;
  const condB = isEs && syl > 2;

  // Special toy: if proper name, prefer grave (as with Κηδέστης)
  let preference = null;
  let why = [];

  if(mode === 'proper'){
    preference = 'grave';
    why.push("Proper-name mode: prefer barytone (βαρύνεται) in this toy.");
  }

  if(condA){
    preference = 'acute';
    why.push("Matches Herodian’s -στης pattern (η in penult, στ, >2 syllables) → oxytone.");
  }

  if(condB && mode !== 'proper'){
    preference = 'grave';
    why.push("Looks like a polysyllabic -ης form (toy proxy for -ος → -ης paronym) → barytone.");
  }

  if(!preference){
    preference = (mode === 'epithet') ? 'acute' : 'grave';
    why.push("No strong pattern detected; defaulting by mode.");
  }

  // Confidence badge
  let conf = 'warn';
  if((condA && preference==='acute') || (condB && preference==='grave') || (mode==='proper' && preference==='grave')) conf='ok';
  if(syl<=1) conf='bad';

  return { syllables:syl, condA, condB, preference, why, conf, isCapitalized };
}

function render(){
  const raw = $('#w').value;
  const word = lastWord(raw);
  const mode = $('#modeProper').checked ? 'proper' : 'epithet';
  const forceFinal = $('#forceFinal').checked;

  if(!word){
    $('#out').innerHTML = `<div class="muted">Enter a word and click <b>Analyze</b>.</div>`;
    return;
  }

  const info = classify(word, mode);
  const pref = info.preference;

  const accented = forceFinal ? addFinalAccent(word, pref) : addFinalAccent(word, pref);

  const badgeClass = info.conf;
  const badgeText = info.conf==='ok' ? 'pattern match' : (info.conf==='bad' ? 'very unsure' : 'guess');
  const prefLabel = pref==='acute' ? 'ὀξύνεται (acute)' : 'βαρύνεται (grave)';

  const flags = [];
  if(info.condA) flags.push('−στης rule');
  if(info.condB) flags.push('−ης paronym rule (toy)');
  if(!flags.length) flags.push('no rule hit');

  $('#out').innerHTML = `
    <div class="big">${escapeHtml(accented)}</div>
    <div style="margin-top:8px">
      <span class="badge ${badgeClass}">${badgeText}</span>
      <span class="badge">${prefLabel}</span>
      <span class="badge">${mode}</span>
    </div>
    <div class="kv" style="margin-top:10px">
      <div class="k">Input (last word)</div><div class="v"><span class="big" style="font-size:16px">${escapeHtml(word)}</span></div>
      <div class="k">Syllables (toy)</div><div class="v">${info.syllables}</div>
      <div class="k">Signals</div><div class="v">${flags.join(' · ')}</div>
      <div class="k">Why</div><div class="v">${info.why.map(escapeHtml).join('<br>')}</div>
    </div>
  `;
}

function escapeHtml(s){
  return (s+"")
    .replaceAll('&','&amp;')
    .replaceAll('<','&lt;')
    .replaceAll('>','&gt;')
    .replaceAll('"','&quot;')
    .replaceAll("'",'&#39;');
}

const examples = [
  {g:"κηδεστης", label:"κηδεστης"},
  {g:"Κηδεστης", label:"Κηδεστης (proper?)"},
  {g:"ἀργεστης", label:"ἀργεστης"},
  {g:"ἑρπηστης", label:"ἑρπηστης"},
  {g:"ὀρχηστης", label:"ὀρχηστης"},
  {g:"Αραξης", label:"Αραξης"},
  {g:"Λαπιθης", label:"Λαπιθης"},
  {g:"ευσεβης", label:"ευσεβης"},
  {g:"ἀνηλεγης", label:"ἀνηλεγης"},
  {g:"πολυκλαδης", label:"πολυκλαδης"}
];

function mountChips(){
  const box = $('#chips');
  box.innerHTML = "";
  for(const ex of examples){
    const b = document.createElement('button');
    b.className = 'chip';
    b.type = 'button';
    b.textContent = ex.label;
    b.addEventListener('click', () => {
      $('#w').value = ex.g;
      render();
      $('#w').focus();
    });
    box.appendChild(b);
  }
}

$('#analyze').addEventListener('click', render);
$('#clear').addEventListener('click', () => {
  $('#w').value = "";
  render();
  $('#w').focus();
});
$('#w').addEventListener('keydown', (e) => {
  if(e.key === 'Enter') render();
});
$('#modeEpithet').addEventListener('change', render);
$('#modeProper').addEventListener('change', render);
