(() => {
  const $ = (sel, root=document) => root.querySelector(sel);
  const inp = $('#inp');
  const outMain = $('#outMain');
  const outMeta = $('#outMeta');
  const outWhy = $('#outWhy');
  const whyBox = $('#whyBox');

  const tProper = $('#tProper');
  const tArk = $('#tArk');
  const tOlo = $('#tOlo');
  const tGenTos = $('#tGenTos');

  const examples = Array.from(document.querySelectorAll('.chip'));

  // --- Greek helpers (toy-level) ---
  const COMBINING = /[\u0300-\u036f]/g;
  const tonosMap = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ',
    'ϊ':'ΐ','ϋ':'ΰ','Ϊ':'Ϊ','Ϋ':'Ϋ'
  };

  function normalizeGreek(s){
    if(!s) return '';
    s = s.trim();
    // normalize final sigma
    s = s.replace(/σ\b/g,'ς');
    // NFC for precomposed tonos where possible
    try { s = s.normalize('NFC'); } catch(e) {}
    return s;
  }

  function stripDiacritics(s){
    // Remove combining marks; also map precomposed tonos to base by NFD.
    try { s = s.normalize('NFD').replace(COMBINING,'').normalize('NFC'); }
    catch(e){ /* ignore */ }
    return s;
  }

  function lastIndexOfAny(s, chars){
    for(let i=s.length-1;i>=0;i--) if(chars.includes(s[i])) return i;
    return -1;
  }

  function addAcuteToLastVowel(word){
    // Add acute to the last vowel letter (very rough).
    const vowels = 'αεηιουωΑΕΗΙΟΥΩϊϋΪΫ';
    let w = word;
    const idx = lastIndexOfAny(w, vowels);
    if(idx < 0) return w;
    const ch = w[idx];
    const repl = tonosMap[ch] || ch;
    return w.slice(0, idx) + repl + w.slice(idx+1);
  }

  function addAcuteToPenultVowel(word){
    // Add acute to the penult vowel (roughly: second-to-last vowel).
    const vowels = 'αεηιουωΑΕΗΙΟΥΩϊϋΪΫ';
    let positions = [];
    for(let i=0;i<word.length;i++) if(vowels.includes(word[i])) positions.push(i);
    if(positions.length === 0) return word;
    const idx = positions.length >= 2 ? positions[positions.length-2] : positions[0];
    const ch = word[idx];
    const repl = tonosMap[ch] || ch;
    return word.slice(0, idx) + repl + word.slice(idx+1);
  }

  function removeAccents(word){
    // remove tonos/dialytika tonos etc.
    return stripDiacritics(word);
  }

  // --- Rule heuristics inspired by the passage ---
  const properNameList = new Set([
    'αριφραδης','διοπειθης','πολυδευκης','αιδης','αριστοφανης','διομηδης'
  ]);

  function endsWithAny(s, arr){
    return arr.some(x => s.endsWith(x));
  }

  function guessAccent(raw){
    const original = normalizeGreek(raw);
    const base = removeAccents(original);
    const low = base.toLowerCase();

    const tags = [];
    const why = [];

    // Identify some patterns
    const isNeuterEs = endsWithAny(low, ['ες']);
    const isMascHs = endsWithAny(low, ['ης']);

    // Exceptions families
    const isArk = /αρκης$/.test(low);
    const isOlo = /ωλης$/.test(low);

    // A toy heuristic for “genitive in -τος” group: many -ης adjectives like -βλης, -θνης, -τρης etc.
    const looksGenTosFamily = /(βλης|θνης|τρης|πλης|κρης|δρης|φλης)\b/.test(low);

    // Another toy: compounds from neuter -ος -> -ης (e.g. εἶδος -> εὐειδής; βάθος -> ἀγχιβαθής)
    const looksFromNeuterOs = /(ειδης|βαθης)\b/.test(low);

    // Decide accent type
    let decision = 'oxytone'; // acute on last vowel

    // Proper name switch
    if(tProper.checked || properNameList.has(low)){
      decision = 'barytone';
      tags.push('proper-name');
      why.push('Proper names in the passage are said to be barytone (e.g. Ἀριφράδης, Διοπείθης, Πολυδεύκης, Ἀΐδης).');
    }

    // Marked exceptions: -ωλης from ὄλω
    if(decision !== 'barytone' && tOlo.checked && isOlo){
      decision = 'barytone';
      tags.push('marked:-ωλης');
      why.push('Herodian marks forms from ὄλω (πανώλης, ἐξώλης, προώλης) as barytone.');
    }

    // Marked exceptions: -αρκης from ἀρκῶ
    if(decision !== 'barytone' && tArk.checked && isArk){
      decision = 'barytone';
      tags.push('marked:-αρκης');
      why.push('Herodian treats compounds from ἀρκῶ (αὐτάρκης, ποδάρκης) as marked exceptions: barytone, though an adjective might “expect” oxytone.');
    }

    // Neuter -ές: oxytone (po-da-rkés)
    if(isNeuterEs){
      tags.push('neuter:-ες');
      why.push('The passage notes neuter ποδαρκές as oxytone.');
      // keep oxytone unless forced barytone by proper-name toggle
      if(decision !== 'barytone') decision = 'oxytone';
    }

    // General tendency: many -ης adjectives oxytone
    if(isMascHs && decision !== 'barytone'){
      tags.push('adj:-ης');
      why.push('Many adjectival -ής forms are oxytone in Herodian’s discussion (e.g. ἐπιβλής, εὐειδής, ἀγχιβαθής).');
    }

    if(tGenTos.checked && looksGenTosFamily && decision !== 'barytone'){
      tags.push('heuristic:-τος-gen');
      why.push('He mentions a class that “makes the genitive in -τος” and is oxytone (toy heuristic: patterns like -βλης, -θνης, -τρης).');
      decision = 'oxytone';
    }

    if(looksFromNeuterOs && decision !== 'barytone'){
      tags.push('from-neuter-ος');
      why.push('He also notes compounds from disyllabic neuters in -ος (e.g. εἶδος → εὐειδής; βάθος → ἀγχιβαθής) as oxytone when adjectival.');
      decision = 'oxytone';
    }

    // Produce accented form
    let accented;
    if(decision === 'oxytone'){
      accented = addAcuteToLastVowel(base);
    } else {
      // barytone: for this toy, put acute on penult vowel (common for many barytones)
      accented = addAcuteToPenultVowel(base);
    }

    // If user already typed accents, show both
    const userHadAccents = stripDiacritics(original) !== original;

    return {
      original,
      base,
      accented,
      decision,
      tags,
      why,
      userHadAccents
    };
  }

  function render(){
    const val = inp.value;
    if(!val.trim()){
      outMain.textContent = '—';
      outMeta.textContent = '';
      outWhy.textContent = '';
      whyBox.open = false;
      return;
    }
    const g = guessAccent(val);

    outMain.textContent = g.accented;

    const lines = [];
    if(g.userHadAccents) lines.push(`you typed: ${g.original}`);
    lines.push(`normalized: ${g.base}`);
    lines.push(`guess: ${g.decision === 'oxytone' ? 'oxytone (acute on last)' : 'barytone (toy: acute on penult)'}`);
    if(g.tags.length) lines.push(`tags: ${g.tags.join(', ')}`);
    outMeta.textContent = lines.join('\n');

    outWhy.innerHTML = '';
    const tagWrap = document.createElement('div');
    g.tags.forEach(t => {
      const sp = document.createElement('span');
      sp.className = 'tag';
      sp.textContent = t;
      tagWrap.appendChild(sp);
    });
    outWhy.appendChild(tagWrap);

    const ul = document.createElement('ul');
    ul.style.margin = '8px 0 0';
    ul.style.paddingLeft = '18px';
    (g.why.length ? g.why : ['No specific pattern matched; defaulting to oxytone for -ής-like adjectives.']).forEach(w => {
      const li = document.createElement('li');
      li.textContent = w;
      ul.appendChild(li);
    });
    outWhy.appendChild(ul);
    whyBox.open = true;
  }

  $('#go').addEventListener('click', render);
  $('#clear').addEventListener('click', () => { inp.value=''; inp.focus(); render(); });
  inp.addEventListener('keydown', (e) => { if(e.key === 'Enter') render(); });

  [tProper, tArk, tOlo, tGenTos].forEach(el => el.addEventListener('change', render));

  examples.forEach(btn => {
    btn.addEventListener('click', () => {
      inp.value = btn.getAttribute('data-ex');
      inp.focus();
      render();
    });
  });

  // initial
  inp.value = 'επιβλης';
  render();
})();

