const $ = (sel, root=document) => root.querySelector(sel);

const examples = [
  {adj:"διογενής", name:"Διογένης"},
  {adj:"πολυνεικής", name:"Πολυνείκης"},
  {adj:"παγκρατής", name:"Παγκράτης"},
  {adj:"εὐρυσθενής", name:"Εὐρυσθένης"},
  {adj:"εὐτειχής", name:"Εὐτείχης"},
  {adj:"εὐγενής", name:"Εὐγένης"},
  {adj:"δυσμενής", name:"Δυσμένης"},
  {adj:"ἀγενής", name:"Ἀγένης"}
];

// --- tiny polytonic helpers (heuristic, not scholarly) ---
const combining = /[\u0300-\u036f]/g;
function nfd(s){return s.normalize('NFD');}
function nfc(s){return s.normalize('NFC');}
function stripCombining(s){return nfd(s).replace(combining,'');}
function stripAccentOnly(s){
  // remove tonos/oxia/varia/perispomeni combining marks but keep breathings/diaeresis/iota-subscript
  // Combining marks: 0300 grave, 0301 acute, 0342 perispomeni, 1FFD? (precomposed handled by NFD)
  return nfc(nfd(s).replace(/[\u0300\u0301\u0342]/g,''));
}
function lastVowelIndex(base){
  const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);
  for(let i=base.length-1;i>=0;i--){
    if(vowels.has(base[i])) return i;
  }
  return -1;
}
function addAcuteToLastVowel(word){
  // heuristic: add combining acute to last vowel letter
  const s = nfd(word);
  const base = stripCombining(s);
  const idx = lastVowelIndex(base);
  if(idx<0) return word;
  // rebuild by mapping base index to NFD positions
  // simplest: operate on base string, then reinsert acute as combining after that vowel
  let out = "";
  for(let i=0;i<base.length;i++){
    out += base[i];
    if(i===idx) out += "\u0301";
  }
  return nfc(out);
}
function addAcuteToPenult(word){
  const base = stripCombining(nfd(word));
  const vowels = [];
  const vset = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);
  for(let i=0;i<base.length;i++) if(vset.has(base[i])) vowels.push(i);
  if(vowels.length<2) return addAcuteToLastVowel(word);
  const idx = vowels[vowels.length-2];
  let out="";
  for(let i=0;i<base.length;i++){
    out += base[i];
    if(i===idx) out += "\u0301";
  }
  return nfc(out);
}

function looksLikeEis(word){
  const bare = stripCombining(nfd(word));
  return /εις$/i.test(bare);
}
function looksLikeEs(word){
  const bare = stripCombining(nfd(word));
  return /ες$/i.test(bare);
}
function looksLikeHs(word){
  const bare = stripCombining(nfd(word));
  return /ης$/i.test(bare);
}

function proposeProperName(adj){
  const cleaned = adj.trim();
  if(!cleaned) return {name:"", note:""};

  // If it matches our curated examples, trust that.
  const hit = examples.find(e => stripAccentOnly(e.adj) === stripAccentOnly(cleaned));
  if(hit) return {name: hit.name, note:"Matched a passage-style example."};

  // Generic heuristic:
  // -ής -> -ης and pull accent back to penult (barytone-ish)
  // -εικής -> -είκης (keep ει, accent penult)
  // -κρατής -> -κράτης (already -ης? actually -της; treat separately)

  const bare = stripCombining(nfd(cleaned));
  let baseNoAccent = stripAccentOnly(cleaned);

  let name = baseNoAccent;
  let noteBits = [];

  if(/ής$/i.test(stripCombining(nfd(baseNoAccent)))){
    name = baseNoAccent.replace(/ής$/i, "ης");
    noteBits.push("Changed ending -ής → -ης (name-like). ");
    name = addAcuteToPenult(name);
    noteBits.push("Moved accent back (toy barytone). ");
  } else if(/ειχής$/i.test(stripCombining(nfd(baseNoAccent)))){
    name = baseNoAccent.replace(/ειχής$/i, "είχης");
    noteBits.push("Treated -ειχής like εὐτειχής → Εὐτείχης.");
  } else if(/εικής$/i.test(stripCombining(nfd(baseNoAccent)))){
    name = baseNoAccent.replace(/εικής$/i, "είκης");
    noteBits.push("Treated -εικής like πολυνεικής → Πολυνείκης.");
  } else if(/κρατής$/i.test(stripCombining(nfd(baseNoAccent)))){
    name = baseNoAccent.replace(/κρατής$/i, "κράτης");
    noteBits.push("Treated -κρατής like παγκρατής → Παγκράτης.");
  } else {
    // fallback: just try barytone accent
    name = addAcuteToPenult(baseNoAccent);
    noteBits.push("No clear -ής ending detected; just tried a barytone-ish accent.");
  }

  return {name, note: noteBits.join("")};
}

function buildToyTable(adj, name){
  // Minimal mnemonic: show nom/gen sg and nom pl for each shape.
  // We do not compute real genitives; we show common patterns:
  // adj -ής (3rd decl): gen -οῦς; nom pl -εῖς
  // name -ης (1st decl masc): gen -ου; nom pl -αι
  const adjBare = stripAccentOnly(adj);
  const nameBare = stripAccentOnly(name);

  const adjStem = adjBare.replace(/ής$/i, "");
  const nameStem = nameBare.replace(/ης$/i, "");

  const adjNom = adj;
  const adjGen = adjStem ? addAcuteToLastVowel(adjStem + "οῦς") : "—";
  const adjPl = adjStem ? addAcuteToLastVowel(adjStem + "εῖς") : "—";

  const nameNom = name;
  const nameGen = nameStem ? addAcuteToLastVowel(nameStem + "ου") : "—";
  const namePl = nameStem ? addAcuteToLastVowel(nameStem + "αι") : "—";

  const cells = [
    {k:"Shape", v:"Adjective -ής"},
    {k:"Nom. sg.", v: adjNom},
    {k:"Gen. sg. (toy)", v: adjGen},
    {k:"Shape", v:"Proper name -ης"},
    {k:"Nom. sg.", v: nameNom},
    {k:"Gen. sg. (toy)", v: nameGen},
    {k:"Nom. pl. (toy)", v: adjPl},
    {k:"Nom. pl. (toy)", v: namePl},
    {k:"Herodian’s point", v:"same-looking compound ↔ different accent/declension"}
  ];

  return cells.map(c => `<div class="cell"><span class="k">${escapeHtml(c.k)}</span><span class="v">${escapeHtml(c.v)}</span></div>`).join("");
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
}

function renderMain(){
  const w = $("#inWord").value.trim();
  if(!w){
    $("#outAdj").textContent = "—";
    $("#outName").textContent = "—";
    $("#outAdjNote").innerHTML = "";
    $("#outNameNote").innerHTML = "";
    $("#outTable").innerHTML = "";
    return;
  }

  const adj = w;
  const prop = proposeProperName(adj);

  $("#outAdj").textContent = adj;

  const bare = stripCombining(nfd(stripAccentOnly(adj)));
  let adjNote = [];
  if(/ής$/i.test(bare)) adjNote.push("Looks like an <mark>-ής</mark> adjective.");
  else if(/εικής$/i.test(bare)) adjNote.push("Looks like <mark>-εικής</mark>.");
  else if(/ειχής$/i.test(bare)) adjNote.push("Looks like <mark>-ειχής</mark>.");
  else if(/κρατής$/i.test(bare)) adjNote.push("Looks like <mark>-κρατής</mark>.");
  else adjNote.push("Ending not recognized; still trying a name-like accent shift.");

  $("#outAdjNote").innerHTML = adjNote.join(" ");

  $("#outName").textContent = prop.name || "—";
  $("#outNameNote").innerHTML = prop.name ? prop.note : "";

  $("#outTable").innerHTML = buildToyTable(adj, prop.name || "—");
}

// --- -ετής toggle ---
function normalizeEtosInput(s){
  return s.trim();
}
function toKoineEtēs(word){
  // aim for ...ετής (acute on eta). If user typed ...έτης, convert.
  let w = stripAccentOnly(word);
  // convert final -ετης/-ετής variants to -ετής
  w = w.replace(/ετης$/i, "ετης");
  // add acute to last vowel (usually η)
  // if ends with ετης, make ετής by changing η? Actually spelling differs: ετής has eta.
  // We'll accept both and just accent last vowel.
  // If user has -ετης with epsilon, keep epsilon but accent it: -έτης (Attic-ish). Koine wants -ετής with eta.
  // Try to swap last 'ετης' -> 'ετής' (eta)
  const bare = stripCombining(nfd(w));
  if(/ετης$/i.test(bare)){
    w = w.replace(/ετης$/i, "ετης");
  }
  // If it ends with 'ετης' (epsilon), change to 'ετής' (eta)
  w = w.replace(/ετης$/i, "ετης");
  // Now specifically: replace last 'ετης' with 'ετης'?? no-op; do eta swap:
  w = w.replace(/ετης$/i, "ετης");
  // Better: if ends with 'ετης' in base, replace with 'ετης' but with eta: 'ετης' -> 'ετης' doesn't.
  // Use Greek eta explicitly: ε + τ + η + ς
  w = w.replace(/ετης$/i, "ετησ");
  // fix final sigma
  w = w.replace(/σ$/i, "ς");
  // add acute to that eta (penult/last vowel). We'll just accent last vowel.
  w = addAcuteToLastVowel(w);
  // restore eta if we accidentally used latin? ensure Greek
  w = w.replace(/ετησ$/i, "ετης");
  // Actually we want ετής: epsilon + tau + eta + final sigma.
  w = stripAccentOnly(w);
  w = w.replace(/ετης$/i, "ετης");
  // swap the vowel before final ς to eta
  w = w.replace(/ετες$/i, "ετης");
  // ensure eta: ετ η ς
  w = w.replace(/ετης$/i, "ετης");
  // add acute to eta by accenting last vowel
  w = addAcuteToLastVowel(w);
  return w;
}
function toAtticEtēs(word){
  // aim for ...έτης (epsilon with acute)
  let w = stripAccentOnly(word);
  // if ends with ετής (eta), change to έτης (epsilon)
  const bare = stripCombining(nfd(w));
  if(/ετης$/i.test(bare)){
    // already epsilon; just accent it
    w = addAcuteToPenult(w); // often on epsilon before -της
    return w;
  }
  // if ends with eta before ς, swap to epsilon
  w = w.replace(/ετης$/i, "ετης");
  // accent the epsilon in -ετης: easiest: accent penult
  w = addAcuteToPenult(w);
  return w;
}

function renderEtos(mode){
  const raw = normalizeEtosInput($("#inEtos").value);
  if(!raw){
    $("#outEtos").textContent = "—";
    $("#outEtosNote").textContent = "";
    return;
  }
  let out = raw;
  let note = "";
  if(mode === "koine"){
    out = toKoineEtēs(raw);
    note = "Koine-ish: accent on -ετής (Herodian: διετής, τριετής).";
  } else {
    out = toAtticEtēs(raw);
    note = "Attic-ish: barytone -έτης (Herodian: διέτης, τριέτης, ἑξαέτης).";
  }
  $("#outEtos").textContent = out;
  $("#outEtosNote").textContent = note;
}

// --- wire up ---
$("#btnGo").addEventListener("click", renderMain);
$("#inWord").addEventListener("input", () => { renderMain(); });
$("#btnRand").addEventListener("click", () => {
  const pick = examples[Math.floor(Math.random()*examples.length)];
  $("#inWord").value = pick.adj;
  renderMain();
});

$("#btnKoine").addEventListener("click", () => {
  $("#btnKoine").classList.remove("ghost");
  $("#btnAttic").classList.add("ghost");
  renderEtos("koine");
});
$("#btnAttic").addEventListener("click", () => {
  $("#btnAttic").classList.remove("ghost");
  $("#btnKoine").classList.add("ghost");
  renderEtos("attic");
});
$("#inEtos").addEventListener("input", () => {
  // follow whichever button is currently active
  const atticActive = !$("#btnAttic").classList.contains("ghost");
  renderEtos(atticActive ? "attic" : "koine");
});

// initial state
$("#btnKoine").classList.remove("ghost");
$("#btnAttic").classList.add("ghost");
$("#inWord").value = "διογενής";
$("#inEtos").value = "τριετής";
renderMain();
renderEtos("koine");

passages.gadget_css:
:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --card:#1d2140;
  --ink:#eef0ff;
  --muted:#b9bce6;
  --faint:#8b90c9;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --good:#34d399;
  --warn:#fbbf24;
  --bad:#fb7185;
  --line:rgba(255,255,255,.10);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Noto Sans", "Liberation Sans", sans-serif;
}

*{box-sizing:border-box}

.wrap{
  font-family:var(--sans);
  color:var(--ink);
  background: radial-gradient(1200px 700px at 20% 0%, rgba(167,139,250,.18), transparent 60%),
              radial-gradient(900px 600px at 90% 10%, rgba(125,211,252,.16), transparent 55%),
              linear-gradient(180deg, #0b0d18, var(--bg));
  padding:18px;
  border-radius:16px;
}

.hdr{
  display:flex;
  gap:14px;
  align-items:flex-start;
  padding:14px 14px 6px;
}

h1{font-size:18px; margin:0 0 6px; letter-spacing:.2px}
.sub{margin:0; color:var(--muted); font-size:13px; line-height:1.35}

.panel{
  display:grid;
  grid-template-columns: 1.05fr .95fr;
  gap:14px;
  padding:10px 14px 14px;
}

@media (max-width: 900px){
  .panel{grid-template-columns:1fr}
}

.controls{
  background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));
  border:1px solid var(--line);
  border-radius:14px;
  padding:14px;
  box-shadow:var(--shadow);
}

.lbl{display:block; font-size:12px; color:var(--muted); margin-bottom:6px}

.row{display:flex; gap:8px; align-items:center}

input[type="text"]{
  flex:1;
  padding:10px 12px;
  border-radius:12px;
  border:1px solid rgba(255,255,255,.14);
  background:rgba(0,0,0,.25);
  color:var(--ink);
  outline:none;
  font-size:16px;
}
input[type="text"]:focus{border-color: rgba(125,211,252,.55); box-shadow:0 0 0 3px rgba(125,211,252,.12)}

.btn{
  padding:10px 12px;
  border-radius:12px;
  border:1px solid rgba(255,255,255,.16);
  background:linear-gradient(180deg, rgba(125,211,252,.22), rgba(125,211,252,.10));
  color:var(--ink);
  cursor:pointer;
  font-weight:600;
}
.btn:hover{filter:brightness(1.08)}
.btn:active{transform:translateY(1px)}
.btn.ghost{
  background:rgba(255,255,255,.06);
}

.toggles{display:flex; gap:14px; flex-wrap:wrap; margin-top:10px}
.chk{font-size:12px; color:var(--muted); user-select:none}
.chk input{transform:translateY(1px)}

.hint{margin:10px 0 0; color:var(--faint); font-size:12px; line-height:1.35}
.ex{font-family:var(--mono); color:var(--ink); background:rgba(255,255,255,.06); padding:1px 6px; border-radius:999px; border:1px solid rgba(255,255,255,.10)}

.out{display:flex; flex-direction:column; gap:14px}

.card{
  background:linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,.02));
  border:1px solid var(--line);
  border-radius:14px;
  padding:14px;
  box-shadow:var(--shadow);
}

.card h2{margin:0 0 8px; font-size:14px; letter-spacing:.2px}

.result{
  font-family:var(--mono);
  font-size:13px;
  line-height:1.45;
  white-space:pre-wrap;
  padding:10px;
  border-radius:12px;
  border:1px dashed rgba(255,255,255,.18);
  background:rgba(0,0,0,.22);
}
.result.empty{color:var(--faint)}

.badge{
  display:inline-block;
  font-family:var(--sans);
  font-size:11px;
  padding:2px 8px;
  border-radius:999px;
  border:1px solid rgba(255,255,255,.14);
  margin-right:6px;
}
.badge.oxy{background:rgba(52,211,153,.14); border-color:rgba(52,211,153,.35)}
.badge.bar{background:rgba(251,191,36,.14); border-color:rgba(251,191,36,.35)}
.badge.unk{background:rgba(148,163,184,.12); border-color:rgba(148,163,184,.28)}

.mini{margin:0 0 10px; color:var(--muted); font-size:12px; line-height:1.35}

.sandbox{display:flex; flex-direction:column; gap:8px}
.sandRow{display:flex; gap:10px; align-items:flex-start}
.tag{min-width:92px; color:var(--muted); font-size:12px; padding-top:2px}
.sandWord,.sandOut{font-family:var(--mono); font-size:15px}
.sandOut{padding:6px 10px; border-radius:12px; border:1px solid rgba(255,255,255,.14); background:rgba(0,0,0,.22)}
.sandNote{color:var(--faint); font-size:12px; line-height:1.35}

.rules{margin:0; padding-left:18px; color:var(--muted); font-size:12px; line-height:1.45}
.rules li{margin:6px 0}

.ftr{padding:0 14px 14px}
summary{cursor:pointer; color:var(--muted); font-size:12px}
.small{color:var(--muted); font-size:12px; line-height:1.45; margin-top:8px}

kbd{
  font-family:var(--mono);
  font-size:12px;
  padding:1px 6px;
  border-radius:8px;
  border:1px solid rgba(255,255,255,.16);
  background:rgba(0,0,0,.25);
}

