// Herodian Accent Toy (offline, heuristic)

const $ = (sel) => document.querySelector(sel);

// --- Greek accent utilities (very approximate) ---
const ACCENT_RE = /[\u0300\u0301\u0342\u1FBD\u1FBE\u1FBF\u1FC0\u1FC1\u1FCD-\u1FCF\u1FDD-\u1FDF\u1FED-\u1FEF\u1FFD\u1FFE]/g; // combining + some spacing marks
const COMBINING_ACUTE = "\u0301";

function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripAccents(s){
  // remove combining diacritics broadly; keep Greek letters
  return nfc(nfd(s).replace(/[\u0300-\u036f]/g, ''));
}

function hasAccent(s){
  const d = nfd(s);
  return /[\u0300\u0301\u0342]/.test(d) || /[άέήίόύώὰὲὴὶὸὺὼᾶῖῦῶ]/.test(s);
}

function detectAccentType(s){
  const d = nfd(s);
  if (d.includes("\u0342")) return "circumflex (ˆ)";
  if (d.includes("\u0301")) return "acute (´)";
  if (d.includes("\u0300")) return "grave (`)";
  // precomposed check (rough)
  if (/[άέήίόύώ]/.test(s)) return "acute (´)";
  if (/[ὰὲὴὶὸὺὼ]/.test(s)) return "grave (`)";
  if (/[ᾶῖῦῶ]/.test(s)) return "circumflex (ˆ)";
  return "none detected";
}

function isGreekVowel(ch){
  return /[αεηιουωΑΕΗΙΟΥΩ]/.test(stripAccents(ch));
}

function vowelGroups(word){
  // Return array of {start,end} indices in NFD string for vowel groups (syllable-ish)
  const s = nfd(word);
  const base = s; // NFD
  const groups = [];
  let i = 0;
  while (i < base.length){
    const ch = base[i];
    // skip combining marks
    if (/^[\u0300-\u036f]$/.test(ch)) { i++; continue; }
    const isV = isGreekVowel(ch);
    if (!isV){ i++; continue; }
    let start = i;
    i++;
    // consume following combining marks
    while (i < base.length && /^[\u0300-\u036f]$/.test(base[i])) i++;
    // consume additional vowels in a row (treat as one group: diphthong-ish)
    while (i < base.length){
      const c2 = base[i];
      if (/^[\u0300-\u036f]$/.test(c2)) { i++; continue; }
      if (!isGreekVowel(c2)) break;
      i++;
      while (i < base.length && /^[\u0300-\u036f]$/.test(base[i])) i++;
    }
    groups.push({start, end:i});
  }
  return groups;
}

function removeAllAccentMarks(word){
  return nfc(nfd(word).replace(/[\u0300\u0301\u0342]/g, ''));
}

function addAcuteToGroup(word, groupIndexFromEnd){
  // Place combining acute on the first vowel of the chosen vowel-group counting from end.
  // groupIndexFromEnd: 1=ultima, 2=penult, 3=antepenult
  const s = nfd(removeAllAccentMarks(word));
  const groups = vowelGroups(s);
  if (!groups.length) return nfc(s);
  const idx = Math.max(0, groups.length - groupIndexFromEnd);
  const g = groups[idx];

  // find first base vowel char in group
  let insertAt = g.start + 1; // after the vowel char
  // but if there are combining marks immediately after vowel, insert after them
  while (insertAt < s.length && /^[\u0300-\u036f]$/.test(s[insertAt])) insertAt++;

  const out = s.slice(0, insertAt) + COMBINING_ACUTE + s.slice(insertAt);
  return nfc(out);
}

function countSyllables(word){
  return vowelGroups(word).length;
}

// --- Feature 1: compound sandbox ---
function makeCompound(){
  const prefix = ($('#prefix').value || '').trim();
  const base = ($('#base').value || '').trim();
  const assumeMono = $('#assumeMono').checked;
  const exceptionPtox = $('#exceptionPtox').checked;

  const raw = prefix + base;
  $('#compoundRaw').textContent = raw || '—';

  if (!raw){
    $('#compoundAcc').textContent = '—';
    $('#compoundNote').textContent = '';
    return;
  }

  const baseBare = stripAccents(base).toLowerCase();
  const rawBare = stripAccents(raw);

  let note = [];
  let suggested = rawBare;

  // Exception: πτωξ -> πολύπτωξ (do NOT raise; keep accent on prefix as oxytone-ish)
  if (exceptionPtox && baseBare === 'πτωξ' && stripAccents(prefix).toLowerCase().startsWith('πολυ')){
    suggested = addAcuteToGroup(rawBare, 2); // penult as a toy stand-in for πολύπτωξ
    note.push('Applied the passage’s famous exception: πτώξ → πολύπτωξ (toy accent placed on penult).');
  } else if (assumeMono){
    // "raise" = move accent leftward (toward the beginning): put acute on antepenult if possible
    const syl = countSyllables(rawBare);
    if (syl >= 3){
      suggested = addAcuteToGroup(rawBare, 3);
      note.push('Monosyllabic second member: toy “raising” puts an acute on the antepenult.');
    } else if (syl === 2){
      suggested = addAcuteToGroup(rawBare, 2);
      note.push('Only two syllables: toy “raising” puts an acute on the penult.');
    } else {
      suggested = addAcuteToGroup(rawBare, 1);
      note.push('Only one syllable detected: accent placed on the only vowel-group.');
    }
  } else {
    // default: accent on penult if possible
    const syl = countSyllables(rawBare);
    suggested = addAcuteToGroup(rawBare, Math.min(2, syl));
    note.push('No “raising” selected: toy default puts an acute on the penult (if possible).');
  }

  $('#compoundAcc').textContent = suggested;
  $('#compoundNote').innerHTML = note.map(x => `• ${escapeHtml(x)}`).join('<br>');
}

// --- Feature 2: ending-based hints ---
const examples = [
  'λογιότης','λευκότης','ποιότης','ἑνότης','ἰσότης','γλυκύτης',
  'ταχυτής','βραδυτής','ἀνδροτής','δηϊοτής','τραχυτής','κουφοτής',
  'ὄφις','ἔχις','Θέτις','πάϊς','μάντις','Ἄλεξις','Πρύτανις'
];

const exceptionsTēs = new Set(['ταχυτης','βραδυτης','ἁδροτης','ἀνδροτης','δηϊοτης','τραχυτης','κουφοτης']);

function analyzeWord(){
  const w = ($('#inspect').value || '').trim();
  if (!w){
    $('#detAccent').textContent = '—';
    $('#verdict').textContent = '—';
    $('#barytone').textContent = '—';
    $('#analysisNote').textContent = '';
    return;
  }

  $('#detAccent').textContent = detectAccentType(w);

  const bare = stripAccents(w);
  const bareLower = bare.toLowerCase();
  const syl = countSyllables(bare);

  let verdict = [];
  let note = [];

  const endsTēs = /της$/i.test(bareLower);
  const endsIs = /ις$/i.test(bareLower);

  if (endsTēs){
    if (syl >= 3){
      verdict.push('Looks like a polysyllabic -της form. Passage: these are usually barytone.');
      const key = bareLower;
      if (exceptionsTēs.has(key)){
        verdict.push('But it matches a listed/Attic oxytone exception (toy list).');
      }
    } else {
      verdict.push('Ends in -της but seems not polysyllabic here; passage notes some disyllables (ποτής, ἑστής, ἐσθής).');
    }
  }

  if (endsIs){
    verdict.push('Ends in -ις. Passage: -ις nouns (with short/contracted ι) are barytone.');
  }

  if (!endsTēs && !endsIs){
    verdict.push('No targeted ending detected (-της / -ις). Try one of the examples.');
  }

  // Make a toy barytone version: ensure accent not on ultima by placing acute on penult (or antepenult if possible)
  let bary = bare;
  if (syl >= 2){
    // barytone = not final; choose penult
    bary = addAcuteToGroup(bare, 2);
    note.push('Toy barytone: acute placed on the penult (not the last syllable).');
  } else {
    bary = addAcuteToGroup(bare, 1);
    note.push('Only one syllable detected; barytone vs oxytone is not meaningful here.');
  }

  // If the input already has an accent, compare whether it is on ultima (toy)
  if (hasAccent(w)){
    const wNo = removeAllAccentMarks(w);
    const ultimaAcc = addAcuteToGroup(wNo, 1);
    const penultAcc = syl >= 2 ? addAcuteToGroup(wNo, 2) : ultimaAcc;
    const sameAsUlt = stripAccents(w) === stripAccents(ultimaAcc) && nfd(w).includes(nfd(ultimaAcc).replace(/.*(\u0301).*/, '$1'));
    // Above is too brittle; instead do a simpler check: does NFD contain acute within last vowel group?
    const d = nfd(w);
    const groups = vowelGroups(wNo);
    if (groups.length){
      const last = groups[groups.length-1];
      const slice = d.slice(last.start, last.end);
      if (slice.includes(COMBINING_ACUTE) || slice.includes('\u0342') || slice.includes('\u0300')){
        note.push('Input accent seems to fall on the last vowel-group (toy “oxytone”).');
      } else {
        note.push('Input accent seems not to be on the last vowel-group (toy “barytone”).');
      }
    }
  } else {
    note.push('No accent detected in the input; try typing one (e.g. λογιότης) to compare.');
  }

  $('#verdict').innerHTML = verdict.map(x => `• ${escapeHtml(x)}`).join('<br>');
  $('#barytone').textContent = bary;
  $('#analysisNote').innerHTML = note.map(x => `• ${escapeHtml(x)}`).join('<br>');
}

function escapeHtml(s){
  return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function randomExample(){
  const w = examples[Math.floor(Math.random()*examples.length)];
  $('#inspect').value = w;
  analyzeWord();
}

function clearAll(){
  $('#inspect').value = '';
  analyzeWord();
}

// Wire up
$('#make').addEventListener('click', makeCompound);
$('#analyze').addEventListener('click', analyzeWord);
$('#random').addEventListener('click', randomExample);
$('#clear').addEventListener('click', clearAll);
$('#prefix').addEventListener('keydown', (e)=>{ if(e.key==='Enter') makeCompound(); });
$('#base').addEventListener('keydown', (e)=>{ if(e.key==='Enter') makeCompound(); });
$('#inspect').addEventListener('keydown', (e)=>{ if(e.key==='Enter') analyzeWord(); });

// Initial render
makeCompound();
analyzeWord();

