(() => {
  const $ = (sel) => document.querySelector(sel);
  const inEl = $('#in');
  const outWord = $('#outWord');
  const outExplain = $('#outExplain');
  const syllEl = $('#syll');
  const toggleBtn = $('#toggleMarks');

  const ACUTE = '\u0301';      // combining acute
  const CIRC = '\u0342';      // combining perispomeni
  const DIA = '\u0308';       // diaeresis

  const examples = [
    'κνημις','κρηπις','σφραγις','αψις',
    'Θαις','Λαις','Πτολεμαις','Κωπαις','Θηβαις','Κυρηναις','Ρωμαις','Φωκαις',
    'Βρισηις','Νηρηις','Αιγηις','Ιδηις','Αλυβηις','Δρυοπηις','Μεγαρηις'
  ];

  function normalizeGreek(s){
    return (s || '')
      .trim()
      .normalize('NFD')
      // remove existing accents/length marks; keep diaeresis (we may use it)
      .replace(/[\u0300\u0301\u0302\u0304\u0306\u0342\u0345]/g,'')
      .normalize('NFC');
  }

  function hasDiaeresisOnIota(nfd){
    // look for ι + diaeresis in decomposed form
    return /ι\u0308|Ι\u0308/.test(nfd);
  }

  function endsWithIs(nfc){
    const nfd = nfc.normalize('NFD');
    // allow final sigma ς or σ
    return /(ι(?:\u0308)?)(ς|σ)$/i.test(nfd);
  }

  function guessMode(wordNFC){
    const nfd = wordNFC.normalize('NFD');
    // If there is a diaeresis on iota near the end (…αϊς/ηϊς/ωϊς), treat as “pure -ις” list → acute.
    // Also if sequence αις/ηις/οις/υις with diaeresis implied by user typing 'ι' after vowel, we still guess pure.
    if (/(α|η|ω|ο|ε|υ)ι(ς|σ)$/i.test(wordNFC) || hasDiaeresisOnIota(nfd)) return 'pure';
    // Otherwise default to “long i” bucket → circumflex (toy).
    return 'longi';
  }

  function applyFinalAccent(wordNFC, which){
    const nfd = wordNFC.normalize('NFD');
    // capture last iota (optionally with diaeresis) before final sigma
    const m = nfd.match(/^(.*?)(ι)(\u0308?)(ς|σ)$/i);
    if(!m) return null;
    const pre = m[1], iota = m[2], dia = m[3] || '', sig = m[4];
    const mark = which === 'circ' ? CIRC : ACUTE;
    // place accent after diaeresis if present
    const accented = (pre + iota + dia + mark + sig).normalize('NFC');
    return accented;
  }

  function syllabifyToy(wordNFC){
    // Very rough: split before vowels groups; keep Greek-ish vowels.
    const w = wordNFC.normalize('NFD');
    const vowels = 'αεηιουωΑΕΗΙΟΥΩ';
    let parts = [];
    let cur = '';
    for (let i=0;i<w.length;i++){
      const ch = w[i];
      cur += ch;
      const base = ch;
      const next = w[i+1];
      const isV = vowels.includes(base);
      const nextIsV = next && vowels.includes(next);
      // boundary after vowel when next is consonant (or end)
      if (isV && !nextIsV) {
        parts.push(cur);
        cur='';
      }
    }
    if(cur) parts.push(cur);
    // clean empties
    parts = parts.filter(p => p.length);
    // join with middot
    return parts.map(p=>p.normalize('NFC')).join('·');
  }

  function showCombining(s){
    const nfd = s.normalize('NFD');
    // visualize combining marks
    return nfd.replace(/\u0308/g,'◌̈').replace(/\u0301/g,'◌́').replace(/\u0342/g,'◌͂');
  }

  function currentMode(){
    const checked = document.querySelector('input[name="mode"]:checked');
    return checked ? checked.value : 'auto';
  }

  function run(){
    const raw = inEl.value;
    const cleaned = normalizeGreek(raw);

    if(!cleaned){
      outWord.textContent = '—';
      outExplain.innerHTML = 'Type a word ending in <span class="gr">-ις</span> and click <b>Accent it</b>.';
      syllEl.textContent = '—';
      return;
    }

    if(!endsWithIs(cleaned)){
      outWord.textContent = cleaned;
      outExplain.innerHTML = `<span class="bad">Not an -ις ending</span> (this toy only accents words ending in <span class="gr">-ις</span>).`;
      syllEl.textContent = syllabifyToy(cleaned);
      return;
    }

    let mode = currentMode();
    let chosen = mode;
    if(mode === 'auto') chosen = guessMode(cleaned);

    const accented = applyFinalAccent(cleaned, chosen === 'longi' ? 'circ' : 'acute');
    if(!accented){
      outWord.textContent = cleaned;
      outExplain.innerHTML = `<span class="bad">Couldn’t accent</span> (unexpected spelling).`;
      syllEl.textContent = syllabifyToy(cleaned);
      return;
    }

    const label = chosen === 'pure'
      ? '“pure -ις” → final <b>acute</b>'
      : '“long ι” → final <b>circumflex</b>';

    const autoNote = (mode === 'auto')
      ? `Auto-guess picked: <mark>${chosen}</mark>.`
      : `Mode forced: <mark>${chosen}</mark>.`;

    outWord.textContent = accented;
    outExplain.innerHTML = `<span class="good">Final accent applied</span>: ${label}. ${autoNote}`;
    syllEl.textContent = syllabifyToy(accented);

    if(toggleBtn.getAttribute('aria-pressed') === 'true'){
      outWord.textContent = showCombining(accented);
      syllEl.textContent = showCombining(syllabifyToy(accented));
    }
  }

  $('#go').addEventListener('click', run);
  inEl.addEventListener('keydown', (e) => {
    if(e.key === 'Enter') run();
  });

  document.querySelectorAll('input[name="mode"]').forEach(r => r.addEventListener('change', run));

  $('#clear').addEventListener('click', () => {
    inEl.value = '';
    inEl.focus();
    run();
  });

  $('#random').addEventListener('click', () => {
    const pick = examples[Math.floor(Math.random()*examples.length)];
    inEl.value = pick;
    run();
  });

  toggleBtn.addEventListener('click', () => {
    const pressed = toggleBtn.getAttribute('aria-pressed') === 'true';
    toggleBtn.setAttribute('aria-pressed', String(!pressed));
    toggleBtn.textContent = !pressed ? 'Hide combining marks' : 'Show combining marks';
    run();
  });

  // initial
  run();
})();

