const $ = (sel) => document.querySelector(sel);

const baseEl = $('#base');
const prefixEl = $('#prefix');
const normEl = $('#norm');
const resultEl = $('#result');
const hintEl = $('#hint');
const explainEl = $('#explain');

const examples = [
  {base:'μῆτις', prefix:'πολυ', scenario:'barytone'},
  {base:'χάρις', prefix:'εὐ', scenario:'barytone'},
  {base:'πόλις', prefix:'φιλο', scenario:'barytone'},
  {base:'νυχίς', prefix:'παν', scenario:'oxy_fem_only'},
  {base:'σκελίς', prefix:'περι', scenario:'oxy_fem_only'},
  {base:'ἐλπίς', prefix:'δυσ', scenario:'oxy_becomes_masc'},
  {base:'καταιγίς', prefix:'μελαν', scenario:'oxy_becomes_masc'},
  {base:'δρυμός', prefix:'', scenario:'paronymic'},
  {base:'Παρνασσός', prefix:'', scenario:'paronymic'},
];

// --- Greek helpers (toy-level) ---
const combiningMarks = /[\u0300-\u036f]/g;

function stripDiacritics(s){
  return (s||'')
    .normalize('NFD')
    .replace(combiningMarks,'')
    .normalize('NFC');
}

function stripPunctuationSpaces(s){
  return (s||'').replace(/[\s··.,;:!?"'“”‘’()\[\]{}<>]/g,'');
}

function normalizeGreek(s){
  return stripPunctuationSpaces(stripDiacritics(s));
}

function lastVowelIndex(s){
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
  for(let i=s.length-1;i>=0;i--){
    if(vowels.has(s[i])) return i;
  }
  return -1;
}

function penultVowelIndex(s){
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
  let seen = 0;
  for(let i=s.length-1;i>=0;i--){
    if(vowels.has(s[i])){
      seen++;
      if(seen===2) return i;
    }
  }
  return lastVowelIndex(s);
}

function addAcuteToChar(ch){
  // Add tonos to Greek vowel (rough-and-ready)
  const map = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };
  return map[ch] || ch;
}

function accentAt(s, idx){
  if(idx<0 || idx>=s.length) return s;
  // remove existing diacritics first
  let plain = stripDiacritics(s);
  // if character at idx is not a vowel, do nothing
  const before = plain.slice(0, idx);
  const ch = plain[idx];
  const after = plain.slice(idx+1);
  return (before + addAcuteToChar(ch) + after);
}

function makeOxytone(s){
  const i = lastVowelIndex(s);
  return accentAt(s, i);
}

function makeBarytone(s){
  const i = penultVowelIndex(s);
  return accentAt(s, i);
}

function endsWithIs(s){
  const n = normalizeGreek(s);
  return n.endsWith('ις') || n.endsWith('ις'.toUpperCase());
}

function endsWithOs(s){
  const n = normalizeGreek(s);
  return n.endsWith('ος') || n.endsWith('ος'.toUpperCase());
}

function joinPrefix(prefix, base){
  const p = normalizeGreek(prefix);
  const b = normalizeGreek(base);
  if(!p) return b;
  // very simple sandhi: avoid double vowels? (toy: just concatenate)
  return p + b;
}

function paronymicIsFromOs(word){
  const w = normalizeGreek(word);
  if(!w) return '';
  if(endsWithOs(w)) return w.slice(0,-2) + 'ις';
  // if user already gave -ις, keep it
  if(endsWithIs(w)) return w;
  // otherwise, just add -ις
  return w + 'ις';
}

function scenario(){
  return document.querySelector('input[name="scenario"]:checked')?.value || 'barytone';
}

function setOut({norm, result, hint, explain, bad=false}){
  normEl.textContent = norm || '—';
  resultEl.textContent = result || '—';
  hintEl.innerHTML = hint || '—';
  explainEl.innerHTML = explain || '—';
  if(bad){
    resultEl.classList.add('bad');
  } else {
    resultEl.classList.remove('bad');
  }
}

function generate(){
  const baseRaw = baseEl.value.trim();
  const prefixRaw = prefixEl.value.trim();
  const sc = scenario();

  if(!baseRaw){
    setOut({norm:'', result:'(type a word first)', hint:'', explain:'', bad:true});
    return;
  }

  const baseNorm = normalizeGreek(baseRaw);
  const prefixNorm = normalizeGreek(prefixRaw);

  let formed = '';
  let accented = '';
  let hint = '';
  let explain = '';

  if(sc === 'paronymic'){
    formed = paronymicIsFromOs(baseRaw);
    accented = makeOxytone(formed);
    hint = 'Paronymic <span class="mono">-ις</span> forms are treated as <strong>oxytone</strong> (acute on the last syllable) in this toy.';
    explain = `Made a derivative in <span class="mono">-ις</span> (often from <span class="mono">-ος</span>): <span class="mono">${stripDiacritics(baseRaw)}</span> → <span class="mono">${formed}</span>, then accented it oxytone.`;
    setOut({norm: baseNorm, result: accented, hint, explain});
    return;
  }

  // For compound scenarios, require -ις base (loosely)
  if(!endsWithIs(baseRaw)){
    formed = joinPrefix(prefixNorm, baseNorm);
    setOut({
      norm: baseNorm,
      result: '(base should end in -ις for this mode)',
      hint: 'Try switching to “paronymic” mode, or enter a base ending in <span class="mono">-ις</span>.',
      explain: `You entered <span class="mono">${stripDiacritics(baseRaw)}</span>, which doesn’t look like it ends in <span class="mono">-ις</span> after normalization.`,
      bad:true
    });
    return;
  }

  formed = joinPrefix(prefixNorm, baseNorm);

  if(sc === 'barytone'){
    accented = makeBarytone(formed);
    hint = 'Herodian: barytone <span class="mono">-ις</span> words tend to stay barytone in compounds.';
    explain = `Compound formed as <span class="mono">${prefixNorm || '(no prefix)'}</span> + <span class="mono">${baseNorm}</span> → <span class="mono">${formed}</span>. Then accented <strong>barytone</strong> (toy: acute on penult vowel).`;
  } else if(sc === 'oxy_fem_only'){
    accented = makeOxytone(formed);
    hint = 'Herodian: oxytone feminine <span class="mono">-ις</span> that stays feminine in composition keeps the same tone.';
    explain = `Compound formed as <span class="mono">${prefixNorm || '(no prefix)'}</span> + <span class="mono">${baseNorm}</span> → <span class="mono">${formed}</span>. Then kept it <strong>oxytone</strong> (toy: acute on last vowel).`;
  } else if(sc === 'oxy_becomes_masc'){
    accented = makeBarytone(formed);
    hint = 'Herodian: if an oxytone feminine <span class="mono">-ις</span> compound becomes “transferable” (also masculine), it shifts to barytone.';
    explain = `Compound formed as <span class="mono">${prefixNorm || '(no prefix)'}</span> + <span class="mono">${baseNorm}</span> → <span class="mono">${formed}</span>. Then shifted to <strong>barytone</strong> (toy: acute on penult vowel).`;
  }

  setOut({norm: baseNorm, result: accented, hint, explain});
}

function loadExample(){
  const ex = examples[Math.floor(Math.random()*examples.length)];
  baseEl.value = ex.base;
  prefixEl.value = ex.prefix;
  const r = document.querySelector(`input[name="scenario"][value="${ex.scenario}"]`);
  if(r) r.checked = true;
  generate();
}

$('#go').addEventListener('click', generate);
$('#shuffle').addEventListener('click', loadExample);
$('#clear').addEventListener('click', () => {
  baseEl.value='';
  prefixEl.value='';
  setOut({norm:'', result:'—', hint:'—', explain:'—'});
  baseEl.focus();
});

// live update
baseEl.addEventListener('input', () => { if(baseEl.value.trim().length>0) generate(); });
prefixEl.addEventListener('input', () => { if(baseEl.value.trim().length>0) generate(); });
document.querySelectorAll('input[name="scenario"]').forEach(el => el.addEventListener('change', generate));

// initial
setOut({norm:'', result:'—', hint:'Type a word and click Generate (or “Try an example”).', explain:'—'});

