(() => {
  const $ = (sel, el=document) => el.querySelector(sel);
  const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

  const inp = $('#inp');
  const btnGo = $('#btnGo');
  const btnClear = $('#btnClear');
  const ruleBox = $('#ruleBox');
  const accentGuess = $('#accentGuess');
  const out = $('#out');
  const keepBreath = $('#keepBreath');
  const stripAll = $('#stripAll');

  const lastWordEl = $('#lastWord');
  const endingEl = $('#ending');
  const syllEl = $('#syll');
  const nowAccentEl = $('#nowAccent');

  // --- Greek diacritics helpers ---
  const COMBINING = {
    acute: '\u0301',
    grave: '\u0300',
    circumflex: '\u0342',
    smooth: '\u0313',
    rough: '\u0314',
    diaeresis: '\u0308',
    iotaSub: '\u0345',
    macron: '\u0304',
    breve: '\u0306'
  };

  const isGreekLetter = (ch) => /[\u0370-\u03FF\u1F00-\u1FFF]/.test(ch);
  const isCombining = (ch) => /[\u0300-\u036F]/.test(ch);

  function stripDiacritics(s){
    return s.normalize('NFD').replace(/[\u0300-\u036F]/g,'').normalize('NFC');
  }

  function stripAccentMarksKeepBreathings(s){
    // remove acute/grave/circumflex only
    return s.normalize('NFD')
      .replace(new RegExp('['+COMBINING.acute+COMBINING.grave+COMBINING.circumflex+']','g'),'')
      .normalize('NFC');
  }

  function stripAllDiacriticsOption(s){
    return stripAll.checked ? stripDiacritics(s) : s;
  }

  function detectAccentType(word){
    const nfd = word.normalize('NFD');
    if (nfd.includes(COMBINING.acute)) return 'acute';
    if (nfd.includes(COMBINING.circumflex)) return 'circumflex';
    if (nfd.includes(COMBINING.grave)) return 'grave';
    return 'none';
  }

  const VOWELS = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

  function isVowelBase(ch){
    return VOWELS.has(ch);
  }

  function graphemes(s){
    // crude grapheme splitter: base char + following combining marks
    const nfd = s.normalize('NFD');
    const out = [];
    let buf = '';
    for (const ch of nfd){
      if (!buf){ buf = ch; continue; }
      if (isCombining(ch)) buf += ch;
      else { out.push(buf); buf = ch; }
    }
    if (buf) out.push(buf);
    return out.map(g => g.normalize('NFC'));
  }

  function lastGreekWord(text){
    const parts = text.trim().split(/\s+/).filter(Boolean);
    if (!parts.length) return '';
    // take last token, strip trailing punctuation
    return parts[parts.length-1].replace(/[··.,;:!?"'“”‘’()\[\]{}<>]/g,'');
  }

  function ending(word){
    const plain = stripDiacritics(word);
    const low = plain.toLowerCase();
    if (low.endsWith('βις')) return '-βις';
    if (low.endsWith('σις')) return '-σις';
    if (low.endsWith('ις')) return '-ις';
    return '(other)';
  }

  function syllableishCount(word){
    // count vowel nuclei (very rough)
    const plain = stripDiacritics(word);
    let c = 0;
    for (const ch of plain){
      if (isVowelBase(ch)) c++;
    }
    return c || 0;
  }

  function applyAccent(word, kind){
    // kind: 'oxytone' (acute on last vowel) or 'barytone' (circumflex on penult vowel if possible else acute on penult)
    let w = stripAllDiacriticsOption(word);
    w = keepBreath.checked ? stripAccentMarksKeepBreathings(w) : stripDiacritics(w);

    const gs = graphemes(w);
    // find vowel positions
    const vowelIdx = [];
    for (let i=0;i<gs.length;i++){
      const base = gs[i].normalize('NFD')[0];
      if (isVowelBase(base)) vowelIdx.push(i);
    }
    if (!vowelIdx.length) return w;

    const addMark = (g, mark) => {
      const nfd = g.normalize('NFD');
      // insert mark after base and after breathing if present
      // keep existing diaeresis/iota sub etc.
      const base = nfd[0];
      const rest = nfd.slice(1);
      // remove any accent marks just in case
      const cleaned = rest.replace(new RegExp('['+COMBINING.acute+COMBINING.grave+COMBINING.circumflex+']','g'),'');
      // place mark after any breathing marks at start of combining sequence
      let prefix = '';
      let suffix = cleaned;
      // breathings are combining; if present, keep them immediately after base
      const m = cleaned.match(new RegExp('^(['+COMBINING.smooth+COMBINING.rough+']+)'));
      if (m){
        prefix = m[1];
        suffix = cleaned.slice(prefix.length);
      }
      return (base + prefix + mark + suffix).normalize('NFC');
    };

    if (kind === 'oxytone'){
      const i = vowelIdx[vowelIdx.length-1];
      gs[i] = addMark(gs[i], COMBINING.acute);
      return gs.join('');
    }

    // barytone: prefer penult vowel
    const target = vowelIdx.length >= 2 ? vowelIdx[vowelIdx.length-2] : vowelIdx[0];
    // circumflex as a playful stand-in
    gs[target] = addMark(gs[target], COMBINING.circumflex);
    return gs.join('');
  }

  function guessRule(word){
    const plain = stripDiacritics(word).toLowerCase();

    // -σις abstracts (ποιησις, γνωσις, πραξις etc.) -> barytone per passage
    if (plain.endsWith('σις')){
      return {
        guess: 'barytone',
        label: 'Abstract in -σις (often from a future): tends to be barytone (ποιήσω → ποίησις, γνώσω → γνῶσις).'
      };
    }

    // -βις: disyllables mixed; try a tiny whitelist from passage
    if (plain.endsWith('βις')){
      const knownAcute = new Set(['λεσβις','λαβις','βαλβις','νιοβις','λυκαμβις','περραιβις','κανωβις','ερεμβις','τορρηβις']);
      const knownBary = new Set(['ιβις','νιβις','ταβις','ναρβις','ζομβις','χεμβις','αρβις','αραβις']);
      if (knownAcute.has(plain)){
        return {guess:'oxytone', label:"-βις adjective/paronym (passage examples): tends to be oxytone (e.g. Λεσβίς, βαλβίς)."};
      }
      if (knownBary.has(plain)){
        return {guess:'barytone', label:"-βις place/ethnic name of the other type (passage examples): tends to be barytone (e.g. ἶβις, Νίβις)."};
      }
      // heuristic: if 2 syllables, ambiguous; else often acute for adjectives/paronyms
      const syl = syllableishCount(word);
      if (syl <= 2) return {guess:'(either)', label:"Disyllabic -βις can be oxytone or barytone; try both."};
      return {guess:'oxytone', label:"Polysyllabic -βις often oxytone (esp. adjectives/paronyms), though some are proparoxytone; toy picks oxytone."};
    }

    // -ις: patronymics/diminutives often acute; but -σις already handled
    if (plain.endsWith('ις')){
      // special case mentioned: ιφις barytone
      if (plain === 'ιφις' || plain === 'ἰφις'){
        return {guess:'barytone', label:"Ἶφις is noted as barytone (from ἶφι)."};
      }
      // heuristic: if ends with -αντις/-ονις/-αρις etc. treat as patronymic-pattern -> acute
      if (/(αρις|αντις|ονις|ωνις|ιστονις|αβαντις)$/.test(plain)){
        return {guess:'oxytone', label:"Looks like a patronymic/ethnic pattern in -ις: tends to be oxytone (Πριαμίς, Τυνδαρίς, Ἑλικωνίς…)."};
      }
      return {guess:'oxytone', label:"Many -ις patronymics/diminutives are oxytone in the passage; toy defaults to oxytone."};
    }

    return {guess:'(n/a)', label:"No -ις/-βις ending detected; toy has no Herodian-based guess."};
  }

  function reaccentLastWord(text, guess){
    const lw = lastGreekWord(text);
    if (!lw) return {lw:'', out:text};

    let kind = null;
    if (guess === 'oxytone') kind = 'oxytone';
    else if (guess === 'barytone') kind = 'barytone';
    else return {lw, out:text};

    const accented = applyAccent(lw, kind);
    // replace last occurrence of lw in text (token-based)
    const parts = text.trim().split(/\s+/);
    parts[parts.length-1] = parts[parts.length-1].replace(lw, accented);
    return {lw, out: parts.join(' ')};
  }

  function render(){
    const text = inp.value;
    const lw = lastGreekWord(text);

    lastWordEl.textContent = lw || '—';
    endingEl.textContent = lw ? ending(lw) : '—';
    syllEl.textContent = lw ? String(syllableishCount(lw)) : '—';
    nowAccentEl.textContent = lw ? detectAccentType(lw) : '—';

    if (!lw){
      ruleBox.textContent = '—';
      accentGuess.textContent = '—';
      out.textContent = '—';
      return;
    }

    const g = guessRule(lw);
    ruleBox.textContent = g.label;

    let guess = g.guess;
    accentGuess.textContent = guess;

    if (guess === '(either)'){
      const ox = applyAccent(lw, 'oxytone');
      const ba = applyAccent(lw, 'barytone');
      out.textContent = `Try: ${ox}  |  ${ba}`;
      return;
    }

    if (guess === '(n/a)'){
      out.textContent = text;
      return;
    }

    const rr = reaccentLastWord(text, guess);
    out.textContent = rr.out;
  }

  btnGo.addEventListener('click', render);
  inp.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') render();
  });
  btnClear.addEventListener('click', () => {
    inp.value = '';
    render();
    inp.focus();
  });

  $$('.chip').forEach(b => b.addEventListener('click', () => {
    inp.value = b.dataset.ex;
    render();
    inp.focus();
  }));

  keepBreath.addEventListener('change', render);
  stripAll.addEventListener('change', render);

  // initial
  inp.value = 'ποιησις';
  render();
})();

