(function(){
  const $ = (sel, root=document) => root.querySelector(sel);
  const inp = $('#inp');
  const btn = $('#btn');
  const btnRandom = $('#btnRandom');
  const endingEl = $('#ending');
  const guessEl = $('#guess');
  const accentedEl = $('#accented');
  const explainEl = $('#explain');
  const chkAccent = $('#chkAccent');
  const chkExplain = $('#chkExplain');

  const examples = [
    'αἰγίς','μαγίς','σφαγίς','σφραγίς','Βρυγίς','Γέργις','γέλγις','γίγγις',
    'στρατηγίς','ἁλουργίς','ἀμοργίς','ἄμοργις','Μέσσωγις',
    'Μηδίς','Ἀσπενδίς','Λαρανδίς','Σάρδις','Βῖδις','Βούσμαδις',
    'Ῥίζις',
    'πληθίς','Ἀτθίς','τηθίς','Σκυθίς','Τευθίς','Παρθίς','Δένθις','κόρθις','Κρᾶθις'
  ];

  // --- Greek normalization helpers ---
  function stripDiacritics(s){
    // Remove combining marks (accents, breathings, iota subscript, diaeresis, etc.)
    return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  }
  function normalizeGreek(s){
    if(!s) return '';
    s = s.trim();
    // normalize final sigma
    s = s.replace(/ς/g,'σ');
    // lowercase
    s = s.toLowerCase();
    // strip diacritics for matching
    s = stripDiacritics(s);
    // keep only Greek letters
    s = s.replace(/[^\u0370-\u03ff\u1f00-\u1fff]/g,'');
    return s;
  }

  function detectEnding(norm){
    const endings = ['γις','δις','ζις','θις'];
    for(const e of endings){
      if(norm.endsWith(e)) return e;
    }
    return null;
  }

  // crude syllable count: count vowel groups
  function countSyllables(norm){
    const vowels = 'αεηιουω';
    let n=0, prevV=false;
    for(const ch of norm){
      const isV = vowels.includes(ch);
      if(isV && !prevV) n++;
      prevV = isV;
    }
    return Math.max(1,n);
  }

  // Apply a toy acute to the last vowel group (oxytone) or to the penult vowel group (barytone-ish)
  // Not philologically exact; just a visual cue.
  const acuteMap = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };
  function addAcuteToVowelAtGroup(word, groupIndexFromEnd){
    // groupIndexFromEnd: 1 = last vowel group, 2 = penult vowel group
    const chars = Array.from(word);
    const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
    // find vowel groups positions (store last vowel char index of each group)
    let groups=[];
    let inGroup=false;
    for(let i=0;i<chars.length;i++){
      const isV = vowels.has(stripDiacritics(chars[i]));
      if(isV){
        if(!inGroup){
          groups.push([]);
          inGroup=true;
        }
        groups[groups.length-1].push(i);
      } else {
        inGroup=false;
      }
    }
    if(groups.length===0) return word;
    const targetGroup = groups[groups.length - groupIndexFromEnd];
    if(!targetGroup) return word;
    // accent the last vowel char of that group
    const idx = targetGroup[targetGroup.length-1];
    const base = stripDiacritics(chars[idx]);
    const repl = acuteMap[base] || chars[idx];
    chars[idx] = repl;
    return chars.join('');
  }

  function analyze(word){
    const raw = (word||'').trim();
    const norm = normalizeGreek(raw);

    if(!raw){
      endingEl.textContent = '—';
      guessEl.innerHTML = '—';
      accentedEl.textContent = '—';
      explainEl.textContent = chkExplain.checked ? 'Type a word ending in -γις, -δις, -ζις, or -θις.' : '';
      return;
    }

    const ending = detectEnding(norm);
    const sylls = countSyllables(norm);

    let guess = 'Unknown';
    let rule = 'No matching ending (-γις/-δις/-ζις/-θις) detected.';

    // Noted exceptions from the passage (normalized)
    const notedBary = new Set(['αμοργις','μεσσωγις','γεργις','δενθις','κορθις','κραθις']);

    if(ending){
      if(ending==='ζις'){
        guess = 'Barytone';
        rule = 'Rule: forms in -ζις are barytone (e.g. Ῥίζις).';
      } else if(ending==='γις'){
        if(notedBary.has(norm)){
          guess = 'Barytone';
          rule = 'Noted exception: this specific -γις form is marked barytone in the passage.';
        } else if(sylls===2){
          if(norm.startsWith('γ')){
            guess = 'Barytone';
            rule = 'Rule: disyllables in -γις are oxytone, unless they begin with γ- → barytone (Γέργις).';
          } else {
            guess = 'Oxytone';
            rule = 'Rule: disyllables in -γις are oxytone (αἰγίς, μαγίς, etc.).';
          }
        } else {
          // polysyllables
          guess = 'Oxytone';
          rule = 'Rule: polysyllables in -γις are generally oxytone (στρατηγίς, ἁλουργίς, ἀμοργίς), with some noted barytone exceptions.';
        }
      } else if(ending==='δις'){
        // We can’t detect “derivative” reliably; offer a toggle-like heuristic.
        if(notedBary.has(norm)){
          guess = 'Barytone';
          rule = 'Noted exception: marked barytone.';
        } else {
          // heuristic: if starts with capital? not reliable. We'll do: default barytone, but allow user to treat as derivative by prefix marker.
          // Instead: if user types leading * (asterisk) we treat as derivative.
          const isDerivativeHint = raw.trim().startsWith('*');
          if(isDerivativeHint){
            guess = 'Oxytone';
            rule = 'User hint: leading * treated as “derivative in -δις” → oxytone (Μηδίς, Ἀσπενδίς, Λαρανδίς).';
          } else {
            guess = 'Barytone';
            rule = 'Heuristic: many -δις are barytone (Σάρδις, Βῖδις). If you mean a “derivative in -δις”, prefix the word with * to force oxytone.';
          }
        }
      } else if(ending==='θις'){
        if(notedBary.has(norm)){
          guess = 'Barytone';
          rule = 'Noted exception: Δένθις / κόρθις / Κρᾶθις are explicitly noted.';
        } else if(sylls===2){
          guess = 'Oxytone';
          rule = 'Rule: disyllables in -θις are oxytone (πληθίς, Ἀτθίς, etc.), unless special gender-shift conditions apply (not modeled here).';
        } else {
          guess = 'Oxytone';
          rule = 'Heuristic: this toy treats -θις as oxytone by default, except for noted exceptions.';
        }
      }
    }

    endingEl.textContent = ending ? ('-' + ending) : '—';

    const badgeClass = guess==='Oxytone' ? 'oxy' : (guess==='Barytone' ? 'bary' : 'unk');
    guessEl.innerHTML = `${guess} <span class="badge ${badgeClass}">${guess==='Oxytone'?'accent on last':'not on last'}</span>`;

    // Accent suggestion
    if(chkAccent.checked){
      // remove leading * if present
      const cleanRaw = raw.replace(/^\*\s*/,'');
      let toy;
      if(guess==='Oxytone') toy = addAcuteToVowelAtGroup(stripDiacritics(cleanRaw), 1);
      else if(guess==='Barytone') toy = addAcuteToVowelAtGroup(stripDiacritics(cleanRaw), 2);
      else toy = stripDiacritics(cleanRaw);
      accentedEl.textContent = toy;
    } else {
      accentedEl.textContent = '—';
    }

    explainEl.textContent = chkExplain.checked ? rule : '';
  }

  btn.addEventListener('click', ()=>analyze(inp.value));
  inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') analyze(inp.value); });
  btnRandom.addEventListener('click', ()=>{
    const w = examples[Math.floor(Math.random()*examples.length)];
    inp.value = w;
    analyze(w);
    inp.focus();
  });
  chkAccent.addEventListener('change', ()=>analyze(inp.value));
  chkExplain.addEventListener('change', ()=>analyze(inp.value));

  // initial
  inp.value = 'αἰγίς';
  analyze(inp.value);
})();

