const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const mode = $('#mode');
const accentSel = $('#accent');
const outWord = $('#outWord');
const outMeta = $('#outMeta');
const meter = $('#meter');
const mEnding = $('#mEnding');
const mSyl = $('#mSyl');
const mEgypt = $('#mEgypt');
const mRule = $('#mRule');
const chipsBox = $('#chips');
const toggleList = $('#toggleList');
const listBox = $('#listBox');
const randomBtn = $('#random');

// Egyptian city names in -θις mentioned as barytone in the passage.
const egyptThis = [
  'Ταμίαθις','Μένουθις','Τερένουθις','Θέρμουθις','Ἔλβονθις','Φενέβηθις','Ἕρμωνθις'
];

const examples = [
  'κολοκυνθις','ακανθις','αγαθις','Ασπαλαθις','Ημαθις','Ερυμανθις','Παρνηθις',
  'Φωκις','χαλκις','κερκις','Γραικις','Κικις','παλλακις','πινακις','φαρμακις'
];

function stripDiacritics(s){
  // Remove combining marks after NFD; keep Greek letters.
  return (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function lowerGreek(s){
  return stripDiacritics(s).toLowerCase();
}

function detectEnding(s){
  const t = lowerGreek(s).replace(/[^\p{L}]+/gu,'');
  if (t.endsWith('θις')) return 'θις';
  if (t.endsWith('κις')) return 'κις';
  return null;
}

function roughSyllables(s){
  // Very rough: count vowel groups in stripped text.
  const t = lowerGreek(s).replace(/[^\p{L}]+/gu,'');
  if (!t) return 0;
  const vowels = 'αεηιουω';
  let count = 0;
  let prevV = false;
  for (const ch of t){
    const isV = vowels.includes(ch);
    if (isV && !prevV) count++;
    prevV = isV;
  }
  return count;
}

function isEgyptianThis(s){
  const t = lowerGreek(s).replace(/[^\p{L}]+/gu,'');
  return egyptThis.some(w => lowerGreek(w).replace(/[^\p{L}]+/gu,'') === t);
}

function accentChar(baseVowel, accentType){
  // Return precomposed where possible; otherwise combining.
  const acute = '\u0301';
  const circumflex = '\u0342';
  if (accentType === 'none') return baseVowel;
  const mark = accentType === 'acute' ? acute : circumflex;
  return (baseVowel.normalize('NFD') + mark).normalize('NFC');
}

function applyAccentBeforeEnding(original, ending, accentType){
  // Place accent on the last vowel before the ending in the *stripped* letter stream,
  // then map back onto a simplified output (we output stripped letters + accent).
  const letters = stripDiacritics(original).replace(/[^\p{L}]+/gu,'');
  if (!letters) return '';

  const low = letters.toLowerCase();
  const idxEnd = low.lastIndexOf(ending);
  if (idxEnd < 0) return letters; // no change

  const stem = letters.slice(0, idxEnd);
  const tail = letters.slice(idxEnd);

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
  let i = stem.length - 1;
  while (i >= 0 && !vowels.has(stem[i])) i--;
  if (i < 0) return letters;

  const accentedStem = stem.slice(0, i) + accentChar(stem[i], accentType) + stem.slice(i+1);
  return accentedStem + tail;
}

function decideRule(word){
  const ending = detectEnding(word);
  const syl = roughSyllables(word);
  const egypt = ending === 'θις' ? isEgyptianThis(word) : false;

  let applied = {accentType:'none', label:'No rule applied', ending, syl, egypt};

  const m = mode.value;
  if (m === 'manual'){
    applied.accentType = accentSel.value;
    applied.label = `Manual: ${accentSel.options[accentSel.selectedIndex].text}`;
    return applied;
  }

  if (m === 'this-non-egypt'){
    applied.accentType = 'acute';
    applied.label = '-θις (>2 syllables), non-Egyptian → acute';
    return applied;
  }
  if (m === 'this-egypt'){
    applied.accentType = 'circumflex';
    applied.label = 'Egyptian city in -θις → “grave/heavy” (shown as circumflex)';
    return applied;
  }
  if (m === 'kis-disyl'){
    applied.accentType = 'acute';
    applied.label = '-κις (disyllable) → acute';
    return applied;
  }

  // auto
  if (ending === 'θις'){
    if (egypt){
      applied.accentType = 'circumflex';
      applied.label = 'Auto: Egyptian -θις → “grave/heavy” (shown as circumflex)';
    } else if (syl > 2){
      applied.accentType = 'acute';
      applied.label = 'Auto: -θις & >2 syllables → acute';
    } else {
      applied.accentType = 'none';
      applied.label = 'Auto: -θις but not >2 syllables → no guess';
    }
    return applied;
  }

  if (ending === 'κις'){
    if (syl === 2){
      applied.accentType = 'acute';
      applied.label = 'Auto: -κις & disyllable → acute';
    } else {
      applied.accentType = 'none';
      applied.label = 'Auto: -κις but not disyllable → no guess';
    }
    return applied;
  }

  applied.label = 'Auto: word does not end in -θις or -κις';
  return applied;
}

function render(){
  const w = inp.value.trim();
  if (!w){
    outWord.textContent = '—';
    outMeta.textContent = 'Type a word to begin.';
    meter.hidden = true;
    return;
  }

  const info = decideRule(w);
  const ending = info.ending;

  let out = stripDiacritics(w);
  if (ending && info.accentType !== 'none'){
    out = applyAccentBeforeEnding(w, ending, info.accentType);
  }

  outWord.textContent = out;

  const endingLabel = ending ? `-${ending}` : '—';
  const egyptLabel = info.egypt ? 'yes' : 'no';

  outMeta.textContent = info.label;
  meter.hidden = false;
  mEnding.textContent = endingLabel;
  mSyl.textContent = String(info.syl);
  mEgypt.textContent = egyptLabel;
  mRule.textContent = info.accentType === 'none' ? 'none' : info.accentType;
}

function buildChips(){
  chipsBox.innerHTML = '';
  egyptThis.forEach(w => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip';
    b.textContent = w;
    b.addEventListener('click', () => {
      inp.value = w;
      render();
      inp.focus();
    });
    chipsBox.appendChild(b);
  });
}

inp.addEventListener('input', render);
mode.addEventListener('change', () => {
  accentSel.disabled = (mode.value !== 'manual');
  render();
});
accentSel.addEventListener('change', render);

toggleList.addEventListener('click', () => {
  listBox.open = !listBox.open;
  toggleList.textContent = listBox.open ? 'Hide' : 'Show';
});

randomBtn.addEventListener('click', () => {
  const pick = examples[Math.floor(Math.random()*examples.length)];
  inp.value = pick;
  render();
  inp.focus();
});

// init
buildChips();
accentSel.disabled = true;
render();

