(() => {
  const $ = (sel, el=document) => el.querySelector(sel);

  const inp = $('#inp');
  const btn = $('#btn');
  const btnRandom = $('#btnRandom');
  const btnClear = $('#btnClear');

  const optNormalize = $('#optNormalize');
  const optGrave = $('#optGrave');
  const optExplain = $('#optExplain');

  const flagCity = $('#flagCity');
  const flagTheta = $('#flagTheta');
  const flagDimin = $('#flagDimin');

  const detEnding = $('#detEnding');
  const detAccent = $('#detAccent');
  const detWord = $('#detWord');
  const detWhy = $('#detWhy');
  const why = $('#why');

  const samples = [
    'φυλλις','κιγκλις','θυλλις','Ὑλλις','Βυβλις','Βρυλλις','Τραλλις','Βυλλις','δελλις','βαλλις',
    'βολις','φολις','σελις','ψαλις','πυλις','πρυλις','Τυλις',
    'Σαλμακις','Βυζακις','Ιωλκις','Τεμμικις','Σελευκις','Ναρθηκις'
  ];

  // --- Greek helpers ---
  const COMBINING = /[\u0300-\u036f]/g;

  function nfd(s){ return s.normalize('NFD'); }
  function nfc(s){ return s.normalize('NFC'); }

  function stripDiacritics(s){
    return nfd(s).replace(COMBINING,'');
  }

  function normalizeGreek(s){
    if(!s) return '';
    let t = s.trim();
    // unify final sigma
    t = t.replace(/ς/g,'σ');
    // strip punctuation-ish
    t = t.replace(/[··.,;:!?"'“”‘’()\[\]{}<>]/g,'');
    // collapse spaces
    t = t.replace(/\s+/g,' ');
    return t;
  }

  function lastIndexOfAny(str, chars){
    for(let i=str.length-1;i>=0;i--){
      if(chars.includes(str[i])) return i;
    }
    return -1;
  }

  const VOWELS = 'αεηιουω';

  function findLastVowelIndex(word){
    const w = word;
    for(let i=w.length-1;i>=0;i--){
      if(VOWELS.includes(w[i])) return i;
    }
    return -1;
  }

  function applyAcuteOnLastVowel(word){
    // naive: add combining acute to last vowel
    const idx = findLastVowelIndex(word);
    if(idx<0) return word;
    const base = word.slice(0, idx+1) + '\u0301' + word.slice(idx+1);
    return nfc(base);
  }

  function applyGraveOnLastVowel(word){
    const idx = findLastVowelIndex(word);
    if(idx<0) return word;
    const base = word.slice(0, idx+1) + '\u0300' + word.slice(idx+1);
    return nfc(base);
  }

  function titleCaseGreek(s){
    if(!s) return s;
    return s[0].toUpperCase() + s.slice(1);
  }

  // --- Heuristic analysis inspired by Herodian 1.89 ---
  function analyze(raw){
    const explain = [];

    let w = raw || '';
    if(optNormalize.checked){
      w = normalizeGreek(w);
      w = stripDiacritics(w);
      explain.push('Normalization on: stripped accents/diacritics and unified final sigma (ς→σ).');
    } else {
      w = normalizeGreek(w);
      explain.push('Normalization off: kept any accents you typed (but removed punctuation and unified final sigma).');
    }

    // Keep spaces? We’ll analyze last token.
    const parts = w.split(' ').filter(Boolean);
    const token = parts.length ? parts[parts.length-1] : '';

    if(!token){
      return { ok:false, token:'', ending:'—', accent:'—', out:'—', why:'Type a Greek word.' };
    }

    const lower = token.toLowerCase();

    // detect endings
    let ending = 'other';
    if(lower.endsWith('λις')) ending = '-λις';
    else if(lower.endsWith('κις')) ending = '-κίς (place/ethnic type in the list)';

    // flags
    const isCity = flagCity.checked;
    const isTheta = flagTheta.checked;
    const isDimin = flagDimin.checked;

    // built-in known examples from passage (toy knowledge)
    const knownCity = new Set(['τραλλισ','βυλλισ','τυλισ','σαλμακισ']);
    const knownTheta = new Set(['δελλισ']);
    const knownDimin = new Set(['πυλισ']);

    const normKey = lower;
    const autoCity = knownCity.has(normKey);
    const autoTheta = knownTheta.has(normKey);
    const autoDimin = knownDimin.has(normKey);

    const city = isCity || autoCity;
    const theta = isTheta || autoTheta;
    const dimin = isDimin || autoDimin;

    if(autoCity && !isCity) explain.push('Recognized as a city-name example from the passage (auto-flagged).');
    if(autoTheta && !isTheta) explain.push('Recognized as a “θ-declension” example from the passage (auto-flagged).');
    if(autoDimin && !isDimin) explain.push('Recognized as a diminutive example from the passage (auto-flagged).');

    // Determine consonant cluster / doubled lambda before -ις
    // Look at the segment before final "ις": ... X ι σ
    let hasDoubleL = false;
    let hasCluster = false;
    if(lower.endsWith('λις')){
      const stem = lower.slice(0, -2); // remove "ις" leaving ...λ
      // check for ...λλις
      hasDoubleL = lower.includes('λλις');
      // cluster: two consonants immediately before the iota (i.e., before "ις")
      // approximate: check last 3 letters before "ις": e.g. γκλ- in κιγκλις
      const pre = lower.slice(0, -2); // ends with λ
      const beforeIota = lower.slice(0, -2); // same
      // check pattern: ...C C λ ι σ (like γκλ)
      const c1 = lower[lower.length-5];
      const c2 = lower[lower.length-4];
      const c3 = lower[lower.length-3]; // should be λ
      const isConsonant = (ch) => ch && !VOWELS.includes(ch) && ch !== ' ';
      if(c3 === 'λ' && isConsonant(c1) && isConsonant(c2)) hasCluster = true;
    }

    // disyllable guess: count vowels
    const vowelCount = [...lower].filter(ch => VOWELS.includes(ch)).length;
    const isDisyllable = vowelCount === 2;

    // begins with pi
    const beginsWithPi = lower.startsWith('π');

    // Decide accent class
    let accentClass = 'acute'; // default oxytone
    let ruleTag = '';

    if(ending !== '-λις'){
      // For -κις list: many are oxytone in the examples (Ἀρσακίς etc.)
      accentClass = 'acute';
      ruleTag = 'List-like place/ethnic in -κίς → oxytone (toy default).';
    } else {
      // Herodian: clusters/double-l -> acute unless theta-declension or city
      if((hasCluster || hasDoubleL)){
        accentClass = 'acute';
        ruleTag = 'Cluster or doubled λ → oxytone (ὀξύνεται).';
        if(theta){
          accentClass = 'other';
          ruleTag = 'Exception: “declined through θ” (toy treats as not-oxytone).';
        } else if(city){
          accentClass = 'other';
          ruleTag = 'Exception: city-name (toy treats as not-oxytone).';
        }
      } else if(isDisyllable){
        accentClass = 'acute';
        ruleTag = 'Disyllable in -λις (short penult assumed) → oxytone.';
        if(beginsWithPi){
          accentClass = 'other';
          ruleTag = 'Exception: begins with π (Herodian notes different accent).';
        }
        if(dimin){
          accentClass = 'other';
          ruleTag = 'Exception: diminutive (toy treats as not-oxytone).';
        }
      } else {
        accentClass = 'acute';
        ruleTag = 'Fallback: treat -λις as oxytone (toy default).';
        if(city || theta || dimin){
          accentClass = 'other';
          ruleTag = 'Fallback overridden by an exception toggle.';
        }
      }
    }

    explain.push(`Detected ending: ${ending}.`);
    if(ending === '-λις'){
      explain.push(`Heuristic checks: ${hasDoubleL ? 'has <mark>λλ</mark>' : 'no <mark>λλ</mark>'}; ${hasCluster ? 'has consonant cluster before -ις' : 'no clear cluster'}; ${isDisyllable ? 'disyllable-ish' : 'not disyllable-ish'}; ${beginsWithPi ? 'begins with π' : 'does not begin with π'}.`);
    }
    if(city) explain.push('Exception flag active: “city-name”.');
    if(theta) explain.push('Exception flag active: “θ-declension”.');
    if(dimin) explain.push('Exception flag active: “diminutive”.');
    explain.push(ruleTag);

    // Build output word with accent
    let outWord = token;
    // strip any existing combining marks if normalize is on; if off, still re-accent by stripping to avoid double accents
    outWord = stripDiacritics(normalizeGreek(outWord)).replace(/ς/g,'σ');

    let accentLabel = '';
    if(accentClass === 'acute'){
      accentLabel = optGrave.checked ? 'acute (→ grave in running text)' : 'acute';
      outWord = applyAcuteOnLastVowel(outWord);
      if(optGrave.checked) outWord = applyGraveOnLastVowel(stripDiacritics(outWord));
    } else {
      accentLabel = 'grave/other (toy: not oxytone)';
      // toy choice: put circumflex? too hard; we’ll place grave on last vowel to visualize “not acute”
      outWord = applyGraveOnLastVowel(outWord);
    }

    // restore final sigma for display
    outWord = outWord.replace(/σ$/,'ς');

    return {
      ok:true,
      token,
      ending,
      accent: accentLabel,
      out: outWord,
      why: explain.join('<br>')
    };
  }

  function render(){
    const res = analyze(inp.value);
    detEnding.textContent = res.ending;
    detAccent.textContent = res.accent;
    detWord.textContent = res.out;

    if(optExplain.checked){
      why.style.display = '';
      detWhy.innerHTML = res.why;
    } else {
      why.style.display = 'none';
    }
  }

  function setSample(){
    const s = samples[Math.floor(Math.random()*samples.length)];
    inp.value = s;
    // auto-set toggles for a few samples
    const key = stripDiacritics(normalizeGreek(s)).toLowerCase().replace(/ς/g,'σ');
    flagCity.checked = ['τραλλισ','βυλλισ','τυλισ','σαλμακισ'].includes(key);
    flagTheta.checked = ['δελλισ'].includes(key);
    flagDimin.checked = ['πυλισ'].includes(key);
    render();
    inp.focus();
    inp.setSelectionRange(inp.value.length, inp.value.length);
  }

  btn.addEventListener('click', render);
  btnRandom.addEventListener('click', setSample);
  btnClear.addEventListener('click', () => {
    inp.value = '';
    flagCity.checked = flagTheta.checked = flagDimin.checked = false;
    render();
    inp.focus();
  });

  inp.addEventListener('keydown', (e) => {
    if(e.key === 'Enter') render();
  });

  [optNormalize,optGrave,optExplain,flagCity,flagTheta,flagDimin].forEach(el => {
    el.addEventListener('change', render);
  });

  // initial
  inp.value = 'φυλλις';
  render();
})();

