const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const guessWord = $('#guessWord');
const guessLabel = $('#guessLabel');
const why = $('#why');
const nom = $('#nom');
const gen = $('#gen');
const acc = $('#acc');
const baryAcc = $('#baryAcc');
const chips = $('#chips');
const normOut = $('#norm');
const explainEx = $('#explainEx');

// A few examples mentioned in/near the passage (not exhaustive).
// We store a "traditional" accent for display, plus a note.
const EXAMPLES = [
  {w:'Δαυλίς', note:'Herodian: disyllabic -λις (from consonant) often oxytone; cites Homer Δαυλίδα.'},
  {w:'Αὐλίς', note:'City of Boeotia: explicitly oxytone in the passage.'},
  {w:'αὖλις', note:'Aeolic “farmstead”: contrasted with Αὐλίς; often treated barytone in the passage discussion.'},
  {w:'Βοῦλις', note:'City of Phocis; listed among -λις names.'},
  {w:'Ἦλις', note:'City near Olympia; listed as barytone in the passage.'},
  {w:'Θετταλίς', note:'Polysyllabic -λις; listed among oxytone adjectival/ethnic-type forms.'},
  {w:'βούβαλις', note:'Common noun; passage says such appellatives/proper names are proparoxytone.'},
  {w:'δάμαλις', note:'Common noun; proparoxytone per passage.'},
  {w:'βαύκαλις', note:'Common noun; proparoxytone per passage.'},
  {w:'Φαρσαλίς', note:'Listed among oxytone polysyllables.'},
  {w:'Δαιδαλίς', note:'Listed among oxytone polysyllables.'},
];

// --- Greek helpers (toy-level) ---
const COMBINING = /[\u0300-\u036f]/g; // includes tonos/oxia etc.

function stripDiacritics(s){
  return s.normalize('NFD').replace(COMBINING,'').normalize('NFC');
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code>=0x0370 && code<=0x03FF) || (code>=0x1F00 && code<=0x1FFF);
}

function onlyGreekish(s){
  return [...s].filter(c => isGreekLetter(c) || c===' ' || c==='-' || c==='ʼ' || c==='’' || c==="'").join('');
}

function endsWithLis(base){
  const b = base.toLowerCase();
  return b.endsWith('λις');
}

function countVowels(base){
  // crude syllable proxy: count vowel nuclei (including diphthongs as 1 when obvious)
  const s = base.toLowerCase();
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω']);
  let n=0;
  for(let i=0;i<s.length;i++){
    const c=s[i];
    if(!vowels.has(c)) continue;
    // diphthongs: αι ει οι υι αυ ευ ηυ ου
    const next = s[i+1]||'';
    const pair = c+next;
    if(['αι','ει','οι','υι','αυ','ευ','ηυ','ου'].includes(pair)){
      n++; i++; continue;
    }
    n++;
  }
  return Math.max(1,n);
}

function applyAccent(word, position){
  // position: 'ultima' | 'penult' | 'antepenult'
  // We place an acute (U+0301) on the first vowel of the target syllable (approx).
  const sNFD = stripDiacritics(word).normalize('NFD');
  const letters = [...sNFD];
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

  // Find vowel indices (treat diphthongs as one nucleus by taking first vowel index)
  const vowelIdx=[];
  for(let i=0;i<letters.length;i++){
    const c=letters[i];
    if(!vowels.has(c)) continue;
    const next = letters[i+1]||'';
    const pair = (c+next).toLowerCase();
    if(['αι','ει','οι','υι','αυ','ευ','ηυ','ου'].includes(pair)){
      vowelIdx.push(i);
      i++; // skip next
    } else {
      vowelIdx.push(i);
    }
  }
  if(vowelIdx.length===0) return word;

  let target;
  if(position==='ultima') target = vowelIdx[vowelIdx.length-1];
  else if(position==='penult') target = vowelIdx[Math.max(0,vowelIdx.length-2)];
  else target = vowelIdx[Math.max(0,vowelIdx.length-3)];

  // Insert combining acute after the vowel letter.
  letters.splice(target+1,0,'\u0301');
  return letters.join('').normalize('NFC');
}

function makeForms(base){
  // base is stripped of diacritics but keeps case.
  // Replace final -λις with -λιδος / -λιν.
  const low = base.toLowerCase();
  const idx = low.lastIndexOf('λις');
  if(idx<0) return null;
  const stem = base.slice(0, idx);
  return {
    nom: base,
    gen: stem + (base[idx]==='Λ' ? 'Λιδος' : 'λιδος'),
    acc: stem + (base[idx]==='Λ' ? 'Λιν' : 'λιν')
  };
}

// Exceptions (toy): words Herodian treats as barytone or otherwise special.
const BARY_EXCEPT = new Set([
  stripDiacritics('Ἦλις').toLowerCase(),
  stripDiacritics('Βᾶλις').toLowerCase(),
  stripDiacritics('μᾶλις').toLowerCase(),
  stripDiacritics('αὖλις').toLowerCase(),
  stripDiacritics('τῆλις').toLowerCase(),
  stripDiacritics('μαῦλις').toLowerCase(),
]);

function guessAccent(base){
  // base: diacritics stripped, Greek-only.
  const clean = base.trim();
  const low = clean.toLowerCase();
  const syll = countVowels(clean);

  if(!endsWithLis(low)){
    return {ok:false, word:clean, label:'Type a word ending in -λις.', why:[`I only play with words ending in «λις».`], pos:null};
  }

  const whyLines=[];

  // If in exception list: barytone (we'll put accent on penult as a stand-in)
  if(BARY_EXCEPT.has(low)){
    whyLines.push('This is in a small “exception” list inspired by Herodian’s contrasts (barytone items like Ἦλις, αὖλις, etc.).');
    whyLines.push('Toy output: accent on the penult (barytone-ish).');
    return {ok:true, pos:'penult', label:'Guess: barytone-ish (penult)', why:whyLines};
  }

  if(syll<=2){
    whyLines.push('He says many disyllabic -λις forms (esp. starting with a consonant) are oxytone.');
    whyLines.push('Toy output: acute on the last syllable.');
    return {ok:true, pos:'ultima', label:'Guess: oxytone (ultima)', why:whyLines};
  }

  // Polysyllables: if looks like an ethnic/adjectival in -αλ-/-αιαλ- etc, guess oxytone; else proparoxytone.
  if(/(αλ|αιαλ|αιθαλ|οιχαλ|φαρσαλ|δαιδαλ|θετταλ|ιταλ|τανταλ|πανθαλ|αρδαλ)$/i.test(low.replace(/λις$/i,''))){
    whyLines.push('Herodian lists many longer, more “adjectival/ethnic” -λις forms as oxytone (e.g. Θετταλίς).');
    whyLines.push('Toy output: acute on the last syllable.');
    return {ok:true, pos:'ultima', label:'Guess: oxytone (ultima)', why:whyLines};
  }

  whyLines.push('Herodian also says many appellatives/proper names are proparoxytone (e.g. βούβαλις, δάμαλις).');
  whyLines.push('Toy output: accent on the antepenult (when possible).');
  return {ok:true, pos:'antepenult', label:'Guess: proparoxytone (antepenult)', why:whyLines};
}

function update(){
  let raw = inp.value;
  raw = onlyGreekish(raw);
  if(inp.value !== raw) inp.value = raw;

  const base = stripDiacritics(raw);
  normOut.textContent = base || '—';

  const g = guessAccent(base);
  if(!base.trim()){
    guessWord.textContent = '—';
    guessLabel.textContent = '—';
    why.innerHTML = '<span class="bad">Type a Greek word ending in -λις.</span>';
    nom.textContent = gen.textContent = acc.textContent = '—';
    explainEx.textContent = '—';
    return;
  }

  if(!g.ok){
    guessWord.textContent = base;
    guessLabel.textContent = g.label;
    why.innerHTML = g.why.map(x=>`<div>• ${x}</div>`).join('');
    nom.textContent = gen.textContent = acc.textContent = '—';
    return;
  }

  const accentedNom = applyAccent(base, g.pos);
  guessWord.textContent = accentedNom;
  guessLabel.textContent = g.label;
  why.innerHTML = g.why.map(x=>`<div>• ${x}</div>`).join('');

  const forms = makeForms(base);
  if(forms){
    const nomForm = applyAccent(forms.nom, g.pos);
    const genForm = applyAccent(forms.gen, 'penult'); // common-ish for -λιδος

    let accPos = 'penult';
    if(!baryAcc.checked){
      // if nominative guessed oxytone, keep accusative penult (since -λιν is ultima); if proparoxytone, keep penult.
      accPos = 'penult';
    }
    const accForm = applyAccent(forms.acc, accPos);

    nom.textContent = nomForm;
    gen.textContent = genForm;
    acc.textContent = accForm;
  } else {
    nom.textContent = gen.textContent = acc.textContent = '—';
  }

  // If matches an example (diacritics-insensitive), show it.
  const low = base.trim().toLowerCase();
  const ex = EXAMPLES.find(e => stripDiacritics(e.w).toLowerCase() === low);
  explainEx.textContent = ex ? `${e.w} — ${ex.note}` : '—';
}

function buildChips(){
  chips.innerHTML='';
  EXAMPLES.forEach(ex=>{
    const b = document.createElement('button');
    b.type='button';
    b.className='chip greek';
    b.textContent = ex.w;
    b.addEventListener('click', ()=>{
      inp.value = ex.w;
      update();
      inp.focus();
    });
    chips.appendChild(b);
  });
}

inp.addEventListener('input', update);
baryAcc.addEventListener('change', update);

buildChips();
// seed
inp.value = 'Δαυλις';
update();

passages.gadget_css:
:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --panel2:#1d2140;
  --text:#e9ecff;
  --muted:#b9c0ff;
  --faint:#8b93d6;
  --accent:#7cf0c5;
  --warn:#ffcc66;
  --bad:#ff6b7a;
  --good:#7cf0c5;
  --line:rgba(255,255,255,.10);
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, #1a1f3f 0%, var(--bg) 55%);color:var(--text);font:16px/1.35 system-ui,-apple-system,Segoe UI,Roboto,Arial,"Noto Sans",sans-serif}
.wrap{max-width:980px;margin:0 auto;padding:22px}
.top{display:flex;gap:16px;align-items:flex-start;margin-bottom:14px}
h1{font-size:26px;margin:0 0 6px 0;letter-spacing:.2px}
.sub{margin:0;color:var(--muted)}
.panel{background:linear-gradient(180deg,var(--panel) 0%, #14172a 100%);border:1px solid var(--line);border-radius:14px;padding:14px 14px 12px;margin:12px 0;box-shadow:0 10px 30px rgba(0,0,0,.25)}
.row{display:grid;grid-template-columns:140px 1fr auto;gap:10px;align-items:center}
.row.small{grid-template-columns:1fr}
label{color:var(--muted);font-weight:650}
input[type=text]{width:100%;padding:10px 12px;border-radius:12px;border:1px solid var(--line);background:var(--panel2);color:var(--text);font-size:18px;outline:none}
input[type=text]:focus{border-color:rgba(124,240,197,.55);box-shadow:0 0 0 3px rgba(124,240,197,.12)}
.btns{display:flex;gap:8px}
button{border:1px solid var(--line);background:#22264a;color:var(--text);padding:9px 10px;border-radius:12px;cursor:pointer;font-weight:650}
button:hover{border-color:rgba(124,240,197,.45)}
button:active{transform:translateY(1px)}
.hint{color:var(--muted)}
.presets{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
.preset{background:#1f2448}
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.card{border:1px solid var(--line);border-radius:12px;padding:10px;background:rgba(255,255,255,.03)}
.k{color:var(--faint);font-size:12px;text-transform:uppercase;letter-spacing:.12em}
.v{margin-top:6px;font-size:18px}
.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono",monospace}
.result{display:flex;gap:14px;align-items:baseline;flex-wrap:wrap}
.big{font-size:22px;font-weight:800}
.why{color:var(--muted)}
.rules summary{cursor:pointer;color:var(--accent);font-weight:750}
.rules ol{margin:10px 0 0 18px;color:var(--muted)}
.fine{color:var(--faint);font-size:13px}
.play{border:1px dashed rgba(124,240,197,.35);border-radius:14px;padding:12px;background:rgba(124,240,197,.05)}
.playRow{display:flex;justify-content:space-between;gap:12px;align-items:baseline;flex-wrap:wrap}
.playBtns{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}
.judge{margin-top:10px;padding:10px 12px;border-radius:12px;border:1px solid var(--line);background:rgba(255,255,255,.03);color:var(--muted)}
.judge.good{border-color:rgba(124,240,197,.45);color:var(--good)}
.judge.bad{border-color:rgba(255,107,122,.45);color:var(--bad)}
.judge.warn{border-color:rgba(255,204,102,.45);color:var(--warn)}
.foot{margin-top:10px;text-align:center}
@media (max-width:860px){
  .grid{grid-template-columns:repeat(2,1fr)}
  .row{grid-template-columns:1fr;}
  .btns{justify-content:flex-start}
}

passages.gadget_js:
(() => {
  const $ = (id) => document.getElementById(id);

  const els = {
    word: $('word'),
    analyze: $('analyze'),
    clear: $('clear'),
    norm: $('norm'),
    ending: $('ending'),
    syll: $('syll'),
    penult: $('penult'),
    guess: $('guess'),
    why: $('why'),
    accented: $('accented'),
    judge: $('judge'),
    btnOx: $('btnOx'),
    btnPar: $('btnPar'),
    btnPro: $('btnPro')
  };

  // --- Greek helpers (toy-level) ---
  const combiningMarks = /[\u0300-\u036f\u1dc0-\u1dff\u20d0-\u20ff\ufe20-\ufe2f]/g;

  function stripCombining(s){
    return s.normalize('NFD').replace(combiningMarks,'').normalize('NFC');
  }

  function normalizeGreek(s){
    if(!s) return '';
    s = s.trim();
    // normalize final sigma
    s = s.replace(/\u03C2/g,'σ');
    // keep letters only-ish, but allow spaces/hyphen/apostrophe
    s = s.replace(/[^\p{L}\p{M}\s\-’'·\.]/gu,'');
    // collapse spaces
    s = s.replace(/\s+/g,' ').trim();
    return s;
  }

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ','ϊ','ϋ','ΐ','ΰ','ᾳ','ῃ','ῳ']);
  const baseVowels = new Set(['α','ε','η','ι','ο','υ','ω']);
  const diphthongs = ['αι','ει','οι','αυ','ευ','ου','ηυ','υι'];

  function isVowelChar(ch){
    const b = stripCombining(ch).toLowerCase();
    return baseVowels.has(b);
  }

  function lowerBase(s){
    return stripCombining(s).toLowerCase();
  }

  function lastIndexOfVowelNucleus(word){
    const w = lowerBase(word);
    for(let i=w.length-1;i>=0;i--){
      if(isVowelChar(w[i])) return i;
    }
    return -1;
  }

  function syllabifyRough(word){
    // Very rough: split before each vowel nucleus (treat diphthongs as one nucleus)
    const w = lowerBase(word).replace(/\s+/g,'');
    if(!w) return [];

    // Build nuclei positions
    const nuclei = [];
    for(let i=0;i<w.length;i++){
      if(!isVowelChar(w[i])) continue;
      // diphthong check
      const pair = w.slice(i,i+2);
      if(diphthongs.includes(pair)){
        nuclei.push({start:i, len:2});
        i++; // skip next
      } else {
        nuclei.push({start:i, len:1});
      }
    }
    if(nuclei.length===0) return [w];

    // Create syllable boundaries: each syllable starts at previous boundary and includes up to just before next nucleus start
    const sylls = [];
    let start = 0;
    for(let n=0;n<nuclei.length;n++){
      const nextStart = (n+1<nuclei.length) ? nuclei[n+1].start : w.length;
      // heuristic: split at next nucleus start, but keep any consonants after current nucleus with current syllable unless they are many.
      // We'll simply cut at next nucleus start.
      const end = nextStart;
      sylls.push(w.slice(start,end));
      start = end;
    }
    // Clean empties
    return sylls.filter(x=>x.length);
  }

  function getPenultNucleus(word){
    const w = lowerBase(word).replace(/\s+/g,'');
    const sylls = syllabifyRough(w);
    if(sylls.length < 2) return null;
    const pen = sylls[sylls.length-2];
    // find first vowel nucleus in penult
    for(let i=0;i<pen.length;i++){
      if(isVowelChar(pen[i])){
        const pair = pen.slice(i,i+2);
        if(diphthongs.includes(pair)) return pair;
        return pen[i];
      }
    }
    return null;
  }

  function endsWithPattern(word, pat){
    const w = lowerBase(word).replace(/\s+/g,'');
    return w.endsWith(pat);
  }

  // Accent placement: add acute to first vowel nucleus of target syllable (from right)
  const acuteMap = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ'
  };

  function accentSyllable(word, fromRightIndex){
    // fromRightIndex: 1=last,2=penult,3=antepenult
    const raw = normalizeGreek(word);
    const w = lowerBase(raw).replace(/\s+/g,'');
    const sylls = syllabifyRough(w);
    if(sylls.length===0) return raw;
    const idx = sylls.length - fromRightIndex;
    if(idx < 0) return raw;

    // rebuild with acute in that syllable
    let out = '';
    for(let s=0;s<sylls.length;s++){
      let syl = sylls[s];
      if(s===idx){
        // accent first vowel nucleus
        let done=false;
        for(let i=0;i<syl.length;i++){
          if(isVowelChar(syl[i])){
            const pair = syl.slice(i,i+2);
            if(diphthongs.includes(pair)){
              // accent first vowel of diphthong (toy choice)
              const v = pair[0];
              const av = acuteMap[v] || v;
              syl = syl.slice(0,i) + av + syl.slice(i+1);
              done=true;
              break;
            } else {
              const v = syl[i];
              const av = acuteMap[v] || v;
              syl = syl.slice(0,i) + av + syl.slice(i+1);
              done=true;
              break;
            }
          }
        }
        if(!done){
          // no vowel found; leave
        }
      }
      out += syl;
    }
    return out;
  }

  // --- Herodian-ish guesser ---
  const exceptionBarytone = new Set([
    'καβαλλις' // explicitly barytone in passage
  ]);

  const specialProparox = new Set([
    'αδουλις',
    'αρτοπωλις'
  ]);

  function guessAccentClass(word){
    const w = lowerBase(normalizeGreek(word)).replace(/\s+/g,'');
    const sylls = syllabifyRough(w);
    const n = sylls.length;

    if(!w) return {cls:null, label:'—', why:'Type a word.'};

    if(specialProparox.has(w)){
      return {cls:'proparoxytone', label:'Proparoxytone (accent on antepenult)', why:'Special-cased from the passage: Ἄδουλις and ἀρτόπωλις are said to be proparoxytone.'};
    }

    const isLis = endsWithPattern(w,'λις');
    const isLlis = endsWithPattern(w,'λλις');

    if(isLlis && n>2){
      if(exceptionBarytone.has(w)){
        return {cls:'barytone', label:'Barytone (not final-accented)', why:'Rule: -λλις (more than 2 syllables) tends to be oxytone, but κάβαλλις is explicitly barytone.'};
      }
      return {cls:'oxytone', label:'Oxytone (accent on last)', why:'Rule: words in -λλις with more than two syllables are oxytone (toy version).'};
    }

    if(isLis && n>2){
      const pen = getPenultNucleus(w);
      if(pen === 'η'){
        return {cls:'barytone', label:'Barytone (not final-accented)', why:"Rule: -λις words (>2 syllables) with penult η are barytone (e.g. κάπηλις, κύβηλις)."};
      }
      if(pen === 'ι' || pen === 'υ'){
        return {cls:'oxytone', label:'Oxytone (accent on last)', why:"Rule: -λις words (>2 syllables) with a naturally short vowel in the penult (toy: ι or υ) are oxytone (e.g. κυψελίς, πηγυλίς)."};
      }
      if(pen && diphthongs.includes(pen)){
        return {cls:'oxytone', label:'Oxytone (accent on last)', why:'Rule: -λις derivatives with a diphthong in the penult are oxytone (e.g. Αἰτωλίς).'};
      }
      if(pen === 'ω'){
        return {cls:'oxytone', label:'Oxytone (accent on last)', why:'Rule: -λις derivatives with penult ω are oxytone.'};
      }
      return {cls:'unknown', label:'Uncertain (toy can’t decide)', why:'The toy only implements a few patterns from this passage. Try a clearer -λις / -λλις example.'};
    }

    return {cls:'unknown', label:'Uncertain (not targeted by these rules)', why:'This passage focuses on -λις / -λλις patterns. Try a word ending in -λις or -λλις with 3+ syllables.'};
  }

  function endingLabel(word){
    const w = lowerBase(word).replace(/\s+/g,'');
    if(endsWithPattern(w,'λλις')) return '…λλις';
    if(endsWithPattern(w,'λις')) return '…λις';
    return '—';
  }

  function update(){
    const raw = els.word.value;
    const norm = normalizeGreek(raw);
    const w = lowerBase(norm).replace(/\s+/g,'');

    els.norm.textContent = norm || '—';
    els.ending.textContent = norm ? endingLabel(norm) : '—';

    const sylls = norm ? syllabifyRough(w) : [];
    els.syll.textContent = sylls.length ? sylls.join(' · ') : '—';

    const pen = norm ? getPenultNucleus(w) : null;
    els.penult.textContent = pen ? pen : '—';

    const g = guessAccentClass(norm);
    els.guess.textContent = g.label;
    els.why.textContent = g.why;

    els.accented.textContent = '—';
    els.judge.className = 'judge';
    els.judge.textContent = 'Choose an accent button to generate a form.';
  }

  function judgeChoice(choice){
    const norm = normalizeGreek(els.word.value);
    if(!norm){
      els.judge.className = 'judge warn';
      els.judge.textContent = 'Type a word first.';
      return;
    }
    const g = guessAccentClass(norm);
    const accented = accentSyllable(norm, choice);
    els.accented.textContent = accented;

    const choiceName = choice===1 ? 'oxytone' : (choice===2 ? 'paroxytone' : 'proparoxytone');

    if(g.cls === 'unknown' || g.cls === null){
      els.judge.className = 'judge warn';
      els.judge.textContent = `You chose ${choiceName}. The toy has no strong guess here—use your judgment (or try a clearer -λις/-λλις example).`;
      return;
    }

    // Map barytone to "not oxytone"; accept para/pro as barytone.
    let ok = false;
    if(g.cls === 'barytone') ok = (choiceName !== 'oxytone');
    else ok = (g.cls === choiceName);

    if(ok){
      els.judge.className = 'judge good';
      els.judge.textContent = `Match! Your ${choiceName} choice agrees with the toy’s Herodian-ish guess.`;
    } else {
      els.judge.className = 'judge bad';
      els.judge.textContent = `Mismatch: you chose ${choiceName}, but the toy guessed ${g.cls}. (Remember: this is a simplified game.)`;
    }
  }

  // Events
  els.analyze.addEventListener('click', update);
  els.clear.addEventListener('click', () => {
    els.word.value = '';
    update();
    els.word.focus();
  });
  els.word.addEventListener('keydown', (e) => {
    if(e.key === 'Enter') update();
  });

  document.querySelectorAll('.preset').forEach(btn => {
    btn.addEventListener('click', () => {
      els.word.value = btn.getAttribute('data-w');
      update();
    });
  });

  els.btnOx.addEventListener('click', () => judgeChoice(1));
  els.btnPar.addEventListener('click', () => judgeChoice(2));
  els.btnPro.addEventListener('click', () => judgeChoice(3));

  // Initial
  update();
})();

