const $ = (sel) => document.querySelector(sel);

// --- Greek helpers (toy-level) ---
// Strip combining marks and normalize final sigma.
function stripDiacritics(s){
  return (s || "")
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'')
    .replace(/ς/g,'σ')
    .normalize('NFC');
}

function normalizeGreek(s){
  return stripDiacritics(s)
    .replace(/\s+/g,'')
    .toLowerCase();
}

// Very rough vowel detection (includes common polytonic vowels once diacritics stripped)
const VOWELS = new Set([...'αεηιουω']);
function isVowel(ch){ return VOWELS.has(ch); }

// Split into "vowel groups" (each group = vowel + following consonants until next vowel)
function vowelGroups(s){
  const t = normalizeGreek(s);
  if(!t) return [];
  let groups = [];
  let i = 0;
  while(i < t.length){
    // skip leading consonants into first group if any
    let start = i;
    // find next vowel
    while(i < t.length && !isVowel(t[i])) i++;
    if(i >= t.length){
      // no more vowels; attach tail to last group if exists
      if(groups.length) groups[groups.length-1] += t.slice(start);
      else groups.push(t.slice(start));
      break;
    }
    // include consonants before vowel in this group if it's the first group and empty
    // We'll start group at start.
    // Now include vowel
    i++; // include vowel
    // include following consonants until next vowel
    while(i < t.length && !isVowel(t[i])) i++;
    groups.push(t.slice(start, i));
  }
  return groups.filter(g => g.length);
}

function findAntepenultVowelIndex(s){
  const t = normalizeGreek(s);
  // indices of vowels in normalized string
  let vIdx = [];
  for(let i=0;i<t.length;i++) if(isVowel(t[i])) vIdx.push(i);
  if(vIdx.length < 3) return null;
  return vIdx[vIdx.length - 3];
}

function applyAcuteOnAntepenult(original){
  // We apply accent to the *base vowel* at the antepenult position in a diacritic-stripped version,
  // then try to map back to a display string.
  // For simplicity: we output a clean, monotonic-ish accented form (acute only), preserving original letters.

  const clean = stripDiacritics(original).replace(/\s+/g,'');
  const norm = normalizeGreek(original);
  const idx = findAntepenultVowelIndex(original);
  if(idx === null) return {ok:false, out: clean, why:"Need at least 3 vowels to place antepenult accent."};

  // Build mapping from normalized (lowercase, no diacritics, final sigma->sigma) to clean (original case-ish stripped)
  // We'll just accent in the clean string by locating the corresponding vowel occurrence count.
  // Count vowels in norm up to idx, then accent that vowel occurrence in clean.
  let targetVowelCount = 0;
  for(let i=0;i<=idx;i++) if(isVowel(norm[i])) targetVowelCount++;

  let out = "";
  let seen = 0;
  for(let i=0;i<clean.length;i++){
    const ch = clean[i];
    const base = stripDiacritics(ch).toLowerCase().replace(/ς/g,'σ');
    if(base.length===1 && isVowel(base)){
      seen++;
      if(seen === targetVowelCount){
        out += addAcute(ch);
        continue;
      }
    }
    out += ch;
  }
  return {ok:true, out, why:"Toy rule: acute on antepenult vowel."};
}

function addAcute(ch){
  // Add acute to Greek vowel (works for basic Greek letters; keeps case)
  const map = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };
  return map[ch] || ch;
}

function detectPolisCompound(word){
  const norm = normalizeGreek(word);
  const ends = norm.endsWith('πολισ');
  if(!ends) return {isPolis:false};
  const prefixNorm = norm.slice(0, -'πολισ'.length);
  const prefixDisplay = stripDiacritics(word).replace(/\s+/g,'').slice(0, stripDiacritics(word).replace(/\s+/g,'').length - 5);
  return {
    isPolis:true,
    prefixNorm,
    prefixDisplay,
    second: 'πόλις'
  };
}

const toyGlosses = [
  {re:/^χρυσο/i, gloss:"‘golden city’ (χρυσός + πόλις)"},
  {re:/^νεα/i, gloss:"‘new city’ (νέος/νέα + πόλις)"},
  {re:/^νικο/i, gloss:"‘victory city’ (νίκη + πόλις)"},
  {re:/^τρι/i, gloss:"‘three-city’ / ‘triple city’ (τρεῖς + πόλις)"},
  {re:/^τετρα/i, gloss:"‘four-city’ (τέσσαρες + πόλις)"},
  {re:/^καλλι/i, gloss:"‘beautiful city’ (καλός + πόλις)"},
  {re:/^μητρο/i, gloss:"‘mother-city’ / metropolis (μήτηρ + πόλις)"},
  {re:/^ακρο/i, gloss:"‘high city’ / acropolis (ἄκρος + πόλις)"},
  {re:/^σκυθ/i, gloss:"‘Scythian city’ (Σκύθης + πόλις)"},
  {re:/^ταυρο/i, gloss:"‘bull city’ or ‘Taur- city’ (ταῦρος/Ταῦρος + πόλις)"},
  {re:/^ερμο/i, gloss:"‘Hermes-city’ (Ἑρμῆς → Ἑρμο- + πόλις)"},
  {re:/^πυθο/i, gloss:"‘Pytho-city’ (Πυθώ → Πυθο- + πόλις)"},
];

function guessGloss(prefix){
  const n = normalizeGreek(prefix);
  for(const g of toyGlosses){
    if(g.re.test(n)) return g.gloss;
  }
  if(!n) return "—";
  return "‘" + stripDiacritics(prefix) + "-city’ (toy gloss)";
}

function renderAnalysis(){
  const w = $('#inWord').value.trim();
  const det = detectPolisCompound(w);

  if(!w){
    $('#pieces').textContent = '—';
    $('#accented').textContent = '—';
    $('#syll').textContent = '—';
    return;
  }

  const groups = vowelGroups(w);
  $('#syll').textContent = groups.length ? groups.join(' · ') : '—';

  if(det.isPolis){
    $('#pieces').innerHTML = `<span class="gr">${stripDiacritics(det.prefixDisplay) || '∅'}</span> + <span class="gr">πόλις</span> <span class="badge markOk">looks like -πόλις</span>`;
  } else {
    $('#pieces').innerHTML = `<span class="badge markBad">doesn’t look like -πόλις</span> (still can accent by the toy rule)`;
  }

  const acc = applyAcuteOnAntepenult(w);
  $('#accented').textContent = acc.out;
}

function buildWord(){
  const pref = $('#inPrefix').value.trim();
  const second = $('#selSecond').value; // currently only polis
  const raw = (pref + second).replace(/\s+/g,'');
  const acc = applyAcuteOnAntepenult(raw);
  $('#built').textContent = acc.out;
  $('#gloss').textContent = guessGloss(pref);
  // also sync analyzer input for play
  $('#inWord').value = acc.out;
  renderAnalysis();
}

const randomPrefixes = [
  'Χρυσο','Νεα','Νικο','Τρι','Τετρα','Καλλι','Μητρο','Ακρο','Σκυθο','Ταυρο','Πυθο','Ερμο','Φιλιππο','Παρθενο','Ιερα','Περσε','Αμφι','Προξενου','Οδιου'
];
function randomPrefix(){
  const p = randomPrefixes[Math.floor(Math.random()*randomPrefixes.length)];
  $('#inPrefix').value = p;
}

$('#btnAnalyze').addEventListener('click', renderAnalysis);
$('#btnAccent').addEventListener('click', () => {
  const w = $('#inWord').value.trim();
  if(!w) return;
  const acc = applyAcuteOnAntepenult(w);
  $('#inWord').value = acc.out;
  renderAnalysis();
});
$('#btnClear').addEventListener('click', () => {
  $('#inWord').value = '';
  $('#pieces').textContent = '—';
  $('#accented').textContent = '—';
  $('#syll').textContent = '—';
});
$('#btnBuild').addEventListener('click', buildWord);
$('#btnRandom').addEventListener('click', () => { randomPrefix(); buildWord(); });

// Live-ish updates
$('#inWord').addEventListener('input', () => {
  // debounce lightly
  window.clearTimeout(window.__t);
  window.__t = window.setTimeout(renderAnalysis, 120);
});

// initial render
renderAnalysis();
buildWord();

