const $ = (sel) => document.querySelector(sel);

const examples = [
  {stem:"Ἀδριαν", mode:"o", note:"like Ἀδριανούπολις"},
  {stem:"Ἀφροδιτ", mode:"o", note:"like Ἀφροδιτόπολις"},
  {stem:"Γαβα", mode:"ou", note:"like Γαβαούπολις"},
  {stem:"Γυναικ", mode:"o", note:"like Γυναικόσπολις"},
  {stem:"Ἡλι", mode:"ou", note:"like Ἡλιούπολις"},
  {stem:"Σεβαστ", mode:"o", note:"like Σεβαστόπολις"},
  {stem:"Ἑλλην", mode:"o", note:"like Ἑλληνόπολις"},
  {stem:"Δουλ", mode:"o", note:"like Δουλόπολις"},
];

function stripPunct(s){
  return (s||"")
    .replace(/[··;,:.?!“”"'()\[\]{}<>]/g, " ")
    .replace(/\s+/g," ")
    .trim();
}

function normalizeGreek(s){
  // Keep accents; just normalize whitespace.
  return (s||"").replace(/\s+/g," ").trim();
}

function endsWithVowelish(stem){
  // crude: last char in Greek vowel set (incl. accented)
  const v = "αάὰᾶἀἁἄἅἂἃἆἇεέὲἐἑἔἕἒἓηήὴῆἠἡἤἥἢἣἦἧιίὶῖἰἱἴἵἲἳἶἷοόὸὀὁὄὅὂὃυύὺῦὐὑὔὕὒὓὖὗωώὼῶὠὡὤὥὢὣὦὧ";
  const last = (stem||"").slice(-1);
  return v.includes(last);
}

function chooseLinker(stem, mode){
  if(mode !== "auto") return mode;
  // Heuristic: if stem ends in -ι or -υ or -ου already, prefer none; if ends in vowel, none; else -ο-
  const s = stem;
  if(!s) return "none";
  if(/ου\s*$/u.test(s)) return "none";
  if(/[ιίὶῖ]$/u.test(s)) return "none";
  if(/[υύὺῦ]$/u.test(s)) return "none";
  if(endsWithVowelish(s)) return "none";
  // if ends in -αβ/γαβ etc? allow -ου- for stems ending in -α (Gaba-)
  if(/[αάὰᾶ]$/u.test(s)) return "ou";
  return "o";
}

function applyLinker(stem, linker){
  if(linker === "none") return {joined: stem + "πόλις", linkerShown:"(none)"};
  if(linker === "o") return {joined: stem + "όπολις", linkerShown:"-ο-"};
  if(linker === "ou") return {joined: stem + "ούπολις", linkerShown:"-ου-"};
  return {joined: stem + "πόλις", linkerShown:"(none)"};
}

function suggestAccentOnFirstPart(word){
  // Very rough: if no accent marks at all, add acute on the last vowel of the first part (before πόλις).
  // We only handle simple vowels α ε η ι ο υ ω.
  const hasAccent = /[άέήίόύώὰὲὴὶὸὺὼᾶῖῦῶ]/u.test(word);
  if(hasAccent) return {word, note:"kept existing accents"};

  const idx = word.indexOf("πόλις");
  const first = idx >= 0 ? word.slice(0, idx) : word;
  const rest = idx >= 0 ? word.slice(idx) : "";

  const map = {"α":"ά","ε":"έ","η":"ή","ι":"ί","ο":"ό","υ":"ύ","ω":"ώ"};
  for(let i = first.length - 1; i >= 0; i--){
    const ch = first[i];
    if(map[ch]){
      const out = first.slice(0,i) + map[ch] + first.slice(i+1) + rest;
      return {word: out, note:"added a simple acute to the last vowel of the first part"};
    }
  }
  return {word, note:"no vowel found to accent"};
}

function build(){
  const stemRaw = normalizeGreek($("#stem").value);
  const mode = $("#mode").value;
  const accent = $("#accent").value;

  if(!stemRaw){
    $("#result").textContent = "—";
    $("#explain").textContent = "Type a stem first (e.g. Ἀδριαν, Ἀφροδιτ, Γυναικ).";
    return;
  }

  // remove trailing hyphen if user typed Ἀδριαν-
  const stem = stemRaw.replace(/-+$/g, "");

  const linker = chooseLinker(stem, mode);
  const joined = applyLinker(stem, linker);

  let finalWord = joined.joined;
  let accentNote = "no accent changes";
  if(accent === "suggest"){
    const sug = suggestAccentOnFirstPart(finalWord);
    finalWord = sug.word;
    accentNote = sug.note;
  }

  $("#result").textContent = finalWord;
  $("#explain").innerHTML = `Stem: <mark>${escapeHtml(stem)}</mark><br>Linker: <mark>${escapeHtml(joined.linkerShown)}</mark> → + <mark>πόλις</mark><br>Accent: <mark>${escapeHtml(accentNote)}</mark>`;
}

function escapeHtml(s){
  return (s+"")
    .replaceAll("&","&amp;")
    .replaceAll("<","&lt;")
    .replaceAll(">","&gt;")
    .replaceAll('"',"&quot;")
    .replaceAll("'","&#039;");
}

function clearAll(){
  $("#stem").value = "";
  $("#result").textContent = "—";
  $("#explain").textContent = "—";
}

function randomExample(){
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $("#stem").value = ex.stem;
  $("#mode").value = "auto";
  $("#accent").value = "keep";
  build();
  $("#explain").innerHTML += `<br><span style="color:var(--muted)">Example hint: ${escapeHtml(ex.note)}</span>`;
}

function scan(){
  const text = normalizeGreek($("#paste").value);
  const out = $("#scanOut");
  out.innerHTML = "";

  if(!text){
    out.textContent = "Paste some Greek text first.";
    return;
  }

  const cleaned = stripPunct(text);
  const tokens = cleaned.split(" ").filter(Boolean);

  // Find tokens containing πόλις or όπολις or ούπολις (with/without accents)
  const hits = [];
  for(const t of tokens){
    const m = t.match(/^(.*?)(πόλις|πολις|όπολις|οπολις|ούπολις|ουπολις)$/u);
    if(m){
      const first = m[1];
      const second = m[2];
      hits.push({whole:t, first, second});
    }
  }

  if(hits.length === 0){
    out.textContent = "No obvious ‑πόλις compounds found (try including words like Ἡλιούπολις, Ἑλληνόπολις, Δουλόπολις).";
    return;
  }

  const frag = document.createDocumentFragment();
  const p = document.createElement("div");
  p.style.color = "var(--muted)";
  p.style.marginBottom = "8px";
  p.textContent = `Found ${hits.length} token(s) ending in ‑πόλις. Click one to copy its first part into the builder.`;
  frag.appendChild(p);

  hits.forEach((h, i) => {
    const pill = document.createElement("button");
    pill.className = "pill";
    pill.type = "button";
    pill.title = "Click to use the first part as a stem";
    pill.innerHTML = `<span class="w">${escapeHtml(h.whole)}</span><span class="split">${escapeHtml(h.first)} + ${escapeHtml(h.second)}</span>`;
    pill.addEventListener("click", () => {
      $("#stem").value = h.first || "";
      $("#mode").value = "auto";
      $("#accent").value = "keep";
      build();
      window.scrollTo({top: 0, behavior: "smooth"});
    });
    frag.appendChild(pill);
  });

  out.appendChild(frag);
}

function loadPassageSample(){
  const sample = "Ἀδριανούπολις ἡ πρότερον Ἡράκλεια. Ἀνταιούπολις… Ἀφροδιτόπολις… Γαβαούπολις… Γυναικόσπολις… Σεβαστόπολις… Διόσπολις… Δουλόπολις… Ἑλληνόπολις… Ἡλιούπολις… Θεόπολις…";
  $("#paste").value = sample;
  scan();
}

$("#build").addEventListener("click", build);
$("#clear").addEventListener("click", clearAll);
$("#random").addEventListener("click", randomExample);
$("#scan").addEventListener("click", scan);
$("#loadPassage").addEventListener("click", loadPassageSample);

// convenience: Enter in stem triggers build
$("#stem").addEventListener("keydown", (e) => {
  if(e.key === "Enter") build();
});

// initialize
clearAll();
randomExample();

