(() => {
  const $ = (s) => document.querySelector(s);
  const inp = $('#inp');
  const outBig = $('#big');
  const outExplain = $('#explain');
  const btnAnalyze = $('#btnAnalyze');
  const btnRandom = $('#btnRandom');
  const mode = $('#mode');
  const kind = $('#kind');
  const pos = $('#pos');
  const poslbl = $('#poslbl');
  const variants = $('#variants');

  const qword = $('#qword');
  const qfeed = $('#qfeed');
  const qOxy = $('#qOxy');
  const qBary = $('#qBary');
  const qNext = $('#qNext');

  const examples = [
    {w:'μερμις', gloss:'disyllable -μις (barytone)'} ,
    {w:'θεμις', gloss:'disyllable -μις (barytone)'} ,
    {w:'Χαρμις', gloss:'proper name/place (barytone)'} ,
    {w:'Χεμμις', gloss:'place (barytone)'} ,
    {w:'πυραμις', gloss:'>2 syllables, appellative (oxytone)'} ,
    {w:'σησαμις', gloss:'>2 syllables, appellative (oxytone)'} ,
    {w:'καλαμις', gloss:'>2 syllables, appellative (oxytone)'} ,
    {w:'πλοκαμις', gloss:'>2 syllables, appellative (oxytone)'} ,
    {w:'κεραμις', gloss:'>2 syllables, appellative (oxytone)'} ,
    {w:'Αρτεμις', gloss:'proper name (barytone)'} ,
    {w:'Σεμιραμις', gloss:'proper name (barytone)'} ,
    {w:'Χρυσοθεμις', gloss:'proper name (barytone)'} ,
    {w:'Σαλαμις', gloss:'exception: proper name but oxytone'} ,
    {w:'δυναμις', gloss:'exception: appellative but barytone'} ,
    {w:'ρανις', gloss:'-νις, penult a/o (oxytone)'} ,
    {w:'χλανις', gloss:'-νις, penult a/o (oxytone)'} ,
    {w:'σανις', gloss:'-νις, penult a/o (oxytone)'} ,
    {w:'ονις', gloss:'-νις, penult a/o (oxytone)'} ,
    {w:'κονις', gloss:'-νις, penult a/o (oxytone)'} ,
    {w:'Γλανις', gloss:'proper name (barytone)'} ,
    {w:'Τανις', gloss:'proper name (barytone)'} ,
    {w:'Θωνις', gloss:'long penult (barytone)'} ,
    {w:'μηνις', gloss:'long penult (barytone)'} ,
    {w:'ινις', gloss:'long-ish in passage list (barytone)'} ,
    {w:'ηνις', gloss:'long-ish in passage list (barytone)'} ,
    {w:'νηνις', gloss:'long-ish in passage list (barytone)'}
  ];

  // --- Greek helpers (very lightweight) ---
  const combining = /[\u0300-\u036f]/g;
  function nfd(s){ return (s||'').normalize('NFD'); }
  function stripDiacritics(s){ return nfd(s).replace(combining,'').normalize('NFC'); }
  function stripPunct(s){ return (s||'').replace(/[\s··.,;:!?"'“”‘’()\[\]{}<>]/g,''); }

  const vowelsBase = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
  function isVowelChar(ch){ return vowelsBase.has(ch); }

  function lastIndexOfVowel(word){
    const w = nfd(word);
    for(let i=w.length-1;i>=0;i--){
      const ch = w[i];
      if(isVowelChar(ch)) return i;
    }
    return -1;
  }

  function countVowelNuclei(word){
    // crude: count vowel letters in stripped word (treats diphthongs as 2)
    const w = stripDiacritics(word);
    let c=0;
    for(const ch of w){ if(isVowelChar(ch)) c++; }
    return c;
  }

  function endsWithMisNis(word){
    const w = stripDiacritics(word);
    return w.endsWith('μις') || w.endsWith('νις') || w.endsWith('Μις') || w.endsWith('Νις');
  }

  function endingType(word){
    const w = stripDiacritics(word);
    if(w.toLowerCase().endsWith('μις')) return 'mis';
    if(w.toLowerCase().endsWith('νις')) return 'nis';
    return null;
  }

  function looksProper(word){
    // heuristic: initial capital Greek/Latin
    const t = stripPunct(word).trim();
    if(!t) return false;
    const first = t[0];
    return first === first.toUpperCase() && first !== first.toLowerCase();
  }

  function hasLongMark(word){
    // look for omega/eta or circumflex/long-ish signals in NFD
    const w = nfd(word);
    if(/[ωΩηΗ]/.test(w)) return true;
    // circumflex combining perispomeni U+0342 or Greek tonos? (tonos not length)
    if(/\u0342/.test(w)) return true;
    // precomposed with circumflex: ῶ ῆ ῦ etc
    if(/[ῶῆῦᾶῖῦῷῇ]/.test(word)) return true;
    return false;
  }

  function applyAcuteToLastVowel(word){
    // add combining acute to last vowel letter
    const w = nfd(word);
    const i = lastIndexOfVowel(w);
    if(i<0) return word;
    const acute = '\u0301';
    // if vowel already has some accent, remove acute/grave/circumflex first
    let out = '';
    for(let k=0;k<w.length;k++){
      const ch = w[k];
      if(k===i){
        out += ch;
        // skip following combining marks for this base and re-add non-accent marks
        let j=k+1;
        let kept='';
        while(j<w.length && /[\u0300-\u036f]/.test(w[j])){
          const m=w[j];
          if(m==='\u0301' || m==='\u0300' || m==='\u0342'){
            // drop
          } else {
            kept += m;
          }
          j++;
        }
        out += kept + acute;
        k = j-1;
      } else {
        out += ch;
      }
    }
    return out.normalize('NFC');
  }

  function applyAcuteToPenultVowel(word){
    // find last two vowel letters; accent the penult vowel
    const w = nfd(word);
    const vowelIdx=[];
    for(let i=0;i<w.length;i++) if(isVowelChar(w[i])) vowelIdx.push(i);
    if(vowelIdx.length<2) return applyAcuteToLastVowel(word);
    const target = vowelIdx[vowelIdx.length-2];
    const acute='\u0301';
    let out='';
    for(let k=0;k<w.length;k++){
      const ch=w[k];
      if(k===target){
        out += ch;
        let j=k+1;
        let kept='';
        while(j<w.length && /[\u0300-\u036f]/.test(w[j])){
          const m=w[j];
          if(m==='\u0301' || m==='\u0300' || m==='\u0342'){} else kept+=m;
          j++;
        }
        out += kept + acute;
        k=j-1;
      } else out += ch;
    }
    return out.normalize('NFC');
  }

  function applyAcuteToAntepenultVowel(word){
    const w=nfd(word);
    const vowelIdx=[];
    for(let i=0;i<w.length;i++) if(isVowelChar(w[i])) vowelIdx.push(i);
    if(vowelIdx.length<3) return applyAcuteToPenultVowel(word);
    const target=vowelIdx[vowelIdx.length-3];
    const acute='\u0301';
    let out='';
    for(let k=0;k<w.length;k++){
      const ch=w[k];
      if(k===target){
        out += ch;
        let j=k+1;
        let kept='';
        while(j<w.length && /[\u0300-\u036f]/.test(w[j])){
          const m=w[j];
          if(m==='\u0301' || m==='\u0300' || m==='\u0342'){} else kept+=m;
          j++;
        }
        out += kept + acute;
        k=j-1;
      } else out += ch;
    }
    return out.normalize('NFC');
  }

  function accentByPos(word, posFromEnd){
    // 0 last, 1 penult, 2 antepenult
    if(posFromEnd===0) return applyAcuteToLastVowel(word);
    if(posFromEnd===1) return applyAcuteToPenultVowel(word);
    return applyAcuteToAntepenultVowel(word);
  }

  function guessAccent(word, kindChoice){
    const raw = stripPunct(word).trim();
    const t = endingType(raw);
    const syll = countVowelNuclei(raw);
    const proper = (kindChoice==='auto') ? looksProper(raw) : (kindChoice==='prop');
    const appell = (kindChoice==='app');

    const base = stripDiacritics(raw);
    const lower = base.toLowerCase();

    // explicit exceptions mentioned
    if(lower==='σαλαμις') return {class:'oxy', why:'Herodian notes Σαλαμίς is oxytone though a proper name.'};
    if(lower==='δυναμις') return {class:'bary', why:'Herodian notes δύναμις is barytone though an appellative.'};

    if(t==='mis'){
      if(syll<=2){
        return {class:'bary', why:'Disyllables in -μις tend to be barytone (μέρμις, θέμις).'};
      }
      if(proper && !appell){
        return {class:'bary', why:'Proper names in -μις tend to be barytone (Ἄρτεμις, Σεμίραμις).'};
      }
      return {class:'oxy', why:'Appellatives in -μις with >2 syllables tend to be oxytone (πυραμίς, σησαμίς).'};
    }

    if(t==='nis'){
      if(proper && !appell){
        return {class:'bary', why:'Proper names in -νις tend to be barytone (Γλάνις, Τάνις).'};
      }
      // long/lengthened penult heuristic
      if(syll<=2 && hasLongMark(raw)){
        return {class:'bary', why:'Disyllables in -νις with long/lengthened penult tend to be barytone (Θῶνις, μῆνις).'};
      }
      // penult a/o heuristic for short appellatives
      if(syll<=2){
        // find penult vowel letter (crude)
        const w = stripDiacritics(raw);
        const vowels=[];
        for(let i=0;i<w.length;i++) if(isVowelChar(w[i])) vowels.push(w[i].toLowerCase());
        const pen = vowels.length>=2 ? vowels[vowels.length-2] : null;
        if(pen==='α' || pen==='ο'){
          return {class:'oxy', why:'Short appellatives in -νις with penult α/ο tend to be oxytone (ῥανίς, χλανίς, ὀνίς).'};
        }
      }
      // fallback
      return {class:'oxy', why:'Heuristic fallback for -νις: often oxytone among short appellatives unless long-penult/proper-name cues suggest barytone.'};
    }

    if(mode.value==='strict'){
      return {class:null, why:'Strict mode: please enter a word ending in -μις or -νις.'};
    }
    // simple mode: still allow accent play
    return {class:'oxy', why:'Not clearly -μις/-νις; using oxytone as a default for the preview.'};
  }

  function render(){
    const raw0 = inp.value;
    const raw = stripPunct(raw0).trim();
    const accChoice = document.querySelector('input[name="acc"]:checked').value;

    const g = guessAccent(raw, kind.value);
    let cls = g.class;
    if(accChoice==='oxy') cls='oxy';
    if(accChoice==='bary') cls='bary';

    // choose accent position for display
    let display = raw || '—';
    if(raw){
      if(cls==='oxy') display = accentByPos(raw, 0);
      else if(cls==='bary') display = accentByPos(raw, 1);
      else display = raw;
    }

    outBig.textContent = display;
    outExplain.textContent = g.why;

    // slider variants
    const nuclei = countVowelNuclei(raw);
    const maxPos = Math.min(2, Math.max(0, nuclei-1));
    pos.max = String(maxPos);
    if(Number(pos.value) > maxPos) pos.value = String(maxPos);
    poslbl.textContent = `${pos.value} = ${pos.value==0?'last syllable':pos.value==1?'penult':'antepenult'}`;

    variants.innerHTML = '';
    if(!raw){
      variants.textContent = '—';
      return;
    }

    const v0 = accentByPos(raw, 0);
    const v1 = accentByPos(raw, 1);
    const v2 = accentByPos(raw, 2);

    const picked = accentByPos(raw, Number(pos.value));

    const rows = [
      {lab:'Oxytone (last)', val:v0},
      {lab:'Barytone-ish (penult)', val:v1},
      {lab:'Antepenult (play)', val:v2},
      {lab:'Slider pick', val:picked}
    ];

    for(const r of rows){
      const div = document.createElement('div');
      div.className = 'v';
      const left = document.createElement('div');
      left.textContent = r.val;
      const right = document.createElement('div');
      right.className = 'tag';
      right.textContent = r.lab;
      div.appendChild(left);
      div.appendChild(right);
      variants.appendChild(div);
    }
  }

  function setRandom(){
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inp.value = ex.w;
    render();
    outExplain.textContent = ex.gloss + ' — ' + outExplain.textContent;
  }

  // Quiz
  let quizItem = null;
  function nextQuiz(){
    quizItem = examples[Math.floor(Math.random()*examples.length)];
    qword.textContent = quizItem.w;
    qfeed.textContent = ' '; 
  }
  function answerQuiz(ans){
    if(!quizItem) return;
    const g = guessAccent(quizItem.w, 'auto');
    const expected = g.class;
    if(!expected){
      qfeed.textContent = 'No expectation for this item.';
      return;
    }
    const ok = (ans===expected);
    qfeed.innerHTML = ok
      ? `<span class="good">Correct.</span> ${g.why}`
      : `<span class="bad">Not this time.</span> Expected <b>${expected==='oxy'?'oxytone':'barytone'}</b>. ${g.why}`;
  }

  btnAnalyze.addEventListener('click', render);
  btnRandom.addEventListener('click', setRandom);
  inp.addEventListener('input', render);
  mode.addEventListener('change', render);
  kind.addEventListener('change', render);
  pos.addEventListener('input', render);
  document.querySelectorAll('input[name="acc"]').forEach(r => r.addEventListener('change', render));

  qNext.addEventListener('click', nextQuiz);
  qOxy.addEventListener('click', () => answerQuiz('oxy'));
  qBary.addEventListener('click', () => answerQuiz('bary'));

  // init
  inp.value = 'πυραμις';
  nextQuiz();
  render();
})();

