passages.gadget_js:
(() => {
  const $ = (sel) => document.querySelector(sel);
  const inEl = $('#in');
  const normEl = $('#norm');
  const syllEl = $('#syll');
  const outEl = $('#out');
  const ruleEl = $('#rule');
  const btnGuess = $('#btnGuess');
  const btnStrip = $('#btnStrip');
  const btnRandom = $('#btnRandom');

  // --- Polytonic helpers ---
  // Remove combining marks and precomposed tonos/oxia etc. by NFD stripping.
  function stripDiacritics(s){
    return (s || '')
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g,'')
      .normalize('NFC');
  }

  // Basic vowel set (incl. iota subscript as combining mark is stripped above)
  const V = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

  function isVowel(ch){ return V.has(ch); }

  // Rough syllable count: count vowel groups (treat diphthongs as one group).
  // This is intentionally approximate.
  const diph = new Set([
    'αι','ει','οι','υι','αυ','ευ','ηυ','ου',
    'ΑΙ','ΕΙ','ΟΙ','ΥΙ','ΑΥ','ΕΥ','ΗΥ','ΟΥ'
  ]);

  function syllableGroups(s){
    const t = stripDiacritics(s).replace(/\s+/g,'').trim();
    const groups = [];
    let i=0;
    while(i < t.length){
      const ch = t[i];
      if(isVowel(ch)){
        // check diphthong
        const pair = t.slice(i,i+2);
        if(pair.length===2 && diph.has(pair)){
          groups.push({start:i, end:i+2, text:pair});
          i += 2;
        } else {
          groups.push({start:i, end:i+1, text:ch});
          i += 1;
        }
      } else {
        i += 1;
      }
    }
    return {t, groups};
  }

  function endsWithAny(s, arr){
    return arr.some(x => s.endsWith(x));
  }

  // Place an accent on a target vowel group index.
  // type: 'acute' | 'circ'
  function accentOnGroup(original, groupIndexFromEnd, type){
    const base = stripDiacritics(original).replace(/\s+/g,'').trim();
    const {t, groups} = syllableGroups(base);
    if(groups.length === 0) return {word: base, ok:false, why:'No vowels found.'};

    const idx = groups.length - 1 - groupIndexFromEnd;
    if(idx < 0 || idx >= groups.length) return {word: base, ok:false, why:'Not enough syllables.'};

    const g = groups[idx];
    const chunk = t.slice(g.start, g.end);

    // Accent only the first vowel of the group (toy simplification).
    const first = chunk[0];
    const rest = chunk.slice(1);

    const acuteMap = {
      'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
      'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
    };
    const circMap = {
      'α':'ᾶ','η':'ῆ','ι':'ῖ','υ':'ῦ','ω':'ῶ',
      'Α':'ᾶ','Η':'ῆ','Ι':'ῖ','Υ':'ῦ','Ω':'ῶ'
    };

    let accentedFirst = first;
    if(type === 'acute') accentedFirst = acuteMap[first] || first;
    if(type === 'circ') accentedFirst = circMap[first] || (acuteMap[first] || first);

    const newChunk = accentedFirst + rest;
    const out = t.slice(0, g.start) + newChunk + t.slice(g.end);
    return {word: out, ok:true, why:null, groups};
  }

  // --- Herodian-ish toy rules ---
  const examples = [
    {w:'Ῥηνίς', note:'-νις, acute (as in passage)'} ,
    {w:'Θυνίς', note:'ethnic, acute'} ,
    {w:'Βιθυνίς', note:'acute'} ,
    {w:'μαινίς', note:'penult diphthong → acute'} ,
    {w:'θεραπαινίς', note:'penult diphthong → acute'} ,
    {w:'Ὠκεανίς', note:'-ανις >2 syllables → acute'} ,
    {w:'Λυκαονίς', note:'-ονις >2 syllables → acute'} ,
    {w:'εὐμενίς', note:'-ενις >2 syllables → acute'} ,
    {w:'νεᾶνις', note:'special: circumflex on antepenult'} ,
    {w:'εὖνις', note:'special: “βαρύνεται” (toy: no accent)'}
  ];

  const barytoneLike = new Set(['ευνις','βουνις','χλουνις']); // stripped
  const specialCirc = new Set(['νεανις','αδανις']);

  function guess(word, mode){
    const raw = (word||'').trim();
    const base = stripDiacritics(raw).replace(/\s+/g,'');
    const lower = base.toLowerCase();

    const {groups} = syllableGroups(base);
    const syllN = groups.length;

    // Build syllable sketch
    const sketch = groups.map((g,i)=>{
      const posFromEnd = groups.length-1-i;
      const label = posFromEnd===0?'ult':(posFromEnd===1?'pen':(posFromEnd===2?'ant':'pre'+posFromEnd));
      return `${g.text}(${label})`;
    }).join(' · ');

    // Forced modes
    if(mode === 'force-acute'){
      const r = accentOnGroup(base, 0, 'acute');
      return {out:r.word, rule:'Forced: acute on ultima (toy).', norm:base, sketch};
    }
    if(mode === 'force-circ'){
      const r = accentOnGroup(base, 2, 'circ');
      return {out:r.word, rule:'Forced: circumflex on antepenult (toy).', norm:base, sketch};
    }

    // Auto mode
    if(barytoneLike.has(lower)){
      return {out: base, rule:'Special list (εὖνις/βοῦνις/χλοῦνις): passage says “βαρύνεται”. Toy simplification: leave unaccented.', norm:base, sketch};
    }

    if(specialCirc.has(lower)){
      const r = accentOnGroup(base, 2, 'circ');
      return {out: r.word, rule:'Special case: νεᾶνις (and Ἄδανις) → circumflex on antepenult (toy).', norm:base, sketch};
    }

    // If ends in -ανις and >2 syllables => acute on ultima
    if(endsWithAny(lower, ['ανις']) && syllN > 2){
      const r = accentOnGroup(base, 0, 'acute');
      return {out:r.word, rule:'Rule: -ανις (fem.) with >2 syllables → acute (toy places it on ultima).', norm:base, sketch};
    }

    // -ενις or -ονις and >2 syllables => acute on ultima
    if((endsWithAny(lower, ['ενις','ονις'])) && syllN > 2){
      const r = accentOnGroup(base, 0, 'acute');
      return {out:r.word, rule:'Rule: -ενις / -ονις with >2 syllables → acute (toy places it on ultima).', norm:base, sketch};
    }

    // -νις with diphthong in penult => acute on ultima
    if(endsWithAny(lower, ['νις'])){
      // penult vowel group is groups[syllN-2]
      if(syllN >= 2){
        const pen = groups[syllN-2].text;
        const pen2 = pen.length===2 ? pen : null;
        const penIsDiph = pen2 && diph.has(pen2) || diph.has(pen.toLowerCase());
        if(penIsDiph){
          const r = accentOnGroup(base, 0, 'acute');
          return {out:r.word, rule:'Rule: -νις (fem.) with diphthong in penult → acute (toy places it on ultima).', norm:base, sketch};
        }
      }
    }

    // Fallback: if it ends in -νις, just acute on ultima (common in this passage)
    if(endsWithAny(lower, ['νις'])){
      const r = accentOnGroup(base, 0, 'acute');
      return {out:r.word, rule:'Fallback: ends in -νις → acute (toy default for this passage).', norm:base, sketch};
    }

    return {out: base, rule:'No -νις pattern detected. (Try a word ending in -νις / -ανις / -ενις / -ονις.)', norm:base, sketch};
  }

  function currentMode(){
    const r = document.querySelector('input[name="mode"]:checked');
    return r ? r.value : 'auto';
  }

  function render(){
    const w = inEl.value;
    const g = guess(w, currentMode());
    normEl.textContent = g.norm || '—';
    syllEl.textContent = g.sketch || '—';
    outEl.textContent = g.out || '—';
    ruleEl.textContent = g.rule || '—';
  }

  btnGuess.addEventListener('click', render);
  btnStrip.addEventListener('click', () => {
    inEl.value = stripDiacritics(inEl.value);
    render();
  });
  btnRandom.addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inEl.value = ex.w;
    render();
    ruleEl.textContent = `Example: ${ex.note}. ` + ruleEl.textContent;
  });

  inEl.addEventListener('keydown', (e) => {
    if(e.key === 'Enter') render();
  });

  // Seed
  inEl.value = 'Ὠκεανις';
  render();
})();

