passages.gadget_js:
// Herodian -νις accent toy (offline, vanilla JS)

const $ = (sel) => document.querySelector(sel);

// --- Unicode helpers ---
function nfd(s){ return (s||"").normalize('NFD'); }
function nfc(s){ return (s||"").normalize('NFC'); }

// Remove Greek diacritics (combining marks), keep base letters.
function stripDiacritics(s){
  return nfd(s).replace(/[\u0300-\u036f]/g, "");
}

// Roughly remove punctuation/spaces.
function cleanGreek(s){
  return (s||"")
    .replace(/[··.,;:!?\-–—()\[\]{}"'“”‘’]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

// Greek vowels (base letters, lowercase)
const VOWELS = new Set(["α","ε","η","ι","ο","υ","ω"]);

function toLowerGreek(s){ return (s||"").toLowerCase(); }

function isVowel(ch){ return VOWELS.has(ch); }

function lastVowelIndex(base){
  for(let i=base.length-1;i>=0;i--){
    if(isVowel(base[i])) return i;
  }
  return -1;
}

function addAcuteToLastVowel(word, mode){
  // mode: 'poly' (oxia) or 'mono' (tonos)
  const acute = mode === 'mono' ? "\u0301" : "\u0301"; // same combining acute; polytonic vs monotonic differs in precomposed forms, but combining works.
  const wNFD = nfd(word);
  // Build mapping from base-letter positions to NFD indices.
  let base = "";
  let map = []; // baseIndex -> index in NFD string where that base char begins
  for(let i=0;i<wNFD.length;i++){
    const c = wNFD[i];
    // combining marks are in 0300-036F
    if(!(/[\u0300-\u036f]/.test(c))){
      map.push(i);
      base += c;
    }
  }
  const baseLower = toLowerGreek(stripDiacritics(base));
  const lv = lastVowelIndex(baseLower);
  if(lv < 0) return word;

  // Insert acute after the base vowel and after any existing combining marks that belong to it?
  // In NFD, combining marks follow the base letter. We'll insert acute right after the base letter,
  // but if there are already combining marks, put acute after them to avoid splitting.
  const nfdIndex = map[lv];
  let j = nfdIndex + 1;
  while(j < wNFD.length && /[\u0300-\u036f]/.test(wNFD[j])) j++;

  // If already has acute/tonos on that vowel, do nothing.
  const segment = wNFD.slice(nfdIndex, j);
  if(segment.includes("\u0301")) return nfc(wNFD);

  const out = wNFD.slice(0, j) + acute + wNFD.slice(j);
  return nfc(out);
}

function hasAnyAccent(word){
  const d = nfd(word);
  // acute, grave, circumflex, tonos
  return /[\u0300\u0301\u0342]/.test(d);
}

// --- Syllable counting (very rough) ---
function countSyllables(word){
  // Count vowel groups in a diacritic-stripped, lowercase string.
  const s = toLowerGreek(stripDiacritics(word));
  let count = 0;
  let prevV = false;
  for(const ch of s){
    const v = isVowel(ch);
    if(v && !prevV) count++;
    prevV = v;
  }
  return count;
}

function endsWithAny(baseLower, endings){
  return endings.find(e => baseLower.endsWith(e)) || null;
}

// --- Rule toy ---
const EXCEPT_BARY = new Map([
  // explicitly said "βαρύνονται" in the passage
  ["πυηνις", "Named as not-derivative → barytone"],
  ["αθηνις", "Named as not-derivative → barytone"],
  ["αδωνις", "Named as not-derivative → barytone"],
  ["ονωνις", "Named as not-derivative → barytone"],
  ["ασδυνις", "Named exception → barytone"],
]);

const ENDINGS = ["ηνις","ωνις","ινις","υνις","νις"]; // base, lowercase

function analyze(word){
  const raw = cleanGreek(word);
  if(!raw) return { ok:false, msg:"Type a Greek word first." };

  const baseLower = toLowerGreek(stripDiacritics(raw)).replace(/\s+/g, "");
  const ending = endsWithAny(baseLower, ENDINGS);
  const syl = countSyllables(raw);

  let predicted = null; // 'oxy' | 'not'
  let why = [];

  if(EXCEPT_BARY.has(baseLower)){
    predicted = 'not';
    why.push(EXCEPT_BARY.get(baseLower));
  }

  if(!ending){
    if(predicted === null) predicted = 'not';
    why.push("Does not match the -νις family endings in this passage.");
  } else {
    why.push(`Ends with -${ending}.`);

    if(predicted === null){
      if(["ηνις","ωνις","ινις","υνις"].includes(ending)){
        if(syl > 2){
          predicted = 'oxy';
          why.push("Heuristic: >2 syllables → oxytone (…νίς) per Herodian.");
        } else {
          predicted = 'not';
          why.push("Heuristic: not >2 syllables → rule not triggered.");
        }
      } else if(ending === "νις"){
        // Herodian: -νις, >2 syllables, consonant in penult → oxytone.
        if(syl > 2){
          // Determine penult nucleus: find last two vowel groups; check if penult has consonant before its vowel.
          const s = toLowerGreek(stripDiacritics(raw)).replace(/\s+/g, "");
          // Find indices of vowel-group starts
          let starts = [];
          let prevV = false;
          for(let i=0;i<s.length;i++){
            const v = isVowel(s[i]);
            if(v && !prevV) starts.push(i);
            prevV = v;
          }
          const penultStart = starts.length >= 2 ? starts[starts.length-2] : -1;
          const hasConsonantInPenult = (penultStart > 0) ? !isVowel(s[penultStart-1]) : false;
          if(hasConsonantInPenult){
            predicted = 'oxy';
            why.push("Heuristic: >2 syllables and consonant before penult vowel → oxytone (…νίς)." );
          } else {
            predicted = 'not';
            why.push("Heuristic: penult not clearly consonant-led → not predicted oxytone by this toy." );
          }
        } else {
          predicted = 'not';
          why.push("Heuristic: not >2 syllables → rule not triggered.");
        }
      }
    }
  }

  const suggestedPoly = (predicted === 'oxy') ? addAcuteToLastVowel(raw, 'poly') : raw;
  const suggestedMono = (predicted === 'oxy') ? addAcuteToLastVowel(raw, 'mono') : raw;

  return {
    ok:true,
    raw,
    baseLower,
    ending,
    syllables:syl,
    predicted,
    why,
    suggestedPoly,
    suggestedMono
  };
}

function renderAnalysis(res){
  const out = $('#out');
  if(!res.ok){
    out.innerHTML = `<div class="k">Message</div><div class="v">${escapeHTML(res.msg)}</div>`;
    return;
  }

  const tag = res.predicted === 'oxy'
    ? `<span class="tag good">Predicted: OXYTONE</span>`
    : `<span class="tag bad">Predicted: NOT oxytone</span>`;

  const endingTag = res.ending
    ? `<span class="tag">Ending: -${escapeHTML(res.ending)}</span>`
    : `<span class="tag warn">Ending: (none)</span>`;

  const force = $('#chkForce').checked;
  const showMono = $('#chkMonotonic').checked;

  const alreadyAcc = hasAnyAccent(res.raw);
  const polyOut = (res.predicted === 'oxy')
    ? (force ? res.suggestedPoly : (alreadyAcc ? res.raw : res.suggestedPoly))
    : res.raw;

  const monoOut = (res.predicted === 'oxy')
    ? (force ? res.suggestedMono : (alreadyAcc ? res.raw : res.suggestedMono))
    : res.raw;

  out.innerHTML = `
    <div>${tag} ${endingTag} <span class="tag">Syllables≈ ${res.syllables}</span></div>
    <div class="grid" style="margin-top:10px">
      <div>
        <div class="k">Input</div>
        <div class="v">${escapeHTML(res.raw)}</div>
      </div>
      <div>
        <div class="k">Toy output (accented if predicted)</div>
        <div class="v">${escapeHTML(polyOut)}</div>
        ${showMono ? `<div class="small" style="margin-top:6px"><span class="k">Monotonic-ish</span><div class="v" style="font-size:18px">${escapeHTML(monoOut)}</div></div>` : ``}
      </div>
    </div>
    <div style="margin-top:10px">
      <div class="k">Why (toy reasoning)</div>
      <div class="small">${res.why.map(x=>`• ${escapeHTML(x)}`).join('<br>')}</div>
    </div>
  `;
}

function escapeHTML(s){
  return (s||"").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

// --- Examples from the passage ---
const EXAMPLES = [
  "Ἀραφηνίς","Ἑλληνίς","Παλληνίς","Κυζικηνίς","Μεσσηνίς","Τροιζηνίς",
  "Αὐξωνίς","Ἀσκαλωνίς","Βαβυλωνίς","Δωδωνίς","Ἰτωνίς","Κραννωνίς",
  "Σκιρωνίς","Τριτωνίς","Χαιρωνίς",
  // exceptions
  "Πυῆνις","Ἄθηνις","Ἄδωνις","ὄνωνις","Ἄσδυνις",
  // -νις example
  "Ἀβαρνίς"
];

function randomExample(){
  return EXAMPLES[Math.floor(Math.random()*EXAMPLES.length)];
}

// --- Game ---
let gCurrent = null;
let gScore = 0;
let gTotal = 0;

function deal(){
  const w = randomExample();
  gCurrent = analyze(w);
  $('#gWord').textContent = w;
  const hint = gCurrent.ending ? `Ends in -${gCurrent.ending}; syllables≈${gCurrent.syllables}` : `No -νις ending detected`;
  $('#gHint').textContent = hint;
  $('#verdict').textContent = "";
}

function judge(guessOxy){
  if(!gCurrent || !gCurrent.ok){
    $('#verdict').innerHTML = "Deal a word first.";
    return;
  }
  const correctOxy = (gCurrent.predicted === 'oxy');
  gTotal++;
  if(guessOxy === correctOxy) gScore++;
  $('#score').textContent = String(gScore);
  $('#total').textContent = String(gTotal);

  const shown = (gCurrent.predicted === 'oxy') ? addAcuteToLastVowel(gCurrent.raw, 'poly') : gCurrent.raw;
  $('#verdict').innerHTML = `<strong>${guessOxy===correctOxy ? 'Correct' : 'Not quite'}</strong>. Toy predicts: <strong>${correctOxy ? 'oxytone' : 'not oxytone'}</strong>. Suggested form: <strong>${escapeHTML(shown)}</strong><br><span class="small">${gCurrent.why.map(x=>`• ${escapeHTML(x)}`).join(' ')}</span>`;
}

function resetGame(){
  gScore = 0; gTotal = 0;
  $('#score').textContent = "0";
  $('#total').textContent = "0";
  $('#gWord').textContent = "—";
  $('#gHint').textContent = "—";
  $('#verdict').textContent = "";
  gCurrent = null;
}

// --- Wire up UI ---
$('#btn').addEventListener('click', () => renderAnalysis(analyze($('#inp').value)));
$('#inp').addEventListener('keydown', (e)=>{ if(e.key === 'Enter') $('#btn').click(); });
$('#btnRandom').addEventListener('click', ()=>{
  const ex = randomExample();
  $('#inp').value = ex;
  renderAnalysis(analyze(ex));
});
$('#chkForce').addEventListener('change', ()=> renderAnalysis(analyze($('#inp').value)));
$('#chkMonotonic').addEventListener('change', ()=> renderAnalysis(analyze($('#inp').value)));

$('#deal').addEventListener('click', deal);
$('#guessOxy').addEventListener('click', ()=>judge(true));
$('#guessNot').addEventListener('click', ()=>judge(false));
$('#reset').addEventListener('click', resetGame);

// initial
renderAnalysis({ok:false,msg:"Try an example, or type a word ending in -ηνις / -ωνις / -ινις / -υνις / -νις."});

