const $ = (sel) => document.querySelector(sel);

const modeEl = $('#mode');
const singleBox = $('#singleBox');
const futureBox = $('#futureBox');
const inputEl = $('#input');
const futureEl = $('#future');
const nounEl = $('#noun');

const resultEl = $('#result');
const ruleEl = $('#rule');
const notesEl = $('#notes');

const examplesSingle = [
  'λεξις', 'σκηψις', 'ψυξις', 'ἁψις', 'πυξις', 'ὀξις',
  'κοπις', 'λεπις', 'πραπις', 'τροπις', 'ἐλπις', 'ἀσπις',
  'Απις', 'Ἀπις', 'Ἆπις', 'Καβαρνις', 'Θεογνις'
];

const examplesFuture = [
  {f:'λεξω', n:'λεξις'},
  {f:'σκηψω', n:'σκηψις'},
  {f:'ψυξω', n:'ψυξις'},
  {f:'ἑξω', n:'ἑξις'}
];

// --- Greek helpers (toy-level) ---
const COMBINING = {
  acute: '\u0301',
  grave: '\u0300',
  circumflex: '\u0342',
  diaeresis: '\u0308',
  smooth: '\u0313',
  rough: '\u0314',
  macron: '\u0304',
  breve: '\u0306',
  iotaSub: '\u0345'
};

function nfd(s){ return (s||'').normalize('NFD'); }
function nfc(s){ return (s||'').normalize('NFC'); }

function stripAccentsKeepBreathings(s){
  // Remove accent marks (acute/grave/circumflex) but keep breathings/diaeresis/iota sub.
  const d = nfd(s);
  const out = [];
  for (const ch of d){
    if (ch === COMBINING.acute || ch === COMBINING.grave || ch === COMBINING.circumflex) continue;
    out.push(ch);
  }
  return nfc(out.join(''));
}

function stripAllDiacritics(s){
  const d = nfd(s);
  const out = [];
  for (const ch of d){
    // remove all combining marks
    if (ch >= '\u0300' && ch <= '\u036F') continue;
    out.push(ch);
  }
  return nfc(out.join(''));
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code >= 0x0370 && code <= 0x03FF) || (code >= 0x1F00 && code <= 0x1FFF);
}

function tokenizeLetters(s){
  // Return array of "letters" where each base Greek letter carries its combining marks.
  const d = nfd(s);
  const letters = [];
  let cur = '';
  for (const ch of d){
    if (isGreekLetter(ch) && !(ch >= '\u0300' && ch <= '\u036F')){
      if (cur) letters.push(cur);
      cur = ch;
    } else {
      // combining or punctuation/space
      if (!cur){
        // start a non-letter token
        letters.push(ch);
      } else {
        cur += ch;
      }
    }
  }
  if (cur) letters.push(cur);
  // Merge consecutive non-letter tokens
  const merged = [];
  for (const tok of letters){
    if (!merged.length) merged.push(tok);
    else {
      const a = merged[merged.length-1];
      const aIsLetter = isGreekLetter(nfd(a)[0] || '');
      const tIsLetter = isGreekLetter(nfd(tok)[0] || '');
      if (!aIsLetter && !tIsLetter) merged[merged.length-1] = a + tok;
      else merged.push(tok);
    }
  }
  return merged;
}

const VOWELS = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

function baseChar(letterToken){
  const d = nfd(letterToken);
  return d[0] || '';
}

function isVowelToken(tok){
  const b = baseChar(tok);
  return VOWELS.has(b);
}

function findLastVowelIndex(tokens){
  for (let i=tokens.length-1;i>=0;i--) if (isVowelToken(tokens[i])) return i;
  return -1;
}

function findPenultVowelIndex(tokens){
  let count = 0;
  for (let i=tokens.length-1;i>=0;i--){
    if (isVowelToken(tokens[i])){
      count++;
      if (count===2) return i;
    }
  }
  return -1;
}

function addAccentToToken(tok, accent){
  // Add combining accent to the vowel token, preserving existing breathings/diaeresis.
  const d = nfd(tok);
  const base = d[0];
  const marks = d.slice(1);
  // remove any existing accent marks
  const kept = [];
  for (const m of marks){
    if (m === COMBINING.acute || m === COMBINING.grave || m === COMBINING.circumflex) continue;
    kept.push(m);
  }
  kept.push(accent);
  return nfc(base + kept.join(''));
}

function accentWord(word, where, accentType){
  const clean = stripAccentsKeepBreathings(word);
  const tokens = tokenizeLetters(clean);
  const idx = (where==='ultima') ? findLastVowelIndex(tokens)
            : (where==='penult') ? findPenultVowelIndex(tokens)
            : -1;
  if (idx < 0) return {out: word, ok:false};
  tokens[idx] = addAccentToToken(tokens[idx], accentType);
  return {out: tokens.join(''), ok:true};
}

function endsWithAny(s, arr){
  const t = stripAllDiacritics(s).toLowerCase();
  return arr.some(e => t.endsWith(e));
}

function startsWithVowel(s){
  const t = stripAllDiacritics(s).trim();
  for (const ch of t){
    if (isGreekLetter(ch)) return VOWELS.has(ch);
  }
  return false;
}

// --- Rule engine (heuristic) ---
const notedAcute = new Map([
  ['αψις','ἁψίς'],
]);
const notedBary = new Map([
  ['καβαρνις','Κάβαρνις'],
  ['θεογνις','Θέογνις'],
]);
const notedException = new Map([
  ['τροπις','τρόπις']
]);

function analyzeSingle(raw){
  const w = (raw||'').trim();
  if (!w) return {result:'—', rule:'—', notes:'Type a word first.'};

  const key = stripAllDiacritics(w).toLowerCase();

  if (notedAcute.has(key)){
    return {result: notedAcute.get(key), rule:"Noted by Herodian: ἁψίς is oxýtonon (acute on ultima).", notes:"This is explicitly singled out (σεσημείωται)."};
  }
  if (notedException.has(key)){
    return {result: notedException.get(key), rule:"Noted exception: τρόπις.", notes:"Herodian flags it as exceptional among -πις forms."};
  }
  if (notedBary.has(key)){
    return {result: notedBary.get(key), rule:"Herodian: some -νις names are barýtonon (accent not on ultima).", notes:"Toy output uses a penult acute to represent barýtonon."};
  }

  // -ξις / -ψις: default barytone (penult)
  if (endsWithAny(w, ['ξις','ψις'])){
    const acc = accentWord(w, 'penult', COMBINING.acute);
    return {
      result: acc.out,
      rule:"Rule (toy): -ξις / -ψις (esp. from futures) → barýtonon (penult accent).",
      notes:"If your word is a denominative (e.g. πυξίς), Herodian often expects oxýtonon instead—try that by editing the result mentally." 
    };
  }

  // -πις heuristics
  if (endsWithAny(w, ['πις'])){
    const beginsV = startsWithVowel(w);
    // If begins with vowel, toy leans acute (per passage: vowel-initial, not diminutive → acute)
    if (beginsV){
      const acc = accentWord(w, 'ultima', COMBINING.acute);
      return {
        result: acc.out,
        rule:"Rule (toy): vowel-initial -πις (often) → oxýtonon (acute on ultima).",
        notes:"Herodian’s full rule depends on syllable length and whether it’s a diminutive/ethnic; this toy only uses the initial vowel as a hint." 
      };
    }
    // consonant-initial: default acute for 'two short syllables' class
    const acc = accentWord(w, 'ultima', COMBINING.acute);
    return {
      result: acc.out,
      rule:"Rule (toy): consonant-initial disyllabic -πις with two shorts → oxýtonon (acute on ultima).",
      notes:"Examples in the passage: κοπίς, λεπίς, πραπίς. Some other -πις words are barýtona (e.g. σάλπις) depending on other factors." 
    };
  }

  // fallback: just add an acute on penult if possible
  const acc = accentWord(w, 'penult', COMBINING.acute);
  return {
    result: acc.out,
    rule:"Fallback: add a penult acute (not a real rule).",
    notes:"Try a word ending in -ξις, -ψις, or -πις for rules closer to the passage." 
  };
}

function analyzeFuture(fut, noun){
  const f = (fut||'').trim();
  const n = (noun||'').trim();
  if (!f || !n) return {result:'—', rule:'—', notes:'Fill in both fields.'};

  const fKey = stripAllDiacritics(f).toLowerCase();
  const nKey = stripAllDiacritics(n).toLowerCase();

  const okFuture = fKey.endsWith('ξω') || fKey.endsWith('ψω');
  const okNoun = nKey.endsWith('ξις') || nKey.endsWith('ψις');

  let notes = [];
  if (!okFuture) notes.push("Future doesn’t look like -ξω/-ψω.");
  if (!okNoun) notes.push("Noun doesn’t look like -ξις/-ψις.");

  // toy: if future ends -ξω, noun should end -ξις; if -ψω then -ψις
  if (okFuture && okNoun){
    const fEnd = fKey.slice(-2);
    const nEnd = nKey.slice(-3);
    if (fEnd === 'ξω' && nEnd !== 'ξις') notes.push('Mismatch: -ξω usually pairs with -ξις.');
    if (fEnd === 'ψω' && nEnd !== 'ψις') notes.push('Mismatch: -ψω usually pairs with -ψις.');
  }

  const acc = accentWord(n, 'penult', COMBINING.acute);
  return {
    result: acc.out,
    rule:"Herodian: -ξις/-ψις formed from futures are barýtona (penult accent).",
    notes: notes.length ? notes.join(' ') : "Try comparing: λεξω → λέξις; σκηψω → σκῆψις; ψυξω → ψῦξις." 
  };
}

function render(out){
  resultEl.textContent = out.result;
  ruleEl.textContent = out.rule;
  notesEl.textContent = out.notes;
}

function run(){
  if (modeEl.value === 'single') render(analyzeSingle(inputEl.value));
  else render(analyzeFuture(futureEl.value, nounEl.value));
}

function setMode(m){
  modeEl.value = m;
  const isSingle = m === 'single';
  singleBox.classList.toggle('hidden', !isSingle);
  futureBox.classList.toggle('hidden', isSingle);
  // run analysis on switch if something is filled
  run();
}

modeEl.addEventListener('change', (e)=> setMode(e.target.value));
$('#go').addEventListener('click', run);

$('#clear').addEventListener('click', ()=>{
  inputEl.value = '';
  futureEl.value = '';
  nounEl.value = '';
  render({result:'—', rule:'—', notes:'—'});
  inputEl.focus();
});

$('#shuffle').addEventListener('click', ()=>{
  if (modeEl.value === 'single'){
    const w = examplesSingle[Math.floor(Math.random()*examplesSingle.length)];
    inputEl.value = w;
  } else {
    const ex = examplesFuture[Math.floor(Math.random()*examplesFuture.length)];
    futureEl.value = ex.f;
    nounEl.value = ex.n;
  }
  run();
});

// Enter to analyze
[inputEl, futureEl, nounEl].forEach(el=>{
  el.addEventListener('keydown', (e)=>{
    if (e.key === 'Enter') run();
  });
});

// Click chips to load
for (const chip of document.querySelectorAll('.chip')){
  chip.style.cursor = 'pointer';
  chip.title = 'Click to load';
  chip.addEventListener('click', ()=>{
    setMode('single');
    inputEl.value = chip.textContent;
    run();
  });
}

// init
setMode('single');
render({result:'—', rule:'Choose a mode and type Greek.', notes:'The toy adds an accent mark based on a few patterns in the passage.'});
inputEl.focus();

