const $ = (sel) => document.querySelector(sel);

const examples = [
  "Κεκροπις",
  "Δρυοπις",
  "Αἰθιοπις",
  "Σινωπις",
  "Προσωπις",
  "Ιαπις",
  "Πριαπις",
  "Σαραπις",
  "φυλοπις",
  "ιασπις",
  "Δωρις",
  "Τευκρις",
  "πατρις",
  "χειρις",
  "Νευρις"
];

// --- Greek helpers (toy-level) ---
const combining = /[\u0300\u0301\u0342\u0313\u0314\u0345\u0308]/g; // grave, acute, circumflex, smooth, rough, iota sub, diaeresis

function stripDiacritics(s){
  return s.normalize('NFD').replace(combining,'').normalize('NFC');
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code >= 0x0370 && code <= 0x03FF) || (code >= 0x1F00 && code <= 0x1FFF);
}

function onlyGreek(s){
  const t = s.trim();
  if(!t) return false;
  for(const ch of t){
    if(ch === ' ' || ch === '·' || ch === '’' || ch === "'" || ch === '‑' || ch === '-' ) continue;
    if(!isGreekLetter(ch) && !combining.test(ch.normalize('NFD'))) return false;
  }
  return true;
}

const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
function isVowel(ch){
  return vowels.has(ch);
}

function roughSyllableCount(word){
  // Very rough: count vowel nuclei in stripped word, treating common diphthongs as one.
  const w = stripDiacritics(word);
  const chars = Array.from(w);
  let n = 0;
  for(let i=0;i<chars.length;i++){
    const c = chars[i];
    if(!isVowel(c)) continue;
    const next = chars[i+1] || '';
    const pair = (c+next).toLowerCase();
    // diphthongs (toy list)
    if(["αι","ει","οι","υι","αυ","ευ","ου","ηυ","ωυ"].includes(pair)){
      n++; i++; continue;
    }
    n++;
  }
  return n;
}

function detectEnding(word){
  const w = stripDiacritics(word).toLowerCase().replace(/\s+/g,'');
  const endings = ["ωπις","οπις","απις","πις","ρις"]; // order matters
  for(const e of endings){
    if(w.endsWith(e)) return e;
  }
  return null;
}

function endsWithClusterBeforePis(word){
  // heuristic for "long by position" before -πις: consonant cluster right before 'πις'
  const w = stripDiacritics(word).toLowerCase().replace(/\s+/g,'');
  const idx = w.lastIndexOf("πις");
  if(idx <= 0) return false;
  const before = w.slice(0, idx);
  // find last two letters before -pis
  const a = before.slice(-1);
  const b = before.slice(-2, -1);
  if(!a) return false;
  // treat vowels as not cluster
  const isCons = (ch) => ch && !isVowel(ch) && /[α-ω]/i.test(ch);
  // cluster if last two are consonants (e.g. -σπ- in ἴασπις)
  return isCons(a) && isCons(b);
}

function applyAcuteToVowel(word, vowelIndexFromEnd){
  // Place acute on the vowel nucleus of the target syllable counting from end: 1=ultima,2=penult,3=antepenult
  // We strip existing accents first, then add combining acute to the chosen vowel.
  const baseNFD = stripDiacritics(word).normalize('NFD');
  // Build map of vowel nuclei positions in NFC string indices (approx via codepoints)
  const base = baseNFD.normalize('NFC');
  const chars = Array.from(base);

  // Identify vowel nuclei indices (simple: each vowel char counts; diphthongs count as one nucleus at first vowel)
  const nuclei = [];
  for(let i=0;i<chars.length;i++){
    const c = chars[i];
    if(!isVowel(c)) continue;
    const next = chars[i+1] || '';
    const pair = (c+next).toLowerCase();
    if(["αι","ει","οι","υι","αυ","ευ","ου","ηυ","ωυ"].includes(pair)){
      nuclei.push(i);
      i++; continue;
    }
    nuclei.push(i);
  }
  if(nuclei.length === 0) return {word: base, placed: "—"};

  const target = nuclei[nuclei.length - vowelIndexFromEnd];
  if(target === undefined) return {word: base, placed: "(too short)"};

  // Add combining acute after that vowel character.
  const acute = "\u0301";
  const out = chars.map((ch, i) => i === target ? (ch.normalize('NFD') + acute).normalize('NFC') : ch).join('');
  const placed = (vowelIndexFromEnd===1?"ultima":vowelIndexFromEnd===2?"penult":"antepenult");
  return {word: out, placed};
}

function guessRule(word){
  const ending = detectEnding(word);
  const syll = roughSyllableCount(word);

  let accentFromEnd = null;
  let ruleText = "No matching ending rule in this toy.";
  let badge = "";

  const wBare = stripDiacritics(word).toLowerCase().replace(/\s+/g,'');

  if(!ending){
    return {ending:"—", syll, accentFromEnd:null, ruleText, badge};
  }

  if(ending === "ρις"){
    if(syll === 2){
      accentFromEnd = 1; // oxytone
      ruleText = "-ρις disyllables (diminutive/patronymic sense) → oxytone (acute on ultima).";
    } else {
      accentFromEnd = 2;
      ruleText = "-ρις rule here is only for disyllables; for fun, defaulting to penult.";
      badge = "toy default";
    }
  }

  if(ending === "ωπις"){
    if(syll >= 3){
      accentFromEnd = 1;
      ruleText = "-ωπις polysyllables → oxytone (acute on ultima).";
    } else {
      accentFromEnd = 1;
      ruleText = "-ωπις → oxytone (toy applies generally).";
      badge = "toy";
    }
  }

  if(ending === "οπις"){
    if(wBare.endsWith("φυλοπις")){
      accentFromEnd = 3;
      ruleText = "Exception noted: φύλοπις → proparoxytone (acute on antepenult).";
      badge = "exception";
    } else {
      accentFromEnd = 1;
      ruleText = "-οπις polysyllables (not ‘composite’) → oxytone (acute on ultima).";
    }
  }

  if(ending === "απις"){
    if(wBare.endsWith("σαραπις")){
      accentFromEnd = 2;
      ruleText = "Exception noted: Σάραπις is barýtone (accent on penult).";
      badge = "exception";
    } else {
      accentFromEnd = 1;
      ruleText = "-απις polysyllables → oxytone (acute on ultima).";
    }
  }

  if(ending === "πις"){
    // If it is actually -απις/-οπις/-ωπις we already caught it.
    if(syll >= 3 && endsWithClusterBeforePis(word)){
      accentFromEnd = 2;
      ruleText = "-πις polysyllables with long penult by position (toy: consonant cluster before -πις) → barýtone (accent on penult).";
    } else {
      accentFromEnd = 1;
      ruleText = "-πις: passage gives a specific condition; toy defaults to oxytone unless it detects a cluster.";
      badge = "toy default";
    }
  }

  return {ending, syll, accentFromEnd, ruleText, badge};
}

function render(){
  const raw = $('#w').value.trim();
  if(!raw){
    $('#accented').textContent = '—';
    $('#rule').textContent = 'Enter a word to see a rule guess.';
    $('#ending').textContent = '—';
    $('#syll').textContent = '—';
    $('#place').textContent = '—';
    return;
  }

  if(!onlyGreek(raw)){
    $('#accented').textContent = raw;
    $('#rule').innerHTML = "Please use Greek letters (polytonic/monotonic).";
    $('#ending').textContent = '—';
    $('#syll').textContent = '—';
    $('#place').textContent = '—';
    return;
  }

  const g = guessRule(raw);
  $('#ending').textContent = g.ending || '—';
  $('#syll').textContent = String(g.syll);

  if(!g.accentFromEnd){
    $('#accented').textContent = stripDiacritics(raw);
    $('#place').textContent = '—';
    $('#rule').textContent = g.ruleText;
    return;
  }

  const applied = applyAcuteToVowel(raw, g.accentFromEnd);
  $('#accented').textContent = applied.word;
  $('#place').textContent = applied.placed;

  const extra = g.badge ? ` (${g.badge})` : '';
  $('#rule').textContent = g.ruleText + extra;
}

$('#go').addEventListener('click', render);
$('#w').addEventListener('keydown', (e)=>{ if(e.key==='Enter') render(); });
$('#w').addEventListener('input', ()=>{ /* live, but gentle */ render(); });

$('#rnd').addEventListener('click', ()=>{
  const pick = examples[Math.floor(Math.random()*examples.length)];
  $('#w').value = pick;
  render();
  $('#w').focus();
});

$('#clr').addEventListener('click', ()=>{
  $('#w').value = '';
  render();
  $('#w').focus();
});

// initial
render();

