:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --panel2:#1d2140;
  --text:#e9ecff;
  --muted:#b9c0ff;
  --line:#2a2f55;
  --good:#7CFFB2;
  --warn:#ffd27c;
  --bad:#ff7c9a;
  --chip:#232852;
  --chip2:#2b3170;
}
*{box-sizing:border-box}
body{margin:0;background:linear-gradient(180deg,var(--bg),#0b0d18);color:var(--text);font:16px/1.35 system-ui,-apple-system,Segoe UI,Roboto,Arial,"Noto Sans",sans-serif}
.wrap{max-width:980px;margin:0 auto;padding:18px}
header{padding:10px 6px 14px}
h1{margin:0 0 6px;font-size:22px;letter-spacing:.2px}
.sub{margin:0;color:var(--muted)}
.panel{background:rgba(255,255,255,.03);border:1px solid var(--line);border-radius:14px;padding:14px;margin:12px 0;box-shadow:0 10px 30px rgba(0,0,0,.25)}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
label{color:var(--muted);font-size:13px}
#in{flex:1;min-width:260px;padding:10px 12px;border-radius:10px;border:1px solid var(--line);background:var(--panel);color:var(--text);font-size:18px}
button{padding:10px 12px;border-radius:10px;border:1px solid var(--line);background:var(--panel2);color:var(--text);cursor:pointer}
button:hover{border-color:#3a4180}
.small{margin-top:10px;justify-content:space-between}
.tog{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.tog .lbl{color:var(--muted);font-size:13px}
.out{display:grid;grid-template-columns:1.1fr 1.2fr .9fr;gap:12px;margin-top:12px}
@media (max-width:900px){.out{grid-template-columns:1fr}}
.card{background:rgba(0,0,0,.18);border:1px solid var(--line);border-radius:12px;padding:12px}
.k{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.12em}
.v{margin-top:8px;font-size:16px}
.v.big{font-size:26px;letter-spacing:.5px}
.why{margin-top:8px;color:var(--muted);font-size:13px}
.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono",monospace}
