.badge.good{border-color:rgba(124,255,178,.35);color:var(--good)}
.badge.warn{border-color:rgba(255,210,124,.35);color:var(--warn)}
.badge.bad{border-color:rgba(255,124,154,.35);color:var(--bad)}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
.chip{background:var(--chip);border:1px solid var(--line);color:var(--text);padding:8px 10px;border-radius:999px;cursor:pointer;user-select:none}
.chip:hover{background:var(--chip2)}
.chip[aria-selected="true"]{outline:2px solid rgba(124,255,178,.55);border-color:rgba(124,255,178,.35)}
.help h2{margin:0 0 8px;font-size:16px}
.help ul{margin:8px 0 0 18px;color:var(--text)}
.help li{margin:6px 0;color:var(--muted)}
.fine{margin:10px 0 0;color:var(--muted);font-size:12px}

