const $ = (s)=>document.querySelector(s);
const inEl = $('#in');
const predEl = $('#pred');
const whyEl = $('#why');
const accEl = $('#accented');
const syllEl = $('#syllables');
const chipsEl = $('#clickSyll');

const examples = [
  {w:'Παρις', note:'Paris (proper name) — often treated as barytone in the passage list.'},
  {w:'Βαρις', note:'Báris (city/house) — listed as barytone.'},
  {w:'Χαρις', note:'cháris — listed among barytones.'},
  {w:'Νηρις', note:'Nērís — explicitly oxytone in the passage.'},
  {w:'Μακρις', note:'Mákri(s) — proper name in -κρις, barytone.'},
  {w:'ακρις', note:'akrís “locust” — explicitly oxytone (not a proper name).'},
  {w:'Λοκρις', note:'Lokrís — oxytone in the passage.'},
  {w:'Κυπρις', note:'Kýpris — exception with doubled consonant rule (toy approximates).'},
  {w:'Θυμβρις', note:'Thýmbris — barytone example.'},
  {w:'Τιγρις', note:'Tígris — barytone example.'},
  {w:'νεβρις', note:'nebrís — explicitly oxytone.'},
  {w:'πατρις', note:'patrís — disyllabic -τρις derivative, oxytone.'},
  {w:'λατρις', note:'látris — non-derivative/longer type, barytone.'},
  {w:'κιθαρις', note:'kítharis — >2 syllables with α in penult, barytone.'},
  {w:'Συβαρις', note:'Sýbaris — barytone example.'},
  {w:'Μεγαρις', note:'Megarís — exception class, oxytone.'}
];

function normalizeGreek(s){
  return (s||'')
    .trim()
    .replace(/[··]/g,'')
    .replace(/\s+/g,'');
}

function stripAccents(s){
  // Remove combining marks and common precomposed tonos/polytonic by NFD.
  return s.normalize('NFD').replace(/\p{M}+/gu,'').normalize('NFC');
}

function isGreekLetter(ch){
  return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(ch);
}

function endsWithAny(w, arr){
  return arr.some(s=>w.endsWith(s));
}

function syllabifyRough(w){
  // Very rough syllabifier: split before vowel groups.
  // Keeps diphthongs together (αι ει οι υι αυ ευ ου ηυ).
  const s = stripAccents(w);
  const chars = Array.from(s);
  const vowels = 'αεηιουωάέήίόύώϊϋΐΰΑΕΗΙΟΥΩ';
  const isV = (c)=>vowels.includes(c) || /[αεηιουωΑΕΗΙΟΥΩ]/.test(c);
  const lower = (c)=>c.toLowerCase();
  const diph = new Set(['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ωυ']);

  let groups=[];
  let i=0;
  while(i<chars.length){
    // find next vowel
    let start=i;
    while(i<chars.length && !isV(chars[i])) i++;
    if(i>=chars.length){
      if(start<chars.length) groups.push(chars.slice(start).join(''));
      break;
    }
    // include onset consonants in current syllable start
    // We'll start syllable at 'start' and ensure it contains vowel nucleus.
    let nucleusStart=i;
    let nucleus=chars[i];
    // diphthong check
    if(i+1<chars.length && isV(chars[i+1])){
      const pair = lower(chars[i])+lower(chars[i+1]);
      if(diph.has(pair)){
        nucleus = chars[i]+chars[i+1];
        i+=2;
      } else {
        i+=1;
      }
    } else {
      i+=1;
    }
    // now i is after nucleus; we will tentatively take following consonants, but leave last consonant for next onset if another vowel follows.
    let j=i;
    while(j<chars.length && !isV(chars[j])) j++;
    const cons = chars.slice(i,j);
    if(j<chars.length && cons.length>0){
      // split consonant cluster: keep all but last with current syllable
      const keep = cons.length-1;
      const coda = cons.slice(0, keep);
      const nextOnset = cons.slice(keep);
      const syll = chars.slice(start, i).join('') + nucleus + coda.join('');
      groups.push(syll);
      // next syllable starts with last consonant
      i = j - nextOnset.length;
    } else {
      const syll = chars.slice(start, i).join('') + nucleus + cons.join('');
      groups.push(syll);
      i = j;
    }
  }
  // cleanup empties
  groups = groups.filter(x=>x.length);
  return groups;
}

function hasDoubledConsonant(w){
  const s = stripAccents(w).toLowerCase();
  return /(ββ|γγ|δδ|ζζ|θθ|κκ|λλ|μμ|νν|ππ|ρρ|σσ|ττ|φφ|χχ|ψψ|ξξ)/.test(s);
}

function hasInterposedConsonant(w){
  // Herodian: "middle or aspirate or p" before -ρις (…μβρις, …γρις, …πρις etc.)
  // We'll approximate by checking the consonant immediately before final "ρις".
  const s = stripAccents(w).toLowerCase();
  const idx = s.lastIndexOf('ρις');
  if(idx<=0) return false;
  const prev = s[idx-1];
  return 'βγδζθκλμνπρστφχψξ'.includes(prev);
}

function penultHasIotaOrUpsilon(w){
  const syl = syllabifyRough(w);
  if(syl.length<2) return false;
  const pen = stripAccents(syl[syl.length-2]).toLowerCase();
  return pen.includes('ι') || pen.includes('υ');
}

function penultHasAlpha(w){
  const syl = syllabifyRough(w);
  if(syl.length<2) return false;
  const pen = stripAccents(syl[syl.length-2]).toLowerCase();
  return pen.includes('α');
}

function guessAccent(w){
  const raw = normalizeGreek(w);
  const s = stripAccents(raw);
  const lower = s.toLowerCase();

  const info = {class:'warn', label:'uncertain', rule:'Heuristic only.'};

  if(!raw || !Array.from(raw).some(isGreekLetter)){
    return { ...info, class:'bad', label:'needs Greek', rule:'Please type a Greek word.' };
  }

  // explicit-ish exceptions from passage list (toy)
  const lexAcute = new Set(['νηρις','υρις','νεβρις','ακρις','λοκρις','μεγαρις','βλεφαρις','θεαρις','εαρις']);
  if(lexAcute.has(lower)){
    return {class:'good', label:'ὀξύνεται (acute)', rule:'Listed/treated as oxytone in the passage (toy lexicon).', target:'ultima'};
  }

  if(lower.endsWith('κρις')){
    // Proper names in -κρις barytone; common nouns oxytone.
    // We can’t know properness; guess by capitalization.
    const isProper = raw[0] === raw[0].toUpperCase();
    if(isProper){
      return {class:'good', label:'βαρύνεται (recessive)', rule:'-κρις proper name → βαρύνεται (e.g. Μάκρις).', target:'penult'};
    }
    return {class:'warn', label:'ὀξύνεται (acute)', rule:'Non-proper -κρις → ὀξύνεται (e.g. ἀκρίς).', target:'ultima'};
  }

  if(lower.endsWith('τρις')){
    const syl = syllabifyRough(raw);
    if(syl.length===2){
      return {class:'good', label:'ὀξύνεται (acute)', rule:'Disyllabic -τρις derivative → ὀξύνεται (πατρίς).', target:'ultima'};
    }
    return {class:'warn', label:'βαρύνεται (recessive)', rule:'Non-disyllabic -τρις → often βαρύνεται (λάτρις).', target:'penult'};
  }

  if(lower.endsWith('ρις')){
    const syl = syllabifyRough(raw);
    if(syl.length>2 && penultHasAlpha(raw)){
      return {class:'good', label:'βαρύνεται (recessive)', rule:'>2 syllables + α in penult → βαρύνεται (κίθαρις, Σύβαρις).', target:'penult'};
    }

    if(hasInterposedConsonant(raw) && penultHasIotaOrUpsilon(raw) && !hasDoubledConsonant(raw)){
      return {class:'good', label:'βαρύνεται (recessive)', rule:'-ρις with interposed consonant + υ/ι in penult → βαρύνεται (Θύμβρις, Τίγρις).', target:'penult'};
    }

    if(hasDoubledConsonant(raw)){
      return {class:'warn', label:'ὀξύνεται (acute)', rule:'Doubled consonant blocks the barytone tendency (ὕβρις, Κύπρις).', target:'ultima'};
    }

    return {class:'warn', label:'ὀξύνεται (acute)', rule:'Default guess for -ρις here: ὀξύνεται (many exceptions).', target:'ultima'};
  }

  return {class:'warn', label:'not in scope', rule:'Try a word ending in -ρις / -κρις / -τρις.', target:null};
}

function applyAccentToSyllables(syllables, which, style){
  // which: index of syllable to accent (0..n-1)
  // style: tonos or poly
  const mapTonos = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ',
    'ϊ':'ΐ','ϋ':'ΰ','Ϊ':'Ϊ','Ϋ':'Ϋ'
  };
  const mapPolyAcute = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ',
    'ϊ':'ΐ','ϋ':'ΰ'
  };
  const mapPolyGrave = {
    'α':'ὰ','ε':'ὲ','η':'ὴ','ι':'ὶ','ο':'ὸ','υ':'ὺ','ω':'ὼ',
    'Α':'Ὰ','Ε':'Ὲ','Η':'Ὴ','Ι':'Ὶ','Ο':'Ὸ','Υ':'Ὺ','Ω':'Ὼ',
    'ϊ':'ῒ','ϋ':'ῢ'
  };

  function accentOne(syl, kind){
    // kind: 'acute' or 'grave'
    const base = stripAccents(syl);
    const chars = Array.from(base);
    // accent the last vowel in the syllable
    const isV = (c)=>/[αεηιουωΑΕΗΙΟΥΩϊϋ]/.test(c);
    for(let i=chars.length-1;i>=0;i--){
      if(isV(chars[i])){
        if(style==='tonos'){
          chars[i] = mapTonos[chars[i]] || chars[i];
        } else {
          const m = (kind==='grave') ? mapPolyGrave : mapPolyAcute;
          chars[i] = m[chars[i]] || chars[i];
        }
        break;
      }
    }
    return chars.join('');
  }

  const out = syllables.map((s,i)=>{
    if(i!==which) return stripAccents(s);
    // In this toy, "barytone" = accent not on ultima (we use acute on penult),
    // but we also offer a polytonic grave option for fun.
    return accentOne(s, 'acute');
  });
  return out.join('');
}

function renderChips(syllables, selected){
  chipsEl.innerHTML='';
  syllables.forEach((s,i)=>{
    const d=document.createElement('div');
    d.className='chip';
    d.setAttribute('role','listitem');
    d.setAttribute('tabindex','0');
    d.setAttribute('aria-selected', String(i===selected));
    d.textContent = stripAccents(s);
    d.addEventListener('click', ()=>{
      state.forced = i;
      update();
    });
    d.addEventListener('keydown', (e)=>{
      if(e.key==='Enter' || e.key===' '){ e.preventDefault(); state.forced=i; update(); }
    });
    chipsEl.appendChild(d);
  });
}

const state = { forced:null };

function currentStyle(){
  return document.querySelector('input[name="style"]:checked')?.value || 'tonos';
}

function update(){
  const w = normalizeGreek(inEl.value);
  const g = guessAccent(w);

  predEl.innerHTML = `<span class="badge ${g.class}">${g.label}</span>`;
  whyEl.textContent = g.rule;

  const syllables = syllabifyRough(w);
  const showSyl = $('#syll').checked;

  let targetIndex = null;
  if(state.forced!=null) targetIndex = state.forced;
  else if(g.target==='ultima') targetIndex = Math.max(0, syllables.length-1);
  else if(g.target==='penult') targetIndex = Math.max(0, syllables.length-2);
  else targetIndex = Math.max(0, syllables.length-1);

  const accented = applyAccentToSyllables(syllables, targetIndex, currentStyle());
  accEl.textContent = w ? accented : '—';

  syllEl.textContent = showSyl && w ? `Syllables (rough): ${syllables.map(stripAccents).join(' · ')}` : '';
  renderChips(syllables.length?syllables:[w||''], targetIndex);
}

$('#go').addEventListener('click', ()=>{ state.forced=null; update(); });
$('#rand').addEventListener('click', ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  inEl.value = ex.w;
  state.forced=null;
  update();
  whyEl.textContent = whyEl.textContent + ` Example note: ${ex.note}`;
});

inEl.addEventListener('input', ()=>{ state.forced=null; update(); });
for(const r of document.querySelectorAll('input[name="style"]')) r.addEventListener('change', update);
$('#syll').addEventListener('change', update);

// init
inEl.value = 'Μακρις';
update();

