const $ = (sel) => document.querySelector(sel);

const examples = [
  "Ἀστερίς",
  "νυκτερίς",
  "Ἐλευθερίς",
  "Ἑσπερίς",
  "Εὐεσπερίς",
  "Φιλωτερὶς",
  "Πάστερις",
  "Κελένδερις",
  "Τίβερις",
  "Χρυσαορὶς",
  "Νικατορίς",
  "Ἄορις",
  "ἁλμυρίς",
  "πορφυρίς",
  "ἀργυρίς",
  "Ἰλλυρὶς",
  "Φιλυρὶς",
  "Θάμυρις",
  "Ὤγυρις",
  "Κάσυρις",
  "Τίβυρις",
  "πανήγυρις"
];

// --- Greek helpers (toy-level) ---
const combining = {
  acute: "\u0301",
  grave: "\u0300",
  circumflex: "\u0342",
  diaeresis: "\u0308",
  smooth: "\u0313",
  rough: "\u0314",
  iotaSub: "\u0345"
};

const VOWELS = new Set(["α","ε","η","ι","ο","υ","ω","ά","έ","ή","ί","ό","ύ","ώ","ϊ","ϋ","ΐ","ΰ"]);

function normalizeNFD(s){ return (s||"").normalize("NFD"); }
function normalizeNFC(s){ return (s||"").normalize("NFC"); }

function stripAccentsKeepDiaeresis(s){
  // Remove accent marks but keep diaeresis (helps syllable splitting sometimes)
  const n = normalizeNFD(s);
  const out = [];
  for (const ch of n) {
    const code = ch.codePointAt(0);
    // remove tonos/oxia, varia, perispomeni, macron/breve if present
    if (ch === combining.acute || ch === combining.grave || ch === combining.circumflex) continue;
    // keep diaeresis, breathings, iota subscript
    out.push(ch);
  }
  return normalizeNFC(out.join(""));
}

function lowerGreek(s){
  return s.toLowerCase();
}

function detectEnding(base){
  const w = lowerGreek(base);
  if (w.endsWith("ερις")) return "-ερις";
  if (w.endsWith("ορις")) return "-ορις";
  if (w.endsWith("υρις")) return "-υρις";
  if (w.endsWith("γυρις")) return "-γυρις";
  if (w.endsWith("ρις")) return "-ρις";
  return "(other)";
}

function syllableCountRough(base){
  // Count vowel groups; treat common diphthongs as one group unless diaeresis splits.
  const s = normalizeNFD(lowerGreek(stripAccentsKeepDiaeresis(base)));
  // Build a simplified stream of letters with diaeresis markers attached
  const letters = [];
  let cur = "";
  for (const ch of s) {
    if (ch === combining.diaeresis) {
      cur += "¨"; // marker
      continue;
    }
    // skip other combining marks
    if (ch >= "\u0300" && ch <= "\u036f") continue;
    if (cur) { letters.push(cur); cur = ""; }
    letters.push(ch);
  }
  if (cur) letters.push(cur);

  const isV = (x) => {
    const c = x.replace("¨", "");
    return VOWELS.has(c);
  };
  const hasDia = (x) => x.includes("¨");

  const diph = new Set(["αι","ει","οι","υι","αυ","ευ","ου","ηυ","ωυ"]);

  let i = 0, count = 0;
  while (i < letters.length) {
    const a = letters[i];
    if (!isV(a)) { i++; continue; }

    // try diphthong with next vowel if neither has diaeresis
    const b = letters[i+1];
    if (b && isV(b) && !hasDia(a) && !hasDia(b)) {
      const pair = a.replace("¨","") + b.replace("¨","");
      if (diph.has(pair)) {
        count++; i += 2; continue;
      }
    }
    count++; i++;
  }
  return count;
}

function findLastVowelIndexNFD(nfd){
  // Return index in code units of last vowel letter (not combining)
  for (let i = nfd.length - 1; i >= 0; i--) {
    const ch = nfd[i];
    if (ch >= "\u0300" && ch <= "\u036f") continue;
    const low = ch.toLowerCase();
    if (VOWELS.has(low)) return i;
  }
  return -1;
}

function findNthVowelFromEndIndexNFD(nfd, n){
  // n=1 => last vowel, n=2 => penult vowel, etc.
  let seen = 0;
  for (let i = nfd.length - 1; i >= 0; i--) {
    const ch = nfd[i];
    if (ch >= "\u0300" && ch <= "\u036f") continue;
    const low = ch.toLowerCase();
    if (VOWELS.has(low)) {
      seen++;
      if (seen === n) return i;
    }
  }
  return -1;
}

function addAcuteOnVowel(base, whichFromEnd){
  // Strip accents, then add acute combining mark after the target vowel letter.
  const stripped = stripAccentsKeepDiaeresis(base);
  const nfd = normalizeNFD(stripped);
  const idx = findNthVowelFromEndIndexNFD(nfd, whichFromEnd);
  if (idx < 0) return stripped;
  const before = nfd.slice(0, idx+1);
  const after = nfd.slice(idx+1);
  const out = before + combining.acute + after;
  return normalizeNFC(out);
}

function ruleSuggest(word, gender){
  const base = stripAccentsKeepDiaeresis(word).trim();
  if (!base) return { ending:"—", syll:"—", rule:"Type a word.", out:"—", explain:"" };

  const ending = detectEnding(base);
  const syl = syllableCountRough(base);

  // Exceptions mentioned in passage (toy list)
  const exceptionsBarytone = new Set(["παστερις","κελενδερις","τιβερις"]);
  const exceptionsProparox = new Set(["θαμυρις"]);

  const low = lowerGreek(stripAccentsKeepDiaeresis(base));

  let rule = "";
  let out = base;
  let explain = "";

  const overTwo = syl > 2;

  if (exceptionsProparox.has(low)) {
    rule = "Exception in the passage: Θάμυρις is proparoxytone (acute on antepenult).";
    out = addAcuteOnVowel(base, 3);
    explain = "Placed an acute on the 3rd vowel from the end (antepenult).";
    return { ending, syll: String(syl), rule, out, explain };
  }

  if (exceptionsBarytone.has(low)) {
    rule = "Named exception: Πάστερις / Κελένδερις / Τίβερις are said to be ‘barytone’ (not oxytone).";
    // Toy choice: put acute on penult (common-looking barytone), not a real guarantee.
    out = addAcuteOnVowel(base, 2);
    explain = "Toy barytone: moved the accent off the last syllable onto the penult.";
    return { ending, syll: String(syl), rule, out, explain };
  }

  if ((ending === "-ερις" || ending === "-ορις") && overTwo) {
    if (gender === "m") {
      rule = "Herodian: masculine -ορις are barytone (toy: accent on penult).";
      out = addAcuteOnVowel(base, 2);
      explain = "Assuming masculine, the toy avoids final accent and uses penult.";
    } else {
      rule = "Herodian: feminine -ερις / -ορις with more than two syllables are oxytone (acute on the last).";
      out = addAcuteOnVowel(base, 1);
      explain = "Placed an acute on the last vowel (final syllable).";
    }
    return { ending, syll: String(syl), rule, out, explain };
  }

  if (ending === "-υρις" && overTwo) {
    rule = "Herodian: -υρις (not from ‘change’) tends to be oxytone (acute on the last).";
    out = addAcuteOnVowel(base, 1);
    explain = "Placed an acute on the last vowel (final syllable).";
    return { ending, syll: String(syl), rule, out, explain };
  }

  // Fallback
  rule = "No specific match from this passage (or not &gt;2 syllables). Toy default: keep as typed (but stripped of accents).";
  out = base;
  explain = "Removed existing accents (if any) but did not add a new one.";
  return { ending, syll: String(syl), rule, out, explain };
}

function render(){
  const w = $("#inp").value;
  const g = $("#gender").value;
  const r = ruleSuggest(w, g);
  $("#ending").textContent = r.ending;
  $("#syll").textContent = r.syll;
  $("#rule").textContent = r.rule;
  $("#accented").textContent = r.out;
  $("#explain").textContent = r.explain;
}

function initChips(){
  const box = $("#chips");
  for (const w of examples) {
    const b = document.createElement("button");
    b.type = "button";
    b.className = "chip";
    b.textContent = w;
    b.addEventListener("click", () => {
      $("#inp").value = w;
      // crude gender guess: treat Ἄορις as masculine example
      const low = lowerGreek(stripAccentsKeepDiaeresis(w));
      if (low === "αορις") $("#gender").value = "m";
      else $("#gender").value = "f";
      render();
      $("#inp").focus();
    });
    box.appendChild(b);
  }
}

$("#btn").addEventListener("click", render);
$("#inp").addEventListener("keydown", (e) => {
  if (e.key === "Enter") render();
});
$("#gender").addEventListener("change", render);
$("#clear").addEventListener("click", () => {
  $("#inp").value = "";
  $("#ending").textContent = "—";
  $("#syll").textContent = "—";
  $("#rule").textContent = "—";
  $("#accented").textContent = "—";
  $("#explain").textContent = "—";
  $("#inp").focus();
});

initChips();
render();

