                 var(--bg);
}

passages.gadget_js:
const $ = (sel) => document.querySelector(sel);

const examples = [
  {w:"Φαληρις", note:"penult η → oxytone"},
  {w:"Ιβηρις", note:"penult η → oxytone"},
  {w:"Καφηρις", note:"penult η → oxytone"},
  {w:"Κασωρις", note:"penult ω → oxytone"},
  {w:"θεωρις", note:"penult ω → oxytone"},
  {w:"Καβειρις", note:"penult ει → oxytone"},
  {w:"Επιδαυρις", note:"penult αυ → oxytone"},
  {w:"Βαναυρις", note:"penult αυ → oxytone"},
  {w:"Βουσιρις", note:"Egyptian → proparoxytone"},
  {w:"Ταφοσιρις", note:"Egyptian → proparoxytone"},
  {w:"Ταποσειρις", note:"exception (grave in text)"},
  {w:"Αμαστρις", note:"exception (grave in text)"},
  {w:"Νωνακρις", note:"exception (grave in text)"},
  {w:"Λιηβρις", note:"exception (grave in text)"},
  {w:"λαμπουρις", note:"exception list (oxytone rule has 3 noted)"},
  {w:"Τομουρις", note:"exception list"},
  {w:"ιππουρις", note:"exception list"}
];

// --- Polytonic helpers ---
const COMBINING = {
  acute: "\u0301",
  grave: "\u0300",
  circumflex: "\u0342",
  diaeresis: "\u0308",
  smooth: "\u0313",
  rough: "\u0314",
  iotaSub: "\u0345"
};

const VOWELS = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);

function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripDiacriticsKeepDiaeresis(s){
  // remove most combining marks, keep diaeresis (helps distinguish e.g. αϊ)
  const d = nfd(s);
  let out = "";
  for (const ch of d){
    const code = ch.codePointAt(0);
    if (code >= 0x300 && code <= 0x36F){
      if (ch === COMBINING.diaeresis) out += ch;
      // else drop
    } else out += ch;
  }
  return nfc(out);
}

function stripAllCombining(s){
  return nfc(nfd(s).replace(/[\u0300-\u036f]/g, ""));
}

function lowerGreek(s){
  // basic lowercasing; Greek sigma final handled by toLowerCase reasonably
  return s.toLowerCase();
}

function endsWithRis(base){
  const b = lowerGreek(base);
  return b.endsWith("ρις");
}

function isVowel(ch){ return VOWELS.has(ch); }

function syllableNucleiIndices(word){
  // crude: count vowel groups (including common diphthongs) as nuclei.
  // returns array of objects {start,end, nucleusString}
  const w = lowerGreek(stripDiacriticsKeepDiaeresis(word));
  const chars = Array.from(w);

  const diph = new Set(["αι","ει","οι","υι","αυ","ευ","ου","ηυ","ωυ"]);

  let nuclei = [];
  let i = 0;
  while (i < chars.length){
    const c = chars[i];
    if (!isVowel(c)) { i++; continue; }

    // try diphthong
    const c2 = (i+1 < chars.length) ? chars[i+1] : "";
    const pair = c + c2;
    if (c2 && isVowel(c2) && diph.has(pair)){
      nuclei.push({start:i, end:i+2, nucleus:pair});
      i += 2;
      continue;
    }

    // single vowel nucleus
    nuclei.push({start:i, end:i+1, nucleus:c});
    i += 1;
  }
  return nuclei;
}

function penultNucleus(word){
  const nuclei = syllableNucleiIndices(word);
  if (nuclei.length < 2) return null;
  return nuclei[nuclei.length - 2];
}

function accentOnSyllable(word, which, accentType="acute"){
  // which: "ultima" | "penult" | "antepenult"
  // accentType: "acute" | "grave" | "circumflex" (we mainly use acute)
  const nuclei = syllableNucleiIndices(word);
  if (nuclei.length === 0) return word;

  let idx;
  if (which === "ultima") idx = nuclei.length - 1;
  else if (which === "penult") idx = nuclei.length - 2;
  else idx = nuclei.length - 3;

  if (idx < 0) idx = 0;

  // remove existing accents (acute/grave/circumflex) but keep breathings etc.
  // easiest: strip all combining then re-add only one accent; but we'd lose breathings.
  // Instead: NFD, remove accent marks only.
  let d = nfd(word);
  // remove accent marks
  d = d.replace(/[\u0300\u0301\u0342]/g, "");

  // find the nucleus position in the de-accented string by mapping indices.
  // We'll operate on stripped-all-combining base to align with nuclei indices.
  const base = Array.from(lowerGreek(stripAllCombining(word)));
  const target = nuclei[idx];

  // We need to locate the corresponding vowel character in the NFD string.
  // Strategy: walk through NFD string, counting base letters (non-combining).
  const nfdChars = Array.from(d);
  let basePos = -1;
  let insertAt = -1;

  for (let i=0;i<nfdChars.length;i++){
    const ch = nfdChars[i];
    const code = ch.codePointAt(0);
    const isComb = (code >= 0x300 && code <= 0x36F);
    if (!isComb){
      basePos++;
      if (basePos === target.start){
        // insert accent after this base vowel letter and after any existing combining marks that should precede accent?
        // In Greek, accent usually comes after breathings; so insert after any combining marks immediately following the vowel that are breathings/diaeresis/iota-sub.
        insertAt = i+1;
        // advance over combining marks that are not accents (we removed accents already)
        while (insertAt < nfdChars.length){
          const c2 = nfdChars[insertAt];
          const code2 = c2.codePointAt(0);
          const isComb2 = (code2 >= 0x300 && code2 <= 0x36F);
          if (!isComb2) break;
          insertAt++;
        }
        break;
      }
    }
  }

  if (insertAt === -1) return word;

  const mark = COMBINING[accentType] || COMBINING.acute;
  nfdChars.splice(insertAt, 0, mark);
  return nfc(nfdChars.join(""));
}

// --- Rule engine (toy) ---
const EXCEPTIONS_GRAVE = new Map([
  ["ταποσειρις", "Named exception in the passage: Ταπόσειρις is said to be βαρυνεται (not oxytone)."],
  ["αμαστρις", "Named exception: Ἄμαστρις βαρυνεται."],
  ["νωνακρις", "Named exception: Νώνακρις βαρυνεται."],
  ["λιηβρις", "Named exception: Λίηβρις βαρυνεται."],
]);

const EXCEPTIONS_U_DIPH = new Set(["λαμπουρις","τομουρις","ιππουρις"]);

const EGYPTIAN_HINTS = new Set([
  "βουσιρις","βουσοσιρις","ταφοσιρις","καλασιρις","ψενυρις","τεντυρις"
]);

function hasPenultEtaOmegaEi(word){
  const p = penultNucleus(word);
  if (!p) return false;
  const nuc = p.nucleus;
  return nuc === "η" || nuc === "ω" || nuc === "ει";
}

function hasPenultUDiph(word){
  const p = penultNucleus(word);
  if (!p) return false;
  const nuc = p.nucleus;
  return nuc.includes("υ") && (nuc.length === 2); // diphthong with upsilon
}

function guessCategory(word){
  const raw = word.trim();
  const baseLower = lowerGreek(stripAllCombining(raw));
  const nuclei = syllableNucleiIndices(raw);

  let dbg = [];
  dbg.push(`Input (raw): ${raw}`);
  dbg.push(`Base (no combining): ${baseLower}`);
  dbg.push(`Ends with -ρις? ${endsWithRis(baseLower)}`);
  dbg.push(`Syllable nuclei (toy): ${nuclei.map(n=>n.nucleus).join(" · ") || "(none)"}`);

  if (!raw) return {ok:false, msg:"Type a word first.", dbg: dbg.join("\n")};
  if (!endsWithRis(baseLower)){
    return {ok:false, msg:"This toy only plays with words ending in -ρις.", dbg: dbg.join("\n")};
  }

  // Egyptian hint list → proparoxytone
  if (EGYPTIAN_HINTS.has(baseLower)){
    dbg.push("Matched Egyptian hint list → proparoxytone.");
    return {ok:true, accent:"antepenult", accentType:"acute", rule:"Egyptian -ρις → proparoxytone (accent on antepenult).", dbg: dbg.join("\n")};
  }

  // Named grave exceptions
  if (EXCEPTIONS_GRAVE.has(baseLower)){
    dbg.push("Matched named βαρυνεται exception.");
    return {ok:true, accent:"penult", accentType:"grave", rule:`Exception: ${EXCEPTIONS_GRAVE.get(baseLower)} (toy shows a grave on the penult).`, dbg: dbg.join("\n")};
  }

  // Penult η/ω/ει and polysyllabic → oxytone
  if (nuclei.length >= 3 && hasPenultEtaOmegaEi(raw)){
    dbg.push("Penult nucleus is η/ω/ει and word is polysyllabic → oxytone.");
    return {ok:true, accent:"ultima", accentType:"acute", rule:"Polysyllabic -ρις with penult η/ω/ει → oxytone (acute on ultima).", dbg: dbg.join("\n")};
  }

  // Penult diphthong with υ and >2 syllables → oxytone, with 3 exceptions
  if (nuclei.length >= 3 && hasPenultUDiph(raw)){
    if (EXCEPTIONS_U_DIPH.has(baseLower)){
      dbg.push("Penult has υ-diphthong but matched one of the 3 noted exceptions.");
      return {ok:true, accent:"penult", accentType:"grave", rule:"Noted exception among υ-diphthong penults (λάμπουρις/Τόμουρις/ἵππουρις). Toy marks it non-oxytone.", dbg: dbg.join("\n")};
    }
    dbg.push("Penult has υ-diphthong and word is >2 syllables → oxytone.");
    return {ok:true, accent:"ultima", accentType:"acute", rule:"-ρις with penult diphthong containing υ (and >2 syllables) → oxytone.", dbg: dbg.join("\n")};
  }

  // Fallback: if 3+ syllables, default to oxytone (Herodian’s section is about oxytone tendencies)
  if (nuclei.length >= 3){
    dbg.push("No specific trigger matched; fallback for polysyllabic -ρις → oxytone.");
    return {ok:true, accent:"ultima", accentType:"acute", rule:"Fallback: many polysyllabic -ρις in this section are oxytone; toy defaults to oxytone.", dbg: dbg.join("\n")};
  }

  // If only 2 syllables, just accent penult (common Greek default), as a toy choice
  dbg.push("Bisyllable: toy defaults to paroxytone (acute on penult). (Not from this passage.)");
  return {ok:true, accent:"penult", accentType:"acute", rule:"Bisyllable fallback: paroxytone (acute on penult).", dbg: dbg.join("\n")};
}

function run(){
  const input = $("#w").value;
  const g = guessCategory(input);
  if (!g.ok){
    $("#result").textContent = "—";
    $("#rule").textContent = g.msg;
    $("#debug").textContent = g.dbg;
    return;
  }
  const out = accentOnSyllable(input, g.accent, g.accentType);
  $("#result").textContent = out;
  $("#rule").textContent = g.rule;
  $("#debug").textContent = g.dbg + `\nAccent placed: ${g.accent} (${g.accentType})`;
}

function buildChips(){
  const box = $("#chips");
  box.innerHTML = "";
  for (const ex of examples){
    const b = document.createElement("button");
    b.type = "button";
    b.className = "chip";
    b.textContent = ex.w;
    b.title = ex.note;
    b.addEventListener("click", () => {
      $("#w").value = ex.w;
      run();
      $("#w").focus();
    });
    box.appendChild(b);
  }
}

$("#go").addEventListener("click", run);
$("#clear").addEventListener("click", () => {
  $("#w").value = "";
  $("#result").textContent = "—";
  $("#rule").textContent = "—";
  $("#debug").textContent = "";
  $("#w").focus();
});
$("#w").addEventListener("keydown", (e) => {
  if (e.key === "Enter") run();
});

buildChips();
// run once if prefilled by browser
if ($("#w").value.trim()) run();

