(() => {
  const $ = (sel, el=document) => el.querySelector(sel);
  const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

  const inp = $('#inp');
  const normEl = $('#norm');
  const outEl = $('#accented');
  const explainEl = $('#explain');

  const btnAccent = $('#btnAccent');
  const btnStrip = $('#btnStrip');
  const btnRandom = $('#btnRandom');

  // Examples drawn from the passage (not exhaustive)
  const examples = [
    {w:'ποιησις', mode:'bary', note:'from future ποιήσω → ποίησις (barytone)'} ,
    {w:'λυσις', mode:'bary', note:'from future λύσω → λύσις (barytone)'} ,
    {w:'κρισις', mode:'bary', note:'from κέκρισαι → κρίσις (barytone)'} ,
    {w:'στασις', mode:'bary', note:'στάσις (barytone in Herodian’s list)'} ,
    {w:'ανυσις', mode:'bary', note:'ἄνυσις (also a city name)'} ,
    {w:'χρυσις', mode:'oxy', note:'paronym: Χρύσης → Χρυσίς (oxytone)'} ,
    {w:'νησις', mode:'oxy', note:'paronym: νῆσος → νησίς (oxytone)'} ,
    {w:'κρουσις', mode:'auto', note:'Κροῦσις / Κρουσίς both appear (toy can try both)'} ,
    {w:'κρησις', mode:'oxy', note:'Κρησίς (from Κρητός with τ→σ)'} ,
    {w:'παρνασσις', mode:'bary', note:'proper name in -σις often barytone (rule-of-thumb)'}
  ];

  function stripDiacritics(s){
    // Remove combining marks; also normalize Greek tonos/oxia variants.
    return (s || '')
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g,'')
      .normalize('NFC');
  }

  function tokenizePhrase(s){
    // Keep Greek-ish words; split on whitespace.
    return (s || '').trim().split(/\s+/).filter(Boolean);
  }

  function isGreekLetter(ch){
    const code = ch.codePointAt(0);
    return (
      (code >= 0x0370 && code <= 0x03FF) ||
      (code >= 0x1F00 && code <= 0x1FFF)
    );
  }

  function lastIndexOfGreekVowel(word){
    const w = stripDiacritics(word).toLowerCase();
    const vowels = new Set(['α','ε','η','ι','ο','υ','ω']);
    for(let i=w.length-1;i>=0;i--){
      const ch = w[i];
      if(vowels.has(ch)) return i;
    }
    return -1;
  }

  function penultVowelIndex(word){
    const w = stripDiacritics(word).toLowerCase();
    const vowels = new Set(['α','ε','η','ι','ο','υ','ω']);
    let seen = 0;
    for(let i=w.length-1;i>=0;i--){
      if(vowels.has(w[i])){
        seen++;
        if(seen===2) return i;
      }
    }
    return -1;
  }

  function addAcuteOnVowel(word, vowelIndex){
    // Add acute to the vowel at vowelIndex (in NFC output).
    // Works by converting that character to NFD and adding \u0301.
    if(vowelIndex < 0) return word;
    const chars = Array.from(word);
    if(vowelIndex >= chars.length) return word;

    // Find the corresponding index in Array.from(stripDiacritics(word))
    // We operate on stripped base to align indices.
    const base = Array.from(stripDiacritics(word));
    const orig = Array.from(word);

    // Map base indices to orig indices by scanning and counting Greek letters.
    // Simpler: rebuild from base, then reapply accent on base and return.
    // (We intentionally discard original accents for this toy.)
    const baseChars = base;
    const target = baseChars[vowelIndex];
    if(!target) return baseChars.join('');

    const accented = target.normalize('NFD') + '\u0301';
    baseChars[vowelIndex] = accented.normalize('NFC');
    return baseChars.join('').normalize('NFC');
  }

  function accentSisWord(word, mode){
    const w0 = stripDiacritics(word);
    const lower = w0.toLowerCase();

    // Only handle words ending in -σις (case-insensitive)
    if(!lower.endsWith('σις')) return {out: w0, ok:false, why:'Not an -σις word (toy only accents -σις).'};

    if(mode === 'bary'){
      const idx = penultVowelIndex(w0);
      const out = addAcuteOnVowel(w0, idx);
      return {out, ok:true, why:'Barytone: accent on the penult (…́σις).'};
    }
    if(mode === 'oxy'){
      const idx = lastIndexOfGreekVowel(w0);
      const out = addAcuteOnVowel(w0, idx);
      return {out, ok:true, why:'Oxytone: accent on the ultima (…σίς).'};
    }

    // auto
    const guess = guessMode(w0);
    return accentSisWord(w0, guess);
  }

  function guessMode(word){
    const w = stripDiacritics(word).toLowerCase();

    // If it matches our mini lexicon, use that.
    const hit = examples.find(e => stripDiacritics(e.w).toLowerCase() === w && e.mode !== 'auto');
    if(hit) return hit.mode;

    // Crude heuristic:
    // - If it ends in -ησις/-ωσις/-υσις/-ασις/-εσις, often verbal abstracts → bary.
    // - If it looks like a paronym with -ις from a noun/adjective base (very rough):
    //   if it contains -νῆσ-? can't; so just: if it ends in -ισις? no.
    // We'll bias bary unless it starts with a capitalized proper name? Actually proper names in -σις are bary per passage.
    // So: default bary; but if the base (word without -σις) ends with -η/-ος/-ης, lean oxy (paronym-ish).

    const stem = w.slice(0, -3);
    if(/(η|ω|υ|α|ε)σ$/.test(stem)) return 'bary';

    if(/(ος|ης|η|α|ον)$/.test(stem)) return 'oxy';

    return 'bary';
  }

  function accentPhrase(text, mode){
    const words = tokenizePhrase(text);
    if(words.length === 0) return {accented:'', normalized:'', notes:['Type a Greek word or short phrase.']};

    const normalizedWords = words.map(w => stripDiacritics(w));
    const notes = [];

    const accentedWords = normalizedWords.map((w) => {
      const res = accentSisWord(w, mode);
      if(!res.ok){
        // Keep as-is; add note only if it contains Greek letters.
        if(Array.from(w).some(isGreekLetter)) notes.push(`“${w}”: ${res.why}`);
        return res.out;
      }
      return res.out;
    });

    return {
      accented: accentedWords.join(' '),
      normalized: normalizedWords.join(' '),
      notes
    };
  }

  function currentMode(){
    const r = $('input[name="mode"]:checked');
    return r ? r.value : 'auto';
  }

  function render(){
    const text = inp.value;
    const mode = currentMode();
    const res = accentPhrase(text, mode);

    normEl.textContent = res.normalized || '—';
    outEl.textContent = res.accented || '—';

    const modeLabel = mode === 'auto' ? 'Auto' : (mode === 'bary' ? 'Barytone' : 'Oxytone');
    const badge = ` <span class="badge">${modeLabel}</span>`;

    if(!text.trim()){
      explainEl.innerHTML = 'Type something ending in -σις to see the toy’s accent placement.' + badge;
      return;
    }

    const hasSis = tokenizePhrase(stripDiacritics(text)).some(w => w.toLowerCase().endsWith('σις'));
    if(!hasSis){
      explainEl.innerHTML = `<span class="warn">No -σις ending found.</span> Try e.g. <span class="mono">λυσις</span>, <span class="mono">ποιησις</span>, <span class="mono">χρυσις</span>.` + badge;
      return;
    }

    if(res.notes.length){
      explainEl.innerHTML = res.notes.map(n => `<span class="mono">${escapeHtml(n)}</span>`).join('<br>') + badge;
    } else {
      // Give a short explanation of what was applied.
      const applied = (mode === 'auto') ? `Auto guessed <span class="mono">${guessMode(stripDiacritics(tokenizePhrase(text)[0]||''))}</span> for the first -σις word.` :
                      (mode === 'bary') ? 'Placed an acute on the penult (barytone).'
                      : 'Placed an acute on the ultima (oxytone).';
      explainEl.innerHTML = applied + badge;
    }
  }

  function escapeHtml(s){
    return String(s)
      .replaceAll('&','&amp;')
      .replaceAll('<','&lt;')
      .replaceAll('>','&gt;')
      .replaceAll('"','&quot;')
      .replaceAll("'",'&#39;');
  }

  function buildChips(){
    const box = $('#chips');
    box.innerHTML = '';
    examples.forEach((e) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'chip mono';
      b.textContent = e.w;
      b.title = e.note;
      b.addEventListener('click', () => {
        inp.value = e.w;
        // If example has a specific mode, switch to it (unless auto)
        if(e.mode === 'bary' || e.mode === 'oxy'){
          const radio = $(`input[name="mode"][value="${e.mode}"]`);
          if(radio) radio.checked = true;
        } else {
          const radio = $(`input[name="mode"][value="auto"]`);
          if(radio) radio.checked = true;
        }
        render();
        inp.focus();
      });
      box.appendChild(b);
    });
  }

  btnAccent.addEventListener('click', render);
  btnStrip.addEventListener('click', () => {
    inp.value = stripDiacritics(inp.value);
    render();
    inp.focus();
  });
  btnRandom.addEventListener('click', () => {
    const e = examples[Math.floor(Math.random()*examples.length)];
    inp.value = e.w;
    const m = (e.mode === 'bary' || e.mode === 'oxy') ? e.mode : 'auto';
    const radio = $(`input[name="mode"][value="${m}"]`);
    if(radio) radio.checked = true;
    render();
    inp.focus();
  });

  inp.addEventListener('input', () => {
    // live update, but keep it light
    render();
  });
  $$('input[name="mode"]').forEach(r => r.addEventListener('change', render));

  buildChips();
  render();
})();

