(() => {
  const $ = (id) => document.getElementById(id);
  const w = $('w');
  const kind = $('kind');
  const fromHs = $('fromHs');
  const normEl = $('norm');
  const accEl = $('accented');
  const ruleEl = $('rule');
  const syllEl = $('syll');
  const penultEl = $('penult');

  const examples = [
    'φορτις','νοτις','κοιτις','Προιτις','φροντις','Θετις','Βαιτις','Ητις',
    'Βοιωτις','Θεσπρωτις','Ειλωτις','Ενετις','Ελλωτις','Ρακωτις','Λιμενωτις',
    'Καλλατις','Ναυκρατις','Συρτις','Ξυστις','Βερυτις','Αφυτις','ρυτις','κυρτις','Αψυρτις'
  ];

  // --- Greek-ish normalization helpers ---
  const stripDiacritics = (s) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const normalizeSigma = (s) => s.replace(/ς/g, 'σ');
  const toLowerGreekish = (s) => s.toLowerCase();

  function normalizeWord(raw){
    let s = (raw || '').trim();
    if(!s) return '';
    s = s.replace(/^[«"'“”‘’\(\)\[\]·.,;:!?]+|[«"'“”‘’\(\)\[\]·.,;:!?]+$/g,'');
    s = s.replace(/\s+/g,'');
    // accept final sigma or not
    s = toLowerGreekish(s);
    s = stripDiacritics(s);
    // if ends with σ, show as ς for display
    return s;
  }

  function displayFinalSigma(s){
    if(!s) return s;
    // replace final σ with ς
    return s.replace(/σ$/,'ς');
  }

  // --- Syllable estimation ---
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω']);
  const diphthongs = new Set(['αι','ει','οι','αυ','ευ','ου','ηυ','υι']);

  function splitIntoVowelGroups(s){
    // returns array of {start,end,text} for vowel nuclei
    const groups = [];
    let i = 0;
    while(i < s.length){
      const ch = s[i];
      if(vowels.has(ch)){
        let start = i;
        // try diphthong
        if(i+1 < s.length){
          const two = s.slice(i,i+2);
          if(diphthongs.has(two)){
            groups.push({start, end:i+2, text:two});
            i += 2;
            continue;
          }
        }
        groups.push({start, end:i+1, text:ch});
        i += 1;
      } else {
        i += 1;
      }
    }
    return groups;
  }

  function syllableCount(s){
    return splitIntoVowelGroups(s).length;
  }

  function penultVowelGroup(s){
    const g = splitIntoVowelGroups(s);
    if(g.length < 2) return null;
    return g[g.length-2];
  }

  // --- Accent placement (toy) ---
  const ACUTE = '\u0301';      // combining acute
  const CIRC = '\u0342';       // combining perispomeni (circumflex)

  function addAccentToVowelGroup(word, groupIndexFromEnd, mark){
    // groupIndexFromEnd: 1 = ultima, 2 = penult, 3 = antepenult
    const base = word;
    const groups = splitIntoVowelGroups(base);
    if(groups.length === 0) return base;
    const idx = groups.length - groupIndexFromEnd;
    if(idx < 0 || idx >= groups.length) return base;

    const g = groups[idx];
    // place mark on first vowel char of the nucleus
    const insertAt = g.start + 1; // after first vowel
    const out = base.slice(0, insertAt) + mark + base.slice(insertAt);
    return out.normalize('NFC');
  }

  function endsWithTis(s){
    // accept ...τις or ...τισ
    const t = normalizeSigma(s);
    return t.endsWith('τισ');
  }

  function hasVowelBeforeTis(s){
    const t = normalizeSigma(s);
    if(!t.endsWith('τισ')) return false;
    const stem = t.slice(0, -3); // remove τισ
    if(!stem) return false;
    const last = stem[stem.length-1];
    return vowels.has(last) || last === 'ω';
  }

  function penultIsEorHorAI(s){
    const t = normalizeSigma(s);
    const g = penultVowelGroup(t);
    if(!g) return false;
    return g.text === 'ε' || g.text === 'η' || g.text === 'αι';
  }

  function penultIsAorO(s){
    const t = normalizeSigma(s);
    const g = penultVowelGroup(t);
    if(!g) return false;
    return g.text === 'α' || g.text === 'ο';
  }

  function hasYBeforeTis(s){
    const t = normalizeSigma(s);
    if(!t.endsWith('τισ')) return false;
    const stem = t.slice(0, -3);
    return stem.endsWith('υ');
  }

  function guessAccent(raw){
    const base = normalizeWord(raw);
    const shownNorm = displayFinalSigma(base);

    if(!base){
      return {norm:'', accented:'', rule:'', syll:'', penult:''};
    }

    const t = normalizeSigma(base);
    const sylN = syllableCount(t);
    const groups = splitIntoVowelGroups(t);
    const pen = penultVowelGroup(t);
    const penTxt = pen ? pen.text : '—';

    let rule = '';
    let accented = shownNorm;

    if(!endsWithTis(t)){
      rule = 'Not recognized as a -τις word (toy only handles …τις).';
      return {
        norm: shownNorm,
        accented: shownNorm,
        rule,
        syll: sylN ? `${sylN} (vowel-groups)` : '—',
        penult: `penult nucleus: ${penTxt}`
      };
    }

    // Heuristic rules inspired by Herodian 1.103
    const k = kind.value;
    const from = fromHs.value;

    // 1) If marked as from -ης masculine and polysyllabic feminine: circumflex on penult
    if(from === 'yes' && sylN >= 3){
      accented = addAccentToVowelGroup(t, 2, CIRC);
      accented = displayFinalSigma(accented);
      rule = 'Guess: circumflex on penult (toy: “as if from masc. in -ης”, cf. Ῥακῶτις, Λιμενῶτις).';
    }
    // 2) City/place-names polysyllabic with penult α/ο: barytone (accent not on ultima)
    else if(k === 'city' && sylN >= 3 && penultIsAorO(t)){
      // put acute on penult as a simple barytone stand-in
      accented = addAccentToVowelGroup(t, 2, ACUTE);
      accented = displayFinalSigma(accented);
      rule = 'Guess: barytone for polysyllabic city-name with penult α/ο (toy places an acute on the penult).';
    }
    // 3) Disyllabic proper names with penult ε/η/αι: barytone
    else if(k === 'proper' && sylN === 2 && penultIsEorHorAI(t)){
      accented = addAccentToVowelGroup(t, 2, ACUTE);
      accented = displayFinalSigma(accented);
      rule = 'Guess: barytone disyllabic proper name with penult ε/η/αι (toy: acute on penult; cf. Θέτις, Βαῖτις, Ἦτις).';
    }
    // 4) Polysyllabic feminines not from -ης: acute (toy: on ultima)
    else if(sylN >= 3 && k !== 'ethnic' && from === 'no'){
      accented = addAccentToVowelGroup(t, 1, ACUTE);
      accented = displayFinalSigma(accented);
      rule = 'Guess: acute on ultima for polysyllabic feminine not from -ης (cf. Βοιωτίς, Θεσπρωτίς, etc.).';
    }
    // 5) Words with υ before -τις: mixed; toy defaults to barytone for place/city, else acute
    else if(hasYBeforeTis(t)){
      if(k === 'city' || k === 'proper'){
        accented = addAccentToVowelGroup(t, 2, ACUTE);
        accented = displayFinalSigma(accented);
        rule = 'Guess: υ-before-τις, choose barytone-ish (toy: acute on penult; cf. Σύρτις, Ἄφυτις).';
      } else {
        accented = addAccentToVowelGroup(t, 1, ACUTE);
        accented = displayFinalSigma(accented);
        rule = 'Guess: υ-before-τις, choose oxytone (toy: acute on ultima; cf. ῥυτίς, κυρτίς).';
      }
    }
    // 6) Default: if vowel before -τις and not adjectival: oxytone
    else if(hasVowelBeforeTis(t) && k !== 'ethnic'){
      if(k === 'proper'){
        // Herodian: proper names may be barytone; toy chooses penult acute
        accented = addAccentToVowelGroup(t, 2, ACUTE);
        accented = displayFinalSigma(accented);
        rule = 'Guess: proper name → allow barytone (toy: acute on penult).';
      } else {
        accented = addAccentToVowelGroup(t, 1, ACUTE);
        accented = displayFinalSigma(accented);
        rule = 'Guess: non-adjectival -τις with vowel before -τις → oxytone (acute on ultima).';
      }
    }
    // 7) Ethnics/adjectival: toy tends to barytone
    else if(k === 'ethnic'){
      accented = addAccentToVowelGroup(t, 2, ACUTE);
      accented = displayFinalSigma(accented);
      rule = 'Guess: adjectival/ethnic → avoid oxytone (toy: acute on penult).';
    }
    else {
      accented = addAccentToVowelGroup(t, 1, ACUTE);
      accented = displayFinalSigma(accented);
      rule = 'Fallback: acute on ultima.';
    }

    // Syllable display
    const sylPieces = groups.map(g => g.text).join(' · ');

    return {
      norm: shownNorm,
      accented,
      rule,
      syll: `${sylN} (nuclei: ${sylPieces || '—'})`,
      penult: `penult nucleus: ${penTxt}`
    };
  }

  function render(){
    const r = guessAccent(w.value);
    normEl.textContent = r.norm || '—';
    accEl.textContent = r.accented || '—';
    ruleEl.textContent = r.rule || '—';
    syllEl.textContent = r.syll || '—';
    penultEl.textContent = r.penult || '—';
  }

  $('go').addEventListener('click', render);
  $('clear').addEventListener('click', () => { w.value=''; render(); w.focus(); });
  $('shuffle').addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    w.value = ex;
    // set a plausible kind for some examples
    const citySet = new Set(['καλλατις','ναυκρατις','ονειβατις','ιαγξουατις','αβοτις','κραμβοτις','ξυστις','βερυτις','αφυτις','καλυτις','κανυτις','ρακαωτις','ρακαωτις','ρακαωτις']);
    const properSet = new Set(['θετις','βαιτις','ητις','προιτις']);
    const low = normalizeWord(ex);
    if(properSet.has(low)) kind.value='proper';
    else if(citySet.has(low)) kind.value='city';
    else kind.value='common';
    fromHs.value = (low === 'ρακαωτις' || low === 'λιμενωτις') ? 'yes' : 'unknown';
    render();
    w.focus();
    w.setSelectionRange(w.value.length, w.value.length);
  });

  w.addEventListener('keydown', (e) => {
    if(e.key === 'Enter') render();
    if(e.key === 'Escape') { w.value=''; render(); }
  });
  kind.addEventListener('change', render);
  fromHs.addEventListener('change', render);

  // initial
  render();
})();

passages.gadget_css:
:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --card:#1c2036;
  --ink:#e9ecff;
  --muted:#b9c0ffcc;
  --line:#2a2f52;
  --accent:#7aa2ff;
  --good:#7dffb2;
  --warn:#ffd27a;
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, #1a1f3a 0%, var(--bg) 55%);color:var(--ink);font:15px/1.35 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif}
.wrap{max-width:980px;margin:0 auto;padding:18px 16px 28px}
.hdr{display:flex;gap:14px;align-items:flex-start;margin-bottom:14px}
h1{font-size:20px;margin:0 0 6px 0;letter-spacing:.2px}
.sub{margin:0;color:var(--muted)}
.panel{background:linear-gradient(180deg, rgba(255,255,255,.03), rgba(255,255,255,.01));border:1px solid var(--line);border-radius:14px;padding:14px}
.row{display:grid;grid-template-columns:140px 1fr auto auto;gap:10px;align-items:center}
.row.small{grid-template-columns:1fr}
.lbl{color:var(--muted);font-weight:600}
.inp{width:100%;padding:10px 12px;border-radius:10px;border:1px solid var(--line);background:#0c0f1c;color:var(--ink);font-size:16px;outline:none}
.inp:focus{border-color:rgba(122,162,255,.8);box-shadow:0 0 0 3px rgba(122,162,255,.15)}
.btn{padding:10px 12px;border-radius:10px;border:1px solid rgba(122,162,255,.55);background:rgba(122,162,255,.18);color:var(--ink);cursor:pointer;font-weight:650}
.btn:hover{background:rgba(122,162,255,.26)}
.btn.ghost{background:transparent;border-color:var(--line);color:var(--muted)}
.btn.ghost:hover{border-color:rgba(122,162,255,.55);color:var(--ink)}
.hint{color:var(--muted);padding:10px 12px;border:1px dashed var(--line);border-radius:12px;background:rgba(0,0,0,.12)}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}
@media (max-width:860px){.row{grid-template-columns:1fr;}.grid{grid-template-columns:1fr}}
.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:12px}
.card h3{margin:0 0 8px 0;font-size:14px;color:var(--muted);font-weight:750;letter-spacing:.3px;text-transform:uppercase}
.out{font-size:26px;font-weight:800;letter-spacing:.2px;margin:2px 0 6px 0}
.mini{color:var(--muted);font-size:13px}
.rule{padding:10px 10px;border-radius:12px;border:1px solid var(--line);background:rgba(0,0,0,.12);color:var(--ink)}
.details summary{cursor:pointer;color:var(--muted);margin-top:8px}
.details ul{margin:8px 0 0 18px;color:var(--muted)}
.row2{display:grid;gap:8px}
.chk{display:flex;gap:8px;align-items:center;color:var(--muted)}
.ex{cursor:pointer;color:var(--accent);text-decoration:underline;text-underline-offset:2px}
.quiz{display:grid;gap:10px}
.qword{font-size:22px;font-weight:850}
.qbtns{display:flex;gap:10px;flex-wrap:wrap}
.qans{min-height:22px;color:var(--muted)}
.ftr{margin-top:10px;color:var(--muted)}

