const $ = (sel, el=document) => el.querySelector(sel);
const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

// --- Greek helpers (very lightweight) ---
const combining = {
  acute: "\u0301",
  grave: "\u0300",
  circumflex: "\u0342",
  diaeresis: "\u0308",
  smooth: "\u0313",
  rough: "\u0314",
  iotaSub: "\u0345"
};

function nfd(s){ return (s||"").normalize('NFD'); }
function nfc(s){ return (s||"").normalize('NFC'); }

function stripDiacriticsKeepDiaeresis(s){
  // remove most combining marks; keep diaeresis because it affects syllabification
  const d = nfd(s);
  let out = "";
  for (const ch of d){
    const code = ch.codePointAt(0);
    if (code >= 0x300 && code <= 0x36F){
      if (ch === combining.diaeresis) out += ch;
      // else drop
    } else out += ch;
  }
  return nfc(out);
}

function hasAccent(s){
  const d = nfd(s);
  return d.includes(combining.acute) || d.includes(combining.grave) || d.includes(combining.circumflex);
}

function stripAllAccents(s){
  const d = nfd(s);
  let out = "";
  for (const ch of d){
    const code = ch.codePointAt(0);
    if (code >= 0x300 && code <= 0x36F){
      // drop all combining marks
    } else out += ch;
  }
  return nfc(out);
}

function lowerGreek(s){
  return (s||"").trim().toLowerCase();
}

const vowels = new Set(["α","ε","η","ι","ο","υ","ω","ά","έ","ή","ί","ό","ύ","ώ","ϊ","ϋ","ΐ","ΰ"]);

function isVowel(ch){
  return vowels.has(ch);
}

function splitSyllables(word){
  // Very rough syllabifier: groups from vowel to before next vowel.
  // Treat diaeresis as forcing vowel separation.
  const w = nfd(word);
  // Build grapheme-ish units: base letter + combining marks
  const units = [];
  let cur = "";
  for (const ch of w){
    const code = ch.codePointAt(0);
    if (code >= 0x300 && code <= 0x36F){
      cur += ch;
    } else {
      if (cur) units.push(cur);
      cur = ch;
    }
  }
  if (cur) units.push(cur);

  // Determine vowel units (base letter vowel)
  const base = u => u.normalize('NFD')[0];
  const hasDia = u => u.normalize('NFD').includes(combining.diaeresis);

  const sylls = [];
  let i = 0;
  while (i < units.length){
    // onset
    let onset = "";
    while (i < units.length && !isVowel(base(units[i]))){
      onset += units[i];
      i++;
    }
    if (i >= units.length){
      // trailing consonants attach to last syllable
      if (sylls.length) sylls[sylls.length-1] += onset;
      else sylls.push(onset);
      break;
    }
    // nucleus: one vowel unit
    let nucleus = units[i];
    i++;

    // If next unit is vowel and current has no diaeresis and next has no diaeresis,
    // we *may* treat as diphthong for common pairs.
    if (i < units.length && isVowel(base(units[i]))){
      const v1 = base(nucleus), v2 = base(units[i]);
      const dip = new Set(["αι","ει","οι","υι","αυ","ευ","ου","ηυ"]);
      const pair = v1 + v2;
      if (!hasDia(nucleus) && !hasDia(units[i]) && dip.has(pair)){
        nucleus += units[i];
        i++;
      }
    }

    // coda: take consonants until next vowel, but leave last consonant for onset if cluster rules? keep simple.
    let coda = "";
    while (i < units.length && !isVowel(base(units[i]))){
      // lookahead: if next after this consonant is vowel, keep this consonant as onset of next syllable
      if (i+1 < units.length && isVowel(base(units[i+1]))){
        break;
      }
      coda += units[i];
      i++;
    }

    sylls.push(nfc(onset + nucleus + coda));
  }
  return sylls.map(nfc);
}

function addAccentToSyllable(word, syllIndexFromEnd, accentType){
  // accentType: 'acute' or 'circumflex'
  const sylls = splitSyllables(word);
  if (!sylls.length) return {accented: word, sylls};
  const idx = Math.max(0, sylls.length - syllIndexFromEnd);
  const target = sylls[idx];

  // place accent on first vowel in target syllable
  const d = nfd(target);
  let out = "";
  let placed = false;
  for (let i=0;i<d.length;i++){
    const ch = d[i];
    const code = ch.codePointAt(0);
    if (code >= 0x300 && code <= 0x36F){
      out += ch;
      continue;
    }
    out += ch;
    if (!placed && isVowel(ch)){
      out += (accentType === 'circumflex' ? combining.circumflex : combining.acute);
      placed = true;
    }
  }
  sylls[idx] = nfc(out);
  return {accented: nfc(sylls.join("")), sylls};
}

// --- Heuristic rules inspired by Herodian 1.104 ---
const lexicon = new Map([
  // from passage examples (unaccented keys)
  ["κλεπτις", {pattern:"barytone", accent:"paroxytone", note:"Listed as barytone: κλέπτις"}],
  ["ικτις", {pattern:"barytone", accent:"paroxytone", note:"Listed as barytone: ἴκτις"}],
  ["λακτις", {pattern:"barytone", accent:"paroxytone", note:"Listed as barytone: λάκτις"}],
  ["φλυκτις", {pattern:"oxytone", accent:"oxytone", note:"Listed as oxytone: φλυκτίς"}],
  ["πηκτις", {pattern:"oxytone", accent:"oxytone", note:"Listed as oxytone: πηκτίς"}],

  ["αττις", {pattern:"barytone", accent:"paroxytone", note:"-ττις barytone example: Ἄττις"}],
  ["ζηβυττις", {pattern:"barytone", accent:"paroxytone", note:"-ττις barytone example: Ζήβυττις"}],
  ["αδραμυττις", {pattern:"barytone", accent:"paroxytone", note:"-ττις barytone example: Ἀδράμυττις"}],
  ["τριοττις", {pattern:"oxytone", accent:"oxytone", note:"-ττις oxytone example: τριοττίς"}],
  ["νεοττις", {pattern:"oxytone", accent:"oxytone", note:"-ττις oxytone example: νεοττίς"}],

  ["πιστις", {pattern:"barytone", accent:"paroxytone", note:"-στις disyllable barytone: πίστις"}],
  ["μνηστις", {pattern:"barytone", accent:"paroxytone", note:"-στις disyllable barytone: μνῆστις"}],
  ["θεστις", {pattern:"barytone", accent:"paroxytone", note:"-στις disyllable barytone: Θέστις"}],
  ["κιστις", {pattern:"oxytone", accent:"oxytone", note:"Diminutive-ish exception: κιστίς"}],

  ["αγρωστις", {pattern:"proparoxytone", accent:"proparoxytone", note:"-στις >2 syllables proparoxytone: ἄγρωστις"}],
  ["βουβρωστις", {pattern:"proparoxytone", accent:"proparoxytone", note:"-στις >2 syllables proparoxytone: βούβρωστις"}],
  ["αυγωστις", {pattern:"proparoxytone", accent:"proparoxytone", note:"-στις >2 syllables proparoxytone: Αὔγωστις"}],

  ["κεραστις", {pattern:"oxytone", accent:"oxytone", note:"Adjectival/exceptional oxytone: Κεραστίς"}],
  ["λιγυστις", {pattern:"oxytone", accent:"oxytone", note:"Adjectival oxytone: Λιγυστίς"}],
  ["λιβυστις", {pattern:"oxytone", accent:"oxytone", note:"Adjectival oxytone: Λιβυστίς"}],
  ["γεραιστις", {pattern:"oxytone", accent:"oxytone", note:"Adjectival oxytone: Γεραιστίς"}],
  ["ορεστις", {pattern:"oxytone", accent:"oxytone", note:"Adjectival oxytone: Ὀρεστίς"}],

  ["σαντις", {pattern:"barytone", accent:"paroxytone", note:"Disyllabic -ντις barytone: Σάντις"}],
  ["σιντις", {pattern:"barytone", accent:"paroxytone", note:"Disyllabic -ντις barytone: Σίντις"}],
  ["προποντις", {pattern:"oxytone", accent:"oxytone", note:"Polysyllabic -ντις oxytone: Προποντίς"}],
  ["ελλησποντις", {pattern:"oxytone", accent:"oxytone", note:"Polysyllabic -ντις oxytone: Ἑλλησποντίς"}],
  ["αβαντις", {pattern:"oxytone", accent:"oxytone", note:"Polysyllabic -ντις oxytone: Ἀβαντίς"}],
  ["υαντις", {pattern:"oxytone", accent:"oxytone", note:"Polysyllabic -ντις oxytone: Ὑαντίς"}],
  ["ακαμαντις", {pattern:"oxytone", accent:"oxytone", note:"Polysyllabic -ντις oxytone: Ἀκαμαντίς"}],
  ["αθαμαντις", {pattern:"oxytone", accent:"oxytone", note:"Polysyllabic -ντις oxytone: Ἀθαμαντίς"}],
]);

function endsWithAny(w, arr){
  return arr.find(suf => w.endsWith(suf)) || null;
}

function predict(wordRaw, opts){
  const original = wordRaw;
  const keepUser = opts.keepUser;
  const treatAdj = opts.treatAdj;

  const hasUserAcc = hasAccent(original);
  const baseForRules = lowerGreek(stripAllAccents(original));
  const baseNoDia = lowerGreek(stripDiacriticsKeepDiaeresis(baseForRules));

  // If user wants to keep their accent and they provided one, just analyze.
  if (keepUser && hasUserAcc){
    const sylls = splitSyllables(original);
    return {
      input: original,
      normalized: baseForRules,
      accented: original,
      sylls,
      rule: "Kept your accent (analysis only).",
      note: "(No overwrite)"
    };
  }

  // Lexicon override
  if (lexicon.has(baseNoDia)){
    const entry = lexicon.get(baseNoDia);
    const sylls = splitSyllables(baseNoDia);
    let accented = baseNoDia;
    if (entry.accent === "oxytone") accented = addAccentToSyllable(baseNoDia, 1, 'acute').accented;
    else if (entry.accent === "paroxytone") accented = addAccentToSyllable(baseNoDia, 2, 'acute').accented;
    else if (entry.accent === "proparoxytone") accented = addAccentToSyllable(baseNoDia, 3, 'acute').accented;

    return {
      input: original,
      normalized: baseNoDia,
      accented,
      sylls: splitSyllables(accented),
      rule: "Lexicon match: " + entry.note,
      note: "(Example-based)"
    };
  }

  // Heuristic by ending
  const sylls0 = splitSyllables(baseNoDia);
  const sylCount = sylls0.length;

  const suf = endsWithAny(baseNoDia, ["ττις","στις","τις"]);
  if (!suf){
    // default: accent penult if possible
    const accented = addAccentToSyllable(baseNoDia, Math.min(2, sylCount), 'acute').accented;
    return {
      input: original,
      normalized: baseNoDia,
      accented,
      sylls: splitSyllables(accented),
      rule: "No target ending detected (τις/στις/ττις). Defaulted to a simple penult accent.",
      note: "(Fallback)"
    };
  }

  // Special: -ντις
  const hasNBeforeT = baseNoDia.endsWith("ντις");

  let targetFromEnd = 2; // paroxytone default
  let rule = "";

  if (suf === "ττις"){
    // passage says mixed; guess paroxytone unless looks like neo-/trio- (toy)
    if (baseNoDia.startsWith("νεο") || baseNoDia.startsWith("τριο")){
      targetFromEnd = 1;
      rule = "-ττις: guessed oxytone for neo-/trio- style forms (cf. νεοττίς, τριοττίς).";
    } else {
      targetFromEnd = 2;
      rule = "-ττις: guessed barytone (paroxytone) as a common pattern (cf. Ἄττις, Ζήβυττις).";
    }
  } else if (suf === "στις"){
    if (sylCount <= 2){
      // disyllables barytone unless diminutive-ish
      if (baseNoDia.endsWith("ιστις") && baseNoDia.length <= 6){
        targetFromEnd = 1;
        rule = "-στις disyllable: guessed diminutive-ish → oxytone (cf. κιστίς).";
      } else {
        targetFromEnd = 2;
        rule = "-στις disyllable: guessed barytone (paroxytone) (cf. πίστις, μνῆστις).";
      }
    } else {
      // >2 syllables: proparoxytone unless adjectival
      if (treatAdj){
        targetFromEnd = 1;
        rule = "-στις polysyllable: treating as adjectival/ethnic → oxytone (cf. Κεραστίς, Λιγυστίς).";
      } else {
        targetFromEnd = 3;
        rule = "-στις polysyllable: guessed proparoxytone (cf. ἄγρωστις, βούβρωστις).";
      }
    }
  } else if (suf === "τις"){
    if (hasNBeforeT){
      if (sylCount <= 2){
        targetFromEnd = 2;
        rule = "-ντις disyllable: guessed barytone (paroxytone) (cf. Σάντις, Σίντις).";
      } else {
        targetFromEnd = 1;
        rule = "-ντις polysyllable: guessed oxytone (cf. Προποντίς, Ἑλλησποντίς).";
      }
    } else {
      // mixed in passage; guess oxytone if heavy-looking cluster -κτις/-πτis? toy
      if (baseNoDia.endsWith("κτις") || baseNoDia.endsWith("πτις")){
        targetFromEnd = 1;
        rule = "-τις: guessed oxytone for -κτις/-πτις clusters (cf. φλυκτίς, πηκτίς).";
      } else {
        targetFromEnd = 2;
        rule = "-τις: guessed barytone (paroxytone) as a default (cf. κλέπτις, λάκτις).";
      }
    }
  }

  // Apply accent. Use acute everywhere for simplicity.
  const accented = addAccentToSyllable(baseNoDia, Math.min(targetFromEnd, sylCount), 'acute').accented;
  return {
    input: original,
    normalized: baseNoDia,
    accented,
    sylls: splitSyllables(accented),
    rule,
    note: "(Heuristic)"
  };
}

function render(res, opts){
  $('#outMain').textContent = res.accented || '—';
  const showSyl = opts.showSyl;
  const sylTxt = showSyl ? `Syllables: ${res.sylls.join(' · ')}` : '';
  $('#outAlt').textContent = `${sylTxt}${sylTxt && res.note ? "  " : ""}${res.note||""}`.trim();
  $('#outRule').textContent = res.rule || '—';
}

function run(){
  const word = $('#inp').value;
  const opts = {
    keepUser: $('#optKeep').checked,
    showSyl: $('#optShow').checked,
    treatAdj: $('#optAdj').checked
  };
  const res = predict(word, opts);
  render(res, opts);
}

// Examples + quiz
const examples = [
  "κλεπτις","φλυκτις","πηκτις","αττις","νεοττις","πιστις","κιστις","αγρωστις","κεραστις","σαντις","προποντις","ελλησποντις","αβαντις","ακαμαντις"
];

function pick(arr){ return arr[Math.floor(Math.random()*arr.length)]; }

let quizWord = null;
function newQuiz(){
  quizWord = pick(examples);
  $('#qWord').textContent = quizWord;
  $('#qAns').textContent = "";
}

function revealQuiz(){
  const opts = {keepUser:false, showSyl:true, treatAdj: $('#optAdj').checked};
  const res = predict(quizWord, opts);
  $('#qAns').textContent = `${res.accented}  —  ${res.rule}`;
}

// Wire up
$('#btn').addEventListener('click', run);
$('#inp').addEventListener('keydown', (e)=>{ if(e.key==='Enter') run(); });
$('#rnd').addEventListener('click', ()=>{ $('#inp').value = pick(examples); run(); });

$$('.ex').forEach(el=>{
  el.addEventListener('click', ()=>{ $('#inp').value = el.dataset.v; run(); });
});

$('#optKeep').addEventListener('change', run);
$('#optShow').addEventListener('change', run);
$('#optAdj').addEventListener('change', ()=>{ run(); if(quizWord) { /* keep quiz */ } });

$('#qReveal').addEventListener('click', revealQuiz);
$('#qNext').addEventListener('click', newQuiz);

// init
run();
newQuiz();

