(() => {
  const $ = (sel, el=document) => el.querySelector(sel);
  const inWord = $('#inWord');
  const outWord = $('#outWord');
  const outNote = $('#outNote');
  const scan = $('#scan');
  const chips = $('#chips');

  const examples = [
    'κυνηγέτης',
    'δεσπότης',
    'πολίτης',
    'πολιήτης',
    'πρεσβύτης',
    'ἀλείτης',
    'ἀγυιάτης',
    'Μασσαγέτης',
    'Γέτης',
    // a couple of -ις place-names mentioned nearby
    'Σάργαντις',
    'Βούναρτις'
  ];

  // --- Greek helpers (very lightweight) ---
  const COMBINING = /[\u0300-\u036f]/g;

  function nfd(s){ return (s||'').normalize('NFD'); }
  function nfc(s){ return (s||'').normalize('NFC'); }

  function stripCombining(s){ return nfd(s).replace(COMBINING,''); }

  function hasGreek(s){
    return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(s||'');
  }

  function baseLetter(ch){
    return stripCombining(ch).toLowerCase();
  }

  function isVowelBase(ch){
    const b = baseLetter(ch);
    return 'αεηιουω'.includes(b);
  }

  function isDiphthong(v1, v2){
    const a = baseLetter(v1), b = baseLetter(v2);
    const pair = a + b;
    return ['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ωυ'].includes(pair);
  }

  function splitSyllablesRough(word){
    // Rough syllabifier: groups around vowel nuclei; treats common diphthongs as one nucleus.
    const w = nfd(word);
    const chars = Array.from(w);
    const nuclei = [];

    for(let i=0;i<chars.length;i++){
      if(isVowelBase(chars[i])){
        // diphthong nucleus
        if(i+1<chars.length && isVowelBase(chars[i+1]) && isDiphthong(chars[i], chars[i+1])){
          nuclei.push({start:i, end:i+1});
          i++;
        } else {
          nuclei.push({start:i, end:i});
        }
      }
    }
    if(nuclei.length===0) return [word];

    // Build syllables by cutting before each nucleus (except first),
    // and assigning consonants between nuclei mostly to the following syllable.
    const cuts = [0];
    for(let k=1;k<nuclei.length;k++){
      // cut at nucleus start of this syllable
      cuts.push(nuclei[k].start);
    }
    cuts.push(chars.length);

    const raw = [];
    for(let c=0;c<cuts.length-1;c++){
      raw.push(chars.slice(cuts[c], cuts[c+1]).join(''));
    }

    // Now reattach consonants that belong to previous syllable: move leading consonants
    // from each syllable (except first) to previous, leaving at least the nucleus.
    const syls = [raw[0]];
    for(let i=1;i<raw.length;i++){
      const s = raw[i];
      const arr = Array.from(s);
      // find first vowel position
      let fv = arr.findIndex(ch => isVowelBase(ch));
      if(fv<=0){
        // no vowel? attach all to previous
        syls[syls.length-1] += s;
        continue;
      }
      // keep onset consonants with this syllable (Greek often allows clusters),
      // but for a toy, move just one consonant back if there are 2+ before vowel.
      const onset = arr.slice(0,fv);
      if(onset.length>=2){
        syls[syls.length-1] += onset[0];
        syls.push(arr.slice(1).join(''));
      } else {
        syls.push(s);
      }
    }

    return syls.map(nfc);
  }

  function findAccentIndex(word){
    // Return index (in NFD codepoints) of a vowel that bears an accent mark.
    const w = nfd(word);
    const chars = Array.from(w);
    for(let i=0;i<chars.length;i++){
      if(!isVowelBase(chars[i])) continue;
      // look ahead for combining marks on this vowel
      let j=i+1;
      let marks='';
      while(j<chars.length && /[\u0300-\u036f]/.test(chars[j])){ marks += chars[j]; j++; }
      if(/[\u0301\u0300\u0342]/.test(marks)) return i; // acute, grave, circumflex
    }
    return -1;
  }

  function removeAccents(word){
    // remove only accent marks, keep breathings/diaeresis/iota subscript
    const w = nfd(word);
    // accents: acute 0301, grave 0300, circumflex 0342
    return nfc(w.replace(/[\u0301\u0300\u0342]/g,''));
  }

  function applyAcuteToVowelAtSyllable(word, syllableIndex){
    // Put an acute on the first vowel of the target syllable.
    const syls = splitSyllablesRough(word);
    if(syllableIndex<0 || syllableIndex>=syls.length) return word;

    const target = nfd(syls[syllableIndex]);
    const arr = Array.from(target);
    let out = [];
    let done = false;
    for(let i=0;i<arr.length;i++){
      out.push(arr[i]);
      if(!done && isVowelBase(arr[i])){
        // insert acute after any existing non-accent combining marks
        // find existing combining marks following this vowel
        let j=i+1;
        while(j<arr.length && /[\u0300-\u036f]/.test(arr[j])){
          // skip; we'll copy them as they come
          j++;
        }
        // But we already pushed arr[i]; the combining marks will be pushed in loop.
        // Insert acute immediately after vowel (before other marks) for simplicity.
        out.push('\u0301');
        done = true;
      }
    }
    syls[syllableIndex] = nfc(out.join(''));
    return syls.join('');
  }

  function endsWithEtaSigma(word){
    const bare = stripCombining(word).toLowerCase();
    return bare.endsWith('ης');
  }

  function makeFeminine(word){
    const original = word.trim();
    if(!original) return { ok:false, msg:'Enter a Greek word.' };
    if(!hasGreek(original)) return { ok:false, msg:'That doesn’t look like Greek script.' };

    const noAcc = removeAccents(original);
    if(!endsWithEtaSigma(noAcc)){
      return { ok:false, msg:"This toy expects a masculine ending in -ης (often -της). Try κυνηγέτης, δεσπότης, πολίτης." };
    }

    // Replace final ης with ις (preserve case of last sigma is irrelevant here)
    const n = nfd(noAcc);
    const chars = Array.from(n);
    // find last two base letters positions corresponding to η + ς
    // easiest: operate on stripped base string length, but we need to keep diacritics.
    // We'll just drop everything after the last base 'η' that is followed (later) by final sigma.
    // Simpler: remove last base sigma and last base eta by scanning from end.
    let idxSigma = -1, idxEta = -1;
    for(let i=chars.length-1;i>=0;i--){
      if(idxSigma<0 && baseLetter(chars[i])==='ς') { idxSigma=i; continue; }
      if(idxSigma>=0 && idxEta<0 && baseLetter(chars[i])==='η') { idxEta=i; break; }
    }
    if(idxEta<0 || idxSigma<0 || idxEta>idxSigma){
      return { ok:false, msg:'Could not parse the ending -ης in that spelling.' };
    }

    const stem = chars.slice(0, idxEta).join('');
    const fem = nfc(stem + 'ις');

    // Accent rule (toy): accent the syllable immediately before the ending -ις.
    // That is: accent the penult syllable of the feminine.
    const femNoAcc = removeAccents(fem);
    const syls = splitSyllablesRough(femNoAcc);
    const targetSyl = Math.max(0, syls.length - 2);
    const accented = applyAcuteToVowelAtSyllable(femNoAcc, targetSyl);

    return {
      ok:true,
      original,
      feminine: accented,
      syllables: syls,
      targetSyl
    };
  }

  function markSyllable(syls, idx){
    return syls.map((s,i)=> i===idx ? `<mark class="accent">${escapeHtml(s)}</mark>` : escapeHtml(s)).join(' · ');
  }

  function escapeHtml(s){
    return (s+'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  function render(result){
    if(!result.ok){
      outWord.textContent = '—';
      outNote.innerHTML = `<span class="badge" style="color: var(--warn)">hint</span> ${escapeHtml(result.msg)}`;
      scan.innerHTML = '—';
      return;
    }

    outWord.textContent = result.feminine;
    outNote.innerHTML = `Rule applied: <span class="mono">-ης → -ις</span> and accent placed on the syllable before <span class="mono">-ις</span>.`;

    const sylsHtml = markSyllable(result.syllables, result.targetSyl);
    scan.innerHTML = `
      <div class="scanLine"><span class="k">Syllables:</span> <span class="v">${sylsHtml}</span></div>
      <div class="scanLine"><span class="k">Accent target:</span> <span class="v">syllable ${result.targetSyl+1} of ${result.syllables.length}</span> <span class="ok">(one before the ending)</span></div>
    `;
  }

  function doMake(){
    const r = makeFeminine(inWord.value);
    render(r);
  }

  $('#btnMake').addEventListener('click', doMake);
  inWord.addEventListener('keydown', (e)=>{
    if(e.key==='Enter') doMake();
  });

  $('#btnClear').addEventListener('click', ()=>{
    inWord.value='';
    outWord.textContent='—';
    outNote.textContent='Type a word ending in -ης (often -της) and click “Make feminine”.';
    scan.textContent='—';
    inWord.focus();
  });

  $('#btnSwap').addEventListener('click', ()=>{
    const a = inWord.value;
    const b = outWord.textContent;
    if(b && b!=='—'){
      inWord.value = b;
      outWord.textContent = a || '—';
      // re-run on new input
      doMake();
    }
  });

  // chips
  examples.forEach(w=>{
    const d = document.createElement('div');
    d.className='chip';
    d.textContent=w;
    d.title='Click to load';
    d.addEventListener('click', ()=>{
      inWord.value=w;
      doMake();
      inWord.focus();
    });
    chips.appendChild(d);
  });

  // seed
  inWord.value = 'κυνηγέτης';
  doMake();
})();

