.kv{
  display:grid;
  grid-template-columns: 160px 1fr;
  gap: 10px;
  align-items: baseline;
}
.k{color: var(--faint)}
.v{color: var(--text)}

.badge{
  display:inline-block;
  padding: 2px 8px;
  border-radius: 999px;
  border:1px solid var(--border);
  background: rgba(255,255,255,.06);
  color: var(--muted);
  font-size: 12px;
  margin-right: 6px;
}

.greek{font-family: "Noto Serif", "New Athena Unicode", "Palatino Linotype", Palatino, serif; font-size: 1.05em}

.mono{font-family: var(--mono)}

.scan{
  display:flex;
  flex-wrap:wrap;
  gap:6px;
  margin-top: 6px;
}
.syl{
  padding: 6px 8px;
  border-radius: 10px;
  border:1px solid var(--border);
  background: rgba(255,255,255,.06);
}
.syl .len{display:block; font-size: 11px; color: var(--muted)}

.good{color: var(--accent2)}
.warn{color: var(--accent)}
.bad{color: var(--danger)}

.ftr{margin-top: 12px; color: var(--muted)}
summary{cursor:pointer}
.note{margin-top: 10px}
.muted{color: var(--faint)}

@media (min-width: 860px){
  .grid{grid-template-columns: 1fr 1fr}
}

