(() => {
  const $ = (sel, root=document) => root.querySelector(sel);

  const inp = $('#inp');
  const out = $('#out');
  const chkNormalize = $('#chkNormalize');
  const chkShowIPA = $('#chkShowIPA');
  const btnAnalyze = $('#btnAnalyze');
  const btnClear = $('#btnClear');
  const btnRandom = $('#btnRandom');

  const stem = $('#stem');
  const btnBuild = $('#btnBuild');
  const out2 = $('#out2');

  const examples = [
    'Σκιρῖτις','Σφραγῖτις','Φαρκωνῖτις','Χαλκῖτις','Χατραμωτῖτις','Ὠκεανῖτις','Μαρωνεῖτις','Σαλωνεῖτις','Ἀσιᾶτις','Ἀπολλωνιᾶτις','Καρυᾶτις','Πλαταιᾶτις','Πυλᾶτις','Σπαρτιᾶτις','Τεγεᾶτις','Ὑσιᾶτις',
    'ἄκοιτις','παράκοιτις','ἀρτόπωλις','λαχανόπωλις','ἀλφιτόπωλις',
    'Σκυθίς','Περσίς',
    'ῥαφίς','γλυφίς','σταφίς','στροφίς','ὄφις','Ἶφις','Μέμφις',
    'πλευρῖτις','φρενῖτις','νεφρῖτις'
  ];

  // --- Greek helpers ---
  const combiningMarks = /[\u0300-\u036f\u1ab0-\u1aff\u1dc0-\u1dff\u20d0-\u20ff\uFE20-\uFE2F]/g;

  function stripDiacritics(s){
    return s.normalize('NFD').replace(combiningMarks,'').normalize('NFC');
  }

  function stripNonLetters(s){
    return s.replace(/[\s·.,;:“”"'()\[\]{}<>!?—–-]/g,'');
  }

  function hasGreek(s){
    return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(s);
  }

  function translitRough(s){
    // very rough, for fun
    const map = {
      'α':'a','β':'b','γ':'g','δ':'d','ε':'e','ζ':'z','η':'ē','θ':'th','ι':'i','κ':'k','λ':'l','μ':'m','ν':'n','ξ':'x','ο':'o','π':'p','ρ':'r','σ':'s','ς':'s','τ':'t','υ':'y','φ':'ph','χ':'kh','ψ':'ps','ω':'ō',
      'Α':'A','Β':'B','Γ':'G','Δ':'D','Ε':'E','Ζ':'Z','Η':'Ē','Θ':'Th','Ι':'I','Κ':'K','Λ':'L','Μ':'M','Ν':'N','Ξ':'X','Ο':'O','Π':'P','Ρ':'R','Σ':'S','Τ':'T','Υ':'Y','Φ':'Ph','Χ':'Kh','Ψ':'Ps','Ω':'Ō'
    };
    const base = stripDiacritics(s);
    return [...base].map(ch => map[ch] ?? ch).join('');
  }

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ','ϊ','ΐ','ϋ','ΰ','ᾳ','ῃ','ῳ','ᾴ','ῄ','ῴ']);

  function isVowel(ch){
    const b = stripDiacritics(ch).toLowerCase();
    return ['α','ε','η','ι','ο','υ','ω'].includes(b);
  }

  function isDiphthong(v1, v2){
    const a = stripDiacritics(v1).toLowerCase();
    const b = stripDiacritics(v2).toLowerCase();
    const pair = a+b;
    return ['αι','ει','οι','υι','αυ','ευ','ου','ηυ'].includes(pair);
  }

  function syllabify(word){
    // naive syllabification: split before each vowel group
    const w = word;
    const chars = [...w];
    let nuclei = [];
    for(let i=0;i<chars.length;i++){
      if(isVowel(chars[i])){
        // include diphthong
        let j=i;
        if(i+1<chars.length && isVowel(chars[i+1]) && isDiphthong(chars[i], chars[i+1])) j=i+1;
        nuclei.push({start:i, end:j});
        i=j;
      }
    }
    if(nuclei.length===0) return [w];

    let sylls=[];
    let start=0;
    for(let n=0;n<nuclei.length;n++){
      const nuc = nuclei[n];
      const nextNuc = nuclei[n+1];
      if(!nextNuc){
        sylls.push(chars.slice(start).join(''));
        break;
      }
      // boundary somewhere between nuc.end and nextNuc.start
      // put one consonant (if any) with next syllable, rest with current
      const between = chars.slice(nuc.end+1, nextNuc.start);
      if(between.length<=1){
        sylls.push(chars.slice(start, nextNuc.start).join(''));
        start = nextNuc.start;
      } else {
        // keep all but last consonant in current syllable
        const cut = nextNuc.start - 1;
        sylls.push(chars.slice(start, cut).join(''));
        start = cut;
      }
    }
    return sylls.filter(x=>x.length);
  }

  function guessLongPenult(word){
    // heuristic: penult nucleus contains η/ω or diphthong or has iota subscript; or closed by consonant cluster
    const w = stripDiacritics(word);
    const syl = syllabify(w);
    if(syl.length < 2) return false;
    const pen = syl[syl.length-2];
    const penChars = [...pen];
    // find vowel nucleus in penult
    let nucIdx = penChars.findIndex(isVowel);
    if(nucIdx<0) return false;
    const v1 = penChars[nucIdx];
    const v2 = penChars[nucIdx+1];
    const v1b = stripDiacritics(v1).toLowerCase();
    if(v1b==='η' || v1b==='ω') return true;
    if(v2 && isVowel(v2) && isDiphthong(v1, v2)) return true;
    // long by position: vowel followed by 2+ consonants within syllable
    const after = penChars.slice(nucIdx+1);
    const consonants = after.filter(ch => ch && !isVowel(ch));
    if(consonants.length>=2) return true;
    return false;
  }

  function accentuate(word, rule){
    // Add a simple acute/circumflex to the guessed syllable nucleus.
    // This is intentionally approximate.
    const original = word;
    const base = stripDiacritics(word);
    const syl = syllabify(base);
    if(syl.length===0) return original;

    let target = syl.length-1; // default oxytone
    let accentType = 'acute';

    if(rule==='paroxytone') target = Math.max(0, syl.length-2);
    if(rule==='proparoxytone') target = Math.max(0, syl.length-3);
    if(rule==='perispomenon-penult') { target = Math.max(0, syl.length-2); accentType='circ'; }

    // rebuild with accent on first vowel of target syllable
    const acuteMap = {
      'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
      'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
    };
    const circMap = {
      'α':'ᾶ','η':'ῆ','ι':'ῖ','υ':'ῦ','ω':'ῶ',
      'Α':'ᾶ','Η':'ῆ','Ι':'ῖ','Υ':'ῦ','Ω':'ῶ'
    };

    const map = accentType==='acute' ? acuteMap : circMap;

    let outSyl = syl.slice();
    let chars = [...outSyl[target]];
    for(let i=0;i<chars.length;i++){
      if(isVowel(chars[i])){
        const b = chars[i];
        const repl = map[b] || map[stripDiacritics(b)] || null;
        if(repl){ chars[i]=repl; }
        break;
      }
    }
    outSyl[target] = chars.join('');
    return outSyl.join('');
  }

  function classify(word){
    const w = stripDiacritics(word).toLowerCase();
    if(w.endsWith('φις')) return 'phis';
    if(w.endsWith('ιτις')) return 'itis';
    if(w.endsWith('ις')) return 'is';
    return 'other';
  }

  function analyze(){
    let w = inp.value.trim();
    w = stripNonLetters(w);
    if(!w){
      out.innerHTML = '<span class="muted">Type a word above.</span>';
      return;
    }
    if(!hasGreek(w)){
      out.innerHTML = '<span class="bad">This doesn\'t look like Greek letters.</span>';
      return;
    }

    const shown = w;
    const norm = chkNormalize.checked ? stripDiacritics(w) : w;
    const cls = classify(norm);

    const syl = syllabify(stripDiacritics(norm));
    const penLong = guessLongPenult(norm);

    let ruleLabel = '';
    let suggestion = '';
    let why = '';

    if(cls==='phis'){
      // Herodian: -φις disyllables with two shorts -> oxytone; if penult long -> paroxytone or circumflex.
      if(syl.length===2){
        if(penLong){
          // choose between paroxytone and circumflex on penult; we pick circumflex if penult looks long.
          suggestion = accentuate(norm, 'perispomenon-penult');
          ruleLabel = 'Herodian-ish: -φις with long penult → penult accent (often circumflex)';
          why = 'Penult guessed long (η/ω, diphthong, or closed).';
        } else {
          suggestion = accentuate(norm, 'oxytone');
          ruleLabel = 'Herodian-ish: -φις (two short syllables) → oxytone';
          why = 'Disyllable and penult guessed short.';
        }
      } else {
        suggestion = accentuate(norm, 'oxytone');
        ruleLabel = 'Toy default: -φις but not disyllabic → oxytone (simplified)';
        why = 'Herodian\'s note is specifically about disyllables.';
      }
    } else if(cls==='itis'){
      // Many -ιτις toponyms; passage also notes special compounds from κοίτη/πωλῶ are proparoxytone.
      const base = stripDiacritics(norm).toLowerCase();
      const special = base.includes('κοιτι') || base.includes('πωλι');
      if(special){
        suggestion = accentuate(norm, 'proparoxytone');
        ruleLabel = 'Herodian-ish exception: compounds with -κοιτις / -πωλις → antepenult accent';
        why = 'Detected κοιτι-/πωλι- sequence (very rough).';
      } else {
        // common-looking pattern in examples: Χαλκῖτις etc. (circumflex on penult)
        suggestion = accentuate(norm, 'perispomenon-penult');
        ruleLabel = 'Toponymic -ιτις (toy): penult circumflex (like Χαλκῖτις)';
        why = 'Many listed -ιτις names show penult prominence; this is a playful generalization.';
      }
    } else if(cls==='is'){
      // e.g. Σκυθίς, Περσίς: disyllabic oxytone
      if(syl.length===2){
        suggestion = accentuate(norm, 'oxytone');
        ruleLabel = 'Herodian-ish: disyllabic -ίς often oxytone (Σκυθίς, Περσίς)';
        why = 'Disyllable ending in -ις.';
      } else {
        suggestion = accentuate(norm, 'paroxytone');
        ruleLabel = 'Toy default: -ις (3+ syllables) → paroxytone (simplified)';
        why = 'No specific rule applied.';
      }
    } else {
      suggestion = accentuate(norm, syl.length>=3 ? 'paroxytone' : 'oxytone');
      ruleLabel = 'Toy default accent (not from this chapter)';
      why = 'Word does not match -ιτις / -φις patterns.';
    }

    const scan = syl.map((s, i) => {
      const len = (i===syl.length-2 && penLong) ? 'long?' : (i===syl.length-2 ? 'short?' : '');
      return `<span class="syl"><span class="greek">${escapeHtml(s)}</span>${len?`<span class="len">${len}</span>`:''}</span>`;
    }).join('');

    const translit = chkShowIPA.checked ? `<div class="kv"><div class="k">Translit (rough)</div><div class="v mono">${escapeHtml(translitRough(shown))}</div></div>` : '';

    out.innerHTML = `
      <div class="grid">
        <div>
          <div class="kv"><div class="k">You typed</div><div class="v greek">${escapeHtml(shown)}</div></div>
          <div class="kv"><div class="k">Normalized</div><div class="v greek">${escapeHtml(stripDiacritics(shown))}</div></div>
          <div class="kv"><div class="k">Class</div><div class="v"><span class="badge">${cls}</span> <span class="muted">(${escapeHtml(ruleLabel)})</span></div></div>
          <div class="kv"><div class="k">Suggestion</div><div class="v greek"><span class="good">${escapeHtml(suggestion)}</span></div></div>
          <div class="kv"><div class="k">Why</div><div class="v">${escapeHtml(why)}</div></div>
          ${translit}
        </div>
        <div>
          <div class="kv"><div class="k">Syllables (toy)</div><div class="v"><span class="muted">click letters to copy</span></div></div>
          <div class="scan" id="scan">${scan}</div>
          <div class="kv"><div class="k">Penult long?</div><div class="v">${penLong ? '<span class="warn">maybe</span>' : '<span class="muted">probably not</span>'}</div></div>
        </div>
      </div>
    `;

    // click-to-copy syllables
    const scanEl = $('#scan');
    scanEl?.addEventListener('click', (e) => {
      const t = e.target.closest('.syl');
      if(!t) return;
      const txt = t.innerText.replace(/\s+long\?|\s+short\?/g,'').trim();
      copyText(txt);
    }, {once:true});
  }

  function buildItis(){
    let s = stem.value.trim();
    s = stripNonLetters(s);
    if(!s){
      out2.innerHTML = '<span class="muted">Type a stem (Greek letters) above.</span>';
      return;
    }
    if(!hasGreek(s)){
      out2.innerHTML = '<span class="bad">Stem should be Greek letters.</span>';
      return;
    }

    // crude joining rules
    let base = stripDiacritics(s);
    // remove trailing hyphen-like or final sigma issues already stripped
    // if ends with vowel, often insert -ιτις directly; if ends with consonant, add -ιτις.
    let formed = base;
    if(!stripDiacritics(base).toLowerCase().endsWith('ιτι')){
      formed = base + 'ιτις';
    } else {
      formed = base + 'ς';
    }

    // suggest accent like Χαλκῖτις
    const accented = accentuate(formed, 'perispomenon-penult');

    out2.innerHTML = `
      <div class="kv"><div class="k">Stem</div><div class="v greek">${escapeHtml(s)}</div></div>
      <div class="kv"><div class="k">Built form</div><div class="v greek"><span class="good">${escapeHtml(accented)}</span> <span class="muted">(toy)</span></div></div>
      <div class="kv"><div class="k">Try as adjective</div><div class="v greek">ἡ <span class="good">${escapeHtml(accented)}</span> (χώρα/νῆσος/πόλις)</div></div>
      <div class="kv"><div class="k">Copy</div><div class="v"><button class="btn" type="button" id="btnCopyBuilt">Copy built form</button></div></div>
    `;

    $('#btnCopyBuilt')?.addEventListener('click', () => copyText(accented), {once:true});
  }

  function copyText(t){
    // offline-safe clipboard attempt
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(t).catch(() => fallbackCopy(t));
    } else {
      fallbackCopy(t);
    }
  }

  function fallbackCopy(t){
    const ta = document.createElement('textarea');
    ta.value = t;
    ta.setAttribute('readonly','');
    ta.style.position='fixed';
    ta.style.left='-9999px';
    document.body.appendChild(ta);
    ta.select();
    try{ document.execCommand('copy'); }catch(e){}
    document.body.removeChild(ta);
  }

  function escapeHtml(s){
    return String(s)
      .replaceAll('&','&amp;')
      .replaceAll('<','&lt;')
      .replaceAll('>','&gt;')
      .replaceAll('"','&quot;')
      .replaceAll("'",'&#39;');
  }

  // events
  btnAnalyze.addEventListener('click', analyze);
  inp.addEventListener('keydown', (e) => {
    if(e.key==='Enter') analyze();
  });
  btnClear.addEventListener('click', () => {
    inp.value='';
    out.innerHTML = '<span class="muted">Cleared.</span>';
    inp.focus();
  });
  btnRandom.addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inp.value = ex;
    analyze();
  });

  btnBuild.addEventListener('click', buildItis);
  stem.addEventListener('keydown', (e) => {
    if(e.key==='Enter') buildItis();
  });

  // initial state
  out.innerHTML = '<span class="muted">Tip: try <span class="greek">ῥαφις</span>, <span class="greek">Μέμφις</span>, <span class="greek">Χαλκιτις</span>, <span class="greek">ἄκοιτις</span>.</span>';
  out2.innerHTML = '<span class="muted">Try stem: <span class="greek">Χαλκ</span> → <span class="greek">Χαλκῖτις</span> (toy).</span>';
})();

passages.gadget_css:
:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --panel2:#1d2136;
  --text:#e9ecff;
  --muted:#b9c0ff;
  --faint:#8b93d6;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --good:#34d399;
  --warn:#fbbf24;
  --bad:#fb7185;
  --border:rgba(255,255,255,.10);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
}
*{box-sizing:border-box}
.wrap{max-width:980px;margin:18px auto;padding:14px;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,"Noto Sans",sans-serif;color:var(--text)}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, #1b1f3a 0%, var(--bg) 55%)}
.hdr{padding:14px 14px 6px}
.hdr h1{margin:0 0 6px;font-size:22px;letter-spacing:.2px}
.sub{margin:0;color:var(--muted);line-height:1.35}
.panel{background:linear-gradient(180deg,var(--panel),var(--panel2));border:1px solid var(--border);border-radius:14px;padding:14px;margin:12px 0;box-shadow:var(--shadow)}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.row.small{margin-top:10px;align-items:flex-start}
.lbl{min-width:70px;color:var(--muted);font-weight:600}
.inp{flex:1;min-width:260px;padding:10px 12px;border-radius:12px;border:1px solid var(--border);background:rgba(255,255,255,.06);color:var(--text);font-size:16px;outline:none}
.inp:focus{border-color:rgba(125,211,252,.55);box-shadow:0 0 0 4px rgba(125,211,252,.12)}
.btn{padding:9px 12px;border-radius:12px;border:1px solid rgba(125,211,252,.35);background:rgba(125,211,252,.12);color:var(--text);cursor:pointer;font-weight:650}
.btn:hover{background:rgba(125,211,252,.18)}
.btn:active{transform:translateY(1px)}
.btn.ghost{border-color:var(--border);background:rgba(255,255,255,.06);font-weight:600}
.btn.ghost:hover{background:rgba(255,255,255,.09)}
.tog{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:8px 10px;border:1px solid var(--border);border-radius:12px;background:rgba(255,255,255,.04)}
.lbl2{color:var(--muted);font-weight:650;margin-right:4px}
.tog label{color:var(--text);font-size:14px;display:flex;gap:6px;align-items:center}
.hint{color:var(--muted);line-height:1.35}
.hint ul{margin:8px 0 0 18px;padding:0}
.hint code{color:var(--accent);font-weight:700}
.out h2{margin:0 0 10px;font-size:18px}
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
@media (max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}}
@media (max-width:520px){.grid{grid-template-columns:1fr}}
.card{border:1px solid var(--border);border-radius:12px;padding:10px;background:rgba(255,255,255,.04)}
.k{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.08em}
.v{margin-top:6px;font-size:15px}
.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono","Courier New",monospace}
.play{margin-top:12px}
.playRow{display:grid;grid-template-columns:1.3fr 1fr;gap:10px}
@media (max-width:900px){.playRow{grid-template-columns:1fr}}
.playCard{border:1px solid var(--border);border-radius:12px;padding:10px;background:rgba(255,255,255,.04)}
.btnRow{display:flex;gap:8px;flex-wrap:wrap;margin:8px 0}
.big{font-size:22px;padding:10px 12px;border-radius:12px;border:1px dashed rgba(255,255,255,.18);background:rgba(0,0,0,.18)}
.mini{color:var(--faint);font-size:12.5px;margin-top:6px;line-height:1.25}
.details{margin-top:10px}
.details summary{cursor:pointer;color:var(--accent);font-weight:700}
.quote{margin-top:8px;padding:10px 12px;border-radius:12px;border:1px solid var(--border);background:rgba(0,0,0,.18);color:var(--muted);line-height:1.35}
.ftr{padding:4px 14px 14px}
.badge{display:inline-block;padding:2px 8px;border-radius:999px;border:1px solid var(--border);background:rgba(255,255,255,.05);color:var(--muted);font-size:12px}
.noteGood{color:var(--good);font-weight:700}
.noteWarn{color:var(--warn);font-weight:700}
.noteBad{color:var(--bad);font-weight:700}

passages.gadget_js:
const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => Array.from(document.querySelectorAll(sel));

// --- Greek helpers (toy-level) ---
const COMBINING = {
  acute: "\u0301",
  circumflex: "\u0342",
  grave: "\u0300",
  diaeresis: "\u0308",
  smooth: "\u0313",
  rough: "\u0314",
  iotaSub: "\u0345"
};

function nfd(s){ return (s||"").normalize('NFD'); }
function nfc(s){ return (s||"").normalize('NFC'); }

function stripDiacriticsKeepDiaeresis(s){
  // Remove Greek accent/breathing/iota-subscript; keep diaeresis (useful for syllables).
  const t = nfd(s);
  let out = "";
  for (const ch of t){
    const code = ch.codePointAt(0);
    if (code >= 0x0300 && code <= 0x036F){
      if (ch === COMBINING.diaeresis) out += ch;
      // else drop
    } else out += ch;
  }
  return nfc(out);
}

function stripAllCombining(s){
  return nfc(nfd(s).replace(/[\u0300-\u036f]/g, ""));
}

function lastGreekWord(phrase){
  const s = (phrase||"").trim();
  if (!s) return "";
  // Keep Greek letters; split on whitespace/punct.
  const parts = s.split(/\s+/);
  return parts[parts.length-1].replace(/^[^\p{L}]+|[^\p{L}]+$/gu, "");
}

const VOWELS = new Set(["α","ε","η","ι","ο","υ","ω","ά","έ","ή","ί","ό","ύ","ώ","ϊ","ϋ","ΐ","ΰ",
                        "Α","Ε","Η","Ι","Ο","Υ","Ω","Ά","Έ","Ή","Ί","Ό","Ύ","Ώ","Ϊ","Ϋ"]);

function isVowelChar(ch){
  return VOWELS.has(ch);
}

function roughSyllableCount(word){
  // Very rough: count vowel nuclei (including diphthongs as 1 unless diaeresis splits).
  const w = stripDiacriticsKeepDiaeresis(word);
  const s = nfd(w);
  // Build array of base letters with possible diaeresis marker.
  const letters = [];
  let cur = null;
  for (const ch of s){
    if (ch.match(/[\u0300-\u036f]/)){
      if (cur && ch === COMBINING.diaeresis) cur.dia = true;
    } else {
      cur = {ch, dia:false};
      letters.push(cur);
    }
  }
  let count = 0;
  for (let i=0;i<letters.length;i++){
    const a = letters[i];
    if (!isVowelChar(a.ch)) continue;
    // diphthong check with next vowel
    const b = letters[i+1];
    if (b && isVowelChar(b.ch) && !b.dia && !a.dia){
      const pair = (a.ch + b.ch).toLowerCase();
      const diph = new Set(["αι","ει","οι","υι","αυ","ευ","ου","ηυ","ωυ"]);
      if (diph.has(pair)){
        count += 1;
        i += 1;
        continue;
      }
    }
    count += 1;
  }
  return Math.max(count, 1);
}

function detectEnding(word){
  const w = stripAllCombining(word).toLowerCase();
  if (w.endsWith("φις")) return "-φις";
  if (w.endsWith("χις")) return "-χις";
  if (w.endsWith("ις")) return "-ις";
  return "(other)";
}

function removeExistingAccentBreathing(word){
  // remove all combining marks; keep base letters
  return stripAllCombining(word);
}

function addAccentToVowel(word, vowelIndexFromEnd, accentType){
  // accentType: 'acute' | 'circumflex'
  // vowelIndexFromEnd: 1=last vowel nucleus, 2=penult nucleus, 3=antepenult nucleus
  const base = removeExistingAccentBreathing(word);
  const letters = Array.from(nfd(base));
  // Find vowel positions (indices in letters array) for nuclei (approx: each vowel letter counts)
  const vowelPositions = [];
  for (let i=0;i<letters.length;i++){
    const ch = letters[i];
    if (ch.match(/[\u0300-\u036f]/)) continue;
    if (isVowelChar(ch)) vowelPositions.push(i);
  }
  if (!vowelPositions.length) return base;
  const pos = vowelPositions[Math.max(0, vowelPositions.length - vowelIndexFromEnd)];
  const mark = accentType === 'circumflex' ? COMBINING.circumflex : COMBINING.acute;
  letters[pos] = letters[pos] + mark;
  return nfc(letters.join(""));
}

function suggest(word, kind, accChoice){
  const w = lastGreekWord(word);
  const norm = removeExistingAccentBreathing(w);
  const ending = detectEnding(w);
  const syll = roughSyllableCount(w);

  let note = "";
  let suggestedForm = norm;
  let label = "";

  // Auto heuristics: if ends with -ουφις or -εμφις treat as proper-ish (based on examples)
  const low = stripAllCombining(w).toLowerCase();
  const autoProper = /ουφις$/.test(low) || /εμφις$/.test(low);

  const effectiveKind = (kind === 'auto') ? (autoProper ? 'proper' : 'ethnic') : kind;

  if (ending === "-φις"){
    if (effectiveKind === 'proper'){
      suggestedForm = addAccentToVowel(norm, 3, 'acute');
      label = "proparoxytone (antepenult acute)";
      note = "Toy rule: proper names in -φις often προπαροξύνονται (e.g. Ὄνουφις, Μώμεμφις).";
    } else {
      if (syll > 2){
        suggestedForm = addAccentToVowel(norm, 1, 'acute');
        label = "oxytone (final acute)";
        note = "Toy rule: -φις with >2 syllables tends to be oxytone (ὀξύνεται).";
      } else {
        suggestedForm = addAccentToVowel(norm, 1, 'acute');
        label = "oxytone (final acute)";
        note = "Short -φις: this toy still makes it oxytone (cf. Κηφίς, Δελφίς).";
      }
    }
  } else if (ending === "-χις"){
    if (effectiveKind === 'city'){
      suggestedForm = addAccentToVowel(norm, 1, 'acute');
      label = "(place-name exception flagged)";
      note = "Herodian notes place-name exceptions for -χις; this toy keeps final acute but flags it.";
    } else {
      suggestedForm = addAccentToVowel(norm, 1, 'acute');
      label = "oxytone (final acute)";
      note = "Toy rule: -χις tends to be oxytone (ὀξύνεται).";
    }
  } else if (ending === "-ις"){
    // Feminine -is rule based on accusative
    let acc = accChoice;
    if (acc === 'auto'){
      // guess: if ends with -δις/-τις etc maybe -ιν? too hard; default to -α
      acc = '-a';
    }
    if (acc === '-a'){
      suggestedForm = addAccentToVowel(norm, 1, 'acute');
      label = "oxytone (final acute)";
      note = "If acc. is -α, Herodian: ὀξύνονται (e.g. ῥανίς).";
    } else {
      suggestedForm = addAccentToVowel(norm, 1, 'circumflex');
      label = "perispomenon (final circumflex)";
      note = "If acc. is -ιν, Herodian: περισπῶνται (e.g. Βενδῖς).";
    }
  } else {
    suggestedForm = norm;
    label = "(no rule applied)";
    note = "Try a word ending in -φις, -χις, or -ις.";
  }

  return {w, norm, ending, syll, effectiveKind, suggestedForm, label, note};
}

function makeAccusative(word, type){
  // Only for -ις nouns: -α or -ιν
  const base = removeExistingAccentBreathing(lastGreekWord(word));
  const low = base.toLowerCase();
  if (!low.endsWith("ις")) return {form:"—", note:"Works best for feminine -ις nouns."};
  const stem = base.slice(0, -2);
  if (type === '-a'){
    return {form: nfc(stem + "ι" + "ν"), note:"(Toy) Many -ις feminines actually have acc. -ιν; use this button to compare forms."};
  }
  return {form: nfc(stem + "ιν"), note:"Accusative in -ιν (as in Herodian’s περισπώμενα examples)."};
}

// --- UI wiring ---
const examples = [
  "Κηφις",
  "Δελφις",
  "Κερκαφις",
  "Ακραιφις",
  "Ονουφις",
  "Μωμεμφις",
  "Παρεμφις",
  "παννυχις",
  "Τραχις",
  "Δουλιχις",
  "Ερυσιχις",
  "ραχις",
  "εχις",
  "Κολχις",
  "ρανις",
  "κρηπις",
  "Βενδις",
  "Αταργατις"
];

function getKind(){
  return ($$('input[name="kind"]').find(r=>r.checked) || {value:'auto'}).value;
}
function getAcc(){
  return ($$('input[name="acc"]').find(r=>r.checked) || {value:'auto'}).value;
}

function render(){
  const input = $('#inp').value;
  const kind = getKind();
  const acc = getAcc();
  const r = suggest(input, kind, acc);

  $('#norm').textContent = r.norm || '—';
  $('#ending').textContent = r.ending;
  $('#syll').textContent = String(r.syll);

  const kindBadge = `<span class="badge">kind: ${r.effectiveKind}</span>`;
  $('#accent').innerHTML = `<div class="mono" style="font-size:18px;margin-bottom:6px">${escapeHtml(r.suggestedForm)}</div>
    <div class="mini">${kindBadge} <span class="badge">${escapeHtml(r.label)}</span></div>
    <div class="mini">${escapeHtml(r.note)}</div>`;

  $('#accented').textContent = r.suggestedForm || '—';

  // accusative panel
  const low = stripAllCombining(r.norm).toLowerCase();
  if (low.endsWith('ις')){
    const a = makeAccusative(r.norm, '-a');
    const i = makeAccusative(r.norm, '-in');
    $('#accOut').textContent = `${a.form}  /  ${i.form}`;
    $('#accNote').textContent = 'Click a button to pick one and see the matching accent suggestion.';
  } else {
    $('#accOut').textContent = '—';
    $('#accNote').textContent = 'Accusative toy only triggers for words ending in -ις.';
  }
}

function escapeHtml(s){
  return (s??'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

$('#btnAnalyze').addEventListener('click', render);
$('#inp').addEventListener('input', () => { /* live */ render(); });

$('#btnRandom').addEventListener('click', () => {
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#inp').value = ex;
  // reset toggles to auto for a clean demo
  $$('input[name="kind"]').forEach(r=>r.checked = (r.value==='auto'));
  $$('input[name="acc"]').forEach(r=>r.checked = (r.value==='auto'));
  render();
});

$('#btnClear').addEventListener('click', () => {
  $('#inp').value = '';
  render();
});

$$('input[name="kind"]').forEach(r => r.addEventListener('change', render));
$$('input[name="acc"]').forEach(r => r.addEventListener('change', render));

$('#btnOx').addEventListener('click', () => {
  const w = removeExistingAccentBreathing(lastGreekWord($('#inp').value));
  $('#accented').textContent = w ? addAccentToVowel(w, 1, 'acute') : '—';
});
$('#btnPro').addEventListener('click', () => {
  const w = removeExistingAccentBreathing(lastGreekWord($('#inp').value));
  $('#accented').textContent = w ? addAccentToVowel(w, 3, 'acute') : '—';
});
$('#btnPer').addEventListener('click', () => {
  const w = removeExistingAccentBreathing(lastGreekWord($('#inp').value));
  $('#accented').textContent = w ? addAccentToVowel(w, 1, 'circumflex') : '—';
});

$('#btnAccA').addEventListener('click', () => {
  // set acc toggle and re-render
  $$('input[name="acc"]').forEach(r=>r.checked = (r.value==='-a'));
  render();
});
$('#btnAccIn').addEventListener('click', () => {
  $$('input[name="acc"]').forEach(r=>r.checked = (r.value==='-in'));
  render();
});

// initial
render();

passages.gadget_css:
:root{
  --bg:#0f1220;
  --card:#171a2b;
  --card2:#14172a;
  --text:#e9ecff;
  --muted:#b7bce6;
  --faint:#8b92c7;
  --accent:#7bdcff;
  --accent2:#b7ff7b;
  --warn:#ffcf7b;
  --bad:#ff7b9a;
  --border:rgba(255,255,255,.10);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Noto Sans", "Liberation Sans", sans-serif;
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, rgba(123,220,255,.18), transparent 55%), radial-gradient(900px 600px at 90% 10%, rgba(183,255,123,.12), transparent 55%), var(--bg); color:var(--text); font-family:var(--sans)}
.wrap{max-width:980px;margin:24px auto;padding:18px}
.hdr{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:14px}
.hdr h1{font-size:22px;margin:0 0 6px 0;letter-spacing:.2px}
.sub{margin:0;color:var(--muted);line-height:1.35}
.card{background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02)); border:1px solid var(--border); border-radius:14px; padding:14px 14px; box-shadow:var(--shadow)}
.card h2{margin:0 0 10px 0;font-size:16px}
.card h3{margin:0 0 8px 0;font-size:14px;color:var(--muted)}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.lbl{min-width:52px;color:var(--muted)}
.inp{flex:1;min-width:260px;padding:10px 12px;border-radius:12px;border:1px solid var(--border);background:rgba(0,0,0,.25);color:var(--text);font-size:16px;outline:none}
.inp:focus{border-color:rgba(123,220,255,.55); box-shadow:0 0 0 3px rgba(123,220,255,.12)}
.btn{padding:10px 12px;border-radius:12px;border:1px solid rgba(123,220,255,.35);background:rgba(123,220,255,.12);color:var(--text);cursor:pointer}
.btn:hover{background:rgba(123,220,255,.18)}
.btn.ghost{border-color:var(--border);background:rgba(255,255,255,.04)}
.btn.ghost:hover{background:rgba(255,255,255,.07)}
.opts{margin-top:10px}
.opt{display:flex;gap:8px;align-items:center;color:var(--muted);font-size:13px}
.opt input{accent-color:var(--accent)}
.hint{margin:10px 0 0 0;color:var(--faint);font-size:13px;line-height:1.35}
.grid{display:grid;grid-template-columns:1fr;gap:14px;margin-top:14px}
@media (min-width:860px){.grid{grid-template-columns:1fr 1.2fr}}
.out{font-family:var(--mono);font-size:13px;line-height:1.45;white-space:pre-wrap;background:rgba(0,0,0,.22);border:1px solid var(--border);border-radius:12px;padding:10px;min-height:92px}
.two{display:grid;grid-template-columns:1fr;gap:12px}
@media (min-width:860px){.two{grid-template-columns:1fr 1fr}}
.chips{display:flex;flex-wrap:wrap;gap:8px}
.chip{border:1px solid var(--border);background:rgba(255,255,255,.04);color:var(--text);padding:7px 10px;border-radius:999px;cursor:pointer;font-family:var(--mono);font-size:13px}
.chip:hover{border-color:rgba(183,255,123,.35);background:rgba(183,255,123,.10)}
.small{color:var(--muted);font-size:13px;line-height:1.4}
.ftr{margin-top:14px}
details{border:1px dashed rgba(255,255,255,.18);border-radius:14px;padding:10px 12px;background:rgba(0,0,0,.18)}
summary{cursor:pointer;color:var(--accent);font-weight:600}
.k{color:var(--accent)}
.g{color:var(--accent2)}
.w{color:var(--warn)}
.b{color:var(--bad)}
hr{border:none;border-top:1px solid var(--border);margin:10px 0}
.tag{display:inline-block;padding:2px 8px;border-radius:999px;border:1px solid var(--border);background:rgba(255,255,255,.04);font-size:12px;color:var(--muted);margin-right:6px}

passages.gadget_js:
(() => {
  const $ = (sel, el=document) => el.querySelector(sel);
  const inp = $('#inp');
  const analysis = $('#analysis');
  const accentOut = $('#accentOut');
  const lambdaOut = $('#lambdaOut');
  const optNormalize = $('#optNormalize');
  const optAutoAccent = $('#optAutoAccent');
  const optLambdaLoss = $('#optLambdaLoss');

  const examples = [
    'λαός','λαος','λαλός','λαλος','ληός','ληος','ναός','ναος','νηός','νηος','παός','παος','πηός','πηος','Δᾶος','Δαος'
  ];

  const chips = $('#chips');
  examples.forEach(w => {
    const b = document.createElement('button');
    b.className = 'chip';
    b.type = 'button';
    b.textContent = w;
    b.addEventListener('click', () => { inp.value = w; run(); inp.focus(); });
    chips.appendChild(b);
  });

  $('#btnClear').addEventListener('click', () => { inp.value=''; run(); inp.focus(); });
  $('#btnDemo').addEventListener('click', () => {
    const w = examples[Math.floor(Math.random()*examples.length)];
    inp.value = w;
    run();
    inp.focus();
  });

  ;[inp,optNormalize,optAutoAccent,optLambdaLoss].forEach(el => el.addEventListener('input', run));

  // --- Greek helpers ---
  const COMBINING = /[\u0300-\u036f]/g;
  function nfd(s){ return s.normalize('NFD'); }
  function stripCombining(s){ return nfd(s).replace(COMBINING,'').normalize('NFC'); }
  function stripSpaces(s){ return s.replace(/\s+/g,' ').trim(); }

  // Rough-and-ready: remove accents but keep diaeresis/breathing? For matching we remove all combining.
  function normalizeForMatch(s){
    return stripCombining(stripSpaces(s)).toLowerCase();
  }

  function isGreekLetter(ch){
    const code = ch.codePointAt(0);
    return (code>=0x0370 && code<=0x03FF) || (code>=0x1F00 && code<=0x1FFF);
  }

  function lastGreekWord(s){
    const parts = stripSpaces(s).split(' ');
    for(let i=parts.length-1;i>=0;i--){
      if([...parts[i]].some(isGreekLetter)) return parts[i];
    }
    return '';
  }

  function countVowelGroups(word){
    const w = normalizeForMatch(word);
    const vowels = new Set(['α','ε','η','ι','ο','υ','ω']);
    let groups = 0;
    let inV = false;
    for(const ch of w){
      const v = vowels.has(ch);
      if(v && !inV){ groups++; inV=true; }
      if(!v) inV=false;
    }
    return groups;
  }

  function endsWithOs(word){
    const w = normalizeForMatch(word);
    return w.endsWith('ος');
  }

  // Accent placement: add acute to the vowel of the penult syllable (toy).
  // We approximate syllables by vowel groups; for disyllables, penult = first vowel group.
  const acuteMap = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };

  function addAcuteToFirstVowel(word){
    // Preserve original letters as much as possible; if already has tonos/oxia, return as-is.
    if(/[άέήίόύώΆΈΉΊΌΎΏ]/.test(word)) return {out: word, note: 'Already contains an acute/tonos; leaving as-is.'};

    // Work in NFC; find first vowel letter (Greek) and replace with acute version.
    const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
    let arr = [...word];
    for(let i=0;i<arr.length;i++){
      const ch = arr[i];
      if(vowels.has(ch)){
        arr[i] = acuteMap[ch] || ch;
        return {out: arr.join(''), note: 'Toy rule: acute on the penult of a disyllable → here approximated as the first vowel.'};
      }
    }
    return {out: word, note: 'No vowel found to accent.'};
  }

  function lambdaVariants(word){
    const base = normalizeForMatch(word);
    const variants = new Set();

    // 1) If contains λλ or λ, try dropping one λ (λ-loss)
    if(base.includes('λ')){
      // drop first lambda
      variants.add(base.replace('λ',''));
      // drop all lambdas
      variants.add(base.replace(/λ/g,''));
    }

    // 2) If contains αο sequence (as in λαος), try inserting λ between α and ο (λαλος-like)
    variants.add(base.replace('αο','αλο'));

    // 3) If ends with αος, try αλος (λαός ⇄ λαλός toy)
    if(base.endsWith('αος')) variants.add(base.slice(0,-2) + 'λος');
    if(base.endsWith('αλος')) variants.add(base.slice(0,-3) + 'ος');

    // 4) If starts with λαο-, try λαλo-
    if(base.startsWith('λαο')) variants.add('λαλο' + base.slice(3));

    // Clean empties and identical
    variants.delete(base);
    variants.delete('');

    // Return in a nicer display: keep Greek letters, add tonos suggestion optionally.
    return [...variants].slice(0,10);
  }

  const lexicon = {
    'παος': {lemma:'παός', tags:['-ος','disyllable','long α (claimed)'], note:'Listed by Herodian as rare disyllable in -ος with long α in penult; acute.'},
    'πηος': {lemma:'πηός', tags:['-ος','disyllable','long α (claimed)'], note:'Listed by Herodian; acute. (Homeric citation in Od. κ 441.)'},
    'ναος': {lemma:'ναός', tags:['-ος','disyllable','long α (claimed)'], note:'Listed by Herodian; acute. Often contrasted with νηός.'},
    'νηος': {lemma:'νηός', tags:['-ος','disyllable'], note:'Listed by Herodian alongside ναός; acute.'},
    'λαος': {lemma:'λαός', tags:['-ος','disyllable','long α (claimed)'], note:'Herodian: Homer keeps λαός; later Ionic has ληός. Also folk-etymology from λαλῶ → λαλός → λαός.'},
    'ληος': {lemma:'ληός', tags:['-ος','disyllable'], note:'Later Ionic variant of λαός (per Herodian).'},
    'δαος': {lemma:'Δᾶος', tags:['proper name','-ος'], note:'Herodian: as a proper name it is “βαρύνεται” (toy note: proper names may behave differently).'}
  };

  function prettyTags(tags){
    return tags.map(t => `• ${t}`).join('\n');
  }

  function run(){
    const raw = inp.value;
    const trimmed = stripSpaces(raw);

    if(!trimmed){
      analysis.textContent = 'Type a Greek word above (e.g. λαός, ναός, παός)…';
      accentOut.textContent = '—';
      lambdaOut.textContent = '—';
      return;
    }

    const word = lastGreekWord(trimmed);
    const matchKey = optNormalize.checked ? normalizeForMatch(word) : stripSpaces(word).toLowerCase();

    const info = lexicon[matchKey] || null;
    const syll = countVowelGroups(word);
    const os = endsWithOs(word);

    let a = '';
    a += `Input (last Greek word): ${word}\n`;
    a += `Match key: ${matchKey}\n`;
    a += `Looks like -ος? ${os ? 'yes' : 'no'}\n`;
    a += `Vowel-groups (toy syllable count): ${syll}\n`;

    if(info){
      a += `\nRecognized: ${info.lemma}\n`;
      a += `${prettyTags(info.tags)}\n`;
      a += `Note: ${info.note}\n`;
      if(matchKey==='λαος'){
        a += `\nPassage hook: Homeric λαός vs later Ionic ληός.\n`;
      }
    } else {
      a += `\nNot in the tiny built-in list. (That’s fine—try the toy rules below.)\n`;
    }

    analysis.textContent = a;

    // Accent suggestion
    if(optAutoAccent.checked){
      let acc = '';
      if(os && syll===2){
        const {out, note} = addAcuteToFirstVowel(stripSpaces(word));
        acc += `${out}\n`;
        acc += `\n${note}\n`;
        acc += `\nCaution: Herodian’s claim is narrower ("pure" disyllables in -ος with long α in the penult; excluding proper names/adjectives). This toy does not truly measure vowel length.`;
      } else {
        acc += 'No accent suggestion: the toy rule only triggers for disyllables ending in -ος.';
      }
      accentOut.textContent = acc;
    } else {
      accentOut.textContent = 'Accent suggestion is turned off.';
    }

    // Lambda loss
    if(optLambdaLoss.checked){
      const vars = lambdaVariants(word);
      let out = '';
      out += `Base (normalized): ${normalizeForMatch(word)}\n`;
      out += `\nVariants (toy):\n`;
      if(vars.length===0){
        out += '— (no obvious λ-play generated)';
      } else {
        for(const v of vars){
          // show an accented version too, for fun
          const accented = (endsWithOs(v) && countVowelGroups(v)===2) ? addAcuteToFirstVowel(v).out : v;
          out += `• ${v}` + (accented!==v ? `  →  ${accented}` : '') + `\n`;
        }
      }
      out += `\nWhy? Herodian reports etymological/phonological stories involving λ (e.g. λαλῶ → λαλός → λαός; and “lengthening by loss of λ”). This panel lets you poke at that idea.`;
      lambdaOut.textContent = out;
    } else {
      lambdaOut.textContent = 'λ-loss / λ-insertion play is turned off.';
    }
  }

  run();
})();

