const $ = (sel, el=document) => el.querySelector(sel);
const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

// --- Greek helpers (toy-level) ---
const COMBINING = /[\u0300-\u036f]/g;

function stripCombining(s){
  return s.normalize('NFD').replace(COMBINING,'').normalize('NFC');
}

function stripAccentMarks(s){
  // Remove tonos/oxia, varia, perispomeni, dialytika-tonos etc by stripping combining marks.
  // Keep base letters and breathing-less forms.
  return stripCombining(s);
}

function normalizeGreek(s){
  return (s||'')
    .trim()
    .replace(/\s+/g,' ')
    .normalize('NFC');
}

function endsWithAny(w, arr){
  return arr.find(e => w.endsWith(e)) || null;
}

function guessEnding(base){
  // Work on accentless, lowercase.
  const w = stripAccentMarks(base).toLowerCase();
  // Accept both with iota subscript variants? Not needed here.
  const end = endsWithAny(w, ['αιος','αυος','οιος']);
  return end;
}

function countVowelGroups(w){
  // Very rough syllable proxy: count vowel groups.
  // Treat αι, αυ, οι, ει, ου as one group.
  const s = stripAccentMarks(w).toLowerCase();
  const groups = s.match(/(αι|αυ|οι|ει|ου|υι|ηυ|ωυ|[αεηιουωυ])/g);
  return groups ? groups.length : 0;
}

function applyAccent(word, ending, accentType){
  // accentType: 'acute' on penult (iota of -αιος/-οιος), or 'circ' on first vowel (for -αυος and the ποῖος set)
  // We operate on accentless lowercase, then try to preserve original casing by simple heuristic.
  const original = word;
  let w = stripAccentMarks(normalizeGreek(word));
  const isTitle = /^\p{Lu}/u.test(w);
  w = w.toLowerCase();

  const acute = '\u0301';
  const circumflex = '\u0342';

  function addMarkAtIndex(str, idx, mark){
    // Insert combining mark after the character at idx.
    const arr = Array.from(str.normalize('NFD'));
    // Need to find the idx-th base letter in NFC string; easiest: work in NFC codepoints.
    const chars = Array.from(str);
    const before = chars.slice(0, idx+1).join('');
    const after = chars.slice(idx+1).join('');
    return (before.normalize('NFD') + mark + after.normalize('NFD')).normalize('NFC');
  }

  let out = w;

  if(ending === 'αιος'){
    // λαιός: acute on iota of αι (penult vowel)
    const pos = out.lastIndexOf('αι');
    if(pos >= 0){
      // add acute to iota (second char of the digraph)
      out = addMarkAtIndex(out, pos+1, acute);
    }
  } else if(ending === 'οιος'){
    // σμοιός: acute on iota of οι
    const pos = out.lastIndexOf('οι');
    if(pos >= 0){
      out = addMarkAtIndex(out, pos+1, acute);
    }
  } else if(ending === 'αυος'){
    // ναῦος / αὗος: toy uses circumflex on alpha of αυ
    const pos = out.lastIndexOf('αυ');
    if(pos >= 0){
      out = addMarkAtIndex(out, pos, circumflex);
    }
  }

  // Override for "grave/recessive-looking" set: ποῖος etc.
  if(accentType === 'circFirst'){
    // Put circumflex on the first vowel of the word (usually ο in ποιος/toios/koios/oios)
    // Find first vowel char.
    const vowels = new Set(['α','ε','η','ι','ο','υ','ω']);
    const chars = Array.from(out);
    let idx = -1;
    for(let i=0;i<chars.length;i++){
      if(vowels.has(stripAccentMarks(chars[i]).toLowerCase())){ idx = i; break; }
    }
    if(idx >= 0){
      out = stripAccentMarks(out);
      out = addMarkAtIndex(out, idx, circumflex);
    }
  }

  if(isTitle){
    out = out.charAt(0).toUpperCase() + out.slice(1);
  }
  // If original had final sigma ς, keep it.
  if(/ς$/.test(original)){
    out = out.replace(/σ$/,'ς');
  }
  return out;
}

function decideRule(word, ending, kind){
  const bare = stripAccentMarks(normalizeGreek(word)).toLowerCase();
  const syl = countVowelGroups(bare);

  // Exception list from passage.
  const specialOios = new Set(['ποιος','τοιος','κοιος','οιος']);

  let okDisyll = (syl === 2);
  let applied = null;
  let explanation = '';

  if(!ending){
    return {ok:false, syl, applied:null, explanation:"No match for -αιος / -αυος / -οιος endings (toy scope)."};
  }

  if(ending === 'αυος' && bare === 'αγαυος'){
    okDisyll = false;
    explanation = "Herodian notes ἀγαυός is trisyllabic; the toy won’t force the disyllable rule.";
    return {ok:false, syl, applied:null, explanation};
  }

  if(!okDisyll){
    explanation = `Syllable-guess is ${syl}; Herodian’s rule here targets disyllables. (Toy stops.)`;
    return {ok:false, syl, applied:null, explanation};
  }

  if(ending === 'αιος'){
    if(kind === 'proper'){
      applied = 'acutePenult';
      explanation = "-αιος disyllable: Herodian says non-proper words are acute; proper names can differ (toy still shows the common acute pattern).";
    } else {
      applied = 'acutePenult';
      explanation = "-αιος disyllable (not proper): accent with acute (e.g. λαιός, φαιός, βαιός, σκαιός).";
    }
  }

  if(ending === 'αυος'){
    applied = 'circFirst';
    explanation = "-αυος disyllable: Herodian says it is ‘heavy’ (βαρύνεται). Toy renders this as a circumflex on the first vowel (e.g. ναῦος, αὗος).";
  }

  if(ending === 'οιος'){
    if(kind === 'interrog' || specialOios.has(bare)){
      applied = 'circFirst';
      explanation = "-οιος disyllable: usually acute, but ποῖος/τοῖος/κοῖος/οἷος (interrog./relative-like) are ‘heavy’ (βαρύνεται).";
    } else if(kind === 'proper'){
      applied = 'acutePenult';
      explanation = "-οιος disyllable: Herodian exempts proper names; toy still shows the default acute pattern for comparison.";
    } else {
      applied = 'acutePenult';
      explanation = "-οιος disyllable (default): accent with acute (e.g. σμοιός, σκλοιός, δοιός…).";
    }
  }

  return {ok:true, syl, applied, explanation};
}

function accentWord(word, ending, applied){
  if(applied === 'acutePenult'){
    return applyAccent(word, ending, 'acute');
  }
  if(applied === 'circFirst'){
    return applyAccent(word, ending, 'circFirst');
  }
  return stripAccentMarks(word);
}

function swapEnding(word, targetEnding){
  let w = stripAccentMarks(normalizeGreek(word));
  const lower = w.toLowerCase();
  const end = guessEnding(lower);
  if(!end) return null;
  const stem = lower.slice(0, lower.length - end.length);
  let out = stem + targetEnding;
  // restore final sigma if needed
  if(/ς$/.test(w)) out = out.replace(/σ$/,'ς');
  return out;
}

function getKind(){
  const r = $$('input[name="kind"]').find(x=>x.checked);
  return r ? r.value : 'common';
}

function render(){
  const inp = $('#inp').value;
  const w = normalizeGreek(inp);
  const kind = getKind();

  if(!w){
    $('#outWord').textContent = '—';
    $('#outMeta').textContent = 'Enter a word to see a suggested accent and rule.';
    $('#detEnd').textContent = '—';
    $('#detSyl').textContent = '—';
    $('#detAcc').textContent = '—';
    $('#cmpAios').textContent = '—';
    $('#cmpAuos').textContent = '—';
    $('#cmpOios').textContent = '—';
    return;
  }

  const ending = guessEnding(w);
  const decision = decideRule(w, ending, kind);

  $('#detEnd').textContent = ending ? `-${ending}` : '—';
  $('#detSyl').textContent = decision.syl ? String(decision.syl) : '—';

  if(!decision.ok){
    $('#outWord').textContent = stripAccentMarks(w);
    $('#outMeta').textContent = decision.explanation;
    $('#detAcc').textContent = '—';
  } else {
    const accented = accentWord(w, ending, decision.applied);
    $('#outWord').textContent = accented;
    $('#outMeta').textContent = decision.explanation;
    $('#detAcc').textContent = decision.applied === 'acutePenult' ? 'acute (on penult vowel)' : '“heavy” (toy: circumflex on first vowel)';
  }

  // Compare forms
  const aios = swapEnding(w,'αιος');
  const auos = swapEnding(w,'αυος');
  const oios = swapEnding(w,'οιος');

  function accentForEnding(form, end){
    if(!form) return '—';
    const d = decideRule(form, end, kind);
    if(!d.ok) return stripAccentMarks(form);
    return accentWord(form, end, d.applied);
  }

  $('#cmpAios').textContent = aios ? accentForEnding(aios,'αιος') : '—';
  $('#cmpAuos').textContent = auos ? accentForEnding(auos,'αυος') : '—';
  $('#cmpOios').textContent = oios ? accentForEnding(oios,'οιος') : '—';
}

// --- Wire up ---
$('#btn').addEventListener('click', render);
$('#btnClear').addEventListener('click', () => { $('#inp').value=''; render(); $('#inp').focus(); });
$('#inp').addEventListener('input', () => {
  // live update, but debounce lightly
  window.clearTimeout(window.__t);
  window.__t = window.setTimeout(render, 120);
});
$('#inp').addEventListener('keydown', (e)=>{ if(e.key==='Enter'){ e.preventDefault(); render(); }});
$$('.chip').forEach(b=>b.addEventListener('click', ()=>{ $('#inp').value = b.dataset.w; render(); $('#inp').focus(); }));
$$('input[name="kind"]').forEach(r=>r.addEventListener('change', render));

render();

