(() => {
  const $ = (sel) => document.querySelector(sel);

  const elIn = $('#in');
  const elNorm = $('#norm');
  const elBare = $('#bare');
  const elReaccent = $('#reaccent');
  const elRule = $('#rule');
  const elSyll = $('#syll');
  const elManual = $('#manual');
  const elNote = $('#note');

  // Examples drawn from the passage (plus a couple of obvious variants)
  const examples = [
    'οἶος','Οἰός','Μοῖος','Βοῖος','Κοῖος',
    'λεῖος','μεῖος','θεῖος','πλεῖος','ῥεῖος','χρεῖος','Κεῖος','Τεῖος','Κέϊος','Τέϊος',
    'νειός','Βεῦος',
    'πῖος','Πῖος','Χῖος','δῖος','Θρῖος','Γρῖος','Φθῖος','Φλῖος','κριός','Κρῖος','ἰός'
  ];

  const chips = $('#chips');
  examples.forEach(w => {
    const b = document.createElement('button');
    b.className = 'chip';
    b.type = 'button';
    b.textContent = w;
    b.addEventListener('click', () => { elIn.value = w; analyze(); });
    chips.appendChild(b);
  });

  // --- Greek utilities (toy-level) ---
  const combining = {
    acute: '\u0301',
    grave: '\u0300',
    circ:  '\u0342', // perispomeni
    diaer: '\u0308',
    smooth:'\u0313',
    rough: '\u0314',
    macron:'\u0304',
    breve: '\u0306',
    iotaSub:'\u0345'
  };

  const ACCENT_MARKS = new Set([combining.acute, combining.grave, combining.circ]);
  const DIACRITICS = new Set([
    combining.acute, combining.grave, combining.circ,
    combining.diaer, combining.smooth, combining.rough,
    combining.macron, combining.breve, combining.iotaSub
  ]);

  function nfd(s){ return s.normalize('NFD'); }
  function nfc(s){ return s.normalize('NFC'); }

  function stripPunct(s){
    // keep Greek letters + combining marks + spaces
    return s.replace(/[··.,;:!?"'“”‘’()\[\]{}<>«»—–…]/g,'');
  }

  function stripAccentsOnly(s){
    const d = nfd(s);
    let out = '';
    for (const ch of d) out += ACCENT_MARKS.has(ch) ? '' : ch;
    return nfc(out);
  }

  function stripAllDiacritics(s){
    const d = nfd(s);
    let out = '';
    for (const ch of d) out += DIACRITICS.has(ch) ? '' : ch;
    return nfc(out);
  }

  function normalizeInput(s){
    return stripPunct(s).trim().replace(/\s+/g,' ');
  }

  function isVowelBase(ch){
    return 'αεηιουωΑΕΗΙΟΥΩ'.includes(ch);
  }

  function splitIntoVowelGroups(wordBare){
    // wordBare should be NFC, ideally without accents (but may have breathings/diaeresis)
    // We'll work in NFD and treat any vowel base as nucleus; consecutive vowels count as one group.
    const d = nfd(wordBare);
    // Build grapheme-ish clusters: base + following combining marks
    const clusters = [];
    let cur = '';
    for (const ch of d) {
      if (cur === '') { cur = ch; continue; }
      const isComb = DIACRITICS.has(ch);
      if (isComb) cur += ch;
      else { clusters.push(cur); cur = ch; }
    }
    if (cur) clusters.push(cur);

    const groups = [];
    let g = '';
    let inV = false;
    for (const cl of clusters) {
      const base = cl[0];
      const v = isVowelBase(base);
      if (v) {
        if (!inV) { if (g) groups.push(g); g = cl; inV = true; }
        else { g += cl; }
      } else {
        g += cl;
        inV = false;
      }
    }
    if (g) groups.push(g);

    // Now syllables are approximated by splitting at vowel groups boundaries.
    // We'll create syllables by cutting after each vowel group.
    const sylls = [];
    let buf = '';
    for (const part of groups) {
      buf += part;
      // if part contains a vowel base, end syllable
      if ([...part].some(c => isVowelBase(c))) {
        sylls.push(nfc(buf));
        buf = '';
      }
    }
    if (buf) {
      // trailing consonants attach to last syllable
      if (sylls.length) sylls[sylls.length-1] = nfc(nfd(sylls[sylls.length-1]) + nfd(buf));
      else sylls.push(nfc(buf));
    }
    return sylls.filter(x => x.length);
  }

  function addAccentToSyllable(wordBare, syllIndexFromLeft, accentType){
    // Place combining accent on the first vowel base in the chosen syllable.
    const sylls = splitIntoVowelGroups(wordBare);
    if (!sylls.length) return wordBare;
    const idx = Math.max(0, Math.min(syllIndexFromLeft, sylls.length-1));

    const mark = combining[accentType] || combining.acute;

    const newSylls = sylls.map((sy, i) => {
      if (i !== idx) return stripAccentsOnly(sy);
      const d = nfd(stripAccentsOnly(sy));
      let out = '';
      let placed = false;
      for (let j=0;j<d.length;j++){
        const ch = d[j];
        out += ch;
        if (!placed && isVowelBase(ch)) {
          // insert accent after vowel base, before any following combining marks already in syllable
          out += mark;
          placed = true;
        }
      }
      return nfc(out);
    });

    return newSylls.join('');
  }

  function guessRule(word){
    const w = normalizeInput(word);
    const bare = stripAccentsOnly(w);
    const lower = stripAllDiacritics(bare).toLowerCase();

    // Special-cased famous contrasts
    if (stripAllDiacritics(w).toLowerCase() === 'κριος') {
      return { kind:'special', msg:"Special note: Herodian mentions κριός (common noun) as oxytone (acute on ultima).", target:{pos:'ultima', type:'acute'} };
    }
    if (stripAllDiacritics(w).toLowerCase() === 'κριος' && w[0] === 'Κ') {
      // unreachable due to above; keep simple
    }
    if (stripAllDiacritics(w).toLowerCase() === 'κριοσ' || stripAllDiacritics(w).toLowerCase() === 'κριοσ') {
      // no-op
    }

    // Proper name Κρῖος vs κριός
    if (stripAllDiacritics(w).toLowerCase() === 'κριοσ' || stripAllDiacritics(w).toLowerCase() === 'κριος') {
      // handled above
    }
    if (stripAllDiacritics(w).toLowerCase() === 'κριοσ') {
      // no
    }

    if (stripAllDiacritics(w).toLowerCase() === 'κριοσ') {
      // no
