    }

    // Ending-based guesses
    if (lower.endsWith('ειος')) {
      return { kind:'-ειος', msg:"Disyllabic adjectives in -ειος: Herodian says ‘βαρύνεται’ (toy: accent on penult; often realized as circumflex on εῖ).", target:{pos:'penult', type:'circ'} };
    }
    if (lower.endsWith('ευος')) {
      return { kind:'-ευος', msg:"Disyllabic proper names in -ευος: ‘προπερισπᾶται’ (toy: circumflex on antepenult).", target:{pos:'antepenult', type:'circ'} };
    }
    if (lower.endsWith('ιος')) {
      return { kind:'-ιος', msg:"Toy note: many disyllabic masculines in -ιος are written with ι (Herodian mentions this in passing). Accent not fully modeled here.", target:null };
