    const norm = normalizeInput(word);
    const bare = stripAccentsOnly(norm);
    const sylls = splitIntoVowelGroups(bare);
    const g = guessRule(norm);

    let out = bare;
    if (g.target && sylls.length){
      let idx;
      if (g.target.pos === 'ultima') idx = sylls.length - 1;
      else if (g.target.pos === 'penult') idx = Math.max(0, sylls.length - 2);
