      out = addAccentToSyllable(bare, idx, g.target.type);
    }

    return { norm, bare, sylls, guess:g, out };
  }

  function renderSyllButtons(sylls){
    elSyll.innerHTML = '';
    if (!sylls || !sylls.length){
      elSyll.textContent = '—';
      return;
    }
    sylls.forEach((sy, i) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.textContent = sy;
      b.title = 'Accent this syllable';
      b.addEventListener('click', () => {
        const atype = document.querySelector('input[name="atype"]:checked')?.value || 'acute';
        const bare = stripAccentsOnly(normalizeInput(elIn.value));
        const accented = addAccentToSyllable(bare, i, atype);
        elManual.textContent = accented;
      });
      elSyll.appendChild(b);
    });
  }

  function analyze(){
    const val = elIn.value;
    const { norm, bare, sylls, guess, out } = applyGuess(val);

    elNorm.textContent = norm || '—';
    elBare.textContent = bare || '—';
    elReaccent.textContent = out || '—';
    elRule.textContent = guess.msg;

    renderSyllButtons(sylls);
    elManual.textContent = '—';

    // contextual tip
    const low = stripAllDiacritics(norm).toLowerCase();
    if (low.includes('ειος') && low.includes('εϊος')) {
      elNote.textContent = 'You typed a diaeresis form (έϊος). Try “Try ι ⇄ ει” to see a toy contraction-like swap.';
    } else if (low.includes('κειος') || low.includes('τειος')) {
      elNote.textContent = 'Herodian mentions Κεῖος/Τεῖος as contracted from Κέϊος/Τέϊος. Try swapping ι ⇄ ει.';
    } else if (low === 'κριοσ' || low === 'κριος') {
      elNote.textContent = 'Try capitalizing: κριός (common noun) vs Κρῖος (proper name) for the contrast mentioned.';
    } else {
      elNote.textContent = 'Tip: click syllables to test different accent placements, then compare with the toy’s guess.';
    }
  }

  function stripAction(){
    elIn.value = stripAccentsOnly(elIn.value);
    analyze();
  }

  function randomExample(){
    const w = examples[Math.floor(Math.random()*examples.length)];
    elIn.value = w;
    analyze();
  }

  function clearAccent(){
    const bare = stripAccentsOnly(normalizeInput(elIn.value));
    elManual.textContent = bare || '—';
  }

  function swapI(){
    // Toy swap: replace ει <-> ι when it looks like a contraction/spelling variant.
    let s = normalizeInput(elIn.value);
    const bare = stripAccentsOnly(s);
    const low = stripAllDiacritics(bare).toLowerCase();

    let swapped;
    if (low.includes('ει')) {
      swapped = bare.replace(/ει/g,'ι').replace(/Ει/g,'Ι').replace(/ΕΙ/g,'Ι');
    } else {
      // replace iota with ει only in a few contexts to avoid chaos
      swapped = bare.replace(/ι(?=ος\b)/g,'ει').replace(/ι(?=ος$)/g,'ει');
      swapped = swapped.replace(/ι(?=ος\s)/g,'ει');
    }

    elIn.value = swapped;
    analyze();
  }

  $('#analyze').addEventListener('click', analyze);
  $('#strip').addEventListener('click', stripAction);
  $('#random').addEventListener('click', randomExample);
  $('#clearAccent').addEventListener('click', clearAccent);
  $('#swapI').addEventListener('click', swapI);

  elIn.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') analyze();
  });
  elIn.addEventListener('input', () => {
    // light live update
    analyze();
  });

  // init
  elIn.value = 'Χῖος';
  analyze();
})();

passages.gadget_css:
:root{
  --bg:#0f1220;
  --panel:#151a2e;
  --card:#101428;
  --ink:#e9ecff;
  --muted:#b9c0ff;
  --faint:#7f89d6;
  --line:#2a3160;
  --accent:#7cf0c5;
  --accent2:#ffcc66;
  --danger:#ff6b7a;
  --shadow: 0 10px 30px rgba(0,0,0,.35);
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Noto Sans", "Liberation Sans", sans-serif;
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, #1a2050 0%, var(--bg) 55%);color:var(--ink);font-family:var(--sans)}
.wrap{max-width:1100px;margin:0 auto;padding:22px}
.hdr{display:flex;gap:16px;align-items:flex-start;justify-content:space-between;margin-bottom:14px}
h1{font-size:20px;line-height:1.2;margin:0 0 6px 0;letter-spacing:.2px}
.sub{margin:0;color:var(--muted);max-width:78ch}
.panel{background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));border:1px solid var(--line);border-radius:16px;padding:16px;box-shadow:var(--shadow)}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.row.small{margin-top:10px}
.lbl{min-width:60px;color:var(--muted);font-weight:600}
.inp{flex:1;min-width:260px;padding:10px 12px;border-radius:12px;border:1px solid var(--line);background:#0c1022;color:var(--ink);font-size:16px;outline:none}
.inp:focus{border-color:#4b57b8;box-shadow:0 0 0 3px rgba(124,240,197,.12)}
.btn{padding:10px 12px;border-radius:12px;border:1px solid #3a4386;background:#1a2150;color:var(--ink);cursor:pointer;font-weight:650}
.btn:hover{border-color:#5a66d6}
.btn:active{transform:translateY(1px)}
.btn.ghost{background:transparent;border-color:var(--line);color:var(--muted)}
.btn:disabled{opacity:.45;cursor:not-allowed}
.hint{color:var(--muted);background:rgba(124,240,197,.08);border:1px dashed rgba(124,240,197,.35);padding:10px 12px;border-radius:12px;max-width:100%}
.chip{display:inline-block;padding:2px 8px;border-radius:999px;border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.06);font-family:var(--mono);font-size:13px;color:var(--ink)}
.grid{display:grid;grid-template-columns:1.2fr 1fr;gap:12px;margin-top:12px}
@media (max-width: 900px){.grid{grid-template-columns:1fr}}
.card{background:rgba(0,0,0,.18);border:1px solid var(--line);border-radius:16px;padding:14px}
.card h2{margin:0 0 10px 0;font-size:15px;color:var(--muted);letter-spacing:.2px}
.outMain{font-family:var(--mono);font-size:20px;padding:10px 12px;border-radius:12px;background:#0b0f22;border:1px solid rgba(255,255,255,.08);min-height:48px;display:flex;align-items:center}
.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:10px}
.outAlt{margin-top:10px;color:var(--muted);font-size:13px;line-height:1.35}
.outRule{color:var(--ink);line-height:1.4}
.details{margin-top:10px;color:var(--muted)}
.details summary{cursor:pointer;color:var(--muted)}
.details ul{margin:8px 0 0 18px}
.small{font-size:13px;color:var(--muted);line-height:1.35}
.sandbox{border:1px solid rgba(255,255,255,.10);border-radius:14px;overflow:hidden}
.sbRow{display:grid;grid-template-columns:110px 1fr;gap:0;border-top:1px solid rgba(255,255,255,.08)}
.sbRow:first-child{border-top:none}
.sbLbl{padding:10px 12px;background:rgba(255,255,255,.04);color:var(--muted);font-weight:650}
.sbVal{padding:10px 12px;font-family:var(--mono);font-size:18px}
.mini{margin-top:10px;color:var(--faint);font-size:13px}
.ft{margin-top:12px;padding-top:10px;border-top:1px solid rgba(255,255,255,.08)}
mark{background:rgba(255,204,102,.18);color:var(--ink);padding:0 4px;border-radius:6px;border:1px solid rgba(255,204,102,.25)}
.badge{display:inline-block;margin-left:8px;padding:2px 8px;border-radius:999px;font-size:12px;border:1px solid rgba(255,255,255,.14);color:var(--muted)}
.badge.ok{border-color:rgba(124,240,197,.35);color:var(--accent)}
.badge.warn{border-color:rgba(255,204,102,.35);color:var(--accent2)}
.badge.no{border-color:rgba(255,107,122,.35);color:var(--danger)}

