const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const outMain = $('#outMain');
const outAlt = $('#outAlt');
const outRule = $('#outRule');
const sbA = $('#sbA');
const sbB = $('#sbB');

const btnAnalyze = $('#btnAnalyze');
const btnRandom = $('#btnRandom');
const btnClear = $('#btnClear');
const btnToggle = $('#btnToggle');
const btnStrip = $('#btnStrip');
const btnCopy = $('#btnCopy');

// --- Unicode helpers ---
function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

const COMBINING = {
  acute: '\u0301',
  grave: '\u0300',
  circumflex: '\u0342',
  diaeresis: '\u0308',
  smooth: '\u0313',
  rough: '\u0314',
  iotaSub: '\u0345',
  macron: '\u0304',
  breve: '\u0306'
};

const ACCENTS = new Set([COMBINING.acute, COMBINING.grave, COMBINING.circumflex]);

function stripDiacritics(s){
  // remove all combining marks
  return nfc(nfd(s).replace(/\p{M}+/gu,''));
}

function isGreekLetter(ch){
  return /[\u0370-\u03FF\u1F00-\u1FFF]/u.test(ch);
}

function isVowelBase(ch){
  // base vowel letters (including final sigma not relevant)
  return /[αεηιουωΑΕΗΙΟΥΩ]/u.test(ch);
}

function lastVowelIndexNFD(sNFD){
  // returns index in code units of the last base vowel in NFD string
  for(let i=sNFD.length-1;i>=0;i--){
    const ch = sNFD[i];
    if(isVowelBase(ch)) return i;
  }
  return -1;
}

function findLastAccentTarget(s){
  // Find last vowel that already bears an accent; else last vowel.
  const sN = nfd(s);
  // scan for accent marks; track the base vowel they belong to
  let lastAccentedVowelPos = -1;
  for(let i=0;i<sN.length;i++){
    const ch = sN[i];
    if(ACCENTS.has(ch)){
      // walk back to find the base letter
      let j=i-1;
      while(j>=0 && /\p{M}/u.test(sN[j])) j--; // should not happen in NFD, but safe
      if(j>=0 && isVowelBase(sN[j])) lastAccentedVowelPos = j;
    }
  }
  if(lastAccentedVowelPos !== -1) return { sN, pos: lastAccentedVowelPos, hadAccent:true };
  const lv = lastVowelIndexNFD(sN);
  return { sN, pos: lv, hadAccent:false };
}

function getCombiningAfter(sN, pos){
  // collect combining marks immediately after base at pos
  let i = pos+1;
  let marks = '';
  while(i < sN.length && /\p{M}/u.test(sN[i])){ marks += sN[i]; i++; }
  return { marks, end:i };
}

function setAccentOnVowel(s, posNFD, accentMark){
  const sN = nfd(s);
  if(posNFD < 0) return s;
  const { marks, end } = getCombiningAfter(sN, posNFD);
  // remove existing accent marks, keep other marks (breathing, diaeresis, iota sub, etc.)
  const kept = [...marks].filter(m => !ACCENTS.has(m)).join('');
  const newMarks = kept + accentMark;
  const out = sN.slice(0, posNFD+1) + newMarks + sN.slice(end);
  return nfc(out);
}

function toggleAccent(s){
  const t = findLastAccentTarget(s);
  if(t.pos < 0) return {a:s, b:s, note:'No vowel found.'};
  const { marks } = getCombiningAfter(t.sN, t.pos);
  const hasAcute = marks.includes(COMBINING.acute);
  const hasGrave = marks.includes(COMBINING.grave);
  const hasCirc = marks.includes(COMBINING.circumflex);

  let b;
  if(hasCirc){
    // flip circumflex -> acute (toy choice)
    b = setAccentOnVowel(s, t.pos, COMBINING.acute);
  } else if(hasAcute){
    b = setAccentOnVowel(s, t.pos, COMBINING.grave);
  } else if(hasGrave){
    b = setAccentOnVowel(s, t.pos, COMBINING.acute);
  } else {
    // no accent: add acute
    b = setAccentOnVowel(s, t.pos, COMBINING.acute);
  }
  return {a:s, b, note:null};
}

// --- Rule guesser (very simplified heuristics) ---
function countSyllablesRough(word){
  // rough: count vowel groups in stripped form
  const w = stripDiacritics(word).toLowerCase();
  const groups = w.match(/[αεηιουω]+/g);
  return groups ? groups.length : 0;
}

function endsWithAny(w, arr){
  return arr.some(suf => w.endsWith(suf));
}

function startsWithVowel(w){
  const s = stripDiacritics(w).trim();
  if(!s) return false;
  const first = s[0];
  return /[αεηιουωΑΕΗΙΟΥΩ]/u.test(first);
}

function suggestAccent(word){
  const raw = word.trim();
  const w = stripDiacritics(raw).toLowerCase();
  const syl = countSyllablesRough(raw);

  // default
  let rule = {label:'No clear match', badge:'no', text:'This toy did not recognize a matching pattern from the passage. Try a disyllable like νοος, πλεος, Δρυος, σαος, θεος, ἑος.'};
  let suggested = raw;

  // special lexical notes
  const lex = {
    'πυος': {type:'oxytone', note:'Herodian notes πυός as oxytone (acute on last).'},
    'νυος': {type:'oxytone', note:'Herodian notes νυός (fem. “nymph”) as oxytone.'},
    'βιος': {type:'ambiguous', note:'Herodian contrasts βίος “life” vs βιός “bow”.'}
  };

  // helper: put accent on last vowel (oxytone) or penult (recessive-ish for disyllables)
  function accentLast(form, mark){
    const t = findLastAccentTarget(form);
    return setAccentOnVowel(form, t.pos, mark);
  }
  function accentPenult(form, mark){
    const sN = nfd(form);
    // find last two vowels
    let vowelPositions = [];
    for(let i=0;i<sN.length;i++) if(isVowelBase(sN[i])) vowelPositions.push(i);
    if(vowelPositions.length === 0) return form;
    const pos = vowelPositions.length >= 2 ? vowelPositions[vowelPositions.length-2] : vowelPositions[vowelPositions.length-1];
    return setAccentOnVowel(form, pos, mark);
  }

  // -υος disyllables
  if(syl === 2 && w.endsWith('υος')){
    if(w === 'πυος'){
      rule = {label:'Exception: πυός', badge:'warn', text: lex['πυος'].note};
      suggested = accentLast(stripDiacritics(raw), COMBINING.acute);
    } else if(w === 'νυος'){
      rule = {label:'Exception: νυός', badge:'warn', text: lex['νυος'].note};
      suggested = accentLast(stripDiacritics(raw), COMBINING.acute);
    } else {
      rule = {label:'-υος disyllable (masc.) → “grave”/recessive', badge:'ok', text:'Herodian: disyllabic masculines in -υος are barytone (not oxytone). The toy suggests an accent on the penult (shown with acute for visibility; toggle to see grave).'};
      suggested = accentPenult(stripDiacritics(raw), COMBINING.acute);
    }
  }

  // -οος / -εος disyllables starting with consonant (not only θ)
  if(syl === 2 && (w.endsWith('οος') || w.endsWith('εος'))){
    if(startsWithVowel(raw)){
      // ἑός
      rule = {label:'Starts with vowel → acute (ἑός)', badge:'ok', text:'Herodian: ἑός is oxytone because it begins with a vowel.'};
      suggested = accentLast(stripDiacritics(raw), COMBINING.acute);
    } else {
      // θεός/θοός special mention
      if(w === 'θεος' || w === 'θοος'){
        rule = {label:'Special note: θεός / θοός', badge:'warn', text:'Herodian treats θεός and θοός as special (as if from θ alone). The toy still suggests a barytone-style accent for play.'};
      } else {
        rule = {label:'-οος / -εος disyllable (consonant-initial) → “grave”/recessive', badge:'ok', text:'Herodian: disyllables in -οος/-εος beginning with a consonant are barytone. The toy suggests penult accent (toggle to see grave).'};
      }
      suggested = accentPenult(stripDiacritics(raw), COMBINING.acute);
    }
  }

  // -ος disyllables with “dichronon” short → barytone (toy approximation)
  if(syl === 2 && w.endsWith('ος') && !endsWithAny(w, ['υος','οος','εος'])){
    // approximate: if contains αο sequence like σαος, treat as the passage’s example
    if(/αο/.test(w) || w === 'σαος'){
      rule = {label:'-ος disyllable like σάος → “grave”/recessive (approx.)', badge:'ok', text:'Herodian: disyllables in -ος with a dichronon that is short are barytone; example σάος/Σάος. The toy recognizes αο-patterns like σαος and suggests penult accent.'};
      suggested = accentPenult(stripDiacritics(raw), COMBINING.acute);
    }
  }

  // lexical: βιος ambiguity
  if(w === 'βιος'){
    rule = {label:'Lexical contrast: βίος vs βιός', badge:'warn', text: lex['βιος'].note + ' Try toggling or manually placing the accent.'};
    suggested = accentPenult(stripDiacritics(raw), COMBINING.acute);
  }

  return {suggested, rule};
}

function render(){
  const text = inp.value.trim();
  if(!text){
    outMain.textContent = '—';
    outAlt.textContent = '';
    outRule.textContent = '—';
    sbA.textContent = '—';
    sbB.textContent = '—';
    btnToggle.disabled = true;
    btnStrip.disabled = true;
    btnCopy.disabled = true;
    return;
  }

  const { suggested, rule } = suggestAccent(text);
  outMain.textContent = suggested;

  const toggled = toggleAccent(suggested);
  sbA.textContent = toggled.a;
  sbB.textContent = toggled.b;

  outRule.innerHTML = `<div><mark>${escapeHtml(rule.label)}</mark><span class="badge ${rule.badge}">${rule.badge === 'ok' ? 'match' : (rule.badge === 'warn' ? 'note' : 'no match')}</span></div><div class="small" style="margin-top:8px">${escapeHtml(rule.text)}</div>`;

  const stripped = stripDiacritics(text);
  const strippedSuggested = stripDiacritics(suggested);
  outAlt.innerHTML = `Input (stripped): <span class="chip">${escapeHtml(stripped)}</span> &nbsp; Suggested (stripped): <span class="chip">${escapeHtml(strippedSuggested)}</span>`;

  btnToggle.disabled = false;
  btnStrip.disabled = false;
  btnCopy.disabled = false;
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

btnAnalyze.addEventListener('click', render);
inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') render(); });

btnToggle.addEventListener('click', ()=>{
  const current = outMain.textContent;
  const t = toggleAccent(current);
  outMain.textContent = t.b;
  sbA.textContent = t.b;
  sbB.textContent = toggleAccent(t.b).b; // show next flip as preview
});

btnStrip.addEventListener('click', ()=>{
  inp.value = stripDiacritics(inp.value);
  render();
});

btnCopy.addEventListener('click', async ()=>{
  const txt = outMain.textContent;
  try{
    await navigator.clipboard.writeText(txt);
    btnCopy.textContent = 'Copied';
    setTimeout(()=>btnCopy.textContent='Copy output', 700);
  } catch {
    // fallback: select input and copy
    inp.focus();
    inp.select();
    document.execCommand('copy');
  }
});

btnClear.addEventListener('click', ()=>{
  inp.value='';
  render();
  inp.focus();
});

const examples = [
  'σαος','Σαος','Ἴος','Τίος','Χίος','Κίος','Δρυος','Φλυος','πυος','νυος','νοος','γοος','ῥοος','πλοος','θροος','φλοος','κοος','χνοος','φλεος','Κεος','Τεος','πλεος','νεος','ζοος','σοος','ἑος','θεος','θοος','βιος','βιός','βίος'
];
btnRandom.addEventListener('click', ()=>{
  const pick = examples[Math.floor(Math.random()*examples.length)];
  inp.value = pick;
  render();
  inp.focus();
});

// initial
render();

