const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const outWord = $('#outWord');
const outMeta = $('#outMeta');
const outRules = $('#outRules');
const outCycle = $('#outCycle');

const optStrip = $('#optStrip');
const optAttic = $('#optAttic');

const examples = [
  'Κωιος', 'Κῷος', 'σῷος', 'Λῷος', 'Πτῷος',
  'κλωος', 'κλῳος', 'ζωος', 'Τρωος',
  'υιος', 'γυιος', 'υἱός',
  'αγλαος', 'ἀγλαός', 'ταναος', 'κεραος',
  'Θηβαος', 'αρχαος', 'Αλκαος', 'παλαος', 'Αχαος',
  'ιλαος', 'Πιταος'
];

// --- Greek helpers (toy-grade) ---
const COMBINING = {
  acute: '\u0301',
  circumflex: '\u0342',
  grave: '\u0300',
  diaeresis: '\u0308',
  smooth: '\u0313',
  rough: '\u0314',
  iotasub: '\u0345'
};

const ACCENT_MARKS = new Set([COMBINING.acute, COMBINING.circumflex, COMBINING.grave]);

function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripAccentsKeepBreathings(s){
  // remove only accent marks (acute/circumflex/grave), keep breathings/diaeresis/iota-sub
  const d = nfd(s);
  let out = '';
  for (const ch of d){
    if (!ACCENT_MARKS.has(ch)) out += ch;
  }
  return nfc(out);
}

function stripAllDiacritics(s){
  // remove all combining marks
  return nfc(nfd(s).replace(/\p{M}+/gu,''));
}

function isGreekLetter(ch){
  return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(ch);
}

function tokenizeGreekLetters(s){
  // returns array of "letter clusters" (base + combining marks)
  const d = nfd(s);
  const clusters = [];
  let cur = '';
  for (const ch of d){
    if (isGreekLetter(ch) && !/\p{M}/u.test(ch)){
      if (cur) clusters.push(cur);
      cur = ch;
    } else if (/\p{M}/u.test(ch)){
      cur += ch;
    } else {
      if (cur) clusters.push(cur);
      cur = '';
      // ignore non-greek for accent placement; keep as separate cluster
      clusters.push(ch);
    }
  }
  if (cur) clusters.push(cur);
  return clusters;
}

function clusterHasAccent(cluster){
  const d = nfd(cluster);
  for (const ch of d) if (ACCENT_MARKS.has(ch)) return true;
  return false;
}

function removeAccentFromCluster(cluster){
  const d = nfd(cluster);
  let out = '';
  for (const ch of d){
    if (!ACCENT_MARKS.has(ch)) out += ch;
  }
  return out;
}

function addAccentToCluster(cluster, type){
  // add combining mark after base letter (keep other marks)
  const d = nfd(cluster);
  const base = d[0];
  const rest = d.slice(1).filter(ch => !ACCENT_MARKS.has(ch));
  const mark = type === 'circumflex' ? COMBINING.circumflex : COMBINING.acute;
  return nfc(base + mark + rest.join(''));
}

function greekVowelishBase(ch){
  const base = stripAllDiacritics(ch).toLowerCase();
  return ['α','ε','η','ι','ο','υ','ω'].includes(base);
}

function findVowelClusters(word){
  const clusters = tokenizeGreekLetters(word);
  const idxs = [];
  for (let i=0;i<clusters.length;i++){
    const cl = clusters[i];
    const base = stripAllDiacritics(cl);
    if (base && greekVowelishBase(base[0])) idxs.push(i);
  }
  return {clusters, vowelIdxs: idxs};
}

function endsWithAny(s, arr){
  return arr.some(x => s.endsWith(x));
}

function normalizeForRules(s){
  // lowercase, strip accents (optionally), keep breathings
  let t = s.trim();
  if (!t) return '';
  t = optStrip.checked ? stripAccentsKeepBreathings(t) : t;
  return t;
}

function applyAtticSpelling(s){
  // very rough: remove iota in sequences υι, ωι when user toggles
  // keep diacritics by operating on NFD and removing base iota after υ/ω
  if (!optAttic.checked) return s;
  const d = nfd(s);
  // remove iota base (ι or Ι) when preceded by υ/Υ or ω/Ω (ignoring combining marks)
  let out = '';
  let lastBase = '';
  for (let i=0;i<d.length;i++){
    const ch = d[i];
    if (/\p{M}/u.test(ch)){
      out += ch;
      continue;
    }
    const base = ch;
    const low = base.toLowerCase();
    if ((low === 'ι') && (lastBase.toLowerCase() === 'υ' || lastBase.toLowerCase() === 'ω')){
      // skip this iota base; also skip any combining marks that immediately follow it
      // (they'll be handled by loop; but we should not attach them to nothing)
      // So: do nothing here; combining marks will still come—prevent by skipping them too.
      // We'll lookahead and skip marks.
      i++;
      while (i < d.length && /\p{M}/u.test(d[i])) i++;
      i--; // compensate for for-loop increment
      continue;
    }
    out += base;
    lastBase = base;
  }
  return nfc(out);
}

function suggestAccent(word){
  const raw = word;
  let w = normalizeForRules(raw);
  w = applyAtticSpelling(w);

  const wBare = stripAllDiacritics(w).toLowerCase();

  const fired = [];
  let accentType = null; // 'acute' | 'circumflex'
  let target = 'last'; // 'firstVowel' | 'lastVowel' | 'penultVowel'

  // Exception list from passage (toy)
  const acuteExceptions = new Set(['κλωος','κλοιoς','κλῳος','ζωος','ζῳος','τρωος','τρῳος']);

  // Rule A: -υιος acute
  if (endsWithAny(wBare, ['υιος'])){
    accentType = 'acute';
    target = 'lastVowel';
    fired.push('Ends in -υιος → acute (υἱός, γυιός).');
  }

  // Rule B: disyllables in -ωος with written iota → circumflex (toy: detect ωι/ῳ)
  if (!accentType && endsWithAny(wBare, ['ωος'])){
    // detect presence of iota written: ωι or ῳ (omega+iota-sub) somewhere before -ος
    const d = nfd(w);
    const hasOmegaIota = /ωι/i.test(stripAllDiacritics(w)) || d.includes(COMBINING.iotasub);

    if (acuteExceptions.has(wBare)){
      accentType = 'acute';
      target = 'lastVowel';
      fired.push('Exception set (κλῳός/ζῳός/Τρῳός) → acute on the last vowel.');
    } else if (hasOmegaIota){
      accentType = 'circumflex';
      target = 'firstVowel';
      fired.push('Disyllable in -ωος with written ι (ωι/ῳ) → circumflex (toy puts it on the first vowel).');
    } else {
      // fallback: treat as acute on last vowel
      accentType = 'acute';
      target = 'lastVowel';
      fired.push('Ends in -ωος but no written ι detected → default to acute (toy fallback).');
    }
  }

  // Rule C: trisyllables ...-αος (simple -ος with α in penult) → acute unless antepenult long
  if (!accentType && endsWithAny(wBare, ['αος'])){
    // crude "long" detection: if word contains η/ω or diphthongs αι/ει/οι/ου/υι/αυ/ευ/ηυ in the antepenult area
    // We'll just check for any long-ish vowel in the first half.
    const longish = /(η|ω|αι|ει|οι|ου|αυ|ευ|ηυ)/.test(wBare);
    if (longish){
      accentType = 'acute';
      target = 'penultVowel';
      fired.push('...-αος with a likely long element somewhere → toy avoids antepenult and accents penult (very rough).');
    } else {
      accentType = 'acute';
      target = 'lastVowel';
      fired.push('Simple trisyllable ...-αος → acute (ἀγλαός, ἀλαός, κεραός, ταναός).');
    }

    // Aeolic label if looks like -βαος/-χαος etc.
    if (/(θηβαος|αρχαος|αλκαος|παλαος|αχαος)/.test(wBare)){
      fired.push('Looks like an Aeolic “lack of ι” type (Θήβαος, ἄρχαος, etc.) → label only; accent still toy-rule.');
    }
  }

  // Default: if nothing matches, keep as-is or add acute on last vowel
  if (!accentType){
    accentType = 'acute';
    target = 'lastVowel';
    fired.push('No specific pattern matched → default acute on last vowel (toy default).');
  }

  // Place accent
  const {clusters, vowelIdxs} = findVowelClusters(w);
  if (vowelIdxs.length === 0){
    return {result: w, fired, meta: {note:'No vowels detected.'}, cycle: []};
  }

  // remove existing accents if optStrip is on (already stripped), else remove only if we are about to add a new one
  for (let i=0;i<clusters.length;i++){
    if (clusterHasAccent(clusters[i])) clusters[i] = removeAccentFromCluster(clusters[i]);
  }

  let idx;
  if (target === 'firstVowel') idx = vowelIdxs[0];
  else if (target === 'penultVowel') idx = vowelIdxs[Math.max(0, vowelIdxs.length-2)];
  else idx = vowelIdxs[vowelIdxs.length-1];

  clusters[idx] = addAccentToCluster(clusters[idx], accentType);
  const result = clusters.join('');

  // Build cycle variants: acute/circumflex on last vowel and on first vowel
  const cycle = [];
  const bases = [
    {t:'last', i:vowelIdxs[vowelIdxs.length-1]},
    {t:'penult', i:vowelIdxs[Math.max(0, vowelIdxs.length-2)]},
    {t:'first', i:vowelIdxs[0]}
  ];
  const types = ['acute','circumflex'];
  for (const b of bases){
    for (const ty of types){
      const c2 = clusters.map(cl => removeAccentFromCluster(cl));
      c2[b.i] = addAccentToCluster(c2[b.i], ty);
      cycle.push(`${ty.padEnd(10)} @ ${b.t.padEnd(6)} → ${c2.join('')}`);
    }
  }

  const meta = {
    normalized: w,
    bare: wBare,
    vowels: vowelIdxs.length,
    chosen: `${accentType} on ${target}`
  };

  return {result, fired, meta, cycle};
}

function render(){
  const text = inp.value;
  const cleaned = text.trim();
  if (!cleaned){
    outWord.textContent = '—';
    outMeta.textContent = '—';
    outRules.innerHTML = '<li>—</li>';
    outCycle.textContent = '—';
    return;
  }

  const {result, fired, meta, cycle} = suggestAccent(cleaned);
  outWord.textContent = result;
  outMeta.textContent = `normalized: ${meta.normalized}\nplain:      ${meta.bare}\nvowels:     ${meta.vowels}\nchoice:     ${meta.chosen}`;
  outRules.innerHTML = fired.map(x => `<li>${escapeHtml(x)}</li>`).join('');
  outCycle.textContent = cycle.join('\n');
}

function escapeHtml(s){
  return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

let cycleIndex = 0;
function cycleAccents(){
  const text = inp.value.trim();
  if (!text) return;
  const {cycle} = suggestAccent(text);
  if (!cycle.length) return;
  cycleIndex = (cycleIndex + 1) % cycle.length;
  // parse the right side after arrow
  const line = cycle[cycleIndex];
  const m = line.split('→');
  if (m.length === 2){
    outWord.textContent = m[1].trim();
    outMeta.textContent = outMeta.textContent + `\ncycle:      ${line.split('→')[0].trim()}`;
  }
}

async function copyResult(){
  const t = outWord.textContent;
  if (!t || t === '—') return;
  try{
    await navigator.clipboard.writeText(t);
    $('#btnCopy').textContent = 'Copied';
    setTimeout(()=>$('#btnCopy').textContent='Copy result', 900);
  } catch(e){
    // fallback: select input
    inp.focus();
    inp.select();
  }
}

$('#btn').addEventListener('click', render);
$('#btnRnd').addEventListener('click', () => {
  const ex = examples[Math.floor(Math.random()*examples.length)];
  inp.value = ex;
  render();
});
$('#btnCycle').addEventListener('click', cycleAccents);
$('#btnCopy').addEventListener('click', copyResult);

inp.addEventListener('keydown', (e)=>{ if (e.key === 'Enter') render(); });
optStrip.addEventListener('change', render);
optAttic.addEventListener('change', render);

// initial
inp.value = 'Κωιος';
render();

