(() => {
  const $ = (sel) => document.querySelector(sel);

  const inp = $('#inp');
  const endingEl = $('#ending');
  const syllEl = $('#syll');
  const ruleEl = $('#rule');
  const outEl = $('#out');
  const miniIn = $('#miniIn');
  const miniOut = $('#miniOut');

  const examples = [
    'Αμφιαραος',
    'Μενελαος',
    'Οινομαος',
    'φωλεος',
    'κολεος',
    'γαλεος',
    'παλεος',
    'Φενεος',
    'ενεος',
    'αφνεος',
    'κυανεος',
    'λαϊνεος',
    'ελαϊνεος'
  ];

  // --- Greek normalization helpers ---
  // Remove combining diacritics (accents, breathings, diaeresis, iota subscript, etc.)
  function stripDiacritics(s) {
    return (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').normalize('NFC');
  }

  // Map plain Greek vowels to accented versions (acute only, toy)
  const acuteMap = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

  function isGreekLetter(ch){
    const code = ch.codePointAt(0);
    return (code >= 0x0370 && code <= 0x03FF) || (code >= 0x1F00 && code <= 0x1FFF);
  }

  function cleanToken(s){
    // Keep Greek letters and apostrophes/dashes/spaces minimally; focus on first token for rules.
    s = (s || '').trim();
    if(!s) return '';
    // take first "word-like" chunk (Greek letters + combining marks already stripped later)
    const m = s.match(/[\u0370-\u03FF\u1F00-\u1FFF]+/);
    return m ? m[0] : '';
  }

  // Very approximate syllable nuclei count: count vowel groups.
  // Treat αι, ει, οι, υι, αυ, ευ, ηυ, ου as one nucleus.
  const diphthongs = ['αι','ει','οι','υι','αυ','ευ','ηυ','ου','ΑΙ','ΕΙ','ΟΙ','ΥΙ','ΑΥ','ΕΥ','ΗΥ','ΟΥ'];

  function countSyllables(word){
    const w = stripDiacritics(word);
    if(!w) return 0;
    let i=0, n=0;
    while(i < w.length){
      const two = w.slice(i,i+2);
      if(diphthongs.includes(two)){
        n++; i+=2; continue;
      }
      const ch = w[i];
      if(vowels.has(ch)) n++;
      i++;
    }
    return n;
  }

  function detectEnding(word){
    const w = stripDiacritics(word);
    const low = w.toLowerCase();
    if(low.endsWith('αος')) return '-αος';
    if(low.endsWith('λεος')) return '-λεος';
    if(low.endsWith('νεος')) return '-νεος';
    return '—';
  }

  function chooseRule(word){
    const end = detectEnding(word);
    const syl = countSyllables(word);

    // Return {target, label}
    if(end === '-αος' && syl > 3){
      return { target: 'antepenult', label: "-αος, >3 syllables → antepenult (προπαροξύτονον)" };
    }
    if(end === '-λεος' && syl === 3){
      return { target: 'ultima', label: "simple trisyllable -λεος → ultima (ὀξύτονον)" };
    }
    if(end === '-νεος' && syl > 2){
      return { target: 'ultima', label: "-νεος, >2 syllables → ultima (ὀξύτονον)" };
    }
    // fallback: do nothing special
    return { target: null, label: "no matching toy-rule (leaving unaccented)" };
  }

  function accentOnSyllable(word, target){
    const original = cleanToken(word);
    if(!original) return '';

    const w = stripDiacritics(original);

    // Find vowel nuclei positions (index of vowel to accent within nucleus)
    // For diphthongs, accent the second vowel (common convention for acute placement in toy).
    const nuclei = [];
    let i=0;
    while(i < w.length){
      const two = w.slice(i,i+2);
      if(diphthongs.includes(two)){
        nuclei.push(i+1); // accent second char
        i += 2;
        continue;
      }
      if(vowels.has(w[i])) nuclei.push(i);
      i++;
    }

    if(nuclei.length === 0) return w;

    let idx;
    if(target === 'ultima') idx = nuclei.length - 1;
    else if(target === 'penult') idx = nuclei.length - 2;
    else if(target === 'antepenult') idx = nuclei.length - 3;
    else return w;

    if(idx < 0) idx = 0;

    const pos = nuclei[idx];
    const ch = w[pos];
    const accented = acuteMap[ch] || ch;

    return w.slice(0,pos) + accented + w.slice(pos+1);
  }

  function applyMain(){
    const token = cleanToken(inp.value);
    const end = detectEnding(token);
    const syl = countSyllables(token);
    const rule = chooseRule(token);

    endingEl.textContent = end;
    syllEl.textContent = syl ? String(syl) : '—';
    ruleEl.textContent = rule.label;

    const out = rule.target ? accentOnSyllable(token, rule.target) : stripDiacritics(token);
    outEl.textContent = out || '—';

    miniIn.textContent = token || '—';
    miniOut.textContent = out || '—';
  }

  // Buttons
  $('#btnApply').addEventListener('click', applyMain);
  $('#btnRandom').addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inp.value = ex;
    applyMain();
  });
  $('#btnClear').addEventListener('click', () => {
    inp.value = '';
    endingEl.textContent = '—';
    syllEl.textContent = '—';
    ruleEl.textContent = '—';
    outEl.textContent = '—';
    miniIn.textContent = '—';
    miniOut.textContent = '—';
    inp.focus();
  });

  // Target practice
  document.querySelectorAll('.chip').forEach(btn => {
    btn.addEventListener('click', () => {
      const token = cleanToken(inp.value);
      miniIn.textContent = token || '—';
      if(!token){ miniOut.textContent = '—'; return; }
      const target = btn.getAttribute('data-target');
      miniOut.textContent = accentOnSyllable(token, target);
    });
  });

  // Live update on Enter
  inp.addEventListener('keydown', (e) => {
    if(e.key === 'Enter') applyMain();
  });

  // Seed
  inp.value = 'Αμφιαραος';
  applyMain();
})();

