passages.gadget_js:
const $ = (sel) => document.querySelector(sel);
const inp = $('#inp');
const out = $('#out');
const baseBox = $('#baseBox');
const pleoBox = $('#pleoBox');
const meterLine = $('#meterLine');

const tonos = {
  acute: '\u0301',
  grave: '\u0300',
  circumflex: '\u0342',
  diaeresis: '\u0308'
};

function nfd(s){ return (s||'').normalize('NFD'); }
function nfc(s){ return (s||'').normalize('NFC'); }

function stripDiacriticsKeepLetters(s){
  // remove combining marks
  return nfc(nfd(s).replace(/[\u0300-\u036f]/g,''));
}

function hasAccent(s){
  const d = nfd(s);
  return /[\u0300\u0301\u0342]/.test(d);
}

function lastVowelIndex(letters){
  const vowels = 'αεηιουωΑΕΗΙΟΥΩ';
  for(let i=letters.length-1;i>=0;i--){
    if(vowels.includes(letters[i])) return i;
  }
  return -1;
}

function syllableCount(letters){
  // toy syllable count: count vowel groups
  const vowels = 'αεηιουωΑΕΗΙΟΥΩ';
  let c=0, prevV=false;
  for(const ch of letters){
    const isV = vowels.includes(ch);
    if(isV && !prevV) c++;
    prevV = isV;
  }
  return c;
}

function accentOnVowel(word, which){
  // which: 'ultima' | 'penult' | 'antepenult'
  const base = stripDiacriticsKeepLetters(word);
  const letters = Array.from(base);
  const vowels = [];
  const vowelSet = 'αεηιουωΑΕΗΙΟΥΩ';
  for(let i=0;i<letters.length;i++) if(vowelSet.includes(letters[i])) vowels.push(i);
  if(vowels.length===0) return base;
  let target;
  if(which==='ultima') target = vowels[vowels.length-1];
  else if(which==='penult') target = vowels[Math.max(0,vowels.length-2)];
  else target = vowels[Math.max(0,vowels.length-3)];

  // add acute combining mark after the vowel
  letters[target] = letters[target] + tonos.acute;
  return nfc(letters.join(''));
}

function guessRule(word){
  const raw = (word||'').trim();
  const base = stripDiacriticsKeepLetters(raw);
  const lower = base.toLowerCase();

  // special-cases from passage
  if(lower === 'ἐτεος' || lower === 'ετεος'){
    return {rule:'Special: ἐτεός', target:'ultima', why:'Herodian: ἐτεός keeps final acute (from ἐτός + added ι).', badge:'ok'};
  }

  if(lower.endsWith('τεος')){
    return {rule:'-τεος', target:'penult', why:'Herodian: words in -τεος are usually paroxytone (accent on penult), unless possessive / plēonasm.', badge:'ok'};
  }

  if(lower.endsWith('εος')){
    // could be plēonasm -εός preserving final acute
    return {rule:'-εος (plēonasm?)', target:'ultima', why:'Herodian: adding ε in -ος nouns can preserve final acute: κενός→κενεός, ἀδελφός→ἀδελφεός.', badge:'warn'};
  }

  if(lower.endsWith('αλεος')){
    const syl = syllableCount(base);
    if(syl>=4){
      return {rule:'-αλεος (4+ syllables)', target:'penult', why:'Herodian: -αλεος derivatives over three syllables tend to be paroxytone.', badge:'ok'};
    }
    return {rule:'-αλεος', target:'penult', why:'Toy default: -αλεος tends to be paroxytone.', badge:'warn'};
  }

  if(lower.endsWith('οσ') || lower.endsWith('ος')){
    return {rule:'-ος noun (generic)', target:'penult', why:'No specific rule triggered; toy defaults to penult for many -ος words.', badge:'warn'};
  }

  return {rule:'(no ending match)', target:'penult', why:'Toy could not match an ending; defaulting to penult accent.', badge:'bad'};
}

function badgeSpan(kind){
  if(kind==='ok') return '<span class="badge b-ok">rule hit</span>';
  if(kind==='warn') return '<span class="badge b-warn">guess</span>';
  return '<span class="badge b-bad">weak</span>';
}

function setMeter(target){
  // ultima -> right, penult -> middle, antepenult -> left
  let pos='0%';
  if(target==='ultima') pos='66%';
  else if(target==='penult') pos='33%';
  else pos='0%';
  meterLine.style.setProperty('--pos', pos);
}

function analyze(){
  const w = inp.value.trim();
  if(!w){
    out.innerHTML = '<div class="note">Type a word above (or click a sample).</div>';
    baseBox.textContent = '—';
    pleoBox.textContent = '—';
    setMeter('penult');
    return;
  }

  const g = guessRule(w);
  const suggested = accentOnVowel(w, g.target);
  const plain = stripDiacriticsKeepLetters(w);
  const syl = syllableCount(plain);

  setMeter(g.target);

  out.innerHTML = `
    <div class="kv">
      <div class="k">Input</div><div class="v"><span class="mono">${escapeHtml(w)}</span></div>
      <div class="k">Stripped</div><div class="v"><span class="mono">${escapeHtml(plain)}</span></div>
      <div class="k">Syllables (toy)</div><div class="v">${syl}</div>
      <div class="k">Matched</div><div class="v">${escapeHtml(g.rule)} ${badgeSpan(g.badge)}</div>
      <div class="k">Accent suggestion</div><div class="v"><span class="mono">${escapeHtml(suggested)}</span></div>
      <div class="k">Why</div><div class="v">${escapeHtml(g.why)}</div>
    </div>
    <p class="note">If your input already had accents, the toy ignores them and re-accentuates the <i>letters-only</i> form.</p>
  `;

  baseBox.textContent = plain;
  pleoBox.textContent = '—';
}

function makePleo(){
  const w = stripDiacriticsKeepLetters(inp.value.trim());
  if(!w){ return; }

  // Insert epsilon before final -ος if present; otherwise before final -ο if present.
  let made = w;
  if(w.endsWith('ος')){
    made = w.slice(0,-2) + 'ε' + 'ος';
  } else if(w.endsWith('ός')){
    // if user typed tonos as precomposed, stripping removed it; keep simple
    made = w.slice(0,-2) + 'ε' + 'ος';
  } else if(w.endsWith('ο')){
    made = w.slice(0,-1) + 'εο';
  } else {
    // fallback: add ε before last vowel
    const letters = Array.from(w);
    const i = lastVowelIndex(letters);
    if(i>=0) letters.splice(i+1,0,'ε');
    made = letters.join('');
  }

  const accented = accentOnVowel(made, 'ultima');
  pleoBox.textContent = accented;

  // also update meter to show final accent
  setMeter('ultima');
}

function resetAll(){
  inp.value='';
  analyze();
}

function escapeHtml(s){
  return String(s)
    .replaceAll('&','&amp;')
    .replaceAll('<','&lt;')
    .replaceAll('>','&gt;')
    .replaceAll('"','&quot;')
    .replaceAll("'",'&#039;');
}

$('#btnGo').addEventListener('click', analyze);
inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') analyze(); });

document.querySelectorAll('.chip').forEach(b=>{
  b.addEventListener('click', ()=>{
    inp.value = b.getAttribute('data-sample');
    analyze();
  });
});

$('#btnAddE').addEventListener('click', makePleo);
$('#btnReset').addEventListener('click', resetAll);

// initial
analyze();

