passages.gadget_js:
const $ = (sel) => document.querySelector(sel);

const examples = [
  {w:"Ἀχελώϊος", about:"Herodian’s example: Ἀχελώϊος → Ἀχελῷος"},
  {w:"ὑπερώϊον", about:"Herodian’s example: ὑπερώϊον → ὑπερῷον"},
  {w:"αἰζήϊος", about:"Mentioned in the passage as a proposed source-form"},
  {w:"Ἀχελώιος", about:"Same idea, without diaeresis"},
  {w:"ὑπερώιον", about:"Same idea, without diaeresis"}
];

// --- Polytonic helpers (minimal, toy-level) ---
const COMBINING = {
  acute: "\u0301",
  grave: "\u0300",
  circumflex: "\u0342",
  diaeresis: "\u0308",
  smooth: "\u0313",
  rough: "\u0314",
  iotaSub: "\u0345"
};

function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripCombining(s){
  return nfd(s).replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function hasAnyAccent(cluster){
  const d = nfd(cluster);
  return d.includes(COMBINING.acute) || d.includes(COMBINING.grave) || d.includes(COMBINING.circumflex);
}

function accentType(cluster){
  const d = nfd(cluster);
  if(d.includes(COMBINING.circumflex)) return 'circumflex';
  if(d.includes(COMBINING.acute)) return 'acute';
  if(d.includes(COMBINING.grave)) return 'grave';
  return 'none';
}

function removeAccentMarks(cluster){
  return nfd(cluster)
    .replace(new RegExp(`[${COMBINING.acute}${COMBINING.grave}${COMBINING.circumflex}]`, 'g'), '')
    .normalize('NFC');
}

function applyCircumflexToVowel(vowelCluster){
  // Put circumflex on the first base vowel in the cluster.
  const d = nfd(vowelCluster);
  // remove acute/grave/circumflex first
  const cleaned = d.replace(new RegExp(`[${COMBINING.acute}${COMBINING.grave}${COMBINING.circumflex}]`, 'g'), '');
  // insert circumflex after first vowel letter
  // Greek vowels (basic + omega/eta etc.) in NFD are base letters.
  const m = cleaned.match(/^[\u0370-\u03FF\u1F00-\u1FFF]/);
  if(!m) return nfc(cleaned);
  // Find first Greek letter and add circumflex after it (before other combining marks)
  // Strategy: split into first base char + rest
  const first = cleaned[0];
  const rest = cleaned.slice(1);
  return nfc(first + COMBINING.circumflex + rest);
}

function detectPattern(s){
  const d = nfd(s);
  const hasDia = d.includes(COMBINING.diaeresis);
  const plain = stripCombining(s);
  const hasOi = plain.includes('ωιο') || plain.includes('ωιo') || plain.includes('ωι') || plain.includes('ειο') || plain.includes('ειο');
  const hasOmegaIotaOmicron = plain.includes('ωιο');
  const hasEpsilonIotaOmicron = plain.includes('ειο') || plain.includes('εϊο');
  return {hasDia, hasOi, hasOmegaIotaOmicron, hasEpsilonIotaOmicron};
}

function contractToy(input){
  // Toy contractions:
  // 1) ώϊο / ώιο  ->  ῷο (circumflex on ω)
  // 2) έϊο / έιο  ->  εῖο (circumflex on ι? historically on ει; we approximate by making "εῖο")
  // 3) ωϊον -> ῷον ; ωϊος -> ῷος ; ωιος -> ῷος (toy)
  // Keep other letters.

  let s = nfd(input);

  // Normalize iota with diaeresis to plain iota for matching, but keep original for display later.
  // We'll match on base letters ignoring combining marks.
  const base = stripCombining(input);

  // Find the first occurrence of omega + iota + (omicron|alpha|epsilon) and contract.
  // We'll do a simple scan on base string and then map back to original by approximate index.

  function replaceAtBase(baseStr, start, len, replacement){
    return baseStr.slice(0,start) + replacement + baseStr.slice(start+len);
  }

  let b = base;
  let notes = [];

  // Prefer ωιο / ωιo sequences
  const idxWio = b.indexOf('ωιο');
  if(idxWio !== -1){
    b = replaceAtBase(b, idxWio, 3, 'ῷο');
    notes.push("Toy contraction: ωιο → ῷο (circumflex). (Herodian: acute+grave → circumflex)");
  } else {
    // ωι + ον/ος
    const idxWion = b.indexOf('ωιον');
    const idxWios = b.indexOf('ωιος');
    if(idxWion !== -1){
      b = replaceAtBase(b, idxWion, 4, 'ῷον');
      notes.push("Toy contraction: ωιον → ῷον.");
    } else if(idxWios !== -1){
      b = replaceAtBase(b, idxWios, 4, 'ῷος');
      notes.push("Toy contraction: ωιος → ῷος.");
    }
  }

  // Epsilon+iota+omicron: ειο -> εῖο (toy)
  const idxEio = b.indexOf('ειο');
  if(idxEio !== -1){
    b = replaceAtBase(b, idxEio, 3, 'εῖο');
    notes.push("Toy contraction: ειο → εῖο.");
  }

  // Now try to preserve an accent: if the original had an acute/grave on the omega before iota, put circumflex on ω in the replacement.
  // Since we replaced with precomposed ῷ, we’re already showing circumflex.

  return {out: b, notes};
}

function lengthenToy(input){
  // Replace epsilon in εο (with or without accents) by eta.
  // Work in NFD to catch accented epsilon.
  let d = nfd(input);
  // Match: epsilon (any combining marks) + omicron (any combining marks)
  // We'll do a conservative approach: find base sequence 'ε' then later 'ο' with only combining marks between.
  // Simpler: strip combining to find 'εο' positions, then rebuild by naive replacement on stripped form.
  const base = stripCombining(input);
  let b = base;
  const idx = b.indexOf('εο');
  if(idx !== -1){
    b = b.slice(0, idx) + 'ηο' + b.slice(idx+2);
    return {out:b, changed:true};
  }
  return {out:base, changed:false};
}

function renderDetect(s){
  const det = detectPattern(s);
  const lines = [];
  lines.push(`diaeresis present: ${det.hasDia ? 'yes' : 'no'}`);
  lines.push(`contains ωιο / ειο pattern (rough): ${det.hasOi ? 'maybe' : 'no'}`);
  if(det.hasOmegaIotaOmicron) lines.push('found base sequence: ωιο');
  if(det.hasEpsilonIotaOmicron) lines.push('found base sequence: ειο');
  if(!det.hasOmegaIotaOmicron && !det.hasEpsilonIotaOmicron) lines.push('no target sequence found; try an -ώϊος / -ώϊον form');
  return lines.join('\n');
}

function setExample(){
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#in').value = ex.w;
  $('#detect').textContent = renderDetect(ex.w) + `\nexample: ${ex.about}`;
  $('#out').textContent = '';
  $('#note').textContent = '';
}

function runContract(){
  const input = $('#in').value.trim();
  $('#detect').textContent = renderDetect(input);
  const res = contractToy(input);
  $('#out').textContent = res.out;
  $('#note').textContent = res.notes.length ? res.notes.join(' ') : 'No toy contraction applied (try ωϊο / ωιο or εϊο / ειο).';
}

function runLengthen(){
  const input = $('#len').value.trim();
  const res = lengthenToy(input);
  $('#lenOut').textContent = res.out;
}

function buildChips(){
  const presets = [
    {label:'αἰζεός', val:'αἰζεός'},
    {label:'αἰζηός', val:'αἰζηός'},
    {label:'(try) παληός', val:'παληός'},
    {label:'(try) ἀρχῆος', val:'ἀρχῆος'},
    {label:'(try) Ἀχηός', val:'Ἀχηός'}
  ];
  const host = $('#chips');
  host.innerHTML = '';
  presets.forEach(p => {
    const el = document.createElement('div');
    el.className = 'chip greek';
    el.textContent = p.label;
    el.title = 'Click to load';
    el.addEventListener('click', () => {
      $('#len').value = p.val;
      runLengthen();
    });
    host.appendChild(el);
  });
}

$('#go').addEventListener('click', runContract);
$('#swap').addEventListener('click', setExample);
$('#in').addEventListener('keydown', (e)=>{ if(e.key==='Enter') runContract(); });

$('#lenGo').addEventListener('click', runLengthen);
$('#len').addEventListener('keydown', (e)=>{ if(e.key==='Enter') runLengthen(); });

// init
buildChips();
setExample();
runContract();
runLengthen();

passages.gadget_css:
:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --card:#1d2140;
  --ink:#e9ecff;
  --muted:#b9c0ff;
  --faint:#8b93d6;
  --accent:#7cf0c5;
  --warn:#ffd37a;
  --line:rgba(255,255,255,.12);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Noto Sans", "Liberation Sans", sans-serif;
}

*{box-sizing:border-box}

.wrap{
  font-family:var(--sans);
  color:var(--ink);
  background: radial-gradient(1200px 600px at 20% 0%, rgba(124,240,197,.18), transparent 60%),
              radial-gradient(900px 500px at 90% 10%, rgba(185,192,255,.18), transparent 55%),
              var(--bg);
  padding:18px;
  border-radius:16px;
  max-width:980px;
  margin:0 auto;
}

.hdr{
  display:flex;
  gap:14px;
  align-items:flex-start;
  justify-content:space-between;
  margin-bottom:14px;
}

h1{font-size:18px; margin:0 0 6px 0; letter-spacing:.2px}
.sub{margin:0; color:var(--muted); font-size:13px; line-height:1.35}
.ref{color:var(--warn)}
.greek{font-family: "Noto Serif", "Times New Roman", serif; letter-spacing:.2px}

.chips{display:flex; gap:8px; flex-wrap:wrap; justify-content:flex-end}
.chip{
  border:1px solid var(--line);
  background:rgba(255,255,255,.04);
  color:var(--ink);
  padding:8px 10px;
  border-radius:999px;
  cursor:pointer;
  font-size:12px;
}
.chip.active{border-color:rgba(124,240,197,.55); box-shadow:0 0 0 2px rgba(124,240,197,.12) inset}

.panel{
  background:rgba(255,255,255,.03);
  border:1px solid var(--line);
  border-radius:14px;
  padding:14px;
  box-shadow:var(--shadow);
}

.row{
  display:grid;
  grid-template-columns: 120px 1fr auto auto;
  gap:10px;
  align-items:center;
}
.lbl{font-size:12px; color:var(--muted)}
.inp{
  width:100%;
  padding:10px 12px;
  border-radius:10px;
  border:1px solid var(--line);
  background:rgba(0,0,0,.25);
  color:var(--ink);
  font-size:16px;
  font-family: "Noto Serif", "Times New Roman", serif;
}
.inp:focus{outline:none; border-color:rgba(185,192,255,.55); box-shadow:0 0 0 3px rgba(185,192,255,.12)}

.btn{
  border:1px solid rgba(124,240,197,.35);
  background:rgba(124,240,197,.12);
  color:var(--ink);
  padding:10px 12px;
  border-radius:10px;
  cursor:pointer;
  font-size:13px;
}
.btn:hover{background:rgba(124,240,197,.18)}
.btn.ghost{border-color:var(--line); background:rgba(255,255,255,.04)}
.btn.ghost:hover{background:rgba(255,255,255,.07)}
.btn.small{padding:8px 10px; font-size:12px}

.help{margin:10px 0 0 0}
.help details{border:1px dashed rgba(255,255,255,.18); border-radius:12px; padding:10px 12px; background:rgba(0,0,0,.18)}
.help summary{cursor:pointer; color:var(--muted); font-size:13px}
.help ul{margin:10px 0 0 18px; color:var(--ink); font-size:13px; line-height:1.35}
.tiny{color:var(--faint); font-size:12px; margin:8px 0 0 0}

.out{margin-top:12px; display:grid; grid-template-columns: 1.2fr .8fr; gap:12px; align-items:start}
.card{
  background:var(--card);
  border:1px solid var(--line);
  border-radius:14px;
  padding:12px;
}
.card h2{margin:0 0 10px 0; font-size:14px; color:var(--muted)}

.grid{display:grid; grid-template-columns: 1fr 1fr; gap:10px}
.grid2{display:grid; grid-template-columns: 1fr 1fr; gap:10px}
.k{font-size:11px; color:var(--faint); text-transform:uppercase; letter-spacing:.08em}
.v{font-size:14px; margin-top:4px; font-family:var(--mono); word-break:break-word}
.v.big{font-size:18px; font-family:"Noto Serif", "Times New Roman", serif}

.row2{display:flex; gap:8px; flex-wrap:wrap; align-items:center}
.preview{
  margin-top:10px;
  padding:10px 12px;
  border-radius:12px;
  border:1px solid rgba(185,192,255,.25);
  background:rgba(0,0,0,.22);
  font-size:20px;
  font-family:"Noto Serif", "Times New Roman", serif;
}

.mini{font-size:13px; color:var(--muted)}

.ftr{margin-top:10px}

@media (max-width: 860px){
  .hdr{flex-direction:column}
  .chips{justify-content:flex-start}
  .row{grid-template-columns: 1fr;}
  .out{grid-template-columns: 1fr;}
}

