(() => {
  const $ = (sel, el=document) => el.querySelector(sel);
  const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

  const inp = $('#inp');
  const btn = $('#btn');
  const rand = $('#rand');
  const normEl = $('#norm');
  const syllEl = $('#syll');
  const accEl = $('#accent');
  const whyEl = $('#why');
  const preview = $('#preview');
  const stripBtn = $('#strip');

  const diphCard = $('#diphCard');
  const playCard = $('#playCard');
  const orig2 = $('#orig2');
  const trop = $('#trop');
  const ai2oi = $('#ai2oi');
  const ei2e = $('#ei2e');
  const keepAcc = $('#keepAcc');

  let mode = 'dios';

  const examples = [
    'Αρκάδιος', 'Ῥοδίος', 'Σχεδίος', 'Ὁδίος',
    'ἐρῳδιός', 'αἰγυπιός', 'χαραδριός', 'βομβυλιός',
    'Βοιωτία', 'Λύκηος', 'ὄρηος', 'εὔνηος'
  ];

  // --- Greek helpers ---
  const combiningMarksRE = /[\u0300-\u036f\u1ab0-\u1aff\u1dc0-\u1dff\u20d0-\u20ff\ufe20-\ufe2f]/g;

  function nfd(s){ return (s||'').normalize('NFD'); }
  function nfc(s){ return (s||'').normalize('NFC'); }

  function stripCombining(s){ return nfd(s).replace(combiningMarksRE,''); }

  function stripAccentsButKeepDiaeresis(s){
    // Keep diaeresis (\u0308), remove other combining marks.
    const d = nfd(s);
    let out = '';
    for (const ch of d) {
      const code = ch.codePointAt(0);
      const isComb = (code >= 0x0300 && code <= 0x036F) || (code >= 0x1AB0 && code <= 0x1AFF) || (code >= 0x1DC0 && code <= 0x1DFF) || (code >= 0x20D0 && code <= 0x20FF) || (code >= 0xFE20 && code <= 0xFE2F);
      if (!isComb) out += ch;
      else if (ch === '\u0308') out += ch; // diaeresis
      // else drop
    }
    return nfc(out);
  }

  function lowerGreek(s){
    return s.toLocaleLowerCase('el');
  }

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ','ϊ','ϋ','ΐ','ΰ']);

  function isVowelChar(ch){
    const base = stripAccentsButKeepDiaeresis(ch);
    return vowels.has(lowerGreek(base));
  }

  function tokenizeLetters(s){
    // Keep as NFC, but iterate by codepoints.
    return Array.from(nfc(s));
  }

  function roughSyllabify(word){
    // Very rough: split before each vowel nucleus (including diphthongs), attach preceding consonants.
    // Treat αι, ει, οι, αυ, ευ, ου, ηυ as diphthongs unless diaeresis on second vowel.
    const w = nfc(word.trim());
    if (!w) return [];

    const letters = tokenizeLetters(w);
    const baseLetters = tokenizeLetters(stripAccentsButKeepDiaeresis(w));

    const diph = new Set(['αι','ει','οι','αυ','ευ','ου','ηυ','υι']);

    let sylls = [];
    let cur = '';

    function hasDiaeresisAt(i){
      // check if original letter at i has diaeresis combining mark
      const orig = nfd(letters[i]);
      return orig.includes('\u0308');
    }

    for (let i=0;i<letters.length;i++){
      const ch = letters[i];
      const base = lowerGreek(baseLetters[i] || ch);
      const nextBase = lowerGreek(baseLetters[i+1] || '');

      const v = isVowelChar(ch);
      if (!v){
        cur += ch;
        continue;
      }

      // vowel nucleus begins
      // If previous syllable already has a nucleus, start new syllable.
      // But we build by: if cur already contains a vowel nucleus, push it and start new.
      if (cur && /[αεηιουωϊϋ]/i.test(stripAccentsButKeepDiaeresis(cur).toLocaleLowerCase('el'))){
        sylls.push(cur);
        cur = '';
      }

      // Add vowel, maybe diphthong
      cur += ch;
      if (i+1 < letters.length){
        const pair = base + nextBase;
        const nextIsVowel = isVowelChar(letters[i+1]);
        const dia = hasDiaeresisAt(i+1);
        if (nextIsVowel && !dia && diph.has(pair)){
          cur += letters[i+1];
          i++;
        }
      }
    }

    if (cur) sylls.push(cur);

    // Post-process: move trailing consonants (if any) to next syllable? We skip; toy.
    return sylls;
  }

  function vowelIndexInSyllable(syl){
    // find first vowel char index in syllable
    const chars = tokenizeLetters(syl);
    for (let i=0;i<chars.length;i++) if (isVowelChar(chars[i])) return i;
    return -1;
  }

  function addAcuteToSyllable(word, syllables, targetIdxFromEnd){
    // targetIdxFromEnd: 1=ultima,2=penult,3=antepenult
    if (!syllables.length) return word;
    const idx = syllables.length - targetIdxFromEnd;
    if (idx < 0) return word;

    // Rebuild word from syllables, but add acute to vowel nucleus of target syllable.
    const outSyls = syllables.slice();
    const syl = outSyls[idx];
    const chars = tokenizeLetters(nfd(syl));

    // Find first vowel base letter in NFC syllable, then add combining acute after it.
    const sylNFC = nfc(syl);
    const sylChars = tokenizeLetters(sylNFC);
    const vi = vowelIndexInSyllable(sylNFC);
    if (vi === -1) return word;

    // Insert combining acute after that character in NFD form.
    const before = sylChars.slice(0, vi+1).join('');
    const after = sylChars.slice(vi+1).join('');
    const accented = nfc(nfd(before) + '\u0301' + nfd(after));

    outSyls[idx] = accented;
    return outSyls.join('');
  }

  function suggest(word){
    const raw = word.trim();
    const normalized = nfc(raw);
    const plain = lowerGreek(stripAccentsButKeepDiaeresis(normalized));
    const sylls = roughSyllabify(normalized);

    let suggestion = '—';
    let why = '—';
    let target = null; // 1 ultima, 2 penult, 3 antepenult

    if (mode === 'dios'){
      const endsDios = plain.endsWith('διος');
      const exceptions = new Set(['ροδιος','σχεδιος','οδιος']);
      if (endsDios){
        if (exceptions.has(plain)){
          target = 2;
          why = 'Ends in -διος, but in the toy exception list (Ῥοδίος/Σχεδίος/Ὁδίος) → paroxytone.';
        } else {
          target = 3;
          why = 'Ends in -διος → default proparoxytone (accent on antepenult) per the passage’s generalization.';
        }
      } else {
        target = sylls.length >= 3 ? 3 : (sylls.length === 2 ? 2 : 1);
        why = 'Not a clear -διος word; placing an acute on the “default” (antepenult if possible) just for play.';
      }
    }

    if (mode === 'birds'){
      const endsIos = plain.endsWith('ιος');
      const birdish = new Set(['αιγυπιος','χαραδριος','βομβυλιος','ερωδιος','ρωδιος']);
      if (endsIos && sylls.length > 3){
        target = 1;
        why = 'Bird-name pattern: -ιός with >3 syllables → oxytone (acute on ultima), like αἰγυπιός etc.';
      } else if (birdish.has(plain)){
        target = 1;
        why = 'In the toy bird list → oxytone.';
      } else {
        target = sylls.length >= 2 ? 2 : 1;
        why = 'Not matching the toy bird condition; defaulting to paroxytone for comparison.';
      }
    }

    if (mode === 'diph'){
      // No accent suggestion; show transformation.
      target = null;
      why = 'Diphthong mode focuses on spelling change (tropē), not accent.';
    }

    if (target){
      const baseForAccent = stripAccentsButKeepDiaeresis(normalized);
      const baseSylls = roughSyllabify(baseForAccent);
      suggestion = addAcuteToSyllable(baseForAccent, baseSylls, target);
    }

    return { normalized, sylls, suggestion, why };
  }

  function render(){
    const w = inp.value;
    const { normalized, sylls, suggestion, why } = suggest(w);

    normEl.textContent = normalized ? normalized : '—';
    syllEl.textContent = sylls.length ? sylls.join(' · ') : '—';

    if (mode === 'diph'){
      accEl.textContent = '—';
      preview.textContent = '—';
      whyEl.textContent = 'Use the playground below to rewrite αι/ει.';
      diphCard.hidden = false;
      playCard.hidden = true;
      updateTrophe();
      return;
    }

    diphCard.hidden = true;
    playCard.hidden = false;

    accEl.textContent = suggestion;
    preview.textContent = suggestion;
    whyEl.textContent = why;
  }

  function updateTrophe(){
    const original = inp.value.trim();
    orig2.textContent = original || '—';
    if (!original){
      trop.textContent = '—';
      return;
    }

    let s = original;
    if (!keepAcc.checked) s = stripAccentsButKeepDiaeresis(s);

    // Apply changes on accent-stripped base to avoid missing decomposed sequences.
    // Work in lowercase-insensitive way by doing a simple NFD replace on base letters.
    let d = nfd(s);

    function repPair(from, to){
      // Replace both lowercase and uppercase base sequences in NFD.
      const pairs = [from, from.toUpperCase()];
      for (const p of pairs){
        d = d.replaceAll(p, to);
      }
    }

    if (ai2oi.checked){
      repPair('αι', 'οι');
      repPair('Αι', 'Οι');
      repPair('ΑΙ', 'ΟΙ');
    }
    if (ei2e.checked){
      repPair('ει', 'η');
      repPair('Ει', 'Η');
      repPair('ΕΙ', 'Η');
    }

    trop.textContent = nfc(d);
  }

  // --- UI wiring ---
  btn.addEventListener('click', render);
  inp.addEventListener('keydown', (e) => { if (e.key === 'Enter') render(); });
  inp.addEventListener('input', () => {
    if (mode === 'diph') updateTrophe();
  });

  rand.addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inp.value = ex;
    render();
  });

  $$('.chip').forEach(ch => {
    ch.addEventListener('click', () => {
      $$('.chip').forEach(x => x.classList.remove('active'));
      ch.classList.add('active');
      mode = ch.dataset.mode;
      render();
    });
  });

  $$('#playCard [data-ac]').forEach(b => {
    b.addEventListener('click', () => {
      const w = inp.value.trim();
      if (!w) return;
      const base = stripAccentsButKeepDiaeresis(nfc(w));
      const sylls = roughSyllabify(base);
      const kind = b.dataset.ac;
      const target = kind === 'oxytone' ? 1 : (kind === 'parox' ? 2 : 3);
      const out = addAcuteToSyllable(base, sylls, target);
      preview.textContent = out;
    });
  });

  stripBtn.addEventListener('click', () => {
    const w = inp.value;
    if (!w) return;
    const base = stripAccentsButKeepDiaeresis(nfc(w));
    inp.value = base;
    render();
  });

  [ai2oi, ei2e, keepAcc].forEach(el => el.addEventListener('change', updateTrophe));

  // initial
  inp.value = 'Αρκάδιος';
  render();
})();

