(() => {
  const $ = (sel, el=document) => el.querySelector(sel);
  const inp = $('#inp');
  const result = $('#result');
  const rule = $('#rule');
  const syllBox = $('#syll');

  const chips = $('#chips');
  const examples = [
    'Μαραθωνιος','Κιθαιρωνιος','Απολλωνιος','Ελικωνιος','Σιδωνιος','Βαβυλωνιος','Σικυωνιος','Καλυδωνιος',
    'Ελευσινιος','Σαλαμινιος','Τροιζηνιος','παρθενιος','Χαλκηδονιος','Βιστωνιος',
    'Κλονιος','Ανιος','Κρονιος','Ξενιος'
  ];

  // Tiny exception list from the passage (toy-level)
  // value = desired accent position: 'penult' or 'antepenult'
  const exceptions = new Map([
    ['κλονιος','penult'],
    ['ανιος','antepenult'],
    ['κρονιος','antepenult'],
    ['ξενιος','antepenult'],
  ]);

  // --- Greek helpers ---
  const combining = /[\u0300-\u036f]/g;
  function stripCombining(s){ return s.normalize('NFD').replace(combining,'').normalize('NFC'); }
  function lowerGreek(s){ return s.toLocaleLowerCase('el'); }

  // Rough vowel set (incl. common diacritics stripped)
  const V = new Set(['α','ε','η','ι','ο','υ','ω']);
  const diph = new Set(['αι','ει','οι','υι','αυ','ευ','ηυ','ου']);

  function isVowel(ch){ return V.has(ch); }

  function roughSyllabify(word){
    // Very rough: build syllables by grouping vowel nuclei (diphthongs count as one)
    // and attaching following consonants up to next vowel.
    const w = stripCombining(word);
    const s = [...w];
    const syls = [];
    let i = 0;
    while(i < s.length){
      // skip non-letters
      if(!(/[\p{L}]/u.test(s[i]))){
        i++; continue;
      }
      let onset = '';
      while(i < s.length && /[\p{L}]/u.test(s[i]) && !isVowel(lowerGreek(s[i]))){
        onset += s[i]; i++;
      }
      if(i >= s.length){
        if(syls.length){ syls[syls.length-1] += onset; }
        else if(onset) syls.push(onset);
        break;
      }
      // nucleus
      let nuc = s[i];
      const a = lowerGreek(s[i]);
      const b = (i+1 < s.length) ? lowerGreek(s[i+1]) : '';
      if(i+1 < s.length && diph.has(a+b)){
        nuc = s[i] + s[i+1];
        i += 2;
      } else {
        i += 1;
      }
      // coda: take consonants until next vowel, but leave last consonant for next onset if another vowel follows
      let cons = '';
      let j = i;
      while(j < s.length && /[\p{L}]/u.test(s[j]) && !isVowel(lowerGreek(s[j]))){
        cons += s[j]; j++;
      }
      if(j < s.length){
        // another vowel ahead: keep last consonant for next onset (very naive)
        if(cons.length >= 2){
          const keep = cons.slice(-1);
          const take = cons.slice(0,-1);
          syls.push(onset + nuc + take);
          i = i + take.length;
        } else {
          syls.push(onset + nuc);
        }
      } else {
        // end: take all
        syls.push(onset + nuc + cons);
        i = j;
      }
    }
    return syls.filter(x => x.length);
  }

  function addAcuteToVowelNucleus(syl){
    // Put acute on the first vowel of the syllable (or second char if diphthong)
    // using precomposed where possible.
    const map = {
      'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
      'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
    };
    const chars = [...syl];
    for(let i=0;i<chars.length;i++){
      const base = stripCombining(chars[i]);
      const low = lowerGreek(base);
      if(isVowel(low)){
        // replace this character with acute version if known
        const repl = map[base] || map[chars[i]];
        if(repl){ chars[i] = repl; return chars.join(''); }
        // fallback: add combining acute
        chars[i] = chars[i].normalize('NFD') + '\u0301';
        return chars.join('').normalize('NFC');
      }
    }
    return syl;
  }

  function guessAccent(word){
    const raw = word.trim();
    if(!raw) return null;

    const clean = stripCombining(raw);
    const low = lowerGreek(clean).replace(/[^\p{L}]/gu,'');

    const syls = roughSyllabify(clean);
    const n = syls.length;

    // Determine ending class
    const endsOnnios = low.endsWith('ωνιος') || low.endsWith('ώνιος');
    const endsNios = low.endsWith('νιος') || low.endsWith('νιός') || low.endsWith('νιος');

    // Exception override
    let target = null; // 'antepenult' | 'penult'
    if(exceptions.has(low)) target = exceptions.get(low);

    let appliedRule = '';
    if(!target){
      if(endsOnnios){
        target = 'antepenult';
        appliedRule = "Ends in -ωνιος → usually proparoxytone (antepenult).";
      } else if(endsNios){
        if(n > 3){
          target = 'antepenult';
          appliedRule = "Ends in -νιος and >3 syllables → usually proparoxytone.";
        } else {
          target = 'antepenult';
          appliedRule = "Ends in -νιος but ≤3 syllables: rule is shakier; toy defaults to antepenult.";
        }
      } else {
        target = (n >= 3) ? 'antepenult' : 'penult';
        appliedRule = "Not a -ωνιος/-νιος target; toy uses a simple fallback.";
      }
    } else {
      appliedRule = "Exception/cheat-list from the passage.";
    }

    // Compute index
    let idx = null;
    if(target === 'antepenult') idx = n - 3;
    if(target === 'penult') idx = n - 2;
    if(idx == null || idx < 0) idx = Math.max(0, n-1);

    const sylsAcc = syls.slice();
    sylsAcc[idx] = addAcuteToVowelNucleus(sylsAcc[idx]);
    const outWord = sylsAcc.join('');

    return { raw, clean, low, syls, sylsAcc, idx, target, appliedRule, outWord };
  }

  function render(g){
    if(!g){
      result.textContent = '—';
      rule.textContent = '—';
      syllBox.textContent = '—';
      return;
    }
    result.textContent = g.outWord;

    const endTag = (g.low.endsWith('ωνιος') ? '-ωνιος' : (g.low.endsWith('νιος') ? '-νιος' : '—'));
    const pos = (g.target === 'antepenult') ? 'antepenult (proparoxytone)' : 'penult (paroxytone)';
    rule.innerHTML = `<span class="mono">${endTag}</span> · Accent guess: <b>${pos}</b>. <span class="small">${g.appliedRule}</span>`;

    syllBox.innerHTML = '';
    g.syls.forEach((s, i) => {
      const d = document.createElement('div');
      d.className = 'syl' + (i===g.idx ? ' acc' : '');
      d.innerHTML = `<span class="mono">${g.sylsAcc[i]}</span><span class="tag">${i===g.idx?'accented':''}</span>`;
      syllBox.appendChild(d);
    });
  }

  function doGuess(){
    render(guessAccent(inp.value));
  }

  $('#btnGuess').addEventListener('click', doGuess);
  inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') doGuess(); });
  $('#btnClear').addEventListener('click', ()=>{ inp.value=''; inp.focus(); render(null); });

  // Chips
  examples.forEach(w => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip mono';
    b.textContent = w;
    b.addEventListener('click', ()=>{ inp.value = w; doGuess(); });
    chips.appendChild(b);
  });

  // --- Bonus maker: -διος ---
  const stem = $('#stem');
  const addE = $('#addE');
  const lenO = $('#lenO');
  const makerOut = $('#makerOut');
  const makerNote = $('#makerNote');

  function makeDios(){
    const raw = stem.value.trim();
    if(!raw){ makerOut.textContent='—'; makerNote.textContent='—'; return; }
    let w = stripCombining(raw);
    let low = lowerGreek(w).replace(/[^\p{L}]/gu,'');

    // toy stem handling: remove final -ω if present
    if(low.endsWith('ω')){ w = w.slice(0,-1); low = low.slice(0,-1); }

    // If ends with -οιζ- or -οζ-, form -οϊδιος / -οδιος (toy)
    let base = w;
    let note = '';

    // lengthen ο→ω in the last ο before the ending (very naive)
    if(lenO.checked){
      // replace last ο with ω
      const chars = [...base];
      for(let i=chars.length-1;i>=0;i--){
        const c = stripCombining(chars[i]);
        if(lowerGreek(c)==='ο') { chars[i] = (c==='Ο')?'Ω':'ω'; break; }
      }
      base = chars.join('');
      note += "lengthened ο→ω; ";
    }

    let derived = base + 'διος';

    // If the base ends with οι, try to show diaeresis on ι in -οΐδιος style
    // (Herodian: ῥοίζω → ῥοΐδιος)
    const baseStripped = stripCombining(base);
    const baseLow = lowerGreek(baseStripped);
    if(baseLow.endsWith('οι')){
      // insert diaeresis on iota of the diphthong in the output: ...οΐδιος
      derived = base.slice(0,-1) + 'ΐ' + 'διος';
      note += "kept ι with diaeresis (οΐ) to show it’s not a diphthong; ";
    }

    if(addE.checked){
      derived = 'ἐ' + derived;
      note += "added ἐ-; ";
    }

    makerOut.textContent = derived;
    makerNote.textContent = note ? ('Toy steps: ' + note.replace(/; $/,'.')) : 'Toy steps: (none).';
  }

  $('#btnMake').addEventListener('click', makeDios);
  stem.addEventListener('keydown', (e)=>{ if(e.key==='Enter') makeDios(); });

  // Seed
  inp.value = 'Μαραθωνιος';
  doGuess();
})();

