(() => {
  const $ = (sel, el=document) => el.querySelector(sel);
  const inEl = $('#in');
  const outEl = $('#out');
  const metaEl = $('#meta');
  const exEl = $('#examples');

  const examples = [
    'Ροδιος','Σαμιος','Κυπριος','Αιγυπτιος','Δηλιος','Πυλιος',
    'Φοινικιος','Κιλικιος','Αιθιοπιος','Θρηικιος','εντοπιος','εκτοπιος','επιχωριος','εγκωμιος'
  ];

  // --- Greek accent utilities (very small, heuristic) ---
  const tonosMap = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };

  // Remove common polytonic/monotonic diacritics by NFD stripping.
  function stripDiacritics(s){
    return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  }

  function isGreekLetter(ch){
    return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(ch);
  }

  const vowelRe = /[αεηιουωΑΕΗΙΟΥΩ]/;
  const diphthongs = ['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ΑΙ','ΕΙ','ΟΙ','ΥΙ','ΑΥ','ΕΥ','ΟΥ','ΗΥ'];

  function isVowel(ch){ return vowelRe.test(ch); }

  function startsWithAny(s, arr){
    for(const a of arr){ if(s.startsWith(a)) return a; }
    return null;
  }

  // Syllabify by vowel nuclei: each syllable = onset+vowel-group+following consonants until next vowel-group.
  function syllabify(word){
    const w = word;
    const nuclei = [];
    let i=0;
    while(i < w.length){
      const rest = w.slice(i);
      const dip = startsWithAny(rest, diphthongs);
      if(dip){
        nuclei.push({start:i, len:dip.length});
        i += dip.length;
        continue;
      }
      const ch = w[i];
      if(isVowel(ch)) nuclei.push({start:i, len:1});
      i++;
    }
    if(nuclei.length === 0) return [{text:w, start:0, end:w.length, nucleusStart:-1, nucleusLen:0}];

    const sylls = [];
    for(let k=0;k<nuclei.length;k++){
      const n = nuclei[k];
      const start = (k===0) ? 0 : nuclei[k-1].start + nuclei[k-1].len;
      const end = (k===nuclei.length-1) ? w.length : nuclei[k+1].start;
      sylls.push({
        text: w.slice(start, end),
        start, end,
        nucleusStart: n.start,
        nucleusLen: n.len
      });
    }
    // Merge leading consonants into first syllable (already included), but ensure boundaries are sensible.
    return sylls;
  }

  function addAcuteOnFirstVowelOfSyllable(word, syll){
    if(syll.nucleusStart < 0) return word;
    const idx = syll.nucleusStart;
    const ch = word[idx];
    const accented = tonosMap[ch] || ch;
    return word.slice(0, idx) + accented + word.slice(idx+1);
  }

  function accent(word, mode){
    const original = word;
    const clean = stripDiacritics(original);
    const sylls = syllabify(clean);

    let targetIndex;
    if(mode === 'oxytone'){
      targetIndex = sylls.length - 1;
    } else {
      // proparoxytone preference
      if(sylls.length >= 3) targetIndex = sylls.length - 3;
      else if(sylls.length === 2) targetIndex = sylls.length - 2;
      else targetIndex = 0;
    }

    const out = addAcuteOnFirstVowelOfSyllable(clean, sylls[targetIndex]);

    // Build a tiny syllable display
    const sylTexts = sylls.map((s, i) => {
      const t = clean.slice(s.start, s.end);
      return (i===targetIndex) ? '['+t+']' : t;
    }).join('·');

    return {out, clean, sylls, targetIndex, sylTexts};
  }

  function looksLikeIos(word){
    const w = stripDiacritics(word).toLowerCase();
    return w.endsWith('ιος') || w.endsWith('ιος'.normalize('NFC'));
  }

  function currentMode(){
    const r = document.querySelector('input[name="mode"]:checked');
    return r ? r.value : 'proparox';
  }

  function render(){
    const w = inEl.value.trim();
    if(!w){
      outEl.textContent = '—';
      metaEl.textContent = '';
      return;
    }
    const mode = currentMode();
    const res = accent(w, mode);
    outEl.textContent = res.out;

    const noteBits = [];
    noteBits.push(`Syllables: ${res.sylTexts}`);
    if(mode==='proparox'){
      noteBits.push('Rule toy: “-ιος ethnics/toponyms → proparoxytone” (Herodian 1.118)');
      if(!looksLikeIos(w)) noteBits.push('Note: input does not look like -ιος; still applying proparoxytone heuristic.');
    } else {
      noteBits.push('Oxytone mode: acute on ultima (for comparison with e.g. μονιός).');
    }
    metaEl.textContent = noteBits.join(' • ');
  }

  function addExampleButtons(){
    exEl.innerHTML = '';
    for(const ex of examples){
      const b = document.createElement('button');
      b.type = 'button';
      b.textContent = ex;
      b.addEventListener('click', () => { inEl.value = ex; render(); inEl.focus(); });
      exEl.appendChild(b);
    }
  }

  inEl.addEventListener('input', render);
  document.addEventListener('change', (e) => {
    if(e.target && e.target.name === 'mode') render();
  });

  addExampleButtons();
  inEl.value = 'Ροδιος';
  render();
})();

