  border:1px solid var(--line); background:#0c0f1d; color:var(--ink);
  outline:none;
}
input[type="text"]{font-family:var(--mono); font-size:16px}
select{font-size:14px}
input[type="text"]:focus, select:focus{border-color:rgba(125,211,252,.7); box-shadow:0 0 0 3px rgba(125,211,252,.15)}

.check{grid-column:1 / -1; display:flex; gap:10px; align-items:center; padding-top:2px}
.check input{transform:translateY(1px)}

.actions{display:flex; gap:10px; margin-top:12px; flex-wrap:wrap}
button{border:1px solid rgba(125,211,252,.35); background:linear-gradient(180deg, rgba(125,211,252,.22), rgba(125,211,252,.10)); color:var(--ink);
  padding:9px 12px; border-radius:12px; cursor:pointer; font-weight:650; letter-spacing:.2px}
button:hover{border-color:rgba(125,211,252,.7)}
button.ghost{border-color:var(--line); background:rgba(255,255,255,.03); font-weight:600}
button.ghost:hover{border-color:rgba(167,139,250,.6)}

.out{margin-top:14px; padding:12px; border-radius:12px; border:1px dashed rgba(233,236,255,.22); background:rgba(0,0,0,.18)}
.out .row{display:flex; gap:12px; flex-wrap:wrap; align-items:baseline; margin:6px 0}
.tag{display:inline-flex; align-items:center; gap:8px; padding:4px 10px; border-radius:999px; border:1px solid var(--line); background:rgba(255,255,255,.03); color:var(--muted); font-size:12px}
.big{font-family:var(--mono); font-size:20px; color:var(--ink)}
.small{font-size:13px; color:var(--muted); line-height:1.35}

.good{color:var(--good)}
.bad{color:var(--bad)}

.chips{display:flex; flex-wrap:wrap; gap:8px}
.chip{font-family:var(--mono); font-size:14px; padding:7px 10px; border-radius:999px; border:1px solid var(--line); background:rgba(255,255,255,.03); cursor:pointer; user-select:none}
.chip:hover{border-color:rgba(125,211,252,.6)}

details{margin-top:10px}
summary{cursor:pointer; color:var(--accent); font-weight:650}
.notes ul{margin:10px 0 0 18px; color:var(--muted)}

footer{margin-top:10px; color:var(--muted)}
.fine{font-size:12px; margin:0}

@media (max-width:720px){
  .grid{grid-template-columns:1fr}
}

passages.gadget_js:
const $ = (sel) => document.querySelector(sel);

const examples = [
  "θαλάττιος",
  "διπλάσιος",
  "Ἐφέσιος",
  "ἀμβρόσιος",
  "ἱκέσιος",
  "ἀνάρσιος",
  "ἀσπάσιος",
  "πρυμνήσιος",
  "πολέμιος",
  "ποτάμιος",
  "παραποτάμιος",
  "προσωκεάνιος",
  "Παρακηφίσιος",
  "Κλυτίος",
  "χαραδριός",
  "θαλαμιός",
  "Αἰδήψιος",
  "Λυκάψιος",
  "Γαλήψιος"
];

// --- Polytonic helpers ---
// Strip Greek diacritics by NFD decomposition.
function stripDiacritics(s){
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function isGreekLetter(ch){
  return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(ch);
}

function endsWithAny(s, arr){
  return arr.some(x => s.endsWith(x));
}

// Rough syllabifier for Greek: split before a vowel group.
// This is intentionally simple: it aims to give a playable antepenult/penult/ultima.
const VOWELS = new Set(["α","ε","η","ι","ο","υ","ω","ά","έ","ή","ί","ό","ύ","ώ","ϊ","ϋ","ΐ","ΰ","Α","Ε","Η","Ι","Ο","Υ","Ω","Ά","Έ","Ή","Ί","Ό","Ύ","Ώ","Ϊ","Ϋ"]);

function isVowel(ch){
  return VOWELS.has(ch);
}

function syllabifyRough(word){
  // Keep only letters (and final sigma etc.), but preserve Greek letters.
  const w = word;
  let sylls = [];
  let cur = "";
  let seenVowel = false;

  for(let i=0;i<w.length;i++){
    const ch = w[i];
    if(!isGreekLetter(ch) && ch !== "'" && ch !== "᾽" && ch !== "-" && ch !== "·" && ch !== " “" && ch !== " ”"){
      // treat as separator
      if(cur){ sylls.push(cur); cur=""; seenVowel=false; }
      continue;
    }

    // Start new syllable when we already had a vowel and we meet a new vowel.
    if(isVowel(ch)){
      if(seenVowel){
        sylls.push(cur);
        cur = ch;
      } else {
        cur += ch;
        seenVowel = true;
      }
    } else {
      cur += ch;
    }
  }
  if(cur) sylls.push(cur);

  // Post-process: move a single consonant from start of syllable to previous syllable if it looks like onset.
  // This is very rough; helps avoid syllables like "λ" + "ά".
  for(let i=1;i<sylls.length;i++){
    const s = sylls[i];
    // if syllable begins with consonant(s) then vowel, keep as is; if begins with vowel and previous ends with consonant cluster, keep.
    // We'll do a tiny tweak: if syllable starts with a single consonant and previous ends with vowel, move it to previous.
    // But we don't have vowel positions reliably; skip.
  }

  return sylls.filter(x => x.trim().length>0);
}

function countSyllables(word){
  return syllabifyRough(word).length;
}

function looksLikeTribrach(word){
  // Herodian's exception mentions "tribrachs" among proper names.
  // We'll approximate: 3 syllables AND no obvious long markers (η, ω, diphthongs) in the stripped form.
  const w = stripDiacritics(word).toLowerCase();
  const sylls = syllabifyRough(w);
  if(sylls.length !== 3) return false;

  // crude long-vowel/diphthong detection
  if(/[ηω]/.test(w)) return false;
  if(/αι|ει|οι|υι|αυ|ευ|ου|ηυ/.test(w)) return false;
  return true;
}

function accentuateAcuteOnSyllable(word, syllIndex){
  // syllIndex: 0..n-1
  const base = stripDiacritics(word);
  const sylls = syllabifyRough(base);
  if(sylls.length === 0) return {accented: word, sylls: []};
  const idx = Math.max(0, Math.min(syllIndex, sylls.length-1));

  // Put acute on the first vowel of the target syllable.
  const target = sylls[idx];
  let done = false;
  const accentedTarget = target.normalize('NFD').split('').map(ch => {
    if(done) return ch;
    const chNFC = ch.normalize('NFC');
    if(isVowel(chNFC)){
      done = true;
      // add combining acute U+0301
      return ch + "\u0301";
    }
    return ch;
  }).join('').normalize('NFC');

  sylls[idx] = accentedTarget;
  return {accented: sylls.join(''), sylls};
}

function chooseAccentIndex(word, mode, treatAsProper){
  const w = stripDiacritics(word).trim();
  const sylls = syllabifyRough(w);
  const n = sylls.length;
  if(n === 0) return {idx:0, reason:"No syllables detected."};

  const lower = w.toLowerCase();
  const ends = (suf) => lower.endsWith(suf);

  // Special-cased examples mentioned explicitly in the passage
  if(mode === "herodian"){
    if(stripDiacritics(word).toLowerCase() === "κλυτιος"){
      return {idx: Math.max(0,n-2), reason:"Passage notes Κλυτίος (proper name) is paroxytone (penult)."};
    }
    if(stripDiacritics(word).toLowerCase() === "χαραδριος"){
      return {idx: Math.max(0,n-1), reason:"Passage says χαραδριός is oxytone (ultima)."};
    }
    if(stripDiacritics(word).toLowerCase() === "θαλαμιος"){
      return {idx: Math.max(0,n-1), reason:"Passage says θαλαμιός is oxytone (ultima)."};
    }
  }

  const isIosFamily = endsWith("ιος") || endsWith("σιος") || endsWith("τιος");

  if(mode === "forceParox"){
    return {idx: Math.max(0,n-2), reason:"Forced paroxytone (penult)."};
  }
  if(mode === "forceProparox"){
    return {idx: Math.max(0,n-3), reason:"Forced proparoxytone (antepenult)."};
  }

  // Herodian-ish guess
  if(isIosFamily){
    if(treatAsProper && looksLikeTribrach(w)){
      return {idx: Math.max(0,n-2), reason:"Proper-name + tribrach-ish → toy applies the exception: penult."};
    }
    return {idx: Math.max(0,n-3), reason:"-ιος/-σιος/-τιος family → toy prefers antepenult (proparoxytone)."};
  }

  // fallback: if unknown, accent penult if possible
  return {idx: Math.max(0,n-2), reason:"Fallback: penult."};
}

function render(){
  const raw = $("#inWord").value;
  const mode = $("#mode").value;
  const treatAsProper = $("#treatAsProper").checked;
  const showSyll = $("#showSyll").checked;

  const cleaned = raw.trim();
  if(!cleaned){
    $("#out").innerHTML = `<div class="small">Type a Greek word ending in <span class="tag">-ιος</span>, <span class="tag">-σιος</span>, or <span class="tag">-τιος</span> (or click an example).</div>`;
    return;
  }

  const base = stripDiacritics(cleaned);
  const sylls = syllabifyRough(base);
  const pick = chooseAccentIndex(cleaned, mode, treatAsProper);
  const acc = accentuateAcuteOnSyllable(cleaned, pick.idx);

  const n = sylls.length;
  const posName = (i) => {
    if(n===1) return "ultima";
    if(i===n-1) return "ultima (oxytone)";
    if(i===n-2) return "penult (paroxytone)";
    if(i===n-3) return "antepenult (proparoxytone)";
    return `syllable ${i+1}`;
  };

  const trib = looksLikeTribrach(base);
  const endsIos = endsWithAny(base.toLowerCase(), ["ιος","σιος","τιος"]);

  $("#out").innerHTML = `
    <div class="row">
      <span class="tag">input</span>
      <span class="big">${escapeHtml(cleaned)}</span>
    </div>
    <div class="row">
      <span class="tag">stripped</span>
      <span class="big">${escapeHtml(base)}</span>
    </div>
    <div class="row">
      <span class="tag">accented</span>
      <span class="big">${escapeHtml(acc.accented)}</span>
      <span class="tag">${posName(pick.idx)}</span>
    </div>
    <div class="row">
      <span class="tag">why</span>
      <span class="small">${escapeHtml(pick.reason)}</span>
    </div>
    <div class="row">
      <span class="tag">checks</span>
      <span class="small">
        ends -ιος/-σιος/-τιος: <strong class="${endsIos?"good":"bad"}">${endsIos}</strong> ·
        tribrach-ish: <strong class="${trib?"good":"bad"}">${trib}</strong> ·
        syllables (rough): <strong>${sylls.length}</strong>
      </span>
    </div>
    ${showSyll ? `<div class="row"><span class="tag">syllables</span><span class="big">${escapeHtml(sylls.join("·"))}</span></div>` : ""}
  `;
}

function escapeHtml(s){
  return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function mountChips(){
  const box = $("#chips");
  box.innerHTML = "";
  examples.forEach(w => {
    const d = document.createElement('div');
    d.className = 'chip';
    d.setAttribute('role','listitem');
    d.textContent = w;
    d.addEventListener('click', () => {
      $("#inWord").value = w;
      render();
    });
    box.appendChild(d);
  });
}

function randomExample(){
  const w = examples[Math.floor(Math.random()*examples.length)];
  $("#inWord").value = w;
  // Randomize proper-name toggle a bit for fun
  $("#treatAsProper").checked = (Math.random() < 0.25);
  render();
}

$("#btnGo").addEventListener('click', render);
$("#btnClear").addEventListener('click', () => { $("#inWord").value = ""; render(); });
$("#btnRandom").addEventListener('click', randomExample);
$("#mode").addEventListener('change', render);
$("#treatAsProper").addEventListener('change', render);
$("#showSyll").addEventListener('change', render);
$("#inWord").addEventListener('input', () => {
  // live update, but avoid jitter on very long strings
  render();
});

mountChips();
render();

