.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:10px 0}
.lab{min-width:72px;color:var(--muted)}
.inp{flex:1;min-width:220px;padding:10px 10px;border-radius:10px;border:1px solid var(--line);background:#0c0f1c;color:var(--ink);font-size:16px}
.sel{flex:1;min-width:240px;padding:10px 10px;border-radius:10px;border:1px solid var(--line);background:#0c0f1c;color:var(--ink)}
.btn{padding:10px 12px;border-radius:10px;border:1px solid var(--line);background:rgba(139,233,253,.12);color:var(--ink);cursor:pointer}
.btn:hover{border-color:rgba(139,233,253,.55)}
.btn:active{transform:translateY(1px)}
.out{flex:1;min-width:240px;padding:10px 12px;border-radius:10px;border:1px dashed rgba(139,233,253,.55);background:rgba(139,233,253,.06);font-size:18px;letter-spacing:.2px}
.seg{display:flex;gap:8px;flex-wrap:wrap}
.segBtn{padding:8px 10px;border-radius:999px;border:1px solid var(--line);background:rgba(255,255,255,.03);color:var(--ink);cursor:pointer}
.segBtn[aria-pressed="true"]{border-color:rgba(255,212,121,.75);background:rgba(255,212,121,.12)}
.chk{color:var(--muted);display:flex;gap:8px;align-items:center}
.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
.mini{margin-top:8px;border:1px solid var(--line);border-radius:12px;padding:8px 10px;background:rgba(255,255,255,.02)}
.mini summary{cursor:pointer;color:var(--accent)}
.miniBody{color:var(--muted)}
.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px;margin-top:10px}
.tile{border:1px solid var(--line);border-radius:12px;padding:10px;background:rgba(255,255,255,.02);cursor:pointer}
.tile:hover{border-color:rgba(139,233,253,.55)}
.tile .gk{font-size:18px;margin-bottom:4px}
.tile .en{color:var(--muted);font-size:13px}
footer{padding:6px 2px 0}
.foot{margin:0;color:var(--muted);font-size:13px}
.badge{display:inline-block;margin-left:8px;padding:2px 8px;border-radius:999px;border:1px solid var(--line);background:rgba(124,255,178,.08);color:var(--good);font-size:12px}

