const $ = (sel) => document.querySelector(sel);
const baseEl = $('#base');
const outWord = $('#outWord');
const outAccent = $('#outAccent');
const rhoRuleEl = $('#rhoRule');
const accentModeEl = $('#accentMode');

const segBtns = Array.from(document.querySelectorAll('.segBtn'));
let chosenSuffix = '-άσιος';

const examples = [
  {base:'Συρακουσ', suf:'-σιος', note:'→ Συρακόσσιος (toy doubles σ)'} ,
  {base:'Χερσονησ', suf:'-ήσιος', note:'→ Χερσονήσιος'} ,
  {base:'Φλιοῦντ', suf:'-ούσιος', note:'expected → Φλιούσιος'} ,
  {base:'Φλι', suf:'-άσιος', note:'with added α → Φλιᾶσιος'} ,
  {base:'Ἀναγυροῦντ', suf:'-άσιος', note:'→ Ἀναγυράσιος (ρ “likes” α)'} ,
  {base:'Μίλητ', suf:'-ήσιος', note:'→ Μιλήσιος'} ,
  {base:'Μαραθ', suf:'-ήσιος', note:'→ Μαραθήσιος'} ,
  {base:'Νυμφ', suf:'-άσιος', note:'→ Νυμφάσιος'} ,
  {base:'Θηρ', suf:'-άσιος', note:'→ Θηράσιος'} ,
  {base:'Ἰθακ', suf:'-ήσιος', note:'→ Ἰθακήσιος'}
];

function stripDiacritics(s){
  // Remove Greek tonos/oxia, varia, perispomeni, dialytika, iota subscript, etc.
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function endsWithRho(base){
  const b = stripDiacritics(base).trim();
  if(!b) return false;
  const last = b[b.length-1];
  return last === 'ρ' || last === 'Ρ';
}

function applyPlayfulTweaks(base, suf){
  let b = base.trim();
  if(!b) return '';

  // Toy rule: if base ends in -ουσ and suffix begins with σ, double σ (to evoke Συρακόσσιος)
  const plain = stripDiacritics(b);
  if(/ουσ$/i.test(plain) && (suf === '-σιος' || suf === '-άσιος' || suf === '-ήσιος' || suf === '-ούσιος')){
    // Insert extra σ at join: ...ουσ + σιος => ...ουσσιος
    // We'll do it by ensuring base ends with σ and then doubling it.
    if(b.endsWith('σ')) b = b + 'σ';
  }

  // If base ends with τ/ντ, drop it before suffix (very common in ethnic formation; toy)
  if(/[τΤ]$/.test(stripDiacritics(b))) b = b.slice(0,-1);
  if(/ντ$/i.test(stripDiacritics(b))) b = b.slice(0,-2);

  return b;
}

function join(base, suf){
  let s = suf;
  if(rhoRuleEl.checked && endsWithRho(base)){
    // Suggest -άσιος if user picked -σιος or -ήσιος
    if(s === '-σιος' || s === '-ήσιος') s = '-άσιος';
  }
  const b2 = applyPlayfulTweaks(base, s);
  return b2 ? (b2 + s.replace(/^-/,'')).trim() : '';
}

function forceSuffixAccent(word){
  // If the suffix contains α/η/ου, ensure it is accented: ά/ή/ού.
  // Very approximate: just replace the last occurrence of α/η/ου in the word if it is in the suffix region.
  let w = stripDiacritics(word);
  // Handle -ουσιος / -ουσιος-like
  w = w.replace(/ουσιος$/,'ούσιος');
  w = w.replace(/ασιος$/,'άσιος');
  w = w.replace(/ησιος$/,'ήσιος');
  w = w.replace(/σιος$/,'σιος');
  return w;
}

function update(){
  const base = baseEl.value;
  const formed = join(base, chosenSuffix);
  outWord.textContent = formed || '—';

  let acc = formed;
  const mode = accentModeEl.value;
  if(mode === 'none') acc = stripDiacritics(formed);
  if(mode === 'suffix') acc = forceSuffixAccent(formed);
  outAccent.textContent = acc || '—';

  // Add a tiny badge if rho-rule changed the suffix
  const wouldChange = rhoRuleEl.checked && endsWithRho(base) && (chosenSuffix==='-σιος' || chosenSuffix==='-ήσιος');
  outWord.innerHTML = '';
  if(!formed){ outWord.textContent = '—'; return; }
  const span = document.createElement('span');
  span.textContent = formed;
  outWord.appendChild(span);
  if(wouldChange){
    const b = document.createElement('span');
    b.className = 'badge';
    b.textContent = 'ρ→α hint';
    outWord.appendChild(b);
  }
}

segBtns.forEach(btn => {
  btn.addEventListener('click', () => {
    segBtns.forEach(b => b.setAttribute('aria-pressed','false'));
    btn.setAttribute('aria-pressed','true');
    chosenSuffix = btn.dataset.suf;
    update();
  });
});
// default pressed
segBtns.find(b=>b.dataset.suf===chosenSuffix)?.setAttribute('aria-pressed','true');

baseEl.addEventListener('input', update);
rhoRuleEl.addEventListener('change', update);
accentModeEl.addEventListener('change', update);

$('#spin').addEventListener('click', () => {
  // Cycle modes for fun
  const modes = ['keep','suffix','none'];
  const i = modes.indexOf(accentModeEl.value);
  accentModeEl.value = modes[(i+1)%modes.length];
  update();
});

$('#copy').addEventListener('click', async () => {
  const txt = outAccent.textContent && outAccent.textContent !== '—' ? outAccent.textContent : outWord.textContent;
  try{
    await navigator.clipboard.writeText(txt);
  }catch(e){
    // fallback
    const ta = document.createElement('textarea');
    ta.value = txt;
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    ta.remove();
  }
});

$('#rand').addEventListener('click', () => {
  const ex = examples[Math.floor(Math.random()*examples.length)];
  baseEl.value = ex.base;
  chosenSuffix = ex.suf;
  segBtns.forEach(b => b.setAttribute('aria-pressed', b.dataset.suf===chosenSuffix ? 'true':'false'));
  update();
});

function buildGallery(){
  const g = $('#gallery');
  g.innerHTML = '';
  examples.forEach(ex => {
    const tile = document.createElement('button');
    tile.type = 'button';
    tile.className = 'tile';
    const formed = join(ex.base, ex.suf);
    tile.innerHTML = `<div class="gk">${formed || (ex.base + ex.suf.replace('-',''))}</div><div class="en">${ex.note}</div>`;
    tile.addEventListener('click', () => {
      baseEl.value = ex.base;
      chosenSuffix = ex.suf;
      segBtns.forEach(b => b.setAttribute('aria-pressed', b.dataset.suf===chosenSuffix ? 'true':'false'));
      update();
      window.scrollTo({top:0, behavior:'smooth'});
    });
    g.appendChild(tile);
  });
}

buildGallery();
update();

