:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --card:#1d2136;
  --text:#eef0ff;
  --muted:#b9bdd8;
  --line:#2b3150;
  --accent:#7bdcff;
  --accent2:#b7ff7b;
  --warn:#ffcf7b;
}
*{box-sizing:border-box}
body{
