const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => Array.from(document.querySelectorAll(sel));

const examples = [
  {label:"Ὀποῦς", value:"Ὀποῦς"},
  {label:"Ὀπούντος (gen.)", value:"Ὀπούντος"},
  {label:"Σελινοῦς", value:"Σελινοῦς"},
  {label:"Τραπεζοῦς", value:"Τραπεζοῦς"},
  {label:"Ἱεριχούς", value:"Ἱεριχούς"},
  {label:"Τεύθραντος (gen.)", value:"Τεύθραντος"},
  {label:"Ἐρεσός", value:"Ἐρεσός"},
  {label:"Ῥαμνοῦς", value:"Ῥαμνοῦς"},
  {label:"Ἁλιμός", value:"Ἁλιμός"}
];

function stripDiacritics(s){
  // Remove combining marks; keep base Greek letters.
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function lastVowelIndex(s){
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
  for(let i=s.length-1;i>=0;i--){
    if(vowels.has(s[i])) return i;
  }
  return -1;
}

function addToyAccent(word){
  // Very rough: add acute to the last vowel if none present.
  if(/[άέήίόύώΆΈΉΊΌΎΏ]/.test(word)) return word;
  const plain = stripDiacritics(word);
  const idx = lastVowelIndex(plain);
  if(idx<0) return word;
  const map = { 'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
                'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ' };
  const ch = plain[idx];
  const accented = map[ch] || ch;
  return plain.slice(0,idx) + accented + plain.slice(idx+1);
}

function normalizeInput(s){
  return (s||"").trim().replace(/\s+/g,' ');
}

function deriveStemForOuntios(input){
  // Heuristic: if ends with -ους/-οῦς, drop final ς; if ends with -ος drop ς; if ends with -ον drop ν.
  const s = normalizeInput(input);
  const plain = stripDiacritics(s);
  let stem = plain;

  if(/ους$/.test(plain)) stem = plain.replace(/ς$/,'');
  else if(/ος$/.test(plain)) stem = plain.replace(/ς$/,'');
  else if(/ον$/.test(plain)) stem = plain.replace(/ν$/,'');
  else if(/ας$/.test(plain)) stem = plain.replace(/ς$/,'');
  else if(/ης$/.test(plain)) stem = plain.replace(/ς$/,'');
  else if(/ις$/.test(plain)) stem = plain.replace(/ς$/,'');
  else if(/ευς$/.test(plain)) stem = plain.replace(/ς$/,'');
  else if(/ους$/.test(plain)) stem = plain.replace(/ς$/,'');
  else if(/ς$/.test(plain)) stem = plain.slice(0,-1);

  return {stem, plain};
}

function makeOuntios(input){
  const {stem, plain} = deriveStemForOuntios(input);
  // If already looks like ...ουντ..., keep.
  if(/ουντιος$/.test(plain)) return {result: plain, steps:[`Input already ends with -ουντιος.`]};
  const res = stem + 'ουντιος';
  return {result: res, steps:[`Stem ≈ ${stem}`, `Add suffix: + ουντιος` ]};
}

function switchOuntiosToOusios(input){
  const s = normalizeInput(input);
  const plain = stripDiacritics(s);
  let base = plain;
  const steps = [];

  if(!/ουντιος$/.test(plain)){
    const made = makeOuntios(plain);
    base = made.result;
    steps.push(`First make an -ουντιος form: ${base}`);
  } else {
    steps.push(`Start from: ${base}`);
  }

  // Herodian move: ...ουντιος -> ...ουσιος (drop ν, τ→σ)
  const res = base.replace(/ουντιος$/, 'ουσιος');
  steps.push(`Herodian switch: -ουντιος → -ουσιος (drop ν, τ→σ)`);
  return {result: res, steps};
}

function fromGenNtToAntios(input){
  const s = normalizeInput(input);
  const plain = stripDiacritics(s);
  const steps = [];
  if(/ντος$/.test(plain)){
    const stem = plain.replace(/ντος$/,'');
    steps.push(`Genitive detected: -ντος`);
    steps.push(`Remove -ντος → stem ≈ ${stem}`);
    const res = stem + 'αντιος';
    steps.push(`Add suffix: + αντιος`);
    return {result: res, steps};
  }
  // fallback: try to guess a genitive by adding -ντος? (toy)
  steps.push(`No -ντος ending found; treating input as stem.`);
  const res = plain + 'αντιος';
  steps.push(`Add suffix: + αντιος`);
  return {result: res, steps};
}

function makeIos(input){
  const s = normalizeInput(input);
  const plain = stripDiacritics(s);
  const steps = [];
  let stem = plain;
  if(/ος$/.test(plain) || /ους$/.test(plain) || /ης$/.test(plain) || /ας$/.test(plain) || /ις$/.test(plain)){
    stem = plain.replace(/ς$/,'');
    steps.push(`Drop final -ς → stem ≈ ${stem}`);
  } else {
    steps.push(`Use input as stem ≈ ${stem}`);
  }
  const res = stem + 'ιος';
  steps.push(`Add suffix: + ιος`);
  return {result: res, steps};
}

function titleCaseGreek(s){
  // Keep as-is; but if user types lowercase, capitalize first letter (simple).
  if(!s) return s;
  const first = s[0];
  const rest = s.slice(1);
  return first.toUpperCase() + rest;
}

function render(){
  const input = normalizeInput($('#inp').value);
  const mode = ($$('input[name="mode"]').find(r=>r.checked)||{}).value || 'ountios';
  const wantAccent = $('#optAccent').checked;
  const wantExplain = $('#optExplain').checked;

  if(!input){
    $('#out').textContent = '—';
    $('#steps').textContent = '';
    return;
  }

  let pack;
  if(mode==='ountios') pack = makeOuntios(input);
  else if(mode==='ousios') pack = switchOuntiosToOusios(input);
  else if(mode==='antios') pack = fromGenNtToAntios(input);
  else pack = makeIos(input);

  let result = titleCaseGreek(pack.result);
  if(wantAccent) result = addToyAccent(result);

  $('#out').textContent = result;

  if(wantExplain){
    const lines = pack.steps.map(s=>`• ${s}`).join('\n');
    $('#steps').innerHTML = `<b>Steps</b>\n<pre class="mono" style="margin:8px 0 0;white-space:pre-wrap">${escapeHtml(lines)}</pre>`;
  } else {
    $('#steps').textContent = '';
  }
}

function escapeHtml(s){
  return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

function mountChips(){
  const box = $('#chips');
  box.innerHTML = '';
  examples.forEach(ex=>{
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip';
    b.textContent = ex.label;
    b.addEventListener('click', ()=>{ $('#inp').value = ex.value; render(); $('#inp').focus(); });
    box.appendChild(b);
  });
}

function randomExample(){
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#inp').value = ex.value;
  render();
}

$('#btnGo').addEventListener('click', render);
$('#btnShuffle').addEventListener('click', randomExample);
$('#inp').addEventListener('input', ()=>{ render(); });
$$('input[name="mode"]').forEach(r=>r.addEventListener('change', render));
$('#optAccent').addEventListener('change', render);
$('#optExplain').addEventListener('change', render);

$('#btnCopy').addEventListener('click', async ()=>{
  const text = $('#out').textContent.trim();
  if(!text || text==='—') return;
  try{
    await navigator.clipboard.writeText(text);
    $('#copyMsg').textContent = 'Copied.';
  } catch(e){
    // Fallback
    const ta = document.createElement('textarea');
    ta.value = text;
    document.body.appendChild(ta);
    ta.select();
    try{ document.execCommand('copy'); $('#copyMsg').textContent = 'Copied.'; }
    catch(err){ $('#copyMsg').textContent = 'Copy failed.'; }
    document.body.removeChild(ta);
  }
  setTimeout(()=>$('#copyMsg').textContent='', 900);
});

mountChips();
randomExample();

