(() => {
  const $ = (sel, el=document) => el.querySelector(sel);
  const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

  const input = $('#in');
  const normEl = $('#norm');
  const syllEl = $('#syll');
  const accEl = $('#accented');
  const whyEl = $('#why');
  const birdEl = $('#bird');
  const properEl = $('#proper');

  const samples = [
    'ἐνάλιος','Παράλιος','Δενθάλιος','Κυάλιος','Φαρσάλιος','Φαρράλιος',
    'Μαινάλιος','Οἰχάλιος','Πατάλιος','Δασάλιος','θεμέλιος','νυκτέλιος','κειμήλιος','γαμήλιος','Ταργήλιος','ἀπατήλιος',
    'Παμφύλιος','Τριφύλιος','Μασύλιος','Αἰγίλιος','Πραξίλιος','ἐμφύλιος',
    'λαλιός','σκολιός','βαλιός','Βαλίος','Ἅλιος',
    'αἰγωλιός','ἑδωλιός','βομβυλιός',
    'Ἀσκληπιός','Ἀσκλήπιον',
    'αἴτιος','ἁρμόδιος','ἄρκιος','ἄρτιος','ἀντίος'
  ];

  const chips = $('#chips');
  samples.forEach(w => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip';
    b.textContent = w;
    b.addEventListener('click', () => { input.value = w; update(); input.focus(); });
    chips.appendChild(b);
  });

  // --- Greek helpers (toy-level) ---
  const combining = /[\u0300-\u036f]/g;

  function stripDiacritics(s){
    // NFD splits tonos/oxia etc into combining marks; remove them.
    return s.normalize('NFD').replace(combining,'').normalize('NFC');
  }

  function isVowel(ch){
    return 'αεηιουωΑΕΗΙΟΥΩ'.includes(ch);
  }

  function syllableGroups(word){
    // Return array of {start,end} indices (end exclusive) for vowel-groups.
    const w = word;
    const groups = [];
    let i=0;
    while(i<w.length){
      if(isVowel(w[i])){
        let j=i+1;
        while(j<w.length && isVowel(w[j])) j++;
        groups.push({start:i,end:j});
        i=j;
      } else i++;
    }
    return groups;
  }

  function addAcuteToGroup(word, groupIndex){
    const groups = syllableGroups(word);
    if(groups.length===0) return word;
    const gi = Math.max(0, Math.min(groupIndex, groups.length-1));
    const g = groups[gi];
    // Put acute on first vowel of the group.
    const chars = Array.from(word);
    const idx = g.start;
    const base = chars[idx];
    const acuteMap = {
      'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
      'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
    };
    chars[idx] = acuteMap[base] || base;
    return chars.join('');
  }

  function endsWithLios(word){
    return /λιος$/i.test(word);
  }
  function endsWithLiosOxy(word){
    // -λιός (with tonos removed already, so just check -λιος but we use syllable count heuristic)
    // We'll detect original input having -λιός by checking for accented ο/ό at end before stripping.
    return false;
  }

  function detectOriginalOxyLios(raw){
    // crude: does it end with "λιός" or "λιός" etc?
    return /λι[όό]ς$/i.test(raw.normalize('NFC'));
  }

  function decide(wordRaw){
    const raw = (wordRaw||'').trim();
    if(!raw) return null;

    // Keep spaces: accent each token separately? For toy, do first token.
    const token = raw.split(/\s+/)[0];
    const norm = stripDiacritics(token);
    const groups = syllableGroups(norm);
    const n = groups.length;

    const mode = ($$('input[name="mode"]').find(r=>r.checked)||{}).value || 'auto';
    const bird = birdEl.checked;
    const proper = properEl.checked;

    // A couple of demo exceptions mentioned in passage
    // Βαλίος (proper) paroxytone; Ἅλιος (proper) proparoxytone (customary reading)
    const normLower = norm.toLowerCase();

    let target = null; // group index
    let decision = '';
    let badge = 'ok';

    if(mode !== 'auto'){
      if(mode==='oxy') { target = n-1; decision = 'Forced oxytone (ultima).'; badge='warn'; }
      if(mode==='parox') { target = n-2; decision = 'Forced paroxytone (penult).'; badge='warn'; }
      if(mode==='proparox') { target = n-3; decision = 'Forced proparoxytone (antepenult).'; badge='warn'; }
    } else {
      // Auto heuristic
      if(proper && normLower === 'βαλιος'){
        target = n-2;
        decision = 'Proper-name demo: Βαλίος → paroxytone (penult) per passage.';
        badge='ok';
      } else if(proper && normLower === 'αλιος'){
        target = n-3;
        decision = 'Proper-name demo: Ἅλιος → proparoxytone (antepenult) in customary reading.';
        badge='ok';
      } else if(bird){
        target = n-1;
        decision = 'Bird-word toggle: oxytone (ultima) per Herodian’s exception.';
        badge='ok';
      } else if(endsWithLios(norm) && n>=4){
        target = n-3;
        decision = 'Ends in -λιος and 4+ syllables: proparoxytone (antepenult).';
        badge='ok';
      } else if(detectOriginalOxyLios(token) && n===3){
        target = n-1;
        decision = 'Trisyllabic -λιός pattern (e.g. βαλιός): oxytone (ultima).';
        badge='ok';
      } else if(endsWithLios(norm) && n===3){
        // many -λιος trisyllables vary; pick penult as a neutral toy default
        target = n-2;
        decision = 'Trisyllabic -λιος: toy default = paroxytone (penult). (Many real words vary.)';
        badge='warn';
      } else {
        // fallback: keep penult if possible
        target = Math.max(0, n-2);
        decision = 'Not a clear -λιος case: toy fallback = paroxytone (penult).';
        badge='warn';
      }
    }

    // clamp
    if(n===0){
      return {raw, norm, syllables:[], accented:norm, decision:'No vowels detected.', badge:'no'};
    }
    if(target < 0) target = 0;

    const accented = addAcuteToGroup(norm, target);

    // Build syllable display: show vowel groups with separators
    const parts = [];
    let last = 0;
    groups.forEach((g, idx) => {
      parts.push(norm.slice(last, g.end));
      last = g.end;
    });
    const syllStr = parts.join('·');

    return {raw, norm, syllables:parts, syllStr, accented, decision, badge, n};
  }

  function update(){
    const res = decide(input.value);
    if(!res){
      normEl.textContent = '';
      syllEl.textContent = '';
      accEl.textContent = '';
      whyEl.innerHTML = '<span class="badge no">Type a word</span>';
      return;
    }
    normEl.textContent = res.norm;
    syllEl.textContent = res.syllStr || '';
    accEl.textContent = res.accented;
    whyEl.innerHTML = `<span class="badge ${res.badge}">${res.badge==='ok'?'rule-ish':res.badge==='warn'?'toy default':'problem'}</span> ${escapeHtml(res.decision)}`;
  }

  function escapeHtml(s){
    return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  input.addEventListener('input', update);
  $$('input[name="mode"]').forEach(r => r.addEventListener('change', update));
  birdEl.addEventListener('change', update);
  properEl.addEventListener('change', update);

  // Seed
  input.value = 'Μαινάλιος';
  update();
})();

