const $ = (s)=>document.querySelector(s);

const examples = [
  {in:"ὀρθώσομαι", mode:"ios"},
  {in:"ἀσπάσομαι", mode:"ios"},
  {in:"φυλάξομαι", mode:"ios"},
  {in:"ἀλέξω", mode:"ios"},
  {in:"κτήσω", mode:"ios"},
  {in:"μνήσω", mode:"ios"},
  {in:"αἰνήσω", mode:"ios"},
  {in:"ἀρκέσω", mode:"ios"},
  {in:"ἄξω", mode:"ios"},
  {in:"θαυμάζω", mode:"ios"},
  {in:"ἀστεος", mode:"eios"},
  {in:"Καδμειος", mode:"eios"},
  {in:"ἀνδρειος", mode:"eios"},
  {in:"Ἀργειος", mode:"eios"},
  {in:"Βακχειος", mode:"eios"},
  {in:"ἐνιαυτός", mode:"lacon"},
  {in:"πλοῦτος", mode:"lacon"},
  {in:"πλητος", mode:"auto"}
];

// --- Greek helpers (toy-level) ---
const COMBINING = /[\u0300-\u036f]/g; // includes tonos/oxia etc.

function nfd(s){return s.normalize('NFD');}
function nfc(s){return s.normalize('NFC');}

function stripDiacritics(s){
  // remove combining marks; keep base letters
  return nfc(nfd(s).replace(COMBINING,''));
}

function isVowel(ch){
  return /[αεηιουωΑΕΗΙΟΥΩ]/.test(ch);
}

function syllabifySimple(word){
  // Very rough: split before each vowel group.
  const w = stripDiacritics(word);
  let parts=[];
  let cur="";
  for(let i=0;i<w.length;i++){
    const ch=w[i];
    cur+=ch;
    const next=w[i+1];
    if(isVowel(ch)){
      // keep diphthongs together (αι, ει, οι, υι, αυ, ευ, ου, ηυ)
      const pair = ch + (next||"");
      const diph = ["αι","ει","οι","υι","αυ","ευ","ου","ηυ","ΑΙ","ΕΙ","ΟΙ","ΥΙ","ΑΥ","ΕΥ","ΟΥ","ΗΥ"].includes(pair);
      if(diph){
        if(next){cur+=next; i++;}
      }
      parts.push(cur);
      cur="";
    }
  }
  if(cur) parts.push(cur);
  return parts.filter(p=>p.length);
}

function addAcuteOnSyllable(word, syllIndexFromEnd){
  // Put an acute on the first vowel of the target syllable (counting from end: 1=ultima,2=penult,3=antepenult)
  const syls = syllabifySimple(word);
  if(syls.length===0) return word;
  const idx = Math.max(0, syls.length - syllIndexFromEnd);
  const target = syls[idx];
  const tNFD = nfd(target);
  // find first vowel base in NFD stream
  let out="";
  let accented=false;
  for(let i=0;i<tNFD.length;i++){
    const ch=tNFD[i];
    out+=ch;
    if(!accented && /[αεηιουωΑΕΗΙΟΥΩ]/.test(ch)){
      out+="\u0301"; // combining acute
      accented=true;
    }
  }
  syls[idx]=nfc(out);
  return nfc(syls.join(""));
}

function normalizeInput(s){
  return s.trim().replace(/\s+/g,' ');
}

function makeIosFromFuture(base){
  // Heuristic: remove -σομαι, -ξομαι, -ψομαι, -ω (present/future), -σω, -ξω, -ψω
  const raw = normalizeInput(base);
  const bare = stripDiacritics(raw);
  let stem = raw;
  let why = [];

  const endings = [
    {re:/σομαι$/u, cut:5, note:"future middle -σομαι"},
    {re:/ξομαι$/u, cut:5, note:"future middle -ξομαι"},
    {re:/ψομαι$/u, cut:5, note:"future middle -ψομαι"},
    {re:/σω$/u, cut:2, note:"future -σω"},
    {re:/ξω$/u, cut:2, note:"future -ξω"},
    {re:/ψω$/u, cut:2, note:"future -ψω"},
    {re:/ω$/u, cut:1, note:"-ω"}
  ];

  let matched = endings.find(e=>e.re.test(bare));
  if(matched){
    // cut by codepoints from end of raw, but raw may have diacritics; do it on bare length and map? toy: cut on bare, then reattach by stripping diacritics first.
    const bareStem = bare.slice(0, bare.length - matched.cut);
    stem = bareStem; // we will output mostly unaccented then add accent
    why.push(`Detected ${matched.note}; built stem “${bareStem}”.`);
  } else {
    stem = bare;
    why.push("No clear future ending detected; used the input as a stem.");
  }

  let out = stem + "ιος";
  // Herodian: futures → proparoxytone (antepenult)
  out = addAcuteOnSyllable(out, 3);
  why.push("Applied toy accent: proparoxytone (acute on antepenult) for -ιος from a future.");
  return {out, why: why.join(' ')};
}

function makeEiosSpelling(base){
  const raw = normalizeInput(base);
  const bare = stripDiacritics(raw);
  let why=[];

  // If user typed ...ειος already, prefer ...εῖος (circumflex not implemented; we use acute on ει syllable as a stand-in)
  let out = bare;
  if(/ειος$/u.test(bare)){
    out = bare.replace(/ειος$/u, "ειος");
    why.push("Input already ends in -ειος; keeping ει spelling.");
  } else if(/εος$/u.test(bare)){
    out = bare.replace(/εος$/u, "ειος");
    why.push("Converted -εος → -ειος (toy version of Herodian’s ει spelling)." );
  } else if(/ιος$/u.test(bare)){
    // try to switch to -ειος
    out = bare.replace(/ιος$/u, "ειος");
    why.push("Converted -ιος → -ειος to demonstrate the ει spelling rule." );
  } else {
    out = bare + "ειος";
    why.push("Appended -ειος to make an -εῖος-type adjective (toy)." );
  }

  // Accent: many examples are paroxytone with ει (ἀστεῖος etc.). We'll put acute on penult.
  out = addAcuteOnSyllable(out, 2);
  why.push("Applied toy accent: acute on penult (paroxytone), like ἀστεῖος, ἀνδρεῖος.");

  // Also: if it looks like ...α + CC somewhere, mention it.
  if(/α[βγδζθκλμνξπρστφχψ][βγδζθκλμνξπρστφχψ]/u.test(bare)){
    why.push("Noted pattern α + two consonants (very rough check), echoing the passage’s condition.");
  }

  return {out, why: why.join(' ')};
}

function laconianPair(base){
  const raw = normalizeInput(base);
  const bare = stripDiacritics(raw);
  let why=[];

  // From -τος nouns: make -σιος and -τιος as a pair (ἐνιαυτός → ἐνιαύσιος/ἐνιαύτιος; πλοῦτος → πλούσιος/πλούτιος)
  let stem;
  if(/τος$/u.test(bare)){
    stem = bare.slice(0,-2); // remove ος? actually -τος is 3 letters; but we want keep τ? toy
    // better: remove final -ος only, keep τ: ...τ
    stem = bare.slice(0,-2); // removes 'ος'
    why.push("Detected -τος; formed two adjectives by swapping τ→σ (…σιος) and keeping τ (…τιος) as a ‘reminder’." );
  } else {
    stem = bare;
    why.push("No -τος detected; still showing a τ/σ alternation toy." );
  }

  // If stem ends with τ, good; else try to add τ.
  let baseT = stem;
  if(!/τ$/u.test(baseT)) baseT = stem + "τ";

  let sForm = baseT.replace(/τ$/u, "σ") + "ιος";
  let tForm = baseT + "ιος";

  // Accent: just put acute on penult for both.
  sForm = addAcuteOnSyllable(sForm, 2);
  tForm = addAcuteOnSyllable(tForm, 2);

  const out = `${sForm}  /  ${tForm}`;
  why.push("Toy accent: paroxytone for both forms.");
  return {out, why: why.join(' ')};
}

function applyDialectSetting(word, dial){
  if(dial==="none") return stripDiacritics(word);
  return word;
}

function autoTransform(input){
  const bare = stripDiacritics(input);
  // Guess: futures or -ω → -ιος; else if ends -ιος/-ειος/-εος → eios; else if ends -τος → lacon; else default to eios.
  if(/(σομαι|ξομαι|ψομαι|σω|ξω|ψω|ω)$/u.test(bare)) return {mode:"ios"};
  if(/τος$/u.test(bare)) return {mode:"lacon"};
  if(/(ειος|ιος|εος)$/u.test(bare)) return {mode:"eios"};
  return {mode:"eios"};
}

function transform(){
  const inp = normalizeInput($('#inp').value);
  const modeSel = $('#mode').value;
  const dial = $('#dial').value;

  if(!inp){
    $('#out').textContent = '—';
    $('#why').textContent = 'Type something Greek first.';
    return;
  }

  let mode = modeSel;
  if(modeSel==="auto") mode = autoTransform(inp).mode;

  let res;
  if(mode==="ios") res = makeIosFromFuture(inp);
  else if(mode==="eios") res = makeEiosSpelling(inp);
  else res = laconianPair(inp);

  const finalOut = applyDialectSetting(res.out, dial);

  $('#out').textContent = finalOut;
  const label = modeSel==="auto" ? `Auto chose: ${mode}` : `Mode: ${mode}`;
  $('#why').textContent = `${label}. ${res.why}`;
}

$('#go').addEventListener('click', transform);
$('#inp').addEventListener('keydown', (e)=>{ if(e.key==='Enter') transform(); });
$('#clear').addEventListener('click', ()=>{ $('#inp').value=''; $('#out').textContent='—'; $('#why').textContent='—'; $('#inp').focus(); });
$('#rand').addEventListener('click', ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#inp').value = ex.in;
  $('#mode').value = ex.mode;
  transform();
});

// initial
$('#inp').value = 'ὀρθώσομαι';
$('#mode').value = 'ios';
transform();

