.bins{display:grid;grid-template-columns:1fr;gap:10px;margin-top:10px}
@media (min-width:900px){.bins{grid-template-columns:1fr 1fr}}
.bin{border:1px solid rgba(255,255,255,.10);border-radius:12px;padding:10px;background:rgba(0,0,0,.18)}
.bin h3{margin:0 0 8px;font-size:13px;color:var(--muted)}
.chipbox{display:flex;flex-wrap:wrap;gap:8px;min-height:44px}
.chip{user-select:none;cursor:pointer;padding:7px 10px;border-radius:999px;border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.06);font-size:14px}
.chip:hover{border-color:rgba(139,233,253,.45)}
.score{margin-top:10px;padding:9px 10px;border-radius:12px;border:1px solid rgba(255,255,255,.10);background:rgba(0,0,0,.18);color:var(--muted);font-size:13px}
.score b{color:var(--ink)}
.notes{margin-top:12px;border:1px solid rgba(255,255,255,.10);border-radius:12px;padding:10px;background:rgba(0,0,0,.14)}
.notes summary{cursor:pointer;color:var(--accent);font-size:13px}
.noteBody{color:var(--muted);font-size:13px}
.ftr{margin-top:12px;color:var(--muted)}
.badge{display:inline-block;padding:2px 8px;border-radius:999px;border:1px solid rgba(255,255,255,.14);font-size:12px;margin-left:8px}
.badge.good{color:var(--good);border-color:rgba(124,255,178,.35)}
.badge.warn{color:var(--warn);border-color:rgba(255,212,121,.35)}
.badge.bad{color:var(--bad);border-color:rgba(255,122,162,.35)}

