(() => {
  const $ = (sel, el=document) => el.querySelector(sel);

  const inp = $('#inp');
  const ends = $('#ends');
  const syll = $('#syll');
  const hasY = $('#hasY');
  const exc = $('#exc');
  const out = $('#out');
  const why = $('#why');
  const btnPro = $('#btnPro');
  const btnPar = $('#btnPar');
  const btnClear = $('#btnClear');

  // A small list of proper-name tribrach paroxytones mentioned.
  // (Toy list; not exhaustive.)
  const properParoxy = new Set([
    'τυχιος','φρυγιος','πλυτιος','κλυτιος','σκυφιος',
    'σχεδιος','χρομιος','οδιος','δολιος'
  ]);

  // Traditional exceptions listed as proparoxy in the passage (toy handling)
  const tradPro = new Set(['αλιος','ανιος','ξενιος','κρονιος','υπιος']);

  // Some semantic pairs to demonstrate “distinction”
  const semanticPairs = [
    {plain:'νυμφιος', pro:'νύμφιος', par:'νυμφίος', note:'νύμφιος (bridal) vs νυμφίος (bridegroom)'} ,
    {plain:'μυριος', pro:'μύριος', par:'μυρίος', note:'μύριος (definite 10,000) vs μυρίος (indefinite “countless”)'}
  ];

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ','ϊ','ΐ','ϋ','ΰ','ᾳ','ῃ','ῳ']);

  function stripDiacritics(s){
    return (s||'')
      .normalize('NFD')
      .replace(/\p{M}+/gu,'')
      .replace(/[᾽᾿ʼ’]/g,'')
      .toLowerCase();
  }

  function tokenizeWords(s){
    return (s||'').trim().split(/\s+/).filter(Boolean);
  }

  function roughSyllables(word){
    // Very rough: count vowel groups (treat diphthongs as one group).
    const w = stripDiacritics(word);
    if(!w) return 0;
    const diph = ['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ωυ'];
    let i=0, count=0;
    while(i<w.length){
      const two = w.slice(i,i+2);
      if(diph.includes(two)) { count++; i+=2; continue; }
      const ch = w[i];
      if(vowels.has(ch)){
        count++;
        // skip consecutive vowels (hiatus will be undercounted; fine for toy)
        i++;
        while(i<w.length && vowels.has(w[i])) i++;
        continue;
      }
      i++;
    }
    return count;
  }

  function firstSyllableHasY(word){
    // Approx: look up to first vowel group; if it contains υ, return true.
    const w = stripDiacritics(word);
    if(!w) return false;
    const diph = ['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ωυ'];
    let i=0;
    while(i<w.length && !vowels.has(w[i])) i++;
    if(i>=w.length) return false;
    // capture first vowel group (or diphthong)
    const two = w.slice(i,i+2);
    if(diph.includes(two)) return two.includes('υ');
    let grp = '';
    while(i<w.length && vowels.has(w[i])) { grp += w[i]; i++; }
    return grp.includes('υ');
  }

  function endsInIos(word){
    const w = stripDiacritics(word);
    return w.endsWith('ιος');
  }

  function addAcuteToVowel(ch){
    const map = {
      'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
      'ϊ':'ΐ','ϋ':'ΰ'
    };
    return map[ch] || ch;
  }

  function accentWord(word, positionFromEnd){
    // positionFromEnd: 1=ultima, 2=penult, 3=antepenult
    // Place acute on the first vowel of the target syllable (roughly).
    const orig = word;
    const w = word.normalize('NFD');
    // Remove existing accents (keep diaeresis)
    let base = w.replace(/[\u0301\u0342\u0300]/g,''); // acute/circumflex/grave
    base = base.normalize('NFC');

    const plain = stripDiacritics(base);
    if(!plain) return orig;

    // Find vowel-group start indices in plain string
    const diph = ['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ωυ'];
    let idxs = [];
    for(let i=0;i<plain.length;){
      const two = plain.slice(i,i+2);
      if(diph.includes(two)) { idxs.push(i); i+=2; continue; }
      if(vowels.has(plain[i])){
        idxs.push(i);
        i++;
        while(i<plain.length && vowels.has(plain[i])) i++;
        continue;
      }
      i++;
    }
    if(idxs.length===0) return orig;

    const target = idxs.length - positionFromEnd;
    if(target < 0) return base;

    // Now apply accent to corresponding vowel in base string.
    // We assume base and plain have same length in codepoints for Greek letters.
    const chars = Array.from(base);
    const t = idxs[target];
    // Find first vowel char at/after t
    for(let i=t;i<chars.length;i++){
      const p = stripDiacritics(chars[i]);
      if(vowels.has(p)){
        chars[i] = addAcuteToVowel(p);
        // preserve diaeresis if present in original char
        // If original had diaeresis, re-add it by using precomposed forms when possible
        // (handled partially by addAcuteToVowel for ï/ü)
        break;
      }
    }
    return chars.join('');
  }

  function analyzeAndSuggest(input){
    const words = tokenizeWords(input);
    if(words.length===0) return {ok:false};

    // For phrases, focus on the last word.
    const w = words[words.length-1];
    const plain = stripDiacritics(w);

    const isIos = endsInIos(w);
    const syl = roughSyllables(w);
    const y1 = firstSyllableHasY(w);

    let exception = false;
    let exceptionType = '';
    if(properParoxy.has(plain)) { exception=true; exceptionType='proper-name tribrach → paroxytone (toy list)'; }
    if(tradPro.has(plain)) { exception=true; exceptionType='traditional exception → proparoxytone (toy list)'; }

    // Semantic pair handling: if matches, offer both.
    const pair = semanticPairs.find(p => p.plain === plain);

    let suggestion = null;
    let reason = '';

    if(pair){
      suggestion = {mode:'pair', pro: pair.pro, par: pair.par};
      reason = pair.note;
    } else if(!isIos){
      suggestion = {mode:'none', word:w};
      reason = "Rule here is about words ending in -ιος.";
    } else if(syl !== 3){
      // still suggest something, but warn
      const pos = (exception && properParoxy.has(plain)) ? 2 : 3;
      suggestion = {mode:'accent', pos, word: accentWord(w,pos)};
      reason = `Not clearly trisyllabic (rough count: ${syl}). Still placing an accent as a guess.`;
    } else {
      // Core toy rule
      if(exception){
        if(properParoxy.has(plain)){
          suggestion = {mode:'accent', pos:2, word: accentWord(w,2)};
          reason = `Listed as a proper-name type that tends to be paroxytone here.`;
        } else {
          suggestion = {mode:'accent', pos:3, word: accentWord(w,3)};
          reason = `Listed as a traditional exception that is proparoxytone here.`;
        }
      } else if(y1){
        suggestion = {mode:'accent', pos:3, word: accentWord(w,3)};
        reason = "Trisyllabic -ιος with υ in the first syllable → proparoxytone (Herodian’s generalization).";
      } else {
        suggestion = {mode:'accent', pos:2, word: accentWord(w,2)};
        reason = "Outside the specific ‘υ in first syllable’ condition; this toy defaults to paroxytone.";
      }
    }

    return {
      ok:true,
      word:w,
      plain,
      isIos,
      syl,
      y1,
      exception,
      exceptionType,
      suggestion
    };
  }

  function render(ana){
    if(!ana.ok){
      ends.textContent = '—';
      syll.textContent = '—';
      hasY.textContent = '—';
      exc.textContent = '—';
      out.textContent = '—';
      why.textContent = 'Enter a word above.';
      return;
    }

    ends.textContent = ana.isIos ? '-ιος' : '—';
    syll.textContent = String(ana.syl);
    hasY.textContent = ana.y1 ? 'yes' : 'no';

    if(ana.exception){
      exc.innerHTML = `yes <span class="badge warn">${ana.exceptionType}</span>`;
    } else {
      exc.innerHTML = 'no';
    }

    const sug = ana.suggestion;
    if(sug.mode==='pair'){
      out.innerHTML = `${sug.pro} <span class="badge good">proparox.</span> &nbsp;|&nbsp; ${sug.par} <span class="badge warn">parox.</span>`;
      why.textContent = sug ? ana.suggestion ? ana.suggestion.note || '' : '' : '';
      why.textContent = ana.suggestion ? (ana.suggestion.note || ana.suggestion.reason || '') : '';
      // fallback
      if(!why.textContent) why.textContent = 'This input matches a semantic “distinction” pair mentioned in the passage.';
    } else if(sug.mode==='accent'){
      out.textContent = sug.word;
      const label = sug.pos===3 ? 'proparoxytone (antepenult)' : 'paroxytone (penult)';
      why.textContent = `${label}. ${ana.exception ? ana.exceptionType + '. ' : ''}${ana.y1 && ana.syl===3 && ana.isIos && !ana.exception ? '' : ''}${ana.suggestion ? '' : ''}${ana.syl===3 && ana.isIos ? '' : ''}`;
      // Replace with clearer reason
      why.textContent = (ana.suggestion && ana.suggestion.reason) ? ana.suggestion.reason : why.textContent;
    } else {
      out.textContent = ana.word;
      why.textContent = ana.suggestion.reason;
    }
  }

  function force(pos){
    const words = tokenizeWords(inp.value);
    if(words.length===0) return;
    const w = words[words.length-1];
    const accented = accentWord(w,pos);
    // Replace last word in input with accented version
    words[words.length-1] = accented;
    inp.value = words.join(' ');
    update();
  }

  function update(){
    const ana = analyzeAndSuggest(inp.value);
    render(ana);
  }

  inp.addEventListener('input', update);
  btnPro.addEventListener('click', () => force(3));
  btnPar.addEventListener('click', () => force(2));
  btnClear.addEventListener('click', () => { inp.value=''; update(); });

  // --- Mini game ---
  const binPro = $('#binPro');
  const binPar = $('#binPar');
  const score = $('#score');

  const examples = [
    // proparoxy examples from the passage (mostly with υ-)
    {w:'Κύπριος', correct:'pro'},
    {w:'Τύριος', correct:'pro'},
    {w:'Πύλιος', correct:'pro'},
    {w:'Λύκιος', correct:'pro'},
    {w:'Σύριος', correct:'pro'},
    {w:'Μύσιος', correct:'pro'},
    {w:'κύκλιος', correct:'pro'},
    {w:'νύχιος', correct:'pro'},
    // paroxy proper-name type
    {w:'Τυχίος', correct:'par'},
    {w:'Κλυτίος', correct:'par'},
    {w:'Σχεδίος', correct:'par'}
  ];

  function makeChip(item){
    const d = document.createElement('div');
    d.className = 'chip';
    d.textContent = item.w;
    d.dataset.correct = item.correct;
    d.dataset.bin = 'pro';
    d.title = 'Click to move';
    d.addEventListener('click', () => {
      const now = d.dataset.bin;
      const next = now === 'pro' ? 'par' : 'pro';
      d.dataset.bin = next;
      (next==='pro' ? binPro : binPar).appendChild(d);
      updateScore();
    });
    return d;
  }

  function shuffle(arr){
    const a = arr.slice();
    for(let i=a.length-1;i>0;i--){
      const j = Math.floor(Math.random()*(i+1));
      [a[i],a[j]]=[a[j],a[i]];
    }
    return a;
  }

  function updateScore(){
    const chips = [...binPro.querySelectorAll('.chip'), ...binPar.querySelectorAll('.chip')];
    let right = 0;
    for(const c of chips){
      const inBin = c.parentElement === binPro ? 'pro' : 'par';
      if(inBin === c.dataset.correct) right++;
    }
    const total = chips.length;
    const msg = right===total
      ? `<b>${right}/${total}</b> correct. Nice—this matches the toy reading of Herodian’s list.`
      : `<b>${right}/${total}</b> correct. Keep sorting: proper-name tribrachs tend to go to the paroxytone box.`;
    score.innerHTML = msg;
  }

  function initGame(){
    binPro.innerHTML = '';
    binPar.innerHTML = '';
    for(const item of shuffle(examples)){
      // start all in pro bin to make it a game
      const chip = makeChip(item);
      binPro.appendChild(chip);
    }
    updateScore();
  }

  initGame();
  update();
})();

