const $ = (sel) => document.querySelector(sel);

const examples = [
  "αἰγυπιός",
  "χαραδριός",
  "ἐρῳδιός",
  "βομβυλιός",
  "ἀδρυφιός",
  "σκορπίος",
  "κωβίος",
  "διπλόος",
  "τριπλόος",
  "ἁπλόος",
  "δυσήκοος",
  "δίκροος",
  "πρόχοος",
  "ἁθρόος",
  "ἁθροος",
  "Θούριον",
  "Τίβειον"
];

// --- Greek helpers (very heuristic) ---
const combiningMarks = /[\u0300-\u036f]/g;

function nfd(s){return s.normalize('NFD');}
function stripDiacritics(s){
  // remove combining marks; keep base Greek letters
  return nfd(s).replace(combiningMarks, '').normalize('NFC');
}

function stripToLetters(s){
  return stripDiacritics(s).replace(/[^\p{L}]+/gu,'');
}

function isVowel(ch){
  return "αεηιουωΑΕΗΙΟΥΩ".includes(ch);
}

function syllabifyGreek(word){
  // Very rough syllabifier: split before each vowel group, attach preceding consonants.
  // Treat diphthongs as one nucleus: αι ει οι υι αυ ευ ου ηυ
  const w = stripToLetters(word);
  if(!w) return [];
  const lower = w.toLowerCase();

  const diph = new Set(["αι","ει","οι","υι","αυ","ευ","ου","ηυ","ωυ"]);

  let i=0;
  const sylls=[];
  let onset="";

  function takeVowelGroup(){
    if(i>=lower.length) return "";
    const a = lower[i];
    const b = lower[i+1] || "";
    if(isVowel(a)){
      const pair = a+b;
      if(b && isVowel(b) && diph.has(pair)){
        i+=2;
        return pair;
      }
      i+=1;
      return a;
    }
    return "";
  }

  while(i<lower.length){
    const ch = lower[i];
    if(!isVowel(ch)){
      onset += lower[i];
      i++;
      continue;
    }
    const nuc = takeVowelGroup();
    // collect following consonants until next vowel; keep last consonant for next onset if cluster
    let coda="";
    let j=i;
    while(j<lower.length && !isVowel(lower[j])){coda += lower[j]; j++;}

    // simple rule: if more than 1 consonant before next vowel, split before last consonant
    if(j<lower.length && coda.length>1){
      const keep = coda.slice(0, coda.length-1);
      const carry = coda.slice(coda.length-1);
      sylls.push(onset + nuc + keep);
      onset = carry;
      i = j;
    } else {
      sylls.push(onset + nuc + coda);
      onset = "";
      i = j;
    }
  }
  if(onset){
    // trailing consonants: attach to last syllable if any
    if(sylls.length) sylls[sylls.length-1] += onset;
    else sylls.push(onset);
  }
  return sylls.filter(x=>x.length);
}

function acuteOnSyllable(word, syllIndexFromEnd){
  // Place an acute on the first vowel of the target syllable (from end: 1=ultima,2=penult,3=antepenult)
  const original = stripToLetters(word);
  const sylls = syllabifyGreek(original);
  if(!sylls.length) return {form:"", sylls:[]};
  const idx = sylls.length - syllIndexFromEnd;
  if(idx<0 || idx>=sylls.length) return {form: original, sylls};

  const acuteMap = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };

  const out = sylls.map((s,si)=>{
    if(si!==idx) return s;
    // add acute to first vowel char
    for(let k=0;k<s.length;k++){
      const ch = s[k];
      const base = ch; // already stripped
      if(isVowel(base)){
        const rep = acuteMap[base] || base;
        return s.slice(0,k) + rep + s.slice(k+1);
      }
    }
    return s;
  });

  return {form: out.join(''), sylls};
}

function detectPattern(norm, syllCount){
  const lower = norm.toLowerCase();

  // Special lexical toggles
  if(lower === 'αθροος' || lower === 'αθρόος' || lower === 'ἁθροος' || lower === 'ἁθρόος'){
    return {
      label:"ἁθρόος / ἄθροος (two accents in the passage)",
      options:[
        {name:"‘gathered’ (paroxytone)", target:2, note:"Herodian: ἁθρόος (from ἀθροίζειν) is paroxytone."},
        {name:"‘sudden’ (proparoxytone)", target:3, note:"Herodian: ἁθρόος (meaning ‘sudden’) is proparoxytone."}
      ],
      note:"This toy can’t know the sense; choose one."
    };
  }

  // -πλοος
  if(lower.endsWith('πλοος')){
    return {
      label:"-πλοος full form",
      options:[{name:"paroxytone", target:2, note:"Herodian: διπλόος, τριπλόος, ἁπλόος are paroxytone."}],
      note:"Treating -πλοος as simple (not compound) per the passage."
    };
  }

  // -ιος
  if(lower.endsWith('ιος')){
    // exceptions mentioned
    if(lower === 'σκορπιος' || lower === 'κωβιος'){
      return {
        label:"-ιος (special: treated as trisyllables)",
        options:[{name:"paroxytone", target:2, note:"Herodian: σκορπίος, κωβίος are paroxytone as trisyllables."}],
        note:"Toy follows the named exceptions."
      };
    }
    if(syllCount>3){
      return {
        label:"-ιος over-trisyllabic",
        options:[{name:"oxytone", target:1, note:"Herodian: over-trisyllabic -ιος (esp. animal terms) are oxytone."}],
        note:"The passage frames this for ‘irrational animals’; toy applies it broadly."
      };
    }
    return {
      label:"-ιος (≤ 3 syllables)",
      options:[{name:"(no strong rule here)", target:2, note:"Toy default: paroxytone for short -ιος words."}],
      note:"Herodian’s cited rule is for >3 syllables; this is just a default."
    };
  }

  // pure -ος with penult = ο and >2 syllables
  if(lower.endsWith('ος') && syllCount>2){
    const sylls = syllabifyGreek(norm);
    const penult = sylls[sylls.length-2] || "";
    if(penult.includes('ο')){
      return {
        label:"pure -ος with penult ο",
        options:[{name:"proparoxytone", target:3, note:"Herodian: such words are proparoxytone."}],
        note:"He then notes many compounds vary; toy doesn’t detect compounds reliably."
      };
    }
  }

  return {
    label:"(no match)",
    options:[{name:"toy default", target:2, note:"Default guess: paroxytone (acute on penult)."}],
    note:"Try an -ιος, -ος, or -πλοος example from the passage."
  };
}

// --- UI wiring ---
let current = {
  input:"",
  norm:"",
  sylls:[],
  pattern:null,
  chosenTarget:2,
  targetForm:""
};

function render(){
  $('#norm').textContent = current.norm || '—';
  $('#syll').textContent = current.sylls.length ? current.sylls.join(' · ') + `   (${current.sylls.length})` : '—';
  $('#pattern').textContent = current.pattern ? current.pattern.label : '—';

  const sug = current.targetForm || '—';
  $('#suggest').textContent = sug;
  $('#targetForm').textContent = sug;

  $('#notes').textContent = current.pattern ? current.pattern.note : '—';

  // toggles
  const t = $('#toggles');
  t.innerHTML = '';
  if(current.pattern && current.pattern.options && current.pattern.options.length>1){
    current.pattern.options.forEach((opt, idx)=>{
      const b = document.createElement('button');
      b.className = 'pill';
      b.type = 'button';
      b.setAttribute('aria-pressed', String(current.chosenTarget === opt.target));
      b.textContent = opt.name;
      b.addEventListener('click', ()=>{
        current.chosenTarget = opt.target;
        current.targetForm = acuteOnSyllable(current.norm, current.chosenTarget).form;
        render();
        buildGameButtons();
        setResult('—');
      });
      t.appendChild(b);

      const note = document.createElement('div');
      note.style.flexBasis = '100%';
      note.style.color = 'var(--muted)';
      note.style.fontSize = '13px';
      note.textContent = opt.note;
      t.appendChild(note);
    });
  } else if(current.pattern && current.pattern.options && current.pattern.options.length===1){
    const opt = current.pattern.options[0];
    const span = document.createElement('div');
    span.className = 'v';
    span.style.color = 'var(--muted)';
    span.textContent = opt.note;
    t.appendChild(span);
  }
}

function setResult(msg, kind){
  const el = $('#result');
  el.textContent = msg;
  el.classList.remove('good','bad');
  if(kind) el.classList.add(kind);
}

function analyze(){
  const raw = $('#inp').value.trim();
  const norm = stripToLetters(raw);
  const sylls = syllabifyGreek(norm);
  const pattern = detectPattern(norm, sylls.length);
  const chosenTarget = pattern.options[0].target;
  const targetForm = acuteOnSyllable(norm, chosenTarget).form;

  current = {input:raw, norm, sylls, pattern, chosenTarget, targetForm};
  render();
  buildGameButtons();
  $('#yourForm').textContent = '—';
  setResult('Click a syllable to place the acute.');
}

function buildGameButtons(){
  const box = $('#syllBtns');
  box.innerHTML = '';
  if(!current.sylls.length){
    return;
  }
  // show syllables left-to-right; clicking chooses which syllable gets acute
  current.sylls.forEach((s, i)=>{
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'syllBtn';
    btn.textContent = s;
    btn.title = 'Place acute on this syllable';
    btn.addEventListener('click', ()=>{
      [...box.querySelectorAll('.syllBtn')].forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');

      const fromEnd = current.sylls.length - i;
      const your = acuteOnSyllable(current.norm, fromEnd).form;
      $('#yourForm').textContent = your;

      if(current.targetForm && your === current.targetForm){
        setResult('Match! Your accent equals the suggested pattern.', 'good');
      } else {
        setResult('Not the suggested one—try another syllable.', 'bad');
      }
    });
    box.appendChild(btn);
  });
}

$('#btnAnalyze').addEventListener('click', analyze);
$('#btnRandom').addEventListener('click', ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#inp').value = ex;
  analyze();
});
$('#btnClear').addEventListener('click', ()=>{
  $('#inp').value = '';
  current = {input:"", norm:"", sylls:[], pattern:null, chosenTarget:2, targetForm:""};
  render();
  $('#syllBtns').innerHTML='';
  $('#yourForm').textContent='—';
  $('#targetForm').textContent='—';
  setResult('—');
});

// Enter key
$('#inp').addEventListener('keydown', (e)=>{
  if(e.key === 'Enter') analyze();
});

// initial
render();
setResult('Type a word and click Analyze.');

