(() => {
  const $ = (sel) => document.querySelector(sel);

  const inp = $('#inp');
  const btnAnalyze = $('#btnAnalyze');
  const btnRandom = $('#btnRandom');
  const btnClear = $('#btnClear');
  const chkNormalize = $('#chkNormalize');
  const chkSuggest = $('#chkSuggest');

  const rInput = $('#rInput');
  const rNorm = $('#rNorm');
  const rSyl = $('#rSyl');
  const rOs = $('#rOs');
  const rPenult = $('#rPenult');
  const rPred = $('#rPred');
  const rSug = $('#rSug');
  const rNote = $('#rNote');

  const samples = [
    'πατρῷος','ἡρῷος','Ἡρῷος','ἠῷος','Ἀχελῷος','αἰδῷος','Μινῷος','Σαρδῷος','Πυθῷος','Ληθῷος','Ἰνδῷος','Γελῷος','ὀρεσκῷος',
    'κολῳός','λαγωός','πατρωός','πατρυιός','Ἄθωος','Ἀκρόθωοι','θῳῆς'
  ];

  // --- Greek helpers (toy-level) ---
  const combiningMarks = /[\u0300-\u036f]/g; // includes acute/circumflex/breathings/dialytika etc.

  function nfd(s){ return (s || '').normalize('NFD'); }
  function nfc(s){ return (s || '').normalize('NFC'); }

  function stripCombining(s){
    return nfd(s).replace(combiningMarks,'');
  }

  // Keep iota subscript as a *letter* marker: ᾳ ῃ ῳ -> a_i, e_i, o_i (but still display Greek)
  // For pattern checks we mainly need to detect ῳ in penult.
  function normalizeForCheck(s){
    // remove punctuation/spaces, lowercase, strip combining marks but keep base letters like ῳ.
    let t = (s || '').trim();
    t = t.replace(/[··.,;:!?\-—()\[\]{}"'«»]/g,'');
    t = t.replace(/\s+/g,'');
    // strip combining marks; this turns ῷ into ῳ (since circumflex is combining)
    t = stripCombining(t);
    return t.toLowerCase();
  }

  const vowels = new Set([
    'α','ε','η','ι','ο','υ','ω',
    'ᾳ','ῃ','ῳ',
    'ά','έ','ή','ί','ό','ύ','ώ',
    'ϊ','ϋ','ΐ','ΰ'
  ]);

  function isVowelChar(ch){
    return vowels.has(ch);
  }

  // Very rough syllable count: count vowel groups in the normalized string.
  function countSyllablesToy(s){
    const t = normalizeForCheck(s);
    let count = 0;
    let inV = false;
    for (const ch of t){
      const v = isVowelChar(ch);
      if (v && !inV) count++;
      inV = v;
    }
    return count;
  }

  function endsInOs(s){
    const t = normalizeForCheck(s);
    return t.endsWith('ος');
  }

  function splitIntoSyllablesToy(s){
    // Build syllables by vowel-group boundaries; attach following consonants until next vowel group.
    const t = normalizeForCheck(s);
    const chars = Array.from(t);
    const syl = [];
    let cur = '';
    let seenVowelInCur = false;

    for (let i=0;i<chars.length;i++){
      const ch = chars[i];
      const v = isVowelChar(ch);
      if (!cur){
        cur = ch;
        seenVowelInCur = v;
        continue;
      }
      if (v && seenVowelInCur){
        // start new syllable at new vowel group
        syl.push(cur);
        cur = ch;
        seenVowelInCur = true;
      } else {
        cur += ch;
        if (v) seenVowelInCur = true;
      }
    }
    if (cur) syl.push(cur);
    return syl;
  }

  function penultHasOmegaIotaSub(s){
    const syl = splitIntoSyllablesToy(s);
    if (syl.length < 2) return false;
    const penult = syl[syl.length - 2];
    // check for ῳ (omega with iota subscript) in penult
    return penult.includes('ῳ');
  }

  function applyToyAccentSuggestion(original){
    // We do NOT compute real accentuation. We only add a visual marker ^ over the antepenult vowel group.
    // Strategy: return original + highlighted syllable index info; and a "marked" version using brackets.
    const syl = splitIntoSyllablesToy(original);
    if (syl.length < 3) return { marked: '—', where: null };
    const idx = syl.length - 3; // antepenult

    // Reconstruct a "normalized" Greek string with brackets around antepenult syllable.
    // This is not the same as the original spelling (accents/breathings removed), but it shows placement.
    const markedNorm = syl.map((x,i)=> i===idx ? '⟦'+x+'⟧' : x).join('');

    // Also try to produce a "pretty" suggestion by inserting a combining circumflex on the first omega/eta/alpha in that syllable.
    // This is very approximate and may look odd; if we can't, just show bracketed.
    const CIRC = '\u0342'; // combining perispomeni
    let pretty = normalizeForCheck(original);

    // Map syllable boundaries to indices in pretty
    const syl2 = splitIntoSyllablesToy(original);
    let start = 0;
    for (let i=0;i<idx;i++) start += syl2[i].length;
    const target = syl2[idx];

    const targetStart = start;
    const targetEnd = start + target.length;
    const before = pretty.slice(0,targetStart);
    const mid = pretty.slice(targetStart,targetEnd);
    const after = pretty.slice(targetEnd);

    // find first vowel in mid and add circumflex combining mark after it
    let inserted = false;
    let midArr = Array.from(mid);
    for (let i=0;i<midArr.length;i++){
      if (isVowelChar(midArr[i])){
        midArr[i] = nfc(nfd(midArr[i]) + CIRC);
        inserted = true;
        break;
      }
    }
    const prettyAttempt = inserted ? nfc(before + midArr.join('') + after) : null;

    return {
      marked: prettyAttempt ? prettyAttempt : markedNorm,
      where: idx
    };
  }

  function setNote(text, kind){
    rNote.textContent = text;
    rNote.classList.remove('good','bad');
    if (kind) rNote.classList.add(kind);
  }

  function analyze(){
    const raw = inp.value.trim();
    if (!raw){
      rInput.textContent = '—';
      rNorm.textContent = '—';
      rSyl.textContent = '—';
      rOs.textContent = '—';
      rPenult.textContent = '—';
      rPred.textContent = '—';
      rSug.textContent = '—';
      setNote('Type a word like πατρῷος or λαγωός, then click Analyze.', null);
      return;
    }

    const norm = chkNormalize.checked ? normalizeForCheck(raw) : raw;
    const sylCount = countSyllablesToy(raw);
    const os = endsInOs(raw);
    const pen = penultHasOmegaIotaSub(raw);
    const longEnough = sylCount > 2;

    rInput.textContent = raw;
    rNorm.textContent = norm;
    rSyl.textContent = String(sylCount);
    rOs.textContent = os ? 'yes' : 'no';
    rPenult.textContent = pen ? 'yes (…ῳ…)': 'no';

    let pred;
    if (os && pen && longEnough){
      pred = 'Predict: προπερισπᾶται (circumflex on antepenult)';
      rPred.textContent = pred;
      if (chkSuggest.checked){
        const sug = applyToyAccentSuggestion(raw);
        rSug.textContent = sug.marked;
      } else {
        rSug.textContent = '—';
      }
      setNote('Matches Herodian’s pattern: -ος, penult ῳ (ω + iota subscript), and >2 syllables → antepenult circumflex (toy prediction).', 'good');
    } else {
      const reasons = [];
      if (!os) reasons.push('not -ος');
      if (!pen) reasons.push('penult not ῳ (no iota subscript)');
      if (!longEnough) reasons.push('not >2 syllables');
      rPred.textContent = 'Rule not triggered';
      rSug.textContent = '—';
      setNote('Doesn\'t meet the toy conditions ('+reasons.join(', ')+'). Herodian notes exceptions/contrasts like λαγωός, πατρωός (acute, no iota subscript) and Ἄθωος (place-name without iota).', 'bad');
    }
  }

  function buildChips(){
    const box = $('#chips');
    box.innerHTML = '';
    for (const w of samples){
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'chip';
      b.textContent = w;
      b.addEventListener('click', () => { inp.value = w; analyze(); });
      box.appendChild(b);
    }
  }

  btnAnalyze.addEventListener('click', analyze);
  btnClear.addEventListener('click', () => { inp.value=''; analyze(); inp.focus(); });
  btnRandom.addEventListener('click', () => {
    const w = samples[Math.floor(Math.random()*samples.length)];
    inp.value = w;
    analyze();
  });
  inp.addEventListener('keydown', (e) => { if (e.key === 'Enter') analyze(); });

  buildChips();
  analyze();
})();

