const $ = (sel) => document.querySelector(sel);

// --- Greek accent utilities (toy-level) ---
const COMBINING = {
  acute: "\u0301",
  grave: "\u0300",
  circumflex: "\u0342",
  diaeresis: "\u0308",
  smooth: "\u0313",
  rough: "\u0314",
  iotaSub: "\u0345",
};

function nfd(s){ return (s||"").normalize('NFD'); }
function nfc(s){ return (s||"").normalize('NFC'); }

function stripAccentsKeepBreathings(s){
  // remove acute/grave/circumflex only
  return nfc(nfd(s).replace(/[\u0300\u0301\u0342]/g, ""));
}

function stripAllDiacritics(s){
  return nfc(nfd(s).replace(/[\u0300-\u036f]/g, ""));
}

function hasAnyAccent(s){
  const d = nfd(s);
  return /[\u0300\u0301\u0342]/.test(d);
}

function detectAccentType(s){
  const d = nfd(s);
  if (d.includes(COMBINING.circumflex)) return "circumflex";
  if (d.includes(COMBINING.acute)) return "acute";
  if (d.includes(COMBINING.grave)) return "grave";
  return "none";
}

function highlightAccentedVowel(word){
  // Find first base letter that carries an accent mark in NFD.
  const d = nfd(word);
  let out = "";
  for (let i=0; i<d.length; i++){
    const ch = d[i];
    // base letter?
    const isComb = /[\u0300-\u036f]/.test(ch);
    if (!isComb){
      // collect following combining marks
      let j=i+1;
      let comb = "";
      while (j<d.length && /[\u0300-\u036f]/.test(d[j])){ comb += d[j]; j++; }
      const hasAccent = /[\u0300\u0301\u0342]/.test(comb);
      const chunk = nfc(ch + comb);
      if (hasAccent){
        out += `<span class="hl">${escapeHtml(chunk)}</span>`;
      } else {
        out += escapeHtml(chunk);
      }
      i = j-1;
    }
  }
  return out;
}

function escapeHtml(s){
  return (s||"")
    .replaceAll("&","&amp;")
    .replaceAll("<","&lt;")
    .replaceAll(">","&gt;")
    .replaceAll('"',"&quot;")
    .replaceAll("'","&#39;");
}

// --- Very simplified morphology for -αιος ---
function guessAiosFromBase(base){
  const original = (base||"").trim();
  if (!original) return { ok:false, msg:"Type a base word." };

  // Hard-coded exceptions mentioned in/near the passage.
  const exceptions = new Map([
    ["Πειραιός", {form:"Πειραιός", label:"oxytone (acute on ultima)", why:"Harbor-name; contrasted accent in the tradition."}],
    ["Πείραιος", {form:"Πείραιος", label:"proparoxytone (acute on antepenult)", why:"From verb πειρῶ (as Herodian notes)."}],
    ["Ἥραιος", {form:"Ἥραιος", label:"proparoxytone (acute on antepenult)", why:"Contrast-form; Herodian treats it as special."}],
    ["δίκαιος", {form:"δίκαιος", label:"proparoxytone (acute on antepenult)", why:"Listed as proparoxytone exception."}],
    ["βίαιος", {form:"βίαιος", label:"proparoxytone (acute on antepenult)", why:"Listed as proparoxytone exception."}],
    ["φύλαιος", {form:"φύλαιος", label:"proparoxytone (acute on antepenult)", why:"Listed as proparoxytone exception."}],
    ["δείλαιος", {form:"δείλαιος", label:"proparoxytone (acute on antepenult)", why:"Listed as proparoxytone exception."}],
    ["ἐπιπόλαιος", {form:"ἐπιπόλαιος", label:"(often) circumflexed by many; debated", why:"Herodian: not from ἐπιπολῆς but ἐπιπολάζω; many still circumflex."}],
    ["Ἐπιπολαῖος", {form:"Ἐπιπολαῖος", label:"circumflex on penult (…αῖος)", why:"Ethnic adjective form."}],
  ]);

  if (exceptions.has(original)){
    const ex = exceptions.get(original);
    return { ok:true, derived: ex.form, accentLabel: ex.label, explain: `Exception (hard-coded): ${ex.why}` };
  }

  // Normalize for building: remove accent marks but keep breathings etc.
  const baseNoAccent = stripAccentsKeepBreathings(original);
  const baseBare = stripAllDiacritics(original);

  // Determine a crude stem by chopping common endings.
  let stem = baseNoAccent;
  let rule = "";

  // If ends with -ος, drop it.
  if (/ος$/u.test(baseBare)){
    stem = baseNoAccent.slice(0, -2);
    rule = "Base ends in -ος → drop -ος + add -αιος.";
  } else if (/η$/u.test(baseBare)){
    stem = baseNoAccent.slice(0, -1);
    rule = "Base ends in -η → drop -η + add -αιος.";
  } else if (/α$/u.test(baseBare)){
    stem = baseNoAccent.slice(0, -1);
    rule = "Base ends in -α → drop -α + add -αιος.";
  } else {
    // fallback: just append
    stem = baseNoAccent;
    rule = "Unknown ending → just append -αιος (toy fallback).";
  }

  // Build derived form.
  let derived = stem + "αιος";

  // Accent: default to circumflex on the alpha of -αι- (i.e. …αῖος).
  // Implement by replacing the first occurrence of "αιος" at the end with "α" + circumflex + "ιος".
  // In NFD: α + \u0342 + ι ο ς
  const dNfd = nfd(derived);
  const replaced = dNfd.replace(/αιος$/u, "α" + COMBINING.circumflex + "ιος");
  derived = nfc(replaced);

  const accentLabel = "circumflex on penult (…αῖος)";
  const explain = `${rule} Then I applied the passage’s default pattern: many -αιος forms show …αῖος.`;

  return { ok:true, derived, accentLabel, explain };
}

// --- Accent spotter ---
function spot(word){
  const w = (word||"").trim();
  if (!w) return { ok:false, html:"—", meta:"Type a word to inspect." };
  const typ = detectAccentType(w);
  const has = hasAnyAccent(w);
  const meta = has
    ? `Accent detected: <span class="badge good">${typ}</span> (highlighted in green)`
    : `No accent mark detected. (Try polytonic input like <span class="ex">ἀρχαῖος</span>.)`;
  return { ok:true, html: highlightAccentedVowel(w), meta };
}

// --- UI wiring ---
const examples = [
  {base:"ἀρχή", derived:"ἀρχαῖος"},
  {base:"κορυφή", derived:"κορυφαῖος"},
  {base:"πηγή", derived:"πηγαῖος"},
  {base:"σπουδή", derived:"σπουδαῖος"},
  {base:"εὐνή", derived:"εὐναῖος"},
  {base:"ὥρα", derived:"ὡραῖος"},
  {base:"θύρα", derived:"θυραῖος"},
  {base:"Πέλλα", derived:"Πελλαῖος"},
  {base:"Οἴτη", derived:"Οἰταῖος"},
  {base:"χέρσος", derived:"χερσαῖος"},
  {base:"γῆρας", derived:"γηραιός"},
  {base:"κράτος", derived:"κραταιός"},
  {base:"Πείραιος", derived:"Πείραιος"},
  {base:"Ἥραιος", derived:"Ἥραιος"},
];

function renderChips(){
  const box = $("#chips");
  box.innerHTML = "";
  for (const ex of examples){
    const b = document.createElement('button');
    b.className = 'chip';
    b.type = 'button';
    b.textContent = `${ex.base} → ${ex.derived}`;
    b.addEventListener('click', () => {
      $("#baseInput").value = ex.base;
      $("#spotInput").value = ex.derived;
      doBuild();
      doSpot();
      $("#baseInput").focus();
    });
    box.appendChild(b);
  }
}

function doBuild(){
  const base = $("#baseInput").value;
  const res = guessAiosFromBase(base);
  if (!res.ok){
    $("#derivedOut").textContent = "—";
    $("#accentOut").textContent = "—";
    $("#explainOut").textContent = res.msg || "—";
    return;
  }
  $("#derivedOut").textContent = res.derived;
  $("#accentOut").innerHTML = `<span class="badge good">rule</span> ${escapeHtml(res.accentLabel)}`;
  $("#explainOut").textContent = res.explain;

  // Also populate spotter with derived form for convenience.
  $("#spotInput").value = res.derived;
  doSpot();
}

function doSpot(){
  const w = $("#spotInput").value;
  const res = spot(w);
  $("#spotOut").innerHTML = res.html;
  $("#spotMeta").innerHTML = res.meta;
}

function clearAll(){
  $("#baseInput").value = "";
  $("#spotInput").value = "";
  $("#derivedOut").textContent = "—";
  $("#accentOut").textContent = "—";
  $("#explainOut").textContent = "—";
  $("#spotOut").textContent = "—";
  $("#spotMeta").textContent = "—";
  $("#baseInput").focus();
}

$("#buildBtn").addEventListener('click', doBuild);
$("#spotBtn").addEventListener('click', doSpot);
$("#clearBtn").addEventListener('click', clearAll);

$("#baseInput").addEventListener('keydown', (e)=>{
  if (e.key === 'Enter') doBuild();
});
$("#spotInput").addEventListener('keydown', (e)=>{
  if (e.key === 'Enter') doSpot();
});

renderChips();
// preload a friendly example
$("#baseInput").value = "ἀρχή";
doBuild();

