:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --card:#1e2238;
  --text:#e9ecff;
  --muted:#b8bfe6;
  --line:#2c3254;
  --accent:#8be9fd;
  --accent2:#ffd479;
  --bad:#ff6b6b;
  --good:#7CFFB2;
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
}

*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, #1a1f3a 0%, var(--bg) 55%); color:var(--text); font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Noto Sans", "Liberation Sans", sans-serif;}

.wrap{max-width:1100px;margin:0 auto;padding:18px 16px 28px;}
.top h1{margin:0 0 6px;font-size:20px;letter-spacing:.2px}
.sub{margin:0;color:var(--muted);line-height:1.35;font-size:13.5px}

.panel{margin-top:14px;background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02)); border:1px solid var(--line); border-radius:14px; padding:14px;}

.controls{padding:6px 6px 10px}
.lbl{display:block;font-size:12px;color:var(--muted);margin:6px 0}
.lbl.small{font-size:11px;margin-top:10px}

.row{display:flex;gap:10px;align-items:center}
.in{flex:1;min-width:220px;background:#0c0f1d;border:1px solid var(--line);color:var(--text);padding:10px 12px;border-radius:10px;font-size:16px;outline:none}
.in:focus{border-color:#3b4476; box-shadow:0 0 0 3px rgba(139,233,253,.12)}

.btn{background:linear-gradient(180deg, rgba(139,233,253,.22), rgba(139,233,253,.12)); border:1px solid rgba(139,233,253,.35); color:var(--text); padding:10px 12px;border-radius:10px; cursor:pointer; font-weight:650}
.btn:hover{filter:brightness(1.08)}
.btn:active{transform:translateY(1px)}
.btn.ghost{background:transparent;border:1px solid var(--line);color:var(--muted);font-weight:600}

.toggles{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
.chip{display:flex;align-items:center;gap:8px;padding:8px 10px;border-radius:999px;border:1px solid var(--line);background:rgba(0,0,0,.12);font-size:12.5px;color:var(--muted);user-select:none}
.chip input{accent-color:var(--accent)}

.mini{display:flex;gap:12px;flex-wrap:wrap;margin-top:10px}
.miniCol{min-width:240px;flex:1}
.sel{width:100%;background:#0c0f1d;border:1px solid var(--line);color:var(--text);padding:9px 10px;border-radius:10px;outline:none}

.hint{margin:10px 0 0;color:var(--muted);font-size:12.5px;line-height:1.35}

.out{display:grid;grid-template-columns:1.1fr .9fr;gap:12px;margin-top:12px}
@media (max-width: 900px){.out{grid-template-columns:1fr}}

.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:12px}
.card h2{margin:0 0 8px;font-size:14px;color:#dfe6ff;letter-spacing:.2px}

.kv{display:grid;grid-template-columns:140px 1fr;gap:10px;align-items:baseline;padding:8px 0;border-top:1px dashed rgba(184,191,230,.18)}
.kv:first-of-type{border-top:none}
.k{color:var(--muted);font-size:12px}
.v{font-size:16px}

.greek{font-family: "Noto Serif", "Times New Roman", Times, serif;}
.greek.big{font-size:20px}
.mono{font-family:var(--mono)}

.explain{margin-top:10px;border-top:1px solid rgba(184,191,230,.18);padding-top:10px}
.explain summary{cursor:pointer;color:var(--accent);font-weight:650}
.explain ul{margin:8px 0 0 18px;color:var(--muted);font-size:12.5px;line-height:1.35}

.wordbank{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}
.w{padding:7px 10px;border-radius:999px;border:1px solid var(--line);background:rgba(0,0,0,.12);cursor:pointer;font-size:13px;color:var(--text)}
.w:hover{border-color:#3b4476}
.w.good{border-color:rgba(124,255,178,.45); background:rgba(124,255,178,.08)}
.w.bad{border-color:rgba(255,107,107,.45); background:rgba(255,107,107,.08)}

.score{display:flex;gap:14px;margin-top:10px;color:var(--muted);font-size:12.5px;border-top:1px solid rgba(184,191,230,.18);padding-top:10px}

.foot{margin-top:10px;color:var(--muted)}
.small{font-size:12.5px;line-height:1.35}

mark{background:rgba(255,212,121,.22);color:var(--text);padding:0 4px;border-radius:6px;border:1px solid rgba(255,212,121,.25)}

