const $ = (sel, root=document) => root.querySelector(sel);

const examples = [
  "κνέφας",
  "οὖδας",
  "ῥαιός",
  "ἁραιός",
  "βαιός",
  "ἠβαιός",
  "Ἀθῆναι",
  "Θῆβαι",
  "Ῥώμη",
  "Αἴγαι",
  "Γαλιλαία",
  "Ἑβραῖος",
  "Ἀχαιός",
  "Ἐρυσίχαιος"
];

const bankWords = [
  "Ἀθηναῖος","Θηβαῖος","Ῥωμαῖος","Αἰγαῖος","Ἀγραῖος","Βακκαῖος","Γαλιλαῖος","Γενοαῖος",
  "Δερραῖος","Δερσαῖοι","Δυρβαῖος","Ἑβραῖος","Θαμαναῖος","Ἰβαῖος","Λαιαῖος","Παναῖος",
  "Μιναῖος","Πάρθοι","Πάρθιοι","Πλαδαραῖος","Πλαραῖος","Ῥονδαῖος","Σινδοναῖος","Χωραμναῖος",
  "κνέφας","κνεφαῖος","οὖδας","οὐδαῖος","ῥαιός","ἁραιός","ἀραῖος","Ἀχαιός","Ἐρυσίχαιος"
];

function normalizeGreek(s){
  return (s||"")
    .trim()
    .replace(/\s+/g," ")
    .replace(/[··]/g,"·");
}

function stripPunct(s){
  return s.replace(/[\.,;:!?··\(\)\[\]«»“”"']/g,"");
}

function endsWithAny(s, arr){
  return arr.find(x => s.endsWith(x));
}

function makeEthnic(base){
  // Very rough heuristics: remove common place-name endings, then add -αῖος.
  let w = stripPunct(normalizeGreek(base));
  if(!w) return "";

  // If already looks like -αιος/-αῖος, keep it.
  if(/αιος$/i.test(w) || /αῖος$/.test(w) || /αίος$/.test(w)) return w;

  // Common endings to drop
  const drop = ["αι", "ᾶι", "η", "ῃ", "α", "ᾱ", "ᾳ", "ος", "ον", "ηι", "οι", "αις", "ης", "ας", "ων", "ου"];
  const hit = endsWithAny(w, drop);
  if(hit){
    w = w.slice(0, w.length - hit.length);
  }

  // If ends with ν, often keep (Ἀθην-)
  // If ends with μ, keep (Ῥωμ-)

  // Avoid empty
  if(!w) return "";

  return w + "αῖος";
}

function syllabifyRough(word){
  // Not real syllabification; we just count vowel groups.
  // Greek vowels (incl. common diacritics) approximated by base letters.
  const w = word;
  const vowels = new Set(["α","ε","η","ι","ο","υ","ω","ά","έ","ή","ί","ό","ύ","ώ","ᾶ","ῖ","ῦ","ῶ","ὰ","ὲ","ὴ","ὶ","ὸ","ὺ","ὼ","ἀ","ἁ","ἂ","ἃ","ἄ","ἅ","ἆ","ἇ","ἐ","ἑ","ἒ","ἓ","ἔ","ἕ","ἠ","ἡ","ἢ","ἣ","ἤ","ἥ","ἦ","ἧ","ἰ","ἱ","ἲ","ἳ","ἴ","ἵ","ἶ","ἷ","ὀ","ὁ","ὂ","ὃ","ὄ","ὅ","ὐ","ὑ","ὒ","ὓ","ὔ","ὕ","ὖ","ὗ","ὠ","ὡ","ὢ","ὣ","ὤ","ὥ","ὦ","ὧ","ϊ","ΐ","ϋ","ΰ","ῒ","ΐ","ῢ","ΰ"]);

  let groups = [];
  let cur = "";
  let inV = false;
  for(const ch of w){
    const isV = vowels.has(ch);
    if(isV){
      if(!inV && cur){ groups.push(cur); cur = ""; }
      inV = true;
      cur += ch;
    } else {
      if(inV){ groups.push(cur); cur = ""; }
      inV = false;
      cur += ch;
    }
  }
  if(cur) groups.push(cur);

  // Merge into pseudo-syllables by attaching consonant chunks to following vowel chunk.
  // Example: ["Ἀθ","η","ν","αῖ","ος"] -> ["Ἀθη","ναῖ","ος"] (approx)
  let syl = [];
  for(let i=0;i<groups.length;i++){
    const g = groups[i];
    const startsV = vowels.has(g[0]);
    if(startsV){
      // attach previous consonant chunk if any
      if(syl.length && !vowels.has(syl[syl.length-1].slice(-1))){
        syl[syl.length-1] += g;
      } else {
        syl.push(g);
      }
    } else {
      // consonant chunk: start new syllable chunk
      syl.push(g);
    }
  }

  // Second pass: if a syllable has no vowel, attach it to next syllable.
  function hasVowel(str){
    for(const c of str){ if(vowels.has(c)) return true; }
    return false;
  }
  let out = [];
  for(let i=0;i<syl.length;i++){
    if(!hasVowel(syl[i]) && i+1<syl.length){
      syl[i+1] = syl[i] + syl[i+1];
    } else {
      out.push(syl[i]);
    }
  }
  return out.filter(x=>x);
}

function markAntepenult(word){
  const w = stripPunct(normalizeGreek(word));
  if(!w) return "";
  const syl = syllabifyRough(w);
  if(syl.length < 3) return w + " (too short)";
  const idx = syl.length - 3;
  return syl.map((s,i)=> i===idx ? ("^"+s) : s).join("");
}

function pleonasm(word, letter, mode){
  let w = stripPunct(normalizeGreek(word));
  if(!w) return "";

  const startsRho = /^ρ/i.test(w) || /^ῥ/.test(w) || /^ῤ/.test(w);

  if(letter === "α"){
    if(mode === "off") return "α" + w;
    if(mode === "force") return "ἁ" + w;
    if(mode === "auto"){
      if(startsRho) return "ἁ" + w; // visual cue: rough breathing moved to alpha
      return "α" + w;
    }
  }

  // For η/ι just prefix the plain letter.
  return letter + w;
}

function looksLikeAios(word){
  const w = stripPunct(normalizeGreek(word));
  return /αιος$/.test(w) || /αῖος$/.test(w) || /αίος$/.test(w) || /αῖοι$/.test(w) || /αῖοι$/.test(w);
}

function run(){
  const input = normalizeGreek($("#inWord").value);
  const norm = stripPunct(input);
  $("#norm").textContent = norm || "—";

  const doEth = $("#optEthnic").checked;
  const doAcc = $("#optPropercirc").checked;
  const doPleo = $("#optPleonasm").checked;

  let eth = doEth ? makeEthnic(norm) : "";
  $("#ethnic").textContent = eth || "—";

  let acc = "";
  if(doAcc){
    const target = eth || norm;
    acc = target ? markAntepenult(target) : "";
  }
  $("#accent").textContent = acc || "—";

  let pl = "";
  if(doPleo){
    const letter = $("#pleonLetter").value;
    const mode = $("#breathMode").value;
    const target = norm;
    pl = target ? pleonasm(target, letter, mode) : "";
  }
  $("#pleo").textContent = pl || "—";
}

function loadExample(){
  const w = examples[Math.floor(Math.random()*examples.length)];
  $("#inWord").value = w;
  run();
}

function buildBank(){
  const bank = $("#bank");
  bank.innerHTML = "";
  for(const w of bankWords){
    const b = document.createElement("button");
    b.className = "w greek";
    b.type = "button";
    b.textContent = w;
    b.addEventListener("click", () => {
      const clicks = +$("#clicks").textContent + 1;
      $("#clicks").textContent = String(clicks);

      const looks = looksLikeAios(w);
      if(looks){
        b.classList.remove("bad");
        b.classList.add("good");
        $("#looks").textContent = String(+$("#looks").textContent + 1);
      } else {
        b.classList.remove("good");
        b.classList.add("bad");
      }

      $("#inWord").value = w;
      run();
    });
    bank.appendChild(b);
  }
}

$("#btnGo").addEventListener("click", run);
$("#btnRandom").addEventListener("click", loadExample);
$("#inWord").addEventListener("keydown", (e)=>{ if(e.key==="Enter") run(); });
for(const id of ["#optEthnic","#optPropercirc","#optPleonasm","#pleonLetter","#breathMode"]){
  $(id).addEventListener("change", run);
}

buildBank();
loadExample();

const word=document.querySelector('#word'), context=document.querySelector('#context'), answer=document.querySelector('#answer');
const plain=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const examples={αθηναιος:'Ἀθηναῖος',ειρηναιος:'Εἰρηναῖος',αρουραιος:'ἀρουραῖος',αγοραιος:'ἀγοραῖος',δωδωναιος:'Δωδωναῖος'};
function show(form,note){answer.replaceChildren();const title=document.createElement('strong');title.textContent=form;const p=document.createElement('p');p.textContent=note;answer.append(title,p);}
function run(){const key=plain(word.value);if(!key){show('Enter a Greek word','Choose a passage example to begin.');return;}
if(key==='ερυσιχαιος'){if(context.value==='ethnic')show('Ἐρυσιχαῖος','Ethnic reading: circumflex on the penult. Join it to Θεσσαλὸς γένος (Thessalian by race).');else show('ἐρυσίχαιος','Pastoral compound: acute on the antepenult (proparoxytone). Join it to οὐδὲ ποιμήν (nor shepherd): cowherd or goatherd; shepherd is added in apposition.');}
else if(examples[key])show(examples[key],'Passage example: circumflex on the penult. The stated rule concerns -αιος words of more than three syllables, with qualifications for distinctions and compounds.');
else show('Outside this example set','No accent prediction is made. Try Ἀθηναῖος or Ἐρυσιχαῖος.');}
document.querySelector('#read').addEventListener('click',run);word.addEventListener('keydown',e=>{if(e.key==='Enter')run();});context.addEventListener('change',run);
for(const text of ['Ερυσιχαιος',...Object.values(examples)]){const btn=document.createElement('button');btn.textContent=text;btn.addEventListener('click',()=>{word.value=text;run();});document.querySelector('#examples').append(btn);}
document.querySelector('#reset').addEventListener('click',()=>{word.value='';context.value='ethnic';run();});run();

passages.gadget_css:
:root{
