const $ = (sel, el=document) => el.querySelector(sel);
const inp = $('#inp');
const accentedEl = $('#accented');
const analysisEl = $('#analysis');
const pill = $('#pill');
const syllEl = $('#syll');

const examples = [
  'χερσαιος','ὀρφναιος','ἑρσαιος','ἀρχαιος','Ἀρναιος','Τρικκαιος','Ἑρμαιος','Ὀρθαιος','Τυμφαιος','Μενδαιος','Βυσναιος',
  'ὑλαιος','χυδαιος','Λυαιος','λυγαιος','Τρυγαιος',
  'Νισαιος','Πισαιος','Κρισαιος','Θιαιος','Βιλλαιος','Ἰμαιος',
  'Ἰουδαιος','Χαλδαιος','σπουδαιος','ῥαγδαιος','σταδαιος','Ἀριδαιος',
  'βιαιος','δικαιος','Ἀθηναιος','ἀγοραιος','αἰπολος','ὑμεναιος'
];

// --- Greek helpers (very lightweight) ---
const COMBINING = /[\u0300-\u036f]/g;
function nfd(s){return s.normalize('NFD');}
function stripDiacritics(s){return nfd(s).replace(COMBINING,'').normalize('NFC');}
function stripBreathingsAccents(s){
  // remove combining marks; keep base letters
  return stripDiacritics(s);
}
function lowerGreek(s){return s.toLowerCase();}

const vowels = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ','ϊ','ϋ','ΐ','ΰ']);
function isVowel(ch){return vowels.has(ch);}

function endsWithAios(base){return base.endsWith('αιος');}
function endsWithDaios(base){return base.endsWith('δαιος');}

function firstVowelIndex(base){
  for(let i=0;i<base.length;i++) if(isVowel(base[i])) return i;
  return -1;
}

function guessTrisyllableAios(base){
  // crude: count vowel groups
  let groups=0, inV=false;
  for(const ch of base){
    const v=isVowel(ch);
    if(v && !inV){groups++; inV=true;}
    if(!v) inV=false;
  }
  return groups===3 && (endsWithAios(base) || endsWithDaios(base));
}

function accentAntepenultAcute(word){
  // place acute on the vowel of the antepenult syllable (very rough):
  // find vowel groups; accent the first vowel of group #1 (of 3)
  const base = stripBreathingsAccents(lowerGreek(word));
  const map = buildIndexMap(word);
  const groups = vowelGroups(base);
  if(groups.length<3) return word;
  const target = groups[0].start; // antepenult group
  return addAcuteAtOriginalIndex(word, map[target]);
}

function accentPenultCircumflex(word){
  // accent the vowel of the penult syllable (group #2 of 3) with circumflex
  const base = stripBreathingsAccents(lowerGreek(word));
  const map = buildIndexMap(word);
  const groups = vowelGroups(base);
  if(groups.length<2) return word;
  const target = groups.length>=3 ? groups[1].start : groups[groups.length-2].start;
  return addCircumflexAtOriginalIndex(word, map[target]);
}

function vowelGroups(base){
  const groups=[];
  let i=0;
  while(i<base.length){
    if(isVowel(base[i])){
      let j=i+1;
      while(j<base.length && isVowel(base[j])) j++;
      groups.push({start:i,end:j});
      i=j;
    } else i++;
  }
  return groups;
}

function buildIndexMap(original){
  // Map indices of stripped+lowered base letters to indices in original string.
  // We do this by walking original NFD and collecting base letters.
  const n = nfd(original);
  const baseIdx=[];
  for(let i=0;i<n.length;i++){
    const ch=n[i];
    if(!COMBINING.test(ch)) baseIdx.push(i);
  }
  // Now create a map from base-string index to original NFC index.
  // We'll approximate by using baseIdx positions in NFD, then convert back by slicing.
  // For our insertion we will operate in NFD anyway.
  const map=[];
  for(let k=0;k<baseIdx.length;k++) map[k]=baseIdx[k];
  // store also the NFD string on the map object
  map._nfd = n;
  return map;
}

function addMarkAtOriginalNFDIndex(original, nfdIndex, mark){
  const n = nfd(original);
  // insert mark after the base character at nfdIndex, but before any existing combining marks
  let i = nfdIndex+1;
  while(i<n.length && COMBINING.test(n[i])) i++;
  const out = n.slice(0,i) + mark + n.slice(i);
  return out.normalize('NFC');
}

function addAcuteAtOriginalIndex(original, nfdIndex){
  return addMarkAtOriginalNFDIndex(original, nfdIndex, '\u0301');
}
function addCircumflexAtOriginalIndex(original, nfdIndex){
  return addMarkAtOriginalNFDIndex(original, nfdIndex, '\u0342');
}

function analyze(word){
  const raw = word.trim();
  if(!raw) return {ok:false, msg:'Type a word first.'};

  const base = stripBreathingsAccents(lowerGreek(raw));

  // special-cased known exceptions from the passage
  const exceptionSet = new Set(['βιαιος','δικαιος']);
  const isException = exceptionSet.has(base);

  const isAios = endsWithAios(base);
  const isDaios = endsWithDaios(base);
  const looksTri = guessTrisyllableAios(base);

  // heuristics for “first syllable ends in consonant”:
  // if the word begins with consonant(s) before first vowel, treat as consonant-ending first syllable.
  const fv = firstVowelIndex(base);
  const startsWithConsonant = fv>0;

  // first syllable contains υ or ι (very rough: before second vowel group)
  const groups = vowelGroups(base);
  const firstSyllEnd = groups.length ? groups[0].end : Math.min(base.length, fv+1);
  const firstChunk = base.slice(0, firstSyllEnd);
  const hasU = firstChunk.includes('υ');
  const hasI = firstChunk.includes('ι');

  let rule = '';
  let accentType = '';

  if(isException){
    accentType = 'antepenult-acute';
    rule = 'Exception demo list: βίαιος / δίκαιος → antepenult acute.';
  } else if(isDaios){
    accentType = 'penult-circumflex';
    rule = 'Herodian: -δαιος forms tend to be circumflexed on the penult.';
  } else if(isAios && looksTri && (startsWithConsonant)){
    accentType = 'penult-circumflex';
    rule = 'Trisyllabic -αιος with consonant(s) before the first vowel → penult circumflex (rule-of-thumb).';
  } else if(isAios && looksTri && hasU){
    accentType = 'penult-circumflex';
    rule = 'Trisyllabic -αιος with υ in the first syllable → penult circumflex (rule-of-thumb).';
  } else if(isAios && looksTri && hasI){
    accentType = 'penult-circumflex';
    rule = 'Trisyllabic -αιος with ι in the first syllable (non-verbal, handwavy) → penult circumflex.';
  } else if(isAios && looksTri){
    accentType = 'penult-circumflex';
    rule = 'Default for many trisyllabic -αιος in this passage: penult circumflex.';
  } else if(base==='αἰπολος' || base==='αιπολος'){
    accentType = 'antepenult-acute';
    rule = 'From the passage: αἴπολος is antepenult-accented.';
  } else if(base==='ὑμεναιος' || base==='υμεναιος'){
    accentType = 'antepenult-acute';
    rule = 'From the passage: ὑμέναιος is antepenult-accented.';
  } else {
    accentType = 'unknown';
    rule = 'Not a clear match for the toy’s -αιος/-δαιος trisyllable patterns.';
  }

  let suggested = raw;
  if(accentType==='antepenult-acute') suggested = accentAntepenultAcute(raw);
  if(accentType==='penult-circumflex') suggested = accentPenultCircumflex(raw);

  return {
    ok:true,
    base,
    isAios,
    isDaios,
    looksTri,
    startsWithConsonant,
    hasU,
    hasI,
    accentType,
    rule,
    suggested
  };
}

function renderSyllableBoxes(word, accentType){
  syllEl.innerHTML='';
  const base = stripBreathingsAccents(lowerGreek(word));
  const groups = vowelGroups(base);
  if(groups.length===0){
    syllEl.textContent='(no vowels found)';
    return;
  }
  // crude syllable chunks: split at vowel-group boundaries
  const cuts=[0];
  for(const g of groups) cuts.push(g.end);
  cuts[cuts.length-1]=base.length;
  // build chunks by distributing consonants after each vowel group into same chunk
  const chunks=[];
  let start=0;
  for(let gi=0;gi<groups.length;gi++){
    const end = (gi<groups.length-1) ? groups[gi+1].start : base.length;
    chunks.push({text: base.slice(start,end), gi});
    start=end;
  }

  // determine target group index
  let targetGi = null;
  if(accentType==='antepenult-acute' && groups.length>=3) targetGi = 0;
  if(accentType==='penult-circumflex' && groups.length>=3) targetGi = 1;
  if(accentType==='penult-circumflex' && groups.length===2) targetGi = 0;

  chunks.forEach((c, idx)=>{
    const div=document.createElement('div');
    div.className='sbox';
    div.innerHTML = `${escapeHtml(c.text)}<small>${idx===0?'1st':'syll '+(idx+1)}</small>`;
    if(targetGi!==null && c.gi===targetGi) div.classList.add('good');
    div.addEventListener('click', ()=>{
      [...syllEl.children].forEach(x=>x.classList.remove('on'));
      div.classList.add('on');
    });
    syllEl.appendChild(div);
  });
}

function escapeHtml(s){
  return s.replace(/[&<>"']/g, c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
}

function update(){
  const r = analyze(inp.value);
  if(!r.ok){
    pill.textContent='—';
    accentedEl.textContent='(your accented form will appear here)';
    analysisEl.textContent=r.msg;
    syllEl.innerHTML='';
    return;
  }

  if(r.accentType==='penult-circumflex'){
    pill.textContent='Suggest: penult circumflex (…αῖος)';
    pill.style.borderColor='rgba(134,239,172,.45)';
    pill.style.color='var(--good)';
  } else if(r.accentType==='antepenult-acute'){
    pill.textContent='Suggest: antepenult acute (…άιος)';
    pill.style.borderColor='rgba(251,191,36,.45)';
    pill.style.color='var(--warn)';
  } else {
    pill.textContent='No confident guess';
    pill.style.borderColor='rgba(251,113,133,.45)';
    pill.style.color='var(--bad)';
  }

  accentedEl.textContent = r.suggested;

  const bits=[];
  bits.push(r.rule);
  bits.push(`Detected: ${r.looksTri?'“trisyllable-ish”':'not clearly trisyllabic'}; ending: ${r.isDaios?'-δαιος':(r.isAios?'-αιος':'other')}.`);
  if(r.isAios||r.isDaios){
    bits.push(`First chunk: ${r.startsWithConsonant?'starts with consonant(s)':'starts with vowel'}; contains υ=${r.hasU?'yes':'no'}, ι=${r.hasI?'yes':'no'}.`);
  }
  analysisEl.textContent = bits.join(' ');

  renderSyllableBoxes(inp.value, r.accentType);
}

$('#btnGuess').addEventListener('click', update);
$('#btnClear').addEventListener('click', ()=>{inp.value=''; update(); inp.focus();});
$('#btnRandom').addEventListener('click', ()=>{
  const w = examples[Math.floor(Math.random()*examples.length)];
  inp.value = w;
  update();
  inp.focus();
});

inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') update(); });

// initial
update();

