(() => {
  const $ = (sel, el=document) => el.querySelector(sel);
  const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

  const inp = $('#inp');
  const outWord = $('#outWord');
  const outMeta = $('#outMeta');
  const chkSyl = $('#chkSyl');
  const cardsEl = $('#cards');

  let override = 'auto';

  // --- Greek helpers (very lightweight) ---
  const combining = /[\u0300-\u036f]/g;
  const greekTonos = '\u0301'; // acute
  const greekPerispomeni = '\u0342'; // circumflex

  function nfd(s){ return s.normalize('NFD'); }
  function nfc(s){ return s.normalize('NFC'); }
  function stripDiacritics(s){ return nfc(nfd(s).replace(combining,'')); }

  function isGreekLetter(ch){
    const cp = ch.codePointAt(0);
    return (cp >= 0x0370 && cp <= 0x03FF) || (cp >= 0x1F00 && cp <= 0x1FFF);
  }

  function lowerGreek(s){
    // Keep it simple; JS lowercasing handles Greek reasonably.
    return s.toLowerCase();
  }

  function endsWithAny(s, arr){
    return arr.find(x => s.endsWith(x)) || null;
  }

  // Syllabify very roughly: split before vowel groups.
  // We only need last 3 syllables for accent placement.
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ','ϊ','ΐ','ϋ','ΰ','ᾳ','ῃ','ῳ']);
  function isVowel(ch){
    const base = stripDiacritics(ch);
    return vowels.has(base);
  }

  function roughSyllables(word){
    const w = stripDiacritics(lowerGreek(word));
    // Keep only Greek letters (and apostrophe-like marks)
    const letters = Array.from(w).filter(ch => isGreekLetter(ch));
    if (!letters.length) return [];

    // Build syllables by scanning for vowel nuclei.
    const syl = [];
    let cur = '';
    let seenVowel = false;

    for (let i=0;i<letters.length;i++){
      const ch = letters[i];
      cur += ch;
      if (isVowel(ch)){
        seenVowel = true;
        // If next char begins a new vowel nucleus, we may split later; but we also want to attach following consonants until next vowel.
        // We'll decide split when we encounter next vowel after consonants.
        // So do nothing here.
      } else {
        // consonant
      }

      const next = letters[i+1];
      if (!next){
        syl.push(cur);
      } else {
        // split when current syllable has a vowel and next is a vowel (hiatus/diphthong not handled),
        // or when current has vowel and next is consonant but after that comes vowel (we keep consonant with next syllable in Greek, but this is a toy).
        if (seenVowel && isVowel(next)){
          syl.push(cur);
          cur = '';
          seenVowel = false;
        } else if (seenVowel && !isVowel(next)){
          // lookahead: if next consonant is followed by vowel, split before that consonant (i.e., keep consonant with next syllable)
          const after = letters[i+2];
          if (after && isVowel(after)){
            // move next consonant to next syllable: split now (before next consonant)
            syl.push(cur);
            cur = '';
            seenVowel = false;
          }
        }
      }
    }

    return syl.filter(x => x.length);
  }

  function addAccentToSyllable(word, syllables, targetIndexFromEnd, accentType){
    // accentType: 'acute' or 'circ'
    // We will place combining mark on the first vowel of the target syllable.
    const clean = stripDiacritics(word);
    const syl = roughSyllables(clean);
    if (!syl.length) return clean;

    const idx = syl.length - targetIndexFromEnd;
    if (idx < 0 || idx >= syl.length) return clean;

    // Reconstruct with accent by mapping syllables back to string positions.
    // Since our syllabifier is approximate, we just rebuild from syllables.
    const mark = accentType === 'circ' ? greekPerispomeni : greekTonos;

    const accentedSyl = syl.map((s, i) => {
      if (i !== idx) return s;
      const chars = Array.from(s);
      for (let j=0;j<chars.length;j++){
        if (isVowel(chars[j])){
          // add combining mark after vowel
          chars[j] = nfc(nfd(chars[j]) + mark);
          break;
        }
      }
      return chars.join('');
    });

    return nfc(accentedSyl.join(''));
  }

  function showSyllables(word){
    const syl = roughSyllables(word);
    if (!syl.length) return '';
    return syl.join('·');
  }

  // --- Herodian-ish heuristic ---
  function classify(word){
    const w = stripDiacritics(lowerGreek(word)).replace(/[^\p{Script=Greek}]/gu,'');

    const suffix = endsWithAny(w, ['λαιος','μαιος','χαιος','αιος']);
    if (!suffix) return { ok:false, reason:'Not an -αιος word (toy focuses on -αιος family).', w };

    // detect pre-ai consonant pattern for generic -αιος: double consonants or sigma before αι
    // We'll approximate: look for ...σσαῖος etc? Herodian: one of the "double consonants" (ζ, ξ, ψ) or σ before αι.
    const preAi = w.slice(0, -2); // remove 'ος'? no; we want char before 'αι' in ending -αιος
    // Find the last occurrence of 'αιος' and inspect char before 'αι'
    const pos = w.lastIndexOf('αιος');
    let before = pos > 0 ? w[pos-1] : '';

    const doubleCons = new Set(['ζ','ξ','ψ']);
    const hasDoubleOrSigma = doubleCons.has(before) || before === 'σ';

    // Some known exceptions from passage (toy list)
    const exceptions = {
      'δειλαιος': {pattern:'proparox', note:'Marked exception: δείλαιος is antepenult-accented.'},
      'φυλαιος': {pattern:'proparox', note:'Marked exception: φύλαιος is antepenult-accented.'},
      'αχαιος': {pattern:'oxytone', note:'Marked exception: Ἀχαιός is oxytone (final acute).'},
      'ερυσίχαιος': {pattern:'proparox', note:'Marked exception: ἐρυσίχαιος is antepenult-accented.'},
      'τιμαιος': {pattern:'marked', note:'Τίμαιος is noted as exceptional (toy treats as antepenult by default).'}
    };

    const key = w;
    if (exceptions[key]){
      const ex = exceptions[key];
      return { ok:true, suffix, hasDoubleOrSigma, exception:true, pattern: ex.pattern, note: ex.note, w };
    }

    // Default tendencies
    let pattern = 'perisp';
    let note = '';

    if (suffix === 'λαιος'){
      pattern = 'perisp';
      note = 'Default for -λαιος: penult circumflex (προπερισπᾶται).';
    } else if (suffix === 'μαιος'){
      pattern = 'perisp';
      note = 'Default for -μαιος: penult circumflex, unless distinction/compound.';
    } else if (suffix === 'χαιος'){
      pattern = 'perisp';
      note = 'Default for -χαιος: penult circumflex, with some marked exceptions.';
    } else {
      // plain -αιος
      if (hasDoubleOrSigma){
        pattern = 'perisp';
        note = 'Rule: -αιος with ζ/ξ/ψ or σ right before αι → penult circumflex.';
      } else {
        pattern = 'perisp';
        note = 'Generic -αιος: toy defaults to penult circumflex (common in Herodian’s list).';
      }
    }

    return { ok:true, suffix, hasDoubleOrSigma, exception:false, pattern, note, w };
  }

  function applyPattern(word, pattern){
    const clean = stripDiacritics(word);
    if (!clean) return '';

    if (pattern === 'oxytone'){
      return addAccentToSyllable(clean, null, 1, 'acute');
    }
    if (pattern === 'proparox'){
      return addAccentToSyllable(clean, null, 3, 'acute');
    }
    if (pattern === 'perisp'){
      return addAccentToSyllable(clean, null, 2, 'circ');
    }
    if (pattern === 'marked'){
      // For Τίμαιος: show antepenult acute as a playful default.
      return addAccentToSyllable(clean, null, 3, 'acute');
    }
    // auto fallback
    return addAccentToSyllable(clean, null, 2, 'circ');
  }

  function patternLabel(p){
    if (p==='perisp') return 'penult circumflex (προπερισπώμενον)';
    if (p==='proparox') return 'antepenult acute (προπαροξύτονον)';
    if (p==='oxytone') return 'final acute (ὀξύτονον)';
    if (p==='marked') return 'marked/exceptional (σεσημείωται)';
    return 'auto';
  }

  function update(){
    const raw = inp.value.trim();
    const info = classify(raw);

    if (!raw){
      outWord.textContent = '—';
      outMeta.textContent = 'Type a word.';
      return;
    }

    if (!info.ok){
      outWord.textContent = stripDiacritics(raw);
      outMeta.textContent = info.reason;
      return;
    }

    const chosen = (override==='auto') ? info.pattern : override;
    const accented = applyPattern(raw, chosen);

    outWord.textContent = accented;

    const syl = chkSyl.checked ? showSyllables(accented) : '';
    const bits = [];
    bits.push(`Detected ending: -${info.suffix}`);
    if (info.suffix==='αιος'){
      bits.push(`Before αι: ${info.hasDoubleOrSigma ? 'ζ/ξ/ψ/σ (→ circumflex)' : 'other'}`);
    }
    bits.push(`Pattern: ${patternLabel(chosen)}${override!=='auto' ? ' (override)' : ''}`);
    if (info.exception) bits.push('Exception noted in passage.');
    if (info.note) bits.push(info.note);
    if (syl) bits.push(`Syllables (rough): ${syl}`);

    outMeta.textContent = bits.join(' • ');
  }

  // --- UI wiring ---
  $('#btnGuess').addEventListener('click', update);
  inp.addEventListener('input', update);
  chkSyl.addEventListener('change', update);

  $$('.pill').forEach(btn => {
    btn.addEventListener('click', () => {
      $$('.pill').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      override = btn.dataset.override;
      update();
    });
  });

  const examples = [
    {w:'ὑλαιος', d:'Herodian default -λαιος → ὑλαῖος', tag:'rule'},
    {w:'βουλαιος', d:'-λαιος → βουλαῖος', tag:'rule'},
    {w:'ζηλαιος', d:'-λαιος → ζηλαῖος', tag:'rule'},
    {w:'δειλαιος', d:'exception: δείλαιος (antepenult)', tag:'exception'},
    {w:'φυλαιος', d:'exception: φύλαιος (antepenult)', tag:'exception'},
    {w:'πτολεμαιος', d:'-μαιος → Πτολεμαῖος', tag:'rule'},
    {w:'ρωμαιος', d:'-μαιος → Ῥωμαῖος', tag:'rule'},
    {w:'ερμαιος', d:'-μαιος → Ἑρμαῖος (but Ἕρμαιος as proper name by distinction)', tag:'distinction'},
    {w:'αρχαιος', d:'-χαιος → ἀρχαῖος', tag:'rule'},
    {w:'αχαιος', d:'exception: Ἀχαιός (final acute)', tag:'exception'},
    {w:'γaζαιος'.replace('a','α'), d:'ζ before αι → Γαζαῖος', tag:'rule'},
    {w:'νισαιος', d:'σ before αι → Νισαῖος', tag:'rule'},
    {w:'χερσαιος', d:'σ before αι → χερσαῖος', tag:'rule'},
    {w:'μουσαιος', d:'σ before αι → Μουσαῖος', tag:'rule'},
    {w:'ανταιος', d:'from adverb ἄντην → ἀνταῖος (toy: circumflex)', tag:'rule'}
  ];

  function badge(tag){
    if (tag==='rule') return '<span class="badge good">rule</span>';
    if (tag==='exception') return '<span class="badge bad">exception</span>';
    if (tag==='distinction') return '<span class="badge warn">distinction</span>';
    return '';
  }

  function renderCards(){
    cardsEl.innerHTML = examples.map(ex => {
      const shown = applyPattern(ex.w, classify(ex.w).pattern);
      return `<div class="card" data-w="${ex.w}">
        <div class="w">${shown}${badge(ex.tag)}</div>
        <div class="d">${ex.d}</div>
      </div>`;
    }).join('');

    $$('.card', cardsEl).forEach(c => {
      c.addEventListener('click', () => {
        inp.value = c.dataset.w;
        update();
        inp.focus();
      });
    });
  }

  $('#btnRandom').addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inp.value = ex.w;
    update();
    inp.focus();
  });

  renderCards();
  update();
})();

