:root{
  --bg:#0f1220;
  --card:#171a2b;
  --ink:#eef0ff;
  --muted:#b9bce0;
  --line:#2a2f4a;
  --accent:#7dd3fc;
  --accent2:#a7f3d0;
  --warn:#fbbf24;
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
}
*{box-sizing:border-box}
body{margin:0; font-family:var(--sans); background:radial-gradient(1200px 700px at 20% 0%, #1b2150 0%, var(--bg) 55%); color:var(--ink)}
.wrap{max-width:980px; margin:0 auto; padding:22px 16px 40px}
.hdr{display:flex; align-items:flex-end; justify-content:space-between; gap:16px; margin-bottom:14px}
h1{font-size:22px; margin:0 0 6px 0; letter-spacing:.2px}
.sub{margin:0; color:var(--muted); line-height:1.35}
.card{background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02)); border:1px solid var(--line); border-radius:14px; padding:14px 14px 12px; margin-top:12px; box-shadow:0 10px 30px rgba(0,0,0,.25)}
.card h2{margin:0 0 10px 0; font-size:16px; color:#f3f4ff}
.grid{display:grid; grid-template-columns: 1.4fr .9fr 1.1fr; gap:10px; align-items:end}
@media (max-width:860px){.grid{grid-template-columns:1fr}}
.lbl span{display:block; font-size:12px; color:var(--muted); margin:0 0 6px 2px}
.txt,.sel{width:100%; padding:10px 10px; border-radius:10px; border:1px solid var(--line); background:#0f1326; color:var(--ink); outline:none}
.txt:focus,.sel:focus{border-color:rgba(125,211,252,.7); box-shadow:0 0 0 3px rgba(125,211,252,.15)}
.btnRow{display:flex; gap:10px; justify-content:flex-start}
.btn{padding:10px 12px; border-radius:10px; border:1px solid rgba(125,211,252,.35); background:rgba(125,211,252,.12); color:var(--ink); cursor:pointer; font-weight:600}
.btn:hover{background:rgba(125,211,252,.18)}
.btn.ghost{border-color:var(--line); background:transparent; color:var(--muted)}
.btn.ghost:hover{background:rgba(255,255,255,.04); color:var(--ink)}
.out{margin-top:12px; border-top:1px dashed rgba(185,188,224,.25); padding-top:12px}
.outRow{display:grid; grid-template-columns:110px 1fr; gap:10px; align-items:baseline; margin:6px 0}
.tag{font-size:12px; color:var(--muted)}
.big{font-size:26px; letter-spacing:.3px}
.mono{font-family:var(--mono); color:#e7e9ff}
.details summary{cursor:pointer; color:var(--accent); margin-top:8px}
.small{font-size:13px; color:var(--muted); line-height:1.45}
.note{color:#d6d8ff}
.chips{display:flex; flex-wrap:wrap; gap:8px}
.chip{border:1px solid var(--line); background:#0f1326; color:var(--ink); padding:8px 10px; border-radius:999px; cursor:pointer; font-size:13px}
.chip:hover{border-color:rgba(167,243,208,.55); box-shadow:0 0 0 3px rgba(167,243,208,.12)}
.ftr{margin-top:14px; color:var(--muted)}
.kbd{font-family:var(--mono); padding:2px 6px; border:1px solid var(--line); border-bottom-color:#000; border-radius:6px; background:#0f1326}
.hl{color:var(--accent2)}

