(() => {
  const $ = (id) => document.getElementById(id);

  const inWord = $('inWord');
  const mode = $('mode');
  const hint = $('hint');
  const outWord = $('outWord');
  const outRule = $('outRule');
  const btnAccent = $('btnAccent');
  const btnClear = $('btnClear');
  const chips = $('chips');

  // --- Utilities: Greek normalization & accent handling ---
  const COMBINING = {
    ACUTE: '\u0301',
    GRAVE: '\u0300',
    CIRC: '\u0342',
    DIA: '\u0308',
    SMOOTH: '\u0313',
    ROUGH: '\u0314',
    IOTA_SUB: '\u0345'
  };

  function nfd(s){ return (s || '').normalize('NFD'); }
  function nfc(s){ return (s || '').normalize('NFC'); }

  function stripAccentsKeepDiaeresis(s){
    // Remove tonos/oxia, varia, perispomeni, breathings; keep diaeresis and iota subscript.
    const d = nfd(s);
    const keep = new Set([COMBINING.DIA, COMBINING.IOTA_SUB]);
    let out = '';
    for (const ch of d) {
      const code = ch.codePointAt(0);
      // Combining diacritics range
      if (code >= 0x300 && code <= 0x36F) {
        if (keep.has(ch)) out += ch;
      } else {
        out += ch;
      }
    }
    return nfc(out);
  }

  function isGreekLetter(ch){
    const cp = ch.codePointAt(0);
    return (cp >= 0x0370 && cp <= 0x03FF) || (cp >= 0x1F00 && cp <= 0x1FFF);
  }

  function baseGreekLower(s){
    // Lowercase, but keep Greek; strip punctuation.
    return stripAccentsKeepDiaeresis(s)
      .replace(/[··.,;:!?()\[\]{}"'“”‘’—–\-]/g,' ')
      .replace(/\s+/g,' ')
      .trim()
      .toLowerCase();
  }

  function tokenizeGreek(s){
    const t = baseGreekLower(s);
    if (!t) return [];
    return t.split(' ').filter(Boolean);
  }

  // --- Syllable heuristic ---
  const VOWELS = new Set(['α','ε','η','ι','ο','υ','ω']);
  const DIPHTHONGS = new Set([
    'αι','ει','οι','υι','αυ','ευ','ηυ','ου','ωυ','ηι','ωι','ᾳ','ῃ','ῳ'
  ]);

  function stripToLettersNFD(s){
    // Keep Greek letters and combining diaeresis/iota subscript.
    const d = nfd(s);
    let out = '';
    for (const ch of d) {
      const cp = ch.codePointAt(0);
      if (isGreekLetter(ch)) out += ch;
      else if (ch === COMBINING.DIA || ch === COMBINING.IOTA_SUB) out += ch;
      else if (cp >= 0x300 && cp <= 0x36F) {
        // ignore other combining
      }
    }
    return out;
  }

  function syllabify(word){
    // Returns array of syllable objects with start/end indices in NFD string.
    // Very rough: each vowel nucleus (diphthong unless diaeresis breaks it) starts a syllable.
    const w = stripToLettersNFD(word);
    const letters = Array.from(w);

    function letterBase(i){
      // Return base letter (without combining marks) at position i.
      const ch = letters[i];
      if (!ch) return '';
      // combining marks are separate chars in NFD; base letters are Greek letters.
      return ch;
    }

    function hasDiaeresisAt(i){
      // Diaeresis is a combining mark following a vowel base.
      return letters[i+1] === COMBINING.DIA;
    }

    // Build a simplified stream of base letters with mapping to indices.
    const bases = [];
    for (let i=0;i<letters.length;i++){
      const ch = letters[i];
      if (isGreekLetter(ch)) bases.push({ch, i});
    }

    const nuclei = [];
    for (let b=0;b<bases.length;b++){
      const ch = bases[b].ch;
      if (!VOWELS.has(ch)) continue;

      // Try diphthong with next base vowel if no diaeresis on first vowel.
      const next = bases[b+1];
      if (next && VOWELS.has(next.ch) && !hasDiaeresisAt(bases[b].i)){
        const pair = ch + next.ch;
        if (DIPHTHONGS.has(pair)){
          nuclei.push({start: bases[b].i, end: next.i + 1});
          b++; // consume next
          continue;
        }
      }
      nuclei.push({start: bases[b].i, end: bases[b].i + 1});
    }

    if (nuclei.length === 0) return [];

    // Syllable boundaries: start at nucleus start; end at next nucleus start.
    const sylls = [];
    for (let k=0;k<nuclei.length;k++){
      const start = nuclei[k].start;
      const end = (k < nuclei.length-1) ? nuclei[k+1].start : letters.length;
      sylls.push({start, end, nucleus: nuclei[k]});
    }
    return { nfd: w, sylls };
  }

  function addAccent(word, whichFromEnd, accentType){
    // whichFromEnd: 1=ultima, 2=penult, 3=antepenult
    // accentType: 'acute'|'circ'
    const info = syllabify(word);
    if (!info.sylls.length) return word;
    const idx = info.sylls.length - whichFromEnd;
    const target = info.sylls[Math.max(0, idx)];

    // Place accent on first vowel of nucleus.
    const letters = Array.from(info.nfd);
    let insertAt = target.nucleus.start + 1; // after first base vowel

    // If nucleus is diphthong, accent still goes after first vowel base in NFD.
    const mark = accentType === 'circ' ? COMBINING.CIRC : COMBINING.ACUTE;

    // Avoid double accent if already present (shouldn't, we strip first).
    letters.splice(insertAt, 0, mark);
    return nfc(letters.join(''));
  }

  // --- Rule guessing inspired by the passage ---
  const SPECIAL_PREPENULT_CIRC = new Set(['ηλειος','ηθειος','ητειος']);

  function detectSuffix(w){
    const t = baseGreekLower(w);
    if (t.endsWith('ειος')) return 'eios';
    if (t.endsWith('αιος')) return 'aios';
    return null;
  }

  function hasEtaInThirdSyllableFromEnd(word){
    // “pure trisyllables in -ειος having η in the third syllable”
    // Toy interpretation: exactly 3 syllables total, and the antepenult nucleus contains η.
    const info = syllabify(word);
    if (!info.sylls.length) return false;
    if (info.sylls.length !== 3) return false;
    const ante = info.sylls[0];
    const nuc = info.nfd.slice(ante.nucleus.start, ante.nucleus.end);
    return nuc.includes('η');
  }

  function accentGuess(rawWord, forcedMode, derivHint){
    const cleaned = stripAccentsKeepDiaeresis(rawWord).trim();
    const low = baseGreekLower(cleaned);
    if (!low) return {word:'', rule:'Type a Greek word.'};

    const suf = forcedMode === 'auto' ? detectSuffix(low) : forcedMode;

    // Proper-name hint: acute on ultima.
    if (derivHint === 'properName'){
      return {
        word: addAccent(cleaned, 1, 'acute'),
        rule: 'Hint: proper name → acute on the last syllable (toy rule; cf. Κητειός, Πηνειός).'
      };
    }

    // Special vowel-initial cases listed by Herodian.
    if (SPECIAL_PREPENULT_CIRC.has(low)){
      return {
        word: addAccent(cleaned, 2, 'circ'),
        rule: 'Special case: Ἠλεῖος / ἠθεῖος / Ἠτεῖος → prepenult circumflex (toy list from the passage).'
      };
    }

    if (suf === 'eios'){
      if (hasEtaInThirdSyllableFromEnd(cleaned)){
        return {
          word: addAccent(cleaned, 3, 'acute'),
          rule: "-ειος, pure trisyllable with η in the 3rd syllable → antepenult acute (θήρειος-type)."
        };
      }
      // Default for -ειος: penult acute.
      return {
        word: addAccent(cleaned, 2, 'acute'),
        rule: "Default guess for -ειος → penult acute (toy default)."
      };
    }

    if (suf === 'aios'){
      if (derivHint === 'fromVerb'){
        return {
          word: addAccent(cleaned, 2, 'circ'),
          rule: 'Hint: “from a verb” → prefer circumflex (βέβαιος-type; simplified).'
        };
      }
      // Default for -αιος: penult acute.
      return {
        word: addAccent(cleaned, 2, 'acute'),
        rule: 'Default guess for -αιος → penult acute (toy default).'
      };
    }

    // No recognized suffix: just accent penult acute.
    return {
      word: addAccent(cleaned, 2, 'acute'),
      rule: 'No -αιος/-ειος detected → fallback: penult acute.'
    };
  }

  function run(){
    const forced = mode.value;
    const h = hint.value;
    const res = accentGuess(inWord.value, forced, h);
    outWord.textContent = res.word ? res.word : '—';
    outRule.textContent = res.rule;
  }

  // --- Examples ---
  const EXAMPLES = [
    {w:'θηρειος', m:'eios', h:'none', label:'θηρειος → θήρειος'},
    {w:'μηλειος', m:'eios', h:'none', label:'μηλειος → μήλειος'},
    {w:'χηνειος', m:'eios', h:'none', label:'χηνειος → χήνειος'},
    {w:'κρητειος', m:'eios', h:'none', label:'κρητειος → Κρήτειος'},
    {w:'Ηλειος', m:'eios', h:'none', label:'Ηλειος → Ἠλεῖος (special)'},
    {w:'ηθειος', m:'eios', h:'none', label:'ηθειος → ἠθεῖος (special)'},
    {w:'βεβαιος', m:'aios', h:'fromVerb', label:'βεβαιος + from-verb → βεβαῖος'},
    {w:'Κητειος', m:'eios', h:'properName', label:'Κητειος + proper name → Κητειός'},
    {w:'Πηνειος', m:'eios', h:'properName', label:'Πηνειος + proper name → Πηνειός'}
  ];

  function renderChips(){
    chips.innerHTML = '';
    for (const ex of EXAMPLES){
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'chip';
      b.textContent = ex.label;
      b.addEventListener('click', () => {
        inWord.value = ex.w;
        mode.value = ex.m === 'eios' ? 'eios' : (ex.m === 'aios' ? 'aios' : 'auto');
        hint.value = ex.h;
        run();
        inWord.focus();
        inWord.setSelectionRange(inWord.value.length, inWord.value.length);
      });
      chips.appendChild(b);
    }
  }

  btnAccent.addEventListener('click', run);
  btnClear.addEventListener('click', () => {
    inWord.value = '';
    outWord.textContent = '—';
    outRule.textContent = '—';
    inWord.focus();
  });
  inWord.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') run();
  });

  renderChips();
})();

