.panel{background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02)); border:1px solid var(--border); border-radius:14px; padding:14px; box-shadow:var(--shadow); margin:12px 0}
.panel.out{padding:14px 14px 10px}
.row{display:flex; gap:10px; align-items:center; flex-wrap:wrap}
.row.small{margin-top:10px}
.lbl{min-width:110px; color:var(--muted); font-weight:600}
.inp{flex:1; min-width:260px; padding:10px 12px; border-radius:12px; border:1px solid var(--border); background:rgba(0,0,0,.25); color:var(--text); outline:none; font-size:16px}
.inp:focus{border-color:rgba(124,240,197,.55); box-shadow:0 0 0 3px rgba(124,240,197,.12)}
.btn{padding:10px 12px; border-radius:12px; border:1px solid rgba(255,255,255,.14); background:rgba(124,240,197,.14); color:var(--text); cursor:pointer; font-weight:700}
.btn:hover{background:rgba(124,240,197,.20)}
.btn.ghost{background:rgba(255,255,255,.06)}
.btn.ghost:hover{background:rgba(255,255,255,.10)}
.hint{color:var(--muted); line-height:1.35}
.chips{display:flex; flex-wrap:wrap; gap:8px}
.chip{border:1px solid var(--border); background:rgba(138,167,255,.10); color:var(--text); padding:7px 10px; border-radius:999px; cursor:pointer; font-family:var(--mono); font-size:13px}
.chip:hover{background:rgba(138,167,255,.16)}
h2{margin:0 0 10px; font-size:16px; color:var(--muted); letter-spacing:.2px}
.grid{display:grid; grid-template-columns:repeat(2, minmax(0,1fr)); gap:10px}
.card{border:1px solid var(--border); border-radius:12px; padding:10px 12px; background:rgba(0,0,0,.18)}
.card.big{grid-column:1 / -1; background:rgba(124,240,197,.08)}
.k{color:var(--faint); font-size:12px; text-transform:uppercase; letter-spacing:.12em; margin-bottom:6px}
.v{font-size:16px}
.v.big{font-size:22px; font-weight:800; letter-spacing:.2px}
.note{margin-top:8px; color:var(--muted); font-size:13px; line-height:1.35}
.note strong{color:var(--text)}
details.panel.mini{padding:10px 12px}
details summary{cursor:pointer; color:var(--muted); font-weight:700}
.miniBody{margin-top:8px; color:var(--muted); line-height:1.45}
.miniBody ol{margin:8px 0 0 18px; padding:0}
.ftr{margin-top:10px; color:var(--muted)}
@media (max-width:720px){
  .grid{grid-template-columns:1fr}
  .lbl{min-width:auto}
}

