const $ = (s) => document.querySelector(s);
const $$ = (s) => Array.from(document.querySelectorAll(s));

// --- Greek helpers (toy-level) ---
const combining = /[\u0300-\u036f]/g;
function nfd(str){ return (str||"").normalize('NFD'); }
function nfc(str){ return (str||"").normalize('NFC'); }
function stripDiacritics(str){
  return nfc(nfd(str).replace(combining, ''));
}

// Rough vowel/diphthong detection for syllabification
const V = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ','ϊ','ΐ','ϋ','ΰ','ᾳ','ῃ','ῳ']);
const baseVowels = new Set(['α','ε','η','ι','ο','υ','ω']);
const diph = new Set(['αι','ει','οι','υι','αυ','ευ','ηυ','ου']);

function lowerGreek(s){ return (s||"").toLowerCase(); }

function tokenizeVowelUnits(word){
  // returns array of vowel units (single vowel or diphthong) in order
  const w = lowerGreek(stripDiacritics(word));
  const units = [];
  for(let i=0;i<w.length;i++){
    const a = w[i];
    const b = w[i+1] || '';
    const pair = a+b;
    if(diph.has(pair)){
      units.push(pair);
      i++;
      continue;
    }
    if(baseVowels.has(a)) units.push(a);
  }
  return units;
}

function roughSyllableCount(word){
  return tokenizeVowelUnits(word).length || 0;
}

function addAcuteToVowelUnit(word, unitIndexFromStart){
  // Add an acute to the vowel unit at index (0-based) in the stripped word.
  // We ignore existing accents and re-accent.
  const stripped = stripDiacritics(word);
  const w = lowerGreek(stripped);

  // map positions of vowel units to string indices
  const positions = [];
  for(let i=0;i<w.length;i++){
    const a = w[i];
    const b = w[i+1] || '';
    const pair = a+b;
    if(diph.has(pair)){
      positions.push({i, len:2, unit:pair});
      i++;
      continue;
    }
    if(baseVowels.has(a)) positions.push({i, len:1, unit:a});
  }
  if(unitIndexFromStart < 0 || unitIndexFromStart >= positions.length) return stripped;

  const pos = positions[unitIndexFromStart];
  // Put acute on first vowel of the unit (good enough for a toy)
  const acuteMap = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ'
  };
  const chars = Array.from(stripped);
  const ch = lowerGreek(chars[pos.i]);
  if(acuteMap[ch]){
    // preserve original case roughly
    const isUpper = chars[pos.i] === chars[pos.i].toUpperCase() && chars[pos.i] !== chars[pos.i].toLowerCase();
    let rep = acuteMap[ch];
    if(isUpper) rep = rep.toUpperCase();
    chars[pos.i] = rep;
  }
  return chars.join('');
}

function proparoxytone(word){
  // Accent antepenult with acute (toy). If fewer than 3 syllables, accent first.
  const n = roughSyllableCount(word);
  if(n === 0) return word;
  const target = Math.max(0, n-3);
  return addAcuteToVowelUnit(word, target);
}

function endsWithOs(base){
  const s = lowerGreek(stripDiacritics(base)).trim();
  return s.endsWith('ος');
}

function penultIsAlpha(base){
  // check vowel unit of penult syllable in base (rough)
  const units = tokenizeVowelUnits(base);
  if(units.length < 2) return false;
  const pen = units[units.length-2];
  return pen.startsWith('α');
}

function hasSplitCluster(base){
  // Very rough: look for two consonants between two vowels in stripped form.
  const s = lowerGreek(stripDiacritics(base));
  const vowels = baseVowels;
  const isV = (c)=>vowels.has(c);
  const isC = (c)=>c && /[α-ω]/.test(c) && !isV(c);
  for(let i=1;i<s.length-2;i++){
    if(isV(s[i-1]) && isC(s[i]) && isC(s[i+1]) && isV(s[i+2])) return true;
  }
  return false;
}

function derive(base, mode){
  const b = (base||"").trim();
  if(!b) return {form:"", notes:["Type a base word."]};

  const notes = [];
  const stripped = stripDiacritics(b);
  const low = lowerGreek(stripped);

  if(mode === 'priv'){
    // toy: add privative alpha; if base begins with vowel, use ἀ- (we won't add breathing)
    const startsV = baseVowels.has(low[0]);
    const pref = startsV ? 'ἀ' : 'ἀ';
    const form = pref + stripped;
    notes.push("Toy privative formation: ἀ- + base (compare χρεία → ἄχρειος in the passage). Not a real accent engine.");
    return {form, notes};
  }

  // If base ends in -ος, remove it; else keep base as stem.
  let stem = stripped;
  if(endsWithOs(stripped)){
    stem = stripped.slice(0, stripped.length-2);
    notes.push("Detected neuter-like ending -ος; using stem without -ος.");
  } else {
    notes.push("Base not in -ος (or not detected); using whole base as stem.");
  }

  if(mode === 'ios'){
    const form = stem + 'ιος';
    notes.push("Using -ιος (the passage notes that bases with penult α often ‘like’ -ιος spellings: πελάγιος, ἅγιος…).");
    return {form, notes};
  }

  // mode === 'eios'
  let form = stem + 'ειος';
  notes.push("Using -ειος (Herodian’s generalization for many derivatives from neuters in -ος)." );

  // Add caveat hints
  if(penultIsAlpha(stripped)){
    notes.push("Caveat: base seems to have α in the penult syllable → often -ιος is preferred (toy hint). Try switching to -ιος.");
  }
  if(hasSplitCluster(stripped)){
    notes.push("Caveat: detected a possible two-consonant split between syllables (toy). Herodian mentions special cases (e.g. Ἀργεῖος, ἑρκεῖος)." );
  }

  return {form, notes};
}

function getAccentChoice(){
  const r = document.querySelector('input[name="accent"]:checked');
  return r ? r.value : 'proparox';
}

function render(){
  const base = $('#base').value;
  const mode = $('#mode').value;
  const acc = getAccentChoice();

  const {form, notes} = derive(base, mode);
  let out = form;
  if(acc === 'proparox' && form){
    out = proparoxytone(form);
  }

  $('#derived').textContent = out || '—';
  $('#syll').textContent = form ? `${roughSyllableCount(out)} (vowel-units: ${tokenizeVowelUnits(out).join('·') || '—'})` : '—';
  $('#notes').innerHTML = notes.length ? `<ul>${notes.map(n=>`<li>${escapeHtml(n)}</li>`).join('')}</ul>` : '—';
}

function escapeHtml(s){
  return (s||"").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

$('#go').addEventListener('click', render);
$('#clear').addEventListener('click', ()=>{
  $('#base').value='';
  $('#derived').textContent='—';
  $('#syll').textContent='—';
  $('#notes').textContent='—';
});
$('#mode').addEventListener('change', render);
$$('input[name="accent"]').forEach(r=>r.addEventListener('change', render));
$('#base').addEventListener('input', ()=>{
  // live update but not too jumpy
  render();
});
$$('button[data-fill]').forEach(b=>b.addEventListener('click', ()=>{
  $('#base').value = b.getAttribute('data-fill');
  render();
}));

// --- Quiz ---
const quizBases = [
  {base:'τέλος', expected:'yes', note:'τέλος → τέλειος (proparoxytone per passage)'} ,
  {base:'ὄρος', expected:'yes', note:'ὄρος → ὄρειος'} ,
  {base:'ὄνειδος', expected:'yes', note:'ὄνειδος → ὀνείδειος'} ,
  {base:'ἕλος', expected:'yes', note:'ἕλος → ἕλειος (mentioned)'} ,
  {base:'πέλαγος', expected:'no', note:'penult α often goes to -ιος: πελάγιος (toy)'} ,
  {base:'ἅγος', expected:'no', note:'compare ἅγιος (toy)'} ,
  {base:'Ἀλέξανδρος', expected:'yes', note:'Ἀλεξάνδρειος (listed; proparoxytone)'} ,
  {base:'Ὅμηρος', expected:'yes', note:'Ὁμήρειος (listed; proparoxytone)'}
];
let current = null;

function deal(){
  current = quizBases[Math.floor(Math.random()*quizBases.length)];
  // propose a form using -ειος unless penult alpha suggests -ιος
  const base = current.base;
  const suggestMode = (penultIsAlpha(base) ? 'ios' : 'eios');
  const {form} = derive(base, suggestMode);
  const proposed = proparoxytone(form);
  $('#quizWord').textContent = proposed;
  $('#quizMeta').textContent = `Base: ${base} · Proposed derivation: ${suggestMode==='eios' ? '-ειος' : '-ιος'} · Your call: should it be proparoxytone by the passage’s general tendency?`;
  $('#quizResult').textContent = '';
  $('#quizResult').className = 'qresult';
}

function answer(yes){
  if(!current){
    $('#quizResult').textContent = 'Deal a card first.';
    $('#quizResult').className = 'qresult no';
    return;
  }
  const ok = (yes && current.expected==='yes') || (!yes && current.expected==='no');
  $('#quizResult').textContent = (ok ? `✓ Reasonable! ${current.note}` : `Not quite (for this toy set). ${current.note}`);
  $('#quizResult').className = 'qresult ' + (ok ? 'ok' : 'no');
}

$('#deal').addEventListener('click', deal);
$('#ansYes').addEventListener('click', ()=>answer(true));
$('#ansNo').addEventListener('click', ()=>answer(false));

// initial render
render();

