const $ = (s)=>document.querySelector(s);

const examples = [
  "Ἀχιλλεύς",
  "Διομήδης",
  "Ἀριστοτέλης",
  "Δαρδανεύς",
  "πρυτάνις",
  "ἑταῖρος",
  "γυνή",
  "ἀλλοῖος",
  "γελοῖος",
  "ὅμοιος",
  "πατρῷος",
  "ἡρῷος"
];

function initChips(){
  const box = $("#chips");
  box.innerHTML = "";
  examples.forEach(t=>{
    const b = document.createElement("button");
    b.type = "button";
    b.className = "chip";
    b.textContent = t;
    b.addEventListener("click", ()=>{ $("#in").value = t; run(); });
    box.appendChild(b);
  });
}

// --- Greek helpers (very heuristic) ---
const COMBINING = /[\u0300-\u036f]/g; // includes tonos/oxia/perispomeni etc.

function stripDiacritics(s){
  return s.normalize('NFD').replace(COMBINING,'').normalize('NFC');
}

function lastWord(s){
  const parts = s.trim().split(/\s+/).filter(Boolean);
  return parts.length ? parts[parts.length-1] : "";
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code>=0x0370 && code<=0x03FF) || (code>=0x1F00 && code<=0x1FFF);
}

function onlyGreekish(s){
  return [...s].filter(c=>isGreekLetter(c) || c==='’' || c==="'" || c==='-').join('');
}

const VOWELS = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);

function vowelGroups(word){
  // count groups of vowels (after stripping diacritics)
  const w = stripDiacritics(word);
  let groups = [];
  let cur = "";
  for (const ch of [...w]){
    if (VOWELS.has(ch)){
      cur += ch;
    } else {
      if (cur) { groups.push(cur); cur=""; }
    }
  }
  if (cur) groups.push(cur);
  return groups;
}

function roughSyllableSketch(word){
  const w = stripDiacritics(word);
  // split into chunks ending at each vowel group
  let out=[];
  let buf="";
  let inV=false;
  for (const ch of [...w]){
    const v = VOWELS.has(ch);
    buf += ch;
    if (v && !inV){ inV=true; }
    if (!v && inV){
      // we just left vowel region; close syllable at previous char(s) already in buf
      // too hard to do precisely; instead, close syllable at the vowel boundary by inserting a dot before this consonant
      // We'll post-process.
    }
  }
  // simpler: mark vowel groups with · separators
  const vg = vowelGroups(word);
  if (!vg.length) return "(no vowels?)";
  // create a display like: CVCV... by replacing each vowel group with [V]
  let disp = stripDiacritics(word);
  // protect by scanning
  let res="";
  let i=0;
  while (i<disp.length){
    const ch = disp[i];
    if (VOWELS.has(ch)){
      // consume vowel run
      let j=i;
      while (j<disp.length && VOWELS.has(disp[j])) j++;
      res += disp.slice(i,j) + "·";
      i=j;
    } else {
      res += ch;
      i++;
    }
  }
  res = res.replace(/·$/,'');
  return res;
}

function endsWithAny(w, arr){
  return arr.some(s=>w.endsWith(s));
}

function makeEios(base){
  // Very rough: try to form a stem then add -ειος
  const b = base;
  if (endsWithAny(b,["εύς","εύς","ευς"])) return b.replace(/(εύς|εύς|ευς)$/,"ειος");
  if (endsWithAny(b,["ης","ῆς","ης"])) return b.replace(/(ῆς|ης)$/,"ειος");
  if (endsWithAny(b,["ος","ός","ος"])) return b.replace(/(ός|ος)$/,"ειος");
  if (endsWithAny(b,["ις","ίς","ις"])) return b.replace(/(ίς|ις)$/,"ειος");
  if (endsWithAny(b,["ων","ών","ων"])) return b.replace(/(ών|ων)$/,"νειος"); // e.g. Ἰορδάνης? (toy)
  // default: just append
  return b + "ειος";
}

function makeOios(base){
  const b = base;
  if (endsWithAny(b,["ωϊος","ῷος","ωιος"])) return b; // already
  if (endsWithAny(b,["ος","ός","ος"])) return b.replace(/(ός|ος)$/,"οιος");
  return b + "οιος";
}

function applyBoeotian(word){
  // ωϊ / ῳ / ωι -> οι (very rough)
  let w = word;
  w = w.replace(/ωϊ/g,"οι");
  w = w.replace(/ωι/g,"οι");
  w = w.replace(/ῳ/g,"οι");
  w = w.replace(/ῷ/g,"οι");
  return w;
}

function accentSuggestion(word, laterAttic){
  const plain = stripDiacritics(word).toLowerCase();
  const sylls = vowelGroups(word).length;

  // Special cases mentioned
  if (plain === "ψοθοιος"){
    return {label:"Oxytone (acute on last): ψοθοιός", why:"Herodian: ψοθοιός is accented on the acute."};
  }

  if (plain === "δαρδανειος"){
    return {label:"Oxytone (acute on last): Δαρδανειός", why:"Herodian explicitly: Δαρδανειός is oxytone."};
  }

  if (plain === "γελοιος" || plain === "ομοιος"){
    if (laterAttic){
      return {label:"Proparoxytone (accent on antepenult): γέλοιος / ὅμοιος", why:"Herodian notes later Attic writers accent γελοῖος and ὁμοῖος on the antepenult."};
    }
    return {label:"Properly proparoxytone with circumflex on antepenult: γελοῖος / ὁμοῖος", why:"Herodian’s rule for -οιος (more than 2 syllables): προπερισπώμενα (circumflex on antepenult)."};
  }

  // -οιος rule
  if (plain.endsWith("οιος")){
    if (sylls <= 2){
      return {label:"Disyllable exception: often not προπερισπώμενον", why:"Herodian: φλοιός is disyllabic; κολοιός is an appellative (not following the >2-syllable rule)."};
    }
    return {label:"Proparoxytone with circumflex on antepenult (προπερισπώμενον)", why:"Rule stated: -οιος, >2 syllables, adjectival/proper → circumflex on antepenult (e.g. ἀλλοῖος, αἰδοῖος, παντοῖος)."};
  }

  // -ειος: we’ll just give a plausible note
  if (plain.endsWith("ειος")){
    return {label:"Often recessive-ish; many examples in Herodian (-ειος)", why:"Herodian lists many -ειος forms and discusses accent variation (e.g. Δαρδανειός oxytone; ἑταίρειος debated)."};
  }

  return {label:"(No rule triggered)", why:"Try a form ending in -ειος or -οιος."};
}

function run(){
  const raw = $("#in").value;
  const mode = $("#mode").value;
  const laterAttic = $("#laterAttic").checked;
  const boeotian = $("#boeotian").checked;
  const strip = $("#strip").checked;

  let w = onlyGreekish(lastWord(raw));
  if (!w){
    $("#result").textContent = "—";
    $("#accent").textContent = "—";
    $("#syll").textContent = "—";
    $("#resultNote").textContent = "";
    $("#accentWhy").textContent = "";
    return;
  }

  const wForBuild = strip ? stripDiacritics(w) : w;

  let out = wForBuild;
  let note = "";

  const plain = stripDiacritics(wForBuild).toLowerCase();
  const looksEios = plain.endsWith("ειος");
  const looksOios = plain.endsWith("οιος") || plain.endsWith("ῷος") || plain.endsWith("ωϊος");

  let effectiveMode = mode;
  if (mode === "auto"){
    if (looksEios || looksOios) effectiveMode = "analyze";
    else {
      // guess: if ends with -ος/-ης/-εύς etc, default to -ειος (since passage is heavy on -ειος)
      effectiveMode = "eios";
    }
  }

  if (effectiveMode === "eios"){
    out = makeEios(wForBuild);
    note = "Built a toy -ειος adjective from the input stem.";
  } else if (effectiveMode === "oios"){
    out = makeOios(wForBuild);
    note = "Built a toy -οιος adjective from the input stem.";
  } else {
    out = wForBuild;
    note = "Analyzing the word as given (toy rules).";
  }

  if (boeotian){
    const before = out;
    out = applyBoeotian(out);
    if (before !== out) note += " Boeotian option applied (ωϊ/ῳ → οι).";
    else note += " (No ωϊ/ῳ sequence found to change.)";
  }

  const acc = accentSuggestion(out, laterAttic);

  $("#result").textContent = out;
  $("#resultNote").textContent = note;
  $("#accent").textContent = acc.label;
  $("#accentWhy").textContent = acc.why;
  $("#syll").textContent = roughSyllableSketch(out) + `   (vowel-groups: ${vowelGroups(out).length})`;
}

$("#go").addEventListener("click", run);
$("#clear").addEventListener("click", ()=>{
  $("#in").value = "";
  run();
});
$("#in").addEventListener("keydown", (e)=>{ if(e.key==="Enter") run(); });
$("#mode").addEventListener("change", run);
$("#laterAttic").addEventListener("change", run);
$("#boeotian").addEventListener("change", run);
$("#strip").addEventListener("change", run);

initChips();
run();

