const $ = (sel) => document.querySelector(sel);

// --- Unicode helpers ---
function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

// Remove Greek diacritics (accents/breathings/diaeresis/iota subscript) but keep base letters.
function stripDiacritics(s){
  // Remove combining marks in Greek ranges + general combining diacritics.
  return nfc(nfd(s).replace(/[\u0300-\u036f\u1ab0-\u1aff\u1dc0-\u1dff\u20d0-\u20ff\ufe20-\ufe2f]/g,''));
}

function isGreekLetter(ch){
  const cp = ch.codePointAt(0);
  return (cp>=0x0370 && cp<=0x03FF) || (cp>=0x1F00 && cp<=0x1FFF);
}

function keepOnlyGreekAndPunct(s){
  // Keep Greek letters and a few separators.
  return [...s].filter(c => isGreekLetter(c) || /[\s\-·'’]/.test(c)).join('');
}

function lowerGreek(s){
  // Locale-insensitive; good enough for toy.
  return s.toLowerCase();
}

// --- Syllable sketch (very approximate) ---
const vowels = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ']);
const diphthongs = ['αι','ει','οι','υι','αυ','ευ','ου','ηυ'];

function syllableSketch(word){
  const w = lowerGreek(stripDiacritics(word)).replace(/[^\p{L}]/gu,'');
  if(!w) return '—';
  // Mark vowel nuclei; treat diphthongs as one nucleus.
  let nuclei = [];
  for(let i=0;i<w.length;i++){
    const two = w.slice(i,i+2);
    if(diphthongs.includes(two)){
      nuclei.push({i, len:2, text:two});
      i++;
    } else if(vowels.has(w[i])){
      nuclei.push({i, len:1, text:w[i]});
    }
  }
  if(nuclei.length===0) return 'no vowel nuclei found';
  // Build a simple segmentation by cutting before each nucleus after the first.
  let cuts = [0];
  for(let k=1;k<nuclei.length;k++) cuts.push(nuclei[k].i);
  cuts.push(w.length);
  let parts=[];
  for(let c=0;c<cuts.length-1;c++) parts.push(w.slice(cuts[c], cuts[c+1]));
  return parts.join('·');
}

// --- Accent placement (toy rules inspired by passage) ---
function addAcuteToVowelNucleus(word, nucleusIndexFromEnd){
  // nucleusIndexFromEnd: 1=ultima nucleus, 2=penult nucleus, etc.
  const original = word;
  const cleaned = keepOnlyGreekAndPunct(original);
  // Work on a diacritic-stripped version for locating nuclei, but apply to original letters.
  const base = stripDiacritics(cleaned);

  // Map base indices to original indices (best-effort, since stripping can change length in rare cases).
  // We'll operate in NFD to keep combining marks explicit.
  const origNFD = nfd(cleaned);
  const baseNFD = nfd(base);

  // Build an index map from baseNFD letter positions to origNFD positions by scanning letters.
  const origLetters = [];
  for(let i=0;i<origNFD.length;i++){
    const ch = origNFD[i];
    if(/\p{L}/u.test(ch)) origLetters.push({pos:i, ch});
  }
  const baseLetters = [];
  for(let i=0;i<baseNFD.length;i++){
    const ch = baseNFD[i];
    if(/\p{L}/u.test(ch)) baseLetters.push({pos:i, ch});
  }
  const L = Math.min(origLetters.length, baseLetters.length);
  const map = new Array(baseLetters.length).fill(null);
  for(let k=0;k<L;k++) map[k] = origLetters[k].pos;

  const baseLettersStr = baseLetters.map(o=>o.ch).join('');
  const w = lowerGreek(baseLettersStr);

  // Find vowel nuclei positions in baseLettersStr indices.
  let nuclei=[];
  for(let i=0;i<w.length;i++){
    const two = w.slice(i,i+2);
    if(diphthongs.includes(two)){
      nuclei.push({i, len:2});
      i++;
    } else if(vowels.has(w[i])){
      nuclei.push({i, len:1});
    }
  }
  if(nuclei.length===0) return {out: cleaned, note:'Could not find a vowel nucleus to accent.'};

  const idx = nuclei.length - nucleusIndexFromEnd;
  const target = nuclei[Math.max(0, Math.min(nuclei.length-1, idx))];

  // Decide which letter in the nucleus gets the accent: for diphthongs, accent the second vowel.
  const letterIndex = target.i + (target.len===2 ? 1 : 0);
  const origPos = map[letterIndex];
  if(origPos==null) return {out: cleaned, note:'Index mapping failed (toy limitation).'};

  // Insert combining acute after the target letter, removing any existing accent marks on that letter.
  // First, remove combining marks immediately after that letter in origNFD.
  let arr = [...origNFD];
  // Find the array index corresponding to origPos in code units.
  // Since arr is by code points, approximate by slicing string.
  const prefix = origNFD.slice(0, origPos);
  const prefixArrLen = [...prefix].length;
  let j = prefixArrLen + 1;
  while(j < arr.length && /[\u0300-\u036f\u1ab0-\u1aff\u1dc0-\u1dff\u20d0-\u20ff\ufe20-\ufe2f]/.test(arr[j])){
    arr.splice(j,1);
  }
  // Add acute
  arr.splice(prefixArrLen+1, 0, '\u0301');
  return {out: nfc(arr.join('')), note:null};
}

function addCircumflexToPenult(word){
  // Very toy: put circumflex on penult nucleus (combining perispomeni U+0342).
  const cleaned = keepOnlyGreekAndPunct(word);
  const base = stripDiacritics(cleaned);
  const origNFD = nfd(cleaned);
  const baseNFD = nfd(base);

  const origLetters=[]; for(let i=0;i<origNFD.length;i++){ if(/\p{L}/u.test(origNFD[i])) origLetters.push({pos:i,ch:origNFD[i]}); }
  const baseLetters=[]; for(let i=0;i<baseNFD.length;i++){ if(/\p{L}/u.test(baseNFD[i])) baseLetters.push({pos:i,ch:baseNFD[i]}); }
  const L=Math.min(origLetters.length, baseLetters.length);
  const map=new Array(baseLetters.length).fill(null);
  for(let k=0;k<L;k++) map[k]=origLetters[k].pos;

  const w = lowerGreek(baseLetters.map(o=>o.ch).join(''));
  let nuclei=[];
  for(let i=0;i<w.length;i++){
    const two=w.slice(i,i+2);
    if(diphthongs.includes(two)){ nuclei.push({i,len:2}); i++; }
    else if(vowels.has(w[i])) nuclei.push({i,len:1});
  }
  if(nuclei.length<2) return {out: cleaned, note:'Need at least two vowel nuclei for a penult circumflex.'};
  const target = nuclei[nuclei.length-2];
  const letterIndex = target.i + (target.len===2 ? 1 : 0);
  const origPos = map[letterIndex];
  if(origPos==null) return {out: cleaned, note:'Index mapping failed (toy limitation).'};

  let arr=[...origNFD];
  const prefix=origNFD.slice(0, origPos);
  const prefixArrLen=[...prefix].length;
  let j=prefixArrLen+1;
  while(j<arr.length && /[\u0300-\u036f\u1ab0-\u1aff\u1dc0-\u1dff\u20d0-\u20ff\ufe20-\ufe2f]/.test(arr[j])) arr.splice(j,1);
  arr.splice(prefixArrLen+1,0,'\u0342');
  return {out:nfc(arr.join('')), note:null};
}

function endsWithAny(w, arr){
  return arr.some(s => w.endsWith(s));
}

function guessKind(word, selected){
  if(selected !== 'auto') return selected;
  // Heuristic: initial capital => proper name.
  const trimmed = word.trim();
  const firstGreek = [...trimmed].find(ch => isGreekLetter(ch));
  if(firstGreek && firstGreek === firstGreek.toUpperCase() && firstGreek !== firstGreek.toLowerCase()) return 'proper';
  return 'adj';
}

function applyToyRule(input, kindSel){
  const raw = input.trim();
  if(!raw) return {out:'—', rule:'Type a word first.', syll:'—'};

  const cleaned = keepOnlyGreekAndPunct(raw);
  const baseLower = lowerGreek(stripDiacritics(cleaned)).replace(/[^\p{L}]/gu,'');
  const kind = guessKind(cleaned, kindSel);

  // Special noted pair: Bolbos proper vs bolbos appellative.
  if(baseLower === 'βολβος'){
    if(kind === 'proper'){
      const r = addAcuteToVowelNucleus(cleaned, 2); // penult
      return {out:r.out, rule:"Noted exception: Βόλβος (proper name) is paroxytone (penult).", syll:syllableSketch(cleaned)};
    } else {
      // appellative: oxytone (final)
      const r = addAcuteToVowelNucleus(cleaned, 1);
      return {out:r.out, rule:"Appellative βολβός is oxytone (final).", syll:syllableSketch(cleaned)};
    }
  }

  // Rule group 1: -αυος / -ευος (pure diphthong with upsilon)
  if(endsWithAny(baseLower, ['αυος','ευος','ηυος'])){
    if(kind === 'proper'){
      // Herodian: some proper names are barytone; we approximate by penult accent.
      const r = addAcuteToVowelNucleus(cleaned, 2);
      return {out:r.out, rule:"-αυος/-ευος: if treated as a proper name (not adjectival), toy makes it barytone → accent on penult.", syll:syllableSketch(cleaned)};
    } else {
      const r = addAcuteToVowelNucleus(cleaned, 1);
      return {out:r.out, rule:"-αυος/-ευος: adjectival (or proper name homophonous with adjective) → oxytone (final).", syll:syllableSketch(cleaned)};
    }
  }

  // Rule group 2: disyllabic -βος
  if(baseLower.endsWith('βος')){
    // Count vowel nuclei to approximate syllable count.
    const sketch = syllableSketch(cleaned);
    const nucleiCount = (sketch==='—') ? 0 : sketch.split('·').length;

    if(nucleiCount === 2){
      if(kind === 'adj'){
        const r = addAcuteToVowelNucleus(cleaned, 1);
        return {out:r.out, rule:"Disyllabic adjectives in -βος → oxytone (final): e.g. στραβός.", syll:sketch};
      } else {
        const r = addAcuteToVowelNucleus(cleaned, 2);
        return {out:r.out, rule:"Disyllabic nouns/proper names in -βος → barytone (not final): e.g. ὄλβος, Λέσβος.", syll:sketch};
      }
    }

    // Fallback for -βος not disyllabic: just accent penult as a safe-ish default.
    const r = addAcuteToVowelNucleus(cleaned, 2);
    return {out:r.out, rule:"Ends in -βος but not clearly disyllabic (toy). Defaulting to penult accent.", syll:sketch};
  }

  // Default: accent penult nucleus.
  const r = addAcuteToVowelNucleus(cleaned, 2);
  return {out:r.out, rule:"No matching ending; toy default: accent the penult nucleus.", syll:syllableSketch(cleaned)};
}

// --- UI wiring ---
const examples = [
  {w:'στραβος', kind:'adj'},
  {w:'ὄλβος', kind:'proper'},
  {w:'Λεσβος', kind:'proper'},
  {w:'αγαυος', kind:'adj'},
  {w:'Ακαλαυος', kind:'proper'},
  {w:'Πειραυος', kind:'proper'},
  {w:'Αρευος', kind:'proper'},
  {w:'βολβος', kind:'adj'},
  {w:'Βολβος', kind:'proper'},
  {w:'ῥαιβος', kind:'adj'}
];

function render(){
  const input = $('#w').value;
  const kindSel = $('#kind').value;
  const keepCase = $('#keepCase').checked;

  let working = input;
  if(!keepCase) working = lowerGreek(working);

  const res = applyToyRule(working, kindSel);
  $('#result').textContent = res.out;
  $('#rule').textContent = res.rule;
  $('#syll').textContent = res.syll;
}

$('#apply').addEventListener('click', render);
$('#w').addEventListener('input', () => {
  // Live update, but only if there is something.
  if($('#w').value.trim().length) render();
});
$('#kind').addEventListener('change', render);
$('#keepCase').addEventListener('change', render);

$('#strip').addEventListener('click', () => {
  const v = $('#w').value;
  $('#w').value = stripDiacritics(v);
  render();
});

$('#random').addEventListener('click', () => {
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#w').value = ex.w;
  $('#kind').value = 'auto';
  render();
});

// Seed
$('#w').value = 'στραβος';
render();

