(() => {
  const $ = (sel, root=document) => root.querySelector(sel);
  const inp = $('#inp');
  const outWord = $('#outWord');
  const outRule = $('#outRule');
  const outSyl = $('#outSyl');
  const outPen = $('#outPen');

  const examples = [
    'αραβος','κοναβος','ιαμβος','καραβος','σαραβος','αττελαβος','νηραβος','αμολβος','αρισβος','βαταναβος','πρασσαιβος','κανδυβος','μεταβος','πολυβος','χαλυβος','καλλατηβος','τυρρηβος','κανωβος',
    'ερεμβος','περραιβος','κολοβος','βουφορβος','ιπποφορβος','εφηβος','ανηβος','φιλοκυβος',
    'πυργος','σπογγος','φθογγος','γοργος','ελγος','λιγγος','σιγγος','σαργος','αργος','αργος'
  ];

  // --- Greek helpers ---
  const combiningMarks = /[\u0300-\u036f\u1ab0-\u1aff\u1dc0-\u1dff\u20d0-\u20ff\ufe20-\ufe2f]/g;

  function stripDiacritics(s){
    // Remove combining marks and also precomposed polytonic accents by NFD.
    return s.normalize('NFD').replace(combiningMarks,'').normalize('NFC');
  }

  function normalizeGreek(s){
    return stripDiacritics(s)
      .replace(/[\s··.,;:!?"'“”‘’()\[\]{}<>]/g,'')
      .replace(/ς/g,'σ')
      .toLowerCase();
  }

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω']);
  const diphthongs = new Set(['αι','ει','οι','υι','αυ','ευ','ηυ','ου']);

  function syllabify(word){
    // Very rough: split into vowel nuclei (diphthongs count as one).
    const w = word;
    const syl = [];
    let i = 0;
    while(i < w.length){
      // onset
      let onsetStart = i;
      while(i < w.length && !vowels.has(w[i])) i++;
      let onset = w.slice(onsetStart, i);
      if(i >= w.length){
        if(syl.length){
          syl[syl.length-1] += onset;
        } else if(onset){
          syl.push(onset);
        }
        break;
      }
      // nucleus
      let nuc = w[i];
      if(i+1 < w.length){
        const pair = w.slice(i,i+2);
        if(diphthongs.has(pair)){
          nuc = pair;
          i += 2;
        } else {
          i += 1;
        }
      } else {
        i += 1;
      }
      // coda/next onset will be handled by next loop; we attach consonants between nuclei to the next onset,
      // except we keep a single consonant as coda if it is the last.
      syl.push(onset + nuc);
    }

    // Now distribute internal consonant clusters: move trailing consonants from each syllable to next syllable onset.
    // Our construction already puts consonants before vowel into onset; but consonants after nucleus are currently absent.
    // So we need a second pass to insert the inter-vocalic consonants.
    // We'll rebuild by scanning nuclei positions.
    const nuclei = [];
    // find vowel-group indices in word
    let j=0;
    while(j<w.length){
      if(vowels.has(w[j])){
        let start=j;
        let end=j+1;
        if(end<w.length && diphthongs.has(w.slice(start,end+1))) end++;
        nuclei.push([start,end]);
        j=end;
      } else j++;
    }
    if(nuclei.length<=1) return [w];

    const out=[];
    for(let k=0;k<nuclei.length;k++){
      const [ns,ne]=nuclei[k];
      const prevEnd = (k===0)?0:nuclei[k-1][1];
      const nextStart = (k===nuclei.length-1)?w.length:nuclei[k+1][0];
      const onset = w.slice(prevEnd, ns);
      const nucleus = w.slice(ns, ne);
      const between = w.slice(ne, nextStart);
      // put all 'between' consonants into next onset, except if last nucleus then keep as coda
      const coda = (k===nuclei.length-1)?between:'';
      out.push(onset + nucleus + coda);
    }
    return out.filter(x=>x.length);
  }

  function penultVowel(word){
    const syl = syllabify(word);
    if(syl.length < 2) return null;
    const pen = syl[syl.length-2];
    // find last vowel group in penult syllable
    const chars = [...pen];
    for(let i=0;i<chars.length;i++){
      if(vowels.has(chars[i])){
        // check diphthong
        if(i+1<chars.length && diphthongs.has(chars[i]+chars[i+1])) return chars[i]+chars[i+1];
        return chars[i];
      }
    }
    return null;
  }

  function endsWith(word, ending){
    return word.endsWith(ending);
  }

  function looksCompound(word){
    // toy heuristic: contains a clear connector vowel -ο- or -ι- before final -βος/-γος with extra material
    // e.g. βου-φορβος, ιππο-φορβος, φιλο-κυβος
    return /(ο|ι).{1,6}(βος|γος)$/.test(word) && word.length >= 7;
  }

  function accentuate(word, target){
    // target: 'ultima' | 'penult' | 'antepenult'
    const syl = syllabify(word);
    if(!syl.length) return {word:'', syl:[]};
    let idx;
    if(target==='ultima') idx = syl.length-1;
    else if(target==='penult') idx = Math.max(0, syl.length-2);
    else idx = Math.max(0, syl.length-3);

    // place acute on first vowel of that syllable
    const acuteMap = {
      'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
      'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
    };

    const s = syl[idx];
    let placed = false;
    let outSyl = syl.slice();
    let chars = [...s];
    for(let i=0;i<chars.length;i++){
      const ch = chars[i];
      if(vowels.has(ch)){
        // diphthong: accent first vowel (toy)
        chars[i] = acuteMap[ch] || ch;
        placed = true;
        break;
      }
    }
    outSyl[idx] = chars.join('');
    return {word: outSyl.join(''), syl: outSyl};
  }

  function decide(word, forcedKind){
    const w = normalizeGreek(word);
    if(!w) return {ok:false, msg:'Type a Greek word.'};

    const syl = syllabify(w);
    const n = syl.length;
    const penV = penultVowel(w);

    const isBos = endsWith(w,'βος');
    const isGos = endsWith(w,'γος');

    let kind = forcedKind;
    if(kind==='auto'){
      if(isBos) kind = 'proper';
      else if(isGos) kind = 'gosName';
      else kind = 'autoUnknown';
    }

    let target = 'penult';
    let rule = '';

    if(isBos){
      if(kind==='adj'){
        if(n>2){
          if(penV==='η'){
            target = 'penult';
            rule = "-βος adjective (>2 syll.) with η in penult → exception: not oxytone (toy puts accent on penult).";
          } else if(looksCompound(w)){
            target = 'penult';
            rule = "-βος adjective (>2 syll.) that looks compound → exception: not oxytone (toy puts accent on penult).";
          } else {
            target = 'ultima';
            rule = "-βος adjective (>2 syll.) → oxytone (accent on ultima).";
          }
        } else {
          target = 'penult';
          rule = "-βος adjective (≤2 syll.) → toy defaults to penult.";
        }
      } else { // proper/appellative
        if(n>2){
          target = 'antepenult';
          rule = "-βος proper/appellative (>2 syll.) → proparoxytone (accent on antepenult).";
        } else {
          target = 'penult';
          rule = "-βος (≤2 syll.) → toy defaults to penult.";
        }
      }
    } else if(isGos){
      if(kind==='gosAdj'){
        target = 'ultima';
        rule = "-γος adjective (disyllabic pattern) → oxytone (accent on ultima), e.g. γοργός.";
        if(w==='αργος'){
          // ambiguous: Ἄργος vs ἀργός
          rule += " Note: αργος could be Ἄργος (barytone) or ἀργός (oxytone).";
        }
      } else { // noun/name
        target = 'penult';
        rule = "-γος noun/name (disyllabic pattern) → barytone (toy puts accent on penult), e.g. πύργος.";
        if(w==='σαργος'){
          target = 'ultima';
          rule = "Exception noted: σαργός (fish) is oxytone.";
        }
        if(w==='αργος'){
          target = 'penult';
          rule = "Exception noted: Ἄργος is barytone (toy puts accent on penult).";
        }
      }
    } else {
      target = (n>=2)?'penult':'ultima';
      rule = "Word does not end in -βος or -γος; toy just accents the penult (or ultima if monosyllable).";
    }

    const acc = accentuate(w, target);

    // penult ω check for -βος >2 syllables
    let penMsg = '—';
    if(isBos && n>2){
      if(penV==='ω') penMsg = "Penult has ω → ‘odd’ per Herodian (think Κάνωβος).";
      else penMsg = `Penult vowel: ${penV || 'unknown'} (toy check).`;
    } else if(isBos){
      penMsg = `Penult vowel: ${penV || 'unknown'} (toy check).`;
    } else {
      penMsg = `Penult vowel: ${penV || 'unknown'} (toy check).`;
    }

    return {ok:true, base:w, accented:acc.word, syl:acc.syl, rule, penMsg};
  }

  function currentKind(){
    const r = document.querySelector('input[name="kind"]:checked');
    return r ? r.value : 'auto';
  }

  function run(){
    const res = decide(inp.value, currentKind());
    if(!res.ok){
      outWord.textContent = '—';
      outRule.textContent = res.msg;
      outSyl.textContent = '—';
      outPen.textContent = '—';
      return;
    }
    outWord.textContent = res.accented;
    outRule.textContent = res.rule;
    outSyl.textContent = res.syl.join(' · ');
    outPen.textContent = res.penMsg;
  }

  $('#go').addEventListener('click', run);
  inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') run(); });

  $('#rand').addEventListener('click', ()=>{
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inp.value = ex;
    run();
    inp.focus();
    inp.setSelectionRange(0, inp.value.length);
  });

  $('#clear').addEventListener('click', ()=>{
    inp.value='';
    outWord.textContent='—';
    outRule.textContent='—';
    outSyl.textContent='—';
    outPen.textContent='—';
    inp.focus();
  });

  // seed
  inp.value = 'καραβος';
  run();
})();

