:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --card:#1d2140;
  --text:#eef0ff;
  --muted:#b9bce0;
  --faint:#8b8fb8;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --good:#34d399;
  --warn:#fbbf24;
  --bad:#fb7185;
  --border:rgba(255,255,255,.12);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
}

*{box-sizing:border-box}

.wrap{
  max-width: 980px;
  margin: 24px auto;
  padding: 18px;
  color: var(--text);
  font: 16px/1.45 system-ui, -apple-system, Segoe UI, Roboto, Arial, "Noto Sans", "DejaVu Sans", sans-serif;
}

header h1{
  margin: 0 0 6px 0;
  font-size: 22px;
  letter-spacing: .2px;
}

.sub{margin:0 0 14px 0; color: var(--muted)}

.panel{
  background: linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 14px;
  box-shadow: var(--shadow);
  margin: 12px 0;
}

.row{display:flex; gap:12px; align-items:flex-end; flex-wrap:wrap}
.row.small{align-items:center}

label{display:block; font-size: 13px; color: var(--muted); margin-bottom: 6px}

#inp{
  flex: 1 1 420px;
  min-width: 260px;
  padding: 12px 12px;
  border-radius: 12px;
  border: 1px solid var(--border);
  background: rgba(0,0,0,.25);
  color: var(--text);
  outline: none;
  font-size: 18px;
}
#inp:focus{border-color: rgba(125,211,252,.55); box-shadow: 0 0 0 4px rgba(125,211,252,.12)}

.btns{display:flex; gap:10px}
button{
  border: 1px solid var(--border);
  background: rgba(255,255,255,.06);
  color: var(--text);
  padding: 10px 12px;
  border-radius: 12px;
  cursor: pointer;
}
button:hover{background: rgba(255,255,255,.10)}
button:active{transform: translateY(1px)}
button.primary{border-color: rgba(125,211,252,.45); background: rgba(125,211,252,.14)}

.chips{display:flex; flex-wrap:wrap; gap:8px; margin-top: 8px}
.chip{
  padding: 6px 10px;
  border-radius: 999px;
  font-size: 14px;
  background: rgba(167,139,250,.12);
  border-color: rgba(167,139,250,.35);
}

.grid{display:grid; grid-template-columns: 1.1fr .9fr; gap: 12px; margin-top: 12px}
@media (max-width: 860px){.grid{grid-template-columns: 1fr}}

.card{
  background: rgba(0,0,0,.18);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 12px;
}
.card h2{margin: 0 0 8px 0; font-size: 16px; color: var(--accent)}

.out{
  padding: 10px;
  border-radius: 12px;
  border: 1px dashed rgba(255,255,255,.18);
  background: rgba(0,0,0,.18);
  min-height: 92px;
}

.muted{color: var(--muted)}
.note{color: var(--faint); margin: 10px 0 0 0; font-size: 13px}

.help{margin: 0; padding-left: 18px; color: var(--muted)}
.help ul{margin: 6px 0 0 0; padding-left: 18px}

.lab{display:grid; grid-template-columns: repeat(3, 1fr); gap: 10px}
@media (max-width: 860px){.lab{grid-template-columns: 1fr}}

.labTitle{font-size: 13px; color: var(--muted); margin-bottom: 6px}
.mono{font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, "DejaVu Sans Mono", monospace; background: rgba(0,0,0,.18); border: 1px solid var(--border); padding: 10px; border-radius: 12px; min-height: 42px}

.badge{display:inline-block; padding: 2px 8px; border-radius: 999px; font-size: 12px; border: 1px solid var(--border); margin-left: 8px; vertical-align: 2px}
.badge.good{background: rgba(52,211,153,.12); border-color: rgba(52,211,153,.35); color: #bff7df}
.badge.warn{background: rgba(251,191,36,.12); border-color: rgba(251,191,36,.35); color: #ffe7b0}
.badge.bad{background: rgba(251,113,133,.12); border-color: rgba(251,113,133,.35); color: #ffd0d8}

.bigGreek{font-size: 26px; letter-spacing: .2px}
.rule{margin-top: 8px; color: var(--muted)}

footer details{margin-top: 10px}
footer summary{cursor:pointer; color: var(--accent2)}
.details{color: var(--muted); margin-top: 8px}

body{background: radial-gradient(1200px 700px at 20% 0%, rgba(167,139,250,.18), transparent 55%), radial-gradient(900px 600px at 90% 10%, rgba(125,211,252,.16), transparent 55%), var(--bg)}

