const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const out = $('#out');
const normBox = $('#norm');
const syllBox = $('#syll');
const longBox = $('#long');

// Tiny exception list inspired by the passage.
// We store normalized (no accents, lowercase) forms.
const LEX = {
  // -ογος dibrachys barytone examples
  'λογος': {accent: 'penult', tag: 'attested', note: 'Herodian: -ογος dibrachys → barytone.'},
  'μογος': {accent: 'penult', tag: 'attested', note: 'Herodian: -ογος dibrachys → barytone.'},
  'ψογος': {accent: 'penult', tag: 'attested', note: 'Herodian: -ογος dibrachys → barytone.'},

  // -αγος adjectival oxytone examples
  'φαγος': {accent: 'ultima', tag: 'attested', note: 'Herodian: -αγος adjectival (not ethnic) → oxytone.'},
  // κραγος is ambiguous in passage: κραγός (adj) vs κράγος (noun) and Κράγος (mountain)
  'κραγος': {accent: 'either', tag: 'ambiguous', note: 'Herodian distinguishes κραγός (adj, oxytone) vs κράγος (noun/proper, barytone).'},

  // barytone with contracted long before end (examples)
  'παγος': {accent: 'penult', tag: 'attested', note: 'Herodian: disyllables in -γος with contracted long before end → barytone.'},
  'τραγος': {accent: 'penult', tag: 'attested', note: 'Herodian: disyllables in -γος with contracted long before end → barytone.'},

  // naturally long penult oxytone examples
  'λοιγος': {accent: 'ultima', tag: 'attested', note: 'Herodian: naturally long penult → oxytone (unless proper name).'},
  'φηγος': {accent: 'ultima', tag: 'attested', note: 'Herodian: naturally long penult → oxytone (unless proper name).'},
  'πηγος': {accent: 'ultima', tag: 'attested', note: 'Herodian: naturally long penult → oxytone (unless proper name).'},

  // proper name exception
  'λαγος': {accent: 'penult', tag: 'exception', note: 'Herodian: Λᾶγος is a proper name (exception).'}
};

function stripDiacritics(s){
  // Remove combining marks after NFD decomposition.
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function normalizeGreek(s){
  return stripDiacritics(s)
    .replace(/ς/g,'σ')
    .replace(/[^\p{Script=Greek}]/gu,'')
    .toLowerCase();
}

function isGreekish(s){
  return /[\p{Script=Greek}]/u.test(s);
}

function addAcuteOnPenultDisyllable(word){
  // Very rough: find last two vowel nuclei and accent the first of them.
  const vowels = 'αεηιουω';
  const acuteMap = { 'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ' };
  const chars = [...word];
  let nuclei = [];
  for(let i=0;i<chars.length;i++){
    if(vowels.includes(chars[i])) nuclei.push(i);
  }
  if(nuclei.length < 2) return word;
  const penultV = nuclei[nuclei.length-2];
  const ch = chars[penultV];
  chars[penultV] = acuteMap[ch] || ch;
  return chars.join('');
}

function addAcuteOnUltima(word){
  const vowels = 'αεηιουω';
  const acuteMap = { 'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ' };
  const chars = [...word];
  for(let i=chars.length-1;i>=0;i--){
    if(vowels.includes(chars[i])){
      const ch = chars[i];
      chars[i] = acuteMap[ch] || ch;
      break;
    }
  }
  return chars.join('');
}

function roughSyllables(word){
  // Extremely approximate: split before the last vowel nucleus to show “penult | ultima”.
  const vowels = 'αεηιουω';
  const chars = [...word];
  let nuclei = [];
  for(let i=0;i<chars.length;i++) if(vowels.includes(chars[i])) nuclei.push(i);
  if(nuclei.length < 2) return [word];
  const cut = nuclei[nuclei.length-1];
  // find a reasonable boundary before last nucleus: back up to previous consonant cluster start
  let b = cut;
  while(b>0 && !vowels.includes(chars[b-1])) b--; // move left over consonants
  // ensure we don't cut at 0
  if(b<=0) b = cut;
  return [chars.slice(0,b).join(''), chars.slice(b).join('')];
}

function penultLooksLong(word){
  // Toy heuristic: if penult contains η/ω or common long diphthongs.
  // We inspect the penult chunk from rough syllabification.
  const syl = roughSyllables(word);
  if(syl.length < 2) return {val:false, why:'Not enough syllables detected.'};
  const pen = syl[0];
  const longish = ['η','ω','ει','ου','αι','αυ','ευ','ηυ','υι'];
  for(const pat of longish){
    if(pen.includes(pat)) return {val:true, why:`Penult contains “${pat}” (toy treats as longish).`};
  }
  return {val:false, why:'No obvious long-vowel/diphthong marker in penult (toy).'};
}

function guessAccent(raw){
  const hasGreek = isGreekish(raw);
  const norm = normalizeGreek(raw);

  normBox.textContent = norm || '—';

  if(!raw.trim()){
    return {error:'Type a Greek word first.'};
  }
  if(!hasGreek){
    return {error:'Please use Greek letters (the toy ignores punctuation/Latin letters).'};
  }
  if(!norm){
    return {error:'Nothing Greek left after normalization.'};
  }

  const syl = roughSyllables(norm);
  syllBox.textContent = syl.length === 1 ? syl[0] : `${syl[0]} | ${syl[1]}`;

  const longInfo = penultLooksLong(norm);
  longBox.textContent = `${longInfo.val ? 'YES' : 'NO'} — ${longInfo.why}`;

  // Only really designed for ...γος
  const endsGos = norm.endsWith('γος');
  if(!endsGos){
    return {
      norm,
      accent: 'unknown',
      badge: {kind:'warn', text:'Not -γος'},
      display: norm,
      rule: 'Herodian’s rules here are about disyllables in -γος. Try something ending in -γος.'
    };
  }

  // Lexical overrides
  if(LEX[norm]){
    const entry = LEX[norm];
    if(entry.accent === 'either'){
      return {
        norm,
        accent: 'either',
        badge: {kind:'warn', text:'Ambiguous'},
        display: `${addAcuteOnPenultDisyllable(norm)} / ${addAcuteOnUltima(norm)}`,
        rule: entry.note
      };
    }
    const display = entry.accent === 'penult' ? addAcuteOnPenultDisyllable(norm) : addAcuteOnUltima(norm);
    return {
      norm,
      accent: entry.accent,
      badge: {kind: entry.tag === 'exception' ? 'warn' : 'good', text: entry.tag},
      display,
      rule: entry.note
    };
  }

  // Heuristics from the passage (simplified)
  const isDisyllable = roughSyllables(norm).length === 2;
  if(!isDisyllable){
    return {
      norm,
      accent: 'unknown',
      badge: {kind:'warn', text:'Not disyllable?'},
      display: norm,
      rule: 'Toy expects a disyllable in -γος. (Syllable splitter is crude; try a simpler form.)'
    };
  }

  // -ογος dibrachys -> barytone (we can’t truly check quantity, so we just key on -ογος)
  if(norm.endsWith('ογος')){
    return {
      norm,
      accent: 'penult',
      badge: {kind:'good', text:'Rule: -ογος'},
      display: addAcuteOnPenultDisyllable(norm),
      rule: 'Heuristic: disyllables in -ογος are often barytone (λόγος, μόγος, ψόγος).'
    };
  }

  // -αγος adjectival -> oxytone (we can’t know adjectival/ethnic; just suggest oxytone)
  if(norm.endsWith('αγος')){
    return {
      norm,
      accent: 'ultima',
      badge: {kind:'good', text:'Rule: -αγος'},
      display: addAcuteOnUltima(norm),
      rule: 'Heuristic: -αγος disyllables tend to be oxytone when adjectival (not ethnic): φαγός, κραγός.'
    };
  }

  // naturally long penult -> oxytone
  if(longInfo.val){
    return {
      norm,
      accent: 'ultima',
      badge: {kind:'good', text:'Rule: long penult'},
      display: addAcuteOnUltima(norm),
      rule: 'Heuristic: if the penult looks naturally long, Herodian says oxytone (unless a proper name).'
    };
  }

  // default: barytone
  return {
    norm,
    accent: 'penult',
    badge: {kind:'warn', text:'Default'},
    display: addAcuteOnPenultDisyllable(norm),
    rule: 'Default guess: barytone (accent on penult). Try known examples or add a long penult (η/ω/ει/ου…).'
  };
}

function render(res){
  if(res.error){
    out.innerHTML = `<div class="muted">${escapeHtml(res.error)}</div>`;
    return;
  }
  const badge = res.badge ? `<span class="badge ${res.badge.kind}">${escapeHtml(res.badge.text)}</span>` : '';
  out.innerHTML = `
    <div class="bigGreek">${escapeHtml(res.display)} ${badge}</div>
    <div class="rule">${escapeHtml(res.rule || '')}</div>
  `;
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function run(){
  render(guessAccent(inp.value));
}

$('#btnGuess').addEventListener('click', run);
$('#btnClear').addEventListener('click', () => {
  inp.value = '';
  out.innerHTML = `<div class="muted">Enter a word and click <b>Guess accent</b>.</div>`;
  normBox.textContent = '—';
  syllBox.textContent = '—';
  longBox.textContent = '—';
  inp.focus();
});

inp.addEventListener('keydown', (e) => {
  if(e.key === 'Enter') run();
});

document.querySelectorAll('.chip').forEach(btn => {
  btn.addEventListener('click', () => {
    inp.value = btn.getAttribute('data-ex');
    run();
    inp.focus();
  });
});

// Seed with a default example
inp.value = 'λογος';
run();

