:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --card:#1d2140;
  --ink:#eef0ff;
  --muted:#b9bde6;
  --faint:#8a90c7;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --good:#34d399;
  --warn:#fbbf24;
  --bad:#fb7185;
  --line:rgba(255,255,255,.10);
}

*{box-sizing:border-box}

.wrap{
  font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Arial, "Noto Sans", "Liberation Sans", sans-serif;
  color:var(--ink);
  background:linear-gradient(180deg, #0b0d18, var(--bg));
  padding:18px;
  border:1px solid var(--line);
  border-radius:16px;
  max-width:980px;
  margin:0 auto;
}

.hdr h2{margin:0 0 6px 0; font-size:20px; letter-spacing:.2px}
.sub{margin:0; color:var(--muted); line-height:1.35}

.panel{margin-top:14px; background:var(--panel); border:1px solid var(--line); border-radius:14px; padding:14px}

.row label{display:block; color:var(--muted); margin-bottom:8px; font-size:13px}

.inputRow{display:flex; gap:8px; flex-wrap:wrap}

input[type="text"]{
  flex:1 1 320px;
  min-width:240px;
  padding:10px 12px;
  border-radius:12px;
  border:1px solid var(--line);
  background:#0c0f1f;
  color:var(--ink);
  font-size:16px;
  outline:none;
}
input[type="text"]:focus{border-color:rgba(125,211,252,.55); box-shadow:0 0 0 3px rgba(125,211,252,.12)}

button{
  padding:10px 12px;
  border-radius:12px;
  border:1px solid var(--line);
  background:#10142a;
  color:var(--ink);
  cursor:pointer;
}
button:hover{border-color:rgba(255,255,255,.22)}
button.primary{background:linear-gradient(180deg, rgba(125,211,252,.25), rgba(167,139,250,.18)); border-color:rgba(125,211,252,.35)}

.toggles{display:flex; gap:14px; flex-wrap:wrap; margin-top:10px}
.chk{color:var(--muted); font-size:13px; user-select:none}
.chk input{transform:translateY(1px)}

.outGrid{display:grid; grid-template-columns: 1fr 1fr; gap:12px; margin-top:14px}
@media (max-width: 820px){.outGrid{grid-template-columns:1fr}}

.card{background:var(--card); border:1px solid var(--line); border-radius:14px; padding:12px}
.card h3{margin:0 0 8px 0; font-size:14px; color:var(--muted); font-weight:650}

.big{font-size:30px; letter-spacing:.3px; padding:6px 0 2px 0}
.meta{color:var(--faint); font-size:13px; min-height:18px}

.meter{display:flex; flex-direction:column; gap:10px; margin-top:6px}
.mRow{display:grid; grid-template-columns: 210px 1fr; gap:10px; align-items:center}
@media (max-width: 520px){.mRow{grid-template-columns:1fr}}
.mLab{color:var(--muted); font-size:13px}
.bar{height:12px; background:rgba(255,255,255,.08); border-radius:999px; overflow:hidden; border:1px solid rgba(255,255,255,.10)}
.fill{height:100%; width:50%; background:linear-gradient(90deg, var(--accent), var(--accent2)); border-radius:999px; transition:width .25s ease}

.hint{margin:10px 0 0 0; color:var(--muted); font-size:13px; line-height:1.35}

.notes{margin-top:12px; border:1px dashed rgba(255,255,255,.18); border-radius:14px; padding:10px 12px; background:rgba(0,0,0,.12)}
.notes summary{cursor:pointer; color:var(--ink); font-weight:650}
.noteBody{margin-top:8px; color:var(--muted); font-size:13px; line-height:1.4}
.noteBody ul{margin:8px 0 8px 18px; padding:0}
.small{color:var(--faint); margin:0}

.ftr{margin-top:12px; color:var(--muted); font-size:13px}
.ex{padding:1px 6px; border:1px solid rgba(255,255,255,.14); border-radius:999px; background:rgba(125,211,252,.10); color:var(--ink)}

mark.accent{
  background:rgba(52,211,153,.18);
  border:1px solid rgba(52,211,153,.25);
  color:var(--ink);
  padding:0 4px;
  border-radius:6px;
}

.badge{display:inline-block; padding:2px 8px; border-radius:999px; border:1px solid rgba(255,255,255,.14); font-size:12px; color:var(--ink); background:rgba(255,255,255,.06)}
.badge.good{border-color:rgba(52,211,153,.35); background:rgba(52,211,153,.12)}
.badge.warn{border-color:rgba(251,191,36,.35); background:rgba(251,191,36,.12)}
.badge.bad{border-color:rgba(251,113,133,.35); background:rgba(251,113,133,.12)}

