(function(){
  const $ = (sel, root=document) => root.querySelector(sel);

  const inp = $('#inp');
  const outWord = $('#outWord');
  const outSyll = $('#outSyll');
  const outWhy = $('#outWhy');
  const barAnte = $('#barAnte');
  const barUlt = $('#barUlt');
  const strip = $('#strip');
  const showSyll = $('#showSyll');

  const examples = [
    {w:'παταγος', note:'Herodian example (short penult → antepenult).'},
    {w:'ελεγος', note:'Herodian example (short penult → antepenult).'},
    {w:'ασπαραγος', note:'Herodian example (polysyllable -γος).'},
    {w:'ασφαραγος', note:'Herodian example (polysyllable -γος).'},
    {w:'πελαργος', note:'Herodian example (trisyll. masc., long penult → ultima).'},
    {w:'αρηγος', note:'Herodian example (trisyll. masc., long penult → ultima).'},
    {w:'αμολγος', note:'Herodian example (often ultima in masc. use).'},
    {w:'βροτολοιγος', note:'Herodian example (compound-ish; toy still tries).'},
    {w:'αρρωγος', note:'Herodian example.'},
    {w:'πελασγος', note:'Ethnic name.'},
    {w:'αβασγος', note:'Ethnic name.'},
    {w:'χολαργος', note:'Deme name.'},
    {w:'ιππημολγος', note:'Ethnic name (horse-milkers).'},
    {w:'ομαργος', note:'Compound (ὁμοῦ + ἀργός), dog name.'},
    {w:'ολιγος', note:'Oddball: only -γος word with penult ι (Herodian).'},
    {w:'συναγγος', note:'Has doubled γγ (flag).'},
    {w:'σαλαγγος', note:'Has doubled γγ (flag).'}
  ];

  // --- Greek helpers (toy-level) ---
  const combiningMarks = /[\u0300-\u036f\u1ab0-\u1aff\u1dc0-\u1dff\u20d0-\u20ff\ufe20-\ufe2f]/g;

  function stripDiacritics(s){
    // Remove tonos/oxia etc by NFD + remove combining marks.
    // Also normalize final sigma.
    return (s||'')
      .normalize('NFD')
      .replace(combiningMarks,'')
      .normalize('NFC');
  }

  function normalizeGreek(s){
    s = (s||'').trim();
    s = s.replace(/ς/g,'σ');
    // keep Greek letters, apostrophes, spaces, hyphen
    return s;
  }

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ']);

  function isVowel(ch){
    return vowels.has(ch);
  }

  function syllabifyToy(word){
    // Very rough: split before each vowel-group after the first.
    // Treat diphthongs ει, οι, αι, αυ, ευ, ου, υι as one nucleus.
    const w = word;
    const nuclei = [];
    let i=0;
    while(i<w.length){
      const ch = w[i];
      if(isVowel(ch)){
        let j=i+1;
        // combine common diphthongs
        const pair = w.slice(i,i+2);
        const diph = ['αι','ει','οι','υι','αυ','ευ','ου','ηυ'];
        if(diph.includes(pair)) j=i+2;
        nuclei.push({start:i, end:j});
        i=j;
      } else {
        i++;
      }
    }
    if(nuclei.length<=1) return [w];

    // Build syllables by cutting mid-consonant cluster before each nucleus (except first)
    const cuts = [0];
    for(let k=1;k<nuclei.length;k++){
      const prevEnd = nuclei[k-1].end;
      const curStart = nuclei[k].start;
      // consonant cluster between prev nucleus and current nucleus
      const clusterLen = Math.max(0, curStart - prevEnd);
      // naive: put 1 consonant to onset if possible
      const cut = (clusterLen<=1) ? prevEnd : (curStart-1);
      cuts.push(cut);
    }
    cuts.push(w.length);

    const sylls=[];
    for(let c=0;c<cuts.length-1;c++){
      sylls.push(w.slice(cuts[c], cuts[c+1]));
    }
    return sylls.filter(x=>x.length);
  }

  function penultNucleus(sylls){
    if(sylls.length<2) return '';
    return sylls[sylls.length-2];
  }

  function isLongishPenult(pen){
    // Toy heuristic: long by nature: η ω; long by common diphthongs: αι ει οι ου αυ ευ ηυ
    const p = pen;
    if(!p) return false;
    const base = stripDiacritics(p);
    if(/[ηω]/.test(base)) return true;
    if(/(αι|ει|οι|ου|αυ|ευ|ηυ)/.test(base)) return true;
    // long by position (toy): vowel followed by 2+ consonants within the syllable
    // (This is not real syllabification; just a nudge.)
    const m = base.match(/[αεηιουω](.+)$/);
    if(m){
      const tail = m[1].replace(/[^βγδζθκλμνξπρσςτφχψ]/g,'');
      if(tail.length>=2) return true;
    }
    return false;
  }

  function addAcuteOnVowel(syll){
    // Put tonos on first vowel of the syllable (modern monotonic).
    const map = { 'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ' };
    const chars = [...syll];
    for(let i=0;i<chars.length;i++){
      const b = stripDiacritics(chars[i]);
      if(map[b]){
        chars[i] = map[b];
        break;
      }
    }
    return chars.join('');
  }

  function accentWordToy(word, target){
    // target: 'antepenult' or 'ultima'
    const sylls = syllabifyToy(word);
    if(sylls.length===0) return {word, sylls};
    let idx = sylls.length-1;
    if(target==='antepenult') idx = Math.max(0, sylls.length-3);
    if(target==='ultima') idx = sylls.length-1;
    const out = sylls.map((s,i)=> i===idx ? addAcuteOnVowel(s) : s).join('');
    return {word: out, sylls};
  }

  function endsWithGos(w){
    const b = stripDiacritics(w.toLowerCase());
    return b.endsWith('γος');
  }

  function hasDoubleGamma(w){
    const b = stripDiacritics(w.toLowerCase());
    return b.includes('γγ');
  }

  function scoreGuess(word){
    const raw = word;
    const w = strip.checked ? stripDiacritics(raw) : raw;
    const base = stripDiacritics(w.toLowerCase());

    let ante=0.5, ult=0.5;
    const flags=[];

    if(!endsWithGos(w)){
      flags.push({t:'Not -γος', cls:'warn'});
      // still do something: accent ultima by default
      return {ante:0.35, ult:0.65, target:'ultima', flags, reason:'This toy is tuned for words ending in -γος; defaulting to ultima.'};
    }

    const sylls = syllabifyToy(stripDiacritics(w.toLowerCase()));
    const n = sylls.length;

    if(base==='ολιγος'){
      flags.push({t:'Oddball: ὀλίγος', cls:'good'});
      return {ante:0.9, ult:0.1, target:'antepenult', flags, reason:'Herodian calls ὀλίγος “μονῆρες” and antepenult-accented.'};
    }

    if(hasDoubleGamma(w)){
      flags.push({t:'Has γγ', cls:'warn'});
      ante += 0.05; ult += 0.05;
    }

    if(n>=3){
      const pen = penultNucleus(sylls);
      const longish = isLongishPenult(pen);
      if(longish){
        ult += 0.35;
        flags.push({t:'Penult looks long-ish', cls:'good'});
      } else {
        ante += 0.35;
        flags.push({t:'Penult looks short-ish', cls:'good'});
      }

      if(n===3){
        flags.push({t:'Trisyllable', cls:'badge'});
      } else {
        flags.push({t:'Polysyllable', cls:'badge'});
      }
    } else {
      // disyllables in -γος are not the focus here
      flags.push({t:'Only 2 syllables (toy)', cls:'warn'});
      ult += 0.15;
    }

    // normalize
    const sum = ante+ult;
    ante/=sum; ult/=sum;
    const target = (ult>ante) ? 'ultima' : 'antepenult';

    let reason = '';
    if(target==='antepenult'){
      reason = 'Guessing προπαροξύτονον: polysyllabic -γος often does this when the penult is short (e.g. πάταγος, ἔλεγος).';
    } else {
      reason = 'Guessing ὀξύτονον: trisyllabic masculine -γος often does this when the penult is long (e.g. πελαργός, ἀρηγός).';
    }
    if(hasDoubleGamma(w)) reason += ' (But γγ is a warning sign in Herodian.)';

    return {ante, ult, target, flags, reason, sylls};
  }

  function render(){
    const raw = normalizeGreek(inp.value);
    if(!raw){
      outWord.textContent = '—';
      outSyll.textContent = '';
      outWhy.textContent = 'Type a word ending in -γος to see a guess.';
      barAnte.style.width = '50%';
      barUlt.style.width = '50%';
      return;
    }

    const cleaned = strip.checked ? stripDiacritics(raw) : raw;
    const g = scoreGuess(cleaned);

    const accented = accentWordToy(stripDiacritics(cleaned.toLowerCase()), g.target);

    outWord.innerHTML = escapeHtml(accented.word);

    if(showSyll.checked){
      const sylls = accented.sylls || syllabifyToy(stripDiacritics(cleaned.toLowerCase()));
      outSyll.innerHTML = 'syllables (toy): ' + sylls.map(escapeHtml).join(' · ');
    } else {
      outSyll.textContent = '';
    }

    barAnte.style.width = Math.round(g.ante*100) + '%';
    barUlt.style.width = Math.round(g.ult*100) + '%';

    const flagHtml = (g.flags||[]).map(f=>{
      const cls = f.cls && f.cls!=='badge' ? 'badge ' + f.cls : 'badge';
      return '<span class="'+cls+'">'+escapeHtml(f.t)+'</span>';
    }).join(' ');

    outWhy.innerHTML = flagHtml + (flagHtml ? '<br>' : '') + escapeHtml(g.reason || '');
  }

  function escapeHtml(s){
    return (s+'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  $('#btnGuess').addEventListener('click', render);
  $('#btnClear').addEventListener('click', ()=>{inp.value=''; inp.focus(); render();});
  $('#btnRandom').addEventListener('click', ()=>{
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inp.value = ex.w;
    render();
    outWhy.innerHTML = '<span class="badge">Example</span> ' + escapeHtml(ex.note) + '<br>' + outWhy.innerHTML;
  });

  inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter'){ render(); }});
  inp.addEventListener('input', ()=>{ render(); });
  strip.addEventListener('change', render);
  showSyll.addEventListener('change', render);

  // seed
  inp.value = 'παταγος';
  render();
})();

