(() => {
  const $ = (sel, el=document) => el.querySelector(sel);
  const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

  const inp = $('#inp');
  const accentedEl = $('#accented');
  const whyEl = $('#why');
  const toneEl = $('#tone');
  const btn = $('#btn');
  const btnClear = $('#btnClear');
  const quizEl = $('#quiz');

  // --- Greek helpers (very small + heuristic) ---
  const combining = /[\u0300-\u036f]/g;
  const stripCombining = s => s.normalize('NFD').replace(combining,'').normalize('NFC');

  const finalSigma = s => s.replace(/σ\b/g, 'ς');

  // Rough syllable count: count vowel nuclei (incl. common diphthongs)
  const vowels = 'αεηιουω';
  const isVowel = ch => vowels.includes(ch);

  function normalizeGreek(s){
    if(!s) return '';
    s = s.trim();
    // lower-case, strip punctuation-ish
    s = s.toLowerCase();
    s = s.replace(/[··.,;:!?()\[\]{}"'«»<>]/g,'');
    s = stripCombining(s);
    s = finalSigma(s);
    return s;
  }

  function countNuclei(word){
    // treat αι, ει, οι, υι, αυ, ευ, ου, ηυ as one nucleus
    const w = word;
    let i=0, n=0;
    while(i < w.length){
      const a = w[i];
      const b = w[i+1] || '';
      if(isVowel(a)){
        const pair = a+b;
        if(['αι','ει','οι','υι','αυ','ευ','ου','ηυ'].includes(pair)) i += 2;
        else i += 1;
        n++;
      } else {
        i++;
      }
    }
    return n;
  }

  function penultNucleus(word){
    // return the vowel nucleus (string) of the penult syllable, if disyllabic-ish
    // We scan nuclei left->right and take the second-to-last nucleus.
    const nuclei = [];
    let i=0;
    while(i < word.length){
      const a = word[i];
      const b = word[i+1] || '';
      if(isVowel(a)){
        const pair = a+b;
        if(['αι','ει','οι','υι','αυ','ευ','ου','ηυ'].includes(pair)){
          nuclei.push(pair);
          i += 2;
        } else {
          nuclei.push(a);
          i += 1;
        }
      } else i++;
    }
    if(nuclei.length < 2) return null;
    return nuclei[nuclei.length-2];
  }

  function hasConsonantBeforeDelta(word){
    // checks ...Cδος vs ...Vδος
    // find the last occurrence of 'δος' ending
    if(!word.endsWith('δος')) return null;
    const idx = word.length - 3; // position of δ
    const prev = word[idx-1];
    if(!prev) return null;
    return !isVowel(prev);
  }

  function applyAccent(word, accent){
    // accent: 'oxytone' (acute on ultima) or 'paroxytone' (acute on penult)
    // We add combining acute U+0301 to the vowel nucleus of the target syllable.
    // Very heuristic: place on first vowel of the nucleus.
    const wNFD = word.normalize('NFD');
    // map indices in NFC-ish string is hard; instead operate on stripped NFC word.
    const w = word; // already stripped

    const nucleiPos = [];
    let i=0;
    while(i < w.length){
      const a = w[i];
      const b = w[i+1] || '';
      if(isVowel(a)){
        const pair = a+b;
        if(['αι','ει','οι','υι','αυ','ευ','ου','ηυ'].includes(pair)){
          nucleiPos.push({start:i, len:2});
          i += 2;
        } else {
          nucleiPos.push({start:i, len:1});
          i += 1;
        }
      } else i++;
    }
    if(nucleiPos.length === 0) return word;

    let target;
    if(accent === 'oxytone') target = nucleiPos[nucleiPos.length-1];
    else if(accent === 'paroxytone') target = nucleiPos[Math.max(0, nucleiPos.length-2)];
    else target = nucleiPos[nucleiPos.length-1];

    const pos = target.start;
    // insert combining acute after the first vowel char of the nucleus
    const before = w.slice(0, pos+1);
    const after = w.slice(pos+1);
    const out = (before + '\u0301' + after).normalize('NFC');
    return out;
  }

  function guessAccent(word, opts){
    // opts: kind, cluster
    const w = normalizeGreek(word);
    if(!w) return {ok:false, msg:'Type a Greek word.'};

    const ends = w.endsWith('δος');
    const nuclei = countNuclei(w);
    const disyll = nuclei === 2;

    const kind = opts.kind;
    const clusterOpt = opts.cluster;

    // Determine cluster before δ
    let cluster;
    if(clusterOpt === 'auto'){
      const c = hasConsonantBeforeDelta(w);
      cluster = (c === null) ? null : (c ? 'cluster' : 'simple');
    } else cluster = clusterOpt;

    const pen = penultNucleus(w);

    // Rule toy:
    // A) Disyllabic -δος with penult o/ou/oi/ē and NOT compound/ethnic => oxytone.
    // B) If consonant before δ (e.g. -νδος, -ρδος, -λδος) => barytone tendency (we model as paroxytone).
    // C) Ethnics/compounds often behave differently; we nudge to paroxytone.
    // D) Special-cased examples: Ῥόδος paroxytone; ὁδός/σποδός/οὐδός oxytone.

    const lex = {
      'οδος': {accent:'oxytone', note:'Herodian cites ὁδός as oxytone.'},
      'σποδος': {accent:'oxytone', note:'Herodian cites σποδός as oxytone.'},
      'ουδος': {accent:'oxytone', note:'Herodian cites οὐδός as oxytone.'},
      'ροδος': {accent:'paroxytone', note:'Herodian notes Ῥόδος as paroxytone.'},
      'μηδος': {accent:'paroxytone', note:'Herodian treats Μῆδος as ethnic/name; we model as paroxytone.'},
      'λινδος': {accent:'paroxytone', note:'Herodian lists Λίνδος among barytone tendencies; we model as paroxytone.'},
      'μυνδος': {accent:'paroxytone', note:'Herodian mentions Μύνδος; cluster before δ suggests paroxytone.'},
      'ινδος': {accent:'paroxytone', note:'Herodian notes Ἰνδός; cluster before δ suggests paroxytone.'}
    };

    if(lex[w]){
      const acc = lex[w].accent;
      return {
        ok:true,
        normalized:w,
        accent:acc,
        accented:applyAccent(w, acc),
        why:lex[w].note,
        meta:{ends, disyll, nuclei, pen, cluster, kind:'lexicon override'}
      };
    }

    if(!ends){
      return {
        ok:true,
        normalized:w,
        accent:null,
        accented:w,
        why:"This toy is tuned for words ending in -δος. I’ll leave your word unchanged (but you can still use it as a sandbox).",
        meta:{ends, disyll, nuclei, pen, cluster, kind}
      };
    }

    // Decide accent
    let accent = 'paroxytone';
    const reasons = [];

    if(disyll) reasons.push('disyllabic');
    else reasons.push(`~${nuclei} syllable-nuclei (heuristic)`);

    if(cluster === 'cluster'){
      accent = 'paroxytone';
      reasons.push('consonant+δ cluster → barytone tendency');
    } else if(cluster === 'simple'){
      reasons.push('simple vowel+δ');
    }

    const penOk = pen && (pen === 'ο' || pen === 'ου' || pen === 'οι' || pen === 'η');
    if(pen) reasons.push(`penult nucleus ≈ “${pen}”`);

    const kindEff = (kind === 'auto') ? 'auto' : kind;

    if(kindEff === 'compound' || kindEff === 'ethnic'){
      accent = 'paroxytone';
      reasons.push(`${kindEff} → allow non-oxytone behavior`);
    } else if(kindEff === 'adjective'){
      // Herodian: some -νδος etc. may be acute if adjectival; we let adjective override cluster.
      if(cluster === 'cluster'){
        accent = 'oxytone';
        reasons.push('adjective override → allow oxytone');
      }
    } else {
      // appellative/auto
      if(disyll && cluster !== 'cluster' && penOk){
        accent = 'oxytone';
        reasons.push('Herodian-style rule: disyllabic -δος with penult o/ou/oi/ē (not compound/ethnic) → oxytone');
      }
    }

    const accented = applyAccent(w, accent);
    return {
      ok:true,
      normalized:w,
      accent,
      accented,
      why: reasons.join('; ') + '.',
      meta:{ends, disyll, nuclei, pen, cluster, kind:kindEff}
    };
  }

  function currentOpts(){
    const kind = ($$('input[name="kind"]').find(r=>r.checked) || {}).value || 'auto';
    const cluster = ($$('input[name="cluster"]').find(r=>r.checked) || {}).value || 'auto';
    return {kind, cluster};
  }

  function render(result){
    if(!result.ok){
      accentedEl.textContent = '—';
      toneEl.textContent = result.msg || '—';
      whyEl.textContent = '';
      return;
    }
    accentedEl.textContent = result.accented || result.normalized;

    let tone = '—';
    if(result.accent === 'oxytone') tone = 'Toy guess: acute on the last syllable (oxytone).';
    else if(result.accent === 'paroxytone') tone = 'Toy guess: acute on the penult (paroxytone / “barytone tendency”).';
    else tone = 'No accent guess (outside -δος focus).';

    toneEl.textContent = tone;
    whyEl.textContent = result.why;
  }

  function run(){
    const res = guessAccent(inp.value, currentOpts());
    render(res);
  }

  btn.addEventListener('click', run);
  inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') run(); });
  btnClear.addEventListener('click', ()=>{ inp.value=''; inp.focus(); render({ok:true, normalized:'', accented:'—', accent:null, why:'Enter a word ending in -δος to begin.'}); });

  // --- Quiz cards ---
  const quizItems = [
    {w:'οδος', tag:'appellative'},
    {w:'σποδος', tag:'appellative'},
    {w:'ουδος', tag:'appellative'},
    {w:'ροδος', tag:'place-name'},
    {w:'λινδος', tag:'-νδος cluster'},
    {w:'σαρδος', tag:'-ρδος cluster'},
    {w:'μηδος', tag:'ethnic/name'},
    {w:'μυνδος', tag:'-νδος cluster'}
  ];

  function makeCard(item){
    const d = document.createElement('div');
    d.className = 'qcard';
    d.tabIndex = 0;
    d.setAttribute('role','button');
    d.setAttribute('aria-label', `Quiz card ${item.w}`);

    d.innerHTML = `
      <div class="qtop">
        <div class="qword greek">${item.w}</div>
        <div class="qtag">${item.tag}</div>
      </div>
      <div class="qans">Click to reveal</div>
    `;

    const reveal = () => {
      const res = guessAccent(item.w, {kind:'auto', cluster:'auto'});
      const ans = d.querySelector('.qans');
      ans.innerHTML = `Toy: <b class="greek">${res.accented}</b> <span class="code">(${res.accent || '—'})</span>`;
    };

    d.addEventListener('click', reveal);
    d.addEventListener('keydown', (e)=>{ if(e.key==='Enter' || e.key===' ') { e.preventDefault(); reveal(); } });
    return d;
  }

  quizItems.forEach(it => quizEl.appendChild(makeCard(it)));

  // initial
  render({ok:true, normalized:'', accented:'—', accent:null, why:'Enter a word ending in -δος to begin.'});
})();

