const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const btn = $('#btn');
const btnRnd = $('#btnRnd');
const keep = $('#keep');
const strip = $('#strip');

const suggestEl = $('#suggest');
const ruleEl = $('#rule');
const sketchEl = $('#sketch');
const notesEl = $('#notes');

const examples = [
  'ομαδος', 'κελαδος', 'Αραδος', 'Τενεδος', 'Λεβεδος', 'Καπεδος', 'Ναγιδος',
  'μολυβδος', 'σμαραγδος', 'Ασπενδος', 'Βενεβενδος', 'Ισινδος', 'Πυρινδος', 'Αλινδος',
  'Αβυδος', 'Ενουδος', 'Ισσηδος', 'Οροιδος',
  'Τοπαζος', 'Γαζος', 'Αραζος', 'Βυμαζος',
  'κορυδος'
];

// --- Greek helpers ---
const combining = {
  acute: '\u0301',
  grave: '\u0300',
  circumflex: '\u0342',
  diaeresis: '\u0308',
  smooth: '\u0313',
  rough: '\u0314',
  iotaSub: '\u0345'
};

const ACCENT_MARKS = new Set([combining.acute, combining.grave, combining.circumflex]);

function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripAccentMarks(s){
  // remove only accent marks (keep breathings/diaeresis/iota sub)
  return nfc(nfd(s).split('').filter(ch => !ACCENT_MARKS.has(ch)).join(''));
}

function hasAccent(s){
  const d = nfd(s);
  for (const ch of d) if (ACCENT_MARKS.has(ch)) return true;
  return false;
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code >= 0x0370 && code <= 0x03FF) || (code >= 0x1F00 && code <= 0x1FFF);
}

function onlyGreekish(s){
  // keep Greek letters, spaces, apostrophes, hyphen
  return s.split('').filter(ch => isGreekLetter(ch) || /[\s\-’'·.]/.test(ch)).join('');
}

function baseChar(ch){
  // remove combining marks from a single char
  return nfc(nfd(ch).replace(/[\u0300-\u036f]/g,''));
}

const VOWELS = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

function isVowelChar(ch){
  const b = baseChar(ch);
  return VOWELS.has(b);
}

function isDiphthong(v1, v2){
  const a = baseChar(v1);
  const b = baseChar(v2);
  const pair = a + b;
  const dips = new Set(['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ΑΙ','ΕΙ','ΟΙ','ΥΙ','ΑΥ','ΕΥ','ΟΥ','ΗΥ']);
  return dips.has(pair);
}

function tokenizeLetters(s){
  // split into user-perceived letters (base+combining)
  const d = nfd(s);
  const out = [];
  let buf = '';
  for (const ch of d){
    if (/\p{M}/u.test(ch)){
      buf += ch;
    } else {
      if (buf) out.push(nfc(buf));
      buf = ch;
    }
  }
  if (buf) out.push(nfc(buf));
  return out;
}

function vowelNuclei(word){
  // returns array of nuclei objects: {start,end, text}
  const letters = tokenizeLetters(word);
  const nuclei = [];
  let i = 0;
  while (i < letters.length){
    if (isVowelChar(letters[i])){
      // try diphthong
      if (i+1 < letters.length && isVowelChar(letters[i+1]) && isDiphthong(letters[i], letters[i+1])){
        nuclei.push({start:i, end:i+1, text: letters[i] + letters[i+1]});
        i += 2;
        continue;
      }
      nuclei.push({start:i, end:i, text: letters[i]});
    }
    i++;
  }
  return {letters, nuclei};
}

function syllableCount(word){
  return vowelNuclei(word).nuclei.length;
}

function penultNucleus(word){
  const {nuclei} = vowelNuclei(word);
  if (nuclei.length < 2) return null;
  return nuclei[nuclei.length - 2];
}

function antepenultNucleus(word){
  const {nuclei} = vowelNuclei(word);
  if (nuclei.length < 3) return null;
  return nuclei[nuclei.length - 3];
}

function nucleusIsLongByNature(nucleus){
  if (!nucleus) return false;
  const t = nucleus.text;
  // heuristic: η/ω long; diphthongs long
  const b0 = baseChar(t[0]);
  if (t.length >= 2) return true; // diphthong nucleus
  return (b0 === 'η' || b0 === 'ω' || b0 === 'Η' || b0 === 'Ω');
}

function hasPenultCluster(word){
  // heuristic: between antepenult nucleus end and penult nucleus start, do we see 2+ consonant letters?
  const {letters, nuclei} = vowelNuclei(word);
  if (nuclei.length < 2) return false;
  const pen = nuclei[nuclei.length - 2];
  const prev = nuclei[nuclei.length - 3] || null;
  // cluster at start of penult syllable: look at letters immediately before penult nucleus
  // count consecutive consonant letters right before penult nucleus
  let i = pen.start - 1;
  let count = 0;
  while (i >= 0){
    const ch = letters[i];
    if (!isGreekLetter(baseChar(ch))) break;
    if (isVowelChar(ch)) break;
    // treat ρ/λ/μ/ν etc as consonants too
    count++;
    i--;
  }
  // If there are 2+ consonants immediately before the penult vowel nucleus, call it a cluster.
  // This is crude but catches -λβ-, -ργδ-, -σπεν- etc.
  return count >= 2;
}

function endsWithNormalized(word, ending){
  const w = stripAccentMarks(word);
  return w.endsWith(ending) || w.endsWith(ending.toUpperCase());
}

function applyAcuteOnNucleus(word, nucleusIndexFromEnd){
  // nucleusIndexFromEnd: 1=ultima, 2=penult, 3=antepenult
  const {letters, nuclei} = vowelNuclei(word);
  if (nuclei.length < nucleusIndexFromEnd) return word;
  const target = nuclei[nuclei.length - nucleusIndexFromEnd];
  // place acute on first vowel letter of nucleus
  const idx = target.start;
  const d = nfd(letters[idx]);
  // if already has some accent mark, keep it
  if ([...d].some(ch => ACCENT_MARKS.has(ch))) return word;
  letters[idx] = nfc(d + combining.acute);
  return letters.join('');
}

function syllableSketch(word){
  const {letters, nuclei} = vowelNuclei(word);
  if (!nuclei.length) return {sketch:'(no vowels found)', detail:''};
  // Build a simple sketch: C/V groups with nuclei marked
  let out = '';
  let n = 0;
  for (let i=0;i<letters.length;i++){
    const ch = letters[i];
    if (n < nuclei.length && i === nuclei[n].start){
      out += '[' + nuclei[n].text + ']';
      i = nuclei[n].end;
      n++;
    } else {
      const b = baseChar(ch);
      if (!isGreekLetter(b)) { out += b; continue; }
      out += isVowelChar(ch) ? 'V' : 'C';
    }
  }
  const pen = nuclei.length>=2 ? nuclei[nuclei.length-2].text : null;
  const ant = nuclei.length>=3 ? nuclei[nuclei.length-3].text : null;
  const ult = nuclei[nuclei.length-1].text;
  const detail = `nuclei: ${nuclei.map(x=>x.text).join(' · ')}${pen?` | penult=${pen}`:''}${ant?` | antepenult=${ant}`:''} | ultima=${ult}`;
  return {sketch: out, detail};
}

function decideAccent(word){
  const clean = word.trim();
  const sc = syllableCount(clean);

  const isZos = endsWithNormalized(clean, 'ζος');
  const isDos = endsWithNormalized(clean, 'δος');

  if (isZos){
    return {
      target: 2,
      label: 'Rule: -ζος → penult accent (βαρύνεται / παροξύτονον)'
    };
  }

  if (isDos && sc >= 3){
    const pen = penultNucleus(clean);
    const longNat = nucleusIsLongByNature(pen);
    const cluster = hasPenultCluster(clean);

    if (cluster){
      return {
        target: 2,
        label: 'Rule: -δος with consonant “combination/cluster” → penult accent (βαρύνεται)'
      };
    }

    if (longNat){
      return {
        target: 3,
        label: 'Rule (toy): penult long by nature → antepenult accent (προπαροξύτονον)'
      };
    }

    return {
      target: 3,
      label: 'Rule: -δος (3+ syllables) with short penult → antepenult accent (προπαροξύτονον)'
    };
  }

  // fallback: if 2 syllables, suggest penult (common default)
  if (sc === 2){
    return { target: 2, label: 'Fallback: 2 syllables → suggest penult accent' };
  }

  return { target: 1, label: 'Fallback: could not apply Herodian’s -δος/-ζος rules → leave as is / accent ultima' };
}

function process(){
  let s = onlyGreekish(inp.value || '');
  if (!s.trim()){
    suggestEl.textContent = '—';
    ruleEl.textContent = 'Type a Greek word ending in -δος or -ζος.';
    sketchEl.textContent = '—';
    notesEl.textContent = '—';
    return;
  }

  // operate on first token-like word (but keep full string for display)
  // If phrase, we accent the last Greek word.
  const parts = s.split(/(\s+)/);
  let lastWordIdx = -1;
  for (let i=0;i<parts.length;i++){
    if (parts[i].trim() && /[\u0370-\u03FF\u1F00-\u1FFF]/.test(parts[i])) lastWordIdx = i;
  }
  if (lastWordIdx === -1) lastWordIdx = 0;

  let w = parts[lastWordIdx];
  const had = hasAccent(w);

  if (strip.checked) w = stripAccentMarks(w);

  const decision = decideAccent(w);

  let outWord = w;
  if (!(keep.checked && had && !strip.checked)){
    // If keep is on and word already had accent and we didn't strip, do nothing.
    // Otherwise, add acute according to decision.
    outWord = applyAcuteOnNucleus(w, decision.target);
  }

  parts[lastWordIdx] = outWord;
  const full = parts.join('');

  const {sketch, detail} = syllableSketch(outWord);

  suggestEl.textContent = full;
  ruleEl.textContent = decision.label;
  sketchEl.textContent = sketch;

  const sc = syllableCount(outWord);
  const pen = penultNucleus(outWord);
  const ant = antepenultNucleus(outWord);
  const cluster = hasPenultCluster(outWord);
  const longNat = nucleusIsLongByNature(pen);

  const bits = [];
  bits.push(`syllables≈${sc}`);
  if (pen) bits.push(`penult nucleus=${pen.text}${longNat?' (long?)':' (short?)'}`);
  if (ant) bits.push(`antepenult nucleus=${ant.text}`);
  bits.push(`cluster-before-penult=${cluster?'yes':'no'}`);
  bits.push(detail);
  notesEl.textContent = bits.join(' · ');
}

btn.addEventListener('click', process);
inp.addEventListener('keydown', (e)=>{ if (e.key === 'Enter') process(); });

btnRnd.addEventListener('click', ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  inp.value = ex;
  process();
});

// checkbox logic: strip overrides keep in a sensible way
strip.addEventListener('change', ()=>{
  if (strip.checked) keep.checked = false;
});
keep.addEventListener('change', ()=>{
  if (keep.checked) strip.checked = false;
});

// initial
inp.value = 'ομαδος';
process();

