const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const outWord = $('#outWord');
const rule = $('#rule');
const chips = $('#chips');

const examples = [
  {g:'μυθος', label:'μυθος → μῦθος (-θος penult)'} ,
  {g:'Ζηθος', label:'Ζηθος → Ζῆθος (-θος penult)'} ,
  {g:'Ξουθος', label:'Ξουθος → Ξοῦθος (-θος penult)'} ,
  {g:'στρουθος', label:'στρουθος → στρουθός (exception)'} ,
  {g:'πεζος', label:'πεζος → πεζός (-ζός)'} ,
  {g:'χθιζος', label:'χθιζος → χθιζός (-ζός)'} ,
  {g:'πρωιζος', label:'πρωιζος → πρωϊζός (-ζός)'} ,
  {g:'πτορθος', label:'πτορθος → πτόρθος (-θος penult)'} ,
  {g:'γονθος', label:'γονθος → γόνθος (-θος penult)'}
];

for (const ex of examples){
  const b = document.createElement('button');
  b.className = 'chip';
  b.type = 'button';
  b.textContent = ex.label;
  b.addEventListener('click', () => { inp.value = ex.g; run(); inp.focus(); });
  chips.appendChild(b);
}

// --- Greek helpers ---
// Strip combining marks (accents, breathings, iota subscript, diaeresis, etc.)
function stripDiacritics(s){
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code >= 0x0370 && code <= 0x03FF) || (code >= 0x1F00 && code <= 0x1FFF);
}

function tokenizeWords(s){
  // keep Greek sequences; everything else as separators
  const out = [];
  let cur = '';
  let curIsGreek = null;
  for (const ch of s){
    const g = isGreekLetter(ch);
    if (curIsGreek === null){ curIsGreek = g; cur = ch; continue; }
    if (g === curIsGreek){ cur += ch; }
    else { out.push({text:cur, greek:curIsGreek}); cur = ch; curIsGreek = g; }
  }
  if (cur) out.push({text:cur, greek:curIsGreek});
  return out;
}

const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

function isVowel(ch){ return vowels.has(ch); }

function findVowelIndices(word){
  // indices in code units (safe enough for Greek BMP)
  const idx = [];
  for (let i=0;i<word.length;i++) if (isVowel(word[i])) idx.push(i);
  return idx;
}

function looksLongVowelAt(word, i){
  // crude: ω/η long; diphthongs: αι ει οι υι αυ ευ ου ηυ
  const ch = word[i];
  if (ch === 'ω' || ch === 'Ω' || ch === 'η' || ch === 'Η') return true;
  const next = word[i+1] || '';
  const pair = (ch+next).toLowerCase();
  return ['αι','ει','οι','υι','αυ','ευ','ου','ηυ'].includes(pair);
}

function addAccentToVowel(word, vowelIndex, kind){
  // kind: 'acute' | 'circ'
  const base = stripDiacritics(word);
  const ch = base[vowelIndex];
  if (!ch) return base;
  const mark = kind === 'circ' ? '\u0342' : '\u0301';
  // Put combining mark after the vowel
  const out = base.slice(0, vowelIndex+1) + mark + base.slice(vowelIndex+1);
  return out.normalize('NFC');
}

function accentWordHeuristic(raw){
  const w0 = raw.trim();
  if (!w0) return {word:'', why:'Type something Greek.'};

  const w = stripDiacritics(w0);
  const lower = w.toLowerCase();

  // Exception list (very small, just for fun)
  if (lower === 'στρουθος'){
    const v = findVowelIndices(w);
    const lastV = v[v.length-1];
    return {
      word: addAccentToVowel(w, lastV, 'acute'),
      why: 'Exception: στρουθός is marked as “σημειῶδες” (acute on ultima).'
    };
  }

  // -ζος: accent ultima acute
  if (lower.endsWith('ζος')){
    const v = findVowelIndices(w);
    const lastV = v[v.length-1];
    return {
      word: addAccentToVowel(w, lastV, 'acute'),
      why: 'Adverbial-looking -ζός: show acute on the last syllable (πεζός, χθιζός, πρωϊζός).'
    };
  }

  // -θος: if disyllabic-ish, accent penult; choose circumflex if penult looks long
  if (lower.endsWith('θος')){
    const v = findVowelIndices(w);
    if (v.length >= 2){
      const penultV = v[v.length-2];
      const kind = looksLongVowelAt(w, penultV) ? 'circ' : 'acute';
      return {
        word: addAccentToVowel(w, penultV, kind),
        why: `-θος pattern: accent the penult; ${kind==='circ'?'penult looks long → circumflex':'penult looks short → acute'} (toy heuristic).`
      };
    }
  }

  // fallback: accent penult if possible, else ultima
  const v = findVowelIndices(w);
  if (v.length === 0) return {word:w, why:'No vowels found to accent.'};
  const target = v.length >= 2 ? v[v.length-2] : v[v.length-1];
  return {
    word: addAccentToVowel(w, target, 'acute'),
    why: 'Fallback: acute on penult (or ultima if only one vowel).'
  };
}

function run(force=null){
  const s = inp.value;
  const parts = tokenizeWords(s);

  let why = '';
  const outParts = parts.map(p => {
    if (!p.greek) return p.text;
    const raw = p.text;
    const base = stripDiacritics(raw);
    const v = findVowelIndices(base);

    if (force){
      if (v.length === 0) return base;
      let idx;
      if (force === 'ultima') idx = v[v.length-1];
      else if (force === 'penult') idx = v[Math.max(0, v.length-2)];
      else idx = v[Math.max(0, v.length-3)];
      why = `Forced mode: acute on ${force}.`;
      return addAccentToVowel(base, idx, 'acute');
    }

    const res = accentWordHeuristic(raw);
    why = res.why;
    return res.word;
  });

  const out = outParts.join('');
  outWord.textContent = out || '—';
  rule.textContent = why || '—';
}

$('#btn').addEventListener('click', () => run());
inp.addEventListener('keydown', (e) => { if (e.key === 'Enter') run(); });
$('#clear').addEventListener('click', () => { inp.value=''; outWord.textContent='—'; rule.textContent='—'; inp.focus(); });

document.addEventListener('click', (e) => {
  const b = e.target.closest('button[data-force]');
  if (!b) return;
  run(b.getAttribute('data-force'));
});

// seed
inp.value = 'μυθος';
run();

