(() => {
  const $ = (sel, el=document) => el.querySelector(sel);
  const inp = $('#inp');
  const btnAnalyze = $('#btnAnalyze');
  const btnRandom = $('#btnRandom');
  const chkAdj = $('#chkAdj');
  const chkForce = $('#chkForce');

  const normEl = $('#norm');
  const syllEl = $('#syll');
  const trigEl = $('#trig');
  const suggestEl = $('#suggest');
  const noteEl = $('#note');
  const chipsEl = $('#chips');

  // Examples from the passage (mix of accented/unaccented)
  const EX = [
    'Λάπιθος','λέκιθος','ἔριθος','Μίκυθος','ἄκυθος','μαμμάκυθος','Αἴνηθος','Λάπηθος','Πεπάρηθος','Σεσάρηθος',
    'Κάνηθος','Ὄρηθος','Σέβηθος','ἐπίληθος','Ναύαιθος','Φάρβαιθος','Κέλαιθος','Δάμαιθος','Κύναιθος','Ὀλίγαιθος','Σίμαιθος','Ἀρίαιθος',
    'βοηθός','κακηθός',
    'Ἐρύμανθος','Ἄκανθος','Φάλανθος','Πύρανθος','Ψίναφθος','Μέλανθος','Λαβύρινθος','Ὑάκυνθος','Λέβινθος','Προβάλινθος'
  ];

  // --- Greek helpers ---
  const COMBINING = /[\u0300-\u036f]/g; // includes tonos/oxia etc.

  function stripDiacritics(s){
    return s.normalize('NFD').replace(COMBINING,'').normalize('NFC');
  }

  function normalizeGreek(s){
    return (s||'').trim().replace(/\s+/g,' ');
  }

  function endsWithThos(base){
    // base should be diacritic-stripped
    return /θος$/i.test(base);
  }

  const VOW = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ','ϊ','ϋ','ΐ','ΰ','Α','Ε','Η','Ι','Ο','Υ','Ω','Ά','Έ','Ή','Ί','Ό','Ύ','Ώ','Ϊ','Ϋ']);

  function isVowel(ch){
    return VOW.has(ch);
  }

  function syllabifyRough(word){
    // Rough syllables by vowel-grouping on diacritic-stripped lowercase.
    const w = stripDiacritics(word).toLowerCase();
    const groups = [];
    let cur = '';
    let inV = false;
    for (let i=0;i<w.length;i++){
      const ch = w[i];
      const v = isVowel(ch);
      if (v){
        if (!inV && cur){ groups.push(cur); cur=''; }
        inV = true;
        cur += ch;
      } else {
        if (inV && cur){ groups.push(cur); cur=''; }
        inV = false;
        cur += ch;
      }
    }
    if (cur) groups.push(cur);

    // Now merge into syllables: each syllable = onset+vowel nucleus+following consonants until next vowel nucleus begins.
    // We'll do a simpler pass: split into vowel nuclei and attach preceding consonants.
    const syll = [];
    let buf = '';
    let seenV = false;
    for (let i=0;i<w.length;i++){
      const ch = w[i];
      if (isVowel(ch)){
        if (seenV){
          // new vowel starts a new syllable
          syll.push(buf);
          buf = ch;
        } else {
          buf += ch;
          seenV = true;
        }
      } else {
        buf += ch;
      }
    }
    if (buf) syll.push(buf);

    // Ensure at least 1
    return syll.filter(x=>x.length>0);
  }

  function vowelNucleus(syl){
    // return first vowel char index in syllable and the vowel string (incl. diphthong guess)
    const s = syl;
    let idx = -1;
    for (let i=0;i<s.length;i++){
      if (isVowel(s[i])) { idx = i; break; }
    }
    if (idx === -1) return {idx:-1, nuc:''};
    // diphthong-ish: check next char
    let nuc = s[idx];
    if (idx+1 < s.length && isVowel(s[idx+1])){
      nuc += s[idx+1];
    }
    return {idx, nuc};
  }

  function penultInfo(word){
    const syll = syllabifyRough(word);
    if (syll.length < 2) return null;
    const pen = syll[syll.length-2];
    const {nuc} = vowelNucleus(pen);
    const penStr = pen;
    return {syll, pen, nuc, penStr};
  }

  function hasIotaOrUpsilonInPenult(nuc){
    return /[ιυ]/.test(nuc);
  }

  function looksLongByNature(nuc){
    // toy heuristic: eta/omega or common diphthongs
    return /(η|ω|ει|ου|αι|οι|αυ|ευ|ηυ|υι)/.test(nuc);
  }

  function penultHasTwoConsonants(word){
    // Look at the penult syllable's coda+onset cluster: simplest: in the penult syllable string, count consecutive consonants after the vowel nucleus.
    const info = penultInfo(word);
    if (!info) return false;
    const pen = stripDiacritics(info.pen).toLowerCase();
    const {idx, nuc} = vowelNucleus(pen);
    if (idx === -1) return false;
    const after = pen.slice(idx + nuc.length);
    // count consonant letters (ignore apostrophes etc.)
    const cons = after.replace(/[^βγδζθκλμνξπρσςτφχψ]/g,'');
    return cons.length >= 2;
  }

  function removeExistingAccent(word){
    // remove tonos/oxia and other combining marks; keep base letters
    return stripDiacritics(word);
  }

  function placeOxiaOnVowel(word, syllIndexFromEnd){
    // syllIndexFromEnd: 1=ultima,2=penult,3=antepenult
    // We place combining acute (U+0301) on the first vowel of the target syllable in the original word (diacritics stripped if force).
    const base = word;
    const stripped = stripDiacritics(base);
    const syll = syllabifyRough(stripped);
    const targetIndex = syll.length - syllIndexFromEnd;
    if (targetIndex < 0 || targetIndex >= syll.length) return base;

    // Find start position of that syllable in stripped string by scanning syllables.
    let pos = 0;
    for (let i=0;i<syll.length;i++){
      const syl = syll[i];
      if (i === targetIndex){
        // find first vowel in this syllable
        for (let j=0;j<syl.length;j++){
          const ch = syl[j];
          if (isVowel(ch)){
            const abs = pos + j;
            const before = stripped.slice(0, abs+1);
            const after = stripped.slice(abs+1);
            // add combining acute to that vowel
            return (before + '\u0301' + after).normalize('NFC');
          }
        }
        return stripped;
      }
      pos += syl.length;
    }
    return stripped;
  }

  function analyze(){
    const raw = normalizeGreek(inp.value);
    if (!raw){
      normEl.textContent = '—';
      syllEl.textContent = '—';
      trigEl.textContent = '—';
      suggestEl.textContent = '—';
      noteEl.textContent = '';
      return;
    }

    const baseNoMarks = stripDiacritics(raw);
    const baseLower = baseNoMarks.toLowerCase();

    const syll = syllabifyRough(raw);
    const syllCount = syll.length;

    const info = penultInfo(raw);
    const penNuc = info ? info.nuc : '';

    const isThos = endsWithThos(baseLower);
    const over2 = syllCount > 2;
    const penHasIU = info ? hasIotaOrUpsilonInPenult(penNuc) : false;
    const penLong = info ? looksLongByNature(penNuc) : false;
    const pen2cons = penultHasTwoConsonants(raw);

    const adj = chkAdj.checked;

    // Decide accent target
    let target = null; // 1 ultima, 2 penult, 3 antepenult
    let why = [];

    if (!isThos){
      why.push('Not ending in -θος (toy rule won\'t apply).');
      // still allow accent play: default penult if possible
      target = (syllCount >= 2) ? 2 : 1;
    } else {
      if (adj){
        target = 2;
        why.push('Adjectival toggle: prefer penult accent (Herodian’s “if it’s oxytone/penult-accented, it’s adjectival”).');
      } else {
        // Herodian-ish triggers
        if (over2 && (penHasIU || penLong)){
          target = 3;
          why.push('>2 syllables + penult has ι/υ or “long by nature” → antepenult.');
        } else if (over2 && pen2cons){
          target = 3;
          why.push('>2 syllables + penult shows 2 consonants → antepenult.');
        } else {
          // fallback: many -θος are proparoxytone in examples; but keep conservative
          target = (syllCount >= 3) ? 3 : 2;
          why.push('Fallback: suggest antepenult if possible; otherwise penult.');
        }
      }
    }

    // Build output word
    const force = chkForce.checked;
    const baseForAccent = force ? removeExistingAccent(raw) : raw;
    const suggested = placeOxiaOnVowel(baseForAccent, target);

    // UI
    normEl.textContent = baseNoMarks;
    syllEl.textContent = syll.join(' · ') + `   (${syllCount})`;

    const tags = [];
    tags.push(`<span class="tag ${isThos?'good':'bad'}">ends -θος: ${isThos?'yes':'no'}</span>`);
    tags.push(`<span class="tag ${over2?'good':'neutral'}">>2 syll: ${over2?'yes':'no'}</span>`);
    if (info){
      tags.push(`<span class="tag ${penHasIU?'good':'neutral'}">penult nuc: ${penNuc||'—'} (ι/υ: ${penHasIU?'yes':'no'})</span>`);
      tags.push(`<span class="tag ${penLong?'good':'neutral'}">“long” look: ${penLong?'yes':'no'}</span>`);
      tags.push(`<span class="tag ${pen2cons?'good':'neutral'}">penult 2 cons: ${pen2cons?'yes':'no'}</span>`);
    }
    tags.push(`<span class="tag ${adj?'bad':'neutral'}">adjectival: ${adj?'yes':'no'}</span>`);
    trigEl.innerHTML = tags.join(' ');

    suggestEl.textContent = suggested;

    const label = (target===3?'antepenult (proparoxytone)': target===2?'penult (paroxytone)': 'ultima (oxytone)');
    noteEl.textContent = `Placed oxia on the ${label}. ${why.join(' ')}`;
  }

  function renderChips(){
    chipsEl.innerHTML = '';
    EX.slice(0, 24).forEach(w => {
      const b = document.createElement('button');
      b.className = 'chip';
      b.type = 'button';
      b.textContent = w;
      b.addEventListener('click', () => {
        inp.value = w;
        // auto-toggle adjectival for the two explicit exceptions
        const plain = stripDiacritics(w).toLowerCase();
        chkAdj.checked = (plain === 'βοηθος' || plain === 'κακηθος');
        analyze();
        inp.focus();
      });
      chipsEl.appendChild(b);
    });
  }

  function randomExample(){
    const w = EX[Math.floor(Math.random()*EX.length)];
    inp.value = w;
    const plain = stripDiacritics(w).toLowerCase();
    chkAdj.checked = (plain === 'βοηθος' || plain === 'κακηθος');
    analyze();
    inp.focus();
  }

  btnAnalyze.addEventListener('click', analyze);
  btnRandom.addEventListener('click', randomExample);
  inp.addEventListener('input', () => analyze());
  chkAdj.addEventListener('change', analyze);
  chkForce.addEventListener('change', analyze);

  renderChips();
  inp.value = 'Λάπιθος';
  analyze();
})();

