:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --panel2:#1d2140;
  --text:#e9ecff;
  --muted:#b7bce6;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --good:#86efac;
  --warn:#fbbf24;
  --bad:#fb7185;
  --line:rgba(255,255,255,.12);
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Noto Sans", "Liberation Sans", sans-serif;
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 700px at 20% 10%, #1a1f3f 0%, var(--bg) 55%); color:var(--text); font-family:var(--sans)}
.wrap{max-width:980px;margin:0 auto;padding:18px}
.hdr{display:flex;gap:14px;align-items:flex-start;justify-content:space-between;margin-bottom:14px}
.hdr h1{font-size:20px;margin:0 0 6px 0;letter-spacing:.2px}
.sub{margin:0;color:var(--muted);line-height:1.35;font-size:13px}
.panel{background:linear-gradient(180deg, rgba(255,255,255,.06), rgba(255,255,255,.03)); border:1px solid var(--line); border-radius:14px; padding:14px; margin:12px 0; box-shadow:0 10px 30px rgba(0,0,0,.25)}
.lbl{display:block;font-size:12px;color:var(--muted);margin-bottom:8px}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.inp{flex:1;min-width:260px; padding:12px 12px; border-radius:12px; border:1px solid var(--line); background:rgba(0,0,0,.25); color:var(--text); font-size:16px; outline:none}
.inp:focus{border-color:rgba(125,211,252,.55); box-shadow:0 0 0 3px rgba(125,211,252,.15)}
.btn{padding:10px 12px;border-radius:12px;border:1px solid rgba(125,211,252,.35); background:rgba(125,211,252,.12); color:var(--text); cursor:pointer; font-weight:650}
.btn:hover{background:rgba(125,211,252,.18)}
.btn:active{transform:translateY(1px)}
.btn.ghost{border-color:var(--line); background:rgba(255,255,255,.06); font-weight:600}
.btn.ghost:hover{background:rgba(255,255,255,.09)}
.help summary{cursor:pointer;color:var(--accent);font-weight:650}
.help ul{margin:10px 0 8px 18px;color:var(--muted);line-height:1.35}
.note{margin:0;color:rgba(233,236,255,.75);font-size:12px}
.out{display:grid;gap:10px}
.card{border:1px solid var(--line); border-radius:12px; padding:12px; background:rgba(0,0,0,.18)}
.card h3{margin:0 0 8px 0;font-size:14px}
.greek{font-family:var(--sans); font-variant-ligatures:none}
.mono{font-family:var(--mono)}
.pills{display:flex;gap:8px;flex-wrap:wrap;margin:8px 0 0 0}
.pill{border:1px solid var(--line); background:rgba(255,255,255,.06); padding:6px 8px; border-radius:999px; font-size:12px; color:var(--muted)}
.pill b{color:var(--text)}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px}
@media (max-width:720px){.grid2{grid-template-columns:1fr}}
.small{font-size:12px;color:var(--muted);line-height:1.35}
.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:8px}
.sel{border:1px solid var(--line); background:rgba(0,0,0,.22); color:var(--text); padding:8px 10px; border-radius:10px}
.tag{display:inline-block;padding:2px 8px;border-radius:999px;font-size:12px;border:1px solid var(--line);background:rgba(255,255,255,.05);color:var(--muted)}
.tag.good{border-color:rgba(134,239,172,.35); color:rgba(134,239,172,.95)}
.tag.warn{border-color:rgba(251,191,36,.35); color:rgba(251,191,36,.95)}
.tag.bad{border-color:rgba(251,113,133,.35); color:rgba(251,113,133,.95)}
.ftr{margin-top:10px;color:var(--muted);font-size:12px}
.mini{display:flex;gap:12px;justify-content:space-between;align-items:flex-start;flex-wrap:wrap}
.kbd{opacity:.9}
.kbd span{font-family:var(--mono);font-size:11px;border:1px solid var(--line);padding:2px 6px;border-radius:8px;background:rgba(0,0,0,.2);color:var(--text)}
hr.sep{border:none;border-top:1px solid var(--line);margin:10px 0}
.btnTiny{padding:6px 8px;border-radius:10px;border:1px solid var(--line);background:rgba(255,255,255,.06);color:var(--text);cursor:pointer}
.btnTiny:hover{background:rgba(255,255,255,.09)}

