const $ = (s, el=document) => el.querySelector(s);
const $$ = (s, el=document) => Array.from(el.querySelectorAll(s));

const samples = [
  "Ζάκυνθος",
  "ὑλήεσσα Ζάκυνθος",
  "ὑλήεντα Ζάκυνθον",
  "Κόρινθος",
  "Ἀκροκόρινθος",
  "Ἄψυνθος",
  "Ζήρυνθος ἄντρον",
  "φῶκος",
  "σῶκος ἐριούνιος Ἑρμῆς",
  "Γραῖκος",
  "γλαυκός",
  "σηκός",
  "οἶκος"
];

// --- Greek helpers (toy-level) ---
const COMBINING = /[\u0300-\u036f]/g;

function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripCombining(s){ return nfd(s).replace(COMBINING,''); }

function stripDiacriticsButKeepBase(s){
  // remove combining marks; keep base letters (incl. final sigma)
  return stripCombining(s);
}

function lowerGreek(s){
  // crude: lowercase after stripping combining, then reattach original combining? We'll just lowercase original.
  return s.toLowerCase();
}

function tokenizeGreek(s){
  return s
    .replace(/[··.,;:!?()\[\]{}«»“”"'’]/g,' ')
    .split(/\s+/)
    .filter(Boolean);
}

function endsWithBare(word, endingBare){
  const w = stripDiacriticsButKeepBase(word);
  return w.endsWith(endingBare);
}

function guessIndos(word){
  // detect -ινθος / -υνθος / -ινθον etc.
  const bare = stripDiacriticsButKeepBase(word);
  const isInthos = /ινθος$/.test(bare) || /υνθος$/.test(bare) || /ηνθος$/.test(bare) || /ανθος$/.test(bare);
  const isAcc = /ινθον$/.test(bare) || /υνθον$/.test(bare) || /ηνθον$/.test(bare) || /ανθον$/.test(bare);
  return {isInthos, isAcc, bare};
}

function suggestInthosForms(word){
  // Provide toy nominative/accusative with articles for masc/fem.
  // If input is accusative -ον, try to backform -ος.
  const bare = stripDiacriticsButKeepBase(word);
  let stem;
  if (/(ινθον|υνθον|ηνθον|ανθον)$/.test(bare)) stem = bare.slice(0,-2); // remove -ον
  else if (/(ινθος|υνθος|ηνθος|ανθος)$/.test(bare)) stem = bare.slice(0,-2); // remove -ος
  else stem = bare;

  const nom = stem + "ος";
  const acc = stem + "ον";

  return {
    nom, acc,
    masc: {nom: "ὁ " + nom, acc: "τὸν " + acc},
    fem:  {nom: "ἡ " + nom, acc: "τὴν " + acc},
    note: "Herodian notes several -ινθος place-names can be masculine or feminine (e.g. Ζάκυνθος)."
  };
}

// --- Accent toy for -κος ---
function isDisyllabicToy(word){
  // toy syllable count: count vowel groups in stripped word
  const w = stripDiacriticsButKeepBase(word);
  const vg = w.match(/[αεηιουωυ]+/g);
  return vg ? vg.length === 2 : false;
}

function endsWithKos(word){
  const w = stripDiacriticsButKeepBase(word);
  return /κος$/.test(w);
}

function hasCircumflex(word){
  // check for combining perispomeni U+0342 or precomposed with ῶ etc by NFD
  return /\u0342/.test(nfd(word));
}

function accentKosToy(word, sense){
  // sense: 'proper' => "grave" (i.e., circumflex on penult for long penult examples like φῶκος)
  //        'adjective' => acute on penult (e.g. γλαυκός)
  // We'll implement by rewriting last two syllables as: penult gets either circumflex (if possible) or acute.
  // This is not a real accentuation algorithm.

  const bare = stripDiacriticsButKeepBase(word);
  if (!/κος$/.test(bare)) return {ok:false, msg:"Not an -κος word."};

  // Find penult vowel (last vowel group before final -ος)
  // We'll locate the last vowel group before the final 'ο' of -ος.
  const wNFD = nfd(bare);
  // Work on NFC later; we need indices in bare string.

  // Identify positions in bare string
  const base = bare;
  const end = base.length;
  const finalOsIndex = base.lastIndexOf("ος");
  if (finalOsIndex < 1) return {ok:false, msg:"Could not locate -ος."};

  const pre = base.slice(0, finalOsIndex); // up to before -ος
  // Find last vowel in pre
  const vowels = "αεηιουωυ";
  let i = pre.length - 1;
  while (i >= 0 && !vowels.includes(pre[i])) i--;
  if (i < 0) return {ok:false, msg:"No vowel found for penult."};

  // Expand to vowel group start
  let j = i;
  while (j-1 >= 0 && vowels.includes(pre[j-1])) j--;
  const vowelGroup = pre.slice(j, i+1);

  // Build accented vowel group (very toy):
  // If group contains ω/η/α/ι/υ/ου/ει etc, we just accent the last vowel char.
  const acute = "\u0301";
  const circumflex = "\u0342";

  function addMarkToLastVowel(group, mark){
    const g = nfd(group);
    // find last base vowel in group
    const chars = Array.from(g);
    // remove existing marks
    const bases = chars.filter(ch => !COMBINING.test(ch));
    // But we need to keep group as bases only anyway.
    const baseOnly = bases.join('');
    const arr = Array.from(baseOnly);
    for (let k = arr.length-1; k>=0; k--){
      if (vowels.includes(arr[k])){
        arr[k] = nfd(arr[k]) + mark;
        break;
      }
    }
    return nfc(arr.join(''));
  }

  const mark = (sense === 'adjective') ? acute : circumflex;
  const newGroup = addMarkToLastVowel(vowelGroup, mark);

  const rebuilt = pre.slice(0, j) + newGroup + base.slice(finalOsIndex);

  return {
    ok:true,
    input: word,
    output: rebuilt,
    sense,
    rule: (sense === 'adjective')
      ? "Toy rule: adjectival -κός gets an acute (cf. γλαυκός, λευκός)."
      : "Toy rule: proper-name/monogender -κος with long penult is treated as ‘grave’ (shown here with a circumflex on the penult: φῶκος, σῶκος, Γραῖκος)."
  };
}

function makeCard(title, innerHTML){
  const d = document.createElement('div');
  d.className = 'card';
  d.innerHTML = `<h3>${title}</h3>${innerHTML}`;
  return d;
}

function esc(s){
  return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function analyze(){
  const raw = $('#inp').value.trim();
  const out = $('#out');
  out.innerHTML = '';
  if (!raw){
    out.appendChild(makeCard('Nothing to analyze', `<div class="small">Type a Greek word or phrase above.</div>`));
    return;
  }

  const toks = tokenizeGreek(raw);
  const targetsInthos = [];
  const targetsKos = [];

  for (const t of toks){
    const g = guessIndos(t);
    if (g.isInthos || g.isAcc) targetsInthos.push(t);
    if (endsWithKos(t)) targetsKos.push(t);
  }

  // Overview card
  const overview = [];
  overview.push(`<div class="pills">`);
  overview.push(`<span class="pill"><b>Tokens</b> ${toks.length}</span>`);
  overview.push(`<span class="pill"><b>-ινθος hits</b> ${targetsInthos.length}</span>`);
  overview.push(`<span class="pill"><b>-κος hits</b> ${targetsKos.length}</span>`);
  overview.push(`</div>`);
  out.appendChild(makeCard('Scan', `<div class="small mono">${esc(toks.join(' · '))}</div>${overview.join('')}`));

  if (targetsInthos.length){
    const box = document.createElement('div');
    box.className = 'card';
    box.innerHTML = `<h3><span class="greek">-ινθος</span> / <span class="greek">-υνθος</span> place-name play</h3>
      <div class="small">Herodian often treats these as toponyms with variable gender. Pick a hit to see quick article + case variants.</div>
      <div class="controls">
        <label class="small">Choose:</label>
        <select id="selInthos" class="sel"></select>
        <button id="btnInthos" class="btnTiny">Show forms</button>
      </div>
      <div id="inthosOut" class="small" style="margin-top:10px"></div>`;
    out.appendChild(box);

    const sel = $('#selInthos', box);
    targetsInthos.forEach((w,i)=>{
      const opt = document.createElement('option');
      opt.value = w;
      opt.textContent = w;
      sel.appendChild(opt);
      if (i===0) opt.selected = true;
    });

    const render = () => {
      const w = sel.value;
      const forms = suggestInthosForms(w);
      const html = `
        <div class="grid2">
          <div>
            <div class="tag good">masculine option</div>
            <div class="mono" style="margin-top:6px"><span class="greek">${esc(forms.masc.nom)}</span> · <span class="greek">${esc(forms.masc.acc)}</span></div>
          </div>
          <div>
            <div class="tag warn">feminine option</div>
            <div class="mono" style="margin-top:6px"><span class="greek">${esc(forms.fem.nom)}</span> · <span class="greek">${esc(forms.fem.acc)}</span></div>
          </div>
        </div>
        <hr class="sep" />
        <div class="small"><span class="tag">toy backform</span> nominative <span class="greek mono">${esc(forms.nom)}</span> · accusative <span class="greek mono">${esc(forms.acc)}</span></div>
        <div class="small" style="margin-top:6px">${esc(forms.note)}</div>
      `;
      $('#inthosOut', box).innerHTML = html;
    };

    $('#btnInthos', box).addEventListener('click', render);
    sel.addEventListener('change', render);
    render();
  } else {
    out.appendChild(makeCard('No -ινθος found', `<div class="small">Try <span class="greek">Ζάκυνθος</span>, <span class="greek">Κόρινθος</span>, <span class="greek">Πέρινθος</span>, <span class="greek">Ἄψυνθος</span>.</div>`));
  }

  if (targetsKos.length){
    const box = document.createElement('div');
    box.className = 'card';
    box.innerHTML = `<h3><span class="greek">-κος</span> accent switch (proper name vs adjective)</h3>
      <div class="small">Herodian contrasts <span class="greek">Γραῖκος</span> (proper name) vs <span class="greek">Γραικός</span> (adjectival), and discusses <span class="greek">φῶκος</span>, <span class="greek">σῶκος</span>. Choose a word and a “sense” to flip the toy accent.</div>
      <div class="controls">
        <label class="small">Word:</label>
        <select id="selKos" class="sel"></select>
        <label class="small">Sense:</label>
        <select id="selSense" class="sel">
          <option value="proper">proper name / monogender noun (toy: circumflex)</option>
          <option value="adjective">adjective (toy: acute)</option>
        </select>
        <button id="btnKos" class="btnTiny">Accent it</button>
      </div>
      <div id="kosOut" class="small" style="margin-top:10px"></div>
      <div class="small" style="margin-top:8px"><span class="tag">tip</span> Try typing <span class="greek">Γραῖκος</span> and switch sense to see <span class="greek">Γραικός</span> (toy output).</div>`;
    out.appendChild(box);

    const sel = $('#selKos', box);
    targetsKos.forEach((w,i)=>{
      const opt = document.createElement('option');
      opt.value = w;
      opt.textContent = w;
      sel.appendChild(opt);
      if (i===0) opt.selected = true;
    });

    const render = () => {
      const w = sel.value;
      const sense = $('#selSense', box).value;
      const res = accentKosToy(w, sense);
      if (!res.ok){
        $('#kosOut', box).innerHTML = `<span class="tag bad">couldn’t accent</span> ${esc(res.msg)}`;
        return;
      }
      const disyl = isDisyllabicToy(w);
      const circ = hasCircumflex(w);
      const flags = [
        disyl ? `<span class="tag good">toy disyllable</span>` : `<span class="tag warn">not toy-disyllable</span>`,
        circ ? `<span class="tag">input has circumflex</span>` : `<span class="tag">no circumflex detected</span>`
      ].join(' ');

      $('#kosOut', box).innerHTML = `
        <div class="mono"><span class="greek">${esc(w)}</span> → <span class="greek">${esc(res.output)}</span></div>
        <div style="margin-top:6px">${flags}</div>
        <div class="small" style="margin-top:6px">${esc(res.rule)}</div>
      `;
    };

    $('#btnKos', box).addEventListener('click', render);
    $('#selSense', box).addEventListener('change', render);
    sel.addEventListener('change', render);
    render();
  } else {
    out.appendChild(makeCard('No -κος found', `<div class="small">Try <span class="greek">φῶκος</span>, <span class="greek">σῶκος</span>, <span class="greek">Γραῖκος</span>, <span class="greek">γλαυκός</span>, <span class="greek">λευκός</span>, <span class="greek">σηκός</span>.</div>`));
  }
}

$('#btn').addEventListener('click', analyze);
$('#inp').addEventListener('keydown', (e)=>{
  if (e.key === 'Enter') analyze();
});
$('#rnd').addEventListener('click', ()=>{
  const s = samples[Math.floor(Math.random()*samples.length)];
  $('#inp').value = s;
  analyze();
});
$('#clr').addEventListener('click', ()=>{
  $('#inp').value = '';
  $('#inp').focus();
  $('#out').innerHTML = '';
});

window.addEventListener('keydown', (e)=>{
  if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'l'){
    e.preventDefault();
    $('#inp').focus();
    $('#inp').select();
  }
});

// initial
$('#inp').value = 'Ζάκυνθος';
analyze();

