const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const out = $('#out');
const play = $('#play');

const examples = [
  {w:'Μάκκος', note:'proper name; barytone per rule', cls:'good'},
  {w:'Ὄγκος', note:'proper name; barytone per rule', cls:'good'},
  {w:'Λύγκος', note:'place-name; barytone per rule', cls:'good'},
  {w:'λάκκος', note:'appellative; barytone per rule', cls:'good'},
  {w:'σάκκος', note:'appellative; barytone per rule', cls:'good'},
  {w:'ὅρκος', note:'appellative; barytone per rule', cls:'good'},
  {w:'δίσκος', note:'σ-cluster; barytone per rule', cls:'good'},
  {w:'μύσκος', note:'σ-cluster; barytone per rule', cls:'good'},
  {w:'ἀσκός', note:'starts with vowel; mentioned as special case', cls:'warn'},
  {w:'θριγκός', note:'noted exception (oxytone)', cls:'bad'},
  {w:'φακός', note:'noted exception (oxytone)', cls:'bad'},
  {w:'δοκός', note:'contrast pair (noose) vs δόκος (opinion)', cls:'warn'},
  {w:'δόκος', note:'contrast pair (opinion) vs δοκός (noose)', cls:'warn'},
  {w:'χαλκός', note:'has λ before -κος; discussed', cls:'warn'},
];

function stripDiacritics(s){
  // Remove Greek tonos/oxia, varia, perispomeni, dialytika, breathings, iota subscript, etc.
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function hasAccentOrBreathing(s){
  const n = s.normalize('NFD');
  return /[\u0300-\u036f]/.test(n);
}

function endsWithKos(s){
  const base = stripDiacritics(s).toLowerCase();
  return base.endsWith('κος');
}

function vowelGroupsCount(s){
  const base = stripDiacritics(s).toLowerCase();
  // Greek vowels (incl. omega/eta etc.)
  const vowels = 'αεηιουω';
  let count = 0;
  let inV = false;
  for (const ch of base){
    const isV = vowels.includes(ch);
    if (isV && !inV) count++;
    inV = isV;
  }
  return count;
}

function beginsWithConsonant(s){
  const base = stripDiacritics(s).toLowerCase().trim();
  if (!base) return false;
  const vowels = 'αεηιουω';
  const first = base[0];
  return !vowels.includes(first);
}

function hasSigmaCluster(s){
  const base = stripDiacritics(s).toLowerCase();
  // any consonant + σ + consonant, or σ + consonant cluster
  // We'll just look for σ followed by a consonant, and also something like σκ/σπ/στ/σμ/σν/σλ/σρ
  return /σ[βγδζθκλμνξπρστφχψ]/.test(base) || /[βγδζθκλμνξπρστφχψ]σ[βγδζθκλμνξπρστφχψ]/.test(base);
}

function penultEndsInConsonantBeforeKos(s){
  const base = stripDiacritics(s).toLowerCase();
  if (!base.endsWith('κος')) return false;
  // character immediately before 'κος'
  const i = base.length - 3;
  const prev = base[i-1];
  if (!prev) return false;
  const vowels = 'αεηιουω';
  return !vowels.includes(prev);
}

function suggestRule(s){
  const base = stripDiacritics(s);
  const lower = base.toLowerCase();

  const flaggedOxy = new Set(['θριγκος','φακος']);
  const contrast = new Set(['δοκος']);

  if (!endsWithKos(base)){
    return {kind:'none', msg:`Doesn’t look like -κος. Try a disyllable ending in <span class="mono">-κος</span>.`};
  }

  const bare = stripDiacritics(base).toLowerCase();
  const vg = vowelGroupsCount(base);
  const disyll = (vg === 2);

  if (flaggedOxy.has(bare)){
    return {kind:'oxy', msg:`Herodian notes <span class="mono">${base}</span> as an exception: <b>oxytone</b> (accent on the last syllable).`};
  }

  if (contrast.has(bare)){
    return {kind:'warn', msg:`<span class="mono">δοκός</span> vs <span class="mono">δόκος</span> is a meaning-contrast pair in the passage. This toy can’t know your meaning—try both accents in the playground.`};
  }

  const penC = penultEndsInConsonantBeforeKos(base);
  const sigCl = hasSigmaCluster(base);
  const beginsC = beginsWithConsonant(base);

  // Roughly mirror the passage: many disyllables with penult ending in consonant (except λ) are barytone.
  // We'll treat λ-before-κος as "special" rather than strict.
  const beforeKos = stripDiacritics(base).toLowerCase().slice(-4, -3); // one char before κ
  const hasLambdaBeforeKos = (beforeKos === 'λ');

  let reasons = [];
  if (disyll) reasons.push('probably disyllabic');
  else reasons.push(`vowel-groups≈${vg} (not clearly disyllabic)`);

  if (penC) reasons.push('penult ends in a consonant before -κος');
  if (sigCl && beginsC) reasons.push('has a σ-cluster and begins with a consonant');
  if (hasLambdaBeforeKos) reasons.push('has λ before -κος (discussed as special)');

  // Decision heuristic
  let kind = 'bary';
  let confidence = 'medium';

  if (!disyll) confidence = 'low';
  if (sigCl && beginsC) confidence = 'high';
  if (penC) confidence = (confidence === 'low') ? 'medium' : 'high';
  if (hasLambdaBeforeKos) confidence = 'medium';

  // If it starts with vowel and is like ἀσκός, warn.
  if (!beginsC && sigCl){
    kind = 'warn';
    return {kind, msg:`Starts with a vowel but has σ-cluster; Herodian explicitly mentions <span class="mono">ἀσκός</span> as vowel-initial. Treat with caution. (${reasons.join('; ')})`};
  }

  return {
    kind,
    msg:`Heuristic result: <b>barytone</b> (accent not on ultima) <span class="tag ${confidence==='high'?'good':confidence==='medium'?'warn':'bad'}">confidence: ${confidence}</span><hr><div class="small">Why: ${reasons.join('; ')}.</div>`
  };
}

function applyAcuteToSyllable(word, where){
  // where: 'bary' => penult vowel; 'oxy' => ultima vowel
  // We operate on accent-stripped form, then add combining acute to the target vowel.
  const clean = stripDiacritics(word);
  const nfd = clean.normalize('NFD');

  // Identify vowel positions in NFC string by scanning base letters.
  const base = clean; // NFC
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

  // Find last two vowel indices (in code units) in base.
  let vowelIdx = [];
  for (let i=0;i<base.length;i++){
    if (vowels.has(base[i])) vowelIdx.push(i);
  }
  if (vowelIdx.length === 0) return clean;

  let target;
  if (where === 'oxy') target = vowelIdx[vowelIdx.length-1];
  else {
    target = vowelIdx.length >= 2 ? vowelIdx[vowelIdx.length-2] : vowelIdx[vowelIdx.length-1];
  }

  // Insert combining acute after the target vowel.
  const ACUTE = '\u0301';
  const out = base.slice(0, target+1) + ACUTE + base.slice(target+1);
  return out.normalize('NFC');
}

function renderAnalysis(){
  const s = inp.value.trim();
  if (!s){
    out.innerHTML = 'Type a word ending in <span class="mono">-κος</span>.';
    play.textContent = '';
    return;
  }
  const res = suggestRule(s);
  const base = stripDiacritics(s);
  const hasMarks = hasAccentOrBreathing(s);

  let badge = '';
  if (res.kind === 'bary') badge = '<span class="tag good">βαρύνεται</span>';
  else if (res.kind === 'oxy') badge = '<span class="tag bad">ὀξύνεται</span>';
  else badge = '<span class="tag warn">note</span>';

  const plain = `<div><span class="mono">${s}</span> ${badge}</div>`;
  const extra = `<div class="tiny">Plain form: <span class="mono">${base}</span>${hasMarks ? ' (diacritics detected)' : ' (no diacritics detected)'}</div>`;

  out.innerHTML = plain + '<div style="margin-top:6px">' + res.msg + '</div>' + extra;

  // Update playground preview
  const bary = applyAcuteToSyllable(base, 'bary');
  const oxy = applyAcuteToSyllable(base, 'oxy');
  play.innerHTML = `Try: <span class="mono">${bary}</span> (barytone) &nbsp;|&nbsp; <span class="mono">${oxy}</span> (oxytone)`;
}

function renderChips(){
  const box = $('#chips');
  box.innerHTML = '';
  for (const ex of examples){
    const d = document.createElement('div');
    d.className = 'chip';
    d.textContent = ex.w;
    d.title = ex.note;
    d.addEventListener('click', () => {
      inp.value = ex.w;
      renderAnalysis();
    });
    box.appendChild(d);
  }
}

$('#analyze').addEventListener('click', renderAnalysis);
$('#clear').addEventListener('click', () => { inp.value=''; renderAnalysis(); inp.focus(); });
$('#random').addEventListener('click', () => {
  const ex = examples[Math.floor(Math.random()*examples.length)];
  inp.value = ex.w;
  renderAnalysis();
});

$('#apply').addEventListener('click', () => {
  const s = inp.value.trim();
  if (!s) return;
  const base = stripDiacritics(s);
  const where = document.querySelector('input[name="place"]:checked')?.value || 'bary';
  const accented = applyAcuteToSyllable(base, where);
  inp.value = accented;
  renderAnalysis();
});

$('#strip').addEventListener('click', () => {
  const s = inp.value.trim();
  if (!s) return;
  inp.value = stripDiacritics(s);
  renderAnalysis();
});

inp.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') renderAnalysis();
});

renderChips();
renderAnalysis();

