const $ = (sel) => document.querySelector(sel);

const samples = [
  {w:"λευκος", note:"disyllabic -κος → oxytone"},
  {w:"γλαυκος", note:"disyllabic -κος → oxytone"},
  {w:"μικκος", note:"disyllabic -κος → oxytone"},
  {w:"Λαβδακος", note:"proper name, -ακος with consonant before α → barytone"},
  {w:"Πινακος", note:"proper name, -ακος with consonant before α → barytone"},
  {w:"Ασσαρακος", note:"proper name, -ακος with consonant before α → barytone"},
  {w:"Ιθακος", note:"proper name, -ακος with consonant before α → barytone"},
  {w:"Λαμψακος", note:"trisyllabic -ακος, first syllable ends in consonant → proparoxytone"},
  {w:"Ρυνδακος", note:"trisyllabic -ακος → proparoxytone"},
  {w:"Πιττακος", note:"same mute ends 1st and begins 2nd → oxytone"},
  {w:"Καλλιακος", note:"vowel before penult α → oxytone"},
  {w:"Αιακος", note:"vowel before penult α → oxytone"},
  {w:"Αστακος", note:"noted exception in passage"}
];

function buildChips(){
  const box = $("#chips");
  box.innerHTML = "";
  samples.forEach(s => {
    const b = document.createElement("button");
    b.type = "button";
    b.className = "chip";
    b.textContent = s.w;
    b.title = s.note;
    b.addEventListener("click", () => {
      $("#w").value = s.w;
      run();
      $("#w").focus();
    });
    box.appendChild(b);
  });
}

// --- Greek helpers ---
const combining = /[\u0300-\u036f]/g;
function nfd(s){ return s.normalize('NFD'); }
function stripDiacritics(s){
  // remove combining marks; keep base letters
  return nfd(s).replace(combining, "").normalize('NFC');
}

function isGreekLetter(ch){
  const cp = ch.codePointAt(0);
  return (cp>=0x0370 && cp<=0x03FF) || (cp>=0x1F00 && cp<=0x1FFF);
}

const vowels = new Set(["α","ε","η","ι","ο","υ","ω","ά","έ","ή","ί","ό","ύ","ώ","ϊ","ϋ","ΐ","ΰ"]);
function isVowel(ch){
  if(!ch) return false;
  const base = stripDiacritics(ch).toLowerCase();
  return ["α","ε","η","ι","ο","υ","ω"].includes(base);
}

function lastIndexOfVowel(str){
  for(let i=str.length-1;i>=0;i--){
    if(isVowel(str[i])) return i;
  }
  return -1;
}

function roughSyllables(word){
  // Very rough: split before each vowel that starts a new nucleus.
  // Treat diphthongs (αι, ει, οι, υι, αυ, ευ, ου, ηυ) as one nucleus.
  const w = stripDiacritics(word).toLowerCase();
  const dip = new Set(["αι","ει","οι","υι","αυ","ευ","ου","ηυ"]);
  let syl = [];
  let cur = "";
  for(let i=0;i<w.length;i++){
    const ch = w[i];
    cur += word[i]; // keep original char for display
    if(isVowel(ch)){
      const next = w[i+1] || "";
      const pair = ch + next;
      if(next && isVowel(next) && dip.has(pair)){
        // consume next as part of nucleus
        i++;
        cur += word[i];
      }
      // close syllable at vowel nucleus; following consonants will attach until next vowel
      // but if there are multiple consonants, we keep them with current syllable for simplicity
      // and let next vowel start a new syllable.
      syl.push(cur);
      cur = "";
    }
  }
  if(cur) syl[syl.length-1] = (syl[syl.length-1]||"") + cur;
  // If no vowels found, return whole word
  if(syl.length===0) return [word];
  return syl;
}

function applyAcuteOnVowelOfSyllable(word, syllables, targetIndex){
  // Put an acute on the last vowel of the target syllable.
  // We only add acute to α ε η ι ο υ ω (and their uppercase).
  const acuteMap = {
    "α":"ά","ε":"έ","η":"ή","ι":"ί","ο":"ό","υ":"ύ","ω":"ώ",
    "Α":"Ά","Ε":"Έ","Η":"Ή","Ι":"Ί","Ο":"Ό","Υ":"Ύ","Ω":"Ώ"
  };

  // compute start offsets
  let starts = [];
  let pos = 0;
  for(const s of syllables){ starts.push(pos); pos += s.length; }
  const start = starts[targetIndex];
  const end = start + syllables[targetIndex].length;

  // find last vowel in that span
  let chars = Array.from(word);
  let idx = -1;
  for(let i=end-1;i>=start;i--){
    const base = stripDiacritics(chars[i]);
    if(isVowel(base)) { idx = i; break; }
  }
  if(idx<0) return word;

  // strip existing combining marks on that character, then acute it if possible
  const base = stripDiacritics(chars[idx]);
  const repl = acuteMap[base] || acuteMap[base.toLowerCase()] || null;
  if(repl){
    // preserve case if base was uppercase
    const isUpper = base === base.toUpperCase() && base !== base.toLowerCase();
    chars[idx] = isUpper ? (acuteMap[base] || repl) : repl;
  }
  return chars.join("");
}

function endsWithKos(w){
  const s = stripDiacritics(w).toLowerCase();
  return s.endsWith("κος");
}

function penultHasOmega(w){
  // check if the vowel nucleus of penult syllable is ω (rough)
  const syl = roughSyllables(w);
  if(syl.length < 2) return false;
  const pen = stripDiacritics(syl[syl.length-2]).toLowerCase();
  // find last vowel in penult syllable
  for(let i=pen.length-1;i>=0;i--){
    if(isVowel(pen[i])) return pen[i] === "ω";
  }
  return false;
}

function classify(word){
  const raw = word;
  const w = stripDiacritics(raw);
  const low = w.toLowerCase();
  const syl = roughSyllables(w);
  const n = syl.length;

  if(!endsWithKos(w)){
    return {ok:false, syl, rule:"Not a -κος word", why:"Herodian’s snippet here is about words ending in -κος / -ακος.", accentIndex:null};
  }

  // Special-cased exception mentioned
  if(stripDiacritics(w).toLowerCase() === "αστακος"){
    return {ok:true, syl, rule:"Exception noted: Ἀστακός", why:"The passage flags Ἀστακός as ‘σεσημείωται’ (noteworthy/exceptional). We treat it as oxytone.", accentIndex:n-1};
  }

  // Disyllabic -κος: oxytone, except penult ω
  if(n === 2){
    if(penultHasOmega(w)){
      return {ok:true, syl, rule:"Disyllabic -κος, penult ω → (toy) not-final", why:"Herodian: disyllabic -κος are oxytone except those with ω in the penult. The toy punts to penult-accent.", accentIndex:n-2};
    }
    return {ok:true, syl, rule:"Disyllabic -κος → oxytone", why:"Herodian: λευκός, γλαυκός, μικκός.", accentIndex:n-1};
  }

  // Longer words: focus on penult α
  // Determine penult vowel (rough)
  const penSyl = syl[n-2] || "";
  let penV = null;
  const penBase = stripDiacritics(penSyl);
  for(let i=penBase.length-1;i>=0;i--){
    if(isVowel(penBase[i])) { penV = penBase[i].toLowerCase(); break; }
  }

  // If penult vowel is alpha, apply Herodian’s split
  if(penV === "α"){
    // find char immediately before that alpha in the whole word (roughly)
    const baseAll = stripDiacritics(w);
    // locate last alpha before final -κος (i.e., the penult nucleus)
    const baseLow = baseAll.toLowerCase();
    const idxKos = baseLow.lastIndexOf("κος");
    let idxAlpha = -1;
    for(let i=idxKos-1;i>=0;i--){
      if(baseLow[i] === "α") { idxAlpha = i; break; }
      if(isVowel(baseLow[i])) break; // stop at earlier vowel nucleus
    }
    const prev = idxAlpha>0 ? baseLow[idxAlpha-1] : "";

    // If vowel precedes that alpha → oxytone
    if(prev && isVowel(prev)){
      return {ok:true, syl, rule:"…-ιακος / vowel + ακος → oxytone", why:"Herodian: if a vowel precedes the penult α in longer -κος words, accent the ultima (e.g. Καλλιακός, Αἰακός).", accentIndex:n-1};
    }

    // If consonant(s) precede: proper names barytone (toy: penult)
    // We can’t detect ‘proper name’ reliably; heuristic: initial capital → treat as proper.
    const isProperish = raw.trim()[0] && raw.trim()[0] === raw.trim()[0].toUpperCase();
    if(isProperish){
      // For trisyllabic -ακος, Herodian sometimes wants proparoxytone; handle below.
      if(n === 3 && baseLow.endsWith("ακος")){
        // check for “same mute ends 1st and begins 2nd” (toy): look for doubled consonant like ττ, κκ, ππ, etc.
        const doubled = /(ββ|γγ|δδ|ζζ|θθ|κκ|λλ|μμ|νν|ππ|ρρ|σσ|ττ|φφ|χχ|ψψ)/;
        if(doubled.test(baseLow)){
          return {ok:true, syl, rule:"-ακος with same mute at syllable boundary → oxytone", why:"Herodian: Πιττακός and similar are oxytone when the first syllable ends in the same mute that begins the second.", accentIndex:n-1};
        }
        return {ok:true, syl, rule:"Trisyllabic -ακος → proparoxytone (toy)", why:"Herodian: many trisyllables in -ακος are proparoxytone (e.g. Λάμψακος, Ῥύνδακος).", accentIndex:0};
      }
      return {ok:true, syl, rule:"Proper-name-ish …-ακος with consonant before α → barytone (toy)", why:"Herodian: Λάβδακος, Πίνακος, Ἀσσάρακος, Ἴθακος are barytone. The toy places the accent on the penult.", accentIndex:n-2};
    }

    // Not proper: default to oxytone for safety
    return {ok:true, syl, rule:"Penult α in longer -κος → (toy) oxytone", why:"When unsure, the toy leans oxytone; Herodian’s passage is mainly about proper names and certain formations.", accentIndex:n-1};
  }

  // Fallback: accent penult
  return {ok:true, syl, rule:"Fallback: accent penult", why:"Outside the specific -ακος patterns, the toy uses a simple fallback.", accentIndex:Math.max(0,n-2)};
}

function run(){
  const inp = $("#w").value.trim();
  const strip = $("#strip").checked;
  const showSyl = $("#showSyl").checked;

  if(!inp){
    $("#accented").textContent = "—";
    $("#rule").textContent = "—";
    $("#why").textContent = "";
    $("#syl").textContent = "";
    return;
  }

  const base = strip ? stripDiacritics(inp) : inp;
  const info = classify(base);

  if(!info.ok){
    $("#accented").innerHTML = `<span class="bad">${escapeHtml(base)}</span>`;
    $("#rule").textContent = info.rule;
    $("#why").textContent = info.why;
    $("#syl").textContent = showSyl ? `syllables: ${info.syl.join("·")}` : "";
    return;
  }

  const accented = applyAcuteOnVowelOfSyllable(base, info.syl, info.accentIndex);
  $("#accented").innerHTML = `<span class="good">${escapeHtml(accented)}</span>`;
  $("#rule").textContent = info.rule;
  $("#why").textContent = info.why;
  $("#syl").textContent = showSyl ? `syllables: ${info.syl.join("·")}` : "";
}

function escapeHtml(s){
  return s.replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
}

$("#go").addEventListener("click", run);
$("#clear").addEventListener("click", () => { $("#w").value = ""; run(); $("#w").focus(); });
$("#w").addEventListener("keydown", (e) => { if(e.key === "Enter") run(); });
$("#strip").addEventListener("change", run);
$("#showSyl").addEventListener("change", run);

buildChips();
run();

