:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --panel2:#1d2140;
  --text:#e9ecff;
  --muted:#b8bde6;
  --line:#2a2f55;
  --accent:#8be9fd;
  --accent2:#ffd479;
  --bad:#ff6b6b;
  --good:#7CFFB2;
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Noto Sans", "Liberation Sans", sans-serif;
}

*{box-sizing:border-box}

.wrap{
  font-family:var(--sans);
  color:var(--text);
  background:linear-gradient(180deg, #0f1220 0%, #0b0d18 100%);
  padding:18px;
  max-width:980px;
  margin:0 auto;
}

.hdr h1{margin:0 0 6px 0; font-size:22px; letter-spacing:.2px}
.sub{margin:0; color:var(--muted); line-height:1.35}

.panel{
  margin-top:14px;
  background:rgba(255,255,255,0.03);
  border:1px solid var(--line);
  border-radius:14px;
  padding:14px;
}

.row{display:flex; gap:10px; align-items:center; flex-wrap:wrap}
.row.small{margin-top:10px; gap:14px}

label{color:var(--muted); font-size:13px}

input[type="text"]{
  flex:1 1 360px;
  min-width:240px;
  padding:10px 12px;
  border-radius:12px;
  border:1px solid var(--line);
  background:rgba(0,0,0,0.25);
  color:var(--text);
  font-size:18px;
  outline:none;
}
input[type="text"]:focus{border-color:rgba(139,233,253,0.7); box-shadow:0 0 0 3px rgba(139,233,253,0.12)}

button{
  padding:10px 12px;
  border-radius:12px;
  border:1px solid rgba(139,233,253,0.35);
  background:rgba(139,233,253,0.12);
  color:var(--text);
  cursor:pointer;
  font-weight:600;
}
button:hover{background:rgba(139,233,253,0.18)}
button:active{transform:translateY(1px)}
button.ghost{border-color:rgba(255,212,121,0.35); background:rgba(255,212,121,0.10)}
button.ghost:hover{background:rgba(255,212,121,0.16)}

.tog{display:flex; gap:8px; align-items:center; color:var(--muted); font-size:13px}
.tog input{transform:translateY(1px)}

.out{display:grid; grid-template-columns: 1fr 2fr 1.2fr; gap:10px; margin-top:12px}
@media (max-width:820px){.out{grid-template-columns:1fr}}

.card{
  border:1px solid var(--line);
  border-radius:14px;
  padding:12px;
  background:linear-gradient(180deg, rgba(255,255,255,0.04), rgba(255,255,255,0.02));
}
.k{color:var(--muted); font-size:12px; text-transform:uppercase; letter-spacing:.08em}
.v{margin-top:6px; font-size:15px; line-height:1.25}
.v.big{font-size:26px; font-weight:750; letter-spacing:.2px}
.hint{margin-top:6px; color:var(--muted); font-size:12px}

.help{margin-top:10px; color:var(--muted)}
.help summary{cursor:pointer; user-select:none}
.help ul{margin:8px 0 0 18px; padding:0}
.help li{margin:6px 0}

h2{margin:0 0 10px 0; font-size:16px}

.chips{display:flex; flex-wrap:wrap; gap:8px}
.chip{
  border:1px solid var(--line);
  background:rgba(0,0,0,0.18);
  padding:7px 10px;
  border-radius:999px;
  cursor:pointer;
  font-family:var(--mono);
  font-size:13px;
  color:var(--text);
}
.chip:hover{border-color:rgba(139,233,253,0.55)}

.mini{color:var(--muted); font-size:12px; margin:10px 0 0 0}
.ftr{margin-top:10px}

code{font-family:var(--mono); color:var(--accent)}

