(() => {
  const $ = (sel, root=document) => root.querySelector(sel);

  const inp = $('#inp');
  const btnGo = $('#btnGo');
  const btnShuffle = $('#btnShuffle');
  const detEnding = $('#detEnding');
  const suggested = $('#suggested');
  const ruleUsed = $('#ruleUsed');
  const accentHint = $('#accentHint');
  const chips = $('#chips');

  const keepDiacritics = $('#keepDiacritics');
  const showSyll = $('#showSyll');
  const forceLower = $('#forceLower');

  // Examples from the passage (some unaccented to show the toy adding accents)
  const examples = [
    'λιθιακος','μαλθακος','ψιττακος','ἀστακος','ἀνακος','φυλακος','Φύλακος','φαρμακος','φάρμακος',
    'θύλακος','ὕσσακος','αἴσακος','μαίμακος',
    'Δηλιακος','Φρυγιακος','Ἰλιακος','Αἰνιακος','Ἀκτιακος','Ἀλαβανδιακος',
    'Βυζαντιακος','Πελοποννησιακος','Ῥοδιακος','Χιακος',
    'Ἀλώπεκος','Καππαδοκος','Σπόρδοκος','Ἀμάδοκος','Δημόδοκος','Λαόδοκος','ξενοδόκος','ἰοδόκος','αἰγοβοσκός'
  ];

  // Exceptions explicitly mentioned as proparoxytone in the passage
  const exceptionsProparox = new Set([
    stripDiacritics('θύλακος'),
    stripDiacritics('ὕσσακος'),
    stripDiacritics('αἴσακος')
  ]);

  // Utility: strip Greek diacritics (NFD) and normalize final sigma
  function stripDiacritics(s){
    return (s || '')
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g,'')
      .replace(/ς/g,'σ')
      .trim();
  }

  function hasAccent(s){
    const n = (s||'').normalize('NFD');
    return /[\u0301\u0300\u0342]/.test(n); // acute, grave, circumflex
  }

  function toLowerGreek(s){
    // JS lowercasing works for Greek; keep final sigma as typed.
    return (s||'').toLowerCase();
  }

  function lastIndexOfVowelBase(word){
    const w = stripDiacritics(word);
    const vowels = new Set(['α','ε','η','ι','ο','υ','ω']);
    for(let i=w.length-1;i>=0;i--){
      if(vowels.has(w[i])) return i;
    }
    return -1;
  }

  function vowelPositions(word){
    const w = stripDiacritics(word);
    const vowels = new Set(['α','ε','η','ι','ο','υ','ω']);
    const pos=[];
    for(let i=0;i<w.length;i++) if(vowels.has(w[i])) pos.push(i);
    return pos;
  }

  function addAcuteOnVowelAt(word, vowelIndex){
    // Add acute to the vowel at vowelIndex in the original string by mapping to NFD.
    // We approximate by operating on stripped base letters, then recompose.
    const orig = word.normalize('NFD');
    // Build a mapping from base-letter indices to positions in NFD string.
    let baseIdx = -1;
    let targetPos = -1;
    for(let i=0;i<orig.length;i++){
      const ch = orig[i];
      if(!(/[\u0300-\u036f]/.test(ch))){
        baseIdx++;
        if(baseIdx === vowelIndex){
          targetPos = i;
          break;
        }
      }
    }
    if(targetPos === -1) return word;

    // Insert acute after the base character, but before any following combining marks.
    let j = targetPos + 1;
    while(j < orig.length && /[\u0300-\u036f]/.test(orig[j])) j++;

    const before = orig.slice(0, j);
    const after = orig.slice(j);
    const withAcute = before + '\u0301' + after;
    return withAcute.normalize('NFC');
  }

  function removeAllAccents(word){
    return (word||'')
      .normalize('NFD')
      .replace(/[\u0300\u0301\u0342]/g,'')
      .normalize('NFC');
  }

  function roughSyllableSplit(word){
    // Very rough: split before each vowel after the first vowel.
    const base = stripDiacritics(word);
    const vpos = vowelPositions(base);
    if(vpos.length <= 1) return word;
    const cuts = new Set(vpos.slice(1));
    let out='';
    for(let i=0;i<word.length;i++){
      // We need to decide cut positions in base-letter space; approximate by stripping diacritics progressively.
      // Simpler: compute on base and apply to base only.
    }
    // Return split on base (diacritics removed) for clarity.
    let b='';
    for(let i=0;i<base.length;i++){
      if(cuts.has(i)) b += '·';
      b += base[i];
    }
    return b;
  }

  function detectEnding(word){
    const w = stripDiacritics(word);
    if(w.endsWith('ακος')) return '-ακος';
    if(w.endsWith('εκος')) return '-εκος';
    if(w.endsWith('οκος')) return '-οκος';
    if(w.endsWith('κος')) return '-κος';
    return '—';
  }

  function suggestAccent(word){
    const raw = (word||'').trim();
    if(!raw) return {out:'—', ending:'—', rule:'Type something.'};

    const ending = detectEnding(raw);
    const base = stripDiacritics(raw);

    // If user wants to keep existing accents and there is one, just echo (with optional syllable info)
    if(keepDiacritics.checked && hasAccent(raw)){
      return {
        out: formatOut(raw),
        ending,
        rule: 'Kept your existing accent(s).'
      };
    }

    // Work on an unaccented version (but keep breathings etc. if present; we remove accents only)
    let w = removeAllAccents(raw);

    // Determine syllable count roughly by vowel count
    const vpos = vowelPositions(w);
    const sylls = vpos.length;

    // Decide target accent position: last (oxytone) or antepenult (proparoxytone)
    let target = 'last';
    let rule = '';

    if(ending === '-εκος'){
      // Herodian: Ἀλώπεκος from genitive; we won't force a pattern; default to proparox if possible.
      target = (sylls >= 3) ? 'antepenult' : 'penult';
      rule = 'Toy rule: -εκος is rare; defaulting to earlier accent (often proparoxytone if possible).';
    } else if(ending === '-οκος'){
      // Passage: over two syllables -> proparoxytone (rare)
      target = (sylls >= 3) ? 'antepenult' : 'penult';
      rule = 'From the passage: many longer -οκος are proparoxytone (e.g. Καππάδοκος).';
    } else if(ending === '-ακος'){
      target = 'last';
      rule = 'From the passage: possessives in -ακος are oxytone (acute on the last syllable).';
    } else if(ending === '-κος'){
      // If exception list, proparox
      if(exceptionsProparox.has(base)){
        target = (sylls >= 3) ? 'antepenult' : 'penult';
        rule = 'Exception noted by Herodian: this one is proparoxytone.';
      } else {
        // If >2 syllables and penult has alpha (very rough): oxytone
        const penultVowel = (sylls >= 2) ? stripDiacritics(w)[vpos[sylls-2]] : '';
        if(sylls >= 3 && penultVowel === 'α'){
          target = 'last';
          rule = 'From the passage (simplified): longer -κος with α in the penult tend to be oxytone.';
        } else {
          target = 'last';
          rule = 'Default toy guess: oxytone for -κος.';
        }
      }
    } else {
      // Not our domain
      target = (sylls >= 2) ? 'penult' : 'last';
      rule = 'No -κος ending detected; placing a simple accent as a fallback.';
    }

    // Compute vowel index to accent
    let vowelIndexToAccent = -1;
    if(vpos.length === 0){
      return {out: formatOut(raw), ending, rule: 'No vowels detected.'};
    }

    if(target === 'last') vowelIndexToAccent = vpos[vpos.length-1];
    else if(target === 'penult') vowelIndexToAccent = vpos[Math.max(0, vpos.length-2)];
    else if(target === 'antepenult') vowelIndexToAccent = vpos[Math.max(0, vpos.length-3)];

    const accented = addAcuteOnVowelAt(w, vowelIndexToAccent);

    return {out: formatOut(accented), ending, rule};
  }

  function formatOut(s){
    let out = s;
    if(forceLower.checked) out = toLowerGreek(out);
    if(showSyll.checked){
      out += '   (' + roughSyllableSplit(out) + ')';
    }
    return out;
  }

  function render(){
    const res = suggestAccent(inp.value);
    detEnding.textContent = res.ending;
    suggested.textContent = res.out;
    ruleUsed.textContent = res.rule;
    accentHint.textContent = (res.ending === '—')
      ? 'Try something ending in -κος / -ακος / -εκος / -οκος.'
      : 'Click an example chip below, or tweak the word and re-run.';
  }

  function makeChips(){
    chips.innerHTML = '';
    examples.forEach(ex => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'chip';
      b.textContent = ex;
      b.addEventListener('click', () => {
        inp.value = ex;
        render();
        inp.focus();
        inp.setSelectionRange(inp.value.length, inp.value.length);
      });
      chips.appendChild(b);
    });
  }

  btnGo.addEventListener('click', render);
  inp.addEventListener('keydown', (e) => {
    if(e.key === 'Enter') render();
  });
  [keepDiacritics, showSyll, forceLower].forEach(el => el.addEventListener('change', render));

  btnShuffle.addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inp.value = ex;
    render();
    inp.focus();
  });

  makeChips();
  inp.value = 'λιθιακος';
  render();
})();

