const $ = (sel) => document.querySelector(sel);

const inWord = $('#inWord');
const outNorm = $('#outNorm');
const outSyl = $('#outSyl');
const outEnding = $('#outEnding');
const outPenult = $('#outPenult');
const outSuggested = $('#outSuggested');
const outRule = $('#outRule');
const outMorph = $('#outMorph');
const outMorphNote = $('#outMorphNote');
const chkKeepExisting = $('#chkKeepExisting');
const chkShowMarks = $('#chkShowMarks');

const quizWord = $('#quizWord');
const quizResult = $('#quizResult');

// --- Greek helpers (toy-level) ---
const COMBINING = /[\u0300-\u036f]/g;

function stripDiacritics(s){
  return s.normalize('NFD').replace(COMBINING,'').normalize('NFC');
}

function hasAccent(s){
  // acute, grave, circumflex (combining)
  const n = s.normalize('NFD');
  return /[\u0300\u0301\u0342]/.test(n);
}

function normalizeGreek(s){
  return (s||'').trim().replace(/\s+/g,' ');
}

function isVowel(ch){
  return 'αεηιουωΑΕΗΙΟΥΩ'.includes(ch);
}

function roughSyllabify(word){
  // Very rough: count vowel nuclei in stripped form, treating αι/ει/οι/ου/αυ/ευ/ηυ as one.
  const w = stripDiacritics(word);
  const lower = w.toLowerCase();
  const diph = ['αι','ει','οι','ου','αυ','ευ','ηυ','υι'];
  let i=0, syl=[];
  while(i<lower.length){
    const ch = lower[i];
    if(isVowel(ch)){
      let nucleus = ch;
      const two = lower.slice(i,i+2);
      if(diph.includes(two)) { nucleus = two; i+=2; }
      else { i+=1; }
      syl.push(nucleus);
    } else {
      i+=1;
    }
  }
  return syl;
}

function endsWithKos(word){
  const w = stripDiacritics(word).toLowerCase();
  return w.endsWith('κος');
}

function penultChunk(word){
  // Return last 5 letters stripped, to detect -αικος/-οικος/-εικος/-ικος
  const w = stripDiacritics(word).toLowerCase().replace(/[^α-ω]/g,'');
  return w.slice(-5);
}

function classify(word){
  const w = normalizeGreek(word);
  const stripped = stripDiacritics(w);
  const syl = roughSyllabify(stripped);
  const chunk = penultChunk(stripped);

  let ending = '—';
  if(endsWithKos(stripped)) ending = '-κος';

  let penult = 'unknown';
  if(chunk.endsWith('αικος')) penult = 'penult = αι (diphthong)';
  else if(chunk.endsWith('οικος')) penult = 'penult = οι (diphthong)';
  else if(chunk.endsWith('εικος')) penult = 'penult = ει (diphthong)';
  else if(chunk.endsWith('ικος')) penult = 'penult = ι (toy “long i” bucket)';
  else penult = 'other';

  return {w, stripped, syl, ending, penult, chunk};
}

function accentuateToy(word, target){
  // target: 'oxytone'|'parox'|'proparox'
  // We add an ACUTE (combining \u0301) to the vowel nucleus of the target syllable.
  // This is intentionally simplistic.
  const base = stripDiacritics(word);
  const letters = base.normalize('NFD');
  // Build map of vowel nuclei positions in the NFD string.
  const s = letters;
  const vowelIdx = [];
  for(let i=0;i<s.length;i++){
    const ch = s[i];
    if(isVowel(ch)) vowelIdx.push(i);
  }
  if(vowelIdx.length===0) return base;

  let which = vowelIdx.length-1; // last syllable
  if(target==='parox') which = Math.max(0, vowelIdx.length-2);
  if(target==='proparox') which = Math.max(0, vowelIdx.length-3);

  const idx = vowelIdx[which];
  // Insert combining acute after the vowel.
  const out = s.slice(0, idx+1) + '\u0301' + s.slice(idx+1);
  return out.normalize('NFC');
}

function chooseRule(info){
  const sylCount = info.syl.length;
  const w = info.stripped;
  if(!endsWithKos(w)){
    return {rule:'not-kos', target:null, explain:'Input does not end in -κος (toy only handles -κος words).'};
  }

  // Herodian-ish heuristics
  if(info.chunk.endsWith('αικος') || info.chunk.endsWith('οικος')){
    return {rule:'ai/oi-nonadj', target:'proparox', explain:'Penult looks like -αι- or -οι-. Herodian: non-adjectival -αικος/-οικος tends to be proparoxytone.'};
  }
  if(info.chunk.endsWith('εικος')){
    return {rule:'eikos', target:'oxytone', explain:'Penult looks like -ει-. Herodian: -εικος tends to be oxytone (e.g. Κεραμεικός).'};
  }
  if(info.chunk.endsWith('ικος') && sylCount>=3){
    return {rule:'ikos-longi', target:'parox', explain:'Looks like -ικος with 3+ syllables. Herodian: with long ι in the penult, accent tends to fall on the penult (paroxytone).'};
  }

  // fallback
  if(sylCount<=2){
    return {rule:'short', target:'oxytone', explain:'Very short word: toy defaults to oxytone.'};
  }
  return {rule:'default', target:'parox', explain:'No special pattern detected; toy defaults to paroxytone.'};
}

function render(){
  const info = classify(inWord.value);
  outNorm.textContent = info.stripped || '—';
  outSyl.textContent = info.syl.length ? info.syl.join(' · ') + `  (${info.syl.length})` : '—';
  outEnding.textContent = info.ending;
  outPenult.textContent = info.penult;

  const choice = chooseRule(info);
  if(choice.rule==='not-kos'){
    outSuggested.textContent = '—';
    outRule.innerHTML = `<span class="bad">${choice.explain}</span>`;
    return;
  }

  const keep = chkKeepExisting.checked;
  const show = chkShowMarks.checked;

  let suggested;
  if(keep && hasAccent(info.w)){
    suggested = info.w;
    outRule.innerHTML = `Existing accent detected → kept. (Toy rule would suggest <b>${choice.target}</b>.)<br><span class="small">${choice.explain}</span>`;
  } else {
    suggested = accentuateToy(info.w, choice.target);
    outRule.innerHTML = `<b>Suggested:</b> ${choice.target}.<br><span class="small">${choice.explain}</span>`;
  }

  if(!show) suggested = stripDiacritics(suggested);
  outSuggested.textContent = suggested || '—';
}

function morphToItis(word){
  const w = stripDiacritics(normalizeGreek(word));
  if(!endsWithKos(w)){
    return {res:'—', note:'Needs a word ending in -κος.'};
  }
  // crude: -κος -> -κῖτις (as in Ἀμάληκος → Ἀμαληκῖτις)
  const stem = w.slice(0, -2); // remove ος
  const res = stem + 'ῖτις';
  return {res, note:'Toy derivation: -κος → -κῖτις (ethnic/feminine-style). Accent not fully handled.'};
}

function expandEikos(word){
  const w = stripDiacritics(normalizeGreek(word));
  const low = w.toLowerCase();
  if(!low.endsWith('εικος')){
    return {res:'—', note:'Only expands words ending in -εικος.'};
  }
  const res = w.slice(0, -4) + 'ειακος';
  return {res, note:'Toy “unsyncope”: -εικος → -ειακος (cf. βοειακός → βοεικός).'};
}

const EXAMPLES = [
  'Πάταικος','Φάλαικος','Μίθαικος','σόλοικος','μόνοικος',
  'Κεραμεικός','δαρεικός','βοεικός','Δεκελεικός',
  'Φιλόνικος','Ἑλλάνικος','Ἀριστόνικος','Εὔνικος',
  'ἄγροικος','Εὐβοικός','Ἰωλκός','Ἀρδησκός','Πίθηκος'
];

function randomExample(){
  const w = EXAMPLES[Math.floor(Math.random()*EXAMPLES.length)];
  inWord.value = w;
  render();
}

// --- Quiz ---
let currentQuiz = null;
function quizPick(){
  const w = EXAMPLES[Math.floor(Math.random()*EXAMPLES.length)];
  const info = classify(w);
  const choice = chooseRule(info);
  currentQuiz = {w, choice};
  quizWord.textContent = w;
  quizResult.textContent = '—';
  document.querySelectorAll('input[name=q]').forEach(r=>r.checked=false);
}

function revealQuiz(){
  if(!currentQuiz) return;
  const picked = document.querySelector('input[name=q]:checked')?.value;
  const target = currentQuiz.choice.target;
  const map = {oxytone:'oxytone', parox:'parox', proparox:'proparox'};
  const ok = picked && picked===map[target];
  const sug = accentuateToy(currentQuiz.w, target);
  quizResult.innerHTML = `${ok?'<span class="good">Match!</span>':'<span class="bad">Not this time.</span>'} Toy chooses <b>${target}</b> → <span class="greek">${sug}</span><br><span class="small">${currentQuiz.choice.explain}</span>`;
}

// --- Events ---
$('#btnAnalyze').addEventListener('click', render);
inWord.addEventListener('input', render);
chkKeepExisting.addEventListener('change', render);
chkShowMarks.addEventListener('change', render);

$('#btnRandom').addEventListener('click', randomExample);
$('#btnStrip').addEventListener('click', ()=>{
  inWord.value = stripDiacritics(inWord.value);
  render();
});
$('#btnToItis').addEventListener('click', ()=>{
  const {res,note} = morphToItis(inWord.value);
  outMorph.textContent = res;
  outMorphNote.textContent = note;
});
$('#btnUnsync').addEventListener('click', ()=>{
  const {res,note} = expandEikos(inWord.value);
  outMorph.textContent = res;
  outMorphNote.textContent = note;
});

$('#btnNewQuiz').addEventListener('click', quizPick);
$('#btnReveal').addEventListener('click', revealQuiz);

// init
randomExample();
quizPick();
render();

