:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --card:#1e2240;
  --ink:#eef0ff;
  --muted:#b9bce3;
  --faint:#8b8fc7;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --good:#34d399;
  --warn:#fbbf24;
  --bad:#fb7185;
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Noto Sans", "Liberation Sans", sans-serif;
}

*{box-sizing:border-box}

body{
  margin:0;
  font-family:var(--sans);
  background: radial-gradient(1200px 700px at 20% 0%, #1a1f3d 0%, var(--bg) 55%), var(--bg);
  color:var(--ink);
}

.wrap{max-width:980px;margin:0 auto;padding:18px 14px 28px}

.top h1{margin:0 0 6px;font-size:20px;letter-spacing:.2px}
