.row{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}

.btn{
  border:1px solid rgba(255,255,255,.14);
  background: rgba(255,255,255,.06);
  color:var(--ink);
  padding:8px 10px;
  border-radius:12px;
  cursor:pointer;
  font-size:13px;
}
.btn:hover{background: rgba(255,255,255,.10)}
.btn.primary{border-color: rgba(125,211,252,.45); background: rgba(125,211,252,.14)}
.btn.primary:hover{background: rgba(125,211,252,.20)}

.help{margin-top:10px}
.help summary{cursor:pointer;color:var(--accent);font-size:13px}
.helpBody{color:var(--muted);font-size:13px;line-height:1.35}
.helpBody ul{margin:8px 0 0 18px}

.out{display:grid;grid-template-columns: 1fr;gap:8px}

.k{font-size:12px;color:var(--muted)}
.v{padding:8px 10px;border-radius:12px;background: rgba(0,0,0,.18);border:1px solid rgba(255,255,255,.10)}
.v.big{font-size:20px;letter-spacing:.2px}

.mono{font-family:var(--mono)}

.pill{display:inline-block;padding:1px 8px;border-radius:999px;border:1px solid rgba(255,255,255,.14);background: rgba(167,139,250,.12);color: #e9e3ff}

.mini{margin-top:12px;padding-top:10px;border-top:1px solid rgba(255,255,255,.10)}
.miniTitle{font-size:12px;color:var(--muted);margin-bottom:6px}

.chip{
  display:inline-flex;align-items:center;gap:8px;
  padding:6px 10px;border-radius:999px;
  border:1px solid rgba(255,255,255,.12);
  background: rgba(0,0,0,.12);
  font-size:12px;color:var(--ink);
}
.chip input{accent-color: var(--accent)}

.note{margin:8px 0 0;color:var(--faint);font-size:12px;line-height:1.35}

.examples{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
.ex{
  cursor:pointer;
