(() => {
  const $ = (sel, el=document) => el.querySelector(sel);
  const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

  const inp = $('#inp');
  const normEl = $('#norm');
  const endsEl = $('#ends');
  const guessEl = $('#guess');
  const suggestEl = $('#suggest');
  const syllEl = $('#syll');

  const examples = [
    {w:'Κυζικος', hint:'proper name (city) → proparoxytone'},
    {w:'Ὠρικος', hint:'proper name (city/harbor) → proparoxytone'},
    {w:'Ανθερικος', hint:'proper name-like example → proparoxytone'},
    {w:'Θορικος', hint:'often oxytone per Herodian (variation!)'},
    {w:'Γαλατικος', hint:'possessive adj. → oxytone'},
    {w:'Ιταλικος', hint:'possessive adj. → oxytone'},
    {w:'Ομηρικος', hint:'possessive adj. → oxytone'},
    {w:'Τρωικος', hint:'possessive adj. → oxytone'},
    {w:'Αττικος', hint:'special case (euphony) → often proparoxytone in practice'},
    {w:'Χαιρωνικος', hint:'possessive/ethnic adj. → oxytone'},
  ];

  // --- Greek helpers ---
  const combining = /[\u0300-\u036f]/g;
  const tonosMap = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ',
    'ϊ':'ΐ','ϋ':'ΰ','Ϊ':'Ϊ','Ϋ':'Ϋ'
  };

  function stripDiacritics(s){
    // NFD splits polytonic into base + combining marks.
    return s.normalize('NFD').replace(combining,'').normalize('NFC');
  }

  function normalizeGreek(s){
    // Lower-level normalization: remove diacritics, normalize final sigma.
    let t = stripDiacritics(s).trim();
    // normalize sigmas: any word-final σ -> ς
    t = t.replace(/σ\b/g,'ς');
    return t;
  }

  function isGreekLetter(ch){
    return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(ch);
  }

  function tokenizeWords(s){
    // keep Greek sequences; ignore punctuation.
    const out=[];
    let cur='';
    for (const ch of s){
      if (isGreekLetter(ch)) cur += ch;
      else {
        if (cur) out.push(cur);
        cur='';
      }
    }
    if (cur) out.push(cur);
    return out;
  }

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ','ϊ','ϋ','ΐ','ΰ','Α','Ε','Η','Ι','Ο','Υ','Ω','Ά','Έ','Ή','Ί','Ό','Ύ','Ώ','Ϊ','Ϋ']);

  function syllableSketch(word){
    // Very rough: split before each vowel group.
    const w = word;
    const parts=[];
    let cur='';
    let inVowel=false;
    for (let i=0;i<w.length;i++){
      const ch=w[i];
      const isV=vowels.has(ch);
      if (isV){
        if (!inVowel && cur){
          parts.push(cur);
          cur='';
        }
        inVowel=true;
        cur += ch;
      } else {
        inVowel=false;
        cur += ch;
      }
    }
    if (cur) parts.push(cur);
    // Merge tiny leading consonant chunk into next if needed
    if (parts.length>=2 && !containsVowel(parts[0]) && containsVowel(parts[1])){
      parts[1] = parts[0] + parts[1];
      parts.shift();
    }
    return parts;
  }

  function containsVowel(s){
    for (const ch of s) if (vowels.has(ch)) return true;
    return false;
  }

  function addAcuteToLastVowel(chunk){
    // Add acute to the last vowel letter in chunk.
    const arr = Array.from(chunk);
    for (let i=arr.length-1;i>=0;i--){
      const base = stripDiacritics(arr[i]);
      if (vowels.has(arr[i]) || vowels.has(base)){
        const repl = tonosMap[arr[i]] || tonosMap[base];
        if (repl){
          arr[i]=repl;
          return arr.join('');
        }
      }
    }
    return chunk;
  }

  function accentByPosition(word, position){
    // position: 'oxytone' (last), 'paroxytone' (penult), 'proparoxytone' (antepenult)
    const sk = syllableSketch(word);
    if (sk.length === 0) return {accented: word, sketch: '—'};

    let idx;
    if (position==='oxytone') idx = sk.length-1;
    else if (position==='paroxytone') idx = Math.max(0, sk.length-2);
    else idx = Math.max(0, sk.length-3);

    const acc = sk.map((p,i)=> i===idx ? addAcuteToLastVowel(p) : p).join('');
    const sketch = sk.map((p,i)=> i===idx ? `[${p}]` : p).join(' · ');
    return {accented: acc, sketch};
  }

  function endsWithIkos(normWord){
    const w = normWord;
    return /ικος$/i.test(w);
  }

  function guessType(normWord){
    // playful heuristic: if starts with uppercase -> proper; if contains -αγορ-/-ομηρ- etc -> possessive; else unknown.
    const raw = normWord;
    const hasUpper = /[Α-Ω]/.test(raw[0] || '');
    const lower = raw.toLowerCase();

    const possessiveClues = ['ομηρ','πυθαγορ','βασιλ','δεσποτ','δουλ','κλωπ','ελλην','ελλαδ','βαρβαρ','ταυρ','μηδ','λιβυστ','γαλατ','ιταλ','τρω','χαιρων','χαον','ψυλλ','καρ','γαδειρ'];
    const properClues = ['κυζ','ωρ','νηρ','σινδ','ασφοδ','ομβρ','θορ'];

    const poss = possessiveClues.some(c => lower.includes(c));
    const prop = properClues.some(c => lower.includes(c));

    if (poss && !prop) return {type:'poss', why:'Looks like an ethnic/possessive adjective from the list (toy clue).'};
    if (prop && !poss) return {type:'proper', why:'Looks like a place/name from the list (toy clue).'};
    if (hasUpper) return {type:'proper', why:'Starts with a capital letter → often treated as a proper name in this toy.'};
    return {type:'unknown', why:'No strong clue; choose a mode to compare patterns.'};
  }

  function mode(){
    const r = $('input[name="mode"]:checked');
    return r ? r.value : 'auto';
  }

  function analyze(){
    const raw = inp.value.trim();
    if (!raw){
      normEl.textContent = '—';
      endsEl.textContent = '—';
      guessEl.textContent = '—';
      suggestEl.textContent = '—';
      syllEl.textContent = '—';
      return;
    }

    const words = tokenizeWords(raw);
    const first = words[0] || raw;
    const norm = normalizeGreek(first);

    normEl.textContent = norm || '—';

    const isIkos = endsWithIkos(norm);
    endsEl.innerHTML = isIkos ? `<span class="pill" style="background:rgba(52,211,153,.12)">yes</span>` : `<span class="pill" style="background:rgba(251,113,133,.12)">no</span>`;

    let chosen;
    let why = '';

    const m = mode();
    if (m==='proper') { chosen = 'proparoxytone'; why = 'Forced proper-name pattern (accent on antepenult).'; }
    else if (m==='poss') { chosen = 'oxytone'; why = 'Forced possessive-adjective pattern (accent on last).'; }
    else {
      const g = guessType(norm);
      if (g.type==='proper') { chosen = 'proparoxytone'; }
      else if (g.type==='poss') { chosen = 'oxytone'; }
      else { chosen = isIkos ? 'oxytone' : 'paroxytone'; }
      why = g.why;
    }

    const {accented, sketch} = accentByPosition(norm, chosen);

    const label = (chosen==='proparoxytone') ? 'Proper-name style → proparoxytone' :
                  (chosen==='oxytone') ? 'Possessive-adj. style → oxytone' :
                  'Neutral → paroxytone';

    guessEl.innerHTML = `<div><strong>${label}</strong></div><div class="small" style="color:var(--muted);margin-top:4px">${escapeHtml(why)}</div>`;
    suggestEl.textContent = accented;
    syllEl.textContent = sketch;
  }

  function escapeHtml(s){
    return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  function mountExamples(){
    const box = $('#examples');
    box.innerHTML = '';
    for (const ex of examples){
      const b = document.createElement('button');
      b.className = 'ex mono';
      b.type = 'button';
      b.textContent = ex.w;
      b.title = ex.hint;
      b.addEventListener('click', () => { inp.value = ex.w; analyze(); inp.focus(); });
      box.appendChild(b);
    }
  }

  $('#btnAnalyze').addEventListener('click', analyze);
  $('#btnClear').addEventListener('click', () => { inp.value=''; analyze(); inp.focus(); });
  $('#btnRandom').addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inp.value = ex.w;
    analyze();
    inp.focus();
  });

  inp.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') analyze();
  });
  $$('input[name="mode"]').forEach(r => r.addEventListener('change', analyze));

  mountExamples();
  inp.value = 'Κυζικος';
  analyze();
})();

