  --acc:#7dd3fc;
  --acc2:#a78bfa;
  --bad:#fb7185;
  --good:#34d399;
  --mono: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Arial, "Noto Sans", "Liberation Sans", sans-serif;
  --ser: ui-serif, "Noto Serif", "Times New Roman", Times, serif;
}
*{box-sizing:border-box}
.wrap{max-width:980px;margin:24px auto;padding:0 16px;color:var(--ink);font-family:var(--mono)}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, #1b1f3a 0%, var(--bg) 55%)}
.hdr{display:flex;gap:16px;align-items:flex-end;justify-content:space-between;margin-bottom:14px}
h1{font-size:22px;margin:0;letter-spacing:.2px}
