.in{width:100%;padding:10px 12px;border-radius:12px;border:1px solid var(--line);background:#0c0f1d;color:var(--ink);font-size:16px;font-family:var(--ser)}
.in:focus{outline:none;border-color:rgba(125,211,252,.7);box-shadow:0 0 0 3px rgba(125,211,252,.15)}
.btnrow{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}
