.mline{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.pill{display:inline-flex;align-items:center;gap:6px;padding:5px 10px;border-radius:999px;border:1px solid rgba(167,139,250,.35);background:rgba(167,139,250,.10);font-family:var(--mono);font-size:12px;color:#efeaff}
