.small{opacity:.95}
@media (max-width:720px){
  .grid{grid-template-columns:1fr}
  .btnrow{justify-content:flex-start}
  .kv{grid-template-columns:1fr}
}

passages.gadget_js:
const $ = (s)=>document.querySelector(s);

const examples = [
  "Κωρυκος",
  "Κώρυκος",
  "Ἴβυκος",
  "Αμυκος",
  "Δαμασκος",
  "Δαμασκός",
  "παιδισκος",
  "ὀβελίσκος",
  "νεανισκος",
  "Σμυρναικος",
  "Πειραικος",
  "Ακαδημαικος",
  "Γαλαδραϊκός",
  "σατυρίσκος",
  "Δορίσκος"
];

// --- Greek helpers ---
const combining = /[\u0300-\u036f]/g;

function nfd(s){return s.normalize('NFD');}
function nfc(s){return s.normalize('NFC');}

function stripDiacritics(s){
  return nfc(nfd(s).replace(combining, ''));
}

function stripSpaces(s){return s.replace(/\s+/g,' ').trim();}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code>=0x0370 && code<=0x03FF) || (code>=0x1F00 && code<=0x1FFF);
}

function onlyGreekWord(s){
  // take first token that contains Greek letters
  const parts = stripSpaces(s).split(' ');
  for(const p of parts){
    if([...p].some(isGreekLetter)) return p;
  }
  return stripSpaces(s);
}

const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

function countVowelNuclei(word){
  // crude: count vowel letters in stripped form, treating diphthongs as 1 nucleus
  const w = stripDiacritics(word);
  const chars = [...w];
  let nuclei = 0;
  for(let i=0;i<chars.length;i++){
    const c = chars[i];
    const n = chars[i+1]||'';
    const pair = (c+n).toLowerCase();
    if(vowels.has(c)){
      // diphthongs
      if(["αι","ει","οι","υι","αυ","ευ","ου","ηυ"].includes(pair)){
        nuclei++; i++; continue;
      }
      nuclei++;
    }
  }
  return nuclei;
}

function lastIndexOfVowelNucleus(word){
  // return index in codepoints of start of last vowel nucleus (rough)
  const w = stripDiacritics(word);
  const chars = [...w];
  for(let i=chars.length-1;i>=0;i--){
    const c = chars[i];
    if(vowels.has(c)) return i;
  }
  return -1;
}

function nthFromEndVowelIndex(word, nFromEnd){
  // nFromEnd=1 => last nucleus start index; 2 => penult nucleus start index
  const w = stripDiacritics(word);
  const chars = [...w];
  let seen = 0;
  for(let i=chars.length-1;i>=0;i--){
    if(vowels.has(chars[i])){
      seen++;
      if(seen===nFromEnd) return i;
    }
  }
  return -1;
}

function applyAcuteAtVowel(word, vowelIndex){
  // add combining acute to that vowel letter (first codepoint at index)
  if(vowelIndex<0) return word;
  const w = nfd(word);
  // map vowelIndex in stripped NFC to index in codepoints of stripped; approximate by using NFC codepoints
  const base = stripDiacritics(word);
  const baseChars = [...base];
  const targetChar = baseChars[vowelIndex];
  if(!targetChar) return word;

  // find corresponding occurrence in NFD stream by counting Greek letters in base
  const nfdChars = [...w];
  let basePos = -1;
  let nfdPos = 0;
  // Build base from NFD by removing combining marks; track positions
  let baseCount = -1;
  for(let i=0;i<nfdChars.length;i++){
    const ch = nfdChars[i];
    if(ch.match(combining)) continue;
    baseCount++;
    if(baseCount===vowelIndex){
      nfdPos = i;
      break;
    }
  }

  // Insert acute after the base letter at nfdPos, but remove any existing accent marks on that letter
  // Remove acute/grave/circumflex on that vowel cluster
  const accentMarks = new Set(['\u0301','\u0300','\u0342','\u0341']);
  let j = nfdPos+1;
  while(j<nfdChars.length && nfdChars[j].match(combining)){
    if(accentMarks.has(nfdChars[j])) nfdChars.splice(j,1);
    else j++;
  }
  nfdChars.splice(nfdPos+1,0,'\u0301');
  return nfc(nfdChars.join(''));
}

function toMonotonic(s){
  // crude: keep only tonos (acute) and diaeresis; drop other polytonic marks
  const keep = new Set(['\u0301','\u0308']);
  const out = [];
  for(const ch of nfd(s)){
    if(ch.match(combining)){
      if(keep.has(ch)) out.push(ch);
    } else out.push(ch);
  }
  return nfc(out.join(''));
}

function ensureDiaeresisInAikos(word, show){
  // If ends with -αικος/-aikos, optionally show -αϊκος (diaeresis on iota) to signal hiatus.
  // This is a toy: we only target the sequence αι + κός-ish.
  const w = nfd(word);
  const base = stripDiacritics(word);
  const low = base.toLowerCase();
  if(!low.includes('αικ')) return word;

  // find occurrences of iota preceded by alpha in "αικ" sequence
  let chars = [...nfd(word)];
  // Work on NFC base positions for simplicity: replace in NFC then normalize
  let n = nfc(chars.join(''));
  if(show){
    // replace αι with αϊ when followed by κ (first match)
    n = n.replace(/αι(?=κ)/i, (m)=> m[0] + 'ϊ');
  } else {
    // remove diaeresis if present in that spot
    n = n.replace(/αϊ(?=κ)/i, (m)=> m[0] + 'ι');
  }
  return n;
}

function classify(word){
  const base = stripDiacritics(word);
  const low = base.toLowerCase();

  // detect endings
  const ends = (s)=>low.endsWith(s);

  // -σκος group
  if(ends('σκος')){
    // penult vowel letter (rough): look at 2nd from end vowel
    const penV = nthFromEndVowelIndex(base, 2);
    const penChar = penV>=0 ? [...base][penV].toLowerCase() : '';
    const hasIY = (penChar==='ι' || penChar==='υ');

    // special oxytone place-names like Δαμασκός etc.
    const knownOxy = ['δαμασκος','αρδησκος','δραβησκος'];
    if(knownOxy.includes(low)){
      return {rule:"-σκός place-name (oxytone)", accent:"ultima", confidence:"high", note:"Herodian mentions Δαμασκός, Ἀρδησκός, Δραβησκός as oxytone."};
    }

    if(hasIY){
      return {rule:"-σκος with ι/υ in penult → paroxytone", accent:"penult", confidence:"high", note:"Matches Herodian’s rule: -σκος with ι/υ in the penult tends to be accented on the penult."};
    }
    return {rule:"-σκος (default guess)", accent:"penult", confidence:"medium", note:"Toy default: many -σκος forms are paroxytone; exceptions exist."};
  }

  // -υκος group
  if(ends('υκος')){
    // If looks like adjective in -υκός (e.g. Λιβυκός) we might guess oxytone.
    const adjLike = ['λιβυκος','θηλυκος','αλυκος'];
    if(adjLike.includes(low)){
      return {rule:"-υκός adjective (oxytone)", accent:"ultima", confidence:"medium", note:"Herodian notes Λιβυκός/θηλυκός/ἁλυκός are oxytone (having feminine forms)."};
    }
    // proper-name-ish: if >2 syllables, show penult accent as toy ‘βαρύνει’ simplification
    const syl = countVowelNuclei(base);
    if(syl>=3){
      return {rule:"-υκος (proper name, >2 syllables) → ‘barytone’", accent:"penult", confidence:"medium", note:"Herodian: many -υκος proper names (esp. >2 syllables) are ‘barytone’. Toy renders this as penult accent."};
    }
    return {rule:"-υκος (short) default", accent:"penult", confidence:"low", note:"Short -υκος words vary; toy guesses penult."};
  }

  // -ικος / -αικος / -ϊκος group
  if(ends('ικος') || ends('ικός') || ends('ικὸς') || ends('ικός') || low.includes('αικ')){
    // If ends with -ικος and has preceding αι sequence, treat as -αϊκός type
    return {rule:"-ϊκός ethnic/adjective", accent:"ultima", confidence:"medium", note:"Toy assumes -ικός adjectives are oxytone; passage mentions -αϊκός with contraction (e.g. Σμυρναϊκός)."};
  }

  // -λος disyllabic toy
  if(ends('λος')){
    const syl = countVowelNuclei(base);
    if(syl===2){
      return {rule:"disyllabic -λος (toy barytone)", accent:"penult", confidence:"low", note:"Herodian: many disyllabic -λος with two short syllables are barytone; quantity is not computed here."};
    }
  }

  return {rule:"no specific rule matched", accent:"none", confidence:"low", note:"Try an ending like -υκος, -σκος, or -ϊκός."};
}

function accentWord(word, accentPos){
  const base = stripDiacritics(word);
  if(accentPos==='ultima'){
    const idx = nthFromEndVowelIndex(base, 1);
    return applyAcuteAtVowel(base, idx);
  }
  if(accentPos==='penult'){
    const idx = nthFromEndVowelIndex(base, 2);
    return applyAcuteAtVowel(base, idx);
  }
  return base;
}

function prosodyMeter(word, accentPos){
  const base = stripDiacritics(word);
  const syl = countVowelNuclei(base);
  let accentLabel = "—";
  if(accentPos==='ultima') accentLabel = "oxytone (ultima)";
  if(accentPos==='penult') accentLabel = "paroxytone (penult)";
  if(accentPos==='none') accentLabel = "(no guess)";

  // show syllable dots and highlight accent target
  let target = null;
  if(accentPos==='ultima') target = syl;
  if(accentPos==='penult') target = syl-1;

  const pills = [];
  for(let i=1;i<=Math.max(syl,1);i++){
    const hot = (target===i);
    pills.push(`<span class="pill">${hot?'<span class="dot2"></span>':'<span class="dot"></span>'}συλ ${i}${hot?' · τόνος':''}</span>`);
  }

  return {syl, accentLabel, pills: pills.join('')};
}

function render(){
  const raw = $('#in').value;
  const token = onlyGreekWord(raw);
  const dia = $('#dia').checked;
  const mono = $('#mono').checked;

  if(!token){
    $('#out').innerHTML = `<div class="note">Type a Greek word above.</div>`;
    return;
  }

  const cls = classify(token);
  let suggested = accentWord(token, cls.accent);
  suggested = ensureDiaeresisInAikos(suggested, dia);
  let shown = suggested;
  if(mono) shown = toMonotonic(shown);

  const meter = prosodyMeter(suggested, cls.accent);
  const confBadge = cls.confidence==='high'
    ? '<span class="badge good">confidence: high</span>'
    : (cls.confidence==='medium'
      ? '<span class="badge">confidence: medium</span>'
      : '<span class="badge warn">confidence: low</span>');

  const base = stripDiacritics(token);
  const baseShown = mono ? toMonotonic(base) : base;

  $('#out').innerHTML = `
    <div class="kv">
      <div class="k">Input (stripped)</div>
      <div class="v">${escapeHtml(baseShown)}</div>

      <div class="k">Rule guess</div>
      <div class="v">${escapeHtml(cls.rule)} ${confBadge}</div>

      <div class="k">Suggested accent</div>
      <div class="v"><span style="color:var(--acc)">${escapeHtml(shown)}</span></div>

      <div class="k">Why</div>
      <div class="v" style="font-size:14px;color:var(--muted);font-family:var(--mono)">${escapeHtml(cls.note)}</div>
    </div>

    <div class="meter">
      <div class="mline"><span class="badge">syllables: ${meter.syl}</span><span class="badge">${escapeHtml(meter.accentLabel)}</span></div>
      <div class="mline" style="margin-top:8px">${meter.pills}</div>
    </div>
  `;
}

function escapeHtml(s){
  return String(s)
    .replaceAll('&','&amp;')
    .replaceAll('<','&lt;')
    .replaceAll('>','&gt;')
    .replaceAll('"','&quot;')
    .replaceAll("'",'&#39;');
}

$('#an').addEventListener('click', render);
$('#in').addEventListener('keydown', (e)=>{ if(e.key==='Enter') render(); });
$('#dia').addEventListener('change', render);
$('#mono').addEventListener('change', render);

$('#rnd').addEventListener('click', ()=>{
  const pick = examples[Math.floor(Math.random()*examples.length)];
  $('#in').value = pick;
  render();
});

$('#clr').addEventListener('click', ()=>{
  $('#in').value = '';
  $('#out').innerHTML = `<div class="note">Cleared. Try: <span class="ex">Δαμασκος</span>, <span class="ex">παιδισκος</span>, <span class="ex">Κωρυκος</span>, <span class="ex">Σμυρναικος</span>.</div>`;
  $('#in').focus();
});

// initial
$('#out').innerHTML = `<div class="note">Try an example from the passage: <span class="ex">Δαμασκος</span> (oxytone), <span class="ex">παιδισκος</span> (-σκος with ι), <span class="ex">Κωρυκος</span> (-υκος), <span class="ex">Σμυρναικος</span> (-αϊκός).</div>`;

