const $ = (s)=>document.querySelector(s);

const examples = [
  {w:"Μᾶλος", note:"proper name; recessive in passage", tag:"r"},
  {w:"κᾶλος", note:"Homeric; recessive", tag:"r"},
  {w:"Πυλος", note:"place-name; try without accents", tag:"r"},
  {w:"χυλος", note:"χ- word; passage says acute (χυλός)", tag:"x"},
  {w:"χιλος", note:"χ- word; passage says acute (χιλός)", tag:"x"},
  {w:"θολος", note:"toy’s ‘distinction’ acute (θολός ‘ink’)", tag:"d"},
  {w:"ολος", note:"toy’s ‘distinction’ acute (ὀλός ‘destructive’)", tag:"d"},
  {w:"ψιλος", note:"tri-gender; passage treats as long penult; try it", tag:"r"}
];

// --- Greek helpers ---
const tonos = "\u0301"; // acute combining
const perispomeni = "\u0342"; // circumflex combining
const dialytika = "\u0308";

const vowels = new Set(["α","ε","η","ι","ο","υ","ω","ά","έ","ή","ί","ό","ύ","ώ","ϊ","ϋ","ΐ","ΰ","ᾶ","ῖ","ῦ","ῶ"]);

function stripDiacritics(s){
  // remove combining marks + precomposed tonos/perispomeni by NFD
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function lowerGreek(s){
  return s.toLowerCase();
}

function endsWithLos(base){
  const b = lowerGreek(stripDiacritics(base));
  return b.endsWith("λος") || b.endsWith("λοσ");
}

function isDiphthong(a,b){
  const x = a+b;
  return ["αι","ει","οι","υι","αυ","ευ","ου","ηυ"].includes(x);
}

function penultNucleusIndex(word){
  // crude: find the vowel (or diphthong) immediately before the final -λος
  const w = lowerGreek(stripDiacritics(word));
  let s = w;
  if(s.endsWith("λοσ")) s = s.slice(0,-3);
  else if(s.endsWith("λος")) s = s.slice(0,-3);
  else return null;

  // find last vowel/diphthong in s
  for(let i=s.length-1;i>=0;i--){
    const ch = s[i];
    if(vowels.has(ch)){
      // check diphthong with previous char
      if(i>0 && vowels.has(s[i-1]) && isDiphthong(s[i-1], s[i])){
        return {start:i-1, len:2};
      }
      return {start:i, len:1};
    }
  }
  return null;
}

function classifyQuantity(nucleus){
  // nucleus is string of 1-2 vowel letters (no diacritics)
  if(!nucleus) return "unknown";
  if(nucleus.length===2) return "long"; // diphthong
  const v = nucleus;
  if(v==="η"||v==="ω") return "long";
  if(v==="ε"||v==="ο") return "short";
  if(v==="α"||v==="ι"||v==="υ") return "either";
  return "unknown";
}

function addAccentOnPenult(original, accentType){
  // accentType: 'acute' or 'circ'
  const nfd = original.normalize('NFD');
  const plain = stripDiacritics(original);
  const idxInfo = penultNucleusIndex(plain);
  if(!idxInfo) return original;

  // Map plain index to NFD index by walking characters and skipping combining marks
  let plainPos = 0;
  let insertAtNfd = null;
  for(let i=0;i<nfd.length;i++){
    const c = nfd[i];
    const isComb = /[\u0300-\u036f]/.test(c);
    if(isComb) continue;
    if(plainPos === idxInfo.start + idxInfo.len - 1){
      // insert after last base vowel of nucleus
      insertAtNfd = i+1;
      break;
    }
    plainPos++;
  }
  if(insertAtNfd==null) return original;

  const mark = accentType==='circ' ? perispomeni : tonos;
  const out = (nfd.slice(0,insertAtNfd) + mark + nfd.slice(insertAtNfd)).normalize('NFC');
  return out;
}

function suggestAccent(word){
  const raw = word.trim();
  if(!raw) return {ok:false, out:"—", why:"Type a Greek word."};
  if(!endsWithLos(raw)){
    return {ok:false, out:raw, why:"This toy only plays with words ending in -λος."};
  }

  const base = lowerGreek(stripDiacritics(raw));

  // toy “distinction” list from passage discussion
  const distinction = new Set(["θολος","ολος"]);
  if(distinction.has(base)){
    const out = addAccentOnPenult(stripDiacritics(raw), 'acute');
    return {ok:true, out, why:"Toy rule: ‘distinction’ case mentioned in the passage → acute on the penult (θολός, ὀλός).", tag:"d"};
  }

  // χ- exception (passage: χυλός, χιλός)
  if(base.startsWith("χ")){
    const out = addAccentOnPenult(stripDiacritics(raw), 'acute');
    return {ok:true, out, why:"Toy rule: starts with χ- → often acute on the penult in this passage (χυλός, χιλός).", tag:"x"};
  }

  // otherwise: recessive-ish: if penult nucleus long/either -> circumflex; if short -> acute
  const plain = stripDiacritics(raw);
  const idx = penultNucleusIndex(plain);
  let nucleus = null;
  if(idx){
    const p = lowerGreek(stripDiacritics(plain));
    nucleus = p.slice(idx.start, idx.start+idx.len);
  }
  const q = classifyQuantity(nucleus);

  if(q==="short"){
    const out = addAccentOnPenult(plain, 'acute');
    return {ok:true, out, why:"Toy rule: penult looks short → acute on the penult (very rough).", tag:"r"};
  } else {
    const out = addAccentOnPenult(plain, 'circ');
    return {ok:true, out, why:"Toy rule: penult looks long (or ‘either’) → circumflex on the penult (recessive-ish).", tag:"r"};
  }
}

function renderTable(){
  const host = $("#table");
  host.innerHTML = "";
  const header = document.createElement('div');
  header.className = 'trow';
  header.innerHTML = `<div class="cell"><b>Input</b></div><div class="cell"><b>Suggested output</b></div>`;
  host.appendChild(header);

  for(const ex of examples){
    const sug = suggestAccent(ex.w);
    const row = document.createElement('div');
    row.className = 'trow';
    const tagClass = ex.tag;
    const tagLabel = tagClass==='x' ? 'χ-' : (tagClass==='d' ? 'distinction' : 'recessive');
    row.innerHTML = `
      <div class="cell"><span>${ex.w}</span><span class="tag ${tagClass}">${tagLabel}</span><div class="sub" style="margin-top:4px">${ex.note}</div></div>
      <div class="cell"><span style="font-size:16px;font-weight:700">${sug.out}</span><div class="sub" style="margin-top:4px">${sug.why}</div></div>
    `;
    host.appendChild(row);
  }
}

function renderChips(){
  const host = $("#chips");
  for(const ex of examples){
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip';
    b.textContent = ex.w;
    b.addEventListener('click', ()=>{
      $("#inp").value = ex.w;
      run();
      $("#inp").focus();
    });
    host.appendChild(b);
  }
}

function run(){
  const w = $("#inp").value;
  const res = suggestAccent(w);
  $("#accented").textContent = res.out;
  $("#explain").textContent = res.why;
}

$("#btn").addEventListener('click', run);
$("#inp").addEventListener('keydown', (e)=>{ if(e.key==="Enter") run(); });

renderChips();
renderTable();

