const $ = (sel) => document.querySelector(sel);

// --- Greek helpers (very small, heuristic) ---
const combining = /[\u0300-\u036f]/g;

function nfd(s){ return (s||"").normalize('NFD'); }
function nfc(s){ return (s||"").normalize('NFC'); }

function stripDiacritics(s){
  // remove combining marks; keep base letters (including Greek)
  return nfd(s).replace(combining, "").normalize('NFC');
}

function stripSpaces(s){ return (s||"").replace(/\s+/g,'').trim(); }

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code >= 0x0370 && code <= 0x03FF) || (code >= 0x1F00 && code <= 0x1FFF);
}

function greekOnly(s){
  return Array.from(s).filter(c => isGreekLetter(c) || c==='\'' || c==='’' || c==='-' ).join('');
}

const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

function countSyllablesRough(s){
  // rough: count vowel letters in stripped string
  const base = stripDiacritics(s);
  let n = 0;
  for (const ch of Array.from(base)) if (vowels.has(ch)) n++;
  return n;
}

const mutes = new Set(['π','β','φ','κ','γ','χ','τ','δ','θ','Π','Β','Φ','Κ','Γ','Χ','Τ','Δ','Θ']);

function endsWithLos(base){
  return base.endsWith('λος') || base.endsWith('ΛΟΣ') || base.endsWith('λος'.toUpperCase());
}

function findPenultEtaIndex(base){
  // For -ηλος words, find the eta that is immediately before 'λος'
  // Return index in codepoints array, or -1.
  const arr = Array.from(base);
  const n = arr.length;
  if (n < 4) return -1;
  // ... η λ ο ς
  if ((arr[n-4] === 'η' || arr[n-4] === 'Η') && (arr[n-3] === 'λ' || arr[n-3] === 'Λ') && (arr[n-2] === 'ο' || arr[n-2] === 'Ο') && (arr[n-1] === 'ς' || arr[n-1] === 'σ' || arr[n-1] === 'Σ')){
    return n-4;
  }
  return -1;
}

function applyAccentToEta(original, accentType, showGraveAtEnd){
  // accentType: 'acute' | 'circumflex' | 'grave'
  // We rebuild from base letters (strip diacritics), then add combining mark on the penult eta.
  const base = stripDiacritics(original);
  const arr = Array.from(base);
  const idx = findPenultEtaIndex(base);
  if (idx < 0) return nfc(base);

  // Decide mark
  let mark = '\u0301'; // acute
  if (accentType === 'circumflex') mark = '\u0342';
  if (accentType === 'grave') mark = '\u0300';

  // If user wants grave at word-end for acute accents, convert acute->grave when accent is on ultima.
  // Here accent is on penult, so ignore. But for the special note, we allow forcing grave anyway.
  if (showGraveAtEnd && accentType === 'acute'){
    // Herodian mentions "grave" for ζῆλος/ἧλος; we approximate by showing grave on η.
    mark = '\u0300';
  }

  arr[idx] = nfd(arr[idx]) + mark;
  return nfc(arr.join(''));
}

function asciiAccentHint(accentType, showGraveAtEnd){
  if (accentType === 'circumflex') return "accent: circumflex on η (ῆ)";
  if (accentType === 'grave' || (accentType==='acute' && showGraveAtEnd)) return "accent: grave on η (ὴ)";
  return "accent: acute on η (ή)";
}

function analyzeWord(input){
  const raw = (input||"").trim();
  const cleaned = greekOnly(raw);
  const base = stripDiacritics(cleaned);

  const syll = countSyllablesRough(base);
  const isDisyll = (syll === 2);
  const los = endsWithLos(base);
  const etaIdx = findPenultEtaIndex(base);
  const hasPenultEta = etaIdx >= 0;

  let beforeEta = null;
  if (hasPenultEta && etaIdx-1 >= 0) beforeEta = Array.from(base)[etaIdx-1];
  const beforeIsMute = beforeEta ? mutes.has(beforeEta) : false;

  // Special mentions
  const baseLower = Array.from(base).join('').toLowerCase();
  const specialGrave = (baseLower === 'ζηλος' || baseLower === 'ηλος');

  let predicted = null;
  let reason = "";

  if (!los){
    predicted = null;
    reason = "Not an -λος ending (toy rule doesn’t apply).";
  } else if (!isDisyll){
    predicted = null;
    reason = `Ends in -λος, but syllables≈${syll} (toy focuses on disyllables).`;
  } else if (!hasPenultEta){
    predicted = null;
    reason = "Disyllabic -λος, but penult is not η (toy focuses on -ηλος).";
  } else {
    if (specialGrave){
      predicted = 'acute'; // we will optionally display grave via checkbox
      reason = "Herodian notes ζῆλος/ἧλος as ‘grave’; toy marks η and can show grave via checkbox.";
    } else if (beforeIsMute){
      predicted = 'acute';
      reason = `Mute before η (${beforeEta}) → acute (πηλός, βηλός, χηλός, φηλός).`;
    } else {
      predicted = 'circumflex';
      reason = `No mute before η (${beforeEta || '—'}) → circumflex (often proper names: Μῆλος, Βῆλος, Τῆλος…).`;
    }
  }

  return {
    raw, cleaned, base, syll, isDisyll, los, hasPenultEta, beforeEta, beforeIsMute, specialGrave,
    predicted, reason
  };
}

function renderAnalysis(a){
  const showGrave = $('#chkGrave').checked;

  let out = '—';
  let hint = '—';

  if (a.cleaned.length === 0){
    out = '—';
    hint = 'Type a Greek word above.';
  } else if (!a.predicted){
    out = nfc(stripDiacritics(a.cleaned));
    hint = a.reason;
  } else {
    out = applyAccentToEta(a.cleaned, a.predicted, showGrave && a.specialGrave);
    hint = asciiAccentHint(a.predicted, showGrave && a.specialGrave) + "\n" + a.reason;
  }

  $('#outWord').textContent = out;
  $('#outAscii').textContent = hint;

  const facts = [];
  facts.push(`<strong>Input</strong>: ${escapeHtml(a.cleaned || '—')}`);
  facts.push(`<strong>Base (no diacritics)</strong>: ${escapeHtml(a.base || '—')}`);
  facts.push(`<strong>Syllables (rough)</strong>: ${a.syll}`);
  facts.push(`<strong>Ends in -λος</strong>: ${a.los ? 'yes' : 'no'}`);
  facts.push(`<strong>Penult η before -λος</strong>: ${a.hasPenultEta ? 'yes' : 'no'}`);
  if (a.hasPenultEta) facts.push(`<strong>Letter before η</strong>: ${escapeHtml(a.beforeEta || '—')} (${a.beforeIsMute ? 'mute' : 'not mute'})`);
  if (a.specialGrave) facts.push(`<strong>Special mention</strong>: ζῆλος/ἧλος → “grave” in passage`);

  $('#facts').innerHTML = facts.map(x=>`<li>${x}</li>`).join('');
}

function escapeHtml(s){
  return (s||"")
    .replaceAll('&','&amp;')
    .replaceAll('<','&lt;')
    .replaceAll('>','&gt;')
    .replaceAll('"','&quot;')
    .replaceAll("'",'&#39;');
}

// --- Mini game ---
const examples = [
  {w:'Μηλος', note:'proper name → expect circumflex (Μῆλος) by toy'},
  {w:'Βηλος', note:'proper name → expect circumflex (Βῆλος) by toy'},
  {w:'Τηλος', note:'proper name → expect circumflex (Τῆλος) by toy'},
  {w:'Σφηλος', note:'proper name → expect circumflex (Σφῆλος) by toy'},
  {w:'Δηλος', note:'proper name/place → expect circumflex (Δῆλος) by toy'},
  {w:'πηλος', note:'mute π before η → acute (πηλός)'},
  {w:'βηλος', note:'mute β before η → acute (βηλός)'},
  {w:'χηλος', note:'mute χ before η → acute (χηλός)'},
  {w:'φηλος', note:'mute φ before η → acute (φηλός)'},
  {w:'ζηλος', note:'special: “grave” in passage (ζῆλος)'},
  {w:'ηλος', note:'special: “grave” in passage (ἧλος)'}
];

let currentGame = null;

function newGame(){
  currentGame = examples[Math.floor(Math.random()*examples.length)];
  $('#gamePrompt').textContent = `Word: ${currentGame.w}  |  Is the letter before η a mute?`;
  $('#gameResult').textContent = 'Make a guess, then Reveal.';
}

function guess(isMute){
  if (!currentGame){
    $('#gameResult').textContent = 'Press “Random example” first.';
    return;
  }
  const a = analyzeWord(currentGame.w);
  const ok = (a.beforeIsMute === isMute);
  $('#gameResult').textContent = ok ? 'Correct (for the toy’s check).' : `Not quite: the toy sees “${a.beforeEta || '—'}” as ${a.beforeIsMute ? 'mute' : 'not mute'}.`;
}

function reveal(){
  if (!currentGame){
    $('#gameResult').textContent = 'Press “Random example” first.';
    return;
  }
  $('#inp').value = currentGame.w;
  const a = analyzeWord(currentGame.w);
  renderAnalysis(a);
  $('#gameResult').textContent = `Toy predicts: ${$('#outWord').textContent}. (${currentGame.note})`;
}

// --- Wire up ---
$('#btnAnalyze').addEventListener('click', () => renderAnalysis(analyzeWord($('#inp').value)));
$('#btnClear').addEventListener('click', () => { $('#inp').value=''; renderAnalysis(analyzeWord('')); });
$('#btnRandom').addEventListener('click', () => { newGame(); });
$('#btnGuessMute').addEventListener('click', () => guess(true));
$('#btnGuessNot').addEventListener('click', () => guess(false));
$('#btnReveal').addEventListener('click', () => reveal());
$('#chkGrave').addEventListener('change', () => renderAnalysis(analyzeWord($('#inp').value)));

$('#inp').addEventListener('keydown', (e) => {
  if (e.key === 'Enter') renderAnalysis(analyzeWord($('#inp').value));
});

// initial
renderAnalysis(analyzeWord(''));
newGame();

