.hdr h1{font-size:22px;margin:0 0 6px 0;letter-spacing:.2px}
.sub{margin:0;color:var(--muted)}
.panel{background:linear-gradient(180deg,var(--panel),var(--panel2));border:1px solid var(--line);border-radius:14px;padding:14px;margin:12px 0;box-shadow:0 10px 30px rgba(0,0,0,.25)}
.row{display:flex;flex-direction:column;gap:6px;margin:10px 0}
label{color:var(--muted);font-size:13px}
input,select,button{font:inherit}
input,select{background:#0c0f1c;color:var(--text);border:1px solid var(--line);border-radius:10px;padding:10px 12px;outline:none}
input:focus,select:focus{border-color:rgba(139,233,253,.55);box-shadow:0 0 0 3px rgba(139,233,253,.12)}
.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
@media (max-width:820px){.grid{grid-template-columns:1fr}}
.btns{display:flex;gap:10px;flex-wrap:wrap;margin-top:10px}
button{border:1px solid var(--line);background:#0c0f1c;color:var(--text);padding:10px 12px;border-radius:12px;cursor:pointer}
button:hover{border-color:rgba(255,255,255,.22)}
button.primary{background:linear-gradient(180deg, rgba(139,233,253,.22), rgba(189,147,249,.18));border-color:rgba(139,233,253,.35)}
button.ghost{background:transparent}
.out{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:10px;margin-top:12px}
@media (max-width:900px){.out{grid-template-columns:1fr}}
.card{border:1px solid var(--line);border-radius:12px;padding:12px;background:rgba(12,15,28,.55)}
.k{color:var(--muted);font-size:12px;margin-bottom:6px}
.v{font-size:22px;letter-spacing:.2px}
.v.small{font-size:14px;color:var(--text)}
.mini{margin-top:6px;color:var(--muted);font-size:13px}
.help{margin-top:10px;border:1px dashed rgba(255,255,255,.18);border-radius:12px;padding:10px;background:rgba(12,15,28,.35)}
.help summary{cursor:pointer;color:var(--accent)}
.helpBody{margin-top:8px;color:var(--muted)}
.helpBody ul{margin:8px 0 0 18px}
h2{margin:0 0 10px 0;font-size:16px;color:var(--text)}
.chips{display:flex;flex-wrap:wrap;gap:8px}
.chip{border:1px solid var(--line);background:rgba(12,15,28,.55);padding:8px 10px;border-radius:999px;cursor:pointer;color:var(--text)}
.chip:hover{border-color:rgba(139,233,253,.35)}
.chip .g{font-weight:650}
.chip .e{color:var(--muted);margin-left:8px;font-size:12px}
.ftr{color:var(--muted);font-size:12px;margin-top:10px}
.fine{opacity:.9}
.badge{display:inline-block;padding:2px 8px;border-radius:999px;border:1px solid var(--line);color:var(--muted);font-size:12px}
.noteWarn{color:var(--warn)}

