(() => {
  const $ = (sel) => document.querySelector(sel);

  const inWord = $('#inWord');
  const sense = $('#sense');
  const kind = $('#kind');
  const dialytika = $('#dialytika');

  const outWord = $('#outWord');
  const outAlt = $('#outAlt');
  const outRule = $('#outRule');
  const outNotes = $('#outNotes');

  const examples = [
    {w:'κωλος', hint:'Κῶλος (proper/appellative with ω-penult → circumflex)'} ,
    {w:'σκωλος', hint:'Σκῶλος (proper with ω-penult → circumflex)'} ,
    {w:'στωλος', hint:'Στῶλος (proper with ω-penult → circumflex)'} ,
    {w:'τμωλος', hint:'Τμῶλος (proper with ω-penult → circumflex)'} ,
    {w:'χωλος', hint:'χωλός (adjective → acute)'} ,
    {w:'ψωλος', hint:'ψωλός (adjective → acute)'} ,
    {w:'αυλος', hint:'αὐλός (-αυλος simplex, not proper → acute)'} ,
    {w:'δαυλος', hint:'δαυλός (exception: acute)'} ,
    {w:'γαυλος', hint:'γαυλός (vessel) vs γαῦλος (ship/proper)'} ,
    {w:'ναυλος', hint:'ναῦλος (barytone/circumflex per passage)'} ,
    {w:'φαυλος', hint:'φαῦλος (adjective with αυ/ου/ευ/ηυ before -λος → barytone)'} ,
    {w:'δουλος', hint:'δοῦλος (same barytone pattern)'} ,
    {w:'ουλος', hint:'οὖλος (same barytone pattern)'} ,
    {w:'τραυλος', hint:'τραυλός (exception: acute)'} ,
    {w:'κοιλος', hint:'κοῖλος (only -λος with οι-penult → barytone)'} ,
    {w:'υλλος', hint:'Ὕλλος (proper -λλος → barytone)'} ,
    {w:'τελλος', hint:'Τέλλος (proper -λλος → barytone)'} ,
    {w:'μυλλος', hint:'Μύλλος (proper -λλος → barytone)'} ,
    {w:'γαλλος', hint:'Γάλλος (proper -λλος → barytone)'}
  ];

  function stripDiacritics(s){
    // Remove combining marks; keep base Greek letters.
    return (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  }

  function cleanGreek(s){
    s = (s || '').trim();
    // keep Greek letters and final sigma; also allow apostrophe/space/hyphen for short phrases
    s = s.replace(/[^\p{Script=Greek}\s\-’'·\.]/gu,'');
    // collapse spaces
    s = s.replace(/\s+/g,' ');
    return s;
  }

  function lastWord(s){
    const parts = s.trim().split(/\s+/);
    return parts[parts.length-1] || '';
  }

  function applyAccentDisyllable(word, accentType){
    // Toy: place accent on penult vowel group.
    // accentType: 'circ' | 'acute'
    const w = stripDiacritics(word);
    const lower = w.toLowerCase();

    // Find penult vowel nucleus by scanning from end for vowel groups.
    const vowels = 'αεηιουω';
    const isV = (ch) => vowels.includes(ch);

    // collect vowel-group start indices
    let groups = [];
    for(let i=0;i<lower.length;i++){
      const ch = lower[i];
      if(isV(ch)){
        // start of group
        let j=i;
        while(j+1<lower.length && isV(lower[j+1])) j++;
        groups.push({start:i,end:j});
        i=j;
      }
    }
    if(groups.length < 2) return {out: word, note:'Could not confidently find 2 syllables; left unchanged.'};

    const penult = groups[groups.length-2];
    const targetIndex = penult.end; // accent last vowel of the group

    const acuteMap = {α:'ά',ε:'έ',η:'ή',ι:'ί',ο:'ό',υ:'ύ',ω:'ώ'};
    const circMap  = {α:'ᾶ',η:'ῆ',ι:'ῖ',υ:'ῦ',ω:'ῶ'}; // circumflex only where common

    const chars = [...w];
    const base = stripDiacritics(chars[targetIndex]);

    let accented = null;
    if(accentType==='acute') accented = acuteMap[base] || acuteMap[base.toLowerCase()];
    if(accentType==='circ') accented = circMap[base] || null;

    if(!accented){
      // fallback to acute if circumflex not available for that vowel
      accented = acuteMap[base] || base;
      return {out: chars.map((c,idx)=> idx===targetIndex? accented : c).join(''), note:'Circumflex not available on that vowel in this toy; used acute fallback.'};
    }

    const out = chars.map((c,idx)=> idx===targetIndex? accented : c).join('');
    return {out, note:null};
  }

  function analyze(input){
    const raw = cleanGreek(input);
    if(!raw) return {ok:false, msg:'Type a Greek word (e.g. κωλος, χωλος, γαυλος, ναυλος, κοιλος).'};

    const w0 = lastWord(raw);
    const w = stripDiacritics(w0).toLowerCase();

    const notes = [];
    const k = kind.value;
    const s = sense.value;

    // Recognize endings
    const endsLos = w.endsWith('λος');
    const endsAulos = w.endsWith('αυλος');
    const endsLlos = w.endsWith('λλος');

    if(!endsLos && !endsAulos && !endsLlos){
      notes.push('Does not end in -λος / -αυλος / -λλος; rules may not apply.');
    }

    // Hard-coded exceptions/known items from passage
    const known = new Map([
      ['χωλος',{type:'adjective', accent:'acute', rule:'Adjectival χωλός is acute (Herodian contrasts Χῶλος proper name).'}],
      ['ψωλος',{type:'adjective', accent:'acute', rule:'Adjectival ψωλός is acute.'}],
      ['κοιλος',{type:'appellative', accent:'circ', rule:'κοῖλος: μοναδικόν with οι in penult → barytone (implemented as circumflex on penult).'}],
      ['ναυλος',{type:'appellative', accent:'circ', rule:'ναῦλος is barytone/circumflex in the passage (though not a proper name).'}],
      ['φαυλος',{type:'adjective', accent:'circ', rule:'Adjective with αυ before -λος → barytone (φαῦλος).'}],
      ['δουλος',{type:'adjective', accent:'circ', rule:'Adjective with ου before -λος → barytone (δοῦλος).'}],
      ['ουλος',{type:'adjective', accent:'circ', rule:'Adjective with ου before -λος → barytone (οὖλος).'}],
      ['τραυλος',{type:'adjective', accent:'acute', rule:'Exception: τραυλός is acute.'}],
      ['δαυλος',{type:'auto', accent:'acute', rule:'δαυλός is acute (listed among -αυλος simplex; also noted as acute later).'}],
      ['αυλος',{type:'appellative', accent:'acute', rule:'Simplex -αυλος (not proper) → acute (αὐλός).'}],
      ['καυλος',{type:'appellative', accent:'acute', rule:'Simplex -αυλος (not proper) → acute (καυλός).'}],
      ['γαυλος',{type:'ambig', accent:null, rule:'γαυλός (vessel) acute; γαῦλος (ship) barytone/circumflex; also proper names (Βαῦλος/Παῦλος/Γαῦλος) circumflex.'}],
      ['βαυλος',{type:'proper', accent:'circ', rule:'Proper name Βαῦλος → circumflex.'}],
      ['παυλος',{type:'proper', accent:'circ', rule:'Proper name Παῦλος → circumflex.'}],
      ['γαυλος_proper',{type:'proper', accent:'circ', rule:'Proper name Γαῦλος → circumflex.'}],
      ['κωλος',{type:'auto', accent:'circ', rule:'Disyllabic -λος with ω in penult (proper/appellative) → circumflex (Κῶλος / κῶλος).'}],
      ['μωλος',{type:'auto', accent:'circ', rule:'-λος with ω-penult → circumflex (μῶλος).'}],
      ['βωλος',{type:'auto', accent:'circ', rule:'-λος with ω-penult → circumflex (βῶλος).'}],
      ['πωλος',{type:'auto', accent:'circ', rule:'-λος with ω-penult → circumflex (Πῶλος / πῶλος).'}],
      ['χωλος_proper',{type:'proper', accent:'circ', rule:'Proper name Χῶλος → circumflex.'}],
      ['υλλος',{type:'proper', accent:'acute', rule:'Proper masculine -λλος names are barytone (Ὕλλος etc.). Implemented as acute on penult.'}],
      ['τελλος',{type:'proper', accent:'acute', rule:'Proper -λλος barytone (Τέλλος).'}],
      ['μυλλος',{type:'proper', accent:'acute', rule:'Proper -λλος barytone (Μύλλος).'}],
      ['γαλλος',{type:'proper', accent:'acute', rule:'Proper -λλος barytone (Γάλλος).'}]
    ]);

    let chosenAccent = null;
    let ruleText = '';
    let alt = '';

    // Handle γαυλος ambiguity
    if(w === 'γαυλος'){
      if(s === 'vessel'){
        chosenAccent = 'acute';
        ruleText = 'γαυλός (vessel): simplex -αυλος (not proper) → acute.';
      } else if(s === 'ship'){
        chosenAccent = 'circ';
        ruleText = 'γαῦλος (ship): barytone in this sense; toy renders as circumflex on penult.';
      } else {
        notes.push('Ambiguous: choose “vessel” (γαυλός) vs “ship” (γαῦλος), or set “Treat as: proper name”.');
      }
      if(k === 'proper'){
        chosenAccent = 'circ';
        ruleText = 'Proper name Γαῦλος: circumflex.';
      }
    }

    // If known exception and not overridden
    if(!chosenAccent && known.has(w)){
      const info = known.get(w);
      if(k !== 'auto'){
        notes.push('You overrode “Treat as”; the toy will prefer your choice over the canned example when they conflict.');
      } else {
        chosenAccent = info.accent;
        ruleText = info.rule;
      }
    }

    // If still not chosen, apply general toy rules
    if(!chosenAccent){
      // Determine disyllabic-ish: we just assume user is giving disyllables like in passage.
      if(endsLlos){
        // Proper -λλος barytone; if not proper, still barytone-ish.
        chosenAccent = 'acute';
        ruleText = 'Toy rule: -λλος (esp. proper names) → barytone (implemented as acute on penult).';
      } else if(endsAulos){
        // simplex not proper acute; but ναυλος circumflex; adjectives with αυ/ου/ευ/ηυ before -λος barytone
        if(w === 'ναυλος'){
          chosenAccent = 'circ';
          ruleText = 'ναῦλος: barytone/circumflex per passage.';
        } else if(k === 'proper'){
          chosenAccent = 'circ';
          ruleText = 'Proper names in -αυλος: circumflex (per passage examples).';
        } else {
          chosenAccent = 'acute';
          ruleText = 'Simplex disyllables in -αυλος (not proper) → acute.';
        }
      } else if(endsLos){
        // ω-penult circumflex for proper/appellative; adjectives acute unless diphthong-with-upsilon before -λος barytone
        const penultHasOmega = w.includes('ωλ') || w.includes('ωλο');
        const beforeLos = w.slice(0, -2); // remove 'ος'?? too rough
        const hasUpsDiph = /(αυλ|ουλ|ευλ|ηυλ)/.test(w);

        if(k === 'adjective'){
          if(hasUpsDiph && !['τραυλος','δαυλος'].includes(w)){
            chosenAccent = 'circ';
            ruleText = 'Adjectives in -λος with αυ/ου/ευ/ηυ before -λος → barytone (toy: circumflex on penult).';
          } else {
            chosenAccent = 'acute';
            ruleText = 'Toy rule: adjectival -λος tends to be acute (cf. χωλός, ψωλός).';
          }
        } else {
          if(penultHasOmega){
            chosenAccent = 'circ';
            ruleText = 'Disyllabic -λος with ω in penult (proper/appellative) → circumflex.';
          } else if(w === 'κοιλος'){
            chosenAccent = 'circ';
            ruleText = 'κοῖλος: barytone (toy: circumflex on penult).';
          } else {
            // default guess
            chosenAccent = 'circ';
            ruleText = 'Default toy guess for disyllabic -λος nouns/proper names: barytone/circumflex on penult.';
            notes.push('Defaulted: the passage’s main rule targets disyllables with ω in the penult; your input may not match that exactly.');
          }
        }
      } else {
        chosenAccent = 'acute';
        ruleText = 'No matching ending: left mostly to a generic penult-accent guess.';
      }
    }

    // Apply accent
    const res = applyAccentDisyllable(w0, chosenAccent === 'circ' ? 'circ' : 'acute');

    // Special: Χῶλος vs χωλός if user typed χωλος and chose proper
    if(stripDiacritics(w0).toLowerCase() === 'χωλος' && k === 'proper'){
      const r2 = applyAccentDisyllable(w0, 'circ');
      res.out = r2.out;
      ruleText = 'Proper name Χῶλος: circumflex (contrast adjective χωλός).';
    }

    // Special: show κόϊλος alt spelling
    if(stripDiacritics(w0).toLowerCase() === 'κοιλος' && dialytika.value === 'yes'){
      alt = 'Alt spelling mentioned: κόϊλος (with diaeresis).';
    }

    if(res.note) notes.push(res.note);

    return {
      ok:true,
      out: res.out,
      alt,
      rule: ruleText,
      notes: notes.length ? notes.join(' ') : '—'
    };
  }

  function render(result){
    if(!result.ok){
      outWord.textContent = '—';
      outAlt.textContent = '';
      outRule.textContent = result.msg;
      outNotes.textContent = '—';
      outRule.classList.add('noteWarn');
      return;
    }
    outRule.classList.remove('noteWarn');
    outWord.textContent = result.out;
    outAlt.textContent = result.alt || '';
    outRule.textContent = result.rule;
    outNotes.textContent = result.notes;
  }

  function fillChips(){
    const box = $('#chips');
    box.innerHTML = '';
    examples.forEach(ex => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'chip';
      b.innerHTML = `<span class="g">${ex.w}</span><span class="e">${ex.hint}</span>`;
      b.addEventListener('click', () => {
        inWord.value = ex.w;
        // set helpful defaults
        if(ex.w === 'γαυλος') sense.value = 'auto';
        if(['χωλος','ψωλος','φαυλος','δουλος','ουλος','τραυλος','δαυλος'].includes(ex.w)) kind.value = 'adjective';
        else if(['υλλος','τελλος','μυλλος','γαλλος','βαυλος','παυλος'].includes(ex.w)) kind.value = 'proper';
        else kind.value = 'auto';
        render(analyze(inWord.value));
      });
      box.appendChild(b);
    });
  }

  $('#btnAnalyze').addEventListener('click', () => render(analyze(inWord.value)));
  $('#btnClear').addEventListener('click', () => {
    inWord.value = '';
    sense.value = 'auto';
    kind.value = 'auto';
    dialytika.value = 'no';
    outWord.textContent = '—';
    outAlt.textContent = '';
    outRule.textContent = '—';
    outNotes.textContent = '—';
    outRule.classList.remove('noteWarn');
    inWord.focus();
  });
  $('#btnRandom').addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inWord.value = ex.w;
    sense.value = 'auto';
    kind.value = 'auto';
    dialytika.value = 'no';
    render(analyze(inWord.value));
  });

  inWord.addEventListener('keydown', (e) => {
    if(e.key === 'Enter') render(analyze(inWord.value));
  });
  inWord.addEventListener('input', () => {
    // live preview, but avoid being too jumpy on empty
    if(inWord.value.trim().length === 0) return;
    render(analyze(inWord.value));
  });

  fillChips();
})();

