:root{
  --bg:#0f1220;
  --card:#171a2b;
  --card2:#1d2136;
  --text:#eef0ff;
  --muted:#b8bce6;
  --faint:#8b90c7;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --good:#34d399;
  --bad:#fb7185;
  --line:rgba(255,255,255,.10);
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, rgba(167,139,250,.18), transparent 55%),radial-gradient(900px 600px at 90% 10%, rgba(125,211,252,.16), transparent 55%),var(--bg);color:var(--text);font:16px/1.35 system-ui,-apple-system,Segoe UI,Roboto,Arial,"Noto Sans","Noto Sans Greek",sans-serif}
.wrap{max-width:980px;margin:0 auto;padding:22px 16px 28px}
.hdr{display:flex;gap:14px;align-items:flex-start;margin-bottom:14px}
h1{font-size:26px;margin:0 0 6px;letter-spacing:.2px}
.sub{margin:0;color:var(--muted)}
.card{background:linear-gradient(180deg,var(--card),var(--card2));border:1px solid var(--line);border-radius:14px;padding:16px 16px 14px;margin:14px 0;box-shadow:0 10px 30px rgba(0,0,0,.25)}
.card h2{margin:0 0 8px;font-size:18px}
.inst{margin:0 0 12px;color:var(--muted)}
.row{display:grid;grid-template-columns:140px 1fr auto auto;gap:10px;align-items:center}
.lbl{color:var(--muted);font-size:13px}
.inp{width:100%;padding:10px 12px;border-radius:10px;border:1px solid var(--line);background:rgba(0,0,0,.25);color:var(--text);font-size:18px}
.inp:focus{outline:none;border-color:rgba(125,211,252,.55);box-shadow:0 0 0 3px rgba(125,211,252,.15)}
.btn{padding:10px 12px;border-radius:10px;border:1px solid rgba(255,255,255,.14);background:rgba(125,211,252,.18);color:var(--text);cursor:pointer;font-weight:650}
.btn:hover{border-color:rgba(125,211,252,.55)}
.btn.ghost{background:transparent;color:var(--muted)}
.btn.ghost:hover{color:var(--text);border-color:rgba(255,255,255,.22)}
.outGrid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-top:12px}
.outBox{border:1px solid var(--line);border-radius:12px;padding:10px 12px;background:rgba(0,0,0,.18)}
.k{color:var(--faint);font-size:12px;margin-bottom:6px;text-transform:uppercase;letter-spacing:.08em}
.v{font-size:15px}
.v.big{font-size:22px;letter-spacing:.2px}
.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Noto Sans Mono","Noto Sans Greek",monospace}
.notes{margin-top:10px;border:1px dashed rgba(255,255,255,.18);border-radius:12px;padding:10px 12px;background:rgba(0,0,0,.12)}
.notes summary{cursor:pointer;color:var(--accent)}
.pad{margin-top:8px;color:var(--muted)}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0 2px}
.chip{border:1px solid rgba(255,255,255,.14);background:rgba(167,139,250,.14);color:var(--text);padding:7px 10px;border-radius:999px;cursor:pointer;font-weight:650}
.chip:hover{border-color:rgba(167,139,250,.55)}
.mini{margin-top:12px;border-top:1px solid var(--line);padding-top:12px}
.miniTitle{font-weight:750;margin-bottom:6px;color:var(--accent2)}
.quizRow{display:grid;grid-template-columns:1fr auto 1fr;gap:10px;align-items:center}
.sel{padding:10px 12px;border-radius:10px;border:1px solid var(--line);background:rgba(0,0,0,.25);color:var(--text);font-size:16px}
.quizRes{padding:10px 12px;border-radius:10px;border:1px solid var(--line);background:rgba(0,0,0,.18);color:var(--muted)}
.quizRes.good{border-color:rgba(52,211,153,.45);color:var(--good)}
.quizRes.bad{border-color:rgba(251,113,133,.45);color:var(--bad)}
.ftr{margin-top:10px;color:var(--muted)}
.small{font-size:12.5px;color:var(--muted)}
@media (max-width:760px){
  .row{grid-template-columns:1fr;}
  .outGrid{grid-template-columns:1fr}
  .quizRow{grid-template-columns:1fr}
}

