const $ = (id)=>document.getElementById(id);

// --- Greek helpers (toy-level) ---
const COMBINING = /[\u0300-\u036f]/g;
const FINAL_SIGMA = /ς/g;

function nfd(s){ return (s||"").normalize('NFD'); }
function stripCombining(s){ return nfd(s).replace(COMBINING,'').normalize('NFC'); }

function normalizeGreek(s){
  // Keep Greek letters; trim spaces; normalize sigma; remove punctuation around.
  s = (s||"").trim();
  // collapse internal spaces (we want a single word, but don't hard-fail)
  s = s.replace(/\s+/g,' ');
  // remove leading/trailing punctuation
  s = s.replace(/^[^\p{L}]+|[^\p{L}]+$/gu,'');
  // normalize final sigma to σ for processing
  s = s.replace(FINAL_SIGMA,'σ');
  return s;
}

const vowelsBase = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

function isVowel(ch){
  const base = stripCombining(ch);
  return vowelsBase.has(base);
}

function syllabifyToy(word){
  // Very rough: split after each vowel group (including diphthongs-ish).
  // Works decently for short demo words like μαλλος, πολλος, Σελλοι.
  const w = nfd(word);
  let syl = [];
  let cur = '';
  let i=0;
  while(i<w.length){
    const ch = w[i];
    cur += ch;
    // detect vowel nucleus: a vowel letter possibly followed by combining marks
    if(isVowel(ch)){
      // consume combining marks
      let j=i+1;
      while(j<w.length && COMBINING.test(w[j])){ cur += w[j]; j++; }
      // attempt to include a following iota/upsilon for diphthong if present (no perfect)
      if(j<w.length){
        const next = w[j];
        const nextBase = stripCombining(next);
        const thisBase = stripCombining(ch);
        const canDiph = (['α','ε','ο','υ','η','ω'].includes(thisBase.toLowerCase()) && ['ι','υ'].includes(nextBase.toLowerCase()));
        if(canDiph){
          cur += next;
          j++;
          while(j<w.length && COMBINING.test(w[j])){ cur += w[j]; j++; }
        }
      }
      // close syllable here
      syl.push(cur.normalize('NFC'));
      cur='';
      i = j-1;
    }
    i++;
  }
  if(cur) syl[syl.length-1] = (syl[syl.length-1]||'') + cur.normalize('NFC');
  // clean empties
  syl = syl.filter(x=>x && x.length);
  return syl;
}

function hasDoubleLambda(word){
  const base = stripCombining(word).replace(/ς/g,'σ');
  return /λλ/i.test(base);
}

function penultHasIota(syllables){
  if(syllables.length < 2) return false;
  const pen = stripCombining(syllables[syllables.length-2]);
  return /ι/i.test(pen);
}

function addAcuteToLastVowel(syllable){
  // Add combining acute (U+0301) after the first vowel letter in the syllable.
  const s = nfd(syllable);
  let out='';
  let placed=false;
  for(let i=0;i<s.length;i++){
    const ch = s[i];
    out += ch;
    if(!placed && isVowel(ch)){
      // skip existing combining marks right after vowel
      let j=i+1;
      let hasAccent=false;
      while(j<s.length && COMBINING.test(s[j])){
        const m = s[j];
        if(m === '\u0301' || m === '\u0341') hasAccent=true; // acute / tonos
        out += m;
        j++;
      }
      if(!hasAccent){ out += '\u0301'; }
      placed=true;
      i = j-1;
    }
  }
  return out.normalize('NFC');
}

function suggestAccent(word){
  const norm = normalizeGreek(word);
  if(!norm) return {norm:'', syllables:[], trigger:'(no input)', accented:''};

  const syllables = syllabifyToy(norm);
  const dbl = hasDoubleLambda(norm);
  const penI = penultHasIota(syllables);
  const trisyl = syllables.length === 3;

  let triggerParts = [];
  if(dbl) triggerParts.push('contains -λλ-');
  if(trisyl) triggerParts.push('toy: 3 syllables → oxytone');
  if(dbl && !penI) triggerParts.push('toy: -λλ- and penult ≠ ι → oxytone');
  if(dbl && penI) triggerParts.push('penult has ι → toy does NOT auto-oxytone from -λλ-');
  if(!dbl && !trisyl) triggerParts.push('no toy rule fired');

  const shouldOxytone = (trisyl) || (dbl && !penI);

  let accented = norm;
  if(shouldOxytone && syllables.length){
    const last = syllables[syllables.length-1];
    const newLast = addAcuteToLastVowel(last);
    const rebuilt = syllables.slice(0,-1).join('') + newLast;
    accented = rebuilt;
  }

  return {
    norm,
    syllables,
    trigger: triggerParts.join(' · '),
    accented
  };
}

function render(){
  const val = $('inp').value;
  const r = suggestAccent(val);
  $('norm').textContent = r.norm || '—';
  $('syll').textContent = r.syllables.length ? r.syllables.join(' | ') : '—';
  $('rule').textContent = r.trigger || '—';
  $('accented').textContent = r.accented || '—';
}

// --- Examples / quiz ---
const examples = [
  'μαλλος','φαλλος','θαλλος','φελλος','σκελλος','πολλος',
  'Σελλοι','Ἑλλος','Ψυλλος','Σκυλλος','Τραλλος','Κολλος',
  'ἀντιφελλον','Φυλλον'
];

function buildChips(){
  const box = $('chips');
  box.innerHTML='';
  examples.slice(0,12).forEach(w=>{
    const b=document.createElement('button');
    b.className='chip';
    b.type='button';
    b.textContent=w;
    b.addEventListener('click',()=>{ $('inp').value=w; render(); $('inp').focus(); });
    box.appendChild(b);
  });
}

function buildQuiz(){
  const items = [
    {w:'πολλος', expect:true},
    {w:'μαλλος', expect:true},
    {w:'Σελλοι', expect:false},
    {w:'Ψυλλος', expect:false},
    {w:'Τραλλος', expect:true},
    {w:'ἀντιφελλον', expect:true}
  ];
  const sel = $('quizSel');
  sel.innerHTML='';
  items.forEach((it,idx)=>{
    const opt=document.createElement('option');
    opt.value=String(idx);
    opt.textContent=it.w;
    sel.appendChild(opt);
  });

  $('quizCheck').addEventListener('click',()=>{
    const it = items[Number(sel.value)];
    const r = suggestAccent(it.w);
    const got = r.accented !== r.norm; // we only ever add acute on last syllable
    const ok = got === it.expect;
    const res = $('quizRes');
    res.className = 'quizRes ' + (ok ? 'good':'bad');
    res.textContent = ok
      ? `Toy says: ${r.accented} (oxytone).` 
      : `Toy says: ${r.accented}. (Expected ${it.expect? 'oxytone':'not forced'} by toy key.)`;
  });
}

// --- Wire up ---
$('btn').addEventListener('click', render);
$('btnClear').addEventListener('click', ()=>{ $('inp').value=''; render(); $('inp').focus(); });
$('inp').addEventListener('input', ()=>{ render(); });
$('inp').addEventListener('keydown', (e)=>{ if(e.key==='Enter'){ e.preventDefault(); render(); }});

buildChips();
buildQuiz();
render();

