:root{
  --bg:#0f1220;
  --card:#171a2b;
  --muted:#aeb6d6;
  --text:#eef1ff;
  --accent:#7dd3fc;
  --accent2:#c4b5fd;
  --warn:#fbbf24;
  --ok:#34d399;
  --box:#0b0d18;
  --line:rgba(255,255,255,.10);
}
*{box-sizing:border-box}
body{
  margin:0;
  font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Arial, "Noto Sans", "Liberation Sans", sans-serif;
  background: radial-gradient(1200px 700px at 20% 0%, rgba(125,211,252,.18), transparent 55%),
              radial-gradient(900px 600px at 90% 10%, rgba(196,181,253,.16), transparent 55%),
              var(--bg);
  color:var(--text);
}
.wrap{max-width:980px;margin:0 auto;padding:22px 16px 40px}
header h1{margin:0 0 6px;font-size:22px;letter-spacing:.2px}
.sub{margin:0 0 14px;color:var(--muted);line-height:1.35}
.card{
  background: linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));
  border:1px solid var(--line);
  border-radius:14px;
  padding:14px;
  box-shadow: 0 10px 30px rgba(0,0,0,.35);
}
.row{display:grid;grid-template-columns: 1fr;gap:10px}
label{font-size:13px;color:var(--muted)}
input{
  width:100%;
  padding:12px 12px;
  border-radius:12px;
  border:1px solid var(--line);
  background: rgba(0,0,0,.25);
  color:var(--text);
  font-size:18px;
  outline:none;
}
input:focus{border-color: rgba(125,211,252,.55); box-shadow: 0 0 0 3px rgba(125,211,252,.12)}
.btns{display:flex;flex-wrap:wrap;gap:8px}
button{
  border:1px solid rgba(125,211,252,.35);
  background: rgba(125,211,252,.14);
  color:var(--text);
  padding:9px 11px;
  border-radius:12px;
  cursor:pointer;
  font-weight:650;
}
button:hover{background: rgba(125,211,252,.20)}
button.ghost{border-color: var(--line); background: rgba(255,255,255,.05); color: var(--text)}
button.ghost:hover{background: rgba(255,255,255,.08)}
.help{margin-top:10px;border-top:1px solid var(--line);padding-top:10px}
.help summary{cursor:pointer;color:var(--accent);font-weight:650}
.helpBody{color:var(--muted);line-height:1.45}
.helpBody ul{margin:8px 0 0 18px}
.note{margin:10px 0 0;color:rgba(238,241,255,.85)}
.out{margin-top:12px;border-top:1px solid var(--line);padding-top:12px}
.grid{display:grid;grid-template-columns: 1fr;gap:10px}
@media (min-width: 820px){
  .row{grid-template-columns: 1fr auto; align-items:end}
  .btns{justify-content:flex-end}
  .grid{grid-template-columns: 1fr 1fr 1.2fr}
}
h3{margin:0 0 6px;font-size:13px;color:var(--muted);font-weight:700;text-transform:uppercase;letter-spacing:.08em}
.box{
  background: var(--box);
  border:1px solid var(--line);
  border-radius:12px;
  padding:10px 10px;
  min-height:42px;
  display:flex;
  align-items:center;
}
.mono{font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace; font-size:14px}
.big{font-size:22px; letter-spacing:.2px}
.pill{
  display:inline-block;
  margin-top:8px;
  padding:6px 10px;
  border-radius:999px;
  border:1px solid var(--line);
  background: rgba(255,255,255,.05);
  color: rgba(238,241,255,.92);
  font-size:13px;
}
.why{margin:8px 0 0 18px;color:var(--muted);line-height:1.45}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}
.chip{
  border:1px solid rgba(196,181,253,.35);
  background: rgba(196,181,253,.12);
  color: var(--text);
  padding:7px 10px;
  border-radius:999px;
  cursor:pointer;
  font-weight:650;
  font-size:14px;
}
.chip:hover{background: rgba(196,181,253,.18)}
.foot{margin-top:12px;color:var(--muted);font-size:13px;line-height:1.35}
.kbd{font-family: ui-monospace, monospace; padding:2px 6px; border:1px solid var(--line); border-radius:8px; background: rgba(0,0,0,.25)}

