(() => {
  const $ = (sel) => document.querySelector(sel);
  const wEl = $('#w');
  const normEl = $('#norm');
  const endingEl = $('#ending');
  const guessEl = $('#guess');
  const labelEl = $('#label');
  const whyEl = $('#why');
  const chipsEl = $('#chips');

  const examples = [
    'κυκλος', 'οχλος', 'κοχλος', 'βυβλος', 'Βυβλος', 'τυφλος', 'στρεβλος', 'εσθλος',
    'κρυσταλλος', 'Διαλλος', 'οκταλλος', 'Τριβαλλος', 'προβαλλος',
    'Μαρκελλος', 'Κυριλλος', 'Σοφιλλος', 'Αντιφελλος', 'κορυδαλλος', 'κραπαταλλος',
    'ψυλλος', 'Ψυλλος', 'αρυβαλλος', 'περιαλλος', 'αιγιθαλλος', 'μοχλος'
  ];

  // --- Greek helpers (toy-level) ---
  const combiningMarks = /[\u0300-\u036f\u1dc0-\u1dff\u20d0-\u20ff\ufe20-\ufe2f]/g;

  function stripCombining(s){
    return s.normalize('NFD').replace(combiningMarks,'').normalize('NFC');
  }

  // Map a few common precomposed polytonic vowels to plain base vowels.
  // After NFD+stripCombining, most become base Greek letters already.
  function normalizeGreek(s){
    return stripCombining(s)
      .replace(/[··]/g,'')
      .replace(/[\u2019\u02bc']/g,'')
      .replace(/[\s\-–—.,;:!?()\[\]{}<>«»“”"\\/]/g,'')
      .toLowerCase();
  }

  function isGreekLetter(ch){
    const code = ch.codePointAt(0);
    return (code >= 0x0370 && code <= 0x03FF) || (code >= 0x1F00 && code <= 0x1FFF);
  }

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω']);

  function countSyllables(g){
    // Very rough: count vowel letters (treating diphthongs as 1 when obvious).
    // This is a toy; it will be wrong sometimes.
    const s = normalizeGreek(g);
    if(!s) return 0;
    let n = 0;
    for(let i=0;i<s.length;i++){
      const ch = s[i];
      if(!vowels.has(ch)) continue;
      // diphthongs: αι, ει, οι, υι, αυ, ευ, ου, ηυ
      const next = s[i+1] || '';
      const pair = ch + next;
      if(['αι','ει','οι','υι','αυ','ευ','ου','ηυ'].includes(pair)){
        n++; i++; continue;
      }
      n++;
    }
    return n;
  }

  function lastIndexOfVowel(s){
    for(let i=s.length-1;i>=0;i--) if(vowels.has(s[i])) return i;
    return -1;
  }

  function vowelIndices(s){
    const idx=[];
    for(let i=0;i<s.length;i++) if(vowels.has(s[i])) idx.push(i);
    // collapse diphthongs as one nucleus (keep first index)
    const out=[];
    for(let k=0;k<idx.length;k++){
      const i=idx[k];
      const nextV = idx[k+1];
      if(nextV === i+1){
        const pair = s[i]+s[i+1];
        if(['αι','ει','οι','υι','αυ','ευ','ου','ηυ'].includes(pair)){
          out.push(i);
          k++; // skip next
          continue;
        }
      }
      out.push(i);
    }
    return out;
  }

  function addAcuteOnSyllable(s, syllFromEnd){
    // syllFromEnd: 1=ultima,2=penult,3=antepenult
    const g = normalizeGreek(s);
    const vIdx = vowelIndices(g);
    if(vIdx.length === 0) return {accented: s, where: '—'};
    const target = vIdx[vIdx.length - syllFromEnd];
    if(target == null) return {accented: s, where: '—'};

    // Add tonos to the vowel (modern acute). For simplicity, use precomposed where possible.
    const map = { 'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ' };
    const chars = g.split('');
    const v = chars[target];
    chars[target] = map[v] || v;
    return {accented: chars.join(''), where: syllFromEnd === 1 ? 'oxytone (ultima)' : (syllFromEnd===2 ? 'paroxytone (penult)' : 'proparoxytone (antepenult)')};
  }

  function detectEnding(s){
    const g = normalizeGreek(s);
    if(g.endsWith('αλλος')) return '-αλλος';
    if(g.endsWith('λλος')) return '-λλος';
    if(g.endsWith('λος')) return '-λος';
    return '—';
  }

  function hasConsonantClusterBeforeLos(s){
    // Check pattern ...C C λ ο ς (i.e., cluster before -λος)
    const g = normalizeGreek(s);
    if(!g.endsWith('λος')) return false;
    const i = g.length - 3; // index of λ in -λος
    const before = g.slice(0, i);
    if(before.length < 2) return false;
    const c1 = before[before.length-1];
    const c2 = before[before.length-2];
    return !vowels.has(c1) && !vowels.has(c2);
  }

  const exceptionOxytone = new Set([
    'τυφλος','στρεβλος','εσθλος','μοχλος','προβαλλος','κορυδαλλος','κραπαταλλος','κιλλος'
  ]);

  const exceptionBarytone = new Set([
    'ιλλος','σιλλος','βιλλος','αλλος'
  ]);

  function titleCaseGreek(s){
    if(!s) return s;
    return s[0].toUpperCase() + s.slice(1);
  }

  function analyze(input){
    const raw = (input || '').trim();
    const norm = normalizeGreek(raw);

    normEl.textContent = norm || '—';

    if(!norm){
      endingEl.textContent = '—';
      guessEl.textContent = '—';
      labelEl.textContent = '—';
      whyEl.innerHTML = '<li>Type a Greek word to begin.</li>';
      chipsEl.innerHTML = '';
      return;
    }

    const ending = detectEnding(norm);
    endingEl.textContent = ending;

    const sylls = countSyllables(norm);
    const cluster = hasConsonantClusterBeforeLos(norm);

    const why = [];
    why.push(`Syllable guess: <span class="mono">${sylls}</span> (toy vowel-count).`);

    let rule = 'default';
    let syllFromEnd = 2; // default paroxytone

    // Proper-name hint: initial capital in raw
    const looksProper = raw && raw[0] === raw[0].toUpperCase() && isGreekLetter(raw[0]);

    if(exceptionBarytone.has(norm)){
      rule = 'noted barytone';
      syllFromEnd = Math.min(2, sylls) || 1;
      why.push('Listed in the passage as “barytone” (here shown as a penult accent).');
    }

    if(exceptionOxytone.has(norm)){
      rule = 'noted oxytone';
      syllFromEnd = 1;
      why.push('Noted as oxytone/adjectival in the passage (toy: accent on ultima).');
    }

    if(rule === 'default'){
      if(ending === '-αλλος' && sylls === 3 && !looksProper){
        rule = 'trisyllabic -αλλος';
        syllFromEnd = 3;
        why.push('Trisyllabic -αλλος (non-ethnic) → proparoxytone (Herodian).');
      } else if(ending === '-λλος' && sylls >= 4){
        // penult vowel check
        const g = norm;
        // find penult vowel nucleus index
        const vIdx = vowelIndices(g);
        const penultV = vIdx[vIdx.length-2];
        const penultChar = penultV != null ? g[penultV] : '';
        if(penultChar && penultChar !== 'α'){
          rule = 'polysyllabic -λλος (penult ≠ α)';
          syllFromEnd = 3;
          why.push('Polysyllabic -λλος with penult vowel ≠ α → proparoxytone (Herodian).');
        } else {
          rule = 'polysyllabic -λλος (penult α)';
          syllFromEnd = 2;
          why.push('Polysyllabic -λλος with penult α: toy falls back to penult accent (many complications in real accentuation).');
        }
      } else if(ending === '-λος' && cluster){
        rule = '-λος with consonant cluster';
        // “barytone” in passage; we show recessive-ish: if 3+ syllables, antepenult; else penult.
        syllFromEnd = sylls >= 3 ? 3 : 2;
        why.push('Ends in -λος with a consonant cluster → “barytone” tendency (toy: recessive-ish).');
      } else if(ending === '-λος'){
        rule = 'simple -λος';
        syllFromEnd = sylls >= 3 ? 3 : 2;
        why.push('Simple -λος: toy uses a recessive-ish guess (not stated as a rule here, but keeps the game playable).');
      } else {
        rule = 'not in scope';
        syllFromEnd = Math.min(2, sylls) || 1;
        why.push('Not a -λος/-λλος target: toy gives a generic penult accent guess.');
      }
    }

    const {accented, where} = addAcuteOnSyllable(norm, syllFromEnd);

    guessEl.textContent = accented;
    labelEl.textContent = `${where} • rule: ${rule}`;

    // Add a small “Herodian-style” note about adjective if oxytone + -λος cluster
    if((ending === '-λος' || ending === '-αλλος' || ending === '-λλος') && syllFromEnd === 1){
      why.push('Herodian often treats oxytone -λος forms as adjectival (toy hint).');
    }

    // Show a couple of nearby playful transformations
    const chips = [];
    if(ending === '-λος'){
      chips.push({label:'Make it -λλος', value: norm.replace(/λος$/,'λλος')});
      chips.push({label:'Make it -αλλος', value: norm.replace(/λος$/,'αλλος')});
    } else if(ending === '-λλος'){
      chips.push({label:'Make it -λος', value: norm.replace(/λλος$/,'λος')});
      chips.push({label:'Make it -αλλος', value: norm.replace(/λλος$/,'αλλος')});
    } else if(ending === '-αλλος'){
      chips.push({label:'Make it -λλος', value: norm.replace(/αλλος$/,'λλος')});
      chips.push({label:'Make it -λος', value: norm.replace(/αλλος$/,'λος')});
    }
    chips.push({label:'Try Ψύλλος vs ψύλλος', value: looksProper ? 'ψυλλος' : 'Ψυλλος'});

    chipsEl.innerHTML = '';
    for(const c of chips){
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'chip';
      b.textContent = c.label;
      b.addEventListener('click', () => {
        wEl.value = c.value;
        analyze(wEl.value);
        wEl.focus();
      });
      chipsEl.appendChild(b);
    }

    whyEl.innerHTML = why.map(x => `<li>${x}</li>`).join('');
  }

  function randomExample(){
    const pick = examples[Math.floor(Math.random()*examples.length)];
    wEl.value = pick;
    analyze(pick);
    wEl.focus();
  }

  $('#go').addEventListener('click', () => analyze(wEl.value));
  $('#rand').addEventListener('click', randomExample);
  $('#clear').addEventListener('click', () => { wEl.value=''; analyze(''); wEl.focus(); });
  wEl.addEventListener('keydown', (e) => {
    if(e.key === 'Enter') analyze(wEl.value);
  });
  wEl.addEventListener('input', () => {
    // lightweight live update
    analyze(wEl.value);
  });

  // init
  analyze('κυκλος');
})();

