(function(){
  const $ = (s)=>document.querySelector(s);
  const inEl = $('#in');
  const outMain = $('#outMain');
  const outRule = $('#outRule');
  const assumeLong = $('#assumeLong');
  const showSyll = $('#showSyll');

  const examples = [
    'Πράστιλλος','Ῥήγιλλος','Ἀρίστυλλος','Ἥρυλλος','Θράσυλλος','Βάθυλλος','Μελάμφυλλος','Ἄβυλλος',
    'ὀπτίλλος','νεογιλλός',
    'Κώδαλος','Τάνταλος','Ἅρπαλος','δαίδαλος','ἤκαλος','πάσσαλος','Μαίναλος','Μάνταλος','Κώκαλος','Ἄσκαλος',
    'Ψύτταλος','ὀμφαλός','Θεσσαλός','Κέφαλος','ἐγκέφαλος','σίαλος','Φίαλος','δάμαλος','Ῥόπαλος',
    'Πάραλος','Πάταλος','Κύαλος','Κρωβίαλος','Ἀμφίαλος','Εὐρύαλος','Ἀστύαλος','ὕφαλος','ἀγχίαλος',
    'Ἰταλός','αἰγιαλός'
  ];

  // --- Greek normalization helpers (toy-level) ---
  const COMBINING = /[\u0300-\u036f]/g;
  function nfd(s){return (s||'').normalize('NFD');}
  function stripDiacritics(s){return nfd(s).replace(COMBINING,'').normalize('NFC');}
  function stripToLetters(s){
    // keep Greek letters only
    return (s||'').replace(/[^\u0370-\u03FF\u1F00-\u1FFF]+/g,'');
  }
  function lowerGreek(s){return stripToLetters(s).toLowerCase();}

  function hasAnyAccent(s){
    const d = nfd(s);
    return /[\u0300\u0301\u0342]/.test(d); // grave, acute, circumflex
  }

  function removeAccentsKeepBreathings(s){
    // remove only accent marks, keep breathings/diaeresis/iota subscript etc.
    return nfd(s)
      .replace(/[\u0300\u0301\u0342]/g,'')
      .normalize('NFC');
  }

  function addAcuteToVowelInSyllable(word, syllables, targetIndexFromEnd){
    // targetIndexFromEnd: 1=ultima,2=penult,3=antepenult
    const idx = syllables.length - targetIndexFromEnd;
    if(idx < 0) return word;

    // Find span in original string corresponding to syllable by searching sequentially.
    // We do this on a stripped version to align roughly.
    const base = stripDiacritics(word);
    let pos = 0;
    let spans = [];
    for(const syl of syllables){
      const sylBase = stripDiacritics(syl);
      const found = base.indexOf(sylBase, pos);
      if(found === -1){
        spans.push([pos, pos + sylBase.length]);
        pos += sylBase.length;
      } else {
        spans.push([found, found + sylBase.length]);
        pos = found + sylBase.length;
      }
    }
    const [a,b] = spans[idx];
    const segment = word.slice(a,b);

    // Put acute on the first vowel in the segment.
    const segNFD = nfd(segment);
    // map of base vowel to acute combining
    const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω','ά','έ','ή','ί','ό','ύ','ώ']);

    // Walk through codepoints; when we hit a Greek vowel base, insert acute after it (before other combining marks).
    let out = '';
    let i = 0;
    let accented = false;
    while(i < segNFD.length){
      const ch = segNFD[i];
      // If this is a base letter
      if(!accented && /[\u0370-\u03FF\u1F00-\u1FFF]/.test(ch)){
        const baseCh = stripDiacritics(ch);
        if(vowels.has(baseCh)){
          out += ch + '\u0301';
          accented = true;
          i++;
          continue;
        }
      }
      out += ch;
      i++;
    }
    const newSeg = out.normalize('NFC');
    return word.slice(0,a) + newSeg + word.slice(b);
  }

  // Very rough syllabifier: split before a vowel that follows a consonant cluster boundary.
  // Good enough to show “ultima/penult/antepenult” positions for many -alos/-illos words.
  const V = 'αεηιουωάέήίόύώΑΕΗΙΟΥΩ';
  function isVowel(ch){return V.indexOf(stripDiacritics(ch)) !== -1;}
  function roughSyllables(word){
    const w = stripToLetters(word);
    if(!w) return [];
    let syl = '';
    let out = [];
    for(let i=0;i<w.length;i++){
      const ch = w[i];
      syl += ch;
      const next = w[i+1];
      if(next && isVowel(next) && !isVowel(ch)){
        // boundary before next vowel
        out.push(syl);
        syl='';
      }
    }
    if(syl) out.push(syl);
    // merge tiny initial consonant-only syllable into next
    if(out.length>=2 && !out[0].split('').some(isVowel)){
      out[1] = out[0] + out[1];
      out.shift();
    }
    return out;
  }

  // Rules/exceptions from passage (toy list)
  const exceptionsUltima = new Set(['νεογιλλος','ιταλος','αιγιαλος','θεσσαλος']);
  const exceptionsPenult = new Set(['οπτιλλος','ομφαλος']);

  function classify(word){
    const w = lowerGreek(word);
    if(!w) return {kind:'none'};

    if(w.endsWith('ιλλος')) return {kind:'illos'};
    if(w.endsWith('αλος')) return {kind:'alos'};
    return {kind:'other'};
  }

  function suggest(){
    const raw = inEl.value.trim();
    const letters = stripToLetters(raw);
    if(!letters){
      outMain.textContent = '—';
      outRule.textContent = 'Type a Greek word first.';
      return;
    }

    const cls = classify(letters);
    const baseLower = lowerGreek(letters);
    const syll = roughSyllables(letters);

    let target = null; // 1 ultima, 2 penult, 3 antepenult
    let why = '';

    if(cls.kind==='illos'){
      if(exceptionsPenult.has(baseLower)){
        target = 2;
        why = 'Exception noted in the passage: ὀπτίλλος is paroxytone (accent on the penult).';
      } else if(exceptionsUltima.has(baseLower)){
        target = 1;
        why = 'Exception noted in the passage: νεογιλλός is oxytone (accent on the ultima).';
      } else {
        target = 3; // “first syllable” ≈ antepenult for trisyllables; we implement as antepenult if possible, else initial.
        why = 'Pattern in the examples: -ιλλος names like Πράστιλλος, Ῥήγιλλος are accented early (on the first syllable).';
      }
    } else if(cls.kind==='alos'){
      if(exceptionsPenult.has(baseLower)){
        target = 1; // omphalós is oxytone
        why = 'Noted exception: ὀμφαλός is oxytone (accent on the ultima).';
      } else if(exceptionsUltima.has(baseLower)){
        target = 1;
        if(baseLower==='θεσσαλος') why = 'Noted exception: Θεσσαλός (ethnic) is oxytone, matching the founder’s accent.';
        else if(baseLower==='ιταλος') why = 'Noted: Ἰταλός (founder and ethnic) is oxytone.';
        else if(baseLower==='αιγιαλος') why = 'Noted: αἰγιαλός (collective sense) is oxytone.';
        else why = 'Exception list: oxytone.';
      } else {
        if(assumeLong.checked){
          target = 3;
          why = 'Rule stated: -αλος words with the “third from the end” long are proparoxytone (accent on the antepenult). (Here assumed long.)';
        } else {
          target = 2;
          why = 'If the “third from the end” is not long, proparoxytone is not guaranteed; this toy falls back to paroxytone.';
        }
      }
    } else {
      target = 2;
      why = 'Not an -αλος or -ιλλος word; toy fallback: paroxytone (penult).';
    }

    // If word already has an accent, keep it but still explain.
    let display = letters;
    if(!hasAnyAccent(display)){
      display = removeAccentsKeepBreathings(display);
      // If target=3 but not enough syllables, accent the first syllable.
      const t = Math.min(target, syll.length);
      const fromEnd = (target===3 && syll.length<3) ? syll.length : target;
      display = addAcuteToVowelInSyllable(display, syll.length?syll:roughSyllables(display), fromEnd);
    }

    let extra = '';
    if(showSyll.checked){
      const sylTxt = (syll.length?syll:roughSyllables(display)).join(' · ');
      extra = '\nSyllables (rough): ' + sylTxt + '\nTarget: ' + (target===1?'ultima':target===2?'penult':'antepenult');
    }

    outMain.textContent = display + extra;
    outRule.textContent = why;
  }

  $('#go').addEventListener('click', suggest);
  inEl.addEventListener('keydown', (e)=>{ if(e.key==='Enter') suggest(); });

  $('#rand').addEventListener('click', ()=>{
    const w = examples[Math.floor(Math.random()*examples.length)];
    inEl.value = w;
    suggest();
  });

  $('#clear').addEventListener('click', ()=>{
    inEl.value='';
    outMain.textContent='—';
    outRule.textContent='—';
    inEl.focus();
  });

  // initial demo
  inEl.value = 'ομφαλος';
  suggest();
})();

