:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --panel2:#121528;
  --text:#e9ecff;
  --muted:#b8bde6;
  --faint:#7f86c7;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --bad:#fb7185;
  --good:#34d399;
  --border:rgba(255,255,255,.10);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
}
*{box-sizing:border-box}
.wrap{max-width:980px;margin:24px auto;padding:0 16px;color:var(--text);font:16px/1.45 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif}
header{margin-bottom:14px}
h1{font-size:22px;margin:0 0 6px 0;letter-spacing:.2px}
.sub{margin:0;color:var(--muted)}
.panel{background:linear-gradient(180deg,var(--panel),var(--panel2));border:1px solid var(--border);border-radius:14px;padding:14px 14px 12px;box-shadow:var(--shadow);margin:12px 0}
.panel.mini{padding:12px 14px}
.row{display:flex;gap:10px;align-items:end;margin:10px 0}
.row.two>div{flex:1}
label{display:block;font-size:12px;color:var(--muted);margin:0 0 6px 2px}
input,select{width:100%;padding:10px 10px;border-radius:10px;border:1px solid var(--border);background:rgba(255,255,255,.04);color:var(--text);outline:none}
input:focus,select:focus{border-color:rgba(125,211,252,.55);box-shadow:0 0 0 3px rgba(125,211,252,.12)}
button{padding:10px 12px;border-radius:10px;border:1px solid rgba(125,211,252,.35);background:rgba(125,211,252,.12);color:var(--text);cursor:pointer}
button:hover{background:rgba(125,211,252,.18)}
button.ghost{border-color:var(--border);background:rgba(255,255,255,.04)}
button.ghost:hover{background:rgba(255,255,255,.07)}
.out{margin-top:10px;border-top:1px solid var(--border);padding-top:12px}
.outHead{display:flex;align-items:baseline;justify-content:space-between;gap:10px}
.outHead h2{font-size:16px;margin:0}
.hint{font-size:12px;color:var(--faint)}
.tokens{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0 6px}
.token{font-family:var(--mono);padding:8px 10px;border-radius:999px;border:1px solid var(--border);background:rgba(255,255,255,.03);cursor:pointer;user-select:none}
.token small{display:block;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;color:var(--faint);font-size:11px;margin-top:2px}
.token.good{border-color:rgba(52,211,153,.35);background:rgba(52,211,153,.08)}
.token.bad{border-color:rgba(251,113,133,.35);background:rgba(251,113,133,.08)}
.token.neutral{border-color:rgba(167,139,250,.35);background:rgba(167,139,250,.08)}
.explain{font-size:13px;color:var(--muted);padding:8px 10px;border-radius:12px;border:1px dashed rgba(255,255,255,.14);background:rgba(0,0,0,.12)}
.explain code{font-family:var(--mono);color:var(--text)}
ol{margin:8px 0 0 18px;color:var(--muted)}
footer .fine{color:var(--faint);font-size:12px;margin:10px 2px 0}
@media (max-width:640px){
  .row{flex-direction:column;align-items:stretch}
  .outHead{flex-direction:column;align-items:flex-start}
}

