const $ = (s)=>document.querySelector(s);

const inp = $('#inp');
const mode = $('#mode');
const alphaLen = $('#alphaLen');
const tokensEl = $('#tokens');
const explainEl = $('#explain');

const examples = [
  'ἁπαλός', 'χθαμαλός', 'τροχαλός', 'ἀταλός', 'ὁμαλός', 'ἀκαλός', 'γυαλός',
  'μεγάλος', 'Φάρσαλος', 'Τάβαλος', 'Στύμφαλος',
  'ἄμπελος', 'Σθένελος', 'Κύψελος', 'Δέκελος', 'Ἔχελος', 'Πά νελος', 'ἄγγελος', 'σκόπελος', 'σφάκελος', 'ἀσφόδελος',
  'Κρῶμνάν τ᾽ Αἰγιαλόν τε'
];

// --- Greek accent helpers (mechanical, not fully philological) ---
const combining = {
  acute: '\u0301',
  grave: '\u0300',
  circumflex: '\u0342',
  diaeresis: '\u0308',
  smooth: '\u0313',
  rough: '\u0314',
  iotaSub: '\u0345'
};

function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripAccentsKeepDiaeresis(s){
  // remove tonos/oxia, varia, perispomeni, breathing, iota subscript; keep diaeresis
  const d = nfd(s);
  const remove = new Set([
    combining.acute, combining.grave, combining.circumflex,
    combining.smooth, combining.rough, combining.iotaSub
  ]);
  let out = '';
  for (const ch of d){
    if (remove.has(ch)) continue;
    out += ch;
  }
  return nfc(out);
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code>=0x0370 && code<=0x03FF) || (code>=0x1F00 && code<=0x1FFF);
}

function tokenize(text){
  // split into Greek-ish tokens while preserving order; return array of {raw, isGreek}
  const out=[];
  let buf='';
  let bufGreek=null;
  for (const ch of text){
    const g = isGreekLetter(ch) || /[\u0300-\u036f]/.test(ch); // include combining marks
    if (buf==='' ){
      buf=ch; bufGreek=g;
    } else if (g===bufGreek){
      buf+=ch;
    } else {
      out.push({raw:buf, isGreek:bufGreek});
      buf=ch; bufGreek=g;
    }
  }
  if (buf!=='') out.push({raw:buf, isGreek:bufGreek});
  return out;
}

function greekSyllableCount(word){
  // very rough: count vowel groups in stripped word
  const w = stripAccentsKeepDiaeresis(word).toLowerCase();
  const vowels = 'αεηιουω';
  let count=0;
  let prevV=false;
  for (const ch of w){
    const isV = vowels.includes(ch);
    if (isV && !prevV) count++;
    prevV=isV;
  }
  return count;
}

function addAccentToVowel(word, syllableFromEnd, accentType){
  // syllableFromEnd: 1=ultima,2=penult,3=antepenult
  // place combining mark on the first vowel of the target syllable (rough)
  const d = nfd(stripAccentsKeepDiaeresis(word));
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

  // Build syllable starts by scanning vowel groups
  const vowelPositions=[]; // index in code units of d string
  for (let i=0;i<d.length;i++){
    const ch = d[i];
    if (vowels.has(ch)){
      // if previous char is also vowel, skip (same group)
      const prev = d[i-1];
      if (prev && vowels.has(prev)) continue;
      vowelPositions.push(i);
    }
  }
  const sylCount = vowelPositions.length;
  if (sylCount===0) return {word:nfc(d), ok:false, why:'No vowels found.'};
  const targetSyl = sylCount - syllableFromEnd; // 0-based
  if (targetSyl<0) return {word:nfc(d), ok:false, why:`Only ${sylCount} syllable(s); can't accent ${syllableFromEnd} from end.`};

  const pos = vowelPositions[targetSyl];
  const mark = accentType==='grave' ? combining.grave : combining.acute;

  // insert mark after the vowel letter, but after any diaeresis already present
  let insertAt = pos+1;
  while (insertAt<d.length && d[insertAt]===combining.diaeresis) insertAt++;
  const out = d.slice(0, insertAt) + mark + d.slice(insertAt);
  return {word:nfc(out), ok:true, why:null};
}

function classifyAndAccent(token){
  const raw = token;
  const kept = raw;
  const base = stripAccentsKeepDiaeresis(raw);
  const lower = base.toLowerCase();

  const endsAlos = lower.endsWith('αλος');
  const endsElos = lower.endsWith('ελος');

  const syl = greekSyllableCount(base);

  // default: return as-is
  let outWord = kept;
  let label = 'no rule';
  let cls = 'neutral';
  let note = '';

  const m = mode.value;
  if (m==='strip'){
    return {out: base, cls:'neutral', label:'stripped', note:'Accents removed (normalization).'};
  }
  if (m==='keep'){
    return {out: kept, cls:'neutral', label:'kept', note:'Original spelling kept.'};
  }

  // auto
  if (endsAlos){
    // Herodian: either acute on penult (short third syllable) OR grave on antepenult (long alpha, polysyllabic)
    if (alphaLen.value==='long'){
      // require at least 3 syllables for antepenult
      const res = addAccentToVowel(base, 3, 'grave');
      outWord = res.word;
      cls = res.ok ? 'good' : 'bad';
      label = ' -αλος (long α)';
      note = res.ok ? 'Rule: polysyllabic -αλος with long α → grave on antepenult.' : res.why;
    } else {
      const res = addAccentToVowel(base, 2, 'acute');
      outWord = res.word;
      cls = res.ok ? 'good' : 'bad';
      label = ' -αλος (short 3rd syll.)';
      note = res.ok ? 'Rule: trigenic -αλος with short third syllable → acute on penult.' : res.why;
    }

    // playful special-case: μεγαλος noted as paroxytone (acute on penult) in passage
    if (lower==='μεγαλος'){
      const res = addAccentToVowel(base, 2, 'acute');
      outWord = res.word;
      cls = 'good';
      label = ' μεγάλος (noted)';
      note = 'Herodian notes μεγάλος as paroxytone (acute on penult).';
    }

  } else if (endsElos){
    // proparoxytone: acute on antepenult
    const res = addAccentToVowel(base, 3, 'acute');
    outWord = res.word;
    cls = res.ok ? 'good' : 'bad';
    label = ' -ελος (proparox.)';
    note = res.ok ? 'Rule: monogender -ελος → proparoxytone (acute on antepenult), unless irregular.' : res.why;
  } else {
    // no rule
    outWord = kept;
    cls = 'neutral';
    label = 'no match';
    note = 'No -αλος / -ελος ending detected.';
  }

  // extra info
  if (endsAlos || endsElos){
    note += ` (Syllables guessed: ${syl}.)`;
  }

  return {out: outWord, cls, label, note};
}

function render(text){
  tokensEl.innerHTML='';
  explainEl.textContent='';

  const parts = tokenize(text);
  const greekTokens = [];

  for (const p of parts){
    if (!p.isGreek){
      // render non-Greek as plain text chunk
      const span = document.createElement('span');
      span.textContent = p.raw;
      span.style.opacity = '0.9';
      span.style.padding = '6px 2px';
      tokensEl.appendChild(span);
      continue;
    }

    // split Greek chunk further on whitespace/punct inside
    const sub = p.raw.split(/(\s+|[··.,;:!?«»“”"'’\(\)\[\]{}<>—–-])/g).filter(x=>x!=='');
    for (const s of sub){
      if (/^\s+$/.test(s) || /^[··.,;:!?«»“”"'’\(\)\[\]{}<>—–-]$/.test(s)){
        const span = document.createElement('span');
        span.textContent = s;
        span.style.opacity = '0.9';
        span.style.padding = '6px 2px';
        tokensEl.appendChild(span);
        continue;
      }
      const info = classifyAndAccent(s);
      greekTokens.push({in:s, ...info});

      const t = document.createElement('div');
      t.className = `token ${info.cls}`;
      t.tabIndex = 0;
      t.setAttribute('role','button');
      t.setAttribute('aria-label',`Copy ${info.out}`);
      t.innerHTML = `${escapeHtml(info.out)}<small>${escapeHtml(info.label)}</small>`;
      t.addEventListener('click', ()=>copyToClipboard(info.out, t));
      t.addEventListener('keydown', (e)=>{ if(e.key==='Enter' || e.key===' '){ e.preventDefault(); copyToClipboard(info.out, t);} });
      t.addEventListener('mouseenter', ()=>{ explainEl.innerHTML = `<b>${escapeHtml(s)}</b> → <code>${escapeHtml(info.out)}</code><br>${escapeHtml(info.note)}`; });
      tokensEl.appendChild(t);
    }
  }

  // default explanation
  const first = greekTokens.find(x=>x.label!=='no match') || greekTokens[0];
  if (first){
    explainEl.innerHTML = `<b>Hover</b> a token for the rule explanation. Current mode: <code>${escapeHtml(mode.value)}</code>.`;
  } else {
    explainEl.textContent = 'Type some Greek above, then click Analyze.';
  }
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c=>({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));
}

async function copyToClipboard(text, el){
  try{
    await navigator.clipboard.writeText(text);
    flash(el, 'Copied!');
  } catch {
    // fallback
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position='fixed';
    ta.style.left='-9999px';
    document.body.appendChild(ta);
    ta.select();
    try{ document.execCommand('copy'); flash(el,'Copied!'); }
    catch{ flash(el,'Copy failed'); }
    document.body.removeChild(ta);
  }
}

function flash(el, msg){
  const prev = el.querySelector('small').textContent;
  el.querySelector('small').textContent = msg;
  el.style.transform='scale(1.02)';
  setTimeout(()=>{ el.querySelector('small').textContent = prev; el.style.transform=''; }, 650);
}

$('#go').addEventListener('click', ()=>render(inp.value));
$('#clear').addEventListener('click', ()=>{ inp.value=''; tokensEl.innerHTML=''; explainEl.textContent='Type some Greek above, then click Analyze.'; inp.focus(); });
$('#rand').addEventListener('click', ()=>{
  const pick = [];
  while (pick.length<6){
    const w = examples[Math.floor(Math.random()*examples.length)];
    if (!pick.includes(w)) pick.push(w);
  }
  inp.value = pick.join(' · ');
  render(inp.value);
});

mode.addEventListener('change', ()=>render(inp.value));
alphaLen.addEventListener('change', ()=>render(inp.value));

// seed
inp.value = 'αταλος · μεγαλος · Φαρσαλος · αμπελος · Σθενελος';
render(inp.value);

