const $ = (sel) => document.querySelector(sel);
const inp = $('#inp');
const mode = $('#mode');
const dial = $('#dial');
const btnGo = $('#go');
const btnRand = $('#rand');
const btnClear = $('#clear');

const elNorm = $('#norm');
const elEnding = $('#ending');
const elTarget = $('#target');
const elOut = $('#out');
const elWhy = $('#why');

// A few exceptions explicitly mentioned in the passage (toy list)
const OXYTONE_EXCEPTIONS = new Set([
  'οβελος','μυελος','δειελος','σικελος','στροβελος','κεφελος'
]);
// A compound example mentioned: ζάφελος (toy: treat as proparoxytone)
const PROPAROX_EXCEPTIONS = new Set(['ζαφελος']);

const examples = [
  'ευτραπελος','αειδελος','εικελος','πεμπελος','σικελος','οβελος','μυελος','δειελος','ζαφελος',
  'ευκηλος','τραχηλος','καπηλος','καμηλος','φασηλος','στυμφηλος','βεβηλος','κιβδηλος','ερυγμηλος'
];

function stripDiacritics(s){
  // Remove combining marks; keep Greek letters.
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function normalizeGreek(s){
  return stripDiacritics(s)
    .replace(/ς/g,'σ')
    .replace(/\s+/g,' ')
    .trim();
}

function isGreekVowel(ch){
  return 'αεηιουω'.includes(ch);
}

function countSyllables(word){
  // Very rough: count vowel groups (treat diphthongs as one group).
  const w = word;
  let i=0, syl=0;
  while(i<w.length){
    const c = w[i];
    if(isGreekVowel(c)){
      syl++;
      // swallow simple diphthongs
      const n = w[i+1] || '';
      const pair = c+n;
      if(['αι','ει','οι','υι','αυ','ευ','ηυ','ου','ωυ'].includes(pair)) i+=2;
      else i+=1;
      continue;
    }
    i++;
  }
  return syl;
}

function lastWord(phrase){
  const parts = phrase.split(' ').filter(Boolean);
  return parts.length ? parts[parts.length-1] : '';
}

function detectEnding(word){
  if(word.endsWith('ηλος')) return '-ηλος';
  if(word.endsWith('ελος')) return '-ελος';
  return '—';
}

function accentChar(baseVowel, accentType, poly){
  // accentType: 'acute' | 'none'
  if(accentType==='none') return baseVowel;
  // Use precomposed where possible.
  const acuteMap = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ'
  };
  // For polytonic we still use acute only (toy); monotonic same.
  return acuteMap[baseVowel] || baseVowel;
}

function applyAccentToSyllable(word, whichFromEnd, poly){
  // whichFromEnd: 1=ultima, 2=penult, 3=antepenult
  // Strategy: find vowel-group nuclei positions; accent the first vowel of the target group.
  const w = word;
  // collect nuclei indices
  let nuclei = [];
  let i=0;
  while(i<w.length){
    const c = w[i];
    if(isGreekVowel(c)){
      nuclei.push(i);
      const n = w[i+1] || '';
      const pair = c+n;
      if(['αι','ει','οι','υι','αυ','ευ','ηυ','ου','ωυ'].includes(pair)) i+=2;
      else i+=1;
      continue;
    }
    i++;
  }
  if(nuclei.length===0) return w;
  const idx = nuclei.length - whichFromEnd;
  if(idx < 0) return w; // not enough syllables
  const pos = nuclei[idx];
  const ch = w[pos];
  const accented = accentChar(ch,'acute',poly);
  return w.slice(0,pos) + accented + w.slice(pos+1);
}

function suggestAccent(phrase){
  const poly = (dial.value === 'poly');
  const raw = phrase;
  const normPhrase = normalizeGreek(raw);
  const w = lastWord(normPhrase);
  const ending = detectEnding(w);

  let target = '—';
  let why = '';
  let outPhrase = normPhrase;

  if(!w){
    return {norm:normPhrase, ending:'—', target:'—', out:'—', why:'Type something Greek.'};
  }

  // If user forces a mode
  const forced = mode.value;

  // Decide accent placement
  let which = null; // 1 or 3
  let decision = '';

  const syl = countSyllables(w);
  const wKey = w.toLowerCase();

  if(forced === 'none'){
    target = 'no accents';
    outPhrase = normPhrase; // already stripped
    why = 'Accents stripped (normalization removes diacritics).';
    return {norm:normPhrase, ending, target, out:outPhrase, why};
  }

  if(forced === 'proparox'){
    which = 3;
    decision = 'forced proparoxytone';
  } else if(forced === 'oxytone'){
    which = 1;
    decision = 'forced oxytone';
  } else {
    // auto toy rule
    if(PROPAROX_EXCEPTIONS.has(wKey)){
      which = 3;
      decision = 'known compound example → proparoxytone';
    } else if(OXYTONE_EXCEPTIONS.has(wKey)){
      which = 1;
      decision = 'listed/typical oxytone exception';
    } else if(ending === '-ηλος'){
      which = (syl >= 3) ? 3 : 1;
      decision = (syl >= 3)
        ? 'Herodian: many -ηλος (≥3 syllables) → proparoxytone'
        : 'too short for antepenult → fallback to oxytone';
    } else if(ending === '-ελος'){
      // crude proxy for “ὑπερδισύλλαβα”
      if(syl >= 3){
        which = 3;
        decision = 'toy: -ελος with ≥3 syllables → proparoxytone';
      } else {
        which = 1;
        decision = 'toy: short -ελος → oxytone';
      }
    } else {
      which = 1;
      decision = 'ending not recognized → default oxytone';
    }
  }

  // Apply accent to last word only
  const parts = normPhrase.split(' ');
  const last = parts.pop();
  const accentedLast = applyAccentToSyllable(last, which, poly);
  parts.push(accentedLast);
  outPhrase = parts.join(' ');

  target = (which === 3) ? 'proparoxytone (antepenult)' : 'oxytone (ultima)';
  why = `${decision}. Syllables (rough): ${syl}.`;

  return {norm:normPhrase, ending, target, out:outPhrase, why};
}

function render(){
  const res = suggestAccent(inp.value);
  elNorm.textContent = res.norm || '—';
  elEnding.textContent = res.ending;
  elTarget.textContent = res.target;
  elOut.textContent = res.out;
  elWhy.textContent = res.why;
}

btnGo.addEventListener('click', render);
inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') render(); });
mode.addEventListener('change', render);
dial.addEventListener('change', render);

btnRand.addEventListener('click', ()=>{
  const w = examples[Math.floor(Math.random()*examples.length)];
  inp.value = w;
  render();
});

btnClear.addEventListener('click', ()=>{
  inp.value='';
  render();
  inp.focus();
});

// chips
for(const b of document.querySelectorAll('button.chip')){
  b.addEventListener('click', ()=>{
    inp.value = b.getAttribute('data-w');
    render();
  });
}

// initial
render();

