(() => {
  const $ = (sel, el=document) => el.querySelector(sel);
  const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

  const inWord = $('#inWord');
  const outNorm = $('#outNorm');
  const outEnding = $('#outEnding');
  const outSyl = $('#outSyl');
  const outAcc = $('#outAcc');
  const outWhy = $('#outWhy');
  const outFlip = $('#outFlip');

  const optFeminine = $('#optFeminine');
  const optLongI = $('#optLongI');
  const optAlphaCluster = $('#optAlphaCluster');
  const optKeepBreathings = $('#optKeepBreathings');

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ','ϊ','ϋ','ΐ','ΰ','ᾳ','ῃ','ῳ','Α','Ε','Η','Ι','Ο','Υ','Ω','Ά','Έ','Ή','Ί','Ό','Ύ','Ώ','Ϊ','Ϋ']);

  // Remove accents; optionally keep breathings/diaeresis.
  function stripAccents(s, keepBreathings=true){
    if(!s) return '';
    // NFD splits combining marks.
    let n = s.normalize('NFD');
    // Greek combining marks: tonos/oxia (0301), varia (0300), perispomeni (0342), dialytika (0308), breathings (0313/0314), iota subscript (0345)
    // We always remove accent marks; optionally keep breathings/diaeresis/iota-subscript.
    const remove = new Set(['\u0301','\u0300','\u0342']);
    const removeAlso = new Set(['\u0313','\u0314','\u0308','\u0345']);
    let out = '';
    for(const ch of n){
      if(remove.has(ch)) continue;
      if(!keepBreathings && removeAlso.has(ch)) continue;
      out += ch;
    }
    return out.normalize('NFC');
  }

  function lastNChars(s, n){
    return s.slice(Math.max(0, s.length - n));
  }

  function detectEnding(norm){
    const low = norm;
    if(low.endsWith('ηλος') || low.endsWith('ηλον') || low.endsWith('ηλοι') || low.endsWith('ηλου')) return '-ηλος';
    if(low.endsWith('ιλος') || low.endsWith('ιλον') || low.endsWith('ιλοι') || low.endsWith('ιλου')) return '-ιλος';
    return '—';
  }

  // Very rough syllabification: split before each vowel-group.
  function syllabifyRough(s){
    const t = s;
    const groups = [];
    let cur = '';
    let inV = false;

    const isV = (ch) => {
      const base = ch.normalize('NFD')[0];
      return vowels.has(ch) || vowels.has(base);
    };

    for(let i=0;i<t.length;i++){
      const ch = t[i];
      const v = isV(ch);
      if(cur === ''){
        cur = ch;
        inV = v;
        continue;
      }
      // Start new syllable when we encounter a vowel after having already seen a vowel in current syllable
      // OR when current has no vowel yet and we hit first vowel (keep in same syllable).
      if(v && inV){
        groups.push(cur);
        cur = ch;
        inV = true;
      } else {
        cur += ch;
        if(v) inV = true;
      }
    }
    if(cur) groups.push(cur);

    // Ensure each syllable contains a vowel; if not, merge with previous.
    const fixed = [];
    const hasVowel = (chunk) => Array.from(chunk).some(isV);
    for(const g of groups){
      if(fixed.length === 0){ fixed.push(g); continue; }
      if(!hasVowel(g)) fixed[fixed.length-1] += g;
      else fixed.push(g);
    }
    return fixed;
  }

  function addAcuteToVowel(vowelChar){
    // Map base vowels to precomposed acute forms when possible.
    const map = {
      'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
      'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ',
      'ϊ':'ΐ','ϋ':'ΰ','Ϊ':'Ϊ','Ϋ':'Ϋ'
    };
    if(map[vowelChar]) return map[vowelChar];
    // Fallback: add combining acute.
    return vowelChar.normalize('NFD') + '\u0301';
  }

  function accentSyllable(word, syllables, whichFromEnd){
    // whichFromEnd: 1=ultima,2=penult,3=antepenult
    const idx = syllables.length - whichFromEnd;
    if(idx < 0 || idx >= syllables.length) return word;

    const isV = (ch) => {
      const base = ch.normalize('NFD')[0];
      return vowels.has(ch) || vowels.has(base);
    };

    const syl = syllables[idx];
    // Accent the first vowel in the syllable.
    let accentedSyl = '';
    let done = false;
    for(const ch of syl){
      if(!done && isV(ch)){
        accentedSyl += addAcuteToVowel(ch);
        done = true;
      } else {
        accentedSyl += ch;
      }
    }
    const outSyls = syllables.slice();
    outSyls[idx] = accentedSyl;
    return outSyls.join('');
  }

  function suggestAccent(norm, ending, syllables){
    const n = syllables.length;
    if(ending === '-ηλος'){
      if(n >= 3 && optFeminine.checked){
        return {pos:1, why:"-ηλος (≥3 syllables) + ‘has feminine’ → oxytone (ultima), per Herodian’s list (σιγηλός, μιμηλός…)."};
      }
      // Otherwise default to penult as a neutral guess.
      return {pos:2, why:"-ηλος but not using the ‘has feminine’ oxytone rule → default guess: paroxytone (penult)."};
    }

    if(ending === '-ιλος'){
      // If long i and not blocked by alpha+cluster, go antepenult.
      if(optLongI.checked && !optAlphaCluster.checked){
        return {pos:3, why:"-ιλος with ‘lengthened ι’ → proparoxytone (antepenult), unless blocked (Herodian: στρόβιλος, ὅμιλος…)."};
      }
      // If blocked, or short i, go penult.
      if(optAlphaCluster.checked){
        return {pos:2, why:"Proparoxytone blocked by ‘3rd syllable α + consonant cluster’ (toy switch) → paroxytone (penult)."};
      }
      return {pos:2, why:"-ιλος with short ι → usually paroxytone (penult): …-ίλος (Herodian’s general rule)."};
    }

    // Unknown ending: accent penult if possible.
    return {pos: Math.min(2, n), why:"Ending not recognized as -ηλος/-ιλος → default guess: accent the penult (if possible)."};
  }

  function render(){
    const raw = (inWord.value || '').trim();
    if(!raw){
      outNorm.textContent = '—';
      outEnding.textContent = '—';
      outSyl.textContent = '—';
      outAcc.textContent = '—';
      outWhy.textContent = '—';
      outFlip.textContent = '—';
      return;
    }

    const norm = stripAccents(raw, optKeepBreathings.checked);
    const ending = detectEnding(norm);
    const syls = syllabifyRough(norm);

    outNorm.textContent = norm;
    outEnding.textContent = ending;
    outSyl.textContent = syls.join(' · ');

    const sug = suggestAccent(norm, ending, syls);
    const accented = accentSyllable(norm, syls, sug.pos);

    outAcc.textContent = accented.normalize('NFC');
    outWhy.textContent = sug.why;

    // Default flip starts from suggested.
    outFlip.textContent = flipAccent(accented, syls, sug.pos);
  }

  function flipAccent(currentAccented, syllables, currentPos){
    // Cycle 1->2->3->1 (ultima, penult, antepenult)
    const nextPos = currentPos === 1 ? 2 : (currentPos === 2 ? 3 : 1);
    const norm = stripAccents(currentAccented, optKeepBreathings.checked);
    const syls = syllabifyRough(norm);
    return accentSyllable(norm, syls, Math.min(nextPos, syls.length)).normalize('NFC');
  }

  function accentNow(){
    render();
  }

  $('#btnAccent').addEventListener('click', accentNow);
  $('#btnClear').addEventListener('click', () => { inWord.value=''; inWord.focus(); render(); });

  // Live update on input and option changes.
  inWord.addEventListener('input', () => render());
  [optFeminine,optLongI,optAlphaCluster,optKeepBreathings].forEach(el => el.addEventListener('change', render));

  // Flip button: recompute suggested pos, then flip.
  $('#btnFlip').addEventListener('click', () => {
    const raw = (inWord.value || '').trim();
    if(!raw) return;
    const norm = stripAccents(raw, optKeepBreathings.checked);
    const ending = detectEnding(norm);
    const syls = syllabifyRough(norm);
    const sug = suggestAccent(norm, ending, syls);
    const accented = accentSyllable(norm, syls, sug.pos);
    outFlip.textContent = flipAccent(accented, syls, sug.pos);
  });

  // Pills
  $$('.pill').forEach(p => p.addEventListener('click', () => {
    inWord.value = p.getAttribute('data-fill');
    inWord.focus();
    render();
  }));

  // Seed
  inWord.value = 'στροβιλος';
  render();
})();

