(() => {
  const $ = (s, r=document) => r.querySelector(s);
  const inp = $('#inp');
  const outWord = $('#outWord');
  const outRule = $('#outRule');
  const syllablesEl = $('#syllables');
  const accentPosEl = $('#accentPos');
  const chipsEl = $('#chips');

  const examples = [
    'τρίχειλος','ἀγκυλόχειλος','κροκόδειλος','εὔειλος',
    'Αἴολος','Θετταλός','Ἰταλός','ἄσβολος','εὔκολος','διάβολος',
    'αἰόλος','βουκόλος','ὀβολός',
    'κρωβύλος','Κρωβύλος','κηρύλος','Αἰσχύλος','Ῥωμύλος','Σιμύλος','Ἡδύλος','Τουσσύλος',
    'βαιτύλος','Δημύλος','βηθύλος','Οἴτυλος','Ὤγυλος',
    'αἴσυλος','στωμύλος','αἱμύλος','στρογγύλος'
  ];

  function stripDiacriticsKeepLetters(s){
    // Remove combining marks; keep Greek letters.
    return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  }

  function lowerGreek(s){
    return stripDiacriticsKeepLetters(s).toLowerCase();
  }

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω']);
  const diphthongs = ['αι','ει','οι','ου','αυ','ευ','ηυ','υι'];

  function roughSyllabify(word){
    // Very rough: split after each vowel/diphthong nucleus.
    const w = lowerGreek(word).replace(/[^\p{Script=Greek}]/gu,'');
    if(!w) return [];
    let i=0;
    const syl=[];
    let cur='';
    while(i<w.length){
      // try diphthong
      let nucleus = null;
      for(const d of diphthongs){
        if(w.startsWith(d,i)) { nucleus=d; break; }
      }
      const ch = w[i];
      cur += ch;
      if(nucleus){
        // we already added first char; add second
        cur += w[i+1];
        i += 2;
        syl.push(cur);
        cur='';
        continue;
      }
      if(vowels.has(ch)){
        i++;
        syl.push(cur);
        cur='';
        continue;
      }
      i++;
    }
    if(cur) syl[syl.length-1] = (syl[syl.length-1]||'') + cur;
    // Merge leading consonants into first syllable if we started with consonants
    // (already happens), but if first syllable has no vowel, glue it.
    if(syl.length>=2 && ![...syl[0]].some(c=>vowels.has(c))){
      syl[1] = syl[0] + syl[1];
      syl.shift();
    }
    return syl.filter(x=>x.length);
  }

  function initialNaturallyLongToy(word){
    const w = lowerGreek(word).replace(/[^\p{Script=Greek}]/gu,'');
    if(!w) return false;
    const starts = ['αι','ει','οι','ου','αυ','ευ','η','ω'];
    return starts.some(st => w.startsWith(st));
  }

  function findAccentTargetIndex(syl, kind){
    // kind: 'ultima'|'penult'|'antepenult'
    const n = syl.length;
    if(n===0) return -1;
    if(kind==='ultima') return n-1;
    if(kind==='penult') return Math.max(0,n-2);
    if(kind==='antepenult') return Math.max(0,n-3);
    return n-1;
  }

  function addAcuteToSyllable(syll){
    // Add acute to the first vowel of the syllable nucleus.
    const map = {
      'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
      'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
    };
    // Work on NFC Greek letters; if already accented, leave.
    if(/[άέήίόύώΆΈΉΊΌΎΏ]/.test(syll)) return syll;
    // Prefer diphthong second element? Toy: accent first vowel encountered.
    for(let i=0;i<syll.length;i++){
      const ch = syll[i];
      if(map[ch]) return syll.slice(0,i) + map[ch] + syll.slice(i+1);
    }
    return syll;
  }

  function guessRule(word){
    const raw = word.trim();
    const w = lowerGreek(raw);

    // Special lexical exceptions mentioned.
    if(w === 'αιολος') return {kind:'penult', rule:'Exception: αἰόλος (name/epithet) → penult', conf:'ok'};
    if(w === 'βουκολος') return {kind:'penult', rule:'Exception: βουκόλος (from a verb) → penult', conf:'ok'};
    if(w === 'οβολος') return {kind:'ultima', rule:'Exception: ὀβολός → ultima', conf:'ok'};

    if(w.endsWith('ειλος')){
      return {kind:'antepenult', rule:'-ειλος compounds (polysyllabic, from a noun) → antepenult', conf:'ok'};
    }
    if(w.endsWith('ολος')){
      return {kind:'antepenult', rule:'-ολος simple names/appellatives (>2 syllables) → antepenult', conf:'warn'};
    }
    if(w.endsWith('υλος')){
      const syl = roughSyllabify(raw);
      const isTri = syl.length===3;
      const longStart = initialNaturallyLongToy(raw);
      if(isTri && longStart){
        return {kind:'penult', rule:'-υλος trisyllable + “long” start (toy) → penult', conf:'ok'};
      }
      if(isTri && !longStart){
        return {kind:'penult', rule:'-υλος trisyllable (toy default) → penult (low confidence)', conf:'warn'};
      }
      return {kind:'penult', rule:'-υλος (toy default) → penult', conf:'warn'};
    }

    // fallback: if 3+ syllables, antepenult; else penult
    const syl = roughSyllabify(raw);
    if(syl.length>=3) return {kind:'antepenult', rule:'Fallback: 3+ syllables → antepenult (toy)', conf:'bad'};
    return {kind:'penult', rule:'Fallback: 1–2 syllables → penult (toy)', conf:'bad'};
  }

  function render(word){
    const raw = word.trim();
    if(!raw){
      outWord.textContent = '—';
      outRule.textContent = 'Rule: —';
      syllablesEl.textContent = '—';
      accentPosEl.textContent = 'Accent target: —';
      return;
    }

    const syl = roughSyllabify(raw);
    const g = guessRule(raw);
    const idx = findAccentTargetIndex(syl, g.kind);

    const sylAcc = syl.map((s,i)=> i===idx ? addAcuteToSyllable(s) : s);
    const suggested = sylAcc.join('');

    outWord.textContent = suggested || raw;

    const badgeClass = g.conf;
    const badgeText = g.conf==='ok' ? 'higher confidence' : (g.conf==='warn' ? 'medium' : 'low');
    outRule.innerHTML = `Rule: ${escapeHtml(g.rule)} <span class="badge ${badgeClass}">${badgeText}</span>`;

    syllablesEl.innerHTML = '';
    if(syl.length===0){
      syllablesEl.textContent = '(could not syllabify)';
    } else {
      syl.forEach((s,i)=>{
        const d = document.createElement('div');
        d.className = 'syl' + (i===idx ? ' target' : '');
        d.innerHTML = `<span>${escapeHtml(s)}</span>` + (i===idx ? `<span class="mark">´</span>` : '');
        syllablesEl.appendChild(d);
      });
    }

    const label = (g.kind==='ultima') ? 'ultima (last)' : (g.kind==='penult' ? 'penult (2nd last)' : 'antepenult (3rd last)');
    accentPosEl.textContent = `Accent target: ${label}`;
  }

  function escapeHtml(s){
    return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  function buildChips(){
    chipsEl.innerHTML='';
    const uniq = [...new Set(examples)];
    uniq.forEach(w=>{
      const b = document.createElement('button');
      b.type='button';
      b.className='chip';
      b.textContent = w;
      b.addEventListener('click', ()=>{ inp.value = w; render(w); inp.focus(); });
      chipsEl.appendChild(b);
    });
  }

  $('#btnGuess').addEventListener('click', ()=>render(inp.value));
  $('#btnClear').addEventListener('click', ()=>{ inp.value=''; render(''); inp.focus(); });
  $('#btnRandom').addEventListener('click', ()=>{
    const w = examples[Math.floor(Math.random()*examples.length)];
    inp.value = stripDiacriticsKeepLetters(w); // show unaccented-ish input to make the toy do work
    render(inp.value);
    inp.focus();
  });
  inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') render(inp.value); });
  inp.addEventListener('input', ()=>{ if(inp.value.trim().length===0) render(''); });

  buildChips();
  render('');
})();

