const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => Array.from(document.querySelectorAll(sel));

const examples = [
  {w:"γογγυλος", note:"appellative → antepenult"},
  {w:"δακτυλος", note:"appellative → antepenult"},
  {w:"κονδυλος", note:"appellative → antepenult"},
  {w:"σφονδυλος", note:"appellative → antepenult"},
  {w:"Δερκυλος", note:"proper (long 1st) → penult"},
  {w:"Βακχυλος", note:"proper (long 1st) → penult"},
  {w:"Χαρμυλος", note:"proper (long 1st) → penult"},
  {w:"Αξυλος", note:"exception: proper but like appellatives"},
  {w:"Οξυλος", note:"exception: proper but like appellatives"},
  {w:"Σιπυλος", note:"place-name"},
  {w:"Χρεμυλος", note:"penult (Herodian’s note)"},
  {w:"Κρατυλος", note:"penult (Herodian’s note)"},
  {w:"Αγυλος", note:"proper → antepenult (Herodian’s note)"},
  {w:"ερωτυλος", note:">3? (toy) compound-ish → antepenult"},
  {w:"ιαμβυλος", note:"compound-ish"},
  {w:"Ονησυλος", note:"compound-ish"},
  {w:"Νικασυλος", note:"compound-ish"},
  {w:"ευρυπυλος", note:"compound"},
  {w:"Κιμωλος", note:"-ωλος exception (…τω…)"},
  {w:"Μαυσωλος", note:"-ωλος"},
  {w:"φασκωλος", note:"-ωλος"},
  {w:"Εριγμωλος", note:"-ωλος"}
];

function stripDiacritics(s){
  // remove combining marks; also normalize tonos/oxia variants
  return (s||"")
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'')
    .normalize('NFC');
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code>=0x0370 && code<=0x03FF) || (code>=0x1F00 && code<=0x1FFF);
}

function tokenizeGreek(s){
  // keep only Greek letters; drop punctuation/spaces
  const n = stripDiacritics(s);
  let out = "";
  for (const ch of n){
    if (isGreekLetter(ch)) out += ch;
  }
  return out;
}

const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);
const diph = new Set(["αι","ει","οι","υι","αυ","ευ","ου","ηυ","ΑΙ","ΕΙ","ΟΙ","ΥΙ","ΑΥ","ΕΥ","ΟΥ","ΗΥ"]);

function syllabifyToy(word){
  // Very rough: split into syllables by vowel nuclei (vowel or diphthong).
  // We attach preceding consonants to the syllable.
  const w = tokenizeGreek(word);
  if (!w) return [];

  let i=0;
  const syl = [];
  let current = "";

  while (i < w.length){
    const ch = w[i];
    const next = w[i+1] || "";

    if (!vowels.has(ch)){
      current += ch;
      i++;
      continue;
    }

    // vowel nucleus
    let nucleus = ch;
    if (next && vowels.has(next)){
      const pair = ch+next;
      if (diph.has(pair)){
        nucleus = pair;
        i += 2;
      } else {
        // hiatus: end syllable at first vowel
        i += 1;
      }
    } else {
      i += 1;
    }

    current += nucleus;
    syl.push(current);
    current = "";
  }
  if (current) syl[syl.length-1] = (syl[syl.length-1]||"") + current;
  return syl;
}

function endsWithAny(w, arr){
  return arr.some(suf => w.endsWith(suf));
}

function guessKindAuto(raw){
  // crude: initial uppercase => proper
  const t = raw.trim();
  const first = t[0] || "";
  if (first && first === first.toUpperCase() && first !== first.toLowerCase()) return "proper";
  return "appellative";
}

function hasIInThirdSyllable(syl){
  // third syllable from start (index 2)
  if (syl.length < 3) return false;
  return syl[2].includes("ι") || syl[2].includes("Ι");
}

function hasTwoConsonantsBeforeOmegaWithSecondTau(w){
  // For -ωλος rule: check pattern ..C T ωλος (two consonants before ω, second is τ)
  // We'll look for "τωλο" with a consonant immediately before τ.
  const s = tokenizeGreek(w);
  const idx = s.toLowerCase().lastIndexOf("τωλο");
  if (idx <= 0) return false;
  const prev = s[idx-1];
  if (!prev) return false;
  return !vowels.has(prev);
}

function applyAcuteToVowelInSyllable(syll){
  // Put acute on the last vowel of the syllable nucleus.
  // Map plain vowels to tonos forms.
  const map = {
    "α":"ά","ε":"έ","η":"ή","ι":"ί","ο":"ό","υ":"ύ","ω":"ώ",
    "Α":"Ά","Ε":"Έ","Η":"Ή","Ι":"Ί","Ο":"Ό","Υ":"Ύ","Ω":"Ώ"
  };
  // find last vowel char in syll
  for (let i=syll.length-1;i>=0;i--){
    const ch = syll[i];
    if (vowels.has(ch)){
      const rep = map[ch] || ch;
      return syll.slice(0,i) + rep + syll.slice(i+1);
    }
  }
  return syll;
}

function accentByIndex(syl, idxFromEnd){
  // idxFromEnd: 1=ultima,2=penult,3=antepenult
  const n = syl.length;
  const idx = n - idxFromEnd;
  if (idx < 0 || idx >= n) return {word: syl.join(""), idx: null};
  const out = syl.slice();
  out[idx] = applyAcuteToVowelInSyllable(out[idx]);
  return {word: out.join(""), idx};
}

function analyze(raw){
  const cleaned = tokenizeGreek(raw);
  const syl = syllabifyToy(raw);
  const lower = cleaned.toLowerCase();

  const kindSel = document.querySelector('input[name="kind"]:checked').value;
  const compound = $('#compound').checked;
  const kind = (kindSel === "auto") ? guessKindAuto(raw) : kindSel;

  let rule = "";
  let why = "";
  let target = null; // 2 penult, 3 antepenult
  let alt = null;

  const isUlos = endsWithAny(lower, ["υλος"]);
  const isOlos = endsWithAny(lower, ["ωλος"]);

  const exceptionsAnte = new Set(["αξυλος","οξυλος","αγυλος"]);
  const exceptionsPen = new Set(["χρεμυλος","κρατυλος"]);

  if (!cleaned){
    rule = "(nothing to analyze)";
    return {cleaned, syl, kind, rule, why, target, alt};
  }

  if (!(isUlos || isOlos)){
    rule = "Not a -υλος / -ωλος word";
    why = "Herodian’s passage focuses on these endings; the toy only accents those.";
    return {cleaned, syl, kind, rule, why, target, alt};
  }

  if (isUlos){
    if (exceptionsAnte.has(lower)){
      target = 3;
      rule = "Exception noted by Herodian";
      why = `${cleaned} is treated with antepenult accent in the passage.`;
    } else if (exceptionsPen.has(lower)){
      target = 2;
      rule = "Exception noted by Herodian";
      why = `${cleaned} is accented on the penult in the passage.`;
    } else if (syl.length === 3){
      // trisyllables in -υλος
      if (kind === "proper"){
        // we can’t really compute vowel length; offer a toggle-ish explanation
        target = 2;
        alt = 3;
        rule = "Trisyllabic -υλος: proper vs appellative";
        why = "Herodian: proper names (with long 1st syllable) tend to be penult; appellatives tend to be antepenult. Length is not computed here, so an alternative is shown.";
      } else {
        target = 3;
        alt = 2;
        rule = "Trisyllabic -υλος: appellatives";
        why = "Herodian: appellatives in -υλος (3 syllables) are usually antepenult.";
      }

      // extra mini-rule: tribranchs with i in 3rd syllable => antepenult
      if (hasIInThirdSyllable(syl)){
        target = 3;
        rule = "Tribranch note: ι in the 3rd syllable";
        why = "Herodian: if the 3rd syllable contains ι, accent tends to be antepenult.";
      }
    } else if (syl.length > 3){
      if (compound){
        target = 3;
        rule = "-υλος >3 syllables: compound-ish";
        why = "Herodian: longer -υλος words are penult unless they have a sense of composition; this checkbox forces the ‘compound’ behavior.";
      } else {
        target = 2;
        rule = "-υλος >3 syllables";
        why = "Herodian: longer -υλος words tend to be accented on the penult (unless compound).";
      }
    } else {
      rule = "Too short / unclear syllables";
      why = "Need at least 2–3 syllables for these rules to make sense.";
    }
  }

  if (isOlos){
    // -ωλος: antepenult, unless ...CTωλος pattern
    if (syl.length <= 2){
      rule = "-ωλος rule applies to >2 syllables";
      why = "Herodian’s note is for words in -ωλος of more than two syllables.";
    } else {
      if (hasTwoConsonantsBeforeOmegaWithSecondTau(raw)){
        target = 2;
        rule = "-ωλος exception: …Cτωλος";
        why = "Herodian: if two consonants stand before ω in combination and the second is τ, accent shifts to the penult (toy check: …Cτωλο…).";
      } else {
        target = 3;
        rule = "-ωλος (>2 syllables)";
        why = "Herodian: monogenic -ωλος words (>2 syllables) are antepenult by default.";
      }
    }
  }

  return {cleaned, syl, kind, rule, why, target, alt};
}

function render(){
  const raw = $('#inp').value;
  const a = analyze(raw);

  const sylStr = a.syl.length ? a.syl.join(" · ") : "—";
  $('#syll').textContent = sylStr;

  if (!a.target){
    $('#resMain').textContent = a.cleaned ? a.cleaned : "—";
    $('#resAlt').textContent = "";
  } else {
    const main = accentByIndex(a.syl, a.target).word;
    $('#resMain').textContent = main;

    if (a.alt){
      const alt = accentByIndex(a.syl, a.alt).word;
      $('#resAlt').innerHTML = `Alternative: <span class="mono">${alt}</span>`;
    } else {
      $('#resAlt').textContent = "";
    }
  }

  $('#rule').textContent = a.rule || "—";
  $('#why').textContent = a.why || "—";
}

function mountExamples(){
  const box = $('#examples');
  box.innerHTML = "";
  for (const ex of examples){
    const b = document.createElement('button');
    b.className = 'ex';
    b.type = 'button';
    b.textContent = ex.w;
    b.title = ex.note;
    b.addEventListener('click', () => {
      $('#inp').value = ex.w;
      // auto-select kind based on capitalization
      document.querySelector('input[name="kind"][value="auto"]').checked = true;
      $('#compound').checked = false;
      render();
      $('#inp').focus();
    });
    box.appendChild(b);
  }
}

$('#btn').addEventListener('click', render);
$('#btnClear').addEventListener('click', () => { $('#inp').value=''; render(); $('#inp').focus(); });
$('#inp').addEventListener('keydown', (e) => { if (e.key === 'Enter') render(); });
$$('input[name="kind"]').forEach(r => r.addEventListener('change', render));
$('#compound').addEventListener('change', render);

mountExamples();
render();

