const $ = (s)=>document.querySelector(s);

const examples = [
  "Καστωλος",
  "Πακτωλος",
  "Σπαρτωλος",
  "Αἰτωλος",
  "ἁμαρτωλος",
  "φειδωλος",
  "ἑωλος",
  "διαυλος",
  "θυραυλος",
  "Γαιτουλος",
  "Τουρδουλος",
  "Μαυσωλος"
];

const vowels = new Set(["α","ε","η","ι","ο","υ","ω","ά","έ","ή","ί","ό","ύ","ώ","ὰ","ὲ","ὴ","ὶ","ὸ","ὺ","ὼ","ᾶ","ῖ","ῦ","ῶ",
  "ἀ","ἁ","ἂ","ἃ","ἄ","ἅ","ἆ","ἇ","ἐ","ἑ","ἒ","ἓ","ἔ","ἕ","ἠ","ἡ","ἢ","ἣ","ἤ","ἥ","ἦ","ἧ",
  "ἰ","ἱ","ἲ","ἳ","ἴ","ἵ","ἶ","ἷ","ὀ","ὁ","ὂ","ὃ","ὄ","ὅ","ὑ","ὓ","ὕ","ὗ","ὠ","ὡ","ὢ","ὣ","ὤ","ὥ","ὦ","ὧ",
  "ϊ","ϋ","ΐ","ΰ","ῒ","ῢ","ῗ","ῧ"]);

function stripDiacritics(s){
  // Remove combining marks; keep base Greek letters.
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function lowerGreek(s){
  return stripDiacritics(s).toLowerCase();
}

function isVowelChar(ch){
  return vowels.has(ch) || vowels.has(stripDiacritics(ch));
}

function syllabifyToy(word){
  // Very rough syllable splitter: start a new syllable at each vowel nucleus.
  // Treat αυ, ευ, ου, αι, ει, οι, υι as a single nucleus.
  const w = stripDiacritics(word);
  const chars = Array.from(w);
  const nuclei = new Set(["αι","ει","οι","υι","αυ","ευ","ου","ηυ"]);

  let sylls = [];
  let cur = "";
  for(let i=0;i<chars.length;i++){
    const ch = chars[i];
    const next = chars[i+1]||"";
    cur += ch;

    const pair = (ch+next);
    const chIsV = isVowelChar(ch);
    const pairIsNucleus = nuclei.has(pair);

    if(pairIsNucleus){
      // include next char in nucleus
      cur += next;
      i++;
      // close syllable after nucleus if more letters follow
      if(i < chars.length-1){
        sylls.push(cur);
        cur = "";
      }
      continue;
    }

    if(chIsV){
      if(i < chars.length-1){
        sylls.push(cur);
        cur = "";
      }
    }
  }
  if(cur) sylls.push(cur);

  // Post-fix: if we produced 1 syllable but word has multiple vowels, keep as-is.
  return sylls.filter(x=>x.length>0);
}

function addAcuteOnVowel(syll){
  // Add acute to the first vowel of the syllable (toy).
  const map = {
    "α":"ά","ε":"έ","η":"ή","ι":"ί","ο":"ό","υ":"ύ","ω":"ώ",
    "Α":"Ά","Ε":"Έ","Η":"Ή","Ι":"Ί","Ο":"Ό","Υ":"Ύ","Ω":"Ώ"
  };
  const chars = Array.from(syll);
  for(let i=0;i<chars.length;i++){
    const base = stripDiacritics(chars[i]);
    if(map[base]){
      // preserve case by using base
      const isUpper = base === base.toUpperCase() && base !== base.toLowerCase();
      const key = isUpper ? base.toUpperCase() : base.toLowerCase();
      chars[i] = map[key];
      return chars.join("");
    }
  }
  return syll;
}

function accentWordToy(input){
  const raw = input.trim();
  if(!raw) return {out:"—", explain:"Type a word above.", syll:"—"};

  // Only accent the first token; keep rest as tail.
  const parts = raw.split(/\s+/);
  const first = parts[0];
  const tail = parts.slice(1).join(" ");

  const base = stripDiacritics(first);
  const low = base.toLowerCase();

  const sylls = syllabifyToy(base);
  const syllStr = sylls.map((s,i)=>`${i+1}:${s}`).join(" | ");

  function rebuild(accentIndexFromEnd){
    // accentIndexFromEnd: 1=ultima,2=penult,3=antepenult
    const n = sylls.length;
    const idx = n - accentIndexFromEnd;
    if(idx < 0 || idx >= n) return base;
    const outSylls = sylls.slice();
    outSylls[idx] = addAcuteOnVowel(outSylls[idx]);
    return outSylls.join("");
  }

  // Rules from passage (toy)
  let rule = null;
  let accented = base;

  if(low === "εωλος" || low === "ἑωλος" || low === "heolos"){
    rule = "Special case: ἕωλος is proparoxytone (accent on antepenult).";
    accented = rebuild(3);
  } else if(low.endsWith("ωλος")){
    if(low.endsWith("τωλος")){
      rule = "-ωλος with τ before ω (…τωλος): oxytone (accent on ultima), like Καστωλός / Πακτωλός.";
      accented = rebuild(1);
    } else {
      rule = "Ends in -ωλος but no …τωλος detected: this toy does not decide; leaving unaccented.";
      accented = base;
    }
  } else if(low.endsWith("αυλος") || low.endsWith("ουλος")){
    if(sylls.length >= 3){
      rule = "-αυλος / -ουλος with >2 syllables: proparoxytone (accent on antepenult), like δίαυλος / θύραυλος / Γαίτουλος.";
      accented = rebuild(3);
    } else {
      rule = "-αυλος / -ουλος but too short for proparoxytone in this toy; leaving unaccented.";
      accented = base;
    }
  } else {
    rule = "No matching ending rule in this toy; leaving unaccented.";
    accented = base;
  }

  const out = tail ? `${accented} ${tail}` : accented;
  return {out, explain: rule, syll: syllStr || "(could not syllabify)"};
}

function render(){
  const v = $("#in").value;
  const res = accentWordToy(v);
  $("#out").textContent = res.out;
  $("#explain").textContent = res.explain;
  $("#syll").textContent = res.syll;
}

function makeChips(){
  const box = $("#chips");
  examples.forEach(w=>{
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip';
    b.textContent = w;
    b.addEventListener('click', ()=>{ $("#in").value = w; render(); $("#in").focus(); });
    box.appendChild(b);
  });
}

$("#analyze").addEventListener('click', render);
$("#clear").addEventListener('click', ()=>{ $("#in").value=""; render(); $("#in").focus(); });
$("#in").addEventListener('input', ()=>{ render(); });

makeChips();
render();

