const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const endingEl = $('#ending');
const preMuEl = $('#preMu');
const ruleEl = $('#rule');
const accentedEl = $('#accented');
const syllEl = $('#syll');

const stripBox = $('#strip');
const showSyllBox = $('#showSyll');

// Examples drawn from the passage (some without accents to show the toy adding them)
const examples = [
  'νυγμος','φραγμος','αγμος','ψυγμος','λυγμος','ρωγμος','δραγμος','τιναγμος','αλαλαγμος','υλαγμος','διωγμος','παιγμος','εμπαιγμος','κηρυγμος','εκκηρυγμος',
  'ογμος','Ριγμος',
  'αρδμος','σκιαδμος','Καδμος','Κυδμος',
  'βαθμος','ισθμος','σταθμος','αυχμος','πορθμος','πλοχμος'
];

// --- Unicode helpers ---
const COMBINING = /[\u0300-\u036f]/g;
const tonos = '\u0301'; // combining acute

function stripDiacritics(s){
  // Remove combining marks; also normalize to decomposed first.
  return s.normalize('NFD').replace(COMBINING,'').normalize('NFC');
}

function isGreekCapital(ch){
  // Basic Greek uppercase range plus a few with tonos/dialytika stripped.
  const base = stripDiacritics(ch);
  return base >= 'Α' && base <= 'Ω';
}

function endsWithMos(s){
  const base = stripDiacritics(s).toLowerCase();
  return base.endsWith('μος');
}

function consonantBeforeMu(s){
  const base = stripDiacritics(s).toLowerCase();
  // Find last occurrence of 'μ' that is part of final -μος
  if(!base.endsWith('μος')) return null;
  const idxMu = base.lastIndexOf('μ');
  if(idxMu <= 0) return null;
  return base[idxMu-1];
}

function applyAcuteOnOmicronOfMos(original){
  // Put acute on the omicron of the final -μος: ...μ + ό + ς
  // We do this by locating the final "ος" and adding combining acute to ο.
  let s = original.normalize('NFD');
  // Work on stripped base for indexing, but apply to NFD string by mapping.
  const base = stripDiacritics(original).toLowerCase();
  const pos = base.lastIndexOf('ος');
  if(pos < 0) return original;

  // Build a mapping from base indices to NFD indices.
  const nfd = original.normalize('NFD');
  let map = []; // baseIndex -> nfdIndex
  let b = '';
  for(let i=0, bi=0; i<nfd.length; i++){
    const ch = nfd[i];
    const isComb = COMBINING.test(ch);
    COMBINING.lastIndex = 0;
    if(isComb) continue;
    const baseCh = stripDiacritics(ch);
    // baseCh may be multiple chars rarely; handle simply
    for(let k=0;k<baseCh.length;k++){
      map[bi++] = i;
    }
  }

  const oIndexBase = pos; // the 'ο' of final -ος
  const oIndexNfd = map[oIndexBase];
  if(oIndexNfd == null) return original;

  // Remove any existing combining marks immediately after that omicron.
  let out = '';
  for(let i=0;i<nfd.length;i++){
    out += nfd[i];
    if(i === oIndexNfd){
      // skip following combining marks
      let j=i+1;
      while(j<nfd.length && COMBINING.test(nfd[j])) j++;
      COMBINING.lastIndex = 0;
      out += tonos;
      i = j-1;
    }
  }
  return out.normalize('NFC');
}

function applyNoExtraAccent(original){
  // For barytone suggestion we simply return a cleaned version (optionally stripped)
  return original;
}

function naiveSyllables(word){
  // Very rough syllable splitter for Greek: split after each vowel group.
  const w = stripDiacritics(word).toLowerCase();
  const vowels = 'αεηιουω';
  let parts = [];
  let cur = '';
  for(let i=0;i<w.length;i++){
    cur += w[i];
    const ch = w[i];
    const next = w[i+1] || '';
    const isV = vowels.includes(ch);
    const nextIsV = vowels.includes(next);
    if(isV && !nextIsV){
      parts.push(cur);
      cur='';
    }
  }
  if(cur) parts.push(cur);
  // If we got too many tiny parts, just return the word.
  if(parts.length < 2) return [w];
  return parts;
}

function analyze(raw){
  const original = raw.trim();
  if(!original){
    endingEl.textContent = '—';
    preMuEl.textContent = '—';
    ruleEl.textContent = '—';
    accentedEl.textContent = '—';
    syllEl.textContent = '';
    return;
  }

  const input = stripBox.checked ? stripDiacritics(original) : original;
  const base = stripDiacritics(input);

  const hasMos = endsWithMos(base);
  endingEl.textContent = hasMos ? '-μος' : '(not -μος)';

  if(!hasMos){
    preMuEl.textContent = '—';
    ruleEl.innerHTML = '<span class="warn">This toy only knows the -μος corner of the passage.</span>';
    accentedEl.textContent = input;
    syllEl.textContent = '';
    return;
  }

  const pre = consonantBeforeMu(base);
  preMuEl.textContent = pre ? pre : '—';

  // Exception: ὄγμος (barytone)
  const baseLower = stripDiacritics(base).toLowerCase();
  const isOgmos = baseLower === 'ογμος' || baseLower === 'ὀγμος';

  const properNameGuess = isGreekCapital(base[0] || '');

  let guess = {type:'?', label:'', className:''};

  if(isOgmos){
    guess = {type:'bary', label:'Exception noted by Herodian: ὄγμος is barytone (…μος).', className:'warn'};
  } else if(pre === 'γ'){
    guess = {type:'oxy', label:'Rule: -γμος (appellative) → oxytone (…μός).', className:'good'};
  } else if(pre === 'δ'){
    if(properNameGuess){
      guess = {type:'bary', label:'Rule: -δμος proper name → barytone (…μος). (Toy: capital letter ⇒ “proper”.)', className:'warn'};
    } else {
      guess = {type:'oxy', label:'Rule: -δμος appellative → oxytone (…μός).', className:'good'};
    }
  } else if(pre === 'θ' || pre === 'χ'){
    guess = {type:'oxy', label:'Rule: -θμος / -χμος → oxytone (…μός).', className:'good'};
  } else {
    guess = {type:'?', label:'No specific rule here in this snippet; leaving as-is.', className:'warn'};
  }

  ruleEl.innerHTML = `<span class="${guess.className}">${escapeHtml(guess.label)}</span>`;

  let suggested = input;
  if(guess.type === 'oxy'){
    suggested = applyAcuteOnOmicronOfMos(input);
  } else if(guess.type === 'bary'){
    suggested = applyNoExtraAccent(input);
  }

  accentedEl.textContent = suggested;

  if(showSyllBox.checked){
    const syl = naiveSyllables(input);
    syllEl.textContent = `Naive syllables: ${syl.join('·')}`;
  } else {
    syllEl.textContent = '';
  }
}

function escapeHtml(s){
  return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

$('#go').addEventListener('click', () => analyze(inp.value));
inp.addEventListener('keydown', (e) => { if(e.key === 'Enter') analyze(inp.value); });

$('#rand').addEventListener('click', () => {
  const w = examples[Math.floor(Math.random()*examples.length)];
  inp.value = w;
  analyze(w);
  inp.focus();
});

document.querySelectorAll('button.pill').forEach(btn => {
  btn.addEventListener('click', () => {
    const w = btn.getAttribute('data-fill');
    inp.value = w;
    analyze(w);
    inp.focus();
  });
});

stripBox.addEventListener('change', () => analyze(inp.value));
showSyllBox.addEventListener('change', () => analyze(inp.value));

// Seed
inp.value = 'νυγμος';
analyze(inp.value);

