(() => {
  const $ = (sel, root=document) => root.querySelector(sel);
  const $$ = (sel, root=document) => Array.from(root.querySelectorAll(sel));

  const inp = $('#inp');
  const outMain = $('#outMain');
  const outAlt = $('#outAlt');
  const confFill = $('#confFill');
  const confPct = $('#confPct');

  // --- Greek helpers (toy-level) ---
  const combining = /[\u0300-\u036f]/g;
  const greekDiacritics = /[\u0342\u0301\u0300\u0313\u0314\u0308\u0345]/g; // circumflex, acute, grave, smooth/rough, diaeresis, iota sub.

  function nfd(s){ return (s||'').normalize('NFD'); }
  function nfc(s){ return (s||'').normalize('NFC'); }
  function stripCombining(s){ return nfc(nfd(s).replace(combining,'')); }
  function stripAccentMarks(s){
    // remove accent/breathing/diaeresis/iota-sub, keep base letters
    return nfc(nfd(s).replace(greekDiacritics,'').replace(combining,''));
  }

  function isGreekLetter(ch){
    const code = ch.codePointAt(0);
    return (code>=0x0370 && code<=0x03FF) || (code>=0x1F00 && code<=0x1FFF);
  }

  function tokenizeGreekLetters(s){
    const base = stripAccentMarks(s);
    const letters = [];
    for (const ch of base){
      if (isGreekLetter(ch)) letters.push(ch);
    }
    return letters;
  }

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
  function isVowel(ch){ return vowels.has(ch); }

  function lastVowelIndex(letters){
    for (let i=letters.length-1;i>=0;i--) if (isVowel(letters[i])) return i;
    return -1;
  }
  function penultVowelIndex(letters){
    let seen = 0;
    for (let i=letters.length-1;i>=0;i--){
      if (isVowel(letters[i])){
        seen++;
        if (seen===2) return i;
      }
    }
    return -1;
  }

  function applyAccentOnPenult(word, accent){
    // accent: 'acute' | 'circ' | 'grave'
    // We rebuild from base letters only (toy), then add combining mark to the penult vowel.
    const base = stripAccentMarks(word);
    const letters = Array.from(base);
    // Find penult vowel in the full string (not just letters), approximate by scanning from end.
    let vowelCount = 0;
    let idx = -1;
    for (let i=letters.length-1;i>=0;i--){
      if (isVowel(letters[i])){
        vowelCount++;
        if (vowelCount===2){ idx = i; break; }
      }
    }
    if (idx<0){
      // fallback: last vowel
      for (let i=letters.length-1;i>=0;i--){ if (isVowel(letters[i])){ idx=i; break; } }
    }
    if (idx<0) return base;

    const mark = accent==='acute' ? '\u0301' : accent==='grave' ? '\u0300' : '\u0342';
    letters[idx] = nfc(nfd(letters[idx]) + mark);
    return nfc(letters.join(''));
  }

  function endsWithAny(s, arr){ return arr.some(x => s.endsWith(x)); }

  // --- Tiny knowledge base from the passage ---
  const lex = new Map([
    ['αμμος', {accent:'acute', note:'Exception: ἄμμος is feminine (Herodian notes it separately).'}],
    ['ψαμμος', {accent:'acute', note:'Exception: ψάμμος is feminine (Herodian notes it separately).'}],
    ['μαμμος', {accent:'grave', note:'μὰμμος (descendant) is said to be “heavy” (non-acute) because adjectival.'}],

    ['κημος', {accent:'acute', note:'Appellative κημός is acute in the passage (funnel/muzzle/net/bait).'}],
    ['κνημος', {accent:'circ', note:'Proper name Κνῆμος (η in penult) is “heavy” (circumflex) in the passage.'}],
    ['σημος', {accent:'circ', note:'Proper name Σῆμος (η in penult) is “heavy” (circumflex) in the passage.'}],
    ['ρημος', {accent:'circ', note:'Proper name Ῥῆμος (river) is “heavy” (circumflex) in the passage.'}],

    ['δημος', {accent:'ambig', note:'Herodian contrasts δημός (fat) vs δῆμος (people/place). This toy can show both.'}],

    ['γραμμος', {accent:'acute', note:'From γράφω → γραμμός: acute (1st conjugation, penult ends in μ).'}],
    ['τριμμος', {accent:'acute', note:'From τρίβω → τριμμός: acute.'}],
    ['θλιμμος', {accent:'acute', note:'From θλίβω → θλιμμός: acute.'}],
    ['κομμος', {accent:'acute', note:'From κόπτω → κομμός: acute.'}],

    ['γαμος', {accent:'circ', note:'Disyllabic -αμος “one-gender”: γᾶμος is said to be heavy (circumflex).'}],
    ['πραμος', {accent:'circ', note:'Disyllabic -αμος “one-gender”: πρᾶμος heavy (circumflex).'}],
    ['σαμος', {accent:'circ', note:'Σάμος is a proper name; passage groups -αμος disyllables as heavy.'}]
  ]);

  function guessMode(wordBase){
    // wordBase: stripped of accents/breathings, lowercased
    if (wordBase.endsWith('αμος')) return 'aMos';
    if (wordBase.endsWith('μος')){
      // penult vowel check for eta
      const letters = tokenizeGreekLetters(wordBase);
      const p = penultVowelIndex(letters);
      if (p>=0 && (letters[p]==='η' || letters[p]==='Η')) return 'proper';
      return 'appellative';
    }
    return 'auto';
  }

  function suggest(wordRaw, mode){
    const cleaned = (wordRaw||'').trim();
    if (!cleaned) return {ok:false, msg:'Type a Greek word (try: κημος, κνημος, δημος, γραμμος, γαμος).'};

    const baseLower = stripAccentMarks(cleaned).toLowerCase();

    // If phrase, take last token for accenting but keep phrase for display.
    const parts = cleaned.split(/\s+/).filter(Boolean);
    const last = parts[parts.length-1];
    const lastBaseLower = stripAccentMarks(last).toLowerCase();

    const lexEntry = lex.get(lastBaseLower);

    let chosenMode = mode;
    if (chosenMode==='auto') chosenMode = guessMode(lastBaseLower);

    let accent = null;
    let confidence = 0.45;
    let why = [];
    let alts = [];

    if (lexEntry){
      if (lexEntry.accent==='ambig'){
        // special: δημος
        const acute = applyAccentOnPenult(last, 'acute');
        const circ = applyAccentOnPenult(last, 'circ');
        alts.push({form: acute, label:'δημός (fat) — acute'});
        alts.push({form: circ, label:'δῆμος (people/place) — circumflex'});
        confidence = 0.75;
        why.push(lexEntry.note);
        return {
          ok:true,
          main: {form: acute, label:'Two readings (choose by meaning):'},
          alts,
          confidence,
          why,
          mode: chosenMode
        };
      }
      accent = lexEntry.accent;
      confidence = 0.9;
      why.push(lexEntry.note);
    }

    if (!accent){
      if (!endsWithAny(lastBaseLower, ['μος','αμος'])){
        confidence = 0.25;
        why.push('Not a clear -μος / -αμος ending; toy rules may not apply.');
        accent = 'acute';
      } else {
        if (chosenMode==='proper'){
          accent = 'circ';
          confidence = 0.7;
          why.push('Mode: proper name with η in the penult → “heavy” (often circumflex): Κνῆμος, Σῆμος, Ῥῆμος.');
        } else if (chosenMode==='aMos'){
          accent = 'circ';
          confidence = 0.65;
          why.push('Mode: disyllabic -αμος “one-gender” → “heavy” (often circumflex): γᾶμος, πρᾶμος.');
        } else if (chosenMode==='firstConj'){
          accent = 'acute';
          confidence = 0.6;
          why.push('Mode: from 1st conjugation verb with penult ending in μ → acute: γραμμός, τριμμός, θλιμμός, κομμός.');
        } else {
          accent = 'acute';
          confidence = 0.55;
          why.push('Mode: appellative/common noun → often acute on the penult (e.g. κημός), unless distinguished.');
        }
      }
    }

    const accentedLast = applyAccentOnPenult(last, accent);
    const rebuilt = parts.length>1 ? (parts.slice(0,-1).join(' ') + ' ' + accentedLast) : accentedLast;

    // Alternatives for play
    const altAcute = applyAccentOnPenult(last, 'acute');
    const altCirc = applyAccentOnPenult(last, 'circ');
    const altGrave = applyAccentOnPenult(last, 'grave');

    if (accent!=='acute') alts.push({form: altAcute, label:'Try acute'});
    if (accent!=='circ') alts.push({form: altCirc, label:'Try circumflex'});
    if (accent!=='grave') alts.push({form: altGrave, label:'Try grave (rare here; used for μὰμμος in the passage)'});

    return {
      ok:true,
      main:{form: rebuilt, label: accent==='acute'?'Suggested: acute on penult':accent==='circ'?'Suggested: circumflex on penult':'Suggested: grave on penult'},
      alts,
      confidence,
      why,
      mode: chosenMode
    };
  }

  function render(res){
    if (!res.ok){
      outMain.innerHTML = `<span class="meta">${escapeHtml(res.msg)}</span>`;
      outAlt.textContent = '';
      setConf(0);
      return;
    }
    outMain.innerHTML = `<span class="big">${escapeHtml(res.main.form)}</span><span class="meta">${escapeHtml(res.main.label)} • mode: ${escapeHtml(res.mode)}</span>`;

    const why = res.why && res.why.length ? `\n<b>Why:</b> ${escapeHtml(res.why.join(' '))}` : '';
    const alts = res.alts && res.alts.length
      ? `\n<b>Alternatives:</b> ${res.alts.map(a => `<span class="alt"><b>${escapeHtml(a.form)}</b> <span class="dim">(${escapeHtml(a.label)})</span></span>`).join(' • ')}`
      : '';

    outAlt.innerHTML = `${why}${alts}`.replace(/\n/g,'<br>');
    setConf(res.confidence);
  }

  function setConf(x){
    const pct = Math.round(Math.max(0, Math.min(1, x))*100);
    confFill.style.width = pct + '%';
    confPct.textContent = pct ? (pct + '%') : '—';
  }

  function escapeHtml(s){
    return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  function currentMode(){
    const r = $('input[name="mode"]:checked');
    return r ? r.value : 'auto';
  }

  function analyze(){
    const res = suggest(inp.value, currentMode());
    render(res);
  }

  $('#btnAnalyze').addEventListener('click', analyze);
  $('#btnClear').addEventListener('click', () => { inp.value=''; inp.focus(); render({ok:false,msg:'Type a Greek word ending in -μος or -αμος.'}); });
  inp.addEventListener('keydown', (e) => {
    if (e.key==='Enter') analyze();
    if (e.key==='Escape') { $('#btnClear').click(); }
  });
  $$('input[name="mode"]').forEach(r => r.addEventListener('change', analyze));

  // --- Quiz ---
  const qWord = $('#qWord');
  const qResult = $('#qResult');
  let qCurrent = null;

  const quizDeck = [
    {w:'κημος', mode:'appellative'},
    {w:'κνημος', mode:'proper'},
    {w:'σημος', mode:'proper'},
    {w:'ρημος', mode:'proper'},
    {w:'δημος', mode:'auto'},
    {w:'γραμμος', mode:'firstConj'},
    {w:'τριμμος', mode:'firstConj'},
    {w:'θλιμμος', mode:'firstConj'},
    {w:'κομμος', mode:'firstConj'},
    {w:'αμμος', mode:'auto'},
    {w:'ψαμμος', mode:'auto'},
    {w:'μαμμος', mode:'auto'},
    {w:'γαμος', mode:'aMos'},
    {w:'πραμος', mode:'aMos'},
    {w:'σαμος', mode:'aMos'}
  ];

  function expectedClass(res){
    // Map suggestion to quiz buckets
    if (!res.ok) return 'other';
    const last = res.main.form.split(/\s+/).pop();
    const base = stripAccentMarks(last).toLowerCase();
    if (base==='δημος') return 'other';
    if (base==='μαμμος') return 'other';
    // Determine which accent was applied by comparing to our generated forms
    const acute = applyAccentOnPenult(last, 'acute');
    const circ = applyAccentOnPenult(last, 'circ');
    if (last === acute) return 'acute';
    if (last === circ) return 'circ';
    return 'other';
  }

  function deal(){
    qResult.textContent = '';
    const pick = quizDeck[Math.floor(Math.random()*quizDeck.length)];
    qCurrent = pick;
    qWord.textContent = pick.w;
  }

  function reveal(){
    if (!qCurrent){ qResult.textContent = 'Click Deal first.'; return; }
    const res = suggest(qCurrent.w, qCurrent.mode);
    const cls = expectedClass(res);
    const show = res.ok ? res.main.form : qCurrent.w;
    qResult.innerHTML = `Answer: <b>${escapeHtml(show)}</b> • bucket: <b>${escapeHtml(cls)}</b>`;
  }

  $('#btnDeal').addEventListener('click', deal);
  $('#btnReveal').addEventListener('click', reveal);

  $$('.chip').forEach(btn => btn.addEventListener('click', () => {
    if (!qCurrent){ qResult.textContent = 'Click Deal first.'; return; }
    const res = suggest(qCurrent.w, qCurrent.mode);
    const exp = expectedClass(res);
    const got = btn.dataset.ans;

    if (exp === got){
      qResult.innerHTML = `<span class="good">Correct.</span> ${escapeHtml(res.ok ? res.main.form : qCurrent.w)}`;
    } else {
      qResult.innerHTML = `<span class="bad">Not quite.</span> Reveal to compare.`;
    }
  }));

  // initial render
  analyze();
  deal();
})();

passages.gadget_css:
:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --ink:#e9ecff;
  --muted:#b8bde6;
  --faint:#7f86c7;
  --accent:#7cf0c5;
  --warn:#ffcc66;
  --bad:#ff6b7a;
  --good:#7cf0c5;
  --line:rgba(255,255,255,.10);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Noto Sans", "Liberation Sans", sans-serif;
}

*{box-sizing:border-box}
body{margin:0; background:radial-gradient(1200px 700px at 20% 0%, #1a1f3a 0%, var(--bg) 55%); color:var(--ink); font-family:var(--sans)}

.wrap{max-width:980px; margin:0 auto; padding:22px 16px 40px}
.hdr{padding:10px 6px 18px}
.hdr h1{margin:0 0 8px; font-size:26px; letter-spacing:.2px}
.sub{margin:0; color:var(--muted); line-height:1.35}

.panel{background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02)); border:1px solid var(--line); border-radius:14px; padding:14px; box-shadow:var(--shadow); margin:12px 0}

.row{display:flex; gap:10px; align-items:center; flex-wrap:wrap}
label{color:var(--muted); font-size:13px}
input[type=text]{
  flex:1 1 360px;
  padding:12px 12px;
  border-radius:12px;
  border:1px solid var(--line);
  background:rgba(0,0,0,.25);
  color:var(--ink);
  font-size:18px;
  outline:none;
}
input[type=text]:focus{border-color:rgba(124,240,197,.55); box-shadow:0 0 0 4px rgba(124,240,197,.12)}

button{
  padding:11px 12px;
  border-radius:12px;
  border:1px solid rgba(124,240,197,.35);
  background:rgba(124,240,197,.14);
  color:var(--ink);
  cursor:pointer;
  font-weight:650;
}
button:hover{background:rgba(124,240,197,.20)}
button:active{transform:translateY(1px)}
button.ghost{border-color:var(--line); background:rgba(255,255,255,.06)}
button.ghost:hover{background:rgba(255,255,255,.09)}

.opts{margin-top:8px}
.chk{display:flex; gap:8px; align-items:center; user-select:none; color:var(--muted)}
.chk input{accent-color:var(--accent)}

.out{margin-top:12px; padding:12px; border-radius:12px; border:1px dashed rgba(255,255,255,.16); background:rgba(0,0,0,.18)}
.big{font-size:34px; font-family:var(--mono); letter-spacing:.3px}
.meta{margin-top:6px; color:var(--muted)}
.steps{margin-top:10px}
.steps summary{cursor:pointer; color:var(--muted)}
.steps ol{margin:8px 0 0 18px; color:var(--muted)}
.steps li{margin:6px 0}

h2{margin:0 0 6px; font-size:18px}

.game{display:grid; grid-template-columns:repeat(auto-fit, minmax(180px, 1fr)); gap:10px; margin-top:10px}
.card{
  border:1px solid var(--line);
  border-radius:14px;
  padding:12px;
  background:rgba(0,0,0,.18);
  cursor:pointer;
  position:relative;
  overflow:hidden;
}
.card:hover{border-color:rgba(124,240,197,.35)}
.word{font-family:var(--mono); font-size:22px}
.hint{margin-top:6px; color:var(--faint); font-size:12px; line-height:1.25}
.badge{position:absolute; top:10px; right:10px; font-size:12px; padding:4px 8px; border-radius:999px; border:1px solid var(--line); color:var(--muted); background:rgba(255,255,255,.05)}

.card.good{border-color:rgba(124,240,197,.55); box-shadow:0 0 0 4px rgba(124,240,197,.10) inset}
.card.bad{border-color:rgba(255,107,122,.55); box-shadow:0 0 0 4px rgba(255,107,122,.10) inset}

.score{display:flex; justify-content:space-between; align-items:center; margin-top:10px; color:var(--muted)}

.ftr{color:var(--muted); font-size:13px; padding:6px 4px}

kbd{font-family:var(--mono); font-size:12px; padding:2px 6px; border:1px solid var(--line); border-bottom-color:rgba(255,255,255,.18); border-radius:8px; background:rgba(0,0,0,.22)}

