(() => {
  const $ = (sel, el=document) => el.querySelector(sel);
  const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

  const inp = $('#inp');
  const btn = $('#btn');
  const btnRandom = $('#btnRandom');
  const strip = $('#strip');
  const showSteps = $('#showSteps');
  const outWord = $('#outWord');
  const outMeta = $('#outMeta');
  const stepsBox = $('#stepsBox');
  const stepsOl = $('#steps');

  // --- Utilities ---
  const tonos = '\u0301'; // combining acute
  const circumflex = '\u0342'; // combining perispomeni

  function nfd(s){ return (s||'').normalize('NFD'); }
  function nfc(s){ return (s||'').normalize('NFC'); }

  function stripDiacritics(s){
    // remove combining marks (accents, breathings, diaeresis, iota subscript, etc.)
    return nfc(nfd(s).replace(/[\u0300-\u036f]/g,''));
  }

  function isGreekLetter(ch){
    const code = ch.codePointAt(0);
    return (code >= 0x0370 && code <= 0x03FF) || (code >= 0x1F00 && code <= 0x1FFF);
  }

  function onlyGreekAndPunct(s){
    return (s||'').split('').filter(c => isGreekLetter(c) || /[\s·\-’'.,;:!?]/.test(c)).join('');
  }

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ','ϊ','ϋ','ΐ','ΰ','ᾳ','ῃ','ῳ','Α','Ε','Η','Ι','Ο','Υ','Ω']);

  function isVowelBase(ch){
    const base = stripDiacritics(ch).toLowerCase();
    return ['α','ε','η','ι','ο','υ','ω'].includes(base);
  }

  function lastVowelIndex(word){
    const w = nfd(word);
    // iterate by code units; combining marks follow base vowel
    for(let i=w.length-1;i>=0;i--){
      const ch = w[i];
      if(isGreekLetter(ch) && isVowelBase(ch)) return i;
    }
    return -1;
  }

  function penultVowelIndex(word){
    const w = nfd(word);
    let found = 0;
    for(let i=w.length-1;i>=0;i--){
      const ch = w[i];
      if(isGreekLetter(ch) && isVowelBase(ch)){
        found++;
        if(found===2) return i;
      }
    }
    return -1;
  }

  function addAcuteAtVowel(word, which){
    // which: 'ultima' or 'penult'
    const w = nfd(word);
    const idx = which==='ultima' ? lastVowelIndex(w) : penultVowelIndex(w);
    if(idx<0) return word;

    // insert combining acute after the vowel base and any existing combining marks right after it
    // First, remove any existing accent marks (acute/grave/circumflex) anywhere.
    let cleaned = w.replace(/[\u0300\u0301\u0342]/g,'');

    // recompute index on cleaned string (structure may change slightly)
    const idx2 = which==='ultima' ? lastVowelIndex(cleaned) : penultVowelIndex(cleaned);
    if(idx2<0) return nfc(cleaned);

    // find insertion point: after vowel and following combining marks
    let j = idx2 + 1;
    while(j < cleaned.length && /[\u0300-\u036f]/.test(cleaned[j])) j++;
    const out = cleaned.slice(0,j) + tonos + cleaned.slice(j);
    return nfc(out);
  }

  function syllableCountRough(word){
    // rough: count vowel nuclei (treat diphthongs as 1 when obvious)
    const w = stripDiacritics(word).toLowerCase();
    // basic diphthongs
    const diph = ['αι','ει','οι','υι','αυ','ευ','ηυ','ου','ωυ'];
    let s = w;
    for(const d of diph){ s = s.split(d).join('§'); }
    let count = 0;
    for(const ch of s){ if(['α','ε','η','ι','ο','υ','ω','§'].includes(ch)) count++; }
    return count;
  }

  // --- Passage-inspired heuristics ---
  // A few lexical exceptions explicitly mentioned.
  const lexicon = new Map([
    ['αμος', {accent:'penult', note:'Proper name/place: Ἄμος (Caria)'}],
    ['λαμος', {accent:'penult', note:'Proper name: Λάμος'}],
    ['πλαμος', {accent:'penult', note:'Proper name/place: Πλάμος (Caria)'}],

    ['αμος_pron', {accent:'ultima', note:'Pronoun/adverbial: ἀμός ("our") is tri-gender → oxytone'}],
    ['ομος_similar', {accent:'ultima', note:'ὁμός = "similar" is tri-gender → oxytone'}],

    ['κωμος', {accent:'penult', note:'κῶμος (song) is an exception → paroxytone'}],
    ['μωμος', {accent:'penult', note:'μῶμος begins with μ → paroxytone (per passage)'}],
    ['βρωμος', {accent:'penult', note:'βρῶμος (grass) → paroxytone (exception)'}],
    ['κρωμος', {accent:'penult', note:'Κρῶμος (proper name) → paroxytone (exception)'}],
    ['ωμος', {accent:'penult', note:'ὦμος (shoulder) → paroxytone (avoid confusion)'}],

    ['θυμος', {accent:'ultima', note:'θυμός (spirit) with long υ → oxytone'}],
    ['θυμος_part', {accent:'penult', note:'θύμος (part/herb) → paroxytone (lexical)'}],

    ['μιμος', {accent:'penult', note:'μῖμος listed as paroxytone in -ιμος set'}],
    ['τιμος', {accent:'penult', note:'τῖμος listed as paroxytone in -ιμος set'}],
    ['βριμος', {accent:'penult', note:'βρῖμος listed as paroxytone in -ιμος set'}],
    ['φιμος', {accent:'ultima', note:'φιμός listed as oxytone in -ιμος set'}],
    ['λιμος', {accent:'ultima', note:'λιμός listed as oxytone in -ιμος set'}],
    ['σιμος', {accent:'ultima', note:'σιμός listed as oxytone in -ιμος set'}],

    ['βρομος', {accent:'penult', note:'βρόμος listed as paroxytone in -μος set'}],
    ['γομος', {accent:'penult', note:'γόμος listed as paroxytone in -μος set'}],
    ['τρομος', {accent:'penult', note:'τρόμος listed as paroxytone in -μος set'}],
    ['δρομος', {accent:'penult', note:'δρόμος listed as paroxytone in -μος set'}],
    ['ρομος', {accent:'penult', note:'ῥόμος (worm) listed as paroxytone in -μος set'}],
    ['δομος', {accent:'penult', note:'δόμος listed as paroxytone in -μος set'}],
    ['τομος', {accent:'penult', note:'τόμος (thing cut) listed as paroxytone'}],
    ['τομος_cutter', {accent:'ultima', note:'τομός (cutter) contrasted as oxytone'}],
    ['νομος_pasture', {accent:'ultima', note:'νομός (pasturage) contrasted as oxytone'}],
    ['νομος_law', {accent:'penult', note:'νόμος (law) contrasted as paroxytone'}],

    ['κρυμος', {accent:'ultima', note:'κρυμός listed as oxytone in -υμος set'}],
    ['ρυμος', {accent:'ultima', note:'ῥυμός listed as oxytone in -υμος set'}],
    ['χυμος', {accent:'ultima', note:'χυμός listed as oxytone in -υμος set'}],
    ['δρυμος', {accent:'ultima', note:'Δρυμός listed as oxytone'}],

    ['βωμος', {accent:'ultima', note:'βωμός listed as oxytone in -ωμος set'}],
    ['ψωμος', {accent:'ultima', note:'ψωμός listed as oxytone in -ωμος set'}],
    ['ζωμος', {accent:'ultima', note:'ζωμός listed as oxytone in -ωμος set'}],
    ['θωμος', {accent:'ultima', note:'θωμός listed as oxytone in -ωμος set'}],
    ['βλωμος', {accent:'ultima', note:'βλωμός listed as oxytone in -ωμος set'}],
  ]);

  function classify(wordRaw){
    const steps = [];
    let w0 = onlyGreekAndPunct(wordRaw).trim();
    if(!w0) return {ok:false, steps:["Type a Greek word (e.g. βρομος)."], out:'—', meta:'—'};

    // keep only first token for simplicity
    const token = w0.split(/\s+/)[0];
    steps.push(`Input token: “${token}”.`);

    const normalized = strip.checked ? stripDiacritics(token) : token;
    const w = normalized.toLowerCase();
    if(strip.checked) steps.push('Normalization: removed accents/breathings for matching.');

    // quick sanity
    if(!/[α-ω]/i.test(w)){
      return {ok:false, steps:[...steps, 'No Greek letters detected.'], out:'—', meta:'Try Greek letters ending in -μος.'};
    }

    // detect ending group
    const ending = (w.endsWith('ωμος') ? 'ωμος' : w.endsWith('υμος') ? 'υμος' : w.endsWith('ιμος') ? 'ιμος' : w.endsWith('μος') ? 'μος' : 'other');
    steps.push(`Detected ending: -${ending}.`);

    // disyllable check (rough)
    const syl = syllableCountRough(w);
    steps.push(`Rough syllable count: ${syl}. (Herodian’s rules here mainly target disyllables.)`);

    // lexical override via a tiny disambiguation UI trick: allow suffix tags like "_law" etc.
    // If user types e.g. "νομος" we can't know which; we provide a hint.
    const lex = lexicon.get(w);
    if(lex){
      steps.push(`Found in example list: ${lex.note}.`);
      return {ok:true, accent:lex.accent, steps, meta:lex.note, normalized:token};
    }

    // special ambiguous prompts
    if(w === 'νομος'){
      steps.push('Ambiguous: νόμος (law) vs νομός (pasturage).');
      steps.push('Toy default: paroxytone (νόμος). Try typing “νομος_pasture” or “νομος_law” if you want the listed contrast.');
      return {ok:true, accent:'penult', steps, meta:'Ambiguous in passage: νόμος vs νομός. Defaulting to νόμος (paroxytone).', normalized:token};
    }
    if(w === 'τομος'){
      steps.push('Ambiguous: τόμος (thing cut) vs τομός (cutter).');
      steps.push('Toy default: paroxytone (τόμος). Try “τομος_cutter” for the other.');
      return {ok:true, accent:'penult', steps, meta:'Ambiguous in passage: τόμος vs τομός. Defaulting to τόμος (paroxytone).', normalized:token};
    }
    if(w === 'θυμος'){
      steps.push('Ambiguous: θυμός (spirit) vs θύμος (part/herb).');
      steps.push('Toy default: oxytone (θυμός). Try “θυμος_part” for the other.');
      return {ok:true, accent:'ultima', steps, meta:'Ambiguous in passage: θυμός vs θύμος. Defaulting to θυμός (oxytone).', normalized:token};
    }
    if(w === 'αμος'){
      steps.push('Ambiguous: Ἄμος (place-name) vs ἀμός ("our").');
      steps.push('Toy default: place-name Ἄμος (paroxytone). Try “αμος_pron” for the tri-gender word.');
      return {ok:true, accent:'penult', steps, meta:'Ambiguous in passage: Ἄμος vs ἀμός. Defaulting to Ἄμος (paroxytone).', normalized:token};
    }

    // heuristic rules
    let accent = 'penult';

    if(ending === 'ιμος'){
      steps.push('Rule-of-thumb: -ιμος often oxytone in the passage (φιμός, λιμός, σιμός), but some are paroxytone (μῖμος, τῖμος, βρῖμος).');
      accent = 'ultima';
    } else if(ending === 'υμος'){
      steps.push('Rule-of-thumb: disyllabic -υμος with long υ tends to be oxytone (κρυμός, ῥυμός, χυμός, θυμός).');
      accent = 'ultima';
    } else if(ending === 'ωμος'){
      const startsWithMu = w.startsWith('μ');
      if(startsWithMu){
        steps.push('Exception rule: -ωμος starting with μ is paroxytone in the passage (μῶμος).');
        accent = 'penult';
      } else {
        steps.push('Rule-of-thumb: disyllabic appellatives in -ωμος starting with a consonant other than μ are oxytone (βωμός, ψωμός, ζωμός...).');
        accent = 'ultima';
      }
    } else if(ending === 'μος'){
      // check penult vowel o/e (roughly: second-to-last vowel is ο or ε)
      const base = stripDiacritics(w).toLowerCase();
      // find penult vowel base
      const penIdx = penultVowelIndex(base);
      const penV = penIdx>=0 ? base[penIdx] : '';
      steps.push(`Penult vowel (rough): “${penV || '—'}”.`);

      if(['ο','ε'].includes(penV)){
        steps.push('Rule-of-thumb: disyllables in -μος with penult ο/ε, not tri-gender, beginning with consonant(s) → paroxytone (βρόμος, δρόμος...).');
        accent = 'penult';
      } else {
        steps.push('No strong -μος rule triggered; toy defaults to paroxytone for -μος unless other rules apply.');
        accent = 'penult';
      }
    } else {
      steps.push('Not a -μος/-ιμος/-υμος/-ωμος word; toy will still place an acute on the penult as a default.');
      accent = 'penult';
    }

    // If not disyllabic, warn
    if(syl !== 2){
      steps.push('Caution: input is not (roughly) disyllabic; Herodian’s specific generalizations may not apply.');
    }

    return {ok:true, accent, steps, meta:'Heuristic guess based on Herodian (1.169).', normalized:token};
  }

  function render(){
    const res = classify(inp.value);
    stepsOl.innerHTML = '';
    stepsBox.style.display = showSteps.checked ? '' : 'none';

    for(const s of res.steps){
      const li = document.createElement('li');
      li.textContent = s;
      stepsOl.appendChild(li);
    }

    if(!res.ok){
      outWord.textContent = res.out;
      outMeta.textContent = res.meta;
      return;
    }

    const token = (strip.checked ? stripDiacritics(res.normalized) : res.normalized);
    const accented = addAcuteAtVowel(token, res.accent === 'ultima' ? 'ultima' : 'penult');

    outWord.textContent = accented;
    outMeta.textContent = (res.accent === 'ultima' ? 'Suggested: oxytone (ultima).' : 'Suggested: paroxytone (penult).') + ' ' + res.meta;
  }

  btn.addEventListener('click', render);
  inp.addEventListener('keydown', (e) => { if(e.key === 'Enter') render(); });
  strip.addEventListener('change', render);
  showSteps.addEventListener('change', render);

  // --- Game ---
  const gameEl = $('#game');
  const scoreEl = $('#score');
  const streakEl = $('#streak');
  const resetBtn = $('#reset');

  let score = 0;
  let streak = 0;

  const quizItems = [
    {w:'βρομος', a:'penult', hint:'listed among -μος paroxytones'},
    {w:'δρομος', a:'penult', hint:'listed among -μος paroxytones'},
    {w:'θυμος', a:'ultima', hint:'θυμός (spirit) in -υμος set'},
    {w:'κωμος', a:'penult', hint:'exception: κῶμος'},
    {w:'μωμος', a:'penult', hint:'exception: starts with μ'},
    {w:'βωμος', a:'ultima', hint:'-ωμος substance/appellative'},
    {w:'μιμος', a:'penult', hint:'-ιμος paroxytone example'},
    {w:'λιμος', a:'ultima', hint:'-ιμος oxytone example'},
    {w:'κρυμος', a:'ultima', hint:'-υμος oxytone example'},
    {w:'ωμος', a:'penult', hint:'exception: ὦμος'},
  ];

  function shuffle(arr){
    const a = arr.slice();
    for(let i=a.length-1;i>0;i--){
      const j = Math.floor(Math.random()*(i+1));
      [a[i],a[j]]=[a[j],a[i]];
    }
    return a;
  }

  function buildGame(){
    gameEl.innerHTML = '';
    const items = shuffle(quizItems).slice(0,6);
    for(const it of items){
      const card = document.createElement('div');
      card.className = 'card';
      const word = document.createElement('div');
      word.className = 'word';
      word.textContent = addAcuteAtVowel(it.w, 'penult'); // show with a default accent to provoke thought

      const badge = document.createElement('div');
      badge.className = 'badge';
      badge.textContent = 'click: oxytone / paroxytone';

      const hint = document.createElement('div');
      hint.className = 'hint';
      hint.textContent = 'Hint: ' + it.hint;

      card.appendChild(word);
      card.appendChild(badge);
      card.appendChild(hint);

      card.addEventListener('click', () => {
        const guess = (Math.random() < 0.5) ? 'ultima' : 'penult';
        // Instead of random guess, ask user via small prompt-like toggle UI:
      });

      // Two buttons inside each card
      const btnRow = document.createElement('div');
      btnRow.style.display = 'flex';
      btnRow.style.gap = '8px';
      btnRow.style.marginTop = '10px';

      const b1 = document.createElement('button');
      b1.className = 'ghost';
      b1.textContent = 'Oxytone';
      const b2 = document.createElement('button');
      b2.className = 'ghost';
      b2.textContent = 'Paroxytone';

      function answer(ans){
        const correct = (ans === it.a);
        if(correct){
          score += 1;
          streak += 1;
          card.classList.remove('bad');
          card.classList.add('good');
          badge.textContent = '✓ correct';
        } else {
          streak = 0;
          card.classList.remove('good');
          card.classList.add('bad');
          badge.textContent = '✗ ' + (it.a==='ultima' ? 'oxytone' : 'paroxytone');
        }
        // reveal correct accent on the word
        word.textContent = addAcuteAtVowel(it.w, it.a==='ultima' ? 'ultima' : 'penult');
        scoreEl.textContent = String(score);
        streakEl.textContent = String(streak);
        b1.disabled = true;
        b2.disabled = true;
      }

      b1.addEventListener('click', (e) => { e.stopPropagation(); answer('ultima'); });
      b2.addEventListener('click', (e) => { e.stopPropagation(); answer('penult'); });

      btnRow.appendChild(b1);
      btnRow.appendChild(b2);
      card.appendChild(btnRow);

      gameEl.appendChild(card);
    }
  }

  resetBtn.addEventListener('click', () => {
    score = 0; streak = 0;
    scoreEl.textContent = '0';
    streakEl.textContent = '0';
    buildGame();
  });

  btnRandom.addEventListener('click', () => {
    const ex = shuffle(quizItems)[0].w;
    inp.value = ex;
    render();
  });

  // init
  buildGame();
  inp.value = 'βρομος';
  render();
})();

passages.gadget_css:
:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --panel2:#1d2136;
  --text:#eef0ff;
  --muted:#b9bde6;
  --faint:#8b90c7;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --good:#34d399;
  --warn:#fbbf24;
  --bad:#fb7185;
  --border:rgba(255,255,255,.10);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
}

*{box-sizing:border-box}

.wrap{
  font-family:var(--sans);
  color:var(--text);
  background:linear-gradient(180deg, rgba(125,211,252,.08), transparent 35%), var(--bg);
  border:1px solid var(--border);
  border-radius:16px;
  padding:18px;
  box-shadow:var(--shadow);
  max-width:980px;
  margin:0 auto;
}

.hdr h1{font-size:18px; margin:0 0 6px 0; letter-spacing:.2px}
.sub{margin:0; color:var(--muted); font-size:13px; line-height:1.35}

.panel{
  margin-top:14px;
  background:linear-gradient(180deg, rgba(255,255,255,.04), transparent 60%), var(--panel);
  border:1px solid var(--border);
  border-radius:14px;
  padding:14px;
}

.grid{
  display:grid;
  grid-template-columns: 1.2fr .9fr;
  gap:12px;
}

@media (max-width: 820px){
  .grid{grid-template-columns:1fr}
}

.field{display:flex; flex-direction:column; gap:8px}
.lbl{font-size:12px; color:var(--muted)}

input[type="text"]{
  width:100%;
  padding:12px 12px;
  border-radius:12px;
  border:1px solid var(--border);
  background:var(--panel2);
  color:var(--text);
  font-size:16px;
  outline:none;
}
input[type="text"]:focus{border-color: rgba(125,211,252,.55); box-shadow: 0 0 0 3px rgba(125,211,252,.12)}

.hint{font-size:12px; color:var(--faint); line-height:1.35}

.modes{display:flex; gap:12px; flex-wrap:wrap; padding:10px; border:1px solid var(--border); border-radius:12px; background:var(--panel2)}
.modes label{font-size:13px; color:var(--muted)}

.manual{display:flex; gap:8px; flex-wrap:wrap}

.chip{
  border:1px solid var(--border);
  background:rgba(167,139,250,.10);
  color:var(--text);
  padding:8px 10px;
  border-radius:999px;
  cursor:pointer;
  font-size:13px;
}
.chip:hover{border-color: rgba(167,139,250,.55)}
.chip.active{background:rgba(167,139,250,.22); border-color: rgba(167,139,250,.65)}

.out{
  padding:12px;
  border-radius:12px;
  border:1px solid var(--border);
  background:var(--panel2);
  font-size:18px;
  letter-spacing:.2px;
  min-height:46px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
}

.row{display:flex; gap:8px; flex-wrap:wrap}
.btn{
  border:1px solid var(--border);
  background:rgba(125,211,252,.12);
  color:var(--text);
  padding:9px 10px;
  border-radius:12px;
  cursor:pointer;
  font-size:13px;
}
.btn:hover{border-color: rgba(125,211,252,.55)}
.btn.ghost{background:transparent}

.why{
  padding:12px;
  border-radius:12px;
  border:1px solid var(--border);
  background:rgba(255,255,255,.03);
  color:var(--muted);
  font-size:13px;
  line-height:1.4;
  min-height:92px;
}

details summary{cursor:pointer; color:var(--accent); font-size:13px}
ul{margin:10px 0 0 18px; color:var(--muted); font-size:13px; line-height:1.45}
code{font-family:var(--mono); font-size:12px; color:var(--text)}
.small{color:var(--faint); font-size:12px; line-height:1.35; margin:10px 0 0 0}

.ftr{margin-top:10px}

