(() => {
  const $ = (sel, el=document) => el.querySelector(sel);
  const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

  const input = $('#in');
  const out = $('#out');
  const why = $('#why');
  const copyBtn = $('#copy');
  const randomBtn = $('#random');
  const clearBtn = $('#clear');
  const manualWrap = $('#manual');

  const examples = [
    'ωμος', 'ὠμος', 'ὦμος',
    'ωρος', 'ὧρος',
    'ωχρος', 'ὦχρος',
    'ᾠδος', 'ᾠδός',
    'λαιμος', 'λοιμος',
    'Αιμος', 'Αἷμος',
    'οἶμος',
    'Δειμος', 'Δεῖμος',
    'ποταμος', 'ιταμος',
    'πλοκαμος', 'κεραμος', 'καλαμος', 'θαλαμος', 'κυαμος', 'Πριαμος',
    'Πυραμος', 'Σησαμος', 'Τευταμος', 'Ιαμος',
    'ουλαμος', 'χηραμος', 'φωριαμος'
  ];

  // --- Greek helpers (toy-level) ---
  const combining = {
    acute: '\u0301',
    grave: '\u0300',
    circumflex: '\u0342',
    diaeresis: '\u0308',
    iotaSub: '\u0345',
    smooth: '\u0313',
    rough: '\u0314'
  };

  function nfd(s){ return s.normalize('NFD'); }
  function nfc(s){ return s.normalize('NFC'); }

  function stripAccentsKeepBreathings(s){
    // Remove acute/grave/circumflex; keep breathings/diaeresis/iota-sub.
    const d = nfd(s);
    const removed = d.replace(/[\u0300\u0301\u0342]/g,'');
    return nfc(removed);
  }

  function stripAllDiacritics(s){
    return nfc(nfd(s).replace(/[\u0300-\u036f]/g,''));
  }

  function isGreekLetter(ch){
    const code = ch.codePointAt(0);
    return (code >= 0x0370 && code <= 0x03FF) || (code >= 0x1F00 && code <= 0x1FFF);
  }

  function tokenizeGreekWords(text){
    // Keep only first Greek word-like token for this toy.
    const m = text.match(/[\u0370-\u03FF\u1F00-\u1FFF]+/u);
    return m ? m[0] : '';
  }

  const vowelsBase = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

  function baseChar(ch){
    // Return base letter without diacritics.
    return stripAllDiacritics(ch);
  }

  function isVowelChar(ch){
    const b = baseChar(ch);
    return vowelsBase.has(b);
  }

  function startsWithConsonant(word){
    const w = tokenizeGreekWords(word);
    if(!w) return false;
    // Find first base letter
    const d = nfd(w);
    // iterate by codepoints in NFC chunks: simplest: scan original string for first Greek letter
    for(const ch of w){
      if(isGreekLetter(ch)){
        return !isVowelChar(ch);
      }
    }
    return false;
  }

  function hasIotaAttachedOmega(word){
    // Detect omega with iota subscript OR omega+i (rough heuristic for ᾠ / ωι)
    const d = nfd(tokenizeGreekWords(word));
    // omega with iota subscript
    if(/\u03C9[\u0300-\u036f]*\u0345/i.test(d)) return true;
    // omega followed by iota (ωι / ῳ? already covered)
    const plain = stripAllDiacritics(tokenizeGreekWords(word));
    return /ωι/i.test(plain);
  }

  function endsWith(word, ending){
    const plain = stripAllDiacritics(tokenizeGreekWords(word)).toLowerCase();
    return plain.endsWith(ending);
  }

  function countSyllables(word){
    // Very rough: count vowel nuclei, treating common diphthongs as one.
    const w = stripAllDiacritics(tokenizeGreekWords(word)).toLowerCase();
    if(!w) return 0;
    const diph = ['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ωυ'];
    let i=0, count=0;
    while(i < w.length){
      const two = w.slice(i,i+2);
      if(diph.includes(two)){
        count++; i+=2; continue;
      }
      const ch = w[i];
      if('αεηιουω'.includes(ch)) count++;
      i++;
    }
    return count;
  }

  function penultHasDiphthong(word){
    // For disyllables only: check if first syllable nucleus is diphthong.
    const w = stripAllDiacritics(tokenizeGreekWords(word)).toLowerCase();
    const diph = ['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ωυ'];
    // Find first vowel nucleus
    for(let i=0;i<w.length-1;i++){
      const two = w.slice(i,i+2);
      if(diph.includes(two)) return true;
      if('αεηιουω'.includes(w[i])) return false;
    }
    return false;
  }

  function applyAccent(word, accentType){
    // Apply an accent mark to the vowel nucleus of the target syllable.
    // We strip existing pitch accents first but keep breathings/iota-sub.
    const original = tokenizeGreekWords(word);
    if(!original) return '';

    const w = stripAccentsKeepBreathings(original);
    const plain = stripAllDiacritics(w);
    const sylls = countSyllables(w);
    if(sylls === 0) return w;

    let targetFromEnd = 1; // 1=ultima,2=penult,3=antepenult
    if(accentType === 'oxytone') targetFromEnd = 1;
    else if(accentType === 'paroxytone') targetFromEnd = 2;
    else if(accentType === 'proparoxytone') targetFromEnd = 3;
    else if(accentType === 'barytone') targetFromEnd = 2; // toy: barytone -> circumflex on penult when possible

    if(targetFromEnd > sylls) targetFromEnd = sylls;

    // Decide mark: acute normally; barytone uses circumflex if possible.
    const mark = (accentType === 'barytone') ? combining.circumflex : combining.acute;

    // Find vowel nucleus positions in NFD string.
    const d = nfd(w);
    // Build array of indices (in code units) where a nucleus starts.
    const base = stripAllDiacritics(d);

    // We'll scan the base (diacritics removed) but need mapping to d indices.
    // Simpler: scan d, collect positions of base letters that are vowels and not second of diphthong.
    const diph = new Set(['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ωυ']);

    // Create array of objects {i: index in d where vowel base letter occurs, base: letter}
    const letters = [];
    for(let i=0;i<d.length;i++){
      const ch = d[i];
      // skip combining marks
      if(ch >= '\u0300' && ch <= '\u036f') continue;
      letters.push({ idx:i, ch });
    }

    // Determine nuclei among letters
    const nuclei = [];
    for(let k=0;k<letters.length;k++){
      const b1 = stripAllDiacritics(letters[k].ch).toLowerCase();
      const b2 = (k+1<letters.length) ? stripAllDiacritics(letters[k+1].ch).toLowerCase() : '';
      const two = b1 + b2;
      if('αεηιουω'.includes(b1)){
        if(b2 && 'αεηιουω'.includes(b2) && diph.has(two)){
          nuclei.push({ idx: letters[k].idx, kind:'diph' });
          k++; // consume second vowel
        } else {
          nuclei.push({ idx: letters[k].idx, kind:'v' });
        }
      }
    }

    if(nuclei.length === 0) return w;

    const targetIndex = nuclei.length - targetFromEnd;
    const nuc = nuclei[Math.max(0, targetIndex)];

    // Insert accent mark after any existing breathing/diaeresis on that vowel.
    // In NFD, vowel letter at nuc.idx; following combining marks may include breathings etc.
    let insertPos = nuc.idx + 1;
    while(insertPos < d.length){
      const c = d[insertPos];
      if(!(c >= '\u0300' && c <= '\u036f')) break;
      // keep breathings/diaeresis/iota-sub before accent
      if(c === combining.smooth || c === combining.rough || c === combining.diaeresis || c === combining.iotaSub){
        insertPos++;
        continue;
      }
      // if some other combining mark, stop
      break;
    }

    const outD = d.slice(0, insertPos) + mark + d.slice(insertPos);
    return nfc(outD);
  }

  function guessAccentType(word){
    const w0 = tokenizeGreekWords(word);
    const w = stripAllDiacritics(w0).toLowerCase();
    const trace = [];

    if(!w0){
      return { type:null, trace:['No Greek word detected.'] };
    }

    const sylls = countSyllables(w0);

    // Rule 1: ω- disyllables, no i attached
    if(sylls === 2 && w.startsWith('ω')){
      if(!hasIotaAttachedOmega(w0)){
        trace.push("Starts with ω, disyllabic, and no attached ι → barytone (ὧρος/ὦμος/ὦχρος). ");
        return { type:'barytone', trace };
      } else {
        trace.push("Starts with ω but has attached ι (ᾠ-/ωι-) → treat as exception (cf. ᾠδός), fall through.");
      }
    }

    // Rule 2: disyllables in -μος
    if(sylls === 2 && endsWith(w0,'μος')){
      const diphPen = penultHasDiphthong(w0);
      const consStart = startsWithConsonant(w0);
      if(diphPen && consStart){
        trace.push("Disyllable in -μος with diphthong in penult and consonant start → oxytone (λοιμός/λαιμός). ");
        return { type:'oxytone', trace };
      }
      if(diphPen && !consStart){
        trace.push("Disyllable in -μος with diphthong in penult but vowel start → barytone (Αἷμος / οἶμος). ");
        return { type:'barytone', trace };
      }
      trace.push("Ends in -μος but doesn’t match the diphthong+start condition → default paroxytone (toy default). ");
      return { type:'paroxytone', trace };
    }

    // Rule 3: trisyllables in -αμος
    if(sylls === 3 && endsWith(w0,'αμος')){
      // check for -ταμος (t before a)
      if(/ταμος$/.test(w)){
        trace.push("Trisyllable in -αμος with τ before α (…ταμος) → oxytone (ποταμός/ἰταμός). ");
        return { type:'oxytone', trace };
      }
      trace.push("Trisyllable in -αμος → proparoxytone (πλόκαμος etc.), unless special quantity/proper-name cases (toy ignores). ");
      return { type:'proparoxytone', trace };
    }

    // Fallback
    trace.push("No matching Herodian-style trigger found → default paroxytone (toy default). ");
    return { type:'paroxytone', trace };
  }

  let manualAccent = 'oxytone';

  function setManualAccent(type){
    manualAccent = type;
    $$('#manual .chip').forEach(b => b.classList.toggle('active', b.dataset.accent === type));
    render();
  }

  function currentMode(){
    return $('input[name="mode"]:checked').value;
  }

  function render(){
    const raw = input.value;
    const word = tokenizeGreekWords(raw);
    if(!word){
      out.textContent = '—';
      why.textContent = 'Enter a word to see the rule trace.';
      return;
    }

    let accentType, trace;
    if(currentMode() === 'auto'){
      const g = guessAccentType(word);
      accentType = g.type;
      trace = g.trace;
    } else {
      accentType = manualAccent;
      trace = [`Manual mode: you chose ${accentType}.`];
    }

    const accented = applyAccent(word, accentType);

    out.textContent = accented;
    why.innerHTML = trace.map(t => `• ${escapeHtml(t)}`).join('<br>');
  }

  function escapeHtml(s){
    return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  // Events
  input.addEventListener('input', render);

  $$('#manual .chip').forEach(btn => {
    btn.addEventListener('click', () => setManualAccent(btn.dataset.accent));
  });

  $$('input[name="mode"]').forEach(r => {
    r.addEventListener('change', () => {
      const m = currentMode();
      manualWrap.hidden = (m !== 'manual');
      render();
    });
  });

  copyBtn.addEventListener('click', async () => {
    const text = out.textContent;
    if(!text || text === '—') return;
    try{
      await navigator.clipboard.writeText(text);
      copyBtn.textContent = 'Copied';
      setTimeout(()=> copyBtn.textContent='Copy', 700);
    } catch(e){
      // Fallback: select input and instruct
      input.focus();
      input.setSelectionRange(0, input.value.length);
      copyBtn.textContent = 'Select & copy';
      setTimeout(()=> copyBtn.textContent='Copy', 900);
    }
  });

  randomBtn.addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    input.value = ex;
    render();
  });

  clearBtn.addEventListener('click', () => {
    input.value = '';
    render();
    input.focus();
  });

  // init
  setManualAccent('oxytone');
  render();
})();

