.miniRow{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.tag{font-size:11px;color:var(--faint);border:1px solid rgba(255,255,255,.14);padding:2px 8px;border-radius:999px;background:rgba(0,0,0,.18)}
