.btn{background:rgba(124,240,197,.14);border:1px solid rgba(124,240,197,.35);color:var(--text);padding:10px 12px;border-radius:12px;cursor:pointer;font-size:13px}
.btn:hover{background:rgba(124,240,197,.20)}
.out{min-height:120px;padding:10px;border-radius:12px;background:rgba(0,0,0,.22);border:1px solid rgba(255,255,255,.10);font-size:14px;line-height:1.45}
