.line:last-child{margin-bottom:0}
.k{color:var(--faint);font-size:12px}
.v{margin-top:2px}
.good{color:var(--accent)}
.warn{color:var(--warn)}
.bad{color:var(--bad)}
.hint{margin-top:10px;color:var(--muted);font-size:12.5px}
details summary{cursor:pointer;color:var(--muted);font-size:13px}
.rules{margin-top:10px;color:var(--muted);font-size:13px;line-height:1.45}
.rules strong{color:var(--text)}
.small{color:var(--muted);font-size:12.5px}
.foot{margin-top:12px;opacity:.95}
mark{background:rgba(124,240,197,.18);color:var(--text);padding:0 4px;border-radius:6px;border:1px solid rgba(124,240,197,.25)}

