(() => {
  const $ = (sel) => document.querySelector(sel);
  const inp = $('#inp');
  const out = $('#out');
  const btnDemo = $('#btnDemo');
  const optStrip = $('#optStrip');
  const optPhrase = $('#optPhrase');
  const optShowSyll = $('#optShowSyll');

  const ACUTE = '\u0301'; // combining acute

  // --- Greek helpers (toy-level) ---
  const combiningMarks = /[\u0300-\u036f]/g;

  function nfd(s){ return s.normalize('NFD'); }
  function nfc(s){ return s.normalize('NFC'); }

  function stripDiacriticsKeepLetters(s){
    // Keep Greek letters, remove combining marks; also normalize final sigma.
    const t = nfd(s).replace(combiningMarks,'');
    return nfc(t);
  }

  function isGreekLetter(ch){
    const code = ch.codePointAt(0);
    return (
      (code >= 0x0370 && code <= 0x03FF) ||
      (code >= 0x1F00 && code <= 0x1FFF)
    );
  }

  function normalizeWord(raw){
    let s = raw.trim();
    if (!s) return '';
    // remove punctuation around
    s = s.replace(/^[^\p{L}]+|[^\p{L}]+$/gu,'');
    // normalize sigma
    s = s.replace(/ς/g,'σ');
    return s;
  }

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

  function isVowel(ch){ return vowels.has(ch); }

  function roughSyllables(word){
    // Very rough: split before each vowel group (diphthongs treated as one group).
    // Returns array of syllable strings.
    const w = word;
    if (!w) return [];

    const chars = Array.from(w);
    const syl = [];
    let cur = '';

    function isDiph(a,b){
      const A = a.toLowerCase(), B = (b||'').toLowerCase();
      const pairs = new Set(['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ωυ']);
      return pairs.has(A+B);
    }

    for (let i=0;i<chars.length;i++){
      const ch = chars[i];
      const next = chars[i+1];
      cur += ch;
      if (isVowel(ch)){
        // if diphthong, keep going
        if (next && isVowel(next) && isDiph(ch,next)){
          continue;
        }
        // close syllable at end of vowel group; consonants after will be handled by next syllable start
        syl.push(cur);
        cur = '';
      }
    }
    if (cur) {
      // attach trailing consonants to last syllable if any
      if (syl.length) syl[syl.length-1] += cur;
      else syl.push(cur);
    }
    return syl;
  }

  function penultHasE(word){
    const syl = roughSyllables(word);
    if (syl.length < 2) return false;
    const pen = syl[syl.length-2].toLowerCase();
    return pen.includes('ε');
  }

  function penultHasEta(word){
    const syl = roughSyllables(word);
    if (syl.length < 2) return false;
    const pen = syl[syl.length-2];
    return pen.includes('η') || pen.includes('Η');
  }

  function startsWithTwoConsonants(word){
    const w = word;
    const chars = Array.from(w);
    let letters = chars.filter(isGreekLetter);
    if (letters.length < 2) return false;
    const a = letters[0], b = letters[1];
    return !isVowel(a) && !isVowel(b);
  }

  function endsWith(word, ending){
    return word.toLowerCase().endsWith(ending);
  }

  function addAcuteToSyllable(word, syllIndex){
    // Add combining acute to first vowel in that syllable.
    const syl = roughSyllables(word);
    if (!syl.length) return {accented: word, syl};
    const idx = Math.max(0, Math.min(sylIndex, syl.length-1));

    let target = syl[idx];
    const chars = Array.from(target);
    for (let i=0;i<chars.length;i++){
      if (isVowel(chars[i])){
        chars[i] = nfd(chars[i]) + ACUTE;
        target = nfc(chars.join(''));
        break;
      }
    }
    syl[idx] = target;
    return {accented: nfc(syl.join('')), syl};
  }

  function guessAccent(wordRaw){
    const original = normalizeWord(wordRaw);
    if (!original) return null;

    const base = optStrip.checked ? stripDiacriticsKeepLetters(original) : original;
    const w = base;
    const syl = roughSyllables(w);
    const syllCount = syl.length;

    const lower = w.toLowerCase();

    // Special cases explicitly mentioned
    const specialOxytone = new Set(['σχινδαλαμος','θελεμος']);
    if (specialOxytone.has(stripDiacriticsKeepLetters(lower))){
      const res = addAcuteToSyllable(w, syllCount-1);
      return {
        original,
        normalized: w,
        rule: 'Special case from passage: oxytone (accent on ultima).',
        position: 'ultima',
        syllables: res.syl,
        accented: res.accented
      };
    }

    // Determine ending class
    const ending = ['ιμος','ομος','υμος','αμος','εμος','ημος','μος'].find(e => endsWith(lower, e));

    let target = null;
    let rule = '';

    if (!ending){
      // fallback: if 3+ syllables, antepenult; else penult
      if (syllCount >= 3){
        target = syllCount-3;
        rule = 'Fallback: 3+ syllables → antepenult.';
      } else if (syllCount === 2){
        target = syllCount-2;
        rule = 'Fallback: 2 syllables → penult.';
      } else {
        target = 0;
        rule = 'Fallback: 1 syllable.';
      }
    } else {
      if (ending === 'αμος'){
        if (startsWithTwoConsonants(w) && syllCount >= 3){
          target = syllCount-3;
          rule = "-αμος + starts with two consonants → antepenult (Herodian).";
        } else {
          // not covered well; choose penult if possible
          target = syllCount >= 2 ? syllCount-2 : 0;
          rule = "-αμος but not (two-consonant start) → toy chooses penult.";
        }
      } else if (ending === 'μος'){
        if (syllCount > 2 && penultHasE(w)){
          target = syllCount-3;
          rule = "-μος, >2 syllables, ε in penult → antepenult (Herodian).";
        } else if (syllCount >= 3){
          target = syllCount-3;
          rule = "-μος, >2 syllables → toy leans antepenult (common in passage).";
        } else {
          target = syllCount === 2 ? syllCount-2 : 0;
          rule = "-μος, ≤2 syllables → toy chooses penult/only syllable.";
        }
      } else if (ending === 'εμος'){
        if (syllCount > 2){
          target = syllCount-3;
          rule = "-εμος, >2 syllables → antepenult (by the ε-penult pattern).";
        } else {
          target = syllCount-2;
          rule = "-εμος, 2 syllables → penult (toy).";
        }
      } else if (ending === 'ημος'){
        if (syllCount > 2){
          target = syllCount-3;
          rule = "-ημος (simple, rare) → antepenult (Herodian; toy).";
        } else {
          target = syllCount-2;
          rule = "-ημος, 2 syllables → penult (toy).";
        }
      } else if (ending === 'ιμος'){
        if (syllCount > 2){
          target = syllCount-3;
          rule = "-ιμος, >2 syllables → antepenult (Herodian).";
        } else {
          target = syllCount-2;
          rule = "-ιμος, 2 syllables → penult (toy).";
        }
      } else if (ending === 'ομος'){
        if (syllCount > 2){
          target = syllCount-3;
          rule = "-ομος, >2 syllables → antepenult (Herodian; exceptions exist).";
        } else {
          target = syllCount-2;
          rule = "-ομος, 2 syllables → penult (toy).";
        }
      } else if (ending === 'υμος'){
        if (syllCount > 2){
          target = syllCount-3;
          rule = "-υμος with short υ before -μος → antepenult (Herodian; toy assumes short).";
        } else {
          target = syllCount-2;
          rule = "-υμος, 2 syllables → penult (toy).";
        }
      }
    }

    const res = addAcuteToSyllable(w, target);
    const posName = (target === syllCount-1) ? 'ultima' : (target === syllCount-2) ? 'penult' : (target === syllCount-3) ? 'antepenult' : `syllable ${target+1}`;

    return {
      original,
      normalized: w,
      rule,
      position: posName,
      syllables: res.syl,
      accented: res.accented
    };
  }

  function escapeHtml(s){
    return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  function render(){
    const text = inp.value;
    const parts = optPhrase.checked ? text.split(/\s+/).filter(Boolean) : [text];
    const results = [];

    for (const p of parts){
      const r = guessAccent(p);
      if (r) results.push(r);
    }

    if (!results.length){
      out.innerHTML = `<div class="k">Type a word above. The toy will suggest an accent for -μος words.</div>`;
      return;
    }

    out.innerHTML = results.map(r => {
      const syl = optShowSyll.checked ? `<div class="k">Syllables (rough): <span class="mono">${escapeHtml(r.syllables.join('·'))}</span></div>` : '';
      const changed = stripDiacriticsKeepLetters(r.original) !== stripDiacriticsKeepLetters(r.accented);
      const statusClass = changed ? 'good' : 'warn';
      const status = changed ? 'accented' : 'no change';
      return `
        <div class="line">
          <div class="k">Input: <span class="mono">${escapeHtml(r.original)}</span></div>
          <div class="v">Guess: <mark class="mono">${escapeHtml(r.accented)}</mark> <span class="k">(${escapeHtml(r.position)})</span> <span class="k ${statusClass}">• ${status}</span></div>
          ${syl}
          <div class="k">Rule: ${escapeHtml(r.rule)}</div>
        </div>
      `;
    }).join('');
  }

  inp.addEventListener('input', render);
  optStrip.addEventListener('change', render);
  optPhrase.addEventListener('change', render);
  optShowSyll.addEventListener('change', render);

  btnDemo.addEventListener('click', () => {
    inp.value = 'πολεμος Τηλεμος σχινδαλαμος θελεμος ἀγωγιμος ἑβδομος Περγαμος';
    render();
    inp.focus();
  });

  // initial
  render();
})();

