const $ = (id)=>document.getElementById(id);

const examples = [
  {w:"μερισμος", note:"…σμος >2 syllables → oxytone"},
  {w:"οπλισμος", note:"…σμος >2 syllables → oxytone"},
  {w:"αθροισμος", note:"…σμος >2 syllables → oxytone"},
  {w:"αφλοισμος", note:"…σμος >2 syllables → oxytone"},
  {w:"κυδοιμος", note:"trisyllabic -οιμος (fem.) → oxytone"},
  {w:"Ευρωμος", note:"-ωμος >2 syllables → proparoxytone"},
  {w:"Ιθωμος", note:"-ωμος >2 syllables → proparoxytone"},
  {w:"Πατουμος", note:"-ουμος >2 syllables → proparoxytone"},
  {w:"στεγνος", note:"-γνος (fem.) → oxytone"},
  {w:"στυγνος", note:"-γνος (fem.) → oxytone"},
  {w:"αγνος", note:"-γνος (fem.) → oxytone"},
  {w:"λαγνος", note:"exception mentioned: λάγνος not oxytone"}
];

// --- Greek normalization helpers ---
const COMBINING = /[\u0300-\u036f]/g;

function stripDiacritics(s){
  // NFD splits polytonic into base + combining marks; remove combining.
  return s.normalize('NFD').replace(COMBINING,'').normalize('NFC');
}

function stripPunctuation(s){
  return s.replace(/[··.,;:!?"'“”‘’()\[\]{}<>«»—–…]/g,' ').replace(/\s+/g,' ').trim();
}

function normalizeGreek(s){
  s = stripPunctuation(s);
  // keep Greek letters only + spaces
  s = s.replace(/[^\u0370-\u03FF\u1F00-\u1FFF\s]/g,'');
  return stripDiacritics(s);
}

function hasAccent(s){
  // detect tonos/oxia/varia/perispomeni as combining or precomposed
  const nfd = s.normalize('NFD');
  return /[\u0300\u0301\u0342]/.test(nfd) || /[άέήίόύώΆΈΉΊΌΎΏΐΰ]/.test(s);
}

// --- Rough syllabification ---
const vowels = new Set([...'αεηιουωΑΕΗΙΟΥΩ']);

function isVowel(ch){return vowels.has(ch);}

function syllabify(word){
  // Very rough: split after each vowel group (including diphthongs).
  // Treat αι ει οι υι αυ ευ ου ηυ as vowel groups.
  const w = word;
  const groups = [];
  let i=0;
  while(i<w.length){
    let ch = w[i];
    if(!isVowel(ch)){
      // accumulate consonants until vowel
      let j=i;
      while(j<w.length && !isVowel(w[j])) j++;
      // attach consonant cluster to next syllable onset; store temporarily
      groups.push({type:'C', text:w.slice(i,j)});
      i=j;
      continue;
    }
    // vowel group
    let j=i+1;
    // possible diphthongs (lowercase compare)
    const a = w[i].toLowerCase();
    const b = (w[i+1]||'').toLowerCase();
    const pair = a+b;
    const diph = new Set(['αι','ει','οι','υι','αυ','ευ','ου','ηυ']);
    if(diph.has(pair)) j=i+2;
    groups.push({type:'V', text:w.slice(i,j)});
    i=j;
  }
  // Build syllables: onset consonants + vowel group + following consonants up to next vowel (but keep last consonant as onset if possible)
  // Simpler: create syllable at each V group; attach preceding C group as onset.
  const sylls=[];
  let onset='';
  for(let k=0;k<groups.length;k++){
    const g=groups[k];
    if(g.type==='C') onset += g.text;
    else {
      sylls.push(onset + g.text);
      onset='';
    }
  }
  if(onset && sylls.length){
    // trailing consonants: attach to last syllable
    sylls[sylls.length-1]+=onset;
  }
  if(!sylls.length) return [word];
  return sylls;
}

function accentuate(word, target){
  // target: 'oxy' last, 'paro' penult, 'proparo' antepenult
  const sylls = syllabify(word);
  const n = sylls.length;
  let idx = n-1;
  if(target==='paro') idx = Math.max(0,n-2);
  if(target==='proparo') idx = Math.max(0,n-3);

  // place acute on first vowel of that syllable
  const syl = sylls[idx];
  const chars = [...syl];
  let placed=false;
  for(let i=0;i<chars.length;i++){
    if(isVowel(chars[i])){
      // add combining acute
      chars[i] = (chars[i].normalize('NFD') + '\u0301').normalize('NFC');
      placed=true;
      break;
    }
  }
  const newSyl = chars.join('');
  const out = sylls.map((s,i)=> i===idx?newSyl:s).join('');
  return {out, sylls, idx, placed};
}

function detectPattern(norm){
  const w = norm.replace(/\s+/g,'');
  const sylls = syllabify(w);
  const n = sylls.length;

  const lower = w.toLowerCase();

  // -ωμος / -ουμος
  if(lower.endsWith('ωμος') && n>2){
    return {rule:'-ωμος (>2 syllables) → proparoxytone', target:'proparo', strength:'good', why:"Herodian: Τὰ εἰς 'ωμος' ὑπερδισύλλαβα προπαροξύνεται."};
  }
  if(lower.endsWith('ουμος') && n>2){
    return {rule:'-ουμος (>2 syllables) → proparoxytone', target:'proparo', strength:'good', why:"Herodian: ὁμοίως τὰ διὰ τοῦ 'ουμος' ὑπερδισύλλαβα (e.g. Πάτουμος)."};
  }

  // -σμος with >2 syllables
  if(lower.endsWith('σμος') && n>2){
    return {rule:'…σμος (>2 syllables) → oxytone', target:'oxy', strength:'good', why:"Herodian: Τὰ εἰς 'μος' … ἔχοντα πρὸ τοῦ 'μ' τὸ 'σ' ὀξύνεσθαι θέλει (μερισμός, ὁπλισμός…)."};
  }

  // trisyllabic -οιμος
  if(lower.endsWith('οιμος') && n===3){
    return {rule:'trisyllabic -οιμος → often oxytone (esp. fem.)', target:'oxy', strength:'warn', why:"Herodian: τρισύλλαβα εἰς -μος παραληγόμενα τῇ 'οι' διφθόγγῳ … θηλυκῷ γένει ὀξύνεται (κυδοιμός)."};
  }

  // -νος with medial consonant before ν
  if(lower.endsWith('νος') && lower.length>=3){
    const beforeN = lower[lower.length-3];
    const medial = new Set(['γ','δ','θ','κ','π','τ','β','φ','χ']);
    if(medial.has(beforeN)){
      // exception: λαγνος mentioned as not oxytone
      if(lower==='λαγνος'){
        return {rule:"exception: λάγνος not oxytone", target:'paro', strength:'bad', why:"Herodian: τὸ μέντοι λάγνος βαρύνεται."};
      }
      return {rule:'-νος with medial before ν → oxytone (esp. fem.)', target:'oxy', strength:'warn', why:"Herodian: Τὰ εἰς 'νος' … ἔχοντα πρὸ τοῦ 'ν' ἕν τι τῶν μέσων στοιχείων … θηλυκὸν γένος ὀξύνεται (στεγνός, στυγνός…)."};
    }
  }

  // fallback
  return {rule:'no specific rule detected here', target:(sylls.length>=3?'paro':'oxy'), strength:'warn', why:"This toy only implements a few patterns from the passage; try a word in -σμος, -ωμος, -ουμος, or -γνος/-κνος etc."};
}

function strengthLabel(s){
  if(s==='good') return '<span class="badge hl-good">strong match</span>';
  if(s==='bad') return '<span class="badge hl-bad">exception</span>';
  return '<span class="badge hl-warn">heuristic</span>';
}

function render(word, forcedTarget=null){
  const raw = word;
  const keep = $('chkKeep').checked;
  const norm = normalizeGreek(raw);
  const compact = norm.replace(/\s+/g,'');

  $('norm').textContent = compact || '—';
  if(!compact){
    $('syll').textContent = '—';
    $('pat').innerHTML = '—';
    $('acc').textContent = '—';
    $('why').textContent = '—';
    return;
  }

  const det = detectPattern(compact);
  const target = forcedTarget || det.target;

  const alreadyAccented = hasAccent(raw);
  let suggested;
  if(keep && alreadyAccented){
    // still show syllables based on normalized form
    const sylls = syllabify(compact);
    suggested = {out: raw, sylls};
  } else {
    suggested = accentuate(compact, target);
  }

  $('syll').textContent = suggested.sylls.join('·');
  $('pat').innerHTML = `${det.rule} ${strengthLabel(det.strength)}`;
  $('acc').textContent = suggested.out;
  $('why').textContent = det.why + (forcedTarget?` (You forced: ${forcedTarget}.)`:'' ) + (keep && alreadyAccented?" (Kept your existing accents.)":"");
}

$('btnAnalyze').addEventListener('click', ()=>render($('inp').value));
$('btnClear').addEventListener('click', ()=>{ $('inp').value=''; render(''); $('inp').focus(); });
$('btnRandom').addEventListener('click', ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('inp').value = ex.w;
  render(ex.w);
});
$('inp').addEventListener('keydown', (e)=>{ if(e.key==='Enter') render($('inp').value); });

$('btnOx').addEventListener('click', ()=>render($('inp').value,'oxy'));
$('btnPar').addEventListener('click', ()=>render($('inp').value,'paro'));
$('btnPro').addEventListener('click', ()=>render($('inp').value,'proparo'));

// initial
render('');

