:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --card:#1e2238;
  --text:#e9ecff;
  --muted:#b7bddc;
  --faint:#8c93b8;
  --accent:#8be9fd;
  --accent2:#b4f59a;
  --warn:#ffcc66;
  --danger:#ff6b8a;
  --border:rgba(255,255,255,.10);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
}
*{box-sizing:border-box}
body{margin:0; font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Arial, "Noto Sans", "Liberation Sans", sans-serif; background: radial-gradient(1200px 700px at 20% 0%, #1a1f3a 0%, var(--bg) 55%); color:var(--text)}
.wrap{max-width:1050px; margin:0 auto; padding:22px 18px 40px}
header h1{margin:0 0 6px; font-size:22px; letter-spacing:.2px}
.sub{margin:0; color:var(--muted); line-height:1.35}
.panel{margin-top:16px; background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02)); border:1px solid var(--border); border-radius:14px; padding:14px; box-shadow:var(--shadow)}
.row{display:flex; gap:10px; align-items:center; flex-wrap:wrap}
.row.small{margin-top:10px}
label{color:var(--muted); font-size:13px; min-width:52px}
input[type=text]{flex:1; min-width:260px; padding:10px 12px; border-radius:10px; border:1px solid var(--border); background:rgba(0,0,0,.25); color:var(--text); outline:none}
input[type=text]:focus{border-color:rgba(139,233,253,.55); box-shadow:0 0 0 3px rgba(139,233,253,.12)}
button{padding:9px 11px; border-radius:10px; border:1px solid rgba(139,233,253,.35); background:rgba(139,233,253,.12); color:var(--text); cursor:pointer}
button:hover{background:rgba(139,233,253,.18)}
button.ghost{border-color:var(--border); background:rgba(255,255,255,.06)}
button.ghost:hover{background:rgba(255,255,255,.10)}
.out{display:grid; grid-template-columns: 1fr; gap:12px; margin-top:12px}
@media (min-width: 900px){.out{grid-template-columns: 1fr 1fr 1.2fr}}
.card{background:var(--card); border:1px solid var(--border); border-radius:14px; padding:12px 12px 10px}
.card h2{margin:0 0 8px; font-size:14px; color:var(--muted); font-weight:650; letter-spacing:.2px}
.mono{font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "DejaVu Sans Mono", monospace}
.big{font-size:22px; font-weight:750; letter-spacing:.2px}
.hint{margin-top:8px; color:var(--faint); font-size:12.5px; line-height:1.35}
.grid2{display:grid; grid-template-columns:1fr; gap:10px}
@media (min-width: 520px){.grid2{grid-template-columns:1fr 1fr}}
.label{color:var(--muted); font-size:12px; margin-bottom:4px}
.controls{display:flex; gap:10px; flex-wrap:wrap; margin-top:10px}
.chips{display:flex; gap:8px; flex-wrap:wrap}
.chip{border:1px solid var(--border); background:rgba(255,255,255,.06); padding:6px 9px; border-radius:999px; font-size:12.5px; color:var(--muted); cursor:pointer; user-select:none}
.chip:hover{background:rgba(255,255,255,.10)}
#ruleGuess.ok{color:var(--accent2)}
#ruleGuess.warn{color:var(--warn)}
#ruleGuess.bad{color:var(--danger)}
footer{margin-top:14px; color:var(--muted)}
details{border:1px solid var(--border); border-radius:12px; padding:10px 12px; background:rgba(0,0,0,.18)}
summary{cursor:pointer; color:var(--text); font-weight:650}
.note{color:var(--muted); font-size:13px; line-height:1.45}
.note ul{margin:8px 0 0 18px}
.note p{margin:8px 0}

