const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const detected = $('#detected');
const ruleGuess = $('#ruleGuess');
const ruleWhy = $('#ruleWhy');
const ox = $('#ox');
const gr = $('#gr');

const chips = $('#chips');
const examples = [
  'πυκνος',
  'τερπνος',
  'στρυφνος',
  'στριφνος',
  'ὀκνος',
  'κυκνος',
  'Κυδνος',
  'μορφνος',
  'γυμνος',
  'στυγνος'
];

function stripDiacritics(s){
  // Remove combining marks; keep Greek letters.
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function lastWord(s){
  const cleaned = s.trim().replace(/[··.,;:!?()\[\]{}<>«»“”"'’]/g,' ');
  const parts = cleaned.split(/\s+/).filter(Boolean);
  return parts.length ? parts[parts.length-1] : '';
}

function isGreekish(s){
  return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(s);
}

function endsWithNos(base){
  return base.endsWith('νος');
}

function countVowels(base){
  // base should be diacritic-free lowercase Greek
  const m = base.match(/[αεηιουω]/g);
  return m ? m.length : 0;
}

function vowelBeforeNos(base){
  // returns the vowel immediately before the final -νος, if present
  if(!endsWithNos(base) || base.length < 4) return null;
  const idx = base.length - 3; // position of ν in -νος
  // look left for the nearest vowel
  for(let i = idx-1; i >= 0; i--){
    const ch = base[i];
    if('αεηιουω'.includes(ch)) return ch;
    // stop if we hit another vowel? (we already check)
  }
  return null;
}

function hasOrNearEnd(base){
  // crude: contains 'ορ' in the last 4-5 letters before ending
  // e.g. μορφνος has 'ορ' before end.
  const tail = base.slice(Math.max(0, base.length-6));
  return tail.includes('ορ');
}

function titleCaseGreek(s){
  if(!s) return s;
  return s[0].toUpperCase() + s.slice(1);
}

function applyAcuteOnUltima(word){
  // Put an acute on the last vowel of the word.
  // Very simplified: only handles plain vowels (αεηιουω) and common diphthongs.
  const w = word.normalize('NFC');
  const base = stripDiacritics(w);
  // Find last vowel position in base, map to original indices by scanning.
  // We'll rebuild from base to avoid mixed diacritics.
  const chars = Array.from(base);
  let i = chars.length - 1;
  while(i >= 0 && !'αεηιουω'.includes(chars[i])) i--;
  if(i < 0) return w;

  // Handle diphthongs: if last vowel is ι or υ and preceded by αεοηω, accent the first.
  if(i > 0 && (chars[i] === 'ι' || chars[i] === 'υ') && 'αεοηω'.includes(chars[i-1])){
    i = i-1;
  }

  const acuteMap = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };
  chars[i] = acuteMap[chars[i]] || chars[i];
  return chars.join('');
}

function acuteToGraveOnUltima(word){
  // Replace acute on last vowel with grave (ά->ὰ etc.)
  const w = word.normalize('NFC');
  const chars = Array.from(w);
  // Find last vowel (including accented forms)
  const vowelLike = /[αεηιουωάέήίόύώὰὲὴὶὸὺὼᾶῆῖῦῶ]/;
  let i = chars.length - 1;
  while(i >= 0 && !vowelLike.test(chars[i])) i--;
  if(i < 0) return w;

  const map = {
    'ά':'ὰ','έ':'ὲ','ή':'ὴ','ί':'ὶ','ό':'ὸ','ύ':'ὺ','ώ':'ὼ',
    'Ά':'Ὰ','Έ':'Ὲ','Ή':'Ὴ','Ί':'Ὶ','Ό':'Ὸ','Ύ':'Ὺ','Ώ':'Ὼ'
  };
  chars[i] = map[chars[i]] || chars[i];
  return chars.join('');
}

function guessRule(word){
  const raw = word;
  const base = stripDiacritics(raw).toLowerCase();

  if(!raw) return {status:'bad', label:'—', why:'Type something.'};
  if(!isGreekish(raw)) return {status:'bad', label:'Not Greek?', why:'This toy expects Greek letters.'};
  if(!endsWithNos(base)) return {status:'warn', label:'Not -νος', why:"Herodian’s rule here is about words ending in -νος. Try one like πυκνος / ὀκνος."};

  const vcount = countVowels(base);
  const disyll = (vcount === 2);
  const vBefore = vowelBeforeNos(base);
  const hasOr = hasOrNearEnd(base);

  // Heuristic inspired by the passage:
  // - If disyllabic and vowel before -νος is not α => barytone tendency (ὄκνος, κύκνος)
  // - If no -ορ- near end and looks adjective-ish => oxytone tendency (πυκνός etc.)
  // We cannot detect adjective vs proper name reliably; we just report confidence.

  if(disyll && vBefore && vBefore !== 'α'){
    return {
      status:'ok',
      label:'Barytone-leaning',
      why:`Looks disyllabic (-νος) with vowel before -νος = “${vBefore}” (≠ α) → like ὄκνος, κύκνος in the passage.`
    };
  }

  if(hasOr){
    return {
      status:'ok',
      label:'Barytone-leaning',
      why:`Contains “ορ” near the end → Herodian notes -ορ- before the end tends to pull words away from the oxytone pattern (cf. μόρφνος discussion).`
    };
  }

  return {
    status:'ok',
    label:'Oxytone-leaning',
    why:`Simple -νος form without “ορ” near the end → like πυκνός, τερπνός, στρυφνός (as discussed).`
  };
}

function update(){
  const w = lastWord(inp.value);
  detected.textContent = w || '—';

  const g = guessRule(w);
  ruleGuess.textContent = g.label;
  ruleGuess.classList.remove('ok','warn','bad');
  ruleGuess.classList.add(g.status);
  ruleWhy.textContent = g.why;

  if(!w){
    ox.textContent = '—';
    gr.textContent = '—';
    return;
  }

  const oxForm = applyAcuteOnUltima(w);
  ox.textContent = oxForm;
  gr.textContent = acuteToGraveOnUltima(oxForm);
}

function setInput(val){
  inp.value = val;
  update();
  inp.focus();
}

function buildChips(){
  chips.innerHTML = '';
  for(const ex of examples){
    const b = document.createElement('div');
    b.className = 'chip mono';
    b.textContent = ex;
    b.title = 'Click to load';
    b.addEventListener('click', () => setInput(ex));
    chips.appendChild(b);
  }
}

$('#btnDemo').addEventListener('click', () => {
  const pick = examples[Math.floor(Math.random()*examples.length)];
  setInput(pick);
});

$('#btnClear').addEventListener('click', () => setInput(''));

$('#btnFlip').addEventListener('click', () => {
  if(ox.textContent === '—') return;
  // flip displayed ox/gr by toggling acute<->grave on ultima
  const cur = ox.textContent;
  const flipped = acuteToGraveOnUltima(cur);
  if(flipped !== cur){
    ox.textContent = flipped;
    gr.textContent = applyAcuteOnUltima(stripDiacritics(flipped));
  }else{
    // if no acute to convert, re-apply acute
    const re = applyAcuteOnUltima(stripDiacritics(cur));
    ox.textContent = re;
    gr.textContent = acuteToGraveOnUltima(re);
  }
});

$('#btnApply').addEventListener('click', () => {
  const w = lastWord(inp.value);
  if(!w) return;
  const g = guessRule(w);
  const base = stripDiacritics(w);

  if(g.label.startsWith('Oxy')){
    setInput(applyAcuteOnUltima(base));
  }else if(g.label.startsWith('Bary')){
    // For barytone, we *avoid* accenting the ultima; as a toy, put acute on penult if possible.
    const b = stripDiacritics(w);
    const chars = Array.from(b);
    // find penult vowel (second-to-last vowel)
    const vowelIdx = [];
    for(let i=0;i<chars.length;i++) if('αεηιουω'.includes(chars[i])) vowelIdx.push(i);
    if(vowelIdx.length >= 2){
      let i = vowelIdx[vowelIdx.length-2];
      // diphthong handling (accent first element)
      if(i+1 < chars.length && (chars[i+1]==='ι' || chars[i+1]==='υ') && 'αεοηω'.includes(chars[i])){
        // keep i
      } else if(i>0 && (chars[i]==='ι' || chars[i]==='υ') && 'αεοηω'.includes(chars[i-1])){
        i = i-1;
      }
      const acuteMap = {'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ','Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'};
      chars[i] = acuteMap[chars[i]] || chars[i];
      setInput(chars.join(''));
    }else{
      // fallback: just remove diacritics
      setInput(b);
    }
  }else{
    setInput(base);
  }
});

inp.addEventListener('input', update);

buildChips();
update();

