const $ = (sel, el=document) => el.querySelector(sel);
const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

const inp = $('#inp');
const accentedEl = $('#accented');
const traceEl = $('#trace');
const meterEl = $('#meter');

const tonos = '\u0301'; // combining acute
const dialytika = '\u0308';

function stripDiacritics(s){
  // Remove Greek combining marks (tonos, varia, perispomeni, breathings, iota subscript, diaeresis, etc.)
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code>=0x0370 && code<=0x03FF) || (code>=0x1F00 && code<=0x1FFF);
}

function lowerGreek(s){
  // Keep initial capitalization info separately; for matching, lowercase.
  return s.replace(/\p{L}+/gu, m => m.toLowerCase());
}

function endsWithAny(s, arr){
  return arr.some(x => s.endsWith(x));
}

function tokenizeLetters(s){
  // Keep only Greek letters (and final sigma handled by toLowerCase)
  const n = s.normalize('NFC');
  let out='';
  for (const ch of n){
    if (isGreekLetter(ch)) out += ch;
  }
  return out;
}

const vowels = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ']);

function isVowel(ch){
  return vowels.has(ch);
}

function syllabifySimple(word){
  // Very rough: syllable nucleus = vowel; attach following consonants until next vowel.
  const w = stripDiacritics(word);
  const letters = Array.from(w);
  const nuclei = [];
  for (let i=0;i<letters.length;i++){
    if (isVowel(letters[i])) nuclei.push(i);
  }
  if (nuclei.length===0) return {syllables:[w], nuclei:[]};
  const syllables=[];
  for (let s=0;s<nuclei.length;s++){
    const start = (s===0)?0:nuclei[s-1]+1;
    const end = (s===nuclei.length-1)?letters.length:nuclei[s+1];
    // include from start to just before next nucleus
    syllables.push(letters.slice(start,end).join(''));
  }
  return {syllables, nuclei};
}

function applyAcuteOnVowel(word, syllIndexFromEnd){
  // Place combining acute on the vowel of the target syllable (from end: 1=ultima,2=penult,3=antepenult)
  const base = stripDiacritics(word).normalize('NFD');
  const letters = Array.from(base);
  // Find vowel positions in NFD stream (letters only, no marks)
  const plain = stripDiacritics(word);
  const syl = syllabifySimple(plain);
  const n = syl.syllables.length;
  const target = n - syllIndexFromEnd;
  if (target < 0) return stripDiacritics(word);

  // Determine vowel index within the whole word by scanning plain letters
  const plainLetters = Array.from(plain);
  let vowelPositions=[];
  for (let i=0;i<plainLetters.length;i++) if (isVowel(plainLetters[i])) vowelPositions.push(i);
  if (vowelPositions.length===0) return plain;

  // Find the vowel that belongs to the target syllable: take the nucleus at that syllable index.
  // Our syllabifySimple nuclei are indices in plainLetters.
  const nuclei = [];
  for (let i=0;i<plainLetters.length;i++) if (isVowel(plainLetters[i])) nuclei.push(i);
  const nucleusPos = nuclei[Math.min(target, nuclei.length-1)];

  // Now rebuild with acute on that vowel (in NFC)
  let out='';
  for (let i=0;i<plainLetters.length;i++){
    out += plainLetters[i];
    if (i===nucleusPos) out += tonos;
  }
  return out.normalize('NFC');
}

function hasPenultVowel(word, v){
  const plain = stripDiacritics(word);
  const {syllables} = syllabifySimple(plain);
  if (syllables.length < 2) return false;
  const pen = syllables[syllables.length-2];
  return pen.includes(v);
}

function penultLooksLongByNature(word){
  // Toy heuristic: penult contains η or ω, or a diphthong (αι,ει,οι,υι,αυ,ευ,ου,ηυ)
  const plain = stripDiacritics(word);
  const {syllables} = syllabifySimple(plain);
  if (syllables.length < 2) return false;
  const pen = syllables[syllables.length-2];
  if (pen.includes('η') || pen.includes('ω')) return true;
  const dips = ['αι','ει','οι','υι','αυ','ευ','ου','ηυ'];
  return dips.some(d => pen.includes(d));
}

function hasConsonantClusterBeforeNos(word){
  // Look for ...C C (optional) + νος at end; approximate by checking last 4-5 letters.
  const w = stripDiacritics(word);
  if (!w.endsWith('νος')) return false;
  const stem = w.slice(0,-3);
  if (stem.length<2) return false;
  const last2 = stem.slice(-2);
  const c1 = last2[0], c2 = last2[1];
  return !isVowel(c1) && !isVowel(c2);
}

function hasDoubleNn(word){
  const w = stripDiacritics(word);
  return w.includes('νν');
}

function guessAccent(raw){
  const original = raw.trim();
  const lettersOnly = tokenizeLetters(original);
  const plain = stripDiacritics(lettersOnly);
  const lower = lowerGreek(plain);
  const trace=[];

  if (!plain){
    return {accented:'—', trace:['Type a Greek word.'], pills:[]};
  }

  const {syllables} = syllabifySimple(lower);
  trace.push(`Normalized: ${plain} → ${lower} (${syllables.length} syllable${syllables.length===1?'':'s'} by toy syllabifier).`);

  // Special cases explicitly mentioned
  const specials = {
    'καπνος': {place:1, note:"Special-case from passage: καπνός is oxytone (acute on ultima)."},
    'ιπνος': {place:1, note:"Special-case from passage: appellative ἰπνός is oxytone."},
    'αμνος': {place:1, note:"Special-case from passage: ἀμνός is oxytone."}
  };
  if (specials[lower]){
    const acc = applyAcuteOnVowel(lower, specials[lower].place);
    trace.push(specials[lower].note);
    return {accented: preserveInitialCase(plain, acc), trace, pills: buildPills(lower)};
  }

  // -ννος note
  if (hasDoubleNn(lower)){
    trace.push("Contains -νν-: passage notes certain feminine, uninflected -νν- words tend to be barytone. Toy: avoid oxytone unless forced.");
  }

  // -μνος rules
  if (lower.endsWith('μνος')){
    trace.push("Ends in -μνος.");
    const disyll = syllables.length===2;
    if (disyll){
      if (hasPenultVowel(lower,'α')){
        trace.push("Disyllabic -μνος with penult α (+ consonant): barytone in Herodian (θάμνος, ῥάμνος). Toy: accent penult.");
        const acc = applyAcuteOnVowel(lower, 2);
        return {accented: preserveInitialCase(plain, acc), trace, pills: buildPills(lower)};
      }
      const longPen = penultLooksLongByNature(lower);
      if (longPen){
        trace.push("Disyllabic -μνος with penult long by nature: barytone (e.g. Λῆμνος, Τῆμνος). Toy: accent penult.");
        const acc = applyAcuteOnVowel(lower, 2);
        return {accented: preserveInitialCase(plain, acc), trace, pills: buildPills(lower)};
      }
      // tri-gender heuristic: if ends with -νος but looks adjectival? We'll guess by common endings -ος adjectives.
      trace.push("Disyllabic -μνος with penult not clearly long: Herodian says monogender tends barytone, trigender tends oxytone (γυμνός, σεμνός...). Toy heuristic: if it looks adjectival, make oxytone; else barytone.");
      const adjectival = true; // default guess for -μνος forms
      const acc = applyAcuteOnVowel(lower, adjectival?1:2);
      trace.push(adjectival?"Heuristic: treat as adjectival → oxytone (ultima).":"Heuristic: treat as monogender noun → barytone (penult)."");
      return {accented: preserveInitialCase(plain, acc), trace, pills: buildPills(lower)};
    } else {
      trace.push("Polysyllabic -μνος: Herodian often gives proparoxytone for proper/appellatives without their own feminine. Toy: accent antepenult when possible.");
      const place = syllables.length>=3 ? 3 : 2;
      const acc = applyAcuteOnVowel(lower, place);
      return {accented: preserveInitialCase(plain, acc), trace, pills: buildPills(lower)};
    }
  }

  // -νος with consonant cluster + penult υ
  if (lower.endsWith('νος')){
    trace.push("Ends in -νος.");
    const disyll = syllables.length===2;
    const cluster = hasConsonantClusterBeforeNos(lower);
    const penultU = hasPenultVowel(lower,'υ');
    if (disyll && cluster && penultU){
      trace.push("Matches Herodian’s pattern: disyllabic -νος with consonant cluster and penult υ → barytone (ὕμνος, κύκνος, λύχνος, Κύθνος...). Toy: accent penult.");
      const acc = applyAcuteOnVowel(lower, 2);
      return {accented: preserveInitialCase(plain, acc), trace, pills: buildPills(lower)};
    }
    trace.push("No strong match from the cited rule. Toy default: accent penult if possible (recessive-ish)." );
    const acc = applyAcuteOnVowel(lower, syllables.length>=2?2:1);
    return {accented: preserveInitialCase(plain, acc), trace, pills: buildPills(lower)};
  }

  trace.push("Not a -νος/-μνος word. Toy default: accent penult if possible." );
  const acc = applyAcuteOnVowel(lower, syllables.length>=2?2:1);
  return {accented: preserveInitialCase(plain, acc), trace, pills: buildPills(lower)};
}

function preserveInitialCase(originalPlain, accentedLower){
  // If original starts with uppercase Greek, capitalize first letter of output.
  const orig = tokenizeLetters(originalPlain);
  if (!orig) return accentedLower;
  const first = orig[0];
  const isUpper = first === first.toUpperCase() && first !== first.toLowerCase();
  if (!isUpper) return accentedLower;
  // Capitalize first base letter; keep combining marks after it.
  const nfd = accentedLower.normalize('NFD');
  const chars = Array.from(nfd);
  // Find first letter
  for (let i=0;i<chars.length;i++){
    const ch = chars[i];
    if (isGreekLetter(ch)){
      chars[i] = ch.toUpperCase();
      break;
    }
  }
  return chars.join('').normalize('NFC');
}

function buildPills(lower){
  const pills=[];
  const {syllables} = syllabifySimple(lower);
  pills.push({t:`syllables: ${syllables.length}`, cls:'pill'});
  if (lower.endsWith('νος')) pills.push({t:'ends: -νος', cls:'pill good'});
  if (lower.endsWith('μνος')) pills.push({t:'ends: -μνος', cls:'pill good'});
  if (hasConsonantClusterBeforeNos(lower)) pills.push({t:'cluster before -νος', cls:'pill warn'});
  if (hasPenultVowel(lower,'υ')) pills.push({t:'penult has υ', cls:'pill warn'});
  if (hasPenultVowel(lower,'α')) pills.push({t:'penult has α', cls:'pill warn'});
  if (penultLooksLongByNature(lower)) pills.push({t:'penult looks long', cls:'pill'});
  if (hasDoubleNn(lower)) pills.push({t:'has νν', cls:'pill'});
  return pills;
}

function render(result){
  accentedEl.textContent = result.accented;
  traceEl.innerHTML = '';
  result.trace.forEach(line => {
    const li = document.createElement('li');
    li.textContent = line;
    traceEl.appendChild(li);
  });
  meterEl.innerHTML='';
  (result.pills||[]).forEach(p => {
    const span = document.createElement('span');
    span.className = p.cls;
    span.textContent = p.t;
    meterEl.appendChild(span);
  });
}

function go(){
  render(guessAccent(inp.value));
}

$('#btnGo').addEventListener('click', go);
$('#btnClear').addEventListener('click', () => { inp.value=''; inp.focus(); render({accented:'—', trace:[], pills:[]}); });

inp.addEventListener('keydown', (e)=>{
  if (e.key==='Enter') go();
});

$$('.chip').forEach(b=>b.addEventListener('click', ()=>{ inp.value = b.dataset.w; go(); inp.focus(); }));

// initial
render({accented:'—', trace:["Pick a sample or type a word, then click ‘Accent it’."], pills:[]});

