(() => {
  const $ = (sel, root=document) => root.querySelector(sel);

  const inp = $('#inp');
  const btnGuess = $('#btnGuess');
  const btnClear = $('#btnClear');
  const endingEl = $('#ending');
  const guessEl = $('#guess');
  const suggestEl = $('#suggest');
  const explainEl = $('#explain');
  const chkStrip = $('#chkStrip');
  const chkExplain = $('#chkExplain');
  const chips = $('#chips');

  const examples = [
    'κενός','στενός','ξένος','ἔνος','Τένος',
    'Τῆνος','φηνός','πτηνός','ψηνός','θρῆνος',
    'δῖνος','σχῖνος','λίνος','ῥινός','κλεινός',
    'θυνός','ξυνός','φρυνός','Κῦνος'
  ];

  // --- Greek helpers (very lightweight) ---
  const combiningMarks = /[\u0300-\u036f]/g;

  function nfd(s){ return s.normalize('NFD'); }
  function nfc(s){ return s.normalize('NFC'); }

  function stripDiacriticsKeepLetters(s){
    // Remove combining marks; keep Greek letters.
    return nfc(nfd(s).replace(combiningMarks,''));
  }

  function lastIndexOfAny(str, chars){
    for(let i=str.length-1;i>=0;i--){
      if(chars.includes(str[i])) return i;
    }
    return -1;
  }

  const vowels = 'αεηιουωΑΕΗΙΟΥΩ';

  function findLastVowelIndex(word){
    // Work in NFD so we can insert combining acute after base vowel.
    const w = nfd(word);
    // Scan from end, find a base vowel (Greek vowel char)
    for(let i=w.length-1;i>=0;i--){
      const ch = w[i];
      if(vowels.includes(ch)) return i;
    }
    return -1;
  }

  function addAcuteToLastVowel(word){
    const w = nfd(word);
    const i = findLastVowelIndex(word);
    if(i<0) return word;

    // If there is already an accent on that vowel (acute/grave/circumflex), leave it.
    // In NFD, accents are combining marks after the vowel.
    const after = w.slice(i+1);
    const nextChar = after[0] || '';
    const hasAccent = /[\u0300\u0301\u0342]/.test(nextChar) || /[\u0300\u0301\u0342]/.test(after);
    if(hasAccent) return nfc(w);

    const acute = '\u0301';
    const out = w.slice(0,i+1) + acute + w.slice(i+1);
    return nfc(out);
  }

  function detectEnding(word){
    const w = stripDiacriticsKeepLetters(word.trim());
    const lower = w.toLowerCase();
    const endings = ['ενος','ηνος','ινος','υνος'];
    for(const e of endings){
      if(lower.endsWith(e)) return e;
    }
    return null;
  }

  // A tiny “lexicon” of items mentioned in the passage, to make the toy feel grounded.
  // Values: 'oxy' or 'bary'
  const known = new Map([
    // -ενος
    ['ξενος','bary'],
    ['ενος','bary'],
    ['τενος','bary'],
    ['κενος','oxy'],
    ['στενος','oxy'],

    // -ηνος (proper names/appellatives bary; adjectives oxy)
    ['τηνος','bary'],
    ['φηνος','bary'], // river name in passage
    ['ρηνος','bary'],
    ['στρηνος','bary'],
    ['ληνος','bary'],
    ['σηνος','bary'],
    ['ηνος','bary'],
    ['σφηνος','bary'],
    ['σμηνος','bary'],
    ['γληνος','bary'],
    ['μηνος','bary'],
    ['θρηνος','bary'],
    // adjectives in -ηνος
    ['φηνος_adj','oxy'],
    ['πτηνος','oxy'],
    ['ψηνος','oxy'],
    ['στρηνος_adj','oxy'],

    // -ινος
    ['νινος','bary'],
    ['πινος','bary'],
    ['δινος','bary'],
    ['σχινος','bary'],
    ['λινος','bary'],
    ['σπινος','bary'],
    ['γρινος','bary'],
    ['πρινος','bary'],
    ['ρινος','oxy'],
    ['κλεινος','oxy'],
    ['αινος','oxy'],
    ['δεινος','oxy'],

    // -υνος
    ['θυνος','oxy'],
    ['ξυνος','oxy'],
    ['γρυνος','oxy'],
    ['πλυνος','oxy'],
    ['φρυνος','oxy'],
    ['κυνος','bary']
  ]);

  function normalizeKey(word){
    return stripDiacriticsKeepLetters(word).toLowerCase();
  }

  function guessAccent(word){
    const raw = word.trim();
    if(!raw) return { ok:false, msg:'Type a Greek word.' };

    const ending = detectEnding(raw);
    if(!ending) {
      return { ok:false, ending:'—', msg:"I only play with words ending in -ενος, -ηνος, -ινος, -υνος (as in the passage)." };
    }

    const key = normalizeKey(raw);

    // Special handling: φηνός vs Φῆνος etc. We can’t know POS, so offer a toggle-like hint.
    // If user types something that matches a known proper name in -ηνος, treat as bary.
    // If they type a lowercase-looking adjective (no initial capital) and ending -ηνος, lean oxy.
    let verdict = null;
    let confidence = 'warn';
    let why = '';

    // Direct known hits
    if(known.has(key)) {
      verdict = known.get(key);
      confidence = 'good';
      why = 'Matched an example mentioned in the passage.';
    }

    // Heuristic rules from the passage
    if(!verdict) {
      if(ending === 'ενος') {
        verdict = 'bary';
        confidence = 'warn';
        why = 'In -ενος Herodian lists both barytones (ξένος) and oxytones (κενός). Without a lexicon, I default to barytone.';
      } else if(ending === 'ηνος') {
        // If looks like a proper name (initial capital Greek), guess bary; else guess oxy (adjectives).
        const first = raw.trim()[0] || '';
        const isCapitalGreek = first && first === first.toUpperCase() && first !== first.toLowerCase();
        verdict = isCapitalGreek ? 'bary' : 'oxy';
        confidence = 'warn';
        why = isCapitalGreek
          ? 'Herodian: proper names/appellatives in -ηνος are barytone (e.g. Τῆνος).'
          : 'Herodian: adjectives in -ηνος are oxytone (e.g. πτηνός).';
      } else if(ending === 'ινος') {
        verdict = 'bary';
        confidence = 'warn';
        why = 'Herodian: disyllables in -ινος are generally barytone, with a few oxytone exceptions (ῥινός; also κλεινός/αἰνός/δεινός).';
      } else if(ending === 'υνος') {
        // Proper names bary; otherwise oxy.
        const first = raw.trim()[0] || '';
        const isCapitalGreek = first && first === first.toUpperCase() && first !== first.toLowerCase();
        verdict = isCapitalGreek ? 'bary' : 'oxy';
        confidence = 'warn';
        why = isCapitalGreek
          ? 'Herodian: proper names in -υνος are barytone (e.g. Κῦνος).'
          : 'Herodian: disyllables in -υνος are oxytone unless proper names (e.g. θυνός).';
      }
    }

    return { ok:true, ending, verdict, confidence, why };
  }

  function render(){
    const raw0 = inp.value;
    const raw = chkStrip.checked ? stripDiacriticsKeepLetters(raw0) : raw0;

    const res = guessAccent(raw);

    if(!res.ok){
      endingEl.textContent = res.ending || '—';
      guessEl.innerHTML = `<span>—</span> <span class="badge bad">no guess</span>`;
      suggestEl.textContent = '—';
      explainEl.textContent = chkExplain.checked ? res.msg : '';
      return;
    }

    endingEl.textContent = '-' + res.ending;

    const badgeClass = res.confidence === 'good' ? 'good' : (res.confidence === 'warn' ? 'warn' : 'bad');
    const label = res.verdict === 'oxy' ? 'oxytone (acute on last)' : 'barytone (not last)';
    guessEl.innerHTML = `<span>${label}</span> <span class="badge ${badgeClass}">${res.confidence}</span>`;

    let suggested = raw;
    if(res.verdict === 'oxy') {
      suggested = addAcuteToLastVowel(raw);
    } else {
      // For barytone we do not attempt full recessive accentuation; we just avoid last-syllable acute.
      // If user typed an oxytone already and chose “ignore accents”, it will be stripped anyway.
      suggested = raw;
    }
    suggestEl.textContent = suggested;

    explainEl.innerHTML = chkExplain.checked
      ? `<b>Why:</b> ${res.why} <br><b>Note:</b> This toy only places an <b>acute</b> on the last vowel for “oxytone”; it does not compute full Greek accentuation for barytones.`
      : '';
  }

  function mountChips(){
    chips.innerHTML = '';
    for(const ex of examples){
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'chip';
      b.textContent = ex;
      b.addEventListener('click', () => {
        inp.value = ex;
        render();
        inp.focus();
        inp.setSelectionRange(inp.value.length, inp.value.length);
      });
      chips.appendChild(b);
    }
  }

  btnGuess.addEventListener('click', render);
  btnClear.addEventListener('click', () => {
    inp.value = '';
    render();
    inp.focus();
  });
  inp.addEventListener('input', () => {
    // live update, but keep it calm: only if there is something
    if(inp.value.trim().length === 0) render();
  });
  inp.addEventListener('keydown', (e) => {
    if(e.key === 'Enter') render();
  });
  chkStrip.addEventListener('change', render);
  chkExplain.addEventListener('change', render);

  mountChips();
  render();
})();

