const $ = (sel) => document.querySelector(sel);

const examples = [
  "χρονος",
  "Κρονος",
  "δονος",
  "φθονος",
  "πονος",
  "γονος",
  "γονός",
  "Πρωνος",
  "κωνος",
  "ωνος",
  "αινος",
  "οινος",
  "Αυαινος",
  "Κολαινος",
  "Μυραινος",
  "Μελαγχλαινος"
];

// --- Greek helpers (rough-and-ready) ---
const combiningMarks = /[\u0300-\u036f]/g; // includes tonos/oxia etc.

function stripCombining(s){
  return s.normalize('NFD').replace(combiningMarks,'').normalize('NFC');
}

function lowerGreekish(s){
  // Keep Greek final sigma handling simple.
  return s.toLowerCase();
}

function normalizeForMatch(s){
  // remove accents/diacritics for matching endings
  return lowerGreekish(stripCombining(s)).replace(/ς/g,'σ');
}

function isVowel(ch){
  return "αεηιουω".includes(ch);
}

function countSyllables(word){
  // Very rough: count vowel groups, treating common diphthongs as one.
  const w = normalizeForMatch(word);
  const diph = ["αι","ει","οι","υι","αυ","ευ","ου","ηυ","ωυ"]; // last two rare
  let i=0, syl=0;
  while(i<w.length){
    const two = w.slice(i,i+2);
    if(diph.includes(two)){
      syl++; i+=2; continue;
    }
    if(isVowel(w[i])){ syl++; i++; continue; }
    i++;
  }
  return Math.max(0,syl);
}

function endsWithAny(w, arr){
  return arr.find(e => w.endsWith(e)) || null;
}

function accentOnLastSyllable(unaccented){
  // Put acute on the last vowel of the word (very naive).
  const nfd = unaccented.normalize('NFD');
  // find last vowel base in NFD stream
  const bases = Array.from(nfd);
  const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);
  for(let i=bases.length-1;i>=0;i--){
    const ch = bases[i];
    if(vowels.has(ch)){
      bases.splice(i+1,0,"\u0301"); // combining acute
      return bases.join("").normalize('NFC');
    }
  }
  return unaccented;
}

function accentOnPenult(unaccented){
  // Put acute on the penultimate vowel group (naive, but works for many).
  const w = unaccented;
  const n = normalizeForMatch(w);
  // map positions of vowel-group starts in original string indices (approx by scanning original too)
  // We'll scan original string but decide vowel groups using normalized.
  const orig = Array.from(w);
  const norm = Array.from(n);
  const diph = new Set(["αι","ει","οι","υι","αυ","ευ","ου","ηυ","ωυ"]);

  let groups = []; // store index in orig array where group vowel begins
  let i=0;
  while(i<norm.length){
    const two = norm.slice(i,i+2).join("");
    if(diph.has(two)){
      groups.push(i);
      i+=2; continue;
    }
    if(isVowel(norm[i])){ groups.push(i); i++; continue; }
    i++;
  }
  if(groups.length < 2) return accentOnLastSyllable(unaccented);
  const targetNormIndex = groups[groups.length-2];

  // Find corresponding position in original array: assume same length in codepoints after stripping combining.
  // So strip combining from original and align.
  const stripped = Array.from(stripCombining(w));
  // targetNormIndex refers to index in stripped (with final sigma normalized, but length same)
  let targetOrigIndex = targetNormIndex;
  if(targetOrigIndex >= stripped.length) targetOrigIndex = stripped.length-1;

  // Now insert combining acute after that vowel in NFD form.
  const nfd = stripped.join("").normalize('NFD');
  const bases = Array.from(nfd);
  const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);

  // We need the target vowel occurrence number in the stripped string.
  // Count vowels in stripped up to targetOrigIndex and accent that vowel.
  let vowelPositions = [];
  for(let j=0;j<stripped.length;j++){
    if("αεηιουωΑΕΗΙΟΥΩ".includes(stripped[j])) vowelPositions.push(j);
  }
  // Find which vowel position equals targetOrigIndex or nearest at/after.
  let chosen = vowelPositions.find(vp => vp >= targetOrigIndex);
  if(chosen === undefined) chosen = vowelPositions[vowelPositions.length-1];

  // In NFD bases, find the chosen-th base vowel occurrence.
  let seen=0;
  for(let k=0;k<bases.length;k++){
    if(vowels.has(bases[k])){
      if(seen === vowelPositions.indexOf(chosen)){
        bases.splice(k+1,0,"\u0301");
        return bases.join("").normalize('NFC');
      }
      seen++;
    }
  }
  return accentOnLastSyllable(unaccented);
}

function analyze(word){
  const raw = (word||"").trim();
  if(!raw) return {error:"Type a Greek word first."};

  const norm = normalizeForMatch(raw);
  const syll = countSyllables(raw);

  const ending = endsWithAny(norm, ["ονος","ωνος","αινος","οινος"]);

  let rule = null;
  let suggestion = null;
  let note = "";

  if(ending === "ονος"){
    rule = "Herodian: disyllabic, monogender, uninflected -ονος words are barytone (accent not on ultima).";
    if(syll === 2){
      suggestion = accentOnPenult(stripCombining(raw));
      note = "Looks disyllabic → barytone guess: accent the penult.";
    } else {
      suggestion = accentOnPenult(stripCombining(raw));
      note = "Not clearly disyllabic by the toy’s counter, but still showing a barytone-style penult accent.";
    }

    // Special-case γονος/γονός mentioned in passage
    if(norm === "γονος"){
      note += " Special note: Herodian distinguishes γόνος (\"offspring/that which has come to be\") barytone vs γονός (\"begetter\") oxytone.";
    }
  } else if(ending === "ωνος"){
    rule = "Herodian: -ωνος words are barytone.";
    suggestion = accentOnPenult(stripCombining(raw));
    note = "Barytone guess: accent the penult.";
  } else if(ending === "αινος" || ending === "οινος"){
    rule = "Herodian: monogender -αινος and -οινος words are barytone.";
    suggestion = accentOnPenult(stripCombining(raw));
    note = "Barytone guess: accent the penult.";
  } else {
    rule = "No matching ending from this passage’s set.";
    suggestion = null;
    note = "Try a word ending in -ονος, -ωνος, -αινος, or -οινος.";
  }

  // Compare with user accent if any: detect if last syllable seems accented (very rough: tonos/oxia on last vowel)
  const hasAcute = raw.normalize('NFD').includes("\u0301");
  let accentBadge = {text:"unaccented input", cls:"warn"};
  if(hasAcute){
    // Determine if acute is on last vowel by checking last vowel index in NFD and whether next char is acute.
    const nfd = raw.normalize('NFD');
    const arr = Array.from(nfd);
    const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);
    let lastV=-1;
    for(let i=0;i<arr.length;i++) if(vowels.has(arr[i])) lastV=i;
    const lastIsAcute = lastV>=0 && arr[lastV+1]==="\u0301";
    accentBadge = lastIsAcute ? {text:"oxytone-looking", cls:"bad"} : {text:"barytone-looking", cls:"good"};
  }

  return {raw, norm, syll, ending, rule, suggestion, note, accentBadge};
}

function render(res){
  const out = $("#out");
  const ws = $("#workshop");
  ws.innerHTML = "";

  if(res.error){
    out.innerHTML = `<h3>Result</h3><div class="card"><div class="v">${escapeHtml(res.error)}</div></div>`;
    return;
  }

  const endingLabel = res.ending ? `<span class="badge good">ends in -${res.ending}</span>` : `<span class="badge warn">ending not in scope</span>`;
  const syllLabel = res.syll ? `<span class="badge">~${res.syll} syll.</span>` : `<span class="badge warn">syllables?</span>`;
  const accLabel = `<span class="badge ${res.accentBadge.cls}">${escapeHtml(res.accentBadge.text)}</span>`;

  const sugBlock = res.suggestion
    ? `<div class="card"><div class="k">Suggested form (toy)</div><div class="v"><span class="mono">${escapeHtml(res.suggestion)}</span></div></div>`
    : `<div class="card"><div class="k">Suggested form (toy)</div><div class="v">—</div></div>`;

  out.innerHTML = `
    <h3>Result</h3>
    <div class="grid">
      <div class="card">
        <div class="k">Input</div>
        <div class="v"><span class="mono">${escapeHtml(res.raw)}</span> ${endingLabel} ${syllLabel} ${accLabel}</div>
        <div class="k" style="margin-top:10px">Rule cue</div>
        <div class="v" style="font-size:14px; color: var(--muted)">${escapeHtml(res.rule)}</div>
        <div class="k" style="margin-top:10px">Note</div>
        <div class="v" style="font-size:14px; color: var(--muted)">${escapeHtml(res.note)}</div>
      </div>
      ${sugBlock}
    </div>
  `;

  // Workshop suggestions
  const base = stripCombining(res.raw);
  const opts = [];
  if(res.ending){
    opts.push({w: accentOnPenult(base), tag:"barytone (penult acute)"});
    opts.push({w: accentOnLastSyllable(base), tag:"oxytone (ultima acute)"});
    // If -ονος, show the γόνος/γονός contrast explicitly
    if(res.ending === "ονος" && normalizeForMatch(base) === "γονος"){
      opts.unshift({w: "γόνος", tag:"Herodian: barytone sense"});
      opts.unshift({w: "γονός", tag:"Herodian: oxytone sense"});
    }
  } else {
    opts.push({w: accentOnPenult(base), tag:"try penult"});
    opts.push({w: accentOnLastSyllable(base), tag:"try ultima"});
  }

  // Deduplicate
  const seen = new Set();
  for(const o of opts){
    if(seen.has(o.w)) continue;
    seen.add(o.w);
    const pill = document.createElement('div');
    pill.className = 'pill';
    pill.innerHTML = `<span class="w">${escapeHtml(o.w)}</span><span class="tag">${escapeHtml(o.tag)}</span>`;
    pill.addEventListener('click', () => {
      $("#inp").value = o.w;
      run();
      $("#inp").focus();
    });
    ws.appendChild(pill);
  }
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function run(){
  const w = $("#inp").value;
  render(analyze(w));
}

$("#btn").addEventListener('click', run);
$("#inp").addEventListener('keydown', (e)=>{ if(e.key==="Enter") run(); });
$("#btnRandom").addEventListener('click', ()=>{
  const pick = examples[Math.floor(Math.random()*examples.length)];
  $("#inp").value = pick;
  run();
  $("#inp").focus();
});

// initial
$("#inp").value = "χρονος";
run();

