const $ = (sel) => document.querySelector(sel);

// --- Polytonic helpers (minimal, heuristic) ---
const COMBINING = {
  acute: "\u0301",
  grave: "\u0300",
  circumflex: "\u0342",
  diaeresis: "\u0308",
  smooth: "\u0313",
  rough: "\u0314",
  iotaSub: "\u0345",
};

const ACCENT_MARKS = new Set([COMBINING.acute, COMBINING.grave, COMBINING.circumflex]);

function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripAccents(s){
  const d = nfd(s);
  let out = "";
  for (const ch of d){
    if (ACCENT_MARKS.has(ch)) continue;
    out += ch;
  }
  return nfc(out);
}

function stripAllDiacritics(s){
  // Keep Greek letters, remove combining marks broadly.
  return nfc(nfd(s).replace(/[\u0300-\u036f]/g, ""));
}

function lastVowelIndex(base){
  // base should be NFC or plain; we search in NFD to handle combining.
  const d = nfd(base);
  const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);
  // Walk grapheme-ish: find indices of vowel base letters in NFD string.
  let idx = -1;
  for (let i=0;i<d.length;i++){
    const ch = d[i];
    if (vowels.has(ch)) idx = i;
  }
  return idx;
}

function applyFinalAccent(word, which){
  // Add acute/grave to the last vowel letter (not perfect for diphthongs).
  const clean = stripAccents(word);
  const d = nfd(clean);
  const i = lastVowelIndex(clean);
  if (i < 0) return word;
  const mark = which === 'grave' ? COMBINING.grave : COMBINING.acute;
  // Insert mark after the vowel base letter, but before any following combining marks.
  let out = "";
  for (let k=0;k<d.length;k++){
    out += d[k];
    if (k === i){
      // skip if already has accent (we stripped, so no)
      out += mark;
    }
  }
  return nfc(out);
}

function applyProparoxytone(word){
  // Heuristic: accent the antepenult vowel (third from end) with acute.
  // We approximate by counting vowel base letters in NFD.
  const clean = stripAccents(word);
  const d = nfd(clean);
  const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);
  const vowelPositions = [];
  for (let i=0;i<d.length;i++) if (vowels.has(d[i])) vowelPositions.push(i);
  if (vowelPositions.length < 3) {
    // fallback: paroxytone if possible
    if (vowelPositions.length >= 2) return applyAccentAtVowelIndex(clean, vowelPositions[vowelPositions.length-2], COMBINING.acute);
    return applyFinalAccent(clean, 'acute');
  }
  const target = vowelPositions[vowelPositions.length-3];
  return applyAccentAtVowelIndex(clean, target, COMBINING.acute);
}

function applyAccentAtVowelIndex(word, nfdIndex, mark){
  const clean = stripAccents(word);
  const d = nfd(clean);
  let out = "";
  for (let i=0;i<d.length;i++){
    out += d[i];
    if (i === nfdIndex) out += mark;
  }
  return nfc(out);
}

// --- Rule heuristics inspired by the passage ---
const EXCEPTIONS = new Map([
  ["πελανος", {type:"oxytone", note:"Noted exception: πελανός."}],
  ["ουρανος", {type:"oxytone", note:"Noted exception: οὐρανός (also ὠρανός/ὀρανός variants mentioned)."}],
  ["χαυνος", {type:"barytone", note:"Herodian mentions Χαῦνος (ethnic) as barytone (grave in running text)."}],
  ["πυραυνος", {type:"proparoxytone", note:"Herodian: πύραυνος is proparoxytone."}],
  ["λουγδουνος", {type:"proparoxytone", note:"Herodian: Λούγδουνος is proparoxytone."}],
]);

function endsWithAny(s, arr){ return arr.some(x => s.endsWith(x)); }

function analyzeWord(input){
  const raw = (input || "").trim();
  if (!raw) return {suggested:"—", rule:"Type a word above."};

  const base = stripAccents(raw);
  const key = stripAllDiacritics(base).toLowerCase();

  // Exceptions first
  if (EXCEPTIONS.has(key)){
    const ex = EXCEPTIONS.get(key);
    let suggested = base;
    if (ex.type === "oxytone") suggested = applyFinalAccent(base, 'acute');
    if (ex.type === "barytone") suggested = applyFinalAccent(base, 'grave');
    if (ex.type === "proparoxytone") suggested = applyProparoxytone(base);
    return {suggested, rule: ex.note};
  }

  // -ανος rule (very simplified)
  if (key.endsWith("ανος") || key.endsWith("anos")){
    // look at letter before alpha in -ανος: ...Xανος
    const plain = stripAllDiacritics(base);
    const idx = plain.toLowerCase().lastIndexOf("ανος");
    const beforeA = idx > 0 ? plain[idx-1].toLowerCase() : "";

    // If before α is δ/ε/υ, do NOT apply proparoxytone by this toy.
    if (["δ","ε","υ"].includes(beforeA)){
      const suggested = applyFinalAccent(base, 'acute');
      return {
        suggested,
        rule: "Toy rule: -ανος with δ/ε/υ right before α → not the proparoxytone pattern here; defaulting to oxytone (acute on last)."
      };
    }

    const suggested = applyProparoxytone(base);
    return {
      suggested,
      rule: "Toy rule: -ανος (short α) often proparoxytone (e.g. στέφανος, κλίβανος, λίβανος)."
    };
  }

  // -νος with diphthong in penult: look for αυ/ευ/ου/ηυ before final -νος
  if (key.endsWith("νος") || key.endsWith("nos")){
    const plain = stripAllDiacritics(base).toLowerCase();
    // crude: check for diphthong immediately before final νoς: ...(αυ|ευ|ου|ηυ)νος
    if (/(αυ|ευ|ου|ηυ)νος$/.test(plain)){
      const suggested = applyFinalAccent(base, 'acute');
      return {
        suggested,
        rule: "Toy rule: -νος with a diphthong in the penult (…αυ/ευ/ου/ηυ-νος) → oxytone (acute on last), like καυνός, κρουνός, βουνός, κεραυνός."
      };
    }
  }

  // Default: keep as-is but add a gentle guess: paroxytone if possible
  const clean = stripAccents(raw);
  const d = nfd(clean);
  const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);
  const vowelPositions = [];
  for (let i=0;i<d.length;i++) if (vowels.has(d[i])) vowelPositions.push(i);
  let suggested = clean;
  if (vowelPositions.length >= 2) suggested = applyAccentAtVowelIndex(clean, vowelPositions[vowelPositions.length-2], COMBINING.acute);
  else suggested = applyFinalAccent(clean, 'acute');

  return {
    suggested,
    rule: "No specific match; defaulting to a simple paroxytone-ish guess (for play)."
  };
}

// --- UI wiring ---
const examples = [
  "καυνος",
  "Καυνός",
  "κρουνός",
  "βουνός",
  "κεραυνος",
  "Χαῦνος",
  "πυραυνος",
  "Λούγδουνος",
  "στεφανος",
  "κλίβανος",
  "λίβανος",
  "πελανός",
  "οὐρανός",
  "Σικανός",
  "κοίρανος",
  "Κάντανος",
  "Ἴτανος",
];

function renderChips(){
  const box = $("#chips");
  box.innerHTML = "";
  examples.forEach(w => {
    const d = document.createElement('div');
    d.className = 'chip';
    d.textContent = w;
    d.title = 'Click to load';
    d.addEventListener('click', () => {
      $("#inp").value = w;
      $("#inp").focus();
    });
    box.appendChild(d);
  });
}

function update(){
  const {suggested, rule} = analyzeWord($("#inp").value);
  $("#out").textContent = suggested;
  $("#rule").textContent = rule;
}

$("#analyze").addEventListener('click', update);
$("#inp").addEventListener('keydown', (e) => {
  if (e.key === 'Enter') update();
});

$("#random").addEventListener('click', () => {
  const w = examples[Math.floor(Math.random()*examples.length)];
  $("#inp").value = w;
  update();
});

$("#clear").addEventListener('click', () => {
  $("#inp").value = "";
  $("#out").textContent = "—";
  $("#rule").textContent = "—";
  $("#inp").focus();
});

$("#grave").addEventListener('click', () => {
  const v = $("#out").textContent;
  if (v && v !== "—") $("#out").textContent = applyFinalAccent(v, 'grave');
});

$("#acute").addEventListener('click', () => {
  const v = $("#out").textContent;
  if (v && v !== "—") $("#out").textContent = applyFinalAccent(v, 'acute');
});

$("#strip").addEventListener('click', () => {
  const v = $("#inp").value;
  if (!v) return;
  $("#inp").value = stripAccents(v);
  update();
});

renderChips();
update();

