const $ = (sel, root=document) => root.querySelector(sel);
const $$ = (sel, root=document) => Array.from(root.querySelectorAll(sel));

const samples = [
  "σφεδανός",
  "Ἀπιδανός",
  "Ῥοδανός",
  "Ἠριδανός",
  "Ἐδδανός",
  "Δάρδανος",
  "Ἰάρδανος",
  "ὠκεανός",
  "πυανός",
  "κυανός",
  "στεγανός πιθανός ἱκανός ὀρφανός ἀγανός τραγανός",
  "Ἀσιανός Παριανός Βοσποριανός Ταυριανός Σκορπιανός",
  "Ἱσπανός Γερμανός Βρεττανός Ἀφρικανός Ὑρκανός"
];

// --- Greek helpers ---
const COMBINING = /[\u0300-\u036f]/g;
function nfd(s){ return s.normalize('NFD'); }
function stripDiacritics(s){ return nfd(s).replace(COMBINING,'').normalize('NFC'); }

// crude vowel set (polytonic + plain)
const VOWELS = new Set([...'αεηιουωΑΕΗΙΟΥΩάέήίόύώΆΈΉΊΌΎΏϊΐϋΰΪΫᾳᾴᾲᾷᾀᾁᾂᾃᾄᾅᾆᾇᾈᾉᾊᾋᾌᾍᾎᾏᾶᾷᾴᾲᾱᾰᾹᾸᾱᾰ'.split('')]);
function isVowel(ch){ return VOWELS.has(ch) || VOWELS.has(stripDiacritics(ch)); }

function tokenizeGreek(text){
  // keep Greek-ish tokens; split on spaces/punct but keep apostrophes inside
  const cleaned = text.replace(/[“”"\(\)\[\]{}<>]/g,' ');
  const parts = cleaned.split(/[^\p{L}\p{M}᾽'’]+/u).filter(Boolean);
  return parts;
}

function syllableCount(word){
  const base = stripDiacritics(word);
  let count = 0;
  for (let i=0;i<base.length;i++){
    const ch = base[i];
    if (isVowel(ch)){
      // naive diphthong handling: αι ει οι υι αυ ευ ου ηυ
      const next = base[i+1] || '';
      const pair = (ch+next).toLowerCase();
      if (["αι","ει","οι","υι","αυ","ευ","ου","ηυ"].includes(pair)){
        count++; i++; continue;
      }
      count++;
    }
  }
  return count;
}

function endsWithAnos(word){
  const base = stripDiacritics(word).toLowerCase();
  return base.endsWith('ανος');
}

function endsWithIanos(word){
  const base = stripDiacritics(word).toLowerCase();
  return base.endsWith('ιανος');
}

function applyAcuteOnLastVowel(word){
  // Put tonos on last vowel of the word (modern acute). Works best on unaccented input.
  const chars = Array.from(stripDiacritics(word));
  const vowelIdx = [];
  for (let i=0;i<chars.length;i++) if (isVowel(chars[i])) vowelIdx.push(i);
  if (!vowelIdx.length) return stripDiacritics(word);
  const i = vowelIdx[vowelIdx.length-1];
  const map = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };
  chars[i] = map[chars[i]] || chars[i];
  return chars.join('');
}

function highlightRulesInToken(tok){
  // highlight sequences: ρδ, εα, υα (ignoring diacritics)
  const raw = tok;
  const base = stripDiacritics(tok);
  // build mapping from base indices to raw indices (approx by NFD length)
  // We'll do a simple per-character alignment by stripping combining marks.
  const rawN = nfd(raw);
  const rawChars = Array.from(rawN);
  const rawBase = rawChars.map(ch => ch.replace(COMBINING,'')).join('');

  function markPair(pair, cls){
    const low = rawBase.toLowerCase();
    let out = '';
    let i=0;
    while (i < rawChars.length){
      // find next base index corresponding to raw index i
      // compute base index by counting non-combining chars up to i
      let baseIndex = 0;
      for (let k=0;k<i;k++) if (!COMBINING.test(rawChars[k])) baseIndex++;
      const slice = low.slice(baseIndex, baseIndex+2);
      if (slice === pair){
        // wrap the next two base letters (including their combining marks)
        // collect raw segment for first base letter
        let seg1 = rawChars[i];
        let j=i+1;
        while (j<rawChars.length && COMBINING.test(rawChars[j])){ seg1 += rawChars[j]; j++; }
        // second base letter
        let seg2 = rawChars[j] || '';
        let k=j+1;
        while (k<rawChars.length && COMBINING.test(rawChars[k])){ seg2 += rawChars[k]; k++; }
        out += `<span class="${cls}">${seg1}${seg2}</span>`;
        i = k;
      } else {
        out += rawChars[i];
        i++;
      }
    }
    return out.normalize('NFC');
  }

  let out = raw;
  // apply in order; use NFD-safe wrapper by operating on raw each time
  out = markPair('ρδ','hit');
  // markPair returns full string but built from rawChars; for simplicity, redo from original for each pair is messy.
  // We'll instead do a simpler approach: sequentially replace on base with placeholders.
  // Fallback: if above produced no tags, do a simpler base-level highlight.
  if (!out.includes('hit')){
    const b = stripDiacritics(raw);
    const simple = b
      .replace(/ρδ/gi, m => `<span class="hit">${m}</span>`)
      .replace(/εα/gi, m => `<span class="hit2">${m}</span>`)
      .replace(/υα/gi, m => `<span class="hit2">${m}</span>`);
    return simple;
  }
  // Now also highlight εα and υα on the already-tagged string (simple, may miss diacritics but ok)
  out = out
    .replace(/εα/gi, m => `<span class="hit2">${m}</span>`)
    .replace(/υα/gi, m => `<span class="hit2">${m}</span>`);
  return out;
}

function analyzeWord(word){
  const base = stripDiacritics(word);
  const lower = base.toLowerCase();
  const syl = syllableCount(word);

  const hits = {
    rd: /ρδ/i.test(lower),
    ea: /εα/i.test(lower),
    ya: /υα/i.test(lower)
  };

  const isAnos = endsWithAnos(word);
  const isIanos = endsWithIanos(word);

  let guess = null;
  let rationale = [];

  if (isAnos){
    // Herodian: trisyllables in -ανος are oxytone; many -ιανός etc. also oxytone.
    if (syl === 3){
      guess = applyAcuteOnLastVowel(base);
      rationale.push("Ends in -ανος and looks trisyllabic → suggest oxytone (acute on last). (Herodian’s pattern)");
    } else {
      guess = applyAcuteOnLastVowel(base);
      rationale.push("Ends in -ανος → often oxytone in Herodian’s lists; syllable-count here is not 3, so this is a playful guess.");
    }
    if (isIanos) rationale.push("Subtype -ιανός (often ethnic/place-name) → also commonly oxytone in the passage’s examples.");
  }

  if (hits.rd) rationale.push("Contains ρ before δ (Herodian notes an exception/rule around this cluster: Δάρδανος)." );
  if (hits.ea) rationale.push("Contains ε before α (passage mentions ε before α with ὠκεανός)." );
  if (hits.ya) rationale.push("Contains υ before α (passage mentions πυανός, κυανός)." );

  return {
    word,
    base,
    syllables: syl,
    isAnos,
    isIanos,
    hits,
    guess,
    rationale
  };
}

function renderTokens(text){
  const tokens = tokenizeGreek(text);
  const mark = $('#markRules').checked;
  const strip = $('#strip').checked;

  const box = $('#tokens');
  box.innerHTML = '';

  if (!tokens.length){
    box.innerHTML = '<div class="muted">No tokens found yet.</div>';
    return;
  }

  for (const t of tokens){
    const shown = strip ? stripDiacritics(t) : t;
    const btn = document.createElement('button');
    btn.className = 'tok';
    btn.type = 'button';
    btn.innerHTML = mark ? highlightRulesInToken(shown) : escapeHtml(shown);
    btn.addEventListener('click', () => showAnalysis(t));
    box.appendChild(btn);
  }
}

function showAnalysis(word){
  const strip = $('#strip').checked;
  const w = strip ? stripDiacritics(word) : word;
  const a = analyzeWord(w);

  const badges = [];
  if (a.isAnos) badges.push('<span class="badge good">-ανος</span>');
  if (a.isIanos) badges.push('<span class="badge good">-ιανός</span>');
  if (a.hits.rd) badges.push('<span class="badge warn">ρδ</span>');
  if (a.hits.ea) badges.push('<span class="badge warn">εα</span>');
  if (a.hits.ya) badges.push('<span class="badge warn">υα</span>');
  if (!badges.length) badges.push('<span class="badge">no special pattern spotted</span>');

  const guessLine = a.guess
    ? `<div class="kv"><div class="k">Toy guess</div><div class="v"><code>${escapeHtml(a.guess)}</code></div></div>`
    : `<div class="kv"><div class="k">Toy guess</div><div class="v muted">(Only guesses for -ανος words.)</div></div>`;

  const why = a.rationale.length
    ? `<div class="kv"><div class="k">Why</div><div class="v">${a.rationale.map(x=>`<div>• ${escapeHtml(x)}</div>`).join('')}</div></div>`
    : `<div class="kv"><div class="k">Why</div><div class="v muted">No rule triggered.</div></div>`;

  $('#analysis').innerHTML = `
    <div style="font-size:20px;margin-bottom:6px">${escapeHtml(a.word)} ${badges.join(' ')}</div>
    <div class="kv">
      <div class="k">Stripped</div><div class="v"><code>${escapeHtml(a.base)}</code></div>
      <div class="k">Syllables (toy)</div><div class="v">${a.syllables}</div>
      <div class="k">Ends with</div><div class="v">${a.isIanos ? '-ιανος' : (a.isAnos ? '-ανος' : '—')}</div>
    </div>
    ${guessLine}
    <hr/>
    ${why}
  `;

  // also sync guesser input
  $('#word').value = a.base;
}

function guessFromGuesser(){
  const w = $('#word').value.trim();
  if (!w){ $('#guessOut').textContent = 'Type a word first.'; return; }
  const a = analyzeWord(w);
  if (!a.isAnos){
    $('#guessOut').innerHTML = `Not an <b>-ανος</b> word (after stripping accents). Try one like <code>στεγανος</code> or <code>Ἀσιανος</code>.`;
    return;
  }
  const g = a.guess || applyAcuteOnLastVowel(a.base);
  $('#guessOut').innerHTML = `Guessed form: <code>${escapeHtml(g)}</code><div class="small" style="margin-top:6px">Tip: paste unaccented Greek to see the toy add an acute on the last vowel.</div>`;
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function randomSample(){
  const s = samples[Math.floor(Math.random()*samples.length)];
  $('#inp').value = s;
  renderTokens(s);
  const toks = tokenizeGreek(s);
  if (toks[0]) showAnalysis(toks[0]);
}

function analyzeInput(){
  const t = $('#inp').value.trim();
  renderTokens(t);
  const toks = tokenizeGreek(t);
  if (toks[0]) showAnalysis(toks[0]);
  else $('#analysis').innerHTML = '<div class="muted">No tokens found. Try a Greek word.</div>';
}

function clearAll(){
  $('#inp').value='';
  $('#word').value='';
  $('#tokens').innerHTML='<div class="muted">No tokens found yet.</div>';
  $('#analysis').innerHTML='<div class="muted">Type something and press <b>Analyze</b>.</div>';
  $('#guessOut').textContent='';
}

async function copyGuess(){
  const out = $('#guessOut').innerText;
  const m = out.match(/Guessed form:\s*(.+)/);
  const g = m ? m[1].trim() : '';
  const guess = (g && !g.includes('Type a word')) ? g : '';
  const val = guess || ($('#guessOut').textContent || '').trim();
  const toCopy = ($('#guessOut').querySelector('code')?.textContent) || '';
  if (!toCopy){
    $('#guessOut').textContent = 'Nothing to copy yet.';
    return;
  }
  try{
    await navigator.clipboard.writeText(toCopy);
    $('#guessOut').innerHTML = `Copied: <code>${escapeHtml(toCopy)}</code>`;
  } catch(e){
    // offline fallback: select in input
    $('#word').value = toCopy;
    $('#word').focus();
    $('#word').select();
    $('#guessOut').innerHTML = `Clipboard blocked. Selected the text in the input—press Ctrl/Cmd+C.`;
  }
}

// wire up
$('#btnAnalyze').addEventListener('click', analyzeInput);
$('#btnRandom').addEventListener('click', randomSample);
$('#btnClear').addEventListener('click', clearAll);
$('#btnGuess').addEventListener('click', guessFromGuesser);
$('#btnCopy').addEventListener('click', copyGuess);
$('#strip').addEventListener('change', () => { renderTokens($('#inp').value); });
$('#markRules').addEventListener('change', () => { renderTokens($('#inp').value); });
$('#inp').addEventListener('keydown', (e)=>{ if(e.key==='Enter') analyzeInput(); });
$('#word').addEventListener('keydown', (e)=>{ if(e.key==='Enter') guessFromGuesser(); });

// init
renderTokens('');
$('#guessOut').textContent = '';
randomSample();

