mark{background:rgba(251,191,36,.18); color:var(--text); padding:0 4px; border-radius:6px}

passages.gadget_js:
const $ = (s)=>document.querySelector(s);

const samples = [
  {g:"Ὠλενος", note:"-ενος (>2 syll.) → proparoxytone"},
  {g:"ωλενος", note:"type unaccented"},
  {g:"ἔβενος", note:"already accented"},
  {g:"παρθενος", note:"exception → παρθένος"},
  {g:"Στησαμενος", note:"-μενος participle → oxytone"},
  {g:"Ακεσαμενος", note:"-μενος participle → oxytone"},
  {g:"Τήμενος", note:"not -ενος/-μενος"},
  {g:"Ἀσπουργιανοί", note:"ethnic plural (toy won’t fully handle)"}
];

function stripDiacritics(str){
  // Remove combining marks; keep base Greek letters.
  return str.normalize('NFD').replace(/[\u0300-\u036f\u1dc0-\u1dff\u20d0-\u20ff\ufe20-\ufe2f]/g,'').normalize('NFC');
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code>=0x0370 && code<=0x03FF) || (code>=0x1F00 && code<=0x1FFF);
}

function tokenizeWords(s){
  // Keep Greek word chunks; ignore punctuation.
  const out=[];
  let cur="";
  for(const ch of s){
    if(isGreekLetter(ch) || ch==="ʼ" || ch==="᾽") cur+=ch;
    else {
      if(cur) out.push(cur);
      cur="";
    }
  }
  if(cur) out.push(cur);
  return out;
}

const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω",
  "ά","έ","ή","ί","ό","ύ","ώ","Ά","Έ","Ή","Ί","Ό","Ύ","Ώ",
  "ϊ","ϋ","ΐ","ΰ","Ϊ","Ϋ"]);

function roughSyllables(word){
  // Very rough: count vowel nuclei in stripped word.
  const w = stripDiacritics(word);
  let nuclei=[];
  let i=0;
  while(i<w.length){
    const ch=w[i];
    if(vowels.has(ch)){
      // treat common diphthongs as one nucleus
      const next=w[i+1]||"";
      const pair=(ch+next).toLowerCase();
      if(["αι","ει","οι","υι","αυ","ευ","ου","ηυ"].includes(pair)){
        nuclei.push(w.slice(i,i+2));
        i+=2; continue;
      }
      nuclei.push(ch);
    }
    i++;
  }
  return nuclei;
}

function addAcuteToVowel(v){
  const map={
    "α":"ά","ε":"έ","η":"ή","ι":"ί","ο":"ό","υ":"ύ","ω":"ώ",
    "Α":"Ά","Ε":"Έ","Η":"Ή","Ι":"Ί","Ο":"Ό","Υ":"Ύ","Ω":"Ώ",
    "ϊ":"ΐ","ϋ":"ΰ","Ι":"Ί","Υ":"Ύ","ι":"ί","υ":"ύ"
  };
  return map[v]||v;
}

function accentOnSyllable(word, targetFromEnd){
  // targetFromEnd: 1=ultima, 2=penult, 3=antepenult
  const original = word;
  const w = stripDiacritics(word);
  // find vowel nuclei positions (start index, length)
  let nuclei=[];
  for(let i=0;i<w.length;i++){
    const ch=w[i];
    if(vowels.has(ch)){
      const next=w[i+1]||"";
      const pair=(ch+next).toLowerCase();
      if(["αι","ει","οι","υι","αυ","ευ","ου","ηυ"].includes(pair)){
        nuclei.push({i, len:2});
        i++; continue;
      }
      nuclei.push({i, len:1});
    }
  }
  if(nuclei.length===0) return original;
  const idx = nuclei.length - targetFromEnd;
  if(idx<0) return original;
  const n = nuclei[idx];
  // accent first vowel of nucleus
  const chars = Array.from(w);
  chars[n.i] = addAcuteToVowel(chars[n.i]);
  return chars.join("");
}

function analyzeWord(word, opts){
  const raw = word.trim();
  if(!raw) return null;
  const base = opts.strip ? stripDiacritics(raw) : raw;

  // optionally handle plural -οι/-αι by stripping to base for rule detection
  let detect = stripDiacritics(base);
  let pluralSuffix = "";
  if(opts.poly){
    const low = detect.toLowerCase();
    if(low.endsWith("οι") || low.endsWith("αι")){
      pluralSuffix = detect.slice(-2);
      detect = detect.slice(0,-2);
    }
  }

  const syl = roughSyllables(detect);
  const sylCount = syl.length;

  const low = detect.toLowerCase();
  let rule = "No rule matched; leaving as-is.";
  let suggested = base;

  // Exception: παρθένος
  if(low === "παρθενος"){
    rule = "Exception noted by Herodian: παρθένος is paroxytone (accent on penult).";
    suggested = accentOnSyllable(detect, 2) + pluralSuffix;
    return {suggested, rule, syl};
  }

  // -μενος participles: oxytone
  if(low.endsWith("μενος")){
    rule = "Looks like -μενος (participial type): suggest oxytone (accent on ultima).";
    suggested = accentOnSyllable(detect, 1) + pluralSuffix;
    return {suggested, rule, syl};
  }

  // -ενος non-participles: if >2 syllables, proparoxytone
  if(low.endsWith("ενος")){
    if(sylCount>2){
      rule = "Looks like -ενος (non-participial): if >2 syllables, suggest proparoxytone (antepenult).";
      suggested = accentOnSyllable(detect, 3) + pluralSuffix;
    } else {
      rule = "Looks like -ενος but only 2 syllables: toy does not force a rule (often penult/ultima depends).";
      suggested = detect + pluralSuffix;
    }
    return {suggested, rule, syl};
  }

  // fallback: if 3+ syllables, offer a playful antepenult accent
  if(sylCount>=3){
    rule = "Fallback: 3+ syllables → playful antepenult accent (not a Herodian rule).";
    suggested = accentOnSyllable(detect, 3) + pluralSuffix;
  } else if(sylCount===2){
    rule = "Fallback: 2 syllables → playful penult accent.";
    suggested = accentOnSyllable(detect, 2) + pluralSuffix;
  } else {
    rule = "Fallback: 1 syllable → playful ultima accent.";
    suggested = accentOnSyllable(detect, 1) + pluralSuffix;
  }

  return {suggested, rule, syl};
}

function renderSyllables(syl){
  if(!syl || !syl.length) return "—";
  return syl.map(x=>`<span class="badge">${x}</span>`).join(" ");
}

function run(){
  const inp = $('#inp').value;
  const opts = {strip: $('#strip').checked, poly: $('#poly').checked};
  const words = tokenizeWords(inp);
  if(words.length===0){
    $('#out').textContent = '—';
    $('#rule').textContent = '—';
    $('#syll').innerHTML = '—';
    return;
  }

  // If multiple words, accent each separately and join with spaces.
  let rules=[];
  let syllInfo=[];
  let outWords=[];
  for(const w of words){
    const a = analyzeWord(w, opts);
    if(!a){ outWords.push(w); continue; }
    outWords.push(a.suggested);
    rules.push(`• ${w} → ${a.rule}`);
    syllInfo.push(`${w}: ${a.syl.join("-") || "?"}`);
  }

  $('#out').textContent = outWords.join(' ');
  $('#rule').textContent = rules.join('\n');
  $('#syll').innerHTML = renderSyllables(roughSyllables(stripDiacritics(words[0])));
}

function buildChips(){
  const box = $('#chips');
  box.innerHTML='';
  for(const s of samples){
    const d=document.createElement('div');
    d.className='chip gr';
    d.textContent=s.g;
    d.title=s.note;
    d.addEventListener('click', ()=>{ $('#inp').value=s.g; run(); $('#inp').focus(); });
    box.appendChild(d);
  }
}

$('#btn').addEventListener('click', run);
$('#btnClear').addEventListener('click', ()=>{ $('#inp').value=''; run(); $('#inp').focus(); });
$('#inp').addEventListener('keydown', (e)=>{ if(e.key==='Enter'){ e.preventDefault(); run(); }});
$('#strip').addEventListener('change', run);
$('#poly').addEventListener('change', run);

buildChips();
run();

