const $ = (sel) => document.querySelector(sel);

// --- Greek accent helpers (toy-level) ---
const COMBINING = {
  acute: "\u0301",
  grave: "\u0300",
  circumflex: "\u0342",
  diaeresis: "\u0308",
  smooth: "\u0313",
  rough: "\u0314",
  iotaSub: "\u0345"
};

const VOWELS = new Set(["α","ε","η","ι","ο","υ","ω","ά","έ","ή","ί","ό","ύ","ώ","ϊ","ΐ","ϋ","ΰ","ᾳ","ῃ","ῳ","ἀ","ἁ","ἂ","ἃ","ἄ","ἅ","ἆ","ἇ","ἐ","ἑ","ἒ","ἓ","ἔ","ἕ","ἠ","ἡ","ἢ","ἣ","ἤ","ἥ","ἦ","ἧ","ἰ","ἱ","ἲ","ἳ","ἴ","ἵ","ἶ","ἷ","ὀ","ὁ","ὂ","ὃ","ὄ","ὅ","ὐ","ὑ","ὒ","ὓ","ὔ","ὕ","ὖ","ὗ","ὠ","ὡ","ὢ","ὣ","ὤ","ὥ","ὦ","ὧ"]);

function stripAccents(s){
  // Remove combining marks and precomposed tonos by NFD + filter
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code >= 0x0370 && code <= 0x03FF) || (code >= 0x1F00 && code <= 0x1FFF);
}

function tokenizeGreekLetters(s){
  // Keep only Greek letters and combining marks attached; preserve spaces/punct separately.
  // For our toy, we accent only the last Greek "word".
  return s;
}

function lastGreekWord(s){
  // Return {prefix, word, suffix}
  // Find last run of Greek letters (incl. combining marks) in the string.
  const nfd = s.normalize('NFD');
  // We'll treat Greek base letters as those in Greek blocks; combining marks allowed inside.
  let end = -1;
  for(let i=nfd.length-1;i>=0;i--){
    const ch = nfd[i];
    if(/[\u0300-\u036f]/.test(ch)) continue;
    if(isGreekLetter(ch)) { end = i; break; }
    if(end !== -1) break;
  }
  if(end === -1) return {prefix:s, word:"", suffix:""};

  // expand to include combining marks after end
  let end2 = end+1;
  while(end2 < nfd.length && /[\u0300-\u036f]/.test(nfd[end2])) end2++;

  // find start
  let start = end;
  while(start-1 >= 0){
    const ch = nfd[start-1];
    if(/[\u0300-\u036f]/.test(ch)) { start--; continue; }
    if(isGreekLetter(ch)) { start--; continue; }
    break;
  }
  // include any combining marks right after start? (already included)

  const prefix = nfd.slice(0,start).normalize('NFC');
  const word = nfd.slice(start,end2).normalize('NFC');
  const suffix = nfd.slice(end2).normalize('NFC');
  return {prefix, word, suffix};
}

function countSyllables(word){
  // Very rough: count vowel groups in stripped word.
  const w = stripAccents(word).toLowerCase();
  const vowels = "αεηιουω";
  let count = 0;
  let prevV = false;
  for(const ch of w){
    const isV = vowels.includes(ch);
    if(isV && !prevV) count++;
    prevV = isV;
  }
  return count;
}

function vowelPositionsNFD(word){
  // Return indices (in NFD string) of vowel base letters.
  const nfd = word.normalize('NFD');
  const base = nfd.replace(/[\u0300-\u036f]/g,'');
  // Map base indices to nfd indices
  const map = [];
  let bi = 0;
  for(let i=0;i<nfd.length;i++){
    if(/[\u0300-\u036f]/.test(nfd[i])) continue;
    map[bi++] = i;
  }
  const vowels = "αεηιουωΑΕΗΙΟΥΩ";
  const pos = [];
  for(let j=0;j<base.length;j++){
    if(vowels.includes(base[j])) pos.push(map[j]);
  }
  return {nfd, pos};
}

function addAcuteToVowel(word, vowelIndexFromEnd){
  // Add combining acute to the Nth vowel from the end (1=ultima).
  const {nfd, pos} = vowelPositionsNFD(word);
  if(pos.length === 0) return word;
  const target = pos[Math.max(0, pos.length - vowelIndexFromEnd)];

  // Remove existing accent marks (acute/grave/circumflex) from the whole word first.
  let cleaned = nfd.replace(/[\u0300\u0301\u0342]/g,'');

  // Recompute positions after cleaning
  const vp = vowelPositionsNFD(cleaned.normalize('NFC'));
  let cleanedNFD = vp.nfd;
  let cleanedPos = vp.pos;
  const t = cleanedPos[Math.max(0, cleanedPos.length - vowelIndexFromEnd)];

  // Insert acute after the vowel base letter and after any breathing/diaeresis already present.
  // Find insertion point: right after the base letter and any following combining marks.
  let ins = t + 1;
  while(ins < cleanedNFD.length && /[\u0300-\u036f]/.test(cleanedNFD[ins])) ins++;
  const out = cleanedNFD.slice(0, ins) + COMBINING.acute + cleanedNFD.slice(ins);
  return out.normalize('NFC');
}

function looksLikeCompound(w){
  const s = stripAccents(w).toLowerCase();
  const prefixes = ["παν", "προσ", "δυσ", "ευ", "κακο", "α", "αν"]; // toy
  const numerals = ["δι", "τρι", "τετρα", "πεντα", "εξ", "επτα"]; // toy
  return prefixes.some(p => s.startsWith(p) && s.length > p.length+3) || numerals.some(p => s.startsWith(p) && s.length > p.length+3);
}

function endsWithHenos(w){
  const s = stripAccents(w).toLowerCase();
  return s.endsWith("ηνος") || s.endsWith("ηνου") || s.endsWith("ηνον") || s.endsWith("ηνοι") || s.endsWith("ηνοις") || s.endsWith("ηνων");
}

function accentToy(input, mode, dial){
  const parts = lastGreekWord(input);
  if(!parts.word) return {out: input, explain: "No Greek word detected at the end of the input."};

  const originalWord = parts.word;
  const bare = stripAccents(originalWord);
  const syl = countSyllables(bare);
  const compound = looksLikeCompound(bare);
  const henos = endsWithHenos(bare);

  let target = originalWord;
  let explainBits = [];

  if(mode === "none"){
    target = stripAccents(originalWord);
    explainBits.push("Removed accents (NFD stripping). ");
  } else if(mode === "oxytone"){
    target = addAcuteToVowel(originalWord, 1);
    explainBits.push("Forced oxytone: accent on ultima.");
  } else if(mode === "proparox"){
    target = addAcuteToVowel(originalWord, 3);
    explainBits.push("Forced proparoxytone: accent on antepenult (if possible). ");
  } else {
    // auto
    if(henos && syl > 2 && !compound){
      target = addAcuteToVowel(originalWord, 1);
      explainBits.push("Auto: looks like a non-compound >2-syllable word in -ηνος → toy rule chooses oxytone (…ηνός). ");
    } else if(henos && syl <= 2){
      target = addAcuteToVowel(originalWord, 1);
      explainBits.push("Auto: short -ηνος word → default oxytone in this toy.");
    } else {
      // fallback: accent ultima
      target = addAcuteToVowel(originalWord, 1);
      explainBits.push("Auto: not clearly in -ηνος (or looks compound) → fallback oxytone.");
    }
  }

  // Add exception flags
  if(dial === "syr") explainBits.push(" Flag: Herodian mentions Syracusan ‘imitative’ formations as a special case.");
  if(dial === "gen") explainBits.push(" Flag: ‘referred back from a genitive’ (e.g. Τροίζηνος from Τροιζήνοιο). ");
  if(dial === "fem") explainBits.push(" Flag: ‘gender-change’ derivatives from feminine in -η (e.g. Μυκήνη → Μύκηνος). ");

  // Diagnostics badges
  const badges = [];
  badges.push(`<span class="badge ${henos?"ok":""}">ends -ηνος? ${henos?"yes":"no"}</span>`);
  badges.push(`<span class="badge ${syl>2?"ok":""}">syllables≈${syl}</span>`);
  badges.push(`<span class="badge ${compound?"warn":""}">compound? ${compound?"maybe":"no"}</span>`);

  const explain = badges.join(" ") + `<div style="margin-top:8px">${explainBits.join("")}</div>`;
  return {out: parts.prefix + target + parts.suffix, explain};
}

// --- Ethnic maker ---
function normalizeStem(stem){
  return stem.trim().replace(/\s+/g,'');
}

function endsWithVowel(st){
  const s = stripAccents(st).toLowerCase();
  return /[αεηιουω]$/.test(s);
}

function makeEthnic(stem, joinMode){
  let st = normalizeStem(stem);
  if(!st) return {word:"", note:"Type a stem first."};

  // Remove trailing hyphen-like characters
  st = st.replace(/[\-–—·•]+$/g,'');

  let base = st;
  let suffix = "ηνός";

  if(joinMode === "ηνός_i"){
    // Insert ι if ends with consonant cluster (toy): if last two are consonants.
    const s = stripAccents(base).toLowerCase();
    const last2 = s.slice(-2);
    const vowels = "αεηιουω";
    const isCluster = last2.length===2 && !vowels.includes(last2[0]) && !vowels.includes(last2[1]);
    if(isCluster) base = base + "ι";
  }

  if(joinMode === "ηνός_k"){
    const s = stripAccents(base).toLowerCase();
    if(/[κγχ]$/.test(s)) suffix = "κηνός";
  }

  let candidate = base + suffix;
  // Accent oxytone on the whole candidate
  candidate = addAcuteToVowel(candidate, 1);

  const note = `Toy ethnic: stem + -ηνός (often oxytone in Herodian’s list).`;
  return {word:candidate, note};
}

// --- UI wiring ---
const examples = [
  "Δαμασκηνος",
  "Περγαμηνος",
  "Λαμψακηνος",
  "Ἰσμηνος",
  "Αβυδηνος",
  "Τυρσηνος",
  "πανσεληνος",
  "προσεληνος",
  "δυστηνος",
  "διμηνος",
  "Μυκηνη",
  "Τροιζηνος"
];

function setHTML(id, html){ $(id).innerHTML = html; }
function setText(id, txt){ $(id).textContent = txt; }

function runAccent(){
  const input = $("#inp").value;
  const mode = $("#mode").value;
  const dial = $("#dial").value;
  const res = accentToy(input, mode, dial);
  setText("#outWord", res.out || "—");
  setHTML("#outExplain", res.explain);
}

$("#go").addEventListener("click", runAccent);
$("#inp").addEventListener("keydown", (e)=>{ if(e.key==="Enter") runAccent(); });
$("#mode").addEventListener("change", runAccent);
$("#dial").addEventListener("change", runAccent);

$("#rand").addEventListener("click", ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $("#inp").value = ex;
  runAccent();
});

$("#clear").addEventListener("click", ()=>{
  $("#inp").value = "";
  setText("#outWord","—");
  setHTML("#outExplain","Type something ending in <span class=\"greek\">-ηνος</span> / <span class=\"greek\">-ηνός</span> to see the toy rule.");
});

let lastEthnic = "";
$("#make").addEventListener("click", ()=>{
  const stem = $("#stem").value;
  const join = $("#join").value;
  const res = makeEthnic(stem, join);
  lastEthnic = res.word;
  setText("#ethnic", res.word || "—");
  setText("#ethnicNote", res.note);
});

$("#swap").addEventListener("click", ()=>{
  if(!lastEthnic) return;
  $("#inp").value = lastEthnic;
  $("#mode").value = "auto";
  runAccent();
  window.scrollTo({top:0, behavior:"smooth"});
});

// Seed with a relevant example
$("#inp").value = "Δαμασκηνος";
runAccent();
$("#stem").value = "Δαμασκ";
$("#make").click();

