:root{
  --bg:#0f1220;
  --panel:#171b2e;
  --panel2:#12162a;
  --text:#e9ecff;
  --muted:#b7bddc;
  --faint:#7f87b3;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --good:#34d399;
  --warn:#fbbf24;
  --bad:#fb7185;
  --border:rgba(255,255,255,.10);
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, #1b2150 0%, var(--bg) 55%);color:var(--text);font:15px/1.35 system-ui,-apple-system,Segoe UI,Roboto,Arial,"Noto Sans",sans-serif}
.wrap{max-width:980px;margin:0 auto;padding:22px 16px 28px}
header h1{margin:0 0 6px;font-size:22px;letter-spacing:.2px}
.sub{margin:0 0 14px;color:var(--muted)}
.panel{background:linear-gradient(180deg,var(--panel),var(--panel2));border:1px solid var(--border);border-radius:14px;padding:14px 14px 12px;box-shadow:0 10px 30px rgba(0,0,0,.25)}
.panel + .panel{margin-top:14px}
.row{margin:10px 0}
.row.two{display:grid;grid-template-columns:1fr 1fr;gap:10px}
label{display:block;font-weight:650;margin:0 0 6px;color:var(--text)}
input[type=text], select{width:100%;padding:10px 11px;border-radius:10px;border:1px solid var(--border);background:rgba(255,255,255,.04);color:var(--text);outline:none}
input[type=text]:focus, select:focus{border-color:rgba(125,211,252,.55);box-shadow:0 0 0 3px rgba(125,211,252,.12)}
.hint{margin-top:6px;color:var(--faint);font-size:12.5px}
code{background:rgba(255,255,255,.06);padding:1px 6px;border-radius:8px;border:1px solid rgba(255,255,255,.08)}
.chips{display:flex;flex-wrap:wrap;gap:8px}
.chip{cursor:pointer;border:1px solid var(--border);background:rgba(255,255,255,.04);color:var(--text);padding:8px 10px;border-radius:999px;font-size:13px}
.chip[aria-pressed=true]{border-color:rgba(167,139,250,.65);box-shadow:0 0 0 3px rgba(167,139,250,.14);background:rgba(167,139,250,.12)}
.actions{display:flex;gap:10px;flex-wrap:wrap}
.actions button{cursor:pointer;border:1px solid var(--border);background:rgba(255,255,255,.06);color:var(--text);padding:9px 12px;border-radius:10px;font-weight:650}
.actions button:hover{border-color:rgba(125,211,252,.45)}
.actions button:active{transform:translateY(1px)}
.out h2{margin:0 0 10px;font-size:16px;color:var(--muted);font-weight:750}
.outGrid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.box{border:1px solid var(--border);border-radius:12px;padding:10px;background:rgba(255,255,255,.03)}
.k{color:var(--faint);font-size:12px;margin-bottom:6px}
.v{font-size:15px}
.v.big{font-size:22px;font-weight:800;letter-spacing:.2px}
.mini{margin-top:10px}
.mini summary{cursor:pointer;color:var(--accent);font-weight:700}
.examples{margin-top:10px;display:flex;flex-wrap:wrap;gap:8px}
.ex{border:1px solid var(--border);background:rgba(255,255,255,.03);padding:7px 9px;border-radius:999px;cursor:pointer;font-size:13px}
.ex:hover{border-color:rgba(125,211,252,.45)}
.fine{margin:12px 2px 0;color:var(--faint);font-size:12.5px}
@media (max-width:720px){
  .row.two{grid-template-columns:1fr}
  .outGrid{grid-template-columns:1fr}
}

