// Herodian -inos accent toy (offline, heuristic)
(function(){
  const elWord = document.getElementById('word');
  const elApply = document.getElementById('apply');
  const elRandom = document.getElementById('random');
  const elClear = document.getElementById('clear');
  const elNorm = document.getElementById('norm');
  const elAcc = document.getElementById('accented');
  const elShape = document.getElementById('shape');
  const elNotes = document.getElementById('notes');
  const elExamples = document.getElementById('examples');
  const elILen = document.getElementById('iLen');
  const elCase = document.getElementById('case');
  const chips = Array.from(document.querySelectorAll('.chip'));

  const examples = [
    {w:'ἐχῖνος', cat:'water', note:'water-creature; also proper name/place in the passage'},
    {w:'κορακῖνος', cat:'water', note:'fish-name type'},
    {w:'φοξῖνος', cat:'water', note:'fish-name type'},
    {w:'καρκίνος', cat:'water', note:'Herodian says many wrongly accent it; he prefers proparoxytone circumflex'},
    {w:'γυρῖνος', cat:'water', note:'“small frog”'},
    {w:'ἰκτῖνος', cat:'water', note:'bird-name; also proper name'},
    {w:'κάμινος', cat:'appellative', note:'appellative; barytone'},
    {w:'κύμινος', cat:'appellative', note:'appellative; barytone'},
    {w:'κυκλάμινος', cat:'appellative', note:'appellative; barytone'},
    {w:'ἐρινός', cat:'oxytone', note:'rare oxytone'},
    {w:'χαλινός', cat:'oxytone', note:'rare oxytone'},
    {w:'Φιλῖνος', cat:'proper', note:'proper name; proparoxytone circumflex'},
    {w:'Κρατῖνος', cat:'proper', note:'proper name; proparoxytone circumflex'},
    {w:'Ἐρυθῖνος', cat:'proper', note:'place/ethnic; proparoxytone circumflex'},
    {w:'Λαμητῖνος', cat:'proper', note:'place/ethnic; proparoxytone circumflex'},
    {w:'Λατῖνος', cat:'proper', note:'ethnic; proparoxytone circumflex'}
  ];

  // --- Utilities ---
  const greekMap = [
    ['th','θ'],['ph','φ'],['ch','χ'],['ps','ψ'],['ks','ξ'],
    ['a','α'],['b','β'],['g','γ'],['d','δ'],['e','ε'],['z','ζ'],['h','η'],['i','ι'],['k','κ'],['l','λ'],['m','μ'],['n','ν'],['x','χ'],['o','ο'],['p','π'],['r','ρ'],['s','σ'],['t','τ'],['u','υ'],['y','υ'],['w','ω'],
  ];

  function stripDiacritics(s){
    return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  }

  function toGreekish(s){
    // If it already contains Greek letters, keep it.
    if(/[\u0370-\u03FF\u1F00-\u1FFF]/.test(s)) return s;
    let t = s.toLowerCase().trim();
    // crude latin->greek
    for(const [src,dst] of greekMap){
      t = t.replaceAll(src,dst);
    }
    // final sigma
    t = t.replace(/σ\b/g,'ς');
    return t;
  }

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ','ϊ','ΐ','ϋ','ΰ']);

  function splitSyllablesHeuristic(word){
    // Very rough: group consecutive vowels as nucleus; everything before next nucleus attaches to previous.
    const w = word;
    const parts = [];
    let i=0;
    while(i<w.length){
      // find next vowel
      let start = i;
      while(i<w.length && !vowels.has(w[i])) i++;
      if(i>=w.length){
        if(parts.length===0) parts.push(w.slice(start));
        else parts[parts.length-1] += w.slice(start);
        break;
      }
      // onset consonants from start..i
      const onset = w.slice(start,i);
      // nucleus: one or more vowels
      let j=i;
      while(j<w.length && vowels.has(w[j])) j++;
      const nuc = w.slice(i,j);
      // attach onset to previous syllable if there is one, else start new
      if(parts.length===0) parts.push(onset + nuc);
      else parts.push(onset + nuc);
      i=j;
    }
    // Post-process: if we ended with consonants, they are already appended above.
    return parts.filter(p=>p.length>0);
  }

  function accentVowelGroup(syl, mark){
    // mark: 'acute' or 'circ'
    // Put accent on the last vowel of the syllable's vowel group.
    const base = syl.normalize('NFD');
    // find last vowel in NFD stream by scanning original NFC indices (simpler: scan NFC)
    let idx = -1;
    for(let i=syl.length-1;i>=0;i--){
      if(vowels.has(syl[i])){ idx=i; break; }
    }
    if(idx<0) return syl;
    const ch = stripDiacritics(syl[idx]);
    const acuteMap = { 'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ' };
    const circMap  = { 'α':'ᾶ','η':'ῆ','ι':'ῖ','υ':'ῦ','ω':'ῶ','ο':'ῶ','ε':'έ' };
    // Note: circumflex on ε/ο is not real; keep acute fallback.
    const rep = (mark==='circ' ? (circMap[ch]||acuteMap[ch]||syl[idx]) : (acuteMap[ch]||syl[idx]));
    return syl.slice(0,idx) + rep + syl.slice(idx+1);
  }

  function applyAccent(word, pattern){
    // pattern: 'propercirc' (antepenult circumflex), 'parox' (penult acute), 'oxy' (ultima acute), 'bary' (penult acute as a stand-in)
    const syls = splitSyllablesHeuristic(word);
    if(syls.length===0) return {out:word, syls};

    let target = 0;
    let mark = 'acute';
    if(pattern==='propercirc'){
      target = Math.max(0, syls.length-3);
      mark = 'circ';
    } else if(pattern==='parox'){
      target = Math.max(0, syls.length-2);
      mark = 'acute';
    } else if(pattern==='oxy'){
      target = syls.length-1;
      mark = 'acute';
    } else { // bary
      target = Math.max(0, syls.length-2);
      mark = 'acute';
    }

    const outSyls = syls.map((s,i)=> i===target ? accentVowelGroup(s, mark) : stripExistingAccent(s));
    return {out: outSyls.join(''), syls};
  }

  function stripExistingAccent(s){
    // remove tonos/circumflex etc.
    return stripDiacritics(s);
  }

  function normalizeInput(raw){
    let s = raw.trim();
    s = toGreekish(s);
    // keep only letters and spaces
    s = s.replace(/[^\p{L}\s]/gu,'');
    // normalize sigma at end of words
    s = s.split(/\s+/).map(w=>{
      if(!w) return w;
      w = w.replace(/σ$/,'ς');
      return w;
    }).join(' ');
    return s;
  }

  function endsWithInos(w){
    const bare = stripDiacritics(w);
    return bare.endsWith('ινος') || bare.endsWith('ινου');
  }

  function setCat(cat){
    chips.forEach(b=>b.setAttribute('aria-pressed', String(b.dataset.cat===cat)));
  }

  function getCat(){
    const on = chips.find(b=>b.getAttribute('aria-pressed')==='true');
    return on ? on.dataset.cat : 'water';
  }

  function patternFor(cat){
    if(cat==='water') return 'propercirc';
    if(cat==='proper') return 'propercirc';
    if(cat==='appellative') return 'bary';
    if(cat==='oxytone') return 'oxy';
    return 'bary';
  }

  function shapeLabel(cat){
    if(cat==='water') return 'προπερισπώμενον (toy: antepenult circumflex)';
    if(cat==='proper') return 'προπερισπώμενον (toy: antepenult circumflex)';
    if(cat==='appellative') return 'βαρύτονον (toy: not-final; uses penult acute)';
    if(cat==='oxytone') return 'ὀξύτονον (toy: ultima acute)';
    return '—';
  }

  function notesFor(cat, w){
    const base = stripDiacritics(w);
    const iLen = elILen.value;
    const form = elCase.value;
    const bits = [];
    if(iLen==='long') bits.push('Assuming long ι in -ινος (as discussed in the passage).');
    if(form==='gen') bits.push('Genitive selected: toy expects -ίνου.');
    if(!endsWithInos(w)) bits.push('Does not clearly end in -ινος/-ινου; still accents by syllable count.');
    if(base.includes('καρκιν')) bits.push('Herodian flags καρκίνος: many accent it on the penult; he prefers proparoxytone circumflex.');
    if(cat==='appellative') bits.push('Appellatives with long ι are said to “want to be barytone” (e.g. κάμινος).');
    if(cat==='oxytone') bits.push('Oxytone -ινος words are said to be rare (e.g. ἐρινός, χαλινός).');
    return bits.join(' ');
  }

  function enforceCase(word){
    // If user chose genitive, try to convert final -ινος -> -ινου (bare), preserving letters.
    const bare = stripDiacritics(word);
    if(elCase.value==='gen'){
      if(bare.endsWith('ινος')) return bare.slice(0,-3) + 'νου'; // replace 'νος' with 'νου'
      if(bare.endsWith('ινου')) return bare;
    } else {
      if(bare.endsWith('ινου')) return bare.slice(0,-2) + 'ς';
      if(bare.endsWith('ινος')) return bare;
    }
    return bare;
  }

  function run(){
    const raw = elWord.value;
    const norm = normalizeInput(raw);
    const cat = getCat();
    const w0 = norm.split(/\s+/)[0] || '';
    const w = enforceCase(w0);

    elNorm.textContent = w || '—';

    if(!w){
      elAcc.textContent = '—';
      elShape.textContent = '—';
      elNotes.textContent = 'Type a word ending in -ινος (e.g. καρκινος, echinos, kaminos).';
      return;
    }

    const pat = patternFor(cat);
    const res = applyAccent(w, pat);

    elAcc.textContent = res.out;
    elShape.textContent = shapeLabel(cat);
    elNotes.textContent = notesFor(cat, w);
  }

  // --- UI wiring ---
  chips.forEach(btn=>{
    btn.setAttribute('aria-pressed','false');
    btn.addEventListener('click', ()=>{ setCat(btn.dataset.cat); run(); });
  });
  setCat('water');

  elApply.addEventListener('click', run);
  elWord.addEventListener('keydown', (e)=>{ if(e.key==='Enter') run(); });
  elILen.addEventListener('change', run);
  elCase.addEventListener('change', run);

  elRandom.addEventListener('click', ()=>{
    const ex = examples[Math.floor(Math.random()*examples.length)];
    elWord.value = stripDiacritics(ex.w);
    setCat(ex.cat);
    // guess case from example
    elCase.value = stripDiacritics(ex.w).endsWith('ινου') ? 'gen' : 'nom';
    run();
  });

  elClear.addEventListener('click', ()=>{
    elWord.value='';
    run();
    elWord.focus();
  });

  // Render examples
  examples.forEach(ex=>{
    const b = document.createElement('button');
    b.className='ex';
    b.type='button';
    b.textContent = ex.w;
    b.title = ex.note;
    b.addEventListener('click', ()=>{
      elWord.value = stripDiacritics(ex.w);
      setCat(ex.cat);
      elCase.value = stripDiacritics(ex.w).endsWith('ινου') ? 'gen' : 'nom';
      run();
    });
    elExamples.appendChild(b);
  });

  run();
})();

