.lbl{min-width:220px;color:var(--muted)}
.inp{flex:1;min-width:260px; padding:10px 12px; border-radius:12px; border:1px solid var(--line); background:#0c0f1f; color:var(--text); outline:none; font-size:16px}
.inp:focus{border-color:rgba(125,211,252,.7); box-shadow:0 0 0 3px rgba(125,211,252,.15)}
.btns{display:flex;gap:10px;flex-wrap:wrap}
.btn{padding:9px 12px;border-radius:12px;border:1px solid var(--line); background:#0c0f1f;color:var(--text); cursor:pointer}
.btn:hover{border-color:rgba(167,139,250,.7)}
.btn.primary{background:linear-gradient(180deg, rgba(125,211,252,.18), rgba(167,139,250,.14)); border-color:rgba(125,211,252,.35)}
.tog{display:flex;gap:14px;flex-wrap:wrap;align-items:center;color:var(--muted)}
.chk{display:flex;gap:8px;align-items:center;user-select:none}
.out{margin-top:10px; padding:12px; border-radius:12px; border:1px dashed rgba(125,211,252,.35); background:rgba(12,15,31,.65)}
.kv{display:grid;grid-template-columns: 160px 1fr; gap:6px 12px; align-items:baseline}
.k{color:var(--muted)}
.v{color:var(--text)}
.badge{display:inline-block; padding:2px 8px; border-radius:999px; border:1px solid var(--line); background:rgba(255,255,255,.04); color:var(--muted); font-size:12px; margin-left:8px}
.tag{display:inline-block; padding:2px 8px; border-radius:999px; font-size:12px; margin-left:8px; border:1px solid transparent}
.tag.good{background:rgba(52,211,153,.12); border-color:rgba(52,211,153,.35); color:#bff7df}
.tag.warn{background:rgba(251,191,36,.12); border-color:rgba(251,191,36,.35); color:#ffe7b0}
.tag.bad{background:rgba(251,113,133,.12); border-color:rgba(251,113,133,.35); color:#ffd0d8}
.help{margin-top:10px; border:1px solid var(--line); border-radius:12px; padding:10px 12px; background:rgba(255,255,255,.03)}
.help summary{cursor:pointer; color:var(--accent)}
.helpBody{color:var(--muted)}
.examples{display:flex;flex-wrap:wrap;gap:10px;margin-top:10px}
.ex{flex:1;min-width:220px; border:1px solid var(--line); border-radius:12px; padding:10px 12px; background:rgba(12,15,31,.55)}
.ex .w{font-size:18px; letter-spacing:.2px}
.ex .meta{color:var(--muted); font-size:13px; margin-top:4px}
.ftr{margin-top:10px;color:var(--muted);font-size:12.5px}
.note{opacity:.95}
.mono{font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace}
hr{border:0;border-top:1px solid var(--line); margin:10px 0}
@media (max-width:560px){
  .kv{grid-template-columns: 1fr}
  .lbl{min-width:unset}
}
@media(max-width:560px){.inp{min-width:0;width:100%}.ex{min-width:0}.hdr{display:block}}
.wrap{overflow-wrap:anywhere}.row>*{max-width:100%}.kv>*{min-width:0}

