(() => {
  const $ = (id) => document.getElementById(id);

  const inp = $("inp");
  const selRule = $("selRule");
  const chkEthnic = $("chkEthnic");
  const normEl = $("norm");
  const syllEl = $("syll");
  const accEl = $("accented");
  const expEl = $("explain");

  const examples = [
    {w:"κινδυνος", rule:"unos", ethnic:true},
    {w:"παχυνος", rule:"unos", ethnic:true},
    {w:"βοθυνος", rule:"unos", ethnic:false},
    {w:"φορκυνος", rule:"unos", ethnic:false},
    {w:"πολτυνος", rule:"unos", ethnic:false},
    {w:"κοινωνος", rule:"onos", ethnic:false},
    {w:"οιωνος", rule:"onos", ethnic:false},
    {w:"τετραγωνος", rule:"compound", ethnic:false},
    {w:"ευφωνος", rule:"compound", ethnic:false},
    {w:"Βιθυνος", rule:"unos", ethnic:true},
    {w:"Μαριανδυνος", rule:"unos", ethnic:true}
  ];

  // --- Polytonic stripping (toy-level) ---
  function stripDiacritics(s){
    // NFD splits base + combining marks; remove combining marks.
    return (s || "").normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  }

  function cleanWord(s){
    // keep Greek letters and spaces/hyphen/apostrophe; collapse spaces
    const t = (s||"").trim();
    return t.replace(/[^\p{Script=Greek}\s\-’']/gu,'').replace(/\s+/g,' ');
  }

  const vowels = new Set(["α","ε","η","ι","ο","υ","ω","ά","έ","ή","ί","ό","ύ","ώ","ϊ","ϋ","ΐ","ΰ",
                         "Α","Ε","Η","Ι","Ο","Υ","Ω","Ά","Έ","Ή","Ί","Ό","Ύ","Ώ","Ϊ","Ϋ"]);

  function isVowel(ch){
    return vowels.has(ch);
  }

  function toLowerGreek(s){
    // locale-insensitive; good enough
    return s.toLowerCase();
  }

  function syllabifyToy(word){
    // Very rough: split before each vowel group, attach preceding consonants.
    // Handles diphthongs crudely by treating consecutive vowels as one nucleus.
    const w = word;
    const parts = [];
    let i = 0;
    while(i < w.length){
      // onset
      let onset = "";
      while(i < w.length && !isVowel(w[i])){ onset += w[i]; i++; }
      if(i >= w.length){
        if(parts.length) parts[parts.length-1] += onset;
        else if(onset) parts.push(onset);
        break;
      }
      // nucleus (vowel group)
      let nuc = "";
      while(i < w.length && isVowel(w[i])){ nuc += w[i]; i++; }
      // coda: take following consonants up to (but not including) next vowel, but leave last consonant for next onset if there is a next vowel
      let cons = "";
      let j = i;
      while(j < w.length && !isVowel(w[j])){ cons += w[j]; j++; }
      if(j < w.length && cons.length > 0){
        // leave last consonant for next onset
        const coda = cons.slice(0, -1);
        const carry = cons.slice(-1);
        parts.push(onset + nuc + coda);
        i = i + coda.length; // keep carry for next loop
      } else {
        parts.push(onset + nuc + cons);
        i = j;
      }
    }
    return parts.filter(p => p.length);
  }

  function detectRule(wordLower){
    if(wordLower.endsWith("υνος")) return "unos";
    if(wordLower.endsWith("ωνος")) return "onos";
    return "auto";
  }

  function chooseAccentIndex(sylls, mode, ethnic){
    const n = sylls.length;
    if(n === 0) return null;

    // default: if <=2 syllables, accent penult (toy fallback)
    const penult = Math.max(0, n-2);
    const ultima = n-1;
    const antepenult = Math.max(0, n-3);

    if(mode === "unos"){
      if(n > 2){
        return ethnic ? ultima : antepenult;
      }
      return penult;
    }

    if(mode === "onos"){
      if(n > 2) return ultima;
      return penult;
    }

    if(mode === "compound"){
      if(n > 2) return antepenult;
      return penult;
    }

    // auto fallback
    return penult;
  }

  function addAcuteToSyllable(syll){
    // Put acute on first vowel of the syllable.
    // Use combining acute to avoid needing precomposed mapping.
    const acute = "\u0301";
    const chars = syll.normalize('NFD').split('');
    for(let i=0;i<chars.length;i++){
      const base = chars[i];
      // skip combining marks
      if(/^[\u0300-\u036f]$/.test(base)) continue;
      const ch = base.normalize('NFC');
      if(isVowel(ch)){
        // insert acute after this base char (before any following combining marks)
        chars.splice(i+1, 0, acute);
        return chars.join('').normalize('NFC');
      }
    }
    return syll;
  }

  function accentWordToy(word, mode, ethnic){
    const cleaned = cleanWord(word);
    const stripped = stripDiacritics(cleaned);
    const lower = toLowerGreek(stripped);

    let chosenMode = mode;
    if(mode === "auto"){
      const d = detectRule(lower);
      chosenMode = (d === "auto") ? "unos" : d; // if unknown, default to -υνος-like behavior
    }

    // Only accent the last token if phrase
    const tokens = stripped.split(/\s+/).filter(Boolean);
    if(tokens.length === 0) return {norm:"", sylls:[], accented:"", explain:"Type a Greek word."};

    const last = tokens[tokens.length-1];
    const sylls = syllabifyToy(last);
    const idx = chooseAccentIndex(sylls, chosenMode, ethnic);

    const outSylls = sylls.slice();
    if(idx != null && outSylls[idx]) outSylls[idx] = addAcuteToSyllable(outSylls[idx]);

    const accentedLast = outSylls.join('');
    const rebuilt = tokens.slice(0,-1).concat([accentedLast]).join(' ');

    const ruleExplain = (() => {
      const n = sylls.length;
      const posName = (i) => {
        if(i === n-1) return "ultima";
        if(i === n-2) return "penult";
        if(i === n-3) return "antepenult";
        return `syllable ${i+1}`;
      };
      if(chosenMode === "unos"){
        if(n>2 && ethnic) return `Mode: -υνος with “ethnic exception” → oxytone (accent on ${posName(idx)}).`;
        if(n>2) return `Mode: -υνος (ὑπερδισύλλαβα) → proparoxytone (accent on ${posName(idx)}).`;
        return `Mode: -υνος but only ${n} syllable(s) → toy fallback accent on ${posName(idx)}.`;
      }
      if(chosenMode === "onos"){
        if(n>2) return `Mode: -ωνος (simple) → oxytone (accent on ${posName(idx)}).`;
        return `Mode: -ωνος but only ${n} syllable(s) → toy fallback accent on ${posName(idx)}.`;
      }
      if(chosenMode === "compound"){
        if(n>2) return `Mode: compound -ωνος → proparoxytone (accent on ${posName(idx)}).`;
        return `Mode: compound -ωνος but only ${n} syllable(s) → toy fallback accent on ${posName(idx)}.`;
      }
      return `Auto mode → accent on ${posName(idx)}.`;
    })();

    return {
      norm: stripped,
      sylls,
      accented: rebuilt,
      explain: ruleExplain,
      chosenMode
    };
  }

  function render(res){
    normEl.textContent = res.norm || "—";
    syllEl.textContent = (res.sylls && res.sylls.length) ? res.sylls.join(" · ") : "—";
    accEl.textContent = res.accented || "—";
    expEl.textContent = res.explain || "—";
  }

  function apply(){
    const mode = selRule.value;
    const ethnic = chkEthnic.checked;
    const res = accentWordToy(inp.value, mode, ethnic);
    render(res);
  }

  $("btnApply").addEventListener('click', apply);
  inp.addEventListener('keydown', (e) => {
    if(e.key === 'Enter') apply();
  });

  $("btnStrip").addEventListener('click', () => {
    inp.value = stripDiacritics(cleanWord(inp.value));
    apply();
  });

  $("btnSyll").addEventListener('click', () => {
    const cleaned = cleanWord(inp.value);
    const stripped = stripDiacritics(cleaned);
    const tokens = stripped.split(/\s+/).filter(Boolean);
    const last = tokens[tokens.length-1] || "";
    const sylls = last ? syllabifyToy(last) : [];
    normEl.textContent = stripped || "—";
    syllEl.textContent = sylls.length ? sylls.join(" · ") : "—";
    accEl.textContent = "—";
    expEl.textContent = "Syllabification is a toy heuristic (good enough for playing with accent placement).";
  });

  $("btnRandom").addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inp.value = ex.w;
    selRule.value = ex.rule === "compound" ? "compound" : (ex.rule === "onos" ? "onos" : "unos");
    chkEthnic.checked = !!ex.ethnic;
    apply();
  });

  // initial
  inp.value = "κινδυνος";
  selRule.value = "auto";
  chkEthnic.checked = true;
  apply();
})();

