(() => {
  const $ = (sel) => document.querySelector(sel);

  const elIn = $('#in');
  const elGo = $('#go');
  const elRand = $('#rand');
  const elClear = $('#clear');

  const elAsTyped = $('#asTyped');
  const elLower = $('#lower');
  const elPlain = $('#plain');
  const elSyll = $('#syll');
  const elRule = $('#rule');
  const elAccented = $('#accented');
  const elWhy = $('#why');

  const elAsPlace = $('#asPlace');
  const elAsAdj = $('#asAdj');
  const elModePill = $('#modePill');
  const elChips = $('#chips');

  // Toy lexicon from the passage + the explicit oxytone notes.
  const samples = [
    'Λίπαξος','Ἄραξος','Πύξος','μύξος','Βύξος','Σίξος','Φρίξος','Λίξος','Ῥοῖξος','Κρόξος','Βόξος','Λάοξος','Ὦξος','Ἄξος','Νάξος','Ὄαξος','Χάραξος','Ὀλόφυξος','Ἴξος','ἰξός','λοξός','φοξός','κοραξός','λαξός','φυλλοξός'
  ];

  // Exceptions: oxytone as adjective/appellative (per passage); barytone as ethnic/place.
  // We'll treat these as "flip" words.
  const flipToOxy = new Set(['ιξος','λοξος','φοξος','κοραξος']);

  // Some words are explicitly said to be oxytone as adjectives; we also include the accented forms.
  const flipDisplay = [
    {plain:'ιξος', place:'Ἴξος', adj:'ἰξός', gloss:'ἰξός (appellative) vs Ἴξος (place)'} ,
    {plain:'λοξος', place:'Λοξος', adj:'λοξός', gloss:'λοξός (adj.)'} ,
    {plain:'φοξος', place:'Φοξος', adj:'φοξός', gloss:'φοξός (adj.)'} ,
    {plain:'κοραξος', place:'Κόραξος', adj:'κοραξός', gloss:'κοραξός (adj.) / barytone as ethnic'}
  ];

  let mode = 'place'; // 'place' or 'adj'

  function setMode(next){
    mode = next;
    const isPlace = mode === 'place';
    elAsPlace.setAttribute('aria-pressed', String(isPlace));
    elAsAdj.setAttribute('aria-pressed', String(!isPlace));
    elModePill.textContent = 'Mode: ' + (isPlace ? 'place/ethnic' : 'adjective/appellative');
    analyze();
  }

  function stripDiacritics(s){
    // Remove combining marks; keep base Greek letters.
    return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  }

  function toLowerGreek(s){
    return s.toLocaleLowerCase('el');
  }

  function cleanToken(s){
    // Keep Greek letters and spaces/apostrophes; remove punctuation.
    return s.replace(/[··.,;:!?()\[\]{}"“”‘’]/g,'').trim();
  }

  function lastWord(s){
    const parts = s.trim().split(/\s+/).filter(Boolean);
    return parts.length ? parts[parts.length-1] : '';
  }

  function roughSyllabify(wordPlain){
    // Very rough: split before each vowel group.
    // Treat αι, ει, οι, υι, αυ, ευ, ου, ηυ as one group.
    const w = wordPlain;
    const diph = ['αι','ει','οι','υι','αυ','ευ','ου','ηυ'];
    const vowels = 'αεηιουω';

    let i = 0;
    const syl = [];
    let cur = '';

    while(i < w.length){
      const ch = w[i];
      const next2 = w.slice(i, i+2);
      cur += ch;

      // If we are at a vowel or diphthong end, we may cut syllable after following consonant cluster heuristically.
      let isVowel = vowels.includes(ch);
      let isDiph = diph.includes(next2);

      if(isDiph){
        // replace last char with diphthong
        cur = cur.slice(0, -1) + next2;
        i += 2;
        // attach following consonants up to (but not including) next vowel group start
        while(i < w.length){
          const look = w[i];
          const look2 = w.slice(i, i+2);
          const lookIsV = vowels.includes(look) || diph.includes(look2);
          if(lookIsV) break;
          cur += look;
          i++;
        }
        syl.push(cur);
        cur = '';
        continue;
      }

      if(isVowel){
        i++;
        while(i < w.length){
          const look = w[i];
          const look2 = w.slice(i, i+2);
          const lookIsV = vowels.includes(look) || diph.includes(look2);
          if(lookIsV) break;
          cur += look;
          i++;
        }
        syl.push(cur);
        cur = '';
        continue;
      }

      i++;
    }
    if(cur) syl.push(cur);
    return syl.filter(x => x.length);
  }

  function accentOxy(wordPlain){
    // Put acute on the last vowel of the word (very simplified).
    return accentOnVowelFromEnd(wordPlain, 1, 'acute');
  }

  function accentBary(wordPlain){
    // Put acute on the penult vowel if possible, else on ultima.
    const syl = roughSyllabify(wordPlain);
    if(syl.length >= 2) return accentOnVowelFromEnd(wordPlain, 2, 'acute');
    return accentOnVowelFromEnd(wordPlain, 1, 'acute');
  }

  function accentOnVowelFromEnd(wordPlain, syllFromEnd, kind){
    // Find vowel in the target syllable (from end) and add acute.
    // We operate on plain Greek without diacritics.
    const vowels = new Set(['α','ε','η','ι','ο','υ','ω']);
    const syl = roughSyllabify(wordPlain);
    const idx = syl.length - syllFromEnd;
    if(idx < 0) return wordPlain;

    // Determine character index range of that syllable in the word.
    let start = 0;
    for(let i=0;i<idx;i++) start += syl[i].length;
    let end = start + syl[idx].length;

    // Find last vowel in that syllable.
    let pos = -1;
    for(let i=end-1;i>=start;i--){
      if(vowels.has(wordPlain[i])) { pos = i; break; }
    }
    if(pos === -1){
      // fallback: last vowel in word
      for(let i=wordPlain.length-1;i>=0;i--){
        if(vowels.has(wordPlain[i])) { pos = i; break; }
      }
    }
    if(pos === -1) return wordPlain;

    const acuteMap = {
      'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ'
    };
    const ch = wordPlain[pos];
    const rep = (kind==='acute' && acuteMap[ch]) ? acuteMap[ch] : ch;
    return wordPlain.slice(0,pos) + rep + wordPlain.slice(pos+1);
  }

  function endsWithXos(wordPlain){
    return wordPlain.endsWith('ξος');
  }

  function analyze(){
    const raw = elIn.value;
    elAsTyped.textContent = raw ? raw : '—';

    const cleaned = cleanToken(raw);
    const w = lastWord(cleaned);
    const lower = toLowerGreek(w);
    const plain = stripDiacritics(lower);

    elLower.textContent = lower || '—';
    elPlain.textContent = plain || '—';

    if(!plain){
      elSyll.textContent = '—';
      elRule.innerHTML = '—';
      elAccented.textContent = '—';
      elWhy.textContent = '—';
      return;
    }

    const syl = roughSyllabify(plain);
    elSyll.textContent = syl.length ? syl.join('·') : plain;

    let proposed = plain;
    let ruleText = '';
    let why = '';

    if(endsWithXos(plain)){
      const isFlip = flipToOxy.has(plain);
      if(mode === 'adj' && isFlip){
        proposed = accentOxy(plain);
        ruleText = '<span class="ruleWarn">Oxytone (toy exception)</span>';
        why = 'Herodian notes some -ξος forms are oxytone as adjectives/appellatives (e.g. ἰξός, λοξός, φοξός, κοραξός).';
      } else {
        proposed = accentBary(plain);
        ruleText = '<span class="ruleGood">Barytone (Herodian’s default)</span>';
        why = 'Rule in the passage: “words in -ξος … are barytone” (accent not on the last syllable).';
        if(mode === 'adj' && isFlip){
          why += ' (Switch to adjective/appellative mode to see the oxytone reading.)';
        }
      }
    } else {
      proposed = accentBary(plain);
      ruleText = '<span class="ruleBad">Not -ξος</span>';
      why = 'This toy is tuned for -ξος. I still put a playful penult accent as a fallback.';
    }

    // Re-capitalize if original started with uppercase Greek.
    const startsUpper = w && w[0] !== toLowerGreek(w[0]);
    if(startsUpper){
      proposed = proposed[0].toLocaleUpperCase('el') + proposed.slice(1);
    }

    elRule.innerHTML = ruleText;
    elAccented.textContent = proposed;
    elWhy.textContent = why;
  }

  function pickSample(){
    const s = samples[Math.floor(Math.random()*samples.length)];
    elIn.value = s;
    analyze();
    elIn.focus();
  }

  function renderChips(){
    elChips.innerHTML = '';
    for(const item of flipDisplay){
      const b = document.createElement('button');
      b.className = 'chip greek';
      b.type = 'button';
      b.textContent = item.gloss;
      b.addEventListener('click', () => {
        elIn.value = (mode === 'place') ? item.place : item.adj;
        analyze();
        elIn.focus();
      });
      elChips.appendChild(b);
    }
  }

  elGo.addEventListener('click', analyze);
  elIn.addEventListener('input', analyze);
  elIn.addEventListener('keydown', (e) => {
    if(e.key === 'Enter') analyze();
  });
  elRand.addEventListener('click', pickSample);
  elClear.addEventListener('click', () => { elIn.value=''; analyze(); elIn.focus(); });

  elAsPlace.addEventListener('click', () => setMode('place'));
  elAsAdj.addEventListener('click', () => setMode('adj'));

  renderChips();
  pickSample();
})();

