const $ = (sel) => document.querySelector(sel);

const input = $('#w');
const btn = $('#go');
const btnRand = $('#rand');
const stripAccents = $('#strip');
const allowCaps = $('#allowCaps');
const resultEl = $('#result');
const metaEl = $('#meta');
const reasonsEl = $('#reasons');
const chipsEl = $('#chips');

// --- Utilities for (very) small-scale Greek accent play ---
// We only place: acute on the penult vowel (barytone for disyllables) OR acute on the ultima vowel (oxytone).

const COMBINING = {
  acute: '\u0301',
  grave: '\u0300',
  circumflex: '\u0342',
  diaeresis: '\u0308',
  smooth: '\u0313',
  rough: '\u0314',
  iotaSub: '\u0345'
};

function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripGreekAccents(s){
  // Remove accent marks but keep diaeresis and breathings? For simplicity, remove most combining marks except diaeresis and iota subscript.
  const keep = new Set([COMBINING.diaeresis, COMBINING.iotaSub]);
  let out = '';
  for (const ch of nfd(s)){
    const code = ch.codePointAt(0);
    const isCombining = (code >= 0x300 && code <= 0x36F);
    if (isCombining && !keep.has(ch)) continue;
    out += ch;
  }
  return nfc(out);
}

function isGreekLetter(ch){
  const cp = ch.codePointAt(0);
  return (cp >= 0x0370 && cp <= 0x03FF) || (cp >= 0x1F00 && cp <= 0x1FFF);
}

const VOWELS = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

function findVowelNuclei(word){
  // Return indices (in codepoints array) of vowel letters (not combining marks).
  const cps = Array.from(nfd(word));
  const letters = [];
  // Build array of base letters with their index in cps.
  for (let i=0;i<cps.length;i++){
    const ch = cps[i];
    const code = ch.codePointAt(0);
    const isCombining = (code >= 0x300 && code <= 0x36F);
    if (isCombining) continue;
    letters.push({ch, i});
  }
  const vowelPositions = [];
  for (let k=0;k<letters.length;k++){
    if (VOWELS.has(letters[k].ch)) vowelPositions.push(letters[k].i);
  }
  return { cps, vowelPositions };
}

function addAcuteOnVowel(word, which){
  // which: 'ultima' or 'penult'
  const base = nfd(word);
  const { cps, vowelPositions } = findVowelNuclei(base);
  if (vowelPositions.length === 0) return word;
  const target = (which === 'ultima')
    ? vowelPositions[vowelPositions.length-1]
    : (vowelPositions.length >= 2 ? vowelPositions[vowelPositions.length-2] : vowelPositions[0]);

  // Insert acute after the vowel letter but before any following combining marks already attached to it.
  // Find insertion point: right after the base vowel, before combining marks that follow.
  let insertAt = target + 1;
  while (insertAt < cps.length){
    const code = cps[insertAt].codePointAt(0);
    const isCombining = (code >= 0x300 && code <= 0x36F);
    if (!isCombining) break;
    // If there is already an acute/grave/circumflex, replace it with acute.
    if (cps[insertAt] === COMBINING.acute || cps[insertAt] === COMBINING.grave || cps[insertAt] === COMBINING.circumflex){
      cps[insertAt] = COMBINING.acute;
      return nfc(cps.join(''));
    }
    insertAt++;
  }
  cps.splice(insertAt, 0, COMBINING.acute);
  return nfc(cps.join(''));
}

function endsWithPos(w){
  const s = stripGreekAccents(w).trim();
  return /πος$/i.test(s);
}

function normalizeForLookup(w){
  // Lowercase, strip accents, normalize final sigma.
  let s = stripGreekAccents(w).trim().toLowerCase();
  s = s.replace(/ς/g,'σ');
  return s;
}

// --- Heuristic rules inspired by the passage ---

const known = {
  // explicitly mentioned / strongly implied in passage
  'τοπος': {class:'bary', label:'barytone', reason:'Non-adjectival example in the passage (τόπος).'},
  'κοπος': {class:'bary', label:'barytone', reason:'From κόπτω → κόπος; treated as barytone.'},
  'κηπος': {class:'bary', label:'barytone', reason:'Listed among barytone -πος words (κῆπος).'},
  'τυπος': {class:'bary', label:'barytone', reason:'Listed among barytone -πος words (τύπος).'},
  'κτυπος': {class:'bary', label:'barytone', reason:'Listed among barytone -πος words (κτύπος).'},
  'στυπος': {class:'bary', label:'barytone', reason:'Listed among barytone -πος words (στύπος).'},
  'ιππος': {class:'bary', label:'barytone', reason:'Herodian: ἵππος barytone (special condition with -μ/-π mentioned).'},
  'παππος': {class:'bary', label:'barytone', reason:'Herodian: πάππος barytone.'},
  'καμπος': {class:'bary', label:'barytone', reason:'Herodian: κάμπος barytone.'},
  'καρπος': {class:'oxy', label:'oxytone', reason:'Herodian explicitly: καρπός is oxytone.'},
  'σκοπος': {class:'oxy', label:'oxytone', reason:'Herodian: σκοπός is oxytone.'},
  'λοπος': {class:'oxy', label:'oxytone', reason:'Herodian: λοπός is oxytone.'},
  'οπος': {class:'oxy', label:'oxytone', reason:'Herodian: ὀπός is oxytone.'},
  'λοιπος': {class:'oxy', label:'oxytone', reason:'Herodian: λοιπός (adjective) oxytone.'},
  'γρυπος': {class:'oxy', label:'oxytone', reason:'Herodian: γρυπός (adjective) oxytone.'},
  'πομπος': {class:'oxy', label:'oxytone', reason:'Herodian: πομπός (adjective) oxytone.'},
  'χαλεπος': {class:'oxy', label:'oxytone', reason:'Herodian: χαλεπός (adjective) oxytone.'},
  // a few more from the list (treated as barytone there)
  'ρυπος': {class:'bary', label:'barytone', reason:'Listed among barytone -πος words (ῥύπος).'},
  'τριπος': {class:'bary', label:'barytone', reason:'Listed among barytone -πος words (τρίπος).'},
  'ριπος': {class:'bary', label:'barytone', reason:'Listed among barytone -πος words (ῥῖπος).'},
  'γριπος': {class:'bary', label:'barytone', reason:'Listed among barytone -πος words (γρῖπος).'},
  'κολπος': {class:'bary', label:'barytone', reason:'Herodian: κόλπος barytone.'},
  'δορπος': {class:'bary', label:'barytone', reason:'Herodian: δόρπος barytone.'}
};

function guessAdjectival(wNorm){
  // Very rough: if it matches some common adjective-looking patterns in -πος.
  // (Not philologically rigorous; just for play.)
  const stems = ['λοιπ','γρυπ','πομπ','χαλεπ','λαμπ','κομπ','τροπ'];
  return stems.some(st => wNorm.startsWith(st));
}

function analyze(wordRaw){
  const reasons = [];
  let w = wordRaw.trim();
  if (!w){
    return { ok:false, reasons:['Type a Greek word (preferably ending in -πος).'] };
  }

  const keepCaps = allowCaps.checked;
  const wasCapitalized = keepCaps && /^[Α-ΩΆΈΉΊΌΎΏ]/.test(w);

  if (stripAccents.checked) w = stripGreekAccents(w);

  if (!endsWithPos(w)){
    reasons.push('Input does not look like it ends in -πος (after stripping accents).');
    return { ok:false, word:w, reasons };
  }

  const norm = normalizeForLookup(w);

  // Known list overrides.
  if (known[norm]){
    const k = known[norm];
    reasons.push('Matched a known example: ' + k.reason);
    const accented = (k.class === 'oxy') ? addAcuteOnVowel(w, 'ultima') : addAcuteOnVowel(w, 'penult');
    return {
      ok:true,
      norm,
      class:k.class,
      label:k.label,
      accented: wasCapitalized ? capitalizeGreek(accented) : accented,
      reasons
    };
  }

  // Heuristic: if looks adjectival, prefer oxytone.
  if (guessAdjectival(norm)){
    reasons.push('Heuristic: looks like an adjective-pattern in -πος → prefer oxytone (like λοιπός, γρυπός).');
    const accented = addAcuteOnVowel(w, 'ultima');
    return { ok:true, norm, class:'oxy', label:'oxytone (guess)', accented: wasCapitalized ? capitalizeGreek(accented) : accented, reasons };
  }

  // Default: barytone for disyllabic -πος (toy assumes disyllabic).
  reasons.push('Default: many non-adjectival disyllables in -πος are barytone in Herodian’s discussion.');
  const accented = addAcuteOnVowel(w, 'penult');
  return { ok:true, norm, class:'bary', label:'barytone (default)', accented: wasCapitalized ? capitalizeGreek(accented) : accented, reasons };
}

function capitalizeGreek(s){
  // Capitalize first Greek letter; keep rest.
  const chars = Array.from(s);
  for (let i=0;i<chars.length;i++){
    if (isGreekLetter(chars[i])){
      chars[i] = chars[i].toUpperCase();
      break;
    }
  }
  return chars.join('');
}

function render(res){
  reasonsEl.innerHTML = '';
  if (!res.ok){
    resultEl.innerHTML = '<span class="err">—</span>';
    metaEl.textContent = res.reasons.join(' ');
    const li = document.createElement('li');
    li.textContent = res.reasons[0] || '—';
    reasonsEl.appendChild(li);
    return;
  }

  const badge = res.class === 'oxy'
    ? '<span class="badge oxy">oxytone</span>'
    : '<span class="badge bary">barytone</span>';

  resultEl.innerHTML = `${escapeHtml(res.accented)} ${badge}`;
  metaEl.textContent = 'Toy output: acute on ' + (res.class === 'oxy' ? 'ultima' : 'penult') + ' (for -πος).';

  for (const r of res.reasons){
    const li = document.createElement('li');
    li.textContent = r;
    reasonsEl.appendChild(li);
  }
}

function escapeHtml(s){
  return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function run(){
  render(analyze(input.value));
}

btn.addEventListener('click', run);
input.addEventListener('keydown', (e)=>{ if (e.key === 'Enter') run(); });

const examples = [
  'τοπος','τόπος','κοπος','κόπος','καρπος','καρπός','λοιπος','λοιπός','γρυπος','γρυπός',
  'σκοπος','σκοπός','κηπος','κῆπος','τυπος','τύπος','παππος','πάππος','καμπος','κάμπος',
  'κολπος','κόλπος','δορπος','δόρπος','ιππος','ἵππος'
];

function makeChips(){
  chipsEl.innerHTML = '';
  for (const ex of examples){
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip';
    b.textContent = ex;
    b.addEventListener('click', ()=>{ input.value = ex; run(); input.focus(); });
    chipsEl.appendChild(b);
  }
}

btnRand.addEventListener('click', ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  input.value = ex;
  run();
  input.focus();
});

makeChips();
input.value = 'τοπος';
run();

