:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --ink:#eef0ff;
  --muted:#b9bddb;
  --line:#2a2f4a;
  --accent:#7dd3fc;
  --good:#86efac;
  --warn:#fbbf24;
  --bad:#fb7185;
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 600px at 20% 0%, #1b2140 0%, var(--bg) 55%);color:var(--ink);font:15px/1.35 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif}
.wrap{max-width:980px;margin:0 auto;padding:22px 16px 28px}
header h1{margin:0 0 6px;font-size:22px;letter-spacing:.2px}
.sub{margin:0 0 14px;color:var(--muted)}
.panel{background:color-mix(in oklab, var(--panel) 92%, black 8%);border:1px solid var(--line);border-radius:14px;padding:14px}
.row{display:flex;gap:10px;align-items:end;margin:10px 0}
.row.two>div{flex:1}
label{display:block;color:var(--muted);font-size:12px;margin:0 0 6px}
input,select{width:100%;padding:10px 10px;border-radius:10px;border:1px solid var(--line);background:#0e1020;color:var(--ink);outline:none}
input:focus,select:focus{border-color:color-mix(in oklab, var(--accent) 60%, var(--line) 40%);box-shadow:0 0 0 3px color-mix(in oklab, var(--accent) 18%, transparent)}
button{padding:10px 12px;border-radius:10px;border:1px solid color-mix(in oklab, var(--accent) 35%, var(--line) 65%);background:linear-gradient(180deg, color-mix(in oklab, var(--accent) 22%, #0e1020), #0e1020);color:var(--ink);cursor:pointer}
button:hover{border-color:color-mix(in oklab, var(--accent) 60%, var(--line) 40%)}
button.ghost{background:transparent;border:1px solid var(--line);color:var(--muted)}
button.ghost:hover{color:var(--ink);border-color:color-mix(in oklab, var(--accent) 40%, var(--line) 60%)}
.out{display:grid;grid-template-columns:1fr 1fr 2fr;gap:10px;margin-top:10px}
.card{border:1px solid var(--line);border-radius:12px;padding:10px;background:rgba(0,0,0,.12)}
.card.big{grid-column:1/-1}
.k{color:var(--muted);font-size:12px;margin-bottom:6px}
.v{font-size:15px}
.v.big{font-size:26px;letter-spacing:.3px}
.mono{font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace}
.meter{margin-top:10px;border-top:1px dashed var(--line);padding-top:10px;display:flex;gap:8px;flex-wrap:wrap}
.pill{padding:6px 8px;border-radius:999px;border:1px solid var(--line);background:#0e1020;color:var(--muted);font-size:12px}
.pill.on{border-color:color-mix(in oklab, var(--good) 55%, var(--line) 45%);color:var(--ink);background:color-mix(in oklab, var(--good) 12%, #0e1020)}
.pill.warn{border-color:color-mix(in oklab, var(--warn) 55%, var(--line) 45%);color:var(--ink)}
.help{margin-top:10px;border:1px solid var(--line);border-radius:12px;padding:10px;background:rgba(0,0,0,.10)}
.help summary{cursor:pointer;color:var(--accent);font-weight:600}
.help ul{margin:8px 0 8px 18px;color:var(--muted)}
.help li{margin:4px 0}
footer{margin-top:10px;color:var(--muted)}
.tiny{font-size:12px;color:var(--muted)}
@media (max-width:820px){
  .out{grid-template-columns:1fr}
  .card.big{grid-column:auto}
}

