const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const mode = $('#mode');
const dial = $('#dial');
const btn = $('#btn');
const btnRandom = $('#btnRandom');
const btnClear = $('#btnClear');

const normEl = $('#norm');
const ruleEl = $('#rule');
const accentedEl = $('#accented');
const meterEl = $('#meter');

// --- Utilities: Greek normalization ---
// Remove combining marks and common precomposed tonos/oxia variants by NFD stripping.
function stripDiacritics(s){
  return (s || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'')
    .replace(/\u0342/g,'') // perispomeni
    .replace(/\u0345/g,'') // iota subscript
    .normalize('NFC');
}

function cleanGreek(s){
  return stripDiacritics(s)
    .replace(/[^\p{L}]/gu,'')
    .toLowerCase();
}

const vowels = new Set(['α','ε','η','ι','ο','υ','ω']);

function isVowel(ch){ return vowels.has(ch); }

// Very simple syllabifier: split before each vowel group (diphthongs treated as one group).
const diphthongs = ['αι','ει','οι','υι','αυ','ευ','ηυ','ου','ωυ'];

function syllabify(word){
  // word should be lowercase, no diacritics
  if(!word) return [];
  let syls = [];
  let i = 0;
  while(i < word.length){
    // find next vowel
    let start = i;
    while(i < word.length && !isVowel(word[i])) i++;
    if(i >= word.length){
      // trailing consonants attach to last syllable
      if(syls.length) syls[syls.length-1] += word.slice(start);
      else syls.push(word.slice(start));
      break;
    }
    // we are at a vowel; include any onset consonants in this syllable
    let onset = word.slice(start, i);

    // capture vowel nucleus (diphthong or single)
    let nucleus = word[i];
    let two = word.slice(i, i+2);
    if(diphthongs.includes(two)){
      nucleus = two;
      i += 2;
    } else {
      i += 1;
    }

    // now capture following consonants up to next vowel, but leave last consonant for next onset if possible
    let cStart = i;
    while(i < word.length && !isVowel(word[i])) i++;
    let cluster = word.slice(cStart, i);

    // heuristic: if cluster length >=2, split before last consonant (so last becomes onset)
    let coda = '';
    if(cluster.length <= 1){
      coda = cluster;
      cluster = '';
    } else {
      coda = cluster.slice(0, -1);
      cluster = cluster.slice(-1); // carry to next onset
    }

    syls.push(onset + nucleus + coda);

    // carryover consonant becomes start of next syllable
    if(cluster){
      i -= cluster.length;
    }
  }
  return syls.filter(x=>x.length);
}

function endsWithAny(w, arr){
  return arr.some(suf => w.endsWith(suf));
}

// --- Accent placement ---
// We output either tonos (ά) or polytonic acute (ά/ό etc). For simplicity, polytonic uses oxia (U+1F71 etc?)
// We'll implement tonos for both, and for "poly" we use combining acute U+0301 on the vowel nucleus.

function addAcuteToSyllable(syl, style){
  // add acute to the first vowel of the syllable nucleus
  // work in NFD to insert combining acute
  let nfd = syl.normalize('NFD');
  for(let i=0;i<nfd.length;i++){
    const ch = nfd[i];
    const base = stripDiacritics(ch);
    if(isVowel(base)){
      // insert combining acute after this base vowel (and after any existing combining marks)
      // find end of combining marks following this char
      let j = i+1;
      while(j < nfd.length && /[\u0300-\u036f]/.test(nfd[j])) j++;
      nfd = nfd.slice(0, j) + '\u0301' + nfd.slice(j);
      break;
    }
  }
  let out = nfd.normalize('NFC');
  if(style === 'tonos'){
    // tonos is fine as combining acute in NFC; Greek letters will usually compose to tonos.
    return out;
  }
  // "poly": keep combining acute; NFC may still compose to tonos on modern fonts, but acceptable offline.
  return out;
}

function accentByPosition(word, posFromEnd, style){
  // posFromEnd: 1=ultima, 2=penult, 3=antepenult
  const w = cleanGreek(word);
  const syls = syllabify(w);
  if(syls.length === 0) return {accented:'', syls:[], idx:-1};
  let idx = syls.length - posFromEnd;
  if(idx < 0) idx = 0;
  const outSyls = syls.map((s,i)=> i===idx ? addAcuteToSyllable(s, style) : s);
  return {accented: outSyls.join(''), syls: outSyls, idx};
}

// --- Rule engine (toy) ---
const examples = [
  'ἡμεδαπος','ποδαπος','παντοδαπος','ἀλλοδαπος','τηλεδαπος',
  'πολυωπος','ευωπος','τηλωπος','μελανωπος','πελιωπος',
  'Αροπος','Τριοπος','Δουριοπος','Αναπος','Υαπος','Μεσσαπος','Πριαπος','Αστεροπος',
  'ατραπος','αελλοπος','ωκυπος','Ινωπος','Ασωπος','Ωρωπος'
];

const exceptionParoxytone = new Set([
  cleanGreek('ατραπος'),
  cleanGreek('αελλοπος'),
  cleanGreek('ωκυπος'),
  cleanGreek('αρτιπος')
]);

function guessRule(raw, forcedType){
  const w = cleanGreek(raw);
  if(!w) return {kind:'none', msg:'Type a Greek word.'};

  // 1) -δαπος derivatives: oxytone
  if(w.endsWith('δαπος')){
    return {kind:'oxytone', msg:"Ends in -δαπος → oxytone (acute on ultima)."};
  }

  // 2) exceptions noted: paroxytone
  if(exceptionParoxytone.has(w)){
    return {kind:'paroxytone', msg:"Noted exception (e.g. ἀτραπός / ἀελλόπος / ὠκύπος) → paroxytone."};
  }

  // 3) compound adjectives with -ωπος (penult ω): oxytone
  // crude check: ends with ωπος or contains ωπ before final ος
  if(w.endsWith('ωπος')){
    // If user forces proper name, Herodian says these can vary; still show oxytone as the headline rule for adjectives.
    if(forcedType === 'proper'){
      return {kind:'either', msg:"Ends in -ωπος. Herodian notes -ω- penult forms can be barytone or oxytone; toy offers both."};
    }
    return {kind:'oxytone', msg:"Compound adjective with penult -ω- (…ωπος) → oxytone."};
  }

  // 4) -πος, >2 syllables, non-adjectival, penult not ω: proparoxytone
  if(w.endsWith('πος')){
    const syls = syllabify(w);
    const penult = syls.length >= 2 ? syls[syls.length-2] : '';
    const penultHasOmega = penult.includes('ω');

    if(syls.length > 2 && !penultHasOmega){
      if(forcedType === 'adj'){
        return {kind:'unknown', msg:"Ends in -πος, but you chose ‘adjective’; rule here targets non-adjectival names/appellatives. Toy will default to paroxytone."};
      }
      return {kind:'proparoxytone', msg:"-πος, >2 syllables, penult not ω, and (assumed) proper/appellative → proparoxytone."};
    }

    if(penultHasOmega){
      return {kind:'either', msg:"-πος with penult ω: Herodian allows barytone or oxytone; toy offers both."};
    }

    // fallback for short -πος words
    return {kind:'paroxytone', msg:"-πος but not clearly in the >2-syllable name pattern → toy defaults to paroxytone."};
  }

  return {kind:'unknown', msg:"No matching -δαπος / -ωπος / -πος pattern found. Toy will accent the penult (paroxytone) as a default."};
}

function renderMeter(syls, idx, label){
  meterEl.innerHTML = '';
  if(!syls || !syls.length) return;
  const total = syls.length;
  for(let i=0;i<total;i++){
    const fromEnd = total - i;
    const pill = document.createElement('div');
    pill.className = 'pill' + (i===idx ? ' on' : '');
    let name = fromEnd===1 ? 'ultima' : fromEnd===2 ? 'penult' : fromEnd===3 ? 'antepenult' : `${fromEnd}th from end`;
    pill.textContent = `${syls[i]}  (${name})`;
    meterEl.appendChild(pill);
  }
  if(label){
    const note = document.createElement('div');
    note.className = 'pill warn';
    note.textContent = label;
    meterEl.appendChild(note);
  }
}

function apply(){
  const raw = inp.value.trim();
  const forced = mode.value;
  const style = dial.value;

  const normalized = cleanGreek(raw);
  normEl.textContent = normalized || '—';

  const r = guessRule(raw, forced);
  ruleEl.textContent = r.msg;

  let result;
  let extra = '';

  if(r.kind === 'oxytone'){
    result = accentByPosition(raw, 1, style);
  } else if(r.kind === 'paroxytone'){
    result = accentByPosition(raw, 2, style);
  } else if(r.kind === 'proparoxytone'){
    result = accentByPosition(raw, 3, style);
  } else if(r.kind === 'either'){
    // show two options
    const ox = accentByPosition(raw, 1, style).accented;
    const ba = accentByPosition(raw, 2, style).accented;
    accentedEl.textContent = `${ox}  /  ${ba}`;
    const syls = syllabify(cleanGreek(raw));
    renderMeter(syls, Math.max(0, syls.length-1), 'Two suggestions shown: oxytone / barytone(paroxytone)');
    return;
  } else {
    result = accentByPosition(raw, 2, style);
    extra = 'Defaulted to penult.';
  }

  accentedEl.textContent = result.accented || '—';
  renderMeter(result.syls.length ? result.syls : syllabify(cleanGreek(raw)), result.idx, extra);
}

btn.addEventListener('click', apply);
inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') apply(); });

btnRandom.addEventListener('click', ()=>{
  const pick = examples[Math.floor(Math.random()*examples.length)];
  inp.value = pick;
  apply();
