passages.gadget_js:
const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const normOut = $('#norm');
const detectOut = $('#detect');
const whyOut = $('#why');
const notesUl = $('#notes');

const sugBtns = [$('#sug1'), $('#sug2'), $('#sug3')];

// --- Greek helpers (very lightweight) ---
const tonosMap = {
  'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
  'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
};

const stripDiacritics = (s) => {
  // Remove combining marks and also precomposed tonos/dialytika variants by NFD.
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
};

const isVowel = (ch) => 'αεηιουωΑΕΗΙΟΥΩ'.includes(ch);

function syllabifyRough(word){
  // Very rough syllable nuclei finder: each vowel (or diphthong) counts as a nucleus.
  // Handles common diphthongs: αι ει οι υι αυ ευ ου ηυ (and uppercase).
  const w = word;
  const nuclei = [];
  const diph = new Set(['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ΑΙ','ΕΙ','ΟΙ','ΥΙ','ΑΥ','ΕΥ','ΟΥ','ΗΥ']);
  let i=0;
  while(i<w.length){
    const ch = w[i];
    const next = w[i+1] || '';
    if(isVowel(ch)){
      const pair = ch+next;
      if(next && isVowel(next) && diph.has(pair)){
        nuclei.push({start:i, len:2});
        i += 2;
        continue;
      } else {
        nuclei.push({start:i, len:1});
        i += 1;
        continue;
      }
    }
    i += 1;
  }
  return nuclei;
}

function accentOnNucleus(word, nucleusIndexFromEnd){
  // Place acute on the vowel nucleus counted from end: 1=ultima,2=penult,3=antepenult.
  const nuclei = syllabifyRough(word);
  if(nuclei.length === 0) return word;
  const idx = nuclei.length - nucleusIndexFromEnd;
  if(idx < 0 || idx >= nuclei.length) return word;

  const n = nuclei[idx];
  // Accent first char of nucleus.
  const chars = Array.from(word);
  const pos = n.start;
  const base = chars[pos];
  const accented = tonosMap[base] || base;
  chars[pos] = accented;
  return chars.join('');
}

function titleCaseLike(original, suggestion){
  // Preserve initial capitalization if original starts with uppercase Greek.
  if(original && original[0] === original[0].toUpperCase()){
    return suggestion[0].toUpperCase() + suggestion.slice(1);
  }
  return suggestion;
}

function setSug(i, text, tag){
  const b = sugBtns[i];
  b.disabled = !text;
  if(!text){ b.textContent = '—'; return; }
  b.innerHTML = `<span class="mono">${escapeHtml(text)}</span><span class="tag">${escapeHtml(tag)}</span>`;
  b.dataset.copy = text;
}

function escapeHtml(s){
  return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function renderNotes(items){
  notesUl.innerHTML = '';
  if(!items.length){
    const li = document.createElement('li');
    li.textContent = 'No special note triggered. Try Αἴσωπος or Κάνωπος.';
    notesUl.appendChild(li);
    return;
  }
  for(const it of items){
    const li = document.createElement('li');
    li.innerHTML = it;
    notesUl.appendChild(li);
  }
}

function analyze(){
  const raw = inp.value.trim();
  if(!raw){
    normOut.textContent = '—';
    detectOut.textContent = '—';
    whyOut.textContent = '—';
    setSug(0,'',''); setSug(1,'',''); setSug(2,'','');
    renderNotes([]);
    return;
  }

  // Normalize: strip accents/combining marks, keep Greek letters/spaces/apostrophes.
  const cleaned = stripDiacritics(raw).replace(/[^\p{Script=Greek}\s’'·\-]/gu,'');
  const words = cleaned.split(/\s+/).filter(Boolean);
  const first = words[0] || cleaned;

  normOut.textContent = cleaned;

  const lowerFirst = first.toLowerCase();
  const notes = [];

  // Detection of endings
  let detected = [];
  if(lowerFirst.endsWith('ωπος')) detected.push('ends in -ωπος');
  if(lowerFirst.endsWith('οπος')) detected.push('ends in -οπος');
  if(lowerFirst.endsWith('ρος')) detected.push('ends in -ρος');
  if(lowerFirst.endsWith('σος')) detected.push('ends in -σος');
  if(lowerFirst.endsWith('τος')) detected.push('ends in -τος');
  if(lowerFirst.endsWith('φος')) detected.push('ends in -φος');

  detectOut.textContent = detected.length ? detected.join(' · ') : 'No target ending detected (still can accent by syllables).';

  // Special triggers from the passage
  if(lowerFirst === 'αισωπος'){
    notes.push('Herodian: <b>σημείωσαι τὸ Αἴσωπος</b> (“note Aesop”). Try comparing accent placements.');
  }
  if(lowerFirst === 'κανωπος'){
    notes.push('Herodian: <b>Κάνωπος</b> “ought to be written with π, but is written with β” → playful variant: <span class="mono">Κάνωβος</span>.');
  }
  if(lowerFirst === 'κροτωπος' || lowerFirst === 'μελανωπος'){
    notes.push('Herodian: <b>Κρότωπος</b> and <b>Μελάνωπος</b> (proper names) “do not begin with a long [vowel]” (a quantity note, not implemented).');
  }

  // Accent suggestions inspired by the passage
  // 1) If ανθρωπος: proparoxytone (antepenult)
  // 2) If στενωπος or αλωπος: oxytone (ultima)
  // Otherwise: offer three options (antepenult/penult/ultima) as a playground.

  const base = first; // already stripped
  let s1='', s2='', s3='';
  let why='';

  if(lowerFirst === 'ανθρωπος'){
    s1 = titleCaseLike(first, accentOnNucleus(base, 3));
    s2 = titleCaseLike(first, accentOnNucleus(base, 2));
    s3 = titleCaseLike(first, accentOnNucleus(base, 1));
    why = 'Passage: <b>ἄνθρωπος</b> is said to be <b>proparoxytone</b> (acute on the antepenult).';
    setSug(0, s1, 'proparoxytone');
    setSug(1, s2, 'try penult');
    setSug(2, s3, 'try ultima');
  } else if(lowerFirst === 'στενωπος' || lowerFirst === 'αλωπος'){
    s1 = titleCaseLike(first, accentOnNucleus(base, 1));
    s2 = titleCaseLike(first, accentOnNucleus(base, 2));
    s3 = titleCaseLike(first, accentOnNucleus(base, 3));
    why = 'Passage: <b>στενωπός</b> and <b>ἀλωπός</b> are said to be <b>oxytone</b> (acute on the ultima).';
    setSug(0, s1, 'oxytone');
    setSug(1, s2, 'try penult');
    setSug(2, s3, 'try antepenult');
  } else {
    // Generic playground
    s1 = titleCaseLike(first, accentOnNucleus(base, 3));
    s2 = titleCaseLike(first, accentOnNucleus(base, 2));
    s3 = titleCaseLike(first, accentOnNucleus(base, 1));
    why = 'Playground: three possible acute placements by syllable-count (antepenult / penult / ultima). Not a full rule system.';
    setSug(0, s1, 'antepenult');
    setSug(1, s2, 'penult');
    setSug(2, s3, 'ultima');
  }

  // Add playful spelling note for Κάνωπος
  if(lowerFirst === 'κανωπος'){
    const kanobos = titleCaseLike(first, base.slice(0,-2) + 'βος');
    notes.push(`Variant (spelling joke): click to copy <span class="mono copy" data-copy="${escapeHtml(kanobos)}">${escapeHtml(kanobos)}</span>.`);
  }

  whyOut.textContent = why;
  renderNotes(notes);
}

$('#analyze').addEventListener('click', analyze);
$('#clear').addEventListener('click', () => { inp.value=''; inp.focus(); analyze(); });

inp.addEventListener('keydown', (e) => {
  if(e.key === 'Enter') analyze();
});

function copyText(t){
  if(!t) return;
  // Offline-safe clipboard attempt
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(t).catch(()=>fallbackCopy(t));
  } else fallbackCopy(t);
}
function fallbackCopy(t){
  const ta = document.createElement('textarea');
  ta.value = t;
  ta.style.position='fixed';
  ta.style.left='-9999px';
  document.body.appendChild(ta);
  ta.select();
  try{ document.execCommand('copy'); }catch(_){ }
  document.body.removeChild(ta);
}

for(const b of sugBtns){
  b.addEventListener('click', () => copyText(b.dataset.copy));
}

notesUl.addEventListener('click', (e) => {
  const el = e.target.closest('[data-copy]');
  if(el) copyText(el.getAttribute('data-copy'));
});

// initial
analyze();

