passages.gadget_js:
const $ = (sel, el=document) => el.querySelector(sel);
const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

const inp = $('#inp');
const outWord = $('#outWord');
const outMeta = $('#outMeta');
const outExplain = $('#outExplain');
const explainCard = $('#explainCard');
const chkStrip = $('#chkStrip');
const chkExplain = $('#chkExplain');

let mode = 'auto';
let lastResult = '';

const examples = [
  {w:'κηρος', m:'appellative'},
  {w:'φηρος', m:'appellative'},
  {w:'μηρος', m:'appellative'},
  {w:'κληρος', m:'appellative'},
  {w:'Σηρος', m:'proper'},
  {w:'Τρηρος', m:'proper'},
  {w:'Δρηρος', m:'proper'},
  {w:'σκληρος', m:'adjective'},
  {w:'ξηρος', m:'adjective'},
  {w:'πηρος', m:'adjective'}
];

// --- Greek helpers (toy-level) ---
const combining = {
  acute: '\u0301',
  grave: '\u0300',
  circumflex: '\u0342',
  diaeresis: '\u0308',
  smooth: '\u0313',
  rough: '\u0314',
  iotaSub: '\u0345'
};

function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripDiacritics(s){
  // Remove Greek combining marks broadly.
  return nfc(nfd(s).replace(/[\u0300-\u036f]/g,''));
}

function isGreekLetter(ch){
  const cp = ch.codePointAt(0);
  return (cp>=0x0370 && cp<=0x03FF) || (cp>=0x1F00 && cp<=0x1FFF);
}

function tokenizeGreek(s){
  // Keep only Greek letters and final sigma; preserve spaces.
  // Also allow apostrophe and hyphen.
  return s.replace(/[^\p{Script=Greek}\s\-’'·\.]/gu,'');
}

const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

function findPenultVowelIndex(word){
  // Very rough: count vowel letters; penult vowel = second-to-last vowel.
  const chars = Array.from(word);
  const vowelIdx = [];
  for(let i=0;i<chars.length;i++){
    if(vowels.has(chars[i])) vowelIdx.push(i);
  }
  if(vowelIdx.length < 2) return -1;
  return vowelIdx[vowelIdx.length-2];
}

function addAccentOnVowel(word, which){
  // which: 'acute' | 'circumflex'
  const clean = stripDiacritics(word);
  const idx = findPenultVowelIndex(clean);
  if(idx<0) return clean;
  const chars = Array.from(clean);
  chars[idx] = nfc(nfd(chars[idx]) + combining[which]);
  return nfc(chars.join(''));
}

function beginsWithConsonantCluster(word){
  const w = stripDiacritics(word);
  const chars = Array.from(w);
  // skip leading non-letters
  let i=0;
  while(i<chars.length && !isGreekLetter(chars[i])) i++;
  if(i>=chars.length) return false;
  const c1 = chars[i];
  const c2 = chars[i+1];
  if(!c2) return false;
  const isV1 = vowels.has(c1);
  const isV2 = vowels.has(c2);
  return (!isV1 && !isV2);
}

function endsWith(word, ending){
  return stripDiacritics(word).toLowerCase().endsWith(ending);
}

function guessModeAuto(word){
  // Toy heuristics:
  // 1) If starts with uppercase Greek -> proper
  // 2) If ends with -ος and looks like adjective examples (σκληρος/ξηρος/πηρος) -> adjective
  // 3) default appellative
  const trimmed = word.trim();
  const first = Array.from(trimmed)[0] || '';
  if(first && first === first.toUpperCase() && first !== first.toLowerCase() && isGreekLetter(first)) return 'proper';

  const w = stripDiacritics(trimmed).toLowerCase();
  if(w === 'σκληρος' || w === 'ξηρος' || w === 'πηρος' || w === 'λαρος' || w === 'ψαρος' || w === 'ναρος' || w === 'μναρος') return 'adjective';

  return 'appellative';
}

function suggest(word, forcedMode){
  const original = word;
  const cleaned = chkStrip.checked ? stripDiacritics(word) : word;
  const w = cleaned.trim();
  if(!w){
    return {ok:false, out:'—', meta:'', explain:''};
  }

  const m = forcedMode === 'auto' ? guessModeAuto(w) : forcedMode;

  // Focus: disyllables in -ηρος (toy: detect by ending "ηρος" after stripping)
  const isEros = endsWith(w,'ηρος');
  const isRos = endsWith(w,'ρος');

  let out = stripDiacritics(w);
  let explain = [];
  let metaBits = [];

  metaBits.push(`<span class="badge">mode: <b>${m}</b></span>`);

  if(isEros){
    metaBits.push(`<span class="badge">pattern: <b>-ηρος</b></span>`);

    if(m === 'proper'){
      // barytone: put circumflex on penult (toy choice)
      out = addAccentOnVowel(out,'circumflex');
      explain.push(`Proper name in <span class="mono">-ηρος</span> → “barytone” (toy renders this as <b>circumflex on the penult</b>): cf. <span class="mono">Σῆρος, Τρῆρος, Δρῆρος</span>.`);
    } else if(m === 'appellative'){
      // oxytone in Herodian’s summary; toy renders as acute on penult (since we only place on penult)
      // Special case: κληρος is barytone due to consonant cluster.
      const cluster = beginsWithConsonantCluster(out);
      if(stripDiacritics(out).toLowerCase() === 'κληρος' || cluster){
        out = addAccentOnVowel(out,'circumflex');
        explain.push(`Appellative in <span class="mono">-ηρος</span>, but treated as barytone here because it begins with a <b>consonant cluster</b> (toy check), echoing Herodian’s note on <span class="mono">κλῆρος</span>.`);
      } else {
        out = addAccentOnVowel(out,'acute');
        explain.push(`Appellative in <span class="mono">-ηρος</span> → oxytone in the passage (toy renders as <b>acute on the penult</b>): cf. <span class="mono">κηρός, φηρός, μηρός</span>.`);
      }
    } else if(m === 'adjective'){
      // If begins with semivowel (toy: ξ, σ? actually not semivowels; but passage says semivowel start; we approximate with σ/ξ as in examples)
      const base = stripDiacritics(out).toLowerCase();
      if(base === 'σκληρος' || base === 'ξηρος'){
        out = addAccentOnVowel(out,'acute');
        explain.push(`Adjective in <span class="mono">-ηρος</span> like <span class="mono">σκληρός</span>/<span class="mono">ξηρός</span> → oxytone (acute).`);
      } else if(base === 'πηρος'){
        out = addAccentOnVowel(out,'acute');
        explain.push(`For <span class="mono">πηρος</span>: poet has <span class="mono">πηρός</span> (acute), while Attic is reported as <span class="mono">πῆρος</span> (circumflex). Toy suggests the poet’s accent; try the “circumflex” button to see the Attic variant.`);
      } else {
        out = addAccentOnVowel(out,'acute');
        explain.push(`Adjective in <span class="mono">-ηρος</span> → toy defaults to oxytone (acute) following the passage’s tendency for adjectival forms.`);
      }
    }

  } else if(isRos){
    metaBits.push(`<span class="badge">pattern: <b>-ρος</b></span>`);
    // Small riff: adjectives like μναρός/λαρός/ψαρός/ναρός are oxytone (acute) per passage.
    const base = stripDiacritics(out).toLowerCase();
    const adjSet = new Set(['μναρος','λαρος','ψαρος','ναρος']);
    if(m === 'adjective' || adjSet.has(base)){
      out = addAccentOnVowel(out,'acute');
      explain.push(`Adjectives in <span class="mono">-ρος</span> are said here to be <b>oxytone</b> (acute): e.g. <span class="mono">μναρός, λαρός, ψαρός, ναρός</span>.`);
    } else {
      out = addAccentOnVowel(out,'circumflex');
      explain.push(`Not an <span class="mono">-ηρος</span> disyllable; toy falls back to a “barytone-ish” penult circumflex for <span class="mono">-ρος</span> unless marked as adjective.`);
    }
  } else {
    metaBits.push(`<span class="badge">pattern: <b>other</b></span>`);
    out = stripDiacritics(out);
    explain.push(`This toy mainly knows <span class="mono">-ηρος</span> and a small <span class="mono">-ρος</span> add-on. Your input doesn’t match those endings after stripping accents.`);
  }

  return {
    ok:true,
    out,
    meta: metaBits.join(' '),
    explain: explain.join(' ')
  };
}

function render(){
  const raw = tokenizeGreek(inp.value);
  if(raw !== inp.value) inp.value = raw;

  const res = suggest(inp.value, mode);
  lastResult = res.ok ? res.out : '';
  outWord.textContent = res.out;
  outMeta.innerHTML = res.meta || '—';
  outExplain.innerHTML = res.explain || '—';
  explainCard.style.display = chkExplain.checked ? '' : 'none';
}

function setMode(m){
  mode = m;
  $$('.segBtn').forEach(b=>{
    const on = b.dataset.mode === m;
    b.setAttribute('aria-pressed', on ? 'true' : 'false');
  });
  render();
}

// --- events ---
$$('.segBtn').forEach(btn=>{
  btn.addEventListener('click', ()=> setMode(btn.dataset.mode));
});

$('#btnTry').addEventListener('click', render);
$('#btnShuffle').addEventListener('click', ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  inp.value = ex.w;
  setMode('auto');
  render();
});
$('#btnClear').addEventListener('click', ()=>{
  inp.value='';
  render();
  inp.focus();
});

chkStrip.addEventListener('change', render);
chkExplain.addEventListener('change', render);

$('#btnAcute').addEventListener('click', ()=>{
  const base = stripDiacritics(inp.value.trim());
  const out = addAccentOnVowel(base,'acute');
  outWord.textContent = out;
  lastResult = out;
});
$('#btnCirc').addEventListener('click', ()=>{
  const base = stripDiacritics(inp.value.trim());
  const out = addAccentOnVowel(base,'circumflex');
  outWord.textContent = out;
  lastResult = out;
});
$('#btnNone').addEventListener('click', ()=>{
  const out = stripDiacritics(inp.value.trim());
  outWord.textContent = out || '—';
  lastResult = out;
});
$('#btnCopy').addEventListener('click', async ()=>{
  const txt = (lastResult || outWord.textContent || '').trim();
  if(!txt || txt==='—') return;
  try{
    await navigator.clipboard.writeText(txt);
    outMeta.innerHTML = outMeta.innerHTML + ' <span class="badge good">copied</span>';
    setTimeout(()=>render(), 700);
  } catch(e){
    // fallback: select input
    inp.value = txt;
    inp.focus();
    inp.select();
    outMeta.innerHTML = outMeta.innerHTML + ' <span class="badge warn">clipboard blocked; selected instead</span>';
    setTimeout(()=>render(), 900);
  }
});

inp.addEventListener('input', ()=>{
  // live update, but keep it light
  render();
});

// init
setMode('auto');
inp.value = 'κηρος';
render();

