const $ = (sel) => document.querySelector(sel);

const inEl = $('#in');
const outWord = $('#outWord');
const outRule = $('#outRule');
const btnGuess = $('#btnGuess');
const btnClear = $('#btnClear');
const chipsEl = $('#chips');

// --- Minimal polytonic accent helpers (toy-level) ---
// We only place: acute on penult vowel (barytone) OR acute on ultima vowel (oxytone).
// We do not attempt circumflex/breathings; we keep existing diacritics if present.

const combiningAcute = '\u0301';

function stripCombining(s){
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  // Greek and Coptic + Greek Extended
  return (code >= 0x0370 && code <= 0x03FF) || (code >= 0x1F00 && code <= 0x1FFF);
}

function normalizeGreekInput(raw){
  // Keep only Greek letters and apostrophes/spaces/hyphens for display; analysis uses last token.
  return raw.replace(/[^\p{Script=Greek}\s\-’'·\.]/gu,'');
}

function lastGreekToken(s){
  const parts = s.trim().split(/\s+/).filter(Boolean);
  return parts.length ? parts[parts.length-1] : '';
}

const vowels = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ','ϊ','ΐ','ϋ','ΰ','ᾳ','ῃ','ῳ']);

function findVowelPositions(word){
  // Return indices of base letters that are vowels (ignoring combining marks).
  const nfd = word.normalize('NFD');
  // Map from NFD index to NFC "base letter index" in the original string is hard.
  // Instead: work on an array of grapheme-ish clusters: base + combining marks.
  const clusters = [];
  let cur = '';
  for (const ch of nfd){
    const isComb = /[\u0300-\u036f]/.test(ch);
    if (!isComb){
      if (cur) clusters.push(cur);
      cur = ch;
    } else {
      cur += ch;
    }
  }
  if (cur) clusters.push(cur);

  const vowelIdx = [];
  for (let i=0;i<clusters.length;i++){
    const base = clusters[i][0].toLowerCase();
    if (vowels.has(base)) vowelIdx.push(i);
  }
  return {clusters, vowelIdx};
}

function addAcuteToCluster(cluster){
  // If already has an accent mark, leave it.
  const nfd = cluster.normalize('NFD');
  if (/[\u0300\u0301\u0342]/.test(nfd)) return cluster.normalize('NFC');
  return (nfd + combiningAcute).normalize('NFC');
}

function accentWord(word, where){
  // where: 'penult' or 'ultima'
  const {clusters, vowelIdx} = findVowelPositions(word);
  if (vowelIdx.length === 0) return word;
  const target = (where === 'penult')
    ? (vowelIdx.length >= 2 ? vowelIdx[vowelIdx.length-2] : vowelIdx[0])
    : vowelIdx[vowelIdx.length-1];

  clusters[target] = addAcuteToCluster(clusters[target]);
  return clusters.join('').normalize('NFC');
}

function endsWithRos(word){
  const w = stripCombining(word).toLowerCase();
  return w.endsWith('ρος');
}

function penultNucleus(word){
  // Very rough: take the vowel immediately before the final -ρος.
  const base = stripCombining(word).toLowerCase();
  if (!base.endsWith('ρος')) return null;
  const stem = base.slice(0, -3); // remove ρος
  // Find last vowel in stem
  for (let i=stem.length-1;i>=0;i--){
    const ch = stem[i];
    if ('αεηιουω'.includes(ch)){
      // Check for diphthong αι/ει/οι/υι/αυ/ευ/ου/ηυ (toy: only αι matters for this passage)
      if (ch === 'ι' && i>0 && stem[i-1] === 'α') return 'αι';
      return ch;
    }
  }
  return null;
}

function guessHerodian(word){
  const clean = normalizeGreekInput(word);
  const token = lastGreekToken(clean);
  if (!token) return {ok:false, msg:'Type a Greek word.'};
  if (!endsWithRos(token)){
    return {ok:false, msg:"This toy only guesses for words ending in -ρος."};
  }

  const pen = penultNucleus(token);
  // Simplified rules from the passage:
  // - penult υ (short) => barytone
  // - penult ω => barytone (esp. proper names; we don't detect that)
  // - penult αι => (passage continues; we just flag as "incomplete")
  // - otherwise => oxytone

  if (pen === 'αι'){
    return {
      ok:true,
      accent:'penult',
      label:'(partial) penult = αι → Herodian continues here… (toy defaults to barytone)'
    };
  }
  if (pen === 'υ'){
    return {ok:true, accent:'penult', label:'penult = υ → barytone (accent on penult)'};
  }
  if (pen === 'ω'){
    return {ok:true, accent:'penult', label:'penult = ω → barytone (often name-like forms)'};
  }
  return {ok:true, accent:'ultima', label:'otherwise → oxytone (accent on ultima)'};
}

function render(){
  const raw = inEl.value;
  const cleaned = normalizeGreekInput(raw);
  if (raw !== cleaned) inEl.value = cleaned;

  const token = lastGreekToken(cleaned);
  if (!token){
    outWord.textContent = '—';
    outRule.textContent = '—';
    return;
  }

  const g = guessHerodian(token);
  if (!g.ok){
    outWord.textContent = token;
    outRule.innerHTML = `<span class="bad">${g.msg}</span>`;
    return;
  }

  const unaccented = stripCombining(token);
  const accented = accentWord(unaccented, g.accent);
  outWord.textContent = accented;

  const pen = penultNucleus(token);
  const penShow = pen ? `<span class="mono">${pen}</span>` : '<span class="mono">?</span>';
  const kind = (g.accent === 'penult')
    ? `<span class="pill bary">barytone</span>`
    : `<span class="pill oxy">oxytone</span>`;

  outRule.innerHTML = `${kind} • penult nucleus: ${penShow} • ${g.label}`;
}

btnGuess.addEventListener('click', render);
btnClear.addEventListener('click', () => { inEl.value=''; inEl.focus(); render(); });
inEl.addEventListener('input', render);

// Practice chips (some from the passage; some contrast forms)
const practice = [
  'Συρος', 'Τυρος', 'Μυρος', 'Κυρος', 'Σκυρος', 'Δωρος',
  'πυρος', 'τυρος', 'χλωρος', 'μωρος', 'σωρος'
];

for (const w of practice){
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'chip';
  b.textContent = w;
  b.addEventListener('click', () => { inEl.value = w; inEl.focus(); render(); });
  chipsEl.appendChild(b);
}

render();

