const $ = (sel) => document.querySelector(sel);

// --- Polytonic helpers (combining marks) ---
const COMB = {
  acute: "\u0301",      //  ́
  grave: "\u0300",      //  ̀
  circumflex: "\u0342", //  ͂
  diaeresis: "\u0308",
};

function nfd(s){ return (s||"").normalize('NFD'); }
function nfc(s){ return (s||"").normalize('NFC'); }

function stripDiacritics(s){
  // Keep Greek letters; remove combining marks.
  return nfd(s).replace(/[\u0300-\u036f]/g, "");
}

function hasGreek(s){
  return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(s);
}

function isVowel(ch){
  return "αεηιουωΑΕΗΙΟΥΩ".includes(ch);
}

function syllabifyGreek(word){
  // Very rough syllabifier: split before each vowel-group (incl. diphthongs).
  // Returns array of syllable strings (in stripped form).
  const w = stripDiacritics(word);
  if(!w) return [];

  // Identify vowel groups.
  const diph = new Set(["αι","ει","οι","υι","αυ","ευ","ηυ","ου","ωυ"]);

  let parts = [];
  let i = 0;
  while(i < w.length){
    // find next vowel
    let start = i;
    while(start < w.length && !isVowel(w[start])) start++;
    if(start >= w.length){
      if(parts.length===0) parts.push(w);
      else parts[parts.length-1] += w.slice(i);
      break;
    }
    // attach consonants up to vowel to previous syllable if exists
    if(parts.length===0){
      parts.push(w.slice(i, start));
    } else {
      parts[parts.length-1] += w.slice(i, start);
      parts.push("");
    }

    // vowel group length 2 if diphthong
    let vg = w[start];
    if(start+1 < w.length){
      const two = w.slice(start, start+2);
      if(diph.has(two)) vg = two;
    }
    parts[parts.length-1] += vg;
    i = start + vg.length;
  }

  // Now we have chunks ending in vowel groups; distribute following consonants:
  // naive: keep consonants with current syllable unless next syllable exists.
  // (Already mostly handled above.)
  return parts.filter(p=>p.length>0);
}

function addAccentToVowelGroup(syllable, accentType){
  // Add combining mark to the first vowel in the syllable.
  const base = nfd(syllable);
  let out = "";
  let done = false;
  for(let i=0;i<base.length;i++){
    const ch = base[i];
    out += ch;
    if(!done && isVowel(ch)){
      out += COMB[accentType] || "";
      done = true;
    }
  }
  return nfc(out);
}

function accentWord(word, syllIndexFromEnd, accentType){
  // syllIndexFromEnd: 1=ultima, 2=penult, 3=antepenult
  const syl = syllabifyGreek(word);
  if(syl.length===0) return {accented: word, syl};
  const idx = syl.length - syllIndexFromEnd;
  if(idx < 0 || idx >= syl.length) return {accented: word, syl};
  const newSyl = syl.map((s,i)=> i===idx ? addAccentToVowelGroup(s, accentType) : s);
  return {accented: nfc(newSyl.join("")), syl};
}

// --- Toy logic based on the passage ---
const examples = [
  {w:"Σφαῖρος", note:"barytone (given)"},
  {w:"Σκαῖρος", note:"barytone (given)"},
  {w:"καιρός", note:"oxytone (given)"},
  {w:"θαιρός", note:"oxytone (given)"},
  {w:"δαῖρος", note:"double accentuation (mentioned)"},
  {w:"φλαῦρος", note:"αυ + animate → barytone"},
  {w:"σαῦρος", note:"αυ + animate → barytone"},
  {w:"καῦρος", note:"αυ + animate → barytone"},
  {w:"ταῦρος", note:"αυ + animate → barytone"},
  {w:"σταυρός", note:"note: inanimate"},
  {w:"μαυρός", note:"from ἀμαυρός"},
  {w:"εὖρος", note:"ευ barytone (rare)"},
  {w:"πλεῦρος", note:"ευ barytone (rare)"},
  {w:"λευρός", note:"adjective"},
  {w:"Νευρός", note:"ethnic name"},
  {w:"χοῖρος", note:"special: proparoxytone circumflex"},
  {w:"οὖρος", note:"ου barytone (wind)"},
  {w:"οὐρός", note:"distinction: oxytone"},
  {w:"Φροῦρος", note:"proper name"},
  {w:"φρουρός", note:"adjective"},
  {w:"κοῦρος", note:"ου barytone"},
  {w:"θοῦρος", note:"ου barytone"},
  {w:"λοῦρος", note:"ου barytone"},
  {w:"κηπουρός", note:"compound trisyllable → oxytone"},
  {w:"οἰκουρός", note:"compound trisyllable → oxytone"},
];

function detect(word){
  const raw = word.trim();
  const stripped = stripDiacritics(raw);
  const lower = stripped.toLowerCase();
  const syl = syllabifyGreek(raw);

  const endsRos = /ρος$/i.test(lower);
  const endsOs = /ος$/i.test(lower);

  // penult vowel group (rough): take second-to-last syllable and find its vowel group
  let penult = syl.length>=2 ? syl[syl.length-2].toLowerCase() : "";
  let penultVG = "";
  // find first vowel and maybe diphthong
  for(let i=0;i<penult.length;i++){
    if(isVowel(penult[i])){
      penultVG = penult[i];
      if(i+1<penult.length){
        const two = penult.slice(i,i+2);
        if(["αι","ει","οι","υι","αυ","ευ","ηυ","ου","ωυ"].includes(two)) penultVG = two;
      }
      break;
    }
  }

  return {raw, stripped, lower, syl, endsRos, endsOs, penultVG};
}

function suggest(word){
  const d = detect(word);
  const sylCount = d.syl.length;

  if(!d.raw){
    return {shape:"—", suggestion:"—", why:"Type a word above.", also:""};
  }
  if(!hasGreek(d.raw)){
    return {shape:"(no Greek detected)", suggestion:d.raw, why:"This toy expects Greek letters.", also:"Try: ταυρος, σταυρος, καιρος, χοιρος"};
  }

  // Special case: χοῖρος
  if(d.lower === "χοιρος" || nfd(d.raw).includes("χο") && d.lower.endsWith("οιρος")){
    // Herodian: proparoxytone circumflex (i.e., circumflex on antepenult)
    const acc = accentWord(d.raw, 3, "circumflex").accented;
    return {
      shape:`${sylCount} syllable(s), ends -ος, penult οι`,
      suggestion: acc,
      why:"Herodian singles out χοῖρος: the only disyllable in -ος with penult οι that is προπερισπώμενον (circumflex on the antepenult).",
      also:"Compare ordinary -ρος patterns: ταῦρος, οὖρος."
    };
  }

  // If trisyllabic compounds like κηπουρός / οἰκουρός: oxytone
  if(d.lower === "κηπουρος" || d.lower === "οικουρος" || d.lower.endsWith("πουρος") || d.lower.endsWith("κουρος")){
    if(sylCount>=3){
      const acc = accentWord(d.raw, 1, "acute").accented;
      return {
        shape:`${sylCount} syllable(s), looks like compound in -ουρός`,
        suggestion: acc,
        why:"Herodian: κηπουρός and οἰκουρός, as compound trisyllables with long initial, are oxytone (acute on the ultima).",
        also:"Try: κηπουρος, οικουρος"
      };
    }
  }

  // Main: disyllables in -ρος
  if(d.endsRos && sylCount===2){
    const pen = d.penultVG;

    // αι: examples show barytone for Σφαῖρος/Σκαῖρος, but καιρός/θαιρός oxytone.
    if(pen === "αι"){
      // If starts with σφ/σκ -> barytone; else oxytone (toy heuristic)
      const isSphSk = /^σφ|^σκ/.test(d.lower);
      const acc = accentWord(d.raw, 2, isSphSk ? "grave" : "acute").accented;
      return {
        shape:"2 syllables, -ρος, penult αι",
        suggestion: acc,
        why: isSphSk
          ? "Passage gives Σφαῖρος, Σκαῖρος as barytone (grave on the penult in citation)."
          : "Passage contrasts: if not like Σφαῖρος/Σκαῖρος, then oxytone (καιρός, θαιρός). This toy guesses oxytone unless it looks like those names.",
        also:"Try: Σφαῖρος, Σκαῖρος, καιρός, θαιρός"
      };
    }

    // αυ: animate -> barytone
    if(pen === "αυ"){
      const anim = document.querySelector('input[name="anim"]:checked')?.value || "animate";
      const bary = (anim === "animate");
      const acc = accentWord(d.raw, bary ? 2 : 1, bary ? "grave" : "acute").accented;
      return {
        shape:"2 syllables, -ρος, penult αυ",
        suggestion: acc,
        why: bary
          ? "Herodian: -ρος disyllables with penult αυ, when applied to animate beings, are barytone (e.g. φλαῦρος, σαῦρος, καῦρος)."
          : "If treated as inanimate/other usage, this toy flips to oxytone just to make the toggle do something (not a full rule!).",
        also:"Try: φλαυρος, σαυρος, καυρος, ταυρος, σταυρος"
      };
    }

    // ευ: rarely barytone; we’ll default to oxytone unless in a small whitelist
    if(pen === "ευ"){
      const whitelist = new Set(["ευρος","πλευρος"]);
      const bary = whitelist.has(d.lower);
      const acc = accentWord(d.raw, bary ? 2 : 1, bary ? "grave" : "acute").accented;
      return {
        shape:"2 syllables, -ρος, penult ευ",
        suggestion: acc,
        why: bary
          ? "Herodian notes rare barytones with ευ: εὖρος, πλεῦρος."
          : "Otherwise this toy defaults to oxytone for ευ-penult -ρος (since barytones are said to be rare).",
        also:"Try: εὖρος, πλεῦρος, λευρός, Νευρός"
      };
    }

    // ου: usually barytone unless by distinction
    if(pen === "ου"){
      const dist = $('#dist')?.checked;
      const acc = accentWord(d.raw, dist ? 1 : 2, dist ? "acute" : "grave").accented;
      return {
        shape:"2 syllables, -ρος, penult ου",
        suggestion: acc,
        why: dist
          ? "Herodian: -ουρος disyllables are barytone unless ‘by distinction’ (διαστολή). The toggle forces oxytone to model οὖρος vs οὐρός."
          : "Herodian: simple disyllables in -ρος with penult ου are barytone (e.g. κοῦρος, θοῦρος, λοῦρος).",
        also:"Try: οὖρος / οὐρός, κοῦρος, θοῦρος, λοῦρος"
      };
    }

    // default for other penults
    const acc = accentWord(d.raw, 1, "acute").accented;
    return {
      shape:`2 syllables, -ρος, penult ${pen || "?"}`,
      suggestion: acc,
      why:"No specific pattern from the passage recognized; toy defaults to oxytone (acute on ultima).",
      also:"Try a clearer case: ταυρος, ευρος, ουρος, χοιρος"
    };
  }

  // Fallback: show syllables and do nothing
  return {
    shape:`${d.syl.length} syllable(s) (rough), ${d.endsRos?"ends -ρος":""}${(!d.endsRos && d.endsOs)?"ends -ος":""}`.trim() || "(unclassified)",
    suggestion: d.raw,
    why:"This toy mainly targets disyllables in -ρος (and χοῖρος).",
    also:"Try: ταυρος, οὐρος, εὖρος, χοιρος"
  };
}

function render(){
  const w = $('#inp').value;
  const res = suggest(w);
  $('#shape').textContent = res.shape;
  $('#suggest').textContent = res.suggestion;
  $('#why').textContent = res.why;
  $('#also').textContent = res.also;
}

function mountChips(){
  const box = $('#chips');
  box.innerHTML = "";
  examples.forEach(ex => {
    const b = document.createElement('button');
    b.className = 'chip';
    b.type = 'button';
    b.textContent = ex.w;
    b.title = ex.note;
    b.addEventListener('click', () => {
      $('#inp').value = ex.w;
      // set toggles to sensible defaults for some examples
      if(stripDiacritics(ex.w).toLowerCase().includes('αυρ')){
        document.querySelector('input[name="anim"][value="animate"]').checked = true;
      }
      if(stripDiacritics(ex.w).toLowerCase() === 'ουρος'){
        $('#dist').checked = false;
      }
      if(stripDiacritics(ex.w).toLowerCase() === 'ουρος' || stripDiacritics(ex.w).toLowerCase() === 'ουρος'){
        // no-op
      }
      render();
      $('#inp').focus();
    });
    box.appendChild(b);
  });
}

$('#btn').addEventListener('click', render);
$('#rnd').addEventListener('click', () => {
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#inp').value = ex.w;
  render();
});
$('#inp').addEventListener('keydown', (e)=>{ if(e.key==='Enter') render(); });
for(const el of document.querySelectorAll('input[name="anim"], #dist')){
  el.addEventListener('change', render);
}

mountChips();
render();

