const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const outMain = $('#outMain');
const outDetails = $('#outDetails');
const syllBox = $('#syll');
const gameMsg = $('#gameMsg');
const scoreEl = $('#score');

let score = 0;
let current = null; // {word, norm, syllables, targetIndex, suggested}

// --- Greek helpers ---
const combining = /[\u0300-\u036f\u1dc0-\u1dff]/g; // includes Greek combining marks

function stripCombining(s){
  return s.normalize('NFD').replace(combining,'').normalize('NFC');
}

function stripPunctSpace(s){
  return s.replace(/[\s··.,;:!?"'“”‘’()\[\]{}<>]/g,'');
}

function endsWithRos(norm){
  return norm.endsWith('ρος') || norm.endsWith('ΡΟΣ') || norm.toLowerCase().endsWith('ρος');
}

function isVowel(ch){
  return 'αεηιουωάέήίόύώΑΕΗΙΟΥΩΆΈΉΊΌΎΏ'.includes(ch);
}

function syllabifyRough(word){
  // Very rough: split before each vowel group; keep consonants with following vowel.
  // Handles diphthongs crudely by treating consecutive vowels as one nucleus.
  const w = word;
  const parts = [];
  let i = 0;
  while(i < w.length){
    // find next vowel
    let start = i;
    while(i < w.length && !isVowel(w[i])) i++;
    if(i >= w.length){
      if(parts.length) parts[parts.length-1] += w.slice(start);
      else parts.push(w.slice(start));
      break;
    }
    // i is at vowel; include preceding consonants in this syllable
    let sylStart = start;
    // consume vowel group
    let j = i;
    while(j < w.length && isVowel(w[j])) j++;
    // now j is after vowel group
    // lookahead consonants until next vowel; keep them for next syllable, but leave one consonant as coda? too hard.
    // We'll attach all following consonants up to next vowel to this syllable EXCEPT if there is another vowel later, keep consonants for next onset.
    let k = j;
    while(k < w.length && !isVowel(w[k])) k++;
    // If there is another vowel later, keep consonants for next syllable onset.
    const hasNextVowel = k < w.length;
    const sylEnd = hasNextVowel ? j : w.length;
    parts.push(w.slice(sylStart, sylEnd));
    i = sylEnd;
  }
  // cleanup empties
  return parts.filter(p => p.length);
}

function penultVowel(norm){
  // Find vowel in penult syllable nucleus (rough): syllabify and take last vowel in penult syllable.
  const syls = syllabifyRough(norm);
  if(syls.length < 2) return {v:null, syls};
  const pen = syls[syls.length-2];
  const vowels = [...pen].filter(isVowel);
  return {v: vowels.length ? vowels[vowels.length-1] : null, syls};
}

function addAcuteToAntepenult(original){
  // Put an acute on the first vowel of the antepenult syllable (rough).
  // If already accented, we first strip accents.
  const base = stripCombining(original);
  const norm = base; // keep case
  const {syls} = penultVowel(norm);
  if(syls.length < 3) return {suggested: base, syls, targetIndex: null};
  const targetIndex = syls.length - 3;
  const target = syls[targetIndex];
  // find first vowel position in target syllable
  let pos = -1;
  for(let i=0;i<target.length;i++){
    if(isVowel(target[i])){ pos = i; break; }
  }
  if(pos === -1) return {suggested: base, syls, targetIndex};

  const acuteMap = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };
  const chars = [...target];
  const v = chars[pos];
  chars[pos] = acuteMap[v] || v;
  const newTarget = chars.join('');
  const newSyls = syls.slice();
  newSyls[targetIndex] = newTarget;
  return {suggested: newSyls.join(''), syls: newSyls, targetIndex};
}

function reduplicationVibe(norm){
  // Fun heuristic: first two syllables start with same consonant cluster or same first 2 letters.
  const syls = syllabifyRough(norm.toLowerCase());
  if(syls.length < 2) return false;
  const a = syls[0];
  const b = syls[1];
  const a2 = stripCombining(a).slice(0,2);
  const b2 = stripCombining(b).slice(0,2);
  if(a2 && a2 === b2) return true;
  // also barbaros-like: pattern CVCV where first consonant repeats
  const firstCon = stripCombining(a).match(/^[^αεηιουω]+/);
  const secondCon = stripCombining(b).match(/^[^αεηιουω]+/);
  if(firstCon && secondCon && firstCon[0] === secondCon[0] && firstCon[0].length>0) return true;
  return false;
}

function analyzeAndRender(){
  const raw = inp.value;
  const cleaned = stripPunctSpace(raw);
  if(!cleaned){
    outMain.textContent = '—';
    outDetails.textContent = '';
    syllBox.innerHTML = '';
    gameMsg.textContent = '';
    current = null;
    return;
  }

  const base = stripCombining(cleaned);
  const norm = base; // keep as-is
  const lower = norm.toLowerCase();

  const ros = endsWithRos(lower);
  const {v: penV, syls} = penultVowel(norm);
  const sylCount = syls.length;
  const penIsAlpha = penV ? stripCombining(penV).toLowerCase() === 'α' : false;

  const {suggested, targetIndex} = addAcuteToAntepenult(norm);

  const matchesHerodian = ros && sylCount >= 3 && penIsAlpha;
  const vibe = reduplicationVibe(norm);

  // Output main
  if(matchesHerodian){
    outMain.textContent = suggested;
  } else {
    outMain.textContent = base;
  }

  // Details tags
  const tags = [];
  tags.push(`<span class="tag ${ros?'good':'bad'}">ends -ρος: ${ros?'yes':'no'}</span>`);
  tags.push(`<span class="tag ${sylCount>=3?'good':'warn'}">syllables≈${sylCount}</span>`);
  tags.push(`<span class="tag ${penIsAlpha?'good':'warn'}">penult vowel≈${penV||'?'}</span>`);
  if(vibe) tags.push(`<span class="tag warn">reduplication vibe</span>`);
  tags.push(`<span class="tag ${matchesHerodian?'good':'warn'}">rule match: ${matchesHerodian?'likely':'unclear'}</span>`);

  const expl = matchesHerodian
    ? `Toy rule applied: proparoxytone → acute on antepenult (roughly).`
    : `Toy rule not applied (maybe not -ρος, not ≥3 syllables, or penult not α).`;

  outDetails.innerHTML = `${tags.join(' ')}<div class="mini">${expl}</div>`;

  // Game setup
  current = {
    word: cleaned,
    norm,
    syllables: syls,
    targetIndex: (sylCount>=3 ? sylCount-3 : null),
    suggested: matchesHerodian ? suggested : base,
    matchesHerodian
  };

  renderGame();
}

function renderGame(){
  syllBox.innerHTML = '';
  gameMsg.textContent = '';
  if(!current) return;

  const syls = syllabifyRough(stripCombining(current.suggested));
  // If we applied accent, syllabify again on stripped version; keep display syllables from suggested by slicing proportionally is hard.
  // We'll display syllables from stripped version but show the full suggested above.

  if(syls.length < 3){
    gameMsg.textContent = 'Need at least 3 syllables for an antepenult.';
    return;
  }

  const target = syls.length - 3;

  syls.forEach((s, idx) => {
    const b = document.createElement('button');
    b.className = 'sylBtn';
    b.type = 'button';
    b.textContent = s;
    b.addEventListener('click', () => {
      // reset classes
      [...syllBox.querySelectorAll('.sylBtn')].forEach(x => x.classList.remove('good','bad'));
      if(idx === target){
        b.classList.add('good');
        score += 1;
        scoreEl.textContent = String(score);
        gameMsg.innerHTML = `<span class="tag good">Correct</span> Antepenult = 3rd from end.`;
      } else {
        b.classList.add('bad');
        score = Math.max(0, score - 1);
        scoreEl.textContent = String(score);
        gameMsg.innerHTML = `<span class="tag bad">Nope</span> Try the 3rd syllable from the end.`;
      }
    });
    syllBox.appendChild(b);
  });

  const note = current.matchesHerodian
    ? `Click the antepenult syllable for the suggested proparoxytone.`
    : `Even if the rule is unclear, you can still practice: pick the antepenult.`;
  gameMsg.textContent = note;
}

// UI wiring
$('#go').addEventListener('click', analyzeAndRender);
$('#clear').addEventListener('click', () => { inp.value=''; analyzeAndRender(); inp.focus(); });
inp.addEventListener('keydown', (e) => { if(e.key === 'Enter') analyzeAndRender(); });
inp.addEventListener('input', () => { /* live, but gentle */ analyzeAndRender(); });

document.querySelectorAll('.chip').forEach(btn => {
  btn.addEventListener('click', () => {
    inp.value = btn.getAttribute('data-fill');
    analyzeAndRender();
    inp.focus();
  });
});

// initial
analyzeAndRender();

