const $ = (sel) => document.querySelector(sel);

const input = $('#w');
const accentedEl = $('#accented');
const ruleEl = $('#rule');
const diagEl = $('#diag');
const chipsEl = $('#chips');
const examplesEl = $('#examples');

// --- Utilities: Greek normalization & accent handling ---

// Remove combining marks (tonos/oxia, varia, perispomeni, breathings, diaeresis, iota subscript, etc.)
function stripDiacritics(s){
  return (s || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'')
    // also strip Greek tonos characters that may be precomposed but survive weird input
    .normalize('NFC');
}

function hasAnyGreek(s){
  return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(s);
}

function toGreekish(s){
  // Keep Greek letters, apostrophes, hyphens, spaces; drop other punctuation.
  return (s||'').replace(/[^\u0370-\u03FF\u1F00-\u1FFF\s'’-]/g,'').trim();
}

const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

function isVowel(ch){
  return vowels.has(ch);
}

function countSyllables(plain){
  // Very rough: count vowel groups; treat diphthongs as one group.
  const s = plain;
  const lower = s.toLowerCase();
  const diph = ['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ωυ'];
  let i=0, n=0;
  while(i<lower.length){
    const two = lower.slice(i,i+2);
    if(diph.includes(two)) { n++; i+=2; continue; }
    if(isVowel(lower[i])) { n++; i++; while(i<lower.length && !isVowel(lower[i])) i++; continue; }
    i++;
  }
  return n;
}

function vowelPositions(plain){
  // Return indices of vowel nuclei (approx), using diphthong detection.
  const lower = plain.toLowerCase();
  const diph = ['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ωυ'];
  const pos=[];
  let i=0;
  while(i<lower.length){
    const two = lower.slice(i,i+2);
    if(diph.includes(two)) { pos.push(i); i+=2; continue; }
    if(isVowel(lower[i])) { pos.push(i); i++; continue; }
    i++;
  }
  return pos;
}

function applyAcuteOnSyllable(plain, whichFromEnd){
  // whichFromEnd: 1=ultima, 2=penult, 3=antepenult
  const pos = vowelPositions(plain);
  if(pos.length === 0) return plain;
  const idx = pos.length - whichFromEnd;
  if(idx < 0) return plain;
  const insertAt = pos[idx];
  // Insert combining acute after the vowel nucleus start.
  const acute = '\u0301';
  const out = plain.slice(0, insertAt+1) + acute + plain.slice(insertAt+1);
  return out.normalize('NFC');
}

function startsWithReduplication(plain){
  // Toy heuristic: first two letters identical (κάρχαρος has κ-αρ-χ-αρ... not identical),
  // so also allow pattern CVCV with same consonant repeated: καρ-χαρ (k...k?)
  // We'll implement a simple check: first consonant repeats within first 4 letters.
  const s = plain.toLowerCase();
  const letters = [...s].filter(ch => /[\u0370-\u03FF\u1F00-\u1FFF]/.test(ch));
  if(letters.length < 4) return false;
  const first = letters[0];
  // If first is vowel, ignore.
  if(isVowel(first)) return false;
  return letters.slice(1,5).includes(first);
}

function penultHasAlpha(plain){
  // Approx: find penult vowel nucleus and see if it's alpha or begins with alpha in diphthong.
  const lower = plain.toLowerCase();
  const pos = vowelPositions(lower);
  if(pos.length < 2) return false;
  const pen = pos[pos.length-2];
  const ch = lower[pen];
  return ch === 'α';
}

function approxLongFirstSyllable(plain){
  // Herodian: trisyllables in -τερος with long initial syllable -> proparoxytone.
  // Toy approximation: first vowel is η/ω or a diphthong (αι/ει/οι/ου/αυ/ευ/ηυ).
  const lower = plain.toLowerCase();
  const diph = ['αι','ει','οι','ου','αυ','ευ','ηυ','ωυ','υι'];
  for(let i=0;i<lower.length;i++){
    if(isVowel(lower[i])){
      const two = lower.slice(i,i+2);
      if(diph.includes(two)) return true;
      if(lower[i]==='η' || lower[i]==='ω') return true;
      return false;
    }
  }
  return false;
}

// --- Rule engine inspired by the passage ---

const exceptions = new Map([
  ['φλυαρος', {accent:3, note:'Exception in Herodian: φλύαρος is proparoxytone.'}],
  ['εγκαρος', {accent:3, note:'Exception in Herodian: ἔγκαρος is proparoxytone.'}],
  ['καρχαρος', {accent:2, note:'Herodian notes initial reduplication; toy avoids oxytone here.'}],
  ['υστερος', {accent:3, note:'Herodian treats ὕστερος as special (from ὑπότερος by syncope).'}],
  ['δευτερος', {accent:3, note:'Common proparoxytone: δεύτερος.'}],
  ['ικτερος', {accent:3, note:'Common proparoxytone: ἴκτερος.'}],
  ['καρτερος', {accent:1, note:'Herodian: καρτερός is oxytone (from κρατερός).'}],
  ['ποτερος', {accent:2, note:'Interrogative/relational -τερος: paroxytone (πότερος).'}],
  ['πότερος', {accent:2, note:'Interrogative/relational -τερος: paroxytone (πότερος).'}],
  ['προτερος', {accent:2, note:'Interrogative/relational -τερος: paroxytone (πρότερος).'}],
  ['ετερος', {accent:2, note:'Interrogative/relational -τερος: paroxytone (ἕτερος).'}],
  ['εκατερος', {accent:2, note:'Interrogative/relational -τερος: paroxytone (ἑκάτερος).'}],
]);

function suggestSyncopeSigma(plain){
  const lower = plain.toLowerCase();
  // toy: θεοφατον -> θεσφατον, θεοεικελον -> θεσκελον
  if(lower === 'θεοφατον') return 'θεσφατον';
  if(lower === 'θεοεικελον') return 'θεσκελον';
  return null;
}

function guessAccent(plain){
  const lower = plain.toLowerCase();
  const syll = countSyllables(lower);
  const endsRos = lower.endsWith('ρος');
  const endsTeros = lower.endsWith('τερος');

  // direct exceptions
  const key = stripDiacritics(lower);
  if(exceptions.has(key)){
    const ex = exceptions.get(key);
    return {accent: ex.accent, why: ex.note, tags:['exception']};
  }

  // -ρος rule
  if(endsRos && syll >= 3 && penultHasAlpha(lower)){
    if(startsWithReduplication(lower)){
      return {accent:2, why:"Looks like initial reduplication; toy avoids oxytone (Herodian: unless reduplicated).", tags:['-ρος','reduplication?']};
    }
    return {accent:1, why:"-ρος (≥3 syllables) with penult α → usually oxytone (ultima) in Herodian.", tags:['-ρος','penult α']};
  }

  // -τερος rules
  if(endsTeros){
    if(syll === 3){
      if(approxLongFirstSyllable(lower)){
        return {accent:3, why:"Trisyllabic -τερος with (approx.) long first syllable → proparoxytone (antepenult).", tags:['-τερος','3 syllables','long first?']};
      }
      // default for trisyllabic -τερος: proparoxytone is common, but Herodian highlights special paroxytone set.
      return {accent:3, why:"Trisyllabic -τερος: toy defaults to proparoxytone unless it matches the interrogative/relational set.", tags:['-τερος','3 syllables']};
    }
    if(syll > 3){
      return {accent:3, why:"Comparative-like -τερος with >3 syllables → proparoxytone (antepenult).", tags:['-τερος','>3 syllables']};
    }
  }

  // fallback: keep as-is but offer a gentle guess
  if(syll >= 3){
    return {accent:2, why:"Fallback guess: paroxytone (penult). Use the force-buttons to explore.", tags:['fallback']};
  }
  return {accent:1, why:"Very short word: toy puts accent on ultima by default.", tags:['fallback']};
}

function render(wordRaw, forcedAccent=null){
  const cleaned = toGreekish(wordRaw);
  if(!cleaned){
    accentedEl.textContent = '—';
    ruleEl.textContent = 'Type a Greek word and click “Accent it”.';
    diagEl.textContent = '';
    chipsEl.innerHTML = '';
    return;
  }
  if(!hasAnyGreek(cleaned)){
    accentedEl.textContent = cleaned;
    ruleEl.textContent = 'No Greek letters detected. Try Greek (e.g. χαλαρος).';
    diagEl.textContent = '';
    chipsEl.innerHTML = '';
    return;
  }

  const plain = stripDiacritics(cleaned);
  const guess = guessAccent(plain);
  const accentWhich = forcedAccent ?? guess.accent;
  const accented = applyAcuteOnSyllable(plain, accentWhich);

  accentedEl.textContent = accented;
  ruleEl.textContent = forcedAccent ? `Forced accent: ${accentName(accentWhich)}.` : guess.why;

  const syll = countSyllables(plain);
  const syn = suggestSyncopeSigma(plain);

  const lines = [];
  lines.push(`input (as typed): ${cleaned}`);
  lines.push(`plain (no diacritics): ${plain}`);
  lines.push(`syllables (toy): ${syll}`);
  lines.push(`endswith: ${plain.toLowerCase().endsWith('τερος') ? '-τερος' : (plain.toLowerCase().endsWith('ρος') ? '-ρος' : '—')}`);
  lines.push(`penult has α (toy): ${penultHasAlpha(plain)}`);
  lines.push(`initial reduplication? (toy): ${startsWithReduplication(plain)}`);
  lines.push(`first syllable long? (toy): ${approxLongFirstSyllable(plain)}`);
  if(syn) lines.push(`syncope→σ suggestion: ${plain} → ${syn}`);
  diagEl.textContent = lines.join('\n');

  const tags = new Set(guess.tags || []);
  if(syn) tags.add('syncope→σ');
  chipsEl.innerHTML = '';
  [...tags].forEach(t => {
    const span = document.createElement('span');
    span.className = 'chip';
    span.innerHTML = `<b>tag</b> ${escapeHtml(t)}`;
    chipsEl.appendChild(span);
  });
}

function accentName(which){
  if(which===1) return 'oxytone (ultima)';
  if(which===2) return 'paroxytone (penult)';
  if(which===3) return 'proparoxytone (antepenult)';
  return '—';
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

// --- Examples ---
const examples = [
  {g:'χαλαρος', note:'-ρος, penult α → oxytone (χαλαρός)'},
  {g:'λιπαρος', note:'-ρος, penult α → oxytone (λιπαρός)'},
  {g:'φλυαρος', note:'exception → φλύαρος'},
  {g:'εγκαρος', note:'exception → ἔγκαρος'},
  {g:'φερτερος', note:'-τερος trisyllable → φέρτερος'},
  {g:'βελτερος', note:'-τερος trisyllable → βέλτερος'},
  {g:'ποτερος', note:'interrogative set → πότερος'},
  {g:'εκατερος', note:'interrogative/relational → ἑκάτερος'},
  {g:'ημετερος', note:'>3 syllables → ἡμέτερος'},
  {g:'θεοφατον', note:'syncope→σ: θεόφατον → θέσφατον'},
  {g:'θεοεικελον', note:'syncope→σ: θεοείκελον → θέσκελον'},
];

function renderExamples(){
  examplesEl.innerHTML='';
  for(const ex of examples){
    const row = document.createElement('div');
    row.className='ex';
    const left = document.createElement('div');
    left.innerHTML = `<code>${escapeHtml(ex.g)}</code><div class="hint">${escapeHtml(ex.note)}</div>`;
    left.querySelector('.hint').style.color = 'var(--faint)';
    left.querySelector('.hint').style.fontSize = '12px';
    const btn = document.createElement('button');
    btn.type='button';
    btn.textContent='Use';
    btn.addEventListener('click', () => { input.value = ex.g; render(input.value); input.focus(); });
    row.appendChild(left);
    row.appendChild(btn);
    examplesEl.appendChild(row);
  }
}

// --- Events ---
$('#go').addEventListener('click', () => render(input.value));
$('#clear').addEventListener('click', () => { input.value=''; render(''); input.focus(); });
input.addEventListener('keydown', (e) => { if(e.key==='Enter') render(input.value); });

$('#ultima').addEventListener('click', () => render(input.value, 1));
$('#penult').addEventListener('click', () => render(input.value, 2));
$('#antepenult').addEventListener('click', () => render(input.value, 3));

renderExamples();
render('');

