:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --card:#1d2136;
  --ink:#e9ecff;
  --muted:#b8bde6;
  --faint:#7f86c7;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --bad:#fb7185;
  --good:#34d399;
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
}

*{box-sizing:border-box}

.wrap{
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, "Noto Sans", "DejaVu Sans", sans-serif;
  color:var(--ink);
  background:linear-gradient(180deg, #0b0d18, var(--bg));
  padding:18px;
  border-radius:16px;
  max-width:980px;
  margin:0 auto;
  border:1px solid rgba(255,255,255,.08);
}

.top{display:flex; gap:14px; align-items:flex-start; justify-content:space-between; margin-bottom:14px;}

h1{font-size:18px; margin:0 0 6px 0; letter-spacing:.2px}
.sub{margin:0; color:var(--muted); font-size:13px; line-height:1.35}

.panel{background:rgba(255,255,255,.03); border:1px solid rgba(255,255,255,.08); border-radius:14px; padding:14px;}

.row{display:flex; gap:10px; align-items:center; flex-wrap:wrap}
.row.small{margin-top:10px}

.lab{font-size:12px; color:var(--muted); min-width:92px}

.inp{
  flex:1;
  min-width:260px;
  padding:10px 12px;
  border-radius:12px;
  border:1px solid rgba(255,255,255,.12);
  background:var(--panel);
  color:var(--ink);
  outline:none;
  font-size:16px;
}
.inp:focus{border-color:rgba(125,211,252,.55); box-shadow:0 0 0 3px rgba(125,211,252,.15)}

.btn{
  padding:10px 12px;
  border-radius:12px;
  border:1px solid rgba(255,255,255,.14);
  background:linear-gradient(180deg, rgba(125,211,252,.18), rgba(167,139,250,.12));
  color:var(--ink);
  cursor:pointer;
  font-weight:600;
}
.btn:hover{border-color:rgba(255,255,255,.22)}
.btn:active{transform:translateY(1px)}
.btn.ghost{background:transparent}

.hint{color:var(--muted); font-size:12px; line-height:1.35}
.mono{font-family:var(--mono)}

.grid{display:grid; grid-template-columns: 1.2fr 1fr; gap:12px; margin-top:12px}
@media (max-width: 860px){.grid{grid-template-columns:1fr}}

.card{
  background:var(--card);
  border:1px solid rgba(255,255,255,.08);
  border-radius:14px;
  padding:12px;
}
.card h2{margin:0 0 8px 0; font-size:13px; color:var(--muted); font-weight:700; letter-spacing:.2px}

.out{
  font-size:28px;
  padding:10px 12px;
  border-radius:12px;
  background:rgba(0,0,0,.18);
  border:1px solid rgba(255,255,255,.08);
  min-height:56px;
  display:flex;
  align-items:center;
  gap:10px;
}

.meta{margin-top:8px; color:var(--faint); font-size:12px; line-height:1.35}

.knobs{display:flex; flex-direction:column; gap:8px}
.chk{font-size:13px; color:var(--ink)}
.chk input{transform:translateY(1px)}

.mini{margin:10px 0 0 0; color:var(--muted); font-size:12px; line-height:1.35}

.chips{display:flex; flex-wrap:wrap; gap:8px}
.chip{
  font-family:var(--mono);
  font-size:13px;
  padding:7px 10px;
  border-radius:999px;
  border:1px solid rgba(255,255,255,.12);
  background:rgba(0,0,0,.18);
  cursor:pointer;
  user-select:none;
}
.chip:hover{border-color:rgba(125,211,252,.45)}

.tag{font-family:var(--mono); font-size:12px; padding:2px 8px; border-radius:999px; border:1px solid rgba(255,255,255,.12); color:var(--muted)}
.tag.good{border-color:rgba(52,211,153,.35); color:rgba(52,211,153,.95)}
.tag.bad{border-color:rgba(251,113,133,.35); color:rgba(251,113,133,.95)}

details{margin-top:12px}
summary{cursor:pointer; color:var(--muted); font-weight:650}
.explain{color:var(--muted); font-size:12px; line-height:1.45; margin-top:8px}
.explain ol{margin:6px 0 0 18px; padding:0}

.foot{margin-top:10px}

