(() => {
  const $ = (sel, root=document) => root.querySelector(sel);

  const inp = $('#inp');
  const outMain = $('#outMain');
  const outMeta = $('#outMeta');
  const btnGo = $('#btnGo');
  const btnClear = $('#btnClear');
  const btnDemo = $('#btnDemo');
  const chips = $('#chips');

  const optProper = $('#optProper');
  const optMonogenes = $('#optMonogenes');
  const optTribrach = $('#optTribrach');
  const optShowSyll = $('#optShowSyll');

  const samples = [
    {w:'τρυφερος', note:'-ερος, tribrach adjective → often oxytone'},
    {w:'γοερος', note:'-ερος, tribrach adjective → oxytone'},
    {w:'σταθερος', note:'-ερος, tribrach adjective → oxytone'},
    {w:'πενθερος', note:'-ερος, tribrach adjective → oxytone'},
    {w:'αριστερος', note:'-ερος with τ before ε (…τερ-) → exception-ish'},
    {w:'δεξιτερος', note:'-ερος with τ before ε (…τερ-) → exception-ish'},
    {w:'Αμφοτερος', note:'proper name reading → oxytone (Ἀμφοτερός)'},
    {w:'αμφοτερος', note:'adjectival reading → not necessarily oxytone'},
    {w:'Τερμερος', note:'monogenes/proper -ερος >2 syllables → barytone'},
    {w:'Συβερος', note:'place-name -ερος → barytone'},
    {w:'Ωλερος', note:'place-name -ερος → barytone'},
    {w:'ιμερος', note:'often barytone in the passage'},
    {w:'ομηρος', note:'-ηρος >2 syllables → proparoxytone'},
    {w:'σιδηρος', note:'-ηρος >2 syllables → proparoxytone'},
    {w:'Αβδηρος', note:'place-name -ηρος → proparoxytone'},
  ];

  function makeChips(){
    chips.innerHTML = '';
    for(const s of samples){
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'chip';
      b.textContent = s.w;
      b.title = s.note;
      b.addEventListener('click', () => {
        inp.value = s.w;
        // quick heuristic: capital initial suggests proper name
        optProper.checked = /^[Α-Ω]/.test(s.w);
        // monogenes toggle for some known place-name-ish samples
        optMonogenes.checked = /Τερμερος|Συβερος|Ωλερος/.test(s.w);
        run();
        inp.focus();
      });
      chips.appendChild(b);
    }
  }

  // --- Greek helpers ---
  const COMBINING = /[\u0300-\u036f]/g;

  function stripDiacritics(s){
    return s.normalize('NFD').replace(COMBINING,'').normalize('NFC');
  }

  function normalizeGreek(s){
    return stripDiacritics(s)
      .replace(/[’']/g,'')
      .replace(/\s+/g,' ')
      .trim();
  }

  function isGreekLetter(ch){
    return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(ch);
  }

  function tokenizeWords(s){
    // keep Greek sequences as tokens
    const out = [];
    let cur = '';
    for(const ch of s){
      if(isGreekLetter(ch)) cur += ch;
      else {
        if(cur) out.push(cur);
        cur = '';
      }
    }
    if(cur) out.push(cur);
    return out;
  }

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

  function splitSyllables(word){
    // very rough: split before each vowel group, attach preceding consonants
    const w = word;
    const syl = [];
    let i = 0;
    while(i < w.length){
      // onset
      let onset = '';
      while(i < w.length && !vowels.has(w[i])){ onset += w[i]; i++; }
      if(i >= w.length){
        if(syl.length) syl[syl.length-1] += onset;
        else if(onset) syl.push(onset);
        break;
      }
      // nucleus: vowel group (treat diphthongs crudely)
      let nuc = w[i]; i++;
      if(i < w.length){
        const pair = nuc + w[i];
        if(['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ΑΙ','ΕΙ','ΟΙ','ΥΙ','ΑΥ','ΕΥ','ΟΥ','ΗΥ'].includes(pair)){
          nuc = pair; i++;
        }
      }
      syl.push(onset + nuc);
    }
    // coda distribution: move consonants between vowels to next syllable except last
    // already mostly handled by onset collection; but clusters after vowel are currently in next onset.
    return syl.filter(x => x.length);
  }

  function addAcuteToVowelGroup(syl){
    // add tonos to the last vowel of the syllable nucleus
    // map base vowel to tonos vowel
    const map = {
      'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
      'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
    };
    // find last vowel char in syllable
    const chars = [...syl];
    for(let i=chars.length-1;i>=0;i--){
      const ch = chars[i];
      if(map[ch]){ chars[i] = map[ch]; return chars.join(''); }
    }
    return syl;
  }

  function accentWord(word, accentIndexFromEnd){
    const syl = splitSyllables(word);
    if(syl.length === 0) return {word, syl};
    const idx = syl.length - accentIndexFromEnd;
    const safeIdx = Math.max(0, Math.min(syl.length-1, idx));
    syl[safeIdx] = addAcuteToVowelGroup(syl[safeIdx]);
    return {word: syl.join(''), syl};
  }

  function endsWithEros(w){
    return /ερος$/i.test(w);
  }
  function endsWithHeros(w){
    return /ηρος$/i.test(w);
  }
  function hasTauBeforeE(w){
    // ...τερoς pattern (tau immediately before epsilon of -ερος)
    return /τερo?ς$/i.test(w.replace('ο','o')) || /τερος$/i.test(w);
  }

  function decideAccent(wNorm, opts){
    const w = wNorm;
    const syl = splitSyllables(w);
    const n = syl.length;

    const info = {
      kind: 'unknown',
      syllables: syl,
      rule: '',
      accentFromEnd: 2,
      tags: []
    };

    if(endsWithEros(w)){
      info.kind = '-ερος';
      const tau = /τερo?ς$/i.test(w.replace('ο','o')) || /τερος$/i.test(w);
      if(opts.proper){
        info.accentFromEnd = 1; // oxytone
        info.rule = 'Proper-name reading → oxytone (acute on ultima), like Ἀμφοτερός.';
        info.tags.push({t:'proper', cls:'good'});
      } else if(opts.monogenes){
        info.accentFromEnd = 3; // barytone-ish (antepenult)
        info.rule = 'Monogenes/proper -ερος (>2 syllables) → barytone (accent earlier).';
        info.tags.push({t:'monogenes', cls:'good'});
      } else if(opts.tribrach){
        if(tau){
          info.accentFromEnd = 2; // penult
          info.rule = 'Tribrach -ερος usually oxytone, but τ before ε (…τερ-) pushes accent earlier (toy rule).';
          info.tags.push({t:'…τερ-', cls:'bad'});
        } else {
          info.accentFromEnd = 1;
          info.rule = 'Tribrach -ερος (3-gender adjective) → oxytone (acute on ultima).';
          info.tags.push({t:'tribrach', cls:'good'});
        }
      } else {
        info.accentFromEnd = 2;
        info.rule = 'Default -ερος guess → penult accent (fallback).';
      }

      // clamp: if too few syllables, move to penult/ultima
      if(n <= 2) info.accentFromEnd = 1;
      if(n === 3 && info.accentFromEnd === 3) info.accentFromEnd = 2;
      return info;
    }

    if(endsWithHeros(w)){
      info.kind = '-ηρος';
      if(n >= 3){
        info.accentFromEnd = 3; // proparoxytone
        info.rule = '-ηρος (>2 syllables) → proparoxytone (acute on antepenult), like ὅμηρος, σίδηρος.';
        info.tags.push({t:'proparox', cls:'good'});
      } else {
        info.accentFromEnd = 2;
        info.rule = '-ηρος but short word → fallback.';
      }
      return info;
    }

    // unknown ending: try to accent like a generic Greek word: penult
    info.kind = 'other';
    info.accentFromEnd = (n >= 2) ? 2 : 1;
    info.rule = 'Not recognized as -ερος/-ηρος → generic penult accent (toy fallback).';
    return info;
  }

  function renderTags(tags){
    if(!tags.length) return '';
    return tags.map(x => `<span class="tag ${x.cls||''}">${escapeHtml(x.t)}</span>`).join(' ');
  }

  function escapeHtml(s){
    return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  function run(){
    const raw = inp.value;
    const norm = normalizeGreek(raw);
    if(!norm){
      outMain.textContent = '—';
      outMeta.textContent = '';
      return;
    }

    // If phrase, accent each Greek token separately and rejoin by spaces (simple)
    const tokens = norm.split(' ');
    const outTokens = [];
    const metaBits = [];

    for(const tok of tokens){
      const w = tok;
      const wBare = normalizeGreek(w);
      const info = decideAccent(wBare, {
        proper: optProper.checked,
        monogenes: optMonogenes.checked,
        tribrach: optTribrach.checked
      });
      const acc = accentWord(wBare, info.accentFromEnd);
      outTokens.push(acc.word);

      const sylTxt = optShowSyll.checked ? `Syllables: ${info.syllables.join('·')}` : '';
      metaBits.push(`• <span class="mono">${escapeHtml(wBare)}</span> → <b>${escapeHtml(info.kind)}</b> ${renderTags(info.tags)}<br><span class="metaLine">${escapeHtml(info.rule)}${sylTxt?`<br><span class="mono">${escapeHtml(sylTxt)}</span>`:''}</span>`);
    }

    outMain.textContent = outTokens.join(' ');
    outMeta.innerHTML = metaBits.join('<br>');
  }

  btnGo.addEventListener('click', run);
  btnClear.addEventListener('click', () => { inp.value=''; run(); inp.focus(); });
  btnDemo.addEventListener('click', () => {
    inp.value = samples.map(s => s.w).slice(0,6).join(' ');
    optProper.checked = false;
    optMonogenes.checked = false;
    optTribrach.checked = true;
    run();
    inp.focus();
  });

  inp.addEventListener('keydown', (e) => {
    if(e.key === 'Enter') run();
  });

  [optProper,optMonogenes,optTribrach,optShowSyll].forEach(el => el.addEventListener('change', run));

  makeChips();
  run();
})();

