(() => {
  const $ = (sel, root=document) => root.querySelector(sel);

  const inp = $('#inp');
  const fem = $('#fem');
  const mode = $('#mode');
  const normEl = $('#norm');
  const accEl = $('#accented');
  const noteEl = $('#accentNote');
  const femOutEl = $('#femOut');

  const examples = [
    {w:'λυπηρος', mode:'adj', hint:'adjective in -ηρος → oxytone (λυπηρός)'} ,
    {w:'ὀτρηρος', mode:'adj', fem:'ὀτρηρη', hint:'Herodian: ὀτρηρός, fem. ὀτρηρή'} ,
    {w:'πονηρος', mode:'attic', hint:'Attic: meaning can shift accent'} ,
    {w:'μοχθηρος', mode:'attic', hint:'Attic: meaning can shift accent'} ,
    {w:'Τροιζηνος', mode:'proper', hint:'Herodian: Τροίζηνος barytone “by peculiarity”'} ,
    {w:'Κυθηρος', mode:'proper', hint:'proper name / ethnicon-like'} ,
    {w:'Διζηρος', mode:'proper', hint:'river-name in -ηρος'} ,
    {w:'Δοβηρος', mode:'proper', hint:'place-name in -ηρος'}
  ];

  function stripDiacritics(s){
    // Remove combining marks; keep base Greek letters.
    return (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  }

  function isGreekLetter(ch){
    return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(ch);
  }

  function tokenizeGreek(s){
    // Keep only Greek letters and spaces; collapse whitespace.
    let out = '';
    for (const ch of (s||'')){
      if (isGreekLetter(ch) || ch===' ' || ch==='\n' || ch==='\t') out += ch;
    }
    return out.replace(/\s+/g,' ').trim();
  }

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

  function lastVowelIndex(word){
    for (let i=word.length-1;i>=0;i--){
      if (vowels.has(word[i])) return i;
    }
    return -1;
  }

  function prevVowelIndex(word, from){
    for (let i=from-1;i>=0;i--){
      if (vowels.has(word[i])) return i;
    }
    return -1;
  }

  function accentAt(word, vIndex, mark='\u0301'){
    // Add combining acute after the vowel at vIndex.
    if (vIndex < 0 || vIndex >= word.length) return word;
    const base = word.normalize('NFD');
    // Map vIndex in NFC to index in NFD is messy; so operate on NFC by inserting combining mark after char.
    // This is acceptable for a toy because we stripped diacritics first.
    return word.slice(0, vIndex+1) + mark + word.slice(vIndex+1);
  }

  function oxytone(word){
    return accentAt(word, lastVowelIndex(word));
  }

  function paroxytone(word){
    const lv = lastVowelIndex(word);
    const pv = prevVowelIndex(word, lv);
    return accentAt(word, pv);
  }

  function proparoxytone(word){
    const lv = lastVowelIndex(word);
    const pv = prevVowelIndex(word, lv);
    const ppv = prevVowelIndex(word, pv);
    return accentAt(word, ppv);
  }

  function endsWithAny(w, arr){
    return arr.some(suf => w.endsWith(suf));
  }

  function guessAccent(wordRaw, femRaw, modeVal){
    const cleaned = tokenizeGreek(wordRaw);
    const base = stripDiacritics(cleaned);
    const w = base;

    const femClean = tokenizeGreek(femRaw);
    const femBase = stripDiacritics(femClean);

    let note = '';
    let accented = w;
    let femOut = '—';

    const lower = w.toLowerCase();

    // Determine if it looks like -ηρος / -ηρον-ish (toy heuristic)
    const looksEros = endsWithAny(lower, ['ηρος','ηρον','ηρου','ηροι','ηρα','ηρας','ηραι','ηρων']);

    // Auto mode chooses based on a few cues.
    let m = modeVal;
    if (m === 'auto'){
      if (lower === 'πονηρος' || lower === 'μοχθηρος') m = 'attic';
      else if (femBase && femBase.length) m = 'adj';
      else if (!looksEros) m = 'proper';
      else m = 'adj';
    }

    if (!w){
      return {norm:'—', accented:'—', note:'Type a Greek word above.', femOut:'—'};
    }

    if (m === 'attic'){
      // Herodian: Attics proparoxytone for “toilsome”, oxytone for “base in soul”.
      // Provide a toggle-like behavior based on a tiny keyword in the input phrase.
      // If phrase contains "ψυχη" or "φαυλ" → oxytone; if contains "κοπ" or "μοχθ" or "ἐπιπον" → proparoxytone.
      const phrase = stripDiacritics(tokenizeGreek(wordRaw)).toLowerCase();
      const isMoral = /ψυχ|φαυλ|κακ/.test(phrase);
      const isToilsome = /κοπ|μοχθ|πον|ἐπιπον|επιπον|ἐπιμοχθ|επιμοχθ/.test(phrase);

      if (lower !== 'πονηρος' && lower !== 'μοχθηρος'){
        note = 'Attic mode is mainly for πόνηρος / μόχθηρος; applying the same “meaning-shift” toy rule anyway.';
      }

      if (isMoral && !isToilsome){
        accented = oxytone(w);
        note = 'Attic (toy): “base in soul” → oxytone (accent on ultima). Try adding a hint like «ψυχῇ» in the input phrase.';
      } else {
        accented = proparoxytone(w);
        note = 'Attic (toy): “toilsome/laborious” → proparoxytone (accent on antepenult). Try adding a hint like «ἐπίπονον» in the input phrase.';
      }
      femOut = '—';
    }

    if (m === 'adj'){
      // Passage: multi-syllable adjectives in -ηρος with distinct feminine are oxytone.
      if (!looksEros){
        note = 'Adjective mode: your word does not look like -ηρος; still accenting as oxytone for the toy.';
      } else {
        note = 'Rule-of-thumb from Herodian 1.197: many adjectival -ηρος (esp. >2 syllables) with distinct feminine are oxytone.';
      }
      accented = oxytone(w);

      // Feminine: if user supplies, accent it on ultima too; else try to derive -ηρή from -ηρός.
      if (femBase){
        femOut = oxytone(femBase);
      } else {
        // Derive only for nominative masc -ηρος
        if (lower.endsWith('ηρος')){
          const stem = w.slice(0, w.length-4);
          femOut = oxytone(stem + 'ηρη');
        } else {
          femOut = '—';
        }
      }
    }

    if (m === 'proper'){
      // Proper names: the passage notes peculiar barytone behavior (e.g. Τροίζηνος).
      // Toy: default to paroxytone (barytone) for -ηνος/-ηρος proper names; but keep oxytone for some river/place patterns if user wants.
      const low = lower;
      if (low.endsWith('ηνος')){
        accented = paroxytone(w);
        note = 'Proper-name toy: barytone tendency (paroxytone) for -ηνος (cf. Τροίζηνος).';
      } else if (low.endsWith('ηρος')){
        accented = paroxytone(w);
        note = 'Proper-name toy: barytone tendency (paroxytone) for many -ηρος names listed by Herodian (simplified).';
      } else {
        accented = paroxytone(w);
        note = 'Proper-name toy: defaulting to paroxytone (barytone).';
      }
      femOut = '—';
    }

    // If user typed multiple words, accent only the last token and keep the rest.
    const parts = w.split(' ');
    if (parts.length > 1){
      const last = parts[parts.length-1];
      const before = parts.slice(0,-1).join(' ');
      // Recompute accent on last only using same mode, but without spaces.
      const g = guessAccent(last, femBase, m);
      accented = before + ' ' + g.accented;
      // Keep note from earlier.
    }

    return {norm:w, accented, note, femOut};
  }

  function render(){
    const g = guessAccent(inp.value, fem.value, mode.value);
    normEl.textContent = g.norm;
    accEl.textContent = g.accented;
    noteEl.textContent = g.note;
    femOutEl.textContent = g.femOut;
  }

  function setExample(ex){
    inp.value = ex.w;
    mode.value = ex.mode;
    fem.value = ex.fem || '';
    render();
  }

  $('#go').addEventListener('click', render);
  inp.addEventListener('keydown', (e) => { if (e.key === 'Enter') render(); });
  fem.addEventListener('keydown', (e) => { if (e.key === 'Enter') render(); });
  mode.addEventListener('change', render);

  $('#clear').addEventListener('click', () => {
    inp.value = '';
    fem.value = '';
    mode.value = 'auto';
    render();
    inp.focus();
  });

  $('#rand').addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    setExample(ex);
  });

  // Chips
  const chips = $('#chips');
  examples.forEach(ex => {
    const d = document.createElement('div');
    d.className = 'chip';
    d.textContent = ex.w;
    d.title = ex.hint;
    d.addEventListener('click', () => setExample(ex));
    chips.appendChild(d);
  });

  // Initial render
  render();
})();

