const $ = (sel) => document.querySelector(sel);

const examples = [
  "δοροκοττορος",
  "κατηγορος",
  "συνηγορος",
  "τελεσφορος",
  "δορυφορος",
  "βουληφορος",
  "εωσφορος",
  "αφορος",
  "παντοπορος",
  "γαμορος",
  "καταμορος",
  "παπυρος",
  "διαπυρος",
  "μαρτυρος",
  "αργυρος",
  "πορφυρος",
  "ζεφυρος",
  "σατυρος",
  "λαθυρος",
  "ιδυρος",
  "αμυρος",
  "γλαφυρος",
  "ελυρος",
  "εφυρος",
  "βακυρος",
  "σιμυρος",
  "κασπαπυρος"
];

// --- Greek utilities (toy-level) ---
const COMBINING = /[\u0300-\u036f]/g;

function stripCombining(s){
  return s.normalize('NFD').replace(COMBINING,'').normalize('NFC');
}

function stripGreekAccents(s){
  // remove tonos/oxia, varia, perispomeni, dialytika, etc. via NFD combining marks
  return stripCombining(s);
}

function normalizeGreek(s){
  return stripGreekAccents(s)
    .replace(/ς/g,'σ')
    .replace(/[^\p{Script=Greek}]/gu,'')
    .toLowerCase();
}

function isVowel(ch){
  return "αεηιουω".includes(ch);
}

function roughSyllabify(word){
  // Very rough: split into vowel-groups with preceding consonants.
  // e.g. τελεσφορος -> τε | λεσ | φο | ρος (approx)
  const w = word;
  if(!w) return [];
  let syll = [];
  let cur = "";
  let seenVowel = false;

  for(let i=0;i<w.length;i++){
    const ch = w[i];
    cur += ch;
    if(isVowel(ch)){
      seenVowel = true;
      // absorb following vowel if diphthong-ish (toy): αι, ει, οι, υι, αυ, ευ, ου, ηυ
      const next = w[i+1] || "";
      const pair = ch + next;
      const diph = ["αι","ει","οι","υι","αυ","ευ","ου","ηυ"].includes(pair);
      if(diph){
        cur += next;
        i++;
      }
      // close syllable here; consonants after will start next syllable
      syll.push(cur);
      cur = "";
      seenVowel = false;
    }
  }
  if(cur) syll[syll.length-1] = (syll[syll.length-1]||"") + cur;
  return syll.filter(x=>x.length);
}

function penultVowel(norm){
  // find vowel in penult syllable nucleus (toy): last vowel of penult syllable
  const syl = roughSyllabify(norm);
  if(syl.length < 2) return null;
  const pen = syl[syl.length-2];
  for(let i=pen.length-1;i>=0;i--){
    if(isVowel(pen[i])) return pen[i];
  }
  return null;
}

function looksCompound(norm){
  // heuristic: common compound second members in passage
  return /(φορος|ηγορος|αγορος|μορος|πορος)$/.test(norm);
}

function addAcuteOnSyllable(norm, syllIndexFromEnd){
  // syllIndexFromEnd: 1=ultima,2=penult,3=antepenult
  const syl = roughSyllabify(norm);
  if(syl.length === 0) return {word:norm, where:null, syl};
  const idx = syl.length - syllIndexFromEnd;
  if(idx < 0) return {word:norm, where:null, syl};

  // place acute on the last vowel of that syllable
  let target = syl[idx];
  let chars = target.split('');
  let vpos = -1;
  for(let i=chars.length-1;i>=0;i--){
    if(isVowel(chars[i])) { vpos = i; break; }
  }
  if(vpos === -1) return {word:norm, where:null, syl};

  // map plain vowel -> vowel + tonos (modern combining acute)
  const tonos = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ'
  };
  chars[vpos] = tonos[chars[vpos]] || chars[vpos];
  syl[idx] = chars.join('');
  return {word: syl.join(''), where: syllIndexFromEnd, syl};
}

function toyAccentDecision(norm, compoundSetting, penultSetting){
  const endsRos = norm.endsWith('ρος');
  const syl = roughSyllabify(norm);
  const n = syl.length;

  if(!endsRos){
    return {ok:false, reason:"Not an -ρος word (toy only handles -ρος).", target:null, syl};
  }
  if(n < 3){
    return {ok:false, reason:"Too short for the passage’s ‘more than disyllabic’ rule.", target:null, syl};
  }

  const comp = compoundSetting === 'auto' ? looksCompound(norm) : (compoundSetting === 'yes');
  const pv = penultSetting === 'auto' ? penultVowel(norm) : (penultSetting === 'o' ? 'ο' : penultSetting === 'u' ? 'υ' : null);

  // Exception-ish list from the passage section: some are said to have tone on penult.
  const penultAccentList = new Set(["τελεσφορος","δορυφορος","βουληφορος","εωσφορος"]);
  const proparoxList = new Set(["αφορος","παντοπορος","γαμορος","καταμορος"]);

  let target = 3; // default: antepenult
  let why = [];

  if(penultAccentList.has(norm)){
    target = 2;
    why.push("Listed here as having accent on the penult (τελεσφόρος etc.).");
  } else if(proparoxList.has(norm)){
    target = 3;
    why.push("Treated as proparoxytone in the passage (ἄφορος, παντοπόρος, γαμόρος, κατάμορος)." );
  } else {
    if(pv === 'ο'){
      target = 3;
      why.push("Penult vowel ≈ ο and word is >2 syllables → proparoxytone (toy rule)." );
      if(comp) why.push("Compound/simple doesn’t change the toy outcome here (both often proparoxytone in the passage)." );
    } else if(pv === 'υ'){
      target = 3;
      why.push("Penult vowel ≈ υ and word is >2 syllables → proparoxytone (toy rule)." );
    } else {
      target = 3;
      why.push("Unknown penult vowel; defaulting to proparoxytone for -ρος πολυσύλλαβα (toy default)." );
    }
  }

  return {ok:true, reason: why.join(' '), target, syl};
}

function render(){
  const raw = $('#w').value.trim();
  const norm = normalizeGreek(raw);
  $('#norm').textContent = norm || '—';

  const syl = roughSyllabify(norm);
  $('#syll').textContent = syl.length ? syl.join(' · ') : '—';

  const compoundSetting = $('#compound').value;
  const penultSetting = $('#penult').value;
  const dec = toyAccentDecision(norm, compoundSetting, penultSetting);

  if(!norm){
    $('#result').textContent = '—';
    $('#explain').textContent = 'Type a Greek word ending in -ρος.';
    return;
  }

  if(!dec.ok){
    $('#result').textContent = raw || norm;
    $('#explain').textContent = dec.reason;
    return;
  }

  const accented = addAcuteOnSyllable(norm, dec.target).word;

  const modePractice = $('#modePractice').classList.contains('on');
  if(modePractice){
    $('#result').textContent = '…';
    $('#explain').textContent = 'Practice mode: enter your guess below, then Check (or Reveal).';
  } else {
    $('#result').textContent = accented;
    $('#explain').textContent = dec.reason;
  }

  // store current toy answer for practice checking
  $('#result').dataset.answer = accented;
}

function setMode(which){
  const g = $('#modeGuess');
  const p = $('#modePractice');
  if(which === 'guess'){
    g.classList.add('on');
    p.classList.remove('on');
  } else {
    p.classList.add('on');
    g.classList.remove('on');
  }
  render();
}

function checkPractice(){
  const ans = $('#result').dataset.answer || '';
  const user = $('#guess').value.trim();
  const fb = $('#feedback');

  if(!$('#modePractice').classList.contains('on')){
    fb.className = 'feedback warn';
    fb.textContent = 'Switch to Practice mode to use Check.';
    return;
  }
  if(!ans){
    fb.className = 'feedback warn';
    fb.textContent = 'No toy answer yet—type a word above and click Apply.';
    return;
  }
  if(!user){
    fb.className = 'feedback warn';
    fb.textContent = 'Type your accented guess first.';
    return;
  }

  // Compare accent-insensitive base + accent position-ish by comparing stripped forms and exact match.
  const baseUser = normalizeGreek(user);
  const baseAns = normalizeGreek(ans);

  if(baseUser !== baseAns){
    fb.className = 'feedback bad';
    fb.textContent = `Different base word. I expected something like: ${baseAns}`;
    return;
  }

  if(stripGreekAccents(user) === stripGreekAccents(ans) && user === ans){
    fb.className = 'feedback good';
    fb.textContent = 'Match (according to the toy).';
  } else {
    // If user has no accents, nudge.
    if(stripGreekAccents(user) === user){
      fb.className = 'feedback warn';
      fb.textContent = `Same letters, but you didn’t include an accent. Toy answer: ${ans}`;
    } else {
      fb.className = 'feedback bad';
      fb.textContent = `Not the same accent as the toy. Toy answer: ${ans}`;
    }
  }
}

function reveal(){
  const ans = $('#result').dataset.answer || '';
  const fb = $('#feedback');
  if(!ans){
    fb.className = 'feedback warn';
    fb.textContent = 'Nothing to reveal yet—type a word above and click Apply.';
    return;
  }
  fb.className = 'feedback';
  fb.textContent = `Toy answer: ${ans}`;
}

// --- wire up ---
$('#go').addEventListener('click', render);
$('#w').addEventListener('keydown', (e)=>{ if(e.key==='Enter') render(); });
$('#clear').addEventListener('click', ()=>{ $('#w').value=''; $('#guess').value=''; $('#feedback').textContent='—'; $('#feedback').className='feedback'; render(); });
$('#random').addEventListener('click', ()=>{ $('#w').value = examples[Math.floor(Math.random()*examples.length)]; render(); });
$('#modeGuess').addEventListener('click', ()=>setMode('guess'));
$('#modePractice').addEventListener('click', ()=>setMode('practice'));
$('#check').addEventListener('click', checkPractice);
$('#reveal').addEventListener('click', reveal);

// initial
$('#w').value = 'τελεσφορος';
render();

