// Herodian -ωρος / -υρος accent toy (offline, heuristic)
(function(){
  const $ = (sel)=>document.querySelector(sel);
  const inp = $('#inp');
  const btn = $('#btn');
  const btnClear = $('#btnClear');
  const suggest = $('#suggest');
  const rule = $('#rule');
  const sketch = $('#sketch');
  const treatProper = $('#treatProper');
  const keepExisting = $('#keepExisting');
  const chips = $('#chips');

  const examples = [
    'Θεοδωρος', 'Αψωρος', 'Ισοδωρος', 'Αλωρος', 'Αζωρος',
    'θεωρος', 'πυλωρος', 'θυρωρος', 'μυλωρος', 'φρυκτωρος', 'σκευωρος',
    'νεωρος', 'μετεωρος', 'ολιγωρος',
    'λιγυρος', 'ισχυρος', 'βδελυρος',
    'Λευκοσυρος', 'Νισυρος'
  ];

  // --- Unicode helpers ---
  const COMB_ACUTE = '\u0301';
  const COMB_GRAVE = '\u0300';
  const COMB_CIRC  = '\u0342';

  const combiningRE = /[\u0300-\u036f]/g;

  function nfd(s){ return s.normalize('NFD'); }
  function nfc(s){ return s.normalize('NFC'); }

  function stripCombining(s){ return nfd(s).replace(combiningRE,'').normalize('NFC'); }

  function hasAccent(s){
    const d = nfd(s);
    return /[\u0300\u0301\u0342]/.test(d);
  }

  function isGreekLetter(ch){
    const code = ch.codePointAt(0);
    return (code>=0x0370 && code<=0x03FF) || (code>=0x1F00 && code<=0x1FFF);
  }

  function looksProper(s){
    // crude: first Greek letter is uppercase
    const d = stripCombining(s).trim();
    for (const ch of d){
      if (!isGreekLetter(ch)) continue;
      return ch === ch.toUpperCase() && ch !== ch.toLowerCase();
    }
    return false;
  }

  // --- Toy syllabification ---
  // We only need syllable nuclei positions (vowels/diphthongs) to place an accent.
  const V = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ','ϊ','ΐ','ϋ','ΰ','ᾳ','ῃ','ῳ']);

  function lowerGreek(s){
    // keep Greek; toLowerCase handles polytonic reasonably
    return s.toLowerCase();
  }

  function getNuclei(word){
    // returns array of objects {start,end} in NFD-stripped string indices
    const w = stripCombining(word);
    const s = lowerGreek(w);
    const nuclei = [];

    // treat common diphthongs as one nucleus
    const diph = new Set(['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ωυ']);

    let i=0;
    while(i<s.length){
      const ch = s[i];
      if (V.has(ch)){
        // check diphthong
        if (i+1<s.length){
          const pair = s.slice(i,i+2);
          if (diph.has(pair)){
            nuclei.push({start:i,end:i+2});
            i+=2; continue;
          }
        }
        nuclei.push({start:i,end:i+1});
      }
      i++;
    }
    return {base:w, nuclei};
  }

  function syllableCount(word){
    return getNuclei(word).nuclei.length;
  }

  function accentOnNucleus(word, nucleusIndexFromEnd, mark){
    // nucleusIndexFromEnd: 1=ultima, 2=penult, 3=antepenult
    const info = getNuclei(word);
    const base = info.base;
    const nuclei = info.nuclei;
    if (nuclei.length===0) return word;

    const idx = nuclei.length - nucleusIndexFromEnd;
    const target = nuclei[Math.max(0, Math.min(nuclei.length-1, idx))];

    // Insert combining mark after the first vowel char of the nucleus.
    // Work in NFD to avoid precomposed issues.
    const d = nfd(base);
    // Need mapping from base indices to NFD indices; approximate by rebuilding.
    // Since base is NFC without combining marks, NFD length may differ for precomposed.
    // We'll locate by scanning base and NFD in parallel.
    let bi=0, di=0;
    let insertAt = null;
    while (bi<base.length && di<d.length){
      const bch = base[bi];
      const dch = d[di];
      if (bch === dch){
        if (bi === target.start){
          // move di to after this base char and any existing combining marks
          di++;
          while (di<d.length && /[\u0300-\u036f]/.test(d[di])) di++;
          insertAt = di;
          break;
        }
        bi++; di++;
      } else {
        // If NFD decomposed a precomposed vowel, base char corresponds to multiple NFD chars.
        // Advance di until next base char matches.
        // First, if we are at the target.start, insert after the first decomposed base char.
        if (bi === target.start){
          // consume one NFD char (the base letter), then skip combining
          di++;
          while (di<d.length && /[\u0300-\u036f]/.test(d[di])) di++;
          insertAt = di;
          break;
        }
        // otherwise advance both cautiously
        bi++; // move base forward
        // advance di until it matches new base[bi] or end
        while (di<d.length && base[bi] && d[di] !== base[bi]) di++;
      }
    }
    if (insertAt==null) return word;

    // Remove any existing accent marks first (acute/grave/circumflex) to avoid stacking.
    const cleaned = d.replace(/[\u0300\u0301\u0342]/g,'');

    // But insertAt was computed on old d; recompute insertAt on cleaned by re-running with base.
    // Simpler: apply accent by rebuilding from base with no accents.
    const baseNoAcc = stripCombining(word);
    const info2 = getNuclei(baseNoAcc);
    const nuclei2 = info2.nuclei;
    const idx2 = nuclei2.length - nucleusIndexFromEnd;
    const target2 = nuclei2[Math.max(0, Math.min(nuclei2.length-1, idx2))];
    const d2 = nfd(baseNoAcc);

    // Find insertion point in d2 corresponding to target2.start
    let bi2=0, di2=0, ins=null;
    while (bi2<baseNoAcc.length && di2<d2.length){
      if (bi2 === target2.start){
        di2++;
        while (di2<d2.length && /[\u0300-\u036f]/.test(d2[di2])) di2++;
        ins = di2; break;
      }
      // advance one base char; in NFD it may be multiple, but first char is base letter
      di2++;
      while (di2<d2.length && /[\u0300-\u036f]/.test(d2[di2])) di2++;
      bi2++;
    }
    if (ins==null) return word;

    const out = d2.slice(0,ins) + mark + d2.slice(ins);
    return nfc(out);
  }

  function endsWithAny(s, arr){
    const t = lowerGreek(stripCombining(s.trim()));
    return arr.some(x => t.endsWith(x));
  }

  // --- Heuristic rule selection ---
  const watcherWords = new Set([
    'θεωρος','υληωρος','ιωρος','πυλωρος','θυρωρος','μυλωρος','φρυκτωρος','σκευωρος'
  ]);
  const baryWords = new Set(['νεωρος','ασχεδωρος','μετεωρος','ολιγωρος','ουδενοσωρος']);
  const yrosAcute = new Set(['λιγυρος','καπυρος','αλμυρος','οιζυρος','οχυρος','εχυρος','ισχυρος','βδελυρος','εκυρος']);

  function decide(word){
    const raw = word.trim();
    const base = stripCombining(raw);
    const low = lowerGreek(base);
    const sc = syllableCount(base);

    const proper = treatProper.checked && looksProper(base);

    // If already accented and user wants to keep it
    if (keepExisting.checked && hasAccent(raw)){
      return {form: raw, why: 'Input already accented (kept as-is).', accentType: 'kept'};
    }

    // -υρος tri-gender adjectives: oxytone
    if (endsWithAny(low, ['υρος']) && yrosAcute.has(low)){
      return {form: accentOnNucleus(base, 1, COMB_ACUTE), why: 'Rule: -υρός tri-gender adjective → oxytone (acute on ultima).', accentType:'oxytone'};
    }

    // -ωρος watcher/guard compounds: oxytone
    if (endsWithAny(low, ['ωρος']) && watcherWords.has(low)){
      return {form: accentOnNucleus(base, 1, COMB_ACUTE), why: 'Rule: “watcher/guard” (-ωρός with sense of ὠρῶ) → oxytone.', accentType:'oxytone'};
    }

    // -ωρος barytone list: we place acute on penult as a simple barytone default
    if (endsWithAny(low, ['ωρος']) && baryWords.has(low)){
      return {form: accentOnNucleus(base, 2, COMB_ACUTE), why: 'Rule: listed -ωρος adjectives → barytone (toy: acute on penult).', accentType:'barytone'};
    }

    // Proper names in -ωρος, more than two syllables: proparoxytone
    if (proper && endsWithAny(low, ['ωρος']) && sc>=3){
      return {form: accentOnNucleus(base, 3, COMB_ACUTE), why: 'Rule: proper name in -ωρος with >2 syllables → proparoxytone (acute on antepenult).', accentType:'proparoxytone'};
    }

    // Fallbacks
    if (endsWithAny(low, ['ωρος'])){
      // default: if 3+ syllables, proparoxytone; else oxytone
      if (sc>=3) return {form: accentOnNucleus(base, 3, COMB_ACUTE), why: 'Fallback: -ωρος (≥3 syllables) → proparoxytone (toy default).', accentType:'proparoxytone'};
      return {form: accentOnNucleus(base, 1, COMB_ACUTE), why: 'Fallback: -ωρος (2 syllables) → oxytone (toy default).', accentType:'oxytone'};
    }
    if (endsWithAny(low, ['υρος'])){
      return {form: accentOnNucleus(base, 1, COMB_ACUTE), why: 'Fallback: -υρος → oxytone (toy default).', accentType:'oxytone'};
    }

    // Not our domain: just show syllables and do nothing
    return {form: base, why: 'No -ωρος/-υρος ending detected; no accent rule applied.', accentType:'none'};
  }

  function makeSketch(word){
    const base = stripCombining(word.trim());
    const info = getNuclei(base);
    const n = info.nuclei;
    if (!base) return '—';
    if (n.length===0) return base + ' (no vowel nuclei found)';

    // Build a simple CV-ish segmentation by marking nuclei with brackets
    let out = '';
    let last = 0;
    for (let i=0;i<n.length;i++){
      const a = n[i].start;
      const b = n[i].end;
      out += base.slice(last,a);
      out += '[' + base.slice(a,b) + ']';
      last = b;
    }
    out += base.slice(last);
    out += `   (nuclei: ${n.length})`;
    return out;
  }

  function run(){
    const w = inp.value;
    if (!w.trim()){
      suggest.textContent = '—';
      rule.textContent = 'Type a word above.';
      sketch.textContent = '—';
      return;
    }
    const res = decide(w);
    suggest.textContent = res.form;
    rule.textContent = res.why;
    sketch.textContent = makeSketch(w);
  }

  function clearAll(){
    inp.value='';
    suggest.textContent='—';
    rule.textContent='—';
    sketch.textContent='—';
    inp.focus();
  }

  // chips
  function addChip(txt){
    const b = document.createElement('button');
    b.type='button';
    b.className='chip';
    b.textContent=txt;
    b.addEventListener('click', ()=>{ inp.value = txt; run(); inp.focus(); });
    chips.appendChild(b);
  }
  examples.forEach(addChip);

  btn.addEventListener('click', run);
  btnClear.addEventListener('click', clearAll);
  inp.addEventListener('keydown', (e)=>{ if (e.key==='Enter') run(); });

  // initial hint
  rule.textContent = 'Tip: try Θεοδωρος (proper name) vs θεωρος (watcher) vs νεωρος (barytone list).';
})();

passages.gadget_css:
:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --card:#1d2140;
  --text:#eef0ff;
  --muted:#b9bde6;
  --accent:#8be9fd;
  --warn:#ffb86c;
  --ok:#50fa7b;
  --bad:#ff5555;
  --line:rgba(255,255,255,.12);
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, #1a1f3a 0%, var(--bg) 55%);color:var(--text);font:16px/1.35 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif}
.wrap{max-width:980px;margin:0 auto;padding:22px 16px 28px}
h2{margin:0 0 8px;font-size:22px;letter-spacing:.2px}
.sub{margin:0 0 14px;color:var(--muted)}
.panel{background:linear-gradient(180deg, rgba(255,255,255,.06), rgba(255,255,255,.03));border:1px solid var(--line);border-radius:14px;padding:14px}
label{display:block;color:var(--muted);font-size:13px;margin:0 0 6px}
.row{display:flex;gap:10px;align-items:center}
input{flex:1;min-width:220px;padding:12px 12px;border-radius:12px;border:1px solid var(--line);background:rgba(0,0,0,.25);color:var(--text);font-size:18px;outline:none}
input:focus{border-color:rgba(139,233,253,.55);box-shadow:0 0 0 3px rgba(139,233,253,.12)}
button{padding:11px 12px;border-radius:12px;border:1px solid rgba(139,233,253,.35);background:rgba(139,233,253,.14);color:var(--text);cursor:pointer;font-weight:650}
button:hover{background:rgba(139,233,253,.2)}
button.ghost{border-color:var(--line);background:rgba(255,255,255,.06);font-weight:600}
button.ghost:hover{background:rgba(255,255,255,.09)}
.grid{display:grid;grid-template-columns:1.1fr .9fr;gap:12px;margin-top:12px}
@media (max-width:860px){.grid{grid-template-columns:1fr}}
.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:12px}
.card h3{margin:0 0 8px;font-size:14px;color:var(--muted);font-weight:700;letter-spacing:.3px;text-transform:uppercase}
.big{font-size:30px;letter-spacing:.2px;margin:2px 0 6px}
.rule{color:var(--muted)}
.rule b{color:var(--accent)}
.bullets{margin:0;padding-left:18px;color:var(--muted)}
.bullets li{margin:6px 0}
.tiny{margin:10px 0 0;color:rgba(238,240,255,.78);font-size:12.5px}
.details{margin-top:10px;border:1px dashed rgba(255,255,255,.18);border-radius:12px;padding:10px;background:rgba(0,0,0,.18)}
.details summary{cursor:pointer;color:var(--muted);font-weight:650}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
.chip{border:1px solid rgba(255,255,255,.16);background:rgba(255,255,255,.06);padding:7px 10px;border-radius:999px;cursor:pointer;color:var(--text);font-size:14px}
.chip:hover{border-color:rgba(139,233,253,.35)}
.mini{margin-top:10px;color:rgba(238,240,255,.72);font-size:12.5px}
footer{margin-top:10px}
.foot{color:rgba(238,240,255,.55);font-size:12px}
.badge{display:inline-block;padding:2px 8px;border-radius:999px;border:1px solid var(--line);font-size:12px;margin-left:8px;color:var(--muted)}
.badge.ok{border-color:rgba(80,250,123,.35);color:rgba(80,250,123,.95)}
.badge.warn{border-color:rgba(255,184,108,.35);color:rgba(255,184,108,.95)}
.badge.bad{border-color:rgba(255,85,85,.35);color:rgba(255,85,85,.95)}

