const $ = (s) => document.querySelector(s);

const examples = [
  "Παλαιρος",
  "χῆμαιρος",
  "κύπαιρος",
  "εὔκαιρος",
  "ἄκαιρος",
  "ἑταῖρος",
  "Ἴσαυρος",
  "Ἐπίδαυρος",
  "Κένταυρος",
  "Ἄγλαυρος",
  "θησαυρός",
  "μάρμαρος",
  "βάρβαρος"
];

// --- Greek helpers ---
const combining = {
  acute: "\u0301",
  grave: "\u0300",
  circumflex: "\u0342",
  diaeresis: "\u0308",
  smooth: "\u0313",
  rough: "\u0314",
  iotaSub: "\u0345",
  macron: "\u0304",
  breve: "\u0306"
};

const ACCENT_MARKS = new Set([combining.acute, combining.grave, combining.circumflex]);
const DIACRITICS = new Set(Object.values(combining));

function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripDiacritics(s){
  const d = nfd(s);
  let out = "";
  for (const ch of d){
    if (!DIACRITICS.has(ch)) out += ch;
  }
  return nfc(out);
}

function stripAccentsOnly(s){
  const d = nfd(s);
  let out = "";
  for (const ch of d){
    if (!ACCENT_MARKS.has(ch)) out += ch;
  }
  return nfc(out);
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code >= 0x0370 && code <= 0x03FF) || (code >= 0x1F00 && code <= 0x1FFF);
}

function tokenizeGreekWords(text){
  // keep only Greek letters and spaces; split on whitespace
  const cleaned = [...text].map(c => (isGreekLetter(c) ? c : (c === ' ' ? ' ' : ' '))).join('');
  return cleaned.split(/\s+/).filter(Boolean);
}

const VOWELS = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);

function isVowelBase(ch){ return VOWELS.has(ch); }

function baseLetters(s){
  // remove diacritics but keep letters
  return stripDiacritics(s);
}

function countSyllables(word){
  // heuristic: count vowel nuclei; treat αι, αυ, ει, οι, ου, υι as one nucleus
  const w = baseLetters(word);
  const chars = [...w];
  let n = 0;
  for (let i=0;i<chars.length;i++){
    const c = chars[i];
    if (!isVowelBase(c)) continue;
    const next = chars[i+1] || "";
    const pair = (c+next).toLowerCase();
    if (["αι","αυ","ει","οι","ου","υι","ηυ","ευ"].includes(pair)){
      n++; i++; continue;
    }
    n++;
  }
  return n;
}

function findVowelNuclei(word){
  // return array of {start,end} indices in NFD string (base letters only positions in NFC string are hard);
  // We'll work on NFD but map to NFC by rebuilding with combining marks.
  // Simpler: operate on NFC string by scanning codepoints and treating vowel letters as nuclei.
  const w = nfc(word);
  const letters = [...w];
  const bases = [...baseLetters(w)];
  // We need nuclei positions in terms of base-letter index.
  let nuclei = [];
  for (let i=0;i<bases.length;i++){
    const c = bases[i];
    if (!isVowelBase(c)) continue;
    const next = bases[i+1] || "";
    const pair = (c+next).toLowerCase();
    if (["αι","αυ","ει","οι","ου","υι","ηυ","ευ"].includes(pair)){
      nuclei.push({baseIndex:i, length:2, text:pair});
      i++;
    } else {
      nuclei.push({baseIndex:i, length:1, text:c.toLowerCase()});
    }
  }
  return nuclei;
}

function endsWithRos(word){
  const w = baseLetters(word).toLowerCase();
  return w.endsWith("ρος");
}

function penultNucleus(word){
  const nuclei = findVowelNuclei(word);
  if (nuclei.length < 2) return null;
  return nuclei[nuclei.length-2];
}

function applyAccent(word, targetFromEnd, accentType){
  // targetFromEnd: 1=ultima,2=penult,3=antepenult
  // accentType: 'acute' or 'circumflex'
  const clean = stripAccentsOnly(word);
  const wBase = baseLetters(clean);
  const nuclei = findVowelNuclei(clean);
  if (nuclei.length === 0) return clean;
  const idx = nuclei.length - targetFromEnd;
  if (idx < 0) return clean;
  const target = nuclei[idx];

  // Build mapping from base-letter index to position in NFD string with combining marks.
  const nfdWord = nfd(clean);
  // Create arrays of clusters: each base letter + its combining marks.
  let clusters = [];
  let current = "";
  for (const ch of nfdWord){
    if (!DIACRITICS.has(ch)){
      if (current) clusters.push(current);
      current = ch;
    } else {
      current += ch;
    }
  }
  if (current) clusters.push(current);

  // Determine which cluster(s) correspond to the vowel nucleus.
  // We use base-letter indices: clusters correspond 1:1 with base letters.
  const start = target.baseIndex;
  const len = target.length;

  // Place accent on the first vowel of the nucleus (good enough for αι/αυ etc.).
  const accentMark = accentType === 'circumflex' ? combining.circumflex : combining.acute;
  const c0 = clusters[start] || "";
  // Remove any existing accent marks (already stripped, but just in case)
  const c0n = [...c0].filter(ch => !ACCENT_MARKS.has(ch)).join('');
  clusters[start] = c0n + accentMark;

  return nfc(clusters.join(''));
}

function analyze(word){
  const raw = word.trim();
  const w = raw;
  const base = baseLetters(stripAccentsOnly(w));
  const lower = base.toLowerCase();

  const syll = countSyllables(w);
  const hasRos = endsWithRos(w);
  const pen = penultNucleus(w);
  const penText = pen ? pen.text : null;

  // Exception: ἑταῖρος (and common unaccented spellings)
  const normalized = lower;
  const isHetairos = normalized === "εταιρος" || normalized === "ἑταιρος"; // rough breathing stripped anyway

  let verdict = {
    ok:false,
    accentWord: stripAccentsOnly(w),
    label:"",
    explanation:"",
    badge:"warn"
  };

  if (!raw){
    verdict.label = "Type a word ending in -ρος.";
    verdict.explanation = "";
    verdict.badge = "warn";
    return verdict;
  }

  if (!hasRos){
    verdict.label = "Not an -ρος word (toy rule won’t apply).";
    verdict.explanation = `I only try to accent words ending in -ρος. Detected: “${base}”.`;
    verdict.badge = "bad";
    verdict.accentWord = stripAccentsOnly(w);
    return verdict;
  }

  if (syll < 3){
    verdict.label = "Too short for Herodian’s rule (needs 3+ syllables).";
    verdict.explanation = `He’s talking about ὑπερδισύλλαβα (more than two syllables). I count ≈ ${syll}.`;
    verdict.badge = "warn";
    verdict.accentWord = stripAccentsOnly(w);
    return verdict;
  }

  if (isHetairos){
    verdict.ok = true;
    verdict.accentWord = applyAccent(stripAccentsOnly(w), 2, 'circumflex');
    verdict.label = "Exception: προπερισπώμενον (penult circumflex).";
    verdict.explanation = "Herodian: τὸ μέντοι ἑταῖρος προπερισπᾶται.";
    verdict.badge = "ok";
    return verdict;
  }

  if (penText === "αι"){
    verdict.ok = true;
    verdict.accentWord = applyAccent(stripAccentsOnly(w), 3, 'acute');
    verdict.label = "Rule: …αιρος → προπαροξύτονον (antepenult acute).";
    verdict.explanation = "Herodian: τὰ εἰς -ρος … παραληγόμενα τῇ αι διφθόγγῳ προπαροξύνονται.";
    verdict.badge = "ok";
    return verdict;
  }

  if (penText === "αυ"){
    verdict.ok = true;
    verdict.accentWord = applyAccent(stripAccentsOnly(w), 3, 'acute');
    verdict.label = "Rule: …αυρος → προπαροξύτονον (antepenult acute).";
    verdict.explanation = "Herodian: τὰ εἰς -ρος … παραληγόμενα τῇ αυ διφθόγγῳ … προπαροξύνεται (with conditions).";
    verdict.badge = "ok";
    return verdict;
  }

  // Fallback: if it’s -ρος but not αι/αυ in penult, just show a conservative guess: antepenult acute if possible.
  verdict.ok = true;
  verdict.accentWord = applyAccent(stripAccentsOnly(w), 3, 'acute');
  verdict.label = "Fallback guess: προπαροξύτονον (antepenult acute).";
  verdict.explanation = "Not αι/αυ in the penult (by my heuristic), but many -ρος words are proparoxytone; treat this as a playful guess.";
  verdict.badge = "warn";
  return verdict;
}

function render(){
  const text = $('#inp').value;
  const words = tokenizeGreekWords(text);
  const target = words[0] || "";
  const res = analyze(target);

  $('#out').textContent = res.accentWord || "—";
  const badgeClass = res.badge;
  const badgeText = badgeClass === 'ok' ? 'match' : (badgeClass === 'bad' ? 'nope' : 'maybe');
  $('#rule').innerHTML = `${escapeHtml(res.label)} <span class="badge ${badgeClass}">${badgeText}</span><div class="tiny" style="margin-top:6px">${escapeHtml(res.explanation)}</div>`;
}

function escapeHtml(s){
  return (s||"").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function setupChips(){
  const box = $('#chips');
  box.innerHTML = "";
  for (const ex of examples){
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip';
    b.textContent = ex;
    b.addEventListener('click', () => { $('#inp').value = ex; render(); $('#inp').focus(); });
    box.appendChild(b);
  }
}

$('#btn').addEventListener('click', render);
$('#btnClear').addEventListener('click', () => { $('#inp').value = ""; render(); $('#inp').focus(); });
$('#inp').addEventListener('keydown', (e) => { if (e.key === 'Enter') render(); });
$('#inp').addEventListener('input', () => { /* live, but gentle */ render(); });

setupChips();
render();

