const $ = (sel, el=document) => el.querySelector(sel);
const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

// --- Greek helpers (very lightweight) ---
const COMBINING = /[\u0300-\u036f]/g;

function stripDiacritics(s){
  return s.normalize('NFD').replace(COMBINING,'').normalize('NFC');
}

function stripToLetters(s){
  // keep Greek letters and spaces/hyphen/apostrophe
  return s.replace(/[^\u0370-\u03FF\u1F00-\u1FFF\s\-’']/g,'');
}

function normalizeGreek(s){
  s = stripToLetters(s.trim());
  // unify final sigma
  s = s.replace(/ς/g,'σ');
  // remove diacritics for analysis
  return stripDiacritics(s).toLowerCase();
}

const vowels = new Set(['α','ε','η','ι','ο','υ','ω']);

function isVowel(ch){ return vowels.has(ch); }

function syllabifyRough(word){
  // Very rough syllable nuclei finder: each vowel group counts as a syllable.
  const w = word;
  let nuclei = [];
  let i=0;
  while(i<w.length){
    if(isVowel(w[i])){
      let j=i+1;
      while(j<w.length && isVowel(w[j])) j++;
      nuclei.push({start:i, end:j});
      i=j;
    } else i++;
  }
  return nuclei;
}

function endsWithRos(w){
  return w.endsWith('ρος');
}

function hasOuInPenult(w){
  // check for ...ουρος ending (penult nucleus = ου)
  return /ουρος$/.test(w);
}

function consonantClusterBeforeOu(w){
  // Look at letters immediately before the 'ου' of -ουρος.
  // If there are 2+ consonants right before it, treat as cluster.
  const m = w.match(/(.+)ουρος$/);
  if(!m) return false;
  const pre = m[1];
  let count=0;
  for(let i=pre.length-1;i>=0;i--){
    const ch = pre[i];
    if(isVowel(ch)) break;
    if(ch===' '||ch==='-'||ch==="'"||ch==='’') break;
    count++;
    if(count>=2) return true;
  }
  return false;
}

function startsWithNeCluster(w){
  // Herodian: disyllables in -ρος with consonant cluster, starting with νε-
  // We'll approximate: starts with νε + consonant (i.e. νεκ-, νεβ-, νεφ- ...)
  return /^νε[^αεηιουω\s\-’']/.test(w);
}

function hasBCluster(w){
  // Approximate: contains 'μβρ'/'βρ' cluster early; for disyllables like αβρος, εβρος, ιμβρος, ομβρος etc.
  // We'll just detect 'βρ' or 'μβρ' before -ος.
  return /(μβρ|βρ)ος$/.test(w);
}

function startsWithOAndHasDoubleConsonant(w){
  // General note: disyllables in -ος beginning with o- and having 2+ consonants.
  // We'll approximate: starts with ο and has a consonant cluster somewhere before final -ος.
  if(!w.startsWith('ο')) return false;
  // find any two consecutive consonants
  for(let i=0;i<w.length-1;i++){
    const a=w[i], b=w[i+1];
    if(!isVowel(a) && !isVowel(b) && a!==' ' && b!==' ' && a!=='-' && b!=='-') return true;
  }
  return false;
}

// --- Accent placement (toy) ---
function addAccentToVowel(vowel, mark){
  // mark: 'acute' or 'circ'
  const map = {
    'acute': { 'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ' },
    'circ':  { 'α':'ᾶ','η':'ῆ','ι':'ῖ','υ':'ῦ','ω':'ῶ' } // no circumflex for ε/ο
  };
  return (map[mark] && map[mark][vowel]) ? map[mark][vowel] : vowel;
}

function accentSyllable(word, nuclei, whichFromEnd, mark){
  // whichFromEnd: 1=ultima,2=penult,3=antepenult
  const idx = nuclei.length - whichFromEnd;
  if(idx < 0 || idx >= nuclei.length) return word;
  const n = nuclei[idx];
  // accent first vowel of nucleus
  const chars = Array.from(word);
  for(let i=n.start;i<n.end;i++){
    if(isVowel(chars[i])){ chars[i] = addAccentToVowel(chars[i], mark); break; }
  }
  return chars.join('');
}

function guessAccent(raw){
  const cleaned = stripToLetters(raw).trim();
  const w = normalizeGreek(cleaned);
  const nuclei = syllabifyRough(w);

  let why = [];
  let meta = [];

  if(!w){
    return {out:'—', meta:'Type a Greek word.', why:["(Nothing to analyze yet.)"]};
  }

  // If phrase, analyze last token
  const tokens = w.split(/\s+/).filter(Boolean);
  const last = tokens[tokens.length-1];
  const lastNuclei = syllabifyRough(last);

  let target = last;
  let out = last;

  if(!endsWithRos(target)){
    why.push("The last word doesn’t end in -ρος, so I won’t apply the -ρος rules.");
    meta.push(`Syllables (rough): ${lastNuclei.length}`);
    return {out: cleaned, meta: meta.join(' · '), why};
  }

  // Exception mentioned: γαμβρός
  if(target === 'γαμβρος'){
    out = accentSyllable(target, lastNuclei, 1, 'acute');
    why.push("Exception in the passage: γαμβρός is oxytone (accent on the ultima)." );
    meta.push("Rule hit: explicit exception (γαμβρός)");
    return {out: reassemble(cleaned, last, out), meta: meta.join(' · '), why};
  }

  const syl = lastNuclei.length;
  meta.push(`Syllables (rough): ${syl}`);

  // Disyllables special cases
  if(syl === 2){
    if(startsWithNeCluster(target)){
      out = accentSyllable(target, lastNuclei, 1, 'acute');
      why.push("Disyllable in -ρος starting with νε- plus a consonant: toy follows Herodian’s νεκρός/νεβρός/νεφρός pattern → oxytone." );
      meta.push("Rule hit: νε- disyllable → oxytone");
      return {out: reassemble(cleaned, last, out), meta: meta.join(' · '), why};
    }

    if(hasBCluster(target)){
      // barytone: we’ll put acute on penult (dictionary form), and note grave in running text.
      out = accentSyllable(target, lastNuclei, 2, 'acute');
      why.push("Disyllable with β-cluster (…βρος/…μβρος): toy treats it as barytone (accent not on ultima), like Ἄβρος/Ἕβρος/ὄμβρος." );
      why.push("Note: ‘grave’ is a running-text variant of an acute on the final syllable; here we’re simply making it non-oxytone." );
      meta.push("Rule hit: β-cluster disyllable → barytone");
      return {out: reassemble(cleaned, last, out), meta: meta.join(' · '), why};
    }

    if(startsWithOAndHasDoubleConsonant(target)){
      out = accentSyllable(target, lastNuclei, 2, 'acute');
      why.push("General note: disyllables in -ος beginning with ο- and having a consonant cluster tend to be barytone (e.g. ὄμβρος)." );
      meta.push("Rule hit: ο- + cluster → barytone");
      return {out: reassemble(cleaned, last, out), meta: meta.join(' · '), why};
    }

    // default for disyllabic -ρος: penult acute
    out = accentSyllable(target, lastNuclei, 2, 'acute');
    why.push("Default toy behavior for disyllabic -ρος: accent the penult (barytone)." );
    meta.push("Rule hit: default disyllable");
    return {out: reassemble(cleaned, last, out), meta: meta.join(' · '), why};
  }

  // Polysyllables
  if(hasOuInPenult(target)){
    if(syl === 3){
      if(consonantClusterBeforeOu(target)){
        // penult circumflex on ου
        out = accentSyllable(target, lastNuclei, 2, 'circ');
        why.push("Trisyllable in -ουρος with a consonant cluster right before ου: toy imitates ἀρκτοῦρος / ἀγχοῦρος / κλαγγοῦρος → circumflex on the penult." );
        meta.push("Rule hit: cluster before ου → penult circumflex");
        return {out: reassemble(cleaned, last, out), meta: meta.join(' · '), why};
      }

      // If user flags initial long in builder, we mark oxytone.
      if(/#long$/.test(w)){
        out = accentSyllable(target, lastNuclei, 1, 'acute');
        why.push("Trisyllable in -ουρος with ‘initial long’ (user flag): toy follows οἰκουρός/κηπουρός/τηλουρός → oxytone." );
        meta.push("Rule hit: trisyllable + initial long (flag) → oxytone");
        return {out: reassemble(cleaned, last, out), meta: meta.join(' · '), why};
      }

      // Otherwise, prefer antepenult acute (as in ἐπίκουρος) but admit ambiguity.
      out = accentSyllable(target, lastNuclei, 3, 'acute');
      why.push("Polysyllable in -ρος with ου in the penult: toy prefers antepenult accent (e.g. ἐπίκουρος)." );
      why.push("But Herodian also notes some trisyllables can be oxytone under conditions; this toy can’t reliably detect vowel length, so it defaults to antepenult unless you flag ‘initial long’." );
      meta.push("Rule hit: -ουρος → antepenult (default)");
      return {out: reassemble(cleaned, last, out), meta: meta.join(' · '), why};
    }

    // 4+ syllables: antepenult
    out = accentSyllable(target, lastNuclei, 3, 'acute');
    why.push("More than two syllables + -ουρος: toy follows the passage’s generalization → antepenult accent." );
    meta.push("Rule hit: polysyllable -ουρος → antepenult");
    return {out: reassemble(cleaned, last, out), meta: meta.join(' · '), why};
  }

  // Polysyllabic -ρος without -ουρος: default antepenult
  out = accentSyllable(target, lastNuclei, 3, 'acute');
  why.push("Word ends in -ρος but not -ουρος: toy defaults to antepenult accent (very rough)." );
  meta.push("Rule hit: default polysyllable");
  return {out: reassemble(cleaned, last, out), meta: meta.join(' · '), why};
}

function reassemble(originalCleaned, lastNorm, lastAccented){
  // Reassemble into the original (possibly accented) input shape as best we can.
  // We'll replace the last token in a diacritic-stripped version of the input.
  const base = stripDiacritics(stripToLetters(originalCleaned)).replace(/ς/g,'σ');
  const parts = base.trim().split(/\s+/);
  if(parts.length===0) return lastAccented;
  parts[parts.length-1] = lastAccented;
  return parts.join(' ');
}

function render(res){
  $('#outWord').textContent = res.out;
  $('#outMeta').textContent = res.meta;
  const ol = $('#outWhy');
  ol.innerHTML = '';
  res.why.forEach(line => {
    const li = document.createElement('li');
    li.textContent = line;
    ol.appendChild(li);
  });
}

function run(){
  const val = $('#inp').value;
  const res = guessAccent(val);
  render(res);
}

$('#btn').addEventListener('click', run);
$('#inp').addEventListener('keydown', (e)=>{ if(e.key==='Enter') run(); });
$('#btnClear').addEventListener('click', ()=>{ $('#inp').value=''; $('#inp').focus(); render({out:'—', meta:'—', why:['Enter a word ending in -ρος to see a guess.']}); });

$$('.chip').forEach(b=>b.addEventListener('click', ()=>{ $('#inp').value = b.dataset.ex; run(); }));

$('#btnBuild').addEventListener('click', ()=>{
  const pre = normalizeGreek($('#pre').value).replace(/\s+/g,'');
  const stem = $('#stem').value;
  let word = pre + 'ουρος';
  if(stem.includes('#long')) word = pre + 'ουρος#long';
  $('#inp').value = word;
  run();
});

// initial render
render({out:'—', meta:'Try an example chip, or type your own.', why:[
  'Type an unaccented form like επικουρος / αρκτουρος / νεκρος / αβρος / ομβρος / γαμβρος.',
  'The toy will add one accent mark based on a few Herodian-inspired patterns.'
]});

