    {w:'ὠχρός', note:'adjective: oxytone in passage'},
    {w:'μακρός', note:'-κρος from consonant: oxytone'},
    {w:'πικρός', note:'-κρος from consonant: oxytone'},
    {w:'μικρός', note:'-κρος from consonant: oxytone'},
    {w:'νεκρός', note:'-κρος from consonant: oxytone'},
    {w:'Λοκρός', note:'ethnic/founder: oxytone'},
    {w:'Τευκρός', note:'ethnic: oxytone'},
    {w:'Τεῦκρος', note:'proper name: different accent (toy will not fully capture)'}
  ];

  function buildChips(){
    chipsEl.innerHTML = '';
    examples.slice(0, 18).forEach(ex => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'chip';
      b.textContent = ex.w;
      b.title = ex.note;
      b.addEventListener('click', () => {
        inEl.value = ex.w;
        analyze();
      });
      chipsEl.appendChild(b);
    });
  }

  // --- Greek normalization helpers ---
  // Remove combining marks (accents, breathings, iota subscript, diaeresis, etc.)
  function stripDiacritics(s){
    return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  }

  // Lowercase, keep Greek letters, remove spaces/punct except apostrophe
  function normalizeGreek(s){
    let t = s.trim();
    t = t.replace(/\s+/g,' ');
    // keep letters and spaces; drop most punctuation
    t = t.replace(/[^\p{L}\p{M}\s’'··]/gu,'');
    t = t.toLowerCase();
    return t;
  }

  function lastWord(s){
    const parts = s.trim().split(/\s+/).filter(Boolean);
    return parts.length ? parts[parts.length-1] : '';
  }

  // Very simple syllabification: split into vowel-groups
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ','ϊ','ϋ','ΐ','ΰ']);
  function syllables(word){
    const w = word;
    if(!w) return [];
    const chars = Array.from(w);
    const syl = [];
    let cur = '';
    let seenV = false;

    const isV = (ch) => vowels.has(ch) || vowels.has(stripDiacritics(ch));

    for(let i=0;i<chars.length;i++){
      const ch = chars[i];
      cur += ch;
      if(isV(ch)){
        seenV = true;
        // if next char starts a new vowel group, cut here
        const next = chars[i+1];
        if(next && isV(next)){
          syl.push(cur);
          cur = '';
          seenV = false;
        }
      } else {
        // consonant after we've seen a vowel: if next is vowel, cut before next vowel
        const next = chars[i+1];
        if(seenV && next && isV(next)){
          syl.push(cur);
          cur = '';
          seenV = false;
        }
      }
    }
    if(cur) syl.push(cur);
    return syl.filter(x => x.length);
  }

  function addAcuteToSyllable(word, sylIndex){
    // Put acute on first vowel of chosen syllable (after stripping diacritics)
    const plain = stripDiacritics(word);
    const syl = syllables(plain);
    if(!syl.length) return plain;
    const idx = Math.max(0, Math.min(sylIndex, syl.length-1));

    // Map syllables back to string positions
    let start = 0;
    for(let i=0;i<syl.length;i++){
      const part = syl[i];
      const end = start + part.length;
      if(i === idx){
        const segment = plain.slice(start, end);
        const accented = accentFirstVowel(segment);
        return plain.slice(0,start) + accented + plain.slice(end);
      }
      start = end;
    }
    return plain;
  }

  function accentFirstVowel(seg){
    const chars = Array.from(seg);
    for(let i=0;i<chars.length;i++){
      const base = stripDiacritics(chars[i]);
      const acuteMap = {
        'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ'
      };
      if(acuteMap[base]){
        chars[i] = acuteMap[base];
        break;
      }
    }
    return chars.join('');
  }

  // --- Rule-of-thumb classifier inspired by the passage ---
  function classify(wordPlain){
    // wordPlain should be stripped of diacritics and lowercased
    const w = wordPlain;
    const info = {
      ending: '—',
      pattern: '—',
      accent: 'penult', // 'ultima' or 'penult'
      why: ''
    };

    if(!w){
      info.why = 'Type something Greek.';
      return info;
    }

    // Focus on last word only
    const lw = lastWord(w);

    // detect endings
    if(lw.endsWith('κρος')){
      info.ending = '-κρος';
      // passage: disyllabic -κρος beginning with consonant -> oxytone
      const startsWithVowel = ['α','ε','η','ι','ο','υ','ω'].includes(lw[0]);
      info.pattern = startsWithVowel ? 'starts with vowel (rule in passage is for consonant-start)' : 'consonant-start -κρος';
      info.accent = startsWithVowel ? 'ultima' : 'ultima';
      info.why = startsWithVowel
        ? 'Passage says consonant-start -κρος are oxytone; we still guess oxytone here.'
        : '“Τὰ εἰς κρος … ἀπὸ συμφώνου ἀρχόμενα ὀξύνεται” → guess oxytone.';
      return info;
    }

    if(lw.endsWith('ρος')){
      info.ending = '-ρος';

      // -γρος with insertion of gamma: monogender barytone; trigender oxytone.
      // Toy heuristic: if it contains "γρ" and not "υγρ/λυγρ"? We'll special-case known trigender-ish stems.
      if(lw.includes('γρ')){
        info.pattern = 'contains γρ';
        // heuristic: if starts with υ/λυ/α (υγρος, λυγρος, αγρος) -> oxytone; else penult
        if(lw.startsWith('υγρ') || lw.startsWith('λυγρ') || lw === 'αγρος'){
          info.accent = 'ultima';
          info.why = 'Passage: trigender λυγρός, ὑγρός (and ἀγρός) are oxytone.';
        } else {
          info.accent = 'penult';
          info.why = 'Passage: monogender -γρος (φάγρος, πάγρος, γόγγρος) “βαρύνεται” → toy makes it non-oxytone.';
        }
        return info;
      }

      // δρος: monogender barytone (Andros, Skidros, Kodros)
      if(lw.includes('δρ')){
        info.pattern = 'contains δρ';
        info.accent = 'penult';
        info.why = 'Passage: disyllabic -δρος monogender “βαρύνεται” (Ἄνδρος, Σκίδρος, Κόδρος).';
        return info;
      }

      // rough before rho: θρ / χρ / φρ / βληχρ etc. -> oxytone for trigender
      if(lw.includes('θρ') || lw.includes('χρ') || lw.includes('φρ')){
        info.pattern = 'θρ/χρ/φρ (rough-ish cluster before ρ)';
        info.accent = 'ultima';
        info.why = 'Passage: trigender with rough before ρ are oxytone (νωθρός, σαθρός, ψυχρός, ἐχθρός, αἰσχρός, στιφρός, βληχρός).';
        return info;
      }

      // special note: αφρος (liquid) oxytone vs ethnic Aphros barytone; we can’t know sense.
      if(lw === 'αφρος'){
        info.pattern = 'special case ἀφρος';
        info.accent = 'ultima';
        info.why = 'Passage notes ἀφρός (foam) is oxytone, but ethnic Ἄφρος is barytone; toy defaults to foam.';
        return info;
      }

      // default for -ρος: guess oxytone (many adjectives)
      info.pattern = 'default -ρος';
      info.accent = 'ultima';
      info.why = 'Default guess: many -ρός adjectives are oxytone; passage gives several oxytone sets.';
      return info;
    }

    // -ος starting with ω without iota: barytone (ὦμος). Toy: if starts with ω and is disyllabic-ish.
    if(lw.endsWith('ος') && lw.startsWith('ω') && !lw.startsWith('ωι') && !lw.startsWith('ῳ')){
      info.ending = '-ος';
      info.pattern = 'ω- initial (no ι)';
      info.accent = 'penult';
      info.why = 'Passage: disyllabic monogender in -ος beginning with ω (no ι) “βαρύνεται” (ὦμος).';
      return info;
    }

    info.ending = '(other)';
    info.pattern = 'no rule triggered';
    info.accent = 'penult';
    info.why = 'This toy focuses on -ρος/-κρος patterns from the passage.';
    return info;
  }

  function renderSandbox(wordPlain, suggestedAccent){
    const syl = syllables(wordPlain);
    segEl.innerHTML = '';

    if(!wordPlain){
      sandOutEl.textContent = '—';
      return;
    }

    if(syl.length === 0){
      sandOutEl.textContent = wordPlain;
      return;
    }

    // choose default index
    let idx = syl.length - 1; // ultima
    if(suggestedAccent === 'penult') idx = Math.max(0, syl.length - 2);

    function setIdx(newIdx){
      idx = newIdx;
      Array.from(segEl.children).forEach((b, i) => b.classList.toggle('on', i === idx));
      sandOutEl.textContent = addAcuteToSyllable(wordPlain, idx);
    }

    syl.forEach((s, i) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.textContent = s;
      b.addEventListener('click', () => setIdx(i));
      segEl.appendChild(b);
    });

    setIdx(idx);
  }

  function analyze(){
    const raw = inEl.value;
    const norm = normalizeGreek(raw);
    const target = lastWord(norm);

    const plain = stripEl.checked ? stripDiacritics(target) : target;
    const plainLower = plain.toLowerCase();

    const info = classify(plainLower);

    normEl.textContent = plainLower || '—';
    endingEl.textContent = info.ending + (info.pattern !== '—' ? `  (${info.pattern})` : '');

    // Build guess word with acute on ultima or penult
    const syl = syllables(plainLower);
    let guess = plainLower;
    if(syl.length){
      const idx = info.accent === 'ultima' ? syl.length - 1 : Math.max(0, syl.length - 2);
      guess = addAcuteToSyllable(plainLower, idx);
    }

    const badge = info.accent === 'ultima'
      ? '<span class="badge"><span class="markGood">oxytone</span> (acute on last)</span>'
      : '<span class="badge"><span class="markWarn">not-oxytone</span> (toy: penult)</span>';

    guessEl.innerHTML = `${escapeHtml(guess)} ${badge}`;
    whyEl.textContent = info.why;

    renderSandbox(plainLower, info.accent);
  }

  function escapeHtml(s){
    return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  goEl.addEventListener('click', analyze);
  randEl.addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inEl.value = ex.w;
    analyze();
  });

  inEl.addEventListener('input', () => {
    if(autoEl.checked) analyze();
  });
  stripEl.addEventListener('change', analyze);

  buildChips();
  inEl.value = 'λυγρος';
  analyze();
})();

