:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --ink:#e9ecff;
  --muted:#b7bddb;
  --faint:#7f86aa;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --bad:#fb7185;
  --good:#34d399;
  --border:rgba(255,255,255,.10);
}
*{box-sizing:border-box}
body{margin:0;background:linear-gradient(180deg,#0b0e1a, #0f1220 40%, #0b0e1a);color:var(--ink);font:15px/1.35 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif}
.wrap{max-width:980px;margin:24px auto;padding:0 16px 28px}
h2{margin:0 0 6px;font-size:22px;letter-spacing:.2px}
.sub{margin:0 0 14px;color:var(--muted)}
.panel{background:rgba(255,255,255,.03);border:1px solid var(--border);border-radius:14px;padding:14px 14px 12px;margin:12px 0;box-shadow:0 10px 30px rgba(0,0,0,.25)}
label{display:block;color:var(--muted);font-size:12px;margin:0 0 6px}
textarea{width:100%;resize:vertical;min-height:56px;max-height:160px;border-radius:12px;border:1px solid var(--border);background:rgba(0,0,0,.25);color:var(--ink);padding:10px 12px;font-size:16px;outline:none}
textarea:focus{border-color:rgba(125,211,252,.55);box-shadow:0 0 0 3px rgba(125,211,252,.12)}
.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-top:10px}
button{border:1px solid rgba(125,211,252,.35);background:linear-gradient(180deg,rgba(125,211,252,.22),rgba(125,211,252,.10));color:var(--ink);padding:9px 12px;border-radius:12px;cursor:pointer;font-weight:650}
button:hover{border-color:rgba(125,211,252,.65)}
button.ghost{border-color:var(--border);background:rgba(255,255,255,.04);font-weight:600;color:var(--muted)}
button.ghost:hover{color:var(--ink)}
.chk{display:flex;gap:8px;align-items:center;color:var(--muted);font-size:13px}
.chk input{accent-color:var(--accent)}
.mini{display:flex;gap:8px;align-items:center}
select{border-radius:12px;border:1px solid var(--border);background:rgba(0,0,0,.25);color:var(--ink);padding:8px 10px;outline:none}
select:focus{border-color:rgba(167,139,250,.55);box-shadow:0 0 0 3px rgba(167,139,250,.12)}
.outHead{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;flex-wrap:wrap}
.out h3{margin:0;font-size:16px}
.hint{color:var(--faint);font-size:12px;max-width:560px}
.pill{display:inline-block;border:1px solid var(--border);padding:2px 8px;border-radius:999px;margin:2px 2px;background:rgba(255,255,255,.03);cursor:pointer}
.pill:hover{border-color:rgba(125,211,252,.55);color:var(--ink)}
#out{margin-top:10px}
.card{border:1px solid var(--border);border-radius:14px;padding:12px;background:rgba(0,0,0,.18);margin:10px 0}
.wordLine{display:flex;gap:10px;align-items:baseline;flex-wrap:wrap}
.greek{font-size:22px;font-weight:750;letter-spacing:.2px}
.raw{color:var(--faint);font-size:13px}
.tag{font-size:12px;padding:2px 8px;border-radius:999px;border:1px solid var(--border);color:var(--muted)}
.tag.good{border-color:rgba(52,211,153,.35);color:rgba(167,243,208,.95)}
.tag.bad{border-color:rgba(251,113,133,.35);color:rgba(254,202,202,.95)}
.expl{margin-top:8px;color:var(--muted)}
.small{color:var(--faint);font-size:12px;margin:8px 0 0}
.rules{margin:8px 0 0 18px;color:var(--muted)}
summary{cursor:pointer;color:var(--ink);font-weight:700}
hr{border:none;border-top:1px solid var(--border);margin:10px 0}
.kbd{font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;font-size:12px;color:var(--muted)}

passages.gadget_js:
const elIn = document.getElementById('in');
const elOut = document.getElementById('out');
const elGo = document.getElementById('go');
const elClear = document.getElementById('clear');
const elKeep = document.getElementById('keepDiacritics');
const elMode = document.getElementById('mode');
const elView = document.getElementById('view');

// --- Greek helpers (toy-level) ---
const combiningMarks = /[\u0300-\u036F]/g;

function stripCombining(s){
  return s.normalize('NFD').replace(combiningMarks,'').normalize('NFC');
}

function hasAccent(s){
  const n = s.normalize('NFD');
  return /[\u0301\u0342\u0300]/.test(n); // acute, circumflex, grave
}

function removeAccentsKeepBreathing(s){
  // remove tonos/oxia, varia, perispomeni; keep breathings/diaeresis/iota-subscript etc.
  const n = s.normalize('NFD');
  const out = n.replace(/[\u0301\u0342\u0300]/g,'');
  return out.normalize('NFC');
}

function isGreekVowelBase(ch){
  return 'αεηιουωΑΕΗΙΟΥΩ'.includes(ch);
}

function vowelPositions(word){
  // returns indices in NFC string where a vowel letter occurs (ignoring combining marks)
  const n = word.normalize('NFD');
  // map from NFD positions to NFC indices is hard; instead, work in NFC by scanning codepoints
  const chars = Array.from(word);
  const pos = [];
  for(let i=0;i<chars.length;i++){
    const base = stripCombining(chars[i]);
    if(base && isGreekVowelBase(base)) pos.push(i);
  }
  return pos;
}

function addAcuteOnVowel(word, vowelIndex){
  const chars = Array.from(word);
  if(vowelIndex < 0 || vowelIndex >= chars.length) return word;
  // Add combining acute after the character in NFD, then NFC.
  const n = chars[vowelIndex].normalize('NFD');
  // If already has acute/circ/grave, leave it.
  if(/[\u0301\u0342\u0300]/.test(n)) return word;
  chars[vowelIndex] = (n + '\u0301').normalize('NFC');
  return chars.join('');
}

function accentOxytone(word){
  const w = removeAccentsKeepBreathing(word);
  const vpos = vowelPositions(w);
  if(vpos.length === 0) return w;
  return addAcuteOnVowel(w, vpos[vpos.length-1]);
}

function accentParoxytone(word){
  const w = removeAccentsKeepBreathing(word);
  const vpos = vowelPositions(w);
  if(vpos.length < 2) return accentOxytone(w);
  return addAcuteOnVowel(w, vpos[vpos.length-2]);
}

function barytone(word){
  return removeAccentsKeepBreathing(word);
}

function tokenizeGreekish(text){
  // Keep Greek words; split on whitespace/punct.
  return text
    .split(/[^\p{L}\p{M}]+/u)
    .filter(Boolean);
}

function guessRule(word){
  const raw = word;
  const w = stripCombining(word).toLowerCase();

  // Only play with -ρος / -ρος-like endings.
  const endsRos = w.endsWith('ρος');
  if(!endsRos){
    return {kind:'skip', label:'(not -ρος)', apply:(x)=>x, why:'Does not end in -ρος, so the toy leaves it alone.'};
  }

  // Compounds mentioned: -ανδρος/-εδρος/-υδρος barytone
  if(/(ανδρος|εδρος|υδρος)$/.test(w)){
    return {kind:'barytone', label:'compound (-ανδρος/-εδρος/-υδρος)', apply:barytone,
      why:'Herodian notes many compounds like δείλανδρος, ἄνανδρος, ἔνυδρος are barytone (toy simplification).'};
  }

  // -προς (π before ρ): paroxytone (toy uses acute on penult)
  if(/προς$/.test(w)){
    return {kind:'paroxytone', label:'π before ρ (-προς)', apply:accentParoxytone,
      why:'Pattern: simple -προς words (κόπρος, κάπρος, Κύπρος) are treated as paroxytone in this toy.'};
  }

  // -ρρος adjectives: oxytone
  if(/ρρος$/.test(w)){
    return {kind:'oxytone', label:'double ρρ (-ρρος)', apply:accentOxytone,
      why:'Herodian: adjectival -ρρος forms are oxytone (e.g. στερρός, πυρρός as adjective).'};
  }

  // disyllabic -τρος (or cluster with τ before ρ): barytone
  // crude syllable count by vowel count
  const vcount = vowelPositions(removeAccentsKeepBreathing(word)).length;
  if(vcount === 2 && /τρος$/.test(w)){
    return {kind:'barytone', label:'disyllabic -τρος', apply:barytone,
      why:'Herodian: many disyllables in -τρος that are not adjectives are barytone (Χύτρος, Λεῦκτρος, οἶστρος, βόστρος, Ἴστρος).'};
  }

  // longer adjectives with consonant cluster before -ρος: oxytone (toy: -κρος/-χρος/-βρος/-γρος)
  if(vcount >= 3 && /(κρος|χρος|βρος|γρος)$/.test(w)){
    return {kind:'oxytone', label:'longer + cluster (-κρος/-χρος...)', apply:accentOxytone,
      why:'Herodian: longer adjectival -ρος forms with clusters tend to be oxytone (φαλακρός, ἐρυθρός, πενιχρός).'};
  }

  // fallback: paroxytone for -ρος
  return {kind:'paroxytone', label:'default -ρος guess', apply:accentParoxytone,
    why:'Fallback guess: many -ρος words are shown with a prominent penult accent in examples; this toy defaults to paroxytone.'};
}

function applyMode(word, rule){
  const mode = elMode.value;
  if(mode === 'forceOxytone') return {out: accentOxytone(word), tag:'forced oxytone', why:'Mode override: acute on last vowel.'};
  if(mode === 'forceParoxytone') return {out: accentParoxytone(word), tag:'forced paroxytone', why:'Mode override: acute on penult vowel.'};
  if(mode === 'forceBarytone') return {out: barytone(word), tag:'forced barytone', why:'Mode override: remove accent marks.'};
  // auto
  return {out: rule.apply(word), tag: rule.label, why: rule.why};
}

function render(){
  const text = elIn.value.trim();
  const words = tokenizeGreekish(text);
  if(!text){
    elOut.innerHTML = '<div class="small">Enter something above. The toy will process each Greek-looking word.</div>';
    return;
  }
  if(words.length === 0){
    elOut.innerHTML = '<div class="small">No words found (try Greek letters).</div>';
    return;
  }

  const view = elView.value;
  const keep = elKeep.checked;

  const cards = words.map(w => {
    const rule = guessRule(w);
    let outWord = w;
    let tag = rule.label;
    let why = rule.why;

    if(rule.kind === 'skip'){
      // leave as-is
    } else {
      if(keep && hasAccent(w)){
        outWord = w;
        tag = 'kept existing accent';
        why = 'Input already had an accent mark; “keep existing accents” is on.';
      } else {
        const applied = applyMode(w, rule);
        outWord = applied.out;
        tag = applied.tag;
        why = applied.why;
      }
    }

    const changed = (removeAccentsKeepBreathing(w) !== removeAccentsKeepBreathing(outWord)) || (w !== outWord);
    const tagClass = (rule.kind==='skip') ? '' : (changed ? 'good' : 'bad');

    const showAccented = (view === 'both' || view === 'accented');
    const showExplain = (view === 'both' || view === 'explain');

    return `
      <div class="card">
        <div class="wordLine">
          ${showAccented ? `<div class="greek">${escapeHtml(outWord)}</div>` : ''}
          ${showAccented ? `<div class="raw">from <span class="kbd">${escapeHtml(w)}</span></div>` : ''}
          <span class="tag ${tagClass}">${escapeHtml(tag)}</span>
        </div>
        ${showExplain ? `<div class="expl">${escapeHtml(why)}</div>` : ''}
      </div>
    `;
  }).join('');

  elOut.innerHTML = cards;
}

function escapeHtml(s){
  return String(s)
    .replaceAll('&','&amp;')
    .replaceAll('<','&lt;')
    .replaceAll('>','&gt;')
    .replaceAll('"','&quot;')
    .replaceAll("'",'&#39;');
}

elGo.addEventListener('click', render);
elClear.addEventListener('click', () => { elIn.value=''; render(); elIn.focus(); });
elIn.addEventListener('keydown', (e) => {
  if((e.ctrlKey || e.metaKey) && e.key === 'Enter') render();
});
[elKeep, elMode, elView].forEach(el => el.addEventListener('change', render));

// clickable examples
document.querySelectorAll('.pill').forEach(p => {
  p.addEventListener('click', () => {
    const t = p.textContent.trim();
    elIn.value = t;
    render();
    elIn.focus();
  });
});

render();

