const $ = (sel) => document.querySelector(sel);

const examples = [
  "Μίνυθρος",
  "Ἔρυθρος",
  "Χάραδρος",
  "Σκάμανδρος",
  "Μυρίανδρος",
  "Μαίανδρος",
  "Ἄντανδρος",
  "Τήλανδρος",
  "Φολέγανδρος",
  "Κάϋστρος",
  "Τέγεστρος",
  "Οἰνωτρός",
  "Καλαβρός",
  "Κανταβρός",
  "Ἴνσοβρος",
  "Θάσος",
  "Κάσος",
  "Ἄσος",
  "νόσος",
  "δρόσος",
  "μέσος",
  "ἴσος",
  "πόσος",
  "ὅσος",
  "τόσος"
];

// --- Greek helpers (toy-level) ---
const combiningMarks = /[\u0300-\u036f]/g;

function nfd(s){ return s.normalize('NFD'); }
function stripCombining(s){ return nfd(s).replace(combiningMarks,'').normalize('NFC'); }

// Remove polytonic/monotonic accents but keep base letters.
function stripDiacriticsGreek(s){
  // Also remove Greek tonos/oxia etc when precomposed by decomposing.
  return stripCombining(s);
}

function lowerGreek(s){
  return s.toLocaleLowerCase('el');
}

const vowels = new Set(["α","ε","η","ι","ο","υ","ω","ά","έ","ή","ί","ό","ύ","ώ","ϊ","ϋ","ΐ","ΰ"]);

function isVowel(ch){
  const base = stripDiacriticsGreek(ch);
  return vowels.has(ch) || vowels.has(base);
}

function syllabifyToy(word){
  // Split into vowel groups (very rough): each group = nucleus; attach following consonants up to next vowel.
  const w = word;
  const chars = Array.from(w);
  let nuclei = [];
  let i=0;
  while(i<chars.length){
    // find next vowel
    while(i<chars.length && !isVowel(chars[i])) i++;
    if(i>=chars.length) break;
    let start=i;
    i++;
    while(i<chars.length && isVowel(chars[i])) i++; // vowel group
    nuclei.push({vStart:start, vEnd:i});
  }
  if(nuclei.length===0) return {syllables:[w], nuclei};

  // Build syllables by cutting before each nucleus except first.
  let cuts = [0];
  for(let k=1;k<nuclei.length;k++) cuts.push(nuclei[k].vStart);
  cuts.push(chars.length);

  let syllables=[];
  for(let c=0;c<cuts.length-1;c++){
    syllables.push(chars.slice(cuts[c], cuts[c+1]).join(''));
  }

  // Now, for each syllable except last, move leading consonants of next syllable to previous syllable
  // leaving at least one consonant if there is a cluster? This is messy; keep simple: if next syllable starts with 2+ consonants, keep last consonant with next.
  for(let s=0;s<syllables.length-1;s++){
    const next = syllables[s+1];
    const nextChars = Array.from(next);
    let j=0;
    while(j<nextChars.length && !isVowel(nextChars[j])) j++;
    const onset = nextChars.slice(0,j);
    if(onset.length>=2){
      // move all but last consonant to previous
      const move = onset.slice(0,onset.length-1).join('');
      syllables[s] += move;
      syllables[s+1] = onset.slice(onset.length-1).join('') + nextChars.slice(j).join('');
    }
  }

  return {syllables, nuclei};
}

function hasConsonantCluster(word){
  const w = lowerGreek(stripDiacriticsGreek(word));
  // crude: any two consecutive consonants (Greek letters) excluding spaces/punct.
  const letters = Array.from(w).filter(ch => /[α-ω]/.test(ch));
  for(let i=0;i<letters.length-1;i++){
    if(!isVowel(letters[i]) && !isVowel(letters[i+1])) return true;
  }
  return false;
}

function endsWithRos(word){
  const w = lowerGreek(stripDiacriticsGreek(word)).replace(/[^α-ω]/g,'');
  return w.endsWith('ρος');
}

function endsWithSos(word){
  const w = lowerGreek(stripDiacriticsGreek(word)).replace(/[^α-ω]/g,'');
  return w.endsWith('σος');
}

function accentuateMonotonic(baseWord, syllables, targetFromEnd){
  // targetFromEnd: 1=ultima,2=penult,3=antepenult
  // Put tonos on first vowel of target syllable.
  const plain = stripDiacriticsGreek(baseWord);
  const syl = syllabifyToy(plain).syllables;
  const idx = syl.length - targetFromEnd;
  if(idx<0 || idx>=syl.length) return plain;

  // Find position in full string where that syllable begins.
  let start=0;
  for(let i=0;i<idx;i++) start += Array.from(syl[i]).length;
  const chars = Array.from(plain);

  // Find first vowel in that syllable span.
  const spanLen = Array.from(syl[idx]).length;
  let pos=-1;
  for(let k=0;k<spanLen;k++){
    if(isVowel(chars[start+k])){ pos=start+k; break; }
  }
  if(pos===-1) return plain;

  const map = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ',
    'ϊ':'ΐ','ϋ':'ΰ','Ϊ':'Ϊ','Ϋ':'Ϋ'
  };
  const ch = chars[pos];
  const base = stripDiacriticsGreek(ch);
  // Preserve case by mapping base.
  const repl = map[ch] || map[base] || ch;
  chars[pos] = repl;
  return chars.join('');
}

function analyze(word, opts){
  const raw = word.trim();
  if(!raw) return {ok:false, msg:"Type a Greek word."};

  const syl = syllabifyToy(stripDiacriticsGreek(raw)).syllables;
  const sylCount = syl.length;
  const cluster = hasConsonantCluster(raw);
  const ros = endsWithRos(raw);
  const sos = endsWithSos(raw);

  let target = null;
  let rule = "";

  if(ros && sylCount>2 && cluster && !opts.ethnic){
    target = 3; // antepenult
    rule = "Rule A: -ρος proper name (>2 syllables) + consonant cluster → antepenult accent (proparoxytone).";
  } else if(sos && sylCount===2){
    target = 2; // penult
    rule = "Rule B: disyllable in -σος → penult accent (paroxytone), like Θάσος / Κάσος / Ἄσος.";
  } else if(ros && opts.ethnic){
    rule = "Ethnic toggle is ON: Herodian notes ethnics can be exceptions to the -ρος antepenult tendency.";
  } else if(ros){
    rule = "Ends in -ρος, but the toy didn’t detect both (>2 syllables) and a clear consonant cluster; no strong suggestion.";
  } else if(sos){
    rule = "Ends in -σος, but the toy only applies the passage’s note to disyllables.";
  } else {
    rule = "No matching ending (-ρος / -σος) for this passage-based toy.";
  }

  let suggested = stripDiacriticsGreek(raw);
  if(target){
    suggested = opts.monotonic ? accentuateMonotonic(raw, syl, target) : accentuateMonotonic(raw, syl, target);
  }

  // Build scan line
  const scan = syl.map((s,i)=>{
    const clean = s;
    const mark = (target && i===syl.length-target) ? "ˈ" : "";
    return mark + clean;
  }).join(" · ");

  return {
    ok:true,
    raw,
    suggested,
    rule,
    syl,
    scan,
    meta:{sylCount, cluster, ros, sos, ethnic:opts.ethnic}
  };
}

function render(res){
  $('#suggest').textContent = res.ok ? res.suggested : '—';
  $('#rule').textContent = res.ok ? res.rule : res.msg;
  if(res.ok){
    const flags = [];
    flags.push(`${res.meta.sylCount} syll.`);
    if(res.meta.ros) flags.push("-ρος");
    if(res.meta.sos) flags.push("-σος");
    flags.push(res.meta.cluster ? "cluster✓" : "cluster×");
    if(res.meta.ethnic) flags.push("ethnic");
    $('#scan').textContent = `${res.scan}\n[${flags.join(' | ')}]`;
  } else {
    $('#scan').textContent = '—';
  }
}

function run(){
  const word = $('#inp').value;
  const res = analyze(word, {ethnic: $('#ethnic').checked, monotonic: $('#monotonic').checked});
  render(res);
}

function setInput(v){
  $('#inp').value = v;
  run();
  $('#inp').focus();
}

function buildChips(){
  const box = $('#chips');
  box.innerHTML = '';
  const pick = [...examples].slice(0, 14);
  for(const w of pick){
    const b = document.createElement('button');
    b.type='button';
    b.className='chip';
    b.textContent = w;
    b.addEventListener('click', ()=> setInput(w));
    box.appendChild(b);
  }
}

$('#go').addEventListener('click', run);
$('#inp').addEventListener('keydown', (e)=>{ if(e.key==='Enter') run(); });
$('#rand').addEventListener('click', ()=>{
  const w = examples[Math.floor(Math.random()*examples.length)];
  setInput(w);
});
$('#clear').addEventListener('click', ()=>{
  $('#inp').value='';
  $('#ethnic').checked=false;
  render({ok:false,msg:"Enter a word and click “Accent it”."});
  $('#inp').focus();
});
$('#ethnic').addEventListener('change', run);
$('#monotonic').addEventListener('change', run);

buildChips();
render({ok:false,msg:"Enter a word and click “Accent it”."});

