const $ = (sel) => document.querySelector(sel);

const examples = [
  {w:"Ναῖσος", note:"barytone (Herodian)"},
  {w:"Βλαῖσος", note:"barytone (Herodian)"},
  {w:"Κροῖσος", note:"barytone (Herodian)"},
  {w:"Βροῦσος", note:"barytone (Herodian)"},
  {w:"κόρσος", note:"barytone list"},
  {w:"μόλσος", note:"barytone list"},
  {w:"θύρσος", note:"barytone list"},
  {w:"μύρσος", note:"barytone list"},
  {w:"πυρσός", note:"oxytone exception"},
  {w:"κιρσός", note:"oxytone exception"},
  {w:"ὀρσός", note:"oxytone exception"},
  {w:"Μαρσός", note:"oxytone exception"},
  {w:"ταρσός", note:"oxytone exception"},
  {w:"Βάγαρσος", note:"polysyllable barytone"},
  {w:"Μάγαρσος", note:"polysyllable barytone"},
  {w:"Μαίμαρσος", note:"polysyllable barytone"},
  {w:"Μόκαρσος", note:"polysyllable barytone"},
  {w:"Ἀγάθυρσος", note:"polysyllable barytone"},
  {w:"Ἄορσος", note:"ethnic"}
];

// --- Greek helpers (toy-level) ---
const COMBINING = /[\u0300-\u036f]/g;
function nfd(s){return s.normalize('NFD');}
function stripDiacritics(s){return nfd(s).replace(COMBINING,'').normalize('NFC');}
function stripAccentsOnly(s){
  // remove tonos/oxia/varia/perispomeni and breathings too (toy)
  return nfd(s)
    .replace(/[\u0300\u0301\u0342\u0313\u0314\u0345]/g,'')
    .replace(COMBINING,'')
    .normalize('NFC');
}
function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code>=0x0370 && code<=0x03FF) || (code>=0x1F00 && code<=0x1FFF);
}
function onlyGreekAndMarks(s){
  const t = nfd(s);
  for(const ch of t){
    if(ch===' '||ch==='-'||ch==='·'||ch==='ʼ'||ch==="'"||ch==='’') continue;
    const cp = ch.codePointAt(0);
    const isMark = (cp>=0x0300 && cp<=0x036F);
    if(!isMark && !isGreekLetter(ch)) return false;
  }
  return true;
}

const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
function isVowel(baseChar){return vowels.has(baseChar);}

function syllableCountApprox(word){
  // count vowel letters in stripped form; treat αι/ει/οι/υι/αυ/ευ/ου as 1 (very rough)
  let s = stripAccentsOnly(word);
  // remove spaces/hyphens
  s = s.replace(/[\s\-·ʼ'’]/g,'');
  const lower = s.toLowerCase();
  const diph = ['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ωυ'];
  let i=0, count=0;
  while(i<lower.length){
    const two = lower.slice(i,i+2);
    if(diph.includes(two)) {count++; i+=2; continue;}
    const ch = lower[i];
    if(isVowel(ch)) count++;
    i++;
  }
  return count;
}

function penultVowelBase(word){
  // return base vowel letter of penult syllable (approx): find vowels from left, pick second last
  let s = stripAccentsOnly(word).replace(/[\s\-·ʼ'’]/g,'');
  const lower = s.toLowerCase();
  // collect vowel positions (treat diphthongs as one, take first vowel char as representative)
  const diph = ['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ωυ'];
  let i=0; const reps=[];
  while(i<lower.length){
    const two = lower.slice(i,i+2);
    if(diph.includes(two)) {reps.push(lower[i]); i+=2; continue;}
    const ch = lower[i];
    if(isVowel(ch)) reps.push(ch);
    i++;
  }
  if(reps.length<2) return null;
  return reps[reps.length-2];
}

function endsWithSos(word){
  const s = stripAccentsOnly(word).toLowerCase().replace(/[\s\-·ʼ'’]/g,'');
  return s.endsWith('σος');
}

function applyAcuteOnUltima(word){
  // add acute to last vowel in the word (toy)
  const map = { 'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
                'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ' };
  let s = stripAccentsOnly(word);
  // work in NFD to avoid surprises
  let chars = Array.from(s);
  for(let i=chars.length-1;i>=0;i--){
    const ch = chars[i];
    if(map[ch]){ chars[i]=map[ch]; break; }
  }
  return chars.join('');
}

function applyAcuteOnPenult(word){
  // add acute to the penult vowel (approx): find vowel nuclei and accent the second last
  const map = { 'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
                'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ' };
  let s = stripAccentsOnly(word);
  let chars = Array.from(s);
  // find vowel indices (simple: individual vowel letters)
  const idx=[];
  for(let i=0;i<chars.length;i++){
    const base = stripDiacritics(chars[i]);
    if(isVowel(base)) idx.push(i);
  }
  if(idx.length<2) return applyAcuteOnUltima(word);
  const target = idx[idx.length-2];
  const base = stripDiacritics(chars[target]);
  chars[target] = map[base] ? map[base] : chars[target];
  return chars.join('');
}

function highlightPenultVowel(word){
  // wrap the first occurrence of the penult vowel letter (base) in a span (approx)
  const pv = penultVowelBase(word);
  if(!pv) return escapeHtml(word);
  const raw = stripAccentsOnly(word);
  const lower = raw.toLowerCase();
  const idx = lower.lastIndexOf(pv, lower.lastIndexOf(pv)-1); // second last occurrence heuristic
  if(idx<0) return escapeHtml(word);
  return escapeHtml(raw.slice(0,idx)) + '<span class="hl">' + escapeHtml(raw[idx]) + '</span>' + escapeHtml(raw.slice(idx+1));
}

function escapeHtml(s){
  return s.replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function predict(word, bias){
  // returns {class:"bary"|"oxy", why:[], suggested:string}
  const why=[];
  const clean = word.trim();
  if(!clean) return {error:"Type a Greek word."};
  if(!onlyGreekAndMarks(clean)) return {error:"Please use Greek letters (accents optional)."};
  if(!endsWithSos(clean)) return {error:"This toy expects a word ending in -σος."};

  const syl = syllableCountApprox(clean);
  const pv = penultVowelBase(clean);

  // base tendency: barytone
  let score = -0.6;
  why.push("Default tendency for -σος: barytone (per Herodian’s discussion)." );

  // if penult vowel is i or a, push toward oxytone depending on bias
  if(pv === 'ι' || pv === 'α'){
    const push = (bias/100) * 1.4;
    score += push;
    why.push(`Penult vowel looks like “${pv}” → pushes toward oxytone in this toy (+${push.toFixed(2)}).`);
  } else if(pv){
    why.push(`Penult vowel looks like “${pv}” → no special oxytone push.`);
  }

  // polysyllables with penult alpha: barytone (Herodian)
  if(syl >= 3 && pv === 'α'){
    score -= 1.0;
    why.push("Polysyllable with penult α → barytone (Herodian’s later rule)." );
  }

  // a tiny list of marked exceptions from the passage
  const exceptionOxy = new Set(['πυρσος','κιρσος','ορσος','κορσος','μαρσος','ταρσος']);
  const base = stripAccentsOnly(clean).toLowerCase().replace(/[\s\-·ʼ'’]/g,'');
  if(exceptionOxy.has(base)){
    score += 1.2;
    why.push("Listed as oxytone exception in the passage (toy recognizes it)." );
  }

  const cls = score>0 ? 'oxy' : 'bary';
  const suggested = (cls==='oxy') ? applyAcuteOnUltima(clean) : applyAcuteOnPenult(clean);
  return {class:cls, why, suggested, syl, pv};
}

function renderResult(word, bias){
  const out = $('#out');
  const res = predict(word, bias);
  if(res.error){
    out.innerHTML = `<div class="err">${escapeHtml(res.error)}</div>`;
    return;
  }
  const tag = res.class==='oxy'
    ? `<span class="tag oxy">oxytone-ish</span>`
    : `<span class="tag bary">barytone-ish</span>`;

  out.innerHTML = `
    <div class="big">Suggested: <strong>${escapeHtml(res.suggested)}</strong> ${tag}</div>
    <div class="kv">
      <div class="k">Input (de-accented)</div><div class="v">${highlightPenultVowel(word)}</div>
      <div class="k">Syllables (rough)</div><div class="v">${res.syl}</div>
      <div class="k">Penult vowel (rough)</div><div class="v">${res.pv ? escapeHtml(res.pv) : '—'}</div>
    </div>
    <div class="k" style="margin-top:10px">Why this guess?</div>
    <ul style="margin:6px 0 0 18px;color:var(--muted)">
      ${res.why.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}
    </ul>
  `;
}

function buildChips(){
  const box = $('#chips');
  box.innerHTML = '';
  for(const ex of examples){
    const div = document.createElement('div');
    div.className = 'chip';
    div.setAttribute('role','listitem');
    div.innerHTML = `${escapeHtml(ex.w)} <span class="miniTag">${escapeHtml(ex.note)}</span>`;
    div.addEventListener('click', ()=>{
      $('#inWord').value = ex.w;
      renderResult(ex.w, Number($('#bias').value));
      $('#inWord').focus();
    });
    box.appendChild(div);
  }
}

function randomExample(){
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#inWord').value = ex.w;
  renderResult(ex.w, Number($('#bias').value));
}

// wire up
buildChips();
$('#btnAnalyze').addEventListener('click', ()=>renderResult($('#inWord').value, Number($('#bias').value)));
$('#inWord').addEventListener('keydown', (e)=>{ if(e.key==='Enter') renderResult($('#inWord').value, Number($('#bias').value)); });
$('#btnShuffle').addEventListener('click', randomExample);
$('#bias').addEventListener('input', ()=>{
  $('#biasVal').textContent = $('#bias').value;
  const w = $('#inWord').value.trim();
  if(w) renderResult(w, Number($('#bias').value));
});

// initial
$('#biasVal').textContent = $('#bias').value;
$('#inWord').value = 'πυρσος';
renderResult($('#inWord').value, Number($('#bias').value));

