const $ = (sel) => document.querySelector(sel);
const inp = $('#inp');
const result = $('#result');
const rule = $('#rule');
const checksEl = $('#checks');

const stripBox = $('#strip');
const showSylBox = $('#showSyl');
const polyBox = $('#poly');

const examples = [
  'Βεσσος','Θυσσος','Ασσος','Ησσος','Ψησσος','Τνυσσος','Βυσσος','Ισσος',
  'δισσος','τρισσος','λισσος','κισσος','Κισσος','μεσσος','τοσσος','οσσος',
  'κοκκος','κοννος','ορρος','κοττος','κομμος','γλωσσος'
];

// --- Greek helpers ---
const vowels = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ','ὰ','ὲ','ὴ','ὶ','ὸ','ὺ','ὼ','ᾶ','ῖ','ῦ','ῶ','ϊ','ϋ','ΐ','ΰ','ἀ','ἁ','ἂ','ἃ','ἄ','ἅ','ἆ','ἇ','ἐ','ἑ','ἒ','ἓ','ἔ','ἕ','ἠ','ἡ','ἢ','ἣ','ἤ','ἥ','ἦ','ἧ','ἰ','ἱ','ἲ','ἳ','ἴ','ἵ','ἶ','ἷ','ὀ','ὁ','ὂ','ὃ','ὄ','ὅ','ὠ','ὡ','ὢ','ὣ','ὤ','ὥ','ὦ','ὧ','ῃ','ῄ','ῂ','ῇ','ῳ','ῴ','ῲ','ῷ','ᾳ','ᾴ','ᾲ','ᾷ']);

function normalizeGreek(s){
  return (s||'').trim().replace(/\s+/g,' ');
}

function stripAccents(s){
  // Remove combining marks; also normalize to NFD then back.
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function lowerGreek(s){
  return s.toLocaleLowerCase('el');
}

function isVowel(ch){
  return vowels.has(ch);
}

function lastVowelIndex(s){
  for(let i=s.length-1;i>=0;i--){
    if(isVowel(s[i])) return i;
  }
  return -1;
}

function penultVowelIndex(s){
  let found = 0;
  for(let i=s.length-1;i>=0;i--){
    if(isVowel(s[i])){
      found++;
      if(found===2) return i;
    }
  }
  return -1;
}

function countVowels(s){
  let c=0;
  for(const ch of s) if(isVowel(ch)) c++;
  return c;
}

function endsWithOs(s){
  const t = lowerGreek(s);
  return t.endsWith('ος');
}

function endsWithSos(s){
  const t = lowerGreek(s);
  return t.endsWith('σος');
}

function hasSigmaInPenultSyllable(s){
  // crude: check for σ immediately before the last vowel (i.e., in penult onset/coda area)
  const t = lowerGreek(s);
  const pv = penultVowelIndex(t);
  if(pv<0) return false;
  // look from pv-2..pv+2 for σ/ς
  const a = Math.max(0,pv-2), b = Math.min(t.length, pv+3);
  return /[σς]/.test(t.slice(a,b));
}

function hasDoubleSigmaBeforeOs(s){
  const t = lowerGreek(s);
  return /σσ[οό]ς$/.test(stripAccents(t));
}

function hasODoubleConsonantPattern(s){
  // Inspired by κόννος, κόκκος, κόττος, ὄρρος, ὄσσος: disyllable, ends -ος, penult vowel is ο,
  // and somewhere after that ο there is a doubled consonant (same letter twice).
  const raw = stripAccents(lowerGreek(s));
  if(!raw.endsWith('ος')) return false;
  if(countVowels(raw)!==2) return false;
  const pv = penultVowelIndex(raw);
  if(pv<0 || raw[pv] !== 'ο') return false;
  const tail = raw.slice(pv+1); // after penult vowel
  return /(ββ|γγ|δδ|ζζ|θθ|κκ|λλ|μμ|νν|ππ|ρρ|σσ|ττ|φφ|χχ|ψψ)/.test(tail);
}

function syllableGuess(s){
  // Very rough: split at vowel groups.
  const t = stripAccents(lowerGreek(s)).replace(/[^\p{L}]+/gu,'');
  if(!t) return [];
  let parts=[];
  let cur='';
  for(let i=0;i<t.length;i++){
    const ch=t[i];
    cur+=ch;
    const next=t[i+1];
    if(isVowel(ch) && (!next || !isVowel(next))){
      parts.push(cur);
      cur='';
    }
  }
  if(cur) parts[parts.length-1]=(parts[parts.length-1]||'')+cur;
  return parts.filter(Boolean);
}

function applyAccent(word, kind){
  // kind: 'acuteUlt' | 'graveUlt' | 'circUlt' | 'none'
  // We accent the last vowel we can find.
  const usePoly = polyBox.checked;
  const w = word;
  const idx = lastVowelIndex(w);
  if(idx<0) return w;

  const base = w[idx].normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');

  const map = {
    'α': {acute:'ά', grave:'ὰ', circ:'ᾶ'},
    'ε': {acute:'έ', grave:'ὲ', circ:'ε'},
    'η': {acute:'ή', grave:'ὴ', circ:'ῆ'},
    'ι': {acute:'ί', grave:'ὶ', circ:'ῖ'},
    'ο': {acute:'ό', grave:'ὸ', circ:'ο'},
    'υ': {acute:'ύ', grave:'ὺ', circ:'ῦ'},
    'ω': {acute:'ώ', grave:'ὼ', circ:'ῶ'},
    'Α': {acute:'Ά', grave:'Ὰ', circ:'Α'},
    'Ε': {acute:'Έ', grave:'Ὲ', circ:'Ε'},
    'Η': {acute:'Ή', grave:'Ὴ', circ:'Η'},
    'Ι': {acute:'Ί', grave:'Ὶ', circ:'Ι'},
    'Ο': {acute:'Ό', grave:'Ὸ', circ:'Ο'},
    'Υ': {acute:'Ύ', grave:'Ὺ', circ:'Υ'},
    'Ω': {acute:'Ώ', grave:'Ὼ', circ:'Ω'}
  };

  function withCombining(mark){
    return (base.normalize('NFD') + mark).normalize('NFC');
  }

  let accented = base;
  if(kind==='none') accented = base;
  else if(usePoly && map[base]){
    if(kind==='acuteUlt') accented = map[base].acute;
    if(kind==='graveUlt') accented = map[base].grave;
    if(kind==='circUlt') accented = map[base].circ;
  } else {
    // fallback: combining marks
    if(kind==='acuteUlt') accented = withCombining('\u0301');
    if(kind==='graveUlt') accented = withCombining('\u0300');
    if(kind==='circUlt') accented = withCombining('\u0342');
  }

  return w.slice(0,idx) + accented + w.slice(idx+1);
}

function analyzeWord(input){
  const original = normalizeGreek(input);
  if(!original) return null;

  const base = stripBox.checked ? stripAccents(original) : original;
  const bare = stripAccents(base);
  const lowBare = lowerGreek(bare);

  // If phrase, analyze last token but keep phrase.
  const tokens = base.split(' ');
  const lastTok = tokens[tokens.length-1];

  const lastBare = stripAccents(lastTok);
  const low = lowerGreek(lastBare);

  const vCount = countVowels(low);
  const disyll = (vCount===2);

  const checkEndsSos = endsWithSos(low);
  const checkEndsOs = endsWithOs(low);
  const checkPenultSigma = hasSigmaInPenultSyllable(low);
  const checkDoubleSigma = hasDoubleSigmaBeforeOs(low);

  const heavyPattern = hasODoubleConsonantPattern(low);

  // Exception-ish: Κίσσος proper name treated as heavy (grave) in passage.
  const isKissosProper = stripAccents(lastTok) === 'Κισσος' || stripAccents(lastTok) === 'Κίσσος';

  let decision = {kind:'none', label:'No suggestion', why:'Not enough pattern match.'};

  if(disyll && checkEndsSos && (checkPenultSigma || checkDoubleSigma)){
    decision = {kind:'acuteUlt', label:'Herodian -σος acute', why:'Disyllable in -σος with another σ in the penult → suggest acute on ultima.'};
  }

  if(heavyPattern || isKissosProper){
    decision = {kind:'graveUlt', label:'“Heavy” grave', why:'Looks like ο + doubled consonant in a disyllable ending -ος (or Κίσσος proper name) → suggest grave/low accent.'};
  }

  // If both triggered, show warning and prefer heavy (as a playful conflict).
  const both = (disyll && checkEndsSos && (checkPenultSigma || checkDoubleSigma)) && (heavyPattern || isKissosProper);

  // Apply to last token only.
  let outTok = lastTok;
  if(stripBox.checked){
    outTok = applyAccent(stripAccents(lastTok), decision.kind);
  } else {
    // keep existing accents but also show suggested by re-accenting a stripped version
    outTok = applyAccent(stripAccents(lastTok), decision.kind);
  }

  const outPhrase = tokens.slice(0,-1).concat([outTok]).join(' ');

  return {
    original,
    base,
    outPhrase,
    decision,
    both,
    checks:{
      disyll, vCount,
      endsSos:checkEndsSos,
      endsOs:checkEndsOs,
      penultSigma:checkPenultSigma,
      doubleSigma:checkDoubleSigma,
      heavyPattern,
      isKissosProper
    },
    syllables: syllableGuess(lastTok)
  };
}

function li(text, badgeText, badgeClass){
  const el = document.createElement('li');
  el.textContent = text;
  if(badgeText){
    const b = document.createElement('span');
    b.className = 'badge ' + (badgeClass||'');
    b.textContent = badgeText;
    el.appendChild(b);
  }
  return el;
}

function render(a){
  checksEl.innerHTML='';
  if(!a){
    result.textContent='—';
    rule.textContent='Type something and click Analyze.';
    return;
  }

  result.textContent = a.outPhrase;

  const badge = a.both ? ' (conflict!)' : '';
  rule.textContent = a.decision.label + badge + ' — ' + a.decision.why;

  checksEl.appendChild(li('Vowel-count (rough) = ' + a.checks.vCount + (a.checks.disyll ? ' → disyllable' : ''), a.checks.disyll?'2':'≠2', a.checks.disyll?'good':'warn'));
  checksEl.appendChild(li('Ends in -σος', a.checks.endsSos?'yes':'no', a.checks.endsSos?'good':'bad'));
  checksEl.appendChild(li('Ends in -ος', a.checks.endsOs?'yes':'no', a.checks.endsOs?'good':'bad'));
  checksEl.appendChild(li('Extra σ near penult (heuristic)', a.checks.penultSigma?'yes':'no', a.checks.penultSigma?'good':'warn'));
  checksEl.appendChild(li('Has -σσ- before -ος', a.checks.doubleSigma?'yes':'no', a.checks.doubleSigma?'good':'warn'));
  checksEl.appendChild(li('“Heavy” pattern (ο + doubled consonant)', a.checks.heavyPattern?'yes':'no', a.checks.heavyPattern?'warn':'good'));
  if(a.checks.isKissosProper){
    checksEl.appendChild(li('Exception: Κίσσος (proper name) treated as heavy in passage', 'yes', 'warn'));
  }

  if(showSylBox.checked){
    const syl = a.syllables;
    if(syl.length){
      checksEl.appendChild(li('Syllable guess: ' + syl.join(' · '), 'toy', ''));
    }
  }
}

function run(){
  const a = analyzeWord(inp.value);
  render(a);
}

$('#analyze').addEventListener('click', run);
$('#clear').addEventListener('click', () => { inp.value=''; render(null); inp.focus(); });
$('#random').addEventListener('click', () => {
  const ex = examples[Math.floor(Math.random()*examples.length)];
  inp.value = ex;
  run();
  inp.focus();
});

inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') run(); });

for(const btn of document.querySelectorAll('.chip')){
  btn.addEventListener('click', ()=>{ inp.value = btn.getAttribute('data-put'); run(); inp.focus(); });
}

stripBox.addEventListener('change', run);
showSylBox.addEventListener('change', run);
polyBox.addEventListener('change', run);

// Seed
inp.value = 'Βεσσος';
run();

