:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --card:#1e2238;
  --ink:#e9ecff;
  --muted:#b9c0ff;
  --faint:#8d95d6;
  --accent:#7cf0c5;
  --warn:#ffcc66;
  --bad:#ff6b7a;
  --line:rgba(255,255,255,.10);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
}

*{box-sizing:border-box}

.wrap{
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
  color:var(--ink);
  background: radial-gradient(1200px 600px at 20% 0%, rgba(124,240,197,.12), transparent 60%),
              radial-gradient(900px 500px at 90% 10%, rgba(185,192,255,.12), transparent 55%),
              var(--bg);
  padding:18px;
  border-radius:16px;
}

.top{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:16px;
  margin-bottom:14px;
}

h1{font-size:20px; margin:0 0 6px 0; letter-spacing:.2px}
.sub{margin:0; color:var(--muted); font-size:13px; line-height:1.35}

.panel{
  background: linear-gradient(180deg, rgba(255,255,255,.04), transparent 40%), var(--panel);
  border:1px solid var(--line);
  border-radius:14px;
  padding:14px;
  box-shadow: var(--shadow);
}

.controls{margin-bottom:12px}
.lbl{display:block; font-size:13px; color:var(--muted); margin-bottom:6px}
.row{display:flex; gap:8px; flex-wrap:wrap}

input[type=text]{
  flex:1 1 340px;
  min-width:240px;
  padding:10px 12px;
  border-radius:10px;
  border:1px solid var(--line);
  background: rgba(255,255,255,.04);
  color:var(--ink);
  outline:none;
  font-size:16px;
}
input[type=text]:focus{border-color: rgba(124,240,197,.55); box-shadow: 0 0 0 3px rgba(124,240,197,.12)}

.btn{
  padding:10px 12px;
  border-radius:10px;
  border:1px solid rgba(124,240,197,.35);
  background: rgba(124,240,197,.12);
  color:var(--ink);
  cursor:pointer;
  font-weight:650;
}
.btn:hover{background: rgba(124,240,197,.18)}
.btn:active{transform: translateY(1px)}
.btn.ghost{
  border-color: var(--line);
  background: rgba(255,255,255,.04);
  font-weight:600;
}
.btn.ghost:hover{background: rgba(255,255,255,.07)}

.hint{margin:8px 0 0 0; color:var(--faint); font-size:12.5px}

.grid{
  display:grid;
  grid-template-columns: repeat(12, 1fr);
  gap:10px;
}
.card{
  grid-column: span 12;
  background: linear-gradient(180deg, rgba(255,255,255,.04), transparent 55%), var(--card);
  border:1px solid var(--line);
  border-radius:12px;
  padding:12px;
}
@media (min-width: 860px){
  .card:nth-child(1){grid-column: span 4}
  .card:nth-child(2){grid-column: span 5}
  .card:nth-child(3){grid-column: span 3}
}

h2{margin:0 0 8px 0; font-size:14px; color:var(--muted); letter-spacing:.2px}

.kv{display:grid; grid-template-columns: 160px 1fr; gap:6px 10px; align-items:baseline}
.k{color:var(--faint); font-size:12.5px}
.v{font-family: var(--mono); font-size:13px; color:var(--ink); word-break:break-word}

.out{border:1px dashed rgba(185,192,255,.25); border-radius:12px; padding:10px; background: rgba(0,0,0,.12)}
.big{font-family: var(--mono); font-size:20px; letter-spacing:.2px}
.mini{margin-top:6px; color:var(--faint); font-size:12.5px; line-height:1.35}

.small{margin:0 0 10px 0; color:var(--faint); font-size:12.5px; line-height:1.35}

.toggleRow{display:flex; gap:14px; flex-wrap:wrap; margin-top:10px}
.chk{color:var(--muted); font-size:12.5px; user-select:none}
.chk input{transform: translateY(1px)}

.chips{display:flex; flex-wrap:wrap; gap:6px}
.chip{
  border:1px solid var(--line);
  background: rgba(255,255,255,.04);
  color:var(--ink);
  padding:6px 8px;
  border-radius:999px;
  cursor:pointer;
  font-family: var(--mono);
  font-size:12.5px;
}
.chip:hover{border-color: rgba(185,192,255,.35); background: rgba(255,255,255,.07)}

.greek{font-variant-ligatures:none}

.foot{margin-top:10px}
summary{cursor:pointer; color:var(--muted)}
.explain{color:var(--faint); font-size:12.5px; line-height:1.45; margin-top:8px}

.badge{
  display:inline-block;
  padding:2px 6px;
  border-radius:999px;
  border:1px solid var(--line);
  font-size:11.5px;
  color:var(--muted);
  margin-left:6px;
}

.markOk{color:var(--accent)}
.markWarn{color:var(--warn)}
.markBad{color:var(--bad)}

