(() => {
  const $ = (sel) => document.querySelector(sel);

  const inp = $('#inp');
  const btnAnalyze = $('#btnAnalyze');
  const btnRandom = $('#btnRandom');
  const btnClear = $('#btnClear');

  const normEl = $('#norm');
  const endingEl = $('#ending');
  const syllEl = $('#syll');
  const hasSSEl = $('#hasSS');
  const singleSEl = $('#singleS');

  const suggestEl = $('#suggest');
  const ruleEl = $('#rule');

  const showMarks = $('#showMarks');
  const keepBreath = $('#keepBreath');

  const examples = [
    'κομπασος', 'Ἅρπασος', 'Δάμασος', 'βαύνασος', 'θίασος', 'Ἴασος', 'Ἴμβρασος', 'Τράγασος',
    'Καύκασος', 'Βάργασος', 'Μύλασος', 'Νάκρασος', 'Πρόγασος', 'Πύρασος', 'Πήδασος', 'Τάμασος',
    'Πάρρασος', 'Ἔρασος', 'κερασος', 'Ἐγγυασός', 'Παρνασσος', 'Ὑγασσός', 'Βυβασσός', 'Κρυασσός',
    'Σαγαλασσός', 'Ἁλικαρνασσός', 'Συασσός', 'Ἀμαμασσός', 'Καβασσός'
  ];

  // --- Greek helpers (heuristic) ---
  const combining = /[\u0300-\u036f]/g;

  function nfd(s){ return s.normalize('NFD'); }
  function nfc(s){ return s.normalize('NFC'); }

  function stripDiacritics(s){
    // Remove combining marks (accents, breathings, iota subscript, diaeresis, etc.)
    return nfc(nfd(s).replace(combining, ''));
  }

  function stripAccentsKeepBreathing(s){
    // Keep breathings (rough/smooth) if present, but remove accent marks.
    // In Unicode, breathings are combining marks too; we approximate by keeping
    // U+0313 (smooth) and U+0314 (rough) and removing others.
    const keep = new Set(['\u0313','\u0314']);
    const out = [];
    for (const ch of nfd(s)){
      const code = ch.codePointAt(0);
      if (code >= 0x300 && code <= 0x36f){
        const hex = code.toString(16).padStart(4,'0');
        const u = `\\u${hex}`;
        if (keep.has(u)) out.push(ch);
      } else out.push(ch);
    }
    return nfc(out.join(''));
  }

  function isVowel(base){
    return 'αεηιουωΑΕΗΙΟΥΩ'.includes(base);
  }

  function roughSyllableCount(s){
    // Count vowel groups in a diacritic-stripped string.
    const t = stripDiacritics(s);
    let count = 0;
    let prevV = false;
    for (const ch of t){
      const v = isVowel(ch);
      if (v && !prevV) count++;
      prevV = v;
    }
    return count;
  }

  function endsWithSos(s){
    const t = stripDiacritics(s).toLowerCase();
    return t.endsWith('σος');
  }

  function hasDoubleSigma(s){
    const t = stripDiacritics(s).toLowerCase();
    return t.includes('σσ');
  }

  function hasSingleSigmaBeforeOs(s){
    const t = stripDiacritics(s).toLowerCase();
    // Look for ...σος but not ...σσος
    return t.endsWith('σος') && !t.endsWith('σσος');
  }

  function lastIndexOfVowel(s){
    const t = nfd(s);
    // Find last base vowel (ignoring combining marks)
    for (let i = t.length - 1; i >= 0; i--){
      const ch = t[i];
      const code = ch.codePointAt(0);
      if (code >= 0x300 && code <= 0x36f) continue;
      if (isVowel(ch)) return i;
    }
    return -1;
  }

  function vowelPositions(s){
    // Return indices in NFD string of base vowels
    const t = nfd(s);
    const pos = [];
    for (let i=0;i<t.length;i++){
      const ch = t[i];
      const code = ch.codePointAt(0);
      if (code >= 0x300 && code <= 0x36f) continue;
      if (isVowel(ch)) pos.push(i);
    }
    return {t, pos};
  }

  function addAcuteOnVowel(s, vowelIndexFromEnd){
    // Place acute on the Nth vowel from the end: 1=ultima, 2=penult, 3=antepenult
    const {t, pos} = vowelPositions(s);
    if (pos.length === 0) return s;
    const idx = pos[Math.max(0, pos.length - vowelIndexFromEnd)];

    // Insert combining acute (U+0301) after that base vowel, but after any existing breathing on it.
    // We first remove existing accents (optionally keep breathing), then add acute.
    const cleaned = keepBreath.checked ? stripAccentsKeepBreathing(s) : stripDiacritics(s);
    const {t: tt, pos: pp} = vowelPositions(cleaned);
    const j = pp[Math.max(0, pp.length - vowelIndexFromEnd)];

    let arr = Array.from(nfd(cleaned));
    // Find insertion point: after base vowel and any immediately following breathing marks.
    let ins = j + 1;
    while (ins < arr.length){
      const code = arr[ins].codePointAt(0);
      if (code >= 0x300 && code <= 0x36f){
        // keep existing combining marks (e.g. breathing) before acute
        ins++;
      } else break;
    }
    arr.splice(ins, 0, '\u0301');
    return nfc(arr.join(''));
  }

  function dotSyllables(s){
    // Insert · before each vowel group (except the first) in a stripped string for visualization.
    const base = keepBreath.checked ? stripAccentsKeepBreathing(s) : stripDiacritics(s);
    const t = nfd(base);
    let out = '';
    let prevV = false;
    for (let i=0;i<t.length;i++){
      const ch = t[i];
      const code = ch.codePointAt(0);
      if (code >= 0x300 && code <= 0x36f){
        out += ch;
        continue;
      }
      const v = isVowel(ch);
      if (v && !prevV && out.length>0) out += '·';
      out += ch;
      prevV = v;
    }
    return nfc(out);
  }

  function analyze(){
    const raw = inp.value.trim();
    if (!raw){
      normEl.textContent = '—';
      endingEl.textContent = '—';
      syllEl.textContent = '—';
      hasSSEl.textContent = '—';
      singleSEl.textContent = '—';
      suggestEl.textContent = '—';
      ruleEl.textContent = '—';
      return;
    }

    // If phrase, analyze last token but keep full phrase for output.
    const parts = raw.split(/\s+/);
    const last = parts[parts.length-1];

    const normalized = keepBreath.checked ? stripAccentsKeepBreathing(last) : stripDiacritics(last);
    const syll = roughSyllableCount(last);
    const inSos = endsWithSos(last);
    const dbl = hasDoubleSigma(last);
    const single = hasSingleSigmaBeforeOs(last);

    normEl.textContent = normalized;
    endingEl.textContent = inSos ? '-σος' : '(not -σος)';
    syllEl.textContent = String(syll);
    hasSSEl.innerHTML = dbl ? '<span class="markWarn">yes</span>' : '<span class="markOk">no</span>';
    singleSEl.innerHTML = single ? '<span class="markOk">yes</span>' : (inSos ? '<span class="markWarn">no</span>' : '<span class="markBad">n/a</span>');

    let suggestion = raw;
    let note = '';

    if (!inSos){
      // Still allow accent play: default to penult if 2+ syllables else ultima.
      const target = syll >= 2 ? 2 : 1;
      const accentedLast = addAcuteOnVowel(last, target);
      parts[parts.length-1] = accentedLast;
      suggestion = parts.join(' ');
      note = 'Not an -σος word: playful default → acute on penult (or ultima if monosyllable).';
    } else {
      if (dbl){
        // playful contrast: oxytone
        const accentedLast = addAcuteOnVowel(last, 1);
        parts[parts.length-1] = accentedLast;
        suggestion = parts.join(' ');
        note = 'Has -σσ-: toy suggests ὀξύτονον (acute on ultima), echoing Herodian’s contrast (e.g. Παρνασσός).';
      } else if (syll >= 3 && single){
        const accentedLast = addAcuteOnVowel(last, 3);
        parts[parts.length-1] = accentedLast;
        suggestion = parts.join(' ');
        note = 'Matches the toy-version of Herodian’s rule: 3+ syllables, -σος, single σ → προπαροξύτονον (antepenult).';
      } else {
        // fallback: paroxytone
        const accentedLast = addAcuteOnVowel(last, Math.min(2, Math.max(1, syll)));
        parts[parts.length-1] = accentedLast;
        suggestion = parts.join(' ');
        note = 'Doesn’t clearly match the rule (or too few syllables): toy falls back to acute on penult.';
      }
    }

    const shown = showMarks.checked ? dotSyllables(suggestion) : suggestion;
    suggestEl.textContent = shown;
    ruleEl.textContent = note;
  }

  function buildChips(){
    const box = $('#chips');
    box.innerHTML = '';
    for (const ex of examples){
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'chip';
      b.textContent = ex;
      b.addEventListener('click', () => {
        inp.value = ex;
        analyze();
        inp.focus();
      });
      box.appendChild(b);
    }
  }

  btnAnalyze.addEventListener('click', analyze);
  btnClear.addEventListener('click', () => { inp.value=''; analyze(); inp.focus(); });
  btnRandom.addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inp.value = ex;
    analyze();
    inp.focus();
  });

  inp.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') analyze();
  });
  showMarks.addEventListener('change', analyze);
  keepBreath.addEventListener('change', analyze);

  buildChips();
  inp.value = 'κομπασος';
  analyze();
})();

