const $ = (sel) => document.querySelector(sel);

const samples = [
  "Εφεσος",
  "Ερεσος",
  "Θυεσσος",
  "Ταρτησσος",
  "Μυκαλησσος",
  "Τευμησσος",
  "Οδησσος",
  "Σαλμυδησσος",
  "Ακαλησσος",
  "Ασσησσος",
  "Κυβασσος",
  "Πρινασσος",
  "Λυρνησσος",
  "Λυκαβησσος",
  "Εδεβησσος",
  "Ερβησσος",
  "Αγησσος"
];

// --- Greek helpers ---
const COMBINING = /[\u0300-\u036f]/g;

function stripDiacritics(s){
  return s.normalize('NFD').replace(COMBINING,'').normalize('NFC');
}

function hasGreek(s){
  return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(s);
}

function normalizeSigmaFinal(s){
  // keep as-is; but for matching, treat ς as σ
  return s.replace(/ς/g,'σ');
}

function isVowel(ch){
  return "αεηιουω".includes(ch);
}

function lastIndexOfVowel(word){
  for(let i=word.length-1;i>=0;i--){
    if(isVowel(word[i])) return i;
  }
  return -1;
}

function syllabifyRough(word){
  // Very rough syllabifier: split after each vowel group.
  // Not academically correct; good enough for a toy.
  const w = word;
  let syls = [];
  let buf = "";
  let i=0;
  while(i<w.length){
    const ch = w[i];
    buf += ch;
    if(isVowel(ch)){
      // absorb following iota subscript? (already stripped) / diphthongs (rough)
      // treat αι, ει, οι, υι, αυ, ευ, ου, ηυ as one nucleus
      const next = w[i+1] || "";
      const pair = ch + next;
      const diph = ["αι","ει","οι","υι","αυ","ευ","ου","ηυ"].includes(pair);
      if(diph){
        buf += next;
        i++;
      }
      syls.push(buf);
      buf = "";
    }
    i++;
  }
  if(buf) syls[syls.length-1] = (syls[syls.length-1]||"") + buf;
  // merge leading consonants if first syllable has no vowel (edge cases)
  if(syls.length===0) return [w];
  return syls;
}

function penultVowel(word){
  // Return the vowel (or vowel pair) of the penult syllable nucleus, rough.
  const syls = syllabifyRough(word);
  if(syls.length < 2) return null;
  const pen = syls[syls.length-2];
  // find last vowel in pen syllable
  let vIdx = -1;
  for(let i=pen.length-1;i>=0;i--){
    if(isVowel(pen[i])) { vIdx = i; break; }
  }
  if(vIdx<0) return null;
  const v = pen[vIdx];
  const next = pen[vIdx+1] || "";
  const pair = v + next;
  if(["αι","ει","οι","υι","αυ","ευ","ου","ηυ"].includes(pair)) return pair;
  return v;
}

function endsWithSos(word){
  return word.endsWith("σος");
}

function hasDoubleSigmaBeforeEnding(word){
  // look for -σσος ending
  return word.endsWith("σσος");
}

function countSigmasNearEnd(word){
  // crude: count σ in last 5 chars
  const tail = word.slice(-6);
  return (tail.match(/σ/g)||[]).length;
}

// Accent placement: add combining acute to the vowel nucleus of target syllable.
function addAcuteToSyllable(word, sylIndex){
  const syls = syllabifyRough(word);
  if(sylIndex < 0 || sylIndex >= syls.length) return word;
  const target = syls[sylIndex];
  // find vowel nucleus position in target syllable (first vowel)
  let pos = -1;
  for(let i=0;i<target.length;i++){
    if(isVowel(target[i])) { pos = i; break; }
  }
  if(pos<0) return word;
  // If diphthong, accent first vowel for simplicity
  const accented = target.slice(0,pos+1) + "\u0301" + target.slice(pos+1);
  syls[sylIndex] = accented;
  return syls.join("").normalize('NFC');
}

function guessAccent(word){
  // Implements a simplified reading of the passage:
  // 1) -σος polysyllables with penult simple ε and single σ -> proparoxytone (antepenult)
  // 2) Θυεσσός-type with -σσος -> oxytone (ultima)
  // 3) -σος polysyllables with penult η and single σ -> oxytone (ultima)
  // Otherwise: default to paroxytone (penult) as a neutral guess.

  const syls = syllabifyRough(word);
  const facts = [];

  facts.push(`Syllables (rough): ${syls.join("·")}`);

  if(!endsWithSos(word)){
    return {accented: word, rule: "Not an -σος word (toy only handles -σος).", facts};
  }

  if(syls.length < 3){
    facts.push("Not polysyllabic enough for the passage’s rule (needs 3+ syllables)." );
    // still: accent penult if possible
    const idx = Math.max(0, syls.length-2);
    return {accented: addAcuteToSyllable(word, idx), rule: "Fallback: paroxytone (penult).", facts};
  }

  const penV = penultVowel(word);
  facts.push(`Penult nucleus (rough): ${penV ?? "?"}`);

  const dbl = hasDoubleSigmaBeforeEnding(word);
  const sigmaCount = countSigmasNearEnd(word);
  facts.push(`Ending pattern: ${dbl ? "-σσος" : "-σος"} (σ near end ≈ ${sigmaCount})`);

  // Rule 2: -σσος -> oxytone
  if(dbl){
    const accented = addAcuteToSyllable(word, syls.length-1);
    return {accented, rule: "Heuristic: -σσος tends to be oxytone (accent on ultima), like Θυεσσός.", facts};
  }

  // Rule 1: penult ε and single σ -> proparoxytone
  if(penV === "ε"){
    const accented = addAcuteToSyllable(word, syls.length-3);
    return {accented, rule: "Heuristic: -σος with penult ε and single σ → proparoxytone (antepenult), like Ἔφεσος / Ἔρεσος.", facts};
  }

  // Rule 3: penult η and single σ -> oxytone
  if(penV === "η"){
    const accented = addAcuteToSyllable(word, syls.length-1);
    return {accented, rule: "Heuristic: -σος with penult η and single σ → oxytone (ultima).", facts};
  }

  // Default
  const accented = addAcuteToSyllable(word, syls.length-2);
  return {accented, rule: "Fallback: paroxytone (penult).", facts};
}

function renderSyllables(word){
  const box = $('#syllables');
  box.innerHTML = '';
  if(!word){
    box.textContent = '(enter a word)';
    return;
  }
  const syls = syllabifyRough(word);
  syls.forEach((s, i) => {
    const span = document.createElement('span');
    span.className = 'syl';
    const fromEnd = syls.length - 1 - i;
    let role = '';
    if(fromEnd===0) role='ultima';
    if(fromEnd===1) role='penult';
    if(fromEnd===2) role='antepenult';
    if(role) span.dataset.role = role;

    span.textContent = s;
    if(role){
      const tag = document.createElement('span');
      tag.className = 'tag';
      tag.textContent = role;
      span.appendChild(tag);
      span.title = role;
    }
    box.appendChild(span);
  });
}

function apply(){
  const inp = $('#inp');
  let raw = (inp.value || '').trim();
  const mode = $('#mode').value;
  const dia = $('#toggleDiacritics').value;

  if(!raw){
    $('#outWord').textContent = '—';
    $('#outRule').textContent = 'Type a word ending in -σος.';
    $('#outFacts').innerHTML = '<li>—</li>';
    renderSyllables('');
    return;
  }

  if(!hasGreek(raw)){
    $('#outWord').textContent = raw;
    $('#outRule').textContent = 'This doesn’t look like Greek letters; the toy works best with Greek input.';
    $('#outFacts').innerHTML = '<li>Tip: try Εφεσος, Θυεσσος, Μυκαλησσος…</li>';
    renderSyllables(raw);
    return;
  }

  let w = raw;
  if(dia === 'strip') w = stripDiacritics(w);
  if(dia === 'auto') w = stripDiacritics(w); // for consistent behavior
  // keep: do nothing

  w = w.toLowerCase();
  w = normalizeSigmaFinal(w);

  // show mode: no accenting
  if(mode === 'show'){
    $('#outWord').textContent = w;
    const facts = [];
    facts.push(`Syllables (rough): ${syllabifyRough(w).join('·')}`);
    facts.push(`Penult nucleus (rough): ${penultVowel(w) ?? '?'}`);
    facts.push(`Ends in -σος: ${endsWithSos(w) ? 'yes' : 'no'}`);
    facts.push(`Has -σσος: ${hasDoubleSigmaBeforeEnding(w) ? 'yes' : 'no'}`);
    $('#outRule').textContent = 'Syllable/penult view only (no accent guess).';
    $('#outFacts').innerHTML = facts.map(x=>`<li>${x}</li>`).join('');
    renderSyllables(w);
    return;
  }

  const res = guessAccent(w);
  $('#outWord').textContent = res.accented;
  $('#outRule').textContent = res.rule;
  $('#outFacts').innerHTML = res.facts.map(x=>`<li>${x}</li>`).join('');
  renderSyllables(res.accented);
}

$('#btnGuess').addEventListener('click', apply);
$('#btnClear').addEventListener('click', () => {
  $('#inp').value = '';
  apply();
});
$('#btnRandom').addEventListener('click', () => {
  const pick = samples[Math.floor(Math.random()*samples.length)];
  $('#inp').value = pick;
  apply();
});
$('#inp').addEventListener('keydown', (e) => {
  if(e.key === 'Enter') apply();
});

// initialize
apply();

