(() => {
  const $ = (sel, root=document) => root.querySelector(sel);
  const $$ = (sel, root=document) => Array.from(root.querySelectorAll(sel));

  const inp = $('#inp');
  const normEl = $('#norm');
  const endingEl = $('#ending');
  const scountEl = $('#scount');
  const syllEl = $('#syll');
  const penultEl = $('#penult');

  const outInput = $('#outInput');
  const outGuess = $('#outGuess');
  const outAlt = $('#outAlt');
  const explain = $('#explain');

  const samples = [
    'Καρδαμυλησσός','Καρδησσός','Κορησσός','Μερμησσός','Σαρδησσός','Σινδησσός','Τεγησσός','Τερμησσός','Τυλησσός','Τυμνησσός','Ἀγορησσός','Καβησσός','Καβασσός','Μάρπησσος','Κάρησος','Βρίλησος','Χερρόνησος','Μυόννησος'
  ];

  // --- Greek helpers (toy-level) ---
  const combining = /[\u0300-\u036f]/g;
  const tonos = '\u0301'; // combining acute
  const dialytika = '\u0308';

  function nfd(s){ return (s||'').normalize('NFD'); }
  function nfc(s){ return (s||'').normalize('NFC'); }

  function stripDiacritics(s){
    // keep Greek letters, remove combining marks
    return nfc(nfd(s).replace(combining,''));
  }

  function stripNonLetters(s){
    return (s||'').replace(/[^\p{Script=Greek}]/gu,'');
  }

  function lastWordGreek(s){
    // take last Greek token
    const tokens = (s||'').trim().split(/\s+/);
    for(let i=tokens.length-1;i>=0;i--){
      const g = stripNonLetters(tokens[i]);
      if(g) return g;
    }
    return '';
  }

  function detectEnding(word){
    const w = stripDiacritics(word);
    const lower = w.toLowerCase();

    const endings = [
      {re:/νησος$/i, label:'-νησος ("peninsula/island")'},
      {re:/σσός$/i, label:'-σσός'},
      {re:/σσος$/i, label:'-σσος'},
      {re:/σσον$/i, label:'-σσον'},
      {re:/σος$/i, label:'-σος'},
      {re:/ος$/i, label:'-ος'}
    ];
    for(const e of endings){
      if(e.re.test(lower)) return e;
    }
    return {re:/.*/, label:'(unknown)'};
  }

  function countSigmaInEnding(word){
    const w = stripDiacritics(word).toLowerCase();
    const m = w.match(/(σ+)(ος|ον)$/);
    if(!m) return 0;
    return m[1].length;
  }

  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ','ϊ','ϋ','ΐ','ΰ']);

  function isVowel(ch){ return vowels.has(ch.toLowerCase()); }

  function toySyllabify(word){
    // Very rough: split before each vowel group after the first.
    const w = stripDiacritics(word);
    const chars = Array.from(w);
    const parts = [];
    let cur = '';
    let seenVowel = false;

    for(let i=0;i<chars.length;i++){
      const ch = chars[i];
      const v = isVowel(ch);
      if(v){
        if(seenVowel && cur){
          parts.push(cur);
          cur = '';
        }
        seenVowel = true;
      }
      cur += ch;
    }
    if(cur) parts.push(cur);

    // Post-process: try to move a single consonant from start of a syllable to previous (CV.CV feel)
    for(let i=1;i<parts.length;i++){
      const p = parts[i];
      if(p.length>=2 && !isVowel(p[0]) && isVowel(p[1])){
        // keep onset consonant with this syllable; do nothing
      } else if(p.length>=1 && !isVowel(p[0])){
        // move first consonant to previous syllable
        parts[i-1] += p[0];
        parts[i] = p.slice(1) || parts[i];
      }
    }
    return parts.filter(x=>x.length>0);
  }

  function penultVowel(word){
    const syl = toySyllabify(word);
    if(syl.length < 2) return '—';
    const pen = syl[syl.length-2];
    // find last vowel in penult syllable
    const chars = Array.from(pen);
    for(let i=chars.length-1;i>=0;i--){
      if(isVowel(chars[i])) return chars[i];
    }
    return '—';
  }

  function addAcuteToLastVowel(syllable){
    // Add combining acute to the last vowel letter in the syllable.
    const n = nfd(syllable);
    const chars = Array.from(n);
    // find last base vowel (Greek vowel) and insert tonos after it, removing any existing accents on that vowel
    for(let i=chars.length-1;i>=0;i--){
      const ch = chars[i];
      if(isVowel(ch)){
        // remove following combining marks (if any)
        let j=i+1;
        while(j<chars.length && /[\u0300-\u036f]/.test(chars[j])){
          chars.splice(j,1);
        }
        chars.splice(i+1,0,tonos);
        return nfc(chars.join(''));
      }
    }
    return syllable;
  }

  function accentWord(word, where){
    // where: 'ox' (last), 'par' (penult)
    const syl = toySyllabify(word);
    if(syl.length === 0) return word;
    const idx = (where==='par' && syl.length>=2) ? syl.length-2 : syl.length-1;
    syl[idx] = addAcuteToLastVowel(syl[idx]);
    return syl.join('');
  }

  function toggleSigmaNearEnd(word){
    // Toggle ...σσος <-> ...σος and ...σσός <-> ...σός (diacritics ignored for matching)
    const raw = word;
    const base = stripDiacritics(raw);
    const lower = base.toLowerCase();

    // Find last occurrence of σσ before final ος/ός
    // We'll operate on diacritic-stripped version, then re-accent with original accent position (toy: keep as-is if possible)
    let toggled;
    if(/σσ(ο|ό)ς$/i.test(lower)){
      toggled = base.replace(/σσ(ο)(ς)$/i,'σ$1$2');
    } else if(/σ(ο|ό)ς$/i.test(lower)){
      toggled = base.replace(/σ(ο)(ς)$/i,'σσ$1$2');
    } else {
      return raw; // no change
    }

    // Try to preserve original diacritics by re-accenting according to where the original had an accent (if any)
    const hadAcute = /[άέήίόύώΐΰ]/.test(raw) || nfd(raw).includes(tonos);
    if(!hadAcute) return toggled;

    // If original seems oxytone (accent on last syllable), keep oxytone; else keep paroxytone.
    const origGuess = guessAccent(raw).guess;
    const where = origGuess.where;
    return accentWord(toggled, where);
  }

  function guessAccent(word){
    // Toy rule inspired by the passage:
    // If word ends in -ησος and has double sigma near the end (…ησσ-), suggest oxytone.
    // If ends in -ησος with single sigma (…ησ-), suggest barytone/paroxytone.
    // Otherwise: if ends -σσός, suggest oxytone (many are written with -σσός in the list);
    // else default paroxytone.

    const w = stripDiacritics(word);
    const lower = w.toLowerCase();
    const sigmaCount = countSigmaInEnding(word);

    let where = 'par';
    let reason = '';

    if(/ησσ?ος$/i.test(lower)){
      if(/ησσος$/i.test(lower) || sigmaCount>=2){
        where = 'ox';
        reason = 'Toy rule: -ησσ- before -ος → suggest oxytone (acute on last), echoing Herodian’s note about some -ησος words with an extra σ.';
      } else {
        where = 'par';
        reason = 'Toy rule: -ησος with single σ → suggest barytone/paroxytone (acute on penult), like Herodian’s “written with one σ … barytone”.';
      }
    } else if(/σσός$/i.test(lower) || /σσος$/i.test(lower)){
      where = 'ox';
      reason = 'Toy rule: many -σσός/-σσος place-names are shown as oxytone in the list; we put an acute on the last syllable.';
    } else if(/νησος$/i.test(lower)){
      where = 'par';
      reason = 'Toy rule: compounds in -νησος often behave like ordinary -ος nouns; we default to paroxytone for demonstration.';
    } else {
      where = 'par';
      reason = 'Default: paroxytone (acute on penult) for a simple, visible contrast.';
    }

    const guess = accentWord(w, where);
    const alt = accentWord(w, where==='ox' ? 'par' : 'ox');

    return {guess, alt, where, reason};
  }

  function analyze(){
    const raw = inp.value;
    const word = lastWordGreek(raw);

    outInput.textContent = word || '—';

    if(!word){
      normEl.textContent = '—';
      endingEl.textContent = '—';
      scountEl.textContent = '—';
      syllEl.textContent = '—';
      penultEl.textContent = '—';
      outGuess.textContent = '—';
      outAlt.textContent = '—';
      explain.textContent = 'Type a Greek word (letters only) to see the toy analysis.';
      return;
    }

    const norm = stripDiacritics(word);
    const end = detectEnding(word);
    const sc = countSigmaInEnding(word);
    const syl = toySyllabify(word);
    const penV = penultVowel(word);

    normEl.textContent = norm;
    endingEl.textContent = end.label;
    scountEl.textContent = sc ? String(sc) : '0/—';
    syllEl.textContent = syl.join(' · ');
    penultEl.textContent = penV;

    const g = guessAccent(word);
    outGuess.textContent = g.guess;
    outAlt.textContent = g.alt;
    explain.textContent = g.reason + ' (Try toggling σσ/σ to see the suggestion flip.)';
  }

  // --- UI wiring ---
  $('#btnAnalyze').addEventListener('click', analyze);
  inp.addEventListener('input', () => {
    // live, but cheap
    analyze();
  });

  $('#btnRandom').addEventListener('click', () => {
    inp.value = samples[Math.floor(Math.random()*samples.length)];
    analyze();
  });

  $('#btnClear').addEventListener('click', () => {
    inp.value = '';
    analyze();
    inp.focus();
  });

  $('#btnToggle').addEventListener('click', () => {
    const word = lastWordGreek(inp.value);
    if(!word) return;
    const toggled = toggleSigmaNearEnd(word);
    inp.value = toggled;
    analyze();
  });

  $('#btnOx').addEventListener('click', () => {
    const word = lastWordGreek(inp.value);
    if(!word) return;
    inp.value = accentWord(stripDiacritics(word), 'ox');
    analyze();
  });

  $('#btnPar').addEventListener('click', () => {
    const word = lastWordGreek(inp.value);
    if(!word) return;
    inp.value = accentWord(stripDiacritics(word), 'par');
    analyze();
  });

  $$('.chip').forEach(ch => {
    ch.addEventListener('click', () => {
      inp.value = ch.textContent.trim();
      analyze();
    });
  });

  // initial
  analyze();
})();

passages.gadget_css:
:root{
  --bg:#0f1220;
  --card:#171a2b;
  --ink:#e9ecff;
  --muted:#b8bde6;
  --faint:#8b92c7;
  --line:#2a2f52;
  --accent:#7dd3fc;
  --good:#86efac;
  --bad:#fca5a5;
  --warn:#fde68a;
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, #1a1f3a 0%, var(--bg) 55%);color:var(--ink);font:15px/1.35 system-ui,-apple-system,Segoe UI,Roboto,Arial,"Noto Sans",sans-serif}
.wrap{max-width:980px;margin:0 auto;padding:22px 16px 40px}
.hdr{display:flex;gap:14px;align-items:flex-start;margin-bottom:14px}
h1{font-size:22px;margin:0 0 6px}
.sub{margin:0;color:var(--muted)}
.ref{color:var(--accent)}
.card{background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));border:1px solid var(--line);border-radius:14px;padding:14px 14px 12px;margin:12px 0}
.card h2{font-size:16px;margin:0 0 8px}
.inst{margin:0 0 10px;color:var(--muted)}
.row{display:grid;grid-template-columns:90px 1fr auto auto;gap:10px;align-items:center}
.lbl{color:var(--muted)}
input[type=text]{width:100%;padding:10px 12px;border-radius:10px;border:1px solid var(--line);background:#0c0f1d;color:var(--ink);outline:none}
input[type=text]:focus{border-color:#3b82f6;box-shadow:0 0 0 3px rgba(59,130,246,.18)}
.btn{padding:9px 12px;border-radius:10px;border:1px solid #33406b;background:#111633;color:var(--ink);cursor:pointer}
.btn:hover{border-color:#4b5aa0}
.btn:active{transform:translateY(1px)}
.btn.ghost{background:transparent}
.chip{border:1px solid var(--line);background:rgba(255,255,255,.03);color:var(--ink);padding:4px 8px;border-radius:999px;cursor:pointer;margin-right:6px;margin-bottom:6px}
.chip:hover{border-color:#4b5aa0}
.opts{display:flex;gap:16px;flex-wrap:wrap;margin:10px 0 6px;color:var(--muted)}
.opts input{transform:translateY(1px)}
.out{margin-top:10px;border-top:1px dashed var(--line);padding-top:10px}
.outRow{display:grid;grid-template-columns:160px 1fr;gap:10px;padding:6px 0;border-bottom:1px solid rgba(42,47,82,.35)}
.outRow:last-child{border-bottom:none}
.k{color:var(--faint)}
.v{color:var(--ink)}
.v.big{font-size:20px;letter-spacing:.2px}
.note{margin:10px 0 0;color:var(--muted)}
.quiz{display:grid;gap:10px}
.qword{font-size:26px;letter-spacing:.3px;padding:10px 12px;border-radius:12px;border:1px solid var(--line);background:#0c0f1d}
.qbtns{display:flex;gap:10px;flex-wrap:wrap}
.qres{min-height:22px;color:var(--muted)}
.qres.good{color:var(--good)}
.qres.bad{color:var(--bad)}
.qres.warn{color:var(--warn)}
.qfoot{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}
.score{color:var(--muted)}
.ftr{margin-top:10px;color:var(--muted)}
details{border:1px solid var(--line);border-radius:12px;padding:8px 10px;background:rgba(255,255,255,.02)}
summary{cursor:pointer;color:var(--ink)}
.small{margin-top:8px;color:var(--muted)}

passages.gadget_js:
const $ = (sel) => document.querySelector(sel);
const inp = $('#inp');
const go = $('#go');
const clearBtn = $('#clear');
const strip = $('#strip');
const keepCase = $('#keepCase');

const endingEl = $('#ending');
const matchEl = $('#match');
const suggestEl = $('#suggest');
const sketchEl = $('#sketch');
const noteEl = $('#note');

// --- Greek helpers (toy-level) ---
const COMBINING = /[\u0300-\u036f]/g;

function nfd(s){ return s.normalize('NFD'); }
function stripDiacritics(s){ return nfd(s).replace(COMBINING,'').normalize('NFC'); }

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code>=0x0370 && code<=0x03FF) || (code>=0x1F00 && code<=0x1FFF);
}

const VOWELS = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

function baseLower(s){
  // Lowercase + strip diacritics for analysis.
  return stripDiacritics(s).toLowerCase();
}

function lastGreekWord(s){
  // Take last run of Greek letters.
  const m = s.match(/[\u0370-\u03FF\u1F00-\u1FFF]+/g);
  if(!m) return '';
  return m[m.length-1];
}

function countSyllablesToy(word){
  // Count vowel groups (very rough; treats diphthongs as 1 group if adjacent vowels).
  const w = baseLower(word);
  let count = 0;
  let prevV = false;
  for(const ch of w){
    const v = VOWELS.has(ch);
    if(v && !prevV) count++;
    prevV = v;
  }
  return count;
}

function syllableSketch(word){
  // Mark vowels with · separators between vowel groups.
  const raw = stripDiacritics(word);
  const w = nfd(raw);
  let out = '';
  let prevV = false;
  for(const ch of w){
    if(COMBINING.test(ch)) continue;
    const v = VOWELS.has(ch);
    if(v && !prevV && out.length>0) out += '·';
    out += ch;
    prevV = v;
  }
  return out;
}

function endsWithS(s){
  const w = baseLower(s);
  return w.endsWith('ς') || w.endsWith('σ');
}

function detectEnding(word){
  const w = baseLower(word);
  if(w.endsWith('σσος') || w.endsWith('σσός') || w.endsWith('σσοσ')) return '-σσος';
  if(w.endsWith('νησος') || w.endsWith('νῆσος') || w.endsWith('νησοσ')) return '-νησος';
  return '—';
}

function herodianRuleMatch(word){
  // Passage rule (toy):
  // - ends in -σσος
  // - more than 2 syllables
  // - has iota right before the ending: ...ι + σσος
  // - ends in -ς (sigma final)
  const w = baseLower(word);
  const syll = countSyllablesToy(word);
  const ends = w.endsWith('σσος');
  const hasIotaBefore = w.endsWith('ισσος');
  const finalSigma = endsWithS(word);
  return { ends, syll, hasIotaBefore, finalSigma, ok: ends && syll>2 && hasIotaBefore && finalSigma };
}

function applyAcuteOnAntepenult(word){
  // Place an acute on the vowel of the antepenult syllable (toy).
  // Strategy: find vowel-group starts; pick the one that begins the antepenult syllable.
  const original = word;
  const wNFD = nfd(original);

  // Build arrays of base chars (no combining) with mapping to NFD indices.
  const baseChars = [];
  const baseToNfdIndex = [];
  for(let i=0;i<wNFD.length;i++){
    const ch = wNFD[i];
    if(COMBINING.test(ch)) continue;
    baseToNfdIndex.push(i);
    baseChars.push(ch);
  }

  // Identify vowel-group starts in baseChars.
  const starts = [];
  let prevV = false;
  for(let i=0;i<baseChars.length;i++){
    const ch = baseChars[i];
    const v = VOWELS.has(stripDiacritics(ch));
    if(v && !prevV) starts.push(i);
    prevV = v;
  }
  if(starts.length < 3) return null;

  const targetStart = starts[starts.length - 3];

  // Find first vowel char within that vowel group (at targetStart).
  const baseIndex = targetStart;
  const nfdIndex = baseToNfdIndex[baseIndex];

  // Insert combining acute after that base char, but remove any existing accent marks if strip option.
  let out = wNFD;

  // If stripping, remove combining marks from whole word first.
  if(strip.checked){
    out = nfd(stripDiacritics(original));
  }

  // Recompute mapping after stripping.
  const outBase = [];
  const outMap = [];
  for(let i=0;i<out.length;i++){
    const ch = out[i];
    if(COMBINING.test(ch)) continue;
    outMap.push(i);
    outBase.push(ch);
  }

  // Find vowel-group starts again.
  const outStarts = [];
  prevV = false;
  for(let i=0;i<outBase.length;i++){
    const ch = outBase[i];
    const v = VOWELS.has(stripDiacritics(ch));
    if(v && !prevV) outStarts.push(i);
    prevV = v;
  }
  if(outStarts.length < 3) return null;
  const outTargetBaseIndex = outStarts[outStarts.length-3];
  const outNfdIndex = outMap[outTargetBaseIndex];

  // Insert combining acute U+0301 after the vowel base char.
  out = out.slice(0, outNfdIndex+1) + '\u0301' + out.slice(outNfdIndex+1);

  // Normalize to NFC for display.
  let final = out.normalize('NFC');

  // Optionally preserve case: we already kept original letters; stripping may have removed tonos.
  // If keepCase is off, lowercase it.
  if(!keepCase.checked) final = final.toLowerCase();

  return final;
}

function analyzeAndRender(){
  const raw = inp.value.trim();
  const w = lastGreekWord(raw);
  if(!w){
    endingEl.textContent = '—';
    matchEl.textContent = '—';
    suggestEl.textContent = '—';
    sketchEl.textContent = '—';
    noteEl.textContent = 'Type a Greek word (the toy uses the last Greek-looking word in the box).';
    return;
  }

  const ending = detectEnding(w);
  endingEl.textContent = ending;

  const m = herodianRuleMatch(w);
  const bits = [];
  bits.push(m.ends ? 'ends -σσος' : 'not -σσος');
  bits.push(m.syll + ' syll.');
  bits.push(m.hasIotaBefore ? '…ι-σσος' : 'no …ι-σσος');
  matchEl.textContent = m.ok ? `Yes → proparoxytone (antepenult) [${bits.join(', ')}]` : `No/unclear [${bits.join(', ')}]`;

  const sug = m.ok ? applyAcuteOnAntepenult(w) : null;
  suggestEl.textContent = sug ? sug : '(no suggestion)';

  sketchEl.textContent = syllableSketch(w) + `  (≈${m.syll} syllables)`;

  noteEl.textContent = m.ok
    ? 'Toy output: acute on the antepenult, following the pattern described by Herodian for many …ι-σσος words.'
    : 'No match: the passage’s rule is narrow; many -σσος words won’t qualify (and real accentuation depends on more than this toy checks).';
}

// --- Quiz ---
const QUIZ_WORDS = [
  'κυπαρισσος','ναρκισσος','παροπανισσος','πεδνηλισσος','μυρμισσος','βαρβαλισσος','θεμισσος','μουκισσος','μυγισσος','υδισσος',
  // a few distractors / non-matches
  'μελισσος','βόλισσος','πελοποννησος','προκοννησος','ελαφονησος'
];

let qCurrent = null;
let score = 0;
let total = 0;

const qwordEl = $('#qword');
const qresEl = $('#qres');
const scoreEl = $('#score');
const totalEl = $('#total');

function expectedAccentPosition(word){
  const m = herodianRuleMatch(word);
  if(m.ok) return 'antepenult';
  // For non-matches, we don't pretend to know; return null.
  return null;
}

function newQuizWord(){
  qresEl.textContent = ' ';
  qresEl.className = 'qres';
  const w = QUIZ_WORDS[Math.floor(Math.random()*QUIZ_WORDS.length)];
  qCurrent = w;
  // Display stripped (no accents) to make the question about position.
  qwordEl.textContent = stripDiacritics(w);
}

function answerQuiz(ans){
  if(!qCurrent) return;
  total++;
  totalEl.textContent = String(total);

  const exp = expectedAccentPosition(qCurrent);
  if(exp === null){
    qresEl.textContent = `Trickier: this word doesn’t fit the toy’s Herodian pattern, so the toy won’t judge it.`;
    qresEl.className = 'qres warn';
    return;
  }

  if(ans === exp){
    score++;
    scoreEl.textContent = String(score);
    const accented = applyAcuteOnAntepenult(qCurrent) || qCurrent;
    qresEl.textContent = `Correct: ${accented} (antepenult).`;
    qresEl.className = 'qres good';
  } else {
    const accented = applyAcuteOnAntepenult(qCurrent) || qCurrent;
    qresEl.textContent = `No: toy expects antepenult → ${accented}.`;
    qresEl.className = 'qres bad';
  }
}

// --- Wire up ---
document.addEventListener('click', (e) => {
  const chip = e.target.closest('.chip');
  if(chip){
    inp.value = chip.getAttribute('data-in');
    analyzeAndRender();
  }

  const qbtn = e.target.closest('.qbtns .btn');
  if(qbtn){
    answerQuiz(qbtn.getAttribute('data-ans'));
  }
});

go.addEventListener('click', analyzeAndRender);
inp.addEventListener('input', () => {
  // live update, but cheap
  analyzeAndRender();
});
clearBtn.addEventListener('click', () => {
  inp.value = '';
  analyzeAndRender();
  inp.focus();
});
strip.addEventListener('change', analyzeAndRender);
keepCase.addEventListener('change', analyzeAndRender);
$('#next').addEventListener('click', newQuizWord);

// init
analyzeAndRender();
newQuizWord();
scoreEl.textContent = '0';
totalEl.textContent = '0';

