const $ = (sel) => document.querySelector(sel);

const examples = [
  {w:"Τελμισσός", note:"-οσσός → oxytone"},
  {w:"νεοσσός", note:"-οσσός → oxytone"},
  {w:"κολοσσός", note:"-οσσός → oxytone"},
  {w:"Μολοσσός", note:"-οσσός → oxytone"},
  {w:"Γένυσσος", note:"-υσσος → proparoxytone"},
  {w:"Ἄμφρυσσος", note:"-υσσος → proparoxytone"},
  {w:"Ἴνυσσος", note:"-υσσος → proparoxytone"},
  {w:"μέθυσος", note:"single -σος, proparoxytone per passage"},
  {w:"γόγγυσος", note:"single -σος, proparoxytone per passage"},
  {w:"Διόνυσος", note:"single -σος, proparoxytone per passage"},
  {w:"Ἰάλυσος", note:"single -σος, proparoxytone per passage"},
  {w:"Ἀμφίλυσος", note:"single -σος, proparoxytone per passage"},
  {w:"Κηφισός", note:"barytone/exception list"},
  {w:"Ἰλισός", note:"barytone/exception list"},
  {w:"Ἄρνισος", note:"from feminine Ἄρνισα"},
  {w:"Λάρισος", note:"from feminine Λάρισα"},
  {w:"Κερωσσός", note:"-ωσσός → oxytone"},
  {w:"Βηρωσσός", note:"-ωσσός → oxytone"},
  {w:"ἅλωσος", note:"one σ; from ἁλώσω"}
];

function stripDiacritics(s){
  // Remove combining marks; keep base Greek letters.
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function isGreekLetter(ch){
  return /[\u0370-\u03FF\u1F00-\u1FFF]/.test(ch);
}

function normalizeWord(raw){
  let s = raw.trim();
  // unify final sigma
  s = s.replace(/ς/g,'σ');
  // remove punctuation/spaces around
  s = s.replace(/^[^\p{L}]+|[^\p{L}]+$/gu,'');
  return s;
}

const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

function countSyllables(word){
  // crude: count vowel nuclei; treat diphthongs as one nucleus
  const w = word;
  const diph = ["αι","ει","οι","υι","αυ","ευ","ου","ηυ","Αι","Ει","Οι","Υι","Αυ","Ευ","Ου","Ηυ"];
  let i=0, n=0;
  while(i<w.length){
    const two = w.slice(i,i+2);
    if(diph.includes(two)) { n++; i+=2; continue; }
    const ch = w[i];
    if(vowels.has(ch)) n++;
    i++;
  }
  return n;
}

function lastIndexOfVowelNucleus(word){
  // return indices (start,endExclusive) of last vowel nucleus (diphthong or single)
  const diph = ["αι","ει","οι","υι","αυ","ευ","ου","ηυ","Αι","Ει","Οι","Υι","Αυ","Ευ","Ου","Ηυ"];
  for(let i=word.length-2;i>=0;i--){
    const two = word.slice(i,i+2);
    if(diph.includes(two)) return [i,i+2];
  }
  for(let i=word.length-1;i>=0;i--){
    if(vowels.has(word[i])) return [i,i+1];
  }
  return null;
}

function vowelNuclei(word){
  // list of nuclei as {start,end}
  const diph = ["αι","ει","οι","υι","αυ","ευ","ου","ηυ","Αι","Ει","Οι","Υι","Αυ","Ευ","Ου","Ηυ"];
  const out=[];
  let i=0;
  while(i<word.length){
    const two = word.slice(i,i+2);
    if(diph.includes(two)) { out.push({start:i,end:i+2}); i+=2; continue; }
    if(vowels.has(word[i])) { out.push({start:i,end:i+1}); }
    i++;
  }
  return out;
}

function endsWithAny(word, arr){
  return arr.some(suf => word.endsWith(suf));
}

function applyAcuteOnNucleus(word, nucleusIndexFromEnd){
  // nucleusIndexFromEnd: 1=ultima,2=penult,3=antepenult
  const nuclei = vowelNuclei(word);
  if(nuclei.length===0) return word;
  const idx = nuclei.length - nucleusIndexFromEnd;
  if(idx<0) return word;
  const nuc = nuclei[idx];
  // Put acute on first vowel of nucleus.
  const base = word;
  const pos = nuc.start;
  const ch = base[pos];
  const accented = addAcute(ch);
  return base.slice(0,pos) + accented + base.slice(pos+1);
}

function addAcute(ch){
  // minimal mapping for Greek vowels (both cases)
  const map = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };
  return map[ch] || ch;
}

function guessRule(word){
  const w = word;
  const syll = countSyllables(w);
  const lower = w.toLowerCase();

  const info = { syllables: syll, ending: null, guess: null, tags: [], reasoning: [] };

  const hasSso = lower.endsWith('σσος');
  const hasSos = lower.endsWith('σος');
  if(!hasSos && !hasSso){
    info.tags.push({t:"not -σος/-σσος", cls:"bad"});
    info.reasoning.push("Input doesn’t end in -σος or -σσος (after normalizing ς→σ). Try one of the examples.");
    return info;
  }

  info.ending = hasSso ? "-σσος" : "-σος";

  // Determine penult nucleus vowel (very rough)
  const nuclei = vowelNuclei(w);
  const penult = nuclei.length>=2 ? w.slice(nuclei[nuclei.length-2].start, nuclei[nuclei.length-2].end) : "";
  const penultFirst = penult ? penult[0].toLowerCase() : "";

  // Rule 2: ...οσσός oxytone (needs >2 syllables)
  if(syll>2 && lower.endsWith('οσσος')){
    info.guess = {pattern:"oxytone", nucleusFromEnd:1};
    info.tags.push({t:"rule: -οσσός → oxytone", cls:"good"});
    info.reasoning.push("Herodian: -σος words with penult ο and doubled σ (…οσσός) are oxytone.");
    return info;
  }

  // Rule 3: ...υσσος proparoxytone (needs >2 syllables)
  if(syll>2 && lower.endsWith('υσσος')){
    info.guess = {pattern:"proparoxytone", nucleusFromEnd:3};
    info.tags.push({t:"rule: -υσσος → proparoxytone", cls:"good"});
    info.reasoning.push("Herodian: with two σσ and penult υ (…υσσος) → proparoxytone.");
    return info;
  }

  // Rule: -ωσσός oxytone (needs >2 syllables)
  if(syll>2 && lower.endsWith('ωσσος')){
    info.guess = {pattern:"oxytone", nucleusFromEnd:1};
    info.tags.push({t:"rule: -ωσσός → oxytone", cls:"good"});
    info.reasoning.push("Herodian: -σσος with penult ω (…ωσσός) → oxytone.");
    return info;
  }

  // Rule 1: ...ι-σος (penult i) oxytone (needs >2 syllables)
  if(syll>2 && hasSos && !hasSso && penultFirst==='ι'){
    info.guess = {pattern:"oxytone", nucleusFromEnd:1};
    info.tags.push({t:"rule: …ι-σος → oxytone", cls:"good"});
    info.reasoning.push("Herodian: -σος words with penult ending in long ι are oxytone (toy approximates this as penult vowel = ι)." );
    return info;
  }

  // Otherwise: default to proparoxytone for longer words (common in passage list)
  if(syll>=3){
    info.guess = {pattern:"proparoxytone (default)", nucleusFromEnd:3};
    info.tags.push({t:"default guess", cls:"warn"});
    info.reasoning.push("No specific trigger matched; many -σος/-σσος items in the passage are proparoxytone, so the toy defaults to that for 3+ syllables.");
    info.reasoning.push("Herodian also notes barytone exceptions (often from feminines), which this toy can’t detect reliably.");
    return info;
  }

  // 2 syllables: guess oxytone (very rough)
  info.guess = {pattern:"oxytone (2-syllable fallback)", nucleusFromEnd:1};
  info.tags.push({t:"fallback", cls:"warn"});
  info.reasoning.push("Two-syllable case: toy falls back to oxytone; Herodian’s rules here focus on >2 syllables.");
  return info;
}

function render(wordRaw){
  const out = $('#out');
  let raw = wordRaw;
  if(!raw.trim()){
    out.innerHTML = "<div class='mono'>Type a word above, then click Analyze.</div>";
    return;
  }

  let w = normalizeWord(raw);
  const stripped = stripDiacritics(w);
  const useStripped = $('#strip').checked;
  const base = useStripped ? stripped : w;

  const info = guessRule(base);

  let suggested = base;
  if(info.guess && $('#poly').checked){
    suggested = applyAcuteOnNucleus(base, info.guess.nucleusFromEnd);
  }

  // restore final sigma for display
  const displayBase = base.replace(/σ$/,'ς');
  const displaySuggested = suggested.replace(/σ$/,'ς');

  const tagsHtml = (info.tags||[]).map(x=>`<span class="tag ${x.cls}">${escapeHtml(x.t)}</span>`).join('');
  const reasoning = (info.reasoning||[]).map(r=>`<li>${escapeHtml(r)}</li>`).join('');

  out.innerHTML = `
    <div class="big mono">${escapeHtml(displaySuggested)}</div>
    <div style="margin-top:6px">${tagsHtml}</div>
    <div class="kv">
      <div class="k">Normalized input</div><div class="v mono">${escapeHtml(displayBase)}</div>
      <div class="k">Ending</div><div class="v">${escapeHtml(info.ending || '—')}</div>
      <div class="k">Syllables (toy)</div><div class="v">${escapeHtml(String(info.syllables ?? '—'))}</div>
      <div class="k">Accent guess</div><div class="v">${escapeHtml(info.guess ? info.guess.pattern : '—')}</div>
    </div>
    <div style="margin-top:10px">
      <div class="k" style="margin-bottom:6px">Why?</div>
      <ul class="rules" style="margin-top:0">${reasoning || '<li>No reasoning available.</li>'}</ul>
    </div>
  `;
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function buildChips(){
  const box = $('#chips');
  box.innerHTML = '';
  examples.forEach(ex=>{
    const b = document.createElement('button');
    b.className = 'chip mono';
    b.type = 'button';
    b.textContent = ex.w;
    b.title = ex.note;
    b.addEventListener('click', ()=>{ $('#w').value = ex.w; render(ex.w); });
    box.appendChild(b);
  });
}

$('#analyze').addEventListener('click', ()=>render($('#w').value));
$('#clear').addEventListener('click', ()=>{ $('#w').value=''; render(''); $('#w').focus(); });
$('#random').addEventListener('click', ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#w').value = stripDiacritics(ex.w); // show unaccented to encourage play
  render($('#w').value);
});
$('#w').addEventListener('keydown', (e)=>{ if(e.key==='Enter') render($('#w').value); });
$('#strip').addEventListener('change', ()=>render($('#w').value));
$('#poly').addEventListener('change', ()=>render($('#w').value));

buildChips();
render('');

