const $ = (sel, el=document) => el.querySelector(sel);
const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

// --- Greek helpers (toy-level) ---
const COMBINING = /[\u0300-\u036f]/g;

function normalizeGreek(s){
  if(!s) return "";
  // NFD to separate diacritics; unify final sigma; remove most punctuation.
  let t = s.normalize('NFD');
  t = t.replace(/[··.,;:!?\[\]{}()"'“”‘’]/g, ' ');
  t = t.replace(/\s+/g,' ').trim();
  // unify sigma forms
  t = t.replace(/ς/g,'σ');
  return t.normalize('NFC');
}

function stripDiacritics(s){
  return s.normalize('NFD').replace(COMBINING,'').normalize('NFC');
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code>=0x0370 && code<=0x03FF) || (code>=0x1F00 && code<=0x1FFF);
}

function tokenizeGreek(s){
  // keep Greek tokens; split on spaces
  return s.split(/\s+/).filter(Boolean);
}

function lastVowelIndex(word){
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
  const w = word.normalize('NFD');
  for(let i=w.length-1;i>=0;i--){
    const ch = w[i];
    if(vowels.has(ch)) return i;
  }
  return -1;
}

function addAcuteToLastVowel(word){
  // crude: add combining acute to last vowel letter (in NFD)
  let w = word.normalize('NFD');
  const i = lastVowelIndex(w);
  if(i<0) return word;
  // remove existing accent marks on that vowel cluster
  // find span of combining marks after vowel
  let j=i+1;
  while(j<w.length && /[\u0300-\u036f]/.test(w[j])) j++;
  const base = w.slice(0,i+1);
  const after = w.slice(j);
  // keep breathings/diaeresis if present between i+1..j, but remove acute/grave/circumflex
  let comb = w.slice(i+1,j).replace(/[\u0300\u0301\u0342]/g,'');
  w = base + comb + '\u0301' + after;
  return w.normalize('NFC');
}

function addGraveToLastVowel(word){
  let w = word.normalize('NFD');
  const i = lastVowelIndex(w);
  if(i<0) return word;
  let j=i+1;
  while(j<w.length && /[\u0300-\u036f]/.test(w[j])) j++;
  const base = w.slice(0,i+1);
  const after = w.slice(j);
  let comb = w.slice(i+1,j).replace(/[\u0300\u0301\u0342]/g,'');
  w = base + comb + '\u0300' + after;
  return w.normalize('NFC');
}

function addAcuteToPenultVowel(word){
  // toy: accent the second-to-last vowel
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
  let w = word.normalize('NFD');
  let vowelPositions = [];
  for(let i=0;i<w.length;i++){
    if(vowels.has(w[i])) vowelPositions.push(i);
  }
  if(vowelPositions.length<2) return addAcuteToLastVowel(word);
  const i = vowelPositions[vowelPositions.length-2];
  let j=i+1;
  while(j<w.length && /[\u0300-\u036f]/.test(w[j])) j++;
  const before = w.slice(0,i+1);
  const after = w.slice(j);
  let comb = w.slice(i+1,j).replace(/[\u0300\u0301\u0342]/g,'');
  w = before + comb + '\u0301' + after;
  return w.normalize('NFC');
}

function removeAccents(word){
  // remove acute/grave/circumflex but keep breathings/diaeresis/iota subscript
  return word.normalize('NFD')
    .replace(/[\u0300\u0301\u0342]/g,'')
    .normalize('NFC');
}

// --- Passage-inspired mini-lexicon (very small) ---
// Store unaccented keys.
const LEX = {
  // contrasts
  'βροτος': { gloss: 'either “blood” (βρότος) or “mortal” (βροτός) depending on accent', notes: 'Herodian cites βρότος vs βροτός.' },
  'ποτος': { gloss: 'either “drinking-party” (πότος) or “drinkable/what is drunk” (ποτός)', notes: 'Herodian cites πότος vs ποτός.' },
  'στρατος': { gloss: 'either the proper name Στράτος (city) or στρατός “army/gathering”', notes: 'Herodian contrasts Στράτος vs στρατός.' },
  // adjectival -τός examples
  'ρητος': { gloss: 'ῥητός “spoken/said”', notes: 'Adjectival -τός → often acute.' },
  'νητος': { gloss: 'νητός (toy) “spun/heap?” (example list)', notes: 'From the passage’s list.' },
  'κμητος': { gloss: 'κμητός (example list)', notes: 'From the passage’s list.' },
  'τρητος': { gloss: 'τρητός “pierced”', notes: 'From the passage’s list.' },
  'πλωτος': { gloss: 'πλωτός “floating/sailable”', notes: 'From the passage; cf. Od. κ 3.' },
  'στρωτος': { gloss: 'στρωτός “strewn/spread”', notes: 'From the passage’s list.' },
  'γνωτος': { gloss: 'γνωτός “known”', notes: 'From the passage’s list.' },
  'πτωτος': { gloss: 'πτωτός “fallen”', notes: 'From the passage’s list.' },
  'βρωτος': { gloss: 'βρωτός “edible”', notes: 'From the passage’s list.' },
  'τρωτος': { gloss: 'τρωτός “wounded”', notes: 'From the passage’s list.' },
  'πρωτος': { gloss: 'either πρωτός “fated” (toy) or πρῶτος “first” (ordinal)', notes: 'Herodian discusses πρωτός vs πρῶτος.' },
  // barytone -τος (single-gender) examples
  'βατος': { gloss: 'βάτος (example list)', notes: 'Single-gender disyllabic -τος → often barytone.' },
  'λατος': { gloss: 'λάτος (example list)', notes: 'From the passage’s list.' },
  'κροτος': { gloss: 'κρότος “clatter”', notes: 'From the passage’s list.' },
  'κοτος': { gloss: 'κότος “grudge”', notes: 'From the passage’s list.' },
  'μιτος': { gloss: 'μίτος “thread”', notes: 'From the passage’s list.' },
  'νοτος': { gloss: 'νότος “south wind / back” (varies by word)', notes: 'From the passage’s list.' },
  'σκοτος': { gloss: 'σκότος “darkness”', notes: 'From the passage’s list.' },
  // acute proper names
  'κριτος': { gloss: 'Κριτός (proper name) → acute', notes: 'Herodian: Κριτός ὀξύνεται.' },
  'κλιτος': { gloss: 'Κλιτός (proper name) → acute', notes: 'Herodian: Κλιτός ὀξύνεται.' },
};

function suggestAccent(word, cat, showGrave){
  // Return {form, ruleTag}
  const raw = word;
  const base = stripDiacritics(normalizeGreek(raw)).toLowerCase();
  const cleaned = removeAccents(normalizeGreek(raw));

  // Special toy handling for πρῶτος vs πρωτός
  if(base === 'πρωτος'){
    if(cat === 'ordinal'){
      // approximate: circumflex on omega (πρῶτος). We'll just output the precomposed form.
      return { form: 'πρῶτος', ruleTag: 'ordinal (πρῶτος)' };
    }
    if(cat === 'adjective'){
      // πρωτός (acute on omega)
      let f = addAcuteToPenultVowel('πρωτος'); // penult vowel is ω
      // if final acute requested and word ends with acute on last syllable, apply grave; here it is penult, so ignore.
      return { form: f, ruleTag: 'adjectival (πρωτός)' };
    }
  }

  // If user chose adjective: acute (toy: on penult for disyllables)
  if(cat === 'adjective'){
    let f = addAcuteToPenultVowel(cleaned);
    // If acute ended up on final vowel (monosyllables etc.), optionally grave it.
    if(showGrave){
      // detect acute on last vowel by comparing
      const acuteLast = addAcuteToLastVowel(removeAccents(cleaned));
      if(stripDiacritics(acuteLast) === stripDiacritics(f) && acuteLast === f){
        f = addGraveToLastVowel(removeAccents(cleaned));
      }
    }
    return { form: f, ruleTag: 'adjectival → acute (toy)' };
  }

  // Substantive/single-gender: barytone (toy: accent on first vowel/antepenult-ish)
  if(cat === 'substantive'){
    // For disyllables, barytone often means accent not on ultima; we’ll put acute on first vowel.
    let w = removeAccents(cleaned).normalize('NFD');
    const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
    let pos = -1;
    for(let i=0;i<w.length;i++){
      if(vowels.has(w[i])){ pos=i; break; }
    }
    if(pos<0) return { form: cleaned, ruleTag: 'substantive → barytone (toy)' };
    let j=pos+1;
    while(j<w.length && /[\u0300-\u036f]/.test(w[j])) j++;
    let comb = w.slice(pos+1,j).replace(/[\u0300\u0301\u0342]/g,'');
    w = w.slice(0,pos+1) + comb + '\u0301' + w.slice(j);
    return { form: w.normalize('NFC'), ruleTag: 'substantive → barytone (toy)' };
  }

  if(cat === 'proper'){
    // Proper names: often acute in Herodian’s examples (Κριτός, Κλιτός). Toy: acute on penult.
    return { form: addAcuteToPenultVowel(cleaned), ruleTag: 'proper name → acute (toy)' };
  }

  if(cat === 'ordinal'){
    // Toy: if ends -τος, suggest πρῶτος-like? But only really for πρῶτος.
    if(base === 'πρωτος') return { form: 'πρῶτος', ruleTag: 'ordinal (πρῶτος)' };
    // otherwise: barytone-ish
    return { form: addAcuteToPenultVowel(cleaned), ruleTag: 'ordinal (toy default)' };
  }

  return { form: cleaned, ruleTag: 'no category chosen' };
}

// --- UI wiring ---
let chosenCat = 'adjective';
const segBtns = $$('.segBtn');
segBtns.forEach(b=>{
  b.addEventListener('click', ()=>{
    chosenCat = b.dataset.cat;
    segBtns.forEach(x=>x.setAttribute('aria-pressed', x===b ? 'true':'false'));
    analyze();
  });
});
segBtns[0].setAttribute('aria-pressed','true');

const inp = $('#inp');
const out = $('#out');
const chkGrave = $('#chkGrave');
const chkNormalize = $('#chkNormalize');

function analyze(){
  let text = inp.value;
  if(chkNormalize.checked) text = normalizeGreek(text);
  const tokens = tokenizeGreek(text);
  if(tokens.length===0){
    out.innerHTML = `<div class="meta">Type a Greek word above (try: <span class="pill">βροτος</span> <span class="pill">ποτος</span> <span class="pill">πλωτος</span> <span class="pill">πρωτος</span> <span class="pill">Κριτος</span>).</div>`;
    return;
  }

  const showGrave = chkGrave.checked;
  const results = tokens.map(w=>{
    const sug = suggestAccent(w, chosenCat, showGrave);
    const key = stripDiacritics(normalizeGreek(w)).toLowerCase();
    const lex = LEX[key];
    return { in:w, out:sug.form, tag:sug.ruleTag, lex };
  });

  const lines = results.map(r=>{
    const known = r.lex ? `<span class="pill good">in passage list</span>` : `<span class="pill warn">not in list</span>`;
    const gloss = r.lex ? `<div class="meta"><span class="pill">gloss</span> ${escapeHtml(r.lex.gloss)}<br><span class="pill">note</span> ${escapeHtml(r.lex.notes)}</div>` : `<div class="meta">Toy rule applied: <b>${escapeHtml(r.tag)}</b>. (No built-in note for this word.)</div>`;
    return `
      <div class="big">${escapeHtml(r.in)} → <b>${escapeHtml(r.out)}</b></div>
      <div class="meta">${known} <span class="pill">category</span> ${escapeHtml(chosenCat)} <span class="pill">rule</span> ${escapeHtml(r.tag)}</div>
      ${gloss}
    `;
  }).join('<hr class="sep">');

  out.innerHTML = lines;
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c=>({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
  }[c]));
}

$('#btnAnalyze').addEventListener('click', analyze);
inp.addEventListener('input', ()=>{ window.clearTimeout(window.__t); window.__t = window.setTimeout(analyze, 120); });
chkGrave.addEventListener('change', analyze);
chkNormalize.addEventListener('change', analyze);

const EXAMPLES = [
  'βροτος','ποτος','στρατος','πλωτος','τρωτος','βρωτος','γνωτος','σκοτος','κριτος','κλιτος','πρωτος'
];
$('#btnShuffle').addEventListener('click', ()=>{
  const w = EXAMPLES[Math.floor(Math.random()*EXAMPLES.length)];
  inp.value = w;
  analyze();
  inp.focus();
});

// --- Quiz ---
let qTotal=0, qRight=0;
function setScore(){ $('#score').textContent = `Score: ${qRight}/${qTotal}`; }

function makeQuizItem(){
  const keys = Object.keys(LEX);
  const key = keys[Math.floor(Math.random()*keys.length)];
  const base = key;
  const display = base; // unaccented prompt

  // Choose a "target" category for this quiz item.
  // For a few items we hardcode likely categories.
  let targetCat = 'adjective';
  if(['βατος','λατος','κροτος','κοτος','μιτος','νοτος','σκοτος'].includes(base)) targetCat = 'substantive';
  if(['κριτος','κλιτος'].includes(base)) targetCat = 'proper';
  if(base==='πρωτος') targetCat = (Math.random()<0.5 ? 'ordinal' : 'adjective');
  if(['βροτος','ποτος','στρατος'].includes(base)) targetCat = (Math.random()<0.5 ? 'substantive' : 'adjective');

  return { base, display, targetCat, lex: LEX[base] };
}

function renderQuiz(n=6){
  const quiz = $('#quiz');
  quiz.innerHTML = '';
  for(let i=0;i<n;i++){
    const item = makeQuizItem();
    const card = document.createElement('div');
    card.className = 'qcard';
    card.innerHTML = `
      <div class="qword">${escapeHtml(item.display)}</div>
      <div class="qbtns">
        <button class="qbtn" data-cat="adjective">Adjective (-τός)</button>
        <button class="qbtn" data-cat="substantive">Substantive (-τος)</button>
        <button class="qbtn" data-cat="ordinal">Ordinal</button>
        <button class="qbtn" data-cat="proper">Proper</button>
      </div>
      <div class="qres"></div>
    `;
    const res = $('.qres', card);
    $$('.qbtn', card).forEach(btn=>{
      btn.addEventListener('click', ()=>{
        if(btn.disabled) return;
        const guess = btn.dataset.cat;
        const sug = suggestAccent(item.base, guess, false);
        const correct = (guess === item.targetCat);
        qTotal++; if(correct) qRight++;
        setScore();
        $$('.qbtn', card).forEach(b=>b.disabled=true);
        res.innerHTML = `${correct ? `<span class="pill good">correct</span>` : `<span class="pill bad">not quite</span>`}
          <span class="pill">you chose</span> ${escapeHtml(guess)}
          <br><span class="pill">toy accent</span> <b>${escapeHtml(sug.form)}</b>
          <br><span class="pill">note</span> ${escapeHtml(item.lex.notes)}`;
      });
    });
    quiz.appendChild(card);
  }
}

$('#btnNewQuiz').addEventListener('click', ()=>renderQuiz(6));

// init
renderQuiz(6);
