const $ = (sel) => document.querySelector(sel);

const examples = [
  {w:"σῖτος", note:"penult ι → barytone"},
  {w:"βρυτός", note:"penult υ (appellative) → oxytone"},
  {w:"λυτός", note:"penult υ → oxytone"},
  {w:"πλυτός", note:"penult υ → oxytone"},
  {w:"Βύτος", note:"proper name noted barytone"},
  {w:"φόρτος", note:"penult ends in ρ → barytone"},
  {w:"χόρτος", note:"penult ends in ρ → barytone"},
  {w:"ἄρτος", note:"penult ends in ρ → barytone"},
  {w:"κοντός", note:"noted exception: oxytone"},
  {w:"παλτός", note:"noted exception: oxytone"},
  {w:"Σιντός", note:"ethnic: oxytone"},
  {w:"Κελτός", note:"ethnic: oxytone"},
  {w:"Σπαρτός", note:"proper name: oxytone"}
];

// --- Greek helpers ---
const COMBINING = /[\u0300-\u036f]/g;
const tonosMap = {
  "ά":"α", "έ":"ε", "ή":"η", "ί":"ι", "ό":"ο", "ύ":"υ", "ώ":"ω",
  "Ά":"Α", "Έ":"Ε", "Ή":"Η", "Ί":"Ι", "Ό":"Ο", "Ύ":"Υ", "Ώ":"Ω",
  "ΐ":"ι", "ΰ":"υ", "ϊ":"ι", "ϋ":"υ",
};

function stripDiacritics(s){
  // Remove combining marks and also monotonic precomposed tonos letters.
  let out = "";
  for (const ch of s){
    out += (tonosMap[ch] ?? ch);
  }
  return out.normalize('NFD').replace(COMBINING,'').normalize('NFC');
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code>=0x0370 && code<=0x03FF) || (code>=0x1F00 && code<=0x1FFF);
}

function lastGreekWord(phrase){
  // Return last contiguous run of Greek letters.
  const chars = Array.from(phrase);
  let end = chars.length-1;
  while (end>=0 && !isGreekLetter(chars[end])) end--;
  if (end<0) return {word:"", start:0, end:-1};
  let start = end;
  while (start>=0 && isGreekLetter(chars[start])) start--;
  start++;
  return {word: chars.slice(start,end+1).join(''), start, end};
}

const vowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);

function roughSyllables(word){
  // Very rough: split before each vowel group.
  const w = stripDiacritics(word);
  const chars = Array.from(w);
  let syl = [];
  let cur = "";
  let seenVowel = false;
  for (let i=0;i<chars.length;i++){
    const ch = chars[i];
    const isV = vowels.has(ch);
    if (isV){
      if (seenVowel){
        // start new syllable at this vowel
        syl.push(cur);
        cur = ch;
      } else {
        cur += ch;
        seenVowel = true;
      }
    } else {
      cur += ch;
    }
  }
  if (cur) syl.push(cur);
  // Clean empties
  syl = syl.filter(x=>x.length);
  return syl;
}

function endsWithTos(word){
  const w = stripDiacritics(word);
  return /τος$/i.test(w);
}

function penultChunk(word){
  const syl = roughSyllables(word);
  if (syl.length<2) return {syl, penult:"", ultima:""};
  return {syl, penult:syl[syl.length-2], ultima:syl[syl.length-1]};
}

function hasPenultI(word){
  const {penult} = penultChunk(word);
  return /ι/i.test(penult);
}
function hasPenultY(word){
  const {penult} = penultChunk(word);
  return /υ/i.test(penult);
}
function penultEndsInRorHard(word){
  const {penult} = penultChunk(word);
  // If penult contains rho or ends with consonant cluster (very rough)
  if (/ρ/i.test(penult)) return true;
  // ends with consonant (not vowel)
  const p = stripDiacritics(penult);
  const last = Array.from(p).at(-1);
  if (!last) return false;
  return !vowels.has(last);
}

const knownOxy = new Set(["κοντος","παλτος","σπαρτος","σιντος","κελτος","κυρτος"]);
const knownBary = new Set(["βυτος"]);

function classify(word){
  const raw = word;
  const base = stripDiacritics(raw);
  const lower = base.toLowerCase();
  const {syl} = penultChunk(raw);

  if (!endsWithTos(raw)){
    return {ok:false, label:"Not -τος", why:"This toy focuses on words ending in -τος (…τος)."};
  }
  if (syl.length !== 2){
    return {ok:false, label:"Not disyllabic (roughly)", why:`I counted ${syl.length} syllable(s) (very roughly). Herodian’s rule here is for disyllables.`};
  }

  if (knownOxy.has(lower)){
    return {ok:true, label:"Oxytone (noted/ethnic)", why:"Treated as a known oxytone from the passage (or ethnic/proper-name pattern).", kind:"oxy", conf:"warn"};
  }
  if (knownBary.has(lower)){
    return {ok:true, label:"Barytone (proper name)", why:"Treated as a known barytone proper name (Βύτος).", kind:"bary", conf:"warn"};
  }

  if (hasPenultI(raw)){
    return {ok:true, label:"Barytone (penult ι)", why:"Penult has ι; Herodian says disyllables in -τος with long ι in the penult are barytone.", kind:"bary", conf:"good"};
  }
  if (hasPenultY(raw)){
    return {ok:true, label:"Oxytone (penult υ)", why:"Penult has υ; Herodian says appellatives with υ in the penult tend to be oxytone.", kind:"oxy", conf:"good"};
  }
  if (penultEndsInRorHard(raw)){
    return {ok:true, label:"Barytone (penult ‘hard’)", why:"Penult ends in ρ / consonant-ish; Herodian groups these as barytone unless adjectival with feminine.", kind:"bary", conf:"warn"};
  }

  return {ok:true, label:"Uncertain", why:"No strong cue matched; defaulting to barytone as a conservative guess.", kind:"bary", conf:"bad"};
}

function applyAccentToWord(word, kind, style, phraseFinal){
  // Remove existing accents, then add acute on chosen syllable.
  // For polytonic: if phraseFinal and oxytone, use grave on ultima.
  const clean = stripDiacritics(word);
  const syl = roughSyllables(clean);
  if (syl.length<2) return clean;

  const targetIndex = (kind === 'oxy') ? syl.length-1 : syl.length-2;

  // Find first vowel in the target syllable and accent it.
  const chars = Array.from(clean);

  // Map syllable boundaries to character indices by greedy matching.
  let pos = 0;
  let sylStarts = [];
  for (const s of syl){
    sylStarts.push(pos);
    pos += Array.from(s).length;
  }
  const start = sylStarts[targetIndex];
  const end = (targetIndex === syl.length-1) ? chars.length : sylStarts[targetIndex+1];

  let accentChar = null;
  if (style === 'mono'){
    accentChar = 'TONOS';
  } else {
    accentChar = (kind==='oxy' && phraseFinal) ? 'GRAVE' : 'ACUTE';
  }

  for (let i=start;i<end;i++){
    const ch = chars[i];
    const low = ch.toLowerCase();
    if (vowels.has(ch) || vowels.has(low)){
      chars[i] = addAccent(ch, accentChar);
      break;
    }
  }
  return chars.join('');
}

function addAccent(ch, which){
  // Use combining marks to avoid huge precomposed tables.
  const base = stripDiacritics(ch);
  const isUpper = (base === base.toUpperCase() && base !== base.toLowerCase());
  const b = base; // keep case
  let mark = '';
  if (which === 'TONOS' || which === 'ACUTE') mark = '\u0301';
  else if (which === 'GRAVE') mark = '\u0300';
  else mark = '';
  return (b.normalize('NFD') + mark).normalize('NFC');
}

function render(){
  const phrase = $('#inp').value;
  const style = $('#mode').value;
  const force = $('#force').value;

  const {word, start, end} = lastGreekWord(phrase);
  const norm = stripDiacritics(word);
  $('#norm').textContent = word ? norm : '—';

  if (!word){
    $('#syll').textContent = '—';
    $('#pred').innerHTML = '—';
    $('#acc').textContent = '—';
    return;
  }

  const syl = roughSyllables(word);
  $('#syll').textContent = syl.join(' · ');

  let kind = null;
  let info = null;

  if (force === 'none'){
    kind = null;
    info = {ok:true,label:"Accents removed",why:"You chose ‘Remove accents’.",conf:"warn"};
  } else if (force === 'oxy'){
    kind = 'oxy';
    info = {ok:true,label:"Forced oxytone",why:"You chose ‘Oxytone’.",conf:"warn"};
  } else if (force === 'bary'){
    kind = 'bary';
    info = {ok:true,label:"Forced barytone",why:"You chose ‘Barytone’.",conf:"warn"};
  } else {
    info = classify(word);
    kind = info.kind;
  }

  const badgeClass = info.conf ? `badge ${info.conf}` : 'badge';
  $('#pred').innerHTML = `${escapeHtml(info.label)} <span class="${badgeClass}">${info.conf || ''}</span><div class="why">${escapeHtml(info.why || '')}</div>`;

  let outWord = stripDiacritics(word);
  if (force === 'none'){
    outWord = stripDiacritics(word);
  } else if (kind){
    // phraseFinal: if the Greek word is the last non-space char in the whole input
    const tail = phrase.slice(end+1);
    const phraseFinal = tail.trim().length === 0;
    outWord = applyAccentToWord(word, kind, style, phraseFinal);
  }

  // Replace the last Greek word in the phrase with accented suggestion.
  const chars = Array.from(phrase);
  const newPhrase = chars.slice(0,start).join('') + outWord + chars.slice(end+1).join('');
  $('#acc').textContent = newPhrase;
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function mountChips(){
  const box = $('#chips');
  box.innerHTML = '';
  for (const ex of examples){
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip';
    b.textContent = ex.w;
    b.title = ex.note;
    b.addEventListener('click', () => {
      $('#inp').value = ex.w;
      $('#force').value = 'auto';
      render();
    });
    box.appendChild(b);
  }
}

$('#analyze').addEventListener('click', render);
$('#inp').addEventListener('input', render);
$('#mode').addEventListener('change', render);
$('#force').addEventListener('change', render);
$('#clear').addEventListener('click', () => { $('#inp').value=''; render(); });
$('#random').addEventListener('click', () => {
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#inp').value = ex.w;
  $('#force').value = 'auto';
  render();
});

mountChips();
render();

// Small CSS hook for the why text inside pred
const styleHook = document.createElement('div');
styleHook.className = 'sr';
// (No injected <style>; just a harmless node to keep JS self-contained.)

// Add a class to the why div via JS after render; handled inline in pred.

(() => {
  const $ = s => document.querySelector(s);
  const word = $('#word'), sense = $('#sense');
  const key = text => text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/ς/g,'σ');
  const entries = [
    ['πιστός','Oxytone · adjective','The passage lists πιστός among disyllabic -στος adjectives with different gender forms, which tend to take final acute.'],
    ['πλεῖστος','Barytone · superlative','πλεῖστος is a superlative: the passage makes superlatives an exception to the final-accent tendency. The penult has a circumflex.'],
    ['λῷστος','Barytone · superlative','λῷστος is listed with πλεῖστος and ῥᾷστος as a barytone superlative.'],
    ['ῥᾷστος','Barytone · superlative','ῥᾷστος is listed as a barytone superlative, with circumflex on the penult.'],
    ['Δύστος','Barytone · named exception','Δύστος, the city of Euboea, is specifically marked as an exception. This entry concerns the city, not the adjective δύστος.'],
    ['νόστος','Barytone · short penult','νόστος is listed among words with a short penult, outside the opening rule’s condition.'],
    ['κόστος','Barytone · short penult','κόστος is listed among words with a short penult.'],
    ['πλεκτός','Oxytone · verbal adjective','πλεκτός illustrates non-numeral verbal adjectives in -τος with κ or π immediately before τ.'],
    ['ἑλκτός','Oxytone · verbal adjective','ἑλκτός is another example in the passage’s verbal-adjective group.'],
    ['οἶκτος','Barytone · not verbal','οἶκτος is barytone because it is not a verbal adjective. The passage also notes a barytone tendency among certain disyllables beginning with οι.'],
    ['ἱστός','Oxytone · opening group','ἱστός illustrates the opening tendency for disyllabic single-gender -στος words, with a condition excluding naturally short vowels in the penult.']
  ];
  const dictionary = new Map(entries.map(row => [key(row[0]),row]));
  function render() {
    const input = word.value.trim(), k = key(input);
    let entry = dictionary.get(k);
    if(k === key('Φαιστος')) entry = sense.value === 'hero'
      ? ['Φαῖστος','Barytone · hero','For the hero, the passage gives Φαῖστος with penult circumflex and quotes Iliad Ε 43. Changing the referent changes the accent.']
      : ['Φαιστός','Oxytone · city','For the city of Crete (Odyssey γ 296), and another city in the Peloponnese formerly called Φρίξα, the passage gives Φαιστός.'];
    if(!input) entry = ['—','Enter a Greek word','Choose an example or type one word from the passage.'];
    else if(!entry) entry = ['—','Outside this selection','No accent is inferred for this input. Try πιστος, πλειστος, Φαιστος, Δυστος, πλεκτος or οικτος.'];
    $('#form').textContent = entry[0]; $('#kind').textContent = entry[1]; $('#reason').textContent = entry[2];
  }
  $('#lookup').addEventListener('submit',e=>{e.preventDefault();render();});
  sense.addEventListener('change',render);
  document.querySelectorAll('[data-word]').forEach(button=>button.addEventListener('click',()=>{word.value=button.dataset.word;render();}));
  $('#reset').addEventListener('click',()=>{word.value='';sense.value='city';render();word.focus();});
  render();
})();

const entries=[['ἥρως','Barytone: masculine -ως with an extra syllable in declension through pure -ος.'],['Μίνως','Barytone: masculine -ως with an extra syllable in declension through pure -ος.'],['ἱδρώς','Oxytone: simple -ως declined through -τος with a long penult.'],['γέλως','Barytone: iambic -ως declined through -τος.'],['ἔρως','Barytone: iambic -ως declined through -τος.'],['ἀείζως','Paroxytone: compound from monosyllabic ζώς.'],['δύσερως','Proparoxytone: an Attic compound exception.'],['φιλόγελως','Proparoxytone: an Attic compound exception.'],['νεώς','Attic form: keeps the accent of ναός (oxytone).'],['Ἄθως','Double declension: Ἄθωος and Ἄθω; also Ἄθοος and contracted Ἄθους.']];
const key=s=>s.normalize('NFD').replace(/\p{M}/gu,'').toLowerCase().trim();
function show(){const s=document.querySelector('#word').value;const e=entries.find(e=>key(e[0])===key(s));document.querySelector('#answer').textContent=!s.trim()?'Enter a Greek example.':e?e[0]+' — '+e[1]:'Not in this explorer. Try one of the listed passage examples.';}
